# iOS Habit Tracking App

Here's a complete implementation of a native iOS habit tracking application using SwiftUI. This app allows users to track daily habits, view progress, and set reminders.

## 1. Project Setup

First, create a new Xcode project:
- Select "App" template
- Choose SwiftUI interface
- Name it "HabitTracker"

## 2. Data Model

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetPerWeek: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String, frequency: Frequency, targetPerWeek: Int, color: String) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetPerWeek = targetPerWeek
        self.color = color
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var weeklyProgress: Int {
        let calendar = Calendar.current
        let startOfWeek = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: Date()))!
        let endOfWeek = calendar.date(byAdding: .day, value: 6, to: startOfWeek)!

        return completionDates.filter { $0 >= startOfWeek && $0 <= endOfWeek }.count
    }
}
```

## 3. View Models

```swift
// HabitStore.swift
import SwiftUI

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    static func load(completion: @escaping (Result<[Habit], Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let fileURL = try fileURL()
                guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                    DispatchQueue.main.async {
                        completion(.success([]))
                    }
                    return
                }
                let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
                DispatchQueue.main.async {
                    completion(.success(habits))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }

    static func save(habits: [Habit], completion: @escaping (Result<Int, Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let data = try JSONEncoder().encode(habits)
                let outfile = try fileURL()
                try data.write(to: outfile)
                DispatchQueue.main.async {
                    completion(.success(habits.count))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        save()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].isCompletedToday {
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                habits[index].completionDates.append(Date())
            }
            save()
        }
    }

    private func save() {
        HabitStore.save(habits: habits) { _ in }
    }
}
```

## 4. Views

```swift
// HabitTrackerApp.swift
import SwiftUI

@main
struct HabitTrackerApp: App {
    @StateObject private var store = HabitStore()

    var body: some Scene {
        WindowGroup {
            ContentView(store: store)
                .onAppear {
                    HabitStore.load { result in
                        switch result {
                        case .failure(let error):
                            fatalError(error.localizedDescription)
                        case .success(let habits):
                            store.habits = habits
                        }
                    }
                }
        }
    }
}

