# Native iOS Habit Tracking App

Here's a complete implementation of a habit tracking app for iOS using SwiftUI. This app includes features like habit creation, tracking progress, and visualization.

## 1. Project Setup

First, create a new Xcode project:
- Select "App" template
- Choose SwiftUI interface
- Name it "HabitTracker"

## 2. Data Model

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetFrequency: Int // times per day/week
    var frequencyUnit: FrequencyUnit
    var color: String // hex color code
    var completionDates: [Date]

    init(id: UUID = UUID(), name: String, description: String, targetFrequency: Int, frequencyUnit: FrequencyUnit, color: String) {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.frequencyUnit = frequencyUnit
        self.color = color
        self.completionDates = []
    }

    enum FrequencyUnit: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
    }

    var completedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var progressPercentage: Double {
        let calendar = Calendar.current
        let now = Date()

        switch frequencyUnit {
        case .daily:
            let todayCompletions = completionDates.filter { calendar.isDateInToday($0) }
            return Double(todayCompletions.count) / Double(targetFrequency)

        case .weekly:
            let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!
            let weekEnd = calendar.date(byAdding: .day, value: 6, to: weekStart)!

            let weekCompletions = completionDates.filter {
                $0 >= weekStart && $0 <= weekEnd
            }
            return Double(weekCompletions.count) / Double(targetFrequency)
        }
    }
}
```

## 3. View Models

```swift
// HabitStore.swift
import Foundation
import SwiftUI

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].completedToday {
                // Remove today's completion
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                // Add today's completion
                habits[index].completionDates.append(Date())
            }
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none saved
        habits = [
            Habit(name: "Drink Water", description: "Stay hydrated", targetFrequency: 8, frequencyUnit: .daily, color: "#3498DB"),
            Habit(name: "Read", description: "Read for 30 minutes", targetFrequency: 1, frequencyUnit: .daily, color: "#2ECC71"),
            Habit(name: "Exercise", description: "Workout for 30 minutes", targetFrequency: 3, frequencyUnit: .weekly, color: "#E74C3C")
        ]
    }
}
```

