import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        do {
            let fileURL = try Self.fileURL()
            guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                return
            }
            let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
            DispatchQueue.main.async {
                self.habits = habits
            }
        } catch {
            print("Error loading habits: \(error)")
        }
    }

    func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            let outfile = try Self.fileURL()
            try data.write(to: outfile)
        } catch {
            print("Error saving habits: \(error)")
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        save()
    }

    func completeHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habit

            // Calculate new streak
            let calendar = Calendar.current
            let now = Date()

            if let lastCompleted = habit.lastCompleted {
                let daysSinceLastCompletion = calendar.dateComponents([.day], from: lastCompleted, to: now).day ?? 0

                if daysSinceLastCompletion == 1 {
                    // Consecutive day
                    updatedHabit.streak += 1
                } else if daysSinceLastCompletion > 1 {
                    // Broken streak
                    updatedHabit.streak = 1
                }
            } else {
                // First completion
                updatedHabit.streak = 1
            }

            updatedHabit.lastCompleted = now
            habits[index] = updatedHabit
            save()
        }
    }
}
