```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per week

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.completionDates = []
        self.targetFrequency = targetFrequency
    }

    // Check if habit was completed today
    var isCompletedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    // Get completion count for current week
    var weeklyCompletionCount: Int {
        let calendar = Calendar.current
        let now = Date()
        let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!

        return completionDates.filter { date in
            calendar.isDate(date, equalTo: weekStart, toGranularity: .weekOfYear)
        }.count
    }

    // Get completion percentage for current week
    var weeklyCompletionPercentage: Double {
        guard targetFrequency > 0 else { return 0 }
        return min(Double(weeklyCompletionCount) / Double(targetFrequency), 1.0)
    }
}
