### Habit Store
```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        do {
            let fileURL = try Self.fileURL()
            guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                DispatchQueue.main.async {
                    self.habits = []
                }
                return
            }
            let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
            DispatchQueue.main.async {
                self.habits = habits
            }
        } catch {
            print("Error loading habits: \(error.localizedDescription)")
        }
    }

    func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            let outfile = try Self.fileURL()
            try data.write(to: outfile)
        } catch {
            print("Error saving habits: \(error.localizedDescription)")
        }
    }

    // Add a new habit
    func addHabit(name: String, description: String, targetFrequency: Int) {
        let newHabit = Habit(name: name, description: description, targetFrequency: targetFrequency)
        habits.append(newHabit)
        save()
    }

    // Toggle habit completion for today
    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].isCompletedToday {
                // Remove today's completion
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                // Add today's completion
                habits[index].completionDates.append(Date())
            }
            save()
        }
    }

    // Delete a habit
    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        save()
    }
}
