## 3. View Models

```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            do {
                let fileURL = try Self.fileURL()
                guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                    DispatchQueue.main.async {
                        self?.habits = Self.sampleHabits
                    }
                    return
                }
                let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
                DispatchQueue.main.async {
                    self?.habits = habits
                }
            } catch {
                DispatchQueue.main.async {
                    self?.habits = Self.sampleHabits
                }
            }
        }
    }

    func save() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let habits = self?.habits else { return }
            do {
                let data = try JSONEncoder().encode(habits)
                let outfile = try Self.fileURL()
                try data.write(to: outfile)
            } catch {
                print("Error saving habits: \(error)")
            }
        }
    }

    static var sampleHabits: [Habit] {
        [
            Habit(name: "Drink Water", description: "Stay hydrated", targetCount: 8),
            Habit(name: "Exercise", description: "30 minutes of workout", targetCount: 5),
            Habit(name: "Read", description: "Read for 20 minutes", targetCount: 7),
            Habit(name: "Meditate", description: "5 minutes of meditation", targetCount: 7)
        ]
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            if Calendar.current.isDateInToday(updatedHabit.lastCompletedDate ?? .distantPast) {
                // Already completed today, toggle off
                updatedHabit.isCompletedToday = false
                updatedHabit.completionCount -= 1
                updatedHabit.lastCompletedDate = nil
            } else {
                // First completion today
                updatedHabit.isCompletedToday = true
                updatedHabit.completionCount += 1
                updatedHabit.lastCompletedDate = Date()
            }

            habits[index] = updatedHabit
            save()
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }
}
