```swift
// HabitStore.swift
import Foundation
import UserNotifications

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var progress: [HabitProgress] = []

    private let habitsKey = "habits"
    private let progressKey = "habitProgress"

    init() {
        loadData()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveData()
        scheduleNotification(for: habit)
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveData()
            scheduleNotification(for: habit)
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        progress.removeAll { $0.habitId == habit.id }
        saveData()
        cancelNotification(for: habit)
    }

    func recordProgress(habitId: UUID, value: Double) {
        let today = Calendar.current.startOfDay(for: Date())

        if let existingProgress = progress.first(where: { $0.habitId == habitId && Calendar.current.isDate($0.date, inSameDayAs: today) }) {
            if let index = progress.firstIndex(where: { $0.id == existingProgress.id }) {
                progress[index].value = value
            }
        } else {
            let newProgress = HabitProgress(habitId: habitId, date: today, value: value)
            progress.append(newProgress)
        }

        saveData()
    }

    func getProgress(for habit: Habit, in period: DateRange) -> [HabitProgress] {
        return progress.filter {
            $0.habitId == habit.id && $0.date >= period.start && $0.date <= period.end
        }.sorted(by: { $0.date < $1.date })
    }

    private func saveData() {
        if let encodedHabits = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encodedHabits, forKey: habitsKey)
        }

        if let encodedProgress = try? JSONEncoder().encode(progress) {
            UserDefaults.standard.set(encodedProgress, forKey: progressKey)
        }
    }

    private func loadData() {
        if let habitsData = UserDefaults.standard.data(forKey: habitsKey),
           let decodedHabits = try? JSONDecoder().decode([Habit].self, from: habitsData) {
            habits = decodedHabits
        }

        if let progressData = UserDefaults.standard.data(forKey: progressKey),
           let decodedProgress = try? JSONDecoder().decode([HabitProgress].self, from: progressData) {
            progress = decodedProgress
        }
    }

    private func scheduleNotification(for habit: Habit) {
        guard let reminderTime = habit.reminderTime, habit.isActive else {
            cancelNotification(for: habit)
            return
        }

        let content = UNMutableNotificationContent()
        content.title = "Habit Reminder"
        content.body = "Don't forget to track your \(habit.name) habit!"
        content.sound = .default

        var dateComponents = Calendar.current.dateComponents([.hour, .minute], from: reminderTime)
        let trigger = UNCalendarNotificationTrigger(dateMatching: dateComponents, repeats: true)

        let request = UNNotificationRequest(
            identifier: habit.id.uuidString,
            content: content,
            trigger: trigger
        )

        UNUserNotificationCenter.current().add(request) { error in
            if let error = error {
                print("Error scheduling notification: \(error.localizedDescription)")
            }
        }
    }

    private func cancelNotification(for habit: Habit) {
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: [habit.id.uuidString])
    }
}

enum DateRange {
    case today
    case thisWeek
    case thisMonth
    case custom(start: Date, end: Date)

    var start: Date {
        switch self {
        case .today:
            return Calendar.current.startOfDay(for: Date())
        case .thisWeek:
            return Calendar.current.date(from: Calendar.current.dateComponents([.yearForWeekOfYear, .weekOfYear], from: Date()))!
        case .thisMonth:
            return Calendar.current.date(from: Calendar.current.dateComponents([.year, .month], from: Date()))!
        case .custom(let start, _):
            return start
        }
    }

    var end: Date {
        switch self {
        case .today:
            return Calendar.current.date(byAdding: .day, value: 1, to: start)!
        case .thisWeek:
            return Calendar.current.date(byAdding: .day, value: 7, to: start)!
        case .thisMonth:
            return Calendar.current.date(byAdding: .month, value: 1, to: start)!
        case .custom(_, let end):
            return end
        }
    }
}
