// HabitViewModel.swift
import SwiftUI
import Combine

class HabitViewModel: ObservableObject {
    @Published var habit: Habit
    @Published var currentValue: Double = 0
    @Published var progressHistory: [HabitProgress] = []

    private var habitStore: HabitStore
    private var cancellables = Set<AnyCancellable>()

    init(habit: Habit, habitStore: HabitStore) {
        self.habit = habit
        self.habitStore = habitStore

        // Load current progress
        if let todayProgress = habitStore.progress.first(where: {
            $0.habitId == habit.id && Calendar.current.isDate($0.date, inSameDayAs: Date())
        }) {
            currentValue = todayProgress.value
        }

        // Load progress history
        progressHistory = habitStore.getProgress(for: habit, in: .thisWeek)

        // Subscribe to changes
        habitStore.$progress
            .sink { [weak self] _ in
                self?.updateProgress()
            }
            .store(in: &cancellables)
    }

    func updateProgress() {
        if let todayProgress = habitStore.progress.first(where: {
            $0.habitId == habit.id && Calendar.current.isDate($0.date, inSameDayAs: Date())
        }) {
            currentValue = todayProgress.value
        }

        progressHistory = habitStore.getProgress(for: habit, in: .thisWeek)
    }

    func saveProgress() {
        habitStore.recordProgress(habitId: habit.id, value: currentValue)
    }

    func incrementValue() {
        currentValue += 1
        saveProgress()
    }

    func decrementValue() {
        if currentValue > 0 {
            currentValue -= 1
            saveProgress()
        }
    }

    func updateHabit() {
        habitStore.updateHabit(habit)
    }

    func deleteHabit() {
        habitStore.deleteHabit(habit)
    }
}
