```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var streak: Int
    var lastCompletedDate: Date?
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per day to complete

    init(id: UUID = UUID(), name: String, description: String = "", streak: Int = 0, lastCompletedDate: Date? = nil, completionDates: [Date] = [], targetFrequency: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.streak = streak
        self.lastCompletedDate = lastCompletedDate
        self.completionDates = completionDates
        self.targetFrequency = targetFrequency
    }

    // Check if habit was completed today
    var isCompletedToday: Bool {
        guard let lastDate = lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastDate)
    }

    // Check if habit was completed yesterday
    var wasCompletedYesterday: Bool {
        guard let lastDate = lastCompletedDate else { return false }
        return Calendar.current.isDateInYesterday(lastDate)
    }

    // Check if habit was completed this week
    var wasCompletedThisWeek: Bool {
        guard let lastDate = lastCompletedDate else { return false }
        return Calendar.current.isDate(lastDate, equalTo: Date(), toGranularity: .weekOfYear)
    }

    // Check if habit was completed this month
    var wasCompletedThisMonth: Bool {
        guard let lastDate = lastCompletedDate else { return false }
        return Calendar.current.isDate(lastDate, equalTo: Date(), toGranularity: .month)
    }
}
