```swift
// HabitStore.swift
import Foundation
import Combine

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var progress: [HabitProgress] = []

    private let habitsKey = "habits"
    private let progressKey = "habitProgress"

    init() {
        loadData()
    }

    // MARK: - Habit Management
    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        progress.removeAll { $0.habitId == habit.id }
        saveHabits()
        saveProgress()
    }

    // MARK: - Progress Tracking
    func recordProgress(for habit: Habit, count: Int) {
        let today = Calendar.current.startOfDay(for: Date())

        if let existingProgress = progress.first(where: { $0.habitId == habit.id && Calendar.current.isDate($0.date, inSameDayAs: today) }) {
            if let index = progress.firstIndex(where: { $0.id == existingProgress.id }) {
                progress[index].completionCount = count
            }
        } else {
            let newProgress = HabitProgress(habitId: habit.id, date: today, completionCount: count)
            progress.append(newProgress)
        }

        saveProgress()
    }

    func getProgress(for habit: Habit, date: Date = Date()) -> Int {
        let startOfDay = Calendar.current.startOfDay(for: date)
        return progress.first { $0.habitId == habit.id && Calendar.current.isDate($0.date, inSameDayAs: startOfDay) }?.completionCount ?? 0
    }

    func getWeeklyProgress(for habit: Habit) -> [Date: Int] {
        let calendar = Calendar.current
        let today = Date()
        var weeklyProgress: [Date: Int] = [:]

        for day in 0..<7 {
            if let date = calendar.date(byAdding: .day, value: -day, to: today) {
                let startOfDay = calendar.startOfDay(for: date)
                let count = progress.first { $0.habitId == habit.id && calendar.isDate($0.date, inSameDayAs: startOfDay) }?.completionCount ?? 0
                weeklyProgress[startOfDay] = count
            }
        }

        return weeklyProgress
    }

    // MARK: - Persistence
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    private func saveProgress() {
        if let encoded = try? JSONEncoder().encode(progress) {
            UserDefaults.standard.set(encoded, forKey: progressKey)
        }
    }

    private func loadData() {
        if let habitsData = UserDefaults.standard.data(forKey: habitsKey),
           let decodedHabits = try? JSONDecoder().decode([Habit].self, from: habitsData) {
            habits = decodedHabits
        }

        if let progressData = UserDefaults.standard.data(forKey: progressKey),
           let decodedProgress = try? JSONDecoder().decode([HabitProgress].self, from: progressData) {
            progress = decodedProgress
        }
    }
}
