## 3. View Models

```swift
import SwiftUI
import SwiftData
import UserNotifications

@MainActor
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var selectedHabit: Habit?
    @Published var showingAddHabit = false
    @Published var showingEditHabit = false

    private let modelContext: ModelContext
    private let notificationCenter = UNUserNotificationCenter.current()

    init(modelContext: ModelContext) {
        self.modelContext = modelContext
        requestNotificationAuthorization()
    }

    func fetchHabits() {
        let descriptor = FetchDescriptor<Habit>(sortBy: [SortDescriptor(\.name)])
        do {
            habits = try modelContext.fetch(descriptor)
        } catch {
            print("Failed to fetch habits: \(error.localizedDescription)")
        }
    }

    func addHabit(name: String, description: String, color: String, targetCount: Int) {
        let newHabit = Habit(name: name, description: description, color: color, targetCount: targetCount)
        modelContext.insert(newHabit)
        saveContext()
        fetchHabits()
    }

    func updateHabit(habit: Habit, name: String, description: String, color: String, targetCount: Int) {
        habit.name = name
        habit.description = description
        habit.color = color
        habit.targetCount = targetCount
        saveContext()
        fetchHabits()
    }

    func deleteHabit(_ habit: Habit) {
        modelContext.delete(habit)
        saveContext()
        fetchHabits()
    }

    func toggleHabitCompletion(_ habit: Habit) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let lastCompletedDate = habit.lastCompletedDate {
            let lastDate = calendar.startOfDay(for: lastCompletedDate)

            if lastDate == today {
                // Toggle completion for today
                habit.isCompletedToday.toggle()
            } else if calendar.date(byAdding: .day, value: -1, to: today) == lastDate {
                // Completed yesterday - new streak
                habit.isCompletedToday = true
                habit.currentStreak += 1
                habit.bestStreak = max(habit.currentStreak, habit.bestStreak)
            } else {
                // Broken streak
                habit.isCompletedToday = true
                habit.currentStreak = 1
            }
        } else {
            // First completion ever
            habit.isCompletedToday = true
            habit.currentStreak = 1
            habit.bestStreak = 1
        }

        habit.lastCompletedDate = Date()
        saveContext()
        fetchHabits()
    }

    func resetDailyHabits() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        for habit in habits {
            if let lastCompletedDate = habit.lastCompletedDate {
                let lastDate = calendar.startOfDay(for: lastCompletedDate)
                if lastDate != today {
                    habit.isCompletedToday = false
                }
            } else {
                habit.isCompletedToday = false
            }
        }

        saveContext()
        fetchHabits()
    }

    func addReminder(to habit: Habit, time: Date) {
        let reminder = Reminder(time: time)
        if habit.reminders == nil {
            habit.reminders = []
        }
        habit.reminders?.append(reminder)
        scheduleNotification(for: habit, reminder: reminder)
        saveContext()
    }

    func removeReminder(from habit: Habit, reminder: Reminder) {
        habit.reminders?.removeAll { $0.id == reminder.id }
        cancelNotification(for: habit, reminder: reminder)
        saveContext()
    }

    private func saveContext() {
        do {
            try modelContext.save()
        } catch {
            print("Failed to save context: \(error.localizedDescription)")
        }
    }

    private func requestNotificationAuthorization() {
        notificationCenter.requestAuthorization(options: [.alert, .sound, .badge]) { granted, error in
            if let error = error {
                print("Notification authorization error: \(error.localizedDescription)")
            }
        }
    }

    private func scheduleNotification(for habit: Habit, reminder: Reminder) {
        let content = UNMutableNotificationContent()
        content.title = "Habit Reminder"
        content.body = "Don't forget to complete your \(habit.name) habit!"
        content.sound = .default

        let calendar = Calendar.current
        let components = calendar.dateComponents([.hour, .minute], from: reminder.time)

        let trigger = UNCalendarNotificationTrigger(dateMatching: components, repeats: true)

        let request = UNNotificationRequest(
            identifier: "\(habit.id)-\(reminder.id)",
            content: content,
            trigger: trigger
        )

        notificationCenter.add(request) { error in
            if let error = error {
                print("Error scheduling notification: \(error.localizedDescription)")
            }
        }
    }

    private func cancelNotification(for habit: Habit, reminder: Reminder) {
        notificationCenter.removePendingNotificationRequests(withIdentifiers: ["\(habit.id)-\(reminder.id)"])
    }
}
