                                    reminder.isActive = isActive
                                    if isActive {
                                        viewModel.scheduleNotification(for: habit, reminder: reminder)
                                    } else {
                                        viewModel.cancelNotification(for: habit, reminder: reminder)
                                    }
                                }
                            ))
                        }
                    }
                    .onDelete { indices in
                        indices.forEach { index in
                            if let reminders = habit.reminders {
                                viewModel.removeReminder(from: habit, reminder: reminders[index])
                            }
                        }
                    }
                } else {
                    Text("No reminders set")
                        .foregroundColor(.gray)
                }

                Button("Add Reminder") {
                    showingReminderPicker = true
                }
            }
        }
        .navigationTitle(habit.name)
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                Button("Edit") {
                    showingEdit = true
                }
            }
        }
        .sheet(isPresented: $showingEdit) {
            EditHabitView(habit: habit, viewModel: viewModel)
        }
        .sheet(isPresented: $showingReminderPicker) {
            ReminderPickerView(
                selectedTime: $selectedReminderTime,
                onSave: { time in
                    viewModel.addReminder(to: habit, time: time)
                }
            )
        }
    }

    private func formatTime(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.timeStyle = .short
        return formatter.string(from: date)
    }
}

