## 2. ViewModels

```swift
// HabitViewModel.swift
import Foundation
import SwiftUI

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var progressRecords: [HabitProgress] = []

    private let persistenceManager = PersistenceManager.shared

    init() {
        loadHabits()
        loadProgressRecords()
    }

    // MARK: - Habit Management

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        progressRecords.removeAll { $0.habitId == habit.id }
        saveHabits()
        saveProgressRecords()
    }

    // MARK: - Progress Management

    func recordProgress(for habit: Habit, count: Int = 1) {
        let today = Calendar.current.startOfDay(for: Date())

        if let existingRecordIndex = progressRecords.firstIndex(where: {
            $0.habitId == habit.id && Calendar.current.isDate($0.date, inSameDayAs: today)
        }) {
            progressRecords[existingRecordIndex].count += count
        } else {
            let newRecord = HabitProgress(habitId: habit.id, date: today, count: count)
            progressRecords.append(newRecord)
        }

        saveProgressRecords()
    }

    func getProgress(for habit: Habit, in period: DatePeriod = .week) -> [Date: Int] {
        let calendar = Calendar.current
        let now = Date()
        var startDate: Date

        switch period {
        case .week:
            startDate = calendar.date(byAdding: .day, value: -6, to: now) ?? now
        case .month:
            startDate = calendar.date(byAdding: .month, value: -1, to: now) ?? now
        case .year:
            startDate = calendar.date(byAdding: .year, value: -1, to: now) ?? now
        }

        var progressDict: [Date: Int] = [:]

        // Initialize all dates in the period with 0
        var currentDate = startDate
        while currentDate <= now {
            let dateKey = calendar.startOfDay(for: currentDate)
            progressDict[dateKey] = 0
            currentDate = calendar.date(byAdding: .day, value: 1, to: currentDate) ?? now
        }

        // Fill in actual progress
        for record in progressRecords where record.habitId == habit.id {
            let recordDate = calendar.startOfDay(for: record.date)
            if let existingCount = progressDict[recordDate] {
                progressDict[recordDate] = existingCount + record.count
            }
        }

        return progressDict
    }

    func getStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        var currentDate = today
        var streak = 0

        while let record = progressRecords.first(where: {
            $0.habitId == habit.id && calendar.isDate($0.date, inSameDayAs: currentDate)
        }) {
            if record.count >= habit.targetCount {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? today
            } else {
                break
            }
        }

        return streak
    }

    // MARK: - Persistence

    private func saveHabits() {
        persistenceManager.saveHabits(habits)
    }

    private func loadHabits() {
        habits = persistenceManager.loadHabits()
    }

    private func saveProgressRecords() {
        persistenceManager.saveProgressRecords(progressRecords)
    }

    private func loadProgressRecords() {
        progressRecords = persistenceManager.loadProgressRecords()
    }
}

enum DatePeriod {
    case week, month, year
}
```

## 3. Persistence Layer

```swift
// PersistenceManager.swift
import Foundation

class PersistenceManager {
    static let shared = PersistenceManager()

    private let habitsKey = "habits"
    private let progressKey = "progress"

    private init() {}

    // MARK: - Habits

    func saveHabits(_ habits: [Habit]) {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    func loadHabits() -> [Habit] {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let habits = try? JSONDecoder().decode([Habit].self, from: data) {
            return habits
        }
        return []
    }

    // MARK: - Progress Records

    func saveProgressRecords(_ records: [HabitProgress]) {
        if let encoded = try? JSONEncoder().encode(records) {
            UserDefaults.standard.set(encoded, forKey: progressKey)
        }
    }

    func loadProgressRecords() -> [HabitProgress] {
        if let data = UserDefaults.standard.data(forKey: progressKey),
           let records = try? JSONDecoder().decode([HabitProgress].self, from: data) {
            return records
        }
        return []
    }
}
