class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var logs: [HabitLog] = []
    @Published var selectedDate = Date()

    private let service = HabitService()

    init() {
        loadData()
    }

    func loadData() {
        habits = service.loadHabits()
        logs = service.loadLogs()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        service.saveHabits(habits)
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            service.saveHabits(habits)
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        logs.removeAll { $0.habitId == habit.id }
        service.saveHabits(habits)
        service.saveLogs(logs)
    }

    func logHabit(_ habit: Habit, count: Int) {
        let calendar = Calendar.current
        let dateComponents = calendar.dateComponents([.year, .month, .day], from: selectedDate)

        if let existingLogIndex = logs.firstIndex(where: {
            $0.habitId == habit.id &&
            calendar.isDate($0.date, inSameDayAs: selectedDate)
        }) {
            logs[existingLogIndex].count += count
        } else {
