            logs.append(newLog)
        }

        service.saveLogs(logs)
    }

    func getLogs(for habit: Habit, in date: Date) -> HabitLog? {
        let calendar = Calendar.current
        return logs.first {
            $0.habitId == habit.id &&
            calendar.isDate($0.date, inSameDayAs: date)
        }
    }

    func getDailyProgress(for habit: Habit, in date: Date) -> Double {
        guard let log = getLogs(for: habit, in: date) else { return 0 }
        return Double(log.count) / Double(habit.targetFrequency)
    }

    func getWeeklyProgress(for habit: Habit) -> [Date: Double] {
        var progress: [Date: Double] = [:]
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        for day in 0..<7 {
            if let date = calendar.date(byAdding: .day, value: -day, to: today) {
                let dayProgress = getDailyProgress(for: habit, in: date)
                progress[date] = dayProgress
            }
        }

        return progress
    }

    func getMonthlyProgress(for habit: Habit) -> [Date: Double] {
        var progress: [Date: Double] = [:]
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        guard let monthStart = calendar.date(from: calendar.dateComponents([.year, .month], from: today)) else {
            return progress
        }

        var currentDate = monthStart
        while currentDate <= today {
            let dayProgress = getDailyProgress(for: habit, in: currentDate)
            progress[currentDate] = dayProgress
            currentDate = calendar.date(byAdding: .day, value: 1, to: currentDate) ?? today
        }

        return progress
    }
}
