## 1. Models

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var targetCount: Int
    var color: String
    var isActive: Bool

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, targetCount: Int = 1, color: String = "blue", isActive: Bool = true) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.targetCount = targetCount
        self.color = color
        self.isActive = isActive
    }
}

enum Frequency: String, Codable, CaseIterable {
    case daily = "Daily"
    case weekly = "Weekly"
    case monthly = "Monthly"
}

// HabitLog.swift
import Foundation

struct HabitLog: Identifiable, Codable {
    let id: UUID
    let habitId: UUID
    let date: Date
    var count: Int

    init(id: UUID = UUID(), habitId: UUID, date: Date = Date(), count: Int = 1) {
        self.id = id
        self.habitId = habitId
        self.date = date
        self.count = count
    }
}
