## 2. Services

```swift
// HabitService.swift
import Foundation

class HabitService {
    private let habitsKey = "habits"
    private let logsKey = "habitLogs"

    func saveHabits(_ habits: [Habit]) {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    func loadHabits() -> [Habit] {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let habits = try? JSONDecoder().decode([Habit].self, from: data) {
            return habits
        }
        return []
    }

    func saveLogs(_ logs: [HabitLog]) {
        if let encoded = try? JSONEncoder().encode(logs) {
            UserDefaults.standard.set(encoded, forKey: logsKey)
        }
    }

    func loadLogs() -> [HabitLog] {
        if let data = UserDefaults.standard.data(forKey: logsKey),
           let logs = try? JSONDecoder().decode([HabitLog].self, from: data) {
            return logs
        }
        return []
    }

    func logHabit(habitId: UUID, count: Int = 1) {
        var logs = loadLogs()
        let newLog = HabitLog(habitId: habitId, count: count)
        logs.append(newLog)
        saveLogs(logs)
    }

    func getLogs(for habitId: UUID) -> [HabitLog] {
        let allLogs = loadLogs()
        return allLogs.filter { $0.habitId == habitId }
    }

    func getLogs(for habitId: UUID, in dateRange: ClosedRange<Date>) -> [HabitLog] {
        let allLogs = loadLogs()
        return allLogs.filter { $0.habitId == habitId && dateRange.contains($0.date) }
    }
}

// NotificationService.swift
import UserNotifications

class NotificationService {
    static let shared = NotificationService()
    private let center = UNUserNotificationCenter.current()

    func requestPermission() {
        center.requestAuthorization(options: [.alert, .sound]) { granted, error in
            if granted {
                print("Notification permission granted")
            } else if let error = error {
                print("Notification permission error: \(error.localizedDescription)")
            }
        }
    }

    func scheduleDailyReminder(for habit: Habit, at time: DateComponents) {
        let content = UNMutableNotificationContent()
        content.title = "Habit Reminder"
        content.body = "Don't forget to complete your \(habit.name) habit!"
        content.sound = .default

        let trigger = UNCalendarNotificationTrigger(dateMatching: time, repeats: true)
        let request = UNNotificationRequest(identifier: habit.id.uuidString, content: content, trigger: trigger)

        center.add(request) { error in
            if let error = error {
                print("Error scheduling notification: \(error.localizedDescription)")
            }
        }
    }

    func removeReminder(for habitId: UUID) {
        center.removePendingNotificationRequests(withIdentifiers: [habitId.uuidString])
    }
}
