## 3. ViewModels

```swift
// HabitViewModel.swift
import SwiftUI
import Combine

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var selectedDate = Date()
    @Published var showingAddHabit = false

    private let habitService = HabitService()
    private var cancellables = Set<AnyCancellable>()

    init() {
        loadHabits()
    }

    func loadHabits() {
        habits = habitService.loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
        NotificationService.shared.removeReminder(for: habit.id)
    }

    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].isActive.toggle()
            saveHabits()
        }
    }

    func logHabit(_ habit: Habit, count: Int = 1) {
        habitService.logHabit(habitId: habit.id, count: count)
    }

    func getLogs(for habit: Habit) -> [HabitLog] {
        return habitService.getLogs(for: habit.id)
    }

    func getLogs(for habit: Habit, in dateRange: ClosedRange<Date>) -> [HabitLog] {
        return habitService.getLogs(for: habit.id, in: dateRange)
    }

    func getCompletionCount(for habit: Habit, in dateRange: ClosedRange<Date>) -> Int {
        let logs = getLogs(for: habit, in: dateRange)
        return logs.reduce(0) { $0 + $1.count }
    }

    private func saveHabits() {
        habitService.saveHabits(habits)
    }
}
