```swift
// HabitViewModel.swift
import Foundation
import CoreData

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    private var context: NSManagedObjectContext

    init(context: NSManagedObjectContext) {
        self.context = context
        fetchHabits()
    }

    func fetchHabits() {
        let request: NSFetchRequest<Habit> = Habit.fetchRequest()
        request.sortDescriptors = [NSSortDescriptor(keyPath: \Habit.creationDate, ascending: false)]

        do {
            habits = try context.fetch(request)
        } catch {
            print("Error fetching habits: \(error.localizedDescription)")
        }
    }

    func addHabit(name: String, description: String?) {
        let newHabit = Habit(context: context)
        newHabit.id = UUID()
        newHabit.name = name
        newHabit.habitDescription = description
        newHabit.creationDate = Date()
        newHabit.streakCount = 0

        saveContext()
        fetchHabits()
    }

    func completeHabit(_ habit: Habit) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let lastCompleted = habit.lastCompletedDate {
            let lastCompletedDay = calendar.startOfDay(for: lastCompleted)

            if calendar.isDateInYesterday(lastCompletedDay) {
                // Streak continues
                habit.streakCount += 1
            } else if !calendar.isDate(lastCompletedDay, inSameDayAs: today) {
                // Reset streak if not completed yesterday
                habit.streakCount = 1
            }
        } else {
            // First completion
            habit.streakCount = 1
        }

        habit.lastCompletedDate = Date()
        saveContext()
        fetchHabits()
    }

    func deleteHabit(_ habit: Habit) {
        context.delete(habit)
        saveContext()
        fetchHabits()
    }

    private func saveContext() {
        do {
            try context.save()
        } catch {
            print("Error saving context: \(error.localizedDescription)")
        }
    }
}
