## 2. Data Models

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetCount: Int
    var currentStreak: Int
    var bestStreak: Int
    var completionDates: [Date]
    var color: String

    init(name: String, description: String, targetCount: Int, color: String) {
        self.id = UUID()
        self.name = name
        self.description = description
        self.targetCount = targetCount
        self.currentStreak = 0
        self.bestStreak = 0
        self.completionDates = []
        self.color = color
    }

    mutating func completeHabit() {
        let today = Date().stripTime()

        // Check if already completed today
        if completionDates.contains(where: { $0 == today }) {
            return
        }

        completionDates.append(today)

        // Check for streak
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: today)!.stripTime()
        if completionDates.contains(yesterday) {
            currentStreak += 1
        } else {
            currentStreak = 1
        }

        // Update best streak
        if currentStreak > bestStreak {
            bestStreak = currentStreak
        }
    }

    func isCompletedToday() -> Bool {
        let today = Date().stripTime()
        return completionDates.contains(today)
    }

    func progress() -> Double {
        guard targetCount > 0 else { return 0 }
        return Double(completionDates.count) / Double(targetCount)
    }
}

extension Date {
    func stripTime() -> Date {
        let calendar = Calendar.current
        let components = calendar.dateComponents([.year, .month, .day], from: self)
        return calendar.date(from: components)!
    }
}
```

