```swift
import Foundation
import SwiftUI

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func toggleHabitCompletion(_ habit: Habit) {
        if var updatedHabit = habits.first(where: { $0.id == habit.id }) {
            updatedHabit.isCompletedToday.toggle()

            if updatedHabit.isCompletedToday {
                updatedHabit.completionCount += 1
                updatedHabit.lastCompletedDate = Date()
            } else {
                updatedHabit.completionCount -= 1
                updatedHabit.lastCompletedDate = nil
            }

            updateHabit(updatedHabit)
        }
    }

    func resetDailyCompletion() {
        for index in habits.indices {
            habits[index].isCompletedToday = false
        }
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Drink 8 glasses of water daily", targetCount: 8, color: "blue"),
            Habit(name: "Exercise", description: "30 minutes of exercise", targetCount: 1, color: "green"),
            Habit(name: "Read", description: "Read for 30 minutes", targetCount: 1, color: "purple")
        ]
    }
}
