        let calendar = Calendar.current
        let now = Date()

        for habit in habitStore.habits {
            if let lastCompletedDate = habit.lastCompletedDate {
                if !calendar.isDate(lastCompletedDate, inSameDayAs: now) {
                    habitStore.resetDailyCompletion()
                    break
                }
            }
        }
    }
