## 2. Data Model

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var startDate: Date
    var frequency: HabitFrequency
    var completionDates: [Date]
    var reminderTime: Date?
    var isActive: Bool

    init(id: UUID = UUID(),
         name: String,
         description: String = "",
         startDate: Date = Date(),
         frequency: HabitFrequency = .daily,
         completionDates: [Date] = [],
         reminderTime: Date? = nil,
         isActive: Bool = true) {
        self.id = id
        self.name = name
        self.description = description
        self.startDate = startDate
        self.frequency = frequency
        self.completionDates = completionDates
        self.reminderTime = reminderTime
        self.isActive = isActive
    }

    // Check if habit was completed on a specific date
    func wasCompleted(on date: Date) -> Bool {
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: date) }
    }

    // Toggle completion for a specific date
    mutating func toggleCompletion(on date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }

    // Calculate completion percentage
    func completionPercentage() -> Double {
        let daysSinceStart = Calendar.current.dateComponents([.day], from: startDate, to: Date()).day ?? 1
        let completedDays = completionDates.filter { $0 >= startDate }.count
        return Double(completedDays) / Double(daysSinceStart)
    }
}

enum HabitFrequency: String, Codable, CaseIterable {
    case daily = "Daily"
    case weekly = "Weekly"
    case monthly = "Monthly"
}
```

## 3. Data Persistence

```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    static func load(completion: @escaping (Result<[Habit], Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let fileURL = try fileURL()
                guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                    DispatchQueue.main.async {
                        completion(.success([]))
                    }
                    return
                }
                let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
                DispatchQueue.main.async {
                    completion(.success(habits))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }

    static func save(habits: [Habit], completion: @escaping (Result<Int, Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let data = try JSONEncoder().encode(habits)
                let outfile = try fileURL()
                try data.write(to: outfile)
                DispatchQueue.main.async {
                    completion(.success(habits.count))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }
}
