// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        saveHabits()
    }

    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            if Calendar.current.isDateInToday(updatedHabit.lastCompletedDate ?? Date.distantPast) {
                // Undo completion if already completed today
                updatedHabit.completionCount -= 1
                updatedHabit.isCompletedToday = false
                updatedHabit.lastCompletedDate = nil
            } else {
                // Mark as completed today
                updatedHabit.completionCount += 1
                updatedHabit.isCompletedToday = true
                updatedHabit.lastCompletedDate = Date()
            }

            habits[index] = updatedHabit
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none saved
        habits = [
            Habit(title: "Drink Water", description: "Drink 8 glasses of water daily", targetCount: 8),
            Habit(title: "Exercise", description: "30 minutes of exercise daily"),
            Habit(title: "Read", description: "Read for 20 minutes daily", targetCount: 2)
        ]
    }
}
