```swift
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per week

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.completionDates = []
        self.targetFrequency = targetFrequency
    }

    // Calculate completion percentage for the current week
    func completionPercentage(for date: Date = Date()) -> Double {
        let calendar = Calendar.current
        let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: date))!
        let weekEnd = calendar.date(byAdding: .day, value: 6, to: weekStart)!

        let completedThisWeek = completionDates.filter { $0 >= weekStart && $0 <= weekEnd }.count
        return Double(completedThisWeek) / Double(targetFrequency)
    }

    // Check if habit was completed today
    func completedToday() -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: Date()) }
    }

    // Toggle completion for today
    mutating func toggleCompletion() {
        let calendar = Calendar.current
        let today = Date()

        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
