```swift
// HabitViewModel.swift
import Foundation
import SwiftUI

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []
    @Published var showingAddHabit = false

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, description: String, frequency: HabitFrequency) {
        let newHabit = Habit(name: name, description: description, frequency: frequency)
        habits.append(newHabit)
        saveHabits()
    }

    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]
            updatedHabit.isCompletedToday.toggle()

            // Update streak
            let calendar = Calendar.current
            let today = calendar.startOfDay(for: Date())

            if updatedHabit.isCompletedToday {
                if let lastCompleted = updatedHabit.lastCompletedDate {
                    let lastCompletedDay = calendar.startOfDay(for: lastCompleted)
                    let daysDifference = calendar.dateComponents([.day], from: lastCompletedDay, to: today).day ?? 0

                    if daysDifference == 1 {
                        updatedHabit.streak += 1
                    } else if daysDifference > 1 {
                        updatedHabit.streak = 1
                    }
                } else {
                    updatedHabit.streak = 1
                }
                updatedHabit.lastCompletedDate = Date()
            } else {
                updatedHabit.streak = 0
            }

            habits[index] = updatedHabit
            saveHabits()
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
