import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetPerWeek: Int

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetPerWeek: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetPerWeek = targetPerWeek
    }

    var isCompletedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var completionCountThisWeek: Int {
        let calendar = Calendar.current
        let now = Date()
        let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!

        return completionDates.filter { date in
            date >= weekStart && date <= now
        }.count
    }
}
```

