import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var creationDate: Date
    var completionDates: [Date]
    var targetFrequency: Frequency

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String = "", creationDate: Date = Date(), completionDates: [Date] = [], targetFrequency: Frequency = .daily) {
        self.id = id
        self.name = name
        self.description = description
        self.creationDate = creationDate
        self.completionDates = completionDates
        self.targetFrequency = targetFrequency
    }

    var isCompletedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    mutating func toggleCompletion() {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: Date()) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }
}
