```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetPerWeek: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetPerWeek: Int, color: String) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetPerWeek = targetPerWeek
        self.color = color
    }

    enum Frequency: String, Codable, CaseIterable {
        case daily, weekly, monthly
    }

    var isCompletedToday: Bool {
        guard let today = Calendar.current.date(bySettingHour: 0, minute: 0, second: 0, of: Date()) else { return false }
        return completionDates.contains { date in
            Calendar.current.isDate(date, inSameDayAs: today)
        }
    }

    mutating func toggleCompletion() {
        let today = Date()
        if isCompletedToday {
            completionDates.removeAll { date in
                Calendar.current.isDate(date, inSameDayAs: today)
            }
        } else {
            completionDates.append(today)
        }
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        do {
            let fileURL = try Self.fileURL()
            guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                DispatchQueue.main.async {
                    self.habits = []
                }
                return
            }
            let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
            DispatchQueue.main.async {
                self.habits = habits
            }
        } catch {
            print("Error loading habits: \(error)")
        }
    }

    func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            let outfile = try Self.fileURL()
            try data.write(to: outfile)
        } catch {
            print("Error saving habits: \(error)")
        }
    }

    func add(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func update(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func delete(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        save()
    }
}
