import SwiftUI

struct AddHabitView: View {
    @Environment(\.dismiss) private var dismiss
    @EnvironmentObject var store: HabitStore

    @State private var name = ""
    @State private var description = ""
    @State private var frequency: Habit.Frequency = .daily
    @State private var targetPerWeek = 1
    @State private var color = "blue"

    let colors = ["blue", "green", "red", "purple", "orange", "pink"]

    var editingHabit: Habit?

    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("Basic Info")) {
                    TextField("Habit Name", text: $name)
                    TextField("Description", text: $description)
                }

                Section(header: Text("Frequency")) {
                    Picker("Frequency", selection: $frequency) {
                        ForEach(Habit.Frequency.allCases, id: \.self) { freq in
                            Text(freq.rawValue.capitalized)
                        }
                    }
                    .pickerStyle(.segmented)

                    if frequency == .weekly {
                        Stepper("Target per week: \(targetPerWeek)", value: $targetPerWeek, in: 1...7)
                    }
                }

                Section(header: Text("Appearance")) {
                    Picker("Color", selection: $color) {
                        ForEach(colors, id: \.self) { color in
                            Text(color.capitalized)
                                .tag(color)
                        }
                    }
                    .pickerStyle(.segmented)
                }
            }
            .navigationTitle(editingHabit == nil ? "New Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        saveHabit()
                        dismiss()
                    }
                    .disabled(name.isEmpty)
                }
            }
            .onAppear {
                if let habit = editingHabit {
                    name = habit.name
                    description = habit.description
                    frequency = habit.frequency
                    targetPerWeek = habit.targetPerWeek
                    color = habit.color
                }
            }
        }
    }

    private func saveHabit() {
        if let habit = editingHabit {
            // Update existing habit
            var updatedHabit = habit
            updatedHabit.name = name
            updatedHabit.description = description
            updatedHabit.frequency = frequency
            updatedHabit.targetPerWeek = targetPerWeek
            updatedHabit.color = color
            store.update(updatedHabit)
        } else {
            // Create new habit
            let newHabit = Habit(
                name: name,
                description: description,
                frequency: frequency,
                targetPerWeek: targetPerWeek,
                color: color
            )
            store.add(newHabit)
        }
    }
}
