```swift
// Models/Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var creationDate: Date
    var streak: Int
    var lastCompletedDate: Date?
    var completionDates: [Date]

    init(name: String, description: String = "") {
        self.id = UUID()
        self.name = name
        self.description = description
        self.creationDate = Date()
        self.streak = 0
        self.lastCompletedDate = nil
        self.completionDates = []
    }

    mutating func completeToday() {
        let today = Calendar.current.startOfDay(for: Date())

        // If already completed today, do nothing
        if let lastCompleted = lastCompletedDate,
           Calendar.current.isDate(lastCompleted, inSameDayAs: today) {
            return
        }

        // Check if yesterday was also completed to maintain streak
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: today)!
        if let lastCompleted = lastCompletedDate,
           Calendar.current.isDate(lastCompleted, inSameDayAs: yesterday) {
            streak += 1
        } else if lastCompletedDate == nil {
            streak = 1
        } else {
            streak = 1
        }

        lastCompletedDate = today
        completionDates.append(today)
    }

    func isCompletedToday() -> Bool {
        guard let lastCompleted = lastCompletedDate else { return false }
        return Calendar.current.isDateInToday(lastCompleted)
    }
}

extension Calendar {
    func startOfDay(for date: Date) -> Date {
        return self.startOfDay(for: date)
    }
}
