### Habit.swift
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var title: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var color: String

    init(id: UUID = UUID(), title: String, description: String, frequency: Frequency, color: String) {
        self.id = id
        self.title = title
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.color = color
    }

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var isCompletedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    mutating func toggleCompletion() {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: Date()) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let data = try? Data(contentsOf: try Self.fileURL()) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            guard let habits = try? JSONDecoder().decode([Habit].self, from: data) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            DispatchQueue.main.async {
                self?.habits = habits
            }
        }
    }

    func save() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let habits = self?.habits else { return }
            guard let data = try? JSONEncoder().encode(habits) else { return }
            try? data.write(to: try Self.fileURL(), options: [.atomicWrite])
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        save()
    }

    func toggleCompletion(for habitId: UUID) {
        if let index = habits.firstIndex(where: { $0.id == habitId }) {
            habits[index].toggleCompletion()
            save()
        }
    }
}
```

