import SwiftUI
import Charts

struct AnalyticsView: View {
    @ObservedObject var habitStore: HabitStore

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    // Overall completion rate
                    Section(header: Text("Overall Progress")) {
                        ProgressView(value: overallCompletionRate)
                            .tint(.blue)
                            .padding(.bottom, 5)

                        Text("\(Int(overallCompletionRate * 100))% of habits completed")
                            .font(.caption)
                            .foregroundColor(.secondary)
                    }

                    // Completion chart
                    Section(header: Text("Completion History")) {
                        Chart {
                            ForEach(habitStore.habits) { habit in
                                ForEach(habit.completionDates, id: \.self) { date in
                                    PointMark(
                                        x: .value("Date", date, unit: .day),
                                        y: .value("Habits", habit.name)
                                    )
                                    .foregroundStyle(by: .value("Habit", habit.name))
                                }
                            }
                        }
                        .frame(height: 300)
                        .chartXAxis {
                            AxisMarks(values: .stride(by: .day)) { value in
                                AxisGridLine()
                                AxisTick()
                                AxisValueLabel(format: .dateTime.day().month())
                            }
                        }
                        .chartYAxis {
                            AxisMarks(values: .automatic(desiredCount: habitStore.habits.count))
                        }
                    }

                    // Streak statistics
                    Section(header: Text("Streak Statistics")) {
                        VStack(alignment: .leading, spacing: 10) {
                            HStack {
                                Text("Longest Streak")
                                Spacer()
                                Text("\(longestStreak) days")
                            }

                            HStack {
                                Text("Average Streak")
                                Spacer()
                                Text("\(averageStreak, specifier: "%.1f") days")
                            }

                            HStack {
                                Text("Total Completions")
                                Spacer()
                                Text("\(totalCompletions)")
                            }
                        }
                    }
                }
                .padding()
            }
            .navigationTitle("Analytics")
        }
    }

    private var overallCompletionRate: Double {
        guard !habitStore.habits.isEmpty else { return 0 }
        let totalTargets = habitStore.habits.reduce(0) { $0 + $1.targetCount }
        let totalCompletions = habitStore.habits.reduce(0) { $0 + $1.completionDates.count }
        return Double(totalCompletions) / Double(totalTargets)
    }

    private var longestStreak: Int {
        habitStore.habits.map { $0.bestStreak }.max() ?? 0
    }

    private var averageStreak: Double {
        guard !habitStore.habits.isEmpty else { return 0 }
        let totalStreaks = habitStore.habits.reduce(0) { $0 + $1.bestStreak }
        return Double(totalStreaks) / Double(habitStore.habits.count)
    }

    private var totalCompletions: Int {
        habitStore.habits.reduce(0) { $0 + $1.completionDates.count }
    }
}
