    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, streak: Int = 0, lastCompleted: Date? = nil, isCompletedToday: Bool = false, reminders: [Reminder] = []) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.streak = streak
        self.lastCompleted = lastCompleted
        self.isCompletedToday = isCompletedToday
        self.reminders = reminders
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }
}

struct Reminder: Identifiable, Codable {
    let id: UUID
    var time: Date
    var isActive: Bool

    init(id: UUID = UUID(), time: Date, isActive: Bool = true) {
        self.id = id
        self.time = time
        self.isActive = isActive
    }
}
