### NotificationManager.swift
```swift
import UserNotifications

class NotificationManager {
    static let shared = NotificationManager()

    func requestAuthorization() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .badge, .sound]) { granted, error in
            if granted {
                print("Notification authorization granted")
            } else if let error = error {
                print("Notification authorization error: \(error.localizedDescription)")
            }
        }
    }

    func scheduleNotification(for habit: Habit) {
        for reminder in habit.reminders where reminder.isActive {
            let content = UNMutableNotificationContent()
            content.title = "Habit Reminder"
            content.body = "Don't forget to complete your \(habit.name) habit!"
            content.sound = .default

            var dateComponents = Calendar.current.dateComponents([.hour, .minute], from: reminder.time)
            dateComponents.second = 0

            let trigger = UNCalendarNotificationTrigger(dateMatching: dateComponents, repeats: true)

            let request = UNNotificationRequest(
                identifier: "habit_\(habit.id)_reminder_\(reminder.id)",
                content: content,
                trigger: trigger
            )

            UNUserNotificationCenter.current().add(request) { error in
                if let error = error {
                    print("Error scheduling notification: \(error.localizedDescription)")
                }
            }
        }
    }

    func cancelNotifications(for habit: Habit) {
        for reminder in habit.reminders {
            UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: ["habit_\(habit.id)_reminder_\(reminder.id)"])
        }
    }
}
