import SwiftUI

struct HabitProgressView: View {
    @Binding var habit: Habit

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Progress")
                .font(.headline)

            // Weekly progress view
            WeeklyProgressView(habit: $habit)

            // Completion statistics
            HStack {
                Text("Today:")
                Spacer()
                Text("\(habit.wasCompleted(on: Date()) ? "Completed" : "Not completed")")
                    .foregroundColor(habit.wasCompleted(on: Date()) ? .green : .red)
            }

            HStack {
                Text("This week:")
                Spacer()
                Text("\(completedThisWeek())/\(habit.targetFrequency * 7)")
            }
        }
        .padding()
        .background(Color(.systemGray6))
        .cornerRadius(10)
