    var completionDates: [Date]
    var targetCount: Int
    var color: String

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String, frequency: Frequency, targetCount: Int, color: String) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.targetCount = targetCount
        self.color = color
        self.completionDates = []
    }

    var completionCount: Int {
        completionDates.count
    }

    var progress: Double {
        guard targetCount > 0 else { return 0 }
        return min(Double(completionCount) / Double(targetCount), 1.0)
    }

    mutating func toggleCompletion(for date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }
}
