                            }
                        }

                    if notificationsEnabled {
                        DatePicker("Daily Reminder Time", selection: $dailyReminderTime, displayedComponents: .hourAndMinute)
                            .onChange(of: dailyReminderTime) { _ in
                                scheduleNotifications()
                            }
                    }
                }

                Section(header: Text("About")) {
                    HStack {
                        Text("Version")
                        Spacer()
                        Text("1.0")
                            .foregroundColor(.secondary)
                    }
                }
            }
            .navigationTitle("Settings")
        }
    }

    private func scheduleNotifications() {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .badge, .sound]) { success, error in
            if success {
                UNUserNotificationCenter.current().removeAllPendingNotificationRequests()

                let content = UNMutableNotificationContent()
                content.title = "Time to track your habits!"
                content.body = "Don't forget to update your habit progress today."
                content.sound = .default

                var dateComponents = Calendar.current.dateComponents([.hour, .minute], from: dailyReminderTime)
                dateComponents.second = 0

                let trigger = UNCalendarNotificationTrigger(dateMatching: dateComponents, repeats: true)
                let request = UNNotificationRequest(identifier: "dailyHabitReminder", content: content, trigger: trigger)

                UNUserNotificationCenter.current().add(request) { error in
                    if let error = error {
                        print("Error scheduling notification: \(error.localizedDescription)")
                    }
                }
            } else if let error = error {
                print("Error requesting notification permissions: \(error.localizedDescription)")
            }
        }
    }
}
