```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var streak: Int
    var lastCompleted: Date?
    var completionDates: [Date]

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, streak: Int = 0, lastCompleted: Date? = nil, completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.streak = streak
        self.lastCompleted = lastCompleted
        self.completionDates = completionDates
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    mutating func completeToday() {
        let today = Date()

        // If last completed was yesterday, increment streak
        if let lastCompleted = lastCompleted {
            let calendar = Calendar.current
            if calendar.isDateInYesterday(lastCompleted) {
                streak += 1
            } else if !calendar.isDateInToday(lastCompleted) {
                streak = 1
            }
        } else {
            streak = 1
        }

        lastCompleted = today
        completionDates.append(today)
    }

    func isCompletedToday() -> Bool {
        guard let lastCompleted = lastCompleted else { return false }
        return Calendar.current.isDateInToday(lastCompleted)
    }
}
```

