### Habit.swift
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetCount: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetCount: Int = 1, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.targetCount = targetCount
        self.color = color
        self.completionDates = []
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily, weekly, monthly
    }

    var progress: Double {
        let calendar = Calendar.current
        let now = Date()

        switch frequency {
        case .daily:
            let today = calendar.startOfDay(for: now)
            let completedToday = completionDates.filter { calendar.isDate($0, inSameDayAs: today) }.count
            return Double(completedToday) / Double(targetCount)

        case .weekly:
            let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!
            let weekEnd = calendar.date(byAdding: .day, value: 6, to: weekStart)!
            let completedThisWeek = completionDates.filter { $0 >= weekStart && $0 <= weekEnd }.count
            return Double(completedThisWeek) / Double(targetCount * 7)

        case .monthly:
            let monthStart = calendar.date(from: calendar.dateComponents([.year, .month], from: now))!
            let monthEnd = calendar.date(byAdding: .month, value: 1, to: monthStart)!
            let completedThisMonth = completionDates.filter { $0 >= monthStart && $0 < monthEnd }.count
            return Double(completedThisMonth) / Double(targetCount * 30)
        }
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: date)

        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
