```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetCount: Int
    var color: String

    enum Frequency: String, Codable, CaseIterable {
        case daily, weekly, monthly
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, targetCount: Int = 1, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetCount = targetCount
        self.color = color
    }

    var isCompleteToday: Bool {
        guard let today = Calendar.current.date(bySettingHour: 0, minute: 0, second: 0, of: Date()) else { return false }
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }

    var completionCount: Int {
        completionDates.count
    }

    mutating func toggleCompletion() {
        let today = Date()
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
