```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetFrequency: Int // Number of times per day
    var color: String // Hex color code
    var completionDates: [Date] // Dates when habit was completed

    init(id: UUID = UUID(), name: String, description: String, targetFrequency: Int, color: String) {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.color = color
        self.completionDates = []
    }

    // Check if habit was completed on a specific date
    func wasCompleted(on date: Date) -> Bool {
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: date) }
    }

    // Toggle completion status for a date
    mutating func toggleCompletion(on date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }
}
