import SwiftUI

struct AddHabitView: View {
    @EnvironmentObject var store: HabitStore
    @Environment(\.dismiss) var dismiss

    @State private var name: String = ""
    @State private var description: String = ""
    @State private var targetFrequency: Int = 1
    @State private var color: Color = .blue

    // For editing existing habits
    var habit: Habit?

    var body: some View {
        NavigationStack {
            Form {
                Section(header: Text("Habit Details")) {
                    TextField("Name", text: $name)
                    TextField("Description", text: $description)
                }

                Section(header: Text("Target")) {
                    Stepper("\(targetFrequency) time(s) per day", value: $targetFrequency, in: 1...10)
                }

                Section(header: Text("Color")) {
                    ColorPicker("Habit Color", selection: $color)
                }
            }
            .navigationTitle(habit == nil ? "New Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .navigationBarLeading) {
                    Button("Cancel") {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button(habit == nil ? "Add" : "Save") {
                        saveHabit()
                        dismiss()
                    }
                    .disabled(name.isEmpty)
                }
            }
            .onAppear {
                if let habit = habit {
                    name = habit.name
                    description = habit.description
                    targetFrequency = habit.targetFrequency
                    color = Color(hex: habit.color)
                }
            }
        }
    }

    private func saveHabit() {
        let habitColor = color.toHex() ?? "#0000FF"

        if let habit = habit {
            // Update existing habit
            var updatedHabit = habit
            updatedHabit.name = name
            updatedHabit.description = description
            updatedHabit.targetFrequency = targetFrequency
            updatedHabit.color = habitColor
            store.updateHabit(updatedHabit)
        } else {
            // Create new habit
            let newHabit = Habit(
                name: name,
                description: description,
                targetFrequency: targetFrequency,
                color: habitColor
            )
            store.addHabit(newHabit)
        }
    }
