```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetPerWeek: Int

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, targetPerWeek: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetPerWeek = targetPerWeek
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var completedThisWeek: Int {
        let calendar = Calendar.current
        let currentWeek = calendar.component(.weekOfYear, from: Date())

        return completionDates.filter { date in
            calendar.component(.weekOfYear, from: date) == currentWeek
        }.count
    }

    var progress: Double {
        guard targetPerWeek > 0 else { return 0 }
        return Double(completedThisWeek) / Double(targetPerWeek)
    }
}
