                        .foregroundColor(.gray.opacity(0.3))
                        .frame(width: geometry.size.width, height: 20)
                        .cornerRadius(10)

                    Rectangle()
                        .foregroundColor(.blue)
                        .frame(width: progressWidth(in: geometry.size.width), height: 20)
                        .cornerRadius(10)
                }
            }
            .frame(height: 20)

            Text("\(habit.completionCount) completions")
                .font(.caption)
