```swift
// Models/Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    var id = UUID()
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var color: String

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var streak: Int {
        guard let lastDate = completionDates.last else { return 0 }

        var currentDate = Calendar.current.startOfDay(for: Date())
        var streakCount = 0

        while let date = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
              completionDates.contains(date) {
            streakCount += 1
            currentDate = date
        }

        return streakCount
    }
}
