### 2. View Models

```swift
// HabitViewModel.swift
import Foundation

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    // Save habits to UserDefaults
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    // Load habits from UserDefaults
    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits") {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }
        // Default habits if none saved
        habits = [
            Habit(name: "Drink water", completionCount: 0),
            Habit(name: "Exercise", completionCount: 0),
            Habit(name: "Read", completionCount: 0)
        ]
    }

    // Add a new habit
    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        saveHabits()
    }

    // Mark a habit as completed
    func completeHabit(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].completionCount += 1
            habits[index].lastCompleted = Date()
            saveHabits()
        }
    }

    // Delete a habit
    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }
}
