### Habit Model (Habit.swift)
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var lastCompleted: Date?
    var streak: Int

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.streak = 0
    }

    mutating func complete() {
        let calendar = Calendar.current
        let now = Date()

        if let lastCompleted = lastCompleted {
            if calendar.isDateInYesterday(lastCompleted) {
                streak += 1
            } else if !calendar.isDateInToday(lastCompleted) {
                streak = 1
            }
        } else {
            streak = 1
        }

        lastCompleted = now
    }
}
```

### Habit Store (HabitStore.swift)
