import SwiftUI

// Model for a Habit
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completionDates: [Date]

    init(id: UUID = UUID(), name: String, completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.completionDates = completionDates
    }
}

// ViewModel for Habit Tracking
class HabitTracker: ObservableObject {
    @Published var habits: [Habit] = []

    // Save habits to UserDefaults
    func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    // Load habits from UserDefaults
    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    // Add a new habit
    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        saveHabits()
    }

    // Toggle habit completion for today
    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            let today = Calendar.current.startOfDay(for: Date())

            if habits[index].completionDates.contains(today) {
                // Remove today's date if already completed
                habits[index].completionDates.removeAll { Calendar.current.isDate($0, inSameDayAs: today) }
            } else {
                // Add today's date
                habits[index].completionDates.append(today)
            }

            saveHabits()
        }
    }

    // Get streak count for a habit
    func getStreak(for habit: Habit) -> Int {
        let sortedDates = habit.completionDates.sorted(by: >)
        var streak = 0
        var currentDate = Calendar.current.startOfDay(for: Date())

        for date in sortedDates {
            if Calendar.current.isDate(date, inSameDayAs: currentDate) {
                streak += 1
                currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate)!
            } else {
                break
            }
        }

        return streak
    }
}

