### b. Repository (for data access)

```kotlin
// BankRepository.kt
class BankRepository(private val context: Context) {
    private val firebaseAuth = FirebaseAuth.getInstance()
    private val firestore = FirebaseFirestore.getInstance()
    private val encryptedSharedPrefs = EncryptedSharedPreferences.create(
        "secure_prefs",
        MasterKey.Builder(context).setKeyScheme(MasterKey.KeyScheme.AES256_GCM).build(),
        context,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    // User authentication
    suspend fun login(email: String, password: String): Result<User> {
        return try {
            val authResult = firebaseAuth.signInWithEmailAndPassword(email, password).await()
            val user = getUserData(authResult.user?.uid ?: "")
            Result.success(user)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // Get user data from Firestore
    private suspend fun getUserData(userId: String): User {
        return try {
            val document = firestore.collection("users").document(userId).get().await()
            document.toObject(User::class.java) ?: throw Exception("User not found")
        } catch (e: Exception) {
            throw Exception("Failed to fetch user data: ${e.message}")
        }
    }

    // Get account transactions
    suspend fun getAccountTransactions(accountId: String): List<Transaction> {
        return try {
            val querySnapshot = firestore.collection("transactions")
                .whereEqualTo("fromAccount", accountId)
                .orWhereEqualTo("toAccount", accountId)
                .orderBy("date", Query.Direction.DESCENDING)
                .get()
                .await()

            querySnapshot.toObjects(Transaction::class.java)
        } catch (e: Exception) {
            emptyList()
        }
    }

    // Transfer money between accounts
    suspend fun transferMoney(
        fromAccountId: String,
        toAccountId: String,
        amount: Double,
        description: String
    ): Result<Transaction> {
        return try {
            // Create transaction
            val transaction = Transaction(
                transactionId = UUID.randomUUID().toString(),
                amount = amount,
                type = "Transfer",
                date = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date()),
                description = description,
                fromAccount = fromAccountId,
                toAccount = toAccountId
            )

            // Update accounts in Firestore
            firestore.runTransaction { transaction ->
                val fromAccountRef = firestore.collection("accounts").document(fromAccountId)
                val toAccountRef = firestore.collection("accounts").document(toAccountId)

                val fromAccount = transaction.get(fromAccountRef).toObject(Account::class.java)
                val toAccount = transaction.get(toAccountRef).toObject(Account::class.java)

                if (fromAccount?.balance ?: 0.0 < amount) {
                    throw Exception("Insufficient funds")
                }

                transaction.update(fromAccountRef, "balance", (fromAccount?.balance ?: 0.0) - amount)
                transaction.update(toAccountRef, "balance", (toAccount?.balance ?: 0.0) + amount)
            }.await()

            // Add transaction record
            firestore.collection("transactions").document(transaction.transactionId)
                .set(transaction)
                .await()

            Result.success(transaction)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // Save biometric preference
    fun saveBiometricPreference(enabled: Boolean) {
        encryptedSharedPrefs.edit().putBoolean("biometric_enabled", enabled).apply()
    }

    // Get biometric preference
    fun isBiometricEnabled(): Boolean {
        return encryptedSharedPrefs.getBoolean("biometric_enabled", false)
    }
}
```

### c. ViewModel

```kotlin
// BankViewModel.kt
class BankViewModel(application: Application) : AndroidViewModel(application) {
    private val repository = BankRepository(application)
    private val _user = MutableLiveData<User>()
    val user: LiveData<User> = _user

    private val _transactions = MutableLiveData<List<Transaction>>()
    val transactions: LiveData<List<Transaction>> = _transactions

    private val _transferResult = MutableLiveData<Result<Transaction>>()
    val transferResult: LiveData<Result<Transaction>> = _transferResult

    fun login(email: String, password: String) {
        viewModelScope.launch {
            val result = repository.login(email, password)
            if (result.isSuccess) {
                _user.value = result.getOrNull()
                loadAccountData(result.getOrNull()?.accounts?.firstOrNull()?.accountId ?: "")
            }
        }
    }

    fun loadAccountData(accountId: String) {
        viewModelScope.launch {
            _transactions.value = repository.getAccountTransactions(accountId)
        }
    }

    fun transferMoney(fromAccountId: String, toAccountId: String, amount: Double, description: String) {
        viewModelScope.launch {
            _transferResult.value = repository.transferMoney(fromAccountId, toAccountId, amount, description)
            if (_transferResult.value?.isSuccess == true) {
                loadAccountData(fromAccountId)
            }
        }
    }

    fun saveBiometricPreference(enabled: Boolean) {
        repository.saveBiometricPreference(enabled)
    }

    fun isBiometricEnabled(): Boolean {
        return repository.isBiometricEnabled()
    }
}
