## 3. Database (Room)

```kotlin
// AppDatabase.kt
@Database(entities = [User::class, Transaction::class], version = 1)
abstract class AppDatabase : RoomDatabase() {
    abstract fun userDao(): UserDao
    abstract fun transactionDao(): TransactionDao

    companion object {
        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getDatabase(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "banking_db"
                ).build()
                INSTANCE = instance
                instance
            }
        }
    }
}

// UserDao.kt
@Dao
interface UserDao {
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(user: User)

    @Query("SELECT * FROM user WHERE email = :email AND pin = :pin")
    suspend fun login(email: String, pin: String): User?

    @Query("SELECT * FROM user WHERE accountNumber = :accountNumber")
    suspend fun getUserByAccount(accountNumber: String): User?

    @Update
    suspend fun update(user: User)
}

// TransactionDao.kt
@Dao
interface TransactionDao {
    @Insert
    suspend fun insert(transaction: Transaction)

    @Query("SELECT * FROM transaction WHERE fromAccount = :accountNumber OR toAccount = :accountNumber ORDER BY date DESC")
    suspend fun getTransactions(accountNumber: String): List<Transaction>
}
