## 4. Repository

```kotlin
// BankingRepository.kt
class BankingRepository(private val userDao: UserDao, private val transactionDao: TransactionDao) {

    suspend fun login(email: String, pin: String): User? {
        return userDao.login(email, pin)
    }

    suspend fun getUserByAccount(accountNumber: String): User? {
        return userDao.getUserByAccount(accountNumber)
    }

    suspend fun getTransactions(accountNumber: String): List<Transaction> {
        return transactionDao.getTransactions(accountNumber)
    }

    suspend fun transferFunds(fromAccount: String, toAccount: String, amount: Double, description: String) {
        val fromUser = userDao.getUserByAccount(fromAccount)
        val toUser = userDao.getUserByAccount(toAccount)

        if (fromUser != null && toUser != null && fromUser.balance >= amount) {
            // Update balances
            val updatedFromUser = fromUser.copy(balance = fromUser.balance - amount)
            val updatedToUser = toUser.copy(balance = toUser.balance + amount)

            userDao.update(updatedFromUser)
            userDao.update(updatedToUser)

            // Record transaction
            val transaction = Transaction(
                id = UUID.randomUUID().toString(),
                fromAccount = fromAccount,
                toAccount = toAccount,
                amount = amount,
                date = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date()),
                description = description,
                type = TransactionType.TRANSFER
            )

            transactionDao.insert(transaction)
        } else {
            throw Exception("Insufficient funds or invalid accounts")
        }
    }
}
```

## 5. ViewModel

```kotlin
// BankingViewModel.kt
class BankingViewModel(application: Application) : AndroidViewModel(application) {
    private val repository: BankingRepository
    private val _user = MutableLiveData<User?>()
    val user: LiveData<User?> = _user
    private val _transactions = MutableLiveData<List<Transaction>>()
    val transactions: LiveData<List<Transaction>> = _transactions
    private val _error = MutableLiveData<String?>()
    val error: LiveData<String?> = _error

    init {
        val userDao = AppDatabase.getDatabase(application).userDao()
        val transactionDao = AppDatabase.getDatabase(application).transactionDao()
        repository = BankingRepository(userDao, transactionDao)
    }

    fun login(email: String, pin: String) {
        viewModelScope.launch {
            try {
                _user.value = repository.login(email, pin)
                if (_user.value == null) {
                    _error.value = "Invalid credentials"
                }
            } catch (e: Exception) {
                _error.value = e.message
            }
        }
    }

    fun loadTransactions(accountNumber: String) {
        viewModelScope.launch {
            try {
                _transactions.value = repository.getTransactions(accountNumber)
            } catch (e: Exception) {
                _error.value = e.message
            }
        }
    }

    fun transferFunds(fromAccount: String, toAccount: String, amount: Double, description: String) {
        viewModelScope.launch {
            try {
                repository.transferFunds(fromAccount, toAccount, amount, description)
                _user.value = repository.getUserByAccount(fromAccount)
                loadTransactions(fromAccount)
            } catch (e: Exception) {
                _error.value = e.message
            }
        }
    }

    fun clearError() {
        _error.value = null
    }
}
