```kotlin
// MainActivity.kt
class MainActivity : AppCompatActivity() {
    private lateinit var binding: ActivityMainBinding
    private lateinit var viewModel: BankingViewModel
    private lateinit var transactionAdapter: TransactionAdapter

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        viewModel = ViewModelProvider(this).get(BankingViewModel::class.java)

        // Setup RecyclerView
        transactionAdapter = TransactionAdapter()
        binding.transactionRecyclerView.layoutManager = LinearLayoutManager(this)
        binding.transactionRecyclerView.adapter = transactionAdapter

        // Load user data
        val userId = intent.getStringExtra("USER_ID")
        userId?.let {
            viewModel.loadUser(it)
            viewModel.loadTransactions(it)
        }

        // Setup observers
        viewModel.user.observe(this) { user ->
            user?.let {
                binding.balanceTextView.text = String.format("$%.2f", it.balance)
                binding.accountNumberTextView.text = it.accountNumber
            }
        }

        viewModel.transactions.observe(this) { transactions ->
            transactionAdapter.submitList(transactions)
        }

        // Setup click listeners
        binding.transferButton.setOnClickListener {
            showTransferDialog()
        }

        binding.logoutButton.setOnClickListener {
            val intent = Intent(this, LoginActivity::class.java)
            startActivity(intent)
            finish()
        }
    }

    private fun showTransferDialog() {
        val dialogView = LayoutInflater.from(this).inflate(R.layout.dialog_transfer, null)
        val builder = AlertDialog.Builder(this)
            .setView(dialogView)
            .setTitle("Transfer Funds")

        val alertDialog = builder.create()

        dialogView.findViewById<Button>(R.id.transferButton).setOnClickListener {
            val toAccount = dialogView.findViewById<EditText>(R.id.toAccountEditText).text.toString()
            val amount = dialogView.findViewById<EditText>(R.id.amountEditText).text.toString().toDoubleOrNull()
            val description = dialogView.findViewById<EditText>(R.id.descriptionEditText).text.toString()

            if (toAccount.isNotEmpty() && amount != null && amount > 0) {
                viewModel.user.value?.let { user ->
                    viewModel.transferFunds(user.accountNumber, toAccount, amount, description)
                }
                alertDialog.dismiss()
            } else {
                Toast.makeText(this, "Please enter valid details", Toast.LENGTH_SHORT).show()
            }
        }

        alertDialog.show()
    }
}
