## 3. Repository (Network & Local)

```kotlin
// BankRepository.kt
class BankRepository(private val apiService: BankApiService, private val localDataSource: LocalDataSource) {

    suspend fun getUserAccounts(userId: String): Result<List<Account>> {
        return try {
            val remoteAccounts = apiService.getAccounts(userId)
            localDataSource.saveAccounts(remoteAccounts)
            Result.success(remoteAccounts)
        } catch (e: Exception) {
            try {
                val localAccounts = localDataSource.getAccounts(userId)
                Result.success(localAccounts)
            } catch (localError: Exception) {
                Result.failure(localError)
            }
        }
    }

    suspend fun getTransactions(accountNumber: String): Result<List<Transaction>> {
        return try {
            val transactions = apiService.getTransactions(accountNumber)
            Result.success(transactions)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun transferFunds(
        fromAccount: String,
        toAccount: String,
        amount: Double,
        description: String
    ): Result<Transaction> {
        return try {
            val transaction = apiService.transferFunds(
                TransferRequest(fromAccount, toAccount, amount, description)
            )
            Result.success(transaction)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

// BankApiService.kt
interface BankApiService {
    @GET("accounts/{userId}")
    suspend fun getAccounts(@Path("userId") userId: String): List<Account>

    @GET("transactions/{accountNumber}")
    suspend fun getTransactions(@Path("accountNumber") accountNumber: String): List<Transaction>

    @POST("transfer")
    suspend fun transferFunds(@Body request: TransferRequest): Transaction
}

data class TransferRequest(
    val fromAccount: String,
    val toAccount: String,
    val amount: Double,
    val description: String
)
