### e. Money Transfer Activity

```kotlin
// TransferActivity.kt
class TransferActivity : AppCompatActivity() {

    private lateinit var binding: ActivityTransferBinding
    private lateinit var auth: FirebaseAuth
    private lateinit var firestore: FirebaseFirestore

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityTransferBinding.inflate(layoutInflater)
        setContentView(binding.root)

        auth = FirebaseAuth.getInstance()
        firestore = FirebaseFirestore.getInstance()

        binding.btnTransfer.setOnClickListener {
            val recipientAccount = binding.etRecipientAccount.text.toString().trim()
            val amount = binding.etAmount.text.toString().toDoubleOrNull() ?: 0.0
            val description = binding.etDescription.text.toString().trim()

            if (recipientAccount.isEmpty() || amount <= 0) {
                Toast.makeText(this, "Please enter valid details", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }

            transferMoney(recipientAccount, amount, description)
        }
    }

    private fun transferMoney(recipientAccount: String, amount: Double, description: String) {
        val userId = auth.currentUser?.uid ?: return

        // Get sender's account
        firestore.collection("users").document(userId)
            .get()
            .addOnSuccessListener { senderDoc ->
                val senderBalance = senderDoc.getDouble("accountBalance") ?: 0.0

                if (senderBalance < amount) {
                    Toast.makeText(this, "Insufficient balance", Toast.LENGTH_SHORT).show()
                    return@addOnSuccessListener
                }

                // Find recipient by account number
                firestore.collection("users")
                    .whereEqualTo("accountNumber", recipientAccount)
                    .get()
                    .addOnSuccessListener { recipientQuery ->
                        if (recipientQuery.isEmpty) {
                            Toast.makeText(this, "Recipient not found", Toast.LENGTH_SHORT).show()
                            return@addOnSuccessListener
                        }

                        val recipientDoc = recipientQuery.documents[0]
                        val recipientId = recipientDoc.id
                        val recipientBalance = recipientDoc.getDouble("accountBalance") ?: 0.0

                        // Update balances
                        val batch = firestore.batch()

                        // Deduct from sender
                        batch.update(
                            firestore.collection("users").document(userId),
                            "accountBalance", senderBalance - amount
                        )

                        // Add to recipient
                        batch.update(
                            firestore.collection("users").document(recipientId),
                            "accountBalance", recipientBalance + amount
                        )

                        // Add transaction records
                        val transaction = hashMapOf(
                            "amount" to amount,
                            "type" to "Transfer",
                            "date" to SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(Date()),
                            "description" to description,
                            "timestamp" to System.currentTimeMillis()
                        )

                        // Sender's transaction record
                        batch.set(
                            firestore.collection("users").document(userId)
                                .collection("transactions").document(),
                            transaction
                        )

                        // Recipient's transaction record
                        batch.set(
                            firestore.collection("users").document(recipientId)
                                .collection("transactions").document(),
                            transaction
                        )

                        batch.commit()
                            .addOnSuccessListener {
                                Toast.makeText(this, "Transfer successful", Toast.LENGTH_SHORT).show()
                                finish()
                            }
                            .addOnFailureListener {
                                Toast.makeText(this, "Transfer failed", Toast.LENGTH_SHORT).show()
                            }
                    }
            }
    }
}
```

