### c. Repository

```kotlin
// data/repository/BankingRepository.kt
class BankingRepository private constructor(
    private val userDao: UserDao,
    private val transactionDao: TransactionDao
) {
    suspend fun login(email: String, pin: String): User? {
        val user = userDao.getUserByEmail(email)
        return if (user?.pin == pin) user else null
    }

    suspend fun register(user: User) {
        userDao.insert(user)
    }

    suspend fun getAccountDetails(accountNumber: String): User? {
        return userDao.getUserByAccountNumber(accountNumber)
    }

    suspend fun transferFunds(
        fromAccount: String,
        toAccount: String,
        amount: Double,
        description: String
    ): Boolean {
        val fromUser = userDao.getUserByAccountNumber(fromAccount)
        val toUser = userDao.getUserByAccountNumber(toAccount)

        if (fromUser == null || toUser == null || fromUser.balance < amount) {
            return false
        }

        // Update balances
        val updatedFromUser = fromUser.copy(balance = fromUser.balance - amount)
        val updatedToUser = toUser.copy(balance = toUser.balance + amount)

        userDao.update(updatedFromUser)
        userDao.update(updatedToUser)

        // Record transaction
        val transaction = Transaction(
            id = UUID.randomUUID().toString(),
            fromAccount = fromAccount,
            toAccount = toAccount,
            amount = amount,
            date = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date()),
            type = TransactionType.TRANSFER,
            description = description
        )

        transactionDao.insert(transaction)
        return true
    }

    suspend fun getTransactions(accountNumber: String): List<Transaction> {
        return transactionDao.getTransactionsByAccount(accountNumber)
    }

    companion object {
        @Volatile
        private var INSTANCE: BankingRepository? = null

        fun getInstance(userDao: UserDao, transactionDao: TransactionDao): BankingRepository {
            return INSTANCE ?: synchronized(this) {
                val instance = BankingRepository(userDao, transactionDao)
                INSTANCE = instance
                instance
            }
        }
    }
}
