### 2.4. Repository

```kotlin
// BankingRepository.kt
class BankingRepository(private val userDao: UserDao, private val transactionDao: TransactionDao) {

    suspend fun getUser(userId: Int): User? = userDao.getUserById(userId)

    suspend fun getUserByEmail(email: String): User? = userDao.getUserByEmail(email)

    suspend fun updateUser(user: User) = userDao.update(user)

    suspend fun getTransactions(accountNumber: String): List<Transaction> =
        transactionDao.getTransactionsByAccount(accountNumber)

    suspend fun makeTransaction(transaction: Transaction) {
        transactionDao.insert(transaction)

        // Update balances
        val fromUser = userDao.getUserByAccountNumber(transaction.fromAccount)
        val toUser = userDao.getUserByAccountNumber(transaction.toAccount)

        fromUser?.let {
            val newBalance = it.balance - transaction.amount
            userDao.update(it.copy(balance = newBalance))
        }

        toUser?.let {
            val newBalance = it.balance + transaction.amount
            userDao.update(it.copy(balance = newBalance))
        }
    }

    private suspend fun getUserByAccountNumber(accountNumber: String): User? {
        // This would be implemented based on your actual database schema
        // For simplicity, we're assuming a method exists
        return null
    }
}
