    fun makeTransaction(transaction: Transaction) {
        viewModelScope.launch {
            repository.makeTransaction(transaction)
            loadUser(user.value?.id ?: 0) // Refresh user data
            loadTransactions(transaction.fromAccount) // Refresh transactions
