@Composable
fun TransactionItem(transaction: Transaction) {
    val color = when (transaction.type) {
        TransactionType.DEPOSIT -> Color.Green
        TransactionType.WITHDRAWAL -> Color.Red
        TransactionType.TRANSFER -> Color.Blue
    }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(40.dp)
                .background(color, CircleShape)
                .padding(8.dp),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = when (transaction.type) {
                    TransactionType.DEPOSIT -> Icons.Default.ArrowDownward
                    TransactionType.WITHDRAWAL -> Icons.Default.ArrowUpward
                    TransactionType.TRANSFER -> Icons.Default.SwapHoriz
                },
                contentDescription = transaction.type.name,
                tint = Color.White
            )
