### 3. ViewModel (ui package)

```kotlin
// ui/viewmodel/BankingViewModel.kt
class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {
    private val _user = MutableStateFlow<User?>(null)
    val user: StateFlow<User?> = _user

    private val _transactions = MutableStateFlow<List<Transaction>>(emptyList())
    val transactions: StateFlow<List<Transaction>> = _transactions

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading

    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error

    fun loadUserData(userId: String) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                _user.value = repository.getUserDetails(userId)
                _transactions.value = repository.getTransactions(userId)
            } catch (e: Exception) {
                _error.value = "Failed to load user data: ${e.message}"
            } finally {
                _isLoading.value = false
            }
        }
    }

    fun performTransfer(toAccount: String, amount: Double) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                val fromAccount = user.value?.accountNumber ?: return@launch
                val success = repository.performTransfer(fromAccount, toAccount, amount)
                if (success) {
                    // Refresh data
                    loadUserData(user.value?.id ?: return@launch)
                } else {
                    _error.value = "Transfer failed"
                }
            } catch (e: Exception) {
                _error.value = "Transfer error: ${e.message}"
            } finally {
                _isLoading.value = false
            }
        }
    }

    fun clearError() {
        _error.value = null
    }
}
```

