## 5. Repository

### BankingRepository.kt
```kotlin
class BankingRepository(private val accountDao: AccountDao,
                        private val transactionDao: TransactionDao,
                        private val userDao: UserDao,
                        private val apiService: ApiService) {

    // Local database operations
    fun getAccounts(userId: String): LiveData<List<Account>> = accountDao.getAccountsByUser(userId)
    fun getAccountDetails(accountId: String): LiveData<Account> = accountDao.getAccountById(accountId)
    fun getTransactions(accountId: String): LiveData<List<Transaction>> = transactionDao.getTransactionsByAccount(accountId)

    // Remote API operations
    suspend fun fetchAccounts(userId: String): Result<List<Account>> {
        return try {
            val response = apiService.getAccounts(userId)
            if (response.isSuccessful) {
                response.body()?.let { accounts ->
                    accountDao.insertAll(accounts)
                    Result.success(accounts)
                } ?: Result.failure(Exception("Empty response"))
            } else {
                Result.failure(Exception("Failed to fetch accounts"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    // Add other repository methods as needed
}
```

