class BankingViewModel(private val repository: BankingRepository) : ViewModel() {
    private val _accounts = MutableLiveData<List<Account>>()
    val accounts: LiveData<List<Account>> = _accounts

    private val _accountDetails = MutableLiveData<Account>()
    val accountDetails: LiveData<Account> = _accountDetails

    private val _transactions = MutableLiveData<List<Transaction>>()
    val transactions: LiveData<List<Transaction>> = _transactions

    private val _isLoading = MutableLiveData<Boolean>()
    val isLoading: LiveData<Boolean> = _isLoading

    private val _error = MutableLiveData<String>()
    val error: LiveData<String> = _error

    fun loadAccounts(userId: String) {
        viewModelScope.launch {
            _isLoading.value = true
            val result = repository.fetchAccounts(userId)
            _isLoading.value = false

            result.onSuccess { accounts ->
                _accounts.value = accounts
            }.onFailure { exception ->
                _error.value = exception.message ?: "Unknown error"
            }
        }
    }

    fun loadAccountDetails(accountId: String) {
        viewModelScope.launch {
            _isLoading.value = true
            _accountDetails.value = repository.getAccountDetails(accountId).value
            _isLoading.value = false
        }
    }

    fun loadTransactions(accountId: String) {
        viewModelScope.launch {
            _isLoading.value = true
            _transactions.value = repository.getTransactions(accountId).value
            _isLoading.value = false
        }
    }
}
