class BankRepository(private val accountDao: AccountDao, private val transactionDao: TransactionDao) {

    suspend fun getAllAccounts(): List<Account> = accountDao.getAllAccounts()

    suspend fun getAccountById(accountId: String): Account? = accountDao.getAccountById(accountId)

    suspend fun getTransactionsByAccountId(accountId: String): List<Transaction> =
        transactionDao.getTransactionsByAccountId(accountId)

    suspend fun addTransaction(transaction: Transaction) {
        transactionDao.insertTransaction(transaction)
    }

    suspend fun updateAccountBalance(accountId: String, newBalance: Double) {
        val account = accountDao.getAccountById(accountId)?.copy(balance = newBalance)
        account?.let { accountDao.insertAccount(it) }
    }
}
