### 2.5. ViewModel (BankViewModel.kt)

```kotlin
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class BankViewModel(private val repository: BankRepository) : ViewModel() {

    private val _accounts = MutableStateFlow<List<Account>>(emptyList())
    val accounts: StateFlow<List<Account>> = _accounts

    private val _transactions = MutableStateFlow<List<Transaction>>(emptyList())
    val transactions: StateFlow<List<Transaction>> = _transactions

    private val _selectedAccount = MutableStateFlow<Account?>(null)
    val selectedAccount: StateFlow<Account?> = _selectedAccount

    fun loadAccounts() {
        viewModelScope.launch {
            _accounts.value = repository.getAllAccounts()
        }
    }

    fun selectAccount(accountId: String) {
        viewModelScope.launch {
            _selectedAccount.value = repository.getAccountById(accountId)
            loadTransactions(accountId)
        }
    }

    fun loadTransactions(accountId: String) {
        viewModelScope.launch {
            _transactions.value = repository.getTransactionsByAccountId(accountId)
        }
    }

    fun performTransaction(accountId: String, amount: Double, type: String, description: String) {
        viewModelScope.launch {
            val account = repository.getAccountById(accountId) ?: return@launch

            val newBalance = when (type) {
                "DEBIT" -> account.balance - amount
                "CREDIT" -> account.balance + amount
                else -> account.balance
            }

            if (newBalance < 0) {
                // Handle insufficient funds
                return@launch
            }

            val transaction = Transaction(
                id = generateTransactionId(),
                date = getCurrentDate(),
                amount = amount,
                type = type,
                description = description,
                balanceAfter = newBalance
            )

            repository.addTransaction(transaction)
            repository.updateAccountBalance(accountId, newBalance)
            selectAccount(accountId) // Refresh data
        }
    }

    private fun generateTransactionId(): String = UUID.randomUUID().toString()

    private fun getCurrentDate(): String {
        val dateFormat = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault())
        return dateFormat.format(Date())
    }
}
