class AccountDetailFragment : Fragment() {

    private var _binding: FragmentAccountDetailBinding? = null
    private val binding get() = _binding!!
    private val viewModel: BankViewModel by activityViewModels()
    private lateinit var adapter: TransactionAdapter

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentAccountDetailBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupRecyclerView()
        observeAccountDetails()
        observeTransactions()

        binding.fabAddTransaction.setOnClickListener {
            // Show transaction dialog
            showTransactionDialog()
        }
    }

    private fun setupRecyclerView() {
        adapter = TransactionAdapter()
        binding.recyclerViewTransactions.layoutManager = LinearLayoutManager(requireContext())
        binding.recyclerViewTransactions.adapter = adapter
    }

    private fun observeAccountDetails() {
        lifecycleScope.launch {
            viewModel.selectedAccount.collect { account ->
                account?.let {
                    binding.accountNumber.text = it.accountNumber
                    binding.accountType.text = it.accountType
                    binding.accountBalance.text = "${it.currency} ${"%.2f".format(it.balance)}"
                }
            }
        }
    }

    private fun observeTransactions() {
        lifecycleScope.launch {
            viewModel.transactions.collect { transactions ->
                adapter.submitList(transactions)
            }
        }
    }

    private fun showTransactionDialog() {
        val dialog = TransactionDialogFragment { amount, type, description ->
            viewModel.selectedAccount.value?.let { account ->
                viewModel.performTransaction(
                    accountId = account.id,
                    amount = amount,
                    type = type,
                    description = description
                )
            }
        }
        dialog.show(childFragmentManager, "TransactionDialog")
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
