```kotlin
import android.app.Dialog
import android.os.Bundle
import android.widget.ArrayAdapter
import androidx.appcompat.app.AlertDialog
import androidx.fragment.app.DialogFragment
import com.example.bankingapp.databinding.DialogTransactionBinding

class TransactionDialogFragment(
    private val onTransactionAdded: (amount: Double, type: String, description: String) -> Unit
) : DialogFragment() {

    private var _binding: DialogTransactionBinding? = null
    private val binding get() = _binding!!

    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {
        _binding = DialogTransactionBinding.inflate(layoutInflater)

        // Setup spinner
        val transactionTypes = arrayOf("DEBIT", "CREDIT")
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_item, transactionTypes)
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        binding.spinnerTransactionType.adapter = adapter

        return AlertDialog.Builder(requireContext())
            .setTitle("Add Transaction")
            .setView(binding.root)
            .setPositiveButton("Add") { _, _ ->
                val amount = binding.editTextAmount.text.toString().toDoubleOrNull() ?: 0.0
                val type = binding.spinnerTransactionType.selectedItem.toString()
                val description = binding.editTextDescription.text.toString()

                if (amount > 0 && description.isNotBlank()) {
                    onTransactionAdded(amount, type, description)
                }
            }
            .setNegativeButton("Cancel", null)
            .create()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
