# Offline-First Field Surveying App with Sync Capability

Below is a comprehensive implementation of an offline-first field surveying app that syncs data when reconnected to the network. This example uses React with TypeScript and a service worker for offline capabilities.

## 1. Project Setup

First, create a new React project with TypeScript:

```bash
npx create-react-app field-survey-app --template typescript
cd field-survey-app
npm install dexie @types/dexie react-router-dom @mui/material @mui/icons-material
```

## 2. Database Implementation (IndexedDB)

```typescript
// src/db.ts
import Dexie, { Table } from 'dexie';

export interface Survey {
  id?: number;
  title: string;
  location: string;
  date: string;
  notes: string;
  images: string[]; // Base64 encoded images
  status: 'draft' | 'submitted';
  lastModified: number;
}

export class SurveyDB extends Dexie {
  surveys!: Table<Survey>;

  constructor() {
    super('SurveyDB');
    this.version(1).stores({
      surveys: '++id, title, location, date, status, lastModified'
    });
  }

  async saveSurvey(survey: Survey) {
    if (survey.id) {
      return this.surveys.update(survey.id, {
        ...survey,
        lastModified: Date.now()
      });
    } else {
      return this.surveys.add({
        ...survey,
        status: 'draft',
        lastModified: Date.now()
      });
    }
  }

  async getAllSurveys() {
    return this.surveys.toArray();
  }

  async getSurvey(id: number) {
    return this.surveys.get(id);
  }

  async markAsSubmitted(id: number) {
    return this.surveys.update(id, {
      status: 'submitted',
      lastModified: Date.now()
    });
  }

  async getUnsyncedSurveys() {
    return this.surveys.where('status').equals('submitted').toArray();
  }
}

export const db = new SurveyDB();
```

## 3. Sync Service

```typescript
// src/syncService.ts
import { db, Survey } from './db';

const API_ENDPOINT = 'https://api.example.com/surveys';

export async function syncData() {
  if (!navigator.onLine) {
    console.log('Offline - skipping sync');
    return;
  }

  try {
    const unsyncedSurveys = await db.getUnsyncedSurveys();

    for (const survey of unsyncedSurveys) {
      const response = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(survey),
      });

      if (response.ok) {
        // Remove from local DB after successful sync
        await db.surveys.delete(survey.id!);
      }
    }

    console.log(`Synced ${unsyncedSurveys.length} surveys`);
  } catch (error) {
    console.error('Sync failed:', error);
  }
}

// Listen for online events to trigger sync
window.addEventListener('online', syncData);
```

