function SurveyForm() {
  const [survey, setSurvey] = useState<Partial<Survey>>({
    title: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    notes: '',
    images: []
  });
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnlineStatus = () => {
      setIsOnline(navigator.onLine);
    };

    window.addEventListener('online', handleOnlineStatus);
    window.addEventListener('offline', handleOnlineStatus);

    return () => {
      window.removeEventListener('online', handleOnlineStatus);
      window.removeEventListener('offline', handleOnlineStatus);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setSurvey(prev => ({ ...prev, [name]: value }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const readers = files.map(file => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });

      Promise.all(readers).then(images => {
        setSurvey(prev => ({
          ...prev,
          images: [...(prev.images || []), ...images]
        }));
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await db.saveSurvey({
        ...survey as Survey,
        status: isOnline ? 'submitted' : 'draft'
      });

      if (isOnline) {
        await syncData();
      }

      alert(`Survey saved ${isOnline ? 'and submitted' : 'as draft (will sync when online)'}`);
      setSurvey({
        title: '',
        location: '',
        date: new Date().toISOString().split('T')[0],
        notes: '',
        images: []
      });
    } catch (error) {
      console.error('Error saving survey:', error);
      alert('Failed to save survey');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Typography variant="h5" gutterBottom>
        New Survey
      </Typography>
      <div style={{ marginBottom: '1rem' }}>
        <input
          type="text"
          name="title"
          placeholder="Title"
          value={survey.title}
          onChange={handleChange}
          required
          style={{ width: '100%', padding: '0.5rem' }}
        />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <input
          type="text"
          name="location"
          placeholder="Location"
          value={survey.location}
          onChange={handleChange}
          required
          style={{ width: '100%', padding: '0.5rem' }}
        />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <input
          type="date"
          name="date"
          value={survey.date}
          onChange={handleChange}
          required
          style={{ width: '100%', padding: '0.5rem' }}
        />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <textarea
          name="notes"
          placeholder="Notes"
          value={survey.notes}
          onChange={handleChange}
          style={{ width: '100%', padding: '0.5rem', minHeight: '100px' }}
        />
      </div>
      <div style={{ marginBottom: '1rem' }}>
        <input
          type="file"
          accept="image/*"
          multiple
          onChange={handleImageUpload}
        />
        {survey.images && survey.images.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', marginTop: '10px' }}>
            {survey.images.map((img, index) => (
              <img
                key={index}
                src={img}
                alt={`Survey ${index}`}
                style={{ width: '100px', height: '100px', objectFit: 'cover' }}
              />
            ))}
          </div>
        )}
      </div>
      <Button type="submit" variant="contained" color="primary">
        Save Survey
      </Button>
      <div style={{ marginTop: '1rem' }}>
        <Typography variant="body2" color={isOnline ? 'primary' : 'error'}>
          {isOnline ? 'Online - surveys will sync automatically' : 'Offline - surveys will be saved and synced when online'}
        </Typography>
      </div>
    </form>
  );
}

function App() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [unsyncedCount, setUnsyncedCount] = useState(0);

  useEffect(() => {
    const handleOnlineStatus = () => {
      setIsOnline(navigator.onLine);
      if (navigator.onLine) {
        syncData();
      }
    };

    const checkUnsynced = async () => {
      const unsynced = await db.getUnsyncedSurveys();
      setUnsyncedCount(unsynced.length);
    };

    window.addEventListener('online', handleOnlineStatus);
    window.addEventListener('offline', handleOnlineStatus);

    // Check for unsynced surveys periodically
    const interval = setInterval(checkUnsynced, 5000);

    return () => {
      window.removeEventListener('online', handleOnlineStatus);
      window.removeEventListener('offline', handleOnlineStatus);
      clearInterval(interval);
    };
  }, []);

  const handleSyncClick = () => {
    syncData();
  };

  return (
    <Router>
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            Field Survey App
          </Typography>
          <IconButton color="inherit" onClick={handleSyncClick}>
            <Badge badgeContent={unsyncedCount} color="error">
              <SyncIcon />
            </Badge>
          </IconButton>
          <Button color="inherit" component={Link} to="/new">
            <AddIcon /> New Survey
          </Button>
        </Toolbar>
      </AppBar>
