  const [surveys, setSurveys] = useState([]);
  const [currentSurvey, setCurrentSurvey] = useState(null);
  const [isOnline, setIsOnline] = useState(false);
  const [syncStatus, setSyncStatus] = useState('idle');

  // Load surveys from local storage on app start
  useEffect(() => {
    loadSurveys();
  }, []);

  // Set up network status listener
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) {
        syncSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from AsyncStorage
  const loadSurveys = async () => {
    try {
      const savedSurveys = await AsyncStorage.getItem('surveys');
      if (savedSurveys) {
        setSurveys(JSON.parse(savedSurveys));
      }
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  };

  // Save surveys to AsyncStorage
  const saveSurveys = async (surveysToSave) => {
    try {
      await AsyncStorage.setItem('surveys', JSON.stringify(surveysToSave));
    } catch (error) {
      console.error('Error saving surveys:', error);
    }
  };

  // Create a new survey
