      id: Date.now().toString(),
      title: 'New Survey',
      location: '',
      date: new Date(),
      questions: [
        { id: '1', text: 'What is your name?', type: 'text' },
        { id: '2', text: 'How old are you?', type: 'number' },
        { id: '3', text: 'Do you have any comments?', type: 'text' }
      ],
      responses: {},
      isSynced: false,
      lastModified: new Date()
    };

    const updatedSurveys = [...surveys, newSurvey];
    setSurveys(updatedSurveys);
    saveSurveys(updatedSurveys);
    setCurrentSurvey(newSurvey);
  };

  // Update survey responses
  const updateResponse = (surveyId, questionId, value) => {
    const updatedSurveys = surveys.map(survey => {
      if (survey.id === surveyId) {
        return {
          ...survey,
          responses: {
            ...survey.responses,
            [questionId]: value
          },
          isSynced: false,
          lastModified: new Date()
        };
      }
      return survey;
    });

    setSurveys(updatedSurveys);
    saveSurveys(updatedSurveys);
  };

  // Sync surveys with server when online
  const syncSurveys = async () => {
    if (!isOnline) return;

    setSyncStatus('syncing');
    const unsyncedSurveys = surveys.filter(survey => !survey.isSynced);

    if (unsyncedSurveys.length === 0) {
      setSyncStatus('idle');
      return;
    }

    try {
      // Simulate API call to sync data
      // In a real app, you would use fetch or axios to your backend
      console.log('Syncing surveys:', unsyncedSurveys);

      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 1000));

      // Mark surveys as synced
      const updatedSurveys = surveys.map(survey => {
        if (!survey.isSynced) {
          return { ...survey, isSynced: true };
        }
        return survey;
      });

      setSurveys(updatedSurveys);
      saveSurveys(updatedSurveys);
      setSyncStatus('success');
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('error');
    }
  };

