        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={styles.surveyItem}>
            <Text>{item.title}</Text>
            <Text>{new Date(item.date).toLocaleDateString()}</Text>
            {!item.isSynced && <Text style={styles.unsynced}>Unsynced</Text>}
            <Button
              title="View Survey"
              onPress={() => setCurrentSurvey(item)}
            />
          </View>
        )}
      />

      <Button
        title="Create New Survey"
        onPress={createSurvey}
      />
    </View>
  );

  // Render survey form
  const renderSurveyForm = () => (
    <View style={styles.container}>
      <Text style={styles.title}>{currentSurvey.title}</Text>

      {currentSurvey.questions.map(question => (
        <View key={question.id} style={styles.questionContainer}>
          <Text>{question.text}</Text>
          <TextInput
            style={styles.input}
            value={currentSurvey.responses[question.id] || ''}
            onChangeText={text => updateResponse(currentSurvey.id, question.id, text)}
            keyboardType={question.type === 'number' ? 'numeric' : 'default'}
            multiline={question.type === 'text'}
          />
        </View>
      ))}

      <View style={styles.buttonContainer}>
        <Button
          title="Back to Surveys"
          onPress={() => setCurrentSurvey(null)}
        />
        <Button
          title="Sync Now"
          onPress={syncSurveys}
          disabled={!isOnline}
        />
      </View>
    </View>
  );

  return (
    <View style={styles.container}>
      {currentSurvey ? renderSurveyForm() : renderSurveyList()}
    </View>
  );
};

