### 2. Network Service with Offline Handling

```typescript
// services/networkService.ts
import { Survey } from '../models/Survey';

const API_URL = 'https://your-api-endpoint.com/surveys';

export const syncSurveys = async (): Promise<{ success: boolean; message: string }> => {
  if (!navigator.onLine) {
    return { success: false, message: 'No internet connection' };
  }

  try {
    const unsyncedSurveys = await getUnsyncedSurveys();

    if (unsyncedSurveys.length === 0) {
      return { success: true, message: 'All surveys are synced' };
    }

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(unsyncedSurveys),
    });

    if (!response.ok) {
      throw new Error('Failed to sync surveys');
    }

    // Mark surveys as synced locally
    const syncedSurveys = unsyncedSurveys.map(survey => ({
      ...survey,
      synced: true,
    }));

    await Promise.all(syncedSurveys.map(saveSurveyLocally));

    return { success: true, message: 'Surveys synced successfully' };
  } catch (error) {
    console.error('Sync error:', error);
    return { success: false, message: 'Failed to sync surveys' };
  }
};

// Check internet connection
export const isOnline = (): boolean => {
  return navigator.onLine;
};
