# Offline-First Field Surveying App with Sync Capabilities

Below is a comprehensive implementation of an offline-first field surveying app that syncs data when reconnected to the internet. This example uses React Native for the mobile interface, but the core concepts can be adapted to other platforms.

## Core Architecture

```javascript
// App.js - Main application component
import React, { useEffect, useState } from 'react';
import { View, Text, Button, StyleSheet, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { openDatabase } from 'react-native-sqlite-storage';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';

// Initialize local database
const db = openDatabase({ name: 'SurveyApp.db' });

// Initialize tables if they don't exist
const initDatabase = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        surveyor_id TEXT,
        location TEXT,
        date TEXT,
        data TEXT,
        status TEXT DEFAULT 'pending',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      );`,
      [],
      () => console.log('Database initialized'),
      (tx, error) => console.error('Database initialization error:', error)
    );
  });
};

// Main App Component
const App = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [surveys, setSurveys] = useState([]);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    initDatabase();
    loadLocalSurveys();

    // Network state listener
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from local database
  const loadLocalSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY created_at DESC',
        [],
        (tx, results) => {
          const rows = results.rows;
          let surveys = [];
          for (let i = 0; i < rows.length; i++) {
            surveys.push(rows.item(i));
          }
          setSurveys(surveys);
        },
        (tx, error) => console.error('Error loading surveys:', error)
      );
    });
  };

  // Save survey to local database
  const saveSurvey = async (surveyData) => {
    try {
      await db.transaction(tx => {
        tx.executeSql(
          'INSERT INTO surveys (surveyor_id, location, date, data, status) VALUES (?,?,?,?,?)',
          [surveyData.surveyorId, surveyData.location, surveyData.date, JSON.stringify(surveyData.data), 'pending'],
          (tx, results) => {
            console.log('Survey saved locally');
            loadLocalSurveys();
          },
          (tx, error) => console.error('Error saving survey:', error)
        );
      });
    } catch (error) {
      console.error('Database error:', error);
    }
  };

  // Sync pending surveys to server
  const syncPendingSurveys = async () => {
    if (isSyncing) return;

    setIsSyncing(true);

    try {
      // Get all pending surveys
      const pendingSurveys = surveys.filter(survey => survey.status === 'pending');

      if (pendingSurveys.length === 0) {
        console.log('No pending surveys to sync');
        setIsSyncing(false);
        return;
      }

      // Sync each pending survey
      for (const survey of pendingSurveys) {
        try {
          // Simulate API call to your backend
          const response = await axios.post('https://your-api-endpoint.com/surveys', {
            surveyorId: survey.surveyor_id,
            location: survey.location,
            date: survey.date,
            data: JSON.parse(survey.data)
          });

          if (response.data.success) {
            // Update local database status
            await db.transaction(tx => {
              tx.executeSql(
                'UPDATE surveys SET status = ? WHERE id = ?',
                ['synced', survey.id],
                () => console.log(`Survey ${survey.id} marked as synced`),
                (tx, error) => console.error('Error updating survey status:', error)
              );
            });
          }
        } catch (error) {
          console.error('Error syncing survey:', error);
          // Continue with next survey even if one fails
          continue;
        }
      }

      // Refresh surveys after sync
      loadLocalSurveys();
    } catch (error) {
      console.error('Sync error:', error);
    } finally {
      setIsSyncing(false);
    }
  };

  // Example survey data
  const exampleSurvey = {
    surveyorId: 'surveyor123',
    location: '40.7128° N, 74.0060° W',
    date: new Date().toISOString(),
    data: {
      temperature: 22.5,
      humidity: 65,
      observations: 'Good weather conditions',
      photos: ['photo1.jpg', 'photo2.jpg']
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>

      <View style={styles.statusContainer}>
        <Text>Connection Status: {isConnected ? 'Online' : 'Offline'}</Text>
        <Text>Sync Status: {isSyncing ? 'Syncing...' : 'Idle'}</Text>
      </View>

      <Button
        title="Add Survey (Offline)"
        onPress={() => {
          saveSurvey(exampleSurvey);
          Alert.alert('Success', 'Survey saved locally. It will sync when online.');
        }}
      />

      <Button
        title="Force Sync Now"
        onPress={syncPendingSurveys}
        disabled={!isConnected || isSyncing}
      />

      <Text style={styles.sectionTitle}>Local Surveys ({surveys.length})</Text>
      {surveys.map(survey => (
        <View key={survey.id} style={styles.surveyItem}>
          <Text>ID: {survey.id}</Text>
          <Text>Location: {survey.location}</Text>
          <Text>Date: {new Date(survey.date).toLocaleString()}</Text>
          <Text>Status: {survey.status}</Text>
        </View>
      ))}
    </View>
  );
};

