## 3. Service Worker for Web Version (Optional)

If you want to support web browsers as well, here's a service worker implementation:

```javascript
// service-worker.js
const CACHE_NAME = 'survey-app-cache-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/styles.css',
  '/app.js',
  '/database.js',
  // Add other assets here
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('Opened cache');
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        // Clone the request
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDatabase();
  const unsyncedSurveys = await getUnsyncedSurveys(db);

  if (unsyncedSurveys.length > 0) {
    try {
      // Replace with your actual API endpoint
      const response = await fetch('https://your-api.com/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(unsyncedSurveys),
      });

      if (response.ok) {
        await markSurveysAsSynced(db, unsyncedSurveys);
      }
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }
}

// Helper functions for database operations
async function openDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('SurveyDB', 1);

    request.onerror = (event) => {
      reject('Error opening database');
    };

    request.onsuccess = (event) => {
      resolve(event.target.result);
    };

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('surveys')) {
        db.createObjectStore('surveys', { keyPath: 'id' });
      }
    };
  });
}

async function getUnsyncedSurveys(db) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(['surveys'], 'readonly');
    const store = transaction.objectStore('surveys');
    const request = store.getAll();

    request.onsuccess = () => {
      const unsynced = request.result.filter(survey => !survey.synced);
      resolve(unsynced);
    };

    request.onerror = (event) => {
      reject('Error fetching surveys');
    };
  });
}

async function markSurveysAsSynced(db, surveys) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(['surveys'], 'readwrite');
    const store = transaction.objectStore('surveys');

    surveys.forEach(survey => {
      const request = store.put({ ...survey, synced: true });

      request.onerror = (event) => {
        reject('Error updating survey');
      };
    });

    transaction.oncomplete = () => {
      resolve();
    };
  });
}
