## Core Architecture

```javascript
// App.js - Main Application Component
import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, Button, Alert } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { NavigationContainer } from '@react-navigation/native';
import NetInfo from '@react-native-community/netinfo';
import AsyncStorage from '@react-native-async-storage/async-storage';
import SurveyForm from './components/SurveyForm';
import SurveyList from './components/SurveyList';
import SyncManager from './services/SyncManager';

const Stack = createStackNavigator();

const App = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [syncStatus, setSyncStatus] = useState('idle');

  useEffect(() => {
    // Monitor network connectivity
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
    });

    // Check initial connection status
    NetInfo.fetch().then(state => {
      setIsConnected(state.isConnected);
    });

    // Set up periodic sync checks
    const syncInterval = setInterval(() => {
      if (isConnected) {
        handleSync();
      }
    }, 300000); // Check every 5 minutes

    return () => {
      unsubscribe();
      clearInterval(syncInterval);
    };
  }, [isConnected]);

  const handleSync = async () => {
    if (!isConnected) {
      Alert.alert('No Connection', 'Please connect to the internet to sync data');
      return;
    }

    setSyncStatus('syncing');
    try {
      const syncManager = new SyncManager();
      await syncManager.syncAllSurveys();
      setSyncStatus('synced');
      Alert.alert('Success', 'Data synced successfully!');
    } catch (error) {
      setSyncStatus('error');
      Alert.alert('Sync Error', 'Failed to sync data. Please try again later.');
      console.error('Sync error:', error);
    }
  };

  return (
    <NavigationContainer>
      <Stack.Navigator initialRouteName="SurveyList">
        <Stack.Screen
          name="SurveyList"
          component={SurveyList}
          options={{
            title: 'Field Surveys',
            headerRight: () => (
              <View style={styles.headerRight}>
                <Text style={styles.syncStatus}>
                  {isConnected ? 'Online' : 'Offline'}
                </Text>
                <Button
                  title="Sync"
                  onPress={handleSync}
                  disabled={!isConnected || syncStatus === 'syncing'}
                />
              </View>
            ),
          }}
        />
        <Stack.Screen
          name="SurveyForm"
          component={SurveyForm}
          options={{ title: 'New Survey' }}
        />
      </Stack.Navigator>
    </NavigationContainer>
  );
};

const styles = StyleSheet.create({
  headerRight: {
    flexDirection: 'row',
    alignItems: 'center',
    marginRight: 10,
  },
  syncStatus: {
    marginRight: 10,
    color: '#666',
  },
});

export default App;
