## Survey Service (Local Storage)

```javascript
// services/SurveyService.js
import AsyncStorage from '@react-native-async-storage/async-storage';

class SurveyService {
  async saveSurvey(surveyData) {
    try {
      // Generate a unique ID for the survey
      const id = Date.now().toString();
      const survey = {
        ...surveyData,
        id,
        createdAt: new Date().toISOString(),
        synced: false,
      };

      // Get existing surveys
      const existingSurveys = await this.getAllSurveys();

      // Add new survey
      const updatedSurveys = [...existingSurveys, survey];

      // Save to local storage
      await AsyncStorage.setItem('surveys', JSON.stringify(updatedSurveys));

      return survey;
    } catch (error) {
      console.error('Error saving survey:', error);
      throw error;
    }
  }

  async getAllSurveys() {
    try {
      const surveysJson = await AsyncStorage.getItem('surveys');
      return surveysJson ? JSON.parse(surveysJson) : [];
    } catch (error) {
      console.error('Error getting surveys:', error);
      return [];
    }
  }

  async getUnsyncedSurveys() {
    const allSurveys = await this.getAllSurveys();
    return allSurveys.filter(survey => !survey.synced);
  }

  async markAsSynced(surveyId) {
    const allSurveys = await this.getAllSurveys();
    const updatedSurveys = allSurveys.map(survey =>
      survey.id === surveyId ? { ...survey, synced: true } : survey
    );

    await AsyncStorage.setItem('surveys', JSON.stringify(updatedSurveys));
  }

  async clearAllSurveys() {
    await AsyncStorage.removeItem('surveys');
  }
}

export default SurveyService;
```

