// services/SyncManager.js
import SurveyService from './SurveyService';
import { API_BASE_URL } from '../config';

class SyncManager {
  constructor() {
    this.surveyService = new SurveyService();
  }

  async syncAllSurveys() {
    try {
      const unsyncedSurveys = await this.surveyService.getUnsyncedSurveys();

      if (unsyncedSurveys.length === 0) {
        console.log('No surveys to sync');
        return;
      }

      // Sync each survey one by one
      for (const survey of unsyncedSurveys) {
        await this.syncSingleSurvey(survey);
      }

      console.log(`Successfully synced ${unsyncedSurveys.length} surveys`);
    } catch (error) {
      console.error('Sync error:', error);
      throw error;
    }
  }

  async syncSingleSurvey(survey) {
    try {
      // Prepare the survey data for API
      const surveyData = {
        ...survey,
        // Add any transformations needed for the API
      };

      // Send to API
      const response = await fetch(`${API_BASE_URL}/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          // Add any authentication headers if needed
        },
        body: JSON.stringify(surveyData),
