// Survey Form Component
const SurveyForm = ({ navigation }) => {
  const [surveyData, setSurveyData] = useState({
    location: '',
    observations: '',
    timestamp: new Date().toISOString(),
    status: 'pending'
  });

  const saveSurvey = async () => {
    try {
      // Get existing surveys or initialize empty array
      const existingSurveys = await AsyncStorage.getItem('offlineSurveys');
      const surveys = existingSurveys ? JSON.parse(existingSurveys) : [];

      // Add new survey with unique ID
      const newSurvey = {
        ...surveyData,
        id: Date.now().toString()
      };

      surveys.push(newSurvey);
      await AsyncStorage.setItem('offlineSurveys', JSON.stringify(surveys));

      // Check network status and sync if online
      const netInfo = await NetInfo.fetch();
      if (netInfo.isConnected) {
        await syncSurveys();
      }

      navigation.goBack();
    } catch (error) {
      console.error('Error saving survey:', error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey</Text>
      {/* Form fields would go here */}
      <Button title="Save Survey" onPress={saveSurvey} />
    </View>
  );
};

// Survey List Component
const SurveyList = ({ navigation }) => {
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);

  useEffect(() => {
    loadSurveys();

    // Subscribe to network state updates
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) {
        syncSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const loadSurveys = async () => {
    try {
      const storedSurveys = await AsyncStorage.getItem('offlineSurveys');
      if (storedSurveys) {
        setSurveys(JSON.parse(storedSurveys));
      }
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  };

  const syncSurveys = async () => {
    try {
      const storedSurveys = await AsyncStorage.getItem('offlineSurveys');
      if (!storedSurveys) return;

      const pendingSurveys = JSON.parse(storedSurveys).filter(
        survey => survey.status === 'pending'
      );

      if (pendingSurveys.length === 0) return;

      // Simulate API call to sync with server
      console.log('Syncing surveys:', pendingSurveys);

      // Update local storage with synced status
      const updatedSurveys = JSON.parse(storedSurveys).map(survey => {
        if (survey.status === 'pending') {
          return { ...survey, status: 'synced' };
        }
        return survey;
      });

      await AsyncStorage.setItem('offlineSurveys', JSON.stringify(updatedSurveys));
      setSurveys(updatedSurveys);
    } catch (error) {
      console.error('Error syncing surveys:', error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Survey History</Text>
      <Text style={styles.status}>
        Status: {isOnline ? 'Online' : 'Offline'}
      </Text>
      <FlatList
