## 2. Database Setup (using Dexie)

Create a file `src/db.ts`:

```typescript
import Dexie, { Table } from 'dexie';

export interface Survey {
  id?: number;
  title: string;
  location: string;
  date: string;
  notes: string;
  photos: string[];
  status: 'pending' | 'synced';
  createdAt: Date;
}

export class SurveyDB extends Dexie {
  surveys!: Table<Survey>;

  constructor() {
    super('SurveyDatabase');
    this.version(1).stores({
      surveys: '++id, title, location, date, status, createdAt'
    });
  }

  async addSurvey(survey: Omit<Survey, 'id' | 'status' | 'createdAt'>) {
    return this.surveys.add({
      ...survey,
      status: 'pending',
      createdAt: new Date()
    });
  }

  async getPendingSurveys() {
    return this.surveys.where('status').equals('pending').toArray();
  }

  async markAsSynced(id: number) {
    return this.surveys.update(id, { status: 'synced' });
  }
}

export const db = new SurveyDB();
```

