import './App.css';

const App: React.FC = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [newSurvey, setNewSurvey] = useState({
    title: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    notes: '',
    photos: [] as string[]
  });
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    // Load surveys from IndexedDB
    const loadSurveys = async () => {
      const allSurveys = await db.surveys.toArray();
      setSurveys(allSurveys);
    };

    loadSurveys();

    // Set up online/offline listeners
    const handleOnline = () => {
      setIsOnline(true);
      syncPendingSurveys();
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const syncPendingSurveys = async () => {
    const pendingSurveys = await db.getPendingSurveys();

    for (const survey of pendingSurveys) {
      try {
        // Simulate API call (replace with your actual API endpoint)
        const response = await fetch('/api/surveys', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(survey),
        });

        if (response.ok) {
          await db.markAsSynced(survey.id!);
        }
      } catch (error) {
        console.error('Failed to sync survey:', error);
        // The background sync will handle retries
      }
    }

    // Refresh the list
    const allSurveys = await db.surveys.toArray();
    setSurveys(allSurveys);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewSurvey(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Add to IndexedDB
    await db.addSurvey(newSurvey);

    // Reset form
    setNewSurvey({
      title: '',
      location: '',
      date: new Date().toISOString().split('T')[0],
      notes: '',
      photos: []
    });

    // Refresh the list
    const allSurveys = await db.surveys.toArray();
    setSurveys(allSurveys);

    // If online, try to sync immediately
    if (isOnline) {
      await syncPendingSurveys();
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const photoUrls = files.map(file => URL.createObjectURL(file));
      setNewSurvey(prev => ({
        ...prev,
        photos: [...prev.photos, ...photoUrls]
      }));
    }
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
        </div>
      </header>

      <div className="survey-form">
        <h2>New Survey</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Title:</label>
            <input
              type="text"
              name="title"
              value={newSurvey.title}
              onChange={handleInputChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Location:</label>
            <input
              type="text"
              name="location"
              value={newSurvey.location}
              onChange={handleInputChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Date:</label>
            <input
              type="date"
              name="date"
              value={newSurvey.date}
              onChange={handleInputChange}
              required
            />
          </div>

          <div className="form-group">
            <label>Notes:</label>
            <textarea
              name="notes"
              value={newSurvey.notes}
              onChange={handleInputChange}
            />
          </div>

          <div className="form-group">
            <label>Photos:</label>
            <input
              type="file"
              accept="image/*"
              multiple
              onChange={handlePhotoUpload}
            />
            <div className="photo-preview">
              {newSurvey.photos.map((photo, index) => (
                <img key={index} src={photo} alt={`Preview ${index}`} />
              ))}
            </div>
          </div>

          <button type="submit">Save Survey</button>
        </form>
      </div>

      <div className="survey-list">
        <h2>Saved Surveys</h2>
        {surveys.length === 0 ? (
          <p>No surveys saved yet.</p>
        ) : (
          <ul>
            {surveys.map(survey => (
