## Data Storage Layer

```typescript
// storage.ts
import { Survey } from './types';

const DB_NAME = 'SurveyAppDB';
const STORE_NAME = 'surveys';

class SurveyStorage {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, 1);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  async getAllSurveys(): Promise<Survey[]> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async saveSurvey(survey: Survey): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(survey);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async deleteSurvey(id: string): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async markAsSynced(id: string): Promise<void> {
    const surveys = await this.getAllSurveys();
    const survey = surveys.find(s => s.id === id);
    if (survey) {
      survey.isSynced = true;
      await this.saveSurvey(survey);
    }
  }
}

export const storage = new SurveyStorage();
```

## Sync Manager

```typescript
// syncManager.ts
import { Survey, SyncStatus } from './types';
import { storage } from './storage';

class SyncManager {
  private syncInterval: number | null = null;
  private syncStatus: SyncStatus = {
    lastSync: null,
    pendingCount: 0,
    isSyncing: false,
  };

  constructor() {
    this.initSyncListener();
  }

  private initSyncListener() {
    window.addEventListener('online', () => {
      this.checkAndSync();
    });
  }

  async checkAndSync(): Promise<void> {
    if (!navigator.onLine) return;

    const surveys = await storage.getAllSurveys();
    const unsyncedSurveys = surveys.filter(s => !s.isSynced);

    if (unsyncedSurveys.length > 0) {
      this.syncStatus.isSyncing = true;
      this.syncStatus.pendingCount = unsyncedSurveys.length;

      try {
        // Simulate API call to sync data
        await this.syncWithServer(unsyncedSurveys);

        // Mark as synced in local storage
        for (const survey of unsyncedSurveys) {
          await storage.markAsSynced(survey.id);
        }

        this.syncStatus.lastSync = new Date();
        this.syncStatus.pendingCount = 0;
      } catch (error) {
        console.error('Sync failed:', error);
      } finally {
        this.syncStatus.isSyncing = false;
      }
    }
  }

  private async syncWithServer(surveys: Survey[]): Promise<void> {
    // In a real app, this would be an actual API call
    // For demo purposes, we'll simulate a network request
    return new Promise((resolve) => {
      setTimeout(() => {
        console.log('Synced surveys:', surveys);
        resolve();
      }, 1000);
    });
  }

  startPeriodicSync(intervalMinutes: number = 5): void {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }

    this.syncInterval = window.setInterval(() => {
      this.checkAndSync();
    }, intervalMinutes * 60 * 1000);
  }

  stopPeriodicSync(): void {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
      this.syncInterval = null;
    }
  }

  getSyncStatus(): SyncStatus {
    return { ...this.syncStatus };
  }
}

export const syncManager = new SyncManager();
```

