## 1. Core Architecture

```javascript
// App.js - Main App Component
import React, { useEffect, useState } from 'react';
import { View, Text, Button, StyleSheet, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { openDatabase } from 'react-native-sqlite-storage';
import axios from 'axios';

// Initialize SQLite database
const db = openDatabase({ name: 'SurveyApp.db', location: 'default' });

const App = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [surveys, setSurveys] = useState([]);
  const [pendingSyncCount, setPendingSyncCount] = useState(0);

  // Initialize database tables
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, location TEXT, date TEXT, data TEXT, synced INTEGER DEFAULT 0);',
        [],
        () => console.log('Database initialized'),
        (error) => console.error('Database initialization error:', error)
      );
    });

    // Check network status
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncPendingSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from local database
  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY date DESC',
        [],
        (tx, results) => {
          const rows = results.rows.raw();
          setSurveys(rows);
          const pending = rows.filter(survey => survey.synced === 0).length;
          setPendingSyncCount(pending);
        },
        (error) => console.error('Error loading surveys:', error)
      );
    });
  };

  // Save survey to local database
  const saveSurvey = (surveyData) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (title, location, date, data) VALUES (?, ?, ?, ?)',
        [surveyData.title, surveyData.location, new Date().toISOString(), JSON.stringify(surveyData)],
        () => {
          console.log('Survey saved locally');
          loadSurveys();
          if (isConnected) {
            syncSurvey(surveyData);
          }
        },
        (error) => console.error('Error saving survey:', error)
      );
    });
  };

  // Sync a single survey to server
  const syncSurvey = async (surveyData) => {
    try {
      // Replace with your actual API endpoint
      const response = await axios.post('https://your-api-endpoint.com/surveys', surveyData);

      if (response.status === 200 || response.status === 201) {
        // Mark as synced in local database
        db.transaction(tx => {
          tx.executeSql(
            'UPDATE surveys SET synced = 1 WHERE id = ?',
            [surveyData.id],
            () => {
              console.log('Survey synced successfully');
              loadSurveys();
            },
            (error) => console.error('Error updating sync status:', error)
          );
        });
      }
    } catch (error) {
      console.error('Sync error:', error);
    }
  };

  // Sync all pending surveys
  const syncPendingSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE synced = 0',
        [],
        async (tx, results) => {
          const pendingSurveys = results.rows.raw();
          for (const survey of pendingSurveys) {
            await syncSurvey(JSON.parse(survey.data));
          }
        },
        (error) => console.error('Error fetching pending surveys:', error)
      );
    });
  };

  // Example survey data
  const exampleSurvey = {
    title: 'Field Survey ' + new Date().toLocaleDateString(),
    location: '40.7128° N, 74.0060° W',
    data: {
      temperature: 22.5,
      humidity: 45,
      observations: 'Good weather conditions',
      photos: ['photo1.jpg', 'photo2.jpg']
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>

      <View style={styles.statusContainer}>
        <Text style={styles.statusText}>
          {isConnected ? 'Online' : 'Offline'} | {pendingSyncCount} pending syncs
        </Text>
      </View>

      <Button
        title="Start New Survey"
        onPress={() => saveSurvey(exampleSurvey)}
      />

      <View style={styles.surveyList}>
        <Text style={styles.sectionTitle}>Recent Surveys</Text>
        {surveys.map(survey => (
          <View key={survey.id} style={styles.surveyItem}>
            <Text>{survey.title}</Text>
            <Text>{new Date(survey.date).toLocaleString()}</Text>
            <Text style={{ color: survey.synced ? 'green' : 'red' }}>
              {survey.synced ? 'Synced' : 'Pending'}
            </Text>
          </View>
        ))}
      </View>

      {!isConnected && (
        <View style={styles.offlineNotice}>
          <Text style={styles.offlineText}>Working offline. Surveys will sync when you reconnect.</Text>
        </View>
      )}
    </View>
  );
};

