### 1. Local Storage Service (`localStorage.js`)

```javascript
import AsyncStorage from '@react-native-async-storage/async-storage';

const SURVEY_KEY = 'field_surveys';
const PENDING_SYNC_KEY = 'pending_surveys';

export const saveSurveyLocally = async (surveyData) => {
  try {
    // Get existing surveys
    const existingSurveys = await getLocalSurveys();

    // Add new survey with timestamp
    const newSurvey = {
      ...surveyData,
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      isSynced: false
    };

    const updatedSurveys = [...existingSurveys, newSurvey];

    // Save to AsyncStorage
    await AsyncStorage.setItem(SURVEY_KEY, JSON.stringify(updatedSurveys));

    // Add to pending sync queue
    await addToPendingSync(newSurvey);

    return newSurvey;
  } catch (error) {
    console.error('Error saving survey locally:', error);
    throw error;
  }
};

export const getLocalSurveys = async () => {
  try {
    const surveys = await AsyncStorage.getItem(SURVEY_KEY);
    return surveys ? JSON.parse(surveys) : [];
  } catch (error) {
    console.error('Error getting local surveys:', error);
    return [];
  }
};

export const addToPendingSync = async (survey) => {
  try {
    const pendingSurveys = await getPendingSurveys();
    const updatedPending = [...pendingSurveys, survey];
    await AsyncStorage.setItem(PENDING_SYNC_KEY, JSON.stringify(updatedPending));
  } catch (error) {
    console.error('Error adding to pending sync:', error);
    throw error;
  }
};

export const getPendingSurveys = async () => {
  try {
    const pendingSurveys = await AsyncStorage.getItem(PENDING_SYNC_KEY);
    return pendingSurveys ? JSON.parse(pendingSurveys) : [];
  } catch (error) {
    console.error('Error getting pending surveys:', error);
    return [];
  }
};

export const clearPendingSurveys = async () => {
  try {
    await AsyncStorage.removeItem(PENDING_SYNC_KEY);
  } catch (error) {
    console.error('Error clearing pending surveys:', error);
    throw error;
  }
};

export const markAsSynced = async (surveyId) => {
  try {
    const surveys = await getLocalSurveys();
    const updatedSurveys = surveys.map(survey =>
      survey.id === surveyId ? { ...survey, isSynced: true } : survey
    );
    await AsyncStorage.setItem(SURVEY_KEY, JSON.stringify(updatedSurveys));

    // Remove from pending sync queue
    const pendingSurveys = await getPendingSurveys();
    const updatedPending = pendingSurveys.filter(survey => survey.id !== surveyId);
    await AsyncStorage.setItem(PENDING_SYNC_KEY, JSON.stringify(updatedPending));
  } catch (error) {
    console.error('Error marking survey as synced:', error);
    throw error;
  }
};
