### 3. Sync Service (`syncService.js`)

```javascript
import { getPendingSurveys, markAsSynced, clearPendingSurveys } from './localStorage';
import { syncSurveyToServer, checkConnection } from './apiService';

export const syncPendingSurveys = async () => {
  try {
    const isConnected = await checkConnection();
    if (!isConnected) {
      console.log('No internet connection, skipping sync');
      return false;
    }

    const pendingSurveys = await getPendingSurveys();
    if (pendingSurveys.length === 0) {
      console.log('No pending surveys to sync');
      return true;
    }

    console.log(`Found ${pendingSurveys.length} surveys to sync`);

    for (const survey of pendingSurveys) {
      try {
        await syncSurveyToServer(survey);
        await markAsSynced(survey.id);
        console.log(`Successfully synced survey ${survey.id}`);
      } catch (error) {
        console.error(`Failed to sync survey ${survey.id}:`, error);
        // Continue with next survey even if one fails
      }
    }

    // Clear pending queue if all synced successfully
    const remainingPending = await getPendingSurveys();
    if (remainingPending.length === 0) {
      await clearPendingSurveys();
    }

    return true;
  } catch (error) {
    console.error('Error during sync process:', error);
    return false;
  }
};

// Set up periodic sync checks
export const setupSyncListener = (callback) => {
  let isSyncing = false;

  const checkAndSync = async () => {
    if (isSyncing) return;

    isSyncing = true;
    try {
      const success = await syncPendingSurveys();
      if (callback) callback(success);
    } finally {
      isSyncing = false;
    }
  };

  // Check every 5 minutes
  const intervalId = setInterval(checkAndSync, 5 * 60 * 1000);

  // Also check when app comes back online
  const connectionHandler = () => {
    if (navigator.onLine) {
      checkAndSync();
    }
  };

  window.addEventListener('online', connectionHandler);

  return () => {
    clearInterval(intervalId);
    window.removeEventListener('online', connectionHandler);
  };
};
