### 4. App Context (`AppContext.js`)

```javascript
import React, { createContext, useState, useEffect, useContext } from 'react';
import { getLocalSurveys } from '../services/localStorage';
import { setupSyncListener } from '../services/syncService';

const AppContext = createContext();

export const AppProvider = ({ children }) => {
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState(null);

  useEffect(() => {
    const loadSurveys = async () => {
      const localSurveys = await getLocalSurveys();
      setSurveys(localSurveys);
    };

    loadSurveys();

    // Set up network status listener
    const updateOnlineStatus = () => {
      setIsOnline(navigator.onLine);
    };

    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);

    // Set up sync listener
    const cleanupSyncListener = setupSyncListener((success) => {
      if (success) {
        setLastSyncTime(new Date());
        loadSurveys(); // Refresh surveys after sync
      }
    });

    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
      cleanupSyncListener();
    };
  }, []);

  const refreshSurveys = async () => {
    const localSurveys = await getLocalSurveys();
    setSurveys(localSurveys);
  };

  const value = {
    surveys,
    isOnline,
    isSyncing,
    lastSyncTime,
    refreshSurveys,
    setIsSyncing
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useAppContext = () => useContext(AppContext);
