```tsx
import React, { useState, useEffect } from 'react';
import { SurveyForm } from './SurveyForm';
import { SyncStatus } from './SyncStatus';
import { SurveyList } from './SurveyList';
import { initDB, getAllSurveys, syncSurveys } from './db';

interface Survey {
  id: string;
  title: string;
  location: string;
  data: Record<string, any>;
  status: 'pending' | 'synced' | 'error';
  timestamp: number;
}

export const App: React.FC = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [syncing, setSyncing] = useState(false);

  // Initialize database and load surveys
  useEffect(() => {
    const initialize = async () => {
      await initDB();
      const loadedSurveys = await getAllSurveys();
      setSurveys(loadedSurveys);
    };
    initialize();
  }, []);

  // Handle network status changes
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Sync when coming online
  useEffect(() => {
    if (isOnline) {
      const syncData = async () => {
        setSyncing(true);
        try {
          await syncSurveys();
          const updatedSurveys = await getAllSurveys();
          setSurveys(updatedSurveys);
        } catch (error) {
          console.error('Sync failed:', error);
        } finally {
          setSyncing(false);
        }
      };
      syncData();
    }
  }, [isOnline]);

  const handleSurveySubmit = async (survey: Omit<Survey, 'id' | 'status' | 'timestamp'>) => {
    const newSurvey: Survey = {
      ...survey,
      id: Date.now().toString(),
      status: 'pending',
      timestamp: Date.now(),
    };

    // Save to IndexedDB
    await saveSurvey(newSurvey);
    setSurveys([...surveys, newSurvey]);

    // Attempt sync if online
    if (isOnline) {
      try {
        await syncSurveys();
        const updatedSurveys = await getAllSurveys();
        setSurveys(updatedSurveys);
      } catch (error) {
        console.error('Sync failed:', error);
      }
    }
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <SyncStatus isOnline={isOnline} syncing={syncing} />
      </header>

      <main>
        <SurveyForm onSubmit={handleSurveySubmit} />
        <SurveyList surveys={surveys} />
      </main>
    </div>
  );
};
```

### 2. Database Service (`db.ts`)

```typescript
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-status': string; 'by-timestamp': number };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export async function initDB() {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('by-status', 'status');
        store.createIndex('by-timestamp', 'timestamp');
      }
    },
  });
}

export async function saveSurvey(survey: Survey) {
  const db = await initDB();
  await db.put('surveys', survey);
}

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await initDB();
  return db.getAll('surveys');
}

export async function getPendingSurveys(): Promise<Survey[]> {
  const db = await initDB();
  return db.getAllFromIndex('surveys', 'by-status', 'pending');
}

export async function updateSurveyStatus(id: string, status: Survey['status']) {
  const db = await initDB();
  const tx = db.transaction('surveys', 'readwrite');
  const store = tx.objectStore('surveys');
  const survey = await store.get(id);

  if (survey) {
    survey.status = status;
    await store.put(survey);
  }

  await tx.done;
}

export async function syncSurveys() {
  const pendingSurveys = await getPendingSurveys();

  if (pendingSurveys.length === 0) return;

  try {
    // Simulate API call to sync data
    const response = await fetch('https://api.example.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (!response.ok) throw new Error('Sync failed');

    // Update local status if sync was successful
    for (const survey of pendingSurveys) {
      await updateSurveyStatus(survey.id, 'synced');
    }
  } catch (error) {
    console.error('Sync error:', error);
    // Mark as error for retry
    for (const survey of pendingSurveys) {
      await updateSurveyStatus(survey.id, 'error');
    }
    throw error;
  }
}

// Background sync registration (for Service Worker)
export function registerBackgroundSync() {
  if ('serviceWorker' in navigator && 'SyncManager' in window) {
    navigator.serviceWorker.ready.then((registration) => {
      registration.sync.register('sync-surveys').catch((err) => {
        console.error('Background sync registration failed:', err);
      });
    });
  }
}
