### 6. Service Worker (`service-worker.js`)

```javascript
const CACHE_NAME = 'field-survey-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
];

// Install event - cache assets
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS_TO_CACHE))
  );
});

// Activate event - clean up old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

// Fetch event - serve cached assets when offline
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => response || fetch(event.request))
  );
});

// Background sync event
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('FieldSurveyDB', 1);
  const tx = db.transaction('surveys', 'readwrite');
  const store = tx.objectStore('surveys');

  // Get all pending surveys
  const pendingSurveys = await store.index('by-status').getAll('pending');

  if (pendingSurveys.length === 0) return;

  try {
    const response = await fetch('https://api.example.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (!response.ok) throw new Error('Sync failed');

    // Update local status if sync was successful
    for (const survey of pendingSurveys) {
      survey.status = 'synced';
      await store.put(survey);
    }
  } catch (error) {
    console.error('Background sync error:', error);
    // Mark as error for retry
    for (const survey of pendingSurveys) {
      survey.status = 'error';
      await store.put(survey);
    }
  }
}
