### 2. Local Storage Service

```typescript
// services/LocalStorageService.ts
export class LocalStorageService {
  private static readonly STORAGE_KEY = 'field_surveys';

  static async getAllSurveys(): Promise<Survey[]> {
    const data = localStorage.getItem(this.STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  }

  static async saveSurvey(survey: Survey): Promise<void> {
    const surveys = await this.getAllSurveys();
    const existingIndex = surveys.findIndex(s => s.id === survey.id);

    if (existingIndex >= 0) {
      surveys[existingIndex] = survey;
    } else {
      surveys.push(survey);
    }

    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(surveys));
  }

  static async deleteSurvey(id: string): Promise<void> {
    const surveys = await this.getAllSurveys();
    const updatedSurveys = surveys.filter(s => s.id !== id);
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(updatedSurveys));
  }

  static async getUnsyncedSurveys(): Promise<Survey[]> {
    const surveys = await this.getAllSurveys();
    return surveys.filter(s => !s.isSynced);
  }
}
```

### 3. Sync Service

```typescript
// services/SyncService.ts
export class SyncService {
  private static readonly API_URL = 'https://your-api-endpoint.com/surveys';

  static async syncData(): Promise<void> {
    if (!navigator.onLine) {
      console.log('Offline - sync deferred');
      return;
    }

    try {
      const unsyncedSurveys = await LocalStorageService.getUnsyncedSurveys();

      for (const survey of unsyncedSurveys) {
        const response = await fetch(this.API_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(survey),
        });

        if (response.ok) {
          const updatedSurvey = { ...survey, isSynced: true };
          await LocalStorageService.saveSurvey(updatedSurvey);
        }
      }

      console.log(`Synced ${unsyncedSurveys.length} surveys`);
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }

  static setupPeriodicSync(intervalMinutes: number = 5): void {
    setInterval(() => {
      if (navigator.onLine) {
        this.syncData();
      }
    }, intervalMinutes * 60 * 1000);

    // Also sync when coming back online
    window.addEventListener('online', () => {
      this.syncData();
    });
  }
}
```

