// App.tsx
import React, { useState, useEffect } from 'react';
import { Survey } from './models/Survey';
import { LocalStorageService } from './services/LocalStorageService';
import { SyncService } from './services/SyncService';
import SurveyForm from './components/SurveyForm';
import SurveyList from './components/SurveyList';

const App: React.FC = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    // Initialize periodic sync
    SyncService.setupPeriodicSync();

    // Load surveys from local storage
    const loadSurveys = async () => {
      const savedSurveys = await LocalStorageService.getAllSurveys();
      setSurveys(savedSurveys);
    };

    loadSurveys();

    // Set up online/offline listeners
    const handleOnlineStatus = () => {
      setIsOnline(navigator.onLine);
      if (navigator.onLine) {
        SyncService.syncData();
      }
    };

    window.addEventListener('online', handleOnlineStatus);
    window.addEventListener('offline', handleOnlineStatus);

    return () => {
      window.removeEventListener('online', handleOnlineStatus);
      window.removeEventListener('offline', handleOnlineStatus);
    };
  }, []);

  const handleSaveSurvey = async (survey: Survey) => {
    await LocalStorageService.saveSurvey(survey);
    const updatedSurveys = await LocalStorageService.getAllSurveys();
    setSurveys(updatedSurveys);
  };

  const handleDeleteSurvey = async (id: string) => {
    await LocalStorageService.deleteSurvey(id);
    const updatedSurveys = await LocalStorageService.getAllSurveys();
    setSurveys(updatedSurveys);
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
        </div>
      </header>

      <main>
        <SurveyForm onSave={handleSaveSurvey} />
        <SurveyList
          surveys={surveys}
          onDelete={handleDeleteSurvey}
        />
      </main>
    </div>
  );
};

export default App;
