// App.js - Main entry point
import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, Button, Alert } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';
import { createStackNavigator } from '@react-navigation/stack';
import { NavigationContainer } from '@react-navigation/native';

// Survey Form Component
const SurveyForm = ({ navigation }) => {
  const [surveyData, setSurveyData] = useState({
    location: '',
    observations: '',
    timestamp: new Date().toISOString(),
    status: 'pending'
  });

  const saveSurvey = async () => {
    try {
      // Generate a unique ID for the survey
      const surveyId = Date.now().toString();

      // Get existing surveys or initialize empty array
      const existingSurveys = await AsyncStorage.getItem('offlineSurveys');
      const surveys = existingSurveys ? JSON.parse(existingSurveys) : [];

      // Add new survey
      surveys.push({ id: surveyId, ...surveyData });

      // Save back to AsyncStorage
      await AsyncStorage.setItem('offlineSurveys', JSON.stringify(surveys));

      Alert.alert('Success', 'Survey saved offline. Will sync when connected.');
      navigation.goBack();
    } catch (error) {
      console.error('Error saving survey:', error);
      Alert.alert('Error', 'Failed to save survey');
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey</Text>
      {/* Form fields would go here */}
      <Button title="Save Survey" onPress={saveSurvey} />
    </View>
  );
};

// Sync Component
const SyncScreen = () => {
  const [syncStatus, setSyncStatus] = useState('Checking connection...');
  const [pendingSurveys, setPendingSurveys] = useState(0);

  useEffect(() => {
    const checkPendingSurveys = async () => {
      try {
        const surveys = await AsyncStorage.getItem('offlineSurveys');
        const parsedSurveys = surveys ? JSON.parse(surveys) : [];
        setPendingSurveys(parsedSurveys.length);
      } catch (error) {
        console.error('Error checking pending surveys:', error);
      }
    };

    checkPendingSurveys();

    // Set up network listener
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        setSyncStatus('Connected - Syncing...');
        syncData();
      } else {
        setSyncStatus('Offline - Data will sync when connected');
      }
    });

    return () => unsubscribe();
  }, []);

  const syncData = async () => {
    try {
      const surveys = await AsyncStorage.getItem('offlineSurveys');
      const parsedSurveys = surveys ? JSON.parse(surveys) : [];

      if (parsedSurveys.length === 0) {
        setSyncStatus('No pending surveys to sync');
        return;
      }

      // Filter only pending surveys
      const pendingSurveys = parsedSurveys.filter(s => s.status === 'pending');

      if (pendingSurveys.length === 0) {
        setSyncStatus('All surveys already synced');
        return;
      }

      // Simulate API call to sync data
      // In a real app, replace with your actual API endpoint
      const response = await fetch('https://your-api-endpoint.com/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pendingSurveys),
      });

      if (response.ok) {
        // Update status of synced surveys
        const updatedSurveys = parsedSurveys.map(survey => {
          if (pendingSurveys.some(ps => ps.id === survey.id)) {
            return { ...survey, status: 'synced' };
          }
          return survey;
        });

        await AsyncStorage.setItem('offlineSurveys', JSON.stringify(updatedSurveys));
        setSyncStatus(`Successfully synced ${pendingSurveys.length} surveys`);
      } else {
        setSyncStatus('Failed to sync surveys');
      }
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('Error during sync');
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Sync Status</Text>
      <Text>{syncStatus}</Text>
      <Text>Pending surveys: {pendingSurveys}</Text>
      <Button title="Force Sync" onPress={syncData} />
    </View>
  );
};

// Main App Component
