## Backend Implementation (Node.js + Express)

```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const { Pool } = require('pg');

const app = express();
const port = 3001;

// Database configuration
const pool = new Pool({
  user: 'your_db_user',
  host: 'localhost',
  database: 'survey_db',
  password: 'your_db_password',
  port: 5432,
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// API endpoints
app.post('/api/surveys', async (req, res) => {
  const surveys = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: 'Expected an array of surveys' });
  }

  try {
    // Insert surveys into database
    const client = await pool.connect();

    for (const survey of surveys) {
      await client.query(
        `INSERT INTO surveys (id, title, location, notes, timestamp)
         VALUES ($1, $2, $3, $4, $5)
         ON CONFLICT (id) DO UPDATE
         SET title = EXCLUDED.title,
             location = EXCLUDED.location,
             notes = EXCLUDED.notes,
             timestamp = EXCLUDED.timestamp`,
        [survey.id, survey.title, survey.location, survey.notes, new Date(survey.timestamp)]
      );
    }

    client.release();
    res.status(200).json({ message: 'Surveys synced successfully' });
  } catch (error) {
    console.error('Database error:', error);
    res.status(500).json({ error: 'Failed to sync surveys' });
  }
});

app.get('/api/surveys', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM surveys ORDER BY timestamp DESC');
    res.json(result.rows);
  } catch (error) {
    console.error('Database error:', error);
    res.status(500).json({ error: 'Failed to fetch surveys' });
  }
});

// Start server
app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
