      <span>{getStatusMessage()}</span>
      {isOnline && status !== 'syncing' && (
        <button onClick={onSync} disabled={status === 'syncing'}>
          {status === 'error' ? 'Retry Sync' : 'Force Sync'}
        </button>
      )}
    </div>
  );
};
