Below is a comprehensive implementation of an offline-first field surveying app that syncs data when reconnected to the network. This example uses React with TypeScript, but the concepts can be adapted to other frameworks.

## Core Components

### 1. Data Model and Local Storage

```typescript
// models/Survey.ts
export interface Survey {
  id: string;
  title: string;
  location: {
    latitude: number;
    longitude: number;
  };
  notes: string;
  photos: string[]; // Base64 encoded images
  createdAt: Date;
  updatedAt: Date;
  isSynced: boolean;
}

// services/localStorageService.ts
export const localStorageService = {
  getSurveys: (): Survey[] => {
    const surveys = localStorage.getItem('surveys');
    return surveys ? JSON.parse(surveys) : [];
  },

  saveSurvey: (survey: Survey): void => {
    const surveys = localStorageService.getSurveys();
    const existingIndex = surveys.findIndex(s => s.id === survey.id);

    if (existingIndex >= 0) {
      surveys[existingIndex] = survey;
    } else {
      surveys.push(survey);
    }

    localStorage.setItem('surveys', JSON.stringify(surveys));
  },

  getUnsyncedSurveys: (): Survey[] => {
    return localStorageService.getSurveys().filter(s => !s.isSynced);
  },

  markAsSynced: (surveyId: string): void => {
    const surveys = localStorageService.getSurveys();
    const survey = surveys.find(s => s.id === surveyId);
    if (survey) {
      survey.isSynced = true;
      survey.updatedAt = new Date();
      localStorage.setItem('surveys', JSON.stringify(surveys));
    }
  }
};
```

### 2. Network Service with Offline Detection

```typescript
// services/networkService.ts
export const networkService = {
  isOnline: (): boolean => {
    return navigator.onLine;
  },

  syncSurveys: async (): Promise<void> => {
    if (!networkService.isOnline()) {
      throw new Error('No internet connection');
    }

    const unsyncedSurveys = localStorageService.getUnsyncedSurveys();

    for (const survey of unsyncedSurveys) {
      try {
        // In a real app, this would be an API call to your backend
        // For demo purposes, we'll simulate the API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mark as synced in local storage
        localStorageService.markAsSynced(survey.id);

        console.log(`Survey ${survey.id} synced successfully`);
      } catch (error) {
        console.error(`Failed to sync survey ${survey.id}:`, error);
        // Could implement retry logic here
      }
    }
  }
};
