### 4. Main App Component with Sync Logic

```typescript
// App.tsx
import React, { useState, useEffect } from 'react';
import { SurveyForm } from './components/SurveyForm';
import { SurveyList } from './components/SurveyList';
import { networkService } from './services/networkService';
import { localStorageService } from './services/localStorageService';

export const App: React.FC = () => {
  const [isOnline, setIsOnline] = useState(networkService.isOnline());
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');

  useEffect(() => {
    // Set up online/offline event listeners
    const handleOnline = () => {
      setIsOnline(true);
      attemptSync();
    };

    const handleOffline = () => {
      setIsOnline(false);
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Initial sync attempt if online
    if (isOnline) {
      attemptSync();
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const attemptSync = async () => {
    if (!isOnline) return;

    setSyncStatus('syncing');

    try {
      await networkService.syncSurveys();
      setSyncStatus('synced');
    } catch (error) {
      console.error('Sync failed:', error);
      setSyncStatus('error');
    }
  };

  const handleSurveySaved = () => {
    // Refresh the list
    // The SurveyList component already listens for storage changes
    if (isOnline) {
      attemptSync();
    }
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`connection-status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
        </div>
        {syncStatus === 'syncing' && <div>Syncing data...</div>}
        {syncStatus === 'synced' && <div>Data synced successfully!</div>}
        {syncStatus === 'error' && <div>Sync failed. Will retry when online.</div>}
      </header>

      <main>
        <SurveyForm onSurveySaved={handleSurveySaved} />
        <SurveyList />
      </main>
    </div>
  );
};
