### 1. Local Storage Service (`localStorage.js`)

```javascript
import AsyncStorage from '@react-native-async-storage/async-storage';

const STORAGE_KEYS = {
  SURVEYS: 'surveys',
  PENDING_SYNC: 'pending_sync'
};

export const saveSurveyLocally = async (surveyData) => {
  try {
    // Get existing surveys
    const existingSurveys = await getLocalSurveys();

    // Add new survey with timestamp
    const updatedSurveys = [...existingSurveys, {
      ...surveyData,
      localId: Date.now().toString(),
      timestamp: new Date().toISOString(),
      isSynced: false
    }];

    // Save to storage
    await AsyncStorage.setItem(STORAGE_KEYS.SURVEYS, JSON.stringify(updatedSurveys));

    return updatedSurveys;
  } catch (error) {
    console.error('Error saving survey locally:', error);
    throw error;
  }
};

export const getLocalSurveys = async () => {
  try {
    const surveys = await AsyncStorage.getItem(STORAGE_KEYS.SURVEYS);
    return surveys ? JSON.parse(surveys) : [];
  } catch (error) {
    console.error('Error getting local surveys:', error);
    return [];
  }
};

export const markSurveyAsSynced = async (localId) => {
  try {
    const surveys = await getLocalSurveys();
    const updatedSurveys = surveys.map(survey =>
      survey.localId === localId ? { ...survey, isSynced: true } : survey
    );

    await AsyncStorage.setItem(STORAGE_KEYS.SURVEYS, JSON.stringify(updatedSurveys));
    return updatedSurveys;
  } catch (error) {
    console.error('Error marking survey as synced:', error);
    throw error;
  }
};

export const addToPendingSync = async (survey) => {
  try {
    const pending = await getPendingSync();
    const updatedPending = [...pending, survey];
    await AsyncStorage.setItem(STORAGE_KEYS.PENDING_SYNC, JSON.stringify(updatedPending));
    return updatedPending;
  } catch (error) {
    console.error('Error adding to pending sync:', error);
    throw error;
  }
};

export const getPendingSync = async () => {
  try {
    const pending = await AsyncStorage.getItem(STORAGE_KEYS.PENDING_SYNC);
    return pending ? JSON.parse(pending) : [];
  } catch (error) {
    console.error('Error getting pending sync:', error);
    return [];
  }
};

export const clearPendingSync = async () => {
  try {
    await AsyncStorage.removeItem(STORAGE_KEYS.PENDING_SYNC);
  } catch (error) {
    console.error('Error clearing pending sync:', error);
    throw error;
  }
};
```

