### 3. Sync Service (`syncService.js`)

```javascript
import { getPendingSync, clearPendingSync, markSurveyAsSynced } from './localStorage';
import { syncSurveyToServer } from './apiService';
import { isOnline } from './network';

export const attemptSync = async () => {
  if (!isOnline()) {
    console.log('No internet connection - sync deferred');
    return false;
  }

  try {
    const pendingSurveys = await getPendingSync();

    if (pendingSurveys.length === 0) {
      console.log('No pending surveys to sync');
      return true;
    }

    for (const survey of pendingSurveys) {
      try {
        await syncSurveyToServer(survey);
        await markSurveyAsSynced(survey.localId);
      } catch (error) {
        console.error('Failed to sync survey:', survey.localId, error);
        // Continue with next survey even if one fails
        continue;
      }
    }

    // Clear all successfully synced surveys from pending
    await clearPendingSync();
    return true;
  } catch (error) {
    console.error('Error during sync process:', error);
    return false;
  }
};

// Set up periodic sync checks
export const setupPeriodicSync = (interval = 300000) => { // 5 minutes default
  const syncInterval = setInterval(async () => {
    if (isOnline()) {
      await attemptSync();
    }
  }, interval);

  return () => clearInterval(syncInterval);
};
