### 6. App Context (`AppContext.js`)

```javascript
import React, { createContext, useState, useEffect } from 'react';
import { getLocalSurveys } from './services/localStorage';
import { addNetworkListener } from './utils/network';
import { attemptSync, setupPeriodicSync } from './services/syncService';

export const AppContext = createContext();

export const AppProvider = ({ children }) => {
  const [surveys, setSurveys] = useState([]);
  const [isOnline, setIsOnline] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    // Load initial surveys
    const loadSurveys = async () => {
      const localSurveys = await getLocalSurveys();
      setSurveys(localSurveys);
    };

    loadSurveys();

    // Set up network listener
    const unsubscribe = addNetworkListener(async (online) => {
      setIsOnline(online);

      if (online) {
        // Attempt sync when connection is restored
        setIsSyncing(true);
        const syncSuccess = await attemptSync();
        if (syncSuccess) {
          const updatedSurveys = await getLocalSurveys();
          setSurveys(updatedSurveys);
        }
        setIsSyncing(false);
      }
    });

    // Set up periodic sync
    const clearSyncInterval = setupPeriodicSync();

    return () => {
      unsubscribe();
      clearSyncInterval();
    };
  }, []);

  return (
    <AppContext.Provider value={{
      surveys,
      setSurveys,
      isOnline,
      isSyncing
    }}>
      {children}
    </AppContext.Provider>
  );
};
```

