## Sync Manager Service

```javascript
// services/SyncManager.js
import AsyncStorage from '@react-native-async-storage/async-storage';
import { API_BASE_URL } from '../config';

class SyncManager {
  constructor() {
    this.pendingSurveysKey = 'pendingSurveys';
  }

  // Add a survey to the pending sync queue
  async addToPendingQueue(surveyData) {
    try {
      const pendingSurveys = await this.getPendingSurveys();
      pendingSurveys.push(surveyData);
      await AsyncStorage.setItem(
        this.pendingSurveysKey,
        JSON.stringify(pendingSurveys)
      );
    } catch (error) {
      console.error('Error adding to pending queue:', error);
      throw error;
    }
  }

  // Get all pending surveys
  async getPendingSurveys() {
    try {
      const pendingSurveys = await AsyncStorage.getItem(this.pendingSurveysKey);
      return pendingSurveys ? JSON.parse(pendingSurveys) : [];
    } catch (error) {
      console.error('Error getting pending surveys:', error);
      return [];
    }
  }

  // Sync a single survey
  async syncSurvey(surveyData) {
    try {
      const response = await fetch(`${API_BASE_URL}/api/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(surveyData),
      });

      if (!response.ok) {
        throw new Error('Failed to sync survey');
      }

      return true;
    } catch (error) {
      console.error('Sync error:', error);
      // If sync fails, add to pending queue
      await this.addToPendingQueue(surveyData);
      return false;
    }
  }

  // Sync all pending surveys
  async syncAllPending() {
    try {
      const pendingSurveys = await this.getPendingSurveys();
      let syncedCount = 0;

      for (const survey of pendingSurveys) {
        const success = await this.syncSurvey(survey);
        if (success) {
          syncedCount++;
        }
      }

      // Remove synced surveys from pending queue
      if (syncedCount > 0) {
        const remainingSurveys = pendingSurveys.slice(syncedCount);
        await AsyncStorage.setItem(
          this.pendingSurveysKey,
          JSON.stringify(remainingSurveys)
        );
      }

      return syncedCount;
    } catch (error) {
      console.error('Error syncing all pending:', error);
      throw error;
    }
  }

  // Clear all pending surveys
  async clearPendingSurveys() {
    try {
      await AsyncStorage.removeItem(this.pendingSurveysKey);
    } catch (error) {
      console.error('Error clearing pending surveys:', error);
      throw error;
    }
  }
}

export default SyncManager;
```

