## Backend Setup (Node.js/Express)

First, let's set up a simple backend API to handle data synchronization:

```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');
const sqlite3 = require('sqlite3').verbose();
const cors = require('cors');

const app = express();
const PORT = 3000;

// Database setup
const db = new sqlite3.Database('./surveys.db', (err) => {
  if (err) {
    console.error('Database connection error:', err.message);
  } else {
    console.log('Connected to the SQLite database.');
    initializeDatabase();
  }
});

function initializeDatabase() {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      user_id TEXT,
      location TEXT,
      survey_data TEXT,
      timestamp INTEGER,
      is_synced INTEGER DEFAULT 0,
      version INTEGER DEFAULT 1
    )
  `);
}

app.use(cors());
app.use(bodyParser.json());

// Sync endpoint
app.post('/api/sync', async (req, res) => {
  const { userId, surveys } = req.body;

  try {
    // Process each survey
    for (const survey of surveys) {
      // Check if survey exists
      const existing = await new Promise((resolve, reject) => {
        db.get('SELECT * FROM surveys WHERE id = ?', [survey.id], (err, row) => {
          if (err) reject(err);
          resolve(row);
        });
      });

      if (existing) {
        // Update existing survey if newer version
        if (survey.version > existing.version) {
          await new Promise((resolve, reject) => {
            db.run(
              'UPDATE surveys SET survey_data = ?, timestamp = ?, is_synced = 1, version = ? WHERE id = ?',
              [JSON.stringify(survey.data), survey.timestamp, survey.version, survey.id],
              (err) => {
                if (err) reject(err);
                resolve();
              }
            );
          });
        }
      } else {
        // Insert new survey
        await new Promise((resolve, reject) => {
          db.run(
            'INSERT INTO surveys (id, user_id, location, survey_data, timestamp, is_synced, version) VALUES (?, ?, ?, ?, ?, 1, ?)',
            [survey.id, userId, survey.location, JSON.stringify(survey.data), survey.timestamp, survey.version],
            (err) => {
              if (err) reject(err);
              resolve();
            }
          );
        });
      }
    }

    // Get all surveys for the user to send back
    const allSurveys = await new Promise((resolve, reject) => {
      db.all('SELECT * FROM surveys WHERE user_id = ?', [userId], (err, rows) => {
        if (err) reject(err);
        resolve(rows);
      });
    });

    res.json({
      success: true,
      surveys: allSurveys.map(row => ({
        id: row.id,
        data: JSON.parse(row.survey_data),
        timestamp: row.timestamp,
        version: row.version
      }))
    });
  } catch (error) {
    console.error('Sync error:', error);
    res.status(500).json({ success: false, error: 'Sync failed' });
  }
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

