  });
  const [isOnline, setIsOnline] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Initialize user and load surveys
  useEffect(() => {
    const initialize = async () => {
      // Get or create user ID
      let storedUserId = await AsyncStorage.getItem('userId');
      if (!storedUserId) {
        storedUserId = uuid.v4();
        await AsyncStorage.setItem('userId', storedUserId);
      }
      setUserId(storedUserId);

      // Load local surveys
      loadLocalSurveys(storedUserId);
    };

    initialize();

    // Set up network listener
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) {
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from local storage
  const loadLocalSurveys = async (userId) => {
    try {
      const storedSurveys = await AsyncStorage.getItem(`surveys_${userId}`);
      if (storedSurveys) {
        setSurveys(JSON.parse(storedSurveys));
      }
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  };

  // Save survey locally
  const saveSurveyLocally = async (survey) => {
    try {
      const updatedSurveys = [...surveys, survey];
      await AsyncStorage.setItem(`surveys_${userId}`, JSON.stringify(updatedSurveys));
      setSurveys(updatedSurveys);
      setCurrentSurvey({
        id: uuid.v4(),
        location: '',
        data: '',
        timestamp: Date.now(),
        version: 1
      });
    } catch (error) {
      console.error('Error saving survey:', error);
    }
  };

  // Sync data with server
  const syncData = async () => {
    if (!isOnline || isSyncing) return;

    setIsSyncing(true);
    try {
      // Get unsynced surveys
      const unsyncedSurveys = surveys.filter(survey => !survey.isSynced);

      if (unsyncedSurveys.length === 0) {
        setIsSyncing(false);
        return;
      }

      const response = await fetch(SERVER_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
