        }),
      });

      const result = await response.json();

      if (result.success) {
        // Update local surveys with synced status
        const updatedSurveys = surveys.map(survey => {
          const syncedSurvey = result.surveys.find(s => s.id === survey.id);
          if (syncedSurvey) {
            return { ...survey, isSynced: true, version: syncedSurvey.version };
          }
          return survey;
        });

        // Save updated surveys
        await AsyncStorage.setItem(`surveys_${userId}`, JSON.stringify(updatedSurveys));
        setSurveys(updatedSurveys);
