      }
    });

    return () => unsubscribe();
  }, []);

  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY timestamp DESC',
        [],
        (tx, results) => {
          const rows = results.rows.raw();
          setSurveys(rows);
        },
        error => console.error('Error loading surveys:', error)
      );
    });
  };

  const saveSurvey = () => {
    if (!currentSurvey.location.trim()) {
      Alert.alert('Error', 'Please enter a location');
      return;
    }

    const timestamp = new Date().toISOString();

    if (currentSurvey.id) {
      // Update existing survey
      db.transaction(tx => {
        tx.executeSql(
          'UPDATE surveys SET location = ?, notes = ?, timestamp = ? WHERE id = ?',
          [currentSurvey.location, currentSurvey.notes, timestamp, currentSurvey.id],
          () => {
            loadSurveys();
            setCurrentSurvey({
              id: null,
              location: '',
              notes: '',
              timestamp: null,
              synced: false
            });
          },
          error => console.error('Error updating survey:', error)
        );
      });
    } else {
      // Insert new survey
      db.transaction(tx => {
        tx.executeSql(
          'INSERT INTO surveys (location, notes, timestamp, synced) VALUES (?, ?, ?, ?)',
          [currentSurvey.location, currentSurvey.notes, timestamp, 0],
          () => {
            loadSurveys();
            setCurrentSurvey({
              id: null,
              location: '',
              notes: '',
              timestamp: null,
              synced: false
            });
          },
          error => console.error('Error saving survey:', error)
        );
      });
    }
  };

  const syncData = async () => {
    try {
      // Get unsynced surveys
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE synced = 0',
          [],
          async (tx, results) => {
            const unsyncedSurveys = results.rows.raw();

            if (unsyncedSurveys.length > 0) {
              // In a real app, you would send this to your backend API
              console.log('Syncing data:', unsyncedSurveys);

              // Simulate API call
              await new Promise(resolve => setTimeout(resolve, 1000));

              // Mark as synced in local DB
              db.transaction(tx => {
                tx.executeSql(
                  'UPDATE surveys SET synced = 1 WHERE synced = 0',
                  [],
                  () => {
                    console.log('Data synced successfully');
                    loadSurveys();
                  },
                  error => console.error('Error marking surveys as synced:', error)
                );
              });
            }
          },
          error => console.error('Error getting unsynced surveys:', error)
        );
      });
    } catch (error) {
      console.error('Sync error:', error);
    }
  };

  const editSurvey = (survey) => {
    setCurrentSurvey(survey);
  };

  const deleteSurvey = (id) => {
    db.transaction(tx => {
      tx.executeSql(
        'DELETE FROM surveys WHERE id = ?',
        [id],
        () => {
          loadSurveys();
        },
        error => console.error('Error deleting survey:', error)
      );
    });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <Text style={styles.status}>Status: {isConnected ? 'Online' : 'Offline'}</Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={currentSurvey.location}
          onChangeText={text => setCurrentSurvey({...currentSurvey, location: text})}
        />
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Notes"
          multiline
          numberOfLines={4}
          value={currentSurvey.notes}
          onChangeText={text => setCurrentSurvey({...currentSurvey, notes: text})}
        />
        <Button
          title={currentSurvey.id ? "Update Survey" : "Save Survey"}
          onPress={saveSurvey}
        />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={item => item.id.toString()}
        renderItem={({item}) => (
          <View style={styles.surveyItem}>
            <Text style={styles.surveyLocation}>{item.location}</Text>
            <Text style={styles.surveyDate}>
              {new Date(item.timestamp).toLocaleString()}
              {item.synced ? ' (Synced)' : ' (Pending)'}
            </Text>
            <Text style={styles.surveyNotes}>{item.notes}</Text>
            <View style={styles.buttonGroup}>
              <Button title="Edit" onPress={() => editSurvey(item)} />
              <Button title="Delete" onPress={() => deleteSurvey(item.id)} color="red" />
            </View>
          </View>
        )}
      />
    </View>
  );
};

