// server.js
const express = require('express');
const bodyParser = require('body-parser');
const sqlite3 = require('sqlite3').verbose();
const cors = require('cors');

const app = express();
const PORT = 3000;

// Middleware
app.use(cors());
app.use(bodyParser.json());

// Database setup
const db = new sqlite3.Database('./surveyApp.db', (err) => {
  if (err) {
    console.error('Error opening database:', err.message);
  } else {
    console.log('Connected to the SQLite database.');

    // Create tables if they don't exist
    db.run(`
      CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        location TEXT NOT NULL,
        notes TEXT,
        timestamp DATETIME NOT NULL,
        userId INTEGER NOT NULL
      )
    `);

    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
      )
    `);
  }
});

// API Endpoints

// Sync surveys
app.post('/api/sync', (req, res) => {
  const { surveys, userId } = req.body;

  if (!surveys || !Array.isArray(surveys) || !userId) {
    return res.status(400).json({ error: 'Invalid request data' });
  }

  const stmt = db.prepare(`
    INSERT OR REPLACE INTO surveys (id, location, notes, timestamp, userId)
    VALUES (?, ?, ?, ?, ?)
  `);

  surveys.forEach(survey => {
    stmt.run(
      survey.id,
      survey.location,
      survey.notes,
      survey.timestamp,
      userId
    );
  });

  stmt.finalize();

  res.json({ success: true, message: 'Surveys synced successfully' });
});

// Get surveys for a user
app.get('/api/surveys/:userId', (req, res) => {
  const userId = req.params.userId;

  db.all(
    'SELECT * FROM surveys WHERE userId = ? ORDER BY timestamp DESC',
    [userId],
    (err, rows) => {
      if (err) {
        return res.status(500).json({ error: err.message });
      }
      res.json(rows);
    }
  );
});

// User authentication (simplified for example)
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;

  db.get(
    'SELECT * FROM users WHERE username = ? AND password = ?',
    [username, password],
    (err, user) => {
      if (err) {
        return res.status(500).json({ error: err.message });
      }
      if (!user) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }
      res.json({ userId: user.id });
    }
  );
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
