### 2. DatabaseService.js (Local Storage)

```javascript
import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase(
  { name: 'surveys.db', location: 'default' },
  () => {},
  error => { console.error(error); }
);

export const DatabaseService = {
  init: () => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          title TEXT,
          description TEXT,
          location TEXT,
          data JSON,
          isSynced INTEGER DEFAULT 0,
          createdAt TEXT DEFAULT CURRENT_TIMESTAMP
        );`
      );
    });
  },

  saveSurvey: (surveyData) => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'INSERT INTO surveys (title, description, location, data) VALUES (?, ?, ?, ?)',
          [surveyData.title, surveyData.description, surveyData.location, JSON.stringify(surveyData.data)],
          (_, result) => resolve(result.insertId),
          (_, error) => reject(error)
        );
      });
    });
  },

  getAllSurveys: () => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys ORDER BY createdAt DESC',
          [],
          (_, { rows }) => resolve(rows._array),
          (_, error) => reject(error)
        );
      });
    });
  },

  getUnsyncedSurveys: () => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE isSynced = 0',
          [],
          (_, { rows }) => resolve(rows._array),
          (_, error) => reject(error)
        );
      });
    });
  },

  markAsSynced: (surveyId) => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'UPDATE surveys SET isSynced = 1 WHERE id = ?',
          [surveyId],
          () => resolve(),
          (_, error) => reject(error)
        );
      });
    });
  }
};
```

### 3. SyncService.js (Sync Logic)

```javascript
import { DatabaseService } from './DatabaseService';
import { API_BASE_URL } from '../config';

export const SyncService = {
  syncPendingSurveys: async () => {
    try {
      const unsyncedSurveys = await DatabaseService.getUnsyncedSurveys();

      for (const survey of unsyncedSurveys) {
        const response = await fetch(`${API_BASE_URL}/api/surveys`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            title: survey.title,
            description: survey.description,
            location: survey.location,
            data: JSON.parse(survey.data),
            createdAt: survey.createdAt
          }),
        });

        if (response.ok) {
          await DatabaseService.markAsSynced(survey.id);
        }
      }

      return unsyncedSurveys.length;
    } catch (error) {
      console.error('Sync error:', error);
      throw error;
    }
  }
};
```

