```javascript
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./surveys.db');

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS surveys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    location TEXT,
    data TEXT,
    createdAt TEXT DEFAULT CURRENT_TIMESTAMP
  )`);
});

const Survey = {
  create: (surveyData) => {
    return new Promise((resolve, reject) => {
      const stmt = db.prepare(
        'INSERT INTO surveys (title, description, location, data) VALUES (?, ?, ?, ?)'
      );
      stmt.run(
        surveyData.title,
        surveyData.description,
        surveyData.location,
        JSON.stringify(surveyData.data),
        function(err) {
          if (err) {
            reject(err);
          } else {
            resolve({ id: this.lastID, ...surveyData });
          }
        }
      );
      stmt.finalize();
    });
  },

  getAll: () => {
    return new Promise((resolve, reject) => {
      db.all('SELECT * FROM surveys ORDER BY createdAt DESC', (err, rows) => {
        if (err) {
          reject(err);
        } else {
          resolve(rows.map(row => ({
            ...row,
            data: JSON.parse(row.data)
          })));
        }
      });
    });
  },

  getById: (id) => {
    return new Promise((resolve, reject) => {
      db.get('SELECT * FROM surveys WHERE id = ?', [id], (err, row) => {
        if (err) {
          reject(err);
        } else if (row) {
          resolve({
            ...row,
            data: JSON.parse(row.data)
          });
        } else {
          resolve(null);
        }
      });
    });
  },

  update: (id, surveyData) => {
    return new Promise((resolve, reject) => {
      const stmt = db.prepare(
        'UPDATE surveys SET title = ?, description = ?, location = ?, data = ? WHERE id = ?'
      );
      stmt.run(
        surveyData.title,
        surveyData.description,
        surveyData.location,
        JSON.stringify(surveyData.data),
        id,
        function(err) {
          if (err) {
            reject(err);
          } else if (this.changes > 0) {
            resolve({ id, ...surveyData });
          } else {
            resolve(null);
          }
        }
      );
      stmt.finalize();
    });
  },

  delete: (id) => {
    return new Promise((resolve, reject) => {
      db.run('DELETE FROM surveys WHERE id = ?', [id], function(err) {
        if (err) {
          reject(err);
        } else {
          resolve(this.changes > 0);
        }
      });
    });
  }
};

module.exports = Survey;
```

