```javascript
// app.js
document.addEventListener('DOMContentLoaded', () => {
  const surveyApp = new SurveyApp();
  const connectionStatus = document.getElementById('connection-status');
  const surveyForm = document.getElementById('survey-form');
  const surveysList = document.getElementById('surveys');

  // Update connection status UI
  function updateConnectionStatus() {
    connectionStatus.textContent = navigator.onLine ? 'Online' : 'Offline';
    connectionStatus.className = navigator.onLine ? 'online' : 'offline';
  }

  // Handle form submission
  surveyForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const surveyData = {
      location: document.getElementById('location').value,
      species: document.getElementById('species').value,
      count: document.getElementById('count').value,
      notes: document.getElementById('notes').value,
      timestamp: new Date().toISOString()
    };

    try {
      await surveyApp.saveSurvey(surveyData);
      surveyForm.reset();
      updateSurveysList();
    } catch (error) {
      console.error('Error saving survey:', error);
      alert('Survey saved locally. Will sync when online.');
    }
  });

  // Update surveys list
  async function updateSurveysList() {
    try {
      const surveys = await surveyApp.getSurveys();
      surveysList.innerHTML = '';

      surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
          <strong>${survey.location}</strong> - ${survey.species} (${survey.count})
          <span class="sync-status">${survey.synced ? '✓ Synced' : '⏳ Pending'}</span>
        `;
        surveysList.appendChild(li);
      });
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  }

  // Initial setup
  updateConnectionStatus();
  updateSurveysList();

  // Listen for connection changes
  window.addEventListener('online', () => {
    updateConnectionStatus();
    updateSurveysList();
  });

  window.addEventListener('offline', () => {
    updateConnectionStatus();
  });

  // Periodically check for sync when online
  setInterval(async () => {
    if (navigator.onLine) {
      await surveyApp.syncData();
      updateSurveysList();
    }
  }, 30000); // Check every 30 seconds
});
