      const pendingSurveys = surveys.filter(s => s.status === 'pending');

      if (pendingSurveys.length > 0) {
        const syncedIds = await syncData(pendingSurveys);

        // Update local database with synced status
        db.transaction(tx => {
          syncedIds.forEach(id => {
            tx.executeSql(
              'UPDATE surveys SET status = ? WHERE id = ?;',
              ['synced', id]
            );
          });
        });

        loadSurveys();
      }
    } catch (error) {
      console.log('Sync error:', error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <Text style={styles.status}>Connection: {isConnected ? 'Online' : 'Offline'}</Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={newSurvey.location}
          onChangeText={text => setNewSurvey({...newSurvey, location: text})}
        />
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Notes"
          multiline
          value={newSurvey.notes}
          onChangeText={text => setNewSurvey({...newSurvey, notes: text})}
        />
        <Button title="Add Survey" onPress={addSurvey} />
      </View>

      <FlatList
        data={surveys}
        keyExtractor={item => item.id.toString()}
        renderItem={({ item }) => (
          <View style={styles.surveyItem}>
            <Text style={styles.location}>{item.location}</Text>
            <Text>{item.notes}</Text>
            <Text style={[
              styles.status,
              item.status === 'pending' ? styles.pending : styles.synced
            ]}>
              {item.status}
            </Text>
          </View>
        )}
      />
    </View>
  );
};

