// Database setup
const db = new sqlite3.Database('./surveys.db', (err) => {
  if (err) {
    console.error(err.message);
  }
  console.log('Connected to the surveys database.');
});

// Create table if not exists
db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS surveys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    location TEXT NOT NULL,
    notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);
});

app.use(bodyParser.json());

// Sync endpoint
app.post('/api/sync', (req, res) => {
  const surveys = req.body;
  const syncedIds = [];

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: 'Invalid data format' });
  }

  const stmt = db.prepare('INSERT INTO surveys (location, notes) VALUES (?, ?)');

  db.serialize(() => {
    db.run('BEGIN TRANSACTION');

    surveys.forEach(survey => {
      stmt.run(survey.location, survey.notes, function(err) {
        if (err) {
          console.error('Error inserting survey:', err);
        } else {
          syncedIds.push(survey.id);
        }
      });
    });

    stmt.finalize();

    db.run('COMMIT', (err) => {
      if (err) {
        console.error('Transaction commit error:', err);
        return res.status(500).json({ error: 'Database error' });
      }

      res.json({ syncedIds });
    });
  });
});

// Get all surveys (for testing)
app.get('/api/surveys', (req, res) => {
  db.all('SELECT * FROM surveys ORDER BY created_at DESC', [], (err, rows) => {
