  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (id, title, description, createdAt, version) VALUES (?, ?, ?, ?, ?)',
        [id, surveyData.title, surveyData.description, timestamp, 1],
        (_, result) => resolve(id),
        (_, error) => reject(error)
      );
    });
