    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO responses (id, surveyId, data, status, createdAt, updatedAt) VALUES (?, ?, ?, ?, ?, ?)',
        [id, surveyId, JSON.stringify(responseData), 'pending', timestamp, timestamp],
        (_, result) => resolve(id),
        (_, error) => reject(error)
      );
    });
  });
};

export const getPendingResponses = async () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
