### 3. Sync Service

```javascript
// syncService.js
import { getPendingResponses } from './offlineService';
import { uploadResponse } from './apiService';

export const syncData = async () => {
  try {
    const pendingResponses = await getPendingResponses();

    for (const response of pendingResponses) {
      try {
        // Upload to server
        await uploadResponse(response);

        // Mark as synced
        await markResponseAsSynced(response.id);
      } catch (error) {
        console.error('Failed to sync response', response.id, error);
        // Implement retry logic or conflict resolution
      }
    }

    return { success: true, syncedCount: pendingResponses.length };
  } catch (error) {
    console.error('Sync failed', error);
    return { success: false, error };
  }
};

const markResponseAsSynced = async (responseId) => {
  const timestamp = new Date().toISOString();

  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE responses SET status = ?, updatedAt = ? WHERE id = ?',
        ['synced', timestamp, responseId],
        (_, result) => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};
