import NetInfo from '@react-native-community/netinfo';
import { API_URL } from './config';

const db = SQLite.openDatabase('surveyApp.db');

const App = () => {
  const [surveys, setSurveys] = useState([]);
  const [newSurvey, setNewSurvey] = useState({
    location: '',
    notes: '',
    timestamp: new Date().toISOString()
  });
  const [isConnected, setIsConnected] = useState(false);

  // Initialize database
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, location TEXT, notes TEXT, timestamp TEXT, synced INTEGER DEFAULT 0);'
      );
    });

    // Check network status
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from local database
  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY timestamp DESC;',
        [],
        (_, { rows: { _array } }) => setSurveys(_array)
      );
    });
  };

  // Add a new survey (works offline)
