    try {
      const storedSurveys = await AsyncStorage.getItem('surveys');
      if (storedSurveys) {
        setSurveys(JSON.parse(storedSurveys));
      }
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  };

  const saveSurveys = async (surveysToSave) => {
    try {
      await AsyncStorage.setItem('surveys', JSON.stringify(surveysToSave));
    } catch (error) {
      console.error('Error saving surveys:', error);
    }
  };

  const addSurvey = () => {
    if (!newSurvey.location || !newSurvey.notes) {
      Alert.alert('Error', 'Please fill in all fields');
      return;
    }

    const surveyWithTimestamp = {
      ...newSurvey,
      timestamp: new Date().toISOString(),
      status: 'pending'
    };

    const updatedSurveys = [...surveys, surveyWithTimestamp];
    setSurveys(updatedSurveys);
    saveSurveys(updatedSurveys);

    // Reset form
    setNewSurvey({
      location: '',
      notes: '',
      timestamp: '',
      status: 'pending'
    });

    // If online, sync immediately
    if (isConnected) {
      syncSurvey(surveyWithTimestamp);
    }
  };

  const syncSurveys = async () => {
    const pendingSurveys = surveys.filter(survey => survey.status === 'pending');

    for (const survey of pendingSurveys) {
      await syncSurvey(survey);
    }
  };

  const syncSurvey = async (survey) => {
    try {
      const response = await fetch('http://your-backend-api.com/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(survey),
      });

      if (response.ok) {
        // Update local status
        const updatedSurveys = surveys.map(s =>
          s.timestamp === survey.timestamp ? { ...s, status: 'synced' } : s
        );
        setSurveys(updatedSurveys);
        saveSurveys(updatedSurveys);
      }
    } catch (error) {
      console.error('Sync error:', error);
    }
  };

  return (
    <View style={styles.container}>
