```javascript
// database.js
import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase(
  { name: 'surveyDB.db', location: 'default' },
  () => console.log('Database opened'),
  error => console.error('Error opening database', error)
);

export const initDatabase = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        location TEXT,
        data TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        last_updated INTEGER NOT NULL
      );`
    );
  });
};

export const saveSurveyOffline = (surveyData) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (user_id, timestamp, location, data, status, last_updated)
         VALUES (?, ?, ?, ?, 'pending', ?)`,
        [
          surveyData.userId,
          Date.now(),
          JSON.stringify(surveyData.location),
          JSON.stringify(surveyData.data),
          Date.now()
        ],
        (_, result) => resolve(result.insertId),
        (_, error) => reject(error)
      );
    });
  });
};

export const getPendingSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE status = 'pending'`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const updateSurveyStatus = (id, status) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET status = ?, last_updated = ? WHERE id = ?`,
        [status, Date.now(), id],
        (_, result) => resolve(result.rowsAffected),
        (_, error) => reject(error)
      );
    });
  });
};
```

### 2. Network Sync Service

```javascript
// syncService.js
import { getPendingSurveys, updateSurveyStatus } from './database';
import NetInfo from '@react-native-community/netinfo';

const SYNC_INTERVAL = 30000; // 30 seconds
let syncInterval;

export const startSyncService = () => {
  syncInterval = setInterval(checkAndSync, SYNC_INTERVAL);
  // Also check on app resume
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncPendingSurveys();
    }
  });
};

export const stopSyncService = () => {
  if (syncInterval) {
    clearInterval(syncInterval);
  }
};

const checkAndSync = async () => {
  const state = await NetInfo.fetch();
  if (state.isConnected) {
    await syncPendingSurveys();
  }
};

const syncPendingSurveys = async () => {
  try {
    const pendingSurveys = await getPendingSurveys();

    for (const survey of pendingSurveys) {
      try {
        // Mark as syncing to prevent duplicate sync attempts
        await updateSurveyStatus(survey.id, 'syncing');

        // Prepare data for API
        const surveyData = {
          ...JSON.parse(survey.data),
          metadata: {
            timestamp: survey.timestamp,
            location: JSON.parse(survey.location)
          }
        };

        // Send to server
        const response = await fetch('https://api.example.com/surveys', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${getAuthToken()}`
          },
          body: JSON.stringify(surveyData)
        });

        if (response.ok) {
          // Mark as synced
          await updateSurveyStatus(survey.id, 'synced');
        } else {
          // Mark as failed to retry later
          await updateSurveyStatus(survey.id, 'failed');
        }
      } catch (error) {
        console.error('Error syncing survey', survey.id, error);
        await updateSurveyStatus(survey.id, 'failed');
      }
    }
  } catch (error) {
    console.error('Error getting pending surveys', error);
  }
};
```

