  const [currentSurvey, setCurrentSurvey] = useState({
    id: Date.now().toString(),
    location: '',
    notes: '',
    timestamp: new Date().toISOString(),
    synced: false
  });
  const [isConnected, setIsConnected] = useState(false);

  // Load saved surveys from AsyncStorage
  useEffect(() => {
    const loadSurveys = async () => {
      try {
        const savedSurveys = await AsyncStorage.getItem('surveys');
        if (savedSurveys) {
          setSurveys(JSON.parse(savedSurveys));
        }
      } catch (error) {
        console.error('Error loading surveys:', error);
      }
    };
    loadSurveys();

    // Check network status
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  // Save surveys to AsyncStorage whenever they change
  useEffect(() => {
    const saveSurveys = async () => {
      try {
        await AsyncStorage.setItem('surveys', JSON.stringify(surveys));
      } catch (error) {
        console.error('Error saving surveys:', error);
      }
    };
    saveSurveys();
  }, [surveys]);

  const handleInputChange = (field, value) => {
    setCurrentSurvey({ ...currentSurvey, [field]: value });
  };

