        error => console.log('Error loading surveys: ', error)
      );
    });
  };

  // Add new survey to local database
  const addSurvey = () => {
    if (!newSurvey.location) return;

    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (location, notes, timestamp, status) VALUES (?, ?, ?, ?)',
        [newSurvey.location, newSurvey.notes, newSurvey.timestamp, newSurvey.status],
        () => {
          console.log('Survey added to local database');
          loadSurveys();
          setNewSurvey({
            location: '',
            notes: '',
            timestamp: new Date().toISOString(),
            status: 'pending'
          });
        },
        error => console.log('Error adding survey: ', error)
      );
    });
  };

  // Sync pending surveys with server
  const syncData = async () => {
    try {
      // Get pending surveys
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE status = ?',
          ['pending'],
          async (tx, results) => {
            const pendingSurveys = results.rows.raw();

            if (pendingSurveys.length > 0) {
              // Simulate API call to sync with server
              console.log('Syncing with server...');
              await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate network delay

              // Update status to 'synced' after successful sync
              db.transaction(tx => {
                pendingSurveys.forEach(survey => {
                  tx.executeSql(
                    'UPDATE surveys SET status = ? WHERE id = ?',
                    ['synced', survey.id],
                    () => console.log(`Survey ${survey.id} marked as synced`),
                    error => console.log('Error updating survey status: ', error)
                  );
                });
              });

              loadSurveys();
            }
          },
          error => console.log('Error fetching pending surveys: ', error)
        );
      });
    } catch (error) {
      console.log('Sync error: ', error);
    }
  };

  // Load surveys when component mounts
  useEffect(() => {
    loadSurveys();
  }, []);

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <Text style={styles.status}>Network Status: {isConnected ? 'Online' : 'Offline'}</Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={newSurvey.location}
          onChangeText={text => setNewSurvey({...newSurvey, location: text})}
        />
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Notes"
          multiline
          value={newSurvey.notes}
          onChangeText={text => setNewSurvey({...newSurvey, notes: text})}
        />
        <Button title="Add Survey" onPress={addSurvey} />
      </View>

      <Text style={styles.sectionTitle}>Recent Surveys</Text>
      <FlatList
        data={surveys}
        keyExtractor={item => item.id.toString()}
        renderItem={({item}) => (
          <View style={styles.surveyItem}>
            <Text style={styles.surveyLocation}>{item.location}</Text>
            <Text style={styles.surveyNotes}>{item.notes}</Text>
