export const initDatabase = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        is_synced BOOLEAN DEFAULT 0
      );`,
      [],
      () => console.log('Surveys table created'),
      (_, error) => console.error('Error creating surveys table', error)
    );

    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS survey_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        survey_id INTEGER NOT NULL,
        question TEXT NOT NULL,
        answer TEXT,
        FOREIGN KEY (survey_id) REFERENCES surveys (id)
      );`,
      [],
      () => console.log('Survey items table created'),
      (_, error) => console.error('Error creating survey items table', error)
    );
  });
};

export const saveSurvey = (surveyData) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (title, description) VALUES (?, ?)',
        [surveyData.title, surveyData.description],
        (_, result) => {
          const surveyId = result.insertId;
          const items = surveyData.items.map(item => [surveyId, item.question, item.answer]);

          tx.executeSql(
            'INSERT INTO survey_items (survey_id, question, answer) VALUES (?, ?, ?)',
            items.flat(),
            () => resolve(surveyId),
            (_, error) => reject(error)
          );
        },
        (_, error) => reject(error)
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT s.id, s.title, s.description, s.created_at,
                json_group_array(json_object('question', si.question, 'answer', si.answer)) as items
         FROM surveys s
         LEFT JOIN survey_items si ON s.id = si.survey_id
         WHERE s.is_synced = 0
         GROUP BY s.id`,
        [],
        (_, result) => {
          const surveys = [];
          for (let i = 0; i < result.rows.length; i++) {
            surveys.push({
              id: result.rows.item(i).id,
              title: result.rows.item(i).title,
              description: result.rows.item(i).description,
              created_at: result.rows.item(i).created_at,
              items: JSON.parse(result.rows.item(i).items || '[]')
            });
          }
          resolve(surveys);
        },
        (_, error) => reject(error)
      );
    });
  });
};

export const markSurveyAsSynced = (surveyId) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET is_synced = 1 WHERE id = ?',
        [surveyId],
        () => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};
```

### 3. Sync Service (`src/services/sync.js`)

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getUnsyncedSurveys, markSurveyAsSynced } from './database';
import axios from 'axios';

const API_URL = 'http://your-server-address/api/surveys';

export const syncData = async () => {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return false;

  try {
    const unsyncedSurveys = await getUnsyncedSurveys();

    for (const survey of unsyncedSurveys) {
      await axios.post(API_URL, survey);
      await markSurveyAsSynced(survey.id);
    }

    return true;
  } catch (error) {
    console.error('Sync error:', error);
    return false;
  }
};

// Set up periodic sync
export const setupSync = () => {
  // Sync when app comes online
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncData();
    }
  });

  // Sync periodically while online
  const interval = setInterval(async () => {
    const state = await NetInfo.fetch();
    if (state.isConnected) {
      syncData();
    }
  }, 300000); // Every 5 minutes

  return () => clearInterval(interval);
};
```

