```javascript
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./surveys.db');

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS surveys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS survey_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    survey_id INTEGER NOT NULL,
    question TEXT NOT NULL,
    answer TEXT,
    FOREIGN KEY (survey_id) REFERENCES surveys (id)
  )`);
});

module.exports = {
  saveSurvey: (surveyData, callback) => {
    db.serialize(() => {
      db.run(
        'INSERT INTO surveys (title, description) VALUES (?, ?)',
        [surveyData.title, surveyData.description],
        function(err) {
          if (err) return callback(err);

          const surveyId = this.lastID;
          const stmt = db.prepare('INSERT INTO survey_items (survey_id, question, answer) VALUES (?, ?, ?)');

          surveyData.items.forEach(item => {
            stmt.run(surveyId, item.question, item.answer);
          });

          stmt.finalize();
          callback(null, surveyId);
        }
      );
    });
  },

  getAllSurveys: (callback) => {
    db.all(
      `SELECT s.id, s.title, s.description, s.created_at,
              json_group_array(json_object('question', si.question, 'answer', si.answer)) as items
       FROM surveys s
       LEFT JOIN survey_items si ON s.id = si.survey_id
       GROUP BY s.id`,
      [],
      (err, rows) => {
        if (err) return callback(err);

        const surveys = rows.map(row => ({
          ...row,
          items: JSON.parse(row.items || '[]')
        }));

        callback(null, surveys);
      }
    );
  }
};
```

