### 2. Local Storage Service

```javascript
// storageService.js
import { Survey } from './surveyModel';

const STORAGE_KEY = 'fieldSurveyData';

export const saveSurveyLocally = async (survey) => {
  try {
    const existingData = await getLocalSurveys();
    const updatedData = [...existingData.filter(s => s.id !== survey.id), survey];
    await localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedData));
    return survey;
  } catch (error) {
    console.error('Error saving survey locally:', error);
    throw error;
  }
};

export const getLocalSurveys = async () => {
  try {
    const data = await localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Error getting local surveys:', error);
    return [];
  }
};

export const getLocalSurveyById = async (id) => {
  const surveys = await getLocalSurveys();
  return surveys.find(survey => survey.id === id);
};

export const deleteLocalSurvey = async (id) => {
  const surveys = await getLocalSurveys();
  const updatedSurveys = surveys.filter(survey => survey.id !== id);
  await localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedSurveys));
};
```

### 3. Sync Service

```javascript
// syncService.js
import { getLocalSurveys, saveSurveyLocally } from './storageService';

const API_BASE_URL = 'https://your-api-endpoint.com/api';

export const syncData = async () => {
  if (!navigator.onLine) {
    console.log('Offline - sync deferred');
    return;
  }

  try {
    const localSurveys = await getLocalSurveys();
    const unsyncedSurveys = localSurveys.filter(survey => !survey.isSynced);

    if (unsyncedSurveys.length === 0) {
      console.log('No unsynced data to sync');
      return;
    }

    console.log(`Syncing ${unsyncedSurveys.length} surveys...`);

    for (const survey of unsyncedSurveys) {
      try {
        const response = await fetch(`${API_BASE_URL}/surveys`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(survey),
        });

        if (response.ok) {
          const syncedSurvey = await response.json();
          // Mark as synced locally
          survey.isSynced = true;
          await saveSurveyLocally(survey);
          console.log(`Survey ${survey.id} synced successfully`);
        } else {
          console.error(`Failed to sync survey ${survey.id}:`, await response.text());
        }
      } catch (error) {
        console.error(`Error syncing survey ${survey.id}:`, error);
      }
    }
  } catch (error) {
    console.error('Error during sync:', error);
  }
};

// Set up periodic sync checks
export const setupSyncListener = () => {
  // Initial sync when app loads
  syncData();

  // Set up interval for periodic syncs
  const syncInterval = setInterval(syncData, 30000); // Every 30 seconds

  // Listen for online status changes
  window.addEventListener('online', syncData);

  return () => {
    clearInterval(syncInterval);
    window.removeEventListener('online', syncData);
  };
};
```

