// App.js
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet, Alert } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

const App = () => {
  const [surveys, setSurveys] = useState([]);
  const [currentSurvey, setCurrentSurvey] = useState({
    id: Date.now().toString(),
    location: '',
    notes: '',
    timestamp: new Date().toISOString(),
    status: 'pending'
  });
  const [isConnected, setIsConnected] = useState(false);

  // Load surveys from local storage
  useEffect(() => {
    loadSurveys();
  }, []);

  // Monitor network connectivity
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const loadSurveys = async () => {
    try {
      const storedSurveys = await AsyncStorage.getItem('surveys');
      if (storedSurveys) {
        setSurveys(JSON.parse(storedSurveys));
      }
    } catch (error) {
      console.error('Error loading surveys:', error);
    }
  };

  const saveSurvey = async (survey) => {
    try {
      const updatedSurveys = [...surveys, survey];
      await AsyncStorage.setItem('surveys', JSON.stringify(updatedSurveys));
      setSurveys(updatedSurveys);
      setCurrentSurvey({
        id: Date.now().toString(),
        location: '',
        notes: '',
        timestamp: new Date().toISOString(),
        status: 'pending'
      });
      Alert.alert('Success', 'Survey saved locally');
    } catch (error) {
      console.error('Error saving survey:', error);
    }
  };

  const syncSurveys = async () => {
    try {
      const pendingSurveys = surveys.filter(survey => survey.status === 'pending');

      if (pendingSurveys.length > 0) {
        // In a real app, you would send to your backend API
        console.log('Syncing surveys:', pendingSurveys);

        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Update local storage with synced surveys
        const updatedSurveys = surveys.map(survey =>
          pendingSurveys.some(p => p.id === survey.id)
            ? { ...survey, status: 'synced' }
            : survey
        );

        await AsyncStorage.setItem('surveys', JSON.stringify(updatedSurveys));
        setSurveys(updatedSurveys);
        Alert.alert('Success', 'Surveys synced successfully');
      }
    } catch (error) {
      console.error('Error syncing surveys:', error);
      Alert.alert('Error', 'Failed to sync surveys');
    }
  };

  const handleSubmit = () => {
    if (!currentSurvey.location.trim()) {
      Alert.alert('Error', 'Please enter a location');
      return;
    }

    saveSurvey(currentSurvey);
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey App</Text>
      <Text style={styles.status}>
        Status: {isConnected ? 'Online' : 'Offline'}
      </Text>

      <View style={styles.form}>
        <TextInput
          style={styles.input}
          placeholder="Location"
          value={currentSurvey.location}
          onChangeText={(text) => setCurrentSurvey({...currentSurvey, location: text})}
        />
        <TextInput
          style={[styles.input, styles.textArea]}
          placeholder="Notes"
          multiline
          numberOfLines={4}
          value={currentSurvey.notes}
          onChangeText={(text) => setCurrentSurvey({...currentSurvey, notes: text})}
        />
        <Button
          title="Save Survey"
          onPress={handleSubmit}
          disabled={!isConnected && surveys.some(s => s.status === 'pending')}
        />
      </View>

      <Text style={styles.sectionTitle}>Saved Surveys</Text>
      <FlatList
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({item}) => (
          <View style={styles.surveyItem}>
            <Text>Location: {item.location}</Text>
            <Text>Notes: {item.notes}</Text>
            <Text>Status: {item.status}</Text>
            <Text>Date: {new Date(item.timestamp).toLocaleString()}</Text>
          </View>
        )}
      />
    </View>
  );
};

