// server.js
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const PORT = 3000;

// In-memory database for demonstration
let surveys = [];

app.use(cors());
app.use(bodyParser.json());

// Endpoint to receive surveys
app.post('/api/surveys', (req, res) => {
  const surveyData = req.body;

  if (!surveyData || !Array.isArray(surveyData)) {
    return res.status(400).json({ error: 'Invalid survey data' });
  }

  // Process each survey
  const processedSurveys = surveyData.map(survey => ({
    ...survey,
    status: 'synced',
    syncedAt: new Date().toISOString()
  }));

  // Add to our "database"
  surveys.push(...processedSurveys);

  console.log(`Received ${processedSurveys.length} surveys`);

  res.json({
    success: true,
    message: `${processedSurveys.length} surveys processed successfully`,
    syncedCount: processedSurveys.length
  });
});

// Endpoint to get all surveys (for verification)
app.get('/api/surveys', (req, res) => {
  res.json(surveys);
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
