```javascript
import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase(
  { name: 'survey.db', location: 'default' },
  () => { console.log('Database opened'); },
  error => { console.error('Error opening database', error); }
);

export const initDatabase = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS surveys (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          user_id TEXT,
          location TEXT,
          timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
          data TEXT,
          is_synced INTEGER DEFAULT 0
        );`,
        [],
        () => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};

export const saveSurveyOffline = (userId, location, data) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (user_id, location, data) VALUES (?, ?, ?)',
        [userId, location, JSON.stringify(data)],
        (_, result) => resolve(result.insertId),
        (_, error) => reject(error)
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE is_synced = 0',
        [],
        (_, { rows }) => resolve(rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const markSurveyAsSynced = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET is_synced = 1 WHERE id = ?',
        [id],
        () => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};
```

### 3. Sync Service (services/sync.js)

```javascript
import NetInfo from '@react-native-community/netinfo';
import { getUnsyncedSurveys, markSurveyAsSynced } from './database';
import axios from 'axios';

const API_BASE_URL = 'http://your-server-address/api';

export const syncData = async () => {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return false;

  try {
    const unsyncedSurveys = await getUnsyncedSurveys();

    for (const survey of unsyncedSurveys) {
      await axios.post(`${API_BASE_URL}/surveys`, {
        userId: survey.user_id,
        location: survey.location,
        data: JSON.parse(survey.data),
        timestamp: survey.timestamp
      });

      await markSurveyAsSynced(survey.id);
    }

    return true;
  } catch (error) {
    console.error('Sync error:', error);
    return false;
  }
};

// Set up periodic sync
export const setupSync = () => {
  // Sync immediately
  syncData();

  // Set up interval for periodic sync (e.g., every 5 minutes)
  const intervalId = setInterval(syncData, 5 * 60 * 1000);

  // Listen for network changes
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncData();
    }
  });

  return () => {
    clearInterval(intervalId);
    unsubscribe();
  };
};
```

