```typescript
// src/hooks/useOfflineData.ts
import { useState, useEffect, useCallback } from 'react';

interface SurveyData {
  id: string;
  location: string;
  notes: string;
  timestamp: string;
  status: 'pending' | 'synced';
}

export const useOfflineData = () => {
  const [surveys, setSurveys] = useState<SurveyData[]>([]);

  // Load data from IndexedDB when component mounts
  useEffect(() => {
    const loadData = async () => {
      const db = await openDatabase();
      const storedSurveys = await getAllSurveys(db);
      setSurveys(storedSurveys);
    };

    loadData();
  }, []);

  // Add a new survey to local storage and IndexedDB
  const addSurvey = useCallback(async (survey: SurveyData) => {
    const db = await openDatabase();
    await addSurveyToDB(db, survey);
    setSurveys(prev => [...prev, survey]);
  }, []);

  // Sync pending surveys with the server when online
  const syncData = useCallback(async () => {
    const db = await openDatabase();
    const pendingSurveys = surveys.filter(s => s.status === 'pending');

    if (pendingSurveys.length === 0) return;

    try {
      // Simulate API call to sync data
      const response = await fetch('/api/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pendingSurveys),
      });

      if (response.ok) {
        // Update status to 'synced' in IndexedDB
        await updateSurveyStatuses(db, pendingSurveys.map(s => s.id), 'synced');

        // Update local state
        setSurveys(prev =>
          prev.map(s =>
            pendingSurveys.some(ps => ps.id === s.id)
              ? { ...s, status: 'synced' }
              : s
          )
        );
      }
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }, [surveys]);

  return { surveys, addSurvey, syncData };
};

// IndexedDB helper functions
const openDatabase = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('SurveyDB', 1);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains('surveys')) {
        db.createObjectStore('surveys', { keyPath: 'id' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const getAllSurveys = (db: IDBDatabase): Promise<SurveyData[]> => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('surveys', 'readonly');
    const store = transaction.objectStore('surveys');
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const addSurveyToDB = (db: IDBDatabase, survey: SurveyData): Promise<void> => {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('surveys', 'readwrite');
    const store = transaction.objectStore('surveys');
    const request = store.add(survey);

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

const updateSurveyStatuses = (
  db: IDBDatabase,
  ids: string[],
  status: 'pending' | 'synced'
): Promise<void> => {
  return new Promise(async (resolve, reject) => {
    try {
      const transaction = db.transaction('surveys', 'readwrite');
      const store = transaction.objectStore('surveys');

      for (const id of ids) {
        const request = store.get(id);
        request.onsuccess = () => {
          const survey = request.result;
          if (survey) {
            survey.status = status;
            store.put(survey);
          }
        };
      }

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    } catch (error) {
      reject(error);
    }
  });
};
