```javascript
// public/sw.js
const CACHE_NAME = 'survey-app-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
  // Add other assets you want to cache
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        // Clone the request
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDatabase();
  const pendingSurveys = await getPendingSurveys(db);

  if (pendingSurveys.length === 0) return;

  try {
    const response = await fetch('/api/sync', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      await updateSurveyStatuses(db, pendingSurveys.map(s => s.id), 'synced');
    }
  } catch (error) {
    console.error('Background sync failed:', error);
  }
}

// Helper functions for IndexedDB in service worker
function openDatabase() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('SurveyDB', 1);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('surveys')) {
        db.createObjectStore('surveys', { keyPath: 'id' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function getPendingSurveys(db) {
  return new Promise((resolve, reject) => {
    const transaction = db.transaction('surveys', 'readonly');
    const store = transaction.objectStore('surveys');
    const request = store.getAll();

    request.onsuccess = () => {
      const pending = request.result.filter(s => s.status === 'pending');
      resolve(pending);
    };
    request.onerror = () => reject(request.error);
  });
}

function updateSurveyStatuses(db, ids, status) {
  return new Promise(async (resolve, reject) => {
    try {
      const transaction = db.transaction('surveys', 'readwrite');
      const store = transaction.objectStore('surveys');

      for (const id of ids) {
        const request = store.get(id);
        request.onsuccess = () => {
          const survey = request.result;
          if (survey) {
            survey.status = status;
            store.put(survey);
          }
        };
      }

      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    } catch (error) {
      reject(error);
    }
  });
}
