```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const mongoose = require('mongoose');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(bodyParser.json());

// Database connection
mongoose.connect('mongodb://localhost:27017/fieldSurveyDB', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Survey model
const Survey = mongoose.model('Survey', {
  id: String,
  location: String,
  notes: String,
  timestamp: String,
  status: String,
});

// Sync endpoint
app.post('/sync', async (req, res) => {
  try {
    const { surveys } = req.body;

    if (!surveys || !Array.isArray(surveys)) {
      return res.status(400).json({ error: 'Invalid surveys data' });
    }

    // Process each survey
    const results = await Promise.all(
      surveys.map(async (survey) => {
        try {
          // Check if survey already exists
          const existingSurvey = await Survey.findOne({ id: survey.id });

          if (existingSurvey) {
            // Update existing survey
            await Survey.updateOne({ id: survey.id }, {
              location: survey.location,
              notes: survey.notes,
              timestamp: survey.timestamp,
              status: 'synced'
            });
            return { id: survey.id, status: 'updated' };
          } else {
            // Create new survey
            const newSurvey = new Survey({
              id: survey.id,
              location: survey.location,
              notes: survey.notes,
              timestamp: survey.timestamp,
              status: 'synced'
            });
            await newSurvey.save();
            return { id: survey.id, status: 'created' };
          }
        } catch (error) {
          console.error(`Error processing survey ${survey.id}:`, error);
          return { id: survey.id, status: 'error', error: error.message };
        }
      })
    );

    res.json({ success: true, results });
  } catch (error) {
    console.error('Sync error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
