```typescript
import { Survey, SurveyData } from '../types/survey';
import { loadFromLocalStorage, saveToLocalStorage } from './localStorageService';
import { syncSurveys } from './apiService';

export const syncData = async (): Promise<void> => {
  const { surveys } = loadFromLocalStorage();
  const pendingSurveys = surveys.filter(survey => survey.status === 'pending');

  if (pendingSurveys.length === 0) return;

  try {
    const syncedSurveys = await syncSurveys(pendingSurveys);

    // Update local storage with synced status
    const updatedSurveys = surveys.map(localSurvey => {
      const syncedSurvey = syncedSurveys.find(s => s.id === localSurvey.id);
      return syncedSurvey ? { ...localSurvey, status: 'synced' } : localSurvey;
    });

    saveToLocalStorage({
      surveys: updatedSurveys,
      lastSync: new Date().toISOString()
    });

    console.log('Sync completed successfully');
  } catch (error) {
    console.error('Sync failed:', error);

    // Mark failed surveys
    const updatedSurveys = surveys.map(survey =>
      pendingSurveys.some(p => p.id === survey.id)
        ? { ...survey, status: 'failed' }
        : survey
    );

    saveToLocalStorage({
      surveys: updatedSurveys,
      lastSync: null
    });
  }
};

// Check network status and sync if online
export const checkAndSync = async (): Promise<void> => {
  if (navigator.onLine) {
    await syncData();
  }
};

// Set up periodic sync checks
export const setupSyncInterval = (interval: number = 300000): void => {
  setInterval(checkAndSync, interval);
};
