          reader.onload = (event) => resolve(event.target?.result as string);
          reader.readAsDataURL(file);
        });
      });

      Promise.all(readers).then(images => {
        setImages(prev => [...prev, ...images]);
      });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!title || !location) {
      alert('Please provide a title and location');
      return;
    }

    const newSurvey: Survey = {
      id: Date.now().toString(),
      title,
      location,
      notes,
      timestamp: new Date().toISOString(),
      status: 'pending',
      images
    };

    const { surveys, lastSync } = loadFromLocalStorage();
    saveToLocalStorage({
      surveys: [...surveys, newSurvey],
      lastSync
    });

    // Reset form
    setTitle('');
    setNotes('');
    setImages([]);
    alert('Survey saved locally. It will sync when you reconnect.');
  };

  return (
    <form onSubmit={handleSubmit} className="survey-form">
      <h2>New Survey</h2>

      <div className="form-group">
        <label>Title:</label>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
      </div>

      <div className="form-group">
        <label>Location:</label>
        <button type="button" onClick={getCurrentLocation}>
          Get Current Location
        </button>
        {location && (
          <p>Lat: {location.latitude}, Long: {location.longitude}</p>
        )}
      </div>

      <div className="form-group">
        <label>Notes:</label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
      </div>

      <div className="form-group">
