```typescript
import React, { useEffect, useState } from 'react';
import { loadFromLocalStorage } from '../services/localStorageService';
import { checkAndSync, setupSyncInterval } from '../services/syncService';

const SyncStatus: React.FC = () => {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [pendingCount, setPendingCount] = useState(0);

  useEffect(() => {
    // Set up network status listener
    const handleOnline = () => {
      setIsOnline(true);
      checkAndSync();
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Set up periodic sync checks
    setupSyncInterval();

    // Initial sync check
    checkAndSync();

    // Update status from local storage
    const updateStatus = () => {
      const { surveys, lastSync } = loadFromLocalStorage();
      setLastSync(lastSync);
      setPendingCount(surveys.filter(s => s.status === 'pending').length);
    };

    updateStatus();

    // Set up interval to check local storage changes
    const interval = setInterval(updateStatus, 5000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(interval);
    };
  }, []);

  return (
    <div className={`sync-status ${isOnline ? 'online' : 'offline'}`}>
      <p>Status: {isOnline ? 'Online' : 'Offline'}</p>
      {lastSync && (
        <p>Last sync: {new Date(lastSync).toLocaleString()}</p>
      )}
      {pendingCount > 0 && (
        <p>Pending surveys: {pendingCount}</p>
      )}
    </div>
  );
};

export default SyncStatus;
