```javascript
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory database (replace with real database in production)
let surveys = [];

// Sync endpoint
app.post('/api/surveys/sync', (req, res) => {
  const { surveys: incomingSurveys } = req.body;

  if (!incomingSurveys || !Array.isArray(incomingSurveys)) {
    return res.status(400).json({ error: 'Invalid survey data' });
  }

  // Process each survey
  const processedSurveys = incomingSurveys.map(survey => {
    // Assign a new ID if not present (for new surveys)
    const surveyId = survey.id || uuidv4();

    // Here you would typically save to your database
    // For this example, we'll just add to our in-memory array
    const existingIndex = surveys.findIndex(s => s.id === surveyId);

    if (existingIndex >= 0) {
      // Update existing survey
      surveys[existingIndex] = { ...survey, id: surveyId };
    } else {
      // Add new survey
      surveys.push({ ...survey, id: surveyId });
    }

    return { id: surveyId, status: 'synced' };
  });

  res.json(processedSurveys);
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
