## Network Layer

```typescript
// api.ts
const API_BASE_URL = 'https://api.yourfieldsurveyapp.com';

export const syncSurveys = async (surveys: Survey[]): Promise<{ success: boolean; syncedIds: string[] }> => {
  try {
    const response = await fetch(`${API_BASE_URL}/surveys/sync`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(surveys),
    });

    if (!response.ok) {
      throw new Error('Sync failed');
    }

    const result = await response.json();
    return {
      success: true,
      syncedIds: result.syncedIds || surveys.map(s => s.id),
    };
  } catch (error) {
    console.error('Sync error:', error);
    return {
      success: false,
      syncedIds: [],
    };
  }
};

export const checkConnectivity = async (): Promise<boolean> => {
  try {
    // Simple connectivity check
    const response = await fetch(`${API_BASE_URL}/ping`, { method: 'HEAD', mode: 'no-cors' });
    return response.ok || response.type === 'opaque';
  } catch {
    return false;
  }
};
