## Sync Manager

```typescript
// syncManager.ts
import { getUnsyncedSurveys, markSurveyAsSynced } from './db';
import { syncSurveys, checkConnectivity } from './api';

let syncInterval: NodeJS.Timeout | null = null;

export const startSyncProcess = () => {
  // Check connectivity every 30 seconds
  syncInterval = setInterval(async () => {
    const isOnline = await checkConnectivity();

    if (isOnline) {
      const unsyncedSurveys = await getUnsyncedSurveys();

      if (unsyncedSurveys.length > 0) {
        const result = await syncSurveys(unsyncedSurveys);

        if (result.success) {
          // Mark synced surveys as synced
          for (const id of result.syncedIds) {
            await markSurveyAsSynced(id);
          }

          console.log(`Synced ${result.syncedIds.length} surveys`);
        }
      }
    }
  }, 30000);
};

export const stopSyncProcess = () => {
  if (syncInterval) {
    clearInterval(syncInterval);
    syncInterval = null;
  }
};
