import Dexie, { Table } from 'dexie';

export interface Survey {
  id?: number;
  title: string;
  location: string;
  date: string;
  notes: string;
  status: 'draft' | 'submitted';
  createdAt: Date;
  updatedAt: Date;
}

export class SurveyDB extends Dexie {
  surveys!: Table<Survey>;

  constructor() {
    super('FieldSurveyDB');
    this.version(1).stores({
      surveys: '++id, title, location, date, status, createdAt, updatedAt'
    });
  }

  async addSurvey(survey: Omit<Survey, 'id'>): Promise<number> {
    return this.surveys.add({
      ...survey,
      createdAt: new Date(),
      updatedAt: new Date()
    });
  }

  async updateSurvey(id: number, changes: Partial<Survey>): Promise<number> {
    return this.surveys.update(id, {
      ...changes,
      updatedAt: new Date()
    });
  }

  async getAllSurveys(): Promise<Survey[]> {
    return this.surveys.toArray();
  }

  async getPendingSurveys(): Promise<Survey[]> {
    return this.surveys.where('status').equals('draft').toArray();
  }
}

export const db = new SurveyDB();
