// src/services/syncService.ts
import { db, Survey } from '../db';

export const syncData = async (): Promise<void> => {
  if (!navigator.onLine) {
    console.log('No internet connection, skipping sync');
    return;
  }

  try {
    const pendingSurveys = await db.getPendingSurveys();

    if (pendingSurveys.length === 0) {
      console.log('No pending surveys to sync');
      return;
    }

    // Simulate API call to backend
    const response = await fetch('https://your-api-endpoint.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      // Mark surveys as submitted
      const updatedSurveys = pendingSurveys.map(survey => ({
        ...survey,
        status: 'submitted' as const
      }));

      await db.surveys.bulkPut(updatedSurveys);
      console.log('Successfully synced surveys');
    } else {
      console.error('Failed to sync surveys');
    }
  } catch (error) {
    console.error('Sync error:', error);
  }
};

// Listen for online event to trigger sync
window.addEventListener('online', syncData);
