## JavaScript (app.js)

```javascript
// Database setup
let db;
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

// Initialize the database
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(survey) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const request = store.add({
            ...survey,
            timestamp: new Date().toISOString(),
            synced: false
        });

        request.onsuccess = () => resolve();
        request.onerror = (event) => reject(event.target.error);
    });
}

// Get all unsynced surveys
function getUnsyncedSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const index = store.index('timestamp');

        const request = index.getAll();

        request.onsuccess = (event) => {
            const unsynced = event.target.result.filter(survey => !survey.synced);
            resolve(unsynced);
        };
        request.onerror = (event) => reject(event.target.error);
    });
}

// Mark surveys as synced
function markAsSynced(ids) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const requests = ids.map(id => {
            return new Promise((resolve, reject) => {
                const getRequest = store.get(id);

                getRequest.onsuccess = () => {
                    const survey = getRequest.result;
                    survey.synced = true;

                    const updateRequest = store.put(survey);
                    updateRequest.onsuccess = resolve;
                    updateRequest.onerror = reject;
                };
                getRequest.onerror = reject;
            });
        });

        Promise.all(requests).then(resolve).catch(reject);
    });
}

// Simulate syncing with server
async function syncSurveys() {
    if (!navigator.onLine) {
        updateSyncStatus('offline');
        return;
    }

    updateSyncStatus('syncing');

    try {
        const unsynced = await getUnsyncedSurveys();

        if (unsynced.length === 0) {
            updateSyncStatus('online');
            return;
        }

        // Simulate API call to server
        console.log('Syncing surveys:', unsynced);

        // In a real app, you would send to your server here
        // For demo, we'll just mark as synced after a delay
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Mark as synced in DB
        const ids = unsynced.map(survey => survey.id);
        await markAsSynced(ids);

        updateSyncStatus('online');
        updatePendingSurveysDisplay();
    } catch (error) {
        console.error('Sync error:', error);
        updateSyncStatus('error');
    }
}

// Update UI with sync status
function updateSyncStatus(status) {
    const statusElement = document.getElementById('syncStatus');
    statusElement.className = 'sync-status ' + status;

    switch(status) {
        case 'online':
            statusElement.textContent = 'Connected - All surveys synced';
            break;
        case 'offline':
            statusElement.textContent = 'Offline - Surveys will sync when reconnected';
            break;
        case 'syncing':
            statusElement.textContent = 'Syncing surveys with server...';
            break;
        case 'error':
            statusElement.textContent = 'Error syncing - Retrying...';
            break;
    }
}

// Update pending surveys display
async function updatePendingSurveysDisplay() {
    const container = document.getElementById('pendingSurveys');
    const unsynced = await getUnsyncedSurveys();

    if (unsynced.length === 0) {
        container.innerHTML = '';
        return;
    }

    let html = '<h2>Pending Surveys</h2><ul>';
    unsynced.forEach(survey => {
        html += `<li>
            <strong>${survey.location}</strong> - ${survey.species} (${survey.count})
            <small>${new Date(survey.timestamp).toLocaleString()}</small>
        </li>`;
    });
    html += '</ul>';

    container.innerHTML = html;
}

// Initialize the app
async function initApp() {
    try {
        await initDB();
        updateSyncStatus(navigator.onLine ? 'online' : 'offline');
        updatePendingSurveysDisplay();

        // Set up form submission
        document.getElementById('surveyForm').addEventListener('submit', async (e) => {
            e.preventDefault();

            const survey = {
                location: document.getElementById('location').value,
                species: document.getElementById('species').value,
                count: parseInt(document.getElementById('count').value),
                notes: document.getElementById('notes').value
            };

            await saveSurvey(survey);
            e.target.reset();
            updatePendingSurveysDisplay();

            // Try to sync immediately if online
            if (navigator.onLine) {
                syncSurveys();
            }
        });

        // Set up online/offline event listeners
        window.addEventListener('online', () => {
            updateSyncStatus('online');
            syncSurveys();
        });

        window.addEventListener('offline', () => {
            updateSyncStatus('offline');
        });

        // Periodically check for sync (every 30 seconds)
        setInterval(() => {
            if (navigator.onLine) {
                syncSurveys();
            }
        }, 30000);

    } catch (error) {
        console.error('App initialization failed:', error);
    }
}

// Start the app
initApp();
