```javascript
// Database setup
let db;
const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';
const SYNC_INTERVAL = 30000; // 30 seconds

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    initDB();
    setupEventListeners();
    updateConnectionStatus();
    setInterval(checkForSync, SYNC_INTERVAL);
});

// Initialize IndexedDB
function initDB() {
    const request = indexedDB.open(DB_NAME, 1);

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        loadSavedSurveys();
    };

    request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        }
    };
}

// Setup event listeners
function setupEventListeners() {
    document.getElementById('save-button').addEventListener('click', saveSurvey);
    document.getElementById('sync-button').addEventListener('click', syncSurveys);
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);
}

// Save survey to IndexedDB
function saveSurvey() {
    const location = document.getElementById('location').value;
    const observation = document.getElementById('observation').value;
    const date = document.getElementById('date').value;

    if (!location || !observation || !date) {
        alert('Please fill in all fields');
        return;
    }

    const survey = {
        location,
        observation,
        date,
        timestamp: new Date().toISOString(),
        synced: false
    };

    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => {
        alert('Survey saved locally');
        clearForm();
        loadSavedSurveys();
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
    };
}

// Clear the form
function clearForm() {
    document.getElementById('location').value = '';
    document.getElementById('observation').value = '';
    document.getElementById('date').value = '';
}

// Load saved surveys from IndexedDB
function loadSavedSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result;
        displaySurveys(surveys);
        updatePendingCount(surveys);
    };

    request.onerror = (event) => {
        console.error('Error loading surveys:', event.target.error);
    };
}

// Display surveys in the UI
function displaySurveys(surveys) {
    const surveyList = document.getElementById('surveys');
    surveyList.innerHTML = '';

    if (surveys.length === 0) {
        surveyList.innerHTML = '<li>No surveys saved yet</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <strong>${survey.location}</strong> - ${survey.date}
            <p>${survey.observation}</p>
            <small>${survey.synced ? 'Synced' : 'Pending sync'}</small>
        `;
        surveyList.appendChild(li);
    });
}

// Update the pending sync count
function updatePendingCount(surveys) {
    const pendingCount = surveys.filter(s => !s.synced).length;
    document.getElementById('pending-count').textContent = pendingCount;
    document.getElementById('sync-button').disabled = pendingCount === 0;
}

// Check connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.className = 'online';
        checkForSync();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.className = 'offline';
    }
}

// Check if we should sync
function checkForSync() {
    if (navigator.onLine) {
        syncSurveys();
    }
}

// Sync surveys to server (simulated)
function syncSurveys() {
    if (!navigator.onLine) {
        alert('You are offline. Surveys will sync when you reconnect.');
        return;
    }

    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result;
        const pendingSurveys = surveys.filter(s => !s.synced);

        if (pendingSurveys.length === 0) {
            alert('No surveys to sync');
            return;
        }

        // Simulate syncing to server
        console.log('Syncing surveys:', pendingSurveys);
        alert(`Syncing ${pendingSurveys.length} surveys...`);

        // Mark as synced in local DB
        pendingSurveys.forEach(survey => {
            survey.synced = true;
            store.put(survey);
        });

        // In a real app, you would make an actual API call here
