## 3. app.js
```javascript
// Database setup
const DB_NAME = 'SurveyAppDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;

// Initialize IndexedDB
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const request = store.add({
            ...surveyData,
            timestamp: new Date().toISOString(),
            synced: false
        });

        request.onsuccess = () => {
            resolve(request.result);
            displaySurveys();
            showSyncStatus('Survey saved locally. Will sync when online.', 'success');
        };

        request.onerror = (event) => {
            reject(event.target.error);
            showSyncStatus('Error saving survey locally', 'error');
        };
    });
}

// Get all surveys from IndexedDB
function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Update survey sync status
function updateSurveySyncStatus(id, synced) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.get(id);

        request.onsuccess = () => {
            const data = request.result;
            data.synced = synced;
            const updateRequest = store.put(data);

            updateRequest.onsuccess = () => resolve();
            updateRequest.onerror = (event) => reject(event.target.error);
        };

        request.onerror = (event) => reject(event.target.error);
    });
}

// Display surveys in the UI
async function displaySurveys() {
    const surveys = await getAllSurveys();
    const surveyList = document.getElementById('survey-list');

    surveyList.innerHTML = '';

    if (surveys.length === 0) {
        surveyList.innerHTML = '<li>No surveys submitted yet.</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <strong>${survey.location}</strong><br>
            ${survey.observation}<br>
            <small>${new Date(survey.timestamp).toLocaleString()}</small>
            ${survey.synced ? '<span class="synced">(Synced)</span>' : '<span class="not-synced">(Not synced)</span>'}
        `;
        surveyList.appendChild(li);
    });
}

// Sync data with server (simulated)
async function syncData() {
    if (!navigator.onLine) {
        showSyncStatus('No internet connection. Data will sync when online.', 'info');
        return;
    }

    try {
        const surveys = await getAllSurveys();
        const unsyncedSurveys = surveys.filter(survey => !survey.synced);

        if (unsyncedSurveys.length === 0) {
            showSyncStatus('All data is up to date.', 'success');
            return;
        }

        // Simulate API call to sync data
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Mark surveys as synced
        for (const survey of unsyncedSurveys) {
            await updateSurveySyncStatus(survey.id, true);
        }

        showSyncStatus(`Successfully synced ${unsyncedSurveys.length} surveys.`, 'success');
        displaySurveys();
    } catch (error) {
        console.error('Sync error:', error);
        showSyncStatus('Error syncing data. Will retry when online.', 'error');
    }
}

// Show sync status message
function showSyncStatus(message, type) {
    const syncStatus = document.getElementById('sync-status');
    syncStatus.textContent = message;
    syncStatus.className = type;
    syncStatus.style.display = 'block';

    // Hide after 5 seconds
    setTimeout(() => {
        syncStatus.style.display = 'none';
    }, 5000);
}

// Update connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.style.color = 'green';
        syncData();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.style.color = 'red';
    }
}

// Event listeners
document.addEventListener('DOMContentLoaded', async () => {
    try {
        await initDB();
        await displaySurveys();

        // Set up form submission
        const form = document.getElementById('survey-form');
        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            const location = document.getElementById('location').value;
            const observation = document.getElementById('observation').value;
            const photoInput = document.getElementById('photo');
            const photo = photoInput.files[0];

            // In a real app, you would handle the photo file properly
            const surveyData = {
                location,
                observation,
                photo: photo ? photo.name : null
            };

            await saveSurvey(surveyData);

            // Reset form
            form.reset();
        });

        // Set up connection status monitoring
        window.addEventListener('online', updateConnectionStatus);
        window.addEventListener('offline', updateConnectionStatus);

        // Initial connection status check
        updateConnectionStatus();

        // Register service worker
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.register('sw.js')
                .then(registration => {
                    console.log('ServiceWorker registration successful');
                })
                .catch(err => {
                    console.log('ServiceWorker registration failed: ', err);
                });
        }
    } catch (error) {
        console.error('Initialization error:', error);
    }
});
```

## 4. sw.js (Service Worker)
```javascript
const CACHE_NAME = 'survey-app-v1';
const urlsToCache = [
    '/',
    '/index.html',
    '/styles.css',
    '/app.js',
    '/manifest.json'
];

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then((cache) => {
                return cache.addAll(urlsToCache);
            })
    );
});

self.addEventListener('fetch', (event) => {
    event.respondWith(
        caches.match(event.request)
            .then((response) => {
                // Cache hit - return response
                if (response) {
                    return response;
                }

                // Clone the request
                const fetchRequest = event.request.clone();

                return fetch(fetchRequest).then(
                    (response) => {
                        // Check if we received a valid response
                        if (!response || response.status !== 200 || response.type !== 'basic') {
                            return response;
                        }

                        // Clone the response
                        const responseToCache = response.clone();

                        caches.open(CACHE_NAME)
                            .then((cache) => {
                                cache.put(event.request, responseToCache);
                            });

                        return response;
                    }
                );
            })
    );
});

self.addEventListener('activate', (event) => {
    const cacheWhitelist = [CACHE_NAME];

    event.waitUntil(
        caches.keys().then((cacheNames) => {
            return Promise.all(
                cacheNames.map((cacheName) => {
                    if (cacheWhitelist.indexOf(cacheName) === -1) {
                        return caches.delete(cacheName);
                    }
                })
            );
        })
    );
});
```

