```javascript
// Database setup
const DB_NAME = 'SurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = false;

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    // Check connection status
    updateConnectionStatus();
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);

    // Open database
    openDatabase();

    // Form submission
    document.getElementById('surveyForm').addEventListener('submit', handleFormSubmit);

    // Check for pending syncs periodically
    setInterval(checkForPendingSyncs, 10000);
});

// Open or create the IndexedDB database
function openDatabase() {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        console.log('Database opened successfully');
        loadPendingSurveys();
    };

    request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            store.createIndex('synced', 'synced', { unique: false });
        }
    };
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const surveyData = {
        location: document.getElementById('location').value,
        species: document.getElementById('species').value,
        count: document.getElementById('count').value,
        notes: document.getElementById('notes').value,
        timestamp: new Date().toISOString(),
        synced: false
    };

    saveSurvey(surveyData);
    document.getElementById('surveyForm').reset();
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const request = store.add(surveyData);

    request.onsuccess = () => {
        console.log('Survey saved locally');
        loadPendingSurveys();

        if (isOnline) {
            syncSurvey(request.result);
        }
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
    };
}

// Load pending surveys from IndexedDB
function loadPendingSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const index = store.index('synced');

    const request = index.getAll(false);

    request.onsuccess = (event) => {
        const pendingSurveys = event.target.result;
        updateSyncStatus(pendingSurveys.length);

        if (isOnline && pendingSurveys.length > 0) {
            pendingSurveys.forEach(survey => syncSurvey(survey.id));
        }
    };
}

// Update sync status display
function updateSyncStatus(pendingCount) {
    const syncStatus = document.getElementById('syncStatus');
    if (pendingCount > 0) {
        syncStatus.innerHTML = `<p>${pendingCount} survey(s) pending sync</p>`;
    } else {
        syncStatus.innerHTML = `<p>All surveys synced</p>`;
    }
}

// Sync a survey with the server (simulated)
function syncSurvey(id) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    const getRequest = store.get(id);

    getRequest.onsuccess = (event) => {
        const survey = event.target.result;
        if (!survey) return;

        // Simulate API call to sync with server
        console.log('Attempting to sync survey:', survey);

        // In a real app, you would use fetch() here
        // For this example, we'll just mark it as synced after a delay
        setTimeout(() => {
            survey.synced = true;
            const updateRequest = store.put(survey);

            updateRequest.onsuccess = () => {
                console.log('Survey synced successfully');
                loadPendingSurveys();
            };

            updateRequest.onerror = (event) => {
                console.error('Error updating synced status:', event.target.error);
            };
        }, 1000);
    };
}

// Check for pending syncs periodically
function checkForPendingSyncs() {
    if (isOnline) {
        loadPendingSurveys();
    }
}

// Update connection status
function updateConnectionStatus() {
    isOnline = navigator.onLine;
    const statusElement = document.getElementById('connectionStatus');

    if (isOnline) {
        statusElement.textContent = 'Online';
        statusElement.classList.add('connected');
        statusElement.classList.remove('offline');
        loadPendingSurveys(); // Try to sync when coming online
    } else {
        statusElement.textContent = 'Offline';
        statusElement.classList.add('offline');
        statusElement.classList.remove('connected');
    }
}
