// Database setup
let db;
const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';

// Initialize database
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject('Database error');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve();
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(survey) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const request = store.add(survey);

        request.onsuccess = () => {
            resolve();
        };

        request.onerror = (event) => {
            console.error('Error saving survey:', event.target.error);
            reject('Error saving survey');
        };
    });
}

// Get all surveys from IndexedDB
function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = (event) => {
            resolve(event.target.result);
        };

        request.onerror = (event) => {
            console.error('Error getting surveys:', event.target.error);
            reject('Error getting surveys');
        };
    });
}

// Clear all surveys from IndexedDB
function clearSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.clear();

        request.onsuccess = () => {
            resolve();
        };

        request.onerror = (event) => {
            console.error('Error clearing surveys:', event.target.error);
            reject('Error clearing surveys');
        };
    });
}

// Display saved surveys
async function displaySurveys() {
    const surveys = await getAllSurveys();
    const container = document.getElementById('savedSurveys');

    if (surveys.length === 0) {
        container.innerHTML = '<h2>Saved Surveys</h2><p>No surveys saved yet.</p>';
        return;
    }

    let html = '<h2>Saved Surveys</h2><ul>';
    surveys.forEach(survey => {
        html += `
            <li>
                <strong>${survey.location}</strong> - ${survey.species} (${survey.count})
                <p>${survey.notes || 'No notes'}</p>
            </li>
        `;
    });
    html += '</ul>';

    if (navigator.onLine) {
        html += '<button id="syncButton">Sync with Server</button>';
    }

    container.innerHTML = html;

    // Add sync button event listener if online
    if (navigator.onLine) {
        document.getElementById('syncButton').addEventListener('click', syncData);
    }
}

// Sync data with server (simulated)
async function syncData() {
    const syncButton = document.getElementById('syncButton');
    syncButton.disabled = true;
    syncButton.textContent = 'Syncing...';

    try {
        const surveys = await getAllSurveys();

        // Simulate API call to server
        console.log('Syncing data:', surveys);

        // In a real app, you would use fetch() to send data to your server
        // await fetch('/api/surveys', {
        //     method: 'POST',
        //     headers: {
        //         'Content-Type': 'application/json',
        //     },
        //     body: JSON.stringify(surveys),
        // });

        // Clear local data after successful sync
        await clearSurveys();
        displaySurveys();

        alert('Data synced successfully!');
    } catch (error) {
        console.error('Sync error:', error);
        alert('Error syncing data. Please try again.');
    } finally {
        syncButton.disabled = false;
        syncButton.textContent = 'Sync with Server';
    }
}

// Update connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('sync-status');

    if (navigator.onLine) {
        statusElement.textContent = 'Status: Online (Ready to sync)';
        statusElement.className = 'online';
    } else {
        statusElement.textContent = 'Status: Offline (Data will sync when reconnected)';
        statusElement.className = 'offline';
    }

    // If we're online, show sync button if there are saved surveys
    if (navigator.onLine) {
        getAllSurveys().then(surveys => {
            if (surveys.length > 0) {
                displaySurveys();
            }
        });
    }
}

// Initialize the app
async function initApp() {
    await initDB();
    displaySurveys();

    // Set up event listeners
    document.getElementById('surveyForm').addEventListener('submit', async (e) => {
        e.preventDefault();

        const survey = {
            location: document.getElementById('location').value,
            species: document.getElementById('species').value,
            count: parseInt(document.getElementById('count').value),
            notes: document.getElementById('notes').value,
