// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
let db;

function openDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            reject('Error opening database');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains('surveys')) {
                const store = db.createObjectStore('surveys', { keyPath: 'id', autoIncrement: true });
                store.createIndex('synced', 'synced', { unique: false });
            }
        };
    });
}

// Form submission
document.getElementById('survey-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const location = document.getElementById('location').value;
    const observation = document.getElementById('observation').value;
    const photoInput = document.getElementById('photo');
    let photo = null;

    if (photoInput.files && photoInput.files[0]) {
        photo = await readFileAsDataURL(photoInput.files[0]);
    }

    const survey = {
        location,
        observation,
        photo,
        timestamp: new Date().toISOString(),
        synced: false
    };

    try {
        await saveSurvey(survey);
        document.getElementById('survey-form').reset();
        updateSurveyList();
        checkConnectionAndSync();
    } catch (error) {
        console.error('Error saving survey:', error);
    }
});

function readFileAsDataURL(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

async function saveSurvey(survey) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(['surveys'], 'readwrite');
        const store = transaction.objectStore('surveys');

        const request = store.add(survey);

        request.onsuccess = () => resolve();
        request.onerror = (event) => reject('Error saving survey');
    });
}

// Display saved surveys
async function updateSurveyList() {
    const surveys = await getAllSurveys();
    const list = document.getElementById('survey-list');
    list.innerHTML = '';

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <div>
                <strong>${survey.location}</strong> - ${new Date(survey.timestamp).toLocaleString()}
                <p>${survey.observation}</p>
            </div>
            <span class="${survey.synced ? 'synced' : 'not-synced'}">
                ${survey.synced ? '✓ Synced' : '✗ Not synced'}
            </span>
        `;
        list.appendChild(li);
    });
}

function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(['surveys'], 'readonly');
        const store = transaction.objectStore('surveys');
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject('Error getting surveys');
    });
}

// Connection and sync status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    const syncElement = document.getElementById('sync-status');

    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.style.color = '#27ae60';
        checkConnectionAndSync();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.style.color = '#e74c3c';
        syncElement.textContent = '';
    }
}

async function checkConnectionAndSync() {
    if (navigator.onLine) {
        const unsyncedSurveys = await getUnsyncedSurveys();
        if (unsyncedSurveys.length > 0) {
            document.getElementById('sync-status').textContent = 'Syncing...';
            await syncSurveys(unsyncedSurveys);
            updateSurveyList();
            document.getElementById('sync-status').textContent = 'Sync complete!';
        }
    }
}

function getUnsyncedSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(['surveys'], 'readonly');
        const store = transaction.objectStore('surveys');
        const index = store.index('synced');
        const request = index.getAll(false); // false means not synced

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject('Error getting unsynced surveys');
    });
}

async function syncSurveys(surveys) {
    // In a real app, this would send data to a server
    // For this demo, we'll just mark them as synced after a delay
    for (const survey of surveys) {
        await new Promise(resolve => setTimeout(resolve, 500)); // Simulate network delay
        await markAsSynced(survey.id);
    }
}

function markAsSynced(id) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(['surveys'], 'readwrite');
        const store = transaction.objectStore('surveys');

        const request = store.get(id);

        request.onsuccess = (event) => {
            const survey = event.target.result;
            survey.synced = true;

            const updateRequest = store.put(survey);
            updateRequest.onsuccess = () => resolve();
            updateRequest.onerror = () => reject('Error marking as synced');
        };

        request.onerror = () => reject('Error getting survey to mark as synced');
    });
}

// Initialize the app
async function init() {
    try {
        await openDB();
        updateSurveyList();
        updateConnectionStatus();

        // Check connection status periodically
