```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = navigator.onLine;

// Initialize the database
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const request = store.add({
            ...surveyData,
            timestamp: new Date().toISOString(),
            synced: false
        });

        request.onsuccess = () => {
            resolve(request.result);
            displaySavedSurveys();
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Get all surveys from IndexedDB
function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Display saved surveys
async function displaySavedSurveys() {
    const surveys = await getAllSurveys();
    const surveyList = document.getElementById('surveyList');

    if (surveys.length === 0) {
        surveyList.innerHTML = '<p>No surveys saved yet.</p>';
        return;
    }

    let html = '<ul>';
    surveys.forEach(survey => {
        html += `
            <li>
                <strong>${survey.location}</strong> - ${survey.species} (${survey.count})
                <small>${new Date(survey.timestamp).toLocaleString()}</small>
                ${survey.synced ? '<span style="color: green">✓ Synced</span>' : '<span style="color: red">✗ Not synced</span>'}
            </li>
        `;
    });
    html += '</ul>';
    surveyList.innerHTML = html;
}

// Sync data with server (simulated)
async function syncData() {
    if (!isOnline) return;

    const surveys = await getAllSurveys();
    const unsyncedSurveys = surveys.filter(survey => !survey.synced);

    if (unsyncedSurveys.length === 0) return;

    // Simulate API call
    console.log('Syncing data:', unsyncedSurveys);

    // In a real app, you would send to your server here
    // For this example, we'll just mark as synced
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);

    unsyncedSurveys.forEach(survey => {
        const updatedSurvey = { ...survey, synced: true };
        store.put(updatedSurvey);
    });

    displaySavedSurveys();
}

// Update connection status
function updateConnectionStatus() {
    isOnline = navigator.onLine;
    const statusElement = document.getElementById('syncStatus');

    if (isOnline) {
        statusElement.textContent = 'Online - Syncing data...';
        statusElement.className = 'sync-status online';
        syncData();
    } else {
        statusElement.textContent = 'Offline - Data will sync when reconnected';
        statusElement.className = 'sync-status offline';
    }
}

// Event listeners
document.addEventListener('DOMContentLoaded', async () => {
    await initDB();
    displaySavedSurveys();

    document.getElementById('saveSurvey').addEventListener('click', async () => {
        const location = document.getElementById('location').value;
        const species = document.getElementById('species').value;
        const count = document.getElementById('count').value;
        const notes = document.getElementById('notes').value;

        if (!location || !species || !count) {
            alert('Please fill in all required fields');
            return;
        }

        await saveSurvey({
            location,
            species,
            count: parseInt(count),
            notes
        });

        // Clear form
        document.getElementById('location').value = '';
        document.getElementById('species').value = '';
        document.getElementById('count').value = '';
        document.getElementById('notes').value = '';
    });

    // Set up online/offline event listeners
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);

    // Initial status check
    updateConnectionStatus();
});
