```javascript
// Database setup
const dbName = 'FieldSurveyDB';
const storeName = 'surveys';
let db;

function openDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(storeName)) {
                db.createObjectStore(storeName, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.add(surveyData);

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Get all surveys from IndexedDB
function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Delete survey from IndexedDB
function deleteSurvey(id) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.delete(id);

        request.onsuccess = () => resolve();
        request.onerror = (event) => reject(event.target.error);
    });
}

// Sync data to server (mock function)
async function syncData() {
    if (!navigator.onLine) return;

    try {
        const surveys = await getAllSurveys();
        if (surveys.length === 0) return;

        // Mock API call - in a real app, this would be your actual API endpoint
        const response = await fetch('https://api.example.com/surveys', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(surveys)
        });

        if (response.ok) {
            // Clear local data after successful sync
            const transaction = db.transaction([storeName], 'readwrite');
            const store = transaction.objectStore(storeName);
            store.clear();

            updateSyncStatus('synced');
            loadSurveys();
        } else {
            updateSyncStatus('error');
        }
    } catch (error) {
        console.error('Sync error:', error);
        updateSyncStatus('error');
    }
}

// Update UI with connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.className = 'online';
        syncData();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.className = 'offline';
    }
}

// Update UI with sync status
function updateSyncStatus(status) {
    const statusElement = document.getElementById('sync-status');
    if (status === 'syncing') {
        statusElement.textContent = 'Syncing...';
        statusElement.className = 'syncing';
    } else if (status === 'synced') {
        statusElement.textContent = 'Synced!';
        statusElement.className = 'synced';
    } else if (status === 'error') {
        statusElement.textContent = 'Sync failed';
        statusElement.className = 'error';
    } else {
        statusElement.textContent = '';
        statusElement.className = '';
    }
}

// Load surveys from IndexedDB and display them
async function loadSurveys() {
    const surveys = await getAllSurveys();
    const surveyList = document.getElementById('survey-list');
    surveyList.innerHTML = '';

    if (surveys.length === 0) {
        surveyList.innerHTML = '<li>No surveys saved yet</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <strong>${survey.location}</strong> - ${survey.species} (${survey.count})
            <button onclick="deleteSurveyAndRefresh(${survey.id})">Delete</button>
        `;
        surveyList.appendChild(li);
    });
}

// Delete survey and refresh list
async function deleteSurveyAndRefresh(id) {
    await deleteSurvey(id);
    loadSurveys();
}

// Initialize the app
async function init() {
    await openDB();
    loadSurveys();
    updateConnectionStatus();

    // Set up form submission
    document.getElementById('survey-form').addEventListener('submit', async (e) => {
        e.preventDefault();

        const surveyData = {
            location: document.getElementById('location').value,
            species: document.getElementById('species').value,
            count: document.getElementById('count').value,
            notes: document.getElementById('notes').value,
            timestamp: new Date().toISOString()
        };

        await saveSurvey(surveyData);
        e.target.reset();
        loadSurveys();

        if (navigator.onLine) {
            updateSyncStatus('syncing');
            syncData();
        }
    });

    // Listen for connection changes
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);
}

// Start the app
init();
