// Database setup
let db;
const DB_NAME = 'SurveyDB';
const STORE_NAME = 'surveys';

async function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connectionStatus');
    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.classList.add('connected');
        statusElement.classList.remove('disconnected');
    } else {
        statusElement.textContent = 'Offline';
        statusElement.classList.add('disconnected');
        statusElement.classList.remove('connected');
    }
}

// Save survey to IndexedDB
async function saveSurvey(surveyData) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(surveyData);

    return new Promise((resolve, reject) => {
        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Get all surveys from IndexedDB
async function getAllSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    return new Promise((resolve, reject) => {
        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Sync data to server (simulated)
async function syncData() {
    if (!navigator.onLine) {
        alert('You are offline. Data will sync automatically when you reconnect.');
        return;
    }

    const syncStatus = document.getElementById('syncStatus');
    syncStatus.textContent = 'Syncing...';

    try {
        const surveys = await getAllSurveys();
        const unsyncedSurveys = surveys.filter(survey => !survey.synced);

        if (unsyncedSurveys.length === 0) {
            syncStatus.textContent = 'All data is already synced';
            return;
        }

        // Simulate API call to server
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Mark surveys as synced
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        unsyncedSurveys.forEach(survey => {
            survey.synced = true;
            store.put(survey);
        });

        await new Promise((resolve, reject) => {
            transaction.oncomplete = resolve;
            transaction.onerror = reject;
        });

        syncStatus.textContent = `Successfully synced ${unsyncedSurveys.length} surveys`;
        displaySurveys();
    } catch (error) {
        console.error('Sync error:', error);
        syncStatus.textContent = 'Sync failed. Please try again.';
    }
}

// Display surveys in the UI
async function displaySurveys() {
    const surveyList = document.getElementById('surveyList');
    surveyList.innerHTML = '';

    const surveys = await getAllSurveys();

    if (surveys.length === 0) {
        surveyList.innerHTML = '<li>No surveys saved yet</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.className = `survey-item ${survey.synced ? 'synced' : ''}`;
        li.innerHTML = `
            <strong>Location:</strong> ${survey.location}<br>
            <strong>Observation:</strong> ${survey.observation}<br>
            <strong>Date:</strong> ${survey.date}
        `;
        surveyList.appendChild(li);
    });
}

// Event listeners
document.addEventListener('DOMContentLoaded', async () => {
    await initDB();
    displaySurveys();
    updateConnectionStatus();

    // Form submission
    document.getElementById('surveyForm').addEventListener('submit', async (e) => {
        e.preventDefault();

        const surveyData = {
            location: document.getElementById('location').value,
            observation: document.getElementById('observation').value,
            date: document.getElementById('date').value,
            synced: false,
            timestamp: new Date().toISOString()
        };

        try {
            await saveSurvey(surveyData);
            document.getElementById('surveyForm').reset();
            displaySurveys();

            if (navigator.onLine) {
                await syncData();
            } else {
                alert('Survey saved offline. It will sync when you reconnect.');
            }
        } catch (error) {
            console.error('Error saving survey:', error);
            alert('Error saving survey. Please try again.');
        }
    });

    // Sync button
    document.getElementById('syncBtn').addEventListener('click', syncData);

    // Connection status changes
    window.addEventListener('online', () => {
        updateConnectionStatus();
        syncData();
    });

    window.addEventListener('offline', updateConnectionStatus);
});

// Register service worker
if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        navigator.serviceWorker.register('service-worker.js')
            .then(registration => {
                console.log('ServiceWorker registration successful');
            })
            .catch(err => {
                console.log('ServiceWorker registration failed: ', err);
            });
    });
}
