// Database setup
const dbName = 'FieldSurveyDB';
const storeName = 'surveys';
let db;

function openDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(storeName)) {
                const store = db.createObjectStore(storeName, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);

        const request = store.add({
            ...surveyData,
            timestamp: new Date().toISOString(),
            synced: false
        });

        request.onsuccess = () => {
            resolve(request.result);
            updatePendingList();
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Get all unsynced surveys
function getUnsyncedSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const index = store.index('timestamp');

        const request = index.getAll();

        request.onsuccess = () => {
            const unsynced = request.result.filter(survey => !survey.synced);
            resolve(unsynced);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Mark surveys as synced
function markAsSynced(ids) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);

        const promises = ids.map(id => {
            return new Promise((resolve, reject) => {
                const request = store.get(id);
                request.onsuccess = () => {
                    const survey = request.result;
                    survey.synced = true;
                    const updateRequest = store.put(survey);
                    updateRequest.onsuccess = resolve;
                    updateRequest.onerror = reject;
                };
                request.onerror = reject;
            });
        });

        Promise.all(promises)
            .then(resolve)
            .catch(reject);
    });
}

