## app.js
```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
let db;

function openDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            reject('Error opening database');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains('surveys')) {
                db.createObjectStore('surveys', { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Form submission
document.getElementById('survey-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const location = document.getElementById('location').value;
    const observation = document.getElementById('observation').value;
    const photoInput = document.getElementById('photo');
    let photoData = null;

    if (photoInput.files.length > 0) {
        photoData = await readFileAsDataURL(photoInput.files[0]);
    }

    const surveyData = {
        location,
        observation,
        photo: photoData,
        timestamp: new Date().toISOString(),
        synced: false
    };

    try {
        await saveSurvey(surveyData);
        document.getElementById('survey-form').reset();
        updatePendingList();
        checkConnectionAndSync();
    } catch (error) {
        console.error('Error saving survey:', error);
    }
});

function readFileAsDataURL(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

function saveSurvey(survey) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(['surveys'], 'readwrite');
        const store = transaction.objectStore('surveys');
        const request = store.add(survey);

        request.onsuccess = () => resolve();
        request.onerror = (event) => reject(event.target.error);
    });
}

function updatePendingList() {
    const pendingList = document.getElementById('pending-list');
    pendingList.innerHTML = '';

    const transaction = db.transaction(['surveys'], 'readonly');
    const store = transaction.objectStore('surveys');
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result.filter(survey => !survey.synced);

        if (surveys.length === 0) {
            pendingList.innerHTML = '<li>No pending surveys</li>';
            return;
        }

        surveys.forEach(survey => {
            const li = document.createElement('li');
            li.textContent = `${survey.location} - ${new Date(survey.timestamp).toLocaleString()}`;
            pendingList.appendChild(li);
        });
    };
}

// Connection and sync logic
let isOnline = navigator.onLine;
const connectionStatus = document.getElementById('connection-status');
const syncStatus = document.getElementById('sync-status');

function updateConnectionStatus() {
    if (isOnline) {
        connectionStatus.textContent = 'Online';
        connectionStatus.className = 'online';
    } else {
        connectionStatus.textContent = 'Offline';
        connectionStatus.className = 'offline';
    }
}

function checkConnectionAndSync() {
    if (isOnline) {
        syncPendingSurveys();
    }
}

async function syncPendingSurveys() {
    if (!isOnline) return;

    syncStatus.textContent = 'Syncing...';
    syncStatus.className = 'syncing';

    try {
        const transaction = db.transaction(['surveys'], 'readwrite');
        const store = transaction.objectStore('surveys');
        const request = store.getAll();

        request.onsuccess = async (event) => {
            const surveys = event.target.result.filter(survey => !survey.synced);

            for (const survey of surveys) {
                // Simulate API call to server
                await new Promise(resolve => setTimeout(resolve, 500));

                // In a real app, you would send the data to your server here
                console.log('Syncing survey:', survey);

                // Mark as synced
                survey.synced = true;
                const updateRequest = store.put(survey);

                updateRequest.onsuccess = () => {
                    console.log('Survey marked as synced');
                };
            }

            syncStatus.textContent = 'All surveys synced!';
            syncStatus.className = 'synced';
            updatePendingList();
        };
    } catch (error) {
        console.error('Error syncing surveys:', error);
        syncStatus.textContent = 'Sync failed';
        syncStatus.className = 'error';
    }
}

// Event listeners
window.addEventListener('online', () => {
    isOnline = true;
    updateConnectionStatus();
    checkConnectionAndSync();
});

window.addEventListener('offline', () => {
    isOnline = false;
    updateConnectionStatus();
});

// Initialize
async function init() {
    try {
        await openDB();
        updateConnectionStatus();
        updatePendingList();
        checkConnectionAndSync();
    } catch (error) {
        console.error('Initialization error:', error);
    }
}

init();
