### 1. Database Service (`services/db.ts`)

```typescript
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: number;
    value: {
      id: number;
      title: string;
      description: string;
      location: string;
      timestamp: number;
      synced: boolean;
    };
    indexes: { 'by-timestamp': number };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export const initDB = async () => {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', {
          keyPath: 'id',
          autoIncrement: true,
        });
        store.createIndex('by-timestamp', 'timestamp');
      }
    },
  });
};

export const addSurvey = async (survey: Omit<Survey, 'id' | 'synced'>) => {
  const db = await initDB();
  const id = await db.add('surveys', {
    ...survey,
    timestamp: Date.now(),
    synced: false,
  });
  return id;
};

export const getAllSurveys = async () => {
  const db = await initDB();
  return db.getAll('surveys');
};

export const getUnsyncedSurveys = async () => {
  const db = await initDB();
  return db.getAllFromIndex('surveys', 'by-timestamp', IDBKeyRange.lowerBound(0));
};

export const markAsSynced = async (id: number) => {
  const db = await initDB();
  const tx = db.transaction('surveys', 'readwrite');
  const store = tx.objectStore('surveys');
  const survey = await store.get(id);
  if (survey) {
    survey.synced = true;
    await store.put(survey);
  }
  await tx.done;
};
```

### 2. Sync Service (`services/sync.ts`)

```typescript
import { getUnsyncedSurveys, markAsSynced } from './db';

const API_URL = 'https://api.example.com/surveys';

export const syncData = async () => {
  if (!navigator.onLine) {
    return false;
  }

  const unsyncedSurveys = await getUnsyncedSurveys();

  if (unsyncedSurveys.length === 0) {
    return true;
  }

  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(unsyncedSurveys),
    });

    if (response.ok) {
      // Mark all synced surveys as synced in local DB
      for (const survey of unsyncedSurveys) {
        await markAsSynced(survey.id);
      }
      return true;
    }
    return false;
  } catch (error) {
    console.error('Sync failed:', error);
    return false;
  }
};

// Set up periodic sync checks
export const setupSyncListener = () => {
  // Sync when coming back online
  window.addEventListener('online', syncData);

  // Periodic sync check every 5 minutes
  setInterval(() => {
    if (navigator.onLine) {
      syncData();
    }
  }, 5 * 60 * 1000);
};
```

