## JavaScript (app.js)

```javascript
// Database setup
let db;
const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';
const SYNC_INTERVAL = 30000; // 30 seconds

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    initDB();
    setupForm();
    updateConnectionStatus();
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);

    // Check for pending surveys periodically
    setInterval(checkPendingSurveys, SYNC_INTERVAL);
});

// Initialize IndexedDB
function initDB() {
    const request = indexedDB.open(DB_NAME, 1);

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        loadPendingSurveys();
    };

    request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        }
    };
}

// Setup form submission
function setupForm() {
    const form = document.getElementById('surveyForm');
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const survey = {
            location: document.getElementById('location').value,
            observation: document.getElementById('observation').value,
            date: document.getElementById('date').value,
            timestamp: new Date().toISOString(),
            synced: false
        };

        saveSurvey(survey);
        form.reset();
    });
}

// Save survey to IndexedDB
function saveSurvey(survey) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => {
        console.log('Survey saved locally');
        loadPendingSurveys();

        if (navigator.onLine) {
            syncSurvey(request.result);
        }
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
    };
}

// Load pending surveys from IndexedDB
function loadPendingSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => {
        const pendingList = document.getElementById('pendingList');
        pendingList.innerHTML = '';

        const pendingSurveys = request.result.filter(survey => !survey.synced);

        if (pendingSurveys.length === 0) {
            pendingList.innerHTML = '<li>No pending surveys</li>';
        } else {
            pendingSurveys.forEach(survey => {
                const li = document.createElement('li');
                li.textContent = `${survey.date} - ${survey.location}`;
                pendingList.appendChild(li);
            });
        }
    };
}

// Check for pending surveys and sync if online
function checkPendingSurveys() {
    if (navigator.onLine) {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
            const pendingSurveys = request.result.filter(survey => !survey.synced);

            if (pendingSurveys.length > 0) {
                updateStatus('syncing', 'Syncing pending surveys...');
                pendingSurveys.forEach(survey => syncSurvey(survey.id));
            }
        };
    }
}

// Sync a survey to the server (simulated)
function syncSurvey(id) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onsuccess = () => {
        const survey = request.result;

        // Simulate API call (in a real app, this would be a real fetch)
        setTimeout(() => {
            console.log('Survey synced:', survey);

            // Mark as synced
            survey.synced = true;
            const updateRequest = store.put(survey);

            updateRequest.onsuccess = () => {
                loadPendingSurveys();
                updateStatus('online', 'Survey synced successfully');
            };

            updateRequest.onerror = (event) => {
                console.error('Error updating survey:', event.target.error);
            };
        }, 1000); // Simulate network delay
    };

    request.onerror = (event) => {
        console.error('Error getting survey for sync:', event.target.error);
    };
}

// Update connection status display
function updateConnectionStatus() {
    const statusElement = document.getElementById('status');

    if (navigator.onLine) {
        updateStatus('online', 'Online - Syncing data...');
        checkPendingSurveys();
    } else {
        updateStatus('offline', 'Offline - Surveys will sync when reconnected');
    }
}

// Update status display
function updateStatus(status, message) {
    const statusElement = document.getElementById('status');
    statusElement.textContent = message;
    statusElement.className = `sync-status ${status}`;
}
