```javascript
// Database setup
const dbName = 'SurveyDB';
const storeName = 'surveys';
let db;

function openDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, 1);

        request.onerror = (event) => {
            reject('Database error: ' + event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(storeName)) {
                db.createObjectStore(storeName, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.add(surveyData);

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error saving survey: ' + event.target.error);
        };
    });
}

// Get all surveys from IndexedDB
function getAllSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error getting surveys: ' + event.target.error);
        };
    });
}

// Delete survey from IndexedDB
function deleteSurvey(id) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.delete(id);

        request.onsuccess = () => {
            resolve();
        };

        request.onerror = (event) => {
            reject('Error deleting survey: ' + event.target.error);
        };
    });
}

// Sync data with server
async function syncData() {
    if (!navigator.onLine) {
        updateSyncStatus('Offline - data will sync when connection is restored');
        return;
    }

    try {
        updateSyncStatus('Syncing data...');
        const surveys = await getAllSurveys();

        if (surveys.length === 0) {
            updateSyncStatus('No data to sync');
            return;
        }

        // Simulate API call to server
        // In a real app, you would use fetch() to send data to your backend
        console.log('Sending data to server:', surveys);

        // After successful sync, clear local data
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        store.clear();

        updateSyncStatus('Data synced successfully!');
        displaySurveys();
    } catch (error) {
        updateSyncStatus('Error syncing data: ' + error);
    }
}

// Display surveys in the UI
async function displaySurveys() {
    const surveyList = document.getElementById('surveyList');
    surveyList.innerHTML = '';

    try {
        const surveys = await getAllSurveys();

        if (surveys.length === 0) {
            surveyList.innerHTML = '<li>No surveys saved yet</li>';
            return;
        }

        surveys.forEach(survey => {
            const li = document.createElement('li');
            li.innerHTML = `
                <strong>Location:</strong> ${survey.location}<br>
                <strong>Observation:</strong> ${survey.observation}<br>
                <strong>Date:</strong> ${survey.date}<br>
                <button class="delete-btn" data-id="${survey.id}">Delete</button>
            `;
            surveyList.appendChild(li);
        });

        // Add event listeners to delete buttons
        document.querySelectorAll('.delete-btn').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                const id = parseInt(e.target.getAttribute('data-id'));
                await deleteSurvey(id);
                displaySurveys();
            });
        });
