```javascript
// Database setup
let db;
const DB_NAME = 'SurveyDB';
const STORE_NAME = 'surveys';

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    initDB();
    setupForm();
    updateConnectionStatus();
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);
});

// Initialize IndexedDB
function initDB() {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = (event) => {
        db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        }
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        loadSavedSurveys();
        // Try to sync when coming online
        if (navigator.onLine) {
            syncData();
        }
    };

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };
}

// Setup form submission
function setupForm() {
    const form = document.getElementById('survey-form');
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const survey = {
            location: document.getElementById('location').value,
            observation: document.getElementById('observation').value,
            date: document.getElementById('date').value,
            timestamp: new Date().toISOString(),
            synced: false
        };

        saveSurvey(survey);
        form.reset();
    });
}

// Save survey to IndexedDB
function saveSurvey(survey) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => {
        loadSavedSurveys();
        // Try to sync if online
        if (navigator.onLine) {
            syncData();
        }
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
    };
}

// Load saved surveys from IndexedDB
function loadSavedSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result;
        displaySurveys(surveys);
    };

    request.onerror = (event) => {
        console.error('Error loading surveys:', event.target.error);
    };
}

// Display surveys in the UI
function displaySurveys(surveys) {
    const list = document.getElementById('survey-list');
    list.innerHTML = '';

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <strong>${survey.location}</strong> - ${survey.date}
            <div>${survey.observation}</div>
            <small>${survey.synced ? 'Synced' : 'Pending sync'}</small>
        `;
        list.appendChild(li);
    });
}

// Update connection status display
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.className = 'online';
        syncData();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.className = 'offline';
    }
}

// Sync data with server (simulated)
async function syncData() {
    if (!navigator.onLine) return;

    const syncStatus = document.getElementById('sync-status');
    syncStatus.textContent = 'Syncing...';
    syncStatus.className = 'syncing';

    try {
        // Get unsynced surveys
        const unsynced = await getUnsyncedSurveys();

        if (unsynced.length === 0) {
            syncStatus.textContent = 'All data synced';
            syncStatus.className = 'synced';
            return;
        }

        // Simulate API call to sync data
        // In a real app, this would be a fetch to your backend
        await simulateSyncAPI(unsynced);

        // Mark as synced in local DB
        await markAsSynced(unsynced);

        syncStatus.textContent = 'Sync complete';
        syncStatus.className = 'synced';
        loadSavedSurveys();
    } catch (error) {
        console.error('Sync error:', error);
        syncStatus.textContent = 'Sync failed - will retry';
        syncStatus.className = 'offline';
    }
}

// Get unsynced surveys from IndexedDB
function getUnsyncedSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = (event) => {
            const allSurveys = event.target.result;
            const unsynced = allSurveys.filter(survey => !survey.synced);
            resolve(unsynced);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Simulate API call to sync data
function simulateSyncAPI(surveys) {
    return new Promise((resolve) => {
        // Simulate network delay
        setTimeout(() => {
            console.log('Synced surveys:', surveys);
            resolve();
        }, 1000);
    });
}

// Mark surveys as synced in IndexedDB
function markAsSynced(surveys) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        surveys.forEach(survey => {
            const updatedSurvey = { ...survey, synced: true };
            store.put(updatedSurvey);
        });

        transaction.oncomplete = resolve;
        transaction.onerror = (event) => reject(event.target.error);
    });
}

// Register service worker for offline capabilities
if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        navigator.serviceWorker.register('service-worker.js')
            .then(registration => {
                console.log('ServiceWorker registration successful');
            })
            .catch(err => {
                console.log('ServiceWorker registration failed: ', err);
            });
    });
}
