            try {
                await saveSurvey(survey);
                e.target.reset();
                updatePendingList();

                if (navigator.onLine) {
                    await syncData();
                } else {
                    updateStatus('Survey saved locally. Will sync when online.', 'offline');
                }
            } catch (error) {
                console.error('Error saving survey:', error);
                updateStatus('Error saving survey. Please try again.', 'offline');
            }
        });

        // Update UI when connection changes
        window.addEventListener('online', checkConnection);
        window.addEventListener('offline', checkConnection);

        // Initial connection check
        checkConnection();

        // Initial pending list update
        updatePendingList();
    } catch (error) {
        console.error('Initialization error:', error);
        updateStatus('Error initializing app. Please refresh.', 'offline');
    }
};

// Start the app
init();
```

## Features

1. **Offline Storage**: Uses IndexedDB to store surveys when offline
2. **Automatic Sync**: Attempts to sync when connection is restored
3. **Pending Surveys List**: Shows surveys that haven't been synced yet
4. **Connection Status**: Visual indicator of online/offline status
5. **Basic Form**: Collects location, surveyor name, notes, and rating

