```javascript
import { openDB } from 'idb';

const DB_NAME = 'SurveyDB';
const STORE_NAME = 'surveys';

export async function initDB() {
  return openDB(DB_NAME, 1, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
      }
    },
  });
}

export async function saveSurvey(surveyData) {
  const db = await initDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);
  await store.add(surveyData);
  await tx.done;
}

export async function getAllSurveys() {
  const db = await initDB();
  return db.getAll(STORE_NAME);
}

export async function clearSurveys() {
  const db = await initDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  const store = tx.objectStore(STORE_NAME);
  await store.clear();
  await tx.done;
}
```

### 3. Sync Service (src/services/sync.js)

```javascript
import { getAllSurveys, clearSurveys } from './db';

const API_URL = 'https://api.example.com/surveys'; // Replace with your API endpoint

export async function syncData() {
  if (!navigator.onLine) {
    console.log('Offline - data will be synced when connection is restored');
    return false;
  }

  try {
    const surveys = await getAllSurveys();
    if (surveys.length === 0) {
      console.log('No data to sync');
      return true;
    }

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(surveys),
    });

    if (response.ok) {
      await clearSurveys();
      console.log('Data synced successfully');
      return true;
    } else {
      console.error('Failed to sync data');
      return false;
    }
  } catch (error) {
    console.error('Sync error:', error);
    return false;
  }
}

// Set up periodic sync check
export function setupSyncListener() {
  window.addEventListener('online', () => {
    console.log('Connection restored - attempting to sync');
    syncData();
  });

  // Check sync every 5 minutes when online
  setInterval(() => {
    if (navigator.onLine) {
      syncData();
    }
  }, 5 * 60 * 1000);
}
```

