#### Subscription Routes (`routes/subscriptions.js`)

```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const Subscription = require('../models/Subscription');

// Create subscription
router.post('/', auth, async (req, res) => {
  try {
    const { plan } = req.body;
    const user = await User.findById(req.user.id);

    // Create Stripe customer if not exists
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    // Create subscription
    const priceId = getPriceIdForPlan(plan);
    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{ price: priceId }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: req.user.id,
      stripeCustomerId: customerId,
      stripeSubscriptionId: subscription.id,
      plan,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Helper function to get price ID based on plan
function getPriceIdForPlan(plan) {
  const prices = {
    basic: process.env.STRIPE_BASIC_PRICE_ID,
    premium: process.env.STRIPE_PREMIUM_PRICE_ID,
    pro: process.env.STRIPE_PRO_PRICE_ID
  };
  return prices[plan] || prices.basic;
}

// Webhook for Stripe events
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    console.error('Webhook error:', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const paymentIntent = event.data.object;
      // Update user's premium status
      await handleSuccessfulPayment(paymentIntent);
      break;
    case 'customer.subscription.deleted':
      const subscription = event.data.object;
      // Update user's premium status
      await handleSubscriptionDeletion(subscription);
      break;
    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

async function handleSuccessfulPayment(paymentIntent) {
  try {
    const subscription = await Subscription.findOne({
      stripeSubscriptionId: paymentIntent.subscription
    });

    if (subscription) {
      const user = await User.findById(subscription.user);
      user.premium = true;
      user.premiumExpiration = new Date(subscription.currentPeriodEnd);
      await user.save();
    }
  } catch (err) {
    console.error('Error handling successful payment:', err);
  }
}

async function handleSubscriptionDeletion(subscription) {
  try {
    const dbSubscription = await Subscription.findOne({
      stripeSubscriptionId: subscription.id
    });

    if (dbSubscription) {
      const user = await User.findById(dbSubscription.user);
      user.premium = false;
      user.premiumExpiration = null;
      await user.save();

      dbSubscription.status = 'canceled';
      await dbSubscription.save();
    }
  } catch (err) {
    console.error('Error handling subscription deletion:', err);
  }
}

module.exports = router;
```

### 5. Middleware (`middleware/auth.js`)

```javascript
const jwt = require('jsonwebtoken');

module.exports = function(req, res, next) {
  // Get token from header
  const token = req.header('x-auth-token');

  // Check if not token
  if (!token) {
    return res.status(401).json({ msg: 'No token, authorization denied' });
  }

  // Verify token
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded.user;
    next();
  } catch (err) {
    res.status(401).json({ msg: 'Token is not valid' });
  }
};
