import React, { useState, useEffect, useContext } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { io } from 'socket.io-client';
import AuthContext from '../context/AuthContext';

const socket = io(process.env.REACT_APP_API_URL);

function Chat() {
  const { userId } = useParams();
  const { user, messages, setMessages } = useContext(AuthContext);
  const [newMessage, setNewMessage] = useState('');
  const [receiver, setReceiver] = useState(null);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/${userId}`, {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        });
        setMessages(res.data);

        // Mark messages as read
        await axios.put(`${process.env.REACT_APP_API_URL}/api/messages/read/${userId}`, {}, {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        });
      } catch (err) {
        console.error(err);
      }
    };

    const fetchReceiver = async () => {
      try {
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/users/${userId}`);
        setReceiver(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();
    fetchReceiver();
  }, [userId, setMessages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() === '') return;

    const messageData = {
      senderId: user._id,
      receiverId: userId,
      content: newMessage
    };

    socket.emit('sendMessage', messageData);
    setNewMessage('');
  };

  return (
    <div className="chat-container">
      <h2>Chat with {receiver?.username}</h2>
      <div className="messages">
        {messages.map((msg) => (
          <div key={msg._id} className={`message ${msg.sender === user._id ? 'sent' : 'received'}`}>
            <p>{msg.content}</p>
            <small>{new Date(msg.timestamp).toLocaleTimeString()}</small>
          </div>
        ))}
      </div>
      <form onSubmit={handleSendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default Chat;
