  const markNotificationAsRead = async (notificationId) => {
    try {
      await axios.post(`http://localhost:5000/api/notifications/${notificationId}/read`, {},
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );
      setNotifications(notifications.map(n =>
        n._id === notificationId ? { ...n, read: true } : n
      ));
      setUnreadCount(unreadCount - 1);
    } catch (err) {
      console.error(err);
    }
  };

  const loadNotifications = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/notifications', {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setNotifications(res.data);
      setUnreadCount(res.data.filter(n => !n.read).length);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/login" element={user ? <Navigate to="/dashboard" /> : <Login login={login} />} />
          <Route path="/register" element={user ? <Navigate to="/dashboard" /> : <Register register={register} />} />
          <Route path="/dashboard" element={
            user ? (
              <Dashboard
                user={user}
                logout={logout}
                notifications={notifications}
                unreadCount={unreadCount}
                markNotificationAsRead={markNotificationAsRead}
                loadNotifications={loadNotifications}
              />
            ) : (
              <Navigate to="/login" />
            )
          } />
          <Route path="/chat/:userId" element={
            user ? (
              <Chat
                user={user}
                socket={socket}
                stripePromise={stripePromise}
              />
            ) : (
              <Navigate to="/login" />
            )
          } />
          <Route path="/premium" element={
            user ? (
              <Premium
                user={user}
                stripePromise={stripePromise}
                setUser={setUser}
              />
            ) : (
              <Navigate to="/login" />
            )
          } />
          <Route path="*" element={<Navigate to="/dashboard" />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
```

