```javascript
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';

const Chat = ({ user, socket, stripePromise }) => {
  const { userId } = useParams();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [recipient, setRecipient] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Load messages
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/messages/${userId}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setMessages(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    // Load recipient info
    const fetchRecipient = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/user/${userId}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setRecipient(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();
    fetchRecipient();

    // Set up socket listeners
    socket.on('new-message', (message) => {
      if (message.sender === userId || message.recipient === userId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off('new-message');
    };
  }, [userId, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    try {
      const res = await axios.post('http://localhost:5000/api/messages', {
        recipientId: userId,
        content: newMessage
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      setMessages([...messages, res.data]);
      setNewMessage('');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        {recipient && (
          <div className="recipient-info">
            <img src={recipient.profilePicture || '/default-avatar.png'} alt="Profile" />
            <h3>{recipient.username}</h3>
            {recipient.premium && <span className="premium-badge">Premium</span>}
          </div>
        )}
      </div>

      <div className="messages-container">
        {messages.map((message) => (
          <div
            key={message._id}
            className={`message ${message.sender === user._id ? 'sent' : 'received'}`}
          >
            <p>{message.content}</p>
            <span className="timestamp">
              {new Date(message.createdAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={sendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
```

### 4. Premium Subscription Component (Premium.js)

```javascript
import React, { useState } from 'react';
import axios from 'axios';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';

const Premium = ({ user, stripePromise, setUser }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const stripe = useStripe();
  const elements = useElements();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    if (!stripe || !elements) {
      setError('Stripe has not loaded yet. Please try again.');
      setLoading(false);
      return;
    }

    try {
      // Create PaymentMethod
      const { error: stripeError, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: elements.getElement(CardElement),
      });

      if (stripeError) {
        setError(stripeError.message);
        setLoading(false);
        return;
      }

      // Send to backend
      const res = await axios.post('http://localhost:5000/api/create-subscription', {
        paymentMethodId: paymentMethod.id,
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      // Confirm payment
      const { clientSecret } = res.data;
      const { error: confirmError, paymentIntent } = await stripe.confirmCardPayment(clientSecret);

      if (confirmError) {
        setError(confirmError.message);
        setLoading(false);
        return;
      }

      if (paymentIntent.status === 'succeeded') {
        setSuccess(true);
        setUser(res.data.user);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'An error occurred during payment');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="premium-success">
        <h2>Congratulations!</h2>
        <p>You are now a premium member.</p>
        <p>Enjoy all the benefits of our premium features.</p>
      </div>
    );
  }

  return (
    <div className="premium-container">
      <h2>Upgrade to Premium</h2>
      <p>Get access to exclusive features:</p>
      <ul>
        <li>Unlimited messages</li>
        <li>Priority support</li>
        <li>Exclusive stickers</li>
        <li>Ad-free experience</li>
      </ul>

      <div className="premium-pricing">
        <h3>$9.99/month</h3>
      </div>

      <form onSubmit={handleSubmit} className="premium-form">
        <div className="card-element">
          <CardElement options={{
            style: {
              base: {
                fontSize: '16px',
                color: '#424770',
                '::placeholder': {
                  color: '#aab7c4',
                },
              },
              invalid: {
                color: '#9e2146',
              },
            },
          }} />
        </div>

        {error && <div className="error-message">{error}</div>}

        <button
          type="submit"
          disabled={!stripe || loading}
          className="premium-button"
        >
          {loading ? 'Processing...' : 'Subscribe Now'}
        </button>
      </form>
    </div>
  );
};

export default Premium;
