# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code example for a social messaging app with real-time notifications and in-app monetization features. This implementation uses Node.js with Express for the backend, Socket.io for real-time functionality, and React for the frontend.

## Backend Implementation (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Database connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Models
const User = mongoose.model('User', new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  profilePicture: String,
  premium: { type: Boolean, default: false },
  premiumExpiry: Date,
  createdAt: { type: Date, default: Date.now }
}));

const Message = mongoose.model('Message', new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  receiver: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  read: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now }
}));

const Notification = mongoose.model('Notification', new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  type: { type: String, enum: ['message', 'friend_request', 'premium'] },
  content: String,
  read: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now }
}));

// Middleware
app.use(express.json());

// Authentication middleware
const authenticate = async (req, res, next) => {
  try {
    const token = req.header('Authorization').replace('Bearer ', '');
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const user = await User.findOne({ _id: decoded._id });

    if (!user) {
      throw new Error();
    }

    req.token = token;
    req.user = user;
    next();
  } catch (error) {
    res.status(401).send({ error: 'Please authenticate.' });
  }
};

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 8);

    const user = new User({ username, email, password: hashedPassword });
    await user.save();

    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET);
    res.status(201).send({ user, token });
  } catch (error) {
    res.status(400).send(error);
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.findOne({ email });

    if (!user) {
      return res.status(401).send({ error: 'Login failed!' });
    }

    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res.status(401).send({ error: 'Login failed!' });
    }

    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET);
    res.send({ user, token });
  } catch (error) {
    res.status(400).send(error);
  }
});

// Message routes
app.post('/api/messages', authenticate, async (req, res) => {
  try {
    const { receiverId, content } = req.body;
    const message = new Message({
      sender: req.user._id,
      receiver: receiverId,
      content
    });

    await message.save();

    // Emit real-time message
    io.to(receiverId).emit('newMessage', message);

    // Create notification
    const notification = new Notification({
      user: receiverId,
      type: 'message',
      content: `New message from ${req.user.username}`
    });
    await notification.save();

    // Emit real-time notification
    io.to(receiverId).emit('newNotification', notification);

    res.status(201).send(message);
  } catch (error) {
    res.status(400).send(error);
  }
});

app.get('/api/messages', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user._id },
        { receiver: req.user._id }
      ]
    }).populate('sender receiver', 'username profilePicture');

    res.send(messages);
  } catch (error) {
    res.status(500).send(error);
  }
});

// Notification routes
app.get('/api/notifications', authenticate, async (req, res) => {
  try {
    const notifications = await Notification.find({ user: req.user._id })
      .sort({ createdAt: -1 });

    res.send(notifications);
  } catch (error) {
    res.status(500).send(error);
  }
});

app.post('/api/notifications/read', authenticate, async (req, res) => {
  try {
    await Notification.updateMany(
      { user: req.user._id, read: false },
      { $set: { read: true } }
    );

    res.send({ success: true });
  } catch (error) {
    res.status(500).send(error);
  }
});

// Premium subscription routes
app.post('/api/premium/create-checkout-session', authenticate, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [{
        price_data: {
          currency: 'usd',
          product_data: {
            name: 'Premium Subscription',
            description: 'Unlock premium features for 1 month',
          },
          unit_amount: 999, // $9.99
        },
        quantity: 1,
      }],
      mode: 'payment',
      success_url: `${process.env.CLIENT_URL}/premium-success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.CLIENT_URL}/premium-cancel`,
      customer_email: req.user.email,
      client_reference_id: req.user._id.toString(),
    });

    res.json({ sessionId: session.id });
  } catch (error) {
    res.status(500).send(error);
  }
});

app.post('/api/premium/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.client_reference_id;

    // Update user to premium
    await User.findByIdAndUpdate(userId, {
      premium: true,
      premiumExpiry: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // 30 days from now
    });

    // Create notification
    const notification = new Notification({
      user: userId,
      type: 'premium',
      content: 'Your premium subscription has been activated!'
    });
    await notification.save();

    // Emit real-time notification
    io.to(userId).emit('newNotification', notification);
  }

  res.json({ received: true });
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (userId) => {
    socket.join(userId);
    console.log(`User ${userId} joined`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## Frontend Implementation (React)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import io from 'socket.io-client';
import axios from 'axios';
import { loadStripe } from '@stripe/stripe-js';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    // Initialize socket connection
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Check for existing user session
    const token = localStorage.getItem('token');
    if (token) {
      axios.get('/api/user', {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(response => {
        setUser(response.data);
        newSocket.emit('join', response.data._id);
      })
      .catch(() => {
        localStorage.removeItem('token');
      });
    }

    return () => newSocket.close();
  }, []);

  useEffect(() => {
    if (user && socket) {
      // Listen for new messages
      socket.on('newMessage', (message) => {
        setMessages(prev => [...prev, message]);
      });

      // Listen for new notifications
      socket.on('newNotification', (notification) => {
        setNotifications(prev => [notification, ...prev]);
      });
    }
  }, [user, socket]);

  const login = async (email, password) => {
    try {
      const response = await axios.post('/api/login', { email, password });
      localStorage.setItem('token', response.data.token);
      setUser(response.data.user);
      socket.emit('join', response.data.user._id);
      return true;
    } catch (error) {
      console.error('Login failed:', error);
      return false;
    }
  };

  const register = async (username, email, password) => {
    try {
      const response = await axios.post('/api/register', { username, email, password });
      localStorage.setItem('token', response.data.token);
      setUser(response.data.user);
      socket.emit('join', response.data.user._id);
      return true;
    } catch (error) {
      console.error('Registration failed:', error);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
    socket.disconnect();
  };

  const sendMessage = async (receiverId, content) => {
    try {
      const response = await axios.post('/api/messages', {
        receiverId,
        content
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setMessages(prev => [...prev, response.data]);
    } catch (error) {
      console.error('Failed to send message:', error);
    }
  };

  const markNotificationsAsRead = async () => {
    try {
      await axios.post('/api/notifications/read', {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    } catch (error) {
      console.error('Failed to mark notifications as read:', error);
    }
  };

  const upgradeToPremium = async () => {
    try {
      const stripe = await stripePromise;
      const response = await axios.post('/api/premium/create-checkout-session', {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      const result = await stripe.redirectToCheckout({
        sessionId: response.data.sessionId
      });

      if (result.error) {
        console.error('Stripe error:', result.error.message);
      }
    } catch (error) {
      console.error('Failed to create checkout session:', error);
    }
  };

  return (
    <Router>
      <div className="app">
        <header>
          <h1>Social Messenger</h1>
          {user && (
            <div className="user-info">
              <span>Welcome, {user.username}</span>
              {user.premium && <span className="premium-badge">Premium</span>}
              <button onClick={logout}>Logout</button>
            </div>
          )}
        </header>

        <Switch>
          <Route path="/login">
            <LoginForm onLogin={login} />
          </Route>
          <Route path="/register">
            <RegisterForm onRegister={register} />
          </Route>
          <Route path="/messages">
            {user ? (
              <Messages
                user={user}
                messages={messages}
                onSendMessage={sendMessage}
              />
            ) : (
              <Redirect to="/login" />
            )}
          </Route>
          <Route path="/notifications">
            {user ? (
              <Notifications
                notifications={notifications}
                onMarkAsRead={markNotificationsAsRead}
              />
            ) : (
              <Redirect to="/login" />
            )}
          </Route>
          <Route path="/premium">
            {user ? (
              <PremiumPage
                user={user}
                onUpgrade={upgradeToPremium}
              />
            ) : (
              <Redirect to="/login" />
            )}
          </Route>
          <Route path="/">
            {user ? <Home user={user} /> : <Redirect to="/login" />}
          </Route>
        </Switch>
      </div>
    </Router>
  );
}

// Other components (LoginForm, RegisterForm, Messages, Notifications, PremiumPage, etc.)
// would be defined here with their respective implementations

export default App;
