  try {
    const { senderId, receiverId, content, isPremium } = req.body;

    // Check if sender has enough coins if it's a premium message
    if (isPremium) {
      const senderDoc = await db.collection('users').doc(senderId).get();
      const senderData = senderDoc.data();

      if (senderData.coins < 10) {
        return res.status(403).json({ error: "Not enough coins for premium message" });
      }

      // Deduct coins
      await db.collection('users').doc(senderId).update({
        coins: admin.firestore.FieldValue.increment(-10)
      });
    }

    // Save message
