        setUser(user);

        // Get user data from Firestore
        const userDoc = await doc(db, 'users', user.uid).get();
        if (userDoc.exists()) {
          const userData = userDoc.data();
          setCoins(userData.coins || 0);
          setIsPremium(userData.premium || false);
