### 1. Main App Component (`App.js`)

```jsx
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';

import AuthContext from './context/AuthContext';
import PrivateRoute from './components/PrivateRoute';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Chat from './pages/Chat';
import Notifications from './pages/Notifications';
import Subscriptions from './pages/Subscriptions';

const socket = io('http://localhost:5000');

function App() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [subscription, setSubscription] = useState(null);

  // Check for existing token
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      axios.defaults.headers.common['x-auth-token'] = token;
      fetchUserData();
    }

    // Listen for notifications
    socket.on('newNotification', (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    return () => {
      socket.off('newNotification');
    };
  }, []);

  const fetchUserData = async () => {
    try {
      const userRes = await axios.get('/api/auth/user');
      setUser(userRes.data);

      const notificationsRes = await axios.get('/api/notifications');
      setNotifications(notificationsRes.data);

      const subscriptionRes = await axios.get('/api/subscriptions/current');
      setSubscription(subscriptionRes.data);

      // Join user's room
      socket.emit('joinRoom', userRes.data._id);
    } catch (err) {
      console.error(err);
      logout();
    }
  };

  const login = async (email, password) => {
    try {
      const res = await axios.post('/api/auth/login', { email, password });
      localStorage.setItem('token', res.data.token);
      axios.defaults.headers.common['x-auth-token'] = res.data.token;
      await fetchUserData();
      return true;
    } catch (err) {
      console.error(err);
      return false;
    }
  };

  const register = async (username, email, password) => {
    try {
      const res = await axios.post('/api/auth/register', { username, email, password });
      localStorage.setItem('token', res.data.token);
      axios.defaults.headers.common['x-auth-token'] = res.data.token;
      await fetchUserData();
      return true;
    } catch (err) {
      console.error(err);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    delete axios.defaults.headers.common['x-auth-token'];
    setUser(null);
    setNotifications([]);
    setSubscription(null);
  };

  const markNotificationAsRead = async (id) => {
    try {
      await axios.put(`/api/notifications/${id}`);
      setNotifications(notifications.map(n =>
        n._id === id ? { ...n, read: true } : n
      ));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <AuthContext.Provider value={{
      user,
      notifications,
      subscription,
      login,
      register,
      logout,
      markNotificationAsRead,
      socket
    }}>
      <Router>
        <div className="app">
          <Switch>
            <Route path="/login" component={Login} />
            <Route path="/register" component={Register} />
            <PrivateRoute exact path="/" component={Dashboard} />
            <PrivateRoute path="/chat/:userId" component={Chat} />
            <PrivateRoute path="/notifications" component={Notifications} />
            <PrivateRoute path="/subscriptions" component={Subscriptions} />
          </Switch>
        </div>
      </Router>
    </AuthContext.Provider>
  );
}

export default App;
```

