import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import AuthContext from '../context/AuthContext';

const Chat = () => {
  const { userId } = useParams();
  const { user, socket } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [receiver, setReceiver] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`/api/messages/${userId}`);
        setMessages(res.data);

        // Mark messages as read
        await axios.put(`/api/messages/read/${userId}`);

        // Get receiver info
        const receiverRes = await axios.get(`/api/users/${userId}`);
        setReceiver(receiverRes.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();

    // Listen for new messages
    socket.on('newMessage', (message) => {
      if (message.sender === userId || message.receiver === userId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off('newMessage');
    };
  }, [userId, socket, user]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const sendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() === '') return;

    const messageData = {
      senderId: user._id,
      receiverId: userId,
      content: newMessage,
      type: 'text'
    };

    socket.emit('sendMessage', messageData);
    setNewMessage('');
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        {receiver && (
          <>
            <img src={receiver.profilePicture || '/default-avatar.png'} alt="Profile" />
            <h2>{receiver.username}</h2>
            <span className={`status ${receiver.status}`}>{receiver.status}</span>
          </>
        )}
      </div>

      <div className="messages-container">
        {messages.map((message) => (
          <div
            key={message._id}
            className={`message ${message.sender === user._id ? 'sent' : 'received'}`}
          >
            <p>{message.content}</p>
            <span className="timestamp">
              {new Date(message.createdAt).toLocaleTimeString()}
            </span>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={sendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
