import React, { useState, useContext, useEffect } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import axios from 'axios';
import AuthContext from '../context/AuthContext';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const SubscriptionForm = () => {
  const { subscription } = useContext(AuthContext);
  const [plan, setPlan] = useState('premium');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const stripe = useStripe();
  const elements = useElements();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // Create subscription on backend
      const { data } = await axios.post('/api/subscriptions/create', { plan });

      // Confirm payment with Stripe
      const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(
        data.clientSecret,
        {
          payment_method: {
            card: elements.getElement(CardElement),
          },
        }
      );

      if (stripeError) {
        setError(stripeError.message);
        setLoading(false);
        return;
      }

      setSuccess(true);
      setLoading(false);
    } catch (err) {
      setError(err.response?.data?.msg || 'Something went wrong');
      setLoading(false);
    }
  };

  return (
    <div className="subscription-form">
      {subscription?.active ? (
        <div className="active-subscription">
          <h2>Your Current Plan: {subscription.plan.toUpperCase()}</h2>
          <p>Expires: {new Date(subscription.currentPeriodEnd).toLocaleDateString()}</p>
        </div>
      ) : (
        <>
          <h2>Choose Your Plan</h2>
          <div className="plan-options">
            <label>
              <input
                type="radio"
                value="basic"
                checked={plan === 'basic'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Basic ($5/month)
            </label>
            <label>
              <input
                type="radio"
                value="premium"
                checked={plan === 'premium'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Premium ($10/month)
            </label>
            <label>
              <input
                type="radio"
                value="pro"
                checked={plan === 'pro'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Pro ($20/month)
            </label>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="card-element">
              <CardElement />
            </div>
            <button type="submit" disabled={!stripe || loading}>
              {loading ? 'Processing...' : 'Subscribe'}
            </button>
            {error && <div className="error">{error}</div>}
            {success && <div className="success">Subscription successful!</div>}
          </form>
        </>
      )}
    </div>
  );
};

const Subscriptions = () => {
  return (
    <div className="subscriptions-container">
      <h1>Subscriptions</h1>
      <Elements stripe={stripePromise}>
        <SubscriptionForm />
      </Elements>
    </div>
  );
};

export default Subscriptions;
