const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const Subscription = require('../models/Subscription');
const User = require('../models/User');
const auth = require('../middleware/auth');

// Create a subscription
router.post('/create', auth, async (req, res) => {
  try {
    const { plan } = req.body;
    const user = await User.findById(req.user.id);

    // Check if user already has a subscription
    if (user.subscription) {
      return res.status(400).json({ msg: 'User already has a subscription' });
    }

    // Create Stripe customer
    const customer = await stripe.customers.create({
      email: user.email,
      name: user.username,
      metadata: {
        userId: user._id.toString()
      }
    });

    // Create Stripe subscription
    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{
        price: getPriceIdForPlan(plan)
      }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: user._id,
      customerId: customer.id,
      subscriptionId: subscription.id,
      plan,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    // Update user
    user.subscription = newSubscription._id;
    user.premium = true;
    await user.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Get current subscription
router.get('/current', auth, async (req, res) => {
  try {
    const user = await User.findById(req.user.id).populate('subscription');
    res.json(user.subscription);
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Cancel subscription
router.post('/cancel', auth, async (req, res) => {
  try {
    const user = await User.findById(req.user.id).populate('subscription');

    if (!user.subscription) {
      return res.status(400).json({ msg: 'No active subscription' });
    }

    // Cancel Stripe subscription
    await stripe.subscriptions.del(user.subscription.subscriptionId);

    // Update database
    user.subscription.status = 'canceled';
    await user.subscription.save();

    user.premium = false;
    await user.save();

    res.json({ msg: 'Subscription canceled successfully' });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

function getPriceIdForPlan(plan) {
  const prices = {
    basic: process.env.STRIPE_BASIC_PRICE_ID,
    premium: process.env.STRIPE_PREMIUM_PRICE_ID,
    enterprise: process.env.STRIPE_ENTERPRISE_PRICE_ID
  };

  return prices[plan] || prices.basic;
}

module.exports = router;
```

