```javascript
import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { NotificationContext } from '../context/NotificationContext';
import Message from '../components/Message';
import MessageInput from '../components/MessageInput';

const Chat = ({ socket }) => {
  const { userId } = useParams();
  const { user } = useContext(AuthContext);
  const { setUnreadCount } = useContext(NotificationContext);
  const [messages, setMessages] = useState([]);
  const [receiver, setReceiver] = useState(null);
  const [loading, setLoading] = useState(true);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch chat history
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`/api/messages/${userId}`, {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });
        setMessages(res.data);
        setLoading(false);

        // Mark messages as read
        await axios.put(`/api/messages/mark-read/${userId}`, {}, {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });

        // Update unread count
        setUnreadCount(prev => prev - res.data.filter(m => !m.read).length);
      } catch (err) {
        console.error(err);
      }
    };

    // Fetch receiver info
    const fetchReceiver = async () => {
      try {
        const res = await axios.get(`/api/users/${userId}`, {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });
        setReceiver(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();
    fetchReceiver();

    // Join chat room
    socket.emit('join', user._id);

    // Listen for new messages
    socket.on('receiveMessage', (message) => {
      if (message.sender === userId || message.receiver === userId) {
        setMessages(prev => [...prev, message]);
      }
    });

    // Clean up
    return () => {
      socket.off('receiveMessage');
    };
  }, [userId, user._id, socket, setUnreadCount]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const sendMessage = (content, type = 'text') => {
    const message = {
      senderId: user._id,
      receiverId: userId,
      content,
      messageType: type
    };

    socket.emit('sendMessage', message);
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="chat-container">
      <div className="chat-header">
        {receiver && (
          <>
            <img src={receiver.profilePicture} alt={receiver.username} className="avatar" />
            <h2>{receiver.username}</h2>
          </>
        )}
      </div>

      <div className="messages-container">
        {messages.map((message) => (
          <Message
            key={message._id}
            message={message}
            isOwnMessage={message.sender === user._id}
          />
        ))}
        <div ref={messagesEndRef} />
      </div>

      <MessageInput onSendMessage={sendMessage} />
    </div>
  );
};

export default Chat;
```

