          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });
        setCurrentPlan(res.data);
        setLoading(false);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };

    fetchSubscription();
  }, []);

  const handleSuccess = async () => {
    // Refresh user data
    const res = await axios.get('/api/auth/me', {
      headers: {
        'x-auth-token': localStorage.getItem('token')
      }
    });
    setUser(res.data);

    // Refresh subscription
    const subRes = await axios.get('/api/subscriptions/current', {
      headers: {
        'x-auth-token': localStorage.getItem('token')
      }
    });
    setCurrentPlan(subRes.data);
  };

  const handleCancel = async () => {
    try {
      await axios.post('/api/subscriptions/cancel', {}, {
        headers: {
          'x-auth-token': localStorage.getItem('token')
        }
      });

      // Refresh user data
      const res = await axios.get('/api/auth/me', {
        headers: {
          'x-auth-token': localStorage.getItem('token')
        }
      });
      setUser(res.data);
      setCurrentPlan(null);
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="subscription-container">
      <h1>Subscription Plans</h1>

      {currentPlan ? (
        <div className="current-plan">
          <h2>Current Plan: {currentPlan.plan.charAt(0).toUpperCase() + currentPlan.plan.slice(1)}</h2>
