            <button onClick={() => setSelectedPlan('premium')}>Select</button>
          </div>

          <div className="plan-card">
            <h3>Enterprise</h3>
            <p>$49.99/month</p>
            <p>All features + dedicated account manager</p>
            <button onClick={() => setSelectedPlan('enterprise')}>Select</button>
          </div>
        </div>
      )}

      {selectedPlan && !currentPlan && (
        <div className="checkout-form">
          <h2>Checkout</h2>
          <Elements stripe={stripePromise}>
            <CheckoutForm plan={selectedPlan} onSuccess={handleSuccess} />
          </Elements>
        </div>
      )}
    </div>
  );
};

