# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code example for a social messaging app with real-time notifications and in-app monetization features. This implementation uses Node.js with Express for the backend, Socket.io for real-time communication, and React for the frontend.

## Backend Implementation (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// MongoDB connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// User Schema
const userSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  profilePicture: { type: String },
  premium: { type: Boolean, default: false },
  premiumExpiry: { type: Date },
  createdAt: { type: Date, default: Date.now }
});

const User = mongoose.model('User', userSchema);

// Message Schema
const messageSchema = new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  receiver: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: { type: String, required: true },
  timestamp: { type: Date, default: Date.now },
  read: { type: Boolean, default: false }
});

const Message = mongoose.model('Message', messageSchema);

// Notification Schema
const notificationSchema = new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  type: { type: String, enum: ['message', 'friend_request', 'premium'] },
  content: { type: String },
  read: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now }
});

const Notification = mongoose.model('Notification', notificationSchema);

// Middleware
app.use(express.json());

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;

    // Check if user exists
    const existingUser = await User.findOne({ $or: [{ email }, { username }] });
    if (existingUser) {
      return res.status(400).send('User already exists');
    }

    // Hash password
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    // Create user
    const user = new User({
      username,
      email,
      password: hashedPassword
    });

    await user.save();

    // Create token
    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET, { expiresIn: '7d' });

    res.status(201).send({ user, token });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Check if user exists
    const user = await User.findOne({ email });
    if (!user) {
      return res.status(400).send('Invalid credentials');
    }

    // Check password
    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) {
      return res.status(400).send('Invalid credentials');
    }

    // Create token
    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET, { expiresIn: '7d' });

    res.send({ user, token });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.get('/api/messages', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user._id },
        { receiver: req.user._id }
      ]
    }).populate('sender receiver', 'username profilePicture');

    res.send(messages);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/messages', authenticate, async (req, res) => {
  try {
    const { receiverId, content } = req.body;

    const message = new Message({
      sender: req.user._id,
      receiver: receiverId,
      content
    });

    await message.save();

    // Emit message to receiver
    const receiverSocketId = getSocketIdByUserId(receiverId);
    if (receiverSocketId) {
      io.to(receiverSocketId).emit('newMessage', message);
    }

    // Create notification for receiver
    const notification = new Notification({
      user: receiverId,
      type: 'message',
      content: `New message from ${req.user.username}`
    });

    await notification.save();

    // Emit notification to receiver
    if (receiverSocketId) {
      io.to(receiverSocketId).emit('newNotification', notification);
    }

    res.status(201).send(message);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.get('/api/notifications', authenticate, async (req, res) => {
  try {
    const notifications = await Notification.find({ user: req.user._id })
      .sort({ createdAt: -1 })
      .limit(20);

    res.send(notifications);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/notifications/read', authenticate, async (req, res) => {
  try {
    await Notification.updateMany(
      { user: req.user._id, read: false },
      { $set: { read: true } }
    );

    res.send({ success: true });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

// Premium subscription routes
app.post('/api/premium/create-subscription', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);

    // Create Stripe Checkout session
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [{
        price_data: {
          currency: 'usd',
          product_data: {
            name: 'Premium Subscription',
            description: 'Unlock all features for 1 month',
          },
          unit_amount: 999, // $9.99
        },
        quantity: 1,
      }],
      mode: 'payment',
      success_url: `${process.env.FRONTEND_URL}/premium/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.FRONTEND_URL}/premium/cancel`,
      customer_email: user.email,
      client_reference_id: user._id.toString(),
    });

    res.send({ sessionId: session.id });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/premium/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the checkout.session.completed event
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;

    // Fulfill the purchase
    const userId = session.client_reference_id;
    const user = await User.findById(userId);

    if (user) {
      // Set premium status
      user.premium = true;
      user.premiumExpiry = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days from now
      await user.save();

      // Create notification
      const notification = new Notification({
        user: userId,
        type: 'premium',
        content: 'Your premium subscription has been activated!'
      });

      await notification.save();

      // Emit notification if user is online
      const userSocketId = getSocketIdByUserId(userId);
      if (userSocketId) {
        io.to(userSocketId).emit('newNotification', notification);
      }
    }
  }

  res.json({ received: true });
});

// Socket.io connection
const userSocketMap = new Map();

io.on('connection', (socket) => {
  console.log('New client connected');

  // Store user ID with socket ID
  socket.on('registerUser', (userId) => {
    userSocketMap.set(userId, socket.id);
    console.log(`User ${userId} registered with socket ${socket.id}`);
  });

  socket.on('disconnect', () => {
    // Remove user from map when they disconnect
    for (const [userId, socketId] of userSocketMap.entries()) {
      if (socketId === socket.id) {
        userSocketMap.delete(userId);
        console.log(`User ${userId} disconnected`);
        break;
      }
    }
  });
});

function getSocketIdByUserId(userId) {
  return userSocketMap.get(userId);
}

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## Frontend Implementation (React)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';
import './App.css';

// Components
import Login from './components/Login';
import Register from './components/Register';
import Chat from './components/Chat';
import Notifications from './components/Notifications';
import Premium from './components/Premium';
import Navbar from './components/Navbar';

const socket = io('http://localhost:5000');

function App() {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    if (token) {
      // Fetch user data
      axios.get('/api/user', {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(res => {
        setUser(res.data);
        socket.emit('registerUser', res.data._id);
      })
      .catch(err => {
        console.error(err);
        localStorage.removeItem('token');
        setToken(null);
      });

      // Fetch notifications
      fetchNotifications();
    }
  }, [token]);

  useEffect(() => {
    if (user) {
      // Listen for new messages
      socket.on('newMessage', (message) => {
        // Handle new message
        console.log('New message received:', message);
      });

      // Listen for new notifications
      socket.on('newNotification', (notification) => {
        setNotifications(prev => [notification, ...prev]);
        setUnreadCount(prev => prev + 1);
      });

      return () => {
        socket.off('newMessage');
        socket.off('newNotification');
      };
    }
  }, [user]);

  const fetchNotifications = () => {
    axios.get('/api/notifications', {
      headers: { Authorization: `Bearer ${token}` }
    })
    .then(res => {
      setNotifications(res.data);
      setUnreadCount(res.data.filter(n => !n.read).length);
    })
    .catch(err => console.error(err));
  };

  const markNotificationsAsRead = () => {
    axios.post('/api/notifications/read', {}, {
      headers: { Authorization: `Bearer ${token}` }
    })
    .then(() => {
      setUnreadCount(0);
      fetchNotifications();
    })
    .catch(err => console.error(err));
  };

  const handleLogin = (userData, token) => {
    setUser(userData);
    setToken(token);
    localStorage.setItem('token', token);
    socket.emit('registerUser', userData._id);
  };

  const handleLogout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem('token');
    socket.disconnect();
  };

  return (
    <Router>
      <div className="app">
        {user && <Navbar
          user={user}
          unreadCount={unreadCount}
          onLogout={handleLogout}
          onMarkAsRead={markNotificationsAsRead}
        />}

        <Routes>
          <Route path="/login" element={
            <Login onLogin={handleLogin} />
          } />
          <Route path="/register" element={
            <Register onRegister={handleLogin} />
          } />
          <Route path="/chat" element={
            user ? <Chat user={user} token={token} /> : <Login onLogin={handleLogin} />
          } />
          <Route path="/notifications" element={
            user ? <Notifications
              notifications={notifications}
              onMarkAsRead={markNotificationsAsRead}
            /> : <Login onLogin={handleLogin} />
          } />
          <Route path="/premium" element={
            user ? <Premium user={user} token={token} /> : <Login onLogin={handleLogin} />
          } />
          <Route path="/" element={
            user ? <Chat user={user} token={token} /> : <Login onLogin={handleLogin} />
          } />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
