# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code example for a social messaging app with real-time notifications and in-app monetization features. This implementation uses Node.js with Express for the backend, Socket.io for real-time functionality, and React for the frontend.

## Backend Implementation (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Database connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Models
const User = mongoose.model('User', new mongoose.Schema({
  username: { type: String, unique: true, required: true },
  email: { type: String, unique: true, required: true },
  password: { type: String, required: true },
  profilePicture: String,
  premiumStatus: { type: Boolean, default: false },
  premiumExpiration: Date,
  stripeCustomerId: String,
  createdAt: { type: Date, default: Date.now }
}));

const Message = mongoose.model('Message', new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  recipient: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  timestamp: { type: Date, default: Date.now },
  isRead: { type: Boolean, default: false },
  isPremium: { type: Boolean, default: false }
}));

const Notification = mongoose.model('Notification', new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  type: { type: String, enum: ['message', 'premium', 'system'] },
  isRead: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now }
}));

// Middleware
app.use(express.json());

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;

    // Check if user exists
    const existingUser = await User.findOne({ $or: [{ email }, { username }] });
    if (existingUser) {
      return res.status(400).send('User already exists');
    }

    // Hash password
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    // Create user
    const user = new User({
      username,
      email,
      password: hashedPassword
    });

    await user.save();

    // Create Stripe customer
    const customer = await stripe.customers.create({
      email: user.email,
      name: user.username
    });

    user.stripeCustomerId = customer.id;
    await user.save();

    // Generate JWT token
    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET);

    res.status(201).send({ user: { _id: user._id, username: user.username, email: user.email }, token });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    // Check if user exists
    const user = await User.findOne({ email });
    if (!user) {
      return res.status(400).send('Invalid email or password');
    }

    // Check password
    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) {
      return res.status(400).send('Invalid email or password');
    }

    // Generate JWT token
    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET);

    res.send({ user: { _id: user._id, username: user.username, email: user.email }, token });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.get('/api/messages', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user._id },
        { recipient: req.user._id }
      ]
    }).populate('sender', 'username profilePicture')
      .populate('recipient', 'username profilePicture')
      .sort({ timestamp: -1 });

    res.send(messages);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/messages', authenticate, async (req, res) => {
  try {
    const { recipientId, content, isPremium } = req.body;

    // Check if sender is premium if sending premium message
    if (isPremium) {
      const sender = await User.findById(req.user._id);
      if (!sender.premiumStatus) {
        return res.status(403).send('Only premium users can send premium messages');
      }
    }

    const message = new Message({
      sender: req.user._id,
      recipient: recipientId,
      content,
      isPremium
    });

    await message.save();

    // Populate sender and recipient data
    await message.populate('sender', 'username profilePicture');
    await message.populate('recipient', 'username profilePicture');

    // Emit message to recipient
    io.to(recipientId).emit('newMessage', message);

    // Create notification for recipient
    const notification = new Notification({
      user: recipientId,
      content: `New message from ${message.sender.username}`,
      type: 'message'
    });

    await notification.save();
    io.to(recipientId).emit('newNotification', notification);

    res.status(201).send(message);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.get('/api/notifications', authenticate, async (req, res) => {
  try {
    const notifications = await Notification.find({ user: req.user._id })
      .sort({ createdAt: -1 });

    res.send(notifications);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/notifications/:id/read', authenticate, async (req, res) => {
  try {
    const notification = await Notification.findOneAndUpdate(
      { _id: req.params.id, user: req.user._id },
      { isRead: true },
      { new: true }
    );

    if (!notification) {
      return res.status(404).send('Notification not found');
    }

    res.send(notification);
  } catch (err) {
    res.status(500).send(err.message);
  }
});

// Premium subscription routes
app.post('/api/premium/subscribe', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);

    if (!user.stripeCustomerId) {
      return res.status(400).send('Stripe customer not found');
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: user.stripeCustomerId,
      items: [{ price: process.env.STRIPE_PREMIUM_PRICE_ID }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent'],
    });

    res.send({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

app.post('/api/premium/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'customer.subscription.created':
    case 'customer.subscription.updated':
      const subscription = event.data.object;
      const user = await User.findOne({ stripeCustomerId: subscription.customer });

      if (user) {
        user.premiumStatus = subscription.status === 'active';
        user.premiumExpiration = new Date(subscription.current_period_end * 1000);
        await user.save();

        // Notify user
        const notification = new Notification({
          user: user._id,
          content: user.premiumStatus
            ? 'Your premium subscription is active!'
            : 'Your premium subscription has been updated.',
          type: 'premium'
        });

        await notification.save();
        io.to(user._id.toString()).emit('newNotification', notification);
      }
      break;

    case 'customer.subscription.deleted':
      const deletedSubscription = event.data.object;
      const deletedUser = await User.findOne({ stripeCustomerId: deletedSubscription.customer });

      if (deletedUser) {
        deletedUser.premiumStatus = false;
        deletedUser.premiumExpiration = null;
        await deletedUser.save();

        // Notify user
        const deletedNotification = new Notification({
          user: deletedUser._id,
          content: 'Your premium subscription has ended.',
          type: 'premium'
        });

        await deletedNotification.save();
        io.to(deletedUser._id.toString()).emit('newNotification', deletedNotification);
      }
      break;

    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  // Join user's room
  socket.on('join', (userId) => {
    socket.join(userId);
    console.log(`User ${userId} joined their room`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

