```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import io from 'socket.io-client';
import axios from 'axios';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';

// Components
import Login from './components/Login';
import Register from './components/Register';
import Chat from './components/Chat';
import Notifications from './components/Notifications';
import Premium from './components/Premium';
import Navbar from './components/Navbar';

const socket = io('http://localhost:5000');
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function App() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      axios.get('/api/user', {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(res => {
        setUser(res.data);
        socket.emit('join', res.data._id);
        setLoading(false);
      })
      .catch(() => {
        localStorage.removeItem('token');
        setLoading(false);
      });
    } else {
      setLoading(false);
    }

    // Socket.io listeners
    socket.on('newMessage', (message) => {
      setMessages(prev => [message, ...prev]);
    });

    socket.on('newNotification', (notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    return () => {
      socket.off('newMessage');
      socket.off('newNotification');
    };
  }, []);

  const handleLogin = (userData, token) => {
    setUser(userData);
    localStorage.setItem('token', token);
    socket.emit('join', userData._id);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('token');
    socket.disconnect();
  };

  if (loading) return <div>Loading...</div>;

  return (
    <Router>
      <Navbar user={user} notifications={notifications} onLogout={handleLogout} />
      <div className="container">
        <Routes>
          <Route path="/login" element={<Login onLogin={handleLogin} />} />
          <Route path="/register" element={<Register onLogin={handleLogin} />} />
          <Route path="/chat" element={
            user ? <Chat user={user} messages={messages} setMessages={setMessages} /> : <Login onLogin={handleLogin} />
          } />
          <Route path="/notifications" element={
            user ? <Notifications notifications={notifications} /> : <Login onLogin={handleLogin} />
          } />
          <Route path="/premium" element={
            user ? (
              <Elements stripe={stripePromise}>
                <Premium user={user} setUser={setUser} />
              </Elements>
            ) : <Login onLogin={handleLogin} />
          } />
          <Route path="/" element={
            user ? <Chat user={user} messages={messages} setMessages={setMessages} /> : <Login onLogin={handleLogin} />
          } />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
