```jsx
// components/Premium.js
import React, { useState } from 'react';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import axios from 'axios';

function Premium({ user, setUser }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const stripe = useStripe();
  const elements = useElements();

  const handleSubscribe = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // Create subscription on backend
      const { data } = await axios.post('/api/premium/subscribe', {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      // Confirm payment with Stripe
      const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(
        data.clientSecret,
        {
          payment_method: {
            card: elements.getElement(CardElement),
            billing_details: {
              name: user.username,
              email: user.email
            }
          }
        }
      );

      if (stripeError) {
        setError(stripeError.message);
        setLoading(false);
        return;
      }

      if (paymentIntent.status === 'succeeded') {
        // Update user state
        setUser(prev => ({ ...prev, premiumStatus: true }));
        setSuccess(true);
      }
    } catch (err) {
      setError(err.response?.data || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="premium-container">
      <h2>Premium Subscription</h2>

      {user.premiumStatus ? (
        <div className="premium-active">
          <p>Your premium subscription is active!</p>
          <p>Expires: {new Date(user.premiumExpiration).toLocaleDateString()}</p>
        </div>
      ) : (
        <form onSubmit={handleSubscribe}>
          <div className="card-element">
            <CardElement options={{
              style: {
                base: {
                  fontSize: '16px',
                  color: '#424770',
                  '::placeholder': {
                    color: '#aab7c4',
                  },
                },
                invalid: {
                  color: '#9e2146',
                },
              },
            }} />
          </div>

          {error && <div className="error-message">{error}</div>}
          {success && <div className="success-message">Subscription successful!</div>}

          <button type="submit" disabled={!stripe || loading}>
            {loading ? 'Processing...' : 'Subscribe for $9.99/month'}
          </button>
        </form>
      )}

      <div className="premium-features">
        <h3>Premium Features:</h3>
        <ul>
          <li>Send premium messages that stand out</li>
          <li>Access to exclusive content</li>
          <li>Priority customer support</li>
          <li>Ad-free experience</li>
        </ul>
      </div>
    </div>
  );
}

export default Premium;
