#### Subscription Routes (routes/subscriptions.js)

```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const Subscription = require('../models/Subscription');
const User = require('../models/User');
const Notification = require('../models/Notification');

// Create subscription
router.post('/', auth, async (req, res) => {
  try {
    const { plan, paymentMethodId } = req.body;

    // Determine plan details
    let priceId;
    let duration;

    switch (plan) {
      case 'basic':
        priceId = process.env.STRIPE_BASIC_PRICE_ID;
        duration = 30; // days
        break;
      case 'premium':
        priceId = process.env.STRIPE_PREMIUM_PRICE_ID;
        duration = 30; // days
        break;
      case 'enterprise':
        priceId = process.env.STRIPE_ENTERPRISE_PRICE_ID;
        duration = 365; // days
        break;
      default:
        return res.status(400).json({ error: 'Invalid plan' });
    }

    // Create Stripe subscription
    const customer = await stripe.customers.create({
      email: req.user.email,
      payment_method: paymentMethodId,
      invoice_settings: {
        default_payment_method: paymentMethodId,
      },
    });

    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{ price: priceId }],
      expand: ['latest_invoice.payment_intent'],
    });

    // Create subscription in database
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + duration);

    const newSubscription = new Subscription({
      user: req.user.id,
      plan,
      endDate,
      paymentMethod: paymentMethodId,
      stripeSubscriptionId: subscription.id
    });

    await newSubscription.save();

    // Update user premium status
    await User.findByIdAndUpdate(req.user.id, {
      premium: true,
      premiumExpiry: endDate
    });

    // Create notification
    const notification = new Notification({
      user: req.user.id,
      type: 'subscription',
      content: `Your ${plan} subscription has been activated!`,
      relatedId: newSubscription._id,
      onModel: 'Subscription'
    });

    await notification.save();

    res.status(201).json({
      subscription: newSubscription,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Get current subscription
router.get('/current', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.user.id,
      status: 'active'
    }).sort({ startDate: -1 });

    if (!subscription) {
      return res.status(404).json({ error: 'No active subscription found' });
    }

    res.json(subscription);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Cancel subscription
router.put('/cancel', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.user.id,
      status: 'active'
    });

    if (!subscription) {
      return res.status(404).json({ error: 'No active subscription found' });
    }

    // Cancel in Stripe
    await stripe.subscriptions.del(subscription.stripeSubscriptionId);

    // Update in database
    subscription.status = 'cancelled';
    await subscription.save();

    // Update user premium status
    await User.findByIdAndUpdate(req.user.id, {
      premium: false,
      premiumExpiry: null
    });

    // Create notification
    const notification = new Notification({
      user: req.user.id,
      type: 'subscription',
      content: 'Your subscription has been cancelled',
      relatedId: subscription._id,
      onModel: 'Subscription'
    });

    await notification.save();

    res.json({ success: true });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;
```

