#### ChatWindow (components/Chat/ChatWindow.js)

```javascript
import React, { useState, useEffect, useContext } from 'react';
import MessageList from './MessageList';
import MessageInput from './MessageInput';
import { getMessages, sendMessage } from '../../services/messages';
import { useSocket } from '../../context/SocketContext';

const ChatWindow = ({ receiverId }) => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const socket = useSocket();

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const data = await getMessages(receiverId);
        setMessages(data);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching messages:', err);
        setLoading(false);
      }
    };

    fetchMessages();

    if (socket) {
      socket.on('newMessage', (message) => {
        if (message.sender === receiverId || message.receiver === receiverId) {
          setMessages(prev => [...prev, message]);
        }
      });

      return () => {
        socket.off('newMessage');
      };
    }
  }, [receiverId, socket]);

  const handleSendMessage = async (content, isPremium) => {
    try {
      const newMessage = await sendMessage(receiverId, content, isPremium);
      setMessages(prev => [...prev, newMessage]);
    } catch (err) {
      console.error('Error sending message:', err);
    }
  };

  return (
    <div className="chat-window">
      {loading ? (
        <div>Loading messages...</div>
      ) : (
        <>
          <MessageList messages={messages} />
          <MessageInput onSendMessage={handleSendMessage} />
        </>
      )}
    </div>
  );
};

export default ChatWindow;
```

