# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code implementation for a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time communication, and React for the frontend.

## Backend Implementation (Node.js/Express)

### 1. Server Setup (`server.js`)

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(express.json());

// Database connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Models
const User = require('./models/User');
const Message = require('./models/Message');
const Notification = require('./models/Notification');
const Subscription = require('./models/Subscription');

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('joinRoom', (userId) => {
    socket.join(userId);
  });

  socket.on('sendMessage', async (data) => {
    try {
      const { senderId, receiverId, content, type } = data;

      // Save message to database
      const message = new Message({
        sender: senderId,
        receiver: receiverId,
        content,
        type,
        timestamp: new Date()
      });
      await message.save();

      // Create notification for receiver
      const notification = new Notification({
        user: receiverId,
        type: 'message',
        content: `New message from ${senderId}`,
        read: false,
        timestamp: new Date()
      });
      await notification.save();

      // Emit to receiver
      io.to(receiverId).emit('newMessage', message);
      io.to(receiverId).emit('newNotification', notification);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

// Routes
app.use('/api/auth', require('./routes/auth'));
app.use('/api/messages', require('./routes/messages'));
app.use('/api/notifications', require('./routes/notifications'));
app.use('/api/subscriptions', require('./routes/subscriptions'));

// Stripe webhook for subscription payments
app.post('/webhook', express.raw({type: 'application/json'}), async (req, res) => {
  const sig = req.headers['stripe-signature'];

  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const paymentIntent = event.data.object;
      // Update user subscription status
      await Subscription.findOneAndUpdate(
        { stripeCustomerId: paymentIntent.customer },
        { status: 'active', currentPeriodEnd: new Date(paymentIntent.lines.data[0].period.end * 1000) }
      );
      break;
    case 'customer.subscription.deleted':
      const subscription = event.data.object;
      // Update user subscription status
      await Subscription.findOneAndUpdate(
        { stripeCustomerId: subscription.customer },
        { status: 'canceled' }
      );
      break;
    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({received: true});
});

// Start server
const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

