```javascript
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import AuthContext from './context/AuthContext';
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Chat from './pages/Chat';
import Notifications from './pages/Notifications';
import Subscriptions from './pages/Subscriptions';
import Navbar from './components/Navbar';
import PrivateRoute from './components/PrivateRoute';

const socket = io('http://localhost:5000');

function App() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    // Check for existing token
    const token = localStorage.getItem('token');
    if (token) {
      // Verify token and set user
      // This would typically be an API call
      setUser({ id: '123', name: 'Test User' }); // Replace with actual user data
    }

    // Listen for notifications
    socket.on('newNotification', (notification) => {
      setNotifications(prev => [notification, ...prev]);
      setUnreadCount(prev => prev + 1);
    });

    return () => {
      socket.off('newNotification');
    };
  }, []);

  const login = (userData) => {
    setUser(userData);
    localStorage.setItem('token', userData.token);
    socket.emit('joinRoom', userData.id);
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('token');
    socket.disconnect();
  };

  const markNotificationsRead = () => {
    setUnreadCount(0);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      <Router>
        <Navbar notifications={notifications} unreadCount={unreadCount} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/chat/:userId" element={
            <PrivateRoute>
              <Chat socket={socket} />
            </PrivateRoute>
          } />
          <Route path="/notifications" element={
            <PrivateRoute>
              <Notifications
                notifications={notifications}
                markAsRead={markNotificationsRead}
              />
            </PrivateRoute>
          } />
          <Route path="/subscriptions" element={
            <PrivateRoute>
              <Subscriptions />
            </PrivateRoute>
          } />
        </Routes>
      </Router>
    </AuthContext.Provider>
  );
}

export default App;
```

### 2. Chat Component (`pages/Chat.js`)

```javascript
import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import AuthContext from '../context/AuthContext';
import Message from '../components/Message';
import MessageInput from '../components/MessageInput';

const Chat = ({ socket }) => {
  const { userId } = useParams();
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`/api/messages/${userId}`, {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });
        setMessages(res.data);
        setLoading(false);

        // Mark messages as read
        await axios.put(`/api/messages/read/${userId}`, {}, {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };

    fetchMessages();

    // Listen for new messages
    socket.on('newMessage', (message) => {
      if (message.sender === userId || message.receiver === userId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off('newMessage');
    };
  }, [userId, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = (content, type = 'text') => {
    const messageData = {
      senderId: user.id,
      receiverId: userId,
      content,
      type
    };

    socket.emit('sendMessage', messageData);
  };

  if (loading) {
    return <div className="text-center mt-8">Loading messages...</div>;
  }

  return (
    <div className="flex flex-col h-screen">
      <div className="flex-1 overflow-y-auto p-4">
        {messages.map((message) => (
          <Message
            key={message._id}
            message={message}
            isOwnMessage={message.sender === user.id}
          />
        ))}
        <div ref={messagesEndRef} />
      </div>
      <div className="p-4 border-t">
        <MessageInput onSendMessage={sendMessage} />
      </div>
    </div>
  );
};

export default Chat;
```

