#### Message Routes (`routes/messages.js`)

```javascript
const express = require('express');
const router = express.Router();
const Message = require('../models/Message');
const User = require('../models/User');
const { authenticate } = require('../middleware/auth');

// Send a message
router.post('/', authenticate, async (req, res) => {
  try {
    const { recipientId, content, isPremium } = req.body;

    // Check if recipient exists
    const recipient = await User.findById(recipientId);
    if (!recipient) {
      return res.status(404).json({ error: 'Recipient not found' });
    }

    // Check if sender is premium if sending premium message
    if (isPremium) {
      const sender = await User.findById(req.userId);
      if (!sender.premium) {
        return res.status(403).json({ error: 'Premium feature requires subscription' });
      }
    }

    // Create and save message
    const message = new Message({
      sender: req.userId,
      recipient: recipientId,
      content,
      isPremium
    });

    await message.save();

    res.status(201).json(message);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Get messages between two users
router.get('/:userId', authenticate, async (req, res) => {
  try {
    const { userId } = req.params;

    // Check if user exists
    const user = await User.findById(userId);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Get messages between current user and the specified user
    const messages = await Message.find({
      $or: [
        { sender: req.userId, recipient: userId },
        { sender: userId, recipient: req.userId }
      ]
    })
    .sort({ timestamp: 1 })
    .populate('sender', 'username profilePicture')
    .populate('recipient', 'username profilePicture');

    res.json(messages);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Mark messages as read
router.put('/read/:userId', authenticate, async (req, res) => {
  try {
    const { userId } = req.params;

    // Update all unread messages from the specified user
    await Message.updateMany(
      { sender: userId, recipient: req.userId, read: false },
      { $set: { read: true } }
    );

    res.json({ success: true });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;
```

#### Subscription Routes (`routes/subscriptions.js`)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const { authenticate } = require('../middleware/auth');

// Create a subscription checkout session
router.post('/create-checkout-session', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.userId);

    // Create or get Stripe customer
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        metadata: {
          userId: user._id.toString()
        }
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    // Create checkout session
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price: process.env.STRIPE_PREMIUM_PRICE_ID,
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${process.env.CLIENT_URL}/subscription-success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.CLIENT_URL}/subscription-cancelled`,
      customer: customerId,
      metadata: {
        userId: user._id.toString()
      }
    });

    res.json({ sessionId: session.id });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Webhook to handle successful payments
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET;

  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, endpointSecret);
  } catch (err) {
    console.error(`Webhook Error: ${err.message}`);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the checkout.session.completed event
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;

    // Find the user and update their premium status
    const userId = session.metadata.userId;
    const user = await User.findById(userId);

    if (user) {
      user.premium = true;
      user.premiumExpiry = new Date(session.expires_at * 1000);
      await user.save();
    }
  }

  // Handle subscription cancellation
  if (event.type === 'customer.subscription.deleted') {
    const subscription = event.data.object;

    // Find the user and update their premium status
    const user = await User.findOne({ stripeCustomerId: subscription.customer });

    if (user) {
      user.premium = false;
      user.premiumExpiry = null;
      await user.save();
    }
  }

  res.json({ received: true });
});

// Get current user's subscription status
router.get('/status', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({
      premium: user.premium,
      premiumExpiry: user.premiumExpiry
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;
```

### 5. Middleware

#### Authentication Middleware (`middleware/auth.js`)

```javascript
const jwt = require('jsonwebtoken');

// JWT authentication middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ error: 'No token, authorization denied' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Token is not valid' });
  }
};

// Socket.io authentication middleware
const authenticateSocket = (socket, next) => {
  const token = socket.handshake.auth.token;

  if (!token) {
    return next(new Error('Authentication error'));
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.userId = decoded.userId;
    next();
  } catch (err) {
    return next(new Error('Authentication error'));
  }
};

module.exports = { authenticate, authenticateSocket };
```

