### 4. Chat Component (`components/Chat/Chat.js`)

```jsx
import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import axios from 'axios';
import './Chat.css';

function Chat({ socket }) {
  const { user } = useAuth();
  const [contacts, setContacts] = useState([]);
  const [selectedContact, setSelectedContact] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState({});
  const messagesEndRef = useRef(null);

  // Connect to socket when component mounts
  useEffect(() => {
    if (user) {
      socket.auth = { token: localStorage.getItem('token') };
      socket.connect();

      // Listen for private messages
      socket.on('private message', (data) => {
        if (selectedContact && data.from === selectedContact._id) {
          setMessages(prev => [...prev, data]);
          // Mark message as read
          socket.emit('read', { from: data.from });
        }
      });

      // Listen for typing indicators
      socket.on('typing', ({ from }) => {
        setTypingUsers(prev => ({ ...prev, [from]: true }));
        setTimeout(() => {
          setTypingUsers(prev => {
            const newTypingUsers = { ...prev };
            delete newTypingUsers[from];
            return newTypingUsers;
          });
        }, 3000);
      });

      // Listen for read receipts
      socket.on('read', ({ from }) => {
        setMessages(prev => prev.map(msg =>
          msg.from === user.id && msg.to === from ? { ...msg, read: true } : msg
        ));
      });

      return () => {
        socket.off('private message');
        socket.off('typing');
        socket.off('read');
        socket.disconnect();
      };
    }
  }, [user, selectedContact]);

  // Fetch contacts
  useEffect(() => {
    const fetchContacts = async () => {
      try {
        const response = await axios.get('/api/users/contacts');
        setContacts(response.data);
      } catch (err) {
        console.error('Failed to fetch contacts:', err);
      }
    };

    if (user) {
      fetchContacts();
    }
  }, [user]);

  // Fetch messages when contact is selected
  useEffect(() => {
    const fetchMessages = async () => {
      if (selectedContact) {
        try {
          const response = await axios.get(`/api/messages/${selectedContact._id}`);
          setMessages(response.data);

          // Mark messages as read
          await axios.put(`/api/messages/read/${selectedContact._id}`);
        } catch (err) {
          console.error('Failed to fetch messages:', err);
        }
      }
    };

    fetchMessages();
  }, [selectedContact]);

  // Scroll to bottom when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedContact) return;

    try {
      const isPremium = newMessage.startsWith('/premium ');
      const content = isPremium ? newMessage.substring(9) : newMessage;

      const response = await axios.post('/api/messages', {
        recipientId: selectedContact._id,
        content,
        isPremium
      });

      const message = response.data;
      setMessages(prev => [...prev, message]);
      setNewMessage('');

      // Emit message via socket
      socket.emit('private message', {
        to: selectedContact._id,
        message: {
          ...message,
          from: user.id,
          to: selectedContact._id
        }
      });
    } catch (err) {
      console.error('Failed to send message:', err);
      alert(err.response?.data?.error || 'Failed to send message');
    }
  };

  const handleTyping = () => {
    if (selectedContact && !isTyping) {
      setIsTyping(true);
      socket.emit('typing', { to: selectedContact._id });

      setTimeout(() => {
        setIsTyping(false);
      }, 3000);
    }
  };

  return (
    <div className="chat-container">
      <div className="contacts-list">
        <h2>Contacts</h2>
        {contacts.map(contact => (
          <div
            key={contact._id}
            className={`contact-item ${selectedContact?._id === contact._id ? 'selected' : ''}`}
            onClick={() => setSelectedContact(contact)}
          >
            <img src={contact.profilePicture || '/default-avatar.png'} alt={contact.username} />
            <div>
              <h3>{contact.username}</h3>
              {typingUsers[contact._id] && <p className="typing-indicator">Typing...</p>}
            </div>
          </div>
        ))}
      </div>

      <div className="chat-area">
        {selectedContact ? (
          <>
            <div className="chat-header">
              <img src={selectedContact.profilePicture || '/default-avatar.png'} alt={selectedContact.username} />
              <h2>{selectedContact.username}</h2>
            </div>

            <div className="messages-container">
              {messages.map((message, index) => (
                <div
                  key={index}
                  className={`message ${message.sender._id === user.id ? 'sent' : 'received'}`}
                >
                  <div className="message-content">
                    {message.isPremium && <span className="premium-badge">⭐</span>}
                    <p>{message.content}</p>
                    {message.sender._id === user.id && (
                      <span className={`read-receipt ${message.read ? 'read' : 'unread'}`}>
                        {message.read ? '✓✓' : '✓'}
                      </span>
                    )}
                  </div>
                  <span className="message-time">
                    {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="message-form">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyDown={handleTyping}
                placeholder="Type a message..."
              />
              <button type="submit">Send</button>
            </form>
          </>
        ) : (
          <div className="no-contact-selected">
            <p>Select a contact to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default Chat;
```

