#### Chat Window (components/Chat/ChatWindow.js)

```javascript
import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { Box, Typography, Divider } from '@mui/material';
import MessageList from './MessageList';
import MessageInput from './MessageInput';
import { useAuth } from '../../hooks/useAuth';
import { useSocket } from '../../context/SocketContext';
import { getMessages, markMessagesAsRead } from '../../services/messages';

const ChatWindow = () => {
  const { userId } = useParams();
  const { user } = useAuth();
  const socket = useSocket();
  const [messages, setMessages] = useState([]);
  const [typingUsers, setTypingUsers] = useState([]);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    if (userId && user) {
      // Load messages
      getMessages(userId)
        .then(data => {
          setMessages(data);
          // Mark messages as read
          markMessagesAsRead(userId);
        })
        .catch(err => console.error('Error loading messages:', err));

      // Set up socket listeners
      if (socket) {
        socket.on('private message', (message) => {
          if (message.from === userId) {
            setMessages(prev => [...prev, {
              sender: { _id: message.from },
              content: message.message,
              timestamp: message.timestamp
            }]);
          }
        });

        socket.on('typing', ({ from }) => {
          if (from === userId) {
            setTypingUsers(prev => [...prev, from]);
          }
        });

        socket.on('stop typing', ({ from }) => {
          if (from === userId) {
            setTypingUsers(prev => prev.filter(id => id !== from));
          }
        });
      }
    }

    return () => {
      if (socket) {
        socket.off('private message');
        socket.off('typing');
        socket.off('stop typing');
      }
    };
  }, [userId, user, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (message) => {
    if (socket && userId) {
      socket.emit('private message', { to: userId, message });
    }
  };

  const handleTyping = (isTyping) => {
    if (socket && userId) {
      if (isTyping) {
        socket.emit('typing', { to: userId });
      } else {
        socket.emit('stop typing', { to: userId });
      }
    }
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Box sx={{ p: 2, borderBottom: '1px solid #e0e0e0' }}>
        <Typography variant="h6">Chat with User</Typography>
        {typingUsers.includes(userId) && (
          <Typography variant="caption" color="text.secondary">
            Typing...
          </Typography>
        )}
      </Box>

      <MessageList messages={messages} currentUserId={user?.id} />

      <div ref={messagesEndRef} />

      <Divider />

      <MessageInput
        onSendMessage={handleSendMessage}
        onTyping={handleTyping}
      />
    </Box>
  );
};

export default ChatWindow;
```

