### 2. Server Setup (`server.js`)

```javascript
require('dotenv').config();
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
const authRoutes = require('./routes/auth');
const messageRoutes = require('./routes/messages');
const userRoutes = require('./routes/users');
const subscriptionRoutes = require('./routes/subscriptions');
const { authenticateSocket } = require('./middleware/auth');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(express.json());

// Database connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
})
.then(() => console.log('Connected to MongoDB'))
.catch(err => console.error('MongoDB connection error:', err));

// Routes
app.use('/api/auth', authRoutes);
app.use('/api/messages', messageRoutes);
app.use('/api/users', userRoutes);
app.use('/api/subscriptions', subscriptionRoutes);

// Socket.io connection
io.use(authenticateSocket);

io.on('connection', (socket) => {
  console.log(`User connected: ${socket.userId}`);

  // Join user's personal room
  socket.join(socket.userId);

  // Handle private messages
  socket.on('privateMessage', async ({ recipientId, content }) => {
    try {
      const message = await createMessage(socket.userId, recipientId, content);
      io.to(recipientId).emit('newMessage', message);
      io.to(socket.userId).emit('messageSent', message);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  });

  // Handle typing indicators
  socket.on('typing', ({ recipientId }) => {
    io.to(recipientId).emit('userTyping', { userId: socket.userId });
  });

  // Handle read receipts
  socket.on('messageRead', async ({ messageId }) => {
    try {
      await markMessageAsRead(messageId);
      const message = await getMessageById(messageId);
      io.to(message.sender).emit('messageRead', { messageId });
    } catch (error) {
      console.error('Error marking message as read:', error);
    }
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.userId}`);
  });
});

// Helper functions
async function createMessage(senderId, recipientId, content) {
  const Message = mongoose.model('Message');
  const message = new Message({
    sender: senderId,
    recipient: recipientId,
    content,
    timestamp: new Date()
  });
  await message.save();
  return message;
}

async function markMessageAsRead(messageId) {
  const Message = mongoose.model('Message');
  await Message.findByIdAndUpdate(messageId, { read: true, readAt: new Date() });
}

async function getMessageById(messageId) {
  const Message = mongoose.model('Message');
  return await Message.findById(messageId);
}

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

