import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';

import Login from './components/Auth/Login';
import Register from './components/Auth/Register';
import Dashboard from './components/Dashboard/Dashboard';
import Chat from './components/Chat/Chat';
import Subscription from './components/Subscription/Subscription';
import PrivateRoute from './components/PrivateRoute';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function App() {
  const [socket, setSocket] = useState(null);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if user is logged in
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        if (token) {
          const response = await axios.get('/api/auth/me', {
            headers: { Authorization: `Bearer ${token}` }
          });
          setUser(response.data);

          // Initialize socket connection
          const newSocket = io(process.env.REACT_APP_API_URL, {
            auth: { token }
          });
          setSocket(newSocket);
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        localStorage.removeItem('token');
      } finally {
        setLoading(false);
      }
    };

    checkAuth();

    return () => {
      if (socket) {
        socket.disconnect();
      }
    };
  }, []);

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <Router>
      <Elements stripe={stripePromise}>
        <Routes>
          <Route path="/login" element={<Login setUser={setUser} setSocket={setSocket} />} />
          <Route path="/register" element={<Register setUser={setUser} setSocket={setSocket} />} />

          <Route element={<PrivateRoute user={user} />}>
            <Route path="/" element={<Dashboard user={user} socket={socket} />} />
            <Route path="/chat/:userId" element={<Chat user={user} socket={socket} />} />
            <Route path="/subscription" element={<Subscription user={user} />} />
          </Route>
        </Routes>
      </Elements>
    </Router>
  );
}

export default App;
```

