```javascript
import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';

function Chat({ user, socket }) {
  const { userId } = useParams();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [typing, setTyping] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch conversation messages
    const fetchMessages = async () => {
      try {
        const response = await axios.get(`/api/messages/${userId}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setMessages(response.data);
      } catch (error) {
        console.error('Error fetching messages:', error);
      }
    };

    fetchMessages();

    // Socket.io event listeners
    if (socket) {
      socket.on('newMessage', (message) => {
        if (message.sender === userId || message.recipient === userId) {
          setMessages(prev => [...prev, message]);
        }
      });

      socket.on('userTyping', ({ userId: typingUserId }) => {
        if (typingUserId === userId) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 3000);
        }
      });

      socket.on('messageRead', ({ messageId }) => {
        setMessages(prev => prev.map(msg =>
          msg._id === messageId ? { ...msg, read: true } : msg
        ));
      });
    }

    return () => {
      if (socket) {
        socket.off('newMessage');
        socket.off('userTyping');
        socket.off('messageRead');
      }
    };
  }, [userId, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    try {
      // Send message via socket
      socket.emit('privateMessage', {
        recipientId: userId,
        content: newMessage
      });

      setNewMessage('');
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const handleTyping = () => {
    if (!typing) {
      setTyping(true);
      socket.emit('typing', { recipientId: userId });
      setTimeout(() => setTyping(false), 3000);
    }
  };

  return (
    <div className="chat-container">
      <div className="messages">
        {messages.map(message => (
          <div
            key={message._id}
            className={`message ${message.sender === user._id ? 'sent' : 'received'}`}
          >
            <p>{message.content}</p>
            <span className="timestamp">
              {new Date(message.timestamp).toLocaleTimeString()}
              {message.sender === user._id && message.read && ' ✓✓'}
            </span>
          </div>
        ))}
        {isTyping && <div className="typing-indicator">User is typing...</div>}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={handleTyping}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

export default Chat;
```

### 4. Subscription Component (`components/Subscription/Subscription.js`)

```javascript
import React, { useState, useEffect } from 'react';
import { CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import axios from 'axios';

function Subscription({ user }) {
  const stripe = useStripe();
  const elements = useElements();
  const [plan, setPlan] = useState('premium');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);
  const [currentPlan, setCurrentPlan] = useState('free');

  useEffect(() => {
    // Fetch current subscription
    const fetchSubscription = async () => {
      try {
        const response = await axios.get('/api/subscriptions/current', {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setCurrentPlan(response.data.plan);
      } catch (error) {
        console.error('Error fetching subscription:', error);
      }
    };

    fetchSubscription();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    if (!stripe || !elements) {
      setLoading(false);
      return;
    }

    try {
      // Create payment method
      const { error: stripeError, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: elements.getElement(CardElement),
      });

      if (stripeError) {
        setError(stripeError.message);
        setLoading(false);
        return;
      }

      // Create subscription
      const response = await axios.post('/api/subscriptions/create', {
        paymentMethodId: paymentMethod.id,
        plan
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      // Confirm payment
      const { error: confirmError } = await stripe.confirmCardPayment(
        response.data.clientSecret
      );

      if (confirmError) {
        setError(confirmError.message);
        setLoading(false);
        return;
      }

      setSuccess(true);
      setCurrentPlan(plan);
    } catch (error) {
      console.error('Subscription error:', error);
      setError(error.response?.data?.message || 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="subscription-container">
      <h2>Upgrade Your Account</h2>

      {currentPlan !== 'free' && (
        <div className="current-plan">
          <p>Current Plan: {currentPlan.charAt(0).toUpperCase() + currentPlan.slice(1)}</p>
        </div>
      )}

      {success ? (
        <div className="success-message">
          <h3>Subscription Successful!</h3>
          <p>Thank you for upgrading to our {plan} plan.</p>
        </div>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="plan-selection">
            <label>
              <input
                type="radio"
                value="premium"
                checked={plan === 'premium'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Premium Plan - $9.99/month
            </label>
            <label>
              <input
                type="radio"
                value="pro"
                checked={plan === 'pro'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Pro Plan - $19.99/month
            </label>
          </div>

          <div className="payment-form">
            <CardElement options={{
              style: {
                base: {
                  fontSize: '16px',
                  color: '#424770',
                  '::placeholder': {
                    color: '#aab7c4',
                  },
                },
                invalid: {
                  color: '#9e2146',
                },
              },
            }} />

            {error && <div className="error-message">{error}</div>}

            <button
              type="submit"
              disabled={!stripe || loading}
              className="subscribe-button"
            >
              {loading ? 'Processing...' : 'Subscribe'}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

export default Subscription;
```

