          <ListItem
            key={notification._id}
            sx={{
              backgroundColor: notification.read ? 'transparent' : '#f5f5f5',
              borderRadius: 1,
              mb: 1
            }}
            secondaryAction={
              !notification.read && (
                <IconButton
                  edge="end"
                  onClick={() => markAsRead(notification._id)}
                >
