```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const PremiumFeature = require('../models/PremiumFeature');

// Get available premium features
router.get('/features', async (req, res) => {
  try {
    const features = await PremiumFeature.find();
    res.json(features);
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Create Stripe checkout session
router.post('/create-checkout-session', auth, async (req, res) => {
  try {
    const { featureId } = req.body;

    const feature = await PremiumFeature.findById(featureId);
    if (!feature) {
      return res.status(404).json({ msg: 'Feature not found' });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price: feature.stripePriceId,
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${process.env.CLIENT_URL}/premium/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.CLIENT_URL}/premium/cancel`,
      metadata: {
        userId: req.user.id,
        featureId: featureId
      }
    });

    res.json({ sessionId: session.id });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Webhook to handle successful payments
router.post('/webhook', express.raw({type: 'application/json'}), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    console.error(err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the checkout.session.completed event
  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;

    // Fulfill the purchase
    try {
      const userId = session.metadata.userId;
      const featureId = session.metadata.featureId;

      const feature = await PremiumFeature.findById(featureId);
      if (!feature) {
        console.error('Feature not found');
        return res.status(404).json({ msg: 'Feature not found' });
      }

      // Update user's premium status
      const user = await User.findById(userId);
      if (!user) {
        console.error('User not found');
        return res.status(404).json({ msg: 'User not found' });
      }

      // Calculate expiration date
      const duration = feature.duration === 'monthly' ? 30 : 365;
      const expirationDate = new Date();
      expirationDate.setDate(expirationDate.getDate() + duration);

      user.isPremium = true;
      user.premiumExpiration = expirationDate;
      await user.save();

      console.log(`User ${userId} upgraded to premium`);
    } catch (err) {
      console.error('Error processing webhook:', err.message);
    }
  }

  res.json({received: true});
});

module.exports = router;
