```javascript
import React, { useContext, useEffect, useState } from 'react';
import MessageContext from '../../context/message/messageContext';
import AuthContext from '../../context/auth/authContext';
import NotificationContext from '../../context/notification/notificationContext';

const Messages = ({ socket }) => {
  const messageContext = useContext(MessageContext);
  const authContext = useContext(AuthContext);
  const notificationContext = useContext(NotificationContext);

  const { messages, getMessages, sendMessage } = messageContext;
  const { user } = authContext;
  const { getNotifications } = notificationContext;

  const [messageContent, setMessageContent] = useState('');
  const [receiverId, setReceiverId] = useState('');

  useEffect(() => {
    getMessages();
    getNotifications();

    // Join user's room
    if (user) {
      socket.emit('joinRoom', user._id);
    }

    // Listen for new messages
    socket.on('receiveMessage', (message) => {
      getMessages();
      getNotifications();
    });

    // Clean up
    return () => {
      socket.off('receiveMessage');
    };
  }, [user]);

  const onSubmit = (e) => {
    e.preventDefault();
    if (messageContent.trim() === '' || receiverId.trim() === '') return;

    const messageData = {
      senderId: user._id,
      receiverId,
      content: messageContent
    };

    sendMessage(messageData, socket);
    setMessageContent('');
  };

  return (
    <div className="messages-container">
      <h2>Messages</h2>

      <div className="message-list">
        {messages.map((message) => (
          <div key={message._id} className={`message ${message.sender === user._id ? 'sent' : 'received'}`}>
            <p>{message.content}</p>
            <small>{new Date(message.timestamp).toLocaleString()}</small>
          </div>
        ))}
      </div>

      <form onSubmit={onSubmit}>
        <div>
          <label>Receiver ID:</label>
          <input
            type="text"
            value={receiverId}
            onChange={(e) => setReceiverId(e.target.value)}
            required
          />
        </div>
        <div>
          <label>Message:</label>
          <input
            type="text"
            value={messageContent}
            onChange={(e) => setMessageContent(e.target.value)}
            required
          />
        </div>
        <button type="submit">Send Message</button>
      </form>
    </div>
  );
};

export default Messages;
```

