    if (sessionId) {
      try {
        // Verify the session
        const res = await axios.get(`/api/premium/session/${sessionId}`);
        if (res.data.status === 'complete') {
          setSuccess(true);
          // Refresh user data
          await loadUser();
        }
      } catch (err) {
        console.error('Error verifying session:', err);
        setError('Failed to verify payment');
      }
    }
  };

  useEffect(() => {
    handleSuccess();
  }, []);

  if (success) {
    return (
      <div className="premium-success">
        <h2>Thank You for Your Purchase!</h2>
        <p>Your premium features are now active.</p>
      </div>
    );
  }

  return (
    <div className="premium-container">
      <h2>Premium Features</h2>

      {user && user.isPremium && (
        <div className="premium-status">
          <p>You are a premium member!</p>
          <p>Premium expires on: {new Date(user.premiumExpiration).toLocaleDateString()}</p>
        </div>
      )}

      {error && <div className="error-message">{error}</div>}

      <div className="features-list">
        {features.map((feature) => (
          <div
            key={feature._id}
            className={`feature-card ${selectedFeature && selectedFeature._id === feature._id ? 'selected' : ''}`}
            onClick={() => setSelectedFeature(feature)}
          >
            <h3>{feature.name}</h3>
            <p>{feature.description}</p>
            <p>Price: ${feature.price} / {feature.duration}</p>
          </div>
        ))}
      </div>

      {selectedFeature && (
        <form onSubmit={handleSubmit}>
          <div className="payment-form">
            <h3>Complete Your Purchase</h3>
            <div className="payment-details">
              <p>Feature: {selectedFeature.name}</p>
              <p>Price: ${selectedFeature.price} / {selectedFeature.duration}</p>
            </div>

            <button type="submit" disabled={!stripe || loading}>
              {loading ? 'Processing...' : 'Pay Now'}
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default Premium;
