### 2. Chat Component (`pages/Chat.js`)

```javascript
import React, { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../context/AuthContext';
import { ChatContext } from '../context/ChatContext';
import { NotificationContext } from '../context/NotificationContext';
import MessageList from '../components/MessageList';
import MessageInput from '../components/MessageInput';
import UserList from '../components/UserList';

function Chat() {
  const { user } = useContext(AuthContext);
  const { messages, setMessages, socket } = useContext(ChatContext);
  const { notifications, setNotifications } = useContext(NotificationContext);
  const [selectedUser, setSelectedUser] = useState(null);

  useEffect(() => {
    if (socket && user) {
      // Join user's room
      socket.emit('joinRoom', user.id);

      // Listen for new messages
      socket.on('newMessage', (message) => {
        if (message.receiver === user.id || message.sender === user.id) {
          setMessages(prev => [...prev, message]);
        }
      });

      // Listen for new notifications
      socket.on('newNotification', (notification) => {
        setNotifications(prev => [...prev, notification]);
      });
    }

    return () => {
      if (socket) {
        socket.off('newMessage');
        socket.off('newNotification');
      }
    };
  }, [socket, user, setMessages, setNotifications]);

  const handleSendMessage = (content) => {
    if (selectedUser && content.trim()) {
      const messageData = {
        senderId: user.id,
        receiverId: selectedUser.id,
        content
      };
      socket.emit('sendMessage', messageData);
    }
  };

  return (
    <div className="chat-container">
      <div className="user-list">
        <UserList onSelectUser={setSelectedUser} />
      </div>
      <div className="chat-area">
        {selectedUser ? (
          <>
            <MessageList messages={messages.filter(m =>
              (m.sender === selectedUser.id && m.receiver === user.id) ||
              (m.sender === user.id && m.receiver === selectedUser.id)
            )} />
            <MessageInput onSendMessage={handleSendMessage} />
          </>
        ) : (
          <div className="select-user-prompt">
            Select a user to start chatting
          </div>
        )}
      </div>
    </div>
  );
}

export default Chat;
