#### Payment Routes (`routes/payments.js`)

```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const Subscription = require('../models/Subscription');

// Create subscription
router.post('/subscribe', auth, async (req, res) => {
  try {
    const { plan, paymentMethodId } = req.body;

    // Get user
    const user = await User.findById(req.user.id);

    // Create customer if not exists
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        payment_method: paymentMethodId,
        invoice_settings: {
          default_payment_method: paymentMethodId
        }
      });

      user.stripeCustomerId = customer.id;
      await user.save();
      customerId = customer.id;
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{
        price: getPriceId(plan)
      }],
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: req.user.id,
      plan,
      stripeSubscriptionId: subscription.id,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    // Update user premium status
    user.premium = true;
    user.premiumExpiration = new Date(subscription.current_period_end * 1000);
    await user.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Get subscription status
router.get('/subscription', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({ user: req.user.id });

    if (!subscription) {
      return res.json({ active: false });
    }

    res.json({
      active: true,
      plan: subscription.plan,
      currentPeriodEnd: subscription.currentPeriodEnd
    });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Cancel subscription
router.post('/cancel', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({ user: req.user.id });

    if (!subscription) {
      return res.status(404).json({ msg: 'No active subscription found' });
    }

    // Cancel in Stripe
    await stripe.subscriptions.del(subscription.stripeSubscriptionId);

    // Update in database
    subscription.status = 'canceled';
    await subscription.save();

    // Update user
    const user = await User.findById(req.user.id);
    user.premium = false;
    user.premiumExpiration = null;
    await user.save();

    res.json({ msg: 'Subscription canceled' });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

function getPriceId(plan) {
  const prices = {
    basic: process.env.STRIPE_BASIC_PRICE_ID,
    premium: process.env.STRIPE_PREMIUM_PRICE_ID,
    enterprise: process.env.STRIPE_ENTERPRISE_PRICE_ID
  };

  return prices[plan];
}

module.exports = router;
```

