#### Chat Window (`components/Chat/ChatWindow.js`)

```javascript
import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import SocketContext from '../../context/SocketContext';
import MessageList from './MessageList';
import MessageInput from './MessageInput';

const ChatWindow = ({ receiverId }) => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const socket = useContext(SocketContext);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`/api/messages/${receiverId}`);
        setMessages(res.data);
        setLoading(false);

        // Mark messages as read
        await axios.put(`/api/messages/read/${receiverId}`);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };

    fetchMessages();
  }, [receiverId]);

  useEffect(() => {
    if (socket) {
      socket.on('newMessage', (message) => {
        if (
          (message.sender === receiverId && message.receiver === user._id) ||
          (message.sender === user._id && message.receiver === receiverId)
        ) {
          setMessages(prevMessages => [...prevMessages, message]);
        }
      });

      return () => {
        socket.off('newMessage');
      };
    }
  }, [socket, receiverId]);

  const handleSendMessage = (content) => {
    if (socket) {
      socket.emit('sendMessage', {
        senderId: user._id,
        receiverId,
        content
      });
    }
  };

  if (loading) return <div>Loading messages...</div>;

  return (
    <div className="chat-window">
      <MessageList messages={messages} />
      <MessageInput onSendMessage={handleSendMessage} />
    </div>
  );
};

export default ChatWindow;
