// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';
import { Elements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';

// Components
import Login from './components/Login';
import Register from './components/Register';
import Chat from './components/Chat';
import Profile from './components/Profile';
import Notifications from './components/Notifications';
import PremiumCheckout from './components/PremiumCheckout';
import Success from './components/Success';
import Cancel from './components/Cancel';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function App() {
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  // Initialize socket connection
  useEffect(() => {
    const newSocket = io(process.env.REACT_APP_API_URL);
    setSocket(newSocket);

    return () => newSocket.close();
  }, []);

  // Auth state management
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      axios.get(`${process.env.REACT_APP_API_URL}/api/profile`, {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(response => {
        setUser(response.data);
        if (socket) {
          socket.emit('join', response.data._id);
        }
      })
      .catch(() => {
        localStorage.removeItem('token');
      });
    }
  }, [socket]);

  // Fetch notifications
  useEffect(() => {
    if (user) {
      axios.get(`${process.env.REACT_APP_API_URL}/api/notifications`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      })
      .then(response => {
        setNotifications(response.data);
        setUnreadCount(response.data.filter(n => !n.read).length);
      });
    }
  }, [user]);

  // Socket event listeners
  useEffect(() => {
    if (socket && user) {
      socket.on('notification', (notification) => {
        setNotifications(prev => [notification, ...prev]);
        setUnreadCount(prev => prev + 1);
      });

      return () => {
        socket.off('notification');
      };
    }
  }, [socket, user]);

  const handleLogin = (userData, token) => {
    localStorage.setItem('token', token);
    setUser(userData);
    if (socket) {
      socket.emit('join', userData._id);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUser(null);
    if (socket) {
      socket.emit('leave', user._id);
    }
  };

  const markNotificationAsRead = (id) => {
    axios.put(`${process.env.REACT_APP_API_URL}/api/notifications/${id}/read`, {}, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    })
    .then(() => {
      setNotifications(prev => prev.map(n =>
        n._id === id ? { ...n, read: true } : n
      ));
      setUnreadCount(prev => prev - 1);
    });
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/login" element={<Login onLogin={handleLogin} />} />
          <Route path="/register" element={<Register onLogin={handleLogin} />} />
          <Route path="/chat" element={
            user ? (
              <Chat
                user={user}
                socket={socket}
                notifications={notifications}
                unreadCount={unreadCount}
                onLogout={handleLogout}
                onMarkAsRead={markNotificationAsRead}
              />
            ) : (
              <Login onLogin={handleLogin} />
            )
          } />
          <Route path="/profile" element={
            user ? (
              <Profile user={user} onLogout={handleLogout} />
            ) : (
              <Login onLogin={handleLogin} />
            )
          } />
          <Route path="/notifications" element={
            user ? (
              <Notifications
                notifications={notifications}
                onMarkAsRead={markNotificationAsRead}
                onLogout={handleLogout}
              />
            ) : (
              <Login onLogin={handleLogin} />
            )
          } />
          <Route path="/premium" element={
            user ? (
              <Elements stripe={stripePromise}>
                <PremiumCheckout user={user} />
              </Elements>
            ) : (
              <Login onLogin={handleLogin} />
            )
          } />
          <Route path="/success" element={<Success />} />
          <Route path="/cancel" element={<Cancel />} />
          <Route path="/" element={
            user ? (
              <Chat
                user={user}
                socket={socket}
                notifications={notifications}
                unreadCount={unreadCount}
                onLogout={handleLogout}
                onMarkAsRead={markNotificationAsRead}
              />
            ) : (
              <Login onLogin={handleLogin} />
            )
          } />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
```

