#### Subscription Routes (routes/subscriptions.js)
```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const Subscription = require('../models/Subscription');
const User = require('../models/User');

// Get subscription plans
router.get('/plans', async (req, res) => {
  try {
    const plans = [
      {
        id: 'basic',
        name: 'Basic',
        price: 4.99,
        features: ['Basic messaging', '10GB storage']
      },
      {
        id: 'premium',
        name: 'Premium',
        price: 9.99,
        features: ['All Basic features', '50GB storage', 'HD video calls']
      },
      {
        id: 'pro',
        name: 'Pro',
        price: 19.99,
        features: ['All Premium features', '200GB storage', 'Priority support']
      }
    ];

    res.json(plans);
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Create subscription
router.post('/subscribe', auth, async (req, res) => {
  try {
    const { planId, paymentMethodId } = req.body;

    // Get user
    const user = await User.findById(req.user.id);

    // Create customer in Stripe
    let customer;
    if (!user.stripeCustomerId) {
      customer = await stripe.customers.create({
        email: user.email,
        payment_method: paymentMethodId,
        invoice_settings: {
          default_payment_method: paymentMethodId
        }
      });

      user.stripeCustomerId = customer.id;
      await user.save();
    } else {
      customer = await stripe.customers.retrieve(user.stripeCustomerId);
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{ price: process.env[`STRIPE_${planId.toUpperCase()}_PRICE_ID`] }],
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: req.user.id,
      stripeSubscriptionId: subscription.id,
      plan: planId,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    // Update user premium status
    user.premium = true;
    user.premiumExpiration = new Date(subscription.current_period_end * 1000);
    await user.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Get user subscription
router.get('/current', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.user.id,
      status: 'active'
    });

    if (!subscription) {
      return res.json(null);
    }

    res.json(subscription);
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

// Cancel subscription
router.post('/cancel', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.user.id,
      status: 'active'
    });

    if (!subscription) {
      return res.status(404).json({ msg: 'No active subscription found' });
    }

    // Cancel in Stripe
    await stripe.subscriptions.del(subscription.stripeSubscriptionId);

    // Update in database
    subscription.status = 'canceled';
    await subscription.save();

    // Update user premium status
    const user = await User.findById(req.user.id);
    user.premium = false;
    await user.save();

    res.json({ msg: 'Subscription canceled successfully' });
  } catch (err) {
    console.error(err.message);
    res.status(500).send('Server error');
  }
});

module.exports = router;
