                </PrivateRoute>
              }
            />
            <Route
              path="/subscriptions"
              element={
                <PrivateRoute>
                  <Subscriptions />
                </PrivateRoute>
              }
            />
          </Routes>
        </Router>
      </ChatContext.Provider>
    </AuthContext.Provider>
  );
}

