### 2. Chat Component (pages/Chat.js)
```javascript
import React, { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import ChatContext from '../context/ChatContext';
import MessageList from '../components/MessageList';
import MessageInput from '../components/MessageInput';
import UserList from '../components/UserList';

const Chat = () => {
  const { authState } = useContext(AuthContext);
  const { chatState, setChatState, socket } = useContext(ChatContext);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  // Load users and messages
  useEffect(() => {
    const loadData = async () => {
      try {
        // Load users
        const usersRes = await fetch('http://localhost:5000/api/users', {
          headers: {
            'x-auth-token': authState.token
          }
        });
        const usersData = await usersRes.json();
        setUsers(usersData);

        // Join socket room
        socket.emit('joinRoom', authState.user._id);

        // Listen for new messages
        socket.on('newMessage', (message) => {
          setChatState(prevState => ({
            ...prevState,
            messages: [...prevState.messages, message]
          }));
        });

        // Listen for new notifications
        socket.on('newNotification', (notification) => {
          setChatState(prevState => ({
            ...prevState,
            notifications: [...prevState.notifications, notification]
          }));
        });

        setLoading(false);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };

    if (authState.isAuthenticated) {
      loadData();
    }

    // Cleanup
    return () => {
      socket.off('newMessage');
      socket.off('newNotification');
    };
  }, [authState, socket, setChatState]);

  // Load messages when selected user changes
  useEffect(() => {
    const loadMessages = async () => {
      if (chatState.selectedUser) {
        try {
          const res = await fetch(`http://localhost:5000/api/messages/${chatState.selectedUser._id}`, {
            headers: {
              'x-auth-token': authState.token
            }
          });
          const data = await res.json();
          setChatState(prevState => ({
            ...prevState,
            messages: data
          }));

          // Mark messages as read
          await fetch(`http://localhost:5000/api/messages/read/${chatState.selectedUser._id}`, {
            method: 'PUT',
            headers: {
              'x-auth-token': authState.token
            }
          });
        } catch (err) {
          console.error(err);
        }
      }
    };

    loadMessages();
  }, [chatState.selectedUser, authState.token, setChatState]);

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="chat-container">
      <div className="user-list">
        <UserList users={users} />
      </div>
      <div className="chat-area">
        {chatState.selectedUser ? (
          <>
            <div className="message-header">
              <h2>{chatState.selectedUser.username}</h2>
            </div>
            <MessageList messages={chatState.messages} currentUserId={authState.user._id} />
            <MessageInput />
          </>
        ) : (
          <div className="no-conversation">
            <p>Select a user to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Chat;
```

