```javascript
import React, { useState, useEffect, useContext } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import AuthContext from '../context/AuthContext';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const Subscriptions = () => {
  const { authState } = useContext(AuthContext);
  const [plans, setPlans] = useState([]);
  const [currentSubscription, setCurrentSubscription] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Load plans
        const plansRes = await fetch('http://localhost:5000/api/subscriptions/plans');
        const plansData = await plansRes.json();
        setPlans(plansData);

        // Load current subscription
        const subscriptionRes = await fetch('http://localhost:5000/api/subscriptions/current', {
          headers: {
            'x-auth-token': authState.token
          }
        });
        const subscriptionData = await subscriptionRes.json();
        setCurrentSubscription(subscriptionData);

        setLoading(false);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };

    loadData();
  }, [authState.token]);

  const handleSubscribe = async (planId) => {
    try {
      const stripe = await stripePromise;

      // Create payment method
      const { error, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: {
          number: '4242424242424242', // Test card number
          exp_month: 12,
          exp_year: 2025,
          cvc: '123',
        },
      });

      if (error) {
        console.error(error);
        return;
      }

      // Create subscription
      const res = await fetch('http://localhost:5000/api/subscriptions/subscribe', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': authState.token
        },
        body: JSON.stringify({
          planId,
          paymentMethodId: paymentMethod.id
        })
      });

      const data = await res.json();

      // Confirm payment
      const { error: confirmError } = await stripe.confirmCardPayment(data.clientSecret);

      if (confirmError) {
        console.error(confirmError);
        return;
      }

      // Refresh subscription data
      const subscriptionRes = await fetch('http://localhost:5000/api/subscriptions/current', {
        headers: {
          'x-auth-token': authState.token
        }
      });
      const subscriptionData = await subscriptionRes.json();
      setCurrentSubscription(subscriptionData);

      alert('Subscription successful!');
    } catch (err) {
      console.error(err);
      alert('Subscription failed. Please try again.');
    }
  };

  const handleCancel = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/subscriptions/cancel', {
        method: 'POST',
        headers: {
          'x-auth-token': authState.token
        }
      });

      if (res.ok) {
        setCurrentSubscription(null);
        alert('Subscription canceled successfully');
      } else {
        alert('Failed to cancel subscription');
      }
    } catch (err) {
      console.error(err);
      alert('Failed to cancel subscription');
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="subscriptions-container">
      <h1>Subscriptions</h1>

      {currentSubscription ? (
        <div className="current-subscription">
          <h2>Your Current Plan: {currentSubscription.plan}</h2>
          <p>Expires: {new Date(currentSubscription.currentPeriodEnd).toLocaleDateString()}</p>
          <button onClick={handleCancel}>Cancel Subscription</button>
        </div>
      ) : (
        <div className="plans">
          <h2>Choose a Plan</h2>
          <div className="plan-cards">
            {plans.map(plan => (
              <div key={plan.id} className="plan-card">
                <h3>{plan.name}</h3>
                <p className="price">${plan.price}/month</p>
                <ul>
                  {plan.features.map((feature, index) => (
                    <li key={index}>{feature}</li>
                  ))}
                </ul>
                <button onClick={() => handleSubscribe(plan.id)}>Subscribe</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Subscriptions;
