```javascript
// routes/messages.js
const express = require('express');
const router = express.Router();
const Message = require('../models/Message');
const auth = require('../middleware/auth');

// Send message
router.post('/', auth, async (req, res) => {
  try {
    const { receiverId, content, isPremium } = req.body;
    const senderId = req.userId;

    // Check if sender is premium if sending premium message
    if (isPremium) {
      const user = await User.findById(senderId);
      if (!user.premiumStatus) {
        return res.status(403).json({ message: 'Premium feature requires premium membership' });
      }
    }

    const message = new Message({
      sender: senderId,
      receiver: receiverId,
      content,
      isPremium
    });

    await message.save();

    // Emit real-time notification
    req.io.to(receiverId).emit('newMessage', {
      sender: senderId,
      content,
      isPremium,
      createdAt: message.createdAt
    });

    res.status(201).json(message);
  } catch (error) {
    res.status(500).json({ message: 'Server error' });
  }
});

// Get messages
router.get('/:userId', auth, async (req, res) => {
  try {
    const userId = req.params.userId;
    const currentUserId = req.userId;

    const messages = await Message.find({
      $or: [
        { sender: currentUserId, receiver: userId },
        { sender: userId, receiver: currentUserId }
      ]
    }).sort({ createdAt: 1 });

    // Mark messages as read
    await Message.updateMany(
      { sender: userId, receiver: currentUserId, read: false },
      { read: true }
    );

    res.json(messages);
  } catch (error) {
    res.status(500).json({ message: 'Server error' });
  }
});

module.exports = router;
