import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import io from 'socket.io-client';
import axios from 'axios';

import Login from './components/Login';
import Register from './components/Register';
import Dashboard from './components/Dashboard';
import Chat from './components/Chat';
import Premium from './components/Premium';

const socket = io('http://localhost:3000');

function App() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    // Check for existing token
    const token = localStorage.getItem('token');
    if (token) {
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      axios.get('/api/auth/me')
        .then(res => setUser(res.data))
        .catch(() => localStorage.removeItem('token'));
    }

    // Set up socket listeners
    socket.on('newMessage', (message) => {
      setNotifications(prev => [...prev, {
        type: 'message',
        content: `New message from ${message.sender}`,
        timestamp: new Date()
      }]);
    });

    return () => {
      socket.off('newMessage');
    };
  }, []);

  const login = async (credentials) => {
    try {
      const res = await axios.post('/api/auth/login', credentials);
      localStorage.setItem('token', res.data.token);
      axios.defaults.headers.common['Authorization'] = `Bearer ${res.data.token}`;
      const userRes = await axios.get('/api/auth/me');
      setUser(userRes.data);
      socket.emit('join', userRes.data._id);
      return true;
    } catch (error) {
      console.error('Login failed:', error);
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    delete axios.defaults.headers.common['Authorization'];
    setUser(null);
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/login" element={<Login onLogin={login} />} />
          <Route path="/register" element={<Register />} />
          <Route path="/dashboard" element={<Dashboard user={user} onLogout={logout} />} />
          <Route path="/chat/:userId" element={<Chat user={user} socket={socket} />} />
          <Route path="/premium" element={<Premium user={user} />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
