```javascript
// src/components/ChatWindow.js
import React, { useState, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { w3cwebsocket as W3CWebSocket } from 'websocket';

const ChatWindow = ({ recipientId }) => {
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [notifications, setNotifications] = useState([]);
  const user = useSelector(state => state.auth.user);
  const client = useRef(null);

  useEffect(() => {
    // Connect to WebSocket
    client.current = new W3CWebSocket(
      `ws://${window.location.host}/ws/chat/?token=${localStorage.getItem('token')}`
    );

    client.current.onopen = () => {
      console.log('WebSocket Client Connected');
    };

    client.current.onmessage = (message) => {
      const data = JSON.parse(message.data);

      if (data.type === 'message') {
        if (data.message.sender === recipientId || data.message.sender === user.id) {
          setMessages(prev => [...prev, data.message]);
        }
      } else if (data.type === 'notification') {
        setNotifications(prev => [...prev, data.notification]);
      }
    };

    return () => {
      if (client.current) {
        client.current.close();
      }
    };
  }, [recipientId, user.id]);

  const sendMessage = () => {
    if (inputValue.trim() === '') return;

    const message = {
      type: 'message',
      recipient_id: recipientId,
      content: inputValue
    };

    client.current.send(JSON.stringify(message));
    setInputValue('');
  };

  return (
    <div className="chat-container">
      <div className="messages">
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.sender === user.id ? 'sent' : 'received'}`}>
            <p>{msg.content}</p>
            <span className="timestamp">{new Date(msg.timestamp).toLocaleTimeString()}</span>
          </div>
        ))}
      </div>
      <div className="input-area">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Type a message..."
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
};

export default ChatWindow;
