# routes/message_routes.py
from flask import Blueprint, render_template, request, jsonify
from flask_login import login_required, current_user
from models import Message, Notification, User
from app import db, socketio
from datetime import datetime

messages = Blueprint('messages', __name__)

@messages.route('/chat/<int:user_id>')
@login_required
def chat(user_id):
    other_user = User.query.get_or_404(user_id)
    messages = Message.query.filter(
        ((Message.sender_id == current_user.id) & (Message.receiver_id == user_id)) |
        ((Message.sender_id == user_id) & (Message.receiver_id == current_user.id))
    ).order_by(Message.created_at).all()

    return render_template('chat.html', messages=messages, other_user=other_user)

@socketio.on('send_message')
def handle_send_message(data):
    sender_id = current_user.id
    receiver_id = data['receiver_id']
    content = data['content']

    message = Message(
        sender_id=sender_id,
        receiver_id=receiver_id,
        content=content,
        created_at=datetime.utcnow()
    )
    db.session.add(message)
    db.session.commit()

    # Create notification for receiver
    notification = Notification(
        user_id=receiver_id,
        content=f"New message from {current_user.username}",
        notification_type='message'
    )
    db.session.add(notification)
    db.session.commit()

    # Emit to both users
    socketio.emit('receive_message', {
        'sender_id': sender_id,
        'receiver_id': receiver_id,
        'content': content,
        'created_at': message.created_at.isoformat()
    }, room=str(receiver_id))

    socketio.emit('receive_message', {
        'sender_id': sender_id,
        'receiver_id': receiver_id,
        'content': content,
        'created_at': message.created_at.isoformat()
    }, room=str(sender_id))
