## Monetization System

```python
# routes/monetization_routes.py
from flask import Blueprint, render_template, request, redirect, url_for, flash
from flask_login import login_required, current_user
from models import SubscriptionPlan, Transaction
from app import db
import stripe
import os

monetization = Blueprint('monetization', __name__)

# Configure Stripe
stripe.api_key = os.getenv('STRIPE_SECRET_KEY')

@monetization.route('/pricing')
def pricing():
    plans = SubscriptionPlan.query.filter_by(is_active=True).all()
    return render_template('pricing.html', plans=plans)

@monetization.route('/checkout/<int:plan_id>', methods=['GET', 'POST'])
@login_required
def checkout(plan_id):
    plan = SubscriptionPlan.query.get_or_404(plan_id)

    if request.method == 'POST':
        try:
            # Create Stripe checkout session
            session = stripe.checkout.Session.create(
                payment_method_types=['card'],
                line_items=[{
                    'price_data': {
                        'currency': 'usd',
                        'product_data': {
                            'name': plan.name,
                        },
                        'unit_amount': int(plan.price * 100),
                    },
                    'quantity': 1,
                }],
                mode='payment',
                success_url=url_for('monetization.payment_success', plan_id=plan.id, _external=True),
                cancel_url=url_for('monetization.pricing', _external=True),
            )

            # Create transaction record
            transaction = Transaction(
                user_id=current_user.id,
                plan_id=plan.id,
                amount=plan.price,
                status='pending',
                transaction_id=session.id
            )
            db.session.add(transaction)
            db.session.commit()

            return redirect(session.url, code=303)

        except Exception as e:
            flash(f'Payment failed: {str(e)}')
            return redirect(url_for('monetization.pricing'))

    return render_template('checkout.html', plan=plan)

@monetization.route('/payment-success/<int:plan_id>')
@login_required
def payment_success(plan_id):
    plan = SubscriptionPlan.query.get_or_404(plan_id)

    # Update user subscription
    current_user.is_premium = True
    current_user.premium_expiry = datetime.utcnow() + timedelta(days=plan.duration_days)

    # Update transaction status
    transaction = Transaction.query.filter_by(
        user_id=current_user.id,
        plan_id=plan.id,
        status='pending'
    ).first()

    if transaction:
        transaction.status = 'completed'

    db.session.commit()

    flash('Payment successful! Your premium features are now active.')
    return redirect(url_for('main.index'))
