# messaging_routes.py
@app.route('/messages', methods=['GET'])
def get_messages():
    token = request.headers.get('Authorization')
    if not token:
        return jsonify({'message': 'Token is missing'}), 401

    try:
        data = jwt.decode(token, app.config['SECRET_KEY'])
        user_id = data['user_id']
    except:
        return jsonify({'message': 'Token is invalid'}), 401

    messages = Message.query.filter(
        (Message.user_id == user_id) | (Message.recipient_id == user_id)
    ).order_by(Message.timestamp.desc()).all()

    return jsonify([{
        'id': msg.id,
        'content': msg.content,
        'timestamp': msg.timestamp.isoformat(),
        'sender_id': msg.user_id,
        'recipient_id': msg.recipient_id,
        'is_read': msg.is_read
    } for msg in messages])

@socketio.on('send_message')
def handle_send_message(data):
    token = data.get('token')
    if not token:
        emit('error', {'message': 'Token is missing'})
        return

    try:
        decoded = jwt.decode(token, app.config['SECRET_KEY'])
        user_id = decoded['user_id']
    except:
        emit('error', {'message': 'Token is invalid'})
        return

    message = Message(
        content=data['content'],
        user_id=user_id,
        recipient_id=data['recipient_id']
    )
    db.session.add(message)
    db.session.commit()

    # Create notification for recipient
    recipient = User.query.get(data['recipient_id'])
    if recipient:
        notification = Notification(
            content=f'New message from {User.query.get(user_id).username}',
            user_id=recipient.id
        )
        db.session.add(notification)
        db.session.commit()

    emit('new_message', {
        'id': message.id,
        'content': message.content,
        'timestamp': message.timestamp.isoformat(),
        'sender_id': message.user_id,
        'recipient_id': message.recipient_id
    }, room=data['recipient_id'])

    emit('notification', {
        'id': notification.id,
        'content': notification.content,
        'timestamp': notification.timestamp.isoformat()
    }, room=data['recipient_id'])
