@app.route('/create_checkout_session', methods=['POST'])
def create_checkout_session():
    token = request.headers.get('Authorization')
    if not token:
        return jsonify({'message': 'Token is missing'}), 401

    try:
        data = jwt.decode(token, app.config['SECRET_KEY'])
        user_id = data['user_id']
    except:
        return jsonify({'message': 'Token is invalid'}), 401

    feature_id = request.json.get('feature_id')
    feature = PremiumFeature.query.get(feature_id)

    if not feature:
        return jsonify({'message': 'Feature not found'}), 404

    try:
        checkout_session = stripe.checkout.Session.create(
            payment_method_types=['card'],
            line_items=[{
                'price_data': {
                    'currency': 'usd',
                    'product_data': {
                        'name': feature.name,
                    },
                    'unit_amount': int(feature.price * 100),
                },
                'quantity': 1,
            }],
            mode='payment',
            success_url='https://yourdomain.com/success?session_id={CHECKOUT_SESSION_ID}',
            cancel_url='https://yourdomain.com/cancel',
            metadata={
                'user_id': user_id,
                'feature_id': feature_id
            }
        )
        return jsonify({'sessionId': checkout_session['id']})
    except Exception as e:
        return jsonify({'error': str(e)}), 403

@app.route('/webhook', methods=['POST'])
def stripe_webhook():
    payload = request.get_data(as_text=True)
    sig_header = request.headers.get('Stripe-Signature')

    try:
        event = stripe.Webhook.construct_event(
            payload, sig_header, 'your-webhook-secret'
        )
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except stripe.error.SignatureVerificationError as e:
        return jsonify({'error': str(e)}), 400

    if event['type'] == 'checkout.session.completed':
        session = event['data']['object']
        user_id = session['metadata']['user_id']
        feature_id = session['metadata']['feature_id']

        user = User.query.get(user_id)
        feature = PremiumFeature.query.get(feature_id)

        if user and feature:
            user.premium = True
            user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=feature.duration_days)
            db.session.commit()

    return jsonify({'status': 'success'}), 200
