const Message = require('./models/Message');
const Notification = require('./models/Notification');
const Subscription = require('./models/Subscription');

// Middleware
app.use(express.json());

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET);
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/api/auth/register', async (req, res) => {
  // User registration logic
});

app.post('/api/auth/login', async (req, res) => {
  // User login logic
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (userId) => {
    socket.join(userId);
  });

  socket.on('sendMessage', async (data) => {
    // Save message to database
    const message = new Message(data);
    await message.save();

    // Emit to recipient
    io.to(data.recipientId).emit('newMessage', message);

    // Create notification
    const notification = new Notification({
      userId: data.recipientId,
      type: 'message',
      content: `New message from ${data.senderId}`,
      relatedId: message._id
    });
    await notification.save();

    // Emit notification
    io.to(data.recipientId).emit('newNotification', notification);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

// Monetization endpoints
app.post('/api/subscriptions', authenticate, async (req, res) => {
  // Subscription creation logic
});

app.get('/api/subscriptions', authenticate, async (req, res) => {
  // Get user subscriptions
});

server.listen(3000, () => {
  console.log('Server running on port 3000');
});
