                'subscription_id': subscription.id
            }}
        )

        return jsonify({
            'status': 'success',
            'client_secret': subscription.latest_invoice.payment_intent.client_secret
        })

    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 400

@app.route('/cancel_subscription', methods=['POST'])
def cancel_subscription():
    data = request.json
    user_id = data['user_id']

    user = db.users.find_one({'_id': user_id})
    if not user or not user.get('subscription_id'):
        return jsonify({'status': 'error', 'message': 'No active subscription'}), 400

    try:
        # Cancel Stripe subscription
        stripe.Subscription.delete(user['subscription_id'])

        # Update user in database
        db.users.update_one(
            {'_id': user_id},
            {'$set': {
                'premium_status': False,
                'subscription_id': None
            }}
        )

        return jsonify({'status': 'success'})

    except Exception as e:
        return jsonify({'status': 'error', 'message': str(e)}), 400

# Premium feature check
def is_premium_feature(user_id):
    user = db.users.find_one({'_id': user_id})
    return user.get('premium_status', False)
