@app.route('/create_checkout_session', methods=['POST'])
def create_checkout_session():
    try:
        user = User.query.get(request.json['user_id'])
        if not user:
            return jsonify({'error': 'User not found'}), 404

        # Create a new Stripe customer if not exists
        if not user.stripe_customer_id:
            customer = stripe.Customer.create(
                email=user.email,
                name=user.username
            )
            user.stripe_customer_id = customer.id
            db.session.commit()

        # Create a checkout session
        session = stripe.checkout.Session.create(
            payment_method_types=['card'],
            line_items=[{
                'price': 'price_123456789',  # Replace with your actual price ID
                'quantity': 1,
            }],
            mode='subscription',
            success_url='http://localhost:5000/success?session_id={CHECKOUT_SESSION_ID}',
            cancel_url='http://localhost:5000/cancel',
            customer=user.stripe_customer_id
        )

        return jsonify({'id': session.id})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/success')
def success():
    session_id = request.args.get('session_id')
    session = stripe.checkout.Session.retrieve(session_id)

    user = User.query.filter_by(stripe_customer_id=session.customer).first()
    if user:
        user.premium = True
        db.session.commit()

    return render_template('success.html')

@app.route('/cancel')
def cancel():
    return render_template('cancel.html')

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    socketio.run(app, debug=True)
