    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    is_read = db.Column(db.Boolean, default=False)

# Authentication Decorator
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=["HS256"])
            current_user = User.query.filter_by(id=data['user_id']).first()
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        return f(current_user, *args, **kwargs)
    return decorated

# Routes
@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    hashed_password = generate_password_hash(data['password'], method='sha256')
    new_user = User(username=data['username'], email=data['email'], password_hash=hashed_password)
    db.session.add(new_user)
    db.session.commit()
    return jsonify({'message': 'Registered successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()
    if not user or not check_password_hash(user.password_hash, data['password']):
        return jsonify({'message': 'Invalid credentials'}), 401
    token = jwt.encode({
        'user_id': user.id,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, app.config['SECRET_KEY'])
    return jsonify({'token': token})

@app.route('/messages', methods=['GET'])
@token_required
def get_messages(current_user):
    messages = Message.query.filter(
        (Message.sender_id == current_user.id) |
        (Message.recipient_id == current_user.id)
    ).order_by(Message.timestamp.desc()).all()
    return jsonify([{
        'id': msg.id,
        'content': msg.content,
        'timestamp': msg.timestamp,
        'sender_id': msg.sender_id,
        'recipient_id': msg.recipient_id,
        'is_read': msg.is_read,
        'is_premium': msg.is_premium
    } for msg in messages])

# SocketIO Events
@socketio.on('send_message')
@token_required
def handle_send_message(current_user, data):
    recipient = User.query.get(data['recipient_id'])
    if not recipient:
        emit('error', {'message': 'Recipient not found'})
        return

    # Check if message is premium content
    is_premium = data.get('is_premium', False)

    # For premium messages, verify user has premium access
    if is_premium and not current_user.premium:
        emit('error', {'message': 'Premium feature requires subscription'})
        return

    new_message = Message(
        content=data['content'],
        sender_id=current_user.id,
        recipient_id=recipient.id,
        is_premium=is_premium
    )
    db.session.add(new_message)
    db.session.commit()

    # Create notification for recipient
    notification = Notification(
        user_id=recipient.id,
        message=f'New message from {current_user.username}'
    )
    db.session.add(notification)
    db.session.commit()

    # Emit to recipient
    emit('new_message', {
        'id': new_message.id,
        'content': new_message.content,
        'timestamp': new_message.timestamp.isoformat(),
        'sender_id': current_user.id,
        'recipient_id': recipient.id,
        'is_premium': is_premium
    }, room=f'user_{recipient.id}')

    # Emit to sender
    emit('message_sent', {
        'id': new_message.id,
        'content': new_message.content,
        'timestamp': new_message.timestamp.isoformat(),
        'recipient_id': recipient.id,
        'is_premium': is_premium
    }, room=request.sid)

@socketio.on('connect')
@token_required
def handle_connect(current_user):
    join_room(f'user_{current_user.id}')
