# Premium Features
@app.route('/premium/subscribe', methods=['POST'])
@token_required
def subscribe_premium(current_user):
    # In a real app, this would integrate with a payment processor
    current_user.premium = True
    current_user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=30)
    db.session.commit()
