    if not receiver:
        return jsonify({'message': 'Receiver not found'}), 404

    # Check if sender is premium for premium messages
    is_premium = data.get('is_premium', False)
    if is_premium and not current_user.premium_status:
        return jsonify({'message': 'Premium feature requires premium membership'}), 403

    new_message = Message(
        sender_id=current_user.id,
        receiver_id=receiver.id,
        content=data['content'],
        is_premium=is_premium
    )

    db.session.add(new_message)
    db.session.commit()

    # Create notification for receiver
    new_notification = Notification(
        user_id=receiver.id,
        message_id=new_message.id
    )
    db.session.add(new_notification)
    db.session.commit()

    # Emit real-time notification
    socketio.emit('new_message', {
        'sender': current_user.username,
        'content': data['content'],
        'timestamp': str(new_message.timestamp)
    }, room=f"user_{receiver.id}")

    return jsonify({'message': 'Message sent successfully'}), 201

@app.route('/messages/<int:user_id>', methods=['GET'])
@token_required
def get_messages(current_user, user_id):
    messages = Message.query.filter(
        ((Message.sender_id == current_user.id) & (Message.receiver_id == user_id)) |
        ((Message.sender_id == user_id) & (Message.receiver_id == current_user.id))
    ).order_by(Message.timestamp).all()

    # Mark messages as read
    for message in messages:
        if message.receiver_id == current_user.id:
            message.is_read = True

    db.session.commit()

    return jsonify([{
        'id': msg.id,
        'sender': User.query.get(msg.sender_id).username,
        'content': msg.content,
        'timestamp': str(msg.timestamp),
        'is_premium': msg.is_premium
    } for msg in messages])

