## Monetization System

```python
# monetization.py
from flask import request, jsonify
from models import User, PremiumFeature
from database import db
import stripe
from datetime import datetime, timedelta

@app.route('/api/premium_features', methods=['GET'])
def get_premium_features():
    features = PremiumFeature.query.all()
    return jsonify([{
        'id': feature.id,
        'name': feature.name,
        'description': feature.description,
        'price': feature.price,
        'duration_days': feature.duration_days
    } for feature in features])

@app.route('/api/create_checkout_session', methods=['POST'])
def create_checkout_session():
    data = request.get_json()
    user_id = data['user_id']
    feature_id = data['feature_id']

    feature = PremiumFeature.query.get(feature_id)
    if not feature:
        return jsonify({'error': 'Feature not found'}), 404

    try:
        checkout_session = stripe.checkout.Session.create(
            payment_method_types=['card'],
            line_items=[{
                'price_data': {
                    'currency': 'usd',
                    'product_data': {
                        'name': feature.name,
                    },
                    'unit_amount': int(feature.price * 100),
                },
                'quantity': 1,
            }],
            mode='payment',
            success_url=f'{request.host_url}success?session_id={{CHECKOUT_SESSION_ID}}',
            cancel_url=f'{request.host_url}cancel',
            metadata={
                'user_id': user_id,
                'feature_id': feature_id
            }
        )
        return jsonify({'sessionId': checkout_session['id']})
    except Exception as e:
        return jsonify({'error': str(e)}), 400

@app.route('/api/webhook', methods=['POST'])
def stripe_webhook():
    payload = request.get_data(as_text=True)
    sig_header = request.headers.get('Stripe-Signature')

    try:
        event = stripe.Webhook.construct_event(
            payload, sig_header, os.environ.get('STRIPE_WEBHOOK_SECRET')
        )
    except ValueError as e:
        # Invalid payload
        return jsonify({'error': str(e)}), 400
    except stripe.error.SignatureVerificationError as e:
        # Invalid signature
        return jsonify({'error': str(e)}), 400

    # Handle the checkout.session.completed event
    if event['type'] == 'checkout.session.completed':
        session = event['data']['object']
        user_id = session['metadata']['user_id']
        feature_id = session['metadata']['feature_id']

        feature = PremiumFeature.query.get(feature_id)
        user = User.query.get(user_id)

        if user and feature:
            # Update user's premium status
            user.is_premium = True
            if user.premium_expiry and user.premium_expiry > datetime.utcnow():
                user.premium_expiry += timedelta(days=feature.duration_days)
            else:
                user.premium_expiry = datetime.utcnow() + timedelta(days=feature.duration_days)

            db.session.commit()

    return jsonify({'status': 'success'})
