# app/core/consumers.py
import json
from channels.generic.websocket import AsyncWebsocketConsumer
from channels.db import database_sync_to_async
from .models import Message, Notification, User

class ChatConsumer(AsyncWebsocketConsumer):
    async def connect(self):
        self.user = self.scope["user"]
        if not self.user.is_authenticated:
            await self.close()
            return

        self.room_group_name = f"user_{self.user.id}"
        await self.channel_layer.group_add(
            self.room_group_name,
            self.channel_name
        )
        await self.accept()

    async def disconnect(self, close_code):
        await self.channel_layer.group_discard(
            self.room_group_name,
            self.channel_name
        )

    async def receive(self, text_data):
        data = json.loads(text_data)
        message_type = data.get('type')

        if message_type == 'message':
            await self.handle_message(data)
        elif message_type == 'notification':
            await self.handle_notification(data)

    async def handle_message(self, data):
        recipient_id = data.get('recipient_id')
        content = data.get('content')

        if not recipient_id or not content:
            return

        recipient = await self.get_user(recipient_id)
        if not recipient:
            return

        message = await self.create_message(recipient, content)

        await self.channel_layer.group_send(
            f"user_{recipient.id}",
            {
                'type': 'chat_message',
                'message': {
                    'id': message.id,
                    'sender': self.user.id,
                    'content': message.content,
                    'timestamp': str(message.timestamp),
                    'is_read': message.is_read
                }
            }
        )

    async def handle_notification(self, data):
        recipient_id = data.get('recipient_id')
        notification_type = data.get('notification_type')
        message_id = data.get('message_id')

        if not recipient_id or not notification_type:
            return

        recipient = await self.get_user(recipient_id)
        if not recipient:
            return

        message = None
        if message_id:
            message = await self.get_message(message_id)

        notification = await self.create_notification(recipient, notification_type, message)

        await self.channel_layer.group_send(
            f"user_{recipient.id}",
            {
                'type': 'notification_message',
                'notification': {
                    'id': notification.id,
                    'type': notification.notification_type,
                    'sender': self.user.id,
                    'message_id': message_id,
                    'is_read': notification.is_read,
                    'created_at': str(notification.created_at)
                }
            }
        )

    async def chat_message(self, event):
        await self.send(text_data=json.dumps({
            'type': 'message',
            'message': event['message']
        }))

    async def notification_message(self, event):
        await self.send(text_data=json.dumps({
            'type': 'notification',
            'notification': event['notification']
        }))

    @database_sync_to_async
    def get_user(self, user_id):
        try:
            return User.objects.get(id=user_id)
        except User.DoesNotExist:
            return None

    @database_sync_to_async
    def create_message(self, recipient, content):
        return Message.objects.create(
            sender=self.user,
            recipient=recipient,
            content=content
        )

    @database_sync_to_async
    def get_message(self, message_id):
        try:
            return Message.objects.get(id=message_id)
        except Message.DoesNotExist:
            return None

    @database_sync_to_async
    def create_notification(self, recipient, notification_type, message=None):
        return Notification.objects.create(
            recipient=recipient,
            sender=self.user,
            notification_type=notification_type,
            message=message
        )
