def purchase_premium(current_user):
    data = request.get_json()
    feature = PremiumFeature.query.get(data['feature_id'])

    if not feature:
        return jsonify({'message': 'Feature not found'}), 404

    if current_user.coins < feature.price:
        return jsonify({'message': 'Insufficient coins'}), 400

    # Deduct coins
    current_user.coins -= feature.price

    # Update premium status
    if not current_user.premium_status or current_user.premium_expiry < datetime.datetime.utcnow():
        current_user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=feature.duration_days)
    else:
        current_user.premium_expiry += datetime.timedelta(days=feature.duration_days)

    current_user.premium_status = True

    # Record transaction
    transaction = Transaction(
        user_id=current_user.id,
        feature_id=feature.id,
        amount=feature.price
    )
    db.session.add(transaction)
    db.session.commit()

    return jsonify({
        'message': 'Premium feature purchased successfully',
        'premium_expiry': current_user.premium_expiry.isoformat(),
        'remaining_coins': current_user.coins
    })

