## Monetization Features

```python
# monetization.py
from flask import Blueprint, request, jsonify
from models import User, Subscription
from extensions import db
import stripe
from datetime import datetime, timedelta

monetization = Blueprint('monetization', __name__)

@monetization.route('/create_subscription', methods=['POST'])
def create_subscription():
    data = request.get_json()
    user_id = data.get('user_id')
    plan = data.get('plan')  # 'basic' or 'premium'

    user = User.query.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    # In a real app, you would create a Stripe customer and subscription
    try:
        # Create Stripe customer
        customer = stripe.Customer.create(
            email=user.email,
            name=user.username,
            payment_method=data.get('payment_method_id'),
            invoice_settings={'default_payment_method': data.get('payment_method_id')}
        )

        # Create Stripe subscription
        subscription = stripe.Subscription.create(
            customer=customer.id,
            items=[{'price': get_price_id_for_plan(plan)}],
            expand=['latest_invoice.payment_intent']
        )

        # Save subscription to database
        db_subscription = Subscription(
            user_id=user_id,
            stripe_customer_id=customer.id,
            plan=plan,
            active=True,
            start_date=datetime.utcnow(),
            end_date=datetime.utcnow() + timedelta(days=30)  # Monthly subscription
        )
        db.session.add(db_subscription)

        # Update user premium status
        user.premium = True
        user.premium_expiry = db_subscription.end_date
        db.session.commit()

        return jsonify({
            'message': 'Subscription created successfully',
            'client_secret': subscription.latest_invoice.payment_intent.client_secret
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@monetization.route('/cancel_subscription', methods=['POST'])
def cancel_subscription():
    data = request.get_json()
    user_id = data.get('user_id')

    subscription = Subscription.query.filter_by(user_id=user_id, active=True).first()
    if not subscription:
        return jsonify({'error': 'No active subscription found'}), 404

    try:
        # Cancel Stripe subscription
        stripe.Subscription.delete(subscription.stripe_customer_id)

        # Update database
        subscription.active = False
        user = User.query.get(user_id)
        user.premium = False
        db.session.commit()

        return jsonify({'message': 'Subscription cancelled successfully'})

    except Exception as e:
        return jsonify({'error': str(e)}), 500

def get_price_id_for_plan(plan):
    # In a real app, these would be your actual Stripe price IDs
    if plan == 'basic':
        return 'price_basic_monthly'
    elif plan == 'premium':
        return 'price_premium_monthly'
    else:
        raise ValueError('Invalid plan')
