// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const stripe = require('stripe')('your_stripe_secret_key');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Middleware
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = {};
const messages = {};
const premiumUsers = new Set();

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('register', (userId) => {
    users[userId] = socket.id;
    socket.userId = userId;
  });

  socket.on('sendMessage', ({ senderId, receiverId, content }) => {
    const message = {
      id: Date.now().toString(),
      senderId,
      receiverId,
      content,
      timestamp: new Date(),
      read: false
    };

    // Store message
    if (!messages[receiverId]) messages[receiverId] = [];
    messages[receiverId].push(message);

    // Send to receiver if online
    if (users[receiverId]) {
      io.to(users[receiverId]).emit('newMessage', message);
    }

    // Send confirmation to sender
    socket.emit('messageSent', message);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
    // Remove user from active users
    for (const [userId, socketId] of Object.entries(users)) {
      if (socketId === socket.id) {
        delete users[userId];
        break;
      }
    }
  });
});

// API endpoints
app.post('/api/upgrade', async (req, res) => {
  try {
    const { userId, paymentMethodId } = req.body;

    // Create payment intent
    const paymentIntent = await stripe.paymentIntents.create({
      amount: 999, // $9.99
      currency: 'usd',
      payment_method: paymentMethodId,
      confirm: true,
      description: 'Premium Membership'
    });

    if (paymentIntent.status === 'succeeded') {
      premiumUsers.add(userId);
      res.json({ success: true, premium: true });
    } else {
      res.status(400).json({ error: 'Payment failed' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Server error' });
  }
});

app.get('/api/messages/:userId', (req, res) => {
  const userId = req.params.userId;
  res.json(messages[userId] || []);
});

app.get('/api/check-premium/:userId', (req, res) => {
  const userId = req.params.userId;
  res.json({ premium: premiumUsers.has(userId) });
});

// Start server
const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
