            {isPremium && <span className="premium-badge">Premium User</span>}
          </div>

          <div className="messages">
            {messages.map((msg) => (
              <div key={msg.id} className={`message ${msg.senderId === userId ? 'sent' : 'received'}`}>
                <p>{msg.content}</p>
                <small>{new Date(msg.timestamp).toLocaleTimeString()}</small>
              </div>
            ))}
          </div>

          <div className="message-input">
            <input
              type="text"
              placeholder="Enter receiver ID"
              value={receiverId}
              onChange={(e) => setReceiverId(e.target.value)}
            />
            <input
              type="text"
              placeholder="Type a message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
            />
            <button onClick={sendMessage}>Send</button>
          </div>

          {showUpgrade && (
            <div className="upgrade-modal">
              <h2>Upgrade to Premium</h2>
              <Elements stripe={stripePromise}>
                <UpgradeForm
                  userId={userId}
                  onSuccess={() => {
                    setShowUpgrade(false);
                    setIsPremium(true);
                  }}
                />
              </Elements>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function UpgradeForm({ userId, onSuccess }) {
  const stripe = useStripe();
  const elements = useElements();
  const [error, setError] = useState(null);
  const [processing, setProcessing] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setProcessing(true);

    if (!stripe || !elements) {
      return;
    }

    const cardElement = elements.getElement(CardElement);

    try {
      const { paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: cardElement,
      });

      const response = await fetch('http://localhost:5000/api/upgrade', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          userId,
          paymentMethodId: paymentMethod.id,
        }),
      });

      const result = await response.json();

      if (result.success) {
        onSuccess();
      } else {
        setError(result.error || 'Payment failed');
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setProcessing(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <CardElement />
      <button type="submit" disabled={!stripe || processing}>
        {processing ? 'Processing...' : 'Pay $9.99'}
      </button>
      {error && <div className="error">{error}</div>}
    </form>
  );
}

export default App;
