# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and in-app monetization. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication endpoint
app.post('/login', (req, res) => {
    const { username, isPremium } = req.body;
    users[username] = { isPremium: isPremium || false };
    if (isPremium) premiumUsers.add(username);
    res.json({ success: true, username });
});

// Message endpoint
app.post('/message', (req, res) => {
    const { username, text, isPremium } = req.body;
    const message = {
        id: Date.now(),
        username,
        text,
        timestamp: new Date().toISOString(),
        isPremium: isPremium || false
    };
    messages.push(message);
    io.emit('newMessage', message);
    res.json({ success: true });
});

// Get messages endpoint
app.get('/messages', (req, res) => {
    res.json(messages);
});

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });

    // Send premium status updates
    socket.on('checkPremium', (username) => {
        socket.emit('premiumStatus', {
            isPremium: premiumUsers.has(username)
        });
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

