# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a minimal working version of a social messaging app with real-time notifications and in-app monetization. This example uses Node.js for the backend, React for the frontend, and Firebase for real-time functionality and authentication.

## Backend (Node.js + Express + Firebase)

### `server.js`
```javascript
const express = require('express');
const admin = require('firebase-admin');
const cors = require('cors');

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://your-project.firebaseio.com"
});

const app = express();
app.use(cors());
app.use(express.json());

// Firebase Firestore
const db = admin.firestore();

// User authentication
app.post('/api/register', async (req, res) => {
  try {
    const { email, password, username } = req.body;
    const userRecord = await admin.auth().createUser({
      email,
      password,
      displayName: username
    });

    await db.collection('users').doc(userRecord.uid).set({
      username,
      email,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      premium: false,
      premiumExpiry: null
    });

    res.status(201).json({ uid: userRecord.uid });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Messaging endpoints
app.post('/api/messages', async (req, res) => {
  try {
    const { senderId, receiverId, content } = req.body;

    const messageRef = await db.collection('messages').add({
      senderId,
      receiverId,
      content,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
      read: false
    });

    // Send push notification to receiver
    const receiverDoc = await db.collection('users').doc(receiverId).get();
    if (receiverDoc.exists) {
      const receiver = receiverDoc.data();
      if (receiver.fcmToken) {
        const message = {
          notification: {
            title: 'New Message',
            body: content
          },
          token: receiver.fcmToken
        };
        await admin.messaging().send(message);
      }
    }

    res.status(201).json({ id: messageRef.id });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Premium subscription endpoint
app.post('/api/premium/subscribe', async (req, res) => {
  try {
    const { userId, plan } = req.body;

    // In a real app, you would integrate with a payment processor here
    // For this example, we'll just simulate a successful subscription

    const expiryDate = new Date();
    expiryDate.setMonth(expiryDate.getMonth() + (plan === 'monthly' ? 1 : 12));

    await db.collection('users').doc(userId).update({
      premium: true,
      premiumExpiry: expiryDate,
      premiumPlan: plan
    });

    res.status(200).json({ success: true, expiryDate });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

