import React, { useState, useEffect } from 'react';
import { initializeApp } from 'firebase/app';
import { getAuth, onAuthStateChanged, signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, collection, query, where, onSnapshot, addDoc, doc, updateDoc } from 'firebase/firestore';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';

// Firebase configuration
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);
const messaging = getMessaging(app);

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [recipient, setRecipient] = useState('');
  const [isPremium, setIsPremium] = useState(false);

  useEffect(() => {
    // Auth state listener
    const unsubscribeAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setUser(user);

        // Check premium status
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          setIsPremium(userDoc.data().premium);
        }

        // Request notification permission
        Notification.requestPermission().then(permission => {
          if (permission === 'granted') {
            getToken(messaging, { vapidKey: 'YOUR_VAPID_KEY' }).then((currentToken) => {
              if (currentToken) {
                // Save the token to the user's document
                updateDoc(doc(db, 'users', user.uid), {
                  fcmToken: currentToken
                });
              }
            });
          }
        });

        // Listen for messages
        const q = query(
          collection(db, 'messages'),
          where('receiverId', '==', user.uid)
        );

        const unsubscribeMessages = onSnapshot(q, (querySnapshot) => {
          const messagesData = [];
          querySnapshot.forEach((doc) => {
            messagesData.push({ id: doc.id, ...doc.data() });
          });
          setMessages(messagesData);
        });

        return () => unsubscribeMessages();
      } else {
        setUser(null);
        setMessages([]);
      }
    });

    // Listen for foreground messages
    const unsubscribeForeground = onMessage(messaging, (payload) => {
      console.log('Message received. ', payload);
      // You can show a notification here if needed
    });

    return () => {
      unsubscribeAuth();
      unsubscribeForeground();
    };
  }, []);

  const handleLogin = async (email, password) => {
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (error) {
      console.error('Login error:', error);
    }
  };

