      console.error('Registration error:', error);
    }
  };

  const handleSendMessage = async () => {
    if (!user || !recipient || !newMessage) return;

    try {
      await addDoc(collection(db, 'messages'), {
        senderId: user.uid,
        receiverId: recipient,
        content: newMessage,
        timestamp: new Date(),
        read: false
      });
      setNewMessage('');
