```javascript
// server.js
const express = require('express');
const admin = require('firebase-admin');
const bodyParser = require('body-parser');
const cors = require('cors');

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://your-project.firebaseio.com"
});

const db = admin.firestore();
const messaging = admin.messaging();

const app = express();
app.use(cors());
app.use(bodyParser.json());

// User authentication
app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    // In a real app, you would verify credentials against your database
    const user = { id: 'user123', email, name: 'Test User' };
    res.json({ user, token: 'fake-jwt-token' });
  } catch (error) {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

// Send message
app.post('/api/messages', async (req, res) => {
  try {
    const { senderId, recipientId, content } = req.body;

    // Save message to Firestore
    const messageRef = await db.collection('messages').add({
      senderId,
      recipientId,
      content,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
      read: false
    });

    // Send push notification to recipient
    const recipientToken = await db.collection('users').doc(recipientId).get()
      .then(doc => doc.data().fcmToken);

    if (recipientToken) {
      await messaging.send({
        token: recipientToken,
        notification: {
          title: 'New Message',
          body: `From: ${senderId}`
        },
        data: {
          messageId: messageRef.id,
          senderId
        }
      });
    }

    res.json({ success: true, messageId: messageRef.id });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get messages for a user
app.get('/api/messages/:userId', async (req, res) => {
  try {
    const { userId } = req.params;
    const messagesSnapshot = await db.collection('messages')
      .where('recipientId', '==', userId)
      .orderBy('timestamp', 'desc')
      .limit(50)
      .get();

    const messages = messagesSnapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    res.json(messages);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Premium feature - get user profile
app.get('/api/profile/:userId', async (req, res) => {
  try {
    const { userId } = req.params;
    const userDoc = await db.collection('users').doc(userId).get();

    if (!userDoc.exists) {
      return res.status(404).json({ error: 'User not found' });
    }

    const userData = userDoc.data();

    // Check if user has premium access
    if (userData.isPremium) {
      res.json({
        ...userData,
        premiumFeatures: {
          profileViews: userData.profileViews || 0,
          customStatus: userData.customStatus || ''
        }
      });
    } else {
      res.json({
        name: userData.name,
        isPremium: false
      });
    }
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Start server
const PORT = process.env.PORT || 5000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
