# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and in-app monetization. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = {};
const messages = {};
const notifications = {};

// User authentication (simplified)
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // In a real app, verify credentials against database
  if (username && password) {
    users[username] = { id: Date.now().toString(), username };
    res.json({ success: true, user: users[username] });
  } else {
    res.status(401).json({ success: false, message: 'Invalid credentials' });
  }
});

// Send message
app.post('/message', (req, res) => {
  const { sender, recipient, content } = req.body;

  if (!users[sender] || !users[recipient]) {
    return res.status(400).json({ success: false, message: 'Invalid users' });
  }

  const message = {
    id: Date.now().toString(),
    sender,
    recipient,
    content,
    timestamp: new Date().toISOString()
  };

  if (!messages[recipient]) messages[recipient] = [];
  messages[recipient].push(message);

  // Emit real-time notification
  io.to(recipient).emit('new-message', message);
  io.to(recipient).emit('notification', {
    type: 'message',
    from: sender,
    content: content.substring(0, 30) + (content.length > 30 ? '...' : '')
  });

  res.json({ success: true, message });
});

// Get messages for user
app.get('/messages/:username', (req, res) => {
  const username = req.params.username;
  res.json({ success: true, messages: messages[username] || [] });
});

// Monetization endpoint (purchase premium feature)
app.post('/purchase', (req, res) => {
  const { username, feature } = req.body;

  if (!users[username]) {
    return res.status(400).json({ success: false, message: 'User not found' });
  }

  // In a real app, process payment here
  console.log(`Processing purchase for ${username} of feature: ${feature}`);

  // Grant premium feature (simplified)
  users[username].premiumFeatures = users[username].premiumFeatures || [];
  users[username].premiumFeatures.push(feature);

  res.json({
    success: true,
    message: `Successfully purchased ${feature}`,
    user: users[username]
  });
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('register', (username) => {
    socket.join(username);
    console.log(`${username} registered for notifications`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

