      fetch(`http://localhost:3000/messages/${username}`)
        .then(res => res.json())
        .then(data => setMessages(data));

      // Fetch notifications
      fetch(`http://localhost:3000/notifications/${username}`)
        .then(res => res.json())
        .then(data => setNotifications(data));

      // Listen for new messages
      socket.on('new-message', (newMessage) => {
        setMessages(prev => [...prev, newMessage]);
      });

      // Listen for notifications
      socket.on('notification', (notification) => {
        setNotifications(prev => [...prev, notification]);
      });

      // Join room
      socket.emit('join', username);
    }

    return () => {
      socket.off('new-message');
      socket.off('notification');
    };
  }, [loggedIn, username]);

  const handleLogin = async () => {
    const response = await fetch('http://localhost:3000/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username })
    });
    const data = await response.json();
    if (data.username) {
      setLoggedIn(true);
    }
  };

  const handleSendMessage = async () => {
    if (!recipient || !message) return;

    const response = await fetch('http://localhost:3000/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        sender: username,
        recipient,
        content: message,
        isPremium: isPremium
      })
    });

    const data = await response.json();
    if (data.success) {
      setMessage('');
      setMessages(prev => [...prev, {
        sender: username,
        content: message,
        timestamp: new Date().toISOString(),
        isPremium: isPremium
      }]);
    }
  };

  const handleUpgradeToPremium = async () => {
    const response = await fetch('http://localhost:3000/purchase-premium', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username })
    });

    const data = await response.json();
    if (data.success) {
      setIsPremium(true);
    }
  };

  if (!loggedIn) {
    return (
      <div>
        <h1>Login</h1>
        <input
          type="text"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Enter username"
        />
        <button onClick={handleLogin}>Login</button>
      </div>
    );
  }

  return (
    <div>
      <h1>Welcome, {username} {isPremium && <span>💎 Premium</span>}</h1>

      {!isPremium && (
        <div style={{ backgroundColor: '#f0f0f0', padding: '10px', margin: '10px 0' }}>
          <p>Upgrade to Premium for exclusive features!</p>
          <button onClick={handleUpgradeToPremium}>Upgrade to Premium ($4.99/month)</button>
        </div>
      )}

      <div>
        <h2>Notifications</h2>
        {notifications.length === 0 ? (
          <p>No new notifications</p>
        ) : (
          <ul>
            {notifications.map((notif, index) => (
              <li key={index} style={{ color: notif.read ? 'gray' : 'black' }}>
                {notif.content} - {new Date(notif.timestamp).toLocaleTimeString()}
              </li>
            ))}
          </ul>
        )}
      </div>

      <div>
        <h2>Send Message</h2>
        <input
          type="text"
          value={recipient}
          onChange={(e) => setRecipient(e.target.value)}
          placeholder="Recipient username"
        />
        <textarea
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Your message"
        />
        <button onClick={handleSendMessage}>Send</button>
      </div>

      <div>
        <h2>Messages</h2>
        {messages.length === 0 ? (
          <p>No messages yet</p>
        ) : (
          <ul>
            {messages.map((msg, index) => (
              <li key={index} style={{ color: msg.isPremium ? 'gold' : 'black' }}>
                <strong>{msg.sender}:</strong> {msg.content}
                {msg.isPremium && ' 💎'}
                <br />
                <small>{new Date(msg.timestamp).toLocaleString()}</small>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default App;
