```javascript
// server.js
const express = require('express');
const admin = require('firebase-admin');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();
app.use(cors());
app.use(bodyParser.json());

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://your-project.firebaseio.com"
});

const db = admin.firestore();

// User authentication
app.post('/api/register', async (req, res) => {
  try {
    const { email, password, username } = req.body;
    const userRecord = await admin.auth().createUser({
      email,
      password,
      displayName: username
    });

    await db.collection('users').doc(userRecord.uid).set({
      username,
      email,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      premium: false,
      coins: 100 // Starting coins for free users
    });

    res.status(201).json({ uid: userRecord.uid });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Send message
app.post('/api/messages', async (req, res) => {
  try {
    const { senderId, receiverId, content } = req.body;

    const messageRef = await db.collection('messages').add({
      senderId,
      receiverId,
      content,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
      read: false
    });

    // Send push notification to receiver
    const receiverDoc = await db.collection('users').doc(receiverId).get();
    if (receiverDoc.exists) {
      const receiver = receiverDoc.data();
      if (receiver.fcmToken) {
        await admin.messaging().send({
          token: receiver.fcmToken,
          notification: {
            title: 'New Message',
            body: `From ${receiver.displayName}`
          },
          data: {
            messageId: messageRef.id,
            senderId
          }
        });
      }
    }

    res.status(201).json({ messageId: messageRef.id });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Get messages between two users
app.get('/api/messages/:userId1/:userId2', async (req, res) => {
  try {
    const { userId1, userId2 } = req.params;

    const messagesRef = db.collection('messages')
      .where('senderId', 'in', [userId1, userId2])
      .where('receiverId', 'in', [userId1, userId2])
      .orderBy('timestamp', 'asc');

    const snapshot = await messagesRef.get();
    const messages = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    res.json(messages);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Monetization endpoints
app.post('/api/purchase', async (req, res) => {
  try {
    const { userId, productId, amount } = req.body;

    // In a real app, you would verify the payment here
    const userRef = db.collection('users').doc(userId);
    const userDoc = await userRef.get();

    if (!userDoc.exists) {
      return res.status(404).json({ error: 'User not found' });
    }

    const currentCoins = userDoc.data().coins || 0;

    // Update user coins
    await userRef.update({
      coins: currentCoins + amount
    });

    // Record the purchase
    await db.collection('purchases').add({
      userId,
      productId,
      amount,
      timestamp: admin.firestore.FieldValue.serverTimestamp()
    });

    res.json({ success: true, newBalance: currentCoins + amount });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Premium subscription
app.post('/api/subscribe', async (req, res) => {
  try {
    const { userId, planId } = req.body;

    // In a real app, you would verify the subscription here
    const userRef = db.collection('users').doc(userId);

    await userRef.update({
      premium: true,
      premiumPlan: planId,
      premiumSince: admin.firestore.FieldValue.serverTimestamp()
    });

    res.json({ success: true });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
