# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a basic implementation of a social messaging app with real-time notifications and monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and MongoDB for data storage.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// Database connection
mongoose.connect('mongodb://localhost:27017/messagingApp', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Models
const User = mongoose.model('User', new mongoose.Schema({
  username: String,
  password: String,
  coins: { type: Number, default: 100 },
  premium: { type: Boolean, default: false }
}));

const Message = mongoose.model('Message', new mongoose.Schema({
  sender: String,
  receiver: String,
  content: String,
  timestamp: { type: Date, default: Date.now },
  read: { type: Boolean, default: false }
}));

// Middleware
app.use(cors());
app.use(express.json());

// Auth middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, 'secret_key');
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/register', async (req, res) => {
  const { username, password } = req.body;
  const user = new User({ username, password });
  await user.save();
  res.status(201).send('User registered');
});

app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await User.findOne({ username, password });
  if (!user) return res.status(400).send('Invalid credentials');

  const token = jwt.sign({ username }, 'secret_key');
  res.send({ token, coins: user.coins, premium: user.premium });
});

// Monetization routes
app.post('/buy-coins', authenticate, async (req, res) => {
  const { amount } = req.body;
  const user = await User.findOne({ username: req.user.username });
  user.coins += amount;
  await user.save();
  res.send({ coins: user.coins });
});

app.post('/buy-premium', authenticate, async (req, res) => {
  const user = await User.findOne({ username: req.user.username });
  if (user.coins < 500) return res.status(400).send('Not enough coins');

  user.coins -= 500;
  user.premium = true;
  await user.save();
  res.send({ coins: user.coins, premium: user.premium });
});

// Socket.io for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (username) => {
    socket.join(username);
  });

  socket.on('sendMessage', async ({ sender, receiver, content }) => {
    const message = new Message({ sender, receiver, content });
    await message.save();

    // Send to receiver if online
    io.to(receiver).emit('newMessage', message);

    // Send notification
    io.to(receiver).emit('notification', {
      type: 'message',
      from: sender,
      content: content.substring(0, 20) + (content.length > 20 ? '...' : '')
    });
  });

  socket.on('readMessages', async ({ user, contact }) => {
    await Message.updateMany(
      { sender: contact, receiver: user, read: false },
      { read: true }
    );
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

