import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:3000');

function App() {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState('');
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [currentContact, setCurrentContact] = useState('');
  const [newMessage, setNewMessage] = useState('');

  // Login/Register
  const handleLogin = async (username, password) => {
    const response = await fetch('http://localhost:3000/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const data = await response.json();
    setToken(data.token);
    setUser({ username, coins: data.coins, premium: data.premium });
    socket.emit('join', username);
  };

  // Message handling
  const sendMessage = () => {
    if (!newMessage.trim()) return;

    const message = {
      sender: user.username,
      receiver: currentContact,
      content: newMessage
    };

    socket.emit('sendMessage', message);
    setMessages([...messages, { ...message, timestamp: new Date() }]);
    setNewMessage('');
  };

  // Socket listeners
  useEffect(() => {
    if (!user) return;

    socket.on('newMessage', (message) => {
      if (message.sender === currentContact || message.receiver === currentContact) {
        setMessages(prev => [...prev, message]);
        // Mark as read if current chat is open
        if (message.sender === currentContact) {
          socket.emit('readMessages', { user: user.username, contact: currentContact });
        }
      }
    });

    socket.on('notification', (notification) => {
      setNotifications(prev => [...prev, notification]);
    });

    return () => {
      socket.off('newMessage');
      socket.off('notification');
    };
  }, [user, currentContact]);

  // Monetization
