      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });
    const data = await response.json();
    setUser(prev => ({ ...prev, coins: data.coins, premium: data.premium }));
  };

  if (!user) {
    return (
      <div>
        <h1>Login</h1>
        <button onClick={() => handleLogin('user1', 'password1')}>Login as User1</button>
        <button onClick={() => handleLogin('user2', 'password2')}>Login as User2</button>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex' }}>
      <div style={{ width: '250px', borderRight: '1px solid #ccc', padding: '10px' }}>
        <h3>Contacts</h3>
        <button onClick={() => setCurrentContact('user1')}>User1</button>
        <button onClick={() => setCurrentContact('user2')}>User2</button>

        <div style={{ marginTop: '20px' }}>
          <h3>Monetization</h3>
          <p>Coins: {user.coins}</p>
          <button onClick={() => buyCoins(100)}>Buy 100 Coins</button>
          <button onClick={buyPremium} disabled={user.premium}>
            {user.premium ? 'Premium Member' : 'Buy Premium (500 coins)'}
          </button>
        </div>
      </div>

      <div style={{ flex: 1, padding: '10px' }}>
        <h2>Chat with {currentContact}</h2>

        <div style={{ height: '300px', overflowY: 'scroll', border: '1px solid #ccc', padding: '10px' }}>
          {messages.map((msg, index) => (
            <div key={index} style={{ marginBottom: '10px' }}>
