```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = {};
const messages = {};
const notifications = {};

// User authentication (simplified)
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Simulate user lookup
  const userId = `user_${Math.random().toString(36).substr(2, 9)}`;
  users[userId] = { username, premium: false };

  res.json({ userId, username, premium: false });
});

// Message endpoints
app.post('/send-message', (req, res) => {
  const { senderId, receiverId, content } = req.body;
  if (!senderId || !receiverId || !content) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const messageId = `msg_${Date.now()}`;
  const message = {
    id: messageId,
    senderId,
    receiverId,
    content,
    timestamp: new Date().toISOString(),
    read: false
  };

  // Store message
  if (!messages[receiverId]) messages[receiverId] = [];
  messages[receiverId].push(message);

  // Send notification
  if (!notifications[receiverId]) notifications[receiverId] = [];
  notifications[receiverId].push({
    id: `notif_${Date.now()}`,
    type: 'message',
    messageId,
    senderId,
    timestamp: new Date().toISOString()
  });

  // Emit real-time events
  io.to(receiverId).emit('new-message', message);
  io.to(receiverId).emit('new-notification', notifications[receiverId].slice(-1)[0]);

  res.json({ success: true, messageId });
