# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a minimal working version of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time communication, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage for demo purposes
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(express.static(path.join(__dirname, 'public')));
app.use(express.json());

// User authentication endpoint
app.post('/login', (req, res) => {
    const { username } = req.body;
    if (!username) return res.status(400).send('Username required');

    // In a real app, you'd verify credentials here
    users[username] = { username, isPremium: false };
    res.json({ username, isPremium: false });
});

// Monetization endpoint
app.post('/upgrade', (req, res) => {
    const { username } = req.body;
    if (!users[username]) return res.status(404).send('User not found');

    // In a real app, you'd verify payment here
    users[username].isPremium = true;
    premiumUsers.add(username);
    res.json({ success: true, isPremium: true });
});

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Join user to their room
    socket.on('join', (username) => {
        socket.join(username);
        socket.username = username;

        // Send existing messages to the user
        socket.emit('initialMessages', messages.filter(m =>
            m.to === username || m.from === username
        ));
    });

    // Handle new messages
    socket.on('sendMessage', ({ to, text }) => {
        const from = socket.username;
        const message = { from, to, text, timestamp: new Date() };

        // Store message
        messages.push(message);

        // Send to recipient if online
        io.to(to).emit('newMessage', message);

        // Send notification if recipient is premium
        if (premiumUsers.has(to)) {
            io.to(to).emit('notification', {
                type: 'message',
                from,
                text: 'You have a new message'
            });
        }
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
