            border-radius: 5px;
            margin-bottom: 20px;
        }
        .message {
            margin-bottom: 10px;
            padding: 10px;
            border-radius: 5px;
            background-color: #f5f5f5;
        }
        .premium {
            background-color: #ffeb3b;
        }
        .upgrade-btn {
            background-color: #4CAF50;
            color: white;
            padding: 10px 15px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            margin-top: 10px;
        }
        .upgrade-btn:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <div class="login-container" id="loginContainer">
        <h2>Login</h2>
        <input type="text" id="username" placeholder="Enter username">
        <button onclick="login()">Login</button>
    </div>

    <div class="chat-container" id="chatContainer" style="display: none;">
        <h2>Chat <span id="premiumBadge" style="display: none; color: gold;">⭐ Premium</span></h2>
        <div id="messages"></div>
        <div>
            <input type="text" id="recipient" placeholder="Recipient username">
            <input type="text" id="messageText" placeholder="Type your message">
            <button onclick="sendMessage()">Send</button>
        </div>
        <button class="upgrade-btn" id="upgradeBtn" onclick="upgradeToPremium()">Upgrade to Premium ($9.99/month)</button>
    </div>

    <script src="/socket.io/socket.io.js"></script>
    <script>
        let socket;
        let currentUser;

        function login() {
            const username = document.getElementById('username').value.trim();
            if (!username) return alert('Please enter a username');

            fetch('/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username })
            })
            .then(response => response.json())
            .then(data => {
                currentUser = data.username;
                document.getElementById('loginContainer').style.display = 'none';
                document.getElementById('chatContainer').style.display = 'block';

                if (data.isPremium) {
                    showPremiumFeatures();
                }

                // Connect to socket
                socket = io();

                socket.emit('join', currentUser);

                // Handle incoming messages
                socket.on('initialMessages', (messages) => {
                    messages.forEach(displayMessage);
                });

                socket.on('newMessage', (message) => {
                    displayMessage(message);
                });

                // Handle notifications
                socket.on('notification', (notification) => {
                    if (notification.type === 'message') {
                        alert(`Notification: ${notification.from} sent you a message`);
                    }
                });
            })
            .catch(error => console.error('Error:', error));
        }

        function sendMessage() {
            const to = document.getElementById('recipient').value.trim();
            const text = document.getElementById('messageText').value.trim();

            if (!to || !text) return alert('Please enter recipient and message');

            socket.emit('sendMessage', { to, text });
            document.getElementById('messageText').value = '';
        }

        function displayMessage(message) {
            const messagesDiv = document.getElementById('messages');
            const messageDiv = document.createElement('div');
            messageDiv.className = 'message';

            if (message.from === currentUser) {
                messageDiv.innerHTML = `<strong>You to ${message.to}:</strong> ${message.text}`;
            } else {
                messageDiv.innerHTML = `<strong>${message.from}:</strong> ${message.text}`;
            }

            messagesDiv.appendChild(messageDiv);
            messagesDiv.scrollTop = messagesDiv.scrollHeight;
        }

        function upgradeToPremium() {
            fetch('/upgrade', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: currentUser })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    showPremiumFeatures();
                    alert('You are now a premium user! Enjoy enhanced notifications and features.');
                }
            })
            .catch(error => console.error('Error:', error));
        }

        function showPremiumFeatures() {
            document.getElementById('premiumBadge').style.display = 'inline';
            document.getElementById('upgradeBtn').style.display = 'none';
        }
    </script>
</body>
</html>
