# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a minimal working version of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = new Map();
const messages = [];
const notifications = [];

// User authentication (simplified)
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  // In a real app, verify credentials against database
  if (username && password) {
    users.set(username, { username, password, online: true });
    res.json({ success: true, username });
  } else {
    res.status(401).json({ success: false, message: 'Invalid credentials' });
  }
});

// Message endpoints
app.post('/api/messages', (req, res) => {
  const { sender, recipient, content } = req.body;
  const message = { id: Date.now(), sender, recipient, content, timestamp: new Date() };
  messages.push(message);

  // Create notification for recipient
  const notification = {
    id: Date.now(),
    user: recipient,
    message: `New message from ${sender}`,
    read: false,
    timestamp: new Date()
  };
  notifications.push(notification);

  // Emit real-time events
  io.to(recipient).emit('new-message', message);
  io.to(recipient).emit('new-notification', notification);

  res.json({ success: true, message });
});

app.get('/api/messages/:username', (req, res) => {
  const username = req.params.username;
  const userMessages = messages.filter(m =>
    m.sender === username || m.recipient === username
  );
  res.json(userMessages);
});

// Notification endpoints
app.get('/api/notifications/:username', (req, res) => {
  const username = req.params.username;
  const userNotifications = notifications.filter(n => n.user === username);
  res.json(userNotifications);
});

app.post('/api/notifications/read', (req, res) => {
  const { notificationId, username } = req.body;
  const notification = notifications.find(n => n.id === notificationId && n.user === username);
  if (notification) {
    notification.read = true;
    res.json({ success: true });
  } else {
    res.status(404).json({ success: false, message: 'Notification not found' });
  }
});

// Monetization endpoints
app.post('/api/purchase', (req, res) => {
  const { username, productId, amount } = req.body;
  // In a real app, process payment through a payment gateway
  console.log(`Processing purchase for ${username}: ${productId} for $${amount}`);

  // Simulate successful purchase
  res.json({
    success: true,
    receipt: {
      id: Date.now(),
      username,
      productId,
      amount,
      timestamp: new Date()
    }
  });
});

// Socket.io connection handling
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (username) => {
    socket.join(username);
    console.log(`${username} joined`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
