let users = {};

// User authentication
app.post('/register', (req, res) => {
  const { username, email, password } = req.body;
  if (users[username]) {
    return res.status(400).json({ error: 'Username already exists' });
  }

  users[username] = { email, password, coins: 100 }; // Starting with 100 coins
  res.status(201).json({ message: 'User registered successfully' });
});

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  const user = users[username];

  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  res.json({ message: 'Login successful', coins: user.coins });
});

// Messaging endpoints
app.post('/messages', (req, res) => {
  const { sender, recipient, content } = req.body;
  const message = { id: Date.now(), sender, recipient, content, timestamp: new Date() };
  messages.push(message);

  // Send push notification (simplified)
  if (users[recipient]) {
    console.log(`Notification sent to ${recipient}: New message from ${sender}`);
  }

  res.status(201).json(message);
});

app.get('/messages/:username', (req, res) => {
  const { username } = req.params;
  const userMessages = messages.filter(m => m.recipient === username || m.sender === username);
  res.json(userMessages);
});

// Monetization endpoints
app.post('/purchase', (req, res) => {
  const { username, item } = req.body;
  const user = users[username];

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Simple pricing model
  const prices = {
    'sticker_pack': 50,
    'premium_badge': 200
  };

  if (!prices[item]) {
    return res.status(400).json({ error: 'Invalid item' });
  }

  if (user.coins < prices[item]) {
    return res.status(400).json({ error: 'Not enough coins' });
  }

  user.coins -= prices[item];
  res.json({ message: 'Purchase successful', remainingCoins: user.coins });
});

// Firebase Cloud Messaging for real-time notifications
app.post('/send-notification', (req, res) => {
  const { token, title, body } = req.body;

  const message = {
    notification: { title, body },
    token: token
  };

  admin.messaging().send(message)
    .then(response => res.json({ success: true, response }))
    .catch(error => res.status(500).json({ error: error.message }));
});

const PORT = process.env.PORT || 3001;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
