# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a minimal working version of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js for the backend, React for the frontend, and Firebase for real-time capabilities and authentication.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const admin = require('firebase-admin');
const cors = require('cors');

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://your-project.firebaseio.com"
});

const app = express();
app.use(cors());
app.use(express.json());

// Firebase Firestore
const db = admin.firestore();

// User authentication
app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const userRecord = await admin.auth().getUserByEmail(email);
    // In a real app, you'd verify password here
    res.json({ uid: userRecord.uid, email: userRecord.email });
  } catch (error) {
    res.status(401).json({ error: 'Authentication failed' });
  }
});

// Send message
app.post('/api/messages', async (req, res) => {
  try {
    const { senderId, receiverId, text } = req.body;

    // Check if user has premium features
    const userDoc = await db.collection('users').doc(senderId).get();
    const hasPremium = userDoc.exists && userDoc.data().premium;

    // Save message
    const messageRef = await db.collection('messages').add({
      senderId,
      receiverId,
      text,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
      read: false,
      premium: hasPremium
    });

    // Send push notification to receiver
    const receiverToken = await db.collection('users').doc(receiverId).get()
      .then(doc => doc.data().fcmToken);

    if (receiverToken) {
      await admin.messaging().send({
        token: receiverToken,
        notification: {
          title: 'New Message',
          body: hasPremium ? '💎 Premium message' : text
        },
        data: {
          messageId: messageRef.id,
          senderId,
          text
        }
      });
    }

    res.json({ success: true, messageId: messageRef.id });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get messages
app.get('/api/messages/:userId', async (req, res) => {
  try {
    const { userId } = req.params;
    const messagesSnapshot = await db.collection('messages')
      .where('receiverId', '==', userId)
      .orderBy('timestamp', 'desc')
      .limit(50)
      .get();

    const messages = [];
    messagesSnapshot.forEach(doc => {
      messages.push({ id: doc.id, ...doc.data() });
    });

    res.json(messages);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Premium subscription endpoint
app.post('/api/subscribe', async (req, res) => {
  try {
    const { userId, paymentToken } = req.body;

    // In a real app, you would verify the payment token with your payment processor

    // Update user premium status
    await db.collection('users').doc(userId).update({
      premium: true,
      premiumSince: admin.firestore.FieldValue.serverTimestamp()
    });

    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## Frontend (React)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { initializeApp } from 'firebase/app';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';
import axios from 'axios';

// Firebase configuration
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

// Initialize Firebase
const firebaseApp = initializeApp(firebaseConfig);
const messaging = getMessaging(firebaseApp);

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [receiverId, setReceiverId] = useState('');
  const [showPremiumModal, setShowPremiumModal] = useState(false);

  // Request notification permission and get token
  useEffect(() => {
    if (user) {
      Notification.requestPermission().then(permission => {
        if (permission === 'granted') {
          getToken(messaging, { vapidKey: 'YOUR_VAPID_KEY' }).then(token => {
            // Store the token in your database
            axios.post('/api/store-token', { userId: user.uid, token });
          });
        }
      });

      // Listen for incoming messages
      const unsubscribe = onMessage(messaging, (payload) => {
        console.log('Message received: ', payload);
        // Update UI or show notification
        new Notification(payload.notification.title, {
          body: payload.notification.body
        });
      });

      return () => unsubscribe();
    }
  }, [user]);

  // Load messages
  useEffect(() => {
    if (user) {
      const fetchMessages = async () => {
        const response = await axios.get(`/api/messages/${user.uid}`);
        setMessages(response.data);
      };
      fetchMessages();
    }
  }, [user]);

  const handleLogin = async (email, password) => {
    try {
      const response = await axios.post('/api/login', { email, password });
      setUser(response.data);
    } catch (error) {
      console.error('Login failed:', error);
    }
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !receiverId) return;

    try {
      await axios.post('/api/messages', {
        senderId: user.uid,
        receiverId,
        text: newMessage
      });
      setNewMessage('');
      // Refresh messages
      const response = await axios.get(`/api/messages/${user.uid}`);
      setMessages(response.data);
    } catch (error) {
      console.error('Error sending message:', error);
    }
  };

  const handleSubscribe = async () => {
    try {
      // In a real app, you would integrate with a payment processor
      await axios.post('/api/subscribe', {
        userId: user.uid,
        paymentToken: 'payment_token_from_processor'
      });
      setUser({ ...user, premium: true });
      setShowPremiumModal(false);
    } catch (error) {
      console.error('Subscription failed:', error);
    }
  };

  if (!user) {
    return (
      <div className="login-container">
        <h1>Social Messenger</h1>
        <input type="email" placeholder="Email" />
        <input type="password" placeholder="Password" />
        <button onClick={() => handleLogin('test@example.com', 'password')}>
          Login
        </button>
      </div>
    );
  }

  return (
    <div className="app">
      <header>
        <h1>Social Messenger</h1>
        {!user.premium && (
          <button onClick={() => setShowPremiumModal(true)}>
            Go Premium
          </button>
        )}
      </header>

      <div className="message-container">
        {messages.map(msg => (
          <div key={msg.id} className={`message ${msg.premium ? 'premium' : ''}`}>
            <strong>{msg.senderId}</strong>: {msg.text}
            {msg.premium && <span className="premium-badge">💎</span>}
          </div>
        ))}
      </div>

      <div className="message-input">
        <input
          type="text"
          value={receiverId}
          onChange={(e) => setReceiverId(e.target.value)}
          placeholder="Receiver ID"
        />
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type your message..."
        />
        <button onClick={handleSendMessage}>Send</button>
      </div>

      {showPremiumModal && (
        <div className="modal">
          <div className="modal-content">
            <h2>Go Premium</h2>
            <p>Unlock special features with our premium subscription!</p>
            <ul>
              <li>💎 Premium message badges</li>
              <li>🔒 Priority support</li>
              <li>🎁 Exclusive emojis</li>
            </ul>
            <button onClick={handleSubscribe}>Subscribe for $4.99/month</button>
            <button onClick={() => setShowPremiumModal(false)}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
```

