                borderColor: '#3498db',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.4,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    userChart = new Chart(userCtx, {
        type: 'bar',
        data: {
            labels: [],
            datasets: [{
                label: 'Users',
                data: [],
                backgroundColor: '#2ecc71',
                borderColor: '#27ae60',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Load sample data
function loadSampleData() {
    // Generate some random sample data
    const categories = ['sales', 'revenue', 'users', 'other'];
    const today = new Date();

    for (let i = 0; i < 10; i++) {
        const randomCategory = categories[Math.floor(Math.random() * categories.length)];
        const randomValue = Math.floor(Math.random() * 1000) + 100;
        const randomDate = new Date(today);
        randomDate.setDate(today.getDate() - (10 - i));

        const newData = {
            name: `Data ${i + 1}`,
            value: randomValue,
            category: randomCategory,
            date: randomDate.toISOString().split('T')[0]
        };

        dashboardData.tableData.push(newData);

        // Add to appropriate chart data
        if (randomCategory === 'sales') {
            dashboardData.salesData.push({
                date: randomDate.toLocaleDateString(),
                value: randomValue
            });
        } else if (randomCategory === 'users') {
            dashboardData.userData.push({
                date: randomDate.toLocaleDateString(),
                value: randomValue
            });
        }
    }

    // Calculate summary stats
    dashboardData.totalRevenue = dashboardData.tableData
        .filter(item => item.category === 'revenue')
        .reduce((sum, item) => sum + item.value, 0);

    dashboardData.activeUsers = dashboardData.tableData
        .filter(item => item.category === 'users')
        .reduce((sum, item) => sum + item.value, 0);

    dashboardData.totalSales = dashboardData.tableData
        .filter(item => item.category === 'sales')
        .reduce((sum, item) => sum + item.value, 0);

    // Calculate growth rate (simplified)
    dashboardData.growthRate = Math.floor((dashboardData.totalSales / 1000) * 100);
}

// Update dashboard with current data
function updateDashboard() {
    // Update summary cards
    totalRevenueEl.textContent = `$${dashboardData.totalRevenue.toLocaleString()}`;
    activeUsersEl.textContent = dashboardData.activeUsers.toLocaleString();
    totalSalesEl.textContent = dashboardData.totalSales.toLocaleString();
    growthRateEl.textContent = `${dashboardData.growthRate}%`;

    // Update charts
    updateCharts();

    // Update data table
    updateDataTable();
}

// Update charts with current data
function updateCharts() {
    // Prepare sales data for chart
    const salesLabels = dashboardData.salesData.map(item => item.date);
    const salesValues = dashboardData.salesData.map(item => item.value);

    salesChart.data.labels = salesLabels;
    salesChart.data.datasets[0].data = salesValues;
    salesChart.update();

    // Prepare user data for chart
    const userLabels = dashboardData.userData.map(item => item.date);
    const userValues = dashboardData.userData.map(item => item.value);

    userChart.data.labels = userLabels;
    userChart.data.datasets[0].data = userValues;
    userChart.update();
}

// Update data table
function updateDataTable() {
    // Clear existing rows
    dataTable.innerHTML = '';

    // Add new rows
    dashboardData.tableData.forEach((item, index) => {
        const row = dataTable.insertRow();

        // Name cell
        const nameCell = row.insertCell(0);
        nameCell.textContent = item.name;

        // Value cell
        const valueCell = row.insertCell(1);
        valueCell.textContent = item.value;

        // Category cell
        const categoryCell = row.insertCell(2);
        categoryCell.textContent = item.category.charAt(0).toUpperCase() + item.category.slice(1);

        // Date cell
        const dateCell = row.insertCell(3);
        dateCell.textContent = new Date(item.date).toLocaleDateString();

        // Actions cell
        const actionsCell = row.insertCell(4);
        actionsCell.innerHTML = `
            <button class="action-btn edit-btn" data-index="${index}"><i class="fas fa-edit"></i></button>
            <button class="action-btn delete-btn" data-index="${index}"><i class="fas fa-trash"></i></button>
        `;

        // Add event listeners to action buttons
        const editBtn = actionsCell.querySelector('.edit-btn');
        const deleteBtn = actionsCell.querySelector('.delete-btn');

        editBtn.addEventListener('click', () => editData(index));
        deleteBtn.addEventListener('click', () => deleteData(index));
    });
}

// Set up form submission
function setupForm() {
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const name = document.getElementById('dataName').value;
        const value = parseFloat(document.getElementById('dataValue').value);
        const category = document.getElementById('dataCategory').value;
        const date = document.getElementById('dataDate').value;

        // Create new data object
        const newData = {
            name,
            value,
            category,
            date
        };

        // Add to table data
        dashboardData.tableData.push(newData);

        // Add to appropriate chart data
        if (category === 'sales') {
            dashboardData.salesData.push({
                date: new Date(date).toLocaleDateString(),
                value
            });
        } else if (category === 'users') {
            dashboardData.userData.push({
                date: new Date(date).toLocaleDateString(),
                value
            });
        }

        // Update summary stats
        if (category === 'revenue') {
            dashboardData.totalRevenue += value;
        } else if (category === 'users') {
            dashboardData.activeUsers += value;
        } else if (category === 'sales') {
            dashboardData.totalSales += value;
        }

        // Calculate new growth rate (simplified)
        dashboardData.growthRate = Math.floor((dashboardData.totalSales / 1000) * 100);

        // Update dashboard
        updateDashboard();

        // Reset form
        dataForm.reset();

        // Show success message
        alert('Data added successfully!');
    });
}

// Edit data function
function editData(index) {
    const data = dashboardData.tableData[index];

    // Populate form with existing data
    document.getElementById('dataName').value = data.name;
    document.getElementById('dataValue').value = data.value;
    document.getElementById('dataCategory').value = data.category;
    document.getElementById('dataDate').value = data.date;

    // Remove the data from the array (will be re-added when form is submitted)
    dashboardData.tableData.splice(index, 1);

    // Update dashboard
    updateDashboard();
}

// Delete data function
function deleteData(index) {
    if (confirm('Are you sure you want to delete this data?')) {
        const deletedData = dashboardData.tableData[index];

        // Remove from table data
        dashboardData.tableData.splice(index, 1);

        // Remove from appropriate chart data
        if (deletedData.category === 'sales') {
            const salesIndex = dashboardData.salesData.findIndex(item =>
                item.date === new Date(deletedData.date).toLocaleDateString() &&
                item.value === deletedData.value
            );
            if (salesIndex !== -1) {
                dashboardData.salesData.splice(salesIndex, 1);
            }
        } else if (deletedData.category === 'users') {
            const userIndex = dashboardData.userData.findIndex(item =>
                item.date === new Date(deletedData.date).toLocaleDateString() &&
                item.value === deletedData.value
            );
            if (userIndex !== -1) {
                dashboardData.userData.splice(userIndex, 1);
            }
        }

        // Update summary stats
        if (deletedData.category === 'revenue') {
            dashboardData.totalRevenue -= deletedData.value;
        } else if (deletedData.category === 'users') {
            dashboardData.activeUsers -= deletedData.value;
        } else if (deletedData.category === 'sales') {
            dashboardData.totalSales -= deletedData.value;
        }

        // Calculate new growth rate (simplified)
        dashboardData.growthRate = Math.floor((dashboardData.totalSales / 1000) * 100);

        // Update dashboard
        updateDashboard();

        alert('Data deleted successfully!');
    }
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
```

## Features Implemented

