    <script>
        // Sample initial data
        let chartData = {
            labels: ['January', 'February', 'March', 'April', 'May', 'June'],
            datasets: [{
                label: 'Sales Data',
                data: [65, 59, 80, 81, 56, 55],
                backgroundColor: [
                    'rgba(54, 162, 235, 0.5)',
                    'rgba(255, 99, 132, 0.5)',
                    'rgba(75, 192, 192, 0.5)',
                    'rgba(153, 102, 255, 0.5)',
                    'rgba(255, 159, 64, 0.5)',
                    'rgba(255, 205, 86, 0.5)'
                ],
                borderColor: [
                    'rgba(54, 162, 235, 1)',
                    'rgba(255, 99, 132, 1)',
                    'rgba(75, 192, 192, 1)',
                    'rgba(153, 102, 255, 1)',
                    'rgba(255, 159, 64, 1)',
                    'rgba(255, 205, 86, 1)'
                ],
                borderWidth: 1
            }]
        };

        // Chart instances
        let mainChart, secondaryChart;

        // DOM elements
        const dataForm = document.getElementById('dataForm');
        const chartSettingsForm = document.getElementById('chartSettingsForm');
        const refreshBtn = document.getElementById('refreshBtn');
        const clearBtn = document.getElementById('clearBtn');
        const formAlert = document.getElementById('formAlert');

        // Initialize charts
        function initCharts() {
            const mainChartCtx = document.getElementById('mainChart').getContext('2d');
            const secondaryChartCtx = document.getElementById('secondaryChart').getContext('2d');

            mainChart = new Chart(mainChartCtx, {
                type: 'bar',
