        function updateChartData(newData, chartType = 'bar') {
            // Update main chart
            mainChart.data = newData;
            mainChart.config.type = chartType;
            mainChart.update();

            // Update secondary chart with different type
            secondaryChart.data = newData;
            secondaryChart.config.type = chartType === 'bar' ? 'line' : 'bar';
            secondaryChart.update();

            updateStats();
        }

        // Update statistics
        function updateStats() {
            const dataPoints = chartData.datasets[0].data;
            const total = dataPoints.length;
            const sum = dataPoints.reduce((a, b) => a + b, 0);
            const avg = (sum / total).toFixed(2);
            const max = Math.max(...dataPoints);
            const min = Math.min(...dataPoints);

            document.getElementById('totalDataPoints').textContent = total;
            document.getElementById('averageValue').textContent = avg;
            document.getElementById('maxValue').textContent = max;
            document.getElementById('minValue').textContent = min;
