            const value = parseFloat(document.getElementById('dataValue').value);
            const type = document.getElementById('dataType').value;

            if (isNaN(value)) {
                showAlert('Please enter a valid number', 'danger');
                return;
            }

            // Add new data point
            chartData.labels.push(label);
            chartData.datasets[0].data.push(value);

            // Update charts
            updateChartData(chartData, type);

            // Reset form
            dataForm.reset();

            showAlert('Data point added successfully!');
        });

        // Chart settings form handler
        chartSettingsForm.addEventListener('submit', function(e) {
            e.preventDefault();

            const title = document.getElementById('chartTitle').value;
            const type = document.getElementById('chartType').value;

            // Update chart titles
            mainChart.options.plugins = {
                title: {
                    display: true,
                    text: title
                }
            };

            // Update chart types
            mainChart.config.type = type;
            secondaryChart.config.type = type === 'bar' ? 'line' : 'bar';

            // Update charts
            mainChart.update();
            secondaryChart.update();

            showAlert('Chart settings updated!');
        });

        // Refresh button handler
        refreshBtn.addEventListener('click', function() {
            // Simulate fetching new data
            const newData = chartData.datasets[0].data.map(val => val + Math.floor(Math.random() * 10) - 5);
            chartData.datasets[0].data = newData;

            updateChartData(chartData);
            showAlert('Data refreshed with new values!');
        });

        // Clear button handler
        clearBtn.addEventListener('click', function() {
            if (confirm('Are you sure you want to clear all data?')) {
                chartData.labels = [];
                chartData.datasets[0].data = [];
                updateChartData(chartData);
                showAlert('All data cleared!');
            }
        });

        // Initialize the dashboard when the page loads
        window.addEventListener('load', function() {
            initCharts();

            // Simulate real-time updates
            setInterval(() => {
                // Add random data point every 10 seconds
                const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                const month = months[Math.floor(Math.random() * months.length)];
                const value = Math.floor(Math.random() * 100);

                chartData.labels.push(month);
                chartData.datasets[0].data.push(value);

                // Keep only the last 10 data points
                if (chartData.labels.length > 10) {
                    chartData.labels.shift();
                    chartData.datasets[0].data.shift();
                }

                updateChartData(chartData);
            }, 10000);
        });
    </script>
</body>
</html>
