## JavaScript (script.js)

```javascript
// Dashboard application
document.addEventListener('DOMContentLoaded', function() {
    // Initialize dashboard components
    const dashboard = {
        chart: null,
        data: [],
        intervalId: null,
        currentDataSource: 'sales',
        currentTimeRange: '24h',
        updateInterval: 5000, // 5 seconds
        chartColors: {
            sales: 'rgba(52, 152, 219, 0.7)',
            traffic: 'rgba(46, 204, 113, 0.7)',
            temperature: 'rgba(231, 76, 60, 0.7)'
        }
    };

    // Initialize the chart
    function initChart() {
        const ctx = document.getElementById('main-chart').getContext('2d');

        dashboard.chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [{
                    label: 'Value',
                    data: [],
                    backgroundColor: dashboard.chartColors[dashboard.currentDataSource],
                    borderColor: dashboard.chartColors[dashboard.currentDataSource],
                    borderWidth: 2,
                    tension: 0.3,
                    fill: true
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: false
                    }
                },
                plugins: {
                    tooltip: {
                        mode: 'index',
                        intersect: false
                    }
                }
            }
        });
    }

    // Update the chart with new data
    function updateChart() {
        if (!dashboard.chart) return;

        // Generate or fetch new data based on current settings
        const newData = generateData(dashboard.currentDataSource, dashboard.currentTimeRange);

        // Update chart data
        dashboard.chart.data.labels = newData.labels;
        dashboard.chart.data.datasets[0].data = newData.values;
        dashboard.chart.data.datasets[0].backgroundColor = dashboard.chartColors[dashboard.currentDataSource];
        dashboard.chart.data.datasets[0].borderColor = dashboard.chartColors[dashboard.currentDataSource];
        dashboard.chart.update();

        // Update chart title
        const titleMap = {
            'sales': 'Sales Data',
            'traffic': 'Website Traffic',
            'temperature': 'Temperature'
        };
        const rangeMap = {
            '24h': 'Last 24 Hours',
            '7d': 'Last 7 Days',
            '30d': 'Last 30 Days'
        };
        document.getElementById('chart-title').textContent =
            `${titleMap[dashboard.currentDataSource]} - ${rangeMap[dashboard.currentTimeRange]}`;

        // Update summary statistics
        updateSummaryStats(newData.values);

        // Update data table
        updateDataTable(newData);
    }

    // Generate mock data based on parameters
    function generateData(dataSource, timeRange) {
        const now = new Date();
        const dataPoints = timeRange === '24h' ? 24 :
                          timeRange === '7d' ? 7 : 30;

        const labels = [];
        const values = [];

        for (let i = dataPoints - 1; i >= 0; i--) {
            const date = new Date(now);
            if (timeRange === '24h') {
                date.setHours(now.getHours() - i);
                labels.push(date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
            } else {
                date.setDate(now.getDate() - i);
                labels.push(date.toLocaleDateString());
            }

            // Generate different data patterns based on data source
            let value;
            switch(dataSource) {
                case 'sales':
                    value = Math.floor(Math.random() * 1000) + 500;
                    break;
                case 'traffic':
                    value = Math.floor(Math.random() * 5000) + 1000;
                    break;
                case 'temperature':
                    value = Math.floor(Math.random() * 20) + 10;
                    break;
                default:
                    value = Math.random() * 100;
            }

            // Add some variation to make it look more realistic
            if (i > 0) {
                const prevValue = values[values.length - 1];
                const change = (Math.random() - 0.5) * 0.2 * prevValue;
                value = prevValue + change;
            }

            values.push(Math.round(value * 10) / 10);
        }

        return { labels, values };
    }

    // Update summary statistics
    function updateSummaryStats(data) {
        if (data.length === 0) return;

        const total = data.reduce((sum, val) => sum + val, 0);
        const average = total / data.length;
        const max = Math.max(...data);
        const min = Math.min(...data);

        document.getElementById('total-items').textContent = data.length;
        document.getElementById('average-value').textContent = average.toFixed(1);
        document.getElementById('max-value').textContent = max.toFixed(1);
        document.getElementById('min-value').textContent = min.toFixed(1);
    }

    // Update data table
    function updateDataTable(data) {
        const tableBody = document.querySelector('#data-table tbody');
        tableBody.innerHTML = '';

        // Get the labels from the chart
        const labels = dashboard.chart.data.labels;

        // Create table rows
        for (let i = 0; i < data.values.length; i++) {
            const row = document.createElement('tr');

            // Timestamp cell
            const timestampCell = document.createElement('td');
            timestampCell.textContent = labels[i];
            row.appendChild(timestampCell);

            // Value cell
            const valueCell = document.createElement('td');
            valueCell.textContent = data.values[i];
            row.appendChild(valueCell);

            // Change cell (show change from previous value)
            const changeCell = document.createElement('td');
            if (i > 0) {
                const change = data.values[i] - data.values[i-1];
                const changePercent = (change / data.values[i-1]) * 100;

                changeCell.textContent = `${change.toFixed(1)} (${changePercent.toFixed(1)}%)`;
                changeCell.style.color = change >= 0 ? 'var(--success-color)' : 'var(--danger-color)';
            } else {
                changeCell.textContent = '-';
            }
            row.appendChild(changeCell);

            tableBody.appendChild(row);
        }
    }

    // Update date and time display
    function updateDateTime() {
        const now = new Date();
        document.getElementById('current-date').textContent = now.toLocaleDateString();
        document.getElementById('current-time').textContent = now.toLocaleTimeString();
    }

    // Set up form submission handler
    function setupForm() {
        const form = document.getElementById('data-form');

        form.addEventListener('submit', function(e) {
            e.preventDefault();

            // Update dashboard settings
            dashboard.currentDataSource = document.getElementById('data-source').value;
            dashboard.currentTimeRange = document.getElementById('time-range').value;
            dashboard.updateInterval = parseInt(document.getElementById('update-interval').value) * 1000;

            // Clear any existing interval
            if (dashboard.intervalId) {
                clearInterval(dashboard.intervalId);
            }

            // Update the chart immediately
            updateChart();

            // Set up new interval for updates
            dashboard.intervalId = setInterval(updateChart, dashboard.updateInterval);
        });
    }

    // Initialize the dashboard
    function initDashboard() {
        initChart();
        updateDateTime();
        setupForm();

        // Initial data load
        updateChart();

        // Set up interval for automatic updates
        dashboard.intervalId = setInterval(updateChart, dashboard.updateInterval);

        // Set up interval for date/time updates
        setInterval(updateDateTime, 1000);
    }

    // Start the dashboard
    initDashboard();
});
```

## Features of this Dashboard

1. **Real-Time Data Visualization**:
   - Interactive line chart using Chart.js
   - Automatic updates at configurable intervals
   - Different data patterns for different data sources

2. **Form Handling**:
   - Configuration form to select data source and time range
   - Adjustable update interval
   - Immediate updates when form is submitted

3. **Summary Statistics**:
   - Calculates and displays total items, average, max, and min values
   - Updates automatically with new data

4. **Data Table**:
   - Displays raw data in a scrollable table
   - Shows timestamp, value, and change from previous value
   - Color-coded changes (green for increases, red for decreases)

5. **Responsive Design**:
   - Adapts to different screen sizes
   - Mobile-friendly layout

6. **Current Date/Time Display**:
   - Shows the current date and time
   - Updates every second

## How to Use

1. Save the three files (index.html, styles.css, script.js) in the same directory
2. Open index.html in a web browser
3. Use the form controls to:
   - Select different data sources (Sales, Traffic, Temperature)
   - Choose different time ranges (24h, 7d, 30d)
   - Adjust the update interval
4. The dashboard will automatically update with new data based on your settings

This implementation provides a solid foundation that you can extend with additional features like:
- More data sources
- Additional chart types
- User authentication
- Data export functionality
- More detailed statistics
- Theming options

