            const salesCtx = document.getElementById('salesChart').getContext('2d');
            salesChart = new Chart(salesCtx, {
                type: 'line',
                data: salesData,
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            const userActivityCtx = document.getElementById('userActivityChart').getContext('2d');
            userActivityChart = new Chart(userActivityCtx, {
                type: 'bar',
                data: userActivityData,
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }

        // Update stats cards
        function updateStats() {
            document.getElementById('totalSales').textContent = `$${salesData.datasets[0].data.reduce((a, b) => a + b, 0)}`;
            document.getElementById('activeUsers').textContent = userActivityData.datasets[0].data[userActivityData.datasets[0].data.length - 1];
            document.getElementById('conversionRate').textContent = `${Math.floor(Math.random() * 30) + 5}%`;
            document.getElementById('newSignups').textContent = Math.floor(Math.random() * 500) + 100;
        }

        // Update current date and time
        function updateDateTime() {
            const now = new Date();
            const options = {
                weekday: 'long',
                year: 'numeric',
                month: 'long',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            };
            document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
        }

        // Simulate data update
        function updateData() {
            // Update sales data
            salesData.datasets[0].data.push(Math.floor(Math.random() * 20000) + 1000);
            salesData.labels.push(`Week ${salesData.labels.length + 1}`);
            if (salesData.datasets[0].data.length > 6) {
                salesData.datasets[0].data.shift();
                salesData.labels.shift();
            }

            // Update user activity data
            userActivityData.datasets[0].data.push(Math.floor(Math.random() * 2000) + 500);
            userActivityData.labels.push(`Week ${userActivityData.labels.length + 1}`);
            if (userActivityData.datasets[0].data.length > 6) {
                userActivityData.datasets[0].data.shift();
                userActivityData.labels.shift();
            }

            // Update charts
            salesChart.update();
            userActivityChart.update();

            // Update stats
            updateStats();
        }

        // Form handling
        document.getElementById('dataForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const name = document.getElementById('dataName').value;
            const value = document.getElementById('dataValue').value;
            const category = document.getElementById('dataCategory').value;
            const description = document.getElementById('dataDescription').value;

            // Add to table
            const table = document.getElementById('dataTable').getElementsByTagName('tbody')[0];
            const newRow = table.insertRow();
            newRow.innerHTML = `
                <td>${name}</td>
                <td>${value}</td>
                <td>${category}</td>
                <td>${new Date().toLocaleDateString()}</td>
            `;

            // Show success message
            const alert = document.getElementById('alertMessage');
            alert.textContent = 'Data submitted successfully!';
            alert.className = 'alert alert-success';
            alert.style.display = 'block';

            // Hide alert after 3 seconds
            setTimeout(() => {
                alert.style.display = 'none';
            }, 3000);

            // Reset form
            this.reset();
        });

        // Filter form handling
        document.getElementById('filterForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const dateRange = document.getElementById('dateRange').value;
            const dataType = document.getElementById('dataType').value;

            // In a real app, you would fetch filtered data here
            console.log(`Applying filters: Date Range - ${dateRange} days, Data Type - ${dataType}`);

            // Simulate data update
            updateData();

            // Show alert
            const alert = document.getElementById('alertMessage');
            alert.textContent = 'Filters applied successfully!';
            alert.className = 'alert alert-success';
            alert.style.display = 'block';

            setTimeout(() => {
                alert.style.display = 'none';
            }, 3000);
        });

        // Refresh data button
        document.getElementById('refreshData').addEventListener('click', function() {
            updateData();

            // Show alert
            const alert = document.getElementById('alertMessage');
            alert.textContent = 'Data refreshed successfully!';
            alert.className = 'alert alert-success';
            alert.style.display = 'block';

            setTimeout(() => {
                alert.style.display = 'none';
            }, 3000);
        });

        // Export data button
        document.getElementById('exportData').addEventListener('click', function() {
            // In a real app, you would implement actual export functionality
            alert('Data export functionality would be implemented here.');

            // Show alert
            const alert = document.getElementById('alertMessage');
            alert.textContent = 'Data export initiated!';
            alert.className = 'alert alert-success';
            alert.style.display = 'block';

            setTimeout(() => {
                alert.style.display = 'none';
            }, 3000);
        });

        // Initialize the dashboard
        document.addEventListener('DOMContentLoaded', function() {
            initCharts();
            updateStats();
            updateDateTime();

            // Update date/time every minute
            setInterval(updateDateTime, 60000);

            // Simulate data updates every 5 seconds
            setInterval(updateData, 5000);
        });
    </script>
</body>
</html>
