## JavaScript (script.js)

```javascript
// Initialize charts
let salesChart, userGrowthChart;

// Sample data
let dashboardData = {
    totalUsers: 1250,
    totalRevenue: 45200,
    totalOrders: 890,
    salesData: [120, 190, 150, 170, 220, 200, 250],
    userGrowthData: [50, 100, 150, 200, 250, 300, 350],
    activities: [
        { type: 'order', message: 'New order received from John Doe', time: '2 minutes ago' },
        { type: 'user', message: 'New user registered: Sarah Johnson', time: '15 minutes ago' },
        { type: 'payment', message: 'Payment processed for order #12345', time: '1 hour ago' },
        { type: 'system', message: 'System maintenance completed', time: '2 hours ago' }
    ]
};

// Update date and time
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('sales-chart').getContext('2d');
    const userGrowthCtx = document.getElementById('user-growth-chart').getContext('2d');

    // Sales chart
    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul'],
            datasets: [{
                label: 'Sales',
                data: dashboardData.salesData,
                backgroundColor: 'rgba(54, 162, 235, 0.2)',
                borderColor: 'rgba(54, 162, 235, 1)',
                borderWidth: 2,
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // User growth chart
    userGrowthChart = new Chart(userGrowthCtx, {
        type: 'bar',
        data: {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul'],
            datasets: [{
                label: 'Users',
                data: dashboardData.userGrowthData,
                backgroundColor: 'rgba(46, 204, 113, 0.7)',
                borderColor: 'rgba(46, 204, 113, 1)',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Update dashboard stats
function updateStats() {
    document.getElementById('total-users').textContent = dashboardData.totalUsers.toLocaleString();
    document.getElementById('total-revenue').textContent = `$${dashboardData.totalRevenue.toLocaleString()}`;
    document.getElementById('total-orders').textContent = dashboardData.totalOrders.toLocaleString();
}

// Update activity list
function updateActivityList() {
    const activityList = document.getElementById('activity-list');
    activityList.innerHTML = '';

    dashboardData.activities.forEach(activity => {
        const activityItem = document.createElement('div');
        activityItem.className = 'activity-item';

        let iconClass, iconColor;
        switch(activity.type) {
            case 'order':
                iconClass = 'fas fa-shopping-cart';
                iconColor = '#3498db';
                break;
            case 'user':
                iconClass = 'fas fa-user-plus';
                iconColor = '#2ecc71';
                break;
            case 'payment':
                iconClass = 'fas fa-credit-card';
                iconColor = '#f39c12';
                break;
            default:
                iconClass = 'fas fa-info-circle';
                iconColor = '#95a5a6';
        }

        activityItem.innerHTML = `
            <div class="activity-icon" style="background-color: ${iconColor};">
                <i class="${iconClass}"></i>
            </div>
            <div class="activity-content">
                <h4>${activity.message}</h4>
                <p class="activity-time">${activity.time}</p>
            </div>
        `;

        activityList.appendChild(activityItem);
    });
}

// Handle form submission
function setupForm() {
    const form = document.getElementById('data-form');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const label = document.getElementById('data-label').value;
        const value = parseInt(document.getElementById('data-value').value);
        const color = document.getElementById('data-color').value;

        // Add new data to sales chart
        const newData = [...salesChart.data.datasets[0].data];
        newData.push(value);

        salesChart.data.datasets[0].data = newData;
        salesChart.data.labels.push(label);
        salesChart.data.datasets[0].backgroundColor.push(`${color}80`); // Add transparency
        salesChart.data.datasets[0].borderColor.push(color);
        salesChart.update();

        // Add activity
        const newActivity = {
            type: 'system',
            message: `New data point added: ${label} (${value})`,
            time: 'Just now'
        };

        dashboardData.activities.unshift(newActivity);
        if (dashboardData.activities.length > 5) {
            dashboardData.activities.pop();
        }

        updateActivityList();

        // Reset form
        form.reset();
    });
}

// Simulate real-time updates
function simulateRealTimeUpdates() {
    setInterval(() => {
        // Update some random data
        dashboardData.totalUsers += Math.floor(Math.random() * 10);
        dashboardData.totalRevenue += Math.floor(Math.random() * 500);
        dashboardData.totalOrders += Math.floor(Math.random() * 5);

        // Update sales data
        const newSalesValue = dashboardData.salesData[dashboardData.salesData.length - 1] +
                             Math.floor(Math.random() * 20) - 10;
        dashboardData.salesData.push(newSalesValue);
        if (dashboardData.salesData.length > 7) {
            dashboardData.salesData.shift();
        }

        // Update user growth data
        const newUserValue = dashboardData.userGrowthData[dashboardData.userGrowthData.length - 1] +
                           Math.floor(Math.random() * 10);
        dashboardData.userGrowthData.push(newUserValue);
        if (dashboardData.userGrowthData.length > 7) {
            dashboardData.userGrowthData.shift();
        }

        // Update charts and stats
        salesChart.data.datasets[0].data = dashboardData.salesData;
        userGrowthChart.data.datasets[0].data = dashboardData.userGrowthData;
        salesChart.update();
        userGrowthChart.update();
        updateStats();

        // Add new activity
        const activities = [
            'New user registered',
            'Order completed',
            'Payment processed',
            'System update',
            'New feature added'
        ];

        const newActivity = {
            type: ['user', 'order', 'payment', 'system', 'system'][Math.floor(Math.random() * 5)],
            message: activities[Math.floor(Math.random() * activities.length)],
            time: 'Just now'
        };

        dashboardData.activities.unshift(newActivity);
        if (dashboardData.activities.length > 5) {
            dashboardData.activities.pop();
        }

        updateActivityList();
    }, 10000); // Update every 10 seconds
}

// Initialize the dashboard
function initDashboard() {
    updateDateTime();
    setInterval(updateDateTime, 1000);
    initCharts();
    updateStats();
    updateActivityList();
    setupForm();
    simulateRealTimeUpdates();
}

// Start the dashboard when the page loads
window.addEventListener('DOMContentLoaded', initDashboard);
```

