// Update summary cards with latest data
function updateSummaryCards() {
    document.getElementById('total-users').textContent = dashboardData.users[dashboardData.users.length - 1];
    document.getElementById('total-revenue').textContent = `$${dashboardData.revenue[dashboardData.revenue.length - 1]}`;
    document.getElementById('active-sessions').textContent = dashboardData.sessions[dashboardData.sessions.length - 1];
}

// Set up form submission
function setupForm() {
    const form = document.getElementById('data-form');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const label = document.getElementById('data-label').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const color = document.getElementById('data-color').value;

        // Add to custom data
        const newData = {
            label: label,
            value: value,
            color: color,
            timestamp: new Date().toLocaleString()
        };

        dashboardData.customData.push(newData);

        // Update charts with new data
        updateCustomDataChart();

        // Add to table
        addDataToTable(newData);

        // Reset form
        form.reset();

        // Show success message
        alert('Data added successfully!');
    });
}

// Update the main chart with custom data
function updateCustomDataChart() {
    if (dashboardData.customData.length === 0) return;

    // Prepare data for the chart
    const labels = dashboardData.customData.map(item => item.label);
    const values = dashboardData.customData.map(item => item.value);
    const colors = dashboardData.customData.map(item => item.color);

    // Update main chart
    mainChart.data.labels = labels;
    mainChart.data.datasets = [{
        label: 'Custom Data',
        data: values,
        backgroundColor: colors,
        borderColor: colors.map(color => darkenColor(color, 0.2)),
        borderWidth: 1
    }];

    mainChart.update();
}

// Add data to the table
function addDataToTable(data) {
    const tableBody = document.querySelector('#data-table tbody');
    const row = document.createElement('tr');

    row.innerHTML = `
        <td>${data.label}</td>
        <td>${data.value}</td>
        <td>${data.timestamp}</td>
        <td>
            <button class="btn-action btn-edit" onclick="editData('${data.label}')"><i class="fas fa-edit"></i></button>
            <button class="btn-action btn-delete" onclick="deleteData('${data.label}')"><i class="fas fa-trash"></i></button>
        </td>
    `;

    tableBody.appendChild(row);
}

// Edit data (placeholder function)
function editData(label) {
    alert(`Edit functionality for "${label}" would be implemented here.`);
}

// Delete data
function deleteData(label) {
    if (confirm(`Are you sure you want to delete "${label}"?`)) {
        // Remove from custom data
        dashboardData.customData = dashboardData.customData.filter(item => item.label !== label);

        // Update charts
        updateCustomDataChart();

        // Remove from table
        const rows = document.querySelectorAll('#data-table tbody tr');
        rows.forEach(row => {
            if (row.cells[0].textContent === label) {
                row.remove();
            }
        });
    }
}

// Helper function to darken a color
function darkenColor(color, amount) {
    // Convert hex to RGB
    let r = parseInt(color.substring(1, 3), 16);
    let g = parseInt(color.substring(3, 5), 16);
    let b = parseInt(color.substring(5, 7), 16);

    // Darken each channel
    r = Math.max(0, Math.min(255, r - (255 * amount)));
    g = Math.max(0, Math.min(255, g - (255 * amount)));
    b = Math.max(0, Math.min(255, b - (255 * amount)));

    // Convert back to hex
    return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
}

// Load sample data
function loadSampleData() {
    // Add some sample data
    const sampleData = [
        { label: 'Product A', value: 120, color: '#36a2eb', timestamp: new Date().toLocaleString() },
        { label: 'Product B', value: 85, color: '#ff6384', timestamp: new Date().toLocaleString() },
        { label: 'Product C', value: 150, color: '#4bc0c0', timestamp: new Date().toLocaleString() }
    ];

    sampleData.forEach(data => {
        dashboardData.customData.push(data);
        addDataToTable(data);
    });

    updateCustomDataChart();
}
