    <script>
        // Dashboard state
        const state = {
            dataPoints: [],
            maxDataPoints: 50,
            updateInterval: 5000,
            isUpdating: true,
            chartType: 'line',
            currentDataType: 'temperature'
        };

        // DOM elements
        const elements = {
            dataForm: document.getElementById('dataForm'),
            clearForm: document.getElementById('clearForm'),
            applySettings: document.getElementById('applySettings'),
            pauseUpdates: document.getElementById('pauseUpdates'),
            resumeUpdates: document.getElementById('resumeUpdates'),
            currentDateTime: document.getElementById('currentDateTime'),
            currentValue: document.getElementById('currentValue'),
            averageValue: document.getElementById('averageValue'),
            minValue: document.getElementById('minValue'),
            maxValue: document.getElementById('maxValue'),
            successAlert: document.getElementById('successAlert'),
            errorAlert: document.getElementById('errorAlert'),
            dataChart: document.getElementById('dataChart')
        };

        // Initialize Chart.js
        let chart;
        function initChart() {
            const ctx = elements.dataChart.getContext('2d');

            chart = new Chart(ctx, {
                type: state.chartType,
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Data Values',
                        data: [],
                        borderColor: 'rgba(52, 152, 219, 1)',
                        backgroundColor: 'rgba(52, 152, 219, 0.2)',
                        borderWidth: 2,
                        tension: 0.1,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: false
                        }
                    },
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top'
                        }
                    }
                }
            });
        }

        // Update chart with new data
        function updateChart() {
            if (!chart) return;

            // Update chart type if changed
            if (chart.config.type !== state.chartType) {
                chart.destroy();
                initChart();
            }

            // Update chart data
            const labels = state.dataPoints.map((_, index) => index + 1);
            const data = state.dataPoints.map(point => point.value);

            chart.data.labels = labels;
            chart.data.datasets[0].data = data;
            chart.data.datasets[0].label = `${state.currentDataType} (${state.dataPoints[0]?.unit || ''})`;

            // Update chart colors based on data type
            const colorMap = {
                'temperature': 'rgba(231, 76, 60, 1)',
                'humidity': 'rgba(46, 204, 113, 1)',
                'pressure': 'rgba(52, 152, 219, 1)',
                'voltage': 'rgba(155, 89, 182, 1)'
            };

            const color = colorMap[state.currentDataType] || 'rgba(52, 152, 219, 1)';
            chart.data.datasets[0].borderColor = color;
            chart.data.datasets[0].backgroundColor = `${color.replace('1)', '0.2)')}`;

            chart.update();
        }

        // Update statistics display
        function updateStats() {
            if (state.dataPoints.length === 0) {
                elements.currentValue.textContent = '0.00';
                elements.averageValue.textContent = '0.00';
                elements.minValue.textContent = '0.00';
                elements.maxValue.textContent = '0.00';
                return;
            }

            const values = state.dataPoints.map(point => point.value);
            const current = values[values.length - 1];
            const sum = values.reduce((a, b) => a + b, 0);
            const avg = sum / values.length;
            const min = Math.min(...values);
            const max = Math.max(...values);

            elements.currentValue.textContent = current.toFixed(2);
            elements.averageValue.textContent = avg.toFixed(2);
            elements.minValue.textContent = min.toFixed(2);
            elements.maxValue.textContent = max.toFixed(2);
        }

        // Update current date and time
        function updateDateTime() {
            const now = new Date();
            elements.currentDateTime.textContent = now.toLocaleString();
        }

        // Generate random data for demo purposes
        function generateRandomData() {
            if (!state.isUpdating) return;

            const min = 20;
            const max = 100;
            const value = Math.random() * (max - min) + min;

            const dataPoint = {
                type: state.currentDataType,
                value: parseFloat(value.toFixed(2)),
                unit: getUnitForType(state.currentDataType),
                timestamp: new Date().toISOString(),
                notes: 'Simulated data'
            };

            addDataPoint(dataPoint);
        }

        // Get appropriate unit for data type
        function getUnitForType(type) {
            const units = {
                'temperature': '°C',
                'humidity': '%',
                'pressure': 'kPa',
                'voltage': 'V'
            };
            return units[type] || '';
        }

        // Add a new data point to the dataset
        function addDataPoint(dataPoint) {
            state.dataPoints.push(dataPoint);

            // Limit the number of data points
            if (state.dataPoints.length > state.maxDataPoints) {
                state.dataPoints.shift();
            }

            updateChart();
            updateStats();
        }

        // Handle form submission
        elements.dataForm.addEventListener('submit', function(e) {
            e.preventDefault();

            // Get form values
            const dataType = document.getElementById('dataType').value;
            const dataValue = document.getElementById('dataValue').value;
            const dataUnit = document.getElementById('dataUnit').value;
            const dataNotes = document.getElementById('dataNotes').value;

            if (!dataType || !dataValue || !dataUnit) {
                showAlert('error');
                return;
            }

            // Create data point
            const dataPoint = {
                type: dataType,
                value: parseFloat(dataValue),
                unit: dataUnit,
                timestamp: new Date().toISOString(),
                notes: dataNotes
            };

            // Update current data type
            state.currentDataType = dataType;

            // Add to dataset
            addDataPoint(dataPoint);

            // Show success message
            showAlert('success');

            // Reset form
            elements.dataForm.reset();
        });

        // Clear form
        elements.clearForm.addEventListener('click', function() {
            elements.dataForm.reset();
            hideAlerts();
        });

        // Apply settings
        elements.applySettings.addEventListener('click', function() {
            const interval = parseInt(document.getElementById('updateInterval').value);
            const chartType = document.getElementById('chartType').value;

            if (interval >= 1000 && interval <= 60000) {
                state.updateInterval = interval;
                clearInterval(window.dataUpdateInterval);
                window.dataUpdateInterval = setInterval(generateRandomData, state.updateInterval);
            }

            if (chartType) {
                state.chartType = chartType;
                updateChart();
            }

            showAlert('success', 'Settings applied successfully!');
        });

        // Pause updates
        elements.pauseUpdates.addEventListener('click', function() {
            state.isUpdating = false;
            clearInterval(window.dataUpdateInterval);
            showAlert('success', 'Updates paused');
        });

        // Resume updates
        elements.resumeUpdates.addEventListener('click', function() {
            state.isUpdating = true;
            window.dataUpdateInterval = setInterval(generateRandomData, state.updateInterval);
            showAlert('success', 'Updates resumed');
        });

        // Show alert message
        function showAlert(type, message = null) {
            hideAlerts();

            if (type === 'success') {
                elements.successAlert.textContent = message || 'Operation completed successfully!';
                elements.successAlert.style.display = 'block';
            } else if (type === 'error') {
                elements.errorAlert.textContent = message || 'An error occurred. Please try again.';
                elements.errorAlert.style.display = 'block';
            }

            // Hide alert after 3 seconds
            setTimeout(hideAlerts, 3000);
        }

        // Hide all alerts
        function hideAlerts() {
            elements.successAlert.style.display = 'none';
            elements.errorAlert.style.display = 'none';
        }

        // Initialize the dashboard
        function initDashboard() {
            // Initialize chart
            initChart();

            // Set up initial data
            for (let i = 0; i < 10; i++) {
                generateRandomData();
            }

            // Update date/time every second
            updateDateTime();
            setInterval(updateDateTime, 1000);

            // Set up automatic data updates
            window.dataUpdateInterval = setInterval(generateRandomData, state.updateInterval);
        }

        // Start the dashboard when the page loads
        window.addEventListener('load', initDashboard);
    </script>
</body>
</html>
```

## Features of this Dashboard:

1. **Real-Time Data Visualization**:
   - Interactive line chart that updates in real-time
   - Supports both line and bar chart types
   - Dynamic color coding based on data type

2. **Form Handling**:
   - Form for adding new data points
   - Input validation
   - Success/error feedback messages
   - Clear form functionality

3. **Dashboard Controls**:
   - Adjustable update interval
   - Pause/resume functionality
   - Chart type selection

4. **Statistics Display**:
   - Current value
   - Average value
   - Minimum value
   - Maximum value

5. **Responsive Design**:
   - Works on desktop and mobile devices
   - Adapts layout based on screen size

6. **User Feedback**:
