                const newRow = table.insertRow();

                // Insert cells
                const typeCell = newRow.insertCell(0);
                const periodCell = newRow.insertCell(1);
                const dateCell = newRow.insertCell(2);
                const formatCell = newRow.insertCell(3);
                const actionsCell = newRow.insertCell(4);

                // Set cell values
                typeCell.textContent = type.charAt(0).toUpperCase() + type.slice(1) + ' Report';
                periodCell.textContent = period.charAt(0).toUpperCase() + period.slice(1);
                dateCell.textContent = new Date().toLocaleDateString();
                formatCell.textContent = format.toUpperCase();

                // Add action buttons
                const downloadBtn = document.createElement('button');
                downloadBtn.textContent = 'Download';
                downloadBtn.className = 'btn btn-secondary';
                downloadBtn.style.marginRight = '5px';
                downloadBtn.style.padding = '5px 10px';

                const deleteBtn = document.createElement('button');
                deleteBtn.textContent = 'Delete';
                deleteBtn.className = 'btn btn-danger';
                deleteBtn.style.padding = '5px 10px';

                actionsCell.appendChild(downloadBtn);
                actionsCell.appendChild(deleteBtn);

                // Add event listeners for actions
                downloadBtn.addEventListener('click', function() {
                    alert(`Downloading ${type} report in ${format.toUpperCase()} format.`);
                });

                deleteBtn.addEventListener('click', function() {
                    if (confirm('Are you sure you want to delete this report?')) {
                        table.deleteRow(newRow.rowIndex - 1);
                    }
                });

                // Reset form
                form.reset();
            });
        }

        function setupSettingsForm() {
            const form = document.getElementById('settings-form');

            form.addEventListener('submit', function(e) {
                e.preventDefault();

                // Get form values
                const theme = document.getElementById('theme').value;
                const refreshRate = document.getElementById('refresh-rate').value;
                const notifications = document.getElementById('notifications').value;

                // In a real app, you would save these settings to localStorage or a backend
                alert(`Settings saved:\nTheme: ${theme}\nRefresh Rate: ${refreshRate} seconds\nNotifications: ${notifications}`);
            });
        }

        function simulateRealTimeData() {
            // Update stats every 5 seconds
            setInterval(() => {
                document.getElementById('total-users').textContent = Math.floor(Math.random() * 1000) + 1000;
                document.getElementById('active-sessions').textContent = Math.floor(Math.random() * 500) + 500;
                document.getElementById('conversion-rate').textContent = (Math.random() * 10).toFixed(1) + '%';
                document.getElementById('revenue').textContent = '$' + (Math.random() * 100000).toFixed(2);
            }, 5000);

            // Update charts every 10 seconds
            setInterval(() => {
                // Update user growth chart
                userGrowthChart.data.datasets[0].data = generateRandomData(
                    userGrowthChart.data.labels.length,
                    100,
                    500
                );
                userGrowthChart.update();

                // Update revenue chart
                revenueChart.data.datasets[0].data = generateRandomData(
                    revenueChart.data.labels.length,
                    1000,
                    10000
                );
                revenueChart.update();
            }, 10000);
        }
    </script>
</body>
</html>
```

