## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Data',
                data: [],
                borderColor: '#3498db',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Tab navigation
    const tabLinks = document.querySelectorAll('.navigation a');
    const tabContents = document.querySelectorAll('.tab-content');

    tabLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();

            // Remove active class from all links
            tabLinks.forEach(l => l.parentElement.classList.remove('active'));

            // Add active class to clicked link
            this.parentElement.classList.add('active');

            // Hide all tab contents
            tabContents.forEach(content => content.style.display = 'none');

            // Show the selected tab content
            const tabId = this.getAttribute('data-tab');
            document.getElementById(tabId).style.display = 'block';
        });
    });

    // Real-time data simulation
    let updateInterval;
    let dataPoints = 20;
    let currentDataType = 'traffic';

    function generateRandomData() {
        const now = new Date();
        const timeString = now.toLocaleTimeString();

        let value;
        switch(currentDataType) {
            case 'traffic':
                value = Math.floor(Math.random() * 1000) + 500;
                break;
            case 'sales':
                value = Math.floor(Math.random() * 50) + 10;
                break;
            case 'temperature':
                value = Math.floor(Math.random() * 30) + 10;
                break;
            default:
                value = Math.random() * 100;
        }

        return { time: timeString, value: value };
    }

    function updateChart() {
        const data = generateRandomData();

        // Add new data point
        realtimeChart.data.labels.push(data.time);
        realtimeChart.data.datasets[0].data.push(data.value);

        // Remove oldest data point if we exceed the limit
        if (realtimeChart.data.labels.length > dataPoints) {
            realtimeChart.data.labels.shift();
            realtimeChart.data.datasets[0].data.shift();
        }

        // Update chart
        realtimeChart.update();

        // Update quick stats
        document.getElementById('activeUsers').textContent = Math.floor(Math.random() * 1000) + 500;
        document.getElementById('systemLoad').textContent = Math.floor(Math.random() * 100) + '%';
        document.getElementById('dataProcessed').textContent = (Math.random() * 100).toFixed(2) + ' MB';
    }

    // Start/Stop buttons
    document.getElementById('startUpdates').addEventListener('click', function() {
        if (!updateInterval) {
            updateInterval = setInterval(updateChart, 2000);
            this.disabled = true;
            document.getElementById('stopUpdates').disabled = false;
        }
    });

    document.getElementById('stopUpdates').addEventListener('click', function() {
        if (updateInterval) {
            clearInterval(updateInterval);
            updateInterval = null;
            this.disabled = true;
            document.getElementById('startUpdates').disabled = false;
        }
    });

    // Data type selector
    document.getElementById('dataType').addEventListener('change', function() {
        currentDataType = this.value;

        // Clear existing data
        realtimeChart.data.labels = [];
        realtimeChart.data.datasets[0].data = [];

        // Update chart title
        realtimeChart.data.datasets[0].label = this.options[this.selectedIndex].text;

        // Update chart
        realtimeChart.update();
    });

    // Report form handling
    document.getElementById('reportForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const formData = new FormData(this);
        const reportStatus = document.getElementById('reportStatus');

        // Simulate report generation
        reportStatus.className = 'report-status';
        reportStatus.textContent = 'Generating report...';
        reportStatus.style.display = 'block';

        // Simulate API call
        setTimeout(() => {
            // Random success/failure
            const success = Math.random() > 0.2;

            if (success) {
                reportStatus.className = 'report-status success';
                reportStatus.textContent = `Report generated successfully! It will be sent to ${formData.get('email')}.`;
            } else {
                reportStatus.className = 'report-status error';
                reportStatus.textContent = 'Failed to generate report. Please try again.';
            }
        }, 2000);
    });

    // Settings form handling
    document.getElementById('settingsForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const formData = new FormData(this);

        // Apply theme
        if (formData.get('theme') === 'dark') {
            document.body.classList.add('dark-theme');
        } else {
            document.body.classList.remove('dark-theme');
        }

        // Apply refresh rate
        const refreshRate = parseInt(formData.get('refreshRate'));
        if (updateInterval) {
            clearInterval(updateInterval);
            updateInterval = setInterval(updateChart, refreshRate * 1000);
        }

        // Show notification (simulated)
        if (formData.get('notifications') === 'on') {
            alert('Settings saved! Notifications are enabled.');
        } else {
            alert('Settings saved! Notifications are disabled.');
        }
    });

    // Initialize with some data
    for (let i = 0; i < dataPoints; i++) {
        updateChart();
    }
});

function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}
