    <script>
        // Initialize charts
        document.addEventListener('DOMContentLoaded', function() {
            // Sample data for charts
            const salesData = {
                labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
                datasets: [{
                    label: 'Sales',
                    data: [12000, 15000, 18000, 14000, 20000, 22000],
                    backgroundColor: 'rgba(66, 133, 244, 0.2)',
                    borderColor: 'rgba(66, 133, 244, 1)',
                    borderWidth: 2,
                    tension: 0.1,
                    fill: true
                }]
            };

            const visitorData = {
                labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
                datasets: [{
                    label: 'Visitors',
                    data: [120, 190, 150, 170, 220, 250, 200],
                    backgroundColor: 'rgba(52, 168, 83, 0.2)',
                    borderColor: 'rgba(52, 168, 83, 1)',
                    borderWidth: 2,
                    tension: 0.1
                }]
            };

            const productData = {
                labels: ['Product A', 'Product B', 'Product C', 'Product D'],
                datasets: [{
                    label: 'Revenue',
                    data: [30000, 25000, 20000, 15000],
                    backgroundColor: [
                        'rgba(66, 133, 244, 0.7)',
                        'rgba(52, 168, 83, 0.7)',
                        'rgba(251, 188, 5, 0.7)',
                        'rgba(234, 67, 53, 0.7)'
                    ],
                    borderColor: [
                        'rgba(66, 133, 244, 1)',
                        'rgba(52, 168, 83, 1)',
                        'rgba(251, 188, 5, 1)',
                        'rgba(234, 67, 53, 1)'
                    ],
                    borderWidth: 1
                }]
            };

            // Create charts
            const salesChart = new Chart(document.getElementById('salesChart'), {
                type: 'line',
                data: salesData,
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            const visitorChart = new Chart(document.getElementById('visitorChart'), {
                type: 'bar',
                data: visitorData,
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            const productChart = new Chart(document.getElementById('productChart'), {
                type: 'doughnut',
                data: productData,
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'right',
                        }
                    }
                }
            });

            // Sample activity data
            const activityData = [
                { user: 'John Smith', action: 'Created new order', time: '2 mins ago', status: 'active' },
                { user: 'Sarah Johnson', action: 'Updated inventory', time: '15 mins ago', status: 'active' },
                { user: 'Michael Brown', action: 'Generated report', time: '1 hour ago', status: 'pending' },
                { user: 'Emily Davis', action: 'Added new customer', time: '3 hours ago', status: 'active' },
                { user: 'David Wilson', action: 'Processed payment', time: '5 hours ago', status: 'inactive' }
            ];

            // Populate activity table
            const activityTable = document.getElementById('activity-table');
            activityData.forEach(activity => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${activity.user}</td>
                    <td>${activity.action}</td>
                    <td>${activity.time}</td>
                    <td><span class="status status-${activity.status}">${activity.status}</span></td>
                `;
                activityTable.appendChild(row);
            });

            // Navigation functionality
            const navItems = document.querySelectorAll('.nav-item');
            const sections = document.querySelectorAll('.section');

            navItems.forEach(item => {
                item.addEventListener('click', function() {
                    // Update active nav item
                    navItems.forEach(nav => nav.classList.remove('active'));
                    this.classList.add('active');

                    // Show corresponding section
                    const sectionId = this.getAttribute('data-section');
                    sections.forEach(section => {
                        section.classList.remove('active');
                        if (section.id === sectionId) {
                            section.classList.add('active');
                        }
                    });
                });
            });

            // Form handling
            const dataForm = document.getElementById('data-form');
            const reportForm = document.getElementById('report-form');
            const settingsForm = document.getElementById('settings-form');

            dataForm.addEventListener('submit', function(e) {
                e.preventDefault();
                // In a real application, you would send this data to a server
                alert('Form submitted successfully!');
                this.reset();
            });

            reportForm.addEventListener('submit', function(e) {
                e.preventDefault();
                // In a real application, you would generate the report
                alert('Report generation started!');
                this.reset();
            });

            settingsForm.addEventListener('submit', function(e) {
                e.preventDefault();
                // In a real application, you would update the user settings
                alert('Settings updated successfully!');
            });

            // Simulate real-time data updates
            setInterval(() => {
                // Update sales chart with new data
                const newSalesData = Math.floor(Math.random() * 10000) + 10000;
                salesChart.data.datasets[0].data.push(newSalesData);
                salesChart.data.labels.push('Jul');
                if (salesChart.data.datasets[0].data.length > 6) {
                    salesChart.data.datasets[0].data.shift();
                    salesChart.data.labels.shift();
                }
                salesChart.update();

                // Update visitor chart with new data
                const newVisitorData = Math.floor(Math.random() * 100) + 100;
                visitorChart.data.datasets[0].data.push(newVisitorData);
                visitorChart.data.labels.push('Mon');
                if (visitorChart.data.datasets[0].data.length > 7) {
                    visitorChart.data.datasets[0].data.shift();
                    visitorChart.data.labels.shift();
                }
                visitorChart.update();
            }, 5000);
        });
    </script>
</body>
</html>
```

## Key Features of This Dashboard:

1. **Real-Time Data Visualization**:
   - Interactive charts using Chart.js (line, bar, and doughnut charts)
   - Automatic updates to charts every 5 seconds to simulate real-time data

2. **Form Handling**:
   - Multiple forms for different purposes (data entry, report generation, settings)
   - Form validation and submission handling
   - Reset functionality for forms

3. **Interactive Elements**:
   - Navigation sidebar with active state tracking
   - Section switching based on navigation
   - Responsive design that works on different screen sizes

4. **Modern UI Components**:
   - Card-based layout
   - Activity table with status indicators
   - Clean, professional styling with CSS variables

5. **Responsive Design**:
   - Adapts to different screen sizes
   - Mobile-friendly layout

To use this dashboard, simply copy the entire code into an HTML file and open it in a browser. For a production environment, you would need to:
1. Connect to a backend API for real data
2. Implement proper authentication
3. Add more robust error handling
4. Optimize performance for large datasets

