```javascript
// Dashboard Data
let dashboardData = {
    labels: ['January', 'February', 'March', 'April', 'May', 'June'],
    datasets: [{
        label: 'Dataset 1',
        data: [65, 59, 80, 81, 56, 55],
        backgroundColor: 'rgba(54, 162, 235, 0.5)',
        borderColor: 'rgba(54, 162, 235, 1)',
        borderWidth: 1
    }]
};

// Initialize Chart
const ctx = document.getElementById('main-chart').getContext('2d');
const mainChart = new Chart(ctx, {
    type: 'bar',
    data: dashboardData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        },
        animation: {
            duration: 1000
        }
    }
});

// Update date and time
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

updateDateTime();
setInterval(updateDateTime, 1000);

// Form handling
document.getElementById('data-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseInt(document.getElementById('data-value').value);
    const color = document.getElementById('data-color').value;

    // Add to chart
    mainChart.data.labels.push(label);
    mainChart.data.datasets[0].data.push(value);
    mainChart.data.datasets[0].backgroundColor.push(`${color}80`); // Add transparency
    mainChart.data.datasets[0].borderColor.push(color);
    mainChart.update();

    // Add to table
    const tableBody = document.querySelector('#data-table tbody');
    const newRow = document.createElement('tr');

    newRow.innerHTML = `
        <td>${label}</td>
        <td>${value}</td>
        <td><span class="color-box" style="background-color: ${color}"></span></td>
        <td><button class="btn-delete" data-label="${label}">Delete</button></td>
    `;

    tableBody.appendChild(newRow);

    // Update summary cards
    updateSummaryCards();

    // Reset form
    this.reset();
});

// Delete row functionality
document.querySelector('#data-table tbody').addEventListener('click', function(e) {
    if (e.target.classList.contains('btn-delete')) {
        const labelToDelete = e.target.getAttribute('data-label');
        const row = e.target.closest('tr');

        // Remove from chart
        const index = mainChart.data.labels.indexOf(labelToDelete);
        if (index !== -1) {
            mainChart.data.labels.splice(index, 1);
            mainChart.data.datasets[0].data.splice(index, 1);
            mainChart.data.datasets[0].backgroundColor.splice(index, 1);
            mainChart.data.datasets[0].borderColor.splice(index, 1);
            mainChart.update();
        }

        // Remove from table
        row.remove();

        // Update summary cards
        updateSummaryCards();
    }
});

// Update summary cards
function updateSummaryCards() {
    const dataPoints = mainChart.data.labels.length;
    const totalValue = mainChart.data.datasets[0].data.reduce((a, b) => a + b, 0);

    document.getElementById('total-users').textContent = totalValue;
    document.getElementById('active-sessions').textContent = Math.floor(totalValue / 10);
    document.getElementById('data-points').textContent = dataPoints;
}

// Simulate real-time data updates
function simulateRealTimeData() {
    setInterval(() => {
        if (mainChart.data.labels.length > 0) {
            const randomIndex = Math.floor(Math.random() * mainChart.data.labels.length);
            const newValue = Math.floor(Math.random() * 100);

            mainChart.data.datasets[0].data[randomIndex] = newValue;
            mainChart.update();

            // Update the corresponding table row
            const tableRows = document.querySelectorAll('#data-table tbody tr');
            if (tableRows.length > randomIndex) {
                const valueCell = tableRows[randomIndex].querySelector('td:nth-child(2)');
                valueCell.textContent = newValue;
            }

            updateSummaryCards();
        }
    }, 5000);
}

simulateRealTimeData();

// Initialize summary cards
updateSummaryCards();
