```javascript
// Dashboard Data
let dashboardData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [
        {
            label: 'Sales',
            data: [120, 190, 300, 500, 200, 300],
            backgroundColor: 'rgba(52, 152, 219, 0.5)',
            borderColor: 'rgba(52, 152, 219, 1)',
            borderWidth: 2,
            tension: 0.1
        },
        {
            label: 'Revenue',
            data: [150, 220, 350, 400, 250, 350],
            backgroundColor: 'rgba(46, 204, 113, 0.5)',
            borderColor: 'rgba(46, 204, 113, 1)',
            borderWidth: 2,
            tension: 0.1
        },
        {
            label: 'Expenses',
            data: [80, 150, 200, 250, 100, 180],
            backgroundColor: 'rgba(231, 76, 60, 0.5)',
            borderColor: 'rgba(231, 76, 60, 1)',
            borderWidth: 2,
            tension: 0.1
        }
    ]
};

// Initialize Chart
let mainChart;
function initChart() {
    const ctx = document.getElementById('mainChart').getContext('2d');
    mainChart = new Chart(ctx, {
        type: 'line',
        data: dashboardData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            }
        }
    });
}

// Update Date and Time
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Add Activity to Log
function addActivity(message) {
    const activityLog = document.getElementById('activityLog');
    const now = new Date();
    const timeString = now.toLocaleTimeString();

    const li = document.createElement('li');
    li.innerHTML = `
        <span>${message}</span>
        <span class="activity-time">${timeString}</span>
    `;

    activityLog.prepend(li);

    // Limit to 10 items
    if (activityLog.children.length > 10) {
        activityLog.removeChild(activityLog.lastChild);
    }
}

// Form Handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('dataLabel').value;
    const value = parseFloat(document.getElementById('dataValue').value);
    const category = document.getElementById('dataCategory').value;
    const date = document.getElementById('dataDate').value;

    // Validate form
    if (!label || isNaN(value) || !category || !date) {
        alert('Please fill in all fields correctly');
        return;
    }

    // Add data to chart
    const month = new Date(date).toLocaleString('default', { month: 'short' });

    // Check if month exists in labels
    const monthIndex = dashboardData.labels.indexOf(month);

    if (monthIndex === -1) {
        // Add new month
        dashboardData.labels.push(month);

        // Add new data point for each dataset
        dashboardData.datasets.forEach(dataset => {
            dataset.data.push(0);
        });

        // Update the new month with our data
        const newMonthIndex = dashboardData.labels.length - 1;
        const categoryIndex = dashboardData.datasets.findIndex(d => d.label.toLowerCase() === category);

        if (categoryIndex !== -1) {
            dashboardData.datasets[categoryIndex].data[newMonthIndex] = value;
        }
    } else {
        // Update existing month
        const categoryIndex = dashboardData.datasets.findIndex(d => d.label.toLowerCase() === category);

        if (categoryIndex !== -1) {
            dashboardData.datasets[categoryIndex].data[monthIndex] = value;
        }
    }

    // Update chart
    mainChart.update();

    // Add to activity log
    addActivity(`Added ${value} to ${category} for ${month}`);

    // Reset form
    this.reset();

    // Show success message
    alert('Data added successfully!');
});

// Refresh Button
document.getElementById('refreshBtn').addEventListener('click', function() {
    // Simulate fetching new data
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const randomMonth = months[Math.floor(Math.random() * months.length)];

    // Check if month exists
    const monthIndex = dashboardData.labels.indexOf(randomMonth);

    if (monthIndex === -1) {
        // Add new month
        dashboardData.labels.push(randomMonth);

        // Add new data point for each dataset
        dashboardData.datasets.forEach(dataset => {
            dataset.data.push(Math.floor(Math.random() * 500) + 50);
        });
    } else {
        // Update existing month
        dashboardData.datasets.forEach(dataset => {
            dataset.data[monthIndex] = Math.floor(Math.random() * 500) + 50;
        });
    }

    // Update chart
    mainChart.update();

    // Add to activity log
    addActivity('Refreshed data with new values');
});

// Export Button
document.getElementById('exportBtn').addEventListener('click', function() {
    // Convert data to CSV
    let csvContent = "data:text/csv;charset=utf-8,";

    // Add headers
    csvContent += "Month," + dashboardData.datasets.map(d => d.label).join(",") + "\n";

    // Add data rows
    for (let i = 0; i < dashboardData.labels.length; i++) {
        const row = [
            dashboardData.labels[i],
            ...dashboardData.datasets.map(d => d.data[i])
        ];
        csvContent += row.join(",") + "\n";
    }

    // Create download link
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "dashboard_data.csv");
    document.body.appendChild(link);

    // Trigger download
    link.click();

    // Clean up
    document.body.removeChild(link);

    // Add to activity log
    addActivity('Exported data to CSV');
});

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    initChart();
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Add initial activity
    addActivity('Dashboard initialized');
});
