## JavaScript (script.js)

```javascript
// Dashboard Data
let dashboardData = {
    sales: [],
    revenue: [],
    users: [],
    totalRevenue: 0,
    totalSales: 0,
    activeUsers: 0
};

// DOM Elements
const currentDateElement = document.getElementById('current-date');
const currentTimeElement = document.getElementById('current-time');
const dataForm = document.getElementById('data-form');
const dataTableBody = document.querySelector('#data-table tbody');
const totalRevenueElement = document.getElementById('total-revenue');
const totalSalesElement = document.getElementById('total-sales');
const activeUsersElement = document.getElementById('active-users');

// Charts
let salesChart, revenueChart;

// Initialize the dashboard
function initDashboard() {
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    initCharts();

    // Load sample data
    loadSampleData();

    // Set up form submission
    dataForm.addEventListener('submit', handleFormSubmit);
}

// Update date and time
function updateDateTime() {
    const now = new Date();
    currentDateElement.textContent = now.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
    currentTimeElement.textContent = now.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('salesChart').getContext('2d');
    const revenueCtx = document.getElementById('revenueChart').getContext('2d');

    // Sales Chart (Line Chart)
    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Sales',
                data: [],
                borderColor: '#3498db',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.4,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Revenue Chart (Pie Chart)
    revenueChart = new Chart(revenueCtx, {
        type: 'pie',
        data: {
            labels: ['Product A', 'Product B', 'Product C'],
            datasets: [{
                data: [30, 50, 20],
                backgroundColor: [
                    '#3498db',
                    '#2ecc71',
                    '#9b59b6'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    position: 'bottom'
                }
            }
        }
    });
}

// Load sample data
function loadSampleData() {
    const sampleData = [
        { label: 'Q1 2023', value: 12000, type: 'revenue' },
        { label: 'Q2 2023', value: 15000, type: 'revenue' },
        { label: 'Q3 2023', value: 18000, type: 'revenue' },
        { label: 'Jan 2023', value: 500, type: 'sales' },
        { label: 'Feb 2023', value: 650, type: 'sales' },
        { label: 'Mar 2023', value: 800, type: 'sales' },
        { label: 'Team A', value: 120, type: 'users' },
        { label: 'Team B', value: 85, type: 'users' }
    ];

    sampleData.forEach(data => {
        addDataToDashboard(data.label, data.value, data.type);
    });

    updateCharts();
    updateStats();
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const formData = new FormData(dataForm);
    const label = formData.get('label');
    const value = parseFloat(formData.get('value'));
    const type = formData.get('type');

    if (label && !isNaN(value) && type) {
        addDataToDashboard(label, value, type);
        updateCharts();
        updateStats();
        dataForm.reset();
    } else {
        alert('Please fill in all fields with valid data.');
    }
}

// Add data to dashboard
function addDataToDashboard(label, value, type) {
    const dataPoint = {
        label,
        value,
        type,
        date: new Date().toLocaleString()
    };

    // Add to appropriate array
    switch(type) {
        case 'sales':
            dashboardData.sales.push(dataPoint);
            break;
        case 'revenue':
            dashboardData.revenue.push(dataPoint);
            break;
        case 'users':
            dashboardData.users.push(dataPoint);
            break;
    }

    // Add to table
    addDataToTable(dataPoint);
}

// Add data to table
function addDataToTable(data) {
    const row = document.createElement('tr');

    row.innerHTML = `
        <td>${data.label}</td>
        <td>${data.value}</td>
        <td>${data.type}</td>
        <td>${data.date}</td>
        <td>
            <button class="btn-action btn-edit" onclick="editData(this)"><i class="fas fa-edit"></i></button>
            <button class="btn-action btn-delete" onclick="deleteData(this)"><i class="fas fa-trash"></i></button>
        </td>
    `;

    dataTableBody.prepend(row);
}

// Update charts with new data
function updateCharts() {
    // Update sales chart
    const salesLabels = dashboardData.sales.map(item => item.label);
    const salesValues = dashboardData.sales.map(item => item.value);

    salesChart.data.labels = salesLabels;
    salesChart.data.datasets[0].data = salesValues;
    salesChart.update();

    // Update revenue chart (simplified for example)
    // In a real app, you would have more sophisticated logic here
    const revenueValues = dashboardData.revenue.map(item => item.value);
    revenueChart.data.datasets[0].data = revenueValues;
    revenueChart.update();
}

// Update statistics cards
function updateStats() {
    // Calculate totals
    dashboardData.totalRevenue = dashboardData.revenue.reduce((sum, item) => sum + item.value, 0);
    dashboardData.totalSales = dashboardData.sales.reduce((sum, item) => sum + item.value, 0);
    dashboardData.activeUsers = dashboardData.users.reduce((sum, item) => sum + item.value, 0);

    // Update DOM
    totalRevenueElement.textContent = `$${dashboardData.totalRevenue.toLocaleString()}`;
    totalSalesElement.textContent = dashboardData.totalSales.toLocaleString();
    activeUsersElement.textContent = dashboardData.activeUsers.toLocaleString();
}

// Edit data (placeholder function)
function editData(button) {
    const row = button.closest('tr');
    const cells = row.querySelectorAll('td');

    // In a real app, you would populate a form with these values
    alert(`Edit functionality would go here for:\nLabel: ${cells[0].textContent}\nValue: ${cells[1].textContent}\nType: ${cells[2].textContent}`);
}

// Delete data
function deleteData(button) {
    if (confirm('Are you sure you want to delete this data point?')) {
        const row = button.closest('tr');
        const label = row.querySelector('td:first-child').textContent;
        const type = row.querySelector('td:nth-child(3)').textContent;

        // Remove from appropriate array
        switch(type) {
            case 'sales':
                dashboardData.sales = dashboardData.sales.filter(item => item.label !== label);
                break;
            case 'revenue':
                dashboardData.revenue = dashboardData.revenue.filter(item => item.label !== label);
                break;
            case 'users':
                dashboardData.users = dashboardData.users.filter(item => item.label !== label);
                break;
        }

        // Remove from table
        row.remove();

        // Update charts and stats
        updateCharts();
        updateStats();
    }
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
```

## Features Implemented

1. **Real-time Data Visualization**:
   - Line chart for sales data
   - Pie chart for revenue distribution
   - Dynamic updates when new data is added

2. **Form Handling**:
   - Form validation
   - Data submission handling
   - Clear form after submission

3. **Interactive Elements**:
   - Responsive navigation
   - Hover effects on cards and buttons
   - Edit and delete functionality for table rows

4. **Dashboard Components**:
   - Statistics cards with current values
   - Data table showing recent entries
   - Current date and time display

5. **Responsive Design**:
   - Adapts to different screen sizes
   - Mobile-friendly layout

## How to Use

1. Save the three files (index.html, styles.css, script.js) in the same directory
2. Open index.html in a web browser
3. Use the form to add new data points
4. View the data in the charts and table
5. Edit or delete existing data points

This implementation provides a solid foundation that you can extend with additional features like:
- User authentication
- Data persistence (using localStorage or a backend API)
- More sophisticated chart interactions
- Advanced filtering and sorting
- Export functionality for reports

