// Update dashboard cards
function updateDashboardCards() {
    totalSalesEl.textContent = `$${dashboardData.sales.total.toLocaleString()}`;
    salesChangeEl.textContent = `${dashboardData.sales.change > 0 ? '+' : ''}${dashboardData.sales.change}%`;
    salesChangeEl.className = dashboardData.sales.change > 0 ? 'change-positive' : 'change-negative';

    activeUsersEl.textContent = dashboardData.users.total.toLocaleString();
    usersChangeEl.textContent = `${dashboardData.users.change > 0 ? '+' : ''}${dashboardData.users.change}%`;
    usersChangeEl.className = dashboardData.users.change > 0 ? 'change-positive' : 'change-negative';

