    revenueChangeEl.textContent = `${dashboardData.revenue.change > 0 ? '+' : ''}${dashboardData.revenue.change}%`;
    revenueChangeEl.className = dashboardData.revenue.change > 0 ? 'change-positive' : 'change-negative';
