// Update charts with new data
function updateCharts() {
    salesChart.data.labels = dashboardData.sales.labels;
    salesChart.data.datasets[0].data = dashboardData.sales.data;
    salesChart.update();

    usersChart.data.labels = dashboardData.users.labels;
    usersChart.data.datasets[0].data = dashboardData.users.data;
    usersChart.update();
}

// Handle form submission
dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const type = document.getElementById('data-type').value;

    // Add new data point
    dashboardData[type].labels.push(label);
    dashboardData[type].data.push(value);

    // Update totals and changes (simplified for demo)
    dashboardData[type].total = Math.max(...dashboardData[type].data);
    dashboardData[type].change = ((dashboardData[type].data[dashboardData[type].data.length - 1] -
                                  dashboardData[type].data[dashboardData[type].data.length - 2]) /
                                  dashboardData[type].data[dashboardData[type].data.length - 2] * 100).toFixed(1);

    // Update dashboard
    updateDashboardCards();
    updateCharts();

    // Reset form
    dataForm.reset();

    // Show success message
