});

// Simulate real-time updates
function simulateRealTimeUpdates() {
    setInterval(() => {
        // Generate random data for simulation
        const randomSales = Math.floor(Math.random() * 5000) + 1000;
        const randomUsers = Math.floor(Math.random() * 100) + 10;
        const randomRevenue = Math.floor(Math.random() * 2000) + 500;

        // Update data
        dashboardData.sales.data.push(dashboardData.sales.data[dashboardData.sales.data.length - 1] + randomSales);
        dashboardData.users.data.push(dashboardData.users.data[dashboardData.users.data.length - 1] + randomUsers);
        dashboardData.revenue.data.push(dashboardData.revenue.data[dashboardData.revenue.data.length - 1] + randomRevenue);

        // Update labels
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const currentMonth = new Date().getMonth();
        dashboardData.sales.labels.push(months[currentMonth % 12]);
        dashboardData.users.labels.push(months[currentMonth % 12]);
        dashboardData.revenue.labels.push(months[currentMonth % 12]);

        // Update totals and changes
        dashboardData.sales.total = dashboardData.sales.data[dashboardData.sales.data.length - 1];
        dashboardData.users.total = dashboardData.users.data[dashboardData.users.data.length - 1];
        dashboardData.revenue.total = dashboardData.revenue.data[dashboardData.revenue.data.length - 1];

        // Calculate changes (simplified)
        dashboardData.sales.change = ((dashboardData.sales.data[dashboardData.sales.data.length - 1] -
                                      dashboardData.sales.data[dashboardData.sales.data.length - 2]) /
                                      dashboardData.sales.data[dashboardData.sales.data.length - 2] * 100).toFixed(1);

        dashboardData.users.change = ((dashboardData.users.data[dashboardData.users.data.length - 1] -
                                     dashboardData.users.data[dashboardData.users.data.length - 2]) /
                                     dashboardData.users.data[dashboardData.users.data.length - 2] * 100).toFixed(1);

        dashboardData.revenue.change = ((dashboardData.revenue.data[dashboardData.revenue.data.length - 1] -
                                       dashboardData.revenue.data[dashboardData.revenue.data.length - 2]) /
                                       dashboardData.revenue.data[dashboardData.revenue.data.length - 2] * 100).toFixed(1);

        // Update dashboard
        updateDashboardCards();
        updateCharts();
    }, 10000); // Update every 10 seconds
}

// Initialize dashboard
function initDashboard() {
    updateDateTime();
    initCharts();
    updateDashboardCards();
    simulateRealTimeUpdates();

    // Update time every second
    setInterval(updateDateTime, 1000);
}

// Start dashboard when DOM is loaded
document.addEventListener('DOMContentLoaded', initDashboard);
