## JavaScript (script.js)

```javascript
// Initialize charts
let salesChart, categoryChart;

// Sample data
let dashboardData = {
    sales: [],
    revenue: [],
    expenses: [],
    inventory: []
};

// DOM elements
const totalSalesEl = document.getElementById('total-sales');
const totalRevenueEl = document.getElementById('total-revenue');
const totalExpensesEl = document.getElementById('total-expenses');
const totalInventoryEl = document.getElementById('total-inventory');
const dataForm = document.getElementById('data-form');

// Initialize the dashboard
function initDashboard() {
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    initCharts();

    // Load sample data
    loadSampleData();

    // Set up form submission
    dataForm.addEventListener('submit', handleFormSubmit);
}

// Update date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('sales-chart').getContext('2d');
    const categoryCtx = document.getElementById('category-chart').getContext('2d');

    // Sales chart
    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Sales',
                data: [],
                borderColor: 'rgb(52, 152, 219)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Category chart
    categoryChart = new Chart(categoryCtx, {
        type: 'doughnut',
        data: {
            labels: ['Sales', 'Revenue', 'Expenses', 'Inventory'],
            datasets: [{
                data: [0, 0, 0, 0],
                backgroundColor: [
                    'rgb(52, 152, 219)',
                    'rgb(46, 204, 113)',
                    'rgb(231, 76, 60)',
                    'rgb(155, 89, 182)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    position: 'right',
                }
            }
        }
    });
}

// Load sample data
function loadSampleData() {
    // Generate some sample data
    const today = new Date();
    const sampleData = [
        { name: 'Initial Sales', value: 1000, category: 'sales', date: new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000) },
        { name: 'Initial Revenue', value: 1500, category: 'revenue', date: new Date(today.getTime() - 6 * 24 * 60 * 60 * 1000) },
        { name: 'Initial Expenses', value: 500, category: 'expenses', date: new Date(today.getTime() - 5 * 24 * 60 * 60 * 1000) },
        { name: 'Initial Inventory', value: 200, category: 'inventory', date: new Date(today.getTime() - 4 * 24 * 60 * 60 * 1000) }
    ];

    // Add sample data to dashboard
    sampleData.forEach(data => {
        addDataToDashboard(data);
    });

    // Update charts
    updateCharts();
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const formData = {
        name: document.getElementById('data-name').value,
        value: parseFloat(document.getElementById('data-value').value),
        category: document.getElementById('data-category').value,
        date: new Date(document.getElementById('data-date').value)
    };

    // Add data to dashboard
    addDataToDashboard(formData);

    // Reset form
    dataForm.reset();

    // Show success message
    alert('Data added successfully!');
}

// Add data to dashboard
function addDataToDashboard(data) {
    // Add to appropriate category
    dashboardData[data.category].push(data);

    // Update summary cards
    updateSummaryCards();

    // Update charts
    updateCharts();
}

// Update summary cards
function updateSummaryCards() {
    // Calculate totals
    const totalSales = dashboardData.sales.reduce((sum, item) => sum + item.value, 0);
    const totalRevenue = dashboardData.revenue.reduce((sum, item) => sum + item.value, 0);
    const totalExpenses = dashboardData.expenses.reduce((sum, item) => sum + item.value, 0);
    const totalInventory = dashboardData.inventory.reduce((sum, item) => sum + item.value, 0);

    // Update DOM
    totalSalesEl.textContent = `$${totalSales.toFixed(2)}`;
    totalRevenueEl.textContent = `$${totalRevenue.toFixed(2)}`;
    totalExpensesEl.textContent = `$${totalExpenses.toFixed(2)}`;
    totalInventoryEl.textContent = totalInventory;
}

// Update charts
function updateCharts() {
    // Prepare data for sales chart
    const salesData = dashboardData.sales.map(item => ({
        date: item.date.toLocaleDateString(),
        value: item.value
    }));

    // Group by date
    const groupedSales = salesData.reduce((acc, item) => {
        if (!acc[item.date]) {
            acc[item.date] = 0;
        }
        acc[item.date] += item.value;
        return acc;
    }, {});

    // Sort by date
    const sortedDates = Object.keys(groupedSales).sort((a, b) => new Date(a) - new Date(b));

    // Update sales chart
    salesChart.data.labels = sortedDates;
    salesChart.data.datasets[0].data = sortedDates.map(date => groupedSales[date]);
    salesChart.update();

    // Update category chart
    const categoryTotals = {
        sales: dashboardData.sales.reduce((sum, item) => sum + item.value, 0),
        revenue: dashboardData.revenue.reduce((sum, item) => sum + item.value, 0),
        expenses: dashboardData.expenses.reduce((sum, item) => sum + item.value, 0),
        inventory: dashboardData.inventory.reduce((sum, item) => sum + item.value, 0)
    };

    categoryChart.data.datasets[0].data = [
        categoryTotals.sales,
        categoryTotals.revenue,
        categoryTotals.expenses,
        categoryTotals.inventory
    ];
    categoryChart.update();
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
