## JavaScript (script.js)

```javascript
// Dashboard Data and Configuration
const dashboardData = {
    sales: [],
    traffic: [],
    temperature: [],
    chart: null,
    currentChartType: 'line'
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    initChart();

    // Set up form submission
    const form = document.getElementById('data-form');
    form.addEventListener('submit', handleFormSubmit);

    // Set up filter changes
    const timeRangeFilter = document.getElementById('time-range');
    const dataSourceFilter = document.getElementById('data-source');

    timeRangeFilter.addEventListener('change', updateChart);
    dataSourceFilter.addEventListener('change', updateChart);

    // Generate some initial data
    generateInitialData();
});

// Update current date and time display
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize the main chart
function initChart() {
    const ctx = document.getElementById('main-chart').getContext('2d');

    dashboardData.chart = new Chart(ctx, {
        type: dashboardData.currentChartType,
        data: {
            labels: [],
            datasets: []
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            let label = context.dataset.label || '';
                            if (label) {
                                label += ': ';
                            }
                            if (context.parsed.y !== null) {
                                label += new Intl.NumberFormat('en-US', { style: 'decimal' }).format(context.parsed.y);
                            }
                            return label;
                        }
                    }
                }
            }
        }
    });

    // Add event listener for chart type change
    document.getElementById('main-chart').addEventListener('click', function(e) {
        if (e.target.classList.contains('chart-type-btn')) {
            dashboardData.currentChartType = e.target.dataset.type;
            updateChart();
        }
    });
}

// Generate some initial random data
function generateInitialData() {
    const now = new Date();
    const dataTypes = ['sales', 'traffic', 'temperature'];
    const dataPoints = 24; // Last 24 hours

    for (let i = 0; i < dataPoints; i++) {
        const timestamp = new Date(now.getTime() - (dataPoints - i) * 3600000); // 1 hour intervals

        dataTypes.forEach(type => {
            let value;
            switch(type) {
                case 'sales':
                    value = Math.floor(Math.random() * 100) + 50;
                    break;
                case 'traffic':
                    value = Math.floor(Math.random() * 500) + 100;
                    break;
                case 'temperature':
                    value = Math.floor(Math.random() * 20) + 15;
                    break;
            }

            dashboardData[type].push({
                timestamp: timestamp,
                value: value
            });
        });
    }

    updateChart();
    updateStatistics();
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const dataType = document.getElementById('data-type').value;
    const dataValue = parseFloat(document.getElementById('data-value').value);
    const dataTimestamp = new Date(document.getElementById('data-timestamp').value);

    if (!dataType || isNaN(dataValue) || isNaN(dataTimestamp.getTime())) {
        alert('Please fill in all fields correctly');
        return;
    }

    // Add new data point
    dashboardData[dataType].push({
        timestamp: dataTimestamp,
        value: dataValue
    });

    // Sort data by timestamp
    dashboardData[dataType].sort((a, b) => a.timestamp - b.timestamp);

    // Update chart and statistics
    updateChart();
    updateStatistics();

    // Reset form
    e.target.reset();
}

// Update the chart based on current filters
function updateChart() {
    const timeRange = document.getElementById('time-range').value;
    const dataSource = document.getElementById('data-source').value;

    // Calculate time range cutoff
    const now = new Date();
    let cutoffTime;

    switch(timeRange) {
        case '1h':
            cutoffTime = new Date(now.getTime() - 3600000);
            break;
        case '6h':
            cutoffTime = new Date(now.getTime() - 21600000);
            break;
        case '12h':
            cutoffTime = new Date(now.getTime() - 43200000);
            break;
        case '24h':
            cutoffTime = new Date(now.getTime() - 86400000);
            break;
        case '7d':
            cutoffTime = new Date(now.getTime() - 604800000);
            break;
        case '30d':
            cutoffTime = new Date(now.getTime() - 2592000000);
            break;
        default:
            cutoffTime = new Date(0); // All time
    }

    // Prepare data for chart
    const chartData = {
        labels: [],
        datasets: []
    };

    // Determine which data sources to include
    const dataTypesToShow = dataSource === 'all' ? ['sales', 'traffic', 'temperature'] : [dataSource];

    // Colors for different data types
    const colors = {
        sales: 'rgba(52, 152, 219, 0.7)',
        traffic: 'rgba(46, 204, 113, 0.7)',
        temperature: 'rgba(231, 76, 60, 0.7)'
    };

    // Prepare datasets
    dataTypesToShow.forEach(type => {
        const filteredData = dashboardData[type].filter(item => item.timestamp >= cutoffTime);

        if (filteredData.length > 0) {
            const dataset = {
                label: type.charAt(0).toUpperCase() + type.slice(1),
                data: filteredData.map(item => item.value),
                backgroundColor: colors[type],
                borderColor: colors[type].replace('0.7', '1'),
                borderWidth: 2,
                fill: false,
                tension: 0.1
            };

            chartData.datasets.push(dataset);

            // Update labels if this is the first dataset
            if (chartData.labels.length === 0) {
                chartData.labels = filteredData.map(item =>
                    item.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                );
            }
        }
    });

    // Update chart
    dashboardData.chart.data = chartData;
    dashboardData.chart.config.type = dashboardData.currentChartType;
    dashboardData.chart.update();
}

// Update statistics display
function updateStatistics() {
    const allData = [...dashboardData.sales, ...dashboardData.traffic, ...dashboardData.temperature];

    if (allData.length === 0) {
        document.getElementById('total-points').textContent = '0';
        document.getElementById('avg-value').textContent = '0.00';
        document.getElementById('max-value').textContent = '0.00';
        document.getElementById('min-value').textContent = '0.00';
        return;
    }

    const values = allData.map(item => item.value);
    const total = values.reduce((sum, value) => sum + value, 0);
    const avg = total / values.length;
    const max = Math.max(...values);
    const min = Math.min(...values);

    document.getElementById('total-points').textContent = allData.length;
    document.getElementById('avg-value').textContent = avg.toFixed(2);
    document.getElementById('max-value').textContent = max.toFixed(2);
    document.getElementById('min-value').textContent = min.toFixed(2);
}
```

## Features of this Dashboard

1. **Real-Time Data Visualization**:
   - Interactive line chart using Chart.js
   - Multiple data types (sales, traffic, temperature)
   - Dynamic filtering by time range and data source

2. **Form Handling**:
   - Form for adding new data points
   - Validation for required fields
   - Automatic sorting of new data

3. **Interactive Elements**:
   - Real-time clock display
   - Filter controls for data visualization
   - Responsive design that works on different screen sizes

4. **Statistics Display**:
   - Key metrics (total points, average, max, min)
   - Automatically updated when data changes

5. **User Experience**:
   - Clean, modern UI with card-based layout
   - Visual feedback for interactions
   - Mobile-responsive design

To use this dashboard, simply save these three files (index.html, styles.css, and script.js) in the same directory and open index.html in a web browser. The dashboard will generate some initial random data and allow you to add more through the form.

