## JavaScript (script.js)

```javascript
// DOM Elements
const tabLinks = document.querySelectorAll('.nav-link');
const tabContents = document.querySelectorAll('.tab-content');
const dataForm = document.getElementById('dataForm');
const submittedData = document.getElementById('submittedData');
const activityTable = document.getElementById('activityTable');
const settingsForm = document.getElementById('settingsForm');
const generateReportBtn = document.getElementById('generateReport');
const reportOutput = document.getElementById('reportOutput');

// Chart instances
let liveChart, statsChart;

// Sample data
let liveData = [];
let statsData = {
    labels: ['Sales', 'Inventory', 'Customers', 'Other'],
    values: [0, 0, 0, 0]
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set up tab switching
    tabLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const tabId = this.getAttribute('data-tab');

            // Update active tab
            tabLinks.forEach(l => l.classList.remove('active'));
            this.classList.add('active');

            // Show corresponding content
            tabContents.forEach(content => {
                content.classList.remove('active');
                if (content.id === tabId) {
                    content.classList.add('active');
                }
            });

            // Initialize charts when overview tab is selected
            if (tabId === 'overview') {
                initCharts();
            }
        });
    });

    // Initialize charts on page load if overview is active
    if (document.querySelector('.nav-link.active').getAttribute('data-tab') === 'overview') {
        initCharts();
    }

    // Set up data form submission
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();
        handleDataSubmission();
    });

    // Set up settings form submission
    settingsForm.addEventListener('submit', function(e) {
        e.preventDefault();
        handleSettingsSubmission();
    });

    // Set up report generation
    generateReportBtn.addEventListener('click', generateReport);

    // Start data simulation
    simulateLiveData();
});

// Initialize charts
function initCharts() {
    const liveChartCtx = document.getElementById('liveChart').getContext('2d');
    const statsChartCtx = document.getElementById('statsChart').getContext('2d');

    // Live data chart
    liveChart = new Chart(liveChartCtx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Live Data',
                data: [],
                borderColor: 'rgb(52, 152, 219)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Stats chart
    statsChart = new Chart(statsChartCtx, {
        type: 'bar',
        data: {
            labels: statsData.labels,
            datasets: [{
                label: 'Statistics',
                data: statsData.values,
                backgroundColor: [
                    'rgba(52, 152, 219, 0.7)',
                    'rgba(46, 204, 113, 0.7)',
                    'rgba(241, 196, 15, 0.7)',
                    'rgba(155, 89, 182, 0.7)'
                ],
                borderColor: [
                    'rgba(52, 152, 219, 1)',
                    'rgba(46, 204, 113, 1)',
                    'rgba(241, 196, 15, 1)',
                    'rgba(155, 89, 182, 1)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Simulate live data updates
function simulateLiveData() {
    setInterval(() => {
        const now = new Date();
        const value = Math.floor(Math.random() * 100) + 1;

        // Update live data array (keep last 20 points)
        liveData.push({ time: now, value: value });
        if (liveData.length > 20) {
            liveData.shift();
        }

        // Update charts if they exist
        if (liveChart) {
            updateLiveChart();
        }

        // Update activity table
        updateActivityTable();

        // Update stats data
        updateStatsData(value);
    }, 5000); // Update every 5 seconds
}

// Update live chart with new data
function updateLiveChart() {
    const times = liveData.map(item => item.time.toLocaleTimeString());
    const values = liveData.map(item => item.value);

    liveChart.data.labels = times;
    liveChart.data.datasets[0].data = values;
    liveChart.update();
}

// Update activity table with recent data
function updateActivityTable() {
    if (liveData.length === 0) return;

    const lastItem = liveData[liveData.length - 1];
    const row = document.createElement('tr');

    const status = lastItem.value > 70 ? 'High' :
                  lastItem.value > 30 ? 'Medium' : 'Low';

    row.innerHTML = `
        <td>${lastItem.time.toLocaleString()}</td>
        <td>${lastItem.value}</td>
        <td><span class="badge bg-${getStatusColor(status)}">${status}</span></td>
    `;

    // Add new row at the top
    activityTable.insertBefore(row, activityTable.firstChild);

    // Limit to 10 rows
    if (activityTable.rows.length > 10) {
        activityTable.deleteRow(-1);
    }
}

// Update stats data
function updateStatsData(value) {
    // Randomly assign to one of the categories
    const categoryIndex = Math.floor(Math.random() * statsData.labels.length);
    statsData.values[categoryIndex] += value;

    // Update stats chart
    if (statsChart) {
        statsChart.data.datasets[0].data = statsData.values;
        statsChart.update();
    }
}

// Handle data form submission
function handleDataSubmission() {
    const formData = {
        name: document.getElementById('dataName').value,
        value: parseFloat(document.getElementById('dataValue').value),
        category: document.getElementById('dataCategory').value,
        notes: document.getElementById('dataNotes').value,
        timestamp: new Date().toLocaleString()
    };

    // Display submitted data
    submittedData.innerHTML = `
        <div class="card-body">
            <h5>${formData.name}</h5>
            <p><strong>Value:</strong> ${formData.value}</p>
            <p><strong>Category:</strong> ${formData.category}</p>
            <p><strong>Notes:</strong> ${formData.notes || 'None'}</p>
            <p><strong>Submitted:</strong> ${formData.timestamp}</p>
        </div>
    `;

    // Add to live data
    liveData.push({ time: new Date(), value: formData.value });

    // Update charts
    if (liveChart) {
        updateLiveChart();
    }

    // Update stats data
    const categoryIndex = statsData.labels.indexOf(
        formData.category.charAt(0).toUpperCase() + formData.category.slice(1)
    );
    if (categoryIndex !== -1) {
        statsData.values[categoryIndex] += formData.value;
        if (statsChart) {
            statsChart.data.datasets[0].data = statsData.values;
            statsChart.update();
        }
    }

    // Reset form
    dataForm.reset();
}

// Handle settings form submission
function handleSettingsSubmission() {
    const refreshRate = parseInt(document.getElementById('refreshRate').value);
    const theme = document.getElementById('theme').value;
    const notifications = document.getElementById('notifications').checked;

    // Apply theme
    if (theme === 'dark') {
        document.body.classList.add('dark-theme');
    } else {
        document.body.classList.remove('dark-theme');
    }

    // Show notification
    if (notifications) {
        alert('Settings saved successfully!');
    }

    // In a real app, you would save these settings to localStorage or a backend
    console.log('Settings saved:', { refreshRate, theme, notifications });
}

// Generate report
function generateReport() {
    const reportType = document.getElementById('reportType').value;
    const reportDate = document.getElementById('reportDate').value;

    // In a real app, you would fetch data based on these parameters
    const reportData = {
        type: reportType,
        date: reportDate || 'current',
        summary: generateRandomReportData(),
        generatedAt: new Date().toLocaleString()
    };

    // Display report
    reportOutput.innerHTML = `
        <div class="card">
            <div class="card-header">
                <h5>${reportType.charAt(0).toUpperCase() + reportType.slice(1)} Report</h5>
            </div>
            <div class="card-body">
                <p><strong>Date:</strong> ${reportDate || 'Current'}</p>
                <p><strong>Generated:</strong> ${reportData.generatedAt}</p>

                <h6>Summary:</h6>
                <ul>
                    <li>Total Items: ${reportData.summary.totalItems}</li>
                    <li>Average Value: ${reportData.summary.averageValue.toFixed(2)}</li>
                    <li>Highest Value: ${reportData.summary.highestValue}</li>
                    <li>Lowest Value: ${reportData.summary.lowestValue}</li>
                </ul>

                <div class="mt-3">
                    <button class="btn btn-success" onclick="exportReport()">Export as PDF</button>
                </div>
            </div>
        </div>
    `;
}

// Generate random report data for demonstration
function generateRandomReportData() {
    const totalItems = Math.floor(Math.random() * 100) + 10;
    const values = Array.from({length: totalItems}, () => Math.floor(Math.random() * 1000) + 1);

    return {
        totalItems: totalItems,
        averageValue: values.reduce((a, b) => a + b, 0) / totalItems,
        highestValue: Math.max(...values),
        lowestValue: Math.min(...values)
    };
}

// Helper function to get status color
function getStatusColor(status) {
    switch(status) {
        case 'High': return 'danger';
        case 'Medium': return 'warning';
        case 'Low': return 'success';
        default: return 'secondary';
    }
}

// Export report function (placeholder)
function exportReport() {
    alert('Report export functionality would be implemented here.');
}
