            const active = Math.floor(Math.random() * 500) + 300;
            const inactive = Math.floor(Math.random() * 200) + 100;
            const newUsers = Math.floor(Math.random() * 100) + 50;

            userActivityChart.data.datasets[0].data = [active, inactive, newUsers];
            userActivityChart.update();
        }

        function updateChartTimeframe(chart, timeframe) {
            // Generate random data based on timeframe
            let labels = [];
            let data = [];

            if (timeframe === 'daily') {
                for (let i = 0; i < 7; i++) {
                    labels.push(`Day ${i+1}`);
                    data.push(Math.floor(Math.random() * 1000) + 500);
                }
            } else if (timeframe === 'weekly') {
                for (let i = 0; i < 4; i++) {
                    labels.push(`Week ${i+1}`);
                    data.push(Math.floor(Math.random() * 3000) + 2000);
                }
            } else if (timeframe === 'monthly') {
                for (let i = 0; i < 6; i++) {
                    labels.push(`Month ${i+1}`);
                    data.push(Math.floor(Math.random() * 6000) + 4000);
                }
            }

            chart.data.labels = labels;
            chart.data.datasets[0].data = data;
            chart.update();
        }

        function setActiveButton(activeButton) {
            const buttons = document.querySelectorAll('.btn-group .btn');
            buttons.forEach(btn => {
                btn.classList.remove('active');
            });
            activeButton.classList.add('active');
        }

        function handleFormSubmit(salesChart, userActivityChart) {
            const form = document.getElementById('data-form');
            const type = document.getElementById('data-type').value;
            const value = document.getElementById('data-value').value;
            const date = document.getElementById('data-date').value;
            const description = document.getElementById('data-description').value;

            // Add to activity table
            const newActivity = {
                type: type.charAt(0).toUpperCase() + type.slice(1),
                value: type === 'sales' ? '$' + value : value,
                date: date,
                description: description || 'No description'
            };

            // Update the appropriate chart
            if (type === 'sales') {
                // Add to sales chart
                const lastLabel = salesChart.data.labels[salesChart.data.labels.length - 1] || 'Day 1';
                const newLabel = 'Day ' + (parseInt(lastLabel.split(' ')[1]) + 1 || 1);

                salesChart.data.labels.push(newLabel);
                salesChart.data.datasets[0].data.push(parseInt(value));
                salesChart.update();

                // Update total sales
                const currentSales = parseInt(document.getElementById('total-sales').textContent.replace(/[^0-9]/g, ''));
                document.getElementById('total-sales').textContent = '$' + (currentSales + parseInt(value)).toLocaleString();
            } else if (type === 'users') {
                // Update user activity chart
                const currentActive = userActivityChart.data.datasets[0].data[0];
                userActivityChart.data.datasets[0].data[0] = currentActive + parseInt(value);
                userActivityChart.update();

                // Update active users
                const currentUsers = parseInt(document.getElementById('active-users').textContent.replace(/[^0-9]/g, ''));
                document.getElementById('active-users').textContent = (currentUsers + parseInt(value)).toLocaleString();
            }

            // Add to activity table
            const activityTable = document.getElementById('activity-table');
            const newRow = document.createElement('tr');

            newRow.innerHTML = `
                <td>${newActivity.type}</td>
                <td>${newActivity.value}</td>
                <td>${newActivity.date}</td>
                <td>${newActivity.description}</td>
            `;

            activityTable.prepend(newRow);

            // Reset form
            form.reset();

            // Show success message
            showAlert('Data added successfully!', 'success');
        }

        function updateActivityTable(data) {
            const activityTable = document.getElementById('activity-table');
            activityTable.innerHTML = '';

            data.forEach(item => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${item.type}</td>
                    <td>${item.value}</td>
                    <td>${item.date}</td>
                    <td>${item.description}</td>
                `;
                activityTable.appendChild(row);
            });
        }

        function updateRealTimeData(salesChart, userActivityChart) {
            // Simulate real-time updates
            if (Math.random() > 0.7) { // 30% chance of update
                // Update sales chart
                const lastValue = salesChart.data.datasets[0].data[salesChart.data.datasets[0].data.length - 1] || 0;
                const newValue = lastValue + Math.floor(Math.random() * 200) - 100;

                if (newValue >= 0) {
                    salesChart.data.datasets[0].data[salesChart.data.datasets[0].data.length - 1] = newValue;
                    salesChart.update();

                    // Update total sales
                    const currentSales = parseInt(document.getElementById('total-sales').textContent.replace(/[^0-9]/g, ''));
                    document.getElementById('total-sales').textContent = '$' + (currentSales + (newValue - lastValue)).toLocaleString();
                }

                // Update user activity chart
                const activeUsers = userActivityChart.data.datasets[0].data[0];
                const change = Math.floor(Math.random() * 20) - 10;
                userActivityChart.data.datasets[0].data[0] = Math.max(0, activeUsers + change);
                userActivityChart.update();

                // Update active users display
                const currentUsers = parseInt(document.getElementById('active-users').textContent.replace(/[^0-9]/g, ''));
                document.getElementById('active-users').textContent = (currentUsers + change).toLocaleString();
            }
        }

        function showAlert(message, type) {
            const alertContainer = document.createElement('div');
            alertContainer.className = `alert alert-${type} alert-dismissible fade show`;
            alertContainer.role = 'alert';
            alertContainer.innerHTML = `
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
            `;

            // Add alert to the dashboard
            const dashboard = document.querySelector('.dashboard-container');
            dashboard.insertBefore(alertContainer, dashboard.firstChild);

            // Auto-dismiss after 3 seconds
            setTimeout(() => {
                alertContainer.remove();
            }, 3000);
        }
    </script>
</body>
</html>
```

