## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const salesChart = initChart('salesChart', 'line', 'Sales Overview', ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'], [1200, 1900, 3000, 5000, 2400, 3200]);
    const userGrowthChart = initChart('userGrowthChart', 'bar', 'User Growth', ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'], [500, 700, 1200, 1800, 2500, 3000]);

    // Initialize data table
    const dataTable = document.querySelector('#data-table tbody');

    // Form submission handler
    const dataForm = document.getElementById('data-form');
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const label = document.getElementById('data-label').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const type = document.getElementById('data-type').value;

        // Add data to table
        addDataToTable(label, value, type);

        // Update charts based on type
        updateChartBasedOnType(salesChart, userGrowthChart, label, value, type);

        // Update stats cards
        updateStatsCards(value, type);

        // Reset form
        dataForm.reset();
    });

    // Function to update date and time
    function updateDateTime() {
        const now = new Date();
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
        document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
    }

    // Function to initialize a chart
    function initChart(canvasId, type, title, labels, data) {
        const ctx = document.getElementById(canvasId).getContext('2d');
        return new Chart(ctx, {
            type: type,
            data: {
                labels: labels,
                datasets: [{
                    label: title,
                    data: data,
                    backgroundColor: getRandomColor(),
                    borderColor: getRandomColor(),
                    borderWidth: 1,
                    tension: 0.1,
                    fill: type === 'line' ? true : false
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }

    // Function to get random color
    function getRandomColor() {
        const letters = '0123456789ABCDEF';
        let color = '#';
        for (let i = 0; i < 6; i++) {
            color += letters[Math.floor(Math.random() * 16)];
        }
        return color;
    }

    // Function to add data to table
    function addDataToTable(label, value, type) {
        const row = document.createElement('tr');
        const now = new Date();

        row.innerHTML = `
            <td>${label}</td>
            <td>${value}</td>
            <td>${type.charAt(0).toUpperCase() + type.slice(1)}</td>
            <td>${now.toLocaleString()}</td>
            <td><button class="btn-delete" onclick="deleteRow(this)">Delete</button></td>
        `;

        dataTable.appendChild(row);
    }

    // Function to update charts based on data type
    function updateChartBasedOnType(salesChart, userGrowthChart, label, value, type) {
        // For simplicity, we'll just add the new data to both charts
        // In a real application, you might want to handle this more intelligently

        // Add to sales chart
        salesChart.data.labels.push(label);
        salesChart.data.datasets[0].data.push(value);
        salesChart.update();

        // Add to user growth chart
        userGrowthChart.data.labels.push(label);
        userGrowthChart.data.datasets[0].data.push(value);
        userGrowthChart.update();
    }

    // Function to update stats cards
    function updateStatsCards(value, type) {
        // In a real application, you would have more sophisticated logic here
        // For this example, we'll just update some of the cards

        // Update total users if type is bar
        if (type === 'bar') {
            const usersElement = document.getElementById('total-users');
            const currentUsers = parseInt(usersElement.textContent) || 0;
            usersElement.textContent = currentUsers + value;
        }

        // Update total sales if type is line
        if (type === 'line') {
            const salesElement = document.getElementById('total-sales');
            const currentSales = parseInt(salesElement.textContent) || 0;
            salesElement.textContent = currentSales + value;
        }

        // Update revenue (random calculation for demo)
        const revenueElement = document.getElementById('total-revenue');
        const currentRevenue = parseInt(revenueElement.textContent.replace('$', '')) || 0;
        revenueElement.textContent = `$${currentRevenue + Math.floor(value * 0.7)}`;

        // Update growth rate (random calculation for demo)
        const growthElement = document.getElementById('growth-rate');
        const currentGrowth = parseFloat(growthElement.textContent.replace('%', '')) || 0;
        growthElement.textContent = `${(currentGrowth + (value * 0.01)).toFixed(1)}%`;
    }

    // Function to delete a row from the table
    window.deleteRow = function(button) {
        const row = button.closest('tr');
        row.remove();
    };
});
