// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize charts
    const mainChartCtx = document.getElementById('main-chart').getContext('2d');
    const pieChartCtx = document.getElementById('pie-chart').getContext('2d');
    const barChartCtx = document.getElementById('bar-chart').getContext('2d');

    // Create charts
    const mainChart = new Chart(mainChartCtx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Data Points',
                data: [],
                borderColor: 'rgb(52, 152, 219)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    const pieChart = new Chart(pieChartCtx, {
        type: 'pie',
        data: {
            labels: ['Direct', 'Social', 'Referral', 'Email'],
            datasets: [{
                data: [30, 20, 25, 25],
                backgroundColor: [
                    'rgb(52, 152, 219)',
                    'rgb(46, 204, 113)',
                    'rgb(230, 126, 34)',
                    'rgb(155, 89, 182)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false
        }
    });

    const barChart = new Chart(barChartCtx, {
        type: 'bar',
        data: {
            labels: ['Q1', 'Q2', 'Q3', 'Q4'],
            datasets: [{
                label: 'Performance',
                data: [85, 72, 90, 88],
                backgroundColor: 'rgba(52, 152, 219, 0.7)',
                borderColor: 'rgb(52, 152, 219)',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Update time display
    function updateTime() {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        const dateString = now.toLocaleDateString();
        document.getElementById('current-time').textContent = `${dateString} ${timeString}`;
    }

    // Initial time update
    updateTime();
    setInterval(updateTime, 1000);

    // Form submission handler
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();
        fetchAndUpdateData();
    });

    // Auto-refresh toggle
    document.getElementById('auto-refresh').addEventListener('change', function() {
        if (this.checked) {
            // Start auto-refresh
            refreshInterval = setInterval(fetchAndUpdateData, 10000);
        } else {
            // Stop auto-refresh
            clearInterval(refreshInterval);
        }
    });

    // Initial data fetch
    let refreshInterval;
    fetchAndUpdateData();

    // If auto-refresh is enabled, start interval
    if (document.getElementById('auto-refresh').checked) {
        refreshInterval = setInterval(fetchAndUpdateData, 10000);
    }

    // Function to fetch data and update charts
    function fetchAndUpdateData() {
        const dataType = document.getElementById('data-type').value;
        const timeRange = document.getElementById('time-range').value;

        // Simulate API call with mock data
        setTimeout(() => {
            const mockData = generateMockData(dataType, timeRange);

            // Update main chart
            mainChart.data.labels = mockData.labels;
            mainChart.data.datasets[0].data = mockData.values;
            mainChart.data.datasets[0].label = dataType.charAt(0).toUpperCase() + dataType.slice(1);
            mainChart.update();

            // Update quick stats
            document.getElementById('total-sales').textContent = `$${mockData.totalSales.toFixed(2)}`;
            document.getElementById('active-users').textContent = mockData.activeUsers;
            document.getElementById('conversion-rate').textContent = `${mockData.conversionRate}%`;

            // Update last updated time
            const now = new Date();
            document.getElementById('last-updated').textContent = `Last updated: ${now.toLocaleTimeString()}`;
        }, 500); // Simulate network delay
    }

    // Function to generate mock data based on parameters
    function generateMockData(dataType, timeRange) {
        let labels = [];
        let values = [];
        let totalSales = 0;
        let activeUsers = 0;
        let conversionRate = 0;

        const ranges = {
            day: 24,
            week: 7,
            month: 30
        };

        const points = ranges[timeRange];

        for (let i = 0; i < points; i++) {
            // Generate labels based on time range
            if (timeRange === 'day') {
                labels.push(`${i}:00`);
            } else {
                labels.push(`Day ${i + 1}`);
            }

            // Generate random values based on data type
            let value;
            switch(dataType) {
                case 'sales':
                    value = Math.floor(Math.random() * 1000) + 100;
                    break;
                case 'traffic':
                    value = Math.floor(Math.random() * 500) + 50;
                    break;
                case 'inventory':
                    value = Math.floor(Math.random() * 200) + 10;
                    break;
                default:
                    value = Math.floor(Math.random() * 100) + 10;
            }

            values.push(value);
            totalSales += value;
        }

        // Calculate derived metrics
        activeUsers = Math.floor(totalSales / (Math.random() * 5 + 1));
        conversionRate = Math.floor((Math.random() * 10) + 5);

        return {
            labels,
            values,
            totalSales,
            activeUsers,
            conversionRate
        };
    }
});
```

## Features Implemented

1. **Responsive Dashboard Layout**:
   - Clean, modern UI with responsive design
   - Grid layout that adapts to different screen sizes

2. **Real-Time Data Visualization**:
   - Main line chart for primary data visualization
   - Pie chart for traffic sources
   - Bar chart for performance metrics
   - All charts update dynamically based on form inputs

3. **Form Handling**:
   - Data type selection (sales, traffic, inventory)
   - Time range selection (day, week, month)
   - Form submission triggers data refresh

4. **Quick Stats Display**:
   - Key metrics displayed in card format
   - Automatically updated when data changes

