            document.getElementById('support-tickets').textContent = Math.floor(Math.random() * 50) + 10;

            // Initialize charts
            initCharts();

            // Populate projects table
            populateProjectsTable();

            // Set up form submission
            setupForm();
        }

        // Initialize charts
        function initCharts() {
            // User Growth Chart
            const userGrowthCtx = document.getElementById('userGrowthChart').getContext('2d');
            const userGrowthChart = new Chart(userGrowthCtx, {
                type: 'line',
                data: {
                    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
                    datasets: [{
                        label: 'New Users',
                        data: [120, 190, 300, 500, 700, 900],
                        backgroundColor: 'rgba(52, 152, 219, 0.2)',
                        borderColor: 'rgba(52, 152, 219, 1)',
                        borderWidth: 2,
                        tension: 0.4,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            // Revenue Chart
            const revenueCtx = document.getElementById('revenueChart').getContext('2d');
            const revenueChart = new Chart(revenueCtx, {
                type: 'doughnut',
                data: {
                    labels: ['Product Sales', 'Services', 'Subscriptions', 'Other'],
                    datasets: [{
                        data: [30000, 20000, 15000, 5000],
                        backgroundColor: [
                            'rgba(52, 152, 219, 0.8)',
                            'rgba(46, 204, 113, 0.8)',
                            'rgba(241, 196, 15, 0.8)',
                            'rgba(155, 89, 182, 0.8)'
                        ],
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    plugins: {
                        legend: {
                            position: 'right',
                        }
                    }
                }
            });
        }

        // Populate projects table
        function populateProjectsTable() {
            const tableBody = document.querySelector('#projectsTable tbody');
            tableBody.innerHTML = '';

            projects.forEach(project => {
                const row = document.createElement('tr');

                row.innerHTML = `
                    <td>${project.name}</td>
                    <td>${project.description}</td>
                    <td><span class="status status-${project.status}">${project.status}</span></td>
                    <td>$${project.budget.toLocaleString()}</td>
                    <td>
                        <button class="btn btn-primary btn-sm" onclick="editProject(${project.id})">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="btn btn-secondary btn-sm" onclick="deleteProject(${project.id})">
                            <i class="fas fa-trash"></i>
                        </button>
                    </td>
                `;

                tableBody.appendChild(row);
            });
        }

        // Set up form submission
        function setupForm() {
            const form = document.getElementById('projectForm');

            form.addEventListener('submit', function(e) {
                e.preventDefault();

                const formData = new FormData(form);
                const newProject = {
                    id: projects.length > 0 ? Math.max(...projects.map(p => p.id)) + 1 : 1,
                    name: formData.get('projectName'),
                    description: formData.get('projectDescription'),
                    status: formData.get('projectStatus'),
                    budget: parseFloat(formData.get('projectBudget'))
                };

                projects.push(newProject);
                populateProjectsTable();
                updateDashboardStats();
                form.reset();

                // Show success message
                alert('Project added successfully!');
            });
        }

        // Update dashboard statistics
        function updateDashboardStats() {
            document.getElementById('active-projects').textContent = projects.filter(p => p.status === 'active').length;
        }

        // Edit project
        function editProject(id) {
            const project = projects.find(p => p.id === id);
            if (project) {
                document.getElementById('projectName').value = project.name;
                document.getElementById('projectDescription').value = project.description;
                document.getElementById('projectStatus').value = project.status;
                document.getElementById('projectBudget').value = project.budget;

                // Scroll to form
                document.querySelector('.form-container').scrollIntoView({ behavior: 'smooth' });
            }
        }

        // Delete project
        function deleteProject(id) {
            if (confirm('Are you sure you want to delete this project?')) {
                projects = projects.filter(p => p.id !== id);
                populateProjectsTable();
                updateDashboardStats();
            }
        }

        // Initialize dashboard when page loads
        document.addEventListener('DOMContentLoaded', initDashboard);

        // Simulate real-time updates
        setInterval(() => {
            // Update some card values randomly
            document.getElementById('total-users').textContent = Math.floor(Math.random() * 1000) + 500;
            document.getElementById('revenue').textContent = `$${(Math.random() * 100000 + 50000).toFixed(2)}`;
            document.getElementById('support-tickets').textContent = Math.floor(Math.random() * 50) + 10;

            // Update charts with new data
            updateCharts();
        }, 10000);

        // Update charts with new data
        function updateCharts() {
            // Get chart instances
            const userGrowthChart = Chart.getChart('userGrowthChart');
            const revenueChart = Chart.getChart('revenueChart');

            if (userGrowthChart) {
                // Update user growth chart with new random data
                const newData = Array(6).fill(0).map(() => Math.floor(Math.random() * 1000) + 100);
                userGrowthChart.data.datasets[0].data = newData;
                userGrowthChart.update();
            }

            if (revenueChart) {
                // Update revenue chart with new random data
                const newData = [
                    Math.floor(Math.random() * 40000) + 10000,
                    Math.floor(Math.random() * 30000) + 10000,
                    Math.floor(Math.random() * 20000) + 10000,
                    Math.floor(Math.random() * 10000) + 5000
                ];
                revenueChart.data.datasets[0].data = newData;
                revenueChart.update();
            }
        }
    </script>
</body>
</html>
