    setInterval(() => {
        const now = new Date();
        const timeString = now.toLocaleTimeString('en-US', {hour: '2-digit', minute: '2-digit', second: '2-digit'});

        // Add new data point
        const newValue = Math.random() * 10 + 20; // Random temperature between 20-30°C

        realTimeData.labels.push(timeString);
        realTimeData.datasets[0].data.push(newValue);

        // Keep only the last 20 data points
        if (realTimeData.labels.length > 20) {
