});

// Add submission to recent list
function addToRecentSubmissions(data) {
    const submissionsList = document.getElementById('submissionsList');
    const listItem = document.createElement('li');

    listItem.innerHTML = `
        <span>${data.type} (${data.value})</span>
        <span>${data.location}</span>
        <span>${data.timestamp}</span>
    `;

    submissionsList.prepend(listItem);

    // Limit to 5 recent submissions
    if (submissionsList.children.length > 5) {
        submissionsList.removeChild(submissionsList.lastChild);
    }
}

// Initialize everything when the page loads
document.addEventListener('DOMContentLoaded', function() {
    initRealTimeChart();
    initSummaryChart();
    simulateRealTimeData();
});
