        if (newChartType !== currentChartType) {
            currentChartType = newChartType;
            mainChart.destroy();
            mainChart = createChart(ctx, currentChartType);

            // Get current data from chart and update
            const currentData = getChartData(mainChart);
            updateChart(mainChart, currentData);
        }
    });

    // Chart type select change
    document.getElementById('chartType').addEventListener('change', function() {
        const newChartType = this.value;

        if (newChartType !== currentChartType) {
            currentChartType = newChartType;
            mainChart.destroy();
            mainChart = createChart(ctx, currentChartType);

            // Get current data from chart and update
            const currentData = getChartData(mainChart);
            updateChart(mainChart, currentData);
        }
    });
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Create chart based on type
function createChart(ctx, type) {
    const config = {
        type: type,
        data: {
            labels: [],
            datasets: []
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    };

    return new Chart(ctx, config);
}

// Update chart with new data
function updateChart(chart, data) {
    chart.data.labels = data.labels;
    chart.data.datasets = data.datasets;
    chart.update();
}

// Generate sample data
function generateSampleData() {
    const now = new Date();
    const labels = [];
    const salesData = [];
    const trafficData = [];
    const tempData = [];

    for (let i = 0; i < 10; i++) {
        const date = new Date(now);
        date.setDate(now.getDate() - (10 - i));
        labels.push(date.toLocaleDateString());

        salesData.push(Math.floor(Math.random() * 1000) + 100);
        trafficData.push(Math.floor(Math.random() * 5000) + 1000);
        tempData.push(Math.floor(Math.random() * 20) + 10);
    }

    return {
        labels: labels,
        datasets: [
            {
                label: 'Sales',
                data: salesData,
                backgroundColor: 'rgba(52, 152, 219, 0.5)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            },
            {
                label: 'Website Traffic',
                data: trafficData,
                backgroundColor: 'rgba(46, 204, 113, 0.5)',
                borderColor: 'rgba(46, 204, 113, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            },
            {
                label: 'Temperature (°C)',
                data: tempData,
                backgroundColor: 'rgba(243, 156, 18, 0.5)',
                borderColor: 'rgba(243, 156, 18, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }
        ]
    };
}

// Add to activity log
function addToActivityLog(data) {
    const activityLog = document.getElementById('activityLog');
    const li = document.createElement('li');

    const typeMap = {
        'sales': 'Sales',
        'traffic': 'Traffic',
        'temperature': 'Temperature'
    };

    li.innerHTML = `
        <span>${typeMap[data.type] || data.type}</span>
        <span>${data.value} at ${data.timestamp.toLocaleString()}</span>
    `;

    activityLog.prepend(li);

    // Limit to 10 items
    if (activityLog.children.length > 10) {
        activityLog.removeChild(activityLog.lastChild);
    }
}

// Update chart with new data point
function updateChartWithNewData(chart, newData) {
    // Add new label
    const newLabel = newData.timestamp.toLocaleDateString();
    chart.data.labels.push(newLabel);

    // Update or add dataset
    const datasetIndex = chart.data.datasets.findIndex(ds => ds.label.toLowerCase().includes(newData.type));
    const typeMap = {
        'sales': 'Sales',
        'traffic': 'Website Traffic',
        'temperature': 'Temperature (°C)'
    };

    if (datasetIndex >= 0) {
        // Update existing dataset
        chart.data.datasets[datasetIndex].data.push(newData.value);
    } else {
        // Create new dataset
        const color = getColorForType(newData.type);
        chart.data.datasets.push({
            label: typeMap[newData.type] || newData.type,
            data: Array(chart.data.labels.length - 1).fill(null).concat([newData.value]),
            backgroundColor: color.bg,
            borderColor: color.border,
            borderWidth: 2,
            tension: 0.1,
            fill: true
        });
    }

    // Remove oldest data point if we have more than 10
    if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        chart.data.datasets.forEach(ds => {
            ds.data.shift();
        });
    }

    chart.update();
}

// Get color for data type
function getColorForType(type) {
    const colors = {
        'sales': {
            bg: 'rgba(52, 152, 219, 0.5)',
            border: 'rgba(52, 152, 219, 1)'
        },
        'traffic': {
            bg: 'rgba(46, 204, 113, 0.5)',
            border: 'rgba(46, 204, 113, 1)'
        },
        'temperature': {
            bg: 'rgba(243, 156, 18, 0.5)',
            border: 'rgba(243, 156, 18, 1)'
        }
    };

    return colors[type] || {
        bg: 'rgba(155, 89, 182, 0.5)',
        border: 'rgba(155, 89, 182, 1)'
    };
}

// Get current data from chart
function getChartData(chart) {
    return {
        labels: [...chart.data.labels],
        datasets: chart.data.datasets.map(ds => ({
            ...ds,
            data: [...ds.data]
        }))
    };
}
