}

// Simulate real-time data updates
function startDataSimulation() {
    // Update charts periodically
    setInterval(() => {
        updateChartsWithRealTimeData();
        updateKeyMetrics();
        updateDataTable();
    }, 5000); // Update every 5 seconds
}

// Update charts with new data (simulated)
function updateChartsWithNewData(dataSource, timeRange, filter) {
    // In a real application, you would fetch data from an API
    console.log('Updating charts with new data:', { dataSource, timeRange, filter });

    // Update main chart
    const timePoints = timeRange === '24h' ? 24 : timeRange === '7d' ? 7 : 30;
    mainChart.data.labels = generateTimeLabels(timePoints);
    mainChart.data.datasets[0].data = generateRandomData(timePoints, 100, 1000);
    mainChart.data.datasets[0].label = `${dataSource} Data`;
    mainChart.update();

    // Update secondary chart
    secondaryChart.data.datasets[0].data = generateRandomData(12, 1000, 5000);
    secondaryChart.update();
}

// Update charts with real-time data (simulated)
function updateChartsWithRealTimeData() {
    // Add new data point to main chart
    const newDataPoint = Math.floor(Math.random() * 1000) + 100;
    mainChart.data.labels.push(new Date().toLocaleTimeString());
    mainChart.data.datasets[0].data.push(newDataPoint);

    // Remove oldest data point if we have more than 24 points
    if (mainChart.data.labels.length > 24) {
        mainChart.data.labels.shift();
        mainChart.data.datasets[0].data.shift();
    }

    mainChart.update();

    // Update secondary chart with new data
    const monthIndex = new Date().getMonth();
    secondaryChart.data.datasets[0].data[monthIndex] += Math.floor(Math.random() * 100) + 10;
    secondaryChart.update();
}

// Update key metrics (simulated)
function updateKeyMetrics(dataSource = 'sales') {
    // Simulate fetching new metrics
    const totalSales = (Math.random() * 100000).toFixed(2);
    const activeUsers = Math.floor(Math.random() * 1000) + 500;
    const conversionRate = (Math.random() * 10).toFixed(1);

    document.getElementById('total-sales').textContent = `$${totalSales}`;
    document.getElementById('active-users').textContent = activeUsers;
    document.getElementById('conversion-rate').textContent = `${conversionRate}%`;
}

// Update data table with new entries (simulated)
function updateDataTable() {
    const tableBody = document.getElementById('table-body');
    const newRow = document.createElement('tr');

    const timestamp = new Date().toLocaleString();
    const value = (Math.random() * 1000).toFixed(2);
    const source = ['Sales', 'Traffic', 'Inventory'][Math.floor(Math.random() * 3)];
    const status = ['Active', 'Pending', 'Completed'][Math.floor(Math.random() * 3)];

    newRow.innerHTML = `
        <td>${timestamp}</td>
        <td>${value}</td>
        <td>${source}</td>
        <td><span class="status-badge ${status.toLowerCase()}">${status}</span></td>
    `;

    // Add new row to the top
    tableBody.insertBefore(newRow, tableBody.firstChild);

    // Limit to 10 rows
    if (tableBody.children.length > 10) {
        tableBody.removeChild(tableBody.lastChild);
    }
}

// Helper function to generate time labels
function generateTimeLabels(count) {
    const labels = [];
    const now = new Date();

    for (let i = count - 1; i >= 0; i--) {
        const date = new Date(now);
        date.setHours(now.getHours() - i);
        labels.push(date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }

    return labels;
}

// Helper function to generate random data
function generateRandomData(count, min, max) {
    const data = [];
    for (let i = 0; i < count; i++) {
        data.push(Math.floor(Math.random() * (max - min + 1)) + min);
    }
    return data;
}
