## JavaScript Functionality (`script.js`)

```javascript
// Update date and time
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

// Initialize charts
let realtimeChart, barChart;
let realtimeData = [];
let barChartData = {
    labels: ['Temperature', 'Humidity', 'Pressure'],
    datasets: [{
        label: 'Average Values',
        data: [0, 0, 0],
        backgroundColor: [
            'rgba(255, 99, 132, 0.7)',
            'rgba(54, 162, 235, 0.7)',
            'rgba(255, 206, 86, 0.7)'
        ],
        borderColor: [
            'rgba(255, 99, 132, 1)',
            'rgba(54, 162, 235, 1)',
            'rgba(255, 206, 86, 1)'
        ],
        borderWidth: 1
    }]
};

function initCharts() {
    const ctx1 = document.getElementById('realtimeChart').getContext('2d');
    realtimeChart = new Chart(ctx1, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Real-Time Data',
                data: [],
                borderColor: 'rgb(75, 192, 192)',
                tension: 0.1,
                fill: false
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: false
                }
            }
        }
    });

    const ctx2 = document.getElementById('barChart').getContext('2d');
    barChart = new Chart(ctx2, {
        type: 'bar',
        data: barChartData,
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Update real-time chart with new data
function updateRealtimeChart(newValue) {
    const now = new Date();
    const timeString = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit' });

    realtimeData.push({ time: timeString, value: newValue });

    // Keep only the last 20 data points
    if (realtimeData.length > 20) {
        realtimeData.shift();
    }

    realtimeChart.data.labels = realtimeData.map(item => item.time);
    realtimeChart.data.datasets[0].data = realtimeData.map(item => item.value);
    realtimeChart.update();
}

// Update bar chart with new data
function updateBarChart(type, value) {
    let index;
    switch(type) {
        case 'temperature':
            index = 0;
            break;
        case 'humidity':
            index = 1;
            break;
        case 'pressure':
            index = 2;
            break;
        default:
            return;
    }

    // Simple moving average calculation
    const currentValue = barChartData.datasets[0].data[index];
    const newValue = (currentValue + value) / 2;

    barChartData.datasets[0].data[index] = newValue;
    barChart.update();
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const data = {
        type: formData.get('dataType'),
        value: parseFloat(formData.get('dataValue')),
        location: formData.get('dataLocation'),
        timestamp: new Date().toISOString()
    };

    // Update charts
    updateRealtimeChart(data.value);
    updateBarChart(data.type, data.value);

    // Add to recent submissions
    addToSubmissionList(data);

    // Reset form
    form.reset();
}

// Add submission to the list
function addToSubmissionList(data) {
    const list = document.getElementById('submissionList');
    const listItem = document.createElement('li');

    const timeString = new Date(data.timestamp).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });

    listItem.innerHTML = `
        <span>${data.type.charAt(0).toUpperCase() + data.type.slice(1)}: ${data.value}</span>
        <span>${timeString}</span>
    `;

    list.prepend(listItem);

    // Limit to 5 items
    if (list.children.length > 5) {
        list.removeChild(list.lastChild);
    }
}

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time immediately and every second
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    initCharts();

    // Set up form submission handler
    document.getElementById('dataForm').addEventListener('submit', handleFormSubmit);

    // Simulate some initial data
    setTimeout(() => {
        updateRealtimeChart(25.5);
        updateBarChart('temperature', 25.5);
    }, 1000);

    setTimeout(() => {
        updateRealtimeChart(30.2);
        updateBarChart('humidity', 30.2);
    }, 2000);

    setTimeout(() => {
        updateRealtimeChart(1015);
        updateBarChart('pressure', 1015);
    }, 3000);
});
