```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date/time display
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const mainChartCtx = document.getElementById('mainChart').getContext('2d');
    const secondaryChartCtx = document.getElementById('secondaryChart').getContext('2d');

    // Sample data
    let chartData = generateSampleData('sales', '24h');
    let updateInterval = 5000; // Default 5 seconds

    // Main chart configuration
    const mainChart = new Chart(mainChartCtx, {
        type: 'line',
        data: {
            labels: chartData.labels,
            datasets: [{
                label: 'Data Points',
                data: chartData.values,
                borderColor: 'rgba(52, 152, 219, 1)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                borderWidth: 2,
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Main Data Visualization',
                    font: {
                        size: 16
                    }
                }
            }
        }
    });

    // Secondary chart configuration
    const secondaryChart = new Chart(secondaryChartCtx, {
        type: 'bar',
        data: {
            labels: chartData.labels,
            datasets: [{
                label: 'Secondary Data',
                data: chartData.secondaryValues,
                backgroundColor: 'rgba(46, 204, 113, 0.7)',
                borderColor: 'rgba(46, 204, 113, 1)',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Secondary Data Visualization',
                    font: {
                        size: 16
                    }
                }
            }
        }
    });

    // Update statistics display
    function updateStatistics(data) {
        const currentValue = data.values[data.values.length - 1];
        const average = data.values.reduce((a, b) => a + b, 0) / data.values.length;
        const maxValue = Math.max(...data.values);

        document.getElementById('currentValue').textContent = currentValue.toFixed(2);
        document.getElementById('averageValue').textContent = average.toFixed(2);
        document.getElementById('maxValue').textContent = maxValue.toFixed(2);
    }

    // Form submission handler
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const dataType = document.getElementById('dataType').value;
        const timeRange = document.getElementById('timeRange').value;
        const newUpdateInterval = parseInt(document.getElementById('updateInterval').value);

        // Update chart data
        chartData = generateSampleData(dataType, timeRange);

        // Update charts
        mainChart.data.labels = chartData.labels;
        mainChart.data.datasets[0].data = chartData.values;
        mainChart.data.datasets[0].label = `${dataType} Data`;
        mainChart.update();

        secondaryChart.data.labels = chartData.labels;
        secondaryChart.data.datasets[0].data = chartData.secondaryValues;
        secondaryChart.data.datasets[0].label = `Secondary ${dataType} Data`;
        secondaryChart.update();

        // Update statistics
        updateStatistics(chartData);

        // Update interval if changed
        if (newUpdateInterval !== updateInterval) {
            updateInterval = newUpdateInterval;
            clearInterval(dataUpdateInterval);
            dataUpdateInterval = setInterval(updateData, updateInterval);
        }
    });

    // Function to update data in real-time
    function updateData() {
        const dataType = document.getElementById('dataType').value;
        const timeRange = document.getElementById('timeRange').value;

        // Generate new data point
        const newData = generateNewDataPoint(dataType);

        // Update chart data
        chartData.labels.shift();
        chartData.labels.push(newData.label);

        chartData.values.shift();
        chartData.values.push(newData.value);

        chartData.secondaryValues.shift();
        chartData.secondaryValues.push(newData.secondaryValue);

        // Update charts
        mainChart.update();
        secondaryChart.update();

        // Update statistics
        updateStatistics(chartData);
    }

    // Set initial interval for data updates
    let dataUpdateInterval = setInterval(updateData, updateInterval);

    // Clean up intervals when page is unloaded
    window.addEventListener('beforeunload', function() {
        clearInterval(dataUpdateInterval);
    });
});

// Helper function to update date/time display
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Helper function to generate sample data
function generateSampleData(dataType, timeRange) {
    let labels = [];
    let values = [];
    let secondaryValues = [];
    let count;

    // Determine number of data points based on time range
    switch(timeRange) {
        case '24h':
            count = 24;
            break;
        case '7d':
            count = 7;
            break;
        case '30d':
            count = 30;
            break;
        default:
            count = 24;
    }

    // Generate labels and values based on data type
    for (let i = 0; i < count; i++) {
        let label;
        let value;
        let secondaryValue;

        switch(timeRange) {
            case '24h':
                label = `${i}:00`;
                break;
            case '7d':
                label = `Day ${i + 1}`;
                break;
            case '30d':
                label = `Day ${i + 1}`;
                break;
            default:
                label = `Point ${i + 1}`;
        }

        switch(dataType) {
            case 'sales':
                value = Math.floor(Math.random() * 1000) + 100;
                secondaryValue = Math.floor(Math.random() * 500) + 50;
                break;
            case 'traffic':
                value = Math.floor(Math.random() * 10000) + 1000;
                secondaryValue = Math.floor(Math.random() * 5000) + 500;
                break;
            case 'temperature':
                value = (Math.random() * 20) + 10; // 10-30°C
                secondaryValue = (Math.random() * 15) + 5; // 5-20°C
                break;
            default:
                value = Math.random() * 100;
                secondaryValue = Math.random() * 50;
        }

        labels.push(label);
        values.push(value);
        secondaryValues.push(secondaryValue);
    }

    return {
        labels: labels,
        values: values,
        secondaryValues: secondaryValues
    };
}

// Helper function to generate a new data point
function generateNewDataPoint(dataType) {
    let label;
    let value;
    let secondaryValue;

    // Generate appropriate label based on current time
    const now = new Date();
    label = now.toLocaleTimeString('en-US', {hour: '2-digit', minute:'2-digit'});

    // Generate values based on data type
    switch(dataType) {
        case 'sales':
            value = Math.floor(Math.random() * 1000) + 100;
            secondaryValue = Math.floor(Math.random() * 500) + 50;
            break;
        case 'traffic':
            value = Math.floor(Math.random() * 10000) + 1000;
            secondaryValue = Math.floor(Math.random() * 5000) + 500;
            break;
        case 'temperature':
            value = (Math.random() * 20) + 10; // 10-30°C
            secondaryValue = (Math.random() * 15) + 5; // 5-20°C
            break;
        default:
            value = Math.random() * 100;
            secondaryValue = Math.random() * 50;
    }

    return {
        label: label,
        value: value,
        secondaryValue: secondaryValue
    };
}
