```javascript
// Dashboard Data Management
class DashboardData {
    constructor() {
        this.data = {
            sales: [],
            traffic: [],
            inventory: []
        };
        this.chart = null;
        this.initializeDateTime();
        this.initializeChart();
        this.setupForm();
        this.loadSampleData();
    }

    // Initialize current date and time display
    initializeDateTime() {
        const updateDateTime = () => {
            const now = new Date();
            document.getElementById('current-date').textContent = now.toLocaleDateString();
            document.getElementById('current-time').textContent = now.toLocaleTimeString();
        };

        updateDateTime();
        setInterval(updateDateTime, 1000);
    }

    // Initialize the chart
    initializeChart() {
        const ctx = document.getElementById('main-chart').getContext('2d');
        this.chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [
                    {
                        label: 'Sales',
                        data: [],
                        borderColor: 'rgba(52, 152, 219, 1)',
                        backgroundColor: 'rgba(52, 152, 219, 0.2)',
                        tension: 0.3,
                        fill: true
                    },
                    {
                        label: 'Traffic',
                        data: [],
                        borderColor: 'rgba(46, 204, 113, 1)',
                        backgroundColor: 'rgba(46, 204, 113, 0.2)',
                        tension: 0.3,
                        fill: true
                    },
                    {
                        label: 'Inventory',
                        data: [],
                        borderColor: 'rgba(231, 76, 60, 1)',
                        backgroundColor: 'rgba(231, 76, 60, 0.2)',
                        tension: 0.3,
                        fill: true
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }

    // Setup form submission handler
    setupForm() {
        const form = document.getElementById('data-form');
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            const type = document.getElementById('data-type').value;
            const value = parseFloat(document.getElementById('data-value').value);
            const date = document.getElementById('data-date').value;

            if (type && value && date) {
                this.addData(type, value, date);
                form.reset();
            }
        });
    }

    // Add new data point
    addData(type, value, date) {
        const newEntry = { type, value, date };

        // Add to data store
        this.data[type].push(newEntry);

        // Update UI
        this.updateDataTable();
        this.updateChart();
        this.updateSummaryStats();

        // Save to localStorage
        this.saveData();
    }

    // Update the data table display
    updateDataTable() {
        const tableBody = document.getElementById('data-table-body');
        tableBody.innerHTML = '';

        // Combine all data and sort by date
        const allData = [
            ...this.data.sales.map(item => ({...item, type: 'Sales'})),
            ...this.data.traffic.map(item => ({...item, type: 'Traffic'})),
            ...this.data.inventory.map(item => ({...item, type: 'Inventory'}))
        ].sort((a, b) => new Date(a.date) - new Date(b.date));

        // Display last 10 entries
        const recentData = allData.slice(-10).reverse();

        recentData.forEach(entry => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${entry.type}</td>
                <td>${entry.value}</td>
                <td>${new Date(entry.date).toLocaleDateString()}</td>
            `;
            tableBody.appendChild(row);
        });
    }

    // Update the chart with new data
    updateChart() {
        // Prepare data for chart
        const dates = [...new Set([
            ...this.data.sales.map(item => item.date),
            ...this.data.traffic.map(item => item.date),
            ...this.data.inventory.map(item => item.date)
        ])].sort();

        const salesData = dates.map(date => {
            const entry = this.data.sales.find(item => item.date === date);
            return entry ? entry.value : 0;
        });

        const trafficData = dates.map(date => {
            const entry = this.data.traffic.find(item => item.date === date);
            return entry ? entry.value : 0;
        });

        const inventoryData = dates.map(date => {
            const entry = this.data.inventory.find(item => item.date === date);
            return entry ? entry.value : 0;
        });

        // Update chart data
        this.chart.data.labels = dates.map(date => new Date(date).toLocaleDateString());
        this.chart.data.datasets[0].data = salesData;
        this.chart.data.datasets[1].data = trafficData;
        this.chart.data.datasets[2].data = inventoryData;

        this.chart.update();
    }

    // Update summary statistics
    updateSummaryStats() {
        const totalSales = this.data.sales.reduce((sum, item) => sum + item.value, 0);
        const totalTraffic = this.data.traffic.reduce((sum, item) => sum + item.value, 0);
        const inventoryLevel = this.data.inventory.reduce((sum, item) => sum + item.value, 0);

        document.getElementById('total-sales').textContent = `$${totalSales.toFixed(2)}`;
        document.getElementById('total-traffic').textContent = totalTraffic;
        document.getElementById('inventory-level').textContent = inventoryLevel;
    }

    // Load sample data
    loadSampleData() {
        // Check for saved data first
        if (this.loadSavedData()) {
            return;
        }

        // Sample data if no saved data exists
        const today = new Date();
        const sampleData = [
            { type: 'sales', value: 1200.50, date: new Date(today.setDate(today.getDate() - 6)).toISOString().split('T')[0] },
            { type: 'traffic', value: 450, date: new Date(today.setDate(today.getDate() - 6)).toISOString().split('T')[0] },
            { type: 'inventory', value: 300, date: new Date(today.setDate(today.getDate() - 6)).toISOString().split('T')[0] },

            { type: 'sales', value: 1500.75, date: new Date(today.setDate(today.getDate() - 5)).toISOString().split('T')[0] },
            { type: 'traffic', value: 520, date: new Date(today.setDate(today.getDate() - 5)).toISOString().split('T')[0] },
            { type: 'inventory', value: 280, date: new Date(today.setDate(today.getDate() - 5)).toISOString().split('T')[0] },

            { type: 'sales', value: 980.20, date: new Date(today.setDate(today.getDate() - 4)).toISOString().split('T')[0] },
            { type: 'traffic', value: 380, date: new Date(today.setDate(today.getDate() - 4)).toISOString().split('T')[0] },
            { type: 'inventory', value: 320, date: new Date(today.setDate(today.getDate() - 4)).toISOString().split('T')[0] },

            { type: 'sales', value: 1350.00, date: new Date(today.setDate(today.getDate() - 3)).toISOString().split('T')[0] },
            { type: 'traffic', value: 470, date: new Date(today.setDate(today.getDate() - 3)).toISOString().split('T')[0] },
            { type: 'inventory', value: 310, date: new Date(today.setDate(today.getDate() - 3)).toISOString().split('T')[0] },

            { type: 'sales', value: 1100.30, date: new Date(today.setDate(today.getDate() - 2)).toISOString().split('T')[0] },
            { type: 'traffic', value: 420, date: new Date(today.setDate(today.getDate() - 2)).toISOString().split('T')[0] },
            { type: 'inventory', value: 290, date: new Date(today.setDate(today.getDate() - 2)).toISOString().split('T')[0] },

            { type: 'sales', value: 1600.80, date: new Date(today.setDate(today.getDate() - 1)).toISOString().split('T')[0] },
            { type: 'traffic', value: 550, date: new Date(today.setDate(today.getDate() - 1)).toISOString().split('T')[0] },
            { type: 'inventory', value: 330, date: new Date(today.setDate(today.getDate() - 1)).toISOString().split('T')[0] }
        ];

        sampleData.forEach(item => {
            this.addData(item.type, item.value, item.date);
        });
    }

    // Save data to localStorage
    saveData() {
        localStorage.setItem('dashboardData', JSON.stringify(this.data));
    }

    // Load data from localStorage
    loadSavedData() {
        const savedData = localStorage.getItem('dashboardData');
        if (savedData) {
            this.data = JSON.parse(savedData);
            this.updateDataTable();
            this.updateChart();
            this.updateSummaryStats();
            return true;
        }
        return false;
    }
}

