// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize charts
    const cpuChart = initChart('cpu-chart', 'CPU Usage (%)', 'rgba(255, 99, 132, 0.2)', 'rgba(255, 99, 132, 1)');
    const memoryChart = initChart('memory-chart', 'Memory Usage (%)', 'rgba(54, 162, 235, 0.2)', 'rgba(54, 162, 235, 1)');
    const networkChart = initChart('network-chart', 'Network Traffic (MB/s)', 'rgba(75, 192, 192, 0.2)', 'rgba(75, 192, 192, 1)');
    const usersChart = initChart('users-chart', 'Active Users', 'rgba(153, 102, 255, 0.2)', 'rgba(153, 102, 255, 1)');

    // Store charts in an object for easy access
    const charts = {
        cpu: cpuChart,
        memory: memoryChart,
        network: networkChart,
        users: usersChart
    };

    // Initial data load
    fetchDataAndUpdateCharts(charts);

    // Set up time range buttons
    document.querySelectorAll('.time-btn').forEach(button => {
        button.addEventListener('click', function() {
            document.querySelectorAll('.time-btn').forEach(btn => btn.classList.remove('active'));
            this.classList.add('active');
            fetchDataAndUpdateCharts(charts);
        });
    });

    // Set up refresh button
    document.getElementById('refresh-btn').addEventListener('click', function() {
        fetchDataAndUpdateCharts(charts);
    });

    // Set up form submission
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();
        submitFormData(charts);
    });

    // Simulate real-time updates
    setInterval(() => {
        fetchDataAndUpdateCharts(charts, true);
    }, 10000); // Update every 10 seconds
});

// Initialize a chart
function initChart(canvasId, label, backgroundColor, borderColor) {
    const ctx = document.getElementById(canvasId).getContext('2d');
    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: label,
                data: [],
                backgroundColor: backgroundColor,
                borderColor: borderColor,
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                }
            }
        }
    });
}

// Fetch data and update charts
function fetchDataAndUpdateCharts(charts, isUpdate = false) {
    // In a real application, this would be an API call
    // For demo purposes, we'll generate random data

    const timeRange = document.querySelector('.time-btn.active').dataset.range;
    const dataSource = document.getElementById('data-source').value;

    // Generate mock data based on time range
    const dataPoints = getDataPointsForRange(timeRange);

    // Update all charts
    Object.keys(charts).forEach(metric => {
        const chart = charts[metric];

        if (isUpdate) {
            // For updates, just add new data point
            const newLabel = new Date().toLocaleTimeString();
            const newValue = generateRandomValue(metric);

            chart.data.labels.push(newLabel);
            chart.data.datasets[0].data.push(newValue);

            // Keep only the last 20 data points
            if (chart.data.labels.length > 20) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }
        } else {
            // For full refresh, generate all data points
            const labels = [];
            const values = [];

            for (let i = 0; i < dataPoints; i++) {
                const time = new Date(Date.now() - (dataPoints - i) * 1000 * 60 * 5);
                labels.push(time.toLocaleTimeString());
                values.push(generateRandomValue(metric));
            }

            chart.data.labels = labels;
            chart.data.datasets[0].data = values;
        }

        chart.update();
    });
}

// Generate random value based on metric type
function generateRandomValue(metric) {
    switch(metric) {
        case 'cpu':
            return Math.floor(Math.random() * 100);
        case 'memory':
            return Math.floor(Math.random() * 100);
        case 'network':
            return Math.random() * 10;
        case 'users':
            return Math.floor(Math.random() * 1000);
        default:
            return Math.random() * 100;
    }
}

// Get number of data points based on time range
function getDataPointsForRange(range) {
    switch(range) {
        case '1h': return 12;
        case '6h': return 36;
        case '12h': return 72;
        case '24h': return 144;
        case '7d': return 168;
        default: return 24;
    }
}

// Handle form submission
function submitFormData(charts) {
    const formStatus = document.getElementById('form-status');
    const metricName = document.getElementById('metric-name').value;
    const metricValue = parseFloat(document.getElementById('metric-value').value);
    const metricType = document.getElementById('metric-type').value;

    // In a real application, this would be an API call
    // For demo purposes, we'll simulate the submission
    formStatus.style.display = 'block';
    formStatus.className = 'status';
    formStatus.textContent = 'Submitting data...';

    // Simulate API call
    setTimeout(() => {
        // In a real app, you would check the response status
        const success = Math.random() > 0.2; // 80% success rate for demo

        if (success) {
            formStatus.className = 'status success';
            formStatus.textContent = 'Data submitted successfully!';

            // Update the corresponding chart with the new data
            if (charts[metricType]) {
                const chart = charts[metricType];
                const newLabel = new Date().toLocaleTimeString();

                chart.data.labels.push(newLabel);
                chart.data.datasets[0].data.push(metricValue);

                // Keep only the last 20 data points
                if (chart.data.labels.length > 20) {
                    chart.data.labels.shift();
                    chart.data.datasets[0].data.shift();
                }

                chart.update();
            }

            // Reset form
            document.getElementById('data-form').reset();
        } else {
            formStatus.className = 'status error';
            formStatus.textContent = 'Error submitting data. Please try again.';
        }

        // Hide status after 3 seconds
        setTimeout(() => {
            formStatus.style.display = 'none';
        }, 3000);
    }, 1000);
}
