});

// Update charts with new data
function updateCharts(name, value, category) {
    // Update real-time chart
    realtimeData.labels.push(name);
    realtimeData.datasets[0].data.push(value);

    // Keep only the last 7 data points
    if (realtimeData.labels.length > 7) {
        realtimeData.labels.shift();
        realtimeData.datasets[0].data.shift();
    }

    realtimeChart.update();

    // Update pie chart
    const categoryIndex = pieData.labels.indexOf(category);
    if (categoryIndex !== -1) {
        pieData.datasets[0].data[categoryIndex] += value;
    } else {
        pieData.labels.push(category);
        pieData.datasets[0].data.push(value);
        // Add new color for the new category
        const newColor = `rgba(${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, 0.7)`;
        pieData.datasets[0].backgroundColor.push(newColor);
    }

    pieChart.update();
}

