            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Form submission handler
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();
        updateDashboard();
    });

    // Initial data load
    updateDashboard();

    // Simulate real-time updates every 5 seconds
    setInterval(updateDashboard, 5000);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Update dashboard with new data
function updateDashboard() {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;
    const threshold = parseInt(document.getElementById('threshold').value);

    // Simulate API call to get data
    fetchData(dataSource, timeRange)
        .then(data => {
            updateChart(data.chartData);
            updateStats(data.stats);
            updateActivityTable(data.activity);
            checkThresholds(data.stats, threshold);
        })
        .catch(error => {
            console.error('Error fetching data:', error);
            addAlert('Error loading data. Please try again.');
        });
}

// Simulate API call with random data
function fetchData(dataSource, timeRange) {
    return new Promise((resolve) => {
        // Simulate network delay
        setTimeout(() => {
            // Generate mock data based on parameters
            const now = new Date();
            const labels = [];
            const values = [];
            const activity = [];

            // Determine number of data points based on time range
            let points = 24;
            if (timeRange === 'week') points = 7;
            if (timeRange === 'month') points = 30;

            // Generate labels and values
            for (let i = points - 1; i >= 0; i--) {
                const date = new Date(now);
                date.setHours(now.getHours() - i);

                if (timeRange === 'week') {
                    date.setDate(now.getDate() - i);
                } else if (timeRange === 'month') {
                    date.setDate(now.getDate() - i);
                }

                labels.push(date.toLocaleString('default', { month: 'short', day: 'numeric' }));

                // Generate different data based on source
                let value;
                if (dataSource === 'sales') {
                    value = Math.floor(Math.random() * 1000) + 500;
                } else if (dataSource === 'traffic') {
                    value = Math.floor(Math.random() * 5000) + 1000;
                } else { // inventory
                    value = Math.floor(Math.random() * 200) + 50;
                }

                values.push(value);

                // Add to activity log
                activity.push({
                    time: date.toLocaleTimeString(),
                    event: getRandomEvent(dataSource),
                    value: value
                });
            }

            // Calculate stats
            const total = values.reduce((a, b) => a + b, 0);
            const avg = total / values.length;
            const max = Math.max(...values);

            resolve({
                chartData: {
                    labels: labels,
                    values: values
                },
                stats: {
                    total: total,
                    average: avg.toFixed(2),
                    max: max,
                    min: Math.min(...values)
                },
                activity: activity
            });
        }, 500);
    });
}

// Get random event based on data source
function getRandomEvent(dataSource) {
    const salesEvents = ['Product Purchase', 'Refund Processed', 'Subscription Renewed', 'New Customer'];
    const trafficEvents = ['Page View', 'User Login', 'Search Query', 'Checkout Started'];
    const inventoryEvents = ['Stock Added', 'Item Shipped', 'Stock Alert', 'Restock Needed'];

    let events;
    if (dataSource === 'sales') {
        events = salesEvents;
    } else if (dataSource === 'traffic') {
        events = trafficEvents;
    } else {
        events = inventoryEvents;
    }

    return events[Math.floor(Math.random() * events.length)];
}

// Update the main chart
function updateChart(data) {
    const chart = Chart.getChart('main-chart');
    if (chart) {
        chart.data.labels = data.labels;
        chart.data.datasets[0].data = data.values;
        chart.update();
    }
}

// Update statistics cards
function updateStats(stats) {
    document.getElementById('total-sales').textContent = `$${stats.total.toLocaleString()}`;
    document.getElementById('active-users').textContent = stats.average;
    document.getElementById('conversion-rate').textContent = `${stats.max}%`;
}

// Update activity table
function updateActivityTable(activity) {
    const tableBody = document.getElementById('activity-table-body');
    tableBody.innerHTML = '';

    // Show only the most recent 10 activities
    const recentActivity = activity.slice(-10).reverse();

    recentActivity.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.time}</td>
            <td>${item.event}</td>
            <td>${item.value}</td>
        `;
        tableBody.appendChild(row);
    });
}

// Check for threshold breaches
function checkThresholds(stats, threshold) {
    const alertsContainer = document.getElementById('alerts-container');
    alertsContainer.innerHTML = '';

    if (stats.max > threshold) {
        const alertDiv = document.createElement('div');
        alertDiv.className = 'alert-item';
        alertDiv.textContent = `Alert: Maximum value (${stats.max}) exceeded threshold (${threshold})`;
        alertsContainer.appendChild(alertDiv);
    }

    if (stats.average > threshold * 0.9) {
        const alertDiv = document.createElement('div');
        alertDiv.className = 'alert-item';
        alertDiv.textContent = `Warning: Average value (${stats.average.toFixed(2)}) approaching threshold (${threshold})`;
        alertsContainer.appendChild(alertDiv);
    }
}

// Add alert message
function addAlert(message) {
    const alertsContainer = document.getElementById('alerts-container');
    const alertDiv = document.createElement('div');
    alertDiv.className = 'alert-item';
    alertDiv.textContent = message;
    alertsContainer.appendChild(alertDiv);
}
