## JavaScript Functionality (script.js)

```javascript
// Dashboard Data and State
let dashboardData = {
    sales: [],
    traffic: [],
    inventory: [],
    stats: {
        totalSales: 0,
        activeUsers: 0,
        inventoryLevel: 0
    }
};

// Chart instance
let mainChart;

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set up date and time display
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    initChart();

    // Set up form submission
    const form = document.getElementById('data-form');
    form.addEventListener('submit', handleFormSubmit);

    // Generate some initial data
    generateInitialData();

    // Update the dashboard every 5 seconds
    setInterval(updateDashboard, 5000);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize the main chart
function initChart() {
    const ctx = document.getElementById('main-chart').getContext('2d');

    mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales Data',
                    data: [],
                    borderColor: 'rgb(52, 152, 219)',
                    backgroundColor: 'rgba(52, 152, 219, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Website Traffic',
                    data: [],
                    borderColor: 'rgb(46, 204, 113)',
                    backgroundColor: 'rgba(46, 204, 113, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Inventory Levels',
                    data: [],
                    borderColor: 'rgb(231, 76, 60)',
                    backgroundColor: 'rgba(231, 76, 60, 0.1)',
                    tension: 0.3,
                    fill: true
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            }
        }
    });
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const dataType = formData.get('data-type');
    const value = parseFloat(formData.get('data-value'));
    const timestamp = new Date(formData.get('data-timestamp'));
    const category = formData.get('data-category') || 'General';

    // Add data to the appropriate array
    const dataPoint = {
        value: value,
        timestamp: timestamp,
        category: category
    };

    dashboardData[dataType].push(dataPoint);

    // Update statistics
    updateStatistics(dataType, value);

    // Add to activity log
    addToActivityLog(dataType, value, timestamp);

    // Update the chart
    updateChart();

    // Reset form
    form.reset();

    // Show success message (in a real app, you might use a proper notification system)
    alert('Data submitted successfully!');
}

// Update statistics based on new data
function updateStatistics(dataType, value) {
    switch(dataType) {
        case 'sales':
            dashboardData.stats.totalSales += value;
            document.getElementById('total-sales').textContent = `$${dashboardData.stats.totalSales.toFixed(2)}`;
            break;
        case 'traffic':
            dashboardData.stats.activeUsers += Math.floor(value / 10);
            document.getElementById('active-users').textContent = dashboardData.stats.activeUsers;
            break;
        case 'inventory':
            dashboardData.stats.inventoryLevel += value;
            document.getElementById('inventory-level').textContent = dashboardData.stats.inventoryLevel;
            break;
    }
}

// Add entry to activity log
function addToActivityLog(dataType, value, timestamp) {
    const activityLog = document.getElementById('activity-log');
    const activityItem = document.createElement('div');
    activityItem.className = 'activity-item';

    const timeString = timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const dateString = timestamp.toLocaleDateString();

    let description;
    switch(dataType) {
        case 'sales':
            description = `New sale recorded: $${value.toFixed(2)}`;
            break;
        case 'traffic':
            description = `Website traffic update: ${value} visitors`;
            break;
        case 'inventory':
            description = `Inventory change: ${value > 0 ? '+' : ''}${value} units`;
            break;
    }

    activityItem.innerHTML = `
        <span>${description}</span>
        <span class="time">${timeString} - ${dateString}</span>
    `;

    // Add new item at the top
    activityLog.insertBefore(activityItem, activityLog.firstChild);

    // Limit to 10 items
    if (activityLog.children.length > 10) {
        activityLog.removeChild(activityLog.lastChild);
    }
}

// Update the chart with current data
function updateChart() {
    // Get the last 20 data points for each type
    const salesData = dashboardData.sales.slice(-20).map(item => item.value);
    const trafficData = dashboardData.traffic.slice(-20).map(item => item.value);
    const inventoryData = dashboardData.inventory.slice(-20).map(item => item.value);

    // Update chart data
    mainChart.data.datasets[0].data = salesData;
    mainChart.data.datasets[1].data = trafficData;
    mainChart.data.datasets[2].data = inventoryData;

    // Update labels (using timestamps)
    const allTimestamps = [
        ...dashboardData.sales.map(item => item.timestamp),
        ...dashboardData.traffic.map(item => item.timestamp),
        ...dashboardData.inventory.map(item => item.timestamp)
    ].sort((a, b) => a - b);

    const uniqueTimestamps = [...new Set(allTimestamps.map(ts => ts.toLocaleTimeString()))].slice(-20);
    mainChart.data.labels = uniqueTimestamps;

    mainChart.update();
}

// Generate some initial random data
function generateInitialData() {
    const now = new Date();
    const dataTypes = ['sales', 'traffic', 'inventory'];

    // Generate data for the last 20 minutes
    for (let i = 19; i >= 0; i--) {
        const timestamp = new Date(now.getTime() - i * 60000); // 1 minute intervals

        dataTypes.forEach(type => {
            let value;
            switch(type) {
                case 'sales':
                    value = Math.random() * 100 + 50;
                    break;
                case 'traffic':
                    value = Math.floor(Math.random() * 500 + 100);
                    break;
                case 'inventory':
                    value = Math.floor(Math.random() * 20 - 10);
                    break;
            }

            dashboardData[type].push({
                value: value,
                timestamp: timestamp,
                category: 'Initial'
            });

            // Update statistics
            updateStatistics(type, value);
        });
    }

    // Add some initial activity log entries
    const activityLog = document.getElementById('activity-log');
    for (let i = 0; i < 5; i++) {
        const timestamp = new Date(now.getTime() - (5 - i) * 3600000); // 1 hour intervals
        const type = dataTypes[Math.floor(Math.random() * dataTypes.length)];
        const value = dashboardData[type][i].value;

        addToActivityLog(type, value, timestamp);
    }

    // Update the chart
    updateChart();
}

// Update the dashboard with simulated real-time data
function updateDashboard() {
    const now = new Date();
    const dataTypes = ['sales', 'traffic', 'inventory'];

    dataTypes.forEach(type => {
        let value;
        switch(type) {
            case 'sales':
                value = Math.random() * 100 + 50;
                break;
            case 'traffic':
                value = Math.floor(Math.random() * 500 + 100);
                break;
            case 'inventory':
                value = Math.floor(Math.random() * 20 - 10);
                break;
        }

        dashboardData[type].push({
            value: value,
            timestamp: now,
            category: 'Real-time'
        });

        // Update statistics
        updateStatistics(type, value);

        // Add to activity log
        addToActivityLog(type, value, now);
    });

    // Update the chart
    updateChart();
}
