## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    let chartData = {
        labels: ['January', 'February', 'March', 'April', 'May', 'June'],
        datasets: [{
            label: 'Sample Data',
            data: [65, 59, 80, 81, 56, 55],
            backgroundColor: [
                'rgba(54, 162, 235, 0.5)',
                'rgba(255, 99, 132, 0.5)',
                'rgba(75, 192, 192, 0.5)',
                'rgba(153, 102, 255, 0.5)',
                'rgba(255, 159, 64, 0.5)',
                'rgba(201, 203, 207, 0.5)'
            ],
            borderColor: [
                'rgba(54, 162, 235, 1)',
                'rgba(255, 99, 132, 1)',
                'rgba(75, 192, 192, 1)',
                'rgba(153, 102, 255, 1)',
                'rgba(255, 159, 64, 1)',
                'rgba(201, 203, 207, 1)'
            ],
            borderWidth: 1
        }]
    };

    let realtimeChart = new Chart(ctx, {
        type: 'line',
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Update chart data button
    document.getElementById('updateData').addEventListener('click', function() {
        updateChartData(realtimeChart);
    });

    // Change chart type
    document.getElementById('chartType').addEventListener('change', function() {
        realtimeChart.config.type = this.value;
        realtimeChart.update();
    });

    // Form submission
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();
        addDataPoint(realtimeChart);
    });

    // Populate initial table data
    updateDataTable(chartData.datasets[0].data, chartData.labels, chartData.datasets[0].backgroundColor);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Update chart with random data
function updateChartData(chart) {
    const newData = chart.data.datasets[0].data.map(() => Math.floor(Math.random() * 100));
    chart.data.datasets[0].data = newData;
    chart.update();
    updateDataTable(newData, chart.data.labels, chart.data.datasets[0].backgroundColor);
}

// Add new data point from form
function addDataPoint(chart) {
    const labelInput = document.getElementById('dataLabel');
    const valueInput = document.getElementById('dataValue');
    const colorInput = document.getElementById('dataColor');

    const label = labelInput.value.trim();
    const value = parseFloat(valueInput.value);
    const color = colorInput.value;

    if (label && !isNaN(value)) {
        // Add to chart data
        chart.data.labels.push(label);
        chart.data.datasets[0].data.push(value);
        chart.data.datasets[0].backgroundColor.push(`${color}80`); // Add transparency
        chart.data.datasets[0].borderColor.push(color);

        // Update chart
        chart.update();

        // Update table
        updateDataTable(
            chart.data.datasets[0].data,
            chart.data.labels,
            chart.data.datasets[0].backgroundColor
        );

        // Reset form
        labelInput.value = '';
        valueInput.value = '';
    }
}

// Update the data table
function updateDataTable(data, labels, colors) {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    data.forEach((value, index) => {
        const row = document.createElement('tr');

        const labelCell = document.createElement('td');
        labelCell.textContent = labels[index];
        row.appendChild(labelCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = value;
        row.appendChild(valueCell);

        const colorCell = document.createElement('td');
        const colorBox = document.createElement('div');
        colorBox.style.width = '20px';
        colorBox.style.height = '20px';
        colorBox.style.backgroundColor = colors[index];
        colorBox.style.display = 'inline-block';
        colorBox.style.marginRight = '10px';
        colorBox.style.border = '1px solid #ddd';
        colorCell.appendChild(colorBox);
        colorCell.appendChild(document.createTextNode(colors[index]));
        row.appendChild(colorCell);

        const actionsCell = document.createElement('td');
        const deleteBtn = document.createElement('button');
        deleteBtn.textContent = 'Delete';
        deleteBtn.className = 'action-btn delete-btn';
        deleteBtn.dataset.index = index;
        deleteBtn.addEventListener('click', function() {
            deleteDataPoint(this.dataset.index);
        });
        actionsCell.appendChild(deleteBtn);
        row.appendChild(actionsCell);

        tableBody.appendChild(row);
    });
}

// Delete a data point
function deleteDataPoint(index) {
    const chart = Chart.getChart('realtimeChart');
    if (chart) {
        // Remove from chart data
        chart.data.labels.splice(index, 1);
        chart.data.datasets[0].data.splice(index, 1);
        chart.data.datasets[0].backgroundColor.splice(index, 1);
        chart.data.datasets[0].borderColor.splice(index, 1);

        // Update chart
        chart.update();

        // Update table
        updateDataTable(
            chart.data.datasets[0].data,
            chart.data.labels,
            chart.data.datasets[0].backgroundColor
        );
    }
}
