## JavaScript (script.js)

```javascript
// Initialize charts
let mainChart, secondaryChart;

// DOM elements
const dataForm = document.getElementById('dataForm');
const totalSalesElement = document.getElementById('totalSales').querySelector('.value');
const activeUsersElement = document.getElementById('activeUsers').querySelector('.value');
const inventoryLevelElement = document.getElementById('inventoryLevel').querySelector('.value');
const currentDateTimeElement = document.getElementById('currentDateTime');

// Update current date and time
function updateDateTime() {
    const now = new Date();
    currentDateTimeElement.textContent = now.toLocaleString();
}

// Generate random data for demonstration
function generateRandomData(type, timeRange) {
    const data = [];
    const labels = [];

    let count = 0;
    let maxValue = 0;

    switch(timeRange) {
        case 'day':
            count = 24;
            maxValue = type === 'sales' ? 1000 : 500;
            break;
        case 'week':
            count = 7;
            maxValue = type === 'sales' ? 5000 : 2000;
            break;
        case 'month':
            count = 30;
            maxValue = type === 'sales' ? 10000 : 5000;
            break;
    }

    for (let i = 0; i < count; i++) {
        labels.push(`${i + 1}`);
        data.push(Math.floor(Math.random() * maxValue) + 100);
    }

    return { labels, data };
}

// Update charts with new data
function updateCharts(dataType, timeRange) {
    const mainData = generateRandomData(dataType, timeRange);
    const secondaryData = generateRandomData(dataType === 'sales' ? 'traffic' : 'sales', timeRange);

    // Update main chart
    if (mainChart) {
        mainChart.destroy();
    }

    const mainCtx = document.getElementById('mainChart').getContext('2d');
    mainChart = new Chart(mainCtx, {
        type: dataType === 'sales' ? 'bar' : 'line',
        data: {
            labels: mainData.labels,
            datasets: [{
                label: dataType === 'sales' ? 'Sales ($)' : 'Traffic (visitors)',
                data: mainData.data,
                backgroundColor: dataType === 'sales' ? 'rgba(52, 152, 219, 0.7)' : 'rgba(46, 204, 113, 0.7)',
                borderColor: dataType === 'sales' ? 'rgba(52, 152, 219, 1)' : 'rgba(46, 204, 113, 1)',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Update secondary chart
    if (secondaryChart) {
        secondaryChart.destroy();
    }

    const secondaryCtx = document.getElementById('secondaryChart').getContext('2d');
    secondaryChart = new Chart(secondaryCtx, {
        type: 'doughnut',
        data: {
            labels: ['Region A', 'Region B', 'Region C', 'Region D'],
            datasets: [{
                label: 'Distribution',
                data: [
                    Math.floor(Math.random() * 100) + 10,
                    Math.floor(Math.random() * 100) + 10,
                    Math.floor(Math.random() * 100) + 10,
                    Math.floor(Math.random() * 100) + 10
                ],
                backgroundColor: [
                    'rgba(52, 152, 219, 0.7)',
                    'rgba(46, 204, 113, 0.7)',
                    'rgba(231, 76, 60, 0.7)',
                    'rgba(155, 89, 182, 0.7)'
                ],
                borderColor: [
                    'rgba(52, 152, 219, 1)',
                    'rgba(46, 204, 113, 1)',
                    'rgba(231, 76, 60, 1)',
                    'rgba(155, 89, 182, 1)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'right',
                }
            }
        }
    });

    // Update quick stats
    const totalSales = mainData.data.reduce((a, b) => a + b, 0);
    totalSalesElement.textContent = dataType === 'sales' ? `$${totalSales.toLocaleString()}` : totalSales.toLocaleString();

    const activeUsers = Math.floor(Math.random() * 10000) + 500;
    activeUsersElement.textContent = activeUsers.toLocaleString();

    const inventoryLevel = Math.floor(Math.random() * 100) + 1;
    inventoryLevelElement.textContent = `${inventoryLevel}%`;
}

// Form submission handler
dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('dataType').value;
    const timeRange = document.getElementById('timeRange').value;

    updateCharts(dataType, timeRange);
});

// Initialize dashboard
function initDashboard() {
    updateDateTime();
    updateCharts('sales', 'week');

    // Update date/time every second
    setInterval(updateDateTime, 1000);

    // Simulate real-time updates every 5 seconds
    setInterval(() => {
        const dataType = document.getElementById('dataType').value;
        const timeRange = document.getElementById('timeRange').value;
        updateCharts(dataType, timeRange);
    }, 5000);
}

// Start the dashboard when the page loads
window.addEventListener('DOMContentLoaded', initDashboard);
```

