        e.preventDefault();
        const formData = new FormData(this);

        // In a real app, you would send this data to an API
        console.log('Adding new data:', Object.fromEntries(formData));

        // Simulate adding data
        const newData = {
            name: formData.get('dataName'),
            value: parseFloat(formData.get('dataValue')),
            category: formData.get('dataCategory')
        };

        // Update the appropriate data structure
        if (newData.category === 'users') {
            dashboardData.totalUsers += newData.value;
            dashboardData.userActivity.push({
                date: new Date().toISOString().split('T')[0],
                value: newData.value
            });
        } else if (newData.category === 'revenue') {
            dashboardData.totalRevenue += newData.value;
            const productIndex = dashboardData.revenueData.labels.indexOf(newData.name);
            if (productIndex !== -1) {
                dashboardData.revenueData.values[productIndex] += newData.value;
            } else {
                dashboardData.revenueData.labels.push(newData.name);
                dashboardData.revenueData.values.push(newData.value);
            }
        }

        // Update the dashboard
        updateDashboard();

        // Reset form
        this.reset();

        // Show success message
        alert('Data added successfully (simulated)');
    });
}

// Simulate real-time updates
function simulateRealTimeUpdates() {
    // Generate random changes to simulate real-time data
    const changes = {
        totalUsers: Math.floor(Math.random() * 10) - 5,
        totalRevenue: (Math.random() * 100 - 50).toFixed(2),
        activeSessions: Math.floor(Math.random() * 20) - 10,
        conversionRate: (Math.random() * 2 - 1).toFixed(1)
    };

    // Apply changes
    dashboardData.totalUsers = Math.max(0, dashboardData.totalUsers + changes.totalUsers);
    dashboardData.totalRevenue = Math.max(0, parseFloat(dashboardData.totalRevenue) + parseFloat(changes.totalRevenue));
    dashboardData.activeSessions = Math.max(0, dashboardData.activeSessions + changes.activeSessions);
    dashboardData.conversionRate = Math.max(0, Math.min(100, parseFloat(dashboardData.conversionRate) + parseFloat(changes.conversionRate)));

    // Add new data point to user activity
    const lastDate = new Date(dashboardData.userActivity[dashboardData.userActivity.length - 1].date);
    const newDate = new Date(lastDate);
    newDate.setDate(newDate.getDate() + 1);

    dashboardData.userActivity.push({
        date: newDate.toISOString().split('T')[0],
        value: dashboardData.userActivity[dashboardData.userActivity.length - 1].value + Math.floor(Math.random() * 20) - 10
    });

    // Keep only the last 7 days of data
    if (dashboardData.userActivity.length > 7) {
        dashboardData.userActivity.shift();
    }

    // Update the dashboard
    updateDashboard();
}
