// Simulate API call to fetch data
function fetchData(dataSource, timeRange, region) {
    return new Promise((resolve) => {
        // Simulate network delay
        setTimeout(() => {
            // Generate sample data based on parameters
            const labels = generateLabels(timeRange);
            const values = generateRandomData(labels.length);

            // Additional data for other charts
            const pieData = [30, 20, 25, 25];
            const barData = [85, 92, 95, 88];

            // Quick stats data
            const quickStats = {
                totalSales: `$${(Math.random() * 100000).toFixed(2)}`,
                activeUsers: Math.floor(Math.random() * 10000),
                conversionRate: `${(Math.random() * 100).toFixed(1)}%`
            };

            resolve({
                labels,
                values,
                pieData,
                barData,
                quickStats
            });
        }, 500);
    });
}

// Simulate real-time data updates
function fetchRealTimeData(dataSource, timeRange, region) {
    return new Promise((resolve) => {
        // Simulate network delay
        setTimeout(() => {
            // Generate new data point
            const newValue = Math.floor(Math.random() * 100);

            resolve({
                labels: generateLabels(timeRange),
                values: generateRandomData(generateLabels(timeRange).length),
                pieData: [Math.random() * 30, Math.random() * 20, Math.random() * 25, Math.random() * 25],
                barData: [Math.random() * 100, Math.random() * 100, Math.random() * 100, Math.random() * 100],
                quickStats: {
                    totalSales: `$${(Math.random() * 100000).toFixed(2)}`,
                    activeUsers: Math.floor(Math.random() * 10000),
                    conversionRate: `${(Math.random() * 100).toFixed(1)}%`
                }
            });
        }, 300);
    });
}

// Helper function to generate labels based on time range
function generateLabels(timeRange) {
    const now = new Date();
    const labels = [];

    switch(timeRange) {
        case 'day':
            for (let i = 23; i >= 0; i--) {
                const hour = new Date(now);
                hour.setHours(now.getHours() - i);
                labels.push(hour.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
            }
            break;
        case 'week':
            for (let i = 6; i >= 0; i--) {
                const day = new Date(now);
                day.setDate(now.getDate() - i);
                labels.push(day.toLocaleDateString([], {weekday: 'short'}));
            }
            break;
        case 'month':
            for (let i = 29; i >= 0; i--) {
                const day = new Date(now);
                day.setDate(now.getDate() - i);
                labels.push(day.toLocaleDateString([], {month: 'short', day: 'numeric'}));
            }
            break;
        default:
            for (let i = 0; i < 10; i++) {
                labels.push(`Item ${i+1}`);
            }
    }

    return labels;
}

// Helper function to generate random data
function generateRandomData(count) {
    return Array.from({length: count}, () => Math.floor(Math.random() * 100));
}
