## JavaScript Functionality (script.js)

```javascript
// Dashboard Data Management
let dashboardData = {
    records: [],
    chart: null,
    chartConfig: {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Data Values',
                data: [],
                backgroundColor: 'rgba(52, 152, 219, 0.2)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    }
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Initialize chart
    const ctx = document.getElementById('dataChart').getContext('2d');
    dashboardData.chart = new Chart(ctx, dashboardData.chartConfig);

    // Set current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Form submission handler
    document.getElementById('dataForm').addEventListener('submit', handleFormSubmit);

    // Button event listeners
    document.getElementById('refreshBtn').addEventListener('click', refreshChart);
    document.getElementById('clearBtn').addEventListener('click', clearData);

    // Simulate initial data
    simulateInitialData();
});

// Update current date and time display
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const dataEntry = {
        type: formData.get('dataType'),
        value: parseFloat(formData.get('dataValue')),
        timestamp: new Date(formData.get('dataTimestamp'))
    };

    // Add data to records
    dashboardData.records.push(dataEntry);

    // Update UI
    updateStats();
    updateChart();

    // Reset form
    form.reset();
}

// Update statistics display
function updateStats() {
    if (dashboardData.records.length === 0) {
        document.getElementById('totalRecords').textContent = '0';
        document.getElementById('averageValue').textContent = '0.00';
        document.getElementById('lastUpdated').textContent = 'Never';
        return;
    }

    const total = dashboardData.records.length;
    const sum = dashboardData.records.reduce((acc, record) => acc + record.value, 0);
    const average = (sum / total).toFixed(2);
    const lastUpdated = dashboardData.records[dashboardData.records.length - 1].timestamp;

    document.getElementById('totalRecords').textContent = total;
    document.getElementById('averageValue').textContent = average;
    document.getElementById('lastUpdated').textContent = lastUpdated.toLocaleString();
}

// Update chart with current data
function updateChart() {
    if (dashboardData.records.length === 0) {
        dashboardData.chartConfig.data.labels = [];
        dashboardData.chartConfig.data.datasets[0].data = [];
        dashboardData.chart.update();
        return;
    }

    // Prepare data for chart
    const labels = dashboardData.records.map(record =>
        record.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
    );

    const values = dashboardData.records.map(record => record.value);

    // Update chart data
    dashboardData.chartConfig.data.labels = labels;
    dashboardData.chartConfig.data.datasets[0].data = values;

    // Update chart display
    dashboardData.chart.update();
}

// Refresh chart (simulate new data)
function refreshChart() {
    if (dashboardData.records.length === 0) return;

    // Simulate new data point
    const lastRecord = dashboardData.records[dashboardData.records.length - 1];
    const newValue = lastRecord.value + (Math.random() * 10 - 5); // Random variation
    const newTimestamp = new Date(lastRecord.timestamp.getTime() + 300000); // 5 minutes later

    dashboardData.records.push({
        type: lastRecord.type,
        value: Math.max(0, newValue), // Ensure positive value
        timestamp: newTimestamp
    });

    updateStats();
    updateChart();
}

// Clear all data
function clearData() {
    if (confirm('Are you sure you want to clear all data?')) {
        dashboardData.records = [];
        updateStats();
        updateChart();
    }
}

// Simulate initial data
function simulateInitialData() {
    const dataTypes = ['sales', 'traffic', 'temperature'];
    const now = new Date();

    for (let i = 0; i < 5; i++) {
        const randomType = dataTypes[Math.floor(Math.random() * dataTypes.length)];
        const randomValue = Math.floor(Math.random() * 100) + 1;
        const timestamp = new Date(now.getTime() - (5 - i) * 300000); // 5 minutes apart

        dashboardData.records.push({
            type: randomType,
            value: randomValue,
            timestamp: timestamp
        });
    }

    updateStats();
    updateChart();
}
