```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const realtimeChart = initRealtimeChart();
    const barChart = initBarChart();

    // Initialize data storage
    let dashboardData = {
        realtime: [],
        categories: {
            sales: [],
            revenue: [],
            users: [],
            traffic: []
        }
    };

    // Form submission handler
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const label = document.getElementById('dataLabel').value;
        const value = parseFloat(document.getElementById('dataValue').value);
        const category = document.getElementById('dataCategory').value;

        // Add data to storage
        const timestamp = new Date().toLocaleString();
        const newData = { label, value, category, timestamp };

        // Add to realtime data (last 20 entries)
        dashboardData.realtime.push(newData);
        if (dashboardData.realtime.length > 20) {
            dashboardData.realtime.shift();
        }

        // Add to category-specific data
        dashboardData.categories[category].push(newData);

        // Update charts
        updateRealtimeChart(realtimeChart, dashboardData.realtime);
        updateBarChart(barChart, dashboardData.categories);

        // Update table
        updateDataTable(newData);

        // Reset form
        this.reset();
    });

    // Simulate incoming data (for demonstration)
    setInterval(() => {
        if (Math.random() > 0.7) { // 30% chance to simulate new data
            const categories = ['sales', 'revenue', 'users', 'traffic'];
            const randomCategory = categories[Math.floor(Math.random() * categories.length)];
            const randomValue = Math.floor(Math.random() * 100) + 1;

            const simulatedData = {
                label: `Auto ${Math.floor(Math.random() * 1000)}`,
                value: randomValue,
                category: randomCategory,
                timestamp: new Date().toLocaleString()
            };

            dashboardData.realtime.push(simulatedData);
            if (dashboardData.realtime.length > 20) {
                dashboardData.realtime.shift();
            }

            dashboardData.categories[randomCategory].push(simulatedData);

            updateRealtimeChart(realtimeChart, dashboardData.realtime);
            updateBarChart(barChart, dashboardData.categories);
            updateDataTable(simulatedData);
        }
    }, 3000);
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    document.getElementById('currentDateTime').textContent = now.toLocaleString();
}

// Initialize real-time chart
function initRealtimeChart() {
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Real-Time Data',
                data: [],
                borderColor: 'rgb(75, 192, 192)',
                tension: 0.1,
                fill: false
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Real-Time Data Visualization'
                }
            }
        }
    });
}

// Update real-time chart
function updateRealtimeChart(chart, data) {
    const labels = data.map(item => item.timestamp);
    const values = data.map(item => item.value);

    chart.data.labels = labels;
    chart.data.datasets[0].data = values;
    chart.update();
}

// Initialize bar chart
function initBarChart() {
    const ctx = document.getElementById('barChart').getContext('2d');
    return new Chart(ctx, {
        type: 'bar',
        data: {
            labels: ['Sales', 'Revenue', 'Users', 'Traffic'],
            datasets: [{
                label: 'Category Totals',
                data: [0, 0, 0, 0],
                backgroundColor: [
                    'rgba(255, 99, 132, 0.7)',
                    'rgba(54, 162, 235, 0.7)',
                    'rgba(255, 206, 86, 0.7)',
                    'rgba(75, 192, 192, 0.7)'
                ],
                borderColor: [
                    'rgba(255, 99, 132, 1)',
                    'rgba(54, 162, 235, 1)',
                    'rgba(255, 206, 86, 1)',
                    'rgba(75, 192, 192, 1)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Data by Category'
                }
            }
        }
    });
}

// Update bar chart
function updateBarChart(chart, categories) {
    const totals = [
        categories.sales.reduce((sum, item) => sum + item.value, 0),
        categories.revenue.reduce((sum, item) => sum + item.value, 0),
        categories.users.reduce((sum, item) => sum + item.value, 0),
        categories.traffic.reduce((sum, item) => sum + item.value, 0)
    ];

    chart.data.datasets[0].data = totals;
    chart.update();
}

// Update data table
function updateDataTable(newData) {
    const table = document.getElementById('dataTable').getElementsByTagName('tbody')[0];
    const newRow = table.insertRow();

    const cell1 = newRow.insertCell(0);
    const cell2 = newRow.insertCell(1);
    const cell3 = newRow.insertCell(2);
    const cell4 = newRow.insertCell(3);

    cell1.textContent = newData.label;
    cell2.textContent = newData.value;
    cell3.textContent = newData.category;
    cell4.textContent = newData.timestamp;

    // Keep only the last 10 entries in the table
    if (table.rows.length > 10) {
        table.deleteRow(0);
    }
}
