    // Limit to 10 data points for better visualization
    if (chartData.labels.length > 10) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    dataChart.update();
}

// Form submission handler
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const valueInput = document.getElementById('dataValue');
    const labelInput = document.getElementById('dataLabel');

    const value = parseFloat(valueInput.value);
    const label = labelInput.value.trim();

    if (value && label) {
        updateChart(label, value);
        valueInput.value = '';
        labelInput.value = '';
    }
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Initialize the dashboard
function initDashboard() {
    createChart();
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Simulate real-time data updates
    setInterval(() => {
        const randomValue = Math.floor(Math.random() * 20) + 1;
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const randomMonth = months[Math.floor(Math.random() * months.length)];
        updateChart(randomMonth, randomValue);
    }, 5000);
}

// Start the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
