```javascript
// Initialize chart
let chart;
const ctx = document.getElementById('real-time-chart').getContext('2d');

// Data storage
let chartData = {
    labels: [],
    datasets: [{
        label: 'Data Values',
        data: [],
        backgroundColor: 'rgba(52, 152, 219, 0.2)',
        borderColor: 'rgba(52, 152, 219, 1)',
        borderWidth: 2,
        tension: 0.1,
        fill: true
    }]
};

// Initialize the chart
function initChart() {
    chart = new Chart(ctx, {
        type: 'line',
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                }
            }
        }
    });
}

// Update the chart with new data
function updateChart(label, value) {
    // Add new data point
    chartData.labels.push(label);
    chartData.datasets[0].data.push(value);

    // Limit the number of data points displayed
    const maxDataPoints = 10;
    if (chartData.labels.length > maxDataPoints) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    // Update the chart
    chart.update();
}

// Update the data table
function updateTable(timestamp, value, label) {
    const tableBody = document.querySelector('#data-table tbody');
    const newRow = document.createElement('tr');

    newRow.innerHTML = `
        <td>${timestamp}</td>
        <td>${value}</td>
        <td>${label}</td>
    `;

    tableBody.prepend(newRow);

    // Limit the number of rows displayed
    const maxRows = 10;
    if (tableBody.children.length > maxRows) {
        tableBody.removeChild(tableBody.lastChild);
    }
}

// Update the current time display
function updateTime() {
    const now = new Date();
    const timeString = now.toLocaleTimeString();
    document.getElementById('current-time').textContent = timeString;
}

// Form submission handler
document.getElementById('data-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const value = parseFloat(document.getElementById('data-value').value);
    const label = document.getElementById('data-label').value;
    const timestamp = new Date().toLocaleString();

    // Update chart and table
    updateChart(label, value);
    updateTable(timestamp, value, label);

    // Reset form
    this.reset();
});

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    initChart();

    // Update time every second
    updateTime();
    setInterval(updateTime, 1000);

    // Add some initial data
    const initialData = [
        { label: 'Initial 1', value: 10 },
        { label: 'Initial 2', value: 20 },
        { label: 'Initial 3', value: 15 }
    ];

    initialData.forEach(item => {
        updateChart(item.label, item.value);
        updateTable(new Date().toLocaleString(), item.value, item.label);
    });
});
