// Sample initial data
let dashboardData = [
    { category: 'Sales', value: 120, date: '2023-01-15' },
    { category: 'Marketing', value: 85, date: '2023-01-16' },
    { category: 'Operations', value: 95, date: '2023-01-17' }
];

// Initialize chart
let dataChart;
const ctx = document.getElementById('dataChart').getContext('2d');

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const category = document.getElementById('category').value;
    const value = parseFloat(document.getElementById('value').value);
    const date = document.getElementById('date').value;

    if (category && value && date) {
        const newData = { category, value, date };
        dashboardData.push(newData);
        updateDashboard();
        this.reset();
    }
});

// Update functions
function updateDashboard() {
    updateTable();
    updateChart();
}

function updateTable() {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    // Sort by date (newest first)
    const sortedData = [...dashboardData].sort((a, b) => new Date(b.date) - new Date(a.date));

    // Show only last 5 entries
    const recentData = sortedData.slice(0, 5);

    recentData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.category}</td>
            <td>${item.value}</td>
            <td>${new Date(item.date).toLocaleDateString()}</td>
        `;
        tableBody.appendChild(row);
    });
}

function updateChart() {
    // Group data by category
    const categories = [...new Set(dashboardData.map(item => item.category))];
    const chartData = categories.map(category => {
        const categoryData = dashboardData.filter(item => item.category === category);
        const total = categoryData.reduce((sum, item) => sum + item.value, 0);
        return total;
    });

    // Destroy previous chart if it exists
    if (dataChart) {
        dataChart.destroy();
    }

    // Create new chart
    dataChart = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: categories,
            datasets: [{
                label: 'Total Values by Category',
                data: chartData,
                backgroundColor: [
                    'rgba(54, 162, 235, 0.7)',
                    'rgba(255, 99, 132, 0.7)',
                    'rgba(75, 192, 192, 0.7)'
                ],
                borderColor: [
                    'rgba(54, 162, 235, 1)',
                    'rgba(255, 99, 132, 1)',
                    'rgba(75, 192, 192, 1)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Button event listeners
document.getElementById('refreshBtn').addEventListener('click', updateChart);
document.getElementById('clearBtn').addEventListener('click', function() {
    if (confirm('Are you sure you want to clear all data?')) {
        dashboardData = [];
        updateDashboard();
    }
});

// Initialize dashboard
updateDashboard();

// Simulate real-time updates (every 10 seconds)
setInterval(() => {
    // Generate random data for demo purposes
