// Initialize chart
let dataChart;
let chartData = {
    labels: [],
    datasets: [{
        label: 'Data',
        data: [],
        borderColor: 'rgb(52, 152, 219)',
        backgroundColor: 'rgba(52, 152, 219, 0.2)',
