document.addEventListener('DOMContentLoaded', function() {
    const ctx = document.getElementById('dataChart').getContext('2d');
    dataChart = new Chart(ctx, {
        type: 'line',
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            }
        }
    });

    // Load initial data
    updateChart();

    // Handle form submission
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();
        updateChart();
    });
});

// Function to generate random data (simulating real-time data)
function generateRandomData(dataType, timeRange) {
    const now = new Date();
    const dataPoints = timeRange === '1h' ? 60 :
                      timeRange === '6h' ? 360 :
                      1440; // 24h

    const labels = [];
    const data = [];

    for (let i = 0; i < dataPoints; i++) {
        const time = new Date(now.getTime() - (i * (60 * 1000))); // 1 minute intervals
        labels.unshift(time.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));

        // Generate different data based on type
        let value;
        switch(dataType) {
            case 'temperature':
                value = 20 + Math.sin(i * 0.1) * 5 + Math.random() * 2;
                break;
            case 'humidity':
                value = 50 + Math.sin(i * 0.05) * 20 + Math.random() * 5;
                break;
            case 'pressure':
                value = 1010 + Math.sin(i * 0.02) * 10 + Math.random() * 2;
                break;
            default:
                value = Math.random() * 100;
        }

        data.unshift(parseFloat(value.toFixed(2)));
    }

    return { labels, data };
}

// Update the chart with new data
function updateChart() {
    const dataType = document.getElementById('dataType').value;
    const timeRange = document.getElementById('timeRange').value;

    // Generate new data
    const newData = generateRandomData(dataType, timeRange);

    // Update chart data
    dataChart.data.labels = newData.labels;
    dataChart.data.datasets[0].data = newData.data;
    dataChart.data.datasets[0].label = dataType.charAt(0).toUpperCase() + dataType.slice(1);

    // Update chart title
    dataChart.options.plugins.title = {
        display: true,
        text: `${dataType.charAt(0).toUpperCase() + dataType.slice(1)} (${timeRange})`
    };

    // Update last updated time
    document.getElementById('lastUpdated').textContent = new Date().toLocaleTimeString();

    // Redraw the chart
    dataChart.update();
}

// Simulate real-time updates every 5 seconds
setInterval(updateChart, 5000);
