    { name: 'Initial B', value: 15, category: 'B', status: 'inactive' }
];

// Function to update the chart
function updateChart() {
    const categories = ['A', 'B', 'C'];
    const activeData = Array(categories.length).fill(0);
    const inactiveData = Array(categories.length).fill(0);

    dashboardData.forEach(item => {
        const index = categories.indexOf(item.category);
        if (index !== -1) {
            if (item.status === 'active') {
                activeData[index] += item.value;
            } else {
                inactiveData[index] += item.value;
            }
        }
    });

    dataChart.data.labels = categories;
    dataChart.data.datasets[0].data = activeData;
    dataChart.data.datasets[1].data = inactiveData;
    dataChart.update();
}

// Function to update the data table
function updateTable() {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    dashboardData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.name}</td>
            <td>${item.value}</td>
            <td>${item.category}</td>
            <td>
                <span class="status-indicator ${item.status === 'active' ? 'status-active' : 'status-inactive'}"></span>
                ${item.status.charAt(0).toUpperCase() + item.status.slice(1)}
            </td>
        `;
        tableBody.appendChild(row);
    });
}

// Handle form submission
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const newData = {
        name: document.getElementById('dataName').value,
        value: parseFloat(document.getElementById('dataValue').value),
        category: document.getElementById('dataCategory').value,
        status: document.getElementById('dataStatus').value
    };

    dashboardData.push(newData);
    updateChart();
    updateTable();

    // Reset form
    this.reset();
});

// Initialize dashboard
updateChart();
updateTable();

// Simulate real-time updates (every 5 seconds)
setInterval(() => {
    // Add some random data for demonstration
    const categories = ['A', 'B', 'C'];
    const randomCategory = categories[Math.floor(Math.random() * categories.length)];
    const randomValue = Math.floor(Math.random() * 20) + 1;
    const randomStatus = Math.random() > 0.5 ? 'active' : 'inactive';

    dashboardData.push({
        name: `Auto ${Math.floor(Math.random() * 1000)}`,
        value: randomValue,
        category: randomCategory,
        status: randomStatus
    });

    // Keep only the last 10 items
    if (dashboardData.length > 10) {
        dashboardData.shift();
    }

    updateChart();
    updateTable();
}, 5000);
