```javascript
// Initialize chart data
let chartData = {
    labels: [],
    datasets: [{
        label: 'Live Data',
        data: [],
        backgroundColor: 'rgba(75, 192, 192, 0.2)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 2,
        tension: 0.1
    }]
};

// Create chart
const ctx = document.getElementById('liveChart').getContext('2d');
const liveChart = new Chart(ctx, {
    type: 'line',
    data: chartData,
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Form submission handler
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    // Get form values
    const value = parseFloat(document.getElementById('dataValue').value);
    const label = document.getElementById('dataLabel').value;

    // Validate input
    if (isNaN(value) || !label) {
        alert('Please enter valid data');
        return;
    }

    // Add data to chart
    addDataToChart(label, value);

    // Update last updated time
    document.getElementById('lastUpdated').textContent = new Date().toLocaleTimeString();

    // Reset form
    this.reset();
});

// Function to add data to chart
function addDataToChart(label, value) {
    // Limit to 10 data points for demo purposes
    if (chartData.labels.length >= 10) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    // Add new data
    chartData.labels.push(label);
    chartData.datasets[0].data.push(value);

    // Update chart
    liveChart.update();
}

// Simulate real-time data (for demonstration)
function simulateRealTimeData() {
    setInterval(() => {
        const randomValue = Math.floor(Math.random() * 100);
        const timestamp = new Date().toLocaleTimeString();

        addDataToChart(timestamp, randomValue);
        document.getElementById('lastUpdated').textContent = timestamp;
    }, 3000);
}

// Start simulation
simulateRealTimeData();
