let systemLoad = 0;
let dataPoints = 0;

// Update stats display
function updateStats() {
    document.getElementById('active-users').textContent = activeUsers;
    document.getElementById('system-load').textContent = `${systemLoad}%`;
    document.getElementById('data-points').textContent = dataPoints;
}

// Simulate data updates
function simulateData() {
    // Randomly update stats
    activeUsers = Math.floor(Math.random() * 100) + 1;
    systemLoad = Math.floor(Math.random() * 100);
    dataPoints += Math.floor(Math.random() * 5) + 1;

    updateStats();

    // Add random data points to chart
    const now = new Date();
    const timeLabel = now.toLocaleTimeString();

    dataChart.data.labels.push(timeLabel);
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
    }

    dataChart.data.datasets.forEach(dataset => {
        const newValue = Math.random() * 100;
        dataset.data.push(newValue);
        if (dataset.data.length > 20) {
            dataset.data.shift();
        }
    });

    dataChart.update();
}

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('dataType').value;
    const dataValue = parseFloat(document.getElementById('dataValue').value);
    const dataSource = document.getElementById('dataSource').value;

    // Find the dataset index based on data type
    const datasetIndex = dataChart.data.datasets.findIndex(ds =>
        ds.label.toLowerCase() === dataType
    );

    if (datasetIndex !== -1) {
        // Add new data point
        const now = new Date();
        const timeLabel = now.toLocaleTimeString();

        dataChart.data.labels.push(timeLabel);
        if (dataChart.data.labels.length > 20) {
            dataChart.data.labels.shift();
        }

        dataChart.data.datasets.forEach((dataset, index) => {
            if (index === datasetIndex) {
                dataset.data.push(dataValue);
            } else {
                // Add null for other datasets to maintain alignment
                dataset.data.push(null);
            }

            if (dataset.data.length > 20) {
                dataset.data.shift();
            }
        });

        dataChart.update();
        dataPoints++;
        updateStats();

        // Reset form
        this.reset();
    } else {
        alert('Invalid data type selected');
    }
});

// Start simulation
setInterval(simulateData, 3000);
simulateData(); // Initial call
