        borderColor: [
            'rgba(255, 99, 132, 1)',
            'rgba(54, 162, 235, 1)',
            'rgba(255, 206, 86, 1)',
            'rgba(75, 192, 192, 1)'
        ],
        borderWidth: 1
    }]
};

// Initialize charts
const salesCtx = document.getElementById('salesChart').getContext('2d');
const productCtx = document.getElementById('productChart').getContext('2d');

const salesChart = new Chart(salesCtx, {
    type: 'bar',
    data: salesData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

const productChart = new Chart(productCtx, {
    type: 'pie',
    data: productData,
    options: {
        responsive: true
    }
});

// Form handling
const form = document.getElementById('dataForm');
const formStatus = document.getElementById('formStatus');
const lastUpdated = document.getElementById('last-updated');

form.addEventListener('submit', function(e) {
    e.preventDefault();

    // Get form values
    const product = document.getElementById('product').value;
    const quantity = parseInt(document.getElementById('quantity').value);
    const price = parseFloat(document.getElementById('price').value);
    const category = document.getElementById('category').value;

    // Validate
    if (!product || !quantity || !price || !category) {
        showStatus('Please fill all fields', 'error');
        return;
    }

    // Update data (in a real app, this would be an API call)
    updateData(product, quantity, price, category);

    // Show success message
    showStatus('Data added successfully!', 'success');

    // Reset form
    form.reset();
});

function updateData(product, quantity, price, category) {
    // Update sales data (simulating real-time update)
    const currentMonth = new Date().toLocaleString('default', { month: 'short' });
    const monthIndex = salesData.labels.indexOf(currentMonth);

    if (monthIndex !== -1) {
        // Update existing month
        salesData.datasets[0].data[monthIndex] += price * quantity;
    } else {
        // Add new month
        salesData.labels.push(currentMonth);
        salesData.datasets[0].data.push(price * quantity);
    }

    // Update product distribution
    const categoryIndex = productData.labels.indexOf(category.charAt(0).toUpperCase() + category.slice(1));
    if (categoryIndex !== -1) {
        productData.datasets[0].data[categoryIndex] += quantity;
    }

    // Update charts
    salesChart.update();
    productChart.update();

    // Update last updated time
    const now = new Date();
    lastUpdated.textContent = `Last updated: ${now.toLocaleTimeString()}`;
}

function showStatus(message, type) {
    formStatus.textContent = message;
    formStatus.className = `status ${type}`;
    formStatus.style.display = 'block';

    // Hide after 3 seconds
    setTimeout(() => {
        formStatus.style.display = 'none';
    }, 3000);
}

// Simulate real-time updates
setInterval(() => {
    // Generate random data to simulate real-time updates
    const randomValue = Math.floor(Math.random() * 1000) + 100;
    const currentMonth = new Date().toLocaleString('default', { month: 'short' });
    const monthIndex = salesData.labels.indexOf(currentMonth);

    if (monthIndex !== -1) {
        salesData.datasets[0].data[monthIndex] += randomValue;
    } else {
        salesData.labels.push(currentMonth);
        salesData.datasets[0].data.push(randomValue);
    }

    salesChart.update();

    // Update last updated time
    const now = new Date();
    lastUpdated.textContent = `Last updated: ${now.toLocaleTimeString()}`;
}, 5000);
