```javascript
// Initialize chart
let dataChart;
let chartData = {
    labels: [],
    datasets: [{
        label: 'Temperature (°C)',
        data: [],
        borderColor: 'rgb(255, 99, 132)',
        backgroundColor: 'rgba(255, 99, 132, 0.2)',
        tension: 0.1,
        fill: true
    }]
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set up current time display
    updateCurrentTime();
    setInterval(updateCurrentTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('data-chart').getContext('2d');
    dataChart = new Chart(ctx, {
        type: 'line',
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false
                }
            }
        }
    });

    // Load initial data
    loadInitialData();

    // Set up form submission
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();
        updateChartData();
    });

    // Simulate real-time updates
    setInterval(simulateRealTimeData, 5000);
});

// Update current time display
function updateCurrentTime() {
    const now = new Date();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Load initial data
function loadInitialData() {
    // Generate some initial random data
    const now = new Date();
    const dataPoints = 12; // Last 12 hours

    chartData.labels = [];
    chartData.datasets[0].data = [];

    for (let i = dataPoints - 1; i >= 0; i--) {
        const time = new Date(now - i * 60 * 60 * 1000);
        chartData.labels.push(time.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));

        // Generate random temperature between 15-30°C
        const value = Math.floor(Math.random() * 15) + 15;
        chartData.datasets[0].data.push(value);
    }

    // Update table
    updateDataTable();

    // Update chart
    dataChart.update();
}

// Update chart data based on form selection
function updateChartData() {
    const dataType = document.getElementById('data-type').value;
    const timeRange = document.getElementById('time-range').value;

    // Update chart title based on selected data type
    let unit = '°C';
    let label = 'Temperature';

    if (dataType === 'humidity') {
        unit = '%';
        label = 'Humidity';
    } else if (dataType === 'pressure') {
        unit = 'hPa';
        label = 'Pressure';
    }

    // Update chart dataset
    chartData.datasets[0].label = `${label} (${unit})`;

    // Generate new data based on selection
    const now = new Date();
    let dataPoints;
    let interval;

    switch(timeRange) {
        case '1h':
            dataPoints = 60;
            interval = 60 * 1000; // 1 minute intervals
            break;
        case '6h':
            dataPoints = 60;
            interval = 6 * 60 * 1000; // 6 minute intervals
            break;
        case '12h':
            dataPoints = 24;
            interval = 30 * 60 * 1000; // 30 minute intervals
            break;
        case '24h':
        default:
            dataPoints = 24;
            interval = 60 * 60 * 1000; // 1 hour intervals
            break;
    }

    chartData.labels = [];
    chartData.datasets[0].data = [];

    for (let i = dataPoints - 1; i >= 0; i--) {
        const time = new Date(now - i * interval);
        chartData.labels.push(time.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));

        // Generate random values based on data type
        let value;
        if (dataType === 'temperature') {
            value = Math.floor(Math.random() * 15) + 15; // 15-30°C
        } else if (dataType === 'humidity') {
            value = Math.floor(Math.random() * 40) + 30; // 30-70%
        } else {
            value = Math.floor(Math.random() * 50) + 950; // 950-1000 hPa
        }

        chartData.datasets[0].data.push(value);
    }

    // Update table
    updateDataTable();

    // Update chart
    dataChart.update();
}

// Update the data table with the latest values
function updateDataTable() {
    const tableBody = document.getElementById('table-body');
    tableBody.innerHTML = '';

    // Get the last 5 data points
    const recentData = chartData.labels.slice(-5).reverse();
    const recentValues = chartData.datasets[0].data.slice(-5).reverse();

    recentData.forEach((time, index) => {
        const row = document.createElement('tr');
        const timeCell = document.createElement('td');
        const valueCell = document.createElement('td');
        const unitCell = document.createElement('td');

        timeCell.textContent = time;
        valueCell.textContent = recentValues[index];

        // Extract unit from the label
        const unitMatch = chartData.datasets[0].label.match(/\(([^)]+)\)/);
        const unit = unitMatch ? unitMatch[1] : '';
        unitCell.textContent = unit;

        row.appendChild(timeCell);
        row.appendChild(valueCell);
        row.appendChild(unitCell);
        tableBody.appendChild(row);
    });
}

// Simulate real-time data updates
function simulateRealTimeData() {
    // Add new data point
    const now = new Date();
    const timeLabel = now.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    chartData.labels.push(timeLabel);

    // Generate new value based on current data type
    const dataType = document.getElementById('data-type').value;
    let newValue;

    if (dataType === 'temperature') {
        newValue = Math.floor(Math.random() * 15) + 15; // 15-30°C
    } else if (dataType === 'humidity') {
        newValue = Math.floor(Math.random() * 40) + 30; // 30-70%
    } else {
        newValue = Math.floor(Math.random() * 50) + 950; // 950-1000 hPa
    }

    chartData.datasets[0].data.push(newValue);

    // Remove oldest data point if we have more than 24
    if (chartData.labels.length > 24) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    // Update table
    updateDataTable();

    // Update chart
    dataChart.update();
}
```

