// Initialize data storage
let dataPoints = [];
let categoryCounts = { A: 0, B: 0, C: 0 };

// Initialize charts
const ctxRealtime = document.getElementById('realtimeChart').getContext('2d');
const ctxCategory = document.getElementById('categoryChart').getContext('2d');

// Realtime chart configuration
const realtimeChart = new Chart(ctxRealtime, {
    type: 'line',
    data: {
        labels: [],
        datasets: [{
            label: 'Data Values',
            data: [],
            borderColor: 'rgb(75, 192, 192)',
            tension: 0.1,
            fill: false
        }]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Category chart configuration
const categoryChart = new Chart(ctxCategory, {
    type: 'bar',
    data: {
        labels: ['Category A', 'Category B', 'Category C'],
        datasets: [{
            label: 'Entries per Category',
            data: [0, 0, 0],
            backgroundColor: [
                'rgba(255, 99, 132, 0.7)',
                'rgba(54, 162, 235, 0.7)',
                'rgba(255, 206, 86, 0.7)'
            ],
            borderColor: [
                'rgba(255, 99, 132, 1)',
                'rgba(54, 162, 235, 1)',
                'rgba(255, 206, 86, 1)'
            ],
            borderWidth: 1
        }]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: true,
                ticks: {
                    stepSize: 1
                }
            }
        }
    }
});

// Form submission handler
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const value = parseFloat(document.getElementById('value').value);
    const category = document.getElementById('category').value;

    // Add data point
    dataPoints.push({ value, category, timestamp: new Date() });

    // Update category counts
    categoryCounts[category]++;

    // Update charts
    updateCharts();

    // Update statistics
    updateStatistics();

    // Reset form
    this.reset();
});

// Function to update all charts
function updateCharts() {
    // Update realtime chart
    const timestamps = dataPoints.map(dp => dp.timestamp.toLocaleTimeString());
    const values = dataPoints.map(dp => dp.value);

    realtimeChart.data.labels = timestamps;
    realtimeChart.data.datasets[0].data = values;
    realtimeChart.update();

    // Update category chart
    categoryChart.data.datasets[0].data = [
        categoryCounts.A,
        categoryCounts.B,
        categoryCounts.C
    ];
    categoryChart.update();
}

// Function to update statistics
function updateStatistics() {
    const totalEntries = dataPoints.length;
    const sum = dataPoints.reduce((acc, dp) => acc + dp.value, 0);
    const avg = totalEntries > 0 ? (sum / totalEntries).toFixed(2) : 0;
    const lastUpdate = new Date().toLocaleTimeString();

    document.getElementById('totalEntries').textContent = totalEntries;
    document.getElementById('avgValue').textContent = avg;
    document.getElementById('lastUpdate').textContent = lastUpdate;
}

// Simulate real-time data (optional)
function simulateRealTimeData() {
    // Generate random data every 5 seconds
    setInterval(() => {
        const randomValue = Math.floor(Math.random() * 100) + 1;
        const categories = ['A', 'B', 'C'];
        const randomCategory = categories[Math.floor(Math.random() * categories.length)];

        dataPoints.push({
            value: randomValue,
            category: randomCategory,
            timestamp: new Date()
        });

        categoryCounts[randomCategory]++;

        updateCharts();
        updateStatistics();
    }, 5000);
}

// Start simulation (optional)
simulateRealTimeData();
