// Sample data generators
function generateSalesData(timeRange) {
    const labels = [];
    const data = [];

    if (timeRange === 'daily') {
        for (let i = 1; i <= 30; i++) {
            labels.push(`Day ${i}`);
            data.push(Math.floor(Math.random() * 1000) + 500);
        }
    } else if (timeRange === 'weekly') {
        for (let i = 1; i <= 12; i++) {
            labels.push(`Week ${i}`);
            data.push(Math.floor(Math.random() * 5000) + 2000);
        }
    } else { // monthly
        for (let i = 1; i <= 12; i++) {
            labels.push(`Month ${i}`);
            data.push(Math.floor(Math.random() * 20000) + 10000);
        }
    }

    return { labels, data };
}

function generateTrafficData(timeRange) {
    const labels = [];
    const data = [];

    if (timeRange === 'daily') {
        for (let i = 1; i <= 30; i++) {
            labels.push(`Day ${i}`);
            data.push(Math.floor(Math.random() * 5000) + 1000);
        }
    } else if (timeRange === 'weekly') {
        for (let i = 1; i <= 12; i++) {
            labels.push(`Week ${i}`);
            data.push(Math.floor(Math.random() * 20000) + 5000);
        }
    } else { // monthly
        for (let i = 1; i <= 12; i++) {
            labels.push(`Month ${i}`);
            data.push(Math.floor(Math.random() * 100000) + 20000);
        }
    }

    return { labels, data };
}

function generatePerformanceData(timeRange) {
    const labels = [];
    const data = [];

    if (timeRange === 'daily') {
        for (let i = 1; i <= 30; i++) {
            labels.push(`Day ${i}`);
            data.push(Math.floor(Math.random() * 100) + 1);
        }
    } else if (timeRange === 'weekly') {
        for (let i = 1; i <= 12; i++) {
            labels.push(`Week ${i}`);
            data.push(Math.floor(Math.random() * 100) + 1);
        }
    } else { // monthly
        for (let i = 1; i <= 12; i++) {
            labels.push(`Month ${i}`);
            data.push(Math.floor(Math.random() * 100) + 1);
        }
    }

    return { labels, data };
}

// Chart initialization
let mainChart;
const ctx = document.getElementById('mainChart').getContext('2d');

function initChart(dataType, timeRange) {
    let chartData;
    let chartTitle;
    let chartColor;

    switch(dataType) {
        case 'sales':
            chartData = generateSalesData(timeRange);
            chartTitle = 'Sales Data';
            chartColor = 'rgba(52, 152, 219, 0.7)';
            break;
        case 'traffic':
            chartData = generateTrafficData(timeRange);
            chartTitle = 'Traffic Data';
            chartColor = 'rgba(46, 204, 113, 0.7)';
            break;
        case 'performance':
            chartData = generatePerformanceData(timeRange);
            chartTitle = 'Performance Metrics';
            chartColor = 'rgba(231, 76, 60, 0.7)';
            break;
    }

    if (mainChart) {
        mainChart.destroy();
    }

    mainChart = new Chart(ctx, {
        type: 'bar',
        data: {
            labels: chartData.labels,
            datasets: [{
                label: chartTitle,
                data: chartData.data,
                backgroundColor: chartColor,
                borderColor: chartColor.replace('0.7', '1'),
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Update last updated time
    const now = new Date();
    document.getElementById('lastUpdated').textContent = now.toLocaleString();
}

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('dataType').value;
    const timeRange = document.getElementById('timeRange').value;

    initChart(dataType, timeRange);
});

// Initialize with default values
document.addEventListener('DOMContentLoaded', function() {
    initChart('sales', 'daily');
});

// Simulate real-time updates
setInterval(() => {
    const dataType = document.getElementById('dataType').value;
    const timeRange = document.getElementById('timeRange').value;
    initChart(dataType, timeRange);
}, 15000); // Update every 15 seconds
