        data: [],
        borderColor: 'rgb(255, 99, 132)',
        backgroundColor: 'rgba(255, 99, 132, 0.5)',
        tension: 0.1
    }]
};

let summaryData = {
    labels: ['Temperature', 'Humidity', 'Pressure'],
    datasets: [{
        label: 'Average Values',
        data: [25, 50, 1013],
        backgroundColor: [
            'rgba(255, 99, 132, 0.7)',
            'rgba(54, 162, 235, 0.7)',
            'rgba(255, 206, 86, 0.7)'
        ],
        borderColor: [
            'rgba(255, 99, 132, 1)',
            'rgba(54, 162, 235, 1)',
            'rgba(255, 206, 86, 1)'
        ],
        borderWidth: 1
    }]
};

// Initialize charts
const realTimeCtx = document.getElementById('realTimeChart').getContext('2d');
const summaryCtx = document.getElementById('summaryChart').getContext('2d');

const realTimeChart = new Chart(realTimeCtx, {
    type: 'line',
    data: realTimeData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: false
            }
        }
    }
});

const summaryChart = new Chart(summaryCtx, {
    type: 'bar',
    data: summaryData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Form handling
const form = document.getElementById('dataForm');
const statusMessage = document.getElementById('statusMessage');

form.addEventListener('submit', function(e) {
    e.preventDefault();

    // Get form values
    const dataType = document.getElementById('dataType').value;
    const dataValue = parseFloat(document.getElementById('dataValue').value);
    const dataLocation = document.getElementById('dataLocation').value;

    // Validate input
    if (isNaN(dataValue)) {
        showStatus('Please enter a valid number', 'error');
        return;
    }

    // Update charts
    updateRealTimeChart(dataType, dataValue);
    updateSummaryChart(dataType, dataValue);

    // Show success message
    showStatus(`Added ${dataType} data point: ${dataValue} at ${dataLocation}`, 'success');

    // Reset form
    form.reset();
});

function updateRealTimeChart(type, value) {
    // Add new data point
    const now = new Date();
    const timeString = now.toLocaleTimeString();

    realTimeData.labels.push(timeString);
    realTimeData.datasets[0].data.push(value);

    // Update chart title based on data type
    realTimeData.datasets[0].label = `${type.charAt(0).toUpperCase() + type.slice(1)} (${getUnit(type)})`;

    // Limit to 20 data points
    if (realTimeData.labels.length > 20) {
        realTimeData.labels.shift();
        realTimeData.datasets[0].data.shift();
    }

    realTimeChart.update();
}

function updateSummaryChart(type, value) {
    // Find index of the data type
    const index = summaryData.labels.findIndex(label =>
        label.toLowerCase() === type.toLowerCase()
    );

    if (index !== -1) {
        // Update the value (simple average for demo)
        const currentValue = summaryData.datasets[0].data[index];
        const newValue = (currentValue + value) / 2;
        summaryData.datasets[0].data[index] = newValue.toFixed(1);
        summaryChart.update();
    }
}

function getUnit(type) {
    const units = {
        temperature: '°C',
        humidity: '%',
        pressure: 'hPa'
    };
    return units[type] || '';
}

function showStatus(message, type) {
    statusMessage.textContent = message;
    statusMessage.style.display = 'block';

    if (type === 'success') {
        statusMessage.style.backgroundColor = '#e9f7ef';
        statusMessage.style.color = '#2d8659';
    } else {
        statusMessage.style.backgroundColor = '#fde8e8';
        statusMessage.style.color = '#c92a2a';
    }

    // Hide after 3 seconds
    setTimeout(() => {
        statusMessage.style.display = 'none';
    }, 3000);
}

// Simulate real-time data updates
