    labels: [],
    datasets: [{
        label: 'Real-Time Data',
        data: [],
        borderColor: 'rgb(52, 152, 219)',
        backgroundColor: 'rgba(52, 152, 219, 0.2)',
        tension: 0.1,
        fill: true
    }]
};

const realtimeChart = new Chart(ctx, {
    type: 'line',
    data: chartData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        },
        animation: {
            duration: 0 // Disable animations for real-time updates
        }
    }
});

// Simulate WebSocket connection and data updates
function simulateWebSocket() {
    const statusElement = document.getElementById('connection-status');
    statusElement.textContent = 'Connected';
    statusElement.style.color = '#27ae60';

    // Generate random data points
    setInterval(() => {
        const randomValue = Math.floor(Math.random() * 100) + 1;
        const timestamp = new Date().toLocaleTimeString();

        // Update chart
        if (chartData.labels.length > 10) {
            chartData.labels.shift();
            chartData.datasets[0].data.shift();
        }

        chartData.labels.push(timestamp);
        chartData.datasets[0].data.push(randomValue);
        realtimeChart.update();
    }, 2000);
}

// Handle form submission
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const value = parseFloat(document.getElementById('dataValue').value);
    const label = document.getElementById('dataLabel').value;

    if (isNaN(value) || !label) {
        alert('Please enter valid data');
        return;
    }

    // Add to chart
    if (chartData.labels.length > 10) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    chartData.labels.push(label);
    chartData.datasets[0].data.push(value);
    realtimeChart.update();

    // Reset form
    this.reset();
});

// Initialize
simulateWebSocket();
```

