## JavaScript (script.js)

```javascript
// Initialize chart
let dataChart;
const ctx = document.getElementById('data-chart').getContext('2d');

// Initialize with some sample data
let currentData = generateSampleData('temperature', '1h');

// Update time display
function updateTimeDisplay() {
    const now = new Date();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Generate sample data for demonstration
function generateSampleData(type, range) {
    const data = [];
    const now = new Date();
    const hours = parseInt(range) || 1;
    const points = hours * 60; // One point per minute

    for (let i = 0; i < points; i++) {
        const timestamp = new Date(now - (i * 60 * 1000));
        let value;

        switch(type) {
            case 'temperature':
                value = 20 + Math.sin(i * 0.1) * 5 + (Math.random() * 2 - 1);
                break;
            case 'humidity':
                value = 50 + Math.sin(i * 0.05) * 20 + (Math.random() * 5 - 2.5);
                break;
            case 'pressure':
                value = 1013 + Math.sin(i * 0.02) * 5 + (Math.random() * 1 - 0.5);
                break;
            default:
                value = Math.random() * 100;
        }

        data.push({
            timestamp: timestamp,
            value: parseFloat(value.toFixed(2)),
            unit: getUnit(type)
        });
    }

    return data.sort((a, b) => a.timestamp - b.timestamp);
}

function getUnit(type) {
    switch(type) {
        case 'temperature': return '°C';
        case 'humidity': return '%';
        case 'pressure': return 'hPa';
        default: return '';
    }
}

// Update the chart with new data
function updateChart() {
    if (dataChart) {
        dataChart.destroy();
    }

    const labels = currentData.map(item =>
        item.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
    );
    const values = currentData.map(item => item.value);

    dataChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: document.getElementById('data-type').options[
                    document.getElementById('data-type').selectedIndex
                ].text,
                data: values,
                borderColor: '#3498db',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false,
                    title: {
                        display: true,
                        text: getUnit(document.getElementById('data-type').value)
                    }
                },
                x: {
                    title: {
                        display: true,
                        text: 'Time'
                    }
                }
            }
        }
    });
}

// Update the data table
function updateTable() {
    const tableBody = document.getElementById('table-body');
    tableBody.innerHTML = '';

    currentData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.timestamp.toLocaleTimeString()}</td>
            <td>${item.value}</td>
            <td>${item.unit}</td>
        `;
        tableBody.appendChild(row);
    });
}

// Handle form submission
document.getElementById('data-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('data-type').value;
    const timeRange = document.getElementById('time-range').value;

    // Generate new data based on form selection
    currentData = generateSampleData(dataType, timeRange);

    // Update visualizations
    updateChart();
    updateTable();
});

// Initialize the dashboard
function initDashboard() {
    updateTimeDisplay();
    updateChart();
    updateTable();

    // Update time display every second
    setInterval(updateTimeDisplay, 1000);

    // Simulate real-time updates every 5 seconds
    setInterval(() => {
        // Add a new data point
        const now = new Date();
        const type = document.getElementById('data-type').value;
        let value;

        switch(type) {
            case 'temperature':
                value = 20 + Math.sin(Date.now() * 0.001) * 5 + (Math.random() * 2 - 1);
                break;
            case 'humidity':
                value = 50 + Math.sin(Date.now() * 0.0005) * 20 + (Math.random() * 5 - 2.5);
                break;
            case 'pressure':
                value = 1013 + Math.sin(Date.now() * 0.0002) * 5 + (Math.random() * 1 - 0.5);
                break;
            default:
                value = Math.random() * 100;
        }

        currentData.push({
            timestamp: now,
            value: parseFloat(value.toFixed(2)),
            unit: getUnit(type)
        });

        // Keep only the last 60 points (1 hour)
        if (currentData.length > 60) {
            currentData.shift();
        }

        updateChart();
        updateTable();
    }, 5000);
}

// Start the dashboard when the page loads
window.addEventListener('DOMContentLoaded', initDashboard);
```

