  "tid",
  "uid",
  "vid",
  "wid",
  "xid",
  "yid",
  "zid"
];

// Block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    // Check if URL matches any tracking pattern
    for (const pattern of trackingPatterns) {
      if (chrome.webRequest.matchUrl(pattern, details.url)) {
        console.log(`Blocked tracking script: ${details.url}`);
        return { cancel: true };
      }
    }

    // Check for tracking query parameters
    const url = new URL(details.url);
    for (const param of trackingQueryParams) {
      if (url.searchParams.has(param)) {
        console.log(`Blocked tracking parameter in URL: ${details.url}`);
        return { cancel: true };
      }
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Optional: Remove tracking parameters from URLs
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    const url = new URL(details.url);

    // Remove tracking query parameters
    let modified = false;
    for (const param of trackingQueryParams) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        modified = true;
      }
    }

    if (modified) {
      console.log(`Cleaned tracking parameters from URL: ${details.url}`);
      return { redirectUrl: url.toString() };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Store blocked requests count
let blockedCount = 0;

chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    blockedCount++;
    chrome.storage.local.set({ blockedCount });
    return { cancel: false };
  },
  { urls: trackingPatterns },
  ["blocking"]
);

// Initialize blocked count
chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({ blockedCount: 0 });
});
