```javascript
document.addEventListener('DOMContentLoaded', function() {
  // Load blocked count
  chrome.storage.local.get(['blockedCount'], function(result) {
    document.getElementById('blocked-count').textContent = result.blockedCount || 0;
  });

  // Toggle blocking functionality
  const toggle = document.getElementById('enable-blocking');
  chrome.storage.local.get(['blockingEnabled'], function(result) {
    toggle.checked = result.blockingEnabled !== false;
  });

  toggle.addEventListener('change', function() {
    chrome.storage.local.set({ blockingEnabled: toggle.checked });
    chrome.runtime.sendMessage({ action: 'toggleBlocking', enabled: toggle.checked });
  });
});
