// Block inline tracking scripts
const observer = new MutationObserver(function(mutations) {
  mutations.forEach(function(mutation) {
    mutation.addedNodes.forEach(function(node) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        // Check for script tags
        if (node.tagName === 'SCRIPT') {
          const src = node.src || node.getAttribute('src') || '';
          const innerHTML = node.innerHTML || '';

          // Check if this is a tracking script
          const isTracking = trackingScripts.some(script =>
            src.includes(script) || innerHTML.includes(script)
          );

          if (isTracking) {
            console.log("Blocked inline tracking script:", src || innerHTML);
            node.remove();
          }
        }

        // Check for iframes that might contain trackers
        if (node.tagName === 'IFRAME') {
          const src = node.src || node.getAttribute('src') || '';
          const isTracking = trackingDomains.some(pattern =>
            new RegExp(pattern.replace(/\*/g, '.*')).test(src)
          );

          if (isTracking) {
            console.log("Blocked tracking iframe:", src);
            node.remove();
          }
        }
      }
    });
  });
});

// Start observing the document with the configured parameters
observer.observe(document, {
  childList: true,
  subtree: true
});

// Clean up when the page is unloaded
window.addEventListener('beforeunload', function() {
  observer.disconnect();
});
