## Popup JavaScript (popup.js)

```javascript
document.addEventListener('DOMContentLoaded', function() {
  const statusElement = document.getElementById('status');
  const toggleBtn = document.getElementById('toggleBtn');
  const blockedCountElement = document.getElementById('blockedCount');
  const lastBlockedElement = document.getElementById('lastBlocked');

  // Load saved state
  chrome.storage.sync.get(['enabled', 'blockedCount', 'lastBlocked'], function(data) {
    if (data.enabled === false) {
      statusElement.textContent = "Protection Disabled";
      statusElement.className = "status inactive";
      toggleBtn.textContent = "Enable Protection";
    }

    if (data.blockedCount) {
      blockedCountElement.textContent = data.blockedCount;
    }

    if (data.lastBlocked) {
      lastBlockedElement.textContent = new URL(data.lastBlocked).hostname;
    }
  });

  // Toggle protection
  toggleBtn.addEventListener('click', function() {
    chrome.storage.sync.get('enabled', function(data) {
      const newState = data.enabled !== false; // Default is true

      chrome.storage.sync.set({ enabled: !newState }, function() {
        statusElement.textContent = newState ? "Protection Disabled" : "Protection Active";
        statusElement.className = newState ? "status inactive" : "status active";
        toggleBtn.textContent = newState ? "Enable Protection" : "Disable Protection";

        // Reload the active tab to apply changes
        chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {
          if (tabs[0]) {
            chrome.tabs.reload(tabs[0].id);
          }
        });
      });
    });
  });

  // Update badge count
  chrome.runtime.onMessage.addListener(function(request, sender, sendResponse) {
    if (request.action === "updateBadge") {
      chrome.storage.sync.get('blockedCount', function(data) {
        const newCount = (data.blockedCount || 0) + (request.count || 1);
        chrome.storage.sync.set({ blockedCount: newCount }, function() {
          blockedCountElement.textContent = newCount;
        });
      });

      if (request.url) {
        chrome.storage.sync.set({ lastBlocked: request.url }, function() {
          lastBlockedElement.textContent = new URL(request.url).hostname;
        });
      }
    }
  });
});
