];

// Block tracking requests
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    // Check if the request URL matches any tracking pattern
    for (const pattern of trackingScripts) {
      if (details.url.match(pattern)) {
        console.log(`Blocked tracking request: ${details.url}`);
        return { cancel: true };
      }
    }

    // Check if the request domain is in our tracking domains list
    try {
      const url = new URL(details.url);
      if (trackingDomains.some(domain => url.hostname.includes(domain))) {
        console.log(`Blocked tracking request: ${details.url}`);
        return { cancel: true };
