document.addEventListener('DOMContentLoaded', function() {
  const statusElement = document.getElementById('status');
  const toggleBtn = document.getElementById('toggleBtn');
  const settingsBtn = document.getElementById('settingsBtn');
  const blockedCountElement = document.getElementById('blockedCount');
  const scriptsRemovedElement = document.getElementById('scriptsRemoved');

  // Load extension state
  chrome.storage.sync.get(['extensionEnabled', 'blockedCount', 'scriptsRemoved'], function(data) {
    const isEnabled = data.extensionEnabled !== false; // default to true
    updateUI(isEnabled);

    // Update stats
    blockedCountElement.textContent = data.blockedCount || 0;
    scriptsRemovedElement.textContent = data.scriptsRemoved || 0;
  });

  // Toggle extension state
  toggleBtn.addEventListener('click', function() {
    chrome.storage.sync.get('extensionEnabled', function(data) {
      const newState = !(data.extensionEnabled !== false);
      chrome.storage.sync.set({ extensionEnabled: newState }, function() {
        updateUI(newState);
      });
    });
  });

  // Open settings
  settingsBtn.addEventListener('click', function() {
    // This would open a settings page in a new tab
    chrome.tabs.create({ url: 'settings.html' });
