// List of known tracking domains and patterns
const trackingDomains = [
  "*.google-analytics.com",
  "*.googletagmanager.com",
  "*.facebook.com",
  "*.facebook.net",
  "*.doubleclick.net",
  "*.adobe.com",
  "*.hotjar.com",
  "*.newrelic.com",
  "*.optimizely.com",
  "*.quantserve.com",
  "*.scorecardresearch.com",
  "*.tapad.com",
  "*.rubiconproject.com",
  "*.amazon-adsystem.com",
  "*.bidswitch.net",
  "*.criteo.com",
  "*.taboola.com",
  "*.outbrain.com",
  "*.mathtag.com",
  "*.media.net",
  "*.pubmatic.com",
  "*.openx.net",
  "*.yieldmo.com",
  "*.adform.net",
  "*.adroll.com",
  "*.bidswitch.net",
  "*.casalemedia.com",
  "*.conversantmedia.com",
  "*.flashtalking.com",
  "*.inskinad.com",
  "*.liverail.com",
  "*.mookie1.com",
  "*.nexage.com",
  "*.pulse360.com",
  "*.sovrn.com",
  "*.triplelift.com",
  "*.turn.com",
  "*.yahoo.com",
  "*.yimg.com"
];

// List of known tracking script patterns
const trackingPatterns = [
  "*://*/*analytics.js",
  "*://*/*ga.js",
  "*://*/*gtm.js",
  "*://*/*pixel*",
  "*://*/*tracker*",
  "*://*/*beacon*",
  "*://*/*collect*",
  "*://*/*event*",
  "*://*/*log*",
  "*://*/*monitor*",
  "*://*/*track*",
  "*://*/*analytics*",
  "*://*/*adserver*",
  "*://*/*ads*",
  "*://*/*ad*",
  "*://*/*tracking*",
  "*://*/*monitoring*",
  "*://*/*stats*",
  "*://*/*statistics*",
  "*://*/*metrics*",
  "*://*/*metric*"
];

// Initialize storage with default settings
chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.sync.set({
    blockTracking: true,
    blockedCount: 0
  });
});

// Web request listener to block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    // Check if blocking is enabled
    chrome.storage.sync.get(['blockTracking'], (result) => {
      if (result.blockTracking) {
        // Check if URL matches any tracking pattern
        const url = details.url.toLowerCase();
        const domain = new URL(url).hostname;

        if (trackingDomains.some(pattern => matchesPattern(domain, pattern)) ||
            trackingPatterns.some(pattern => matchesPattern(url, pattern))) {

          // Increment blocked count
          chrome.storage.sync.get(['blockedCount'], (countResult) => {
            chrome.storage.sync.set({
              blockedCount: (countResult.blockedCount || 0) + 1
            });
          });

          // Block the request
          return { cancel: true };
        }
      }
    });

    // Allow the request if not blocked
    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Helper function to match patterns
function matchesPattern(url, pattern) {
  // Convert pattern to regex
  const regexPattern = pattern
    .replace(/\*/g, '.*')
    .replace(/\./g, '\\.')
    .replace(/\?/g, '\\?')
    .replace(/\+/g, '\\+');

  const regex = new RegExp(`^${regexPattern}$`, 'i');
  return regex.test(url);
}
