  if (result.whitelistedDomains) {
    whitelistedDomains = result.whitelistedDomains;
  }
});

// Web request listener to block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    // Check if the request URL matches any tracking pattern
    const isTracking = trackingPatterns.some(pattern => {
      return new RegExp(pattern.replace(/\*/g, '.*')).test(details.url);
    });

    // Check if the domain is whitelisted
    const domain = new URL(details.url).hostname;
    const isWhitelisted = whitelistedDomains.includes(domain);

    if (isTracking && !isWhitelisted) {
      console.log(`Blocked tracking request: ${details.url}`);
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Message listener for popup communication
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === "getBlockedCount") {
    // In a real implementation, you would track blocked requests
    sendResponse({ count: 0 });
  } else if (request.action === "whitelistDomain") {
    const domain = request.domain;
    if (!whitelistedDomains.includes(domain)) {
      whitelistedDomains.push(domain);
      chrome.storage.sync.set({ whitelistedDomains });
    }
    sendResponse({ success: true });
  } else if (request.action === "getWhitelistedDomains") {
    sendResponse({ domains: whitelistedDomains });
  }
});
