// Track blocked elements and scripts
let blockedCount = 0;

// MutationObserver to watch for dynamically loaded tracking scripts
const observer = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    mutation.addedNodes.forEach((node) => {
      if (node.nodeType === Node.ELEMENT_NODE) {
        // Check for tracking scripts in added nodes
        if (node.tagName === 'SCRIPT' || node.tagName === 'IFRAME') {
          const src = node.src || node.getAttribute('data-src');
          if (src && isTrackingUrl(src)) {
            node.remove();
            blockedCount++;
            updateBlockedCount();
          }
        }

        // Check for tracking elements
        if (node.tagName === 'IMG' || node.tagName === 'PIXEL') {
          const src = node.src || node.getAttribute('data-src');
          if (src && isTrackingUrl(src)) {
            node.remove();
            blockedCount++;
            updateBlockedCount();
          }
        }
      }
    });
  });
});

// Start observing the document with the configured parameters
