// Block canvas fingerprinting
const originalGetContext = HTMLCanvasElement.prototype.getContext;
HTMLCanvasElement.prototype.getContext = function(type, options) {
  if (type === '2d') {
    const context = originalGetContext.call(this, type, options);

    // Override toString to prevent fingerprinting
    context.toString = function() {
      return '[object CanvasRenderingContext2D]';
    };

    // Add some noise to canvas data
    const originalGetImageData = context.getImageData;
    context.getImageData = function() {
      const data = originalGetImageData.apply(this, arguments);

      // Add some random noise to prevent fingerprinting
      for (let i = 0; i < data.data.length; i += 4) {
        data.data[i] += Math.floor(Math.random() * 5) - 2; // Red
        data.data[i + 1] += Math.floor(Math.random() * 5) - 2; // Green
        data.data[i + 2] += Math.floor(Math.random() * 5) - 2; // Blue
      }

      return data;
    };

    return context;
  }

  return originalGetContext.call(this, type, options);
};
