document.addEventListener('DOMContentLoaded', function() {
  const statusElement = document.getElementById('status');
  const blockedCountElement = document.getElementById('blocked-count');
  const toggleBtn = document.getElementById('toggle-btn');
  const optionsBtn = document.getElementById('options-btn');

  // Load saved state
  chrome.storage.sync.get(['enabled', 'blockedCount'], function(data) {
    const isEnabled = data.enabled !== false; // default to true
    const blockedCount = data.blockedCount || 0;

    statusElement.textContent = isEnabled ? 'Active' : 'Inactive';
    statusElement.className = isEnabled ? 'active' : 'inactive';
    toggleBtn.textContent = isEnabled ? 'Disable Protection' : 'Enable Protection';
    blockedCountElement.textContent = blockedCount;
  });

  // Toggle protection
  toggleBtn.addEventListener('click', function() {
    chrome.storage.sync.get('enabled', function(data) {
      const newState = data.enabled !== false ? false : true;

      chrome.storage.sync.set({ enabled: newState }, function() {
        statusElement.textContent = newState ? 'Active' : 'Inactive';
        statusElement.className = newState ? 'active' : 'inactive';
        toggleBtn.textContent = newState ? 'Disable Protection' : 'Enable Protection';

        // Reload the current tab to apply changes
        chrome.tabs.query({ active: true, currentWindow: true }, function(tabs) {
          if (tabs[0]) {
            chrome.tabs.reload(tabs[0].id);
          }
        });
      });
    });
  });

  // Options button
  optionsBtn.addEventListener('click', function() {
    chrome.runtime.openOptionsPage();
  });
});
