// Web request listener to block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    // Check if the request URL matches any tracking pattern
    for (const pattern of trackingPatterns) {
      if (matchesPattern(details.url, pattern)) {
        blockedCount++;
        return { cancel: true };
      }
    }
    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Helper function to match URL patterns
function matchesPattern(url, pattern) {
  // Simple pattern matching - in production, use a more robust solution
  const regexPattern = pattern
    .replace(/\*/g, '.*')
    .replace(/\./g, '\\.')
    .replace(/\?/g, '\\?');
  const regex = new RegExp(`^${regexPattern}$`, 'i');
  return regex.test(url);
}

// Update badge with blocked count
