    });
  }

  // Initialize the popup
  updateBlockedCount();

  // Listen for changes to the blocked count
  chrome.storage.onChanged.addListener(function(changes, namespace) {
    if (changes.blockedCount) {
      updateBlockedCount();
    }
  });

  // Toggle blocking functionality
  toggleBlocking.addEventListener('change', function() {
    chrome.storage.local.set({ blockingEnabled: this.checked });
  });

  // Load the current blocking state
  chrome.storage.local.get(['blockingEnabled'], function(result) {
    toggleBlocking.checked = result.blockingEnabled !== false;
  });

  // Clear statistics
  clearStatsButton.addEventListener('click', function() {
    chrome.storage.local.set({ blockedCount: 0 }, function() {
      updateBlockedCount();
    });
  });
});
