    blockedCountElement.textContent = data.blockedCount || 0;
    pagesProtectedElement.textContent = data.pagesProtected || 0;
    extensionToggle.checked = data.enabled !== false;
  });

  // Toggle extension on/off
  extensionToggle.addEventListener('change', function() {
    chrome.storage.sync.set({ enabled: this.checked });
    chrome.runtime.sendMessage({ action: "toggle", enabled: this.checked });
  });

  // Reset statistics
  resetStatsButton.addEventListener('click', function() {
    chrome.storage.sync.set({ blockedCount: 0, pagesProtected: 0 });
    blockedCountElement.textContent = '0';
    pagesProtectedElement.textContent = '0';
