                <button id="reset-view">Reset View</button>
            </div>
        </div>

        <div id="heatmap-container">
            <div class="loading">Loading data...</div>
            <canvas id="heatmap"></canvas>
            <div class="tooltip" id="tooltip"></div>
        </div>

        <div class="legend" id="legend"></div>

        <div class="status" id="status">Last updated: Never</div>
    </div>

    <script>
        // Main application class
        class StockHeatmap {
            constructor() {
                this.canvas = document.getElementById('heatmap');
                this.ctx = this.canvas.getContext('2d');
                this.tooltip = document.getElementById('tooltip');
                this.legendContainer = document.getElementById('legend');
                this.statusElement = document.getElementById('status');
                this.loadingElement = document.querySelector('.loading');

                this.timeframeSelect = document.getElementById('timeframe');
                this.updateIntervalSelect = document.getElementById('update-interval');
                this.resetViewButton = document.getElementById('reset-view');

                this.stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
                this.timePoints = [];
                this.priceData = {};
                this.colorScale = this.createColorScale();

                this.zoomLevel = 1;
                this.panOffset = { x: 0, y: 0 };
                this.isPanning = false;
                this.lastMousePos = { x: 0, y: 0 };

                this.updateIntervalId = null;
                this.lastUpdateTime = null;

                this.init();
            }

            init() {
                this.setupCanvas();
                this.setupEventListeners();
                this.generateMockData();
                this.renderLegend();
                this.startAutoUpdates();
            }

            setupCanvas() {
                const container = document.getElementById('heatmap-container');
                this.canvas.width = container.clientWidth;
                this.canvas.height = container.clientHeight;

                // Initial render
                this.renderHeatmap();
            }

            setupEventListeners() {
                // Mouse events for zoom/pan
                this.canvas.addEventListener('mousedown', (e) => this.handleMouseDown(e));
                this.canvas.addEventListener('mousemove', (e) => this.handleMouseMove(e));
                this.canvas.addEventListener('mouseup', () => this.handleMouseUp());
                this.canvas.addEventListener('mouseout', () => this.handleMouseUp());
                this.canvas.addEventListener('wheel', (e) => this.handleMouseWheel(e));

                // Control events
                this.timeframeSelect.addEventListener('change', () => this.handleTimeframeChange());
                this.updateIntervalSelect.addEventListener('change', () => this.handleUpdateIntervalChange());
                this.resetViewButton.addEventListener('click', () => this.resetView());

                // Window resize
                window.addEventListener('resize', () => this.handleResize());
            }

            handleMouseDown(e) {
                this.isPanning = true;
                this.lastMousePos = { x: e.clientX, y: e.clientY };
                this.canvas.style.cursor = 'grabbing';
            }

            handleMouseMove(e) {
                if (this.isPanning) {
                    const dx = e.clientX - this.lastMousePos.x;
                    const dy = e.clientY - this.lastMousePos.y;

                    this.panOffset.x += dx;
                    this.panOffset.y += dy;

                    this.lastMousePos = { x: e.clientX, y: e.clientY };
                    this.renderHeatmap();
                } else {
                    this.showTooltip(e);
                }
            }

            handleMouseUp() {
                this.isPanning = false;
                this.canvas.style.cursor = 'grab';
            }

            handleMouseWheel(e) {
                e.preventDefault();

                const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
                const mouseX = e.clientX - this.canvas.getBoundingClientRect().left;
                const mouseY = e.clientY - this.canvas.getBoundingClientRect().top;

                // Calculate new zoom level
                const newZoom = Math.max(0.5, Math.min(3, this.zoomLevel * zoomFactor));

                // Adjust pan offset to zoom toward mouse position
                this.panOffset.x = mouseX - (mouseX - this.panOffset.x) * (newZoom / this.zoomLevel);
                this.panOffset.y = mouseY - (mouseY - this.panOffset.y) * (newZoom / this.zoomLevel);

                this.zoomLevel = newZoom;
                this.renderHeatmap();
            }

            showTooltip(e) {
                const rect = this.canvas.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;

                // Calculate cell coordinates
                const cellWidth = (this.canvas.width * this.zoomLevel) / this.timePoints.length;
                const cellHeight = (this.canvas.height * this.zoomLevel) / this.stocks.length;

                const col = Math.floor((x - this.panOffset.x) / cellWidth);
                const row = Math.floor((y - this.panOffset.y) / cellHeight);

                if (col >= 0 && col < this.timePoints.length && row >= 0 && row < this.stocks.length) {
                    const stock = this.stocks[row];
                    const time = this.timePoints[col];
                    const price = this.priceData[stock][col];

                    this.tooltip.style.display = 'block';
                    this.tooltip.style.left = `${e.clientX + 10}px`;
                    this.tooltip.style.top = `${e.clientY + 10}px`;

                    const formattedTime = new Date(time).toLocaleString();
                    this.tooltip.innerHTML = `
                        <strong>${stock}</strong><br>
                        Time: ${formattedTime}<br>
                        Price: $${price.toFixed(2)}
                    `;
                } else {
                    this.tooltip.style.display = 'none';
                }
            }

            handleTimeframeChange() {
                this.generateMockData();
                this.resetView();
                this.renderHeatmap();
            }

            handleUpdateIntervalChange() {
                this.startAutoUpdates();
            }

            resetView() {
                this.zoomLevel = 1;
                this.panOffset = { x: 0, y: 0 };
                this.renderHeatmap();
            }

            handleResize() {
                const container = document.getElementById('heatmap-container');
                this.canvas.width = container.clientWidth;
                this.canvas.height = container.clientHeight;
                this.renderHeatmap();
            }

            startAutoUpdates() {
                if (this.updateIntervalId) {
                    clearInterval(this.updateIntervalId);
                }

                const interval = parseInt(this.updateIntervalSelect.value) * 1000;
                this.updateIntervalId = setInterval(() => this.updateData(), interval);

                // Initial update
                this.updateData();
            }

            updateData() {
                this.loadingElement.style.display = 'block';
                this.statusElement.textContent = 'Updating data...';

                // Simulate API call delay
                setTimeout(() => {
                    this.generateMockData(true); // Update with new data
                    this.renderHeatmap();
                    this.loadingElement.style.display = 'none';

                    const now = new Date();
                    this.statusElement.textContent = `Last updated: ${now.toLocaleTimeString()}`;
                    this.lastUpdateTime = now;
                }, 500);
            }

            generateMockData(update = false) {
                const timeframe = this.timeframeSelect.value;
                const now = new Date();

                // Determine time points based on timeframe
                let interval, count;
                switch (timeframe) {
                    case '1D':
                        interval = 15 * 60 * 1000; // 15 minutes
                        count = 96; // 24 hours / 15 minutes
                        break;
                    case '1W':
                        interval = 60 * 60 * 1000; // 1 hour
                        count = 168; // 7 days * 24 hours
                        break;
                    case '1M':
                        interval = 4 * 60 * 60 * 1000; // 4 hours
                        count = 180; // ~30 days
                        break;
                    case '3M':
                        interval = 12 * 60 * 60 * 1000; // 12 hours
                        count = 90; // ~90 days
                        break;
                    case '1Y':
                        interval = 24 * 60 * 60 * 1000; // 1 day
                        count = 252; // ~252 trading days
                        break;
                    default:
                        interval = 60 * 60 * 1000;
                        count = 24;
                }

                // Generate time points
                this.timePoints = [];
                for (let i = 0; i < count; i++) {
                    const time = new Date(now.getTime() - (count - i - 1) * interval);
                    this.timePoints.push(time);
                }

                // Generate price data for each stock
                if (!update || Object.keys(this.priceData).length === 0) {
                    this.priceData = {};
                    this.stocks.forEach(stock => {
                        this.priceData[stock] = [];
                        let basePrice = 100 + Math.random() * 200; // Random base price between 100-300

                        for (let i = 0; i < count; i++) {
                            // Generate a random price change
                            const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
                            basePrice += change;
                            this.priceData[stock].push(Math.max(1, basePrice)); // Ensure price doesn't go below 1
                        }
                    });
                } else {
                    // Update existing data with new values
                    this.stocks.forEach(stock => {
                        const lastPrice = this.priceData[stock][this.priceData[stock].length - 1];
                        const change = (Math.random() - 0.5) * 2; // Smaller change for updates
                        const newPrice = Math.max(1, lastPrice + change);
                        this.priceData[stock].push(newPrice);

                        // Remove oldest data point if we've exceeded the count
                        if (this.priceData[stock].length > count) {
                            this.priceData[stock].shift();
                        }
                    });

                    // Remove oldest time point if needed
                    if (this.timePoints.length > count) {
                        this.timePoints.shift();
                    }
                }
            }

            createColorScale() {
                // Create a color scale from red (low) to green (high)
                const colors = [
                    { stop: 0, color: '#ff0000' },    // Red
                    { stop: 0.25, color: '#ff7f00' },  // Orange
                    { stop: 0.5, color: '#ffff00' },   // Yellow
                    { stop: 0.75, color: '#7fff00' },  // Light green
                    { stop: 1, color: '#00ff00' }      // Green
                ];

                return (value, min, max) => {
                    if (min === max) return colors[0].color;

                    const normalized = (value - min) / (max - min);

                    for (let i = 0; i < colors.length - 1; i++) {
                        if (normalized <= colors[i + 1].stop) {
                            const ratio = (normalized - colors[i].stop) / (colors[i + 1].stop - colors[i].stop);
                            return this.interpolateColor(colors[i].color, colors[i + 1].color, ratio);
                        }
                    }

                    return colors[colors.length - 1].color;
                };
            }

            interpolateColor(color1, color2, ratio) {
                const r1 = parseInt(color1.substring(1, 3), 16);
                const g1 = parseInt(color1.substring(3, 5), 16);
                const b1 = parseInt(color1.substring(5, 7), 16);

                const r2 = parseInt(color2.substring(1, 3), 16);
                const g2 = parseInt(color2.substring(3, 5), 16);
                const b2 = parseInt(color2.substring(5, 7), 16);

                const r = Math.round(r1 + (r2 - r1) * ratio);
                const g = Math.round(g1 + (g2 - g1) * ratio);
                const b = Math.round(b1 + (b2 - b1) * ratio);

                return `rgb(${r}, ${g}, ${b})`;
            }

            renderLegend() {
                this.legendContainer.innerHTML = '';

                // Create legend items
                const legendItems = [
                    { label: 'Low', color: '#ff0000' },
                    { label: 'Medium', color: '#ffff00' },
                    { label: 'High', color: '#00ff00' }
                ];

                legendItems.forEach(item => {
                    const legendItem = document.createElement('div');
                    legendItem.className = 'legend-item';

                    const colorBox = document.createElement('div');
                    colorBox.className = 'legend-color';
                    colorBox.style.backgroundColor = item.color;

                    const label = document.createElement('span');
                    label.textContent = item.label;

                    legendItem.appendChild(colorBox);
                    legendItem.appendChild(label);
                    this.legendContainer.appendChild(legendItem);
                });
            }

            renderHeatmap() {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                if (this.timePoints.length === 0 || this.stocks.length === 0) {
                    return;
                }

                // Calculate cell dimensions
                const cellWidth = (this.canvas.width * this.zoomLevel) / this.timePoints.length;
                const cellHeight = (this.canvas.height * this.zoomLevel) / this.stocks.length;

                // Find min and max prices for color scaling
                let minPrice = Infinity;
                let maxPrice = -Infinity;

                this.stocks.forEach(stock => {
                    this.priceData[stock].forEach(price => {
                        if (price < minPrice) minPrice = price;
                        if (price > maxPrice) maxPrice = price;
                    });
                });

                // Draw heatmap cells
                for (let row = 0; row < this.stocks.length; row++) {
                    const stock = this.stocks[row];

                    for (let col = 0; col < this.timePoints.length; col++) {
                        const price = this.priceData[stock][col];
                        const color = this.colorScale(price, minPrice, maxPrice);

                        // Calculate position with zoom and pan
                        const x = (col * cellWidth) + this.panOffset.x;
                        const y = (row * cellHeight) + this.panOffset.y;

                        // Only draw if cell is visible
                        if (x + cellWidth > 0 && x < this.canvas.width &&
                            y + cellHeight > 0 && y < this.canvas.height) {
                            this.ctx.fillStyle = color;
                            this.ctx.fillRect(x, y, cellWidth, cellHeight);

                            // Draw cell border
                            this.ctx.strokeStyle = '#ddd';
                            this.ctx.strokeRect(x, y, cellWidth, cellHeight);
                        }
                    }
                }

                // Draw axes
                this.drawAxes(cellWidth, cellHeight);
            }

            drawAxes(cellWidth, cellHeight) {
                // Draw vertical lines (time points)
                this.ctx.strokeStyle = '#34495e';
                this.ctx.lineWidth = 1;

                for (let col = 0; col <= this.timePoints.length; col++) {
                    const x = (col * cellWidth) + this.panOffset.x;

                    if (x >= 0 && x <= this.canvas.width) {
                        this.ctx.beginPath();
                        this.ctx.moveTo(x, 0);
                        this.ctx.lineTo(x, this.canvas.height);
                        this.ctx.stroke();

                        // Add labels for some time points
                        if (col % Math.max(1, Math.floor(this.timePoints.length / 10)) === 0) {
                            const time = this.timePoints[col] || this.timePoints[this.timePoints.length - 1];
                            const label = time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

                            this.ctx.fillStyle = '#34495e';
                            this.ctx.font = '12px Arial';
                            this.ctx.textAlign = 'center';
                            this.ctx.fillText(label, x, this.canvas.height - 5);
                        }
                    }
                }

                // Draw horizontal lines (stocks)
                for (let row = 0; row <= this.stocks.length; row++) {
                    const y = (row * cellHeight) + this.panOffset.y;

                    if (y >= 0 && y <= this.canvas.height) {
                        this.ctx.beginPath();
                        this.ctx.moveTo(0, y);
                        this.ctx.lineTo(this.canvas.width, y);
                        this.ctx.stroke();

                        // Add labels for stocks
                        if (row < this.stocks.length) {
                            const stock = this.stocks[row];
                            this.ctx.fillStyle = '#34495e';
                            this.ctx.font = '12px Arial';
                            this.ctx.textAlign = 'right';
                            this.ctx.fillText(stock, 5, y + cellHeight / 2 + 4);
                        }
                    }
                }
            }
        }

        // Initialize the application when the page loads
        document.addEventListener('DOMContentLoaded', () => {
            new StockHeatmap();
        });
    </script>
</body>
</html>
```

