                    <option value="GOOGL" selected>GOOGL</option>
                    <option value="AMZN" selected>AMZN</option>
                    <option value="TSLA" selected>TSLA</option>
                    <option value="META" selected>META</option>
                    <option value="NVDA" selected>NVDA</option>
                    <option value="JPM" selected>JPM</option>
                    <option value="V" selected>V</option>
                    <option value="WMT" selected>WMT</option>
                </select>
            </div>

            <div class="control-group">
                <label for="color-scale">Color Scale:</label>
                <select id="color-scale">
                    <option value="interpolateRdYlGn">Red-Yellow-Green</option>
                    <option value="interpolateViridis" selected>Viridis</option>
                    <option value="interpolatePlasma">Plasma</option>
                    <option value="interpolateCool">Cool</option>
                    <option value="interpolateRainbow">Rainbow</option>
                </select>
            </div>

            <div class="control-group">
                <label for="update-interval">Update Interval:</label>
                <select id="update-interval">
                    <option value="5000">5 seconds</option>
                    <option value="10000" selected>10 seconds</option>
                    <option value="30000">30 seconds</option>
                    <option value="60000">1 minute</option>
                </select>
            </div>

            <div class="control-group">
                <button id="update-btn">Update Now</button>
            </div>
        </div>

        <div id="heatmap-container">
            <button class="reset-zoom" id="reset-zoom">Reset Zoom</button>
            <div class="tooltip" id="tooltip"></div>
        </div>
    </div>

    <script>
        // Configuration
        const config = {
            margin: { top: 50, right: 30, bottom: 80, left: 80 },
            width: 1200,
            height: 600
        };

        // Initialize variables
        let svg, xScale, yScale, colorScale, zoom;
        let data = [];
        let updateIntervalId = null;
        let selectedStocks = Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value);

        // Initialize the visualization
        function init() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Add zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Add tooltip
            const tooltip = d3.select("#tooltip");

            // Set up initial data and render
            generateMockData();
            renderHeatmap();

            // Set up event listeners
            document.getElementById('timeframe').addEventListener('change', handleTimeframeChange);
            document.getElementById('stock-select').addEventListener('change', handleStockSelectionChange);
            document.getElementById('color-scale').addEventListener('change', handleColorScaleChange);
            document.getElementById('update-interval').addEventListener('change', handleUpdateIntervalChange);
            document.getElementById('update-btn').addEventListener('click', generateMockData);
            document.getElementById('reset-zoom').addEventListener('click', resetZoom);

            // Set initial update interval
            handleUpdateIntervalChange();
        }

        // Generate mock data (in a real app, this would fetch from an API)
        function generateMockData() {
            const timeframe = document.getElementById('timeframe').value;
            const now = new Date();

            // Determine time points based on selected timeframe
            let timePoints = [];
            let intervalMinutes;

            switch(timeframe) {
                case '1D':
                    intervalMinutes = 5;
                    for (let i = 0; i < 288; i++) { // 24 hours * 60 minutes / 5 minutes
                        timePoints.push(new Date(now - (i * intervalMinutes * 60000)));
                    }
                    break;
                case '1W':
                    intervalMinutes = 30;
                    for (let i = 0; i < 336; i++) { // 7 days * 24 hours * 60 minutes / 30 minutes
                        timePoints.push(new Date(now - (i * intervalMinutes * 60000)));
                    }
                    break;
                case '1M':
                    intervalMinutes = 60 * 24; // 1 day
                    for (let i = 0; i < 30; i++) {
                        timePoints.push(new Date(now - (i * intervalMinutes * 60000)));
                    }
                    break;
                case '3M':
                    intervalMinutes = 60 * 24 * 3; // 3 days
                    for (let i = 0; i < 90; i++) {
                        timePoints.push(new Date(now - (i * intervalMinutes * 60000)));
                    }
                    break;
                case '1Y':
                    intervalMinutes = 60 * 24 * 7; // 1 week
                    for (let i = 0; i < 52; i++) {
                        timePoints.push(new Date(now - (i * intervalMinutes * 60000)));
                    }
                    break;
            }

            // Generate mock data for selected stocks
            data = selectedStocks.map(stock => {
                return {
                    stock: stock,
                    prices: timePoints.map(time => {
                        // Generate a random price change between -5% and +5%
                        const basePrice = 100 + (Math.random() * 200); // Base price between 100-300
                        const changePercent = (Math.random() * 10) - 5; // -5% to +5%
                        const price = basePrice * (1 + changePercent / 100);

                        return {
                            time: time,
                            price: parseFloat(price.toFixed(2)),
                            change: changePercent
                        };
                    })
                };
            });

            // Update the visualization
            renderHeatmap();
        }

        // Render the heatmap
        function renderHeatmap() {
            if (data.length === 0) return;

            // Clear previous content
            svg.selectAll("*").remove();

            // Create scales
            const allTimes = data[0].prices.map(d => d.time);
            const allStocks = data.map(d => d.stock);

            xScale = d3.scaleBand()
                .domain(allTimes)
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(allStocks)
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.1);

            // Get all price changes for color scale domain
            const allChanges = data.flatMap(stock =>
                stock.prices.map(price => price.change)
            );

            const colorScaleType = document.getElementById('color-scale').value;
            colorScale = d3.scaleSequential(d3[colorScaleType])
                .domain([d3.min(allChanges), d3.max(allChanges)]);

            // Create heatmap cells
            const cells = svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("g")
                .attr("class", "cell-group")
                .selectAll(".cell")
                .data(d => d.prices.map(price => ({
                    stock: d.stock,
                    time: price.time,
                    price: price.price,
                    change: price.change
                })))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    const tooltip = d3.select("#tooltip");
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Time: ${d.time.toLocaleString()}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Change: ${d.change.toFixed(2)}%
                        `)
                        .style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("visibility", "hidden");
                });

            // Add axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d3.timeFormat("%b %d %H:%M"))
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(allTimes.length / 10) === 0));

            const yAxis = d3.axisLeft(yScale);

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-65)");

            svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("y", 20)
                .attr("x", -config.height / 2)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add color legend
            const legendWidth = 200;
            const legendHeight = 20;
            const legendX = config.width - config.margin.right - legendWidth - 10;
            const legendY = config.margin.top;

            const legendScale = d3.scaleLinear()
                .domain(colorScale.domain())
                .range([legendX, legendX + legendWidth]);

            const legendAxis = d3.axisBottom(legendScale)
                .ticks(5)
                .tickFormat(d => `${d.toFixed(1)}%`);

            const legend = svg.append("g")
                .attr("class", "legend")
                .attr("transform", `translate(0, ${legendY})`);

            legend.selectAll("rect")
                .data(d3.range(legendWidth).map(i => i / legendWidth))
                .enter()
                .append("rect")
                .attr("x", d => legendX + d * legendWidth)
                .attr("y", 0)
                .attr("width", 1)
                .attr("height", legendHeight)
                .attr("fill", d => colorScale(d * (colorScale.domain()[1] - colorScale.domain()[0]) + colorScale.domain()[0]));

            legend.append("g")
                .attr("transform", `translate(0, ${legendHeight})`)
                .call(legendAxis);

            legend.append("text")
                .attr("class", "axis-label")
                .attr("x", legendX + legendWidth / 2)
                .attr("y", -5)
                .style("text-anchor", "middle")
                .text("Price Change (%)");
        }

        // Handle zoom events
        function zoomed(event) {
            const transform = event.transform;

            svg.selectAll(".cell-group")
                .attr("transform", transform);

            svg.select(".x-axis").call(
                d3.axisBottom(xScale).scale(transform.rescaleX(xScale))
            );

            svg.select(".y-axis").call(
                d3.axisLeft(yScale).scale(transform.rescaleY(yScale))
            );
        }

        // Reset zoom
        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Event handlers
        function handleTimeframeChange() {
            generateMockData();
        }

        function handleStockSelectionChange() {
            selectedStocks = Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value);
            generateMockData();
        }

        function handleColorScaleChange() {
            renderHeatmap();
        }

        function handleUpdateIntervalChange() {
            const interval = parseInt(document.getElementById('update-interval').value);

            // Clear any existing interval
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }

            // Set new interval
            updateIntervalId = setInterval(generateMockData, interval);
        }

        // Initialize the visualization when the page loads
        window.addEventListener('load', init);
    </script>
</body>
</html>
```

## Features

1. **Interactive Heatmap**:
   - Displays stock price changes as a color-coded heatmap
   - Each cell represents a stock's price change at a specific time point

2. **Real-Time Updates**:
   - Configurable update intervals (5s to 1 minute)
   - Manual update button for immediate refresh

3. **Zoom/Pan Functionality**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan
   - Reset zoom button

4. **Customization Options**:
   - Select different timeframes (1 day to 1 year)
   - Choose which stocks to display
   - Select different color scales
   - Adjust update frequency

5. **Tooltip**:
   - Hover over cells to see detailed information
   - Shows stock symbol, time, price, and change percentage

6. **Responsive Design**:
   - Works on different screen sizes
   - Clean, modern interface

## Implementation Notes

- This uses D3.js for data visualization
- The data generation is mock for demonstration - in a real application, you would replace this with API calls to a financial data service
- The visualization includes proper axes, labels, and a color legend
- All interactions are smooth and responsive

To use this in a production environment, you would need to:
1. Replace the mock data generation with real API calls
2. Add error handling for API failures
3. Implement proper authentication if needed
4. Optimize for performance with large datasets

# Interactive Stock Price Heatmap with Real-Time Updates

Here's a complete implementation of an interactive stock price heatmap using HTML, CSS, and JavaScript with real-time updates and zoom/pan functionality. This solution uses D3.js for data visualization and includes mock data generation for demonstration.

```html
