<body>
    <div class="container">
        <h1>Interactive Stock Price Heatmap</h1>

        <div class="controls">
            <div class="control-group">
                <label for="timeframe">Timeframe:</label>
                <select id="timeframe">
                    <option value="1d">1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m" selected>1 Month</option>
                    <option value="3m">3 Months</option>
                    <option value="1y">1 Year</option>
                </select>
            </div>

            <div class="control-group">
                <label for="stock-count">Stocks to Display:</label>
                <input type="number" id="stock-count" min="1" max="100" value="20">
            </div>

            <div class="control-group">
                <button id="update-btn">Update Data</button>
            </div>
        </div>

        <div id="heatmap-container"></div>
        <div class="tooltip" id="tooltip"></div>

        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 550,
            margin: { top: 30, right: 30, bottom: 80, left: 80 },
            cellPadding: 0.5,
            updateInterval: 5000, // 5 seconds
            maxStocks: 100
        };

        // Mock data generation
        function generateMockData(stockCount, timeframe) {
            const stocks = [];
            const stockNames = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'PYPL', 'ADBE', 'INTC',
                              'CSCO', 'ORCL', 'IBM', 'AMD', 'QCOM', 'NFLX', 'DIS', 'V', 'JPM', 'WMT'];

            // Select random stocks if we have fewer than requested
            const selectedStocks = stockNames.slice(0, Math.min(stockCount, stockNames.length));
            if (stockCount > stockNames.length) {
                for (let i = stockNames.length; i < stockCount; i++) {
                    selectedStocks.push(`STK${i+1}`);
                }
            }

            // Determine time points based on timeframe
            const now = new Date();
            let timePoints = [];
            let timeFormat = d3.timeFormat("%H:%M");

            switch(timeframe) {
                case '1d':
                    // 1 minute intervals for 1 day
                    for (let i = 0; i < 24 * 60; i += 5) {
                        timePoints.push(new Date(now - i * 60 * 1000));
                    }
                    timePoints.reverse();
                    break;
                case '1w':
                    // 1 hour intervals for 1 week
                    for (let i = 0; i < 7 * 24; i++) {
                        timePoints.push(new Date(now - i * 60 * 60 * 1000));
                    }
                    timePoints.reverse();
                    timeFormat = d3.timeFormat("%a %H:%M");
                    break;
                case '1m':
                    // 1 day intervals for 1 month
                    for (let i = 0; i < 30; i++) {
                        timePoints.push(new Date(now - i * 24 * 60 * 60 * 1000));
                    }
                    timePoints.reverse();
                    timeFormat = d3.timeFormat("%b %d");
                    break;
                case '3m':
                    // 1 day intervals for 3 months
                    for (let i = 0; i < 90; i++) {
                        timePoints.push(new Date(now - i * 24 * 60 * 60 * 1000));
                    }
                    timePoints.reverse();
                    timeFormat = d3.timeFormat("%b %d");
                    break;
                case '1y':
                    // 1 week intervals for 1 year
                    for (let i = 0; i < 52; i++) {
                        timePoints.push(new Date(now - i * 7 * 24 * 60 * 60 * 1000));
                    }
                    timePoints.reverse();
                    timeFormat = d3.timeFormat("%b %Y");
                    break;
            }

            // Generate data for each stock
            selectedStocks.forEach(stock => {
                const basePrice = 100 + Math.random() * 200;
                const volatility = 0.01 + Math.random() * 0.05;

                const prices = timePoints.map((time, i) => {
                    // Simulate price movement with some randomness
                    const change = (Math.random() - 0.5) * volatility * basePrice;
                    const price = basePrice + change * i;

                    return {
                        time: time,
                        price: Math.max(0.01, price.toFixed(2))
                    };
                });

                stocks.push({
                    symbol: stock,
                    prices: prices
                });
            });

            return {
                stocks: stocks,
                timePoints: timePoints,
                timeFormat: timeFormat
            };
        }

        // Main visualization function
        function createHeatmap(data) {
            // Clear previous visualization
            d3.select("#heatmap-container").selectAll("*").remove();

            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Extract data
            const stocks = data.stocks;
            const timePoints = data.timePoints;
            const timeFormat = data.timeFormat;

            // Create scales
            const xScale = d3.scaleBand()
                .domain(timePoints.map(d => d))
                .range([0, width])
                .padding(config.cellPadding);

            const yScale = d3.scaleBand()
                .domain(stocks.map(d => d.symbol))
                .range([0, height])
                .padding(config.cellPadding);

            // Find min and max prices for color scale
            const allPrices = stocks.flatMap(stock => stock.prices.map(p => +p.price));
            const minPrice = d3.min(allPrices);
            const maxPrice = d3.max(allPrices);

            // Color scale
            const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                .domain([minPrice, maxPrice]);

            // Create tooltip
            const tooltip = d3.select("#tooltip");

            // Create heatmap cells
            const cells = svg.selectAll(".cell")
                .data(stocks.flatMap(stock =>
                    stock.prices.map(price => ({
                        symbol: stock.symbol,
                        time: price.time,
                        price: price.price
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Time: ${timeFormat(d.time)}<br>
                            Price: $${d.price}
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Add x-axis
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(timeFormat)
                .tickValues(timePoints.filter((d, i) => i % Math.ceil(timePoints.length / 10) === 0));

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            // Add y-axis
            const yAxis = d3.axisLeft(yScale);

            svg.append("g")
                .attr("class", "y-axis")
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add legend
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = [
                { color: colorScale(minPrice), label: `$${minPrice.toFixed(2)}` },
                { color: colorScale((minPrice + maxPrice) / 2), label: `$${((minPrice + maxPrice) / 2).toFixed(2)}` },
                { color: colorScale(maxPrice), label: `$${maxPrice.toFixed(2)}` }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <div class="legend-label">${d.label}</div>
                `);

            // Add zoom and pan functionality
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [width, height]])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.attr("transform", transform);
                });

            svg.call(zoom);

            // Add reset zoom button
            d3.select("#heatmap-container")
                .append("button")
                .attr("class", "reset-zoom")
                .text("Reset Zoom")
                .style("position", "absolute")
                .style("top", "10px")
                .style("right", "10px")
                .on("click", () => {
                    svg.transition().duration(750).call(
                        zoom.transform,
                        d3.zoomIdentity
                    );
                });
        }

        // Initialize the visualization
        function init() {
            const timeframe = d3.select("#timeframe").property("value");
            const stockCount = Math.min(config.maxStocks, +d3.select("#stock-count").property("value"));

            const data = generateMockData(stockCount, timeframe);
            createHeatmap(data);

            // Set up update button
            d3.select("#update-btn").on("click", () => {
                const newTimeframe = d3.select("#timeframe").property("value");
                const newStockCount = Math.min(config.maxStocks, +d3.select("#stock-count").property("value"));

                const newData = generateMockData(newStockCount, newTimeframe);
                createHeatmap(newData);
            });

            // Set up automatic updates
            setInterval(() => {
                const currentTimeframe = d3.select("#timeframe").property("value");
                const currentStockCount = Math.min(config.maxStocks, +d3.select("#stock-count").property("value"));

                const updatedData = generateMockData(currentStockCount, currentTimeframe);
                createHeatmap(updatedData);
            }, config.updateInterval);
        }

        // Start the application
        init();
    </script>
</body>
</html>
```

