    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 50, right: 30, bottom: 50, left: 80 },
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            timeFormat: "%Y-%m-%d %H:%M",
            updateInterval: 10000 // Default 10 seconds
        };

        // Mock data generator
        function generateMockData(symbols, timeframe) {
            const now = new Date();
            let startDate, interval;

            switch(timeframe) {
                case '1d':
                    startDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                    interval = 5 * 60 * 1000; // 5 minutes
                    break;
                case '1w':
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    interval = 30 * 60 * 1000; // 30 minutes
                    break;
                case '1m':
                    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
                    interval = 2 * 60 * 60 * 1000; // 2 hours
                    break;
                case '3m':
                    startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    break;
                case '1y':
                    startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    break;
                default:
                    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
                    interval = 2 * 60 * 60 * 1000;
            }

            const data = [];
            const timePoints = [];

            // Generate time points
            for (let t = startDate.getTime(); t <= now.getTime(); t += interval) {
                timePoints.push(new Date(t));
            }

            // Generate data for each symbol
            symbols.forEach(symbol => {
                const basePrice = 100 + Math.random() * 200;
                let currentPrice = basePrice;

                timePoints.forEach(time => {
                    // Simulate price movement
                    const change = (Math.random() - 0.5) * 0.05; // -2.5% to +2.5% change
                    currentPrice *= (1 + change);

                    data.push({
                        symbol: symbol,
                        time: time,
                        price: currentPrice,
                        change: change
                    });
                });
            });

            return data;
        }

        // Main visualization function
        function createHeatmap(data, symbols, timePoints) {
            // Clear previous visualization
            d3.select("#heatmap-container").selectAll("*").remove();

            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create scales
            const xScale = d3.scaleBand()
                .domain(timePoints.map(d => d.toISOString()))
                .range([0, width])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(symbols)
                .range([0, height])
                .padding(0.01);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => d3.timeFormat(config.timeFormat)(new Date(d)))
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(timePoints.length / 10) === 0));

            const yAxis = d3.axisLeft(yScale);

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.append("g")
                .attr("class", "y-axis")
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Create tooltip
            const tooltip = d3.select("#tooltip");

            // Create heatmap cells
            svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time.toISOString()))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", function(event, d) {
                    tooltip.style("display", "block")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Time: ${d3.timeFormat(config.timeFormat)(d.time)}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Change: ${(d.change * 100).toFixed(2)}%
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("display", "none");
                });

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.attr("transform", transform);
                });

            svg.call(zoom);

            // Add zoom controls
            d3.select("#zoom-in").on("click", () => {
                svg.transition().call(zoom.scaleBy, 1.5);
            });

            d3.select("#zoom-out").on("click", () => {
                svg.transition().call(zoom.scaleBy, 0.75);
            });

            d3.select("#reset-zoom").on("click", () => {
                svg.transition().call(zoom.transform, d3.zoomIdentity);
            });

            // Create legend
            createLegend();
        }

        // Create color legend
        function createLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const colorScale = config.colorScale;
            const domain = colorScale.domain();
            const steps = 10;

            for (let i = 0; i <= steps; i++) {
                const value = domain[0] + (domain[1] - domain[0]) * (i / steps);

                legend.append("div")
                    .attr("class", "legend-item")
                    .html(`
                        <div class="legend-color" style="background-color: ${colorScale(value)}"></div>
                        <div class="legend-label">${(value * 100).toFixed(1)}%</div>
                    `);
            }
        }

        // Update data based on controls
        function updateData() {
            const timeframe = d3.select("#timeframe").property("value");
            const selectedSymbols = Array.from(d3.select("#stock-select").property("selectedOptions"))
                .map(option => option.value);

            if (selectedSymbols.length === 0) {
                alert("Please select at least one stock symbol");
                return;
            }

            // Generate mock data
            const data = generateMockData(selectedSymbols, timeframe);

            // Extract unique time points and symbols
            const timePoints = [...new Set(data.map(d => d.time))].sort((a, b) => a - b);
            const symbols = [...new Set(data.map(d => d.symbol))].sort();

            // Create or update heatmap
            createHeatmap(data, symbols, timePoints);
        }

        // Initialize the visualization
        function init() {
            // Set up event listeners
            d3.select("#update-btn").on("click", updateData);
            d3.select("#timeframe").on("change", updateData);
            d3.select("#stock-select").on("change", updateData);
            d3.select("#update-interval").on("change", function() {
                config.updateInterval = +this.value;
                clearInterval(window.updateIntervalId);
                window.updateIntervalId = setInterval(updateData, config.updateInterval);
            });

            // Initial data load
            updateData();

            // Set up automatic updates
            window.updateIntervalId = setInterval(updateData, config.updateInterval);
        }

        // Start the application
        init();
    </script>
</body>
