                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => d.price ? config.colorScale(d.price) : "#eee")
                .on("mouseover", function(event, d) {
                    if (!d.price) return;

                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Time: ${d3.timeFormat("%b %d %H:%M")(d.time)}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}%
                        `);

                    // Position tooltip near cursor
                    const [x, y] = d3.pointer(event);
                    tooltip.style("top", (y + 10) + "px")
                        .style("left", (x + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                })
                .merge(cells)
                .transition()
                .duration(500)
                .attr("fill", d => d.price ? config.colorScale(d.price) : "#eee");

            // Remove old cells
            cells.exit().remove();

            // Update legend
            updateLegend(allPrices);

            // Hide loading indicator
            loadingIndicator.style("display", "none");
        }

        // Update the legend
        function updateLegend(values) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Get quantile thresholds
            const thresholds = config.colorScale.quantiles();

            // Create legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(thresholds)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            legendItems.append("span")
                .text((d, i) => {
                    if (i === 0) return `< $${d.toFixed(2)}`;
                    if (i === thresholds.length - 1) return `≥ $${d.toFixed(2)}`;
                    return `$${thresholds[i-1].toFixed(2)} - $${d.toFixed(2)}`;
                });
        }

        // Fetch data from API (simulated with mock data)
        async function fetchData() {
            if (isUpdating) return;

            isUpdating = true;
            loadingIndicator.style("display", "block");

            try {
                // Get selected stocks
                selectedStocks = Array.from(stockSelect.selectedOptions).map(opt => opt.value);

                // In a real app, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
                // For this example, we'll use mock data
                const mockData = generateMockData();

                // Process the data
                stockData = mockData.stocks;
                timePoints = mockData.timePoints;

                // Update the visualization
                updateHeatmap();
            } catch (error) {
                console.error("Error fetching data:", error);
                loadingIndicator.text("Error loading data. Please try again.");
            } finally {
                isUpdating = false;
            }
        }

        // Generate mock data for demonstration
        function generateMockData() {
            const symbols = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "META", "NVDA", "JPM", "V", "WMT"];
            const timeExtent = getTimeExtent(currentTimeframe);

            // Generate time points based on timeframe
            const timePoints = [];
            let currentTime = new Date(timeExtent.start);

            while (currentTime <= timeExtent.end) {
                timePoints.push(new Date(currentTime));
                // Add 15 minutes for 1 day, 1 hour for others
                if (currentTimeframe === "1d") {
                    currentTime.setMinutes(currentTime.getMinutes() + 15);
                } else {
                    currentTime.setHours(currentTime.getHours() + 1);
                }
            }

            // Generate stock data
            const stocks = symbols.map(symbol => {
                const basePrice = 100 + Math.random() * 200; // Random base price between 100-300
                const prices = timePoints.map(time => {
                    // Simulate price movement
                    const changePercent = (Math.random() - 0.5) * 2; // Random change between -1% and +1%
                    const price = basePrice * (1 + changePercent / 100);

                    return {
                        time: time,
                        price: parseFloat(price.toFixed(2)),
                        change: parseFloat(changePercent.toFixed(2))
                    };
                });

                return {
                    symbol: symbol,
                    prices: prices
                };
            });

            return {
                stocks: stocks,
                timePoints: timePoints
            };
        }

        // Get time extent based on selected timeframe
        function getTimeExtent(timeframe) {
            const now = new Date();
            let start;

            switch (timeframe) {
                case "1d":
                    start = new Date(now);
                    start.setDate(now.getDate() - 1);
                    break;
                case "1w":
                    start = new Date(now);
                    start.setDate(now.getDate() - 7);
                    break;
                case "1m":
                    start = new Date(now);
                    start.setMonth(now.getMonth() - 1);
                    break;
                case "3m":
                    start = new Date(now);
                    start.setMonth(now.getMonth() - 3);
                    break;
                case "1y":
                    start = new Date(now);
                    start.setFullYear(now.getFullYear() - 1);
                    break;
                default:
                    start = new Date(now);
                    start.setMonth(now.getMonth() - 1);
            }

            return { start: start, end: now };
        }

        // Initialize the application
        init();

        // Simulate real-time updates (every 5 seconds)
        setInterval(() => {
            if (isUpdating) return;

            // Generate new data point for each stock
            const now = new Date();
            const newTimePoint = new Date(now);

            // Add to timePoints if it's a new time point
            if (!timePoints.some(t => t.getTime() === newTimePoint.getTime())) {
                timePoints.push(newTimePoint);
            }

            // Update each stock with new price
            stockData.forEach(stock => {
                const lastPrice = stock.prices[stock.prices.length - 1].price;
                const changePercent = (Math.random() - 0.5) * 0.5; // Smaller random change for real-time updates
                const newPrice = lastPrice * (1 + changePercent / 100);

                stock.prices.push({
                    time: newTimePoint,
                    price: parseFloat(newPrice.toFixed(2)),
                    change: parseFloat(changePercent.toFixed(2))
                });

                // Keep only the last 100 points to prevent memory issues
                if (stock.prices.length > 100) {
                    stock.prices.shift();
                }
            });

            // Update the visualization
            updateHeatmap();
        }, 5000);
    </script>
