    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 30, right: 30, bottom: 30, left: 60 },
            colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf",
                    "#e0f3f8", "#abd9e9", "#74add1", "#4575b4", "#313695"],
            minZoom: 0.5,
            maxZoom: 10,
            defaultUpdateInterval: 10000 // 10 seconds
        };

        // Sample stock data (in a real app, this would come from an API)
