            "AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "BRK.B", "JNJ", "V", "PG",
            "JPM", "NVDA", "DIS", "PYPL", "MA", "HD", "BAC", "INTC", "VZ", "ADBE",
            "CMCSA", "NFLX", "KO", "PEP", "T", "MRK", "XOM", "CSCO", "ABT", "CRM"
        ];

        // Generate sample time points (in a real app, these would be actual timestamps)
        function generateTimePoints(timeframe) {
            const now = new Date();
            const points = [];

            switch(timeframe) {
                case '1d':
                    // 1 hour intervals for 1 day
                    for (let i = 0; i < 24; i++) {
                        const date = new Date(now);
                        date.setHours(now.getHours() - i);
                        points.unshift(date);
                    }
                    break;
                case '1w':
                    // 6 hour intervals for 1 week
                    for (let i = 0; i < 28; i++) {
                        const date = new Date(now);
                        date.setHours(now.getHours() - i * 6);
                        points.unshift(date);
                    }
                    break;
                case '1m':
                    // 1 day intervals for 1 month
                    for (let i = 0; i < 30; i++) {
                        const date = new Date(now);
                        date.setDate(now.getDate() - i);
                        points.unshift(date);
                    }
                    break;
                case '3m':
                    // 3 day intervals for 3 months
                    for (let i = 0; i < 30; i++) {
                        const date = new Date(now);
                        date.setDate(now.getDate() - i * 3);
                        points.unshift(date);
                    }
                    break;
                case '1y':
                    // 1 week intervals for 1 year
                    for (let i = 0; i < 52; i++) {
                        const date = new Date(now);
                        date.setDate(now.getDate() - i * 7);
                        points.unshift(date);
                    }
                    break;
                default:
                    // Default to 1 month
                    for (let i = 0; i < 30; i++) {
                        const date = new Date(now);
                        date.setDate(now.getDate() - i);
                        points.unshift(date);
