                    // Simulate price movement with some randomness
                    const basePrice = 100 + stockIndex * 5;
                    const volatility = 0.02 + Math.random() * 0.03;
                    const trend = 0.001 * timeIndex;

                    const price = basePrice * (1 + Math.sin(timeIndex * 0.1) * volatility + trend);

                    data.push({
                        stock: stock,
                        time: time,
                        price: price.toFixed(2),
                        change: (Math.random() * 4 - 2).toFixed(2) // Random change percentage
                    });
                });
            });

            return data;
        }

        // Main visualization class
        class StockHeatmap {
            constructor(containerId) {
                this.container = d3.select(containerId);
                this.svg = this.container.append("svg")
                    .attr("width", config.width)
                    .attr("height", config.height);

                this.tooltip = this.container.select(".tooltip");
