                // In a real app, this would be an API call
                setTimeout(() => {
                    const timeframe = d3.select("#timeframe").property("value");
                    this.timePoints = generateTimePoints(timeframe);
                    this.data = generatePriceData(this.timePoints, this.stocks);

                    this.updateVisualization();
                    this.container.select(".loading").style("display", "none");

                    this.startAutoUpdate();
                }, 500); // Simulate network delay
            }

            startAutoUpdate() {
                // Clear any existing timer
                if (this.updateTimer) {
                    clearInterval(this.updateTimer);
                }

                // Set up new timer
                this.updateTimer = setInterval(() => {
                    this.updateData();
                }, this.updateInterval);
            }

            updateData() {
                // In a real app, this would fetch new data
                // For demo, we'll just generate new data points
                const lastTime = this.timePoints[this.timePoints.length - 1];
                const newTime = new Date(lastTime);
                const timeframe = d3.select("#timeframe").property("value");

                // Add new time point based on timeframe
                switch(timeframe) {
                    case '1d':
                        newTime.setHours(lastTime.getHours() + 1);
                        break;
                    case '1w':
                        newTime.setHours(lastTime.getHours() + 6);
                        break;
                    case '1m':
                        newTime.setDate(lastTime.getDate() + 1);
                        break;
                    case '3m':
                        newTime.setDate(lastTime.getDate() + 3);
                        break;
                    case '1y':
                        newTime.setDate(lastTime.getDate() + 7);
                        break;
                    default:
                        newTime.setDate(lastTime.getDate() + 1);
                }

                // Generate new data for this time point
                const newData = [];
                this.stocks.forEach((stock, stockIndex) => {
                    const basePrice = parseFloat(this.data[this.data.length - this.stocks.length + stockIndex].price);
                    const volatility = 0.02 + Math.random() * 0.03;
                    const trend = 0.001;

                    const price = basePrice * (1 + Math.sin(this.timePoints.length * 0.1) * volatility + trend);

                    newData.push({
                        stock: stock,
                        time: newTime,
                        price: price.toFixed(2),
                        change: (Math.random() * 4 - 2).toFixed(2)
                    });
                });

                // Remove oldest time point if we've reached the limit
                if (this.timePoints.length >= this.getMaxTimePoints()) {
                    this.timePoints.shift();
                    this.data = this.data.slice(this.stocks.length);
                }

                // Add new time point and data
                this.timePoints.push(newTime);
                this.data = [...this.data, ...newData];

                this.updateVisualization();
