                            }
                        })
                        .tickSizeOuter(0))
                    .selectAll("text")
                    .attr("transform", "rotate(-45)")
                    .style("text-anchor", "end");

                // Add y-axis (stocks)
                this.svg.append("g")
                    .attr("class", "axis axis-y")
                    .attr("transform", `translate(${config.margin.left},0)`)
                    .call(d3.axisLeft(this.yScale).tickSizeOuter(0));

                // Add axis labels
                this.svg.append("text")
                    .attr("class", "axis-label")
                    .attr("x", config.width / 2)
                    .attr("y", config.height - 5)
                    .style("text-anchor", "middle")
                    .text("Time");

                this.svg.append("text")
                    .attr("class", "axis-label")
                    .attr("transform", "rotate(-90)")
                    .attr("x", -config.height / 2)
                    .attr("y", 15)
                    .style("text-anchor", "middle")
                    .text("Stock Symbol");

                // Update legend
                this.updateLegend();
            }

            updateLegend() {
                this.legend.selectAll("*").remove();

                const legendData = this.colorScale.quantiles();
                const legendItems = this.legend.selectAll(".legend-item")
                    .data(legendData)
                    .enter()
                    .append("div")
                    .attr("class", "legend-item");

                legendItems.append("div")
                    .attr("class", "legend-color")
                    .style("background-color", (d, i) => config.colors[i]);

                legendItems.append("span")
                    .text(d => `${d.toFixed(2)}`);
            }

            showTooltip(event, d) {
                const timeframe = d3.select("#timeframe").property("value");
                let timeFormat = "%Y-%m-%d %H:%M";

                if (timeframe === '1d') {
                    timeFormat = "%H:%M";
                } else if (timeframe === '1w') {
                    timeFormat = "%a %H:%M";
                }

                const formattedTime = d3.timeFormat(timeFormat)(new Date(d.time));
                const changeColor = +d.change >= 0 ? "green" : "red";

                this.tooltip.html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${formattedTime}<br>
                    Price: $${d.price}<br>
                    Change: <span style="color: ${changeColor}">${d.change}%</span>
                `)
                .style("visibility", "visible");
            }

            hideTooltip() {
                this.tooltip.style("visibility", "hidden");
            }

            moveTooltip(event) {
                this.tooltip
                    .style("top", (event.pageY + 10) + "px")
                    .style("left", (event.pageX + 10) + "px");
            }

            zoomed(event) {
                const transform = event.transform;

                // Apply zoom to the x-axis
                this.svg.select(".axis-x")
                    .call(d3.axisBottom(this.xScale.scale(transform.rescaleX(this.xScale)))
                        .tickFormat(d => {
                            const date = new Date(d);
                            const timeframe = d3.select("#timeframe").property("value");

                            if (timeframe === '1d') {
                                return d3.timeFormat("%H:%M")(date);
                            } else if (timeframe === '1w') {
                                return d3.timeFormat("%a %Hh")(date);
                            } else {
                                return d3.timeFormat("%b %d")(date);
                            }
                        })
                        .tickSizeOuter(0))
                    .selectAll("text")
                    .attr("transform", "rotate(-45)")
                    .style("text-anchor", "end");

                // Apply zoom to the cells
                this.svg.selectAll(".cell")
                    .attr("x", d => transform.applyX(this.xScale(d.time.toISOString())))
                    .attr("width", this.xScale.bandwidth() * transform.k);
            }
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", () => {
            const heatmap = new StockHeatmap("#heatmap-container");
        });
    </script>
