                </select>
            </div>

            <div class="control-group">
                <label for="stock-select">Select Stocks:</label>
                <select id="stock-select" multiple>
                    <option value="AAPL" selected>Apple (AAPL)</option>
                    <option value="MSFT" selected>Microsoft (MSFT)</option>
                    <option value="GOOGL" selected>Alphabet (GOOGL)</option>
                    <option value="AMZN" selected>Amazon (AMZN)</option>
                    <option value="TSLA" selected>Tesla (TSLA)</option>
                    <option value="FB" selected>Meta (FB)</option>
                    <option value="NVDA" selected>NVIDIA (NVDA)</option>
                    <option value="JPM" selected>JPMorgan (JPM)</option>
                    <option value="V" selected>Visa (V)</option>
                    <option value="WMT" selected>Walmart (WMT)</option>
                </select>
            </div>

            <div class="control-group">
                <label for="color-scale">Color Scale:</label>
                <select id="color-scale">
                    <option value="interpolateRdYlGn">Red-Yellow-Green</option>
                    <option value="interpolateViridis">Viridis</option>
                    <option value="interpolatePlasma">Plasma</option>
                    <option value="interpolateCool">Cool</option>
                    <option value="interpolateRainbow">Rainbow</option>
                </select>
            </div>

            <div class="control-group">
                <label>&nbsp;</label>
                <button id="reset-btn">Reset View</button>
            </div>
        </div>

        <div id="heatmap-container"></div>
        <div class="legend" id="legend"></div>
        <div class="tooltip" id="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            margin: { top: 40, right: 30, bottom: 60, left: 100 },
            cellSize: 20,
            minZoom: 0.5,
            maxZoom: 10
        };

        // Global variables
        let svg, heatmap, xScale, yScale, colorScale, xAxis, yAxis;
        let zoom, tooltip;
        let data = [];
        let currentTimeframe = '1m';
        let selectedStocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT'];
        let currentColorScale = 'interpolateRdYlGn';
        let simulationRunning = false;
        let simulationInterval;

        // Initialize the visualization
        document.addEventListener('DOMContentLoaded', () => {
            initVisualization();
            setupEventListeners();

            // Start with some sample data
            generateSampleData();

            // Start real-time simulation
            startSimulation();
        });

        function initVisualization() {
            // Set up the SVG container
            const container = d3.select('#heatmap-container');
            const width = container.node().getBoundingClientRect().width;
            const height = container.node().getBoundingClientRect().height;

            svg = container.append('svg')
                .attr('width', width)
                .attr('height', height);

            // Create a group for the heatmap
            heatmap = svg.append('g')
                .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

            // Set up scales
            xScale = d3.scaleBand().padding(0.1);
            yScale = d3.scaleBand().padding(0.1);
            colorScale = d3.scaleSequential(d3[currentColorScale]);

            // Set up axes
            xAxis = heatmap.append('g')
                .attr('class', 'x-axis')
                .attr('transform', `translate(0,${height - config.margin.top - config.margin.bottom})`);

            yAxis = heatmap.append('g')
                .attr('class', 'y-axis');

            // Set up zoom behavior
            zoom = d3.zoom()
                .scaleExtent([config.minZoom, config.maxZoom])
                .on('zoom', zoomed);

            svg.call(zoom);

            // Create tooltip
            tooltip = d3.select('#tooltip');

            // Add axis labels
            svg.append('text')
                .attr('class', 'axis-label')
                .attr('x', width / 2)
                .attr('y', height - 10)
                .style('text-anchor', 'middle')
                .text('Time');

            svg.append('text')
                .attr('class', 'axis-label')
                .attr('transform', 'rotate(-90)')
                .attr('x', -height / 2)
                .attr('y', 20)
                .style('text-anchor', 'middle')
                .text('Stock Symbol');

            // Create legend
            createLegend();
        }

        function setupEventListeners() {
            // Timeframe change
            d3.select('#timeframe').on('change', function() {
                currentTimeframe = this.value;
                generateSampleData();
                updateVisualization();
            });

            // Stock selection change
            d3.select('#stock-select').on('change', function() {
                const options = Array.from(this.selectedOptions);
                selectedStocks = options.map(opt => opt.value);
                generateSampleData();
                updateVisualization();
            });

            // Color scale change
            d3.select('#color-scale').on('change', function() {
                currentColorScale = this.value;
                colorScale.interpolator(d3[currentColorScale]);
                updateVisualization();
                createLegend();
            });

            // Reset button
            d3.select('#reset-btn').on('click', resetZoom);

            // Window resize
            window.addEventListener('resize', () => {
                const container = d3.select('#heatmap-container');
                const width = container.node().getBoundingClientRect().width;
                const height = container.node().getBoundingClientRect().height;

                svg.attr('width', width).attr('height', height);

                // Update axis labels position
                svg.selectAll('.axis-label')
                    .filter((d, i) => i === 0) // Time label
                    .attr('x', width / 2)
                    .attr('y', height - 10);

                svg.selectAll('.axis-label')
                    .filter((d, i) => i === 1) // Stock label
                    .attr('x', -height / 2)
                    .attr('y', 20);

                updateVisualization();
            });
        }

        function generateSampleData() {
            // In a real application, this would fetch from an API
            // For demo purposes, we'll generate synthetic data

            // Clear existing data
            data = [];

            // Determine time range based on selected timeframe
            const now = new Date();
            let startDate;

            switch(currentTimeframe) {
                case '1d':
                    startDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
                    break;
                case '1w':
                    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
                    break;
                case '1m':
                    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
                    break;
                case '3m':
                    startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
                    break;
                case '1y':
                    startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
                    break;
                default:
                    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            }

            // Generate time points (hourly for 1d, daily for others)
            const timePoints = [];
            const timeIncrement = currentTimeframe === '1d' ? 60 * 60 * 1000 : 24 * 60 * 60 * 1000;

            for (let time = startDate.getTime(); time <= now.getTime(); time += timeIncrement) {
                timePoints.push(new Date(time));
            }

            // Generate data for each selected stock
            selectedStocks.forEach(stock => {
                const basePrice = 100 + Math.random() * 200; // Random base price

                timePoints.forEach(time => {
                    // Generate a random price change
                    const change = (Math.random() - 0.5) * 10;
                    const price = basePrice + change;

                    // Generate volume (random for demo)
                    const volume = Math.floor(Math.random() * 1000000);

                    data.push({
                        stock,
                        time,
                        price,
                        volume,
                        change: change / basePrice * 100 // Percentage change
                    });
                });
            });
        }

        function updateVisualization() {
            if (!data.length) return;

            // Get container dimensions
            const container = d3.select('#heatmap-container').node();
            const width = container.getBoundingClientRect().width - config.margin.left - config.margin.right;
            const height = container.getBoundingClientRect().height - config.margin.top - config.margin.bottom;

            // Set up scales
            const timePoints = [...new Set(data.map(d => d.time.getTime()))].sort();
            const stocks = [...new Set(data.map(d => d.stock))].sort();

            xScale.domain(timePoints.map(t => new Date(t)))
                .range([0, width]);

            yScale.domain(stocks)
                .range([0, height]);

            // Determine color scale domain based on price changes
            const changes = data.map(d => d.change);
            const minChange = d3.min(changes);
            const maxChange = d3.max(changes);

            colorScale.domain([minChange, maxChange]);

            // Update axes
            xAxis.call(d3.axisBottom(xScale)
                .ticks(timePoints.length > 10 ? 10 : timePoints.length)
                .tickFormat(d3.timeFormat(currentTimeframe === '1d' ? '%H:%M' : '%b %d')));

            yAxis.call(d3.axisLeft(yScale));

            // Bind data to cells
            const cells = heatmap.selectAll('.cell')
                .data(data, d => `${d.stock}-${d.time.getTime()}`);

            // Enter new cells
            cells.enter()
                .append('rect')
                .attr('class', 'cell')
                .attr('x', d => xScale(d.time))
                .attr('y', d => yScale(d.stock))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d.change))
                .on('mouseover', showTooltip)
                .on('mouseout', hideTooltip)
                .on('mousemove', moveTooltip);

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr('x', d => xScale(d.time))
                .attr('y', d => yScale(d.stock))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d.change));

            // Remove old cells
            cells.exit().remove();
        }

        function showTooltip(event, d) {
            tooltip.style('opacity', 1)
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d3.timeFormat('%Y-%m-%d %H:%M')(d.time)}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change.toFixed(2)}%<br>
                    Volume: ${d.volume.toLocaleString()}
                `);
        }

        function hideTooltip() {
            tooltip.style('opacity', 0);
        }

        function moveTooltip(event) {
            tooltip.style('left', `${event.pageX + 10}px`)
                .style('top', `${event.pageY + 10}px`);
        }

        function zoomed(event) {
            const { transform } = event;
            heatmap.attr('transform', transform);

            // Adjust cell sizes based on zoom level
            const scale = transform.k;
            const newCellSize = config.cellSize * scale;

            heatmap.selectAll('.cell')
                .attr('width', newCellSize)
                .attr('height', newCellSize);
        }

        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        function createLegend() {
            const legend = d3.select('#legend');
            legend.selectAll('*').remove();

            // Create a color gradient for the legend
            const gradient = legend.append('defs')
                .append('linearGradient')
                .attr('id', 'legend-gradient')
                .attr('x1', '0%')
                .attr('y1', '0%')
                .attr('x2', '100%')
                .attr('y2', '0%');

            // Add color stops
            const domain = colorScale.domain();
            const range = [0, 1];

            gradient.selectAll('stop')
                .data(domain)
                .enter().append('stop')
                .attr('offset', (d, i) => range[i] * 100 + '%')
                .attr('stop-color', d => colorScale(d));

            // Add the gradient rectangle
            legend.append('rect')
                .attr('width', 200)
                .attr('height', 20)
                .style('fill', 'url(#legend-gradient)');

            // Add min and max labels
            legend.append('text')
                .attr('class', 'legend-label')
                .attr('x', 0)
                .attr('y', 35)
                .text(domain[0].toFixed(2) + '%');

            legend.append('text')
                .attr('class', 'legend-label')
                .attr('x', 180)
                .attr('y', 35)
                .style('text-anchor', 'end')
                .text(domain[1].toFixed(2) + '%');

            legend.append('text')
                .attr('class', 'legend-label')
                .attr('x', 100)
                .attr('y', 35)
                .style('text-anchor', 'middle')
                .text('Price Change (%)');
        }

        function startSimulation() {
            if (simulationRunning) return;

            simulationRunning = true;

            // Simulate real-time updates every 5 seconds
            simulationInterval = setInterval(() => {
                // In a real app, this would fetch new data from a WebSocket or API
                updateDataWithNewValues();
                updateVisualization();
            }, 5000);
        }

        function updateDataWithNewValues() {
            // Add new data point for each stock
            const now = new Date();

            selectedStocks.forEach(stock => {
                // Find the last price for this stock
                const lastEntry = data.filter(d => d.stock === stock)
                    .sort((a, b) => b.time - a.time)[0];

                const lastPrice = lastEntry ? lastEntry.price : 100 + Math.random() * 200;

                // Generate a new price
                const change = (Math.random() - 0.5) * 5;
                const newPrice = lastPrice + change;

                // Generate new volume
                const newVolume = Math.floor(Math.random() * 1000000);

                // Add to data
                data.push({
                    stock,
                    time: now,
                    price: newPrice,
                    volume: newVolume,
                    change: change / lastPrice * 100
                });
            });

            // Remove old data points based on timeframe
            const cutoff = new Date();
            switch(currentTimeframe) {
                case '1d':
                    cutoff.setHours(cutoff.getHours() - 24);
                    break;
                case '1w':
                    cutoff.setDate(cutoff.getDate() - 7);
                    break;
                case '1m':
                    cutoff.setMonth(cutoff.getMonth() - 1);
                    break;
                case '3m':
                    cutoff.setMonth(cutoff.getMonth() - 3);
                    break;
                case '1y':
                    cutoff.setFullYear(cutoff.getFullYear() - 1);
                    break;
                default:
                    cutoff.setMonth(cutoff.getMonth() - 1);
            }

            data = data.filter(d => d.time >= cutoff);
        }

        // Clean up when page is unloaded
        window.addEventListener('beforeunload', () => {
            if (simulationInterval) {
                clearInterval(simulationInterval);
            }
        });
    </script>
</body>
</html>
```

