                .attr("class", "heatmap");

            // Create scales
            xScale = d3.scaleBand();
            yScale = d3.scaleBand();
            colorScale = d3.scaleSequential(d3.interpolateRdYlGn);

            // Create legend
            createLegend();

            // Load initial data
            loadData();

            // Set up event listeners
            timeframeSelect.on("change", loadData);
            stockCountInput.on("change", loadData);
            updateBtn.on("click", loadData);
            resetBtn.on("click", resetView);

            // Start auto-updating
            startAutoUpdate();
        }

        // Create legend
        function createLegend() {
            const legend = d3.select("#legend");
            const legendData = [
                { color: d3.interpolateRdYlGn(0), label: "Low" },
                { color: d3.interpolateRdYlGn(0.5), label: "Medium" },
                { color: d3.interpolateRdYlGn(1), label: "High" }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);
        }

        // Load data based on current settings
        function loadData() {
            if (isLoading) return;

            isLoading = true;
            heatmapContainer.select(".loading").style("display", "block");

            // In a real app, this would fetch from an API
            setTimeout(() => {
                const timeframe = timeframeSelect.property("value");
                const stockCount = Math.min(
                    Math.max(parseInt(stockCountInput.property("value")) || 20, config.minStocks),
                    config.maxStocks
                );

                // Generate mock data (replace with real API call)
                generateMockData(timeframe, stockCount).then(data => {
                    currentData = data;
                    updateVisualization();
                    isLoading = false;
                    heatmapContainer.select(".loading").style("display", "none");
                });
            }, 500); // Simulate network delay
        }

        // Generate mock data (simulating API response)
        async function generateMockData(timeframe, stockCount) {
            const stocks = sampleStocks.slice(0, stockCount);
            const now = new Date();
            let timePoints;

            // Determine time points based on timeframe
            switch(timeframe) {
                case "1d":
                    timePoints = 24; // 1 hour intervals
                    break;
                case "1w":
                    timePoints = 168; // 1 hour intervals
                    break;
                case "1m":
                    timePoints = 30; // daily
                    break;
                case "3m":
                    timePoints = 90; // daily
                    break;
                case "1y":
                    timePoints = 12; // monthly
                    break;
                default:
                    timePoints = 30;
            }

            // Generate data for each stock and time point
            const data = stocks.map(stock => {
                const stockData = {
                    symbol: stock,
                    values: []
                };

                for (let i = 0; i < timePoints; i++) {
                    let date;
                    let price;

                    // Calculate date and price based on timeframe
                    switch(timeframe) {
                        case "1d":
                            date = new Date(now - (24 - i) * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.5) * 20;
                            break;
                        case "1w":
                            date = new Date(now - (168 - i) * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.1) * 20;
                            break;
                        case "1m":
                            date = new Date(now - (30 - i) * 24 * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.2) * 20;
                            break;
                        case "3m":
                            date = new Date(now - (90 - i) * 24 * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.1) * 20;
                            break;
                        case "1y":
                            date = new Date(now - (12 - i) * 30 * 24 * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.5) * 20;
                            break;
                        default:
                            date = new Date(now - (30 - i) * 24 * 60 * 60 * 1000);
                            price = 100 + Math.random() * 50 - Math.sin(i * 0.2) * 20;
                    }

                    stockData.values.push({
                        date: date,
                        price: parseFloat(price.toFixed(2))
                    });
                }

                return stockData;
            });

            return data;
        }

        // Update the visualization with new data
        function updateVisualization() {
            if (currentData.length === 0) return;

            // Flatten data for color scale
            const allPrices = currentData.flatMap(stock =>
                stock.values.map(d => d.price)
            );

            // Update color scale
            colorScale.domain([d3.min(allPrices), d3.max(allPrices)]);

            // Update scales
            const stocks = currentData.map(d => d.symbol);
            const timePoints = currentData[0].values.map(d => d.date);

            xScale.domain(timePoints)
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            yScale.domain(stocks)
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.1);

            // Remove existing cells
            heatmap.selectAll(".cell").remove();

            // Add new cells
            const cells = heatmap.selectAll(".cell")
                .data(currentData)
                .enter()
                .append("g")
                .attr("class", "cell")
                .attr("transform", d => `translate(0, ${yScale(d.symbol)})`);

            cells.selectAll("rect")
                .data(d => d.values.map(v => ({
                    date: v.date,
                    price: v.price,
                    symbol: d.symbol
                })))
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.date))
                .attr("y", 0)
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip);

            // Add axes
            updateAxes();
        }

        // Update axes based on current scales
        function updateAxes() {
            // Remove existing axes
            svg.selectAll(".axis").remove();

            // Add X axis
            svg.append("g")
                .attr("class", "axis axis-x")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat("%b %d"))
                    .tickSizeOuter(0))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            // Add Y axis
            svg.append("g")
                .attr("class", "axis axis-y")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Stock Symbol");
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            tooltip.style("display", "block")
                .html(`
                    <strong>${d.symbol}</strong><br>
                    Date: ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                    Price: $${d.price.toFixed(2)}
                `);

            // Position tooltip near mouse
            const x = event.pageX + 10;
            const y = event.pageY + 10;

            tooltip.style("left", `${x}px`)
                .style("top", `${y}px`);
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // Handle zoom/pan
        function zoomed(event) {
            heatmap.attr("transform", event.transform);

            // Adjust axis scales
            const newXScale = event.transform.rescaleX(xScale);
            const newYScale = event.transform.rescaleY(yScale);

            // Update axes with new scales
            svg.select(".axis-x")
                .call(d3.axisBottom(newXScale)
                    .tickFormat(d3.timeFormat("%b %d"))
                    .tickSizeOuter(0))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.select(".axis-y")
                .call(d3.axisLeft(newYScale).tickSizeOuter(0));
        }

        // Reset view to default
        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Start auto-updating data
        function startAutoUpdate() {
            if (updateIntervalId) clearInterval(updateIntervalId);

            updateIntervalId = setInterval(() => {
                if (!isLoading) {
                    loadData();
                }
            }, config.updateInterval);
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when page unloads
        window.addEventListener("beforeunload", () => {
            if (updateIntervalId) clearInterval(updateIntervalId);
        });
    </script>
</body>
</html>
