        };

        // Sample stock symbols (in a real app, you'd fetch these from an API)
        const sampleStocks = [
            'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.B', 'JNJ', 'JPM', 'V',
