            'CRM', 'VZ', 'T', 'INTC', 'PEP', 'KO', 'MRK', 'ABT', 'AVGO', 'COST',
            'MCD', 'CSCO', 'QCOM', 'NKE', 'WMT', 'XOM', 'DOW', 'IBM', 'AMD', 'TXN'
        ];

        // Generate mock data
        function generateMockData(stocks, timeframe) {
            const data = [];
            const now = new Date();
            let timePoints;

            // Determine time points based on timeframe
            switch(timeframe) {
                case '1D':
                    timePoints = 24; // hourly
                    break;
                case '1W':
                    timePoints = 7 * 24; // hourly
                    break;
                case '1M':
                    timePoints = 30; // daily
                    break;
                case '3M':
                    timePoints = 90; // daily
                    break;
                case '1Y':
                    timePoints = 12; // monthly
                    break;
                default:
                    timePoints = 30;
            }

            // Generate data for each stock
            stocks.forEach(stock => {
                const basePrice = 100 + Math.random() * 1000; // Random base price
                const volatility = 0.01 + Math.random() * 0.05; // Random volatility

                for (let i = 0; i < timePoints; i++) {
                    const date = new Date(now);
                    let timeLabel;

                    switch(timeframe) {
                        case '1D':
                            date.setHours(now.getHours() - i);
                            timeLabel = date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                            break;
                        case '1W':
                            date.setHours(now.getHours() - i);
                            timeLabel = date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], {hour: '2-digit'});
                            break;
                        case '1M':
                            date.setDate(now.getDate() - i);
                            timeLabel = date.toLocaleDateString();
                            break;
                        case '3M':
                            date.setDate(now.getDate() - i * 3);
                            timeLabel = date.toLocaleDateString();
                            break;
                        case '1Y':
                            date.setMonth(now.getMonth() - i);
                            timeLabel = date.toLocaleDateString([], {month: 'short', year: 'numeric'});
                            break;
                        default:
                            date.setDate(now.getDate() - i);
                            timeLabel = date.toLocaleDateString();
                    }

                    // Generate a price with some randomness
                    const price = basePrice * (1 + (Math.random() - 0.5) * volatility * 10);

                    data.push({
                        stock: stock,
                        time: timeLabel,
                        price: price.toFixed(2),
                        change: ((price - basePrice) / basePrice * 100).toFixed(2)
                    });
                }
            });

            return data;
        }

