                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Add axis labels
            g.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 20)
                .style("text-anchor", "middle")
                .text("Time");

            g.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add title
            svg.append("text")
                .attr("x", config.width / 2)
                .attr("y", config.margin.top / 2)
                .attr("text-anchor", "middle")
                .style("font-size", "16px")
                .style("font-weight", "bold")
                .text(`Stock Price Heatmap (${timeframe})`);

            // Add legend
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = [
                { color: colorScale(priceExtent[1]), label: `High ($${priceExtent[1].toFixed(2)})` },
                { color: colorScale((priceExtent[0] + priceExtent[1]) / 2), label: "Mid" },
                { color: colorScale(priceExtent[0]), label: `Low ($${priceExtent[0].toFixed(2)})` }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [width, height]])
                .on("zoom", zoomed);

            svg.call(zoom);

            function zoomed(event) {
                const { transform } = event;
                g.attr("transform", `translate(${config.margin.left},${config.margin.top}) scale(${transform.k}) translate(${transform.x},${transform.y})`);
            }

            // Reset zoom on double click
            svg.on("dblclick", function() {
                svg.transition()
                    .duration(750)
                    .call(zoom.transform, d3.zoomIdentity);
            });
        }

        // Set up event listeners
        document.getElementById("update-btn").addEventListener("click", initHeatmap);

        // Initialize on page load
        document.addEventListener("DOMContentLoaded", function() {
            initHeatmap();

            // Set up automatic updates
            setInterval(initHeatmap, config.updateInterval);
        });
    </script>
</body>
