            margin-right: 5px;
            border: 1px solid #ddd;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Interactive Stock Price Heatmap</h1>

        <div class="controls">
            <div class="control-group">
                <label for="timeframe">Timeframe:</label>
                <select id="timeframe">
                    <option value="1h">1 Hour</option>
                    <option value="4h">4 Hours</option>
                    <option value="1d" selected>1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m">1 Month</option>
                </select>
            </div>

            <div class="control-group">
                <label for="stock-select">Stock:</label>
                <select id="stock-select">
                    <option value="AAPL">AAPL</option>
                    <option value="MSFT">MSFT</option>
                    <option value="GOOGL">GOOGL</option>
                    <option value="AMZN">AMZN</option>
                    <option value="TSLA">TSLA</option>
                </select>
            </div>

            <div class="control-group">
                <label for="update-interval">Update Interval:</label>
                <select id="update-interval">
                    <option value="5000">5 seconds</option>
                    <option value="10000" selected>10 seconds</option>
                    <option value="30000">30 seconds</option>
                    <option value="60000">1 minute</option>
                </select>
            </div>

            <button id="reset-view">Reset View</button>
        </div>

        <div id="heatmap-container"></div>
        <div class="legend" id="legend"></div>
        <div class="tooltip" id="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 50, right: 30, bottom: 50, left: 60 },
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            timeframe: '1d',
            selectedStock: 'AAPL',
            updateInterval: 10000,
            zoom: d3.zoom().scaleExtent([0.5, 10]).on('zoom', zoomed)
        };

        // DOM elements
        const heatmapContainer = d3.select('#heatmap-container');
        const tooltip = d3.select('#tooltip');
        const timeframeSelect = d3.select('#timeframe');
        const stockSelect = d3.select('#stock-select');
        const updateIntervalSelect = d3.select('#update-interval');
        const resetViewButton = d3.select('#reset-view');
        const legendContainer = d3.select('#legend');

        // Data variables
        let data = [];
        let xScale, yScale;
        let svg, heatmapGroup, xAxisGroup, yAxisGroup;
        let updateIntervalId;

        // Initialize the visualization
        init();

        function init() {
            // Set up the SVG container
            svg = heatmapContainer.append('svg')
                .attr('width', config.width)
                .attr('height', config.height)
                .call(config.zoom);

            heatmapGroup = svg.append('g')
                .attr('transform', `translate(${config.margin.left}, ${config.margin.top})`);

            xAxisGroup = svg.append('g')
                .attr('class', 'axis axis--x')
                .attr('transform', `translate(${config.margin.left}, ${config.margin.top + config.height - config.margin.top - config.margin.bottom})`);

            yAxisGroup = svg.append('g')
                .attr('class', 'axis axis--y')
                .attr('transform', `translate(${config.margin.left}, ${config.margin.top})`);

            // Add axis labels
            svg.append('text')
                .attr('class', 'axis-label')
                .attr('x', config.width / 2)
                .attr('y', config.height - 5)
                .style('text-anchor', 'middle')
                .text('Time');

            svg.append('text')
                .attr('class', 'axis-label')
                .attr('transform', 'rotate(-90)')
                .attr('x', -config.height / 2)
                .attr('y', 20)
                .style('text-anchor', 'middle')
                .text('Price Level');

            // Set up event listeners
            timeframeSelect.on('change', function() {
                config.timeframe = this.value;
                fetchData();
            });

            stockSelect.on('change', function() {
                config.selectedStock = this.value;
                fetchData();
            });

            updateIntervalSelect.on('change', function() {
                config.updateInterval = +this.value;
                clearInterval(updateIntervalId);
                updateIntervalId = setInterval(fetchData, config.updateInterval);
            });

            resetViewButton.on('click', resetView);

            // Create legend
            createLegend();

            // Initial data fetch
            fetchData();

            // Set up auto-update
            updateIntervalId = setInterval(fetchData, config.updateInterval);
        }

        function createLegend() {
            const legendData = [
                { value: -0.1, color: config.colorScale(-0.1) },
                { value: -0.05, color: config.colorScale(-0.05) },
                { value: 0, color: config.colorScale(0) },
                { value: 0.05, color: config.colorScale(0.05) },
                { value: 0.1, color: config.colorScale(0.1) }
            ];

            const legend = legendContainer.selectAll('.legend-item')
                .data(legendData)
                .enter()
                .append('div')
                .attr('class', 'legend-item');

            legend.append('div')
                .attr('class', 'legend-color')
                .style('background-color', d => d.color);

            legend.append('span')
                .text(d => `${(d.value * 100).toFixed(1)}%`);
        }

        function fetchData() {
            // In a real application, this would fetch from an API
            // For demo purposes, we'll generate mock data
            generateMockData();
            updateVisualization();
        }

        function generateMockData() {
            const now = new Date();
            const timePoints = [];
            const priceLevels = [];

            // Generate time points based on selected timeframe
            const timeframeMinutes = {
                '1h': 60,
                '4h': 240,
                '1d': 1440,
                '1w': 10080,
                '1m': 43200
            }[config.timeframe];

            const interval = Math.max(1, Math.floor(timeframeMinutes / 100));

            for (let i = 0; i <= timeframeMinutes; i += interval) {
                const time = new Date(now.getTime() - (timeframeMinutes - i) * 60 * 1000);
                timePoints.push(time);
            }

            // Generate price levels (centered around current price)
            const basePrice = 100 + Math.random() * 200;
            const priceRange = basePrice * 0.2; // ±20% range

            for (let i = 0; i < 50; i++) {
                priceLevels.push(basePrice - priceRange / 2 + (priceRange * i / 50));
            }

            // Generate heatmap data
            data = [];
            const baseVolume = 1000000;

            timePoints.forEach(time => {
                priceLevels.forEach(price => {
                    // Calculate percentage change from base price
                    const pctChange = (price - basePrice) / basePrice;

                    // Generate a random volume that's higher for prices near the current price
                    const volumeMultiplier = 1 + (1 - Math.abs(pctChange)) * 2;
                    const volume = baseVolume * volumeMultiplier * (0.8 + Math.random() * 0.4);

                    // Add some randomness to the percentage change
                    const adjustedPctChange = pctChange + (Math.random() * 0.02 - 0.01);

                    data.push({
                        time: time,
                        price: price,
                        pctChange: adjustedPctChange,
                        volume: volume
                    });
                });
            });
        }

        function updateVisualization() {
            if (data.length === 0) return;

            // Set up scales
            const times = data.map(d => d.time);
            const prices = data.map(d => d.price);

            xScale = d3.scaleTime()
                .domain(d3.extent(times))
                .range([0, config.width - config.margin.left - config.margin.right]);

            yScale = d3.scaleLinear()
                .domain(d3.extent(prices))
                .range([config.height - config.margin.top - config.margin.bottom, 0]);

            // Create heatmap
            const heatmap = heatmapGroup.selectAll('.heatmap-cell')
                .data(data, d => `${d.time}-${d.price}`);

            // Update existing cells
            heatmap.attr('x', d => xScale(d.time))
                .attr('y', d => yScale(d.price))
                .attr('width', (config.width - config.margin.left - config.margin.right) / (times.length / priceLevels.length))
                .attr('height', (config.height - config.margin.top - config.margin.bottom) / priceLevels.length)
                .attr('fill', d => config.colorScale(d.pctChange));

            // Add new cells
            heatmap.enter()
                .append('rect')
                .attr('class', 'heatmap-cell')
                .attr('x', d => xScale(d.time))
                .attr('y', d => yScale(d.price))
                .attr('width', (config.width - config.margin.left - config.margin.right) / (times.length / priceLevels.length))
                .attr('height', (config.height - config.margin.top - config.margin.bottom) / priceLevels.length)
                .attr('fill', d => config.colorScale(d.pctChange))
                .on('mouseover', showTooltip)
                .on('mouseout', hideTooltip);

            // Remove old cells
            heatmap.exit().remove();

            // Update axes
            updateAxes();
        }

        function updateAxes() {
            const xAxis = d3.axisBottom(xScale)
                .ticks(Math.min(10, data.length / 10))
                .tickFormat(d3.timeFormat('%H:%M'));

            const yAxis = d3.axisLeft(yScale)
                .ticks(10)
                .tickFormat(d3.format('$.2f'));

            xAxisGroup.call(xAxis);
            yAxisGroup.call(yAxis);
        }

        function showTooltip(event, d) {
            tooltip.style('display', 'block')
                .style('left', `${event.pageX + 10}px`)
                .style('top', `${event.pageY + 10}px`)
                .html(`
                    <strong>${config.selectedStock}</strong><br>
                    Time: ${d3.timeFormat('%Y-%m-%d %H:%M')(d.time)}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${(d.pctChange * 100).toFixed(2)}%<br>
                    Volume: ${d3.format(',')(d.volume)}
                `);
        }

        function hideTooltip() {
            tooltip.style('display', 'none');
        }

        function zoomed(event) {
            const transform = event.transform;
            heatmapGroup.attr('transform', `translate(${config.margin.left}, ${config.margin.top}) scale(${transform.k}) translate(${transform.x}, ${transform.y})`);
            xAxisGroup.call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            yAxisGroup.call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        function resetView() {
            svg.transition()
                .duration(750)
                .call(config.zoom.transform, d3.zoomIdentity);
        }

        // Clean up on page unload
        window.addEventListener('beforeunload', () => {
            clearInterval(updateIntervalId);
        });
    </script>
</body>
</html>
```

## Features

1. **Interactive Heatmap**:
   - Color-coded representation of price changes (red for negative, green for positive)
   - Tooltips showing detailed information on hover

2. **Real-Time Updates**:
   - Configurable update interval (5s to 1 minute)
   - Mock data generation simulates real stock price movements

3. **Zoom/Pan Functionality**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan
   - Reset button to return to default view

4. **Customization Options**:
   - Timeframe selection (1 hour to 1 month)
   - Stock selection (AAPL, MSFT, GOOGL, AMZN, TSLA)
   - Adjustable update interval

5. **Visual Enhancements**:
   - Color legend explaining the color scale
   - Properly labeled axes
   - Responsive design

## Implementation Notes

- This uses D3.js for data visualization, which provides excellent support for interactive visualizations.
- The mock data generator simulates realistic stock price movements with volume patterns.
- The zoom/pan functionality is implemented using D3's zoom behavior.
- The code is structured to be easily extended with real API data by replacing the `generateMockData()` function.

To use real stock data, you would replace the `generateMockData()` function with an API call to a financial data provider (like Alpha Vantage, Yahoo Finance, or a similar service).

