## JavaScript (script.js)

```javascript
// Configuration
const config = {
    updateInterval: 5000, // 5 seconds
    initialTimeframe: '1d',
    colorScheme: d3.interpolateRdYlGn,
    margin: { top: 30, right: 30, bottom: 30, left: 100 },
    minZoom: 0.5,
    maxZoom: 5
};

// Global variables
let svg, xScale, yScale, heatmap, tooltip, zoom, xAxis, yAxis;
let data = [];
let stocks = [];
let currentTimeframe = config.initialTimeframe;
let currentStock = 'all';
let lastUpdateTime = null;
let updateIntervalId = null;

// Initialize the visualization
document.addEventListener('DOMContentLoaded', () => {
    initializeUI();
    initializeHeatmap();
    fetchInitialData();
    startAutoUpdate();
});

// Initialize UI elements
function initializeUI() {
    // Timeframe selector
    document.getElementById('timeframe').addEventListener('change', (e) => {
        currentTimeframe = e.target.value;
        fetchData();
    });

    // Stock selector
    document.getElementById('stock-select').addEventListener('change', (e) => {
        currentStock = e.target.value;
        updateHeatmap();
    });

    // Refresh button
    document.getElementById('refresh-btn').addEventListener('click', () => {
        fetchData();
    });

    // Zoom buttons
    document.getElementById('zoom-in').addEventListener('click', () => {
        zoom.scaleBy(svg.transition().duration(500), 1.2);
    });

    document.getElementById('zoom-out').addEventListener('click', () => {
        zoom.scaleBy(svg.transition().duration(500), 0.8);
    });

    document.getElementById('reset-zoom').addEventListener('click', () => {
        svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
    });
}

// Initialize the heatmap SVG
function initializeHeatmap() {
    const container = d3.select('#heatmap-container');
    const width = container.node().getBoundingClientRect().width;
    const height = container.node().getBoundingClientRect().height;

    // Remove any existing SVG
    container.select('svg').remove();

    // Create new SVG
    svg = container.append('svg')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    tooltip = d3.select('.tooltip');

    // Create zoom behavior
    zoom = d3.zoom()
        .scaleExtent([config.minZoom, config.maxZoom])
        .on('zoom', zoomed);

    // Apply zoom to SVG
    svg.call(zoom);

    // Create main group for heatmap
    heatmap = svg.append('g')
        .attr('class', 'heatmap-group');

    // Create axes groups
    xAxis = svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0,${config.margin.top})`);

    yAxis = svg.append('g')
        .attr('class', 'y-axis')
        .attr('transform', `translate(${config.margin.left},0)`);
}

// Handle zoom events
function zoomed(event) {
    heatmap.attr('transform', event.transform);
    xAxis.call(d3.axisTop(xScale).scale(event.transform.rescaleX(xScale)));
    yAxis.call(d3.axisLeft(yScale).scale(event.transform.rescaleY(yScale)));
}

// Fetch initial data
function fetchInitialData() {
    showLoading(true);

    // In a real application, you would fetch from an API
    // For this example, we'll generate mock data
    setTimeout(() => {
        generateMockData();
        populateStockSelector();
        updateHeatmap();
        showLoading(false);
        updateStatus();
    }, 1000);
}

// Start auto-updating the data
function startAutoUpdate() {
    if (updateIntervalId) clearInterval(updateIntervalId);

    updateIntervalId = setInterval(() => {
        fetchData();
    }, config.updateInterval);
}

// Fetch updated data
function fetchData() {
    // In a real application, you would fetch from an API
    // For this example, we'll update the mock data
    updateMockData();
    updateHeatmap();
    updateStatus();
}

// Generate mock stock data
function generateMockData() {
    const now = new Date();
    const timeframes = {
        '1h': { count: 60, interval: 60 * 1000 }, // 1 minute intervals
        '4h': { count: 240, interval: 15 * 60 * 1000 }, // 15 minute intervals
        '1d': { count: 24, interval: 60 * 60 * 1000 }, // 1 hour intervals
        '1w': { count: 168, interval: 60 * 60 * 1000 }, // 1 hour intervals
        '1m': { count: 30, interval: 24 * 60 * 60 * 1000 } // 1 day intervals
    };

    const tf = timeframes[currentTimeframe];
    const timestamps = Array.from({ length: tf.count }, (_, i) => {
        return new Date(now.getTime() - (tf.count - i) * tf.interval);
    });

    // Generate 10-20 stocks
    const stockCount = Math.floor(Math.random() * 11) + 10;
    stocks = Array.from({ length: stockCount }, (_, i) => `STOCK-${String.fromCharCode(65 + i)}`);

    data = stocks.flatMap(stock => {
        return timestamps.map(time => {
            // Generate a random price change between -5% and +5%
            const change = (Math.random() * 10 - 5) / 100;
            const price = 100 + (Math.random() * 200); // Base price between 100 and 300

            return {
                stock,
                time: time.toISOString(),
                price: price * (1 + change),
                change: change
            };
        });
    });
}

// Update mock data with new values
function updateMockData() {
    const now = new Date();
    const timeframes = {
        '1h': { count: 60, interval: 60 * 1000 }, // 1 minute intervals
        '4h': { count: 240, interval: 15 * 60 * 1000 }, // 15 minute intervals
        '1d': { count: 24, interval: 60 * 60 * 1000 }, // 1 hour intervals
        '1w': { count: 168, interval: 60 * 60 * 1000 }, // 1 hour intervals
        '1m': { count: 30, interval: 24 * 60 * 60 * 1000 } // 1 day intervals
    };

    const tf = timeframes[currentTimeframe];
    const newTimestamp = new Date(now.getTime() - tf.interval);

    // Remove oldest data point for each stock
    const timestamps = data
        .filter(d => d.stock === stocks[0])
        .map(d => new Date(d.time))
        .sort((a, b) => a - b);

    if (timestamps.length > 0) {
        const oldestTime = timestamps[0];
        data = data.filter(d => new Date(d.time) > oldestTime);
    }

    // Add new data point for each stock
    stocks.forEach(stock => {
        // Generate a random price change between -2% and +2%
        const change = (Math.random() * 4 - 2) / 100;
        const lastPrice = data.find(d => d.stock === stock && new Date(d.time) === timestamps[timestamps.length - 1])?.price || 100;
        const newPrice = lastPrice * (1 + change);

        data.push({
            stock,
            time: newTimestamp.toISOString(),
            price: newPrice,
            change: change
        });
    });
}

// Populate the stock selector dropdown
function populateStockSelector() {
    const select = document.getElementById('stock-select');

    // Clear existing options except the first one
    while (select.options.length > 1) {
        select.remove(1);
    }

    // Add stock options
    stocks.forEach(stock => {
        const option = document.createElement('option');
        option.value = stock;
        option.textContent = stock;
        select.appendChild(option);
    });
}

// Update the heatmap visualization
function updateHeatmap() {
    const container = d3.select('#heatmap-container');
    const width = container.node().getBoundingClientRect().width;
    const height = container.node().getBoundingClientRect().height;

    // Filter data based on selected stock
    let filteredData = data;
    if (currentStock !== 'all') {
        filteredData = data.filter(d => d.stock === currentStock);
    }

    // Get unique stocks and times
    const uniqueStocks = [...new Set(filteredData.map(d => d.stock))];
    const uniqueTimes = [...new Set(filteredData.map(d => d.time))].sort();

    // Set up scales
    xScale = d3.scaleBand()
        .domain(uniqueTimes)
        .range([config.margin.left, width - config.margin.right])
        .padding(0.01);

    yScale = d3.scaleBand()
        .domain(uniqueStocks)
        .range([config.margin.top, height - config.margin.bottom])
        .padding(0.01);

    // Get price range for color scale
    const prices = filteredData.map(d => d.price);
    const minPrice = d3.min(prices);
    const maxPrice = d3.max(prices);

    const colorScale = d3.scaleSequential(config.colorScheme)
        .domain([minPrice, maxPrice]);

    // Update axes
    xAxis.call(d3.axisTop(xScale)
        .tickFormat(d => {
            const date = new Date(d);
            return currentTimeframe === '1h' ? date.toLocaleTimeString() :
                   currentTimeframe === '4h' ? date.toLocaleTimeString() :
                   currentTimeframe === '1d' ? date.toLocaleTimeString() :
                   currentTimeframe === '1w' ? date.toLocaleDateString() + ' ' + date.toLocaleTimeString() :
                   date.toLocaleDateString();
        })
        .tickSizeOuter(0));

    yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

    // Update heatmap cells
    const cells = heatmap.selectAll('.cell')
        .data(filteredData, d => `${d.stock}-${d.time}`);

    // Remove old cells
    cells.exit().remove();

    // Add new cells
    cells.enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.time))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.price))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip)
        .on('mousemove', moveTooltip);

    // Update existing cells
    cells.transition()
        .duration(500)
        .attr('x', d => xScale(d.time))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.price));

    // Update legend
    updateLegend(colorScale, minPrice, maxPrice);
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style('opacity', 1)
        .html(`
            <strong>${d.stock}</strong><br>
            Time: ${new Date(d.time).toLocaleString()}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${(d.change * 100).toFixed(2)}%
        `);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style('opacity', 0);
}

// Move tooltip with mouse
function moveTooltip(event) {
    tooltip.style('left', `${event.pageX + 10}px`)
        .style('top', `${event.pageY + 10}px`);
}

// Update the legend
function updateLegend(colorScale, minPrice, maxPrice) {
    const legend = d3.select('#legend');
    legend.selectAll('*').remove();

    // Create legend items
    const legendItems = [
        { value: minPrice, label: `$${minPrice.toFixed(2)}` },
        { value: (minPrice + maxPrice) / 2, label: `$${((minPrice + maxPrice) / 2).toFixed(2)}` },
        { value: maxPrice, label: `$${maxPrice.toFixed(2)}` }
    ];

    legendItems.forEach(item => {
        const legendItem = legend.append('div')
            .attr('class', 'legend-item');

        legendItem.append('div')
            .attr('class', 'legend-color')
            .style('background-color', colorScale(item.value));

        legendItem.append('div')
            .text(item.label);
    });
}

// Update status message
function updateStatus() {
    lastUpdateTime = new Date();
    document.getElementById('status').textContent =
        `Last updated: ${lastUpdateTime.toLocaleTimeString()}`;
}

// Show/hide loading indicator
function showLoading(show) {
    const loading = d3.select('.loading');
    if (show) {
        loading.style('display', 'block');
    } else {
        loading.style('display', 'none');
    }
}

// Handle window resize
window.addEventListener('resize', () => {
    updateHeatmap();
});
```

