    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 20, right: 20, bottom: 60, left: 80 },
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            timeFormat: "%Y-%m-%d",
            dateFormat: d3.timeParse("%Y-%m-%d"),
            updateInterval: 30000 // Default 30 seconds
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select("#tooltip");
        const timeframeSelect = d3.select("#timeframe");
        const stockSelect = d3.select("#stock-select");
        const updateIntervalSelect = d3.select("#update-interval");
        const refreshBtn = d3.select("#refresh-btn");
        const legendContainer = d3.select("#legend");

        // Data variables
        let stockData = [];
        let timePoints = [];
        let selectedStocks = ["AAPL", "MSFT", "GOOGL", "AMZN"];
        let timeframe = "5y";
        let updateTimer;

        // Initialize the visualization
        function init() {
            // Set up event listeners
            timeframeSelect.on("change", handleTimeframeChange);
            stockSelect.on("change", handleStockSelection);
            updateIntervalSelect.on("change", handleUpdateIntervalChange);
            refreshBtn.on("click", fetchData);

            // Initial data fetch
            fetchData();

            // Set up periodic updates
            startPeriodicUpdates();
        }

        // Handle timeframe selection change
        function handleTimeframeChange() {
            timeframe = this.value;
            fetchData();
        }

        // Handle stock selection change
        function handleStockSelection() {
            selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
            updateVisualization();
        }

        // Handle update interval change
        function handleUpdateIntervalChange() {
            config.updateInterval = +this.value;
            restartPeriodicUpdates();
        }

        // Start periodic updates
        function startPeriodicUpdates() {
            updateTimer = setInterval(fetchData, config.updateInterval);
        }

        // Restart periodic updates with new interval
        function restartPeriodicUpdates() {
            clearInterval(updateTimer);
            startPeriodicUpdates();
        }

        // Fetch stock data from API
        async function fetchData() {
            try {
                // Show loading indicator
                heatmapContainer.select(".loading").style("display", "block");

                // In a real application, you would fetch from a stock API
                // For this demo, we'll use mock data
                const mockData = generateMockData();

                // Process the data
                processData(mockData);

                // Update the visualization
                updateVisualization();

                // Hide loading indicator
                heatmapContainer.select(".loading").style("display", "none");
            } catch (error) {
                console.error("Error fetching data:", error);
                heatmapContainer.select(".loading").text("Error loading data. Please try again.");
            }
        }

        // Generate mock data for demonstration
        function generateMockData() {
            const symbols = ["AAPL", "MSFT", "GOOGL", "AMZN", "META", "TSLA", "NVDA", "JPM", "V"];
            const today = new Date();
            const data = [];

            // Determine date range based on timeframe
            let startDate;
            switch (timeframe) {
                case "1d": startDate = new Date(today); startDate.setDate(today.getDate() - 1); break;
                case "5d": startDate = new Date(today); startDate.setDate(today.getDate() - 5); break;
                case "1m": startDate = new Date(today); startDate.setMonth(today.getMonth() - 1); break;
                case "3m": startDate = new Date(today); startDate.setMonth(today.getMonth() - 3); break;
                case "1y": startDate = new Date(today); startDate.setFullYear(today.getFullYear() - 1); break;
                default: // 5y
                    startDate = new Date(today); startDate.setFullYear(today.getFullYear() - 5);
            }

            // Generate dates in the range
            const dates = [];
            for (let d = new Date(startDate); d <= today; d.setDate(d.getDate() + 1)) {
                dates.push(new Date(d));
            }

            // Generate random data for each symbol and date
            symbols.forEach(symbol => {
                dates.forEach(date => {
                    // Generate a random percentage change between -10% and +10%
                    const change = (Math.random() * 20 - 10) / 100;

                    data.push({
                        symbol: symbol,
                        date: date.toISOString().split('T')[0],
                        change: change
                    });
                });
            });

            return data;
        }

        // Process the raw data into a more usable format
        function processData(rawData) {
            // Group data by symbol
            const grouped = d3.group(rawData, d => d.symbol);

            // Convert to array of objects with symbol and values
            stockData = Array.from(grouped, ([symbol, values]) => ({
                symbol,
                values: values.map(v => ({
                    date: config.dateFormat(v.date),
                    change: v.change
                }))
            }));

            // Extract unique time points (dates)
            timePoints = [...new Set(rawData.map(d => config.dateFormat(d.date)))].sort((a, b) => a - b);
        }

        // Update the visualization
        function updateVisualization() {
            // Clear previous visualization
            heatmapContainer.selectAll("svg").remove();

            // Filter data for selected stocks
            const filteredData = stockData.filter(d => selectedStocks.includes(d.symbol));

            if (filteredData.length === 0) {
                heatmapContainer.select(".loading").text("No data available for selected stocks.").style("display", "block");
                return;
            }

            // Calculate dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = heatmapContainer.append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create scales
            const xScale = d3.scaleBand()
                .domain(timePoints.map(d => d))
                .range([0, width])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(filteredData.map(d => d.symbol))
                .range([0, height])
                .padding(0.01);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [width, height]])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.attr("transform", `translate(${config.margin.left + transform.x},${config.margin.top + transform.y}) scale(${transform.k})`);
                });

            // Apply zoom to the SVG
            svg.call(zoom);

            // Add rectangles for each data point
            const cells = svg.selectAll(".cell")
                .data(filteredData.flatMap(d =>
                    d.values.map(v => ({
                        symbol: d.symbol,
                        date: v.date,
                        change: v.change
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip);

            // Add x-axis
            svg.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${height})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat(config.timeFormat))
                    .tickSizeOuter(0))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            // Add y-axis
            svg.append("g")
                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Date");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Update legend
            updateLegend();
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            tooltip.style("display", "block")
                .html(`
                    <strong>${d.symbol}</strong><br>
                    Date: ${d3.timeFormat(config.timeFormat)(d.date)}<br>
                    Change: ${(d.change * 100).toFixed(2)}%
                `)
                .style("left", `${event.pageX + 10}px`)
                .style("top", `${event.pageY - 28}px`);
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // Update the color legend
        function updateLegend() {
            legendContainer.selectAll("*").remove();

            // Create legend items
            const legendItems = legendContainer.selectAll(".legend-item")
                .data([-0.1, -0.05, 0, 0.05, 0.1])
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => config.colorScale(d));

            legendItems.append("span")
                .text(d => `${(d * 100).toFixed(0)}%`);
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
