                    <option value="TSLA">Tesla (TSLA)</option>
                </select>
            </div>

            <div class="time-range">
                <label for="time-range">Time Range:</label>
                <select id="time-range">
                    <option value="1d">1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m" selected>1 Month</option>
                    <option value="3m">3 Months</option>
                    <option value="1y">1 Year</option>
                </select>
            </div>

            <button class="refresh-btn" id="refresh-btn">Refresh Data</button>
        </div>

        <div class="heatmap-container">
            <div class="loading" id="loading">
                <div class="spinner"></div>
            </div>
            <div id="heatmap"></div>
            <div class="tooltip" id="tooltip"></div>
        </div>

        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 800,
            height: 500,
            margin: { top: 30, right: 30, bottom: 30, left: 60 },
            colors: ["#006837", "#1a9850", "#66bd63", "#a6d96a", "#d9ef8b", "#ffffbf", "#fee08b", "#fdae61", "#f46d43", "#d73027", "#a50026"],
            minZoom: 0.5,
            maxZoom: 10
        };

        // Mock data generator for demonstration
        function generateMockData(stockSymbol, timeRange) {
            const now = new Date();
            let interval, count;

            switch(timeRange) {
                case '1d':
                    interval = 15 * 60 * 1000; // 15 minutes
                    count = 24 * 4; // 4 intervals per hour
                    break;
                case '1w':
                    interval = 60 * 60 * 1000; // 1 hour
                    count = 7 * 24; // 24 hours per day
                    break;
                case '1m':
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    count = 30 * 4; // 4 intervals per day
                    break;
                case '3m':
                    interval = 12 * 60 * 60 * 1000; // 12 hours
                    count = 90 * 2; // 2 intervals per day
                    break;
                case '1y':
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    count = 365;
                    break;
                default:
                    interval = 6 * 60 * 60 * 1000;
                    count = 30 * 4;
            }

            const data = [];
            const basePrice = 100 + Math.random() * 100;

            for (let i = 0; i < count; i++) {
                const time = new Date(now.getTime() - (count - i) * interval);
                const price = basePrice + (Math.random() - 0.5) * 20;

                data.push({
                    time: time,
                    price: price.toFixed(2),
                    volume: Math.floor(Math.random() * 1000000),
                    change: ((price - basePrice) / basePrice * 100).toFixed(2)
                });
            }

            return data;
        }

        // Main visualization function
        function createHeatmap(data, containerId) {
            // Clear previous visualization
            d3.select(`#${containerId}`).selectAll("*").remove();

            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = d3.select(`#${containerId}`)
                .append("svg")
                .attr("width", width + config.margin.left + config.margin.right)
                .attr("height", height + config.margin.top + config.margin.bottom)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create scales
            const xScale = d3.scaleTime()
                .domain(d3.extent(data, d => d.time))
                .range([0, width]);

            const yScale = d3.scaleLinear()
                .domain([0, d3.max(data, d => d.volume)])
                .range([height, 0]);

            const colorScale = d3.scaleQuantile()
                .domain([d3.min(data, d => d.change), d3.max(data, d => d.change)])
                .range(config.colors);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .ticks(Math.min(10, data.length))
                .tickFormat(d3.timeFormat("%b %d"));

            const yAxis = d3.axisLeft(yScale)
                .ticks(5);

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(xAxis);

            svg.append("g")
                .attr("class", "y-axis")
                .call(yAxis);

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 15)
                .style("text-anchor", "middle")
                .text("Volume");

            // Create heatmap cells
            const cellWidth = width / data.length;
            const cellHeight = height / data.length;

            svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", (d, i) => xScale(d.time) - cellWidth / 2)
                .attr("y", d => yScale(d.volume) - cellHeight / 2)
                .attr("width", cellWidth)
                .attr("height", cellHeight)
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    d3.select("#tooltip")
                        .style("opacity", 1)
                        .html(`
                            <strong>Time:</strong> ${d3.timeFormat("%b %d, %H:%M")(d.time)}<br>
                            <strong>Price:</strong> $${d.price}<br>
                            <strong>Volume:</strong> ${d.volume.toLocaleString()}<br>
                            <strong>Change:</strong> ${d.change}%<br>
                        `)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY + 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("opacity", 0);
                });

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([config.minZoom, config.maxZoom])
                .on("zoom", (event) => {
                    const transform = event.transform;

                    // Apply the zoom to the x and y scales
                    const newXScale = transform.rescaleX(xScale);
                    const newYScale = transform.rescaleY(yScale);

                    // Update axes
                    svg.select(".x-axis").call(xAxis.scale(newXScale));
                    svg.select(".y-axis").call(yAxis.scale(newYScale));

                    // Update cells
                    svg.selectAll(".cell")
                        .attr("x", (d, i) => newXScale(d.time) - cellWidth / 2)
                        .attr("y", d => newYScale(d.volume) - cellHeight / 2);
                });

            svg.call(zoom);

            // Create legend
            createLegend(colorScale);

            // Add pan and zoom instructions
            svg.append("text")
                .attr("x", width - 10)
                .attr("y", height - 10)
                .attr("text-anchor", "end")
                .style("font-size", "10px")
                .style("fill", "#666")
                .text("Use mouse wheel to zoom, drag to pan");
        }

        // Create legend
        function createLegend(colorScale) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const thresholds = colorScale.quantiles();

            // Add legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(thresholds)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            legendItems.append("span")
                .text(d => `${d.toFixed(2)}%`);

            // Add the last color
            legend.append("div")
                .attr("class", "legend-item")
                .append("div")
                .attr("class", "legend-color")
                .style("background-color", config.colors[config.colors.length - 1]);

            legend.append("span")
                .text(`>${thresholds[thresholds.length - 1].toFixed(2)}%`);
        }

        // Load and display data
        function loadData() {
            const stockSymbol = d3.select("#stock-select").property("value");
            const timeRange = d3.select("#time-range").property("value");

            // Show loading indicator
            d3.select("#loading").style("display", "block");

            // Simulate API call with timeout
            setTimeout(() => {
                const data = generateMockData(stockSymbol, timeRange);
                createHeatmap(data, "heatmap");

                // Hide loading indicator
                d3.select("#loading").style("display", "none");
            }, 800); // Simulate network delay
        }

        // Initialize the visualization
        document.addEventListener("DOMContentLoaded", () => {
            // Load initial data
            loadData();

            // Set up event listeners
            d3.select("#refresh-btn").on("click", loadData);
            d3.select("#stock-select").on("change", loadData);
            d3.select("#time-range").on("change", loadData);

            // Handle window resize
            window.addEventListener("resize", () => {
                const stockSymbol = d3.select("#stock-select").property("value");
                const timeRange = d3.select("#time-range").property("value");
                const data = generateMockData(stockSymbol, timeRange);
                createHeatmap(data, "heatmap");
            });
        });
    </script>
</body>
</html>
```

