    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 30, right: 30, bottom: 30, left: 80 },
            colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf",
                    "#e0f3f8", "#abd9e9", "#74add1", "#4575b4", "#313695"],
            updateInterval: 5000 // 5 seconds
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select("#tooltip");
        const timeframeSelect = d3.select("#timeframe");
        const stocksSelect = d3.select("#stocks");
        const updateBtn = d3.select("#update-btn");

        // Data variables
        let heatmapData = [];
        let xScale, yScale, colorScale;
        let svg, heatmap, xAxis, yAxis;
        let zoom;

        // Initialize the visualization
        function init() {
            // Create SVG
            svg = heatmapContainer.append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create heatmap group
            heatmap = svg.append("g")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Create scales
            xScale = d3.scaleBand()
                .range([0, config.width - config.margin.left - config.margin.right]);

            yScale = d3.scaleBand()
                .range([0, config.height - config.margin.top - config.margin.bottom]);

            colorScale = d3.scaleQuantile()
                .range(config.colors);

            // Create axes
            xAxis = heatmap.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0, ${config.height - config.margin.top - config.margin.bottom})`);

            yAxis = heatmap.append("g")
                .attr("class", "axis axis--y");

            // Create zoom behavior
            zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Generate initial data
            generateData();

            // Set up event listeners
            timeframeSelect.on("change", generateData);
            updateBtn.on("click", generateData);

            // Set up periodic updates
            setInterval(generateData, config.updateInterval);
        }

        // Generate mock data
        function generateData() {
            const timeframe = timeframeSelect.node().value;
            const selectedStocks = Array.from(stocksSelect.node().selectedOptions)
                .map(option => option.value);

            // Generate time points based on selected timeframe
            const now = new Date();
            let timePoints = [];

            switch(timeframe) {
                case "1D":
                    // 1 minute intervals for 1 day
                    for (let i = 0; i < 24 * 60; i++) {
                        timePoints.push(new Date(now - (24 * 60 - i) * 60 * 1000));
                    }
                    break;
                case "1W":
                    // 1 hour intervals for 1 week
                    for (let i = 0; i < 7 * 24; i++) {
                        timePoints.push(new Date(now - (7 * 24 - i) * 60 * 60 * 1000));
                    }
                    break;
                case "1M":
                    // 6 hour intervals for 1 month
                    for (let i = 0; i < 30 * 4; i++) {
                        timePoints.push(new Date(now - (30 * 4 - i) * 6 * 60 * 60 * 1000));
                    }
                    break;
                case "3M":
                    // 12 hour intervals for 3 months
                    for (let i = 0; i < 90 * 2; i++) {
                        timePoints.push(new Date(now - (90 * 2 - i) * 12 * 60 * 60 * 1000));
                    }
                    break;
                case "1Y":
                    // 1 day intervals for 1 year
                    for (let i = 0; i < 365; i++) {
                        timePoints.push(new Date(now - (365 - i) * 24 * 60 * 60 * 1000));
                    }
                    break;
            }

            // Generate random price data for each stock and time point
            heatmapData = selectedStocks.flatMap(stock => {
                const basePrice = 100 + Math.random() * 1000; // Random base price between 100-1100
                const volatility = 0.01 + Math.random() * 0.05; // Random volatility

                return timePoints.map(time => {
                    // Simulate price movement with some randomness
                    const priceChange = (Math.random() - 0.5) * volatility * basePrice;
                    const price = basePrice + priceChange;

                    return {
                        stock,
                        time,
                        price: parseFloat(price.toFixed(2)),
                        timeString: formatTime(time, timeframe)
                    };
                });
            });

            updateVisualization();
        }

        // Format time based on timeframe
        function formatTime(time, timeframe) {
            const options = {
                "1D": { hour: '2-digit', minute: '2-digit' },
                "1W": { month: 'short', day: 'numeric', hour: '2-digit' },
                "1M": { month: 'short', day: 'numeric' },
                "3M": { month: 'short', day: 'numeric' },
                "1Y": { month: 'short', year: 'numeric' }
            };

            return time.toLocaleDateString('en-US', options[timeframe]);
        }

        // Update the visualization with new data
        function updateVisualization() {
            if (heatmapData.length === 0) return;

            // Get unique stocks and times
            const stocks = [...new Set(heatmapData.map(d => d.stock))];
            const times = [...new Set(heatmapData.map(d => d.timeString))];

            // Update scales
            xScale.domain(times);
            yScale.domain(stocks);

            // Update color scale
            const prices = heatmapData.map(d => d.price);
            colorScale.domain([d3.min(prices), d3.max(prices)]);

            // Update axes
            xAxis.call(d3.axisBottom(xScale)
                .tickSizeOuter(0)
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(times.length / 10) === 0)));

            yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Bind data to heatmap cells
            const cells = heatmap.selectAll(".cell")
                .data(heatmapData, d => `${d.stock}-${d.timeString}`);

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.timeString))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip)
                .on("mousemove", moveTooltip);

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("x", d => xScale(d.timeString))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price));

            // Remove old cells
            cells.exit().remove();

            // Update legend
            updateLegend();
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            tooltip.style("display", "block")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d.timeString}<br>
                    Price: $${d.price.toFixed(2)}
                `);
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // Move tooltip with mouse
        function moveTooltip(event) {
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        }

        // Update the legend
        function updateLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendItems = legend.selectAll(".legend-item")
                .data(colorScale.quantiles())
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            legendItems.append("span")
                .text(d => `$${d.toFixed(2)}`);
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap group
            heatmap.attr("transform",
                `translate(${config.margin.left + transform.x}, ${config.margin.top + transform.y})` +
                ` scale(${transform.k})`);

            // Adjust the scales
            xScale.range([0, (config.width - config.margin.left - config.margin.right) * transform.k]);
            yScale.range([0, (config.height - config.margin.top - config.margin.bottom) * transform.k]);

            // Update the axes
            xAxis.call(d3.axisBottom(xScale)
                .tickSizeOuter(0)
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(xScale.domain().length / 10) === 0)));

            yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Update the heatmap cells
            heatmap.selectAll(".cell")
                .attr("x", d => xScale(d.timeString))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth());
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);
    </script>
