<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div class="control-group">
                <label for="timeframe">Timeframe:</label>
                <select id="timeframe">
                    <option value="1D">1 Day</option>
                    <option value="1W">1 Week</option>
                    <option value="1M" selected>1 Month</option>
                    <option value="3M">3 Months</option>
                    <option value="1Y">1 Year</option>
                </select>
            </div>

            <div class="control-group">
                <label for="stocks">Stocks:</label>
                <select id="stocks" multiple size="5">
                    <option value="AAPL" selected>AAPL</option>
                    <option value="MSFT" selected>MSFT</option>
                    <option value="GOOGL" selected>GOOGL</option>
                    <option value="AMZN" selected>AMZN</option>
                    <option value="TSLA" selected>TSLA</option>
                    <option value="FB" selected>FB</option>
                    <option value="NVDA" selected>NVDA</option>
                    <option value="JPM" selected>JPM</option>
                    <option value="V" selected>V</option>
                    <option value="WMT" selected>WMT</option>
                </select>
            </div>

            <div class="control-group">
                <button id="update-btn">Update Data</button>
                <button id="reset-btn">Reset View</button>
            </div>
        </div>

        <div id="heatmap-container"></div>

        <div class="legend" id="legend"></div>

        <div class="status" id="status">Loading initial data...</div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 20, right: 20, bottom: 60, left: 80 },
            colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
            updateInterval: 5000 // 5 seconds
        };

        // Global variables
        let svg, xScale, yScale, colorScale, tooltip, zoom;
        let data = [];
        let isUpdating = false;
        let updateIntervalId = null;

        // Initialize the visualization
        document.addEventListener('DOMContentLoaded', function() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create tooltip
            tooltip = d3.select("body").append("div")
                .attr("class", "tooltip")
                .style("display", "none");

            // Initialize scales
            xScale = d3.scaleBand();
            yScale = d3.scaleBand();
            colorScale = d3.scaleQuantile().range(config.colors);

            // Initialize zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Set up event listeners
            document.getElementById('update-btn').addEventListener('click', updateData);
            document.getElementById('reset-btn').addEventListener('click', resetView);
            document.getElementById('timeframe').addEventListener('change', updateData);

            // Load initial data
            updateData();

            // Set up periodic updates
            startAutoUpdates();
        });

        // Function to generate mock stock data
        function generateMockData() {
            const stocks = Array.from(document.getElementById('stocks').selectedOptions).map(opt => opt.value);
            const timeframe = document.getElementById('timeframe').value;

            // Determine number of time points based on timeframe
            let timePoints;
            switch(timeframe) {
                case '1D': timePoints = 24; break;
                case '1W': timePoints = 7 * 24; break;
                case '1M': timePoints = 30 * 24; break;
                case '3M': timePoints = 90 * 24; break;
                case '1Y': timePoints = 365; break;
                default: timePoints = 30 * 24;
            }

            // Generate time points
            const now = new Date();
            const times = [];
            for (let i = 0; i < timePoints; i++) {
                const time = new Date(now.getTime() - (timePoints - i) * 3600000); // 1 hour intervals
                times.push(time);
            }

            // Generate data for each stock
            const newData = [];
            stocks.forEach(stock => {
                const basePrice = Math.random() * 100 + 50; // Random base price between 50-150
                const volatility = Math.random() * 0.05 + 0.01; // Random volatility

                times.forEach(time => {
                    // Simulate price movement with some randomness
                    const priceChange = (Math.random() - 0.5) * volatility * basePrice;
                    const price = basePrice + priceChange;

                    newData.push({
                        stock: stock,
                        time: time,
                        price: price,
                        change: priceChange / basePrice * 100 // Percentage change
                    });
                });
            });

            return newData;
        }

        // Function to update the visualization with new data
        function updateData() {
            if (isUpdating) return;

            isUpdating = true;
            document.getElementById('status').textContent = 'Updating data...';

            // Simulate fetching data from a server (in a real app, this would be an API call)
            setTimeout(() => {
                data = generateMockData();
                renderHeatmap();
                isUpdating = false;
                document.getElementById('status').textContent = 'Data updated at ' + new Date().toLocaleTimeString();
            }, 500);
        }

        // Function to render the heatmap
        function renderHeatmap() {
            if (data.length === 0) return;

            // Get selected stocks
            const selectedStocks = Array.from(document.getElementById('stocks').selectedOptions).map(opt => opt.value);

            // Filter data for selected stocks
            const filteredData = data.filter(d => selectedStocks.includes(d.stock));

            // Prepare data for heatmap
            const stocks = [...new Set(filteredData.map(d => d.stock))];
            const times = [...new Set(filteredData.map(d => d.time))].sort((a, b) => a - b);

            // Update scales
            xScale.domain(times)
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            yScale.domain(stocks)
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.1);

            // Update color scale
            const priceExtent = d3.extent(filteredData, d => d.price);
            colorScale.domain(priceExtent);

            // Create a map for quick lookup
            const dataMap = new Map();
            filteredData.forEach(d => {
                dataMap.set(`${d.stock}-${d.time.getTime()}`, d);
            });

            // Remove existing heatmap cells
            svg.selectAll(".heatmap-cell").remove();

            // Add heatmap cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(stocks.flatMap(stock =>
                    times.map(time => ({
                        stock,
                        time,
                        data: dataMap.get(`${stock}-${time.getTime()}`)
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "heatmap-cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => d.data ? colorScale(d.data.price) : "#eee")
                .on("mouseover", function(event, d) {
                    if (!d.data) return;

                    tooltip.style("display", "block")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Time: ${d.time.toLocaleString()}<br>
                            Price: $${d.data.price.toFixed(2)}<br>
                            Change: ${d.data.change.toFixed(2)}%
                        `);

                    // Highlight the cell
                    d3.select(this).attr("stroke", "#000").attr("stroke-width", 2);
                })
                .on("mousemove", function(event) {
                    tooltip.style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("display", "none");
                    d3.select(this).attr("stroke", null);
                });

            // Remove existing axes
            svg.selectAll(".axis").remove();

            // Add X axis
            svg.append("g")
                .attr("class", "axis axis-x")
                .attr("transform", `translate(0,${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d => {
                        // Format time based on timeframe
                        const timeframe = document.getElementById('timeframe').value;
                        if (timeframe === '1D') return d.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'});
                        else if (timeframe === '1W') return d.toLocaleDateString([], {weekday: 'short'});
                        else return d.toLocaleDateString([], {month: 'short', day: 'numeric'});
                    })
                    .ticks(Math.min(10, times.length))
                )
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            // Add Y axis
            svg.append("g")
                .attr("class", "axis axis-y")
                .attr("transform", `translate(${config.margin.left},0)`)
                .call(d3.axisLeft(yScale));

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Stock");

            // Update legend
            updateLegend(priceExtent);
        }

        // Function to update the legend
        function updateLegend(priceExtent) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = colorScale.range().map((color, i) => {
                const values = colorScale.invertExtent(color);
                return {
                    color: color,
                    min: values[0] || priceExtent[0],
                    max: values[1] || priceExtent[1]
                };
            });

            const legendItems = legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legendItems.append("div")
                .text(d => `$${d.min.toFixed(2)} - ${d.max ? `$${d.max.toFixed(2)}` : '+'}`);
        }

        // Function to handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap cells
            svg.selectAll(".heatmap-cell")
                .attr("transform", transform);

            // Apply the transform to the axes
            svg.select(".axis-x")
                .call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));

            svg.select(".axis-y")
                .call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        // Function to reset the view
        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Function to start auto-updating the data
        function startAutoUpdates() {
            if (updateIntervalId) clearInterval(updateIntervalId);

            updateIntervalId = setInterval(() => {
                if (!isUpdating) {
                    updateData();
                }
            }, config.updateInterval);
        }

        // Clean up when the page is unloaded
        window.addEventListener('beforeunload', function() {
            if (updateIntervalId) clearInterval(updateIntervalId);
        });
    </script>
</body>
</html>
```

## Features

1. **Interactive Heatmap**:
   - Visualizes stock prices across time for multiple stocks
   - Color-coded based on price values
   - Tooltips showing detailed information on hover

2. **Real-Time Updates**:
   - Simulates real-time data updates (in a real app, you would connect to a WebSocket or API)
   - Auto-updates every 5 seconds
   - Manual update button available

3. **Zoom/Pan Interactions**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan
   - Reset button to return to default view

4. **Customization Options**:
   - Select different timeframes (1 day to 1 year)
   - Choose which stocks to display
   - Responsive design that works on different screen sizes

5. **Visual Enhancements**:
   - Color-coded legend
   - Status messages showing update times
   - Clean, modern UI with proper spacing and styling

## How to Use

1. Copy the entire code into an HTML file
2. Open the file in a modern web browser
3. Interact with the visualization:
   - Use the controls to change timeframe and selected stocks
   - Hover over cells to see details
   - Zoom and pan using mouse interactions
   - Click "Update Data" for manual refresh
   - Click "Reset View" to return to default zoom/pan

For a production application, you would need to:
1. Replace the mock data generation with real API calls
2. Implement proper error handling
3. Add authentication if needed
4. Optimize for performance with large datasets

