                    switch(currentTimeframe) {
                        case '1d': return d3.timeFormat("%H:%M")(date);
                        case '1w': return d3.timeFormat("%a %H:%M")(date);
                        case '1m':
                        case '3m': return d3.timeFormat("%b %d")(date);
                        case '1y': return d3.timeFormat("%b %Y")(date);
                        default: return d3.timeFormat("%H:%M")(date);
                    }
                })
                .ticks(Math.min(10, times.length));

            const yAxis = d3.axisLeft(yScale);

            svg.select("#x-axis")
                .call(xAxis)
                .selectAll("text")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            svg.select("#y-axis").call(yAxis);
        }

        // Update with real-time data (simulated)
        function updateRealTime() {
            if (stockData.length === 0) return;

            // Simulate new data point for each stock
            const now = new Date();

            stockData.forEach(stock => {
                // Generate random percentage change between -5% and +5%
                const change = (Math.random() * 10 - 5) / 100;

                // Add new data point
                stock.data.push({
                    time: now,
                    change: change
                });

                // Remove oldest data point if we have too many
                if (stock.data.length > 100) {
                    stock.data.shift();
                }
            });

            updateVisualization();
        }

        // Tooltip functions
        function showTooltip(event, d) {
            const tooltip = d3.select("#tooltip");
            tooltip.style("display", "block")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.time)}<br>
                    Change: ${(d.change * 100).toFixed(2)}%
                `);
        }

        function hideTooltip() {
            d3.select("#tooltip").style("display", "none");
        }

        function moveTooltip(event) {
            const tooltip = d3.select("#tooltip");
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        }

        // Set up zoom/pan functionality
        function setupZoom() {
            const svg = d3.select("#heatmap-container svg");
            const heatmapGroup = svg.select("#heatmap-group");

            const zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", (event) => {
                    heatmapGroup.attr("transform",
                        `translate(${config.margin.left}, ${config.margin.top})` +
                        ` scale(${event.transform.k})` +
                        ` translate(${event.transform.x}, ${event.transform.y})`
                    );
                });

            svg.call(zoom);
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
```

