    <script>
        // Configuration
        const config = {
            margin: { top: 50, right: 30, bottom: 80, left: 100 },
            width: 1000,
            height: 500,
            colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
            minPrice: 50,
            maxPrice: 200
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select("#tooltip");
        const timeRangeSelect = d3.select("#time-range");
        const stockCountInput = d3.select("#stock-count");
        const updateIntervalInput = d3.select("#update-interval");
        const applyBtn = d3.select("#apply-btn");
        const resetBtn = d3.select("#reset-btn");
        const legendContainer = d3.select("#legend");

        // Data variables
        let stockData = [];
        let timePoints = [];
        let xScale, yScale, colorScale;
        let zoom;
        let svg;

        // Initialize the visualization
        function init() {
            // Create SVG container
            svg = heatmapContainer.append("svg")
                .attr("width", config.width + config.margin.left + config.margin.right)
                .attr("height", config.height + config.margin.top + config.margin.bottom)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Set up zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Generate initial data
            generateData();

            // Create legend
            createLegend();

            // Set up event listeners
            applyBtn.on("click", () => {
                generateData();
                updateVisualization();
            });

            resetBtn.on("click", resetZoom);

            // Start real-time updates
            startRealTimeUpdates();
        }

        // Generate mock stock data
        function generateData() {
            const days = +timeRangeSelect.node().value;
            const stockCount = +stockCountInput.node().value;

            // Generate time points (hours)
            timePoints = Array.from({ length: days * 24 }, (_, i) => {
                const date = new Date();
                date.setHours(date.getHours() - (days * 24 - i));
                return date;
            });

            // Generate stock symbols
            const stocks = Array.from({ length: stockCount }, (_, i) => `STOCK${i + 1}`);

            // Generate price data
            stockData = stocks.map(stock => {
                const basePrice = Math.random() * (config.maxPrice - config.minPrice) + config.minPrice;
                const volatility = Math.random() * 0.05 + 0.01;

                return {
                    symbol: stock,
                    prices: timePoints.map((time, i) => {
                        // Simulate price movement with some randomness
                        const hours = i % 24;
                        const dailyChange = Math.sin(hours / 24 * Math.PI * 2) * 0.1;

                        // Add some random noise
                        const noise = (Math.random() - 0.5) * 0.05;

                        return {
                            time: time,
                            price: basePrice * (1 + dailyChange + noise)
                        };
                    })
                };
            });
        }

        // Create the legend
        function createLegend() {
            const legendItems = [
                { color: config.colors[0], label: "< " + (config.minPrice + (config.maxPrice - config.minPrice) * 0.2).toFixed(2) },
                { color: config.colors[3], label: (config.minPrice + (config.maxPrice - config.minPrice) * 0.4).toFixed(2) + " - " + (config.minPrice + (config.maxPrice - config.minPrice) * 0.6).toFixed(2) },
                { color: config.colors[6], label: "> " + (config.minPrice + (config.maxPrice - config.minPrice) * 0.8).toFixed(2) }
            ];

            legendContainer.selectAll("*").remove();

            legendContainer.selectAll(".legend-item")
                .data(legendItems)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <div class="legend-text">${d.label}</div>
                `);
        }

        // Update the visualization with new data
        function updateVisualization() {
            // Clear previous visualization
            svg.selectAll("*").remove();

            // Set up scales
            xScale = d3.scaleBand()
                .domain(timePoints.map(d => d.getTime()))
                .range([0, config.width])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(stockData.map(d => d.symbol))
                .range([0, config.height])
                .padding(0.01);

            colorScale = d3.scaleQuantile()
                .domain([config.minPrice, config.maxPrice])
                .range(config.colors);

            // Create heatmap cells
            const cells = svg.selectAll(".cell")
                .data(stockData.flatMap(stock =>
                    stock.prices.map(price => ({
                        symbol: stock.symbol,
                        time: price.time.getTime(),
                        price: price.price
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip);

            // Add x-axis (time)
            svg.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${config.height})`)
                .call(d3.axisBottom(xScale)
                    .tickValues(xScale.domain().filter((d, i) => i % 6 === 0))
                    .tickFormat(d => {
                        const date = new Date(d);
                        return `${date.getMonth()+1}/${date.getDate()} ${date.getHours()}:00`;
                    })
                )
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .attr("text-anchor", "end")
                .attr("class", "axis-label");

            // Add y-axis (stock symbols)
            svg.append("g")
                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const date = new Date(d.time);
            const formattedDate = `${date.getFullYear()}-${(date.getMonth()+1).toString().padStart(2, '0')}-${date.getDate().toString().padStart(2, '0')} ${date.getHours().toString().padStart(2, '0')}:00`;

            tooltip.html(`
                <strong>${d.symbol}</strong><br>
                Time: ${formattedDate}<br>
                Price: $${d.price.toFixed(2)}
            `)
            .style("visibility", "visible")
            .style("top", (event.pageY - 10) + "px")
            .style("left", (event.pageX + 10) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("visibility", "hidden");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap cells
            svg.selectAll(".cell")
                .attr("transform", transform);

            // Update axes
            svg.select(".axis--x")
                .call(d3.axisBottom(xScale.scale(transform.rescaleX(xScale)))
                    .tickValues(xScale.domain().filter((d, i) => i % 6 === 0))
                    .tickFormat(d => {
                        const date = new Date(d);
                        return `${date.getMonth()+1}/${date.getDate()} ${date.getHours()}:00`;
                    })
                )
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .attr("text-anchor", "end");

            svg.select(".axis--y")
                .call(d3.axisLeft(yScale.scale(transform.rescaleY(yScale))));
        }

        // Reset zoom to default
        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Simulate real-time updates
        function startRealTimeUpdates() {
            const interval = +updateIntervalInput.node().value;

            setInterval(() => {
                // Update the latest price for each stock
                stockData.forEach(stock => {
                    const lastPrice = stock.prices[stock.prices.length - 1].price;
                    const change = (Math.random() - 0.5) * 0.5; // Random change between -0.5% and +0.5%
                    const newPrice = lastPrice * (1 + change);

                    // Remove oldest data point if we have more than needed
                    if (stock.prices.length >= timePoints.length) {
                        stock.prices.shift();
                    }

                    // Add new data point
                    const newTime = new Date(timePoints[timePoints.length - 1]);
                    newTime.setHours(newTime.getHours() + 1);
                    stock.prices.push({ time: newTime, price: newPrice });

                    // Update time points
                    timePoints.push(newTime);
                    if (timePoints.length > +timeRangeSelect.node().value * 24) {
                        timePoints.shift();
                    }
                });

                // Update visualization
                updateVisualization();
            }, interval);
        }

        // Initialize the visualization when the page loads
        window.addEventListener("load", init);
    </script>
