            const legend = d3.select("#legend");

            // Clear existing legend
            legend.selectAll("*").remove();

            // Create legend items
            const legendData = [
                { value: -0.1, color: config.colorScale(-0.1), label: "-10%" },
                { value: -0.05, color: config.colorScale(-0.05), label: "-5%" },
                { value: 0, color: config.colorScale(0), label: "0%" },
                { value: 0.05, color: config.colorScale(0.05), label: "+5%" },
                { value: 0.1, color: config.colorScale(0.1), label: "+10%" }
            ];

            const legendItems = legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legendItems.append("span")
                .text(d => d.label);
        }

        // Update data function
        async function updateData() {
            // Show loading indicator
            d3.select("#heatmap-container .loading").style("display", "block");

            try {
                // Get selected stocks and timeframe
                const selectedStocks = Array.from(d3.select("#stocks").node().selectedOptions)
                    .map(option => option.value);
                const timeframe = d3.select("#timeframe").node().value;

                // Fetch mock data (in a real app, this would be an API call)
                heatmapData = await fetchMockStockData(selectedStocks, timeframe);

                // Process data
                const processedData = processData(heatmapData);

                // Update visualization
                updateVisualization(processedData);

                // Hide loading indicator
                d3.select("#heatmap-container .loading").style("display", "none");
            } catch (error) {
                console.error("Error updating data:", error);
                d3.select("#heatmap-container .loading").text("Error loading data. Please try again.");
            }
        }

        // Process data for visualization
        function processData(data) {
            // Flatten the data into an array of objects with stock, time, and value
            const flatData = [];
            const times = new Set();
            const stocks = new Set();

            data.forEach(stockData => {
                stocks.add(stockData.symbol);
                stockData.prices.forEach(price => {
                    times.add(price.time);
                    flatData.push({
                        stock: stockData.symbol,
                        time: price.time,
                        value: price.change
                    });
                });
            });

            // Convert sets to arrays and sort
            const sortedTimes = Array.from(times).sort();
            const sortedStocks = Array.from(stocks).sort();

            return {
                data: flatData,
                times: sortedTimes,
                stocks: sortedStocks
            };
        }

        // Update visualization
        function updateVisualization(processedData) {
            // Update scales
            xScale.domain(processedData.times)
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            yScale.domain(processedData.stocks)
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.05);

            // Update axes
            svg.select(".x-axis")
                .call(d3.axisBottom(xScale)
                    .tickFormat(d => formatTime(d))
                    .tickSizeOuter(0))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.select(".y-axis")
                .call(d3.axisLeft(yScale)
                    .tickSizeOuter(0));

            // Remove existing heatmap cells
            svg.selectAll(".heatmap-cell").remove();

            // Create heatmap cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(processedData.data)
                .enter()
                .append("rect")
                .attr("class", "heatmap-cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.value))
                .on("mouseover", function(event, d) {
                    const tooltip = d3.select("#tooltip");
                    tooltip.style("display", "block")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Time: ${formatTime(d.time)}<br>
                            Change: ${(d.value * 100).toFixed(2)}%
                        `)
                        .style("left", `${event.pageX + 10}px`)
                        .style("top", `${event.pageY + 10}px`);
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("display", "none");
                });
        }

        // Format time for display
        function formatTime(time) {
            const date = new Date(time);
            return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        }

        // Zoom handler
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap cells
            svg.selectAll(".heatmap-cell")
                .attr("transform", transform);

            // Update axes
            svg.select(".x-axis").call(d3.axisBottom(xScale.scale().copy().range(transform.rescaleX(xScale).range())));
            svg.select(".y-axis").call(d3.axisLeft(yScale.scale().copy().range(transform.rescaleY(yScale).range())));
        }

        // Mock data generator (simulates API response)
        async function fetchMockStockData(stocks, timeframe) {
            // Simulate API delay
            await new Promise(resolve => setTimeout(resolve, 500));

            // Generate mock data based on selected stocks and timeframe
            const data = [];
            const now = new Date();
            const timeIntervals = getTimeIntervals(timeframe, now);

            stocks.forEach(stock => {
                const prices = timeIntervals.map(time => {
                    // Generate random price change between -10% and +10%
                    const change = (Math.random() * 0.2 - 0.1).toFixed(4);
                    return {
                        time: time.toISOString(),
                        change: parseFloat(change)
                    };
                });

                data.push({
                    symbol: stock,
                    prices: prices
                });
            });

            return data;
        }

        // Generate time intervals based on timeframe
        function getTimeIntervals(timeframe, endDate) {
            const intervals = [];
            const startDate = new Date(endDate);

            switch (timeframe) {
                case '1d':
                    startDate.setDate(endDate.getDate() - 1);
                    for (let i = 0; i < 24; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 3600000));
                    }
                    break;
                case '1w':
                    startDate.setDate(endDate.getDate() - 7);
                    for (let i = 0; i < 7 * 24; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 3600000));
                    }
                    break;
                case '1m':
                    startDate.setMonth(endDate.getMonth() - 1);
                    for (let i = 0; i < 30; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 24 * 3600000));
                    }
                    break;
                case '3m':
                    startDate.setMonth(endDate.getMonth() - 3);
                    for (let i = 0; i < 90; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 24 * 3600000));
                    }
                    break;
                case '1y':
                    startDate.setFullYear(endDate.getFullYear() - 1);
                    for (let i = 0; i < 365; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 24 * 3600000));
                    }
                    break;
                default:
                    // Default to 1 month
                    startDate.setMonth(endDate.getMonth() - 1);
                    for (let i = 0; i < 30; i++) {
                        intervals.push(new Date(startDate.getTime() + i * 24 * 3600000));
                    }
            }

            return intervals;
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when the page is unloaded
        window.addEventListener("beforeunload", () => {
            if (updateInterval) {
                clearInterval(updateInterval);
            }
        });
    </script>
</body>
</html>
