                renderHeatmap();
                isLoading = false;
                d3.select(".loading").style("display", "none");
            }, 500); // Simulate network delay
        }

        // Update data with new values (simulating real-time updates)
        function updateData() {
            if (isLoading) return;

            const timeframe = document.getElementById("timeframe").value;
            const stock = document.getElementById("stock-select").value;

            // Generate new data points (simulating real-time updates)
            const newData = generateMockUpdate(timeframe, stock);

            // Update existing data with new values
            newData.forEach(newPoint => {
                const existingIndex = currentData.findIndex(d =>
                    d.time === newPoint.time && d.attribute === newPoint.attribute
                );

                if (existingIndex !== -1) {
                    currentData[existingIndex].value = newPoint.value;
                } else {
                    currentData.push(newPoint);
                }
            });

            // Update the visualization
            updateHeatmap();
        }

        // Generate mock data for demonstration
        function generateMockData(timeframe, stock) {
            const data = [];
            const attributes = ["Open", "High", "Low", "Close", "Volume"];
            const now = new Date();

            let timePoints;
            switch(timeframe) {
                case "1h":
                    timePoints = 60; // 1 minute intervals
                    break;
                case "4h":
                    timePoints = 240; // 1 minute intervals
                    break;
                case "1d":
                    timePoints = 24 * 60; // 1 minute intervals
                    break;
                case "1w":
                    timePoints = 7 * 24 * 60; // 1 minute intervals
                    break;
                case "1m":
                    timePoints = 30 * 24 * 60; // 1 minute intervals
                    break;
                default:
                    timePoints = 24 * 60;
            }

            // Generate time points
