        // Generate mock updates for real-time simulation
        function generateMockUpdate(timeframe, stock) {
            const updates = [];
            const attributes = ["Open", "High", "Low", "Close", "Volume"];
            const now = new Date();

            // Determine how many time points to update
            let updatePoints;
            switch(timeframe) {
                case "1h":
                    updatePoints = 1; // Update last minute
                    break;
                case "4h":
                    updatePoints = 1; // Update last minute
                    break;
                case "1d":
                    updatePoints = 1; // Update last minute
                    break;
                case "1w":
                    updatePoints = 5; // Update last 5 minutes
                    break;
                case "1m":
                    updatePoints = 10; // Update last 10 minutes
                    break;
                default:
                    updatePoints = 1;
            }

            // Generate update points
            for (let i = 0; i < updatePoints; i++) {
                const time = new Date(now - i * 60000); // Update most recent points first

                for (const attr of attributes) {
                    let value;
                    if (attr === "Volume") {
                        // Volume is typically much larger
                        value = Math.random() * 1000000 + 100000;
                    } else {
                        // Price values - make them change slightly
                        const basePrice = 100 + Math.random() * 100;
                        value = basePrice + (Math.random() - 0.5) * 5; // Smaller change for updates
                    }

                    updates.push({
                        stock,
                        time,
                        attribute: attr,
                        value: parseFloat(value.toFixed(2))
                    });
                }
            }

            return updates;
        }

        // Render the heatmap
        function renderHeatmap() {
            if (!currentData || currentData.length === 0) return;

            // Get unique times and attributes
            const times = [...new Set(currentData.map(d => d.time))];
            const attributes = [...new Set(currentData.map(d => d.attribute))];

            // Update scales
            xScale.domain(times).range([config.margin.left, config.width - config.margin.right]);
            yScale.domain(attributes).range([config.height - config.margin.bottom, config.margin.top]);

            // Update color scale
            const values = currentData.map(d => d.value);
            colorScale.domain([d3.min(values), d3.max(values)]);

