        // Update the legend
        function updateLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Get the color scale thresholds
            const thresholds = colorScale.quantiles();

            // Create legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(thresholds)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            legendItems.append("span")
                .text((d, i) => {
                    if (i === 0) {
                        return `< ${d.toFixed(2)}`;
                    } else if (i === thresholds.length - 1) {
                        return `≥ ${d.toFixed(2)}`;
                    } else {
                        return `${thresholds[i-1].toFixed(2)} - ${d.toFixed(2)}`;
                    }
                });
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const tooltip = d3.select("#tooltip");
            tooltip.style("visibility", "visible")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.time)}<br>
                    ${d.attribute}: ${d.value.toFixed(2)}<br>
                    Change: ${getChange(d)}
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            d3.select("#tooltip").style("visibility", "hidden");
        }

        // Calculate change (for tooltip)
        function getChange(d) {
            // In a real implementation, you would compare with previous value
            // For this demo, we'll just show a random change
            const change = (Math.random() - 0.5) * 2;
            const percent = (change / d.value) * 100;

            if (change > 0) {
                return `+${change.toFixed(2)} (${percent.toFixed(2)}%)`;
            } else {
                return `${change.toFixed(2)} (${percent.toFixed(2)}%)`;
            }
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the cells
            svg.selectAll(".cell")
                .attr("transform", transform);

            // Update axes
            xAxis.call(d3.axisBottom(xScale.scale().copy().range([config.margin.left, config.width - config.margin.right]))
                .tickFormat(d3.timeFormat("%H:%M"))
                .scale(transform.rescaleX(xScale)));

            yAxis.call(d3.axisLeft(yScale.scale().copy().range([config.height - config.margin.bottom, config.margin.top]))
                .scale(transform.rescaleY(yScale)));
        }

        // Reset view to default
        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Initialize the visualization when the page loads
        window.addEventListener("load", init);

        // Clean up when the page unloads
        window.addEventListener("beforeunload", () => {
            clearInterval(updateIntervalId);
        });
    </script>
