                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Add zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Create scales
            xScale = d3.scaleBand();
            yScale = d3.scaleBand();
            colorScale = d3.scaleQuantile().range(config.colors);

            // Generate initial data
            generateHeatmapData();

            // Draw the heatmap
            drawHeatmap();

            // Add axes
            addAxes();

            // Add legend
            addLegend();

            // Add tooltip
            addTooltip();
        }

        // Generate mock heatmap data
        function generateHeatmapData() {
            const timeframes = {
                '1h': { intervals: 60, label: 'Minute' },
                '4h': { intervals: 24, label: 'Hour' },
                '1d': { intervals: 24, label: 'Hour' },
                '1w': { intervals: 7, label: 'Day' },
                '1m': { intervals: 30, label: 'Day' }
            };

            const currentConfig = timeframes[currentTimeframe];
            const now = new Date();
            const timePoints = [];

            // Generate time points based on timeframe
            for (let i = 0; i < currentConfig.intervals; i++) {
                let date;
                if (currentTimeframe === '1h') {
                    date = new Date(now.getTime() - (60 - i) * 60 * 1000);
                } else if (currentTimeframe === '4h') {
                    date = new Date(now.getTime() - (24 - i) * 4 * 60 * 60 * 1000);
                } else if (currentTimeframe === '1d') {
                    date = new Date(now.getTime() - (24 - i) * 60 * 60 * 1000);
                } else if (currentTimeframe === '1w') {
                    date = new Date(now.getTime() - (7 - i) * 24 * 60 * 60 * 1000);
                } else if (currentTimeframe === '1m') {
                    date = new Date(now.getTime() - (30 - i) * 24 * 60 * 60 * 1000);
                }

                timePoints.push({
                    date: date,
                    label: formatTimeLabel(date, currentTimeframe)
                });
            }

            // Generate random price data for each stock
            heatmapData = selectedStocks.map(stock => {
                const basePrice = 100 + Math.random() * 200;
                const priceData = timePoints.map((time, i) => {
                    // Simulate price movement with some randomness
                    const change = (Math.random() - 0.5) * 5;
                    const price = basePrice + i * change + (Math.random() - 0.5) * 2;

                    return {
                        time: time.date,
                        price: parseFloat(price.toFixed(2)),
                        change: parseFloat(change.toFixed(2))
                    };
                });

                return {
                    stock: stock,
                    data: priceData
                };
            });
        }

        // Format time labels based on timeframe
        function formatTimeLabel(date, timeframe) {
            const options = {
                '1h': { hour: '2-digit', minute: '2-digit' },
                '4h': { hour: '2-digit', minute: '2-digit' },
                '1d': { hour: '2-digit', minute: '2-digit' },
                '1w': { month: 'short', day: 'numeric' },
                '1m': { month: 'short', day: 'numeric' }
            };

            return date.toLocaleTimeString('en-US', options[timeframe]);
        }

        // Draw the heatmap
        function drawHeatmap() {
            // Flatten the data for easier processing
            const flatData = [];
            heatmapData.forEach(stock => {
                stock.data.forEach(point => {
                    flatData.push({
                        stock: stock.stock,
                        time: point.time,
                        price: point.price,
                        change: point.change
                    });
                });
            });

            // Update scales
            const timePoints = heatmapData[0]?.data.map(d => d.time) || [];
            const stocks = heatmapData.map(d => d.stock);

            xScale.domain(timePoints)
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.05);

            yScale.domain(stocks)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.1);

            // Update color scale
            const allChanges = flatData.map(d => d.change);
            colorScale.domain([d3.min(allChanges), d3.max(allChanges)]);

            // Remove existing heatmap if it exists
            svg.selectAll(".heatmap-cell").remove();

            // Add new heatmap cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(flatData)
                .enter()
                .append("rect")
                .attr("class", "heatmap-cell")
                .attr("x", d => xScale(d.time) + config.margin.left)
                .attr("y", d => yScale(d.stock) + config.margin.top)
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    showTooltip(event, d);
                })
                .on("mouseout", hideTooltip);
        }

        // Add axes to the heatmap
        function addAxes() {
            // Remove existing axes if they exist
            svg.selectAll(".axis").remove();

            // Add X axis
            svg.append("g")
                .attr("class", "axis axis-x")
                .attr("transform", `translate(${config.margin.left}, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d => formatTimeLabel(d, currentTimeframe))
                    .tickSizeOuter(0))
                .selectAll("text")
                .attr("class", "axis-label")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            // Add Y axis
            svg.append("g")
                .attr("class", "axis axis-y")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`)
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Stock");
        }

        // Add legend to the heatmap
        function addLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Get the color scale thresholds
            const thresholds = colorScale.quantiles();

            // Add legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(thresholds)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            legendItems.append("span")
                .text(d => `${d.toFixed(2)}%`);

            // Add min and max labels
            legend.append("div")
                .attr("class", "legend-item")
                .html(`<div class="legend-color" style="background-color: ${config.colors[0]}"></div><span>&lt; ${thresholds[0].toFixed(2)}%</span>`);

            legend.append("div")
                .attr("class", "legend-item")
                .html(`<div class="legend-color" style="background-color: ${config.colors[config.colors.length - 1]}"></div><span>&gt; ${thresholds[thresholds.length - 1].toFixed(2)}%</span>`);
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const tooltip = d3.select("#tooltip");
            tooltip.style("visibility", "visible")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${formatTimeLabel(d.time, currentTimeframe)}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change.toFixed(2)}%
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            d3.select("#tooltip").style("visibility", "hidden");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap cells
            svg.selectAll(".heatmap-cell")
                .attr("transform", transform);

            // Apply the transform to the axes
            svg.select(".axis-x")
                .call(d3.axisBottom(xScale.scale(transform.rescaleX(xScale)))
                    .tickFormat(d => formatTimeLabel(d, currentTimeframe))
                    .tickSizeOuter(0))
                .selectAll("text")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            svg.select(".axis-y")
                .call(d3.axisLeft(yScale.scale(transform.rescaleY(yScale))));
        }

        // Update the heatmap with new data
        function updateHeatmap() {
            generateHeatmapData();
            drawHeatmap();
            addAxes();
            addLegend();
        }

        // Start auto-updating the data
        function startAutoUpdate() {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }

            updateIntervalId = setInterval(() => {
                updateHeatmap();
            }, config.updateInterval);
        }

        // Clean up when the page is unloaded
        window.addEventListener('beforeunload', function() {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }
        });
    </script>
</body>
</html>
