// Mock data generator for demonstration
function generateMockData(stocks, timeframe) {
    const now = new Date();
    let interval, count;

    switch(timeframe) {
        case '1d':
            interval = 60 * 60 * 1000; // 1 hour
            count = 24;
            break;
        case '1w':
            interval = 6 * 60 * 60 * 1000; // 6 hours
            count = 24 * 7;
            break;
        case '1m':
            interval = 24 * 60 * 60 * 1000; // 1 day
            count = 30;
            break;
        case '3m':
            interval = 24 * 60 * 60 * 1000; // 1 day
            count = 90;
            break;
        case '1y':
            interval = 7 * 24 * 60 * 60 * 1000; // 1 week
            count = 52;
            break;
        default:
            interval = 24 * 60 * 60 * 1000;
            count = 30;
    }

    const data = [];
    const basePrices = {};

    // Initialize base prices for each stock
    stocks.forEach(stock => {
        basePrices[stock] = 100 + Math.random() * 100;
    });

    // Generate time points
    for (let i = 0; i < count; i++) {
        const time = new Date(now - (count - i) * interval);

        stocks.forEach(stock => {
            // Simulate price movement with some randomness
            const change = (Math.random() - 0.5) * 5;
            basePrices[stock] += change;

            data.push({
                stock: stock,
                time: time,
                price: Math.max(0, basePrices[stock]) // Ensure price doesn't go negative
            });
        });
    }

    return data;
}

// Main heatmap class
class StockHeatmap {
    constructor() {
        this.margin = { top: 20, right: 20, bottom: 60, left: 80 };
        this.width = 800 - this.margin.left - this.margin.right;
        this.height = 500 - this.margin.top - this.margin.bottom;

        this.svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", this.width + this.margin.left + this.margin.right)
            .attr("height", this.height + this.margin.top + this.margin.bottom)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.tooltip = d3.select("#tooltip");

        this.xScale = d3.scaleBand();
        this.yScale = d3.scaleBand();
        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn).domain([0, 200]);

        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        this.data = [];
        this.timeframe = '1m';
        this.selectedStocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'META'];

        this.initControls();
        this.updateData();
    }

    initControls() {
        d3.select("#timeframe").on("change", () => {
            this.timeframe = d3.select("#timeframe").property("value");
            this.updateData();
        });

        d3.select("#stock-select").on("change", () => {
            this.selectedStocks = Array.from(
                d3.select("#stock-select").property("selectedOptions"),
                option => option.value
            );
            this.updateData();
        });

        d3.select("#update-btn").on("click", () => this.updateData());
        d3.select("#reset-btn").on("click", () => this.resetZoom());
    }

    updateData() {
        // In a real implementation, this would fetch from an API
        this.data = generateMockData(this.selectedStocks, this.timeframe);
        this.render();
    }

    render() {
        // Clear previous elements
        this.svg.selectAll("*").remove();

        // Process data for heatmap
        const stocks = [...new Set(this.data.map(d => d.stock))];
        const times = [...new Set(this.data.map(d => d.time))].sort((a, b) => a - b);

        // Update scales
        this.xScale.domain(times)
            .range([0, this.width])
            .padding(0.05);

        this.yScale.domain(stocks)
            .range([0, this.height])
            .padding(0.05);

        // Create color scale based on data range
        const prices = this.data.map(d => d.price);
        const minPrice = d3.min(prices);
        const maxPrice = d3.max(prices);
        this.colorScale.domain([minPrice, maxPrice]);

        // Create heatmap cells
        const cells = this.svg.selectAll(".cell")
            .data(this.data)
            .enter()
            .append("rect")
            .attr("class", "cell")
            .attr("x", d => this.xScale(d.time))
            .attr("y", d => this.yScale(d.stock))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.price))
            .on("mouseover", (event, d) => this.showTooltip(event, d))
            .on("mouseout", () => this.hideTooltip());

        // Add axes
        this.svg.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale)
                .tickFormat(d3.timeFormat("%b %d"))
                .tickSizeOuter(0));

        this.svg.append("g")
            .attr("class", "y-axis")
            .call(d3.axisLeft(this.yScale))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        // Add legend
        this.renderLegend(minPrice, maxPrice);
    }

    renderLegend(minPrice, maxPrice) {
        const legend = d3.select("#legend");
        legend.selectAll("*").remove();

        const steps = 5;
        const stepSize = (maxPrice - minPrice) / steps;

        for (let i = 0; i <= steps; i++) {
            const value = minPrice + i * stepSize;

            legend.append("div")
                .attr("class", "legend-item")
                .html(`
                    <div class="legend-color" style="background-color: ${this.colorScale(value)};"></div>
                    <span>${value.toFixed(2)}</span>
                `);
        }
    }

    showTooltip(event, d) {
        this.tooltip.style("display", "block")
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 10) + "px")
            .html(`
                <strong>${d.stock}</strong><br>
                ${d3.timeFormat("%b %d, %Y %H:%M")(d.time)}<br>
                Price: $${d.price.toFixed(2)}
            `);
    }

    hideTooltip() {
        this.tooltip.style("display", "none");
    }

    zoomed(event) {
        const transform = event.transform;

        // Apply zoom to x and y axes
        this.svg.select(".x-axis").call(
            d3.axisBottom(this.xScale.scale(transform.rescaleX(this.xScale)))
                .tickFormat(d3.timeFormat("%b %d"))
                .tickSizeOuter(0)
        );

        this.svg.select(".y-axis").call(
            d3.axisLeft(this.yScale.scale(transform.rescaleY(this.yScale)))
        );

        // Update cell positions and sizes
        this.svg.selectAll(".cell")
            .attr("x", d => this.xScale(d.time))
            .attr("y", d => this.yScale(d.stock))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth());
    }

    resetZoom() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.transform, d3.zoomIdentity);
    }
}

