## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 50, right: 30, bottom: 50, left: 80 },
    maxZoom: 10,
    minZoom: 0.5,
    updateInterval: 5000 // 5 seconds for real-time updates
};

// State variables
let stockData = [];
let isRealtime = true;
let currentTimeRange = '1m';
let zoomLevel = 1;
let zoomTransform = d3.zoomIdentity;

// DOM elements
const heatmapContainer = d3.select('#heatmap');
const tooltip = d3.select('#tooltip');
const loadingIndicator = d3.select('#loading');
const refreshBtn = d3.select('#refresh-btn');
const toggleRealtimeBtn = d3.select('#toggle-realtime');
const timeRangeSelect = d3.select('#time-range');
const legendContainer = d3.select('#legend');
const zoomInBtn = d3.select('#zoom-in');
const zoomOutBtn = d3.select('#zoom-out');
const resetZoomBtn = d3.select('#reset-zoom');

// Initialize the visualization
function init() {
    // Set up event listeners
    refreshBtn.on('click', fetchData);
    toggleRealtimeBtn.on('click', toggleRealtime);
    timeRangeSelect.on('change', function() {
        currentTimeRange = this.value;
        fetchData();
    });

    zoomInBtn.on('click', () => zoom(1.2));
    zoomOutBtn.on('click', () => zoom(0.8));
    resetZoomBtn.on('click', resetZoom);

    // Initial data fetch
    fetchData();

    // Set up real-time updates
    if (isRealtime) {
        setInterval(fetchData, config.updateInterval);
    }
}

// Fetch data from API (simulated with mock data)
async function fetchData() {
    loadingIndicator.style('display', 'block');

    try {
        // In a real implementation, this would be an API call
        // For demo purposes, we'll generate mock data
        const mockData = generateMockData(currentTimeRange);
        stockData = processData(mockData);

        // Update visualization
        updateVisualization();
    } catch (error) {
        console.error('Error fetching data:', error);
    } finally {
        loadingIndicator.style('display', 'none');
    }
}

// Generate mock data for demonstration
function generateMockData(timeRange) {
    const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
    const now = new Date();
    let daysBack;

    switch(timeRange) {
        case '1d': daysBack = 1; break;
        case '1w': daysBack = 7; break;
        case '1m': daysBack = 30; break;
        case '3m': daysBack = 90; break;
        case '1y': daysBack = 365; break;
        default: daysBack = 30;
    }

    const data = [];
    const startDate = new Date(now);
    startDate.setDate(now.getDate() - daysBack);

    // Generate data points for each stock and date
    for (let stock of stocks) {
        const basePrice = 100 + Math.random() * 200; // Random base price between 100-300
        const volatility = 0.01 + Math.random() * 0.05; // Random volatility

        for (let d = new Date(startDate); d <= now; d.setDate(d.getDate() + 1)) {
            const date = new Date(d);
            const priceChange = (Math.random() - 0.5) * volatility * basePrice;
            const price = basePrice + priceChange;

            data.push({
                stock: stock,
                date: date.toISOString().split('T')[0],
                price: parseFloat(price.toFixed(2)),
                change: parseFloat(priceChange.toFixed(2))
            });
        }
    }

    return data;
}

// Process data into a format suitable for visualization
function processData(rawData) {
    // Group data by stock and date
    const nestedData = d3.group(rawData, d => d.stock, d => d.date);

    // Convert to array of objects with stock, date, and price
    const processedData = [];
    for (const [stock, dates] of nestedData) {
        for (const [date, values] of dates) {
            processedData.push({
                stock: stock,
                date: new Date(date),
                price: values[0].price,
                change: values[0].change
            });
        }
    }

    return processedData;
}

// Update the visualization with new data
function updateVisualization() {
    if (stockData.length === 0) return;

    // Clear previous visualization
    heatmapContainer.selectAll('*').remove();

    // Set up dimensions
    const width = config.width - config.margin.left - config.margin.right;
    const height = config.height - config.margin.top - config.margin.bottom;

    // Create SVG
    const svg = heatmapContainer.append('svg')
        .attr('width', width + config.margin.left + config.margin.right)
        .attr('height', height + config.margin.top + config.margin.bottom)
        .append('g')
        .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

    // Get unique stocks and dates
    const stocks = [...new Set(stockData.map(d => d.stock))];
    const dates = [...new Set(stockData.map(d => d.date))].sort((a, b) => a - b);

    // Set up scales
    const xScale = d3.scaleBand()
        .domain(dates.map(d => d3.timeFormat('%Y-%m-%d')(d)))
        .range([0, width])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, height])
        .padding(0.05);

    // Color scale for price changes
    const colorScale = d3.scaleLinear()
        .domain([d3.min(stockData, d => d.change), 0, d3.max(stockData, d => d.change)])
        .range(['#e74c3c', '#ecf0f1', '#2ecc71']);

    // Create heatmap cells
    svg.selectAll('.cell')
        .data(stockData)
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d3.timeFormat('%Y-%m-%d')(d.date)))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', function(event, d) {
            tooltip.style('opacity', 1)
                .html(`
                    <strong>${d.stock}</strong><br>
                    Date: ${d3.timeFormat('%Y-%m-%d')(d.date)}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}
                `)
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY + 10) + 'px');
        })
        .on('mouseout', function() {
            tooltip.style('opacity', 0);
        });

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat('%b %d'))
        .ticks(Math.min(10, dates.length));

    const yAxis = d3.axisLeft(yScale);

    svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0,${height})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    svg.append('g')
        .attr('class', 'y-axis')
        .call(yAxis);

    // Add axis labels
    svg.append('text')
        .attr('class', 'x-label')
        .attr('x', width / 2)
        .attr('y', height + config.margin.bottom - 10)
        .style('text-anchor', 'middle')
        .text('Date');

    svg.append('text')
        .attr('class', 'y-label')
        .attr('transform', 'rotate(-90)')
        .attr('x', -height / 2)
        .attr('y', -config.margin.left + 20)
        .style('text-anchor', 'middle')
        .text('Stock');

    // Update legend
    updateLegend(colorScale);

    // Set up zoom
    const zoom = d3.zoom()
        .scaleExtent([config.minZoom, config.maxZoom])
        .on('zoom', (event) => {
            zoomTransform = event.transform;
            applyZoom();
        });

    svg.call(zoom);

    // Apply initial zoom if needed
    if (zoomTransform !== d3.zoomIdentity) {
        applyZoom();
    }
}

// Apply zoom transformation
function applyZoom() {
    const svg = heatmapContainer.select('svg g');

    svg.attr('transform',
        `translate(${config.margin.left},${config.margin.top})` +
        ` scale(${zoomTransform.k})` +
        ` translate(${zoomTransform.x},${zoomTransform.y})`
    );

    // Adjust axis labels
    svg.select('.x-axis').call(
        d3.axisBottom(xScale)
            .tickFormat(d3.timeFormat('%b %d'))
            .ticks(Math.min(10, dates.length) / zoomTransform.k)
    );

    svg.select('.y-axis').call(
        d3.axisLeft(yScale)
            .ticks(Math.min(10, stocks.length) / zoomTransform.k)
    );
}

// Zoom function
function zoom(factor) {
    const svg = heatmapContainer.select('svg');
    const currentZoom = zoomTransform.k;
    const newZoom = Math.min(Math.max(currentZoom * factor, config.minZoom), config.maxZoom);

    if (newZoom !== currentZoom) {
        const centerX = svg.node().clientWidth / 2;
        const centerY = svg.node().clientHeight / 2;

        const newTransform = d3.zoomIdentity
            .translate(zoomTransform.x, zoomTransform.y)
            .scale(newZoom)
            .translate(
                (centerX - zoomTransform.x) * (1 - factor),
                (centerY - zoomTransform.y) * (1 - factor)
            );

        zoomTransform = newTransform;
        applyZoom();
    }
}

// Reset zoom
function resetZoom() {
    zoomTransform = d3.zoomIdentity;
    applyZoom();
}

// Toggle real-time updates
function toggleRealtime() {
    isRealtime = !isRealtime;
    toggleRealtimeBtn.html(`<i class="fas fa-bolt"></i> Realtime: ${isRealtime ? 'ON' : 'OFF'}`);

    if (isRealtime) {
        setInterval(fetchData, config.updateInterval);
    } else {
        clearInterval(fetchData);
    }
}

// Update legend
function updateLegend(colorScale) {
    legendContainer.selectAll('*').remove();

    const minChange = colorScale.domain()[0];
    const maxChange = colorScale.domain()[2];

    const legendItems = [
        { label: `Down ${Math.abs(minChange).toFixed(2)}`, color: colorScale(minChange) },
        { label: 'No Change', color: colorScale(0) },
        { label: `Up ${maxChange.toFixed(2)}`, color: colorScale(maxChange) }
    ];

    legendContainer.selectAll('.legend-item')
        .data(legendItems)
        .enter()
        .append('div')
        .attr('class', 'legend-item')
        .html(d => `
            <div class="legend-color" style="background-color: ${d.color};"></div>
            <span>${d.label}</span>
        `);
}

// Initialize the application
init();
