## JavaScript Implementation (app.js)

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Configuration
    const config = {
        width: 1200,
        height: 600,
        margin: { top: 20, right: 20, bottom: 60, left: 80 },
        timeRange: '1m', // Default time range
        refreshInterval: 30000, // 30 seconds
        zoomFactor: 1.2,
        maxZoom: 10,
        minZoom: 0.1
    };

    // DOM elements
    const heatmapContainer = d3.select('#heatmap-container');
    const tooltip = d3.select('.tooltip');
    const timeRangeButtons = d3.selectAll('.time-range button');
    const refreshButton = d3.select('#refresh');
    const zoomInButton = d3.select('#zoom-in');
    const zoomOutButton = d3.select('#zoom-out');
    const resetZoomButton = d3.select('#reset-zoom');

    // Data variables
    let stockData = [];
    let currentZoom = 1;
    let currentTransform = d3.zoomIdentity;

    // Initialize the visualization
    function init() {
        // Set up time range buttons
        timeRangeButtons.on('click', function() {
            timeRangeButtons.classed('active', false);
            d3.select(this).classed('active', true);
            config.timeRange = this.id;
            fetchData();
        });

        // Set up refresh button
        refreshButton.on('click', fetchData);

        // Set up zoom buttons
        zoomInButton.on('click', () => zoom(1.2));
        zoomOutButton.on('click', () => zoom(1/1.2));
        resetZoomButton.on('click', resetZoom);

        // Initial data fetch
        fetchData();

        // Set up periodic refresh
        setInterval(fetchData, config.refreshInterval);
    }

    // Fetch data from API (mock implementation)
    async function fetchData() {
        // Show loading indicator
        heatmapContainer.select('.loading').style('display', 'block');

        try {
            // In a real implementation, you would fetch from a stock API
            // For this example, we'll generate mock data
            stockData = generateMockData(config.timeRange);

            // Process and render data
            processData();
            renderHeatmap();
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            // Hide loading indicator
            heatmapContainer.select('.loading').style('display', 'none');
        }
    }

    // Generate mock data for demonstration
    function generateMockData(timeRange) {
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
        const now = new Date();
        let startDate, interval;

        // Set time range parameters
        switch(timeRange) {
            case '1d':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 1);
                interval = 15 * 60 * 1000; // 15 minutes
                break;
            case '1w':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                interval = 60 * 60 * 1000; // 1 hour
                break;
            case '1m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                interval = 4 * 60 * 60 * 1000; // 4 hours
                break;
            case '3m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 3);
                interval = 12 * 60 * 60 * 1000; // 12 hours
                break;
            case '1y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 1);
                interval = 24 * 60 * 60 * 1000; // 1 day
                break;
            case '5y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 5);
                interval = 7 * 24 * 60 * 60 * 1000; // 1 week
                break;
            default:
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                interval = 4 * 60 * 60 * 1000;
        }

        const data = [];
        const timePoints = [];

        // Generate time points
        for (let time = startDate.getTime(); time <= now.getTime(); time += interval) {
            timePoints.push(new Date(time));
        }

        // Generate data for each stock
        stocks.forEach(stock => {
            let lastPrice = 100 + Math.random() * 100; // Random starting price

            timePoints.forEach(time => {
                // Simulate price movement
                const change = (Math.random() - 0.5) * 2; // Random change between -1 and 1
                lastPrice += change;

                data.push({
                    stock: stock,
                    time: time,
                    price: lastPrice,
                    change: change
                });
            });
        });

        return data;
    }

    // Process data for visualization
    function processData() {
        // Group data by stock and time
        const nestedData = d3.group(stockData, d => d.stock, d => d.time);

        // Convert to array of arrays for heatmap
        const stocks = Array.from(nestedData.keys());
        const times = Array.from(nestedData.get(stocks[0]).keys());

        // Create a 2D array for the heatmap
        const heatmapData = stocks.map(stock => {
            return times.map(time => {
                const values = nestedData.get(stock).get(time);
                // For simplicity, we'll just take the first value if there are multiple
                return values[0];
            });
        });

        return {
            stocks: stocks,
            times: times,
            data: heatmapData
        };
    }

    // Render the heatmap
    function renderHeatmap() {
        // Clear previous visualization
        heatmapContainer.selectAll('svg').remove();

        // Process data
        const { stocks, times, data } = processData();

        // Create SVG
        const svg = heatmapContainer.append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Create group for zoomable content
        const g = svg.append('g')
            .attr('transform', `translate(${config.margin.left}, ${config.margin.top})`);

        // Set up scales
        const xScale = d3.scaleBand()
            .domain(times.map(d => d.getTime()))
            .range([0, config.width - config.margin.left - config.margin.right])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, config.height - config.margin.top - config.margin.bottom])
            .padding(0.05);

        // Color scale
        const colorScale = d3.scaleLinear()
            .domain([d3.min(data.flat(), d => d.change), 0, d3.max(data.flat(), d => d.change)])
            .range(['#ff0000', '#ffff00', '#00ff00']);

        // Create heatmap cells
        const cells = g.selectAll('.cell')
            .data(data.flat())
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', (d, i) => xScale(times[Math.floor(i / stocks.length)].getTime()))
            .attr('y', (d, i) => yScale(stocks[i % stocks.length]))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.change))
            .on('mouseover', function(event, d) {
                tooltip.style('display', 'block')
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${d.time.toLocaleString()}<br>
                        Price: ${d.price.toFixed(2)}<br>
                        Change: ${d.change.toFixed(2)}
                    `);
            })
            .on('mousemove', function(event) {
                tooltip.style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY + 10) + 'px');
            })
            .on('mouseout', function() {
                tooltip.style('display', 'none');
            });

        // Add axes
        const xAxis = d3.axisBottom(xScale)
            .tickFormat(d => new Date(d).toLocaleString())
            .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(times.length / 10) === 0));

        const yAxis = d3.axisLeft(yScale);

        g.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0, ${config.height - config.margin.top - config.margin.bottom})`)
            .call(xAxis)
            .selectAll('text')
            .style('text-anchor', 'end')
            .attr('dx', '-.8em')
            .attr('dy', '.15em')
            .attr('transform', 'rotate(-45)');

        g.append('g')
            .attr('class', 'y-axis')
            .call(yAxis);

        // Add axis labels
        svg.append('text')
            .attr('class', 'x-label')
            .attr('x', config.width / 2)
            .attr('y', config.height - 10)
            .style('text-anchor', 'middle')
            .text('Time');

        svg.append('text')
            .attr('class', 'y-label')
            .attr('transform', 'rotate(-90)')
            .attr('x', -config.height / 2)
            .attr('y', 20)
            .style('text-anchor', 'middle')
            .text('Stock');

        // Set up zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([config.minZoom, config.maxZoom])
            .on('zoom', zoomed);

        svg.call(zoom);

        function zoomed(event) {
            currentTransform = event.transform;
            g.attr('transform', event.transform);
        }

        function zoomBy(factor) {
            const newTransform = currentTransform.scaleBy(factor);
            svg.transition().duration(300).call(zoom.transform, newTransform);
        }

        function resetZoom() {
            svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
        }

        // Expose zoom functions to buttons
        window.zoom = zoomBy;
        window.resetZoom = resetZoom;
    }

    // Initialize the application
    init();
});
