## JavaScript Implementation (script.js)

```javascript
// Configuration
const config = {
    container: '#heatmap-container',
    tooltip: '.tooltip',
    timeRangeButtons: '.time-btn',
    refreshButton: '#refresh-btn',
    defaultTimeRange: '1m',
    updateInterval: 30000, // 30 seconds
    colorScale: d3.scaleLinear()
        .domain([-1, 0, 1])
        .range(['#ff0000', '#ffffff', '#00ff00'])
};

// State
let currentData = null;
let currentTimeRange = config.defaultTimeRange;
let zoomTransform = d3.zoomIdentity;
let updateIntervalId = null;

// Initialize the heatmap
function initHeatmap() {
    // Set up the SVG container
    const container = d3.select(config.container);
    container.selectAll('*').remove();

    const svg = container.append('svg')
        .attr('width', '100%')
        .attr('height', '100%');

    // Add zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on('zoom', (event) => {
            zoomTransform = event.transform;
            updateHeatmap();
        });

    svg.call(zoom);

    // Add tooltip
    const tooltip = d3.select(config.tooltip);

    // Set up time range buttons
    d3.selectAll(config.timeRangeButtons).on('click', function() {
        d3.selectAll(config.timeRangeButtons).classed('active', false);
        d3.select(this).classed('active', true);
        currentTimeRange = d3.select(this).attr('data-range');
        fetchData();
    });

    // Set up refresh button
    d3.select(config.refreshButton).on('click', fetchData);

    // Initial data fetch
    fetchData();

    // Set up automatic updates
    if (updateIntervalId) clearInterval(updateIntervalId);
    updateIntervalId = setInterval(fetchData, config.updateInterval);
}

// Fetch mock data (in a real app, this would connect to a stock API)
async function fetchData() {
    showLoading(true);

    try {
        // Simulate API call with mock data
        const mockData = generateMockData(currentTimeRange);
        currentData = processData(mockData);
        updateHeatmap();
    } catch (error) {
        console.error('Error fetching data:', error);
    } finally {
        showLoading(false);
    }
}

// Generate mock data for demonstration
function generateMockData(timeRange) {
    const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'PG'];
    const dates = generateDateRange(timeRange);

    const data = [];

    stocks.forEach(stock => {
        dates.forEach(date => {
            // Generate random price change between -1 and 1
            const change = (Math.random() * 2) - 1;
            data.push({
                stock,
                date,
                change
            });
        });
    });

    return data;
}

// Generate date range based on time range
function generateDateRange(timeRange) {
    const now = new Date();
    const dates = [];

    switch(timeRange) {
        case '1d':
            // 1 day with hourly data
            for (let i = 0; i < 24; i++) {
                const date = new Date(now);
                date.setHours(now.getHours() - i);
                dates.push(date);
            }
            break;
        case '1w':
            // 1 week with daily data
            for (let i = 0; i < 7; i++) {
                const date = new Date(now);
                date.setDate(now.getDate() - i);
                dates.push(date);
            }
            break;
        case '1m':
            // 1 month with daily data
            for (let i = 0; i < 30; i++) {
                const date = new Date(now);
                date.setDate(now.getDate() - i);
                dates.push(date);
            }
            break;
        case '3m':
            // 3 months with weekly data
            for (let i = 0; i < 12; i++) {
                const date = new Date(now);
                date.setDate(now.getDate() - i * 7);
                dates.push(date);
            }
            break;
        case '1y':
            // 1 year with weekly data
            for (let i = 0; i < 52; i++) {
                const date = new Date(now);
                date.setDate(now.getDate() - i * 7);
                dates.push(date);
            }
            break;
        case '5y':
            // 5 years with monthly data
            for (let i = 0; i < 60; i++) {
                const date = new Date(now);
                date.setMonth(now.getMonth() - i);
                dates.push(date);
            }
            break;
        default:
            // Default to 1 month
            for (let i = 0; i < 30; i++) {
                const date = new Date(now);
                date.setDate(now.getDate() - i);
                dates.push(date);
            }
    }

    return dates.sort((a, b) => a - b);
}

// Process data into a format suitable for the heatmap
function processData(rawData) {
    // Group data by stock
    const stocks = [...new Set(rawData.map(d => d.stock))];
    const dates = [...new Set(rawData.map(d => d.date))].sort((a, b) => a - b);

    // Create a matrix of data
    const matrix = stocks.map(stock => {
        return dates.map(date => {
            const entry = rawData.find(d => d.stock === stock && d.date.getTime() === date.getTime());
            return entry ? entry.change : null;
        });
    });

    return {
        stocks,
        dates,
        matrix
    };
}

// Update the heatmap visualization
function updateHeatmap() {
    if (!currentData) return;

    const container = d3.select(config.container);
    const svg = container.select('svg');
    const tooltip = d3.select(config.tooltip);

    // Clear previous content
    svg.selectAll('*').remove();

    // Set dimensions
    const width = container.node().clientWidth;
    const height = container.node().clientHeight;
    const margin = { top: 40, right: 20, bottom: 60, left: 80 };

    // Apply zoom transform
    const g = svg.append('g')
        .attr('transform', zoomTransform);

    // Calculate cell dimensions
    const cellWidth = (width - margin.left - margin.right) / currentData.dates.length;
    const cellHeight = (height - margin.top - margin.bottom) / currentData.stocks.length;

    // Create scales
    const xScale = d3.scaleBand()
        .domain(currentData.dates.map(d => d.toISOString()))
        .range([margin.left, width - margin.right]);

    const yScale = d3.scaleBand()
        .domain(currentData.stocks)
        .range([margin.top, height - margin.bottom]);

    // Add cells
    g.selectAll('rect')
        .data(currentData.matrix.flatMap((row, i) =>
            row.map((value, j) => ({
                stock: currentData.stocks[i],
                date: currentData.dates[j],
                change: value
            }))
        ))
        .enter()
        .append('rect')
        .attr('x', d => xScale(d.date.toISOString()))
        .attr('y', d => yScale(d.stock))
        .attr('width', cellWidth)
        .attr('height', cellHeight)
        .attr('fill', d => d.change !== null ? config.colorScale(d.change) : '#eee')
        .on('mouseover', function(event, d) {
            if (d.change === null) return;

            tooltip.style('opacity', 1)
                .html(`
                    <strong>${d.stock}</strong><br>
                    ${d.date.toLocaleDateString()}<br>
                    Change: ${(d.change * 100).toFixed(2)}%
                `)
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY + 10) + 'px');
        })
        .on('mouseout', function() {
            tooltip.style('opacity', 0);
        });

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => new Date(d).toLocaleDateString())
        .tickSizeOuter(0);

    const yAxis = d3.axisLeft(yScale)
        .tickSizeOuter(0);

    g.append('g')
        .attr('transform', `translate(0, ${height - margin.bottom})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    g.append('g')
        .attr('transform', `translate(${margin.left}, 0)`)
        .call(yAxis);

    // Add axis labels
    g.append('text')
        .attr('x', width / 2)
        .attr('y', height - 10)
        .style('text-anchor', 'middle')
        .text('Date');

    g.append('text')
        .attr('transform', 'rotate(-90)')
        .attr('y', 20)
        .attr('x', -height / 2)
        .style('text-anchor', 'middle')
        .text('Stock');
}

// Show/hide loading indicator
function showLoading(show) {
    const loading = document.querySelector('.loading');
    loading.style.display = show ? 'block' : 'none';
}

