// Configuration
const config = {
    width: 1000,
    height: 500,
    margin: { top: 20, right: 20, bottom: 50, left: 80 },
    cellSize: 20,
    updateInterval: 5000, // 5 seconds
    colorScale: d3.scaleLinear()
        .domain([-1, 0, 1]) // Percentage change ranges
        .range(["#ff0000", "#ffff00", "#00ff00"])
        .clamp(true)
};

// Sample stock data - in a real app, this would come from an API
const stocks = [
    "AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "BRK.A", "JNJ", "JPM", "V",
    "PG", "NVDA", "HD", "MA", "DIS", "PYPL", "VZ", "ADBE", "CRM", "NFLX"
];

// Initialize the heatmap
function initHeatmap() {
    // Clear any existing SVG
    d3.select("#heatmap-container").selectAll("*").remove();

    // Create SVG element
    const svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Create tooltip
    const tooltip = d3.select("#tooltip");

    // Create zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on("zoom", (event) => {
            g.attr("transform", event.transform);
        });

    // Add zoom to SVG
    svg.call(zoom);

    // Create main group for the heatmap
    const g = svg.append("g")
        .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

    // Add reset zoom button functionality
    d3.select("#reset-zoom").on("click", () => {
        svg.transition()
            .duration(750)
            .call(zoom.transform, d3.zoomIdentity);
    });

    // Time range selector
    d3.select("#time-range").on("change", function() {
        updateHeatmap();
    });

    // Initial data load
    updateHeatmap();

    // Set up periodic updates
    setInterval(updateHeatmap, config.updateInterval);
}

// Update the heatmap with new data
function updateHeatmap() {
    // In a real app, this would fetch data from an API
    const timeRange = d3.select("#time-range").property("value");
    const now = moment();
    let timePoints;

    switch(timeRange) {
        case "1D":
            timePoints = Array.from({length: 24}, (_, i) => now.clone().subtract(i, 'hours'));
            break;
        case "1W":
            timePoints = Array.from({length: 168}, (_, i) => now.clone().subtract(i, 'hours'));
            break;
        case "1M":
            timePoints = Array.from({length: 30}, (_, i) => now.clone().subtract(i, 'days'));
            break;
        case "3M":
            timePoints = Array.from({length: 90}, (_, i) => now.clone().subtract(i, 'days'));
            break;
        case "1Y":
            timePoints = Array.from({length: 365}, (_, i) => now.clone().subtract(i, 'days'));
            break;
        default:
            timePoints = Array.from({length: 30}, (_, i) => now.clone().subtract(i, 'days'));
    }

    // Generate random data for demonstration
    const data = stocks.map(stock => {
        return {
            stock,
            values: timePoints.map(time => {
                // Simulate price change (in percentage)
                // In a real app, this would be actual data
                const change = (Math.random() * 2 - 1) * 5; // -5% to +5%
                return {
                    time: time.format("YYYY-MM-DD HH:mm"),
                    change: change
                };
            })
        };
    });

    // Get the main group
    const g = d3.select("#heatmap-container svg g");

    // Clear previous content
    g.selectAll("*").remove();

    // Set up scales
    const xScale = d3.scaleBand()
        .domain(timePoints.map(t => t.format("YYYY-MM-DD HH:mm")))
        .range([0, config.width - config.margin.left - config.margin.right])
        .padding(0.1);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, config.height - config.margin.top - config.margin.bottom])
        .padding(0.1);

    // Create cells
    const cells = g.selectAll(".cell")
        .data(data.flatMap(d => d.values.map(v => ({stock: d.stock, ...v}))))
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => config.colorScale(d.change / 100)) // Normalize to percentage
        .on("mouseover", function(event, d) {
            d3.select("#tooltip")
                .style("display", "block")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d.time}<br>
                    Change: ${d.change.toFixed(2)}%
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        })
        .on("mouseout", function() {
            d3.select("#tooltip").style("display", "none");
        });

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => moment(d).format("MMM D"))
        .ticks(Math.min(10, timePoints.length));

    const yAxis = d3.axisLeft(yScale);

    g.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0, ${config.height - config.margin.top - config.margin.bottom})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    g.append("g")
        .attr("class", "y-axis")
        .call(yAxis);

    // Add axis labels
    g.append("text")
        .attr("class", "x-label")
        .attr("x", (config.width - config.margin.left - config.margin.right) / 2)
        .attr("y", config.height - config.margin.top - config.margin.bottom + 40)
        .style("text-anchor", "middle")
        .text("Time");

    g.append("text")
        .attr("class", "y-label")
        .attr("transform", "rotate(-90)")
        .attr("x", - (config.height - config.margin.top - config.margin.bottom) / 2)
        .attr("y", -60)
        .style("text-anchor", "middle")
        .text("Stock Symbol");
}

// Initialize the heatmap when the page loads
document.addEventListener("DOMContentLoaded", initHeatmap);
