const sampleStocks = [
    'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.B', 'JNJ', 'V', 'PG',
    'JPM', 'WMT', 'DIS', 'MA', 'NVDA', 'PYPL', 'ADBE', 'NFLX', 'INTC', 'CMCSA',
    'PEP', 'KO', 'XOM', 'CVX', 'T', 'VZ', 'MRK', 'ABT', 'PFE', 'CRM'
];

// Generate mock data for demonstration
function generateMockData(stockCount, timeframe) {
    const stocks = sampleStocks.slice(0, stockCount);
    const now = new Date();
    let startDate, interval, pointsPerStock;

    switch(timeframe) {
        case '1d':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 60 * 60 * 1000; // 1 hour
            pointsPerStock = 24;
            break;
        case '5d':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 5);
            interval = 6 * 60 * 60 * 1000; // 6 hours
            pointsPerStock = 20;
            break;
        case '1m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 24 * 60 * 60 * 1000; // 1 day
            pointsPerStock = 30;
            break;
        case '3m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 24 * 60 * 60 * 1000; // 1 day
            pointsPerStock = 90;
            break;
        case '1y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 7 * 24 * 60 * 60 * 1000; // 1 week
            pointsPerStock = 52;
            break;
        case '5y':
        default:
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 5);
            interval = 30 * 24 * 60 * 60 * 1000; // 1 month
            pointsPerStock = 60;
            break;
    }

    const data = [];
    const basePrices = {};

    // Initialize base prices for each stock
    stocks.forEach(stock => {
        basePrices[stock] = Math.random() * 500 + 50; // Random base price between $50 and $550
    });

    // Generate data points for each stock
    stocks.forEach(stock => {
        let currentTime = new Date(startDate);
        let currentPrice = basePrices[stock];

        for (let i = 0; i < pointsPerStock; i++) {
            // Simulate price movement with some randomness
            const change = (Math.random() - 0.5) * 10; // Random change between -5 and +5
            currentPrice = Math.max(1, currentPrice + change); // Ensure price doesn't go below $1

            data.push({
                stock: stock,
                date: new Date(currentTime),
                price: parseFloat(currentPrice.toFixed(2))
            });

            currentTime = new Date(currentTime.getTime() + interval);
        }
    });

    return data;
}

