        // Create SVG
        const svg = heatmapContainer.append('svg')
            .attr('width', width)
            .attr('height', height);

        // Add zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on('zoom', (event) => {
                svg.select('g').attr('transform', event.transform);
            });

        svg.call(zoom);

        // Add a group for the heatmap content
        const g = svg.append('g');

        // Add loading indicator
        g.append('text')
            .attr('x', width / 2)
            .attr('y', height / 2)
            .attr('text-anchor', 'middle')
            .attr('class', 'loading')
            .text('Loading data...');

        return { svg, g, width, height };
    }

    // Update the heatmap with new data
    function updateHeatmap(data) {
        const { svg, g, width, height } = initHeatmap();

        if (!data || data.length === 0) {
            g.select('.loading').text('No data available');
            return;
        }

        // Process data
        const stocks = [...new Set(data.map(d => d.stock))];
        const dates = [...new Set(data.map(d => d.date.getTime()))].sort((a, b) => a - b);

        // Find price range
        const allPrices = data.map(d => d.price);
        const minPrice = Math.min(...allPrices);
        const maxPrice = Math.max(...allPrices);

        // Create scales
        const xScale = d3.scaleBand()
            .domain(dates.map(d => new Date(d)))
            .range([0, width])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, height])
            .padding(0.05);

        // Create color scale
        const colorScale = d3.scaleLinear()
            .domain([minPrice, (minPrice + maxPrice) / 2, maxPrice])
            .range(config.colors);

        // Remove loading indicator
        g.select('.loading').remove();

        // Add heatmap cells
        g.selectAll('.cell')
            .data(data)
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => xScale(d.date))
            .attr('y', d => yScale(d.stock))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.price))
            .on('mouseover', function(event, d) {
                tooltip.style('visibility', 'visible')
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Date: ${moment(d.date).format('YYYY-MM-DD')}<br>
                        Price: $${d.price.toFixed(2)}
                    `);
            })
            .on('mousemove', function(event) {
                tooltip.style('top', (event.pageY - 10) + 'px')
                    .style('left', (event.pageX + 10) + 'px');
            })
            .on('mouseout', function() {
                tooltip.style('visibility', 'hidden');
            });

        // Add axes
        const xAxis = d3.axisBottom(xScale)
            .tickFormat(d => moment(d).format('YYYY-MM-DD'))
            .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

        const yAxis = d3.axisLeft(yScale);

        g.append('g')
            .attr('class', 'axis x-axis')
            .attr('transform', `translate(0, ${height})`)
            .call(xAxis)
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        g.append('g')
            .attr('class', 'axis y-axis')
            .call(yAxis);

        // Update last update time
        lastUpdateSpan.textContent = `Last updated: ${moment().format('YYYY-MM-DD HH:mm:ss')}`;
    }

    // Fetch data (simulated in this case)
    function fetchData() {
        const stockCount = parseInt(stockCountSelect.value);
        const timeframe = timeframeSelect.value;

        // In a real app, this would be an API call
        // For demo purposes, we'll use mock data
        currentData = generateMockData(stockCount, timeframe);
        updateHeatmap(currentData);
    }

    // Start auto-update
    function startAutoUpdate() {
        if (autoUpdateInterval) clearInterval(autoUpdateInterval);

        autoUpdateInterval = setInterval(() => {
            fetchData();
        }, config.updateInterval);

        autoUpdateStatus.textContent = 'On';
        isAutoUpdateEnabled = true;
    }

    // Stop auto-update
    function stopAutoUpdate() {
        if (autoUpdateInterval) clearInterval(autoUpdateInterval);

        autoUpdateStatus.textContent = 'Off';
        isAutoUpdateEnabled = false;
    }

    // Toggle auto-update
    function toggleAutoUpdate() {
        if (isAutoUpdateEnabled) {
            stopAutoUpdate();
        } else {
            startAutoUpdate();
        }
    }

    // Event listeners
    timeframeSelect.addEventListener('change', fetchData);
    stockCountSelect.addEventListener('change', fetchData);
    refreshBtn.addEventListener('click', fetchData);

    // Initialize
    fetchData();

    // Set up auto-update toggle (click on the status text)
    document.getElementById('auto-update').addEventListener('click', toggleAutoUpdate);

    // Handle window resize
    window.addEventListener('resize', () => {
        if (currentData.length > 0) {
            updateHeatmap(currentData);
        }
    });
});
