```javascript
// Mock data generator for demonstration
function generateMockData(stockCount, timeframe) {
    const stocks = [];
    const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT',
                    'PG', 'JNJ', 'DIS', 'MA', 'INTC', 'VZ', 'ADBE', 'PYPL', 'NFLX', 'CMCSA',
                    'NKE', 'KO', 'PEP', 'XOM', 'CVX', 'T', 'BA', 'CAT', 'IBM', 'QCOM',
                    'AMD', 'CRM', 'ORCL', 'CSCO', 'INTU', 'SAP', 'TXN', 'ADP', 'MCD', 'SBUX'];

    // Select random stocks
    const selectedStocks = [];
    for (let i = 0; i < stockCount; i++) {
        const randomIndex = Math.floor(Math.random() * symbols.length);
        selectedStocks.push(symbols[randomIndex]);
    }

    // Generate time points based on timeframe
    const now = new Date();
    let timePoints = [];
    let interval;

    switch(timeframe) {
        case '1D':
            interval = 60 * 60 * 1000; // 1 hour
            for (let i = 0; i < 24; i++) {
                timePoints.push(new Date(now - i * interval));
            }
            break;
        case '1W':
            interval = 6 * 60 * 60 * 1000; // 6 hours
            for (let i = 0; i < 24 * 7; i += 6) {
                timePoints.push(new Date(now - i * interval));
            }
            break;
        case '1M':
            interval = 24 * 60 * 60 * 1000; // 1 day
            for (let i = 0; i < 30; i++) {
                timePoints.push(new Date(now - i * interval));
            }
            break;
        case '3M':
            interval = 3 * 24 * 60 * 60 * 1000; // 3 days
            for (let i = 0; i < 30; i += 3) {
                timePoints.push(new Date(now - i * interval));
            }
            break;
        case '1Y':
            interval = 7 * 24 * 60 * 60 * 1000; // 1 week
            for (let i = 0; i < 52; i++) {
                timePoints.push(new Date(now - i * interval));
            }
            break;
    }

    // Generate random prices
    const data = [];
    selectedStocks.forEach(symbol => {
        const basePrice = 100 + Math.random() * 200;
        timePoints.forEach(time => {
            // Simulate price movement with some randomness
            const change = (Math.random() - 0.5) * 2;
            const price = basePrice + change;

            data.push({
                symbol: symbol,
                time: time,
                price: parseFloat(price.toFixed(2)),
                change: parseFloat(change.toFixed(2))
            });
        });
    });

    return data;
}

// Main heatmap class
class StockHeatmap {
    constructor() {
        this.margin = { top: 30, right: 30, bottom: 80, left: 80 };
        this.width = 800 - this.margin.left - this.margin.right;
        this.height = 600 - this.margin.top - this.margin.bottom;

        this.svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", this.width + this.margin.left + this.margin.right)
            .attr("height", this.height + this.margin.top + this.margin.bottom)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.xScale = d3.scaleBand();
        this.yScale = d3.scaleBand();
        this.colorScale = d3.scaleLinear()
            .range(["#e74c3c", "#f39c12", "#f1c40f", "#2ecc71", "#27ae60"]);

        this.tooltip = d3.select("body").append("div")
            .attr("class", "tooltip")
            .style("opacity", 0)
            .style("position", "absolute")
            .style("background", "white")
            .style("padding", "10px")
            .style("border", "1px solid #ddd")
            .style("border-radius", "4px")
            .style("pointer-events", "none")
            .style("box-shadow", "0 2px 5px rgba(0,0,0,0.2)");

        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        this.data = [];
        this.timeframe = '1M';
        this.stockCount = 50;
        this.updateInterval = 10000; // 10 seconds
        this.updateTimer = null;

        this.initControls();
        this.loadData();
    }

    initControls() {
        // Timeframe selector
        d3.select("#timeframe").on("change", () => {
            this.timeframe = d3.select("#timeframe").property("value");
            this.loadData();
        });

        // Stock count selector
        d3.select("#stock-count").on("change", () => {
            this.stockCount = parseInt(d3.select("#stock-count").property("value"));
            this.loadData();
        });

        // Update interval selector
        d3.select("#update-interval").on("change", () => {
            this.updateInterval = parseInt(d3.select("#update-interval").property("value")) * 1000;
            this.resetUpdateTimer();
        });

        // Refresh button
        d3.select("#refresh-btn").on("click", () => {
            this.loadData();
        });
    }

    loadData() {
        // Show loading indicator
        d3.select("#heatmap-container .loading").style("display", "block");

        // In a real implementation, this would fetch from an API
        // For demo purposes, we use mock data
        setTimeout(() => {
            this.data = generateMockData(this.stockCount, this.timeframe);
            this.render();
            d3.select("#heatmap-container .loading").style("display", "none");

            // Reset update timer
            this.resetUpdateTimer();
        }, 500);
    }

    resetUpdateTimer() {
        if (this.updateTimer) {
            clearInterval(this.updateTimer);
        }

        this.updateTimer = setInterval(() => {
            this.updateData();
        }, this.updateInterval);
    }

    updateData() {
        // In a real implementation, this would fetch new data
        // For demo purposes, we modify existing data slightly
        this.data = this.data.map(item => {
            const change = (Math.random() - 0.5) * 0.5;
            return {
                ...item,
                price: parseFloat((item.price + change).toFixed(2)),
                change: parseFloat(change.toFixed(2))
            };
        });

        this.render();
    }

    render() {
        // Clear previous content
        this.svg.selectAll("*").remove();

        // Prepare data for heatmap
        const stocks = [...new Set(this.data.map(d => d.symbol))];
        const times = [...new Set(this.data.map(d => d.time))].sort((a, b) => a - b);

        // Set up scales
        this.xScale.domain(times)
            .range([0, this.width])
            .padding(0.05);

        this.yScale.domain(stocks)
            .range([0, this.height])
            .padding(0.05);

        // Set up color scale based on price changes
        const allChanges = this.data.map(d => d.change);
        this.colorScale.domain([d3.min(allChanges), 0, d3.max(allChanges)]);

        // Create heatmap cells
        this.svg.selectAll()
            .data(this.data)
            .enter()
            .append("rect")
            .attr("x", d => this.xScale(d.time))
            .attr("y", d => this.yScale(d.symbol))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.change))
            .on("mouseover", (event, d) => {
                this.tooltip.transition()
                    .duration(200)
                    .style("opacity", .9);

                this.tooltip.html(`
                    <strong>${d.symbol}</strong><br>
                    Time: ${d.time.toLocaleString()}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
            })
            .on("mouseout", () => {
                this.tooltip.transition()
                    .duration(500)
                    .style("opacity", 0);
            });

        // Add x-axis
        this.svg.append("g")
            .attr("transform", `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale)
                .tickFormat(d => {
                    if (this.timeframe === '1D') {
                        return d3.timeFormat("%H:%M")(d);
                    } else if (this.timeframe === '1W') {
                        return d3.timeFormat("%a %H:%M")(d);
                    } else {
                        return d3.timeFormat("%b %d")(d);
                    }
                })
                .tickSizeOuter(0))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        // Add y-axis
        this.svg.append("g")
            .call(d3.axisLeft(this.yScale)
                .tickSizeOuter(0));

        // Add x-axis label
        this.svg.append("text")
            .attr("x", this.width / 2)
            .attr("y", this.height + this.margin.bottom - 10)
            .style("text-anchor", "middle")
            .text("Time");

        // Add y-axis label
        this.svg.append("text")
            .attr("transform", "rotate(-90)")
            .attr("y", -this.margin.left + 20)
            .attr("x", -this.height / 2)
            .style("text-anchor", "middle")
            .text("Stock Symbol");

        // Create legend
        this.createLegend();
    }

    createLegend() {
        const legend = d3.select("#legend");
        legend.selectAll("*").remove();

        const legendData = [
            { color: "#e74c3c", label: "Large Decrease" },
            { color: "#f39c12", label: "Decrease" },
            { color: "#f1c40f", label: "Neutral" },
            { color: "#2ecc71", label: "Increase" },
            { color: "#27ae60", label: "Large Increase" }
        ];

        const legendItems = legend.selectAll(".legend-item")
            .data(legendData)
            .enter()
            .append("div")
            .attr("class", "legend-item");

        legendItems.append("div")
            .attr("class", "legend-color")
            .style("background-color", d => d.color);

        legendItems.append("span")
            .text(d => d.label);
    }

    zoomed(event) {
        const { transform } = event;
        this.svg.attr("transform", transform);
    }
}

