    console.log(`Fetching data for ${state.currentStock} (${state.currentTimeframe})`);

    // Show loading indicator
    d3.select(config.container).select('.loading').style('display', 'block');

    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 500));

    // Generate mock data
    const data = generateMockData(state.currentStock, state.currentTimeframe);

    // Update state
    state.data = data;

    // Hide loading indicator
    d3.select(config.container).select('.loading').style('display', 'none');

    // Render the data
    render();
}

// Generate mock data for demonstration
function generateMockData(stock, timeframe) {
    const data = [];
    const now = new Date();
    const timeframes = {
        '1d': { count: 24, unit: 'hour' },
        '1w': { count: 7, unit: 'day' },
        '1m': { count: 30, unit: 'day' },
        '3m': { count: 90, unit: 'day' },
        '1y': { count: 12, unit: 'month' },
        '5y': { count: 5, unit: 'year' }
    };

    const { count, unit } = timeframes[timeframe];
    const basePrice = 100 + Math.random() * 100;

    for (let i = 0; i < count; i++) {
        const date = new Date(now);
        if (unit === 'hour') {
            date.setHours(now.getHours() - i);
        } else if (unit === 'day') {
            date.setDate(now.getDate() - i);
        } else if (unit === 'month') {
            date.setMonth(now.getMonth() - i);
        } else if (unit === 'year') {
            date.setFullYear(now.getFullYear() - i);
        }

        const price = basePrice + (Math.random() * 20 - 10);
        const volume = Math.floor(Math.random() * 1000000);

        data.push({
            date: date,
            price: price,
            volume: volume,
            change: (price - basePrice) / basePrice * 100
        });
    }

    return data.reverse();
}

// Render the heatmap
function render() {
    if (state.data.length === 0) return;

    const svg = d3.select(config.container).select('svg');
    const g = svg.select('g');

    // Clear previous content
    g.selectAll('*').remove();

    // Set up scales
    const xScale = d3.scaleBand()
        .domain(state.data.map(d => d.date))
        .range([0, config.width - config.margin.left - config.margin.right])
        .padding(0.1);

    const yScale = d3.scaleLinear()
        .domain([d3.min(state.data, d => d.price), d3.max(state.data, d => d.price)])
        .range([config.height - config.margin.top - config.margin.bottom, 0]);

    // Color scale based on price change
    const colorScale = d3.scaleQuantile()
        .domain([d3.min(state.data, d => d.change), d3.max(state.data, d => d.change)])
        .range(config.colors);

    // Create heatmap cells
    const cells = g.selectAll('.cell')
        .data(state.data)
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.date))
        .attr('y', d => yScale(d.price))
        .attr('width', xScale.bandwidth())
        .attr('height', d => config.height - config.margin.top - config.margin.bottom - yScale(d.price))
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat('%b %d'))
        .tickSizeOuter(0);

    const yAxis = d3.axisLeft(yScale)
        .tickFormat(d3.format('$.2f'));

    g.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0, ${config.height - config.margin.top - config.margin.bottom})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    g.append('g')
        .attr('class', 'y-axis')
        .call(yAxis);

    // Add axis labels
    g.append('text')
        .attr('class', 'x-axis-label')
        .attr('x', (config.width - config.margin.left - config.margin.right) / 2)
        .attr('y', config.height - config.margin.top - 20)
        .style('text-anchor', 'middle')
        .text('Date');

    g.append('text')
        .attr('class', 'y-axis-label')
        .attr('transform', 'rotate(-90)')
        .attr('x', -(config.height - config.margin.top - config.margin.bottom) / 2)
        .attr('y', -50)
        .style('text-anchor', 'middle')
        .text('Price ($)');

    // Add title
    g.append('text')
        .attr('class', 'title')
        .attr('x', (config.width - config.margin.left - config.margin.right) / 2)
        .attr('y', -10)
        .style('text-anchor', 'middle')
        .style('font-size', '16px')
        .text(`${state.currentStock} Stock Price Heatmap (${state.currentTimeframe})`);

    // Update legend
    updateLegend(colorScale);
}

// Show tooltip on hover
function showTooltip(event, d) {
    const tooltip = d3.select('.tooltip');

    tooltip.html(`
        <strong>${state.currentStock}</strong><br>
        Date: ${d3.timeFormat('%Y-%m-%d')(d.date)}<br>
        Price: $${d.price.toFixed(2)}<br>
        Change: ${d.change.toFixed(2)}%<br>
        Volume: ${d.volume.toLocaleString()}
    `)
    .style('visibility', 'visible')
    .style('top', `${event.pageY - 10}px`)
    .style('left', `${event.pageX + 10}px`);
}

// Hide tooltip
function hideTooltip() {
    d3.select('.tooltip').style('visibility', 'hidden');
}

// Update the legend
function updateLegend(colorScale) {
    const legend = d3.select('#legend');
    legend.selectAll('*').remove();

    const thresholds = colorScale.quantiles();
    const domain = colorScale.domain();

    // Add min value
    legend.append('div')
        .attr('class', 'legend-item')
        .html(`
            <div class="legend-color" style="background-color: ${colorScale(domain[0])}"></div>
            <span>${domain[0].toFixed(2)}%</span>
        `);

    // Add quantiles
    thresholds.forEach((threshold, i) => {
        legend.append('div')
            .attr('class', 'legend-item')
            .html(`
                <div class="legend-color" style="background-color: ${colorScale(threshold)}"></div>
                <span>${threshold.toFixed(2)}%</span>
            `);
    });

    // Add max value
    legend.append('div')
        .attr('class', 'legend-item')
        .html(`
            <div class="legend-color" style="background-color: ${colorScale(domain[1])}"></div>
            <span>${domain[1].toFixed(2)}%</span>
        `);
}

// Initialize the application
init();
