## JavaScript Implementation

```javascript
// Configuration
const config = {
    updateInterval: 60000, // 1 minute
    zoomFactor: 1.2,
    minZoom: 0.5,
    maxZoom: 5
};

// Global variables
let heatmapData = [];
let svg, xScale, yScale, colorScale, zoom;
let currentTimeframe = '1m';
let selectedStocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT'];
let updateIntervalId;
let isLoading = false;

// Initialize the application
document.addEventListener('DOMContentLoaded', function() {
    // Set up event listeners
    document.getElementById('update-btn').addEventListener('click', fetchData);
    document.getElementById('reset-btn').addEventListener('click', resetView);
    document.getElementById('timeframe').addEventListener('change', function() {
        currentTimeframe = this.value;
    });
    document.getElementById('stocks').addEventListener('change', function() {
        selectedStocks = Array.from(this.selectedOptions).map(option => option.value);
    });

    // Initialize the heatmap
    initHeatmap();

    // Fetch initial data
    fetchData();

    // Set up periodic updates
    updateIntervalId = setInterval(fetchData, config.updateInterval);
});

// Initialize the heatmap SVG
function initHeatmap() {
    const container = document.getElementById('heatmap-container');
    const width = container.clientWidth;
    const height = container.clientHeight;

    // Remove any existing SVG
    d3.select('#heatmap-container svg').remove();

    // Create SVG
    svg = d3.select('#heatmap-container')
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height])
        .attr('preserveAspectRatio', 'xMidYMid meet');

    // Add zoom behavior
    zoom = d3.zoom()
        .scaleExtent([config.minZoom, config.maxZoom])
        .on('zoom', zoomed);

    svg.call(zoom);

    // Add tooltip
    const tooltip = d3.select('#tooltip');

    // Add legend
    updateLegend();
}

// Handle zoom events
function zoomed(event) {
    const transform = event.transform;
    svg.selectAll('g').attr('transform', transform);
}

// Reset the view to default
function resetView() {
    svg.transition()
        .duration(750)
        .call(zoom.transform, d3.zoomIdentity);
}

// Fetch stock data
async function fetchData() {
    if (isLoading) return;

    isLoading = true;
    document.getElementById('loading').style.display = 'block';
    document.getElementById('error').style.display = 'none';

    try {
        // In a real application, you would fetch this from an API
        // For this demo, we'll generate mock data
        const mockData = generateMockData(selectedStocks, currentTimeframe);

        // Process the data
        processData(mockData);

        // Update the visualization
        updateHeatmap();

        // Hide loading indicator
        document.getElementById('loading').style.display = 'none';
    } catch (error) {
        console.error('Error fetching data:', error);
        document.getElementById('error').textContent = 'Failed to load data. Please try again.';
        document.getElementById('error').style.display = 'block';
        document.getElementById('loading').style.display = 'none';
    } finally {
        isLoading = false;
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    const data = [];
    const now = new Date();
    const endDate = moment(now).subtract(1, 'day').toDate();
    let startDate;

    // Set start date based on timeframe
    switch(timeframe) {
        case '1d':
            startDate = moment(now).subtract(1, 'day').toDate();
            break;
        case '1w':
            startDate = moment(now).subtract(1, 'week').toDate();
            break;
        case '1m':
            startDate = moment(now).subtract(1, 'month').toDate();
            break;
        case '3m':
            startDate = moment(now).subtract(3, 'months').toDate();
            break;
        case '1y':
            startDate = moment(now).subtract(1, 'year').toDate();
            break;
        case '5y':
            startDate = moment(now).subtract(5, 'years').toDate();
            break;
        default:
            startDate = moment(now).subtract(1, 'month').toDate();
    }

    // Generate data points for each stock
    stocks.forEach(stock => {
        const basePrice = 100 + Math.random() * 200; // Random base price between 100-300
        let currentDate = new Date(startDate);

        while (currentDate <= endDate) {
            // Generate a random price change
            const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
            const price = basePrice + change;

            data.push({
                stock: stock,
                date: new Date(currentDate),
                price: parseFloat(price.toFixed(2)),
                change: parseFloat(change.toFixed(2))
            });

            // Move to next day
            currentDate.setDate(currentDate.getDate() + 1);
        }
    });

    return data;
}

// Process the data into a format suitable for the heatmap
function processData(data) {
    // Group data by stock and date
    const groupedData = d3.group(data, d => d.stock, d => d.date);

    // Convert to array of objects with stock, date, and price
    heatmapData = [];
    for (const [stock, dates] of groupedData) {
        for (const [date, entries] of dates) {
            // Use the last entry for each date (in case of multiple entries)
            const entry = entries[entries.length - 1];
            heatmapData.push({
                stock: stock,
                date: date,
                price: entry.price,
                change: entry.change
            });
        }
    }

    // Sort by date
    heatmapData.sort((a, b) => a.date - b.date);
}

// Update the heatmap visualization
function updateHeatmap() {
    if (!heatmapData.length) return;

    const container = document.getElementById('heatmap-container');
    const width = container.clientWidth;
    const height = container.clientHeight;
    const margin = { top: 20, right: 20, bottom: 50, left: 80 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Get unique stocks and dates
    const stocks = [...new Set(heatmapData.map(d => d.stock))];
    const dates = [...new Set(heatmapData.map(d => d.date))];

    // Create scales
    xScale = d3.scaleBand()
        .domain(dates.map(d => d3.timeFormat('%Y-%m-%d')(d)))
        .range([0, innerWidth])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, innerHeight])
        .padding(0.05);

    // Get min and max price for color scale
    const minPrice = d3.min(heatmapData, d => d.price);
    const maxPrice = d3.max(heatmapData, d => d.price);

    colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
        .domain([minPrice, maxPrice]);

    // Remove previous heatmap elements
    svg.selectAll('g').remove();

    // Create a group for the heatmap
    const heatmapGroup = svg.append('g')
        .attr('transform', `translate(${margin.left}, ${margin.top})`);

    // Add rectangles for each data point
    heatmapGroup.selectAll('rect')
        .data(heatmapData)
        .enter()
        .append('rect')
        .attr('x', d => xScale(d3.timeFormat('%Y-%m-%d')(d.date)))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.price))
        .on('mouseover', function(event, d) {
            const tooltip = d3.select('#tooltip');
            tooltip.html(`
                <strong>${d.stock}</strong><br>
                Date: ${d3.timeFormat('%Y-%m-%d')(d.date)}<br>
                Price: $${d.price.toFixed(2)}<br>
                Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}
            `)
            .style('visibility', 'visible')
            .style('left', (event.pageX + 10) + 'px')
            .style('top', (event.pageY + 10) + 'px');
        })
        .on('mouseout', function() {
            d3.select('#tooltip').style('visibility', 'hidden');
        });

    // Add x-axis
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => d3.timeFormat('%b %d')(new Date(d)))
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    heatmapGroup.append('g')
        .attr('transform', `translate(0, ${innerHeight})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    // Add y-axis
    heatmapGroup.append('g')
        .call(d3.axisLeft(yScale));

    // Add axis labels
    heatmapGroup.append('text')
        .attr('x', innerWidth / 2)
        .attr('y', innerHeight + margin.bottom - 10)
        .style('text-anchor', 'middle')
        .text('Date');

    heatmapGroup.append('text')
        .attr('transform', 'rotate(-90)')
        .attr('y', -margin.left + 20)
        .attr('x', -innerHeight / 2)
        .style('text-anchor', 'middle')
        .text('Stock');

    // Update legend
    updateLegend(minPrice, maxPrice);
}

// Update the legend
function updateLegend(minPrice, maxPrice) {
    const legend = d3.select('#legend');
    legend.selectAll('*').remove();

    if (!minPrice || !maxPrice) return;

    // Create legend items
    const legendItems = [
        { color: colorScale(minPrice), label: `$${minPrice.toFixed(2)}` },
        { color: colorScale((minPrice + maxPrice) / 2), label: `$${((minPrice + maxPrice) / 2).toFixed(2)}` },
        { color: colorScale(maxPrice), label: `$${maxPrice.toFixed(2)}` }
    ];

    legendItems.forEach(item => {
        const legendItem = legend.append('div')
            .attr('class', 'legend-item');

        legendItem.append('div')
            .attr('class', 'legend-color')
            .style('background-color', item.color);

        legendItem.append('div')
            .text(item.label);
    });
}

// Clean up when the page is unloaded
window.addEventListener('beforeunload', function() {
    if (updateIntervalId) {
        clearInterval(updateIntervalId);
    }
});
