    <script src="https://d3js.org/d3.v7.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/moment.js/2.29.1/moment.min.js"></script>
    <script>
        // Main application code will go here
        document.addEventListener('DOMContentLoaded', function() {
            // Configuration
            const config = {
                container: '#heatmap-container',
                width: document.querySelector('#heatmap-container').clientWidth,
                height: document.querySelector('#heatmap-container').clientHeight,
                margin: { top: 30, right: 30, bottom: 30, left: 60 },
                colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([0, 1]),
                tooltip: d3.select('#tooltip'),
                legend: d3.select('#legend')
            };

            // State
            let state = {
                data: [],
                selectedStocks: Array.from(document.querySelectorAll('#stock-select option:checked')).map(opt => opt.value),
                timeframe: document.getElementById('timeframe').value,
                zoom: d3.zoom().scaleExtent([0.5, 10]).on('zoom', zoomed),
                svg: null,
                xScale: null,
                yScale: null,
                colorScale: null,
                xAxis: null,
                yAxis: null,
                heatmap: null,
                lastUpdate: null
            };

            // Initialize the visualization
            initVisualization();

            // Set up event listeners
            setupEventListeners();

            // Initial data load
            loadData();

            // Set up periodic updates
            setInterval(updateData, 30000); // Update every 30 seconds

            // Functions
            function initVisualization() {
                // Clear any existing SVG
                d3.select(config.container).selectAll('svg').remove();

                // Create SVG
                state.svg = d3.select(config.container)
                    .append('svg')
                    .attr('width', config.width)
                    .attr('height', config.height)
                    .call(state.zoom)
                    .append('g')
                    .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

                // Create scales
                state.xScale = d3.scaleBand();
                state.yScale = d3.scaleBand();
                state.colorScale = config.colorScale;

                // Create axes
                state.xAxis = state.svg.append('g').attr('class', 'x-axis');
                state.yAxis = state.svg.append('g').attr('class', 'y-axis');

                // Create heatmap group
                state.heatmap = state.svg.append('g').attr('class', 'heatmap');

                // Create legend
                createLegend();
            }

            function setupEventListeners() {
                document.getElementById('timeframe').addEventListener('change', function() {
                    state.timeframe = this.value;
                    loadData();
                });

                document.getElementById('stock-select').addEventListener('change', function() {
                    state.selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
                    loadData();
                });

                document.getElementById('refresh-btn').addEventListener('click', loadData);
                document.getElementById('reset-btn').addEventListener('click', resetView);
            }

            function createLegend() {
                const legendData = [
                    { color: state.colorScale(0), label: 'Low' },
                    { color: state.colorScale(0.5), label: 'Medium' },
                    { color: state.colorScale(1), label: 'High' }
                ];

                config.legend.selectAll('.legend-item').remove();

                const legendItems = config.legend.selectAll('.legend-item')
                    .data(legendData)
                    .enter()
                    .append('div')
                    .attr('class', 'legend-item');

                legendItems.append('div')
                    .attr('class', 'legend-color')
                    .style('background-color', d => d.color);

                legendItems.append('span')
                    .text(d => d.label);
            }

            function loadData() {
                // Show loading indicator
                d3.select(config.container).select('.loading').style('display', 'block');

                // In a real implementation, this would fetch from an API
                // For this demo, we'll generate mock data
                setTimeout(() => {
                    generateMockData();
                    updateVisualization();
                    d3.select(config.container).select('.loading').style('display', 'none');
                }, 800);
            }

            function updateData() {
                // In a real implementation, this would fetch only the latest data
                // For this demo, we'll just update some values
                if (state.data.length > 0) {
                    state.data.forEach(stock => {
                        stock.values.forEach(day => {
                            // Randomly change prices slightly
                            day.price = day.price * (1 + (Math.random() - 0.5) * 0.02);
                        });
                    });
                    updateVisualization();
                }
            }

            function generateMockData() {
                // Generate mock data based on selected stocks and timeframe
                const now = new Date();
                const timeframes = {
                    '1d': { days: 1, interval: 'hour' },
                    '1w': { days: 7, interval: 'day' },
                    '1m': { days: 30, interval: 'day' },
                    '3m': { days: 90, interval: 'day' },
                    '1y': { days: 365, interval: 'week' }
                };

                const { days, interval } = timeframes[state.timeframe];
                const dates = [];

                // Generate dates based on interval
                for (let i = 0; i < days; i++) {
                    const date = new Date(now);
                    if (interval === 'hour') {
                        date.setHours(date.getHours() - i);
                    } else if (interval === 'day') {
                        date.setDate(date.getDate() - i);
                    } else if (interval === 'week') {
                        date.setDate(date.getDate() - i * 7);
                    }
                    dates.push(date);
                }

                // Generate data for each selected stock
                state.data = state.selectedStocks.map(stock => {
                    const values = dates.map(date => {
                        // Generate random price data
                        const basePrice = 100 + Math.random() * 200;
                        const price = basePrice * (1 + (Math.random() - 0.5) * 0.2);
                        const volume = Math.floor(Math.random() * 1000000);

                        return {
                            date: date,
                            price: price,
                            volume: volume,
                            change: (Math.random() - 0.5) * 0.1
                        };
                    });

                    return {
                        stock: stock,
                        values: values
                    };
                });

                // Normalize the data for color mapping
                const allPrices = state.data.flatMap(stock => stock.values.map(d => d.price));
                const minPrice = Math.min(...allPrices);
                const maxPrice = Math.max(...allPrices);

                state.data.forEach(stock => {
                    stock.values.forEach(d => {
                        d.normalizedPrice = (d.price - minPrice) / (maxPrice - minPrice);
                    });
                });
            }

            function updateVisualization() {
                if (state.data.length === 0) return;

                // Get all dates (x-axis)
                const allDates = state.data[0].values.map(d => d.date);
                const stocks = state.data.map(d => d.stock);

                // Update scales
                state.xScale
                    .domain(allDates)
                    .range([0, config.width - config.margin.left - config.margin.right])
                    .padding(0.05);

                state.yScale
                    .domain(stocks)
                    .range([0, config.height - config.margin.top - config.margin.bottom])
                    .padding(0.1);

                // Update axes
                state.xAxis
                    .attr('transform', `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
                    .call(d3.axisBottom(state.xScale)
                        .tickFormat(d => moment(d).format(state.timeframe === '1d' ? 'HH:mm' : 'MMM D'))
                        .tickSizeOuter(0));

                state.yAxis
                    .call(d3.axisLeft(state.yScale).tickSizeOuter(0));

                // Update heatmap
                const cells = state.heatmap.selectAll('.cell')
                    .data(state.data.flatMap(stock =>
                        stock.values.map(d => ({
                            stock: stock.stock,
                            date: d.date,
                            price: d.price,
                            normalizedPrice: d.normalizedPrice,
                            change: d.change
                        }))
                    ));

                // Remove old cells
                cells.exit().remove();

                // Add new cells
                const newCells = cells.enter()
                    .append('rect')
                    .attr('class', 'cell')
                    .attr('x', d => state.xScale(d.date))
                    .attr('y', d => state.yScale(d.stock))
                    .attr('width', state.xScale.bandwidth())
                    .attr('height', state.yScale.bandwidth())
                    .attr('fill', d => state.colorScale(d.normalizedPrice))
                    .on('mouseover', showTooltip)
                    .on('mouseout', hideTooltip);

                // Merge and update existing cells
                cells.merge(newCells)
                    .transition()
                    .duration(500)
                    .attr('fill', d => state.colorScale(d.normalizedPrice));
            }

            function showTooltip(event, d) {
                config.tooltip.style('display', 'block')
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Date: ${moment(d.date).format('MMM D, YYYY')}<br>
                        Price: $${d.price.toFixed(2)}<br>
                        Change: ${(d.change * 100).toFixed(2)}%
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY + 10) + 'px');
            }

            function hideTooltip() {
                config.tooltip.style('display', 'none');
            }

            function zoomed(event) {
                state.heatmap.attr('transform', event.transform);
                state.xAxis.call(d3.axisBottom(state.xScale).scale(event.transform.rescaleX(state.xScale)));
                state.yAxis.call(d3.axisLeft(state.yScale).scale(event.transform.rescaleY(state.yScale)));
            }

            function resetView() {
                state.svg.transition()
                    .duration(750)
                    .call(state.zoom.transform, d3.zoomIdentity);
            }
        });
    </script>
</body>
</html>
```

## Key Features

1. **Interactive Controls**:
   - Timeframe selection (1 day, 1 week, 1 month, etc.)
   - Stock selection (multiple stocks can be selected)
   - Refresh and reset buttons

2. **Real-time Updates**:
   - Data updates every 30 seconds (simulated in this demo)
   - Smooth transitions for price changes

3. **Zoom/Pan Interactions**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan
   - Reset button to return to default view

4. **Visual Elements**:
   - Color-coded heatmap (green for high prices, red for low)
   - Tooltips showing detailed information
   - Legend explaining the color scale
   - Responsive design that works on different screen sizes

5. **Data Handling**:
   - Mock data generation for demonstration
   - Normalization of price data for consistent coloring
   - Date formatting based on selected timeframe

## Implementation Notes

1. This implementation uses D3.js for data visualization, which provides the necessary tools for creating interactive heatmaps.

2. The mock data generation simulates real stock price data. In a production environment, you would replace this with actual API calls to a financial data provider.

3. The zoom/pan functionality is implemented using D3's built-in zoom behavior.

4. The visualization is responsive and will adjust to the container size.

5. Tooltips provide additional information when hovering over cells.

6. The legend helps users understand the color coding.

For a production implementation, you would need to:
- Replace the mock data with real API calls
- Add error handling for API failures
- Implement proper authentication if needed
- Add more sophisticated data processing
- Consider performance optimizations for large datasets

