        class StockPriceHeatmap {
            constructor() {
                this.container = d3.select('.heatmap-container');
                this.width = this.container.node().clientWidth;
                this.height = this.container.node().clientHeight;
                this.margin = { top: 30, right: 30, bottom: 30, left: 60 };
                this.svg = null;
                this.xScale = null;
