            generateMockData() {
                const now = new Date();
                const points = 100; // Number of time points
                const timeInterval = this.getTimeInterval();

                this.data = this.stocks.map(stock => {
                    const stockData = [];
                    for (let i = 0; i < points; i++) {
                        const time = new Date(now.getTime() - (points - i) * timeInterval);
                        const price = this.generateRandomPrice(stock);
                        stockData.push({ time, price, stock });
                    }
                    return stockData;
                }).flat();
            }

            getTimeInterval() {
                switch (this.timeRange) {
                    case '1h': return 60 * 60 * 1000; // 1 hour
                    case '1d': return 60 * 60 * 1000 * 24; // 1 day
                    case '1w': return 60 * 60 * 1000 * 24 * 7; // 1 week
                    case '1m': return 60 * 60 * 1000 * 24 * 30; // 1 month
                    default: return 60 * 60 * 1000 * 24; // default to 1 day
                }
            }

            generateRandomPrice(stock) {
                // Different base prices for different stocks
                const basePrices = {
                    'AAPL': 150,
                    'MSFT': 300,
                    'GOOGL': 2800,
                    'AMZN': 3400,
                    'FB': 350,
                    'TSLA': 700,
                    'NVDA': 500,
                    'JPM': 150,
                    'V': 220,
                    'WMT': 140
                };

                const basePrice = basePrices[stock] || 100;
                const volatility = 0.02; // 2% volatility

                // Simulate price movement
                const change = (Math.random() * 2 - 1) * volatility * basePrice;
                return basePrice + change;
