                    .html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${d.time.toLocaleString()}<br>
                        Price: $${d.price.toFixed(2)}
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY + 10) + 'px');
            }

            hideTooltip() {
                this.tooltip.style('display', 'none');
            }

            zoomed(event) {
                const transform = event.transform;
                this.svg.selectAll('.cell')
                    .attr('transform', transform);

                // Update axes
                const newXScale = transform.rescaleX(this.xScale);
                this.svg.select('g:first-of-type')
                    .call(d3.axisBottom(newXScale).ticks(Math.max(this.width / 100, 2)))
                    .selectAll('text')
                    .attr('transform', 'rotate(-45)')
                    .style('text-anchor', 'end');
            }

            resetView() {
                this.svg.transition()
                    .duration(750)
                    .call(this.zoom.transform, d3.zoomIdentity);
            }

            setTimeRange(range) {
                this.timeRange = range;
                this.loadData();
            }

            setupRealTimeUpdates() {
                // Simulate real-time updates every 5 seconds
                this.simulationInterval = setInterval(() => {
                    this.updateData();
                }, 5000);
            }

            updateData() {
                // Add new data point for each stock
                const now = new Date();
                const timeInterval = this.getTimeInterval();

                this.stocks.forEach(stock => {
                    const newPrice = this.generateRandomPrice(stock);
                    const newDataPoint = {
                        time: now,
                        price: newPrice,
                        stock: stock
                    };

                    // Find the data for this stock
                    const stockData = this.data.filter(d => d.stock === stock);

                    // Remove oldest point if we have too many
                    if (stockData.length >= 100) {
                        const oldestPoint = stockData.reduce((oldest, d) =>
                            d.time < oldest.time ? d : oldest, stockData[0]);

                        this.data = this.data.filter(d => d !== oldestPoint);
                    }

                    // Add new data point
                    this.data.push(newDataPoint);
                });

                // Update the visualization
                this.renderHeatmap();
            }

            handleResize() {
                this.width = this.container.node().clientWidth;
                this.height = this.container.node().clientHeight;

                this.svg.attr('width', this.width)
                    .attr('height', this.height);

                this.renderHeatmap();
            }

            destroy() {
                if (this.simulationInterval) {
                    clearInterval(this.simulationInterval);
                }
            }
        }
    </script>
</body>
</html>
