```javascript
// Sample data - in a real app, you would fetch this from an API
const sampleStocks = [
    "AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "BRK.B", "JNJ", "JPM", "V",
    "PG", "NVDA", "HD", "MA", "DIS", "PYPL", "VZ", "ADBE", "CRM", "NFLX",
    "INTC", "CMCSA", "PEP", "KO", "MRK", "ABT", "T", "XOM", "CVX", "WMT"
];

// Generate sample data for the heatmap
function generateSampleData(range) {
    const now = new Date();
    let startDate, interval;

    switch(range) {
        case '1d':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 3600 * 1000; // 1 hour
            break;
        case '1w':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 3600 * 1000 * 6; // 6 hours
            break;
        case '1m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 3600 * 1000 * 24; // 1 day
            break;
        case '3m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 3600 * 1000 * 24 * 3; // 3 days
            break;
        case '1y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 3600 * 1000 * 24 * 7; // 1 week
            break;
        case '5y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 5);
            interval = 3600 * 1000 * 24 * 30; // 1 month
            break;
        default:
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 3600 * 1000;
    }

    const data = [];
    const currentTime = new Date(startDate);

    while (currentTime <= now) {
        const timePoint = new Date(currentTime);

        sampleStocks.forEach(stock => {
            // Generate random price change between -5% and +5%
            const change = (Math.random() * 10 - 5) / 100;
            const price = 100 + (Math.random() * 100); // Base price between 100-200

            data.push({
                stock: stock,
                time: timePoint,
                price: price,
                change: change
            });
        });

        currentTime.setTime(currentTime.getTime() + interval);
    }

    return data;
}

// Main heatmap class
class StockHeatmap {
    constructor(containerId, data) {
        this.container = d3.select(containerId);
        this.data = data;
        this.margin = { top: 30, right: 30, bottom: 80, left: 80 };
        this.width = this.container.node().getBoundingClientRect().width - this.margin.left - this.margin.right;
        this.height = this.container.node().getBoundingClientRect().height - this.margin.top - this.margin.bottom;

        this.svg = this.container.append("svg")
            .attr("width", this.width + this.margin.left + this.margin.right)
            .attr("height", this.height + this.margin.top + this.margin.bottom)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.tooltip = d3.select("#tooltip");

        this.xScale = d3.scaleBand();
        this.yScale = d3.scaleBand();
        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn);

        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.init();
    }

    init() {
        // Process data
        this.processData();

        // Set up scales
        this.setupScales();

        // Draw axes
        this.drawAxes();

        // Draw heatmap
        this.drawHeatmap();

        // Add legend
        this.addLegend();

        // Add zoom behavior
        this.svg.call(this.zoom);

        // Add tooltip behavior
        this.addTooltipBehavior();
    }

    processData() {
        // Group data by stock and time
        this.stocks = [...new Set(this.data.map(d => d.stock))];
        this.times = [...new Set(this.data.map(d => d.time.toISOString()))].sort();

        // Create a matrix of changes
        this.matrix = [];
        this.stocks.forEach(stock => {
            const row = [];
            this.times.forEach(time => {
                const point = this.data.find(d =>
                    d.stock === stock && d.time.toISOString() === time
                );
                row.push(point ? point.change : 0);
            });
            this.matrix.push(row);
        });

        // Find min and max values for color scale
        this.minChange = d3.min(this.data, d => d.change);
        this.maxChange = d3.max(this.data, d => d.change);
    }

    setupScales() {
        this.xScale
            .domain(this.times)
            .range([0, this.width])
            .padding(0.05);

        this.yScale
            .domain(this.stocks)
            .range([0, this.height])
            .padding(0.05);

        this.colorScale
            .domain([this.minChange, this.maxChange]);
    }

    drawAxes() {
        // X-axis (time)
        this.svg.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale)
                .tickFormat(d => new Date(d).toLocaleString())
                .tickSizeOuter(0))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        // Y-axis (stocks)
        this.svg.append("g")
            .attr("class", "y-axis")
            .call(d3.axisLeft(this.yScale)
                .tickSizeOuter(0));

        // Add axis labels
        this.svg.append("text")
            .attr("class", "x-label")
            .attr("x", this.width / 2)
            .attr("y", this.height + this.margin.bottom - 10)
            .style("text-anchor", "middle")
            .text("Time");

        this.svg.append("text")
            .attr("class", "y-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -this.height / 2)
            .attr("y", -this.margin.left + 20)
            .style("text-anchor", "middle")
            .text("Stock Symbol");
    }

    drawHeatmap() {
        // Draw the heatmap cells
        this.cells = this.svg.selectAll(".cell")
            .data(this.matrix)
            .enter().append("g")
            .attr("class", "cell-group")
            .selectAll(".cell")
            .data((d, i) => d.map((value, j) => ({
                stock: this.stocks[i],
                time: this.times[j],
                change: value
            })))
            .enter().append("rect")
            .attr("class", "cell")
            .attr("x", d => this.xScale(d.time))
            .attr("y", (d, i) => this.yScale(d.stock))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.change))
            .attr("data-stock", d => d.stock)
            .attr("data-time", d => d.time)
            .attr("data-change", d => d.change);
    }

    addLegend() {
        const legend = d3.select("#legend");
        legend.html("");

        // Create a color scale for the legend
        const legendScale = d3.scaleLinear()
            .domain([this.minChange, this.maxChange])
            .range([0, 200]);

        // Create a gradient for the legend
        const gradient = legend.append("defs")
            .append("linearGradient")
            .attr("id", "legend-gradient")
            .attr("x1", "0%")
            .attr("y1", "0%")
            .attr("x2", "100%")
            .attr("y2", "0%");

        gradient.append("stop")
            .attr("offset", "0%")
            .attr("stop-color", this.colorScale(this.minChange));

        gradient.append("stop")
            .attr("offset", "100%")
            .attr("stop-color", this.colorScale(this.maxChange));

        // Add the gradient bar
        legend.append("rect")
            .attr("width", 200)
            .attr("height", 20)
            .style("fill", "url(#legend-gradient)");

        // Add labels
        legend.append("text")
            .attr("x", 0)
            .attr("y", 35)
            .text(`${(this.minChange * 100).toFixed(2)}%`);

        legend.append("text")
            .attr("x", 180)
            .attr("y", 35)
            .attr("text-anchor", "end")
            .text(`${(this.maxChange * 100).toFixed(2)}%`);

        legend.append("text")
            .attr("x", 100)
            .attr("y", 35)
            .attr("text-anchor", "middle")
            .text("Price Change (%)");
    }

    addTooltipBehavior() {
        this.cells.on("mouseover", (event, d) => {
            const priceData = this.data.find(item =>
                item.stock === d.stock && item.time.toISOString() === d.time
            );

            this.tooltip.style("display", "block")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${new Date(d.time).toLocaleString()}<br>
                    Price: $${priceData.price.toFixed(2)}<br>
                    Change: ${(d.change * 100).toFixed(2)}%
                `);

            // Position tooltip
            const x = event.pageX + 10;
            const y = event.pageY + 10;
            this.tooltip.style("left", `${x}px`)
                .style("top", `${y}px`);
        })
        .on("mouseout", () => {
            this.tooltip.style("display", "none");
        });
    }

    zoomed(event) {
        const transform = event.transform;

        // Apply the zoom to the x and y scales
        const newXScale = transform.rescaleX(this.xScale);
        const newYScale = transform.rescaleY(this.yScale);

        // Update the axes
        this.svg.select(".x-axis").call(d3.axisBottom(newXScale)
            .tickFormat(d => new Date(d).toLocaleString())
            .tickSizeOuter(0))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        this.svg.select(".y-axis").call(d3.axisLeft(newYScale)
            .tickSizeOuter(0));

        // Update the heatmap cells
        this.svg.selectAll(".cell")
            .attr("x", d => newXScale(d.time))
            .attr("y", d => newYScale(d.stock))
            .attr("width", newXScale.bandwidth())
            .attr("height", newYScale.bandwidth());
    }

    updateData(newData) {
        this.data = newData;
        this.init();
    }
}

// Main application
document.addEventListener("DOMContentLoaded", () => {
    // Initial data load
    let currentRange = '1d';
    let heatmap;

    function loadData(range) {
        // In a real app, you would fetch data from an API here
        // For this example, we'll use generated sample data
        const data = generateSampleData(range);

        if (!heatmap) {
            heatmap = new StockHeatmap("#heatmap", data);
        } else {
            heatmap.updateData(data);
        }
    }

    // Set up time range buttons
    document.querySelectorAll(".time-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            document.querySelectorAll(".time-btn").forEach(b => b.classList.remove("active"));
            btn.classList.add("active");
            currentRange = btn.dataset.range;
            loadData(currentRange);
        });
    });

    // Set up refresh button
    document.getElementById("refresh-btn").addEventListener("click", () => {
        loadData(currentRange);
    });

    // Initial load
    loadData(currentRange);

    // Set up auto-refresh every 30 seconds
    setInterval(() => {
        loadData(currentRange);
    }, 30000);
});
