                        <option value="60000">1m</option>
                    </select>
                </div>
                <div class="status">
                    <div class="status-dot connected"></div>
                    <span>Connected</span>
                </div>
            </div>
        </div>
        <div class="heatmap-container">
            <div class="heatmap"></div>
            <div class="tooltip"></div>
            <div class="legend">
                <div class="legend-title">Price Change (%)</div>
                <div class="legend-items"></div>
            </div>
        </div>
    </div>

    <script src="https://d3js.org/d3.v7.min.js"></script>
    <script src="https://cdn.socket.io/4.5.4/socket.io.min.js"></script>
    <script>
        // Main application code will go here
        document.addEventListener('DOMContentLoaded', function() {
            // Initialize the heatmap
            const heatmap = new StockPriceHeatmap();
            heatmap.init();
        });

        class StockPriceHeatmap {
            constructor() {
                this.container = d3.select('.heatmap');
                this.tooltip = d3.select('.tooltip');
                this.legendContainer = d3.select('.legend-items');
                this.statusDot = d3.select('.status-dot');
                this.statusText = d3.select('.status span');

                this.width = 0;
                this.height = 0;
                this.margin = { top: 20, right: 20, bottom: 60, left: 80 };

                this.data = [];
                this.timeframe = '1d';
                this.updateInterval = 10000;
                this.lastUpdate = 0;
                this.isConnected = false;

                // Color scale for price changes
                this.colorScale = d3.scaleLinear()
                    .domain([-5, 0, 5])
                    .range(['#e74c3c', '#f5f7fa', '#2ecc71'])
                    .clamp(true);

                // Zoom behavior
                this.zoom = d3.zoom()
                    .scaleExtent([1, 10])
                    .on('zoom', (event) => this.zoomed(event));

                // Sample stock symbols
                this.stocks = [
                    'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.B', 'JNJ', 'JPM', 'V',
                    'PG', 'NVDA', 'HD', 'MA', 'DIS', 'PYPL', 'BAC', 'VZ', 'ADBE', 'CMCSA',
                    'NFLX', 'KO', 'PEP', 'INTC', 'CSCO', 'XOM', 'CVX', 'T', 'WMT', 'MCD'
                ];

                // Time periods for the x-axis
                this.timePeriods = this.generateTimePeriods(this.timeframe);

                // Initialize data
                this.initializeData();
            }

            init() {
                // Set up the container dimensions
                this.resize();
                window.addEventListener('resize', () => this.resize());

                // Set up controls
                this.setupControls();

                // Set up the SVG and initial heatmap
                this.setupHeatmap();

                // Connect to data source (simulated)
                this.connectToDataSource();

                // Start the update loop
                this.updateLoop();
            }

            resize() {
                const container = this.container.node().parentElement;
                this.width = container.clientWidth - this.margin.left - this.margin.right;
                this.height = container.clientHeight - this.margin.top - this.margin.bottom;
            }

            setupControls() {
                d3.select('#timeframe').on('change', (event) => {
                    this.timeframe = event.target.value;
                    this.timePeriods = this.generateTimePeriods(this.timeframe);
                    this.initializeData();
                    this.updateHeatmap();
                });

                d3.select('#update-interval').on('change', (event) => {
                    this.updateInterval = +event.target.value;
                });
            }

            setupHeatmap() {
                // Create SVG
                this.svg = this.container.append('svg')
                    .attr('width', '100%')
                    .attr('height', '100%')
                    .call(this.zoom)
                    .append('g')
                    .attr('transform', `translate(${this.margin.left},${this.margin.top})`);

                // Add clip path
                this.svg.append('defs').append('clipPath')
                    .attr('id', 'heatmap-clip')
                    .append('rect')
                    .attr('width', this.width)
                    .attr('height', this.height);

                // Create heatmap group
                this.heatmapGroup = this.svg.append('g')
                    .attr('clip-path', 'url(#heatmap-clip)');

                // Create axes
                this.xAxisGroup = this.svg.append('g')
                    .attr('class', 'x-axis')
                    .attr('transform', `translate(0,${this.height})`);

                this.yAxisGroup = this.svg.append('g')
                    .attr('class', 'y-axis');

                // Create legend
                this.createLegend();

                // Initial render
                this.updateHeatmap();
            }

            createLegend() {
                const legendValues = [-5, -3, -1, 1, 3, 5];

                this.legendContainer.selectAll('*').remove();

                const legendItems = this.legendContainer.selectAll('.legend-item')
                    .data(legendValues)
                    .enter()
                    .append('div')
                    .attr('class', 'legend-item');

                legendItems.append('div')
                    .attr('class', 'color-box')
                    .style('background-color', d => this.colorScale(d));

                legendItems.append('div')
                    .attr('class', 'legend-value')
                    .text(d => `${d}%`);
            }

            initializeData() {
                // Generate initial random data
                this.data = this.stocks.map(stock => {
                    return {
                        symbol: stock,
                        values: this.timePeriods.map(time => ({
                            time: time,
                            change: (Math.random() * 10 - 5).toFixed(2) // Random change between -5% and 5%
                        }))
                    };
                });
            }

            connectToDataSource() {
                // In a real application, this would connect to a WebSocket or API
                // For this example, we'll simulate connection status
                this.isConnected = true;
                this.updateConnectionStatus();

                // Simulate occasional disconnections
                setInterval(() => {
                    this.isConnected = !this.isConnected;
                    this.updateConnectionStatus();
                }, 30000);
            }

            updateConnectionStatus() {
                this.statusDot.classed('connected', this.isConnected)
                    .classed('disconnected', !this.isConnected);
                this.statusText.text(this.isConnected ? 'Connected' : 'Disconnected');
            }

            generateTimePeriods(timeframe) {
                const now = new Date();
                const periods = [];
                const count = 24; // Number of time periods to display

                switch(timeframe) {
                    case '1h':
                        for (let i = 0; i < count; i++) {
                            const date = new Date(now.getTime() - (count - i) * 5 * 60000); // 5-minute intervals
                            periods.push(date);
                        }
                        break;
                    case '4h':
                        for (let i = 0; i < count; i++) {
                            const date = new Date(now.getTime() - (count - i) * 20 * 60000); // 20-minute intervals
                            periods.push(date);
                        }
                        break;
                    case '1d':
                        for (let i = 0; i < count; i++) {
                            const date = new Date(now.getTime() - (count - i) * 60 * 60000); // 1-hour intervals
                            periods.push(date);
                        }
                        break;
                    case '1w':
                        for (let i = 0; i < count; i++) {
                            const date = new Date(now.getTime() - (count - i) * 6 * 60 * 60000); // 6-hour intervals
                            periods.push(date);
                        }
                        break;
                    case '1m':
                        for (let i = 0; i < count; i++) {
                            const date = new Date(now.getTime() - (count - i) * 24 * 60 * 60000); // 1-day intervals
                            periods.push(date);
                        }
                        break;
                }

                return periods;
            }

            updateLoop() {
                const now = Date.now();

                if (this.isConnected && (now - this.lastUpdate) > this.updateInterval) {
                    this.updateData();
                    this.updateHeatmap();
                    this.lastUpdate = now;
                }

                requestAnimationFrame(() => this.updateLoop());
            }

            updateData() {
                // Simulate receiving new data
                this.data.forEach(stock => {
                    // Update the most recent time period
                    const lastIndex = stock.values.length - 1;
                    const lastChange = parseFloat(stock.values[lastIndex].change);

                    // Generate a new change value based on previous value
                    const newChange = (lastChange + (Math.random() * 2 - 1)).toFixed(2);

                    // Shift all values left and add new value
                    stock.values.shift();
                    stock.values.push({
                        time: new Date(),
                        change: newChange
                    });
                });
            }

            updateHeatmap() {
                if (!this.data || this.data.length === 0) return;

                // Set up scales
                const xScale = d3.scaleBand()
                    .domain(this.timePeriods.map(d => d.toISOString()))
                    .range([0, this.width])
                    .padding(0.05);

                const yScale = d3.scaleBand()
                    .domain(this.stocks)
                    .range([0, this.height])
                    .padding(0.05);

                // Update axes
                const xAxis = d3.axisBottom(xScale)
                    .tickFormat(d => {
                        const date = new Date(d);
                        return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                    });

                const yAxis = d3.axisLeft(yScale);

                this.xAxisGroup.call(xAxis)
                    .selectAll('text')
                    .attr('transform', 'rotate(-45)')
                    .style('text-anchor', 'end');

                this.yAxisGroup.call(yAxis);

                // Create or update cells
                const cells = this.heatmapGroup.selectAll('.cell')
                    .data(this.data.flatMap(d =>
                        d.values.map(v => ({
                            symbol: d.symbol,
                            time: v.time.toISOString(),
                            change: v.change
                        }))
                    ));

                // Enter new cells
                cells.enter()
                    .append('rect')
                    .attr('class', 'cell')
                    .attr('x', d => xScale(d.time))
                    .attr('y', d => yScale(d.symbol))
                    .attr('width', xScale.bandwidth())
                    .attr('height', yScale.bandwidth())
                    .attr('fill', d => this.colorScale(d.change))
                    .on('mouseover', (event, d) => this.showTooltip(event, d))
                    .on('mouseout', () => this.hideTooltip())
                    .merge(cells)
                    .transition()
                    .duration(300)
                    .attr('fill', d => this.colorScale(d.change));

                // Remove old cells
                cells.exit().remove();
            }

            showTooltip(event, d) {
                const [x, y] = d3.pointer(event);

                this.tooltip.style('opacity', 1)
                    .style('left', `${x + 10}px`)
                    .style('top', `${y + 10}px`)
                    .html(`
                        <strong>${d.symbol}</strong><br>
                        Time: ${new Date(d.time).toLocaleTimeString()}<br>
                        Change: ${d.change}%
                    `);
            }

            hideTooltip() {
                this.tooltip.style('opacity', 0);
            }

            zoomed(event) {
                const { transform } = event;
                this.heatmapGroup.attr('transform', transform);
                this.xAxisGroup.attr('transform', `translate(0,${this.height}) scale(${1/transform.k})`);
                this.yAxisGroup.attr('transform', `scale(${1/transform.k})`);
            }
        }
    </script>
</body>
</html>
```

## Key Features

1. **Interactive Heatmap**:
