## JavaScript Implementation (script.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 20, right: 20, bottom: 20, left: 20 },
    timeRanges: {
        '1d': { days: 1, label: '1 Day' },
        '1w': { days: 7, label: '1 Week' },
        '1m': { days: 30, label: '1 Month' },
        '3m': { days: 90, label: '3 Months' },
        '1y': { days: 365, label: '1 Year' },
        '5y': { days: 365 * 5, label: '5 Years' }
    },
    updateInterval: 60000, // 1 minute
    zoomFactor: 1.5
};

// DOM Elements
const heatmapContainer = d3.select('#heatmap-container');
const tooltip = d3.select('.tooltip');
const loading = d3.select('.loading');

// State
let currentRange = '1m';
let stockData = [];
let zoomTransform = d3.zoomIdentity;
let updateIntervalId;

// Initialize
function init() {
    setupEventListeners();
    fetchStockData(currentRange);
    startAutoUpdate();
}

// Set up event listeners
function setupEventListeners() {
    // Time range buttons
    d3.selectAll('.time-range button').on('click', function() {
        const range = d3.select(this).attr('id');
        if (range !== currentRange) {
            currentRange = range;
            d3.selectAll('.time-range button').classed('active', false);
            d3.select(this).classed('active', true);
            fetchStockData(currentRange);
        }
    });

    // Refresh button
    d3.select('#refresh').on('click', () => {
        fetchStockData(currentRange);
    });

    // Zoom controls
    d3.select('#zoom-in').on('click', () => {
        zoomTransform = zoomTransform.scaleBy(heatmapContainer.node(), config.zoomFactor);
        applyZoom();
    });

    d3.select('#zoom-out').on('click', () => {
        zoomTransform = zoomTransform.scaleBy(heatmapContainer.node(), 1 / config.zoomFactor);
        applyZoom();
    });

    d3.select('#reset-zoom').on('click', () => {
        zoomTransform = d3.zoomIdentity;
        applyZoom();
    });

    // Set up zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on('zoom', (event) => {
            zoomTransform = event.transform;
            applyZoom();
        });

    heatmapContainer.call(zoom);
}

// Fetch stock data (simulated with mock data)
function fetchStockData(range) {
    loading.style('display', 'block');

    // In a real implementation, this would be an API call to a stock data service
    // For demo purposes, we'll generate mock data
    setTimeout(() => {
        generateMockData(range);
        renderHeatmap();
        loading.style('display', 'none');
    }, 500);
}

// Generate mock stock data
function generateMockData(range) {
    const days = config.timeRanges[range].days;
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - days);

    // Generate a list of 20-30 stocks
    const stocks = [];
    const numStocks = 20 + Math.floor(Math.random() * 11);

    for (let i = 0; i < numStocks; i++) {
        stocks.push({
            symbol: generateStockSymbol(),
            name: `Company ${String.fromCharCode(65 + i)}`
        });
    }

    // Generate price data for each stock
    stockData = stocks.map(stock => {
        const prices = [];
        const basePrice = 50 + Math.random() * 150;

        for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
            // Generate a random price change
            const change = (Math.random() - 0.5) * 2; // -1 to +1
            const price = basePrice + change;

            prices.push({
                date: new Date(d),
                price: parseFloat(price.toFixed(2)),
                change: parseFloat(change.toFixed(2))
            });
        }

        return {
            symbol: stock.symbol,
            name: stock.name,
            prices: prices
        };
    });
}

// Generate a random stock symbol
function generateStockSymbol() {
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const first = letters.charAt(Math.floor(Math.random() * letters.length));
    const second = letters.charAt(Math.floor(Math.random() * letters.length));
    const number = Math.floor(Math.random() * 1000);
    return `${first}${second}${number.toString().padStart(3, '0')}`;
}

// Render the heatmap
function renderHeatmap() {
    // Clear previous heatmap
    heatmapContainer.selectAll('svg').remove();

    if (stockData.length === 0) return;

    // Prepare data for heatmap
    const dates = stockData[0].prices.map(d => d.date);
    const stocks = stockData.map(d => d.symbol);

    // Create scales
    const xScale = d3.scaleBand()
        .domain(dates)
        .range([0, config.width - config.margin.left - config.margin.right])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, config.height - config.margin.top - config.margin.bottom])
        .padding(0.05);

    // Create color scale
    const colorScale = d3.scaleLinear()
        .domain([-1, 0, 1]) // Price change range
        .range(['#e74c3c', '#f39c12', '#2ecc71']);

    // Create SVG
    const svg = heatmapContainer.append('svg')
        .attr('width', config.width)
        .attr('height', config.height)
        .append('g')
        .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

    // Create heatmap cells
    svg.selectAll('.cell')
        .data(stockData.flatMap(stock =>
            stock.prices.map(price => ({
                stock: stock.symbol,
                date: price.date,
                price: price.price,
                change: price.change
            }))
        ))
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.date))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', function(event, d) {
            tooltip.style('opacity', 1)
                .html(`
                    <strong>${d.stock}</strong><br>
                    Date: ${d.date.toLocaleDateString()}<br>
                    Price: $${d.price}<br>
                    Change: ${d.change > 0 ? '+' : ''}${d.change}%
                `)
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY + 10) + 'px');
        })
        .on('mouseout', () => {
            tooltip.style('opacity', 0);
        });

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat('%b %d'))
        .ticks(Math.min(10, dates.length));

    const yAxis = d3.axisLeft(yScale);

    svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    svg.append('g')
        .attr('class', 'y-axis')
        .call(yAxis);

    // Apply initial zoom
    applyZoom();
}

// Apply zoom transformation
function applyZoom() {
    const svg = heatmapContainer.select('svg g');
    if (!svg.empty()) {
        svg.attr('transform', zoomTransform);
    }
}

// Start auto-updating the data
function startAutoUpdate() {
    if (updateIntervalId) clearInterval(updateIntervalId);

    updateIntervalId = setInterval(() => {
        fetchStockData(currentRange);
    }, config.updateInterval);
}

// Initialize the application
init();
```

## Features Implemented

1. **Interactive Heatmap**:
   - Visualizes stock price changes over time
   - Color-coded cells showing positive (green), neutral (orange), and negative (red) changes

