```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Configuration
    const config = {
        containerId: '#heatmap-container',
        width: 1200,
        height: 600,
        margin: { top: 50, right: 50, bottom: 50, left: 100 },
        colorScheme: d3.interpolateRdYlGn,
        updateInterval: 30000, // 30 seconds
        maxZoom: 10,
        minZoom: 0.5
    };

    // DOM elements
    const timeframeSelect = document.getElementById('timeframe');
    const stockCountSelect = document.getElementById('stock-count');
    const refreshBtn = document.getElementById('refresh-btn');
    const zoomInBtn = document.getElementById('zoom-in');
    const zoomOutBtn = document.getElementById('zoom-out');
    const resetZoomBtn = document.getElementById('reset-zoom');
    const tooltip = document.getElementById('tooltip');
    const legendContainer = document.getElementById('legend');

    // State variables
    let currentData = null;
    let svg = null;
    let xScale = null;
    let yScale = null;
    let colorScale = null;
    let zoom = null;
    let updateIntervalId = null;

    // Initialize the heatmap
    function initHeatmap() {
        // Clear previous SVG if it exists
        d3.select(config.containerId).select('svg').remove();

        // Create SVG container
        svg = d3.select(config.containerId)
            .append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Add zoom behavior
        zoom = d3.zoom()
            .scaleExtent([config.minZoom, config.maxZoom])
            .on('zoom', zoomed);

        svg.call(zoom);

        // Add group for heatmap
        svg.append('g')
            .attr('class', 'heatmap-group');

        // Add axes groups
        svg.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0, ${config.height - config.margin.bottom})`);

        svg.append('g')
            .attr('class', 'y-axis')
            .attr('transform', `translate(${config.margin.left}, 0)`);

        // Add axis labels
        svg.append('text')
            .attr('class', 'x-axis-label')
            .attr('x', config.width / 2)
            .attr('y', config.height - 10)
            .style('text-anchor', 'middle')
            .text('Time');

        svg.append('text')
            .attr('class', 'y-axis-label')
            .attr('transform', 'rotate(-90)')
            .attr('x', -config.height / 2)
            .attr('y', 20)
            .style('text-anchor', 'middle')
            .text('Stock Symbol');

        // Hide loading indicator
        d3.select('.loading').style('display', 'none');
    }

    // Fetch mock data (in a real app, this would be an API call)
    function fetchData() {
        d3.select('.loading').style('display', 'block');

        // Simulate API call delay
        setTimeout(() => {
            const timeframe = timeframeSelect.value;
            const stockCount = parseInt(stockCountSelect.value);

            // Generate mock data
            const data = generateMockData(timeframe, stockCount);
            currentData = data;

            // Process and render data
            processData(data);

            // Hide loading indicator
            d3.select('.loading').style('display', 'none');
        }, 500);
    }

    // Generate mock data for demonstration
    function generateMockData(timeframe, stockCount) {
        const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.A', 'JNJ', 'JPM', 'V', 'PG', 'NVDA', 'HD', 'MA', 'DIS', 'VZ', 'PYPL', 'ADBE', 'CRM', 'NFLX', 'INTC', 'CMCSA', 'PEP', 'KO', 'T', 'MRK', 'ABT', 'AVGO', 'COST', 'MCD', 'WMT', 'XOM', 'CVX', 'BMY', 'AMGN', 'QCOM', 'TXN', 'NKE', 'PM', 'DHR', 'UNH', 'LIN', 'AMD', 'IBM', 'ORCL', 'CSCO', 'INTU', 'ADP', 'SAP', 'SQ', 'SHOP', 'ZM', 'UBER', 'LYFT', 'SPLK', 'SNOW', 'DDOG', 'WORK', 'ROKU', 'TWTR', 'SNAP', 'ZM', 'SPOT', 'ROKU', 'TWLO', 'OKTA', 'ZS', 'DOCU', 'ZM'];

        // Select random stocks
        const selectedSymbols = [];
        for (let i = 0; i < stockCount; i++) {
            const randomIndex = Math.floor(Math.random() * symbols.length);
            selectedSymbols.push(symbols[randomIndex]);
        }

        // Generate time points based on timeframe
        const now = new Date();
        let timePoints = [];
        let interval;

        switch(timeframe) {
            case '1d':
                interval = 30 * 60 * 1000; // 30 minutes
                for (let i = 0; i < 48; i++) {
                    timePoints.push(new Date(now - i * interval));
                }
                break;
            case '1w':
                interval = 2 * 60 * 60 * 1000; // 2 hours
                for (let i = 0; i < 84; i++) {
                    timePoints.push(new Date(now - i * interval));
                }
                break;
            case '1m':
                interval = 6 * 60 * 60 * 1000; // 6 hours
                for (let i = 0; i < 60; i++) {
                    timePoints.push(new Date(now - i * interval));
                }
                break;
            case '3m':
                interval = 12 * 60 * 60 * 1000; // 12 hours
                for (let i = 0; i < 90; i++) {
                    timePoints.push(new Date(now - i * interval));
                }
                break;
            case '1y':
                interval = 24 * 60 * 60 * 1000; // 1 day
                for (let i = 0; i < 365; i++) {
                    timePoints.push(new Date(now - i * interval));
                }
                break;
        }

        // Generate data points
        const data = [];
        const basePrices = {};

        selectedSymbols.forEach(symbol => {
            // Generate a base price for the stock
            basePrices[symbol] = 100 + Math.random() * 400;

            timePoints.forEach(time => {
                // Generate a random price change
                const change = (Math.random() - 0.5) * 2; // -1 to +1
                const price = basePrices[symbol] + change;

                data.push({
                    symbol: symbol,
                    time: time,
                    price: price,
                    change: change
                });
            });
        });

        return data;
    }

    // Process data and create scales
    function processData(data) {
        if (!data || data.length === 0) return;

        // Extract unique symbols and times
        const symbols = [...new Set(data.map(d => d.symbol))];
        const times = [...new Set(data.map(d => d.time))].sort((a, b) => a - b);

        // Create scales
        const cellWidth = (config.width - config.margin.left - config.margin.right) / times.length;
        const cellHeight = (config.height - config.margin.top - config.margin.bottom) / symbols.length;

        xScale = d3.scaleBand()
            .domain(times.map(d => d.toISOString()))
            .range([config.margin.left, config.width - config.margin.right])
            .padding(0.01);

        yScale = d3.scaleBand()
            .domain(symbols)
            .range([config.margin.top, config.height - config.margin.bottom])
            .padding(0.01);

        // Find price range for color scale
        const prices = data.map(d => d.price);
        const minPrice = d3.min(prices);
        const maxPrice = d3.max(prices);

        colorScale = d3.scaleSequential(config.colorScheme)
            .domain([minPrice, maxPrice]);

        // Update legend
        updateLegend(minPrice, maxPrice);

        // Render heatmap
        renderHeatmap(data);
    }

    // Render the heatmap
    function renderHeatmap(data) {
        const heatmapGroup = svg.select('.heatmap-group');

        // Remove existing cells
        heatmapGroup.selectAll('.cell').remove();

        // Add cells
        const cells = heatmapGroup.selectAll('.cell')
            .data(data)
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => xScale(d.time.toISOString()))
            .attr('y', d => yScale(d.symbol))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.price))
            .on('mouseover', showTooltip)
            .on('mouseout', hideTooltip);

        // Update axes
        updateAxes();
    }

    // Update axes based on current scales
    function updateAxes() {
        const xAxis = d3.axisBottom(xScale)
            .tickFormat(d => {
                const date = new Date(d);
                return d3.timeFormat('%b %d')(date);
            })
            .ticks(10);

        const yAxis = d3.axisLeft(yScale)
            .ticks(10);

        svg.select('.x-axis')
            .call(xAxis)
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        svg.select('.y-axis')
            .call(yAxis);
    }

    // Show tooltip on hover
    function showTooltip(event, d) {
        const [x, y] = d3.pointer(event);

        tooltip.style.display = 'block';
        tooltip.style.left = `${x + 10}px`;
        tooltip.style.top = `${y + 10}px`;

        tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br>
            Time: ${d3.timeFormat('%Y-%m-%d %H:%M')(d.time)}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}
        `;
    }

    // Hide tooltip
    function hideTooltip() {
        tooltip.style.display = 'none';
    }

    // Update legend
    function updateLegend(minPrice, maxPrice) {
        legendContainer.innerHTML = '';

        // Create gradient for legend
        const legendWidth = 200;
        const legendHeight = 20;

        const legendSvg = d3.select(legendContainer)
            .append('svg')
            .attr('width', legendWidth)
            .attr('height', legendHeight);

        const legendGradient = legendSvg.append('defs')
            .append('linearGradient')
            .attr('id', 'legend-gradient')
            .attr('x1', '0%')
            .attr('y1', '0%')
            .attr('x2', '100%')
            .attr('y2', '0%');

        legendGradient.append('stop')
            .attr('offset', '0%')
            .attr('stop-color', config.colorScheme(0));

        legendGradient.append('stop')
            .attr('offset', '100%')
            .attr('stop-color', config.colorScheme(1));

        legendSvg.append('rect')
            .attr('width', legendWidth)
            .attr('height', legendHeight)
            .style('fill', 'url(#legend-gradient)');

        // Add min and max labels
        legendContainer.innerHTML += `
            <div class="legend-item">
                <div class="legend-color" style="background: ${config.colorScheme(0)}"></div>
                <span>$${minPrice.toFixed(2)}</span>
            </div>
            <div class="legend-item">
                <div class="legend-color" style="background: ${config.colorScheme(1)}"></div>
                <span>$${maxPrice.toFixed(2)}</span>
            </div>
        `;
    }

    // Zoom handler
    function zoomed(event) {
        const transform = event.transform;

        // Apply transform to heatmap group
        svg.select('.heatmap-group')
            .attr('transform', transform);

        // Update axes
        const newXScale = transform.rescaleX(xScale);
        const newYScale = transform.rescaleY(yScale);

        const xAxis = d3.axisBottom(newXScale)
            .tickFormat(d => {
                const date = new Date(d);
                return d3.timeFormat('%b %d')(date);
            })
            .ticks(10);

        const yAxis = d3.axisLeft(newYScale)
            .ticks(10);

        svg.select('.x-axis').call(xAxis);
        svg.select('.y-axis').call(yAxis);
    }

    // Event listeners
    timeframeSelect.addEventListener('change', fetchData);
    stockCountSelect.addEventListener('change', fetchData);
    refreshBtn.addEventListener('click', fetchData);

    zoomInBtn.addEventListener('click', () => {
        svg.transition().call(zoom.scaleBy, 1.5);
    });

    zoomOutBtn.addEventListener('click', () => {
        svg.transition().call(zoom.scaleBy, 0.5);
    });

    resetZoomBtn.addEventListener('click', () => {
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });

    // Initialize
    initHeatmap();
    fetchData();

    // Set up periodic updates
    updateIntervalId = setInterval(fetchData, config.updateInterval);

    // Clean up on page unload
    window.addEventListener('beforeunload', () => {
        clearInterval(updateIntervalId);
    });
});
