    const svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Add zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    // Create main group for the heatmap
    const g = svg.append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Add axes groups
    const xAxisGroup = g.append("g")
        .attr("class", "axis axis--x");

    const yAxisGroup = g.append("g")
        .attr("class", "axis axis--y");

    // Add color scale
    const colorScale = d3.scaleQuantile()
        .range(config.colors);

    // Add time scale
    const xScale = d3.scaleTime()
        .range([0, config.width - config.margin.left - config.margin.right]);

    // Add stock scale
    const yScale = d3.scaleBand()
        .range([0, config.height - config.margin.top - config.margin.bottom]);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat("%b %d"));

    const yAxis = d3.axisLeft(yScale);

    // Data storage
    let heatmapData = [];
    let currentData = [];

    // Initialize the visualization
    init();

    // Event listeners
    document.getElementById('timeframe').addEventListener('change', function() {
        config.timeframe = this.value;
        fetchData();
    });

    document.getElementById('stocks').addEventListener('change', function() {
        config.stocks = Array.from(this.selectedOptions).map(option => option.value);
        updateVisualization();
    });

    document.getElementById('refresh-btn').addEventListener('click', fetchData);
    document.getElementById('reset-btn').addEventListener('click', resetView);

    // Functions
    function init() {
        // Create legend
        createLegend();

        // Fetch initial data
        fetchData();

        // Set up resize handler
        window.addEventListener('resize', handleResize);
    }

    function createLegend() {
        const legend = d3.select("#legend");

        // Clear existing legend
        legend.selectAll("*").remove();

        // Add legend items
        const legendItems = legend.selectAll(".legend-item")
            .data(config.colors)
            .enter()
            .append("div")
            .attr("class", "legend-item");

        legendItems.append("div")
            .attr("class", "legend-color")
            .style("background-color", d => d);

        legendItems.append("span")
            .text((d, i) => {
                const extent = colorScale.invertExtent(d);
                if (i === 0) return `< ${extent[1].toFixed(2)}`;
                if (i === config.colors.length - 1) return `> ${extent[0].toFixed(2)}`;
                return `${extent[0].toFixed(2)} - ${extent[1].toFixed(2)}`;
            });
    }

    function fetchData() {
        // In a real implementation, this would fetch from an API
        // For this demo, we'll simulate data
        showLoading(true);

        // Simulate API delay
        setTimeout(() => {
            generateMockData();
            showLoading(false);
        }, 500);
    }

    function generateMockData() {
        // Clear existing data
        heatmapData = [];

        // Generate mock data for selected stocks
        config.stocks.forEach(stock => {
            const stockData = generateStockData(stock);
            heatmapData.push(...stockData);
        });

        // Update visualization
        updateVisualization();
    }

    function generateStockData(stock) {
        const data = [];
        const now = new Date();
        const timeframeDays = {
            '1d': 1,
            '1w': 7,
            '1m': 30,
            '3m': 90,
            '1y': 365
        }[config.timeframe];

        // Generate data points for the timeframe
        for (let i = 0; i < timeframeDays; i++) {
            const date = new Date(now);
            date.setDate(date.getDate() - (timeframeDays - i));

            // Generate a random price change percentage
            const change = (Math.random() * 10 - 5).toFixed(2);

            data.push({
                stock: stock,
                date: date,
                change: parseFloat(change)
            });
        }

        return data;
    }

    function updateVisualization() {
        // Filter data for selected stocks
        currentData = heatmapData.filter(d => config.stocks.includes(d.stock));

        if (currentData.length === 0) {
            showLoading(true, "No data available for selected stocks");
            return;
        }

        // Update scales
        updateScales();

        // Update axes
        updateAxes();

        // Update heatmap
        updateHeatmap();

        // Update legend
        createLegend();
    }

    function updateScales() {
        // Update domain for color scale
        const changes = currentData.map(d => d.change);
        colorScale.domain([d3.min(changes), d3.max(changes)]);

        // Update domain for x scale
        const dates = currentData.map(d => d.date);
        xScale.domain(d3.extent(dates));

        // Update domain for y scale
        const stocks = [...new Set(currentData.map(d => d.stock))];
        yScale.domain(stocks).padding(0.1);
    }

    function updateAxes() {
        xAxisGroup.call(xAxis);
        yAxisGroup.call(yAxis);
    }

    function updateHeatmap() {
        // Remove existing heatmap
        g.selectAll(".heatmap-cell").remove();

        // Add new cells
        const cells = g.selectAll(".heatmap-cell")
            .data(currentData)
            .enter()
            .append("rect")
            .attr("class", "heatmap-cell")
            .attr("x", d => xScale(d.date))
            .attr("y", d => yScale(d.stock))
            .attr("width", xScale(new Date(currentData[0].date.getTime() + 24 * 60 * 60 * 1000)) - xScale(currentData[0].date))
            .attr("height", yScale.bandwidth())
            .attr("fill", d => colorScale(d.change))
            .on("mouseover", showTooltip)
            .on("mouseout", hideTooltip);
    }

    function showTooltip(event, d) {
        config.tooltip.style("display", "block")
            .html(`
                <strong>${d.stock}</strong><br>
                Date: ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                Change: ${d.change.toFixed(2)}%
            `)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
    }

    function hideTooltip() {
        config.tooltip.style("display", "none");
    }

    function zoomed(event) {
        const transform = event.transform;
        g.attr("transform", `translate(${config.margin.left + transform.x},${config.margin.top + transform.y}) scale(${transform.k})`);
    }

    function resetView() {
        svg.transition()
            .duration(750)
            .call(zoom.transform, d3.zoomIdentity);
    }

    function showLoading(show, message = "Loading data...") {
        const loadingDiv = d3.select("#heatmap-container .loading");
        if (show) {
            loadingDiv.style("display", "block").text(message);
            svg.style("display", "none");
        } else {
            loadingDiv.style("display", "none");
            svg.style("display", "block");
        }
    }

    function handleResize() {
        // Update container dimensions
        config.width = document.getElementById('heatmap-container').clientWidth;
        config.height = document.getElementById('heatmap-container').clientHeight;

        // Update SVG dimensions
        svg.attr("width", config.width)
           .attr("height", config.height);

        // Update scales and visualization
        updateScales();
        updateAxes();
        updateHeatmap();
    }
});
```

