## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    updateInterval: 30000, // 30 seconds
    defaultTimeframe: '1M',
    defaultStocks: ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT'],
    colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1])
};

// State
let state = {
    data: [],
    timeframe: config.defaultTimeframe,
    selectedStocks: [...config.defaultStocks],
    zoom: d3.zoom(),
    svg: null,
    xScale: null,
    yScale: null,
    tooltip: null,
    legend: null,
    lastUpdate: null
};

// DOM Elements
const elements = {
    container: document.getElementById('heatmap-container'),
    timeframeSelect: document.getElementById('timeframe'),
    stockSelect: document.getElementById('stock-select'),
    refreshBtn: document.getElementById('refresh-btn'),
    resetBtn: document.getElementById('reset-btn'),
    tooltip: document.getElementById('tooltip'),
    legend: document.getElementById('legend')
};

// Initialize the application
function init() {
    // Set up event listeners
    elements.timeframeSelect.addEventListener('change', handleTimeframeChange);
    elements.stockSelect.addEventListener('change', handleStockSelectionChange);
    elements.refreshBtn.addEventListener('click', fetchData);
    elements.resetBtn.addEventListener('click', resetView);

    // Initialize the visualization
    initVisualization();

    // Fetch initial data
    fetchData();

    // Set up periodic updates
    setInterval(fetchData, config.updateInterval);
}

// Initialize the D3 visualization
function initVisualization() {
    // Clear any existing SVG
    d3.select(elements.container).selectAll('*').remove();

    // Create SVG element
    const width = elements.container.clientWidth;
    const height = elements.container.clientHeight;

    state.svg = d3.select(elements.container)
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height])
        .attr('preserveAspectRatio', 'xMidYMid meet');

    // Initialize scales
    state.xScale = d3.scaleBand();
    state.yScale = d3.scaleBand();

    // Initialize zoom behavior
    state.zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on('zoom', handleZoom);

    state.svg.call(state.zoom);

    // Initialize tooltip
    state.tooltip = d3.select(elements.tooltip);

    // Initialize legend
    createLegend();
}

// Create the legend
function createLegend() {
    // Clear existing legend
    d3.select(elements.legend).selectAll('*').remove();

    // Create legend items
    const legendData = [
        { value: -0.1, label: '-10%' },
        { value: -0.05, label: '-5%' },
        { value: 0, label: '0%' },
        { value: 0.05, label: '+5%' },
        { value: 0.1, label: '+10%' }
    ];

    const legendGroup = d3.select(elements.legend)
        .selectAll('.legend-item')
        .data(legendData)
        .enter()
        .append('div')
        .attr('class', 'legend-item');

    legendGroup.append('div')
        .attr('class', 'legend-color')
        .style('background-color', d => config.colorScale(d.value));

    legendGroup.append('span')
        .text(d => d.label);
}

// Handle zoom/pan events
function handleZoom(event) {
    const { transform } = event;
    state.svg.select('g').attr('transform', transform);
}

// Reset the view to default
function resetView() {
    state.svg.transition()
        .duration(750)
        .call(state.zoom.transform, d3.zoomIdentity);
}

// Handle timeframe selection change
function handleTimeframeChange() {
    state.timeframe = elements.timeframeSelect.value;
    fetchData();
}

// Handle stock selection change
function handleStockSelectionChange() {
    state.selectedStocks = Array.from(elements.stockSelect.selectedOptions)
        .map(option => option.value);
    updateVisualization();
}

// Fetch data from API (mock implementation)
async function fetchData() {
    try {
        // Show loading indicator
        d3.select(elements.container).select('.loading').style('display', 'block');

        // In a real implementation, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
        // This is a mock implementation that generates random data
        const mockData = generateMockData();

        // Process the data
        state.data = processData(mockData);
        state.lastUpdate = new Date();

        // Update the visualization
        updateVisualization();

        // Hide loading indicator
        d3.select(elements.container).select('.loading').style('display', 'none');
    } catch (error) {
        console.error('Error fetching data:', error);
        d3.select(elements.container).select('.loading').text('Error loading data. Please try again.');
    }
}

// Generate mock data for demonstration
function generateMockData() {
    const stocks = state.selectedStocks.length > 0 ? state.selectedStocks : config.defaultStocks;
    const timeframe = state.timeframe || config.defaultTimeframe;

    // Determine number of time points based on timeframe
    let numPoints;
    switch (timeframe) {
        case '1D': numPoints = 24; break; // Hourly for 1 day
        case '1W': numPoints = 7; break; // Daily for 1 week
        case '1M': numPoints = 30; break; // Daily for 1 month
        case '3M': numPoints = 90; break; // Daily for 3 months
        case '1Y': numPoints = 12; break; // Monthly for 1 year
        default: numPoints = 30;
    }

    // Generate mock data
    const data = [];
    const now = new Date();

    for (let i = 0; i < numPoints; i++) {
        const time = new Date(now);
        switch (timeframe) {
            case '1D': time.setHours(now.getHours() - i); break;
            case '1W': time.setDate(now.getDate() - i); break;
            case '1M':
            case '3M':
                time.setDate(now.getDate() - i);
                break;
            case '1Y':
                time.setMonth(now.getMonth() - i);
                break;
        }

        stocks.forEach(stock => {
            // Generate random price change between -10% and +10%
            const change = (Math.random() * 20 - 10) / 100;
            data.push({
                stock,
                time: time.toISOString(),
                change
            });
        });
    }

    return data;
}

// Process the raw data into a format suitable for visualization
function processData(rawData) {
    // Group data by stock
    const grouped = d3.group(rawData, d => d.stock);

    // Convert to array of objects with stock and time series data
    const processed = Array.from(grouped, ([stock, values]) => {
        // Sort by time
        values.sort((a, b) => new Date(a.time) - new Date(b.time));

        return {
            stock,
            values: values.map(d => ({
                time: new Date(d.time),
                change: d.change
            }))
        };
    });

    return processed;
}

// Update the visualization with new data
function updateVisualization() {
    if (!state.data || state.data.length === 0) return;

    // Get dimensions
    const width = elements.container.clientWidth;
    const height = elements.container.clientHeight;

    // Clear previous visualization
    state.svg.selectAll('*').remove();

    // Create main group for zoom/pan
    const g = state.svg.append('g');

    // Set up scales
    const stocks = state.data.map(d => d.stock);
    const times = state.data[0].values.map(d => d.time);

    state.xScale.domain(times)
        .range([0, width])
        .padding(0.1);

    state.yScale.domain(stocks)
        .range([0, height])
        .padding(0.1);

    // Create heatmap cells
    const cells = g.selectAll('.cell')
        .data(state.data)
        .enter()
        .append('g')
        .attr('class', 'cell-group')
        .selectAll('.cell')
        .data(d => d.values.map(v => ({
            stock: d.stock,
            time: v.time,
            change: v.change
        })))
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => state.xScale(d.time))
        .attr('y', d => state.yScale(d.stock))
        .attr('width', state.xScale.bandwidth())
        .attr('height', state.yScale.bandwidth())
        .attr('fill', d => config.colorScale(d.change))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(state.xScale)
        .tickFormat(d3.timeFormat(getTimeFormat(state.timeframe)))
        .tickSizeOuter(0);

    const yAxis = d3.axisLeft(state.yScale)
        .tickSizeOuter(0);

    g.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0, ${height})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    g.append('g')
        .attr('class', 'y-axis')
        .call(yAxis);

    // Add grid lines
    g.append('g')
        .attr('class', 'grid')
        .attr('transform', `translate(0, ${height})`)
        .call(d3.axisBottom(state.xScale)
            .tickSize(-height)
            .tickFormat(''))
        .selectAll('line')
        .attr('stroke', '#eee');

    g.append('g')
        .attr('class', 'grid')
        .call(d3.axisLeft(state.yScale)
            .tickSize(-width)
            .tickFormat(''))
        .selectAll('line')
        .attr('stroke', '#eee');
}

// Determine appropriate time format based on timeframe
function getTimeFormat(timeframe) {
    switch (timeframe) {
        case '1D': return '%H:%M';
        case '1W':
        case '1M':
        case '3M': return '%b %d';
        case '1Y': return '%b %Y';
        default: return '%b %d';
    }
}

// Show tooltip on hover
function showTooltip(event, d) {
    state.tooltip.style('visibility', 'visible')
        .html(`
            <strong>${d.stock}</strong><br>
            Time: ${d3.timeFormat('%Y-%m-%d %H:%M')(d.time)}<br>
            Change: ${(d.change * 100).toFixed(2)}%
        `)
        .style('left', `${event.pageX + 10}px`)
        .style('top', `${event.pageY + 10}px`);
}

// Hide tooltip
function hideTooltip() {
    state.tooltip.style('visibility', 'hidden');
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
