## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    updateInterval: 5000, // 5 seconds
    maxStocks: 100,
    defaultStocks: 20,
    defaultTimeframe: '1w',
    colors: ['#ff0000', '#ff6666', '#ffcccc', '#ffffff', '#ccffcc', '#66ff66', '#00cc00']
};

// State
let state = {
    data: [],
    autoUpdate: true,
    lastUpdate: null,
    zoomTransform: d3.zoomIdentity,
    selectedStocks: [],
    availableStocks: [
        'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.B', 'JNJ', 'JPM', 'V',
        'PG', 'NVDA', 'HD', 'MA', 'DIS', 'PYPL', 'ADBE', 'CRM', 'NFLX', 'INTC',
        'VZ', 'CMCSA', 'PEP', 'KO', 'T', 'MRK', 'ABT', 'XOM', 'CVX', 'WMT'
    ]
};

// DOM Elements
const elements = {
    heatmapContainer: document.getElementById('heatmap-container'),
    timeframeSelect: document.getElementById('timeframe'),
    stockCountInput: document.getElementById('stock-count'),
    refreshBtn: document.getElementById('refresh-btn'),
    autoUpdateBtn: document.getElementById('auto-update-btn'),
    legend: document.getElementById('legend'),
    status: document.getElementById('status'),
    tooltip: document.querySelector('.tooltip')
};

// Initialize the application
function init() {
    // Set up event listeners
    elements.timeframeSelect.addEventListener('change', handleTimeframeChange);
    elements.stockCountInput.addEventListener('change', handleStockCountChange);
    elements.refreshBtn.addEventListener('click', fetchData);
    elements.autoUpdateBtn.addEventListener('click', toggleAutoUpdate);

    // Initialize selected stocks
    state.selectedStocks = state.availableStocks.slice(0, config.defaultStocks);

    // Fetch initial data
    fetchData();

    // Set up auto-update
    setInterval(() => {
        if (state.autoUpdate) {
            fetchData();
        }
    }, config.updateInterval);
}

// Fetch stock data (simulated with mock data)
async function fetchData() {
    try {
        // Show loading indicator
        elements.heatmapContainer.querySelector('.loading').style.display = 'block';

        // In a real application, you would fetch from an API like:
        // const response = await fetch(`/api/stocks?timeframe=${elements.timeframeSelect.value}&count=${elements.stockCountInput.value}`);
        // const data = await response.json();

        // Simulate API call with mock data
        const mockData = generateMockData();
        state.data = mockData;

        // Update last update time
        state.lastUpdate = new Date();
        updateStatus();

        // Render the heatmap
        renderHeatmap();

        // Hide loading indicator
        elements.heatmapContainer.querySelector('.loading').style.display = 'none';
    } catch (error) {
        console.error('Error fetching data:', error);
        elements.heatmapContainer.querySelector('.loading').style.display = 'none';
    }
}

// Generate mock data for demonstration
function generateMockData() {
    const timeframe = elements.timeframeSelect.value;
    const stockCount = Math.min(parseInt(elements.stockCountInput.value), config.maxStocks);

    // Determine number of time points based on timeframe
    let timePoints;
    switch (timeframe) {
        case '1d': timePoints = 24; break;
        case '1w': timePoints = 7; break;
        case '1m': timePoints = 30; break;
        case '3m': timePoints = 90; break;
        case '1y': timePoints = 12; break;
        default: timePoints = 7;
    }

    // Generate mock data
    const data = [];
    const selectedStocks = state.selectedStocks.slice(0, stockCount);

    for (let i = 0; i < selectedStocks.length; i++) {
        const stockData = {
            symbol: selectedStocks[i],
            values: []
        };

        // Generate random price changes
        for (let j = 0; j < timePoints; j++) {
            // Base price (random between 50 and 500)
            const basePrice = 50 + Math.random() * 450;

            // Random percentage change (-5% to +5%)
            const changePercent = (Math.random() - 0.5) * 10;

            // Calculate new price
            const newPrice = basePrice * (1 + changePercent / 100);

            // Time label (simplified)
            let timeLabel;
            switch (timeframe) {
                case '1d': timeLabel = `${j}:00`; break;
                case '1w': timeLabel = `Day ${j+1}`; break;
                case '1m': timeLabel = `Day ${j+1}`; break;
                case '3m': timeLabel = `Day ${j+1}`; break;
                case '1y': timeLabel = `Month ${j+1}`; break;
                default: timeLabel = `Point ${j+1}`;
            }

            stockData.values.push({
                time: timeLabel,
                price: newPrice,
                change: changePercent
            });
        }

        data.push(stockData);
    }

    return data;
}

// Render the heatmap
function renderHeatmap() {
    // Clear previous heatmap
    d3.select('#heatmap-container svg').remove();

    if (state.data.length === 0) return;

    // Set up dimensions
    const margin = { top: 50, right: 20, bottom: 50, left: 100 };
    const width = elements.heatmapContainer.clientWidth - margin.left - margin.right;
    const height = elements.heatmapContainer.clientHeight - margin.top - margin.bottom;

    // Create SVG
    const svg = d3.select('#heatmap-container')
        .append('svg')
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    // Get all time points (assuming all stocks have the same time points)
    const timePoints = state.data[0].values.map(d => d.time);

    // Set up scales
    const xScale = d3.scaleBand()
        .domain(timePoints)
        .range([0, width])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(state.data.map(d => d.symbol))
        .range([0, height])
        .padding(0.1);

    // Color scale (red for negative, green for positive)
    const colorScale = d3.scaleLinear()
        .domain([-5, 0, 5]) // -5% to +5% change
        .range(['#ff0000', '#ffffff', '#00cc00']);

    // Create heatmap cells
    const cells = svg.selectAll('.cell')
        .data(state.data.flatMap(stock =>
            stock.values.map(value => ({
                symbol: stock.symbol,
                time: value.time,
                price: value.price,
                change: value.change
            }))
        ))
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.time))
        .attr('y', d => yScale(d.symbol))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip);

    // Add x-axis
    svg.append('g')
        .attr('class', 'axis axis--x')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(xScale))
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    // Add y-axis
    svg.append('g')
        .attr('class', 'axis axis--y')
        .call(d3.axisLeft(yScale));

    // Add axis labels
    svg.append('text')
        .attr('class', 'axis-label')
        .attr('x', width / 2)
        .attr('y', height + margin.bottom - 10)
        .style('text-anchor', 'middle')
        .text('Time');

    svg.append('text')
        .attr('class', 'axis-label')
        .attr('transform', 'rotate(-90)')
        .attr('x', -height / 2)
        .attr('y', -margin.left + 20)
        .style('text-anchor', 'middle')
        .text('Stock Symbol');

    // Add zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on('zoom', handleZoom);

    svg.call(zoom);

    // Create legend
    createLegend(colorScale);

    // Update status
    updateStatus();
}

// Handle zoom/pan events
function handleZoom(event) {
    state.zoomTransform = event.transform;

    const svg = d3.select('#heatmap-container svg g');
    svg.attr('transform', `translate(${state.zoomTransform.x},${state.zoomTransform.y}) scale(${state.zoomTransform.k})`);
}

// Show tooltip on hover
function showTooltip(event, d) {
    elements.tooltip.style.display = 'block';
    elements.tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br>
        Time: ${d.time}<br>
        Price: $${d.price.toFixed(2)}<br>
        Change: ${d.change.toFixed(2)}%
    `;

    // Position tooltip near mouse
    const x = event.pageX + 10;
    const y = event.pageY + 10;
    elements.tooltip.style.left = `${x}px`;
    elements.tooltip.style.top = `${y}px`;
}

// Hide tooltip
function hideTooltip() {
    elements.tooltip.style.display = 'none';
}

// Create color legend
function createLegend(colorScale) {
    // Clear previous legend
    elements.legend.innerHTML = '';

    // Create legend items
    const legendItems = [
        { label: '-5%', color: colorScale(-5) },
        { label: '-2.5%', color: colorScale(-2.5) },
        { label: '0%', color: colorScale(0) },
        { label: '+2.5%', color: colorScale(2.5) },
        { label: '+5%', color: colorScale(5) }
    ];

    legendItems.forEach(item => {
        const legendItem = document.createElement('div');
        legendItem.className = 'legend-item';

        const colorBox = document.createElement('div');
        colorBox.className = 'legend-color';
        colorBox.style.backgroundColor = item.color;

        const label = document.createElement('span');
        label.textContent = item.label;

        legendItem.appendChild(colorBox);
        legendItem.appendChild(label);
        elements.legend.appendChild(legendItem);
    });
}

// Update status message
function updateStatus() {
    if (state.lastUpdate) {
        elements.status.textContent = `Last updated: ${state.lastUpdate.toLocaleTimeString()}`;
    } else {
        elements.status.textContent = 'Last updated: Never';
    }
}

// Handle timeframe change
function handleTimeframeChange() {
    fetchData();
}

// Handle stock count change
function handleStockCountChange() {
    const count = parseInt(elements.stockCountInput.value);
    if (count < 1) {
        elements.stockCountInput.value = 1;
    } else if (count > config.maxStocks) {
        elements.stockCountInput.value = config.maxStocks;
    }
    fetchData();
}

// Toggle auto-update
function toggleAutoUpdate() {
    state.autoUpdate = !state.autoUpdate;
    elements.autoUpdateBtn.classList.toggle('active', state.autoUpdate);
    elements.autoUpdateBtn.innerHTML = state.autoUpdate
        ? '<i class="fas fa-play"></i> Auto Update'
        : '<i class="fas fa-pause"></i> Auto Update';
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
```

## Features Implemented

1. **Interactive Heatmap**:
   - Displays stock price changes as a color-coded grid
   - Red for negative changes, green for positive changes
   - White for near-zero changes

2. **Real-time Updates**:
   - Auto-refresh functionality (configurable interval)
   - Manual refresh button
   - Status indicator showing last update time

3. **Zoom/Pan Interactions**:
   - Mouse wheel zoom
   - Click and drag to pan
   - Smooth transitions

4. **Customization Options**:
   - Timeframe selection (1 day to 1 year)
   - Adjustable number of stocks displayed
   - Toggle for auto-updating

5. **Visual Enhancements**:
   - Tooltips showing detailed information
   - Color legend explaining the color coding
   - Responsive design

