                    const timePoints = [];
                    const now = new Date();

                    // Generate time points based on current range
                    const ranges = {
                        '1d': { count: 24, unit: 'hour' },
                        '1w': { count: 7, unit: 'day' },
                        '1m': { count: 30, unit: 'day' },
                        '3m': { count: 90, unit: 'day' },
                        '1y': { count: 12, unit: 'month' }
                    };

                    const range = ranges[this.currentTimeRange];
                    for (let i = 0; i < range.count; i++) {
                        const date = new Date(now);
                        if (range.unit === 'hour') {
                            date.setHours(now.getHours() - i);
                        } else if (range.unit === 'day') {
