                // Set up scales
                this.xScale
                    .domain(this.timePoints.map(d => d.toISOString()))
                    .range([0, this.width])
                    .padding(0.05);

                this.yScale
                    .domain(this.stocks)
                    .range([this.height, 0])
                    .padding(0.1);

                // Find min and max change values for color scale
                const minChange = d3.min(this.stockData, d => d.change);
                const maxChange = d3.max(this.stockData, d => d.change);
                this.colorScale.domain([minChange, maxChange]);

                // Remove previous elements
                this.svg.selectAll('.cell').remove();
                this.svg.selectAll('.x-axis').remove();
                this.svg.selectAll('.y-axis').remove();

                // Add cells
                this.svg.selectAll('.cell')
                    .data(this.stockData)
                    .enter().append('rect')
                    .attr('class', 'cell')
                    .attr('x', d => this.xScale(d.time.toISOString()))
                    .attr('y', d => this.yScale(d.stock))
                    .attr('width', this.xScale.bandwidth())
                    .attr('height', this.yScale.bandwidth())
                    .attr('fill', d => this.colorScale(d.change))
                    .on('mouseover', (event, d) => {
                        this.tooltip.style('display', 'block')
                            .html(`
                                <strong>${d.stock}</strong><br>
                                ${d.time.toLocaleString()}<br>
                                Change: ${(d.change * 100).toFixed(2)}%
                            `)
                            .style('left', `${event.pageX + 10}px`)
                            .style('top', `${event.pageY + 10}px`);
                    })
                    .on('mouseout', () => {
                        this.tooltip.style('display', 'none');
                    });

                // Add axes
                const xAxis = d3.axisBottom(this.xScale)
                    .tickFormat(d => new Date(d).toLocaleDateString())
                    .tickSizeOuter(0);

                const yAxis = d3.axisLeft(this.yScale)
                    .tickSizeOuter(0);

                this.svg.append('g')
                    .attr('class', 'x-axis')
                    .attr('transform', `translate(0,${this.height})`)
                    .call(xAxis)
                    .selectAll('text')
                    .attr('transform', 'rotate(-45)')
                    .style('text-anchor', 'end');

                this.svg.append('g')
                    .attr('class', 'y-axis')
                    .call(yAxis);
            }

            zoomed(event) {
                const { transform } = event;
                this.svg.attr('transform', transform);
            }

            setupResizeHandler() {
                window.addEventListener('resize', () => {
                    this.width = this.container.node().clientWidth - this.margin.left - this.margin.right;
                    this.height = this.container.node().clientHeight - this.margin.top - this.margin.bottom;

                    this.svg.attr('width', this.width + this.margin.left + this.margin.right)
                        .attr('height', this.height + this.margin.top + this.margin.bottom);

                    this.xScale.range([0, this.width]);
                    this.yScale.range([this.height, 0]);

                    this.updateHeatmap();
                });
            }
        }
    </script>
</body>
</html>
```

