## JavaScript Implementation (script.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 20, right: 20, bottom: 60, left: 80 },
    colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
    updateInterval: 5000, // 5 seconds
    maxZoom: 10,
    minZoom: 0.5
};

// DOM elements
const heatmapContainer = d3.select("#heatmap-container");
const tooltip = d3.select("#tooltip");
const timeframeSelect = d3.select("#timeframe");
const stockSelect = d3.select("#stock-select");
const updateBtn = d3.select("#update-btn");

// State variables
let currentData = [];
let zoomTransform = d3.zoomIdentity;
let isUpdating = false;

// Initialize the visualization
function init() {
    // Set up zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([config.minZoom, config.maxZoom])
        .on("zoom", handleZoom);

    // Create SVG container
    const svg = heatmapContainer.append("svg")
        .attr("width", config.width)
        .attr("height", config.height)
        .call(zoom);

    // Create main group for the heatmap
    const g = svg.append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Add clip path for zooming
    svg.append("defs").append("clipPath")
        .attr("id", "clip")
        .append("rect")
        .attr("width", config.width - config.margin.left - config.margin.right)
        .attr("height", config.height - config.margin.top - config.margin.bottom);

    // Add event listeners
    updateBtn.on("click", fetchData);
    timeframeSelect.on("change", fetchData);

    // Initial data fetch
    fetchData();

    // Set up periodic updates
    setInterval(fetchData, config.updateInterval);
}

// Handle zoom/pan interactions
function handleZoom(event) {
    zoomTransform = event.transform;
    renderHeatmap();
}

// Fetch stock data (simulated with mock data)
async function fetchData() {
    if (isUpdating) return;

    isUpdating = true;
    heatmapContainer.select(".loading").style("display", "block");

    try {
        // In a real implementation, this would fetch from an API
        // For this example, we'll generate mock data
        const selectedStocks = Array.from(stockSelect.node().selectedOptions).map(opt => opt.value);
        const timeframe = timeframeSelect.node().value;

        // Generate mock data
        currentData = generateMockData(selectedStocks, timeframe);

        // Render the heatmap
        renderHeatmap();

        // Create legend
        createLegend();
    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        isUpdating = false;
        heatmapContainer.select(".loading").style("display", "none");
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    const now = new Date();
    const dataPoints = [];

    // Determine time range based on selected timeframe
    let startDate, interval;
    switch (timeframe) {
        case "1D":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 30; // 30 minutes
            break;
        case "1W":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 2 * 60; // 2 hours
            break;
        case "1M":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 6 * 60; // 6 hours
            break;
        case "3M":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 12 * 60; // 12 hours
            break;
        case "1Y":
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 3 * 24 * 60; // 3 days
            break;
        default:
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 6 * 60;
    }

    // Generate data points
    let currentDate = new Date(startDate);
    while (currentDate <= now) {
        stocks.forEach(stock => {
            // Generate a random price change percentage between -5% and +5%
            const changePercent = (Math.random() * 10) - 5;

            dataPoints.push({
                stock: stock,
                date: new Date(currentDate),
                changePercent: changePercent
            });
        });

        // Move to next interval
        currentDate.setMinutes(currentDate.getMinutes() + interval);
    }

    return dataPoints;
}

// Render the heatmap
function renderHeatmap() {
    if (currentData.length === 0) return;

    // Clear previous content
    heatmapContainer.select("svg").selectAll("*").remove();

    // Set up dimensions
    const width = config.width - config.margin.left - config.margin.right;
    const height = config.height - config.margin.top - config.margin.bottom;

    // Create SVG container
    const svg = heatmapContainer.select("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Create main group for the heatmap
    const g = svg.append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Set up scales
    const stocks = [...new Set(currentData.map(d => d.stock))];
    const dates = [...new Set(currentData.map(d => d.date))].sort((a, b) => a - b);

    const xScale = d3.scaleBand()
        .domain(dates.map(d => d.toISOString()))
        .range([0, width])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, height])
        .padding(0.1);

    // Color scale
    const colorScale = d3.scaleQuantile()
        .domain([d3.min(currentData, d => d.changePercent), d3.max(currentData, d => d.changePercent)])
        .range(config.colors);

    // Create heatmap cells
    g.selectAll(".cell")
        .data(currentData)
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date.toISOString()))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.changePercent))
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => d3.timeFormat("%b %d")(new Date(d)))
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    const yAxis = d3.axisLeft(yScale);

    g.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0,${height})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    g.append("g")
        .attr("class", "y-axis")
        .call(yAxis);

    // Add axis labels
    g.append("text")
        .attr("class", "x-axis-label")
        .attr("x", width / 2)
        .attr("y", height + config.margin.bottom - 10)
        .style("text-anchor", "middle")
        .text("Date");

    g.append("text")
        .attr("class", "y-axis-label")
        .attr("transform", "rotate(-90)")
        .attr("x", -height / 2)
        .attr("y", -config.margin.left + 20)
        .style("text-anchor", "middle")
        .text("Stock");

    // Apply zoom transform
    g.attr("transform", `translate(${config.margin.left},${config.margin.top}) scale(${zoomTransform.k}) translate(${zoomTransform.x},${zoomTransform.y})`);
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style("display", "block")
        .html(`
            <strong>${d.stock}</strong><br>
            Date: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.date)}<br>
            Change: ${d.changePercent.toFixed(2)}%
        `);

    // Position tooltip near mouse
    const [x, y] = d3.pointer(event);
    tooltip.style("left", `${x + 10}px`)
        .style("top", `${y + 10}px`);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style("display", "none");
}

// Create color legend
function createLegend() {
    if (currentData.length === 0) return;

    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    const minValue = d3.min(currentData, d => d.changePercent);
    const maxValue = d3.max(currentData, d => d.changePercent);
    const step = (maxValue - minValue) / (config.colors.length - 1);

    config.colors.forEach((color, i) => {
        const value = minValue + (i * step);

        legend.append("div")
            .attr("class", "legend-item")
            .html(`
                <div class="legend-color" style="background-color: ${color};"></div>
                <span>${value.toFixed(1)}%</span>
            `);
    });
}

// Initialize the visualization when the page loads
document.addEventListener("DOMContentLoaded", init);
