                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip)
                .merge(cells)
                .transition()
                .duration(500)
                .attr("fill", d => colorScale(d.price));

            // Exit old cells
            cells.exit().remove();
        }

        function showTooltip(event, d) {
            const tooltip = d3.select("#tooltip");
            tooltip.style("visibility", "visible")
                .html(`
                    <strong>${d.symbol}</strong><br>
                    Time: ${d.time}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change.toFixed(2)}%
                `)
                .style("top", (event.pageY - 10) + "px")
                .style("left", (event.pageX + 10) + "px");
        }

        function hideTooltip() {
            d3.select("#tooltip").style("visibility", "hidden");
        }

        function zoomed(event) {
            const { transform } = event;
            g.attr("transform", `translate(${config.margin.left + transform.x},${config.margin.top + transform.y}) scale(${transform.k})`);
        }

        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        function updateData() {
            // In a real app, this would fetch new data from an API
            stockData.forEach(d => {
                // Simulate price changes
                const change = (Math.random() - 0.5) * 2;
                d.price += change;
                d.change = change;
            });
        }

        function generateSampleData(timeframe = "1d") {
            const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "BRK.B", "JNJ", "V"];
            const now = new Date();
            let timePoints = [];

            // Generate time points based on timeframe
            switch(timeframe) {
                case "1d":
                    for (let i = 0; i < 24; i++) {
                        const time = new Date(now);
                        time.setHours(now.getHours() - i);
                        timePoints.push(time.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
                    }
                    break;
                case "1w":
                    for (let i = 0; i < 7; i++) {
                        const time = new Date(now);
                        time.setDate(now.getDate() - i);
                        timePoints.push(time.toLocaleDateString());
                    }
                    break;
                case "1m":
                    for (let i = 0; i < 30; i++) {
                        const time = new Date(now);
                        time.setDate(now.getDate() - i);
                        timePoints.push(time.toLocaleDateString());
                    }
                    break;
                case "3m":
                    for (let i = 0; i < 90; i++) {
                        const time = new Date(now);
                        time.setDate(now.getDate() - i);
                        timePoints.push(time.toLocaleDateString());
                    }
                    break;
                case "1y":
                    for (let i = 0; i < 12; i++) {
                        const time = new Date(now);
                        time.setMonth(now.getMonth() - i);
                        timePoints.push(time.toLocaleDateString([], {month: 'short', year: 'numeric'}));
                    }
                    break;
            }

            // Generate sample data
            const data = [];
            stocks.forEach(symbol => {
                timePoints.forEach(time => {
                    data.push({
                        symbol,
                        time,
                        price: 100 + Math.random() * 200,
                        change: (Math.random() - 0.5) * 5
                    });
                });
            });

            return data;
        }
    </script>
</body>
</html>
