            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 20)
                .style("text-anchor", "middle")
                .text("Price");

            // Create color scale
            colorScale = d3.scaleQuantile()
                .range(config.colors);

            // Create legend
            createLegend();

            // Load initial data
            updateData();

            // Set up event listeners
            d3.select("#stock-select").on("change", updateData);
            d3.select("#reset-zoom").on("click", resetZoom);
        }

        // Create legend
        function createLegend() {
            const legend = d3.select("#legend");

            // Clear existing legend
            legend.selectAll("*").remove();

            // Add legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(colorScale.range())
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d);

            legendItems.append("span")
                .text((d, i) => {
                    const extent = colorScale.invertExtent(d);
                    return `${extent[0] ? extent[0].toFixed(2) : ""} - ${extent[1] ? extent[1].toFixed(2) : ""}`;
                });
        }

        // Update data
        function updateData() {
            const stock = d3.select("#stock-select").property("value");
            const endDate = new Date();
            const startDate = new Date();
            startDate.setDate(endDate.getDate() - config.timeRange);

            // Simulate API call with random data
            simulateStockData(stock, startDate, endDate).then(newData => {
                data = newData;
                updateChart();
            });
        }

        // Simulate stock data API call
        function simulateStockData(symbol, startDate, endDate) {
            return new Promise(resolve => {
                setTimeout(() => {
                    const days = Math.floor((endDate - startDate) / (1000 * 60 * 60 * 24));
                    const basePrice = 100 + Math.random() * 200;
                    const volatility = 0.02 + Math.random() * 0.05;

                    const data = [];
                    for (let i = 0; i <= days; i++) {
                        const date = new Date(startDate);
                        date.setDate(startDate.getDate() + i);

                        // Generate hourly data
                        for (let h = 0; h < 24; h++) {
                            const time = new Date(date);
                            time.setHours(h);

                            // Simulate price movement
                            const price = basePrice * Math.exp(
                                (Math.random() - 0.5) * volatility * Math.sqrt(1/24)
                            );

                            // Simulate volume
                            const volume = Math.floor(100000 + Math.random() * 900000);

                            data.push({
                                symbol,
                                time,
                                price: parseFloat(price.toFixed(2)),
                                volume
                            });
                        }
                    }

                    resolve(data);
                }, 500); // Simulate network delay
            });
        }

        // Update chart with new data
        function updateChart() {
            if (data.length === 0) return;

            // Set up scales
            const xExtent = d3.extent(data, d => d.time);
            const yExtent = d3.extent(data, d => d.price);

            xScale = d3.scaleTime()
                .domain(xExtent)
                .range([0, config.width - config.margin.left - config.margin.right]);

            yScale = d3.scaleLinear()
                .domain(yExtent)
                .range([config.height - config.margin.top - config.margin.bottom, 0]);

            // Update color scale domain
            const priceExtent = d3.extent(data, d => d.price);
            colorScale.domain(priceExtent);

            // Update legend
            createLegend();

            // Create heatmap
            const heatmapGroup = d3.select("#heatmap-group");

            // Clear previous heatmap
            heatmapGroup.selectAll("*").remove();

            // Create bins for the heatmap
            const bins = d3.bin()
                .thresholds(xScale.ticks(20))
                .value(d => d.time)(data);

            // Add rectangles for each bin
            heatmapGroup.selectAll("rect")
                .data(bins)
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.x0))
                .attr("y", d => {
                    const avgPrice = d3.mean(d, e => e.price);
                    return yScale(avgPrice);
                })
                .attr("width", d => Math.max(0, xScale(d.x1) - xScale(d.x0) - 1))
                .attr("height", d => {
                    const prices = d.map(e => e.price);
                    const minPrice = d3.min(prices);
                    const maxPrice = d3.max(prices);
                    return Math.max(0, yScale(minPrice) - yScale(maxPrice));
                })
                .attr("fill", d => {
                    const avgPrice = d3.mean(d, e => e.price);
                    return colorScale(avgPrice);
                })
                .on("mouseover", function(event, d) {
                    const avgPrice = d3.mean(d, e => e.price).toFixed(2);
                    const minPrice = d3.min(d, e => e.price).toFixed(2);
                    const maxPrice = d3.max(d, e => e.price).toFixed(2);
                    const count = d.length;

                    d3.select(this)
                        .attr("stroke", "black")
                        .attr("stroke-width", 2);

                    const tooltip = d3.select("body").append("div")
                        .attr("class", "tooltip")
                        .style("position", "absolute")
                        .style("background", "white")
                        .style("padding", "8px")
                        .style("border", "1px solid #ccc")
                        .style("border-radius", "4px")
                        .style("pointer-events", "none")
                        .style("font-size", "12px")
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 20) + "px")
                        .html(`
                            <strong>Time:</strong> ${d.x0.toLocaleString()}<br>
                            <strong>Avg Price:</strong> ${avgPrice}<br>
                            <strong>Min Price:</strong> ${minPrice}<br>
                            <strong>Max Price:</strong> ${maxPrice}<br>
                            <strong>Trades:</strong> ${count}
                        `);
                })
                .on("mouseout", function() {
                    d3.select(this)
                        .attr("stroke", null)
                        .attr("stroke-width", null);

                    d3.select(".tooltip").remove();
                });

            // Update axes
            d3.select(".x-axis")
                .call(d3.axisBottom(xScale)
                    .ticks(10)
                    .tickFormat(d3.timeFormat("%b %d"))
                );

            d3.select(".y-axis")
                .call(d3.axisLeft(yScale)
                    .ticks(10)
                );

            // Set up real-time updates
            setTimeout(updateData, 5000); // Update every 5 seconds
        }

        // Zoom handler
        function zoomed(event) {
            const transform = event.transform;
            d3.select("#heatmap-group").attr("transform", `translate(${config.margin.left}, ${config.margin.top}) scale(${transform.k}) translate(${transform.x}, ${transform.y})`);

            // Update axes with the new scale
            d3.select(".x-axis").call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            d3.select(".y-axis").call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        // Reset zoom
        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Initialize the visualization
        init();
    </script>
