let stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "JPM", "V", "WMT"];
let dates = [];
let priceData = {};

// Generate sample data
function generateSampleData() {
    const now = new Date();
    const timeRange = document.getElementById('timeRange').value;

    // Clear existing data
    dates = [];
    priceData = {};

    // Generate dates based on selected range
    let startDate, interval;
    switch(timeRange) {
        case '1d':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 3600000; // 1 hour
            break;
        case '1w':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 21600000; // 6 hours
            break;
        case '1m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 86400000; // 1 day
            break;
        case '3m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 86400000; // 1 day
            break;
        case '1y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 86400000 * 7; // 1 week
            break;
    }

    // Generate dates
    for (let d = new Date(startDate); d <= now; d = new Date(d.getTime() + interval)) {
        dates.push(new Date(d));
    }

    // Generate random price data for each stock
    stocks.forEach(stock => {
        priceData[stock] = [];
        let basePrice = 100 + Math.random() * 200;

        dates.forEach(date => {
            // Simulate price movement
            const change = (Math.random() - 0.5) * 5;
            basePrice += change;
            priceData[stock].push(Math.max(10, basePrice)); // Ensure price doesn't go below 10
        });
    });
}

// Create the heatmap
function createHeatmap() {
    // Clear previous chart
    d3.select("#heatmap").selectAll("*").remove();

    // Set up dimensions
    const width = config.width - config.margin.left - config.margin.right;
    const height = config.height - config.margin.top - config.margin.bottom;

    // Create SVG
    const svg = d3.select("#heatmap")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height)
        .append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Create scales
    const xScale = d3.scaleBand()
        .domain(dates.map(d => d.toISOString()))
        .range([0, width])
        .padding(0.01);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, height])
        .padding(0.01);

    // Create color scale
    const allPrices = stocks.flatMap(stock => priceData[stock]);
    const colorScale = d3.scaleQuantile()
        .domain([d3.min(allPrices), d3.max(allPrices)])
        .range(config.colors);

    // Create tooltip
    const tooltip = d3.select("#tooltip");

    // Create zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .translateExtent([[0, 0], [width, height]])
        .on("zoom", zoomed);

    // Apply zoom to SVG
    svg.call(zoom);

    // Create heatmap cells
    const cells = svg.selectAll(".cell")
        .data(stocks.flatMap(stock =>
            dates.map((date, i) => ({
                stock,
                date: date.toISOString(),
                value: priceData[stock][i]
            }))
        ))
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.value))
        .on("mouseover", function(event, d) {
            tooltip.style("visibility", "visible")
                .html(`<strong>${d.stock}</strong><br>${new Date(d.date).toLocaleString()}<br>Price: $${d.value.toFixed(2)}`);
        })
        .on("mousemove", function(event) {
            tooltip.style("top", (event.pageY - 10) + "px")
                .style("left", (event.pageX + 10) + "px");
        })
        .on("mouseout", function() {
            tooltip.style("visibility", "hidden");
        });

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => new Date(d).toLocaleDateString())
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    const yAxis = d3.axisLeft(yScale);

    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0,${height})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    svg.append("g")
        .attr("class", "y-axis")
        .call(yAxis);

    // Add axis labels
    svg.append("text")
        .attr("class", "x-label")
        .attr("x", width / 2)
        .attr("y", height + config.margin.bottom - 10)
        .style("text-anchor", "middle")
        .text("Date");

    svg.append("text")
        .attr("class", "y-label")
        .attr("transform", "rotate(-90)")
        .attr("x", -height / 2)
        .attr("y", -config.margin.left + 20)
        .style("text-anchor", "middle")
        .text("Stock");

    // Create legend
    createLegend(colorScale);

    // Zoom function
    function zoomed(event) {
        const { transform } = event;
        svg.attr("transform", transform);
    }

    // Reset zoom button
    d3.select("#resetZoom").on("click", () => {
        svg.transition().duration(750).call(zoom.transform, d3.zoomIdentity);
    });
}

// Create legend
function createLegend(colorScale) {
    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    const thresholds = colorScale.quantiles();

    // Add min value
    legend.append("div")
        .attr("class", "legend-item")
        .html(`<div class="legend-color" style="background:${colorScale(colorScale.domain()[0])}"></div>
               <span>${d3.format(".2f")(colorScale.domain()[0])}</span>`);

    // Add quantile values
    thresholds.forEach((threshold, i) => {
        legend.append("div")
            .attr("class", "legend-item")
            .html(`<div class="legend-color" style="background:${colorScale(threshold)}"></div>
                   <span>${d3.format(".2f")(threshold)}</span>`);
    });

    // Add max value
    legend.append("div")
        .attr("class", "legend-item")
        .html(`<div class="legend-color" style="background:${colorScale(colorScale.domain()[1])}"></div>
               <span>${d3.format(".2f")(colorScale.domain()[1])}</span>`);
}

// Update data and redraw
function updateData() {
    generateSampleData();
    createHeatmap();
}

// Initialize
document.addEventListener("DOMContentLoaded", () => {
    // Initial data generation
    updateData();

    // Set up time range change handler
    document.getElementById('timeRange').addEventListener('change', updateData);

    // Set up periodic updates
    setInterval(updateData, config.updateInterval);
});
```

