</head>
<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div class="time-range">
                <label for="time-range">Time Range:</label>
                <select id="time-range">
                    <option value="1h">1 Hour</option>
                    <option value="4h">4 Hours</option>
                    <option value="1d" selected>1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m">1 Month</option>
                </select>
            </div>
            <div>
                <span id="last-update">Last update: -</span>
            </div>
        </div>

        <div id="heatmap-container"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 30, right: 30, bottom: 30, left: 60 },
            colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
            updateInterval: 5000, // 5 seconds
            initialTimeRange: '1d'
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = [
            "AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "BRK.A", "JNJ", "JPM", "V",
            "PG", "NVDA", "HD", "MA", "DIS", "VZ", "PYPL", "ADBE", "CRM", "NFLX"
        ];

        // Initialize variables
        let data = [];
        let svg, xScale, yScale, colorScale, tooltip;
        let zoom;

        // Initialize the visualization
        function init() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create tooltip
            tooltip = d3.select("body").append("div")
                .attr("class", "tooltip")
                .style("opacity", 0);

            // Set up zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Generate initial data
            generateData();

            // Set up time range selector
            d3.select("#time-range").on("change", function() {
                config.initialTimeRange = this.value;
                generateData();
            });

            // Start real-time updates
            setInterval(updateData, config.updateInterval);
        }

        // Generate sample data
        function generateData() {
            const now = new Date();
            let timeRange;

            switch(config.initialTimeRange) {
                case '1h': timeRange = 60 * 60 * 1000; break;
                case '4h': timeRange = 4 * 60 * 60 * 1000; break;
                case '1d': timeRange = 24 * 60 * 60 * 1000; break;
                case '1w': timeRange = 7 * 24 * 60 * 60 * 1000; break;
                case '1m': timeRange = 30 * 24 * 60 * 60 * 1000; break;
                default: timeRange = 24 * 60 * 60 * 1000;
            }

            const startTime = new Date(now.getTime() - timeRange);
            const endTime = now;

            // Generate timestamps (hourly for larger ranges, minute for smaller)
            const timestamps = [];
            if (config.initialTimeRange === '1h') {
                // Minute intervals for 1 hour
                for (let i = 0; i <= 60; i++) {
                    timestamps.push(new Date(startTime.getTime() + i * 60 * 1000));
                }
            } else if (config.initialTimeRange === '4h') {
                // 5-minute intervals for 4 hours
                for (let i = 0; i <= 48; i++) {
                    timestamps.push(new Date(startTime.getTime() + i * 5 * 60 * 1000));
                }
            } else {
                // Hourly intervals for larger ranges
                const hours = Math.floor(timeRange / (60 * 60 * 1000));
                for (let i = 0; i <= hours; i++) {
                    timestamps.push(new Date(startTime.getTime() + i * 60 * 60 * 1000));
                }
            }

            // Generate random data for each stock and timestamp
            data = stocks.map(stock => {
                const stockData = {
                    symbol: stock,
                    values: []
                };

                let basePrice = 100 + Math.random() * 200;

                timestamps.forEach(time => {
                    // Simulate price movement
                    const change = (Math.random() - 0.5) * 5;
                    basePrice = Math.max(1, basePrice + change);

                    stockData.values.push({
                        time: time,
                        price: basePrice,
                        change: change
                    });
                });

                return stockData;
            });

            updateVisualization();
        }

        // Update data with new values (simulating real-time updates)
        function updateData() {
            const now = new Date();

            // Update each stock's latest value
            data.forEach(stock => {
                if (stock.values.length === 0) return;

                const lastValue = stock.values[stock.values.length - 1];
                const change = (Math.random() - 0.5) * 5;
                const newPrice = Math.max(1, lastValue.price + change);

                stock.values.push({
                    time: now,
                    price: newPrice,
                    change: change
                });

                // Remove old data points based on time range
                let timeRange;
                switch(config.initialTimeRange) {
                    case '1h': timeRange = 60 * 60 * 1000; break;
                    case '4h': timeRange = 4 * 60 * 60 * 1000; break;
                    case '1d': timeRange = 24 * 60 * 60 * 1000; break;
                    case '1w': timeRange = 7 * 24 * 60 * 60 * 1000; break;
                    case '1m': timeRange = 30 * 24 * 60 * 60 * 1000; break;
                    default: timeRange = 24 * 60 * 60 * 1000;
                }

                const cutoffTime = new Date(now.getTime() - timeRange);
                stock.values = stock.values.filter(d => d.time >= cutoffTime);
            });

            updateVisualization();

            // Update last update time
            d3.select("#last-update").text(`Last update: ${now.toLocaleTimeString()}`);
        }

        // Update the visualization with current data
        function updateVisualization() {
            if (data.length === 0) return;

            // Clear previous visualization
            svg.selectAll("*").remove();

            // Get all timestamps across all stocks
            const allTimes = data.flatMap(stock => stock.values.map(d => d.time));
            const minTime = d3.min(allTimes);
            const maxTime = d3.max(allTimes);

            // Get all prices for color scale
            const allPrices = data.flatMap(stock => stock.values.map(d => d.price));
            const minPrice = d3.min(allPrices);
            const maxPrice = d3.max(allPrices);

            // Set up scales
            xScale = d3.scaleTime()
                .domain([minTime, maxTime])
                .range([config.margin.left, config.width - config.margin.right]);

            yScale = d3.scaleBand()
                .domain(stocks)
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.1);

            colorScale = d3.scaleQuantile()
                .domain([minPrice, maxPrice])
                .range(config.colors);

            // Add X axis
            svg.append("g")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale));

            // Add Y axis
            svg.append("g")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(d3.axisLeft(yScale));

            // Add grid lines
            svg.append("g")
                .attr("class", "grid")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickSize(-(config.height - config.margin.top - config.margin.bottom))
                    .tickFormat("")
                );

            svg.append("g")
                .attr("class", "grid")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(d3.axisLeft(yScale)
                    .tickSize(-(config.width - config.margin.left - config.margin.right))
                    .tickFormat("")
                );

            // Add heatmap cells
            const cells = svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("g")
                .attr("class", "cell")
                .attr("transform", d => `translate(0, ${yScale(d.symbol)})`);

            cells.selectAll("rect")
                .data(d => d.values)
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.time))
                .attr("y", 0)
                .attr("width", (d, i, nodes) => {
                    if (i < nodes.length - 1) {
                        const nextTime = data[0].values[i + 1].time;
                        return xScale(nextTime) - xScale(d.time);
                    }
                    return xScale(maxTime) - xScale(d.time);
                })
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.transition()
                        .duration(200)
                        .style("opacity", .9);
                    tooltip.html(`
                        <strong>${d.symbol}</strong><br>
                        Time: ${d.time.toLocaleTimeString()}<br>
                        Price: $${d.price.toFixed(2)}<br>
                        Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}
                    `)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    tooltip.transition()
                        .duration(500)
                        .style("opacity", 0);
                });

            // Add color legend
            const legendWidth = 200;
            const legendHeight = 20;
            const legend = svg.append("g")
                .attr("transform", `translate(${config.width - config.margin.right - legendWidth}, ${config.margin.top})`);

            const legendScale = d3.scaleLinear()
                .domain([minPrice, maxPrice])
                .range([0, legendWidth]);

            legend.selectAll("rect")
                .data(d3.range(legendWidth))
                .enter()
                .append("rect")
                .attr("x", d => d)
                .attr("y", 0)
                .attr("width", 1)
                .attr("height", legendHeight)
                .attr("fill", d => colorScale(legendScale.invert(d)));

            legend.append("g")
                .attr("transform", `translate(0, ${legendHeight})`)
                .call(d3.axisBottom(legendScale).ticks(5));

            legend.append("text")
                .attr("x", legendWidth / 2)
                .attr("y", -10)
                .attr("text-anchor", "middle")
                .text("Price ($)");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const { transform } = event;
            svg.selectAll(".cell").attr("transform", d =>
                `translate(${transform.x}, ${transform.y}) scale(${transform.k})`
            );
        }

        // Initialize the visualization when the page loads
        window.onload = init;
    </script>
</body>
</html>
