            const numBins = 10;
            const binSize = (priceExtent[1] - priceExtent[0]) / numBins;
            const bins = Array.from({length: numBins}, (_, i) => ({
                start: priceExtent[0] + i * binSize,
                end: priceExtent[0] + (i + 1) * binSize
            }));

            yScale = d3.scaleBand()
                .domain(bins.map(b => `${b.start.toFixed(2)}-${b.end.toFixed(2)}`))
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.05);

            // Color scale
            colorScale = d3.scaleQuantile()
                .domain([0, d3.max(data, d => d.volume)])
                .range(config.colors);
        }

        function drawHeatmap(data) {
            // Remove previous heatmap if it exists
            if (heatmap) {
                heatmap.remove();
            }

            // Create heatmap group
            heatmap = svg.append("g")
                .attr("class", "heatmap");

            // Draw rectangles for each time-price combination
            data.forEach(timeData => {
                const timeGroup = heatmap.append("g")
                    .attr("class", "time-group")
                    .attr("transform", `translate(${xScale(timeData.time)}, 0)`);

                // Find which bin each price falls into
                const priceBins = timeData.prices.map(price => {
                    const binIndex = Math.min(
                        Math.floor((price - yScale.domain()[0].split('-')[0]) / (yScale.bandwidth() / yScale.domain().length)),
                        yScale.domain().length - 1
                    );
                    return yScale.domain()[binIndex];
                });

                // Count prices in each bin
                const binCounts = {};
                yScale.domain().forEach(bin => binCounts[bin] = 0);
                priceBins.forEach(bin => binCounts[bin]++);

                // Draw rectangles for each bin
                yScale.domain().forEach(bin => {
                    if (binCounts[bin] > 0) {
                        timeGroup.append("rect")
                            .attr("x", 0)
                            .attr("y", yScale(bin))
                            .attr("width", xScale.bandwidth())
                            .attr("height", yScale.bandwidth())
                            .attr("fill", colorScale(binCounts[bin]))
                            .on("mouseover", function(event, d) {
                                const [x, y] = d3.pointer(event);
                                tooltip.style("visibility", "visible")
                                    .html(`
                                        <strong>Time:</strong> ${timeData.time}<br>
                                        <strong>Price Range:</strong> ${bin}<br>
                                        <strong>Count:</strong> ${binCounts[bin]}<br>
                                        <strong>Avg Price:</strong> ${d3.mean(timeData.prices).toFixed(2)}<br>
                                        <strong>Volume:</strong> ${timeData.volume.toLocaleString()}
                                    `)
                                    .style("left", (x + 10) + "px")
                                    .style("top", (y + 10) + "px");
                            })
                            .on("mouseout", function() {
                                tooltip.style("visibility", "hidden");
                            });
                    }
                });
            });
        }

        function drawAxes() {
            // Remove previous axes if they exist
            svg.selectAll(".axis").remove();

            // X axis
            svg.append("g")
                .attr("class", "axis axis-x")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end")
                .style("font-size", "10px");

            // Y axis
            svg.append("g")
                .attr("class", "axis axis-y")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .style("font-size", "10px");

            // Axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Price Range");
        }

        function zoomed(event) {
            const transform = event.transform;

            // Apply zoom to heatmap
            heatmap.attr("transform", transform);

            // Adjust axes
            svg.select(".axis-x")
                .call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));

            svg.select(".axis-y")
                .call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        // Event listeners
        document.getElementById("time-range").addEventListener("change", updateVisualization);
        document.getElementById("symbol-select").addEventListener("change", updateVisualization);

        // Initialize and set up periodic updates
        initVisualization();

        // Set up periodic updates (replace with WebSocket in production)
        setInterval(updateVisualization, config.updateInterval);
    </script>
</body>
