            <span>Zoom: Scroll or pinch</span>
            <span>Pan: Click and drag</span>
        </div>
        <div class="heatmap-container" id="heatmap"></div>
        <div class="tooltip" id="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 900,
            height: 550,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            numStocks: 20,
            numDays: 50,
            updateInterval: 5000 // 5 seconds
        };

        // Generate mock stock data
        function generateStockData() {
            const stocks = [];
            for (let i = 0; i < config.numStocks; i++) {
                const stock = {
                    name: `STOCK-${String.fromCharCode(65 + i)}`,
                    prices: []
                };
                for (let j = 0; j < config.numDays; j++) {
                    // Generate random price between 50 and 200
                    stock.prices.push(50 + Math.random() * 150);
                }
                stocks.push(stock);
            }
            return stocks;
        }

        // Initialize the heatmap
        function initHeatmap() {
            // Clear previous content
            d3.select("#heatmap").selectAll("*").remove();

            // Create SVG
            const svg = d3.select("#heatmap")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create tooltip
            const tooltip = d3.select("#tooltip");

            // Create scales
            const xScale = d3.scaleBand()
                .domain(d3.range(config.numDays))
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(d3.range(config.numStocks))
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.01);

            const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                .domain([50, 200]);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => `Day ${d + 1}`)
                .tickSizeOuter(0);

            const yAxis = d3.axisLeft(yScale)
                .tickFormat(d => `Stock ${String.fromCharCode(65 + d)}`)
                .tickSizeOuter(0);

            svg.append("g")
                .attr("transform", `translate(0,${config.height - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.append("g")
                .attr("transform", `translate(${config.margin.left},0)`)
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.selectAll(".heatmap-cell")
                        .attr("transform", transform);
                    svg.select(".x-axis").call(xAxis.scale(transform.rescaleX(xScale)));
                    svg.select(".y-axis").call(yAxis.scale(transform.rescaleY(yScale)));
                });

            svg.call(zoom);

            // Store references for updates
            return { svg, xScale, yScale, colorScale, tooltip };
        }

        // Update the heatmap with new data
        function updateHeatmap(data, { svg, xScale, yScale, colorScale, tooltip }) {
            // Remove existing cells
            svg.selectAll(".heatmap-cell").remove();

            // Create groups for each cell
            const cells = svg.selectAll(".heatmap-cell")
                .data(data)
                .enter()
                .append("g")
                .attr("class", "heatmap-cell")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Add rectangles for each day's price
            cells.selectAll("rect")
                .data(d => d.prices.map((price, i) => ({
                    stockIndex: data.indexOf(d),
                    dayIndex: i,
                    price: price
                })))
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.dayIndex))
                .attr("y", d => yScale(d.stockIndex))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", (event, d) => {
                    tooltip.style("display", "block")
                        .html(`
                            <strong>${data[d.stockIndex].name}</strong><br>
                            Day ${d.dayIndex + 1}: $${d.price.toFixed(2)}
                        `);
                })
                .on("mousemove", (event) => {
                    tooltip.style("left", `${event.pageX + 10}px`)
                        .style("top", `${event.pageY + 10}px`);
                })
                .on("mouseout", () => {
                    tooltip.style("display", "none");
                });
        }

        // Main application
        document.addEventListener("DOMContentLoaded", () => {
            // Initialize heatmap
            const heatmap = initHeatmap();

            // Initial data load
            let stockData = generateStockData();
            updateHeatmap(stockData, heatmap);

            // Set up update button
            document.getElementById("update-btn").addEventListener("click", () => {
                stockData = generateStockData();
                updateHeatmap(stockData, heatmap);
            });

            // Set up automatic updates
            setInterval(() => {
                stockData = generateStockData();
                updateHeatmap(stockData, heatmap);
            }, config.updateInterval);
        });
    </script>
</body>
</html>
```

