        }
        .heatmap-container {
            width: 100%;
            height: 600px;
            border: 1px solid #ddd;
            position: relative;
        }
        .tooltip {
            position: absolute;
            padding: 8px;
            background: rgba(0, 0, 0, 0.8);
            color: white;
            border-radius: 4px;
            pointer-events: none;
            font-size: 12px;
            display: none;
        }
        .axis-label {
            font-size: 12px;
            fill: #666;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>
        <div class="controls">
            <button id="reset">Reset Zoom</button>
            <span>Symbols: AAPL, MSFT, GOOGL, AMZN, TSLA, FB, NVDA, JPM, V, WMT</span>
        </div>
        <div class="heatmap-container">
            <div class="tooltip" id="tooltip"></div>
        </div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 60, right: 20, bottom: 80, left: 100 },
            cellSize: 20,
            updateInterval: 5000, // 5 seconds
            symbols: ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT']
        };

        // Initialize SVG
        const svg = d3.select('.heatmap-container')
            .append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Create tooltip
        const tooltip = d3.select('#tooltip');

        // Create scales
        const xScale = d3.scaleBand()
            .range([config.margin.left, config.width - config.margin.right])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .range([config.margin.top, config.height - config.margin.bottom])
            .padding(0.05);

        const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([-0.1, 0.1]); // Price change range (-10% to +10%)

        // Create axes
        const xAxis = svg.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0,${config.margin.top})`);

        const yAxis = svg.append('g')
            .attr('class', 'y-axis')
            .attr('transform', `translate(${config.margin.left},0)`);

        // Add axis labels
        svg.append('text')
            .attr('class', 'axis-label')
            .attr('x', config.width / 2)
            .attr('y', config.margin.top - 20)
            .style('text-anchor', 'middle')
            .text('Time');

        svg.append('text')
            .attr('class', 'axis-label')
            .attr('transform', 'rotate(-90)')
            .attr('x', -config.height / 2)
            .attr('y', config.margin.left - 60)
            .style('text-anchor', 'middle')
            .text('Stock Symbol');

        // Create zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on('zoom', zoomed);

        svg.call(zoom);

        // Reset zoom button
        d3.select('#reset').on('click', () => {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        });

        // Generate initial data
        let data = generateInitialData();

        // Draw the heatmap
        updateHeatmap();

        // Set up real-time updates
        setInterval(() => {
            updateData();
            updateHeatmap();
        }, config.updateInterval);

        // Functions
        function generateInitialData() {
            const now = new Date();
            const hours = 24; // Last 24 hours
            const timePoints = Array.from({length: hours}, (_, i) => {
                const date = new Date(now);
                date.setHours(now.getHours() - (hours - i - 1));
                return date;
            });

            return config.symbols.flatMap(symbol =>
                timePoints.map(time => ({
                    symbol,
                    time,
                    change: (Math.random() * 0.2 - 0.1).toFixed(4) // Random change between -10% and +10%
                }))
            );
        }

        function updateData() {
            const now = new Date();
            const lastTime = data[data.length - 1].time;

            // Add new data point for each symbol
            config.symbols.forEach(symbol => {
                data.push({
                    symbol,
                    time: now,
                    change: (Math.random() * 0.2 - 0.1).toFixed(4)
                });
            });

            // Remove old data points if we have more than 24 hours
            if (data.length > config.symbols.length * 24) {
                data = data.slice(config.symbols.length);
            }
        }

        function updateHeatmap() {
            // Prepare data for heatmap
            const heatmapData = d3.rollup(
                data,
                v => d3.mean(v, d => +d.change),
                d => d.symbol,
                d => d.time.toISOString().split('T')[0] // Group by date
            );

            // Get unique dates and symbols
            const dates = [...new Set(data.map(d => d.time.toISOString().split('T')[0]))];
            const symbols = [...new Set(data.map(d => d.symbol))];

            // Update scales
            xScale.domain(dates);
            yScale.domain(symbols);

            // Update axes
            xAxis.call(d3.axisBottom(xScale)
                .tickFormat(d => new Date(d).toLocaleDateString())
                .tickSizeOuter(0));

            yAxis.call(d3.axisLeft(yScale)
                .tickSizeOuter(0));

            // Remove old cells
            svg.selectAll('.cell').remove();

            // Add new cells
            svg.selectAll('.cell')
                .data(heatmapData)
                .enter()
                .append('rect')
                .attr('class', 'cell')
                .attr('x', d => xScale(d[1]))
                .attr('y', d => yScale(d[0]))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d[1]))
                .on('mouseover', function(event, d) {
                    tooltip.style('display', 'block')
                        .html(`
                            <strong>${d[0]}</strong><br>
                            Date: ${new Date(d[1]).toLocaleDateString()}<br>
                            Avg Change: ${(d[1] * 100).toFixed(2)}%
                        `);
                })
                .on('mousemove', function(event) {
                    tooltip.style('left', (event.pageX + 10) + 'px')
                        .style('top', (event.pageY + 10) + 'px');
                })
                .on('mouseout', function() {
                    tooltip.style('display', 'none');
                });
        }

        function zoomed(event) {
            const transform = event.transform;

            // Apply zoom to x and y axes
            xAxis.call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            yAxis.call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));

            // Apply zoom to cells
            svg.selectAll('.cell')
                .attr('x', d => transform.applyX(xScale(d[1])))
                .attr('y', d => transform.applyY(yScale(d[0])))
                .attr('width', xScale.bandwidth() * transform.k)
                .attr('height', yScale.bandwidth() * transform.k);
        }
    </script>
</body>
</html>
```

