                <span id="time-range">Time range: Loading...</span>
            </div>
        </div>

        <div id="heatmap-container"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            timeRange: '1y', // Default time range
            updateInterval: 60000 // 1 minute in milliseconds
        };

        // Initialize variables
        let svg, xScale, yScale, colorScale, heatmapData = [];
        let zoom = d3.zoom().scaleExtent([0.5, 20]).on("zoom", zoomed);

        // Main function
        function init() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .call(zoom);

            // Add clip path
            svg.append("defs").append("clipPath")
                .attr("id", "clip")
                .append("rect")
                .attr("width", config.width - config.margin.left - config.margin.right)
                .attr("height", config.height - config.margin.top - config.margin.bottom)
                .attr("x", config.margin.left)
                .attr("y", config.margin.top);

            // Add main group
            svg.append("g").attr("id", "main-group");

            // Initial data load
            updateHeatmap();

            // Set up update button
            d3.select("#update-btn").on("click", updateHeatmap);

            // Set up periodic updates
            setInterval(updateHeatmap, config.updateInterval);
        }

        // Update heatmap with new data
        async function updateHeatmap() {
            const symbol = d3.select(".symbol-input").property("value").toUpperCase();

            try {
                // In a real app, you would fetch data from an API
                // This is a simulated data fetch with random data for demonstration
                const data = await fetchMockStockData(symbol);

                // Process data
                processData(data);

                // Update visualization
                renderHeatmap();

                // Update UI
                updateUI(data);
            } catch (error) {
                console.error("Error updating heatmap:", error);
            }
        }

        // Simulate fetching stock data (in a real app, replace with actual API call)
        async function fetchMockStockData(symbol) {
            // Simulate API delay
            await new Promise(resolve => setTimeout(resolve, 500));

            // Generate mock data
            const now = new Date();
            const endDate = new Date(now);
            const startDate = new Date(now);

            // Adjust based on time range (simplified)
            startDate.setFullYear(now.getFullYear() - 1);

            const days = Math.floor((endDate - startDate) / (1000 * 60 * 60 * 24));
            const hours = 24;
            const data = [];

            // Generate random data for each hour of each day
            for (let day = 0; day < days; day++) {
                const date = new Date(startDate);
                date.setDate(startDate.getDate() + day);

                for (let hour = 0; hour < hours; hour++) {
                    const time = new Date(date);
                    time.setHours(hour);

                    // Generate random price movement
                    const open = 100 + Math.random() * 50;
                    const close = open + (Math.random() - 0.5) * 10;
                    const high = Math.max(open, close) + Math.random() * 5;
                    const low = Math.min(open, close) - Math.random() * 5;
                    const volume = Math.floor(Math.random() * 1000000);

                    data.push({
                        date: time,
                        open,
                        high,
                        low,
                        close,
                        volume,
                        symbol
                    });
                }
            }

            return data;
        }

        // Process raw data into heatmap format
        function processData(data) {
            // Group data by date and hour
            const groupedData = d3.group(data, d => d3.timeDay(d.date).getTime());

            // Convert to array of arrays for heatmap
            heatmapData = Array.from(groupedData, ([day, values]) => {
                const dayData = new Array(24).fill(null);

                values.forEach(d => {
                    const hour = d.date.getHours();
                    dayData[hour] = {
                        date: d.date,
                        open: d.open,
                        high: d.high,
                        low: d.low,
                        close: d.close,
                        volume: d.volume
                    };
                });

                return dayData;
            });

            // Filter out days with no data
            heatmapData = heatmapData.filter(day => day.some(hour => hour !== null));
        }

        // Render the heatmap
        function renderHeatmap() {
            // Clear previous content
            d3.select("#main-group").selectAll("*").remove();

            // Create scales
            const days = heatmapData.length;
            const hours = 24;

            xScale = d3.scaleBand()
                .domain(d3.range(hours))
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            yScale = d3.scaleBand()
                .domain(d3.range(days))
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.05);

            // Find min and max prices for color scale
            const allPrices = heatmapData.flat().filter(d => d !== null).flatMap(d => [d.low, d.high]);
            const minPrice = d3.min(allPrices);
            const maxPrice = d3.max(allPrices);

            colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                .domain([minPrice, maxPrice]);

            // Create main group
            const mainGroup = d3.select("#main-group");

            // Add rectangles for each hour
            mainGroup.selectAll(".hour")
                .data(heatmapData.flatMap((day, i) => day.map((hour, j) => ({ day: i, hour: j, data: hour }))))
                .enter()
                .filter(d => d.data !== null)
                .append("rect")
                .attr("class", "hour")
                .attr("x", d => xScale(d.hour))
                .attr("y", d => yScale(d.day))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale((d.data.low + d.data.high) / 2))
                .attr("clip-path", "url(#clip)")
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip);

            // Add axes
            addAxes(mainGroup);
        }

        // Add axes to the visualization
        function addAxes(group) {
            // X-axis (hours)
            group.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d => `${d}:00`)
                    .tickValues(d3.range(0, 24, 3)))
                .selectAll("text")
                .attr("y", 0)
                .attr("x", 9)
                .attr("dy", ".35em")
                .attr("transform", "rotate(45)")
                .style("text-anchor", "start");

            // Y-axis (days)
            group.append("g")
                .attr("class", "axis axis--y")
                .attr("transform", `translate(${config.margin.left},0)`)
                .call(d3.axisLeft(yScale)
                    .tickFormat((d, i) => {
                        if (i % 5 === 0) {
                            const date = heatmapData[d][0].date;
                            return d3.timeFormat("%b %d")(date);
                        }
                        return "";
                    })
                    .tickValues(d3.range(0, heatmapData.length, 5)));

            // Add axis labels
            group.append("text")
                .attr("class", "axis-label")
                .attr("transform", `translate(${config.width/2},${config.height - 5})`)
                .style("text-anchor", "middle")
                .text("Hour of Day");

            group.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("y", 15)
                .attr("x", 0 - (config.height / 2))
                .style("text-anchor", "middle")
                .text("Date");
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const tooltip = d3.select("body").append("div")
                .attr("class", "tooltip")
                .style("position", "absolute")
                .style("padding", "10px")
                .style("background", "rgba(0,0,0,0.8)")
                .style("color", "white")
                .style("border-radius", "5px")
                .style("pointer-events", "none")
                .style("font-size", "12px")
                .style("left", `${event.pageX + 10}px`)
                .style("top", `${event.pageY + 10}px`);

            const date = d3.timeFormat("%b %d, %Y %H:%M")(d.data.date);
            const priceChange = (d.data.close - d.data.open).toFixed(2);
            const priceChangePercent = ((d.data.close - d.data.open) / d.data.open * 100).toFixed(2);

            tooltip.html(`
                <strong>${date}</strong><br>
                Open: ${d.data.open.toFixed(2)}<br>
                Close: ${d.data.close.toFixed(2)}<br>
                High: ${d.data.high.toFixed(2)}<br>
                Low: ${d.data.low.toFixed(2)}<br>
                Change: ${priceChange} (${priceChangePercent}%)<br>
                Volume: ${d.data.volume.toLocaleString()}
            `);
        }

        // Hide tooltip
        function hideTooltip() {
            d3.select(".tooltip").remove();
        }

        // Handle zoom/pan
        function zoomed(event) {
            d3.select("#main-group").attr("transform", event.transform);
        }

        // Update UI with latest info
        function updateUI(data) {
            if (!data || data.length === 0) return;

            const lastUpdate = new Date();
            d3.select("#last-update").text(`Last updated: ${d3.timeFormat("%H:%M:%S")(lastUpdate)}`);

            const firstDate = d3.min(data, d => d.date);
            const lastDate = d3.max(data, d => d.date);
            d3.select("#time-range").text(`Time range: ${d3.timeFormat("%b %d, %Y")(firstDate)} - ${d3.timeFormat("%b %d, %Y")(lastDate)}`);
        }

        // Initialize the visualization
        init();
    </script>
</body>
</html>
