            const yScale = d3.scaleBand()
                .range([config.height - config.margin.bottom, config.margin.top]);

            const colorScale = d3.scaleQuantile()
                .range(config.colors);

            // Create axes
            const xAxis = svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`);

            const yAxis = svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [config.width, config.height]])
                .on("zoom", (event) => {
                    const newXScale = event.transform.rescaleX(xScale);
                    const newYScale = event.transform.rescaleY(yScale);

                    svg.selectAll(".cell")
                        .attr("x", d => newXScale(d.hour))
                        .attr("y", d => newYScale(d.day))
                        .attr("width", newXScale.bandwidth())
                        .attr("height", newYScale.bandwidth());

                    xAxis.call(d3.axisBottom(newXScale).tickFormat(d3.format("d")));
                    yAxis.call(d3.axisLeft(newYScale));
                });

            svg.call(zoom);

            // Reset zoom button
            d3.select("#resetZoom").on("click", () => {
                svg.transition()
                    .duration(750)
                    .call(zoom.transform, d3.zoomIdentity);
            });

            // Tooltip
            const tooltip = d3.select("#tooltip");

            // Create legend
            createLegend();

            // Initial data load
            loadData();

            // Set up periodic updates
            setInterval(loadData, config.updateInterval);
        }

        // Create legend
        function createLegend() {
            const legend = d3.select("#legend");

            const legendItems = [
                { label: "Low", color: config.colors[0] },
                { label: "Medium", color: config.colors[Math.floor(config.colors.length / 2)] },
                { label: "High", color: config.colors[config.colors.length - 1] }
            ];

            legend.selectAll(".legend-item")
                .data(legendItems)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);
        }

        // Load data (simulated API call)
        function loadData() {
            // In a real application, this would fetch from an API
            // For demo purposes, we'll generate random data
            const now = new Date();
            const endDate = new Date(now);

            // Adjust time range based on selection
            switch(currentTimeRange) {
                case "1d": endDate.setDate(now.getDate() - 1); break;
                case "1w": endDate.setDate(now.getDate() - 7); break;
                case "1m": endDate.setMonth(now.getMonth() - 1); break;
                case "3m": endDate.setMonth(now.getMonth() - 3); break;
                case "1y": endDate.setFullYear(now.getFullYear() - 1); break;
            }

            // Generate random data for the selected time range
            const days = Math.ceil((now - endDate) / (1000 * 60 * 60 * 24));
            const hours = 24;

            data = [];
            for (let d = 0; d < days; d++) {
                for (let h = 0; h < hours; h++) {
                    // Generate a random price change (percentage)
                    const change = (Math.random() * 10 - 5).toFixed(2);
                    const date = new Date(endDate);
                    date.setDate(date.getDate() + d);

                    data.push({
                        stock: currentStock,
                        day: date.toISOString().split('T')[0],
                        hour: h,
                        change: parseFloat(change),
                        date: date
                    });
                }
            }

            updateChart();
        }

        // Update the chart with new data
        function updateChart() {
            const svg = d3.select("#heatmap");

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(d3.range(24)) // 24 hours
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(data.map(d => d.day).filter((d, i, arr) => arr.indexOf(d) === i))
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.01);

            const colorScale = d3.scaleQuantile()
                .domain(data.map(d => d.change))
                .range(config.colors);

            // Update axes
            svg.select(".x-axis")
                .call(d3.axisBottom(xScale).tickFormat(d => `${d}:00`));

            svg.select(".y-axis")
                .call(d3.axisLeft(yScale));

            // Bind data to cells
            const cells = svg.selectAll(".cell")
                .data(data, d => `${d.day}-${d.hour}`);

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.hour))
                .attr("y", d => yScale(d.day))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    d3.select("#tooltip")
                        .style("display", "block")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Date: ${d.day}<br>
                            Time: ${d.hour}:00<br>
                            Change: ${d.change}%
                        `)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("display", "none");
                });

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("fill", d => colorScale(d.change));

            // Remove old cells
            cells.exit().remove();
        }

        // Event listeners for controls
        d3.select("#timeRange").on("change", function() {
            currentTimeRange = this.value;
            loadData();
        });

        d3.select("#stockSelect").on("change", function() {
            currentStock = this.value;
            loadData();
        });

        // Initialize the chart when the page loads
        window.onload = initChart;
    </script>
</body>
</html>
