                '3m': { days: 90, label: 'Weekly' },
                '1y': { days: 365, label: 'Monthly' }
            }
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
        let currentData = generateMockData(config.timeRanges['1m']);

        // Set up the SVG container
        const svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        // Create scales
        const xScale = d3.scaleBand()
            .range([config.margin.left, config.width - config.margin.right]);

        const yScale = d3.scaleBand()
            .range([config.margin.top, config.height - config.margin.bottom]);

        const colorScale = d3.scaleQuantile()
            .range(config.colors);

        // Create axes
        const xAxis = svg.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0, ${config.height - config.margin.bottom})`);

        const yAxis = svg.append("g")
            .attr("class", "y-axis")
            .attr("transform", `translate(${config.margin.left}, 0)`);

        // Add axis labels
        svg.append("text")
            .attr("class", "axis-label")
            .attr("x", config.width / 2)
            .attr("y", config.height - 5)
            .style("text-anchor", "middle")
            .text("Time");

        svg.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -config.height / 2)
            .attr("y", 15)
            .style("text-anchor", "middle")
            .text("Stock");

        // Create zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        // Tooltip
        const tooltip = d3.select("#tooltip");

        // Draw the heatmap
        function drawHeatmap(data) {
            // Update scales
            xScale.domain(data.map(d => d.date));
            yScale.domain(stocks);

            // Update color scale
            const allValues = data.flatMap(d => Object.values(d.prices));
            colorScale.domain([d3.min(allValues), d3.max(allValues)]);

            // Update axes
            xAxis.call(d3.axisBottom(xScale)
                .tickFormat(d => d3.timeFormat("%b %d")(new Date(d)))
                .tickSizeOuter(0));

            yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Remove old cells
            svg.selectAll(".cell").remove();

            // Draw cells
            const cells = svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("g")
                .attr("class", "cell")
                .attr("transform", d => `translate(${xScale(d.date)}, 0)`);

            stocks.forEach((stock, i) => {
                cells.append("rect")
                    .attr("x", 0)
                    .attr("y", yScale(stock))
                    .attr("width", xScale.bandwidth())
                    .attr("height", yScale.bandwidth())
                    .attr("fill", d => colorScale(d.prices[stock]))
                    .on("mouseover", function(event, d) {
                        tooltip.style("opacity", 1)
                            .html(`
                                <strong>${stock}</strong><br>
                                Date: ${d3.timeFormat("%b %d, %Y")(new Date(d.date))}<br>
                                Price: $${d.prices[stock].toFixed(2)}
                            `);
                    })
                    .on("mousemove", function(event) {
                        tooltip.style("left", (event.pageX + 10) + "px")
                            .style("top", (event.pageY - 28) + "px");
                    })
                    .on("mouseout", function() {
                        tooltip.style("opacity", 0);
                    });
            });

            // Add legend
            svg.selectAll(".legend").remove();

            const legend = svg.append("g")
                .attr("class", "legend")
                .attr("transform", `translate(${config.width - 150}, ${config.margin.top})`);

            const legendScale = d3.scaleBand()
                .domain(colorScale.quantiles())
                .range([0, 120]);

            legend.selectAll("rect")
                .data(colorScale.range().map((color, i) => {
                    return {
                        color: color,
                        min: i === 0 ? colorScale.domain()[0] : colorScale.quantiles()[i-1],
                        max: colorScale.quantiles()[i]
                    };
                }))
                .enter()
                .append("rect")
                .attr("x", (d, i) => i * 30)
                .attr("y", 0)
                .attr("width", 30)
                .attr("height", 20)
                .attr("fill", d => d.color);

            legend.selectAll("text")
                .data(colorScale.quantiles())
                .enter()
                .append("text")
                .attr("x", (d, i) => i * 30 + 15)
                .attr("y", 35)
                .attr("text-anchor", "middle")
                .text(d => d.toFixed(2))
                .style("font-size", "10px")
                .style("fill", "#666");
        }

        // Zoom handler
        function zoomed(event) {
            const transform = event.transform;

            // Apply zoom to x-axis
            xAxis.call(d3.axisBottom(xScale)
                .scale(transform.rescaleX(xScale))
                .tickFormat(d => d3.timeFormat("%b %d")(new Date(d)))
                .tickSizeOuter(0));

            // Update cell positions
            svg.selectAll(".cell")
                .attr("transform", d => `translate(${transform.applyX(xScale(d.date))}, 0)`);

            // Update cell sizes
            svg.selectAll("rect")
                .attr("width", xScale.bandwidth() * transform.k)
                .attr("height", yScale.bandwidth() * transform.k);
        }

        // Generate mock data (in a real app, replace with API calls)
        function generateMockData(timeRange) {
            const endDate = new Date();
            const startDate = new Date();
            startDate.setDate(endDate.getDate() - timeRange.days);

            const dates = [];
            let currentDate = new Date(startDate);

            // Generate dates based on time range
            if (timeRange.days <= 1) {
                // Hourly data for 1 day
                while (currentDate <= endDate) {
                    dates.push(new Date(currentDate));
                    currentDate.setHours(currentDate.getHours() + 1);
                }
            } else if (timeRange.days <= 7) {
                // Daily data for 1 week
                while (currentDate <= endDate) {
                    dates.push(new Date(currentDate));
                    currentDate.setDate(currentDate.getDate() + 1);
                }
            } else if (timeRange.days <= 30) {
                // Daily data for 1 month
                while (currentDate <= endDate) {
                    dates.push(new Date(currentDate));
                    currentDate.setDate(currentDate.getDate() + 1);
                }
            } else if (timeRange.days <= 90) {
                // Weekly data for 3 months
                while (currentDate <= endDate) {
                    dates.push(new Date(currentDate));
                    currentDate.setDate(currentDate.getDate() + 7);
                }
            } else {
                // Monthly data for 1 year
                while (currentDate <= endDate) {
                    dates.push(new Date(currentDate));
                    currentDate.setMonth(currentDate.getMonth() + 1);
                }
            }

            // Generate random prices for each date and stock
            return dates.map(date => {
                const prices = {};
                stocks.forEach(stock => {
                    // Generate a random price between 100 and 500
                    prices[stock] = 100 + Math.random() * 400;
                });
                return {
                    date: date.toISOString().split('T')[0],
                    prices: prices
                };
            });
        }

        // Event listeners for time range buttons
        document.getElementById('1d').addEventListener('click', () => {
            currentData = generateMockData(config.timeRanges['1d']);
            drawHeatmap(currentData);
        });

        document.getElementById('1w').addEventListener('click', () => {
            currentData = generateMockData(config.timeRanges['1w']);
            drawHeatmap(currentData);
        });

        document.getElementById('1m').addEventListener('click', () => {
            currentData = generateMockData(config.timeRanges['1m']);
            drawHeatmap(currentData);
        });

        document.getElementById('3m').addEventListener('click', () => {
            currentData = generateMockData(config.timeRanges['3m']);
            drawHeatmap(currentData);
        });

        document.getElementById('1y').addEventListener('click', () => {
            currentData = generateMockData(config.timeRanges['1y']);
            drawHeatmap(currentData);
        });

        // Event listeners for zoom controls
        document.getElementById('zoom-in').addEventListener('click', () => {
            svg.transition().call(zoom.scaleBy, 1.5);
        });

        document.getElementById('zoom-out').addEventListener('click', () => {
            svg.transition().call(zoom.scaleBy, 0.75);
        });

        document.getElementById('reset').addEventListener('click', () => {
            svg.transition().call(zoom.transform, d3.zoomIdentity);
        });

        // Initial draw
        drawHeatmap(currentData);

        // Simulate real-time updates (every 5 seconds)
        setInterval(() => {
            // Add a new data point
            const lastDate = new Date(currentData[currentData.length - 1].date);
            const newDate = new Date(lastDate);
            newDate.setDate(newDate.getDate() + 1);

            const newPrices = {};
            stocks.forEach(stock => {
                // Generate a new price based on the last price with some randomness
                const lastPrice = currentData[currentData.length - 1].prices[stock];
                newPrices[stock] = lastPrice * (0.95 + Math.random() * 0.1);
            });

            currentData.push({
                date: newDate.toISOString().split('T')[0],
                prices: newPrices
            });

            // Remove the oldest data point if we have more than 30
            if (currentData.length > 30) {
                currentData.shift();
            }

            drawHeatmap(currentData);
        }, 5000);
    </script>
