        function generateStockData() {
            const stocks = [];
            const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'PYPL', 'ADBE', 'INTC',
                            'CSCO', 'NFLX', 'CRM', 'ORCL', 'IBM', 'QCOM', 'AMD', 'TXN', 'AVGO', 'MU'];

            for (let i = 0; i < config.numStocks; i++) {
                const stock = {
                    symbol: symbols[i],
                    prices: []
                };

                // Generate random price history
                let lastPrice = 100 + Math.random() * 200;
                for (let j = 0; j < config.numDays; j++) {
                    // Random walk with some volatility
                    lastPrice *= 1 + (Math.random() - 0.5) * 0.05;
