            svg.append("g")
                .attr("transform", `translate(${config.margin.left},0)`)
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .attr("text-anchor", "middle")
                .text("Trading Days")
                .attr("class", "axis-label");

            svg.append("text")
                .attr("transform", "rotate(-90)")
                .attr("y", 15)
                .attr("x", -config.height / 2)
                .attr("text-anchor", "middle")
                .text("Stocks")
                .attr("class", "axis-label");

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [config.width, config.height]])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.selectAll(".heatmap-cell")
                        .attr("transform", transform);
                    svg.selectAll(".axis-label")
                        .attr("transform", transform);
                });

            svg.call(zoom);

            // Store scales and elements in the DOM for later updates
            svg.node().__data__ = {
                xScale,
                yScale,
                colorScale,
                tooltip
            };

            return svg;
        }

        // Update the heatmap with new data
        function updateHeatmap(svg, data) {
            const { xScale, yScale, colorScale, tooltip } = svg.node().__data__;

            // Bind data to cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(data.flatMap((stock, stockIndex) =>
                    stock.prices.map((price, dayIndex) => ({
                        stockIndex: stockIndex.toString(),
                        dayIndex: dayIndex.toString(),
                        price,
                        symbol: stock.symbol
                    }))
                ));

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "heatmap-cell")
                .attr("x", d => xScale(d.dayIndex))
                .attr("y", d => yScale(d.stockIndex))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", (event, d) => {
                    tooltip.style("visibility", "visible")
                        .html(`<strong>${d.symbol}</strong><br>Day ${parseInt(d.dayIndex) + 1}: $${d.price}`);
                })
                .on("mousemove", (event) => {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", () => {
                    tooltip.style("visibility", "hidden");
                });

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("fill", d => colorScale(d.price));

            // Remove old cells
            cells.exit().remove();
        }

        // Main function to initialize and update the heatmap
        function main() {
            // Initialize the heatmap
            const svg = initHeatmap();

            // Initial data load
            let stockData = generateStockData();
            updateHeatmap(svg, stockData);

            // Set up periodic updates
            setInterval(() => {
                // Generate new data (simulating real-time updates)
                stockData = generateStockData();
                updateHeatmap(svg, stockData);
            }, config.updateInterval);
        }

        // Start the application
        main();
    </script>
</body>
</html>
```

