    <script>
        // Configuration
        const config = {
            width: 900,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
