                '1y': { days: 365, interval: 'week' }
            }
        };

        // Mock stock data generator
        function generateStockData(range) {
            const now = new Date();
            const endDate = new Date(now);
            const startDate = new Date(now);
            startDate.setDate(now.getDate() - config.timeRanges[range].days);

            const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'BRK.B', 'JNJ', 'JPM'];
            const data = [];

            for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
                stocks.forEach(stock => {
                    // Generate random price movement
                    const basePrice = 100 + Math.random() * 200;
                    const price = basePrice + (Math.random() * 20 - 10); // Random fluctuation
                    const volume = Math.floor(Math.random() * 1000000);

                    data.push({
                        date: new Date(d),
                        stock: stock,
                        price: price,
                        volume: volume,
                        change: (price - basePrice) / basePrice * 100
                    });
                });
            }

            return data;
        }

        // Initialize the heatmap
        function initHeatmap(data, range) {
            // Clear previous chart
            d3.select("#heatmap").selectAll("*").remove();

            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = d3.select("#heatmap")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create scales
            const xScale = d3.scaleBand()
                .domain(d3.group(data, d => d.date.toISOString().split('T')[0]).keys())
                .range([0, width])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(d3.group(data, d => d.stock).keys())
                .range([0, height])
                .padding(0.05);

            const colorScale = d3.scaleQuantile()
                .domain(d3.extent(data, d => d.change))
                .range(config.colors);

            // Create axes
            const xAxis = svg.append("g")
                .attr("class", "axis")
                .attr("transform", `translate(0,${height})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d => {
                        const date = new Date(d);
                        if (range === '1d' || range === '1w') {
                            return d3.timeFormat("%b %d")(date);
                        } else if (range === '1m') {
                            return d3.timeFormat("%b %d")(date);
                        } else {
                            return d3.timeFormat("%b %Y")(date);
                        }
                    })
                    .tickSizeOuter(0));

            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Date");

            const yAxis = svg.append("g")
                .attr("class", "axis")
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .style("text-anchor", "end");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 15)
                .style("text-anchor", "middle")
                .text("Stock");

            // Create cells
            svg.selectAll(".cell")
                .data(data)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date.toISOString().split('T')[0]))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    d3.select("#tooltip")
                        .style("display", "block")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Date: ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Change: ${d.change.toFixed(2)}%<br>
                            Volume: ${d.volume.toLocaleString()}
                        `)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("display", "none");
                });

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", (event) => {
                    const transform = event.transform;
                    svg.attr("transform", transform);

                    // Update zoom level display
                    d3.select("#zoomLevel").text(`${Math.round(transform.k * 100)}%`);
                });

            svg.call(zoom);
        }

        // Initialize with default data
        let currentData = generateStockData('1m');
        initHeatmap(currentData, '1m');

        // Update data when time range changes
        d3.select("#timeRange").on("change", function() {
            const selectedRange = this.value;
            currentData = generateStockData(selectedRange);
            initHeatmap(currentData, selectedRange);
        });

        // Simulate real-time updates
        setInterval(() => {
            // Add new data point (simulating real-time update)
            const lastDate = new Date(currentData[currentData.length - 1].date);
            const newDate = new Date(lastDate);
            newDate.setDate(lastDate.getDate() + 1);

            const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'BRK.B', 'JNJ', 'JPM'];
            const newData = [];

            stocks.forEach(stock => {
