                newData.push({
                    date: newDate,
                    stock: stock,
                    price: price,
                    volume: volume,
                    change: (price - basePrice) / basePrice * 100
                });
            });

            // Update current data
            currentData = [...currentData, ...newData];

            // Reinitialize heatmap (in a real app, you might update incrementally)
            const currentRange = d3.select("#timeRange").property("value");
            initHeatmap(currentData, currentRange);
        }, 5000); // Update every 5 seconds
    </script>
