<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>
        <div class="heatmap-container" id="heatmap"></div>
        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 900,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            numStocks: 20,
            numDays: 30,
            updateInterval: 2000 // ms
        };

        // Generate random stock data
        function generateStockData() {
            const stocks = [];
            const basePrices = Array.from({length: config.numStocks}, () => 100 + Math.random() * 100);

            for (let i = 0; i < config.numStocks; i++) {
                const stock = {
                    name: `STOCK-${String.fromCharCode(65 + i)}`,
                    prices: []
                };

                let prevPrice = basePrices[i];
                for (let j = 0; j < config.numDays; j++) {
                    // Simulate price movement with some randomness
                    const change = (Math.random() - 0.5) * 2;
                    prevPrice = Math.max(1, prevPrice + change);
                    stock.prices.push(prevPrice);
                }

                stocks.push(stock);
            }

            return stocks;
        }

        // Initialize the heatmap
        function initHeatmap() {
            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = d3.select("#heatmap")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create scales
            const xScale = d3.scaleBand()
                .domain(d3.range(config.numDays))
                .range([0, width])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(d3.range(config.numStocks))
                .range([0, height])
                .padding(0.05);

            const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                .domain([80, 120]); // Price range for color mapping

            // Add axes
            const xAxis = svg.append("g")
                .attr("transform", `translate(0,${height})`)
                .call(d3.axisBottom(xScale).tickFormat(d => `Day ${d+1}`));

            const yAxis = svg.append("g")
                .call(d3.axisLeft(yScale).tickFormat(d => `Stock ${String.fromCharCode(65 + d)}`));

            // Add tooltip
            const tooltip = d3.select("body").append("div")
                .attr("class", "tooltip")
                .style("opacity", 0);

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 8])
                .on("zoom", (event) => {
                    svg.attr("transform", event.transform);
                });

            d3.select("#heatmap svg").call(zoom);

            // Create legend
            const legend = d3.select("#legend");
            const legendData = [80, 90, 100, 110, 120];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${colorScale(d)}"></div>
                    <span>${d}</span>
                `);

            return { svg, xScale, yScale, colorScale, tooltip };
        }

        // Update the heatmap with new data
        function updateHeatmap(svg, xScale, yScale, colorScale, tooltip, data) {
            // Remove existing cells
            svg.selectAll(".cell").remove();

            // Add cells
            svg.selectAll(".cell")
                .data(data.flatMap((stock, i) =>
                    stock.prices.map((price, j) => ({
                        stockIndex: i,
                        dayIndex: j,
                        price: price,
                        name: stock.name
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.dayIndex))
                .attr("y", d => yScale(d.stockIndex))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", (event, d) => {
                    tooltip.transition()
                        .duration(200)
                        .style("opacity", .9);
                    tooltip.html(`<strong>${d.name}</strong><br>Day ${d.dayIndex+1}: $${d.price.toFixed(2)}`)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", () => {
                    tooltip.transition()
                        .duration(500)
                        .style("opacity", 0);
                });
        }

        // Main function
        function main() {
            // Initialize heatmap
            const { svg, xScale, yScale, colorScale, tooltip } = initHeatmap();

            // Generate initial data
            let stockData = generateStockData();

            // Initial render
            updateHeatmap(svg, xScale, yScale, colorScale, tooltip, stockData);

            // Set up real-time updates
            setInterval(() => {
                // Update prices (simulate real-time data)
                stockData = stockData.map(stock => {
                    const lastPrice = stock.prices[stock.prices.length - 1];
                    const newPrice = Math.max(1, lastPrice + (Math.random() - 0.5) * 2);
                    return {
                        ...stock,
                        prices: [...stock.prices.slice(1), newPrice]
                    };
                });

                // Update the heatmap
                updateHeatmap(svg, xScale, yScale, colorScale, tooltip, stockData);
            }, config.updateInterval);
        }

        // Start the application
        main();
    </script>
</body>
</html>
```

