        }

        // Fetch data from API (simulated with mock data)
        function fetchData() {
            // In a real implementation, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
            // This is a simulated data generator for demonstration purposes
            const now = new Date();
            const endTime = now.getTime();
            let startTime;

            switch(currentTimeRange) {
                case "1d": startTime = endTime - (24 * 60 * 60 * 1000); break;
                case "1w": startTime = endTime - (7 * 24 * 60 * 60 * 1000); break;
                case "1m": startTime = endTime - (30 * 24 * 60 * 60 * 1000); break;
                case "3m": startTime = endTime - (90 * 24 * 60 * 60 * 1000); break;
                case "1y": startTime = endTime - (365 * 24 * 60 * 60 * 1000); break;
                default: startTime = endTime - (30 * 24 * 60 * 60 * 1000);
            }

            // Generate mock data
            const mockData = generateMockData(startTime, endTime);
            updateVisualization(mockData);
        }

        // Generate mock data for demonstration
        function generateMockData(startTime, endTime) {
            const dataPoints = [];
            const timeInterval = (endTime - startTime) / 100; // 100 time points
            const basePrice = 100 + Math.random() * 100; // Random base price

            for (let i = 0; i < 100; i++) {
                const time = startTime + i * timeInterval;
                const price = basePrice + (Math.random() - 0.5) * 20; // Random price fluctuation
                const volume = Math.floor(Math.random() * 1000000); // Random volume

                dataPoints.push({
                    time: new Date(time),
                    price: price.toFixed(2),
                    volume: volume
                });
            }

            return dataPoints;
        }

        // Update the visualization with new data
        function updateVisualization(newData) {
            data = newData;

            // Set up scales
            xScale = d3.scaleTime()
                .domain(d3.extent(data, d => d.time))
                .range([config.margin.left, config.width - config.margin.right]);

            yScale = d3.scaleLinear()
                .domain([d3.min(data, d => d.price) * 0.95, d3.max(data, d => d.price) * 1.05])
                .range([config.height - config.margin.bottom, config.margin.top]);

            // Set up color scale based on volume
            const volumeExtent = d3.extent(data, d => d.volume);
            colorScale = config.colorScale.domain([volumeExtent[1], volumeExtent[0]]);

            // Update heatmap
            const heatmapGroup = svg.select(".heatmap-group");

            // Create a grid of rectangles
            const gridSize = 10; // Number of cells in each dimension
            const xStep = (xScale.range()[1] - xScale.range()[0]) / gridSize;
            const yStep = (yScale.range()[0] - yScale.range()[1]) / gridSize;

            // Create a grid of data points
            const gridData = [];
            for (let i = 0; i < gridSize; i++) {
                for (let j = 0; j < gridSize; j++) {
                    const x = xScale.range()[0] + i * xStep;
                    const y = yScale.range()[1] + j * yStep;

                    // Find the closest data point
                    const closest = data.reduce((prev, curr) => {
                        const prevDist = Math.abs(xScale(prev.time) - x) + Math.abs(yScale(prev.price) - y);
                        const currDist = Math.abs(xScale(curr.time) - x) + Math.abs(yScale(curr.price) - y);
                        return prevDist < currDist ? prev : curr;
                    });

                    gridData.push({
                        x: x,
                        y: y,
                        time: closest.time,
                        price: closest.price,
                        volume: closest.volume
                    });
                }
            }

            // Bind data to rectangles
            const rects = heatmapGroup.selectAll("rect")
                .data(gridData, d => `${d.x}-${d.y}`);

