                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("opacity", 0);
                });

            // Update existing rectangles
            rects.transition()
                .duration(500)
                .attr("fill", d => colorScale(d.volume));

            // Remove old rectangles
            rects.exit().remove();

            // Update axes
            svg.select(".x-axis")
                .transition()
                .duration(500)
                .call(d3.axisBottom(xScale).ticks(10).tickFormat(d3.timeFormat("%b %d")));

            svg.select(".y-axis")
                .transition()
                .duration(500)
                .call(d3.axisLeft(yScale).ticks(10));
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;
            svg.select(".heatmap-group").attr("transform", transform);
            svg.select(".x-axis").call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            svg.select(".y-axis").call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
