            border: 1px solid #ddd;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>
        <div class="controls">
            <button id="zoom-in">Zoom In</button>
            <button id="zoom-out">Zoom Out</button>
            <button id="reset">Reset View</button>
        </div>
        <div class="heatmap-container" id="heatmap"></div>
        <div class="legend">
            <div class="legend-item">
                <div class="legend-color" style="background-color: #ff0000;"></div>
                <span>High Price</span>
            </div>
            <div class="legend-item">
                <div class="legend-color" style="background-color: #00ff00;"></div>
                <span>Low Price</span>
            </div>
        </div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 900,
            height: 500,
            margin: { top: 30, right: 30, bottom: 30, left: 60 },
            zoomScale: 1.2,
            updateInterval: 5000 // 5 seconds
        };

        // Sample data - in a real app, this would come from an API
        let stockData = generateSampleData();

        // Initialize the heatmap
        const svg = d3.select("#heatmap")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        // Create scales
        const xScale = d3.scaleBand()
            .range([0, config.width - config.margin.left - config.margin.right])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .range([0, config.height - config.margin.top - config.margin.bottom])
            .padding(0.05);

        const colorScale = d3.scaleLinear()
            .range(["#00ff00", "#ff0000"]); // Green to red

        // Create axes
        const xAxis = g.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`);

        const yAxis = g.append("g")
            .attr("class", "y-axis");

        // Create zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        // Update the heatmap
        function updateHeatmap() {
            // Update data (in a real app, this would fetch new data)
            stockData = generateSampleData();

            // Set domains
            const stocks = Array.from(new Set(stockData.map(d => d.stock)));
            const dates = Array.from(new Set(stockData.map(d => d.date)));

            xScale.domain(dates);
            yScale.domain(stocks);

            const prices = stockData.map(d => d.price);
            colorScale.domain([d3.min(prices), d3.max(prices)]);

            // Update axes
            xAxis.call(d3.axisBottom(xScale).tickSizeOuter(0));
            yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Join data to rectangles
            const rects = g.selectAll("rect")
                .data(stockData, d => `${d.stock}-${d.date}`);

            // Enter new rectangles
            rects.enter()
                .append("rect")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .append("title")
                .text(d => `${d.stock} on ${d.date}: $${d.price.toFixed(2)}`);

            // Update existing rectangles
            rects.transition()
                .duration(1000)
                .attr("fill", d => colorScale(d.price))
                .select("title")
                .text(d => `${d.stock} on ${d.date}: $${d.price.toFixed(2)}`);

            // Remove old rectangles
            rects.exit().remove();
        }

        // Zoom handler
        function zoomed(event) {
            g.attr("transform", event.transform);
        }

        // Button event handlers
        document.getElementById("zoom-in").addEventListener("click", () => {
            svg.transition()
                .duration(750)
                .call(zoom.scaleBy, config.zoomScale);
        });

        document.getElementById("zoom-out").addEventListener("click", () => {
            svg.transition()
                .duration(750)
                .call(zoom.scaleBy, 1 / config.zoomScale);
        });

        document.getElementById("reset").addEventListener("click", () => {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        });

        // Generate sample data (simulating API response)
        function generateSampleData() {
            const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "BRK.A"];
            const dates = [];
            const today = new Date();

            // Generate dates for the last 30 days
            for (let i = 0; i < 30; i++) {
                const date = new Date(today);
                date.setDate(today.getDate() - i);
                dates.push(date.toISOString().split('T')[0]);
            }

            // Generate random prices
            return stocks.flatMap(stock =>
                dates.map(date => ({
                    stock,
                    date,
                    price: Math.random() * 100 + 100 // Random price between 100-200
                }))
            );
        }

        // Initial render
        updateHeatmap();

        // Set up periodic updates
        setInterval(updateHeatmap, config.updateInterval);
    </script>
</body>
</html>
