### 5. Board Component (Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import AddTaskForm from './AddTaskForm';
import { db } from '../firebase/firebase';
import { collection, addDoc, updateDoc, doc, deleteDoc } from 'firebase/firestore';
import { useFirestore } from '../hooks/useFirestore';

const Board = () => {
  const { docs: tasks } = useFirestore('tasks');
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    // Organize tasks into columns
    const newColumns = { ...columns };
    Object.keys(newColumns).forEach(columnId => {
      newColumns[columnId].taskIds = tasks
        .filter(task => task.status === columnId)
        .map(task => task.id);
    });
    setColumns(newColumns);
  }, [tasks]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Update task status in Firestore
    const taskRef = doc(db, 'tasks', draggableId);
    updateDoc(taskRef, {
      status: destination.droppableId
    });
  };

  const addTask = async (title, description, status = 'todo') => {
    await addDoc(collection(db, 'tasks'), {
      title,
      description,
      status,
      createdAt: new Date(),
      assignedTo: null
    });
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, 'tasks', taskId));
  };

  return (
    <div className="board">
      <h1>Project Management Board</h1>
      <AddTaskForm onAddTask={addTask} />

      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {Object.entries(columns).map(([columnId, column]) => (
            <Droppable droppableId={columnId} key={columnId}>
              {(provided) => (
                <div
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                  className="column"
                >
                  <Column
                    column={column}
                    tasks={tasks.filter(task => task.status === columnId)}
                    onDeleteTask={deleteTask}
                  />
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

