### 6. Board Component (Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext } from 'react-beautiful-dnd';
import styled from 'styled-components';
import Column from './Column';
import TaskModal from './TaskModal';
import { useFirestore } from '../hooks/useFirestore';

const BoardContainer = styled.div`
  display: flex;
  padding: 20px;
  overflow-x: auto;
`;

const Board = () => {
  const { docs: columns, updateDocument: updateColumn } = useFirestore('columns');
  const { docs: tasks, updateDocument: updateTask } = useFirestore('tasks');
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Update task status if column changed
    if (destination.droppableId !== source.droppableId) {
      updateTask(draggableId, { status: destination.droppableId });
    }

    // Reorder tasks in the same column
    const sourceColumn = columns.find(col => col.id === source.droppableId);
    const destinationColumn = columns.find(col => col.id === destination.droppableId);

    if (sourceColumn === destinationColumn) {
      const newTaskIds = Array.from(sourceColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      updateColumn(sourceColumn.id, { taskIds: newTaskIds });
    } else {
      // Moving to a different column
      const sourceTaskIds = Array.from(sourceColumn.taskIds);
      sourceTaskIds.splice(source.index, 1);
      updateColumn(sourceColumn.id, { taskIds: sourceTaskIds });

      const destinationTaskIds = Array.from(destinationColumn.taskIds);
      destinationTaskIds.splice(destination.index, 0, draggableId);
      updateColumn(destinationColumn.id, { taskIds: destinationTaskIds });
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setSelectedTask(null);
  };

  return (
    <>
      <DragDropContext onDragEnd={onDragEnd}>
        <BoardContainer>
          {columns.map(column => {
            const columnTasks = tasks.filter(task => column.taskIds.includes(task.id));
            return (
              <Column
                key={column.id}
                column={column}
                tasks={columnTasks}
                onTaskClick={handleTaskClick}
              />
            );
          })}
        </BoardContainer>
      </DragDropContext>

      {isModalOpen && selectedTask && (
        <TaskModal
          task={selectedTask}
          onClose={handleModalClose}
        />
      )}
    </>
  );
};

export default Board;
```

