### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db, collection, doc, setDoc, updateDoc, deleteDoc, onSnapshot } from '../services/firebase';

export const useTasks = (projectId) => {
  const [columns, setColumns] = useState({
    'column-1': {
      id: 'column-1',
      title: 'To Do',
      taskIds: []
    },
    'column-2': {
      id: 'column-2',
      title: 'In Progress',
      taskIds: []
    },
    'column-3': {
      id: 'column-3',
      title: 'Done',
      taskIds: []
    }
  });

  const [tasks, setTasks] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!projectId) return;

    const projectRef = doc(db, 'projects', projectId);
    const columnsRef = collection(projectRef, 'columns');
    const tasksRef = collection(projectRef, 'tasks');

    const unsubscribeColumns = onSnapshot(columnsRef, (snapshot) => {
      const newColumns = {};
      snapshot.forEach((doc) => {
        newColumns[doc.id] = doc.data();
      });
      setColumns(newColumns);
    });

    const unsubscribeTasks = onSnapshot(tasksRef, (snapshot) => {
      const newTasks = {};
      snapshot.forEach((doc) => {
        newTasks[doc.id] = doc.data();
      });
      setTasks(newTasks);
      setLoading(false);
    });

    return () => {
      unsubscribeColumns();
      unsubscribeTasks();
    };
  }, [projectId]);

  const addTask = async (columnId, task) => {
    const projectRef = doc(db, 'projects', projectId);
    const tasksRef = collection(projectRef, 'tasks');
    const columnsRef = collection(projectRef, 'columns');

    const taskDocRef = doc(tasksRef);
    await setDoc(taskDocRef, {
      ...task,
      id: taskDocRef.id,
      columnId
    });

    const columnDocRef = doc(columnsRef, columnId);
    await updateDoc(columnDocRef, {
      taskIds: [...columns[columnId].taskIds, taskDocRef.id]
    });
  };

  const updateTask = async (taskId, updates) => {
    const projectRef = doc(db, 'projects', projectId);
    const taskRef = doc(projectRef, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  const deleteTask = async (taskId, columnId) => {
    const projectRef = doc(db, 'projects', projectId);
    const taskRef = doc(projectRef, 'tasks', taskId);
    const columnRef = doc(projectRef, 'columns', columnId);

    await deleteDoc(taskRef);

    const updatedTaskIds = columns[columnId].taskIds.filter(id => id !== taskId);
    await updateDoc(columnRef, { taskIds: updatedTaskIds });
  };

  const onDragEnd = async (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const startColumn = columns[source.droppableId];
    const finishColumn = columns[destination.droppableId];

    if (startColumn === finishColumn) {
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      const projectRef = doc(db, 'projects', projectId);
      const columnRef = doc(projectRef, 'columns', newColumn.id);
      await updateDoc(columnRef, { taskIds: newTaskIds });
    } else {
      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...startColumn,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finishColumn,
        taskIds: finishTaskIds
      };

      const projectRef = doc(db, 'projects', projectId);
      const startColumnRef = doc(projectRef, 'collections', newStart.id);
      const finishColumnRef = doc(projectRef, 'collections', newFinish.id);

      await updateDoc(startColumnRef, { taskIds: newStart.taskIds });
      await updateDoc(finishColumnRef, { taskIds: newFinish.taskIds });

      // Update the task's columnId
      const taskRef = doc(projectRef, 'tasks', draggableId);
      await updateDoc(taskRef, { columnId: newFinish.id });
    }
  };

  return {
    columns,
    tasks,
    loading,
    addTask,
    updateTask,
    deleteTask,
    onDragEnd
  };
};
```

### 4. Board Component (components/Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useTasks } from '../hooks/useTasks';

const Board = ({ projectId }) => {
  const { columns, tasks, loading, addTask, updateTask, deleteTask, onDragEnd } = useTasks(projectId);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);
  const [currentColumnId, setCurrentColumnId] = useState(null);

  const handleAddTask = (columnId) => {
    setCurrentColumnId(columnId);
    setCurrentTask(null);
    setIsModalOpen(true);
  };

  const handleEditTask = (task) => {
    setCurrentTask(task);
    setCurrentColumnId(task.columnId);
    setIsModalOpen(true);
  };

  const handleSaveTask = async (taskData) => {
    if (currentTask) {
      await updateTask(currentTask.id, taskData);
    } else {
      await addTask(currentColumnId, taskData);
    }
    setIsModalOpen(false);
  };

  const handleDeleteTask = async (taskId, columnId) => {
    await deleteTask(taskId, columnId);
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="all-columns"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.values(columns).map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  tasks={tasks}
                  index={index}
                  onAddTask={handleAddTask}
                  onEditTask={handleEditTask}
                  onDeleteTask={handleDeleteTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      <TaskModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveTask}
        task={currentTask}
      />
    </div>
  );
};

export default Board;
```

