### 3. Board Component (Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import AddTaskForm from './AddTaskForm';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { user } = useAuth();
  const { documents: columns, updateDocument } = useFirestore('columns');
  const [showAddTask, setShowAddTask] = useState(false);
  const [selectedColumn, setSelectedColumn] = useState(null);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const sourceColumn = columns.find(col => col.id === source.droppableId);
    const destinationColumn = columns.find(col => col.id === destination.droppableId);

    const newSourceTasks = [...sourceColumn.tasks];
    const [removed] = newSourceTasks.splice(source.index, 1);

    if (sourceColumn.id === destinationColumn.id) {
      newSourceTasks.splice(destination.index, 0, removed);
      updateDocument(sourceColumn.id, { tasks: newSourceTasks });
    } else {
      const newDestinationTasks = [...destinationColumn.tasks];
      newDestinationTasks.splice(destination.index, 0, removed);

      updateDocument(sourceColumn.id, { tasks: newSourceTasks });
      updateDocument(destinationColumn.id, { tasks: newDestinationTasks });
    }
  };

  const handleAddTask = (columnId) => {
    setSelectedColumn(columnId);
    setShowAddTask(true);
  };

  const handleCloseForm = () => {
    setShowAddTask(false);
    setSelectedColumn(null);
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="columns-container"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns && columns.map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  index={index}
                  onAddTask={handleAddTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {showAddTask && (
        <AddTaskForm
          columnId={selectedColumn}
          onClose={handleCloseForm}
        />
      )}
    </div>
  );
};

export default Board;
```

