### 7. Firestore Hook (useFirestore.js)

```javascript
import { useState, useEffect } from 'react';
import { firestore } from '../firebase';

export const useFirestore = (collection) => {
  const [documents, setDocuments] = useState(null);
  const [error, setError] = useState(null);

  // Get all documents
  useEffect(() => {
    const unsubscribe = firestore.collection(collection)
      .orderBy('createdAt', 'desc')
      .onSnapshot(snapshot => {
        let results = [];
        snapshot.docs.forEach(doc => {
          results.push({ ...doc.data(), id: doc.id });
        });
        setDocuments(results);
        setError(null);
      }, err => {
        setError(err.message);
      });

    return () => unsubscribe();
  }, [collection]);

  // Add a document
  const addDocument = async (doc) => {
    try {
      const createdAt = new Date().toISOString();
      const addedDoc = await firestore.collection(collection).add({
        ...doc,
        createdAt
      });
      return addedDoc;
    } catch (err) {
      setError(err.message);
      return null;
    }
  };

  // Update a document
  const updateDocument = async (id, updates) => {
    try {
      await firestore.collection(collection).doc(id).update(updates);
    } catch (err) {
      setError(err.message);
    }
  };

  // Delete a document
  const deleteDocument = async (id) => {
    try {
      await firestore.collection(collection).doc(id).delete();
    } catch (err) {
      setError(err.message);
    }
  };

  return { documents, error, addDocument, updateDocument, deleteDocument };
};
