## Setup Instructions

1. Create a new React project:
```bash
npx create-react-app project-management-app
cd project-management-app
```

2. Install required dependencies:
```bash
npm install firebase react-router-dom react-beautiful-dnd
```

3. Set up Firebase:
   - Create a Firebase project at [Firebase Console](https://console.firebase.google.com/)
   - Enable Firestore database and Authentication (Google provider)
   - Copy your Firebase configuration to `firebase.js`

4. Run the application:
```bash
npm start
```

## Features Implemented

1. **Drag-and-Drop Interface**:
   - Tasks can be dragged between columns
   - Columns can be reordered
   - Visual feedback during dragging

2. **Real-time Collaboration**:
   - Firebase Firestore for real-time data synchronization
   - Automatic updates when data changes

3. **Task Management**:
   - Add new tasks to columns
   - Edit task details
   - Assign tasks to team members

4. **Authentication**:
   - Google sign-in
   - Protected routes
   - User session management

5. **Responsive Design**:
   - Works on desktop and mobile devices
   - Adaptive layout for different screen sizes

This implementation provides a solid foundation that you can extend with additional features like task comments, due dates, attachments, or more advanced user management.

# Browser-Based Project Management Application

Here's a comprehensive implementation of a project management application with drag-and-drop task boards and real-time collaboration features.

## Frontend Implementation (React + TypeScript)

```typescript
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { io, Socket } from 'socket.io-client';
import './App.css';

interface Task {
  id: string;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'done';
  assignee?: string;
  dueDate?: string;
}

interface Column {
  id: string;
  title: string;
  taskIds: string[];
}

interface User {
  id: string;
  name: string;
  color: string;
}

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Record<string, Task>>({});
  const [columns, setColumns] = useState<Record<string, Column>>({
    'column-1': {
      id: 'column-1',
      title: 'To Do',
      taskIds: [],
    },
    'column-2': {
      id: 'column-2',
      title: 'In Progress',
      taskIds: [],
    },
    'column-3': {
      id: 'column-3',
      title: 'Done',
      taskIds: [],
    },
  });
  const [columnOrder, setColumnOrder] = useState<string[]>(['column-1', 'column-2', 'column-3']);
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [socket, setSocket] = useState<Socket | null>(null);

  // Initialize socket connection
  useEffect(() => {
    const newSocket = io('http://localhost:3001');
    setSocket(newSocket);

    // Set up socket listeners
    newSocket.on('connect', () => {
      console.log('Connected to server');
      setCurrentUser({
        id: newSocket.id,
        name: `User ${Math.floor(Math.random() * 1000)}`,
        color: getRandomColor(),
      });
    });

    newSocket.on('updateTasks', (updatedTasks: Record<string, Task>) => {
      setTasks(updatedTasks);
    });

    newSocket.on('updateColumns', (updatedColumns: Record<string, Column>) => {
      setColumns(updatedColumns);
    });

    newSocket.on('updateUsers', (updatedUsers: User[]) => {
      setUsers(updatedUsers);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  // Send initial data to server when connected
  useEffect(() => {
    if (socket && currentUser) {
      socket.emit('join', currentUser);
      socket.emit('getInitialData');
    }
  }, [socket, currentUser]);

  const getRandomColor = (): string => {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
  };

  const onDragEnd = (result: any) => {
    const { destination, source, draggableId, type } = result;

    // If no destination or dropped in the same place
    if (!destination) return;

    // If dropped in the same position
    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Reordering columns
    if (type === 'column') {
      const newColumnOrder = Array.from(columnOrder);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      setColumnOrder(newColumnOrder);
      if (socket) socket.emit('updateColumns', { ...columns, columnOrder: newColumnOrder });
      return;
    }

    // Moving tasks between columns
    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      const newColumns = {
        ...columns,
        [newColumn.id]: newColumn,
      };

      setColumns(newColumns);
      if (socket) socket.emit('updateColumns', newColumns);
      return;
    }

    // Moving tasks between different columns
    const startTaskIds = Array.from(start.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStart = {
      ...start,
      taskIds: startTaskIds,
    };

    const finishTaskIds = Array.from(finish.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinish = {
      ...finish,
      taskIds: finishTaskIds,
    };

    const newColumns = {
      ...columns,
      [newStart.id]: newStart,
      [newFinish.id]: newFinish,
    };

    // Update task status
    const updatedTask = {
      ...tasks[draggableId],
      status: newFinish.id === 'column-1' ? 'todo' :
              newFinish.id === 'column-2' ? 'in-progress' : 'done',
    };

    const newTasks = {
      ...tasks,
      [draggableId]: updatedTask,
    };

    setColumns(newColumns);
    setTasks(newTasks);

    if (socket) {
      socket.emit('updateColumns', newColumns);
      socket.emit('updateTasks', newTasks);
    }
  };

  const addTask = (title: string, description: string) => {
    const newTaskId = `task-${Date.now()}`;
    const newTask: Task = {
      id: newTaskId,
      title,
      description,
      status: 'todo',
    };

    const newTasks = {
      ...tasks,
      [newTaskId]: newTask,
    };

    const newColumn = {
      ...columns['column-1'],
      taskIds: [...columns['column-1'].taskIds, newTaskId],
    };

    const newColumns = {
      ...columns,
      'column-1': newColumn,
    };

    setTasks(newTasks);
    setColumns(newColumns);

    if (socket) {
      socket.emit('updateTasks', newTasks);
      socket.emit('updateColumns', newColumns);
    }
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    const updatedTask = {
      ...tasks[taskId],
      ...updates,
    };

    const newTasks = {
      ...tasks,
      [taskId]: updatedTask,
    };

    setTasks(newTasks);
    if (socket) socket.emit('updateTasks', newTasks);
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <header className="app-header">
          <h1>Project Management Board</h1>
          <div className="user-info">
            {currentUser && (
              <span style={{ color: currentUser.color }}>
                {currentUser.name}
              </span>
            )}
            <div className="online-users">
              {users.map(user => (
                <span
                  key={user.id}
                  className="user-dot"
                  style={{ backgroundColor: user.color }}
                  title={user.name}
                />
              ))}
            </div>
          </div>
        </header>

        <div className="board">
          <TaskBoard
            columns={columns}
            tasks={tasks}
            columnOrder={columnOrder}
            onDragEnd={onDragEnd}
            addTask={addTask}
            updateTask={updateTask}
            users={users}
            currentUser={currentUser}
          />
        </div>
      </div>
    </DndProvider>
  );
};

interface TaskBoardProps {
  columns: Record<string, Column>;
  tasks: Record<string, Task>;
  columnOrder: string[];
  onDragEnd: (result: any) => void;
  addTask: (title: string, description: string) => void;
  updateTask: (taskId: string, updates: Partial<Task>) => void;
  users: User[];
  currentUser: User | null;
}

const TaskBoard: React.FC<TaskBoardProps> = ({
  columns,
  tasks,
  columnOrder,
  onDragEnd,
  addTask,
  updateTask,
  users,
  currentUser,
}) => {
  const [showAddTask, setShowAddTask] = useState(false);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');

  const handleAddTask = () => {
    if (newTaskTitle.trim()) {
      addTask(newTaskTitle, newTaskDescription);
      setNewTaskTitle('');
      setNewTaskDescription('');
      setShowAddTask(false);
    }
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <Droppable droppableId="all-columns" direction="horizontal" type="column">
        {(provided) => (
          <div
            className="columns-container"
            {...provided.droppableProps}
            ref={provided.innerRef}
          >
            {columnOrder.map((columnId, index) => {
              const column = columns[columnId];
              const tasksForColumn = column.taskIds.map(taskId => tasks[taskId]);

              return (
                <Draggable key={column.id} draggableId={column.id} index={index}>
                  {(provided) => (
                    <div
                      className="column"
                      ref={provided.innerRef}
                      {...provided.draggableProps}
                    >
                      <div className="column-header" {...provided.dragHandleProps}>
                        <h3>{column.title}</h3>
                        <span className="task-count">{tasksForColumn.length}</span>
                      </div>

                      <Droppable droppableId={column.id} type="task">
                        {(provided) => (
                          <div
                            className="tasks-container"
                            ref={provided.innerRef}
                            {...provided.droppableProps}
                          >
                            {tasksForColumn.map((task, index) => (
                              <Draggable key={task.id} draggableId={task.id} index={index}>
                                {(provided) => (
                                  <div
                                    className="task"
                                    ref={provided.innerRef}
                                    {...provided.draggableProps}
                                    {...provided.dragHandleProps}
                                  >
                                    <TaskCard
                                      task={task}
                                      updateTask={updateTask}
                                      users={users}
                                      currentUser={currentUser}
                                    />
                                  </div>
                                )}
                              </Draggable>
                            ))}
                            {provided.placeholder}
                          </div>
                        )}
                      </Droppable>

                      {column.id === 'column-1' && (
                        <div className="add-task-section">
                          {showAddTask ? (
                            <div className="add-task-form">
                              <input
                                type="text"
                                placeholder="Task title"
                                value={newTaskTitle}
                                onChange={(e) => setNewTaskTitle(e.target.value)}
                              />
                              <textarea
                                placeholder="Task description"
                                value={newTaskDescription}
                                onChange={(e) => setNewTaskDescription(e.target.value)}
                              />
                              <div className="form-actions">
                                <button onClick={handleAddTask}>Add Task</button>
                                <button onClick={() => setShowAddTask(false)}>Cancel</button>
                              </div>
                            </div>
                          ) : (
                            <button
                              className="add-task-button"
                              onClick={() => setShowAddTask(true)}
                            >
                              + Add Task
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </Draggable>
              );
            })}
            {provided.placeholder}
          </div>
        )}
      </Droppable>
    </DragDropContext>
  );
};

interface TaskCardProps {
  task: Task;
  updateTask: (taskId: string, updates: Partial<Task>) => void;
  users: User[];
  currentUser: User | null;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, updateTask, users, currentUser }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const [editedDescription, setEditedDescription] = useState(task.description);
  const [selectedAssignee, setSelectedAssignee] = useState(task.assignee || '');
  const [dueDate, setDueDate] = useState(task.dueDate || '');

  const handleSave = () => {
    updateTask(task.id, {
      title: editedTitle,
      description: editedDescription,
      assignee: selectedAssignee,
      dueDate: dueDate,
    });
    setIsEditing(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'todo': return '#ff9f89';
      case 'in-progress': return '#f9f871';
      case 'done': return '#8aff87';
      default: return '#ffffff';
    }
  };

  const getAssigneeColor = (userId: string) => {
    const user = users.find(u => u.id === userId);
    return user ? user.color : '#cccccc';
  };

  return (
    <div className="task-card">
      <div className="task-status" style={{ backgroundColor: getStatusColor(task.status) }}></div>

      {isEditing ? (
        <div className="task-edit-form">
          <input
            type="text"
            value={editedTitle}
            onChange={(e) => setEditedTitle(e.target.value)}
          />
          <textarea
            value={editedDescription}
            onChange={(e) => setEditedDescription(e.target.value)}
          />
          <div className="task-meta">
            <select
              value={selectedAssignee}
              onChange={(e) => setSelectedAssignee(e.target.value)}
            >
              <option value="">Unassigned</option>
              {users.map(user => (
                <option key={user.id} value={user.id}>
                  {user.name}
                </option>
              ))}
            </select>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>
          <div className="task-actions">
            <button onClick={handleSave}>Save</button>
            <button onClick={() => setIsEditing(false)}>Cancel</button>
          </div>
        </div>
      ) : (
        <>
          <h4>{task.title}</h4>
          <p>{task.description}</p>
          <div className="task-meta">
            {task.assignee && (
              <div className="assignee" style={{ backgroundColor: getAssigneeColor(task.assignee) }}>
                {users.find(u => u.id === task.assignee)?.name || 'Unknown'}
              </div>
            )}
            {task.dueDate && (
              <div className="due-date">
                Due: {new Date(task.dueDate).toLocaleDateString()}
              </div>
            )}
          </div>
          <button className="edit-button" onClick={() => setIsEditing(true)}>Edit</button>
        </>
      )}
    </div>
  );
};

export default App;
```

## Backend Implementation (Node.js + Socket.io)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// In-memory data store
let tasks = {};
let columns = {
  'column-1': {
    id: 'column-1',
    title: 'To Do',
    taskIds: [],
  },
  'column-2': {
    id: 'column-2',
    title: 'In Progress',
    taskIds: [],
  },
  'column-3': {
    id: 'column-3',
    title: 'Done',
    taskIds: [],
  },
};
let users = [];

io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (user) => {
    users.push(user);
    io.emit('updateUsers', users);
  });

  socket.on('getInitialData', () => {
    socket.emit('updateTasks', tasks);
    socket.emit('updateColumns', columns);
    socket.emit('updateUsers', users);
  });

  socket.on('updateTasks', (updatedTasks) => {
    tasks = updatedTasks;
    socket.broadcast.emit('updateTasks', tasks);
  });

  socket.on('updateColumns', (updatedColumns) => {
    columns = updatedColumns;
    socket.broadcast.emit('updateColumns', columns);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
    users = users.filter(user => user.id !== socket.id);
    io.emit('updateUsers', users);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

