### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from "react";
import { DragDropContext, Droppable } from "react-beautiful-dnd";
import Column from "./Column";
import { db } from "../firebase/firebase";
import {
  collection,
  doc,
  updateDoc,
  arrayUnion,
  arrayRemove,
  onSnapshot,
} from "firebase/firestore";
import { useAuth } from "../context/AuthContext";

const Board = () => {
  const { currentUser } = useAuth();
  const [columns, setColumns] = useState({
    "column-1": {
      id: "column-1",
      title: "To Do",
      taskIds: [],
    },
    "column-2": {
      id: "column-2",
      title: "In Progress",
      taskIds: [],
    },
    "column-3": {
      id: "column-3",
      title: "Done",
      taskIds: [],
    },
  });

  useEffect(() => {
    if (!currentUser) return;

    const unsubscribe = onSnapshot(
      collection(db, "boards"),
      (snapshot) => {
        const boardData = snapshot.docs.find(
          (doc) => doc.id === currentUser.uid
        );
        if (boardData) {
          setColumns(boardData.data().columns);
        }
      }
    );

    return () => unsubscribe();
  }, [currentUser]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      setColumns({
        ...columns,
        [newColumn.id]: newColumn,
      });

      // Update in Firestore
      updateColumnInFirestore(newColumn);
    } else {
      // Moving to different column
      const startTaskIds = Array.from(start.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...start,
        taskIds: startTaskIds,
      };

      const finishTaskIds = Array.from(finish.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finish,
        taskIds: finishTaskIds,
      };

      setColumns({
        ...columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish,
      });

      // Update both columns in Firestore
      updateColumnInFirestore(newStart);
      updateColumnInFirestore(newFinish);
    }
  };

  const updateColumnInFirestore = async (column) => {
    if (!currentUser) return;

    const boardRef = doc(db, "boards", currentUser.uid);
    await updateDoc(boardRef, {
      [`columns.${column.id}`]: column,
    });
  };

  const addNewTask = async (columnId, taskContent) => {
    if (!currentUser) return;

    const taskId = Date.now().toString();
    const newTask = {
      id: taskId,
      content: taskContent,
      createdAt: new Date(),
    };

    // Add task to tasks collection
    await updateDoc(doc(db, "tasks", taskId), newTask);

    // Add task reference to column
    const boardRef = doc(db, "boards", currentUser.uid);
    await updateDoc(boardRef, {
      [`columns.${columnId}.taskIds`]: arrayUnion(taskId),
    });
  };

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="all-columns"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.values(columns).map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  index={index}
                  addNewTask={addNewTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

### 6. Column Component (components/Column.jsx)

```javascript
import React, { useState } from "react";
import { Droppable, Draggable } from "react-beautiful-dnd";
import Task from "./Task";
import TaskModal from "./TaskModal";

const Column = ({ column, index, addNewTask }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newTaskContent, setNewTaskContent] = useState("");

  const handleAddTask = () => {
    if (newTaskContent.trim()) {
      addNewTask(column.id, newTaskContent);
      setNewTaskContent("");
      setIsModalOpen(false);
    }
  };

  return (
    <Draggable draggableId={column.id} index={index}>
      {(provided) => (
        <div
          className="column"
          {...provided.draggableProps}
          ref={provided.innerRef}
        >
          <h3 {...provided.dragHandleProps}>{column.title}</h3>
          <Droppable droppableId={column.id} type="task">
            {(provided) => (
              <div
                className="task-list"
                ref={provided.innerRef}
                {...provided.droppableProps}
              >
                {column.taskIds.map((taskId, index) => (
                  <Task key={taskId} taskId={taskId} index={index} />
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
          <button
            className="add-task-btn"
            onClick={() => setIsModalOpen(true)}
          >
            + Add Task
          </button>

          <TaskModal
            isOpen={isModalOpen}
            onClose={() => setIsModalOpen(false)}
            onSubmit={handleAddTask}
            value={newTaskContent}
            onChange={(e) => setNewTaskContent(e.target.value)}
          />
        </div>
      )}
    </Draggable>
  );
};

export default Column;
```

