### 3. Firestore Hook (hooks/useFirestore.js)

```javascript
import { useEffect, useState } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  doc,
  onSnapshot,
  addDoc,
  updateDoc,
  deleteDoc,
  query,
  orderBy
} from 'firebase/firestore';

export const useFirestore = (collectionName) => {
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const q = query(collection(db, collectionName), orderBy('createdAt'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const documents = [];
      querySnapshot.forEach((doc) => {
        documents.push({ ...doc.data(), id: doc.id });
      });
      setDocs(documents);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [collectionName]);

  const addDocument = async (document) => {
    try {
      const docRef = await addDoc(collection(db, collectionName), {
        ...document,
        createdAt: new Date()
      });
      return docRef.id;
    } catch (error) {
      console.error("Error adding document: ", error);
    }
  };

  const updateDocument = async (id, updates) => {
    try {
      const docRef = doc(db, collectionName, id);
      await updateDoc(docRef, updates);
    } catch (error) {
      console.error("Error updating document: ", error);
    }
  };

  const deleteDocument = async (id) => {
    try {
      const docRef = doc(db, collectionName, id);
      await deleteDoc(docRef);
    } catch (error) {
      console.error("Error deleting document: ", error);
    }
  };

  return { docs, loading, addDocument, updateDocument, deleteDocument };
};
```

### 4. Main Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { user } = useAuth();
  const { docs: columns, loading, updateDocument } = useFirestore('columns');
  const { docs: tasks, addDocument: addTask } = useFirestore('tasks');
  const [newColumnName, setNewColumnName] = useState('');

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === 'column') {
      // Reorder columns
      const newColumnOrder = Array.from(columns);
      const [removed] = newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, removed);

      // Update column order in Firestore
      newColumnOrder.forEach((column, index) => {
        updateDocument(column.id, { order: index });
      });
    } else {
      // Move task between columns
      const startColumn = columns.find(col => col.id === source.droppableId);
      const finishColumn = columns.find(col => col.id === destination.droppableId);

      if (startColumn === finishColumn) {
        // Reorder tasks within the same column
        const newTaskIds = Array.from(startColumn.taskIds);
        newTaskIds.splice(source.index, 1);
        newTaskIds.splice(destination.index, 0, draggableId);

        updateDocument(startColumn.id, { taskIds: newTaskIds });
      } else {
        // Move task to another column
        const startTaskIds = Array.from(startColumn.taskIds);
        startTaskIds.splice(source.index, 1);
        const newStart = {
          ...startColumn,
          taskIds: startTaskIds
        };

        const finishTaskIds = Array.from(finishColumn.taskIds);
        finishTaskIds.splice(destination.index, 0, draggableId);
        const newFinish = {
          ...finishColumn,
          taskIds: finishTaskIds
        };

        updateDocument(newStart.id, { taskIds: newStart.taskIds });
        updateDocument(newFinish.id, { taskIds: newFinish.taskIds });

        // Update task's columnId
        updateDocument(draggableId, { columnId: finishColumn.id });
      }
    }
  };

  const handleAddColumn = async () => {
    if (newColumnName.trim()) {
      await addDocument({
        title: newColumnName,
        taskIds: [],
        order: columns.length,
        createdBy: user.uid
      });
      setNewColumnName('');
    }
  };

  const handleAddTask = async (columnId) => {
    const taskId = await addTask({
      title: 'New Task',
      description: '',
      columnId,
      createdBy: user.uid,
      assignees: []
    });

    const column = columns.find(col => col.id === columnId);
    const newTaskIds = [...column.taskIds, taskId];
    updateDocument(columnId, { taskIds: newTaskIds });
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="columns-container"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns
                .sort((a, b) => a.order - b.order)
                .map((column, index) => (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={tasks.filter(task => task.columnId === column.id)}
                    index={index}
                    onAddTask={handleAddTask}
                  />
                ))}
              {provided.placeholder}

              <div className="add-column">
                <input
                  type="text"
                  value={newColumnName}
                  onChange={(e) => setNewColumnName(e.targetValue)}
                  placeholder="New column name"
                />
                <button onClick={handleAddColumn}>Add Column</button>
              </div>
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

