```javascript
import React, { useState, useEffect } from 'react';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const TaskModal = ({ task, onClose }) => {
  const { user } = useAuth();
  const { updateDocument, deleteDocument } = useFirestore('tasks');
  const [title, setTitle] = useState(task.title);
  const [description, setDescription] = useState(task.description || '');
  const [assignees, setAssignees] = useState(task.assignees || []);
  const [users, setUsers] = useState([]);

  useEffect(() => {
    // Fetch all users for assignee selection
    const fetchUsers = async () => {
      // In a real app, you would fetch from your users collection
      // This is a simplified example
      const mockUsers = [
        { id: '1', name: 'John Doe', email: 'john@example.com' },
        { id: '2', name: 'Jane Smith', email: 'jane@example.com' }
      ];
      setUsers(mockUsers);
    };

    fetchUsers();
  }, []);

  const handleSave = () => {
    updateDocument(task.id, {
      title,
      description,
      assignees
    });
    onClose();
  };

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      deleteDocument(task.id);
      onClose();
    }
  };

  const handleAssigneeChange = (userId) => {
    const user = users.find(u => u.id === userId);
    if (user) {
      setAssignees(prev => {
        if (prev.some(a => a.id === userId)) {
          return prev.filter(a => a.id !== userId);
        } else {
          return [...prev, user];
        }
      });
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal">
        <div className="modal-header">
          <h2>Edit Task</h2>
          <button onClick={onClose} className="close-btn">×</button>
        </div>

        <div className="modal-body">
          <div className="form-group">
            <label>Title</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label>Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label>Assignees</label>
            <div className="assignee-selector">
              {users.map(user => (
                <label key={user.id} className="assignee-option">
                  <input
                    type="checkbox"
                    checked={assignees.some(a => a.id === user.id)}
                    onChange={() => handleAssigneeChange(user.id)}
                  />
                  {user.name}
                </label>
              ))}
            </div>
          </div>
        </div>

        <div className="modal-footer">
          <button onClick={handleDelete} className="delete-btn">Delete Task</button>
          <button onClick={handleSave} className="save-btn">Save Changes</button>
        </div>
      </div>
    </div>
  );
};

export default TaskModal;
