### 3. Task Hook (useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase';
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
  deleteDoc
} from 'firebase/firestore';

export function useTasks(projectId) {
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    if (!projectId) return;

    const q = query(
      collection(db, 'tasks'),
      where('projectId', '==', projectId)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
    });

    return () => unsubscribe();
  }, [projectId]);

  const addTask = async (task) => {
    await addDoc(collection(db, 'tasks'), task);
  };

  const updateTask = async (taskId, updates) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, 'tasks', taskId));
  };

  return { tasks, addTask, updateTask, deleteTask };
}
```

### 4. Board Component (Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from '../TaskModal';
import { useTasks } from '../../hooks/useTasks';

const initialColumns = [
  { id: 'todo', title: 'To Do' },
  { id: 'in-progress', title: 'In Progress' },
  { id: 'done', title: 'Done' },
];

export default function Board({ projectId }) {
  const { tasks, addTask, updateTask, deleteTask } = useTasks(projectId);
  const [columns, setColumns] = useState(initialColumns);
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Update task status in database
    updateTask(draggableId, { status: destination.droppableId });
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (status) => {
    setSelectedTask({
      title: '',
      description: '',
      status,
      projectId,
      createdAt: new Date().toISOString(),
    });
    setIsModalOpen(true);
  };

  const handleSaveTask = async (task) => {
    if (task.id) {
      await updateTask(task.id, task);
    } else {
      await addTask(task);
    }
    setIsModalOpen(false);
  };

  const handleDeleteTask = async () => {
    if (selectedTask.id) {
      await deleteTask(selectedTask.id);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter((task) => task.status === column.id)}
              onTaskClick={handleTaskClick}
              onAddTask={handleAddTask}
            />
          ))}
        </div>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onSave={handleSaveTask}
          onDelete={handleDeleteTask}
          onClose={() => setIsModalOpen(false)}
        />
      )}
    </div>
  );
}
```

