### 4. Board Component (components/Board/Board.js)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { db } from '../../firebase/firebase';
import { collection, query, where, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { useAuth } from '../../context/AuthContext';
import '../../styles/Board.css';

const Board = () => {
  const { currentUser } = useAuth();
  const [columns, setColumns] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!currentUser) return;

    const q = query(
      collection(db, 'boards'),
      where('userId', '==', currentUser.uid)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const boardData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      if (boardData.length > 0) {
        setColumns(boardData[0].columns || []);
      } else {
        // Initialize with default columns if no board exists
        const defaultColumns = [
          { id: 'todo', title: 'To Do', taskIds: [] },
          { id: 'in-progress', title: 'In Progress', taskIds: [] },
          { id: 'done', title: 'Done', taskIds: [] }
        ];
        setColumns(defaultColumns);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [currentUser]);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId, type } = result;

    // If no destination or dropped in the same place
    if (!destination) return;
    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) return;

    // Reordering columns
    if (type === 'column') {
      const newColumnOrder = Array.from(columns);
      const [removed] = newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, removed);

      setColumns(newColumnOrder);
      await updateBoard(newColumnOrder);
      return;
    }

    // Moving tasks between columns
    const startColumn = columns.find(col => col.id === source.droppableId);
    const finishColumn = columns.find(col => col.id === destination.droppableId);

    if (startColumn === finishColumn) {
      // Reordering within the same column
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      const newColumns = columns.map(col =>
        col.id === newColumn.id ? newColumn : col
      );

      setColumns(newColumns);
      await updateBoard(newColumns);
    } else {
      // Moving to a different column
      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStartColumn = {
        ...startColumn,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinishColumn = {
        ...finishColumn,
        taskIds: finishTaskIds
      };

      const newColumns = columns.map(col => {
        if (col.id === newStartColumn.id) return newStartColumn;
        if (col.id === newFinishColumn.id) return newFinishColumn;
        return col;
      });

      setColumns(newColumns);
      await updateBoard(newColumns);
    }
  };

  const updateBoard = async (newColumns) => {
    if (!currentUser) return;

    const q = query(
      collection(db, 'boards'),
      where('userId', '==', currentUser.uid)
    );

    const querySnapshot = await getDocs(q);

    if (querySnapshot.empty) {
      // Create new board if it doesn't exist
      await addDoc(collection(db, 'boards'), {
        userId: currentUser.uid,
        columns: newColumns,
        createdAt: new Date()
      });
    } else {
      // Update existing board
      const boardDoc = querySnapshot.docs[0];
      await updateDoc(doc(db, 'boards', boardDoc.id), {
        columns: newColumns
      });
    }
  };

  if (loading) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <Droppable droppableId="all-columns" direction="horizontal" type="column">
        {(provided) => (
          <div
            className="board"
            {...provided.droppableProps}
            ref={provided.innerRef}
          >
            {columns.map((column, index) => (
              <Column
                key={column.id}
                column={column}
                index={index}
                tasks={column.taskIds.map(taskId => ({
                  id: taskId,
                  content: `Task ${taskId}`
                }))}
              />
            ))}
            {provided.placeholder}
          </div>
        )}
      </Droppable>
    </DragDropContext>
  );
};

export default Board;
```

