```javascript
import React, { createContext, useContext, useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import { collection, query, onSnapshot, doc, updateDoc, addDoc, deleteDoc } from 'firebase/firestore';

const ProjectContext = createContext();

export const ProjectProvider = ({ children }) => {
  const [boards, setBoards] = useState([]);
  const [currentBoard, setCurrentBoard] = useState(null);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch boards and listen for real-time updates
  useEffect(() => {
    const q = query(collection(db, 'boards'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const boardsData = [];
      querySnapshot.forEach((doc) => {
        boardsData.push({ id: doc.id, ...doc.data() });
      });
      setBoards(boardsData);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // Fetch users
  useEffect(() => {
    const q = query(collection(db, 'users'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const usersData = [];
      querySnapshot.forEach((doc) => {
        usersData.push({ id: doc.id, ...doc.data() });
      });
      setUsers(usersData);
    });

    return () => unsubscribe();
  }, []);

  // Create a new board
  const createBoard = async (boardData) => {
    const docRef = await addDoc(collection(db, 'boards'), boardData);
    return docRef.id;
  };

  // Update board
  const updateBoard = async (boardId, updates) => {
    await updateDoc(doc(db, 'boards', boardId), updates);
  };

  // Delete board
  const deleteBoard = async (boardId) => {
    await deleteDoc(doc(db, 'boards', boardId));
  };

  // Create a new task
  const createTask = async (boardId, columnId, taskData) => {
    const boardRef = doc(db, 'boards', boardId);
    const columnRef = doc(boardRef, 'columns', columnId);
    const tasksRef = collection(columnRef, 'tasks');
    const docRef = await addDoc(tasksRef, taskData);
    return docRef.id;
  };

  // Update task
  const updateTask = async (boardId, columnId, taskId, updates) => {
    const taskRef = doc(db, 'boards', boardId, 'columns', columnId, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  // Delete task
  const deleteTask = async (boardId, columnId, taskId) => {
    const taskRef = doc(db, 'boards', boardId, 'columns', columnId, 'tasks', taskId);
    await deleteDoc(taskRef);
  };

  // Move task between columns
  const moveTask = async (boardId, sourceColumnId, destinationColumnId, taskId, newIndex) => {
    // Get the task data
    const sourceTaskRef = doc(db, 'boards', boardId, 'columns', sourceColumnId, 'tasks', taskId);
    const taskDoc = await getDoc(sourceTaskRef);
    const taskData = taskDoc.data();

    // Delete from source
    await deleteDoc(sourceTaskRef);

    // Add to destination at new position
    const destinationColumnRef = doc(db, 'boards', boardId, 'columns', destinationColumnId);
    const tasksRef = collection(destinationColumnRef, 'tasks');
    await addDoc(tasksRef, { ...taskData, position: newIndex });
  };

  return (
    <ProjectContext.Provider
      value={{
        boards,
        currentBoard,
        setCurrentBoard,
        users,
        loading,
        createBoard,
        updateBoard,
        deleteBoard,
        createTask,
        updateTask,
        deleteTask,
        moveTask
      }}
    >
      {children}
    </ProjectContext.Provider>
  );
};

export const useProject = () => useContext(ProjectContext);
```

### 3. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useProject } from '../context/ProjectContext';
import { db } from '../firebase/firebase';
import { doc, updateDoc } from 'firebase/firestore';

const Board = () => {
  const { currentBoard, updateBoard, moveTask } = useProject();
  const [columns, setColumns] = useState([]);

  useEffect(() => {
    if (currentBoard) {
      setColumns(currentBoard.columns || []);
    }
  }, [currentBoard]);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId, type } = result;

    // If no destination or moved to same position, do nothing
    if (!destination ||
        (destination.droppableId === source.droppableId &&
         destination.index === source.index)) {
      return;
    }

    // Handle column reordering
    if (type === 'column') {
      const newColumnOrder = Array.from(columns);
      const [removed] = newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, removed);

      // Update board with new column order
      await updateBoard(currentBoard.id, {
        columns: newColumnOrder
      });

      return;
    }

    // Handle task reordering
    if (type === 'task') {
      await moveTask(
        currentBoard.id,
        source.droppableId,
        destination.droppableId,
        draggableId,
        destination.index
      );
    }
  };

  if (!currentBoard) {
    return <div className="board-empty">Select a board to get started</div>;
  }

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="board-columns"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns.map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  index={index}
                  boardId={currentBoard.id}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

### 4. Column Component (components/Column.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { Draggable, Droppable } from 'react-beautiful-dnd';
import Task from './Task';
import TaskForm from './TaskForm';
import { useProject } from '../context/ProjectContext';
import { db } from '../firebase/firebase';
import { collection, query, onSnapshot, orderBy } from 'firebase/firestore';

const Column = ({ column, index, boardId }) => {
  const [tasks, setTasks] = useState([]);
  const [isAddingTask, setIsAddingTask] = useState(false);
  const { createTask } = useProject();

  useEffect(() => {
    const q = query(
      collection(db, 'boards', boardId, 'columns', column.id, 'tasks'),
      orderBy('position')
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
    });

    return () => unsubscribe();
  }, [boardId, column.id]);

  const handleAddTask = async (taskData) => {
    await createTask(boardId, column.id, {
      ...taskData,
      position: tasks.length,
      createdAt: new Date().toISOString()
    });
    setIsAddingTask(false);
  };

  return (
    <Draggable draggableId={column.id} index={index}>
      {(provided) => (
        <div
          className="column"
          {...provided.draggableProps}
          ref={provided.innerRef}
        >
          <div className="column-header" {...provided.dragHandleProps}>
            <h3>{column.title}</h3>
          </div>

          <Droppable droppableId={column.id} type="task">
            {(provided) => (
              <div
                className="column-tasks"
                {...provided.droppableProps}
                ref={provided.innerRef}
              >
                {tasks.map((task, index) => (
                  <Task
                    key={task.id}
                    task={task}
                    index={index}
                    boardId={boardId}
                    columnId={column.id}
                  />
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>

          <div className="column-footer">
            {isAddingTask ? (
              <TaskForm
                onSubmit={handleAddTask}
                onCancel={() => setIsAddingTask(false)}
              />
            ) : (
              <button
                className="add-task-btn"
                onClick={() => setIsAddingTask(true)}
              >
                + Add Task
              </button>
            )}
          </div>
        </div>
      )}
    </Draggable>
  );
};

export default Column;
```

### 5. Task Component (components/Task.jsx)

```javascript
import React, { useState } from 'react';
import { Draggable } from 'react-beautiful-dnd';
import { useProject } from '../context/ProjectContext';

const Task = ({ task, index, boardId, columnId }) => {
  const [isEditing, setIsEditing] = useState(false);
  const { updateTask, deleteTask, users } = useProject();

  const handleUpdate = async (updates) => {
    await updateTask(boardId, columnId, task.id, updates);
    setIsEditing(false);
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      await deleteTask(boardId, columnId, task.id);
    }
  };

  const getUserName = (userId) => {
    const user = users.find(u => u.id === userId);
    return user ? user.name : 'Unassigned';
  };

  return (
    <Draggable draggableId={task.id} index={index}>
      {(provided) => (
        <div
          className="task"
          ref={provided.innerRef}
          {...provided.draggableProps}
          {...provided.dragHandleProps}
        >
          {isEditing ? (
            <div className="task-edit-form">
              <input
                type="text"
                defaultValue={task.title}
                onBlur={(e) => handleUpdate({ title: e.target.value })}
                autoFocus
              />
              <textarea
                defaultValue={task.description}
                onBlur={(e) => handleUpdate({ description: e.target.value })}
              />
              <button onClick={() => setIsEditing(false)}>Cancel</button>
            </div>
          ) : (
            <div className="task-content" onClick={() => setIsEditing(true)}>
              <h4>{task.title}</h4>
              <p>{task.description}</p>
              {task.assignee && (
                <div className="task-assignee">
                  Assigned to: {getUserName(task.assignee)}
                </div>
              )}
              <div className="task-actions">
                <button onClick={handleDelete}>Delete</button>
              </div>
            </div>
          )}
        </div>
      )}
    </Draggable>
  );
};

export default Task;
```

