### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
  deleteDoc
} from 'firebase/firestore';

export function useTasks(userId) {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!userId) return;

    const q = query(collection(db, 'tasks'), where('userId', '==', userId));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
      setLoading(false);
    });

    return unsubscribe;
  }, [userId]);

  const addTask = async (task) => {
    await addDoc(collection(db, 'tasks'), {
      ...task,
      userId,
      createdAt: new Date().toISOString()
    });
  };

  const updateTask = async (taskId, updates) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, 'tasks', taskId));
  };

  return { tasks, loading, addTask, updateTask, deleteTask };
}
```

### 4. Board Component (components/Board/Board.js)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useTasks } from '../../hooks/useTasks';
import { useAuth } from '../../context/AuthContext';
import TaskModal from '../TaskModal';

const Board = () => {
  const { currentUser } = useAuth();
  const { tasks, loading, addTask, updateTask, deleteTask } = useTasks(currentUser?.uid);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);

  const columns = [
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
  ];

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const task = tasks.find(t => t.id === draggableId);
    if (task) {
      updateTask(draggableId, { status: destination.droppableId });
    }
  };

  const handleTaskClick = (task) => {
    setCurrentTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (status) => {
    setCurrentTask({ status });
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskData) => {
    if (currentTask.id) {
      updateTask(currentTask.id, taskData);
    } else {
      addTask(taskData);
    }
    setIsModalOpen(false);
  };

  const handleDeleteTask = () => {
    if (currentTask.id) {
      deleteTask(currentTask.id);
    }
    setIsModalOpen(false);
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.status === column.id)}
              onTaskClick={handleTaskClick}
              onAddTask={handleAddTask}
            />
          ))}
        </div>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={currentTask}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveTask}
          onDelete={handleDeleteTask}
        />
      )}
    </div>
  );
};

export default Board;
```

