### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { db } from '../firebase/config';
import { useAuth } from '../context/AuthContext';
import '../styles/styles.css';

const Board = () => {
  const [columns, setColumns] = useState([]);
  const [selectedTask, setSelectedTask] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const { currentUser } = useAuth();

  useEffect(() => {
    const unsubscribe = db.collection('boards')
      .doc(currentUser.uid)
      .collection('columns')
      .orderBy('order')
      .onSnapshot(snapshot => {
        const cols = [];
        snapshot.forEach(doc => {
          cols.push({ id: doc.id, ...doc.data() });
        });
        setColumns(cols);
      });

    return () => unsubscribe();
  }, [currentUser.uid]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (type === 'column') {
      const newColumns = Array.from(columns);
      const [removed] = newColumns.splice(source.index, 1);
      newColumns.splice(destination.index, 0, removed);

      // Update order in Firestore
      newColumns.forEach((col, index) => {
        db.collection('boards')
          .doc(currentUser.uid)
          .collection('columns')
          .doc(col.id)
          .update({ order: index });
      });

      return;
    }

    if (source.droppableId === destination.droppableId) {
      // Reorder tasks in the same column
      const column = columns.find(col => col.id === source.droppableId);
      const newTasks = Array.from(column.tasks);
      const [removed] = newTasks.splice(source.index, 1);
      newTasks.splice(destination.index, 0, removed);

      const newColumns = columns.map(col => {
        if (col.id === source.droppableId) {
          return { ...col, tasks: newTasks };
        }
        return col;
      });

      // Update tasks in Firestore
      db.collection('boards')
        .doc(currentUser.uid)
        .collection('columns')
        .doc(column.id)
        .update({ tasks: newTasks });

      setColumns(newColumns);
    } else {
      // Move task to another column
      const sourceColumn = columns.find(col => col.id === source.droppableId);
      const destColumn = columns.find(col => col.id === destination.droppableId);

      const sourceTasks = Array.from(sourceColumn.tasks);
      const [removed] = sourceTasks.splice(source.index, 1);

      const destTasks = Array.from(destColumn.tasks);
      destTasks.splice(destination.index, 0, removed);

      const newColumns = columns.map(col => {
        if (col.id === source.droppableId) {
          return { ...col, tasks: sourceTasks };
        }
        if (col.id === destination.droppableId) {
          return { ...col, tasks: destTasks };
        }
        return col;
      });

      // Update both columns in Firestore
      db.collection('boards')
        .doc(currentUser.uid)
        .collection('columns')
        .doc(sourceColumn.id)
        .update({ tasks: sourceTasks });

      db.collection('boards')
        .doc(currentUser.uid)
        .collection('columns')
        .doc(destColumn.id)
        .update({ tasks: destTasks });

      setColumns(newColumns);
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setShowModal(true);
  };

  const handleAddTask = (columnId) => {
    const newTask = {
      id: `task-${Date.now()}`,
      title: 'New Task',
      description: '',
      assignee: currentUser.email,
      status: 'todo',
      createdAt: new Date().toISOString()
    };

    const column = columns.find(col => col.id === columnId);
    const newTasks = [...column.tasks, newTask];

    db.collection('boards')
      .doc(currentUser.uid)
      .collection('columns')
      .doc(columnId)
      .update({ tasks: newTasks });

    setSelectedTask(newTask);
    setShowModal(true);
  };

  const handleSaveTask = (updatedTask) => {
    const column = columns.find(col => col.tasks.some(task => task.id === updatedTask.id));
    const newTasks = column.tasks.map(task =>
      task.id === updatedTask.id ? updatedTask : task
    );

    db.collection('boards')
      .doc(currentUser.uid)
      .collection('columns')
      .doc(column.id)
      .update({ tasks: newTasks });

    setShowModal(false);
  };

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns.map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  index={index}
                  onTaskClick={handleTaskClick}
                  onAddTask={handleAddTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {showModal && (
        <TaskModal
          task={selectedTask}
          onClose={() => setShowModal(false)}
          onSave={handleSaveTask}
        />
      )}
    </div>
  );
};

export default Board;
```

