### 3. Board Component with Drag-and-Drop (`Board.js`)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { useBoard } from '../../context/BoardContext';
import Task from '../Task/Task';
import TaskForm from '../Task/TaskForm';
import './Board.css';

const Board = () => {
  const { boards, columns, tasks, moveTask, addTask, updateTask, deleteTask } = useBoard();
  const [selectedBoard, setSelectedBoard] = useState(null);
  const [isAddingTask, setIsAddingTask] = useState(false);

  useEffect(() => {
    if (boards.length > 0 && !selectedBoard) {
      setSelectedBoard(boards[0].id);
    }
  }, [boards, selectedBoard]);

  const handleDragEnd = (result) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId !== destination.droppableId) {
      moveTask(
        result.draggableId,
        source.droppableId,
        destination.droppableId,
        destination.index
      );
    }
  };

  const handleAddTask = (taskData) => {
    addTask(selectedBoard, taskData);
    setIsAddingTask(false);
  };

  if (!selectedBoard) return <div>Loading...</div>;

  return (
    <div className="board-container">
      <div className="board-header">
        <h1>Project Management Board</h1>
        <select
          value={selectedBoard}
          onChange={(e) => setSelectedBoard(e.target.value)}
        >
          {boards.map(board => (
            <option key={board.id} value={board.id}>
              {board.name}
            </option>
          ))}
        </select>
        <button onClick={() => setIsAddingTask(true)}>Add Task</button>
      </div>

      {isAddingTask && (
        <TaskForm
          onSubmit={handleAddTask}
          onCancel={() => setIsAddingTask(false)}
        />
      )}

      <DragDropContext onDragEnd={handleDragEnd}>
        <div className="board-columns">
          {columns.map(column => (
            <Droppable key={column.id} droppableId={column.id}>
              {(provided) => (
                <div
                  className="column"
                  {...provided.droppableProps}
                  ref={provided.innerRef}
                >
                  <h3>{column.title}</h3>
                  {tasks
                    .filter(task => task.boardId === selectedBoard && task.columnId === column.id)
                    .map((task, index) => (
                      <Draggable key={task.id} draggableId={task.id} index={index}>
                        {(provided) => (
                          <div
                            ref={provided.innerRef}
                            {...provided.draggableProps}
                            {...provided.dragHandleProps}
                          >
                            <Task
                              task={task}
                              onUpdate={updateTask}
                              onDelete={deleteTask}
                            />
                          </div>
                        )}
                      </Draggable>
                    ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

