### 5. Board Context (`BoardContext.js`)

```javascript
import React, { createContext, useContext, useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, query, where, onSnapshot, addDoc, updateDoc, deleteDoc, doc } from 'firebase/firestore';

const BoardContext = createContext();

export const useBoard = () => useContext(BoardContext);

export const BoardProvider = ({ children }) => {
  const [boards, setBoards] = useState([]);
  const [columns, setColumns] = useState([
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
  ]);
  const [tasks, setTasks] = useState([]);

  // Load boards from Firestore
  useEffect(() => {
    const q = query(collection(db, 'boards'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const boardsData = [];
      querySnapshot.forEach((doc) => {
        boardsData.push({ id: doc.id, ...doc.data() });
      });
      setBoards(boardsData);
    });

    return () => unsubscribe();
  }, []);

  // Load tasks for the current board
  useEffect(() => {
    if (boards.length > 0) {
      const currentBoard = boards[0]; // Default to first board
      const q = query(collection(db, 'tasks'), where('boardId', '==', currentBoard.id));
      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const tasksData = [];
        querySnapshot.forEach((doc) => {
          tasksData.push({ id: doc.id, ...doc.data() });
        });
        setTasks(tasksData);
      });

      return () => unsubscribe();
    }
  }, [boards]);

  const addTask = async (boardId, taskData) => {
    try {
      await addDoc(collection(db, 'tasks'), {
        ...taskData,
        boardId,
        columnId: 'todo', // Default to 'To Do' column
        createdAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error adding task: ", error);
    }
  };

  const updateTask = async (updatedTask) => {
    try {
      const taskRef = doc(db, 'tasks', updatedTask.id);
      await updateDoc(taskRef, updatedTask);
    } catch (error) {
      console.error("Error updating task: ", error);
    }
  };

  const deleteTask = async (taskId) => {
    try {
      await deleteDoc(doc(db, 'tasks', taskId));
    } catch (error) {
      console.error("Error deleting task: ", error);
    }
  };

  const moveTask = async (taskId, sourceColumnId, destinationColumnId, newIndex) => {
    try {
      // Update the columnId of the task
      const taskRef = doc(db, 'tasks', taskId);
      await updateDoc(taskRef, { columnId: destinationColumnId });

      // Reorder tasks in the destination column
      const updatedTasks = [...tasks];
      const taskIndex = updatedTasks.findIndex(task => task.id === taskId);
      const [removedTask] = updatedTasks.splice(taskIndex, 1);
      updatedTasks.splice(newIndex, 0, removedTask);

      setTasks(updatedTasks);
    } catch (error) {
      console.error("Error moving task: ", error);
    }
  };

  return (
    <BoardContext.Provider
      value={{
        boards,
        columns,
        tasks,
        addTask,
        updateTask,
        deleteTask,
        moveTask
      }}
    >
      {children}
    </BoardContext.Provider>
  );
};
```

