### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useFirestore } from '../hooks/useFirestore';
import TaskModal from './TaskModal';

const Board = () => {
  const { docs: columns, updateDocument: updateColumn } = useFirestore('columns');
  const { docs: tasks, addDocument: addTask, updateDocument: updateTask, deleteDocument: deleteTask } = useFirestore('tasks');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (destination.droppableId === source.droppableId && destination.index === source.index) {
      return;
    }

    const task = tasks.find(t => t.id === draggableId);

    if (destination.droppableId !== source.droppableId) {
      // Task moved to a different column
      updateTask(draggableId, {
        columnId: destination.droppableId,
        position: destination.index
      });

      // Update positions in both columns
      const sourceColumnTasks = tasks
        .filter(t => t.columnId === source.droppableId && t.id !== draggableId)
        .sort((a, b) => a.position - b.position);

      const destinationColumnTasks = tasks
        .filter(t => t.columnId === destination.droppableId && t.id !== draggableId)
        .sort((a, b) => a.position - b.position);

      // Update positions in source column
      sourceColumnTasks.forEach((t, index) => {
        if (index >= source.index) {
          updateTask(t.id, { position: index });
        }
      });

      // Update positions in destination column
      destinationColumnTasks.forEach((t, index) => {
        if (index >= destination.index) {
          updateTask(t.id, { position: index + 1 });
        }
      });
    } else {
      // Task reordered within the same column
      const columnTasks = tasks
        .filter(t => t.columnId === source.droppableId)
        .sort((a, b) => a.position - b.position);

      const [removed] = columnTasks.splice(source.index, 1);
      columnTasks.splice(destination.index, 0, removed);

      columnTasks.forEach((t, index) => {
        updateTask(t.id, { position: index });
      });
    }
  };

  const handleAddTask = (columnId) => {
    setCurrentTask({
      title: '',
      description: '',
      columnId,
      position: tasks.filter(t => t.columnId === columnId).length
    });
    setIsModalOpen(true);
  };

  const handleEditTask = (task) => {
    setCurrentTask(task);
    setIsModalOpen(true);
  };

  const handleSaveTask = (taskData) => {
    if (currentTask.id) {
      updateTask(currentTask.id, taskData);
    } else {
      addTask(taskData);
    }
    setIsModalOpen(false);
    setCurrentTask(null);
  };

  const handleDeleteTask = (taskId) => {
    deleteTask(taskId);
    setIsModalOpen(false);
    setCurrentTask(null);
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {columns.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.columnId === column.id).sort((a, b) => a.position - b.position)}
              onAddTask={handleAddTask}
              onEditTask={handleEditTask}
            />
          ))}
        </div>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={currentTask}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveTask}
          onDelete={currentTask.id ? handleDeleteTask : null}
        />
      )}
    </div>
  );
};

export default Board;
```

