### 3. Custom Hook for Tasks (useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import { collection, query, onSnapshot, doc, updateDoc, addDoc, deleteDoc } from 'firebase/firestore';

export const useTasks = (projectId) => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!projectId) return;

    const q = query(collection(db, `projects/${projectId}/tasks`));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
      setLoading(false);
    });

    return unsubscribe;
  }, [projectId]);

  const addTask = async (task) => {
    await addDoc(collection(db, `projects/${projectId}/tasks`), task);
  };

  const updateTask = async (taskId, updates) => {
    await updateDoc(doc(db, `projects/${projectId}/tasks`, taskId), updates);
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, `projects/${projectId}/tasks`, taskId));
  };

  return { tasks, loading, addTask, updateTask, deleteTask };
};
```

### 4. Board Component (Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useTasks } from '../hooks/useTasks';

const Board = ({ projectId }) => {
  const { tasks, loading, addTask, updateTask, deleteTask } = useTasks(projectId);
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const columns = [
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'review', title: 'Review' },
    { id: 'done', title: 'Done' }
  ];

  const onDragEnd = (result) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId === destination.droppableId) {
      // Reordering within the same column
      const columnTasks = tasks.filter(task => task.status === source.droppableId);
      const [removed] = columnTasks.splice(source.index, 1);
      columnTasks.splice(destination.index, 0, removed);

      // Update all tasks in the column
      columnTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });
    } else {
      // Moving to a different column
      const sourceTasks = tasks.filter(task => task.status === source.droppableId);
      const destTasks = tasks.filter(task => task.status === destination.droppableId);

      const [removed] = sourceTasks.splice(source.index, 1);
      destTasks.splice(destination.index, 0, removed);

      // Update the moved task's status
      updateTask(removed.id, {
        status: destination.droppableId,
        order: destination.index
      });

      // Update order in source column
      sourceTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });

      // Update order in destination column
      destTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (status) => {
    setSelectedTask({ status, title: '', description: '', assignee: null });
    setIsModalOpen(true);
  };

  const handleSaveTask = async (taskData) => {
    if (selectedTask.id) {
      await updateTask(selectedTask.id, taskData);
    } else {
      await addTask({ ...taskData, createdAt: new Date(), order: 0 });
    }
    setIsModalOpen(false);
  };

  const handleDeleteTask = async () => {
    if (selectedTask.id) {
      await deleteTask(selectedTask.id);
    }
    setIsModalOpen(false);
  };

  if (loading) return <div>Loading board...</div>;

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.status === column.id)}
              onTaskClick={handleTaskClick}
              onAddTask={handleAddTask}
            />
          ))}
        </div>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onClose={() => setIsModalOpen(false)}
          onSave={handleSaveTask}
          onDelete={handleDeleteTask}
        />
      )}
    </div>
  );
};

export default Board;
```

