# Browser-Based Project Management Application with Drag-and-Drop and Real-Time Collaboration

Below is a comprehensive implementation of a project management application with Kanban-style boards, drag-and-drop functionality, and real-time collaboration features.

## Frontend Implementation (React + TypeScript)

```typescript
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { io, Socket } from 'socket.io-client';
import './App.css';

interface Task {
  id: string;
  title: string;
  description: string;
  status: 'todo' | 'in-progress' | 'done';
  assignee?: string;
  dueDate?: string;
}

interface Column {
  id: string;
  title: string;
  taskIds: string[];
}

interface AppState {
  tasks: { [key: string]: Task };
  columns: { [key: string]: Column };
  columnOrder: string[];
}

const initialData: AppState = {
  tasks: {
    'task-1': { id: 'task-1', title: 'Task 1', description: 'First task', status: 'todo' },
    'task-2': { id: 'task-2', title: 'Task 2', description: 'Second task', status: 'in-progress' },
    'task-3': { id: 'task-3', title: 'Task 3', description: 'Third task', status: 'done' },
  },
  columns: {
    'column-1': {
      id: 'column-1',
      title: 'To Do',
      taskIds: ['task-1'],
    },
    'column-2': {
      id: 'column-2',
      title: 'In Progress',
      taskIds: ['task-2'],
    },
    'column-3': {
      id: 'column-3',
      title: 'Done',
      taskIds: ['task-3'],
    },
  },
  columnOrder: ['column-1', 'column-2', 'column-3'],
};

const TaskCard: React.FC<{ task: Task; index: number }> = ({ task, index }) => {
  return (
    <div className="task-card" data-handler-id={`task-${task.id}`}>
      <h3>{task.title}</h3>
      <p>{task.description}</p>
      {task.assignee && <p>Assigned to: {task.assignee}</p>}
      {task.dueDate && <p>Due: {task.dueDate}</p>}
    </div>
  );
};

const Column: React.FC<{
  column: Column;
  tasks: Task[];
  index: number;
  moveTask: (dragIndex: number, hoverIndex: number) => void;
}> = ({ column, tasks, index, moveTask }) => {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <div className="task-list">
        {tasks.map((task, taskIndex) => (
          <TaskCard key={task.id} task={task} index={taskIndex} />
        ))}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(initialData);
  const [socket, setSocket] = useState<Socket | null>(null);
  const [projectId, setProjectId] = useState<string>('default-project');

  useEffect(() => {
    // Connect to Socket.IO server
    const newSocket = io('http://localhost:3001');
    setSocket(newSocket);

    // Join project room
    newSocket.emit('joinProject', projectId);

    // Listen for state updates
    newSocket.on('stateUpdate', (updatedState: AppState) => {
      setState(updatedState);
    });

    return () => {
      newSocket.disconnect();
    };
  }, [projectId]);

  const onDragEnd = (result: any) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId === destination.droppableId) {
      // Reorder within the same column
      const column = state.columns[source.droppableId];
      const newTaskIds = Array.from(column.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, result.draggableId);

      const newColumn = {
        ...column,
        taskIds: newTaskIds,
      };

      const newState = {
        ...state,
        columns: {
          ...state.columns,
          [newColumn.id]: newColumn,
        },
      };

      setState(newState);
      if (socket) socket.emit('updateState', newState);
    } else {
      // Move to a different column
      const startColumn = state.columns[source.droppableId];
      const finishColumn = state.columns[destination.droppableId];

      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStartColumn = {
        ...startColumn,
        taskIds: startTaskIds,
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, result.draggableId);
      const newFinishColumn = {
        ...finishColumn,
        taskIds: finishTaskIds,
      };

      const newState = {
        ...state,
        columns: {
          ...state.columns,
          [newStartColumn.id]: newStartColumn,
          [newFinishColumn.id]: newFinishColumn,
        },
      };

      setState(newState);
      if (socket) socket.emit('updateState', newState);
    }
  };

  const moveTask = (dragIndex: number, hoverIndex: number) => {
    // This would be used if implementing custom drag-and-drop
    // For this example, we're using react-beautiful-dnd
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <header>
          <h1>Project Management Board</h1>
          <div className="project-selector">
            <label>Project ID: </label>
            <input
              type="text"
              value={projectId}
              onChange={(e) => setProjectId(e.target.value)}
            />
          </div>
        </header>
        <div className="board">
          {state.columnOrder.map((columnId, index) => {
            const column = state.columns[columnId];
            const tasks = column.taskIds.map((taskId) => state.tasks[taskId]);

            return (
              <Column
                key={column.id}
                column={column}
                tasks={tasks}
                index={index}
                moveTask={moveTask}
              />
            );
          })}
        </div>
      </div>
    </DndProvider>
  );
};

export default App;
```

## Backend Implementation (Node.js + Socket.IO)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Store project states in memory (in a real app, use a database)
const projectStates = {};

io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('joinProject', (projectId) => {
    socket.join(projectId);

    // Send current state to the client
    if (projectStates[projectId]) {
      socket.emit('stateUpdate', projectStates[projectId]);
    }
  });

  socket.on('updateState', (newState) => {
    const projectId = Object.keys(socket.rooms)[1]; // Get the project room ID
    projectStates[projectId] = newState;

    // Broadcast to all clients in the project room
    io.to(projectId).emit('stateUpdate', newState);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

