### 4. Task Component (Task.jsx)

```javascript
import React, { useState } from 'react';
import { Draggable } from 'react-beautiful-dnd';
import { useFirestore } from '../hooks/useFirestore';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';

const Task = ({ task, index }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const [editedDescription, setEditedDescription] = useState(task.description || '');
  const { updateDocument, deleteDocument } = useFirestore('tasks');

  const handleEdit = async () => {
    if (isEditing) {
      await updateDocument(task.id, {
        title: editedTitle,
        description: editedDescription
      });
    }
    setIsEditing(!isEditing);
  };

  const handleDelete = async () => {
    await deleteDocument(task.id);
  };

  const handleDragEnd = async (result) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId !== destination.droppableId) {
      const taskRef = doc(db, 'tasks', task.id);
      await updateDoc(taskRef, {
        status: destination.droppableId
      });
    }
  };

  return (
    <Draggable draggableId={task.id} index={index} onDragEnd={handleDragEnd}>
      {(provided) => (
        <div
          ref={provided.innerRef}
          {...provided.draggableProps}
          {...provided.dragHandleProps}
          className="bg-white p-4 rounded-lg shadow-md mb-2 hover:shadow-lg transition-shadow"
        >
          {isEditing ? (
            <div>
              <input
                type="text"
                value={editedTitle}
                onChange={(e) => setEditedTitle(e.target.value)}
                className="w-full p-2 mb-2 border rounded"
              />
              <textarea
                value={editedDescription}
                onChange={(e) => setEditedDescription(e.target.value)}
                className="w-full p-2 mb-2 border rounded"
                rows="3"
              />
            </div>
          ) : (
            <div>
              <h3 className="font-semibold text-lg">{task.title}</h3>
              {task.description && <p className="text-sm text-gray-600 mt-1">{task.description}</p>}
            </div>
          )}
          <div className="flex justify-between mt-2">
            <button
              onClick={handleEdit}
              className="text-blue-500 hover:text-blue-700 text-sm"
            >
              {isEditing ? 'Save' : 'Edit'}
            </button>
            {!isEditing && (
              <button
                onClick={handleDelete}
                className="text-red-500 hover:text-red-700 text-sm"
              >
                Delete
              </button>
            )}
          </div>
        </div>
      )}
    </Draggable>
  );
};

export default Task;
```

