### 4. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { db } from '../firebase/firebase';
import { doc, updateDoc, arrayUnion, arrayRemove } from 'firebase/firestore';

const Board = ({ projectId }) => {
  const [columns, setColumns] = useState([
    { id: 'todo', title: 'To Do', taskIds: [] },
    { id: 'in-progress', title: 'In Progress', taskIds: [] },
    { id: 'done', title: 'Done', taskIds: [] }
  ]);

  const [tasks, setTasks] = useState({});

  useEffect(() => {
    // Load project data from Firestore
    const loadProjectData = async () => {
      // Implementation would fetch project data and populate columns and tasks
    };

    loadProjectData();
  }, [projectId]);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const startColumn = columns.find(col => col.id === source.droppableId);
    const finishColumn = columns.find(col => col.id === destination.droppableId);

    if (startColumn === finishColumn) {
      // Reorder within the same column
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      setColumns(columns.map(col =>
        col.id === newColumn.id ? newColumn : col
      ));

      // Update in Firestore
      const projectRef = doc(db, 'projects', projectId);
      await updateDoc(projectRef, {
        [`columns.${startColumn.id}`]: newTaskIds
      });
    } else {
      // Move to another column
      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStartColumn = {
        ...startColumn,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinishColumn = {
        ...finishColumn,
        taskIds: finishTaskIds
      };

      setColumns(columns.map(col => {
        if (col.id === newStartColumn.id) return newStartColumn;
        if (col.id === newFinishColumn.id) return newFinishColumn;
        return col;
      }));

      // Update in Firestore
      const projectRef = doc(db, 'projects', projectId);
      await updateDoc(projectRef, {
        [`columns.${startColumn.id}`]: newStartColumn.taskIds,
        [`columns.${finishColumn.id}`]: newFinishColumn.taskIds
      });

      // Update task status
      const taskRef = doc(db, 'tasks', draggableId);
      await updateDoc(taskRef, {
        status: finishColumn.id
      });
    }
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div className="board">
        {columns.map(column => (
          <Column
            key={column.id}
            column={column}
            tasks={tasks}
            projectId={projectId}
          />
        ))}
      </div>
    </DragDropContext>
  );
};

export default Board;
```

