```javascript
import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { db } from '../firebase/firebase';
import { collection, query, where, getDocs, addDoc } from 'firebase/firestore';
import Board from '../components/Board';

const Dashboard = () => {
  const { currentUser } = useAuth();
  const [projects, setProjects] = useState([]);
  const [selectedProject, setSelectedProject] = useState(null);
  const [newProjectName, setNewProjectName] = useState('');

  useEffect(() => {
    const fetchProjects = async () => {
      if (currentUser) {
        const q = query(
          collection(db, 'projects'),
          where('members', 'array-contains', currentUser.uid)
        );
        const querySnapshot = await getDocs(q);
        const projectsData = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));
        setProjects(projectsData);
        if (projectsData.length > 0) {
          setSelectedProject(projectsData[0].id);
        }
      }
    };

    fetchProjects();
  }, [currentUser]);

  const handleCreateProject = async () => {
    if (!newProjectName.trim()) return;

    const newProject = {
      name: newProjectName,
      members: [currentUser.uid],
      createdAt: new Date(),
      columns: {
        todo: [],
        'in-progress': [],
        done: []
      }
    };

    const docRef = await addDoc(collection(db, 'projects'), newProject);
    setProjects([...projects, { id: docRef.id, ...newProject }]);
    setSelectedProject(docRef.id);
    setNewProjectName('');
  };

  return (
    <div className="dashboard">
      <div className="sidebar">
        <h2>Projects</h2>
        <ul>
          {projects.map(project => (
            <li
              key={project.id}
              className={selectedProject === project.id ? 'active' : ''}
              onClick={() => setSelectedProject(project.id)}
            >
              {project.name}
            </li>
          ))}
        </ul>
        <div className="new-project">
          <input
            type="text"
            placeholder="New project name"
            value={newProjectName}
            onChange={(e) => setNewProjectName(e.target.value)}
          />
          <button onClick={handleCreateProject}>Create</button>
        </div>
      </div>
      <div className="main-content">
        {selectedProject ? (
          <>
            <h1>{projects.find(p => p.id === selectedProject)?.name}</h1>
            <Board projectId={selectedProject} />
          </>
        ) : (
          <div className="empty-state">
            <h2>Welcome to Project Management</h2>
            <p>Create a new project to get started</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
```

