```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import AddTaskForm from './AddTaskForm';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const Board = ({ projectId }) => {
  const { user } = useAuth();
  const [columns, setColumns] = useState([
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
  ]);
  const [showAddTask, setShowAddTask] = useState(false);
  const [selectedColumn, setSelectedColumn] = useState(null);

  const { docs: tasks, addDocument, updateDocument } = useFirestore('tasks', projectId);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const task = tasks.find(t => t.id === draggableId);
    if (task) {
      updateDocument(draggableId, {
        columnId: destination.droppableId,
        position: destination.index
      });
    }
  };

  const handleAddTask = (columnId) => {
    setSelectedColumn(columnId);
    setShowAddTask(true);
  };

  const handleSubmitTask = async (taskData) => {
    await addDocument({
      ...taskData,
      columnId: selectedColumn,
      projectId,
      position: tasks.filter(t => t.columnId === selectedColumn).length,
      createdBy: user.uid
    });
    setShowAddTask(false);
  };

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Droppable key={column.id} droppableId={column.id}>
              {(provided) => (
                <div
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                  className="column-wrapper"
                >
                  <Column
                    column={column}
                    tasks={tasks.filter(task => task.columnId === column.id)}
                    onAddTask={() => handleAddTask(column.id)}
                  />
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>

      {showAddTask && (
        <AddTaskForm
          onSubmit={handleSubmitTask}
          onClose={() => setShowAddTask(false)}
          columnTitle={columns.find(c => c.id === selectedColumn)?.title}
        />
      )}
    </div>
  );
};

export default Board;
