import React, { useState } from 'react';
import { useFirestore } from '../hooks/useFirestore';

const Task = ({ task }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const { updateDocument, deleteDocument } = useFirestore('tasks', task.projectId);

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleSave = () => {
    updateDocument(task.id, { title: editedTitle });
    setIsEditing(false);
  };

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      deleteDocument(task.id);
    }
  };

  return (
    <div className="task">
      {isEditing ? (
        <div className="task-edit">
          <input
            type="text"
            value={editedTitle}
            onChange={(e) => setEditedTitle(e.target.value)}
          />
          <div className="task-actions">
            <button onClick={handleSave}>Save</button>
            <button onClick={() => setIsEditing(false)}>Cancel</button>
          </div>
        </div>
      ) : (
        <>
          <div className="task-content">
            <h4>{task.title}</h4>
            {task.description && <p>{task.description}</p>}
            {task.dueDate && <p className="due-date">Due: {new Date(task.dueDate).toLocaleDateString()}</p>}
          </div>
          <div className="task-actions">
            <button onClick={handleEdit}>Edit</button>
            <button onClick={handleDelete}>Delete</button>
          </div>
        </>
      )}
    </div>
  );
};

export default Task;
