## 3. JavaScript (script.js)

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // DOM Elements
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column');
    const taskModal = document.getElementById('task-modal');
    const columnModal = document.getElementById('column-modal');
    const taskForm = document.getElementById('task-form');
    const columnForm = document.getElementById('column-form');
    const closeButtons = document.querySelectorAll('.close');
    const changeNameBtn = document.getElementById('change-name');
    const usernameDisplay = document.getElementById('username');

    // State
    let currentUser = localStorage.getItem('username') || 'Guest';
    let columns = JSON.parse(localStorage.getItem('columns')) || [
        { id: 'todo', title: 'To Do', tasks: [] },
        { id: 'in-progress', title: 'In Progress', tasks: [] },
        { id: 'done', title: 'Done', tasks: [] }
    ];

    // Socket.io connection
    const socket = io();

    // Initialize the app
    function init() {
        usernameDisplay.textContent = currentUser;
        renderBoard();
        setupEventListeners();
        setupDragAndDrop();

        // Listen for real-time updates
        socket.on('board-update', (updatedColumns) => {
            columns = updatedColumns;
            renderBoard();
        });

        socket.on('user-joined', (username) => {
            console.log(`${username} joined the board`);
        });
    }

    // Render the entire board
    function renderBoard() {
        board.innerHTML = '';

        columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.id = column.id;

            columnElement.innerHTML = `
                <div class="column-header">
                    <h3 class="column-title">${column.title}</h3>
                    <div class="column-actions">
                        <button class="edit-column" title="Edit Column"><i class="fas fa-edit"></i></button>
                        <button class="delete-column" title="Delete Column"><i class="fas fa-trash"></i></button>
                    </div>
                </div>
                <div class="task-list" data-column-id="${column.id}">
                    ${column.tasks.map(task => createTaskElement(task)).join('')}
                </div>
                <button class="add-task-btn" data-column-id="${column.id}">+ Add Task</button>
            `;

            board.appendChild(columnElement);
        });

        // Save to local storage
        localStorage.setItem('columns', JSON.stringify(columns));
    }

    // Create a task element
    function createTaskElement(task) {
        return `
            <div class="task" draggable="true" data-task-id="${task.id}" data-column-id="${task.columnId}">
                <div class="task-header">
                    <span class="task-title">${task.title}</span>
                    <span class="task-priority priority-${task.priority}">${task.priority}</span>
                </div>
                ${task.description ? `<p class="task-description">${task.description}</p>` : ''}
                ${task.assignee ? `
                    <div class="task-assignee">
                        <i class="fas fa-user"></i>
                        <span>${task.assignee}</span>
                    </div>
                ` : ''}
                <div class="task-actions">
                    <button class="edit-task" title="Edit Task"><i class="fas fa-edit"></i></button>
                    <button class="delete-task" title="Delete Task"><i class="fas fa-trash"></i></button>
                </div>
            </div>
        `;
    }

    // Setup event listeners
    function setupEventListeners() {
        // Add column button
        addColumnBtn.addEventListener('click', () => {
            columnModal.style.display = 'flex';
        });

        // Change username
        changeNameBtn.addEventListener('click', () => {
            const newName = prompt('Enter your name:', currentUser);
            if (newName && newName.trim() !== '') {
                currentUser = newName.trim();
                usernameDisplay.textContent = currentUser;
                localStorage.setItem('username', currentUser);
                socket.emit('user-joined', currentUser);
            }
        });

        // Close modals
        closeButtons.forEach(button => {
            button.addEventListener('click', () => {
                taskModal.style.display = 'none';
                columnModal.style.display = 'none';
            });
        });

        // Window click to close modals
        window.addEventListener('click', (e) => {
            if (e.target === taskModal) {
                taskModal.style.display = 'none';
            }
            if (e.target === columnModal) {
                columnModal.style.display = 'none';
            }
        });

        // Column form submission
        columnForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const title = document.getElementById('column-title').value.trim();

            if (title) {
                const newColumn = {
                    id: 'col-' + Date.now(),
                    title: title,
                    tasks: []
                };

                columns.push(newColumn);
                renderBoard();
                columnForm.reset();
                columnModal.style.display = 'none';

                // Emit update to server
                socket.emit('board-update', columns);
            }
        });

        // Task form submission
        taskForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const id = document.getElementById('task-id').value;
            const title = document.getElementById('task-title').value.trim();
            const description = document.getElementById('task-description').value.trim();
            const priority = document.getElementById('task-priority').value;
            const assignee = document.getElementById('task-assignee').value.trim();
            const columnId = taskForm.dataset.columnId;

            if (title) {
                const task = {
                    id: id || 'task-' + Date.now(),
                    title,
                    description,
                    priority,
                    assignee,
                    columnId
                };

                if (id) {
                    // Update existing task
                    columns = columns.map(col => {
                        if (col.id === columnId) {
                            return {
                                ...col,
                                tasks: col.tasks.map(t => t.id === id ? task : t)
                            };
                        }
                        return col;
                    });
                } else {
                    // Add new task
                    columns = columns.map(col => {
                        if (col.id === columnId) {
                            return {
                                ...col,
                                tasks: [...col.tasks, task]
                            };
                        }
                        return col;
                    });
                }

                renderBoard();
                taskForm.reset();
                taskModal.style.display = 'none';

                // Emit update to server
                socket.emit('board-update', columns);
            }
        });

        // Dynamic event listeners for buttons
        board.addEventListener('click', (e) => {
            // Add task button
            if (e.target.closest('.add-task-btn')) {
                const columnId = e.target.closest('.add-task-btn').dataset.columnId;
                openTaskModal(columnId);
            }

            // Edit task button
            if (e.target.closest('.edit-task')) {
                const taskElement = e.target.closest('.task');
                const taskId = taskElement.dataset.taskId;
                const columnId = taskElement.dataset.columnId;

                const column = columns.find(col => col.id === columnId);
                const task = column.tasks.find(t => t.id === taskId);

                openTaskModal(columnId, task);
            }

            // Delete task button
            if (e.target.closest('.delete-task')) {
                if (confirm('Are you sure you want to delete this task?')) {
                    const taskElement = e.target.closest('.task');
                    const taskId = taskElement.dataset.taskId;
                    const columnId = taskElement.dataset.columnId;

                    columns = columns.map(col => {
                        if (col.id === columnId) {
                            return {
                                ...col,
                                tasks: col.tasks.filter(t => t.id !== taskId)
                            };
                        }
                        return col;
                    });

                    renderBoard();

                    // Emit update to server
                    socket.emit('board-update', columns);
                }
            }

            // Edit column button
            if (e.target.closest('.edit-column')) {
                const columnElement = e.target.closest('.column');
                const columnId = columnElement.dataset.id;
                const column = columns.find(col => col.id === columnId);

                const newTitle = prompt('Enter new column title:', column.title);
                if (newTitle && newTitle.trim() !== '') {
                    columns = columns.map(col => {
                        if (col.id === columnId) {
                            return {
                                ...col,
                                title: newTitle.trim()
                            };
                        }
                        return col;
                    });

                    renderBoard();

                    // Emit update to server
                    socket.emit('board-update', columns);
                }
            }

            // Delete column button
            if (e.target.closest('.delete-column')) {
                if (confirm('Are you sure you want to delete this column and all its tasks?')) {
                    const columnElement = e.target.closest('.column');
                    const columnId = columnElement.dataset.id;

                    columns = columns.filter(col => col.id !== columnId);

                    renderBoard();

                    // Emit update to server
                    socket.emit('board-update', columns);
                }
            }
        });
    }

    // Open task modal for adding or editing
    function openTaskModal(columnId, task = null) {
        taskModal.style.display = 'flex';
        taskForm.dataset.columnId = columnId;

        if (task) {
            document.getElementById('modal-title').textContent = 'Edit Task';
            document.getElementById('task-id').value = task.id;
            document.getElementById('task-title').value = task.title;
            document.getElementById('task-description').value = task.description || '';
            document.getElementById('task-priority').value = task.priority;
            document.getElementById('task-assignee').value = task.assignee || '';
        } else {
            document.getElementById('modal-title').textContent = 'Add New Task';
            taskForm.reset();
            document.getElementById('task-id').value = '';
        }
    }

    // Setup drag and drop functionality
    function setupDragAndDrop() {
        let draggedTask = null;
        let sourceColumnId = null;

        // Drag start
        board.addEventListener('dragstart', (e) => {
            if (e.target.classList.contains('task')) {
                draggedTask = e.target;
                sourceColumnId = e.target.dataset.columnId;
                e.target.classList.add('dragging');
                e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
                e.dataTransfer.effectAllowed = 'move';
            }
        });

        // Drag end
        board.addEventListener('dragend', (e) => {
            if (e.target.classList.contains('task')) {
                e.target.classList.remove('dragging');
            }
        });

        // Drag over
        board.addEventListener('dragover', (e) => {
            e.preventDefault();
            const taskList = e.target.closest('.task-list');
            if (taskList) {
                taskList.classList.add('drag-over');
                e.dataTransfer.dropEffect = 'move';
            }
        });

        // Drag leave
        board.addEventListener('dragleave', (e) => {
            const taskList = e.target.closest('.task-list');
            if (taskList) {
                taskList.classList.remove('drag-over');
            }
        });

        // Drop
        board.addEventListener('drop', (e) => {
            e.preventDefault();
            const taskList = e.target.closest('.task-list');
            if (taskList) {
                taskList.classList.remove('drag-over');

                const taskId = e.dataTransfer.getData('text/plain');
                const targetColumnId = taskList.dataset.columnId;

                if (sourceColumnId !== targetColumnId) {
                    // Move task to new column
                    const taskIndex = columns.find(col => col.id === sourceColumnId)
                                            .tasks.findIndex(t => t.id === taskId);

                    const [movedTask] = columns.find(col => col.id === sourceColumnId)
                                             .tasks.splice(taskIndex, 1);

                    movedTask.columnId = targetColumnId;

                    columns.find(col => col.id === targetColumnId)
                          .tasks.push(movedTask);

                    renderBoard();

                    // Emit update to server
                    socket.emit('board-update', columns);
                }
            }
        });
    }

    // Initialize the app
    init();
});
```

