### 1. Frontend (React Components)

#### Board.tsx
```tsx
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, DropResult } from 'react-beautiful-dnd';
import Column from './Column';
import { useSocket } from '../hooks/useSocket';
import { Task, Column as ColumnType } from '../types/types';

interface BoardProps {
  projectId: string;
}

const Board: React.FC<BoardProps> = ({ projectId }) => {
  const [columns, setColumns] = useState<ColumnType[]>([]);
  const socket = useSocket();

  useEffect(() => {
    // Fetch initial board data
    fetch(`/api/projects/${projectId}/board`)
      .then(res => res.json())
      .then(data => setColumns(data.columns));

    // Listen for real-time updates
    socket.on('board-update', (updatedColumns: ColumnType[]) => {
      setColumns(updatedColumns);
    });

    return () => {
      socket.off('board-update');
    };
  }, [projectId, socket]);

  const onDragEnd = (result: DropResult) => {
    if (!result.destination) return;

    const { source, destination } = result;

    // Handle drag within the same column
    if (source.droppableId === destination.droppableId) {
      const column = columns.find(c => c.id === source.droppableId);
      if (!column) return;

      const newTasks = [...column.tasks];
      const [removed] = newTasks.splice(source.index, 1);
      newTasks.splice(destination.index, 0, removed);

      const newColumns = columns.map(c =>
        c.id === column.id ? { ...c, tasks: newTasks } : c
      );

      setColumns(newColumns);
      socket.emit('update-board', { projectId, columns: newColumns });
    }
    // Handle drag between columns
    else {
      const sourceColumn = columns.find(c => c.id === source.droppableId);
      const destColumn = columns.find(c => c.id === destination.droppableId);

      if (!sourceColumn || !destColumn) return;

      const sourceTasks = [...sourceColumn.tasks];
      const [removed] = sourceTasks.splice(source.index, 1);

      const destTasks = [...destColumn.tasks];
      destTasks.splice(destination.index, 0, removed);

      const newColumns = columns.map(c => {
        if (c.id === sourceColumn.id) return { ...c, tasks: sourceTasks };
        if (c.id === destColumn.id) return { ...c, tasks: destTasks };
        return c;
      });

      setColumns(newColumns);
      socket.emit('update-board', { projectId, columns: newColumns });
    }
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div className="board">
        {columns.map(column => (
          <Column key={column.id} column={column} />
        ))}
      </div>
    </DragDropContext>
  );
};

export default Board;
```

