                    dueDate: '2023-12-10',
                    priority: 'medium',
                    status: 'todo'
                }
            ]
        },
        {
            id: 'col2',
            title: 'In Progress',
            tasks: [
                {
                    id: 'task3',
                    title: 'Set up real-time updates',
                    description: 'Implement WebSocket or similar for real-time collaboration',
                    assignee: 'Bob Johnson',
                    dueDate: '2023-12-20',
                    priority: 'high',
                    status: 'in-progress'
                }
            ]
        },
        {
            id: 'col3',
            title: 'Done',
            tasks: [
                {
                    id: 'task4',
                    title: 'Create project structure',
                    description: 'Set up the basic project structure and files',
                    assignee: 'Alice Williams',
                    dueDate: '2023-12-05',
                    priority: 'low',
                    status: 'done'
                }
            ]
        }
    ]
};

// Current user
let currentUser = 'Guest';

// DOM elements
const boardElement = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnNameInput = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskForm = document.getElementById('task-form');
const modalTitle = document.getElementById('modal-title');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskAssigneeInput = document.getElementById('task-assignee');
const taskDueDateInput = document.getElementById('task-due-date');
const taskPriorityInput = document.getElementById('task-priority');
const changeUserBtn = document.getElementById('change-user');
const currentUserElement = document.getElementById('current-user');

// Current task being edited
let currentTask = null;
let currentColumnId = null;

// Initialize the board
function initBoard() {
    boardElement.innerHTML = '';
    boardData.columns.forEach(column => {
        renderColumn(column);
    });

    // Initialize drag-and-drop for all columns
    boardData.columns.forEach(column => {
        const columnElement = document.getElementById(column.id);
        if (columnElement) {
            const taskList = columnElement.querySelector('.task-list');
            new Sortable(taskList, {
                group: 'tasks',
                animation: 150,
                ghostClass: 'sortable-ghost',
                chosenClass: 'sortable-chosen',
                onEnd: function (evt) {
                    handleTaskMove(evt);
                }
            });
        }
    });
}

// Render a single column
function renderColumn(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.id = column.id;

    columnElement.innerHTML = `
        <div class="column-header">
            <h3 class="column-title">${column.title}</h3>
            <div class="column-actions">
                <button class="edit-column-btn" data-column-id="${column.id}">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="delete-column-btn" data-column-id="${column.id}">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
        <div class="task-list" id="${column.id}-tasks">
            ${column.tasks.map(task => renderTaskCard(task)).join('')}
        </div>
        <button class="add-task-btn" data-column-id="${column.id}">Add Task</button>
    `;

    boardElement.appendChild(columnElement);

    // Add event listeners for column buttons
    const addTaskBtn = columnElement.querySelector('.add-task-btn');
    addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));

    const editColumnBtn = columnElement.querySelector('.edit-column-btn');
    editColumnBtn.addEventListener('click', (e) => editColumn(e.target.dataset.columnId));

    const deleteColumnBtn = columnElement.querySelector('.delete-column-btn');
    deleteColumnBtn.addEventListener('click', (e) => deleteColumn(e.target.dataset.columnId));
}

// Render a single task card
function renderTaskCard(task) {
    return `
        <div class="task-card" data-task-id="${task.id}" draggable="true">
            <div class="task-title">${task.title}</div>
            <div class="task-description">${task.description.substring(0, 50)}${task.description.length > 50 ? '...' : ''}</div>
            <div class="task-meta">
                <span class="task-assignee">${task.assignee || 'Unassigned'}</span>
                <span class="task-due-date">${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date'}</span>
                <span class="task-priority priority-${task.priority}">${task.priority}</span>
            </div>
            <div class="task-actions">
                <button class="edit-task-btn" data-task-id="${task.id}">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="delete-task-btn" data-task-id="${task.id}">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
    `;
}

// Handle task movement between columns
function handleTaskMove(evt) {
    const fromColumnId = evt.from.parentElement.id;
    const toColumnId = evt.to.parentElement.id;
    const taskId = evt.item.dataset.taskId;

    if (fromColumnId === toColumnId) {
        // Task moved within the same column (just reorder)
        const column = boardData.columns.find(col => col.id === fromColumnId);
        const taskIndex = column.tasks.findIndex(task => task.id === taskId);
        const [removed] = column.tasks.splice(taskIndex, 1);
        column.tasks.splice(evt.newIndex, 0, removed);

        // Simulate real-time update
        simulateRealTimeUpdate('task-moved', { taskId, fromColumnId, toColumnId, newIndex: evt.newIndex });
    } else {
        // Task moved to a different column
        const fromColumn = boardData.columns.find(col => col.id === fromColumnId);
        const toColumn = boardData.columns.find(col => col.id === toColumnId);

        const taskIndex = fromColumn.tasks.findIndex(task => task.id === taskId);
        const [movedTask] = fromColumn.tasks.splice(taskIndex, 1);

        // Update the task's status to match the new column
        movedTask.status = toColumn.title.toLowerCase().replace(' ', '-');

        toColumn.tasks.splice(evt.newIndex, 0, movedTask);

        // Simulate real-time update
        simulateRealTimeUpdate('task-moved', { taskId, fromColumnId, toColumnId, newIndex: evt.newIndex });

        // Re-render the board to update the task cards
        initBoard();
    }
}

// Open task modal for editing or creating a new task
function openTaskModal(taskId, columnId) {
    currentTask = taskId;
    currentColumnId = columnId;

    if (taskId) {
        // Editing existing task
        const column = boardData.columns.find(col => col.tasks.some(task => task.id === taskId));
        const task = column.tasks.find(task => task.id === taskId);

        modalTitle.textContent = 'Edit Task';
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description;
        taskAssigneeInput.value = task.assignee || '';
        taskDueDateInput.value = task.dueDate || '';
        taskPriorityInput.value = task.priority || 'medium';
    } else {
        // Creating new task
        modalTitle.textContent = 'Add New Task';
        taskForm.reset();
    }

    taskModal.style.display = 'block';
}

// Close task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
    currentTask = null;
    currentColumnId = null;
}

// Save task (create or update)
function saveTask(e) {
    e.preventDefault();

    const taskData = {
        title: taskTitleInput.value,
        description: taskDescriptionInput.value,
        assignee: taskAssigneeInput.value,
        dueDate: taskDueDateInput.value,
        priority: taskPriorityInput.value,
        status: boardData.columns.find(col => col.id === currentColumnId).title.toLowerCase().replace(' ', '-')
    };

    if (currentTask) {
        // Update existing task
        const column = boardData.columns.find(col => col.tasks.some(task => task.id === currentTask));
        const taskIndex = column.tasks.findIndex(task => task.id === currentTask);
        column.tasks[taskIndex] = { ...column.tasks[taskIndex], ...taskData };

        // Simulate real-time update
        simulateRealTimeUpdate('task-updated', { taskId: currentTask, taskData });
    } else {
        // Create new task
        const newTaskId = 'task' + Date.now();
        const newTask = { ...taskData, id: newTaskId };

        const column = boardData.columns.find(col => col.id === currentColumnId);
        column.tasks.push(newTask);

        // Simulate real-time update
        simulateRealTimeUpdate('task-created', { task: newTask, columnId: currentColumnId });
    }

    closeTaskModal();
    initBoard();
}

// Edit column title
function editColumn(columnId) {
    const column = boardData.columns.find(col => col.id === columnId);
    const newTitle = prompt('Enter new column title:', column.title);

    if (newTitle && newTitle !== column.title) {
        column.title = newTitle;

        // Simulate real-time update
        simulateRealTimeUpdate('column-updated', { columnId, newTitle });

        initBoard();
    }
}

// Delete column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column and all its tasks?')) {
        boardData.columns = boardData.columns.filter(col => col.id !== columnId);

        // Simulate real-time update
        simulateRealTimeUpdate('column-deleted', { columnId });

        initBoard();
    }
}

// Add new column
function addColumn() {
    const columnName = newColumnNameInput.value.trim();

    if (columnName) {
        const newColumnId = 'col' + Date.now();
        const newColumn = {
            id: newColumnId,
            title: columnName,
            tasks: []
        };

        boardData.columns.push(newColumn);
        newColumnNameInput.value = '';

        // Simulate real-time update
        simulateRealTimeUpdate('column-created', { column: newColumn });

        initBoard();
    }
}

// Change current user
function changeUser() {
    const newUser = prompt('Enter your name:', currentUser);
    if (newUser) {
        currentUser = newUser;
        currentUserElement.textContent = `User: ${currentUser}`;
    }
}

// Simulate real-time updates (in a real app, this would use WebSockets or similar)
function simulateRealTimeUpdate(eventType, data) {
    console.log(`Real-time update: ${eventType}`, data);

    // In a real implementation, you would send this to the server
    // and broadcast to all connected clients

    // For this demo, we'll just log it to the console
}

// Event listeners
addColumnBtn.addEventListener('click', addColumn);
closeModal.addEventListener('click', closeTaskModal);
taskForm.addEventListener('submit', saveTask);
changeUserBtn.addEventListener('click', changeUser);

// Close modal when clicking outside
window.addEventListener('click', (e) => {
    if (e.target === taskModal) {
        closeTaskModal();
    }
});

// Initialize the board when the page loads
document.addEventListener('DOMContentLoaded', initBoard);
```

