### 3. Frontend Components

#### Board Component (client/src/components/Board.tsx)
```typescript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable, DropResult } from 'react-beautiful-dnd';
import { useSocket } from '../contexts/SocketContext';
import { Task } from '../types/task';
import TaskCard from './TaskCard';
import api from '../utils/api';

interface BoardProps {
  boardId: string;
}

const Board: React.FC<BoardProps> = ({ boardId }) => {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [columns, setColumns] = useState<Record<string, Task[]>>({});
  const socket = useSocket();

  useEffect(() => {
    const fetchTasks = async () => {
      try {
        const response = await api.get(`/tasks?boardId=${boardId}`);
        setTasks(response.data);

        // Organize tasks by status
        const cols: Record<string, Task[]> = {};
        response.data.forEach((task: Task) => {
          if (!cols[task.status]) {
            cols[task.status] = [];
          }
          cols[task.status].push(task);
        });
        setColumns(cols);
      } catch (error) {
        console.error('Error fetching tasks:', error);
      }
    };

    fetchTasks();

    // Listen for real-time updates
    socket.on('taskUpdated', (updatedTask: Task) => {
      setTasks(prevTasks => {
        const newTasks = prevTasks.map(task =>
          task._id === updatedTask._id ? updatedTask : task
        );

        // Reorganize columns
        const cols: Record<string, Task[]> = {};
        newTasks.forEach(task => {
          if (!cols[task.status]) {
            cols[task.status] = [];
          }
          cols[task.status].push(task);
        });
        setColumns(cols);

        return newTasks;
      });
    });

    return () => {
      socket.off('taskUpdated');
    };
  }, [boardId, socket]);

  const onDragEnd = (result: DropResult) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId === destination.droppableId) {
      // Reordering within the same column
      const column = columns[source.droppableId];
      const [removed] = column.splice(source.index, 1);
      column.splice(destination.index, 0, removed);

      setColumns({
        ...columns,
        [source.droppableId]: column
      });
    } else {
      // Moving to a different column
      const sourceColumn = columns[source.droppableId];
      const destColumn = columns[destination.droppableId];
      const [removed] = sourceColumn.splice(source.index, 1);

      // Update the task status
      const updatedTask = {
        ...removed,
        status: destination.droppableId
      };

      // Update locally
      destColumn.splice(destination.index, 0, updatedTask);

      setColumns({
        ...columns,
        [source.droppableId]: sourceColumn,
        [destination.droppableId]: destColumn
      });

      // Update on server and notify others
      api.put(`/tasks/${updatedTask._id}`, updatedTask)
        .then(() => {
          socket.emit('updateTask', updatedTask);
        })
        .catch(error => {
          console.error('Error updating task:', error);
          // Revert changes if update fails
          setColumns(columns);
        });
    }
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board-columns">
          {Object.entries(columns).map(([columnId, columnTasks]) => (
            <Droppable droppableId={columnId} key={columnId}>
              {(provided) => (
                <div
                  className="board-column"
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                >
                  <h3>{columnId}</h3>
                  {columnTasks.map((task, index) => (
                    <Draggable
                      key={task._id}
                      draggableId={task._id}
                      index={index}
                    >
                      {(provided) => (
                        <div
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                        >
                          <TaskCard task={task} />
                        </div>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

