```typescript
import express from 'express';
import Board from '../models/Board';

const router = express.Router();

// Get all boards
router.get('/', async (req, res) => {
  try {
    const boards = await Board.find();
    res.json(boards);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Create a new board
router.post('/', async (req, res) => {
  const board = new Board({
    name: req.body.name,
    createdBy: req.body.createdBy
  });

  try {
    const newBoard = await board.save();
    res.status(201).json(newBoard);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// Get a specific board
router.get('/:id', getBoard, (req, res) => {
  res.json(res.board);
});

// Middleware to get board by ID
async function getBoard(req: express.Request, res: express.Response, next: express.NextFunction) {
  let board;
  try {
    board = await Board.findById(req.params.id);
    if (board == null) {
      return res.status(404).json({ message: 'Cannot find board' });
    }
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }

  res.board = board;
  next();
}

export default router;
