            name: 'Done',
            tasks: [
                {
                    id: 'task4',
                    title: 'Write documentation',
                    description: 'Document the project setup and architecture',
                    dueDate: '2023-12-05',
                    priority: 'low',
                    assignee: 'Jane Smith'
                }
            ]
        }
    ]
};

// Current state
let state = JSON.parse(JSON.stringify(initialData));
let currentUser = 'Guest';
let onlineUsers = ['John Doe', 'Jane Smith'];

// DOM elements
const boardElement = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnNameInput = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskForm = document.getElementById('task-form');
const changeUserBtn = document.getElementById('change-user');
const currentUserElement = document.getElementById('current-user');

// Initialize the app
function init() {
    renderBoard();
    setupEventListeners();
    updateCurrentUserDisplay();
}

// Render the entire board
function renderBoard() {
    boardElement.innerHTML = '';

    state.columns.forEach(column => {
        const columnElement = createColumnElement(column);
        boardElement.appendChild(columnElement);
    });

    setupDragAndDrop();
}

// Create a column element
function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = column.id;

    const columnHeader = document.createElement('div');
    columnHeader.className = 'column-header';

    const columnTitle = document.createElement('h3');
    columnTitle.textContent = column.name;

    const columnActions = document.createElement('div');
    columnActions.className = 'column-actions';

    const editColumnBtn = document.createElement('button');
    editColumnBtn.innerHTML = '<i class="fas fa-edit"></i>';
    editColumnBtn.title = 'Edit column';
    editColumnBtn.addEventListener('click', () => editColumn(column.id));

    const deleteColumnBtn = document.createElement('button');
    deleteColumnBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteColumnBtn.title = 'Delete column';
    deleteColumnBtn.addEventListener('click', () => deleteColumn(column.id));

    columnActions.appendChild(editColumnBtn);
    columnActions.appendChild(deleteColumnBtn);

    columnHeader.appendChild(columnTitle);
    columnHeader.appendChild(columnActions);

    const tasksContainer = document.createElement('div');
    tasksContainer.className = 'column-tasks';

    column.tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        tasksContainer.appendChild(taskElement);
    });

    const addTaskBtn = document.createElement('button');
    addTaskBtn.className = 'add-task-btn';
    addTaskBtn.textContent = '+ Add Task';
    addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));

    columnElement.appendChild(columnHeader);
    columnElement.appendChild(tasksContainer);
    columnElement.appendChild(addTaskBtn);

    return columnElement;
}

// Create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;

    const taskHeader = document.createElement('div');
    taskHeader.className = 'task-header';

    const taskTitle = document.createElement('div');
    taskTitle.className = 'task-title';
    taskTitle.textContent = task.title;

    const taskPriority = document.createElement('div');
    taskPriority.className = `task-priority ${task.priority}`;
    taskPriority.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

    taskHeader.appendChild(taskTitle);
    taskHeader.appendChild(taskPriority);

    const taskDescription = document.createElement('div');
    taskDescription.className = 'task-description';
    taskDescription.textContent = task.description;

    const taskMeta = document.createElement('div');
    taskMeta.className = 'task-meta';

    const dueDate = document.createElement('span');
    dueDate.textContent = `Due: ${task.dueDate}`;

    const assignee = document.createElement('span');
    assignee.textContent = `Assigned: ${task.assignee}`;

    taskMeta.appendChild(dueDate);
    taskMeta.appendChild(assignee);

    taskElement.appendChild(taskHeader);
    taskElement.appendChild(taskDescription);
    taskElement.appendChild(taskMeta);

    // Add click event to open task details
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.task-priority')) {
            openTaskModal(task.id);
        }
    });

    return taskElement;
}

// Setup drag and drop functionality
function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    const columns = document.querySelectorAll('.column-tasks');

    tasks.forEach(task => {
        task.addEventListener('dragstart', () => {
            task.classList.add('dragging');
            setTimeout(() => {
                task.style.display = 'none';
            }, 0);
        });

        task.addEventListener('dragend', () => {
            task.classList.remove('dragging');
            task.style.display = 'block';
        });
    });

    columns.forEach(column => {
        column.addEventListener('dragover', e => {
            e.preventDefault();
            const draggingTask = document.querySelector('.dragging');
            const afterElement = getDragAfterElement(column, e.clientY);

            if (afterElement) {
                column.insertBefore(draggingTask, afterElement);
            } else {
                column.appendChild(draggingTask);
            }
        });

        column.addEventListener('drop', e => {
            e.preventDefault();
            const draggingTask = document.querySelector('.dragging');
            const columnId = column.closest('.column').dataset.columnId;
            const taskId = draggingTask.dataset.taskId;

            // Update the state
            moveTask(taskId, columnId);

            // Simulate real-time update
            simulateRealTimeUpdate();
        });
    });
}

// Helper function to get the element after which to insert the dragged task
function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Move task in the state
function moveTask(taskId, newColumnId) {
    // Find the task in the current state
    let taskToMove = null;
    let oldColumnIndex = -1;
    let taskIndex = -1;

    state.columns.forEach((column, columnIndex) => {
        const foundIndex = column.tasks.findIndex(task => task.id === taskId);
        if (foundIndex !== -1) {
            taskToMove = column.tasks[foundIndex];
            oldColumnIndex = columnIndex;
            taskIndex = foundIndex;
        }
    });

    if (taskToMove) {
        // Remove from old column
        state.columns[oldColumnIndex].tasks.splice(taskIndex, 1);

        // Add to new column
        const newColumnIndex = state.columns.findIndex(col => col.id === newColumnId);
        if (newColumnIndex !== -1) {
            state.columns[newColumnIndex].tasks.push(taskToMove);
        }

        // Update the UI
        renderBoard();
    }
}

// Open task modal for editing or creating a new task
function openTaskModal(taskId, columnId = null) {
    const task = taskId ? findTaskById(taskId) : null;

    if (task) {
        document.getElementById('task-id').value = task.id;
        document.getElementById('task-title').value = task.title;
        document.getElementById('task-description').value = task.description;
        document.getElementById('task-due-date').value = task.dueDate;
        document.getElementById('task-priority').value = task.priority;
        document.getElementById('task-assignee').value = task.assignee;
    } else {
        // Reset form for new task
        taskForm.reset();
        document.getElementById('task-id').value = generateId();
        // If columnId is provided, we're creating a task in a specific column
        if (columnId) {
            // We'll handle this in the form submission
        }
    }

    taskModal.style.display = 'flex';
}

// Find task by ID
function findTaskById(taskId) {
    for (const column of state.columns) {
        const task = column.tasks.find(t => t.id === taskId);
        if (task) return task;
    }
    return null;
}

// Close modal
function closeTaskModal() {
    taskModal.style.display = 'none';
}

// Save task
function saveTask(event) {
    event.preventDefault();

    const taskId = document.getElementById('task-id').value;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const dueDate = document.getElementById('task-due-date').value;
    const priority = document.getElementById('task-priority').value;
    const assignee = document.getElementById('task-assignee').value;

    const taskData = {
        id: taskId,
        title,
        description,
        dueDate,
        priority,
        assignee
    };

    // Check if this is a new task (not found in any column)
    let isNewTask = true;
    for (const column of state.columns) {
        if (column.tasks.some(t => t.id === taskId)) {
            isNewTask = false;
            break;
        }
    }

    if (isNewTask) {
        // Add to the first column (or you could modify to add to a specific column)
        if (state.columns.length > 0) {
            state.columns[0].tasks.push(taskData);
        }
    } else {
        // Update existing task
        for (const column of state.columns) {
            const taskIndex = column.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                column.tasks[taskIndex] = taskData;
                break;
            }
        }
    }

    closeTaskModal();
    renderBoard();

    // Simulate real-time update
    simulateRealTimeUpdate();
}

// Add a new column
function addColumn() {
    const columnName = newColumnNameInput.value.trim();
    if (columnName) {
        const newColumn = {
            id: generateId(),
            name: columnName,
            tasks: []
        };

        state.columns.push(newColumn);
        newColumnNameInput.value = '';
        renderBoard();

        // Simulate real-time update
        simulateRealTimeUpdate();
    }
}

// Edit column name
function editColumn(columnId) {
    const column = state.columns.find(col => col.id === columnId);
    if (column) {
        const newName = prompt('Enter new column name:', column.name);
        if (newName && newName.trim() !== '') {
            column.name = newName.trim();
            renderBoard();

            // Simulate real-time update
            simulateRealTimeUpdate();
        }
    }
}

// Delete column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column and all its tasks?')) {
        state.columns = state.columns.filter(col => col.id !== columnId);
        renderBoard();

        // Simulate real-time update
        simulateRealTimeUpdate();
    }
}

// Generate a unique ID
function generateId() {
    return 'id-' + Math.random().toString(36).substr(2, 9);
}

// Change user
function changeUser() {
    const newUser = prompt('Enter your name:', currentUser);
    if (newUser && newUser.trim() !== '') {
        currentUser = newUser.trim();
        updateCurrentUserDisplay();

        // Add to online users if not already there
        if (!onlineUsers.includes(currentUser)) {
            onlineUsers.push(currentUser);
        }

        // Simulate real-time update
        simulateRealTimeUpdate();
    }
}

// Update current user display
function updateCurrentUserDisplay() {
    currentUserElement.textContent = `User: ${currentUser}`;
}

// Simulate real-time updates (in a real app, this would use WebSockets)
function simulateRealTimeUpdate() {
    // In a real implementation, this would send the updated state to the server
    // and the server would broadcast to all connected clients

    // For this demo, we'll just simulate receiving an update after a short delay
    setTimeout(() => {
        // Simulate receiving an update from another user
        console.log('Simulating real-time update...');

        // For demo purposes, we'll just re-render the board
        renderBoard();
    }, 1000);
}

// Setup event listeners
function setupEventListeners() {
    addColumnBtn.addEventListener('click', addColumn);
    closeModal.addEventListener('click', closeTaskModal);
    taskForm.addEventListener('submit', saveTask);
    changeUserBtn.addEventListener('click', changeUser);

    // Close modal when clicking outside
    window.addEventListener('click', (event) => {
        if (event.target === taskModal) {
            closeTaskModal();
        }
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
```

