## JavaScript Implementation (`app.js`)

```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();

// DOM elements
const boardsContainer = document.getElementById('boardsContainer');
const createBoardBtn = document.getElementById('createBoardBtn');
const inviteBtn = document.getElementById('inviteBtn');
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const boardModal = new bootstrap.Modal(document.getElementById('boardModal'));
const inviteModal = new bootstrap.Modal(document.getElementById('inviteModal'));

// Current task being edited
let currentTask = null;
let currentBoardId = null;

// Initialize the app
function initApp() {
    // Load boards from Firestore
    loadBoards();

    // Set up event listeners
    setupEventListeners();
}

// Load boards from Firestore
function loadBoards() {
    db.collection('boards').orderBy('createdAt').onSnapshot((snapshot) => {
        boardsContainer.innerHTML = '';

        snapshot.forEach((doc) => {
            const board = doc.data();
            board.id = doc.id;
            renderBoard(board);
        });

        // Initialize drag-and-drop after boards are rendered
        setupDragAndDrop();
    });
}

// Render a single board
function renderBoard(board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'col-md-4';
    boardElement.innerHTML = `
        <div class="board" data-board-id="${board.id}">
            <div class="board-header">
                <h3 class="board-title">${board.name}</h3>
                <div class="dropdown">
                    <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
                        <i class="bi bi-three-dots-vertical"></i>
                    </button>
                    <ul class="dropdown-menu">
                        <li><a class="dropdown-item" href="#" onclick="editBoard('${board.id}')">Edit Board</a></li>
                        <li><a class="dropdown-item" href="#" onclick="deleteBoard('${board.id}')">Delete Board</a></li>
                    </ul>
                </div>
            </div>
            <div class="tasks-container" data-board-id="${board.id}">
                ${board.tasks ? board.tasks.map(task => renderTask(task)).join('') : ''}
            </div>
            <button class="btn btn-sm btn-outline-primary add-task-btn" onclick="addTask('${board.id}')">
                <i class="bi bi-plus"></i> Add Task
            </button>
        </div>
    `;

    boardsContainer.appendChild(boardElement);
}

// Render a single task
function renderTask(task) {
    return `
        <div class="task" data-task-id="${task.id}" onclick="editTask('${task.id}')">
            <div class="task-title">${task.title}</div>
            <div class="task-meta">
                <span class="priority-${task.priority}">${task.priority}</span>
                ${task.dueDate ? ` | Due: ${new Date(task.dueDate).toLocaleDateString()}` : ''}
                ${task.assignee ? ` | ${task.assignee}` : ''}
            </div>
        </div>
    `;
}

// Set up drag-and-drop functionality
function setupDragAndDrop() {
    const containers = document.querySelectorAll('.tasks-container');

    // Initialize dragula
    dragula([...containers], {
        moves: function (el, container, handle) {
            return el.classList.contains('task');
        },
        accepts: function (el, target, source, sibling) {
            return target.classList.contains('tasks-container');
        }
    })
    .on('drop', function (el, target, source, sibling) {
        const taskId = el.getAttribute('data-task-id');
        const newBoardId = target.getAttribute('data-board-id');

        // Update task in Firestore
        updateTaskBoard(taskId, newBoardId);
    });
}

// Update task's board in Firestore
function updateTaskBoard(taskId, newBoardId) {
    // First, get the task document
    db.collection('tasks').doc(taskId).get().then((doc) => {
        if (doc.exists) {
            const taskData = doc.data();

            // Remove from old board's tasks array
            if (taskData.boardId) {
                db.collection('boards').doc(taskData.boardId).update({
                    tasks: firebase.firestore.FieldValue.arrayRemove(taskId)
                });
            }

            // Add to new board's tasks array
            db.collection('boards').doc(newBoardId).update({
                tasks: firebase.firestore.FieldValue.arrayAdd(taskId)
            });

            // Update the task's boardId
            db.collection('tasks').doc(taskId).update({
                boardId: newBoardId
            });
        }
    });
}

// Add a new task to a board
function addTask(boardId) {
    currentBoardId = boardId;
    currentTask = null;

    // Reset form
    document.getElementById('taskForm').reset();

    // Show modal
    taskModal.show();
}

// Edit an existing task
function editTask(taskId) {
    // Get task data from Firestore
    db.collection('tasks').doc(taskId).get().then((doc) => {
        if (doc.exists) {
            const task = doc.data();
            task.id = doc.id;
            currentTask = task;
            currentBoardId = task.boardId;

            // Populate form
            document.getElementById('taskTitle').value = task.title || '';
            document.getElementById('taskDescription').value = task.description || '';
            document.getElementById('taskPriority').value = task.priority || 'medium';
            document.getElementById('taskDueDate').value = task.dueDate || '';
            document.getElementById('taskAssignee').value = task.assignee || '';

            // Show modal
            taskModal.show();
        }
    });
}

// Save task to Firestore
function saveTask() {
    const title = document.getElementById('taskTitle').value;
    const description = document.getElementById('taskDescription').value;
    const priority = document.getElementById('taskPriority').value;
    const dueDate = document.getElementById('taskDueDate').value;
    const assignee = document.getElementById('taskAssignee').value;

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    const taskData = {
        title,
        description,
        priority,
        dueDate,
        assignee,
        boardId: currentBoardId,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (currentTask) {
        // Update existing task
        db.collection('tasks').doc(currentTask.id).update(taskData);
    } else {
        // Create new task
        db.collection('tasks').add(taskData).then((docRef) => {
            // Add task reference to the board
            db.collection('boards').doc(currentBoardId).update({
                tasks: firebase.firestore.FieldValue.arrayUnion(docRef.id)
            });
        });
    }

    // Close modal
    taskModal.hide();
}

// Create a new board
function createBoard() {
    // Reset form
    document.getElementById('boardForm').reset();

    // Show modal
    boardModal.show();
}

// Save board to Firestore
function saveBoard() {
    const name = document.getElementById('boardName').value;
    const description = document.getElementById('boardDescription').value;

    if (!name) {
        alert('Please enter a board name');
        return;
    }

    const boardData = {
        name,
        description,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
        tasks: []
    };

    // Add board to Firestore
    db.collection('boards').add(boardData);

    // Close modal
    boardModal.hide();
}

// Delete a board
function deleteBoard(boardId) {
    if (confirm('Are you sure you want to delete this board? All tasks will be deleted.')) {
        // First delete all tasks in the board
        db.collection('boards').doc(boardId).get().then((doc) => {
            if (doc.exists) {
                const board = doc.data();
                if (board.tasks && board.tasks.length > 0) {
                    const batch = db.batch();
                    board.tasks.forEach(taskId => {
                        batch.delete(db.collection('tasks').doc(taskId));
                    });
                    batch.commit();
                }
            }
        }).then(() => {
            // Then delete the board
            db.collection('boards').doc(boardId).delete();
        });
    }
}

// Invite collaborators
function inviteCollaborator() {
    // Show modal
    inviteModal.show();
}

// Send invite
function sendInvite() {
    const email = document.getElementById('inviteEmail').value;
    const role = document.getElementById('inviteRole').value;

    if (!email) {
        alert('Please enter an email address');
        return;
    }

    // In a real app, you would send an invitation email here
    console.log(`Inviting ${email} as ${role}`);

    // Close modal
    inviteModal.hide();
}

// Set up event listeners
function setupEventListeners() {
    createBoardBtn.addEventListener('click', createBoard);
    inviteBtn.addEventListener('click', inviteCollaborator);

    document.getElementById('saveTaskBtn').addEventListener('click', saveTask);
    document.getElementById('saveBoardBtn').addEventListener('click', saveBoard);
    document.getElementById('sendInviteBtn').addEventListener('click', sendInvite);

    // Make functions available globally for onclick handlers
    window.addTask = addTask;
    window.editTask = editTask;
    window.editBoard = editBoard;
    window.deleteBoard = deleteBoard;
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
