let currentTask = null;
let currentBoard = null;

// Initialize the app
function init() {
    // Load data from localStorage
    const savedData = localStorage.getItem('taskBoardData');
    if (savedData) {
        boards = JSON.parse(savedData);
    } else {
        // Create default boards if none exist
        boards = [
            { id: generateId(), title: 'To Do', tasks: [] },
            { id: generateId(), title: 'In Progress', tasks: [] },
            { id: generateId(), title: 'Done', tasks: [] }
        ];
    }

    // Render boards
    renderBoards();

    // Set up event listeners
    setupEventListeners();

    // Join a room for real-time collaboration
    socket.emit('joinRoom', 'projectRoom');
}

// Generate a unique ID
function generateId() {
    return Math.random().toString(36).substr(2, 9);
}

// Render all boards
function renderBoards() {
    boardsContainer.innerHTML = '';

    boards.forEach(board => {
        const boardElement = document.createElement('div');
        boardElement.className = 'board-container';
        boardElement.innerHTML = `
            <div class="board" data-board-id="${board.id}">
                <div class="board-header">
                    <h3 class="board-title">${board.title}</h3>
                    <div class="board-actions">
                        <button class="btn btn-sm btn-outline-secondary edit-board-btn" data-board-id="${board.id}">✏️</button>
                        <button class="btn btn-sm btn-outline-danger delete-board-btn" data-board-id="${board.id}">🗑️</button>
                    </div>
                </div>
                <div class="tasks-container" data-board-id="${board.id}">
                    ${board.tasks.length === 0 ? '<div class="empty-board">No tasks yet</div>' : ''}
                </div>
            </div>
        `;

        boardsContainer.appendChild(boardElement);

        // Render tasks for this board
        const tasksContainer = boardElement.querySelector('.tasks-container');
        renderTasks(board.id, tasksContainer);
    });

    // Make tasks draggable
    setupDragAndDrop();
}

// Render tasks for a specific board
function renderTasks(boardId, container) {
    const board = boards.find(b => b.id === boardId);
    if (!board) return;

    container.innerHTML = '';

    if (board.tasks.length === 0) {
        container.innerHTML = '<div class="empty-board">No tasks yet</div>';
        return;
    }

    board.tasks.forEach(task => {
        const taskElement = document.createElement('div');
        taskElement.className = `task priority-${task.priority}`;
        taskElement.draggable = true;
        taskElement.dataset.taskId = task.id;
        taskElement.dataset.boardId = boardId;
        taskElement.innerHTML = `
            <div class="task-title">${task.title}</div>
            <div class="task-description">${task.description || ''}</div>
            <div class="task-assignee">${task.assignee ? `Assigned to: ${task.assignee}` : ''}</div>
        `;
        container.appendChild(taskElement);
    });
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    const boards = document.querySelectorAll('.tasks-container');

    tasks.forEach(task => {
        task.addEventListener('dragstart', (e) => {
            e.dataTransfer.setData('text/plain', task.dataset.taskId);
            e.dataTransfer.setData('boardId', task.dataset.boardId);
            setTimeout(() => {
                task.style.opacity = '0.4';
            }, 0);
        });

        task.addEventListener('dragend', () => {
            task.style.opacity = '1';
        });

        task.addEventListener('click', () => {
            currentTask = boards.find(b => b.id === task.dataset.boardId)
                .tasks.find(t => t.id === task.dataset.taskId);
            currentBoard = task.dataset.boardId;
            showTaskModal(currentTask);
        });
    });

    boards.forEach(board => {
        board.addEventListener('dragover', (e) => {
            e.preventDefault();
            board.style.backgroundColor = '#f0f8ff';
        });

        board.addEventListener('dragleave', () => {
            board.style.backgroundColor = '';
        });

        board.addEventListener('drop', (e) => {
            e.preventDefault();
            board.style.backgroundColor = '';

            const taskId = e.dataTransfer.getData('text/plain');
            const sourceBoardId = e.dataTransfer.getData('boardId');
            const targetBoardId = board.dataset.boardId;

            if (sourceBoardId === targetBoardId) return;

            moveTask(taskId, sourceBoardId, targetBoardId);
        });
    });
}

// Move a task between boards
function moveTask(taskId, sourceBoardId, targetBoardId) {
    const sourceBoard = boards.find(b => b.id === sourceBoardId);
    const targetBoard = boards.find(b => b.id === targetBoardId);

    if (!sourceBoard || !targetBoard) return;

    const taskIndex = sourceBoard.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceBoard.tasks.splice(taskIndex, 1);
    targetBoard.tasks.push(task);

    // Update the UI
    renderBoards();

    // Save to localStorage
    saveData();

    // Notify other clients via WebSocket
    socket.emit('taskMoved', {
        taskId,
        sourceBoardId,
        targetBoardId,
        room: 'projectRoom'
    });
}

// Show the task modal
function showTaskModal(task = null) {
    if (task) {
        document.getElementById('taskId').value = task.id;
        document.getElementById('taskTitle').value = task.title;
        document.getElementById('taskDescription').value = task.description || '';
        document.getElementById('taskPriority').value = task.priority || 'medium';
        document.getElementById('taskAssignee').value = task.assignee || '';
    } else {
        taskForm.reset();
        document.getElementById('taskId').value = '';
    }

    taskModal.show();
}

// Show the board modal
function showBoardModal(board = null) {
    if (board) {
        document.getElementById('boardId').value = board.id;
        document.getElementById('boardTitle').value = board.title;
    } else {
        boardForm.reset();
        document.getElementById('boardId').value = '';
    }

    boardModal.show();
}

// Save data to localStorage
function saveData() {
    localStorage.setItem('taskBoardData', JSON.stringify(boards));
}

// Set up event listeners
function setupEventListeners() {
    // Add board button
    addBoardBtn.addEventListener('click', () => {
        showBoardModal();
    });

    // Add task button
    addTaskBtn.addEventListener('click', () => {
        if (boards.length === 0) {
            alert('Please create a board first');
            return;
        }
        currentTask = null;
        currentBoard = boards[0].id; // Default to first board
        showTaskModal();
    });

    // Save task button
    saveTaskBtn.addEventListener('click', () => {
        if (!taskForm.checkValidity()) {
            taskForm.reportValidity();
            return;
        }

        const taskId = document.getElementById('taskId').value;
        const boardId = currentBoard || document.getElementById('boardId').value;
        const title = document.getElementById('taskTitle').value;
        const description = document.getElementById('taskDescription').value;
        const priority = document.getElementById('taskPriority').value;
        const assignee = document.getElementById('taskAssignee').value;

        if (taskId) {
            // Update existing task
            const board = boards.find(b => b.id === boardId);
            if (board) {
                const task = board.tasks.find(t => t.id === taskId);
                if (task) {
                    task.title = title;
                    task.description = description;
                    task.priority = priority;
                    task.assignee = assignee;

                    // Notify other clients
                    socket.emit('taskUpdated', {
                        task,
                        boardId,
                        room: 'projectRoom'
                    });
                }
            }
        } else {
            // Create new task
            const newTask = {
                id: generateId(),
                title,
                description,
                priority,
                assignee
            };

            const board = boards.find(b => b.id === boardId);
            if (board) {
                board.tasks.push(newTask);

                // Notify other clients
                socket.emit('taskAdded', {
                    task: newTask,
                    boardId,
                    room: 'projectRoom'
                });
            }
        }

        // Update UI
        renderBoards();

        // Save to localStorage
        saveData();

        taskModal.hide();
    });

    // Save board button
    saveBoardBtn.addEventListener('click', () => {
        if (!boardForm.checkValidity()) {
            boardForm.reportValidity();
            return;
        }

        const boardId = document.getElementById('boardId').value;
        const title = document.getElementById('boardTitle').value;

        if (boardId) {
            // Update existing board
            const board = boards.find(b => b.id === boardId);
            if (board) {
                board.title = title;

                // Notify other clients
                socket.emit('boardUpdated', {
                    board,
                    room: 'projectRoom'
                });
            }
        } else {
            // Create new board
            const newBoard = {
                id: generateId(),
                title,
                tasks: []
            };

            boards.push(newBoard);

            // Notify other clients
            socket.emit('boardAdded', {
                board: newBoard,
                room: 'projectRoom'
            });
        }

        // Update UI
        renderBoards();

        // Save to localStorage
        saveData();

        boardModal.hide();
    });

    // Edit board buttons
    boardsContainer.addEventListener('click', (e) => {
        if (e.target.classList.contains('edit-board-btn')) {
            const boardId = e.target.dataset.boardId;
            const board = boards.find(b => b.id === boardId);
            if (board) {
                showBoardModal(board);
            }
        }

        // Delete board buttons
        if (e.target.classList.contains('delete-board-btn')) {
            const boardId = e.target.dataset.boardId;
            if (confirm('Are you sure you want to delete this board and all its tasks?')) {
                const boardIndex = boards.findIndex(b => b.id === boardId);
                if (boardIndex !== -1) {
                    boards.splice(boardIndex, 1);

                    // Notify other clients
                    socket.emit('boardDeleted', {
                        boardId,
                        room: 'projectRoom'
                    });

                    // Update UI
                    renderBoards();

                    // Save to localStorage
                    saveData();
                }
            }
        }
    });

    // Socket.IO event listeners
    socket.on('taskAdded', ({ task, boardId }) => {
        const board = boards.find(b => b.id === boardId);
        if (board) {
            board.tasks.push(task);
            renderBoards();
            saveData();
        }
    });

    socket.on('taskUpdated', ({ task, boardId }) => {
        const board = boards.find(b => b.id === boardId);
        if (board) {
            const existingTask = board.tasks.find(t => t.id === task.id);
            if (existingTask) {
                Object.assign(existingTask, task);
                renderBoards();
                saveData();
            }
        }
    });

    socket.on('taskMoved', ({ taskId, sourceBoardId, targetBoardId }) => {
        moveTask(taskId, sourceBoardId, targetBoardId);
    });

    socket.on('boardAdded', ({ board }) => {
        boards.push(board);
        renderBoards();
        saveData();
    });

    socket.on('boardUpdated', ({ board }) => {
        const existingBoard = boards.find(b => b.id === board.id);
        if (existingBoard) {
            existingBoard.title = board.title;
            renderBoards();
            saveData();
        }
    });

    socket.on('boardDeleted', ({ boardId }) => {
        const boardIndex = boards.findIndex(b => b.id === boardId);
        if (boardIndex !== -1) {
            boards.splice(boardIndex, 1);
            renderBoards();
            saveData();
        }
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
```

## 4. Node.js Backend (server.js)

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(path.join(__dirname)));

// Socket.IO connection
io.on('connection', (socket) => {
    console.log('A user connected');

    // Join a room
    socket.on('joinRoom', (room) => {
        socket.join(room);
        console.log(`User joined room: ${room}`);
    });

    // Task events
    socket.on('taskAdded', (data) => {
        socket.to(data.room).emit('taskAdded', data);
    });

    socket.on('taskUpdated', (data) => {
        socket.to(data.room).emit('taskUpdated', data);
    });

    socket.on('taskMoved', (data) => {
        socket.to(data.room).emit('taskMoved', data);
    });

    // Board events
    socket.on('boardAdded', (data) => {
        socket.to(data.room).emit('boardAdded', data);
    });

    socket.on('boardUpdated', (data) => {
        socket.to(data.room).emit('boardUpdated', data);
    });

    socket.on('boardDeleted', (data) => {
        socket.to(data.room).emit('boardDeleted', data);
    });

    socket.on('disconnect', () => {
        console.log('User disconnected');
    });
});

// Start the server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
