    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const boardsContainer = document.getElementById('boardsContainer');
const addBoardBtn = document.getElementById('addBoardBtn');
const addTaskBtn = document.getElementById('addTaskBtn');
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const boardModal = new bootstrap.Modal(document.getElementById('boardModal'));

// Task modal elements
const taskForm = document.getElementById('taskForm');
const taskIdInput = document.getElementById('taskId');
const taskTitleInput = document.getElementById('taskTitle');
const taskDescriptionInput = document.getElementById('taskDescription');
const taskPriorityInput = document.getElementById('taskPriority');
const taskAssigneeInput = document.getElementById('taskAssignee');
const taskDueDateInput = document.getElementById('taskDueDate');
const saveTaskBtn = document.getElementById('saveTaskBtn');

// Board modal elements
const boardForm = document.getElementById('boardForm');
const boardIdInput = document.getElementById('boardId');
const boardTitleInput = document.getElementById('boardTitle');
const boardDescriptionInput = document.getElementById('boardDescription');
const saveBoardBtn = document.getElementById('saveBoardBtn');

// Initialize Dragula
const drake = dragula({
    isContainer: function (el) {
        return el.classList.contains('board-body');
    },
    moves: function (el, container, handle) {
        return el.classList.contains('task-card');
    }
});

// Current board being edited
let currentBoardId = null;

// Load boards from Firebase on page load
database.ref('boards').on('value', (snapshot) => {
    boardsContainer.innerHTML = '';
    const boards = snapshot.val() || {};

    Object.entries(boards).forEach(([boardId, board]) => {
        addBoardToDOM(boardId, board);
    });

    // Initialize drag-and-drop after boards are loaded
    setupDragAndDrop();
});

// Add board to DOM
function addBoardToDOM(boardId, board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'col-md-4';
    boardElement.innerHTML = `
        <div class="board" data-board-id="${boardId}">
            <div class="board-header">
                <h3 class="board-title">${board.title}</h3>
                <div class="board-actions">
                    <button class="btn btn-sm btn-outline-primary edit-board-btn">Edit</button>
                    <button class="btn btn-sm btn-outline-danger delete-board-btn">Delete</button>
                </div>
            </div>
            <div class="board-body" data-board-id="${boardId}">
                ${board.tasks ? Object.entries(board.tasks).map(([taskId, task]) => `
                    <div class="task-card" data-task-id="${taskId}" data-board-id="${boardId}">
                        <h5 class="task-title">${task.title}</h5>
                        <div class="task-meta">
                            <span class="priority-${task.priority}">${task.priority}</span>
                            <span>${task.assignee || 'Unassigned'}</span>
                        </div>
                    </div>
                `).join('') : ''}
            </div>
        </div>
    `;

    boardsContainer.appendChild(boardElement);

    // Add event listeners for board actions
    boardElement.querySelector('.edit-board-btn').addEventListener('click', () => {
        currentBoardId = boardId;
        boardIdInput.value = boardId;
        boardTitleInput.value = board.title;
        boardDescriptionInput.value = board.description || '';
        boardModal.show();
    });

    boardElement.querySelector('.delete-board-btn').addEventListener('click', () => {
        if (confirm('Are you sure you want to delete this board and all its tasks?')) {
            database.ref(`boards/${boardId}`).remove();
        }
    });

    // Add event listeners for task cards
    boardElement.querySelectorAll('.task-card').forEach(taskCard => {
        taskCard.addEventListener('click', (e) => {
            if (!e.target.classList.contains('delete-task-btn')) {
                const taskId = taskCard.getAttribute('data-task-id');
                const boardId = taskCard.getAttribute('data-board-id');
                openTaskModal(boardId, taskId);
            }
        });
    });
}

// Setup drag-and-drop functionality
function setupDragAndDrop() {
    drake.off('drop').on('drop', (el, target, source, sibling) => {
        const taskId = el.getAttribute('data-task-id');
        const oldBoardId = source.getAttribute('data-board-id');
        const newBoardId = target.getAttribute('data-board-id');

        if (oldBoardId !== newBoardId) {
            // Task moved to a different board
            const taskRef = database.ref(`boards/${oldBoardId}/tasks/${taskId}`);
            taskRef.once('value', (snapshot) => {
                const taskData = snapshot.val();
                if (taskData) {
                    // Remove from old board
                    taskRef.remove();

                    // Add to new board
                    database.ref(`boards/${newBoardId}/tasks/${taskId}`).set(taskData);
                }
            });
        }
    });
}

// Add new board
addBoardBtn.addEventListener('click', () => {
    currentBoardId = null;
    boardForm.reset();
    boardModal.show();
});

// Save board
saveBoardBtn.addEventListener('click', () => {
    if (boardForm.checkValidity()) {
        const boardId = boardIdInput.value || database.ref('boards').push().key;
        const boardData = {
            title: boardTitleInput.value,
            description: boardDescriptionInput.value
        };

        database.ref(`boards/${boardId}`).update(boardData);
        boardModal.hide();
    } else {
        boardForm.reportValidity();
    }
});

// Add new task
addTaskBtn.addEventListener('click', () => {
    if (boardsContainer.children.length === 0) {
        alert('Please create a board first.');
        return;
    }

    currentBoardId = boardsContainer.firstElementChild.querySelector('.board-body').getAttribute('data-board-id');
    taskForm.reset();
    taskIdInput.value = '';
    taskModal.show();
});

// Open task modal for editing
function openTaskModal(boardId, taskId) {
    currentBoardId = boardId;

    if (taskId) {
        // Edit existing task
        database.ref(`boards/${boardId}/tasks/${taskId}`).once('value', (snapshot) => {
            const task = snapshot.val();
            if (task) {
                taskIdInput.value = taskId;
                taskTitleInput.value = task.title;
                taskDescriptionInput.value = task.description || '';
                taskPriorityInput.value = task.priority || 'medium';
                taskAssigneeInput.value = task.assignee || '';
                taskDueDateInput.value = task.dueDate || '';
                taskModal.show();
            }
        });
    } else {
        // Add new task
        taskForm.reset();
        taskIdInput.value = '';
        taskModal.show();
    }
}

// Save task
saveTaskBtn.addEventListener('click', () => {
    if (taskForm.checkValidity()) {
        const taskId = taskIdInput.value || database.ref(`boards/${currentBoardId}/tasks`).push().key;
        const taskData = {
            title: taskTitleInput.value,
            description: taskDescriptionInput.value,
            priority: taskPriorityInput.value,
            assignee: taskAssigneeInput.value,
            dueDate: taskDueDateInput.value
        };

        database.ref(`boards/${currentBoardId}/tasks/${taskId}`).update(taskData);
        taskModal.hide();
    } else {
        taskForm.reportValidity();
    }
});
