## JavaScript (app.js)

```javascript
// Initialize Socket.IO connection
const socket = io();

// DOM Elements
const todoList = document.getElementById('todo-list');
const inProgressList = document.getElementById('in-progress-list');
const doneList = document.getElementById('done-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const taskModal = document.getElementById('task-modal');
const closeBtn = document.querySelector('.close-btn');
const taskForm = document.getElementById('task-form');
const taskIdInput = document.getElementById('task-id');
const taskBoardInput = document.getElementById('task-board');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskPriorityInput = document.getElementById('task-priority');
const taskDueDateInput = document.getElementById('task-due-date');
const taskAssigneeInput = document.getElementById('task-assignee');
const usernameDisplay = document.getElementById('username');
const changeNameBtn = document.getElementById('change-name-btn');
const onlineUsersList = document.getElementById('online-users');

// Initialize Dragula for drag-and-drop
const drake = dragula([todoList, inProgressList, doneList], {
    moves: function(el, container, handle) {
        return !el.classList.contains('task-actions'); // Prevent dragging from action buttons
    },
    accepts: function(el, target, source, sibling) {
        return true; // Allow all moves
    }
});

// Task data storage
let tasks = JSON.parse(localStorage.getItem('tasks')) || {
    todo: [],
    'in-progress': [],
    done: []
};

// User data
let currentUser = localStorage.getItem('username') || 'Guest';
usernameDisplay.textContent = currentUser;

// Initialize the app
function init() {
    loadTasks();
    setupEventListeners();
    updateOnlineUsers();
}

// Load tasks from localStorage
function loadTasks() {
    Object.keys(tasks).forEach(board => {
        tasks[board].forEach(task => {
            renderTask(task, board);
        });
    });
}

// Render a task card
function renderTask(task, board) {
    const taskCard = document.createElement('div');
    taskCard.className = 'task-card';
    taskCard.dataset.id = task.id;
    taskCard.dataset.board = board;

    const priorityClass = `priority-${task.priority}`;

    taskCard.innerHTML = `
        <div class="task-card-header">
            <span class="task-title">${task.title}</span>
            <span class="task-priority ${priorityClass}">${task.priority}</span>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span>${task.dueDate ? `Due: ${task.dueDate}` : ''}</span>
            <span>${task.assignee ? `Assigned: ${task.assignee}` : ''}</span>
        </div>
        <div class="task-actions">
            <button class="task-action-btn edit-btn" data-id="${task.id}"><i class="fas fa-edit"></i></button>
            <button class="task-action-btn delete-btn" data-id="${task.id}"><i class="fas fa-trash"></i></button>
        </div>
    `;

    const boardList = document.getElementById(`${board}-list`);
    boardList.appendChild(taskCard);
}

// Save tasks to localStorage
function saveTasks() {
    localStorage.setItem('tasks', JSON.stringify(tasks));
}

// Setup event listeners
function setupEventListeners() {
    // Add task buttons
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const board = btn.dataset.board;
            openTaskModal(null, board);
        });
    });

    // Close modal
    closeBtn.addEventListener('click', () => {
        taskModal.style.display = 'none';
    });

    // Form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();
        saveTask();
    });

    // Edit task buttons (delegated event listener)
    document.addEventListener('click', (e) => {
        if (e.target.closest('.edit-btn')) {
            const taskId = e.target.closest('.edit-btn').dataset.id;
            const board = e.target.closest('.task-card').dataset.board;
            const task = findTaskById(taskId, board);
            openTaskModal(task, board);
        }

        if (e.target.closest('.delete-btn')) {
            const taskId = e.target.closest('.delete-btn').dataset.id;
            const board = e.target.closest('.task-card').dataset.board;
            deleteTask(taskId, board);
        }
    });

    // Change username
    changeNameBtn.addEventListener('click', () => {
        const newName = prompt('Enter your name:', currentUser);
        if (newName && newName.trim() !== '') {
            currentUser = newName.trim();
            usernameDisplay.textContent = currentUser;
            localStorage.setItem('username', currentUser);
            socket.emit('user update', currentUser);
        }
    });

    // Dragula events
    drake.on('drop', (el, target, source, sibling) => {
        const taskId = el.dataset.id;
        const oldBoard = source.parentElement.id.replace('-list', '');
        const newBoard = target.parentElement.id.replace('-list', '');

        // Update task in local data
        const taskIndex = tasks[oldBoard].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            const [task] = tasks[oldBoard].splice(taskIndex, 1);
            tasks[newBoard].push(task);
            saveTasks();

            // Emit event to other clients
            socket.emit('task moved', {
                taskId,
                oldBoard,
                newBoard,
                user: currentUser
            });
        }
    });
}

// Open task modal for editing or creating
function openTaskModal(task, board) {
    if (task) {
        document.getElementById('modal-title').textContent = 'Edit Task';
        taskIdInput.value = task.id;
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description || '';
        taskPriorityInput.value = task.priority;
        taskDueDateInput.value = task.dueDate || '';
        taskAssigneeInput.value = task.assignee || '';
    } else {
        document.getElementById('modal-title').textContent = 'Add New Task';
        taskIdInput.value = '';
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskPriorityInput.value = 'medium';
        taskDueDateInput.value = '';
        taskAssigneeInput.value = '';
    }

    taskBoardInput.value = board;
    taskModal.style.display = 'flex';
}

// Save task (create or update)
function saveTask() {
    const taskId = taskIdInput.value;
    const board = taskBoardInput.value;
    const title = taskTitleInput.value.trim();
    const description = taskDescriptionInput.value.trim();
    const priority = taskPriorityInput.value;
    const dueDate = taskDueDateInput.value;
    const assignee = taskAssigneeInput.value.trim();

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (taskId) {
        // Update existing task
        const taskIndex = tasks[board].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            tasks[board][taskIndex] = {
                ...tasks[board][taskIndex],
                title,
                description,
                priority,
                dueDate,
                assignee
            };

            // Update the DOM
            const taskCard = document.querySelector(`.task-card[data-id="${taskId}"]`);
            if (taskCard) {
                const priorityClass = `priority-${priority}`;
                taskCard.querySelector('.task-title').textContent = title;
                taskCard.querySelector('.task-description').textContent = description;
                taskCard.querySelector('.task-priority').textContent = priority;
                taskCard.querySelector('.task-priority').className = `task-priority ${priorityClass}`;
                taskCard.querySelector('.task-meta').innerHTML = `
                    <span>${dueDate ? `Due: ${dueDate}` : ''}</span>
                    <span>${assignee ? `Assigned: ${assignee}` : ''}</span>
                `;
            }

            // Emit update to other clients
            socket.emit('task updated', {
                task: tasks[board][taskIndex],
                board,
                user: currentUser
            });
        }
    } else {
        // Create new task
        const newTask = {
            id: Date.now().toString(),
            title,
            description,
            priority,
            dueDate,
            assignee,
            createdBy: currentUser,
            createdAt: new Date().toISOString()
        };

        tasks[board].push(newTask);
        renderTask(newTask, board);

        // Emit creation to other clients
        socket.emit('task created', {
            task: newTask,
            board,
            user: currentUser
        });
    }

    saveTasks();
    taskModal.style.display = 'none';
}

// Delete a task
function deleteTask(taskId, board) {
    if (confirm('Are you sure you want to delete this task?')) {
        const taskIndex = tasks[board].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            tasks[board].splice(taskIndex, 1);
            saveTasks();

            // Remove from DOM
            const taskCard = document.querySelector(`.task-card[data-id="${taskId}"]`);
            if (taskCard) {
                taskCard.remove();
            }

            // Emit deletion to other clients
            socket.emit('task deleted', {
                taskId,
                board,
                user: currentUser
            });
        }
    }
}

// Find task by ID
function findTaskById(taskId, board) {
    return tasks[board].find(t => t.id === taskId);
}

// Socket.IO event handlers
socket.on('connect', () => {
    console.log('Connected to server');
    socket.emit('user connected', currentUser);

    // Request current state from server
    socket.emit('request state');
});

socket.on('user connected', (username) => {
    updateOnlineUsers();
});

socket.on('user disconnected', (username) => {
    updateOnlineUsers();
});

socket.on('user update', (username) => {
    updateOnlineUsers();
});

socket.on('task created', ({ task, board, user }) => {
    if (user !== currentUser) {
        tasks[board].push(task);
        renderTask(task, board);
        saveTasks();
    }
});

socket.on('task updated', ({ task, board, user }) => {
    if (user !== currentUser) {
        const taskIndex = tasks[board].findIndex(t => t.id === task.id);
        if (taskIndex !== -1) {
            tasks[board][taskIndex] = task;
            saveTasks();

            // Update DOM
            const taskCard = document.querySelector(`.task-card[data-id="${task.id}"]`);
            if (taskCard) {
                const priorityClass = `priority-${task.priority}`;
                taskCard.querySelector('.task-title').textContent = task.title;
                taskCard.querySelector('.task-description').textContent = task.description;
                taskCard.querySelector('.task-priority').textContent = task.priority;
                taskCard.querySelector('.task-priority').className = `task-priority ${priorityClass}`;
                taskCard.querySelector('.task-meta').innerHTML = `
                    <span>${task.dueDate ? `Due: ${task.dueDate}` : ''}</span>
                    <span>${task.assignee ? `Assigned: ${task.assignee}` : ''}</span>
                `;
            }
        }
    }
});

socket.on('task moved', ({ taskId, oldBoard, newBoard, user }) => {
    if (user !== currentUser) {
        const taskIndex = tasks[oldBoard].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            const [task] = tasks[oldBoard].splice(taskIndex, 1);
            tasks[newBoard].push(task);
            saveTasks();

            // Update DOM
            const taskCard = document.querySelector(`.task-card[data-id="${taskId}"]`);
            if (taskCard) {
                const newBoardList = document.getElementById(`${newBoard}-list`);
                newBoardList.appendChild(taskCard);
                taskCard.dataset.board = newBoard;
            }
        }
    }
});

socket.on('task deleted', ({ taskId, board, user }) => {
    if (user !== currentUser) {
        const taskIndex = tasks[board].findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            tasks[board].splice(taskIndex, 1);
            saveTasks();

            // Remove from DOM
            const taskCard = document.querySelector(`.task-card[data-id="${taskId}"]`);
            if (taskCard) {
                taskCard.remove();
            }
        }
    }
});

socket.on('current state', (state) => {
    tasks = state;
    saveTasks();
    // Reload the UI
    todoList.innerHTML = '';
    inProgressList.innerHTML = '';
    doneList.innerHTML = '';
    loadTasks();
});

socket.on('online users', (users) => {
    updateOnlineUsers(users);
});

// Update online users list
function updateOnlineUsers(users) {
    if (!users) {
        socket.emit('request online users');
        return;
    }

    onlineUsersList.innerHTML = '';
    users.forEach(user => {
        const li = document.createElement('li');
        li.innerHTML = `
            <span class="online-indicator"></span>
            <span>${user}</span>
        `;
        onlineUsersList.appendChild(li);
    });
}

// Initialize the app when DOM is loaded
document.addEventListener('DOMContentLoaded', init);
