## Server Setup (server.js)

For a complete implementation, you would need a server to handle the real-time collaboration. Here's a basic Node.js server using Express and Socket.IO:

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Store tasks in memory (in a real app, use a database)
let tasks = {
    todo: [],
    'in-progress': [],
    done: []
};

// Store connected users
let onlineUsers = {};

app.use(express.static(path.join(__dirname, 'public')));

io.on('connection', (socket) => {
    console.log('New client connected');

    // Handle user connection
    socket.on('user connected', (username) => {
        onlineUsers[socket.id] = username;
        io.emit('user connected', username);
        io.emit('online users', Object.values(onlineUsers));
    });

    // Handle user disconnection
    socket.on('disconnect', () => {
        const username = onlineUsers[socket.id];
        delete onlineUsers[socket.id];
        io.emit('user disconnected', username);
        io.emit('online users', Object.values(onlineUsers));
    });

    // Handle user name change
    socket.on('user update', (username) => {
        onlineUsers[socket.id] = username;
        io.emit('user update', username);
        io.emit('online users', Object.values(onlineUsers));
    });

    // Handle task creation
    socket.on('task created', (data) => {
        tasks[data.board].push(data.task);
        socket.broadcast.emit('task created', data);
    });

    // Handle task update
    socket.on('task updated', (data) => {
        const taskIndex = tasks[data.board].findIndex(t => t.id === data.task.id);
        if (taskIndex !== -1) {
            tasks[data.board][taskIndex] = data.task;
            socket.broadcast.emit('task updated', data);
        }
    });

    // Handle task movement
    socket.on('task moved', (data) => {
        const taskIndex = tasks[data.oldBoard].findIndex(t => t.id === data.taskId);
        if (taskIndex !== -1) {
            const [task] = tasks[data.oldBoard].splice(taskIndex, 1);
            tasks[data.newBoard].push(task);
            socket.broadcast.emit('task moved', data);
        }
    });

    // Handle task deletion
    socket.on('task deleted', (data) => {
        const taskIndex = tasks[data.board].findIndex(t => t.id === data.taskId);
        if (taskIndex !== -1) {
            tasks[data.board].splice(taskIndex, 1);
            socket.broadcast.emit('task deleted', data);
        }
    });

    // Handle request for current state
    socket.on('request state', () => {
        socket.emit('current state', tasks);
    });

    // Handle request for online users
    socket.on('request online users', () => {
        socket.emit('online users', Object.values(onlineUsers));
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

