## 3. JavaScript (app.js)

```javascript
// Initialize the application
document.addEventListener('DOMContentLoaded', function() {
    // DOM elements
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const deleteTaskBtn = document.getElementById('delete-task-btn');
    const changeNameBtn = document.getElementById('change-name-btn');
    const userNameElement = document.getElementById('user-name');

    // App state
    let state = {
        columns: [],
        tasks: [],
        userName: localStorage.getItem('userName') || 'Guest'
    };

    // Initialize Socket.io connection
    const socket = io();

    // Set initial user name
    userNameElement.textContent = state.userName;

    // Load saved state from localStorage
    loadState();

    // Render the board
    renderBoard();

    // Event listeners
    addColumnBtn.addEventListener('click', addColumn);
    closeModal.addEventListener('click', closeTaskModal);
    taskForm.addEventListener('submit', saveTask);
    deleteTaskBtn.addEventListener('click', deleteTask);
    changeNameBtn.addEventListener('click', changeUserName);

    // Socket.io event listeners
    socket.on('connect', () => {
        console.log('Connected to server');
        socket.emit('join', { userName: state.userName });
    });

    socket.on('stateUpdate', (newState) => {
        state = newState;
        renderBoard();
        saveState();
    });

    // Functions
    function loadState() {
        const savedState = localStorage.getItem('taskBoardState');
        if (savedState) {
            state = JSON.parse(savedState);
        } else {
            // Initialize with default columns if no saved state
            state.columns = [
                { id: generateId(), title: 'To Do' },
                { id: generateId(), title: 'In Progress' },
                { id: generateId(), title: 'Done' }
            ];
        }
    }

    function saveState() {
        localStorage.setItem('taskBoardState', JSON.stringify(state));
    }

    function renderBoard() {
        board.innerHTML = '';

        state.columns.forEach(column => {
            const columnElement = createColumnElement(column);
            board.appendChild(columnElement);
        });

        // Make tasks draggable
        setupDragAndDrop();
    }

    function createColumnElement(column) {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        const columnHeader = document.createElement('div');
        columnHeader.className = 'column-header';

        const columnTitle = document.createElement('div');
        columnTitle.className = 'column-title';
        columnTitle.textContent = column.title;
        columnTitle.contentEditable = true;
        columnTitle.addEventListener('blur', () => updateColumnTitle(column.id, columnTitle.textContent));

        const columnActions = document.createElement('div');
        columnActions.className = 'column-actions';

        const deleteColumnBtn = document.createElement('button');
        deleteColumnBtn.innerHTML = '<i class="fas fa-trash"></i>';
        deleteColumnBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            deleteColumn(column.id);
        });

        columnActions.appendChild(deleteColumnBtn);
        columnHeader.appendChild(columnTitle);
        columnHeader.appendChild(columnActions);

        const taskList = document.createElement('div');
        taskList.className = 'task-list';
        taskList.dataset.columnId = column.id;

        // Add tasks to the column
        const columnTasks = state.tasks.filter(task => task.columnId === column.id);
        columnTasks.forEach(task => {
            const taskElement = createTaskElement(task);
            taskList.appendChild(taskElement);
        });

        const addTask = document.createElement('div');
        addTask.className = 'add-task';

        const addTaskBtn = document.createElement('button');
        addTaskBtn.textContent = '+ Add Task';
        addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));

        addTask.appendChild(addTaskBtn);

        columnElement.appendChild(columnHeader);
        columnElement.appendChild(taskList);
        columnElement.appendChild(addTask);

        return columnElement;
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.dataset.taskId = task.id;

        const taskHeader = document.createElement('div');
        taskHeader.className = 'task-header';

        const taskTitle = document.createElement('div');
        taskTitle.className = 'task-title';
        taskTitle.textContent = task.title;

        const taskPriority = document.createElement('div');
        taskPriority.className = `task-priority ${task.priority}`;
        taskPriority.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

        taskHeader.appendChild(taskTitle);
        taskHeader.appendChild(taskPriority);

        const taskDescription = document.createElement('div');
        taskDescription.className = 'task-description';
        taskDescription.textContent = task.description;

        const taskMeta = document.createElement('div');
        taskMeta.className = 'task-meta';

        const taskAssignee = document.createElement('div');
        taskAssignee.textContent = task.assignee || 'Unassigned';

        const taskDueDate = document.createElement('div');
        taskDueDate.textContent = task.dueDate ? formatDate(task.dueDate) : 'No due date';

        taskMeta.appendChild(taskAssignee);
        taskMeta.appendChild(taskDueDate);

        taskElement.appendChild(taskHeader);
        taskElement.appendChild(taskDescription);
        taskElement.appendChild(taskMeta);

        // Add event listeners
        taskElement.addEventListener('click', (e) => {
            if (!e.target.closest('.task-priority')) {
                openTaskModal(task.id);
            }
        });

        taskElement.addEventListener('dragstart', handleDragStart);
        taskElement.addEventListener('dragend', handleDragEnd);

        return taskElement;
    }

    function setupDragAndDrop() {
        const taskLists = document.querySelectorAll('.task-list');

        taskLists.forEach(taskList => {
            taskList.addEventListener('dragover', handleDragOver);
            taskList.addEventListener('dragenter', handleDragEnter);
            taskList.addEventListener('dragleave', handleDragLeave);
            taskList.addEventListener('drop', handleDrop);
        });
    }

    function handleDragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
        e.target.classList.add('dragging');
        setTimeout(() => {
            e.target.style.display = 'none';
        }, 0);
    }

    function handleDragEnd(e) {
        e.target.classList.remove('dragging');
        e.target.style.display = 'block';
    }

    function handleDragOver(e) {
        e.preventDefault();
    }

    function handleDragEnter(e) {
        e.preventDefault();
        e.target.classList.add('drag-over');
    }

    function handleDragLeave(e) {
        e.target.classList.remove('drag-over');
    }

    function handleDrop(e) {
        e.preventDefault();
        e.target.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const columnId = e.target.dataset.columnId;

        if (taskId && columnId) {
            // Update task's column
            const taskIndex = state.tasks.findIndex(task => task.id === taskId);
            if (taskIndex !== -1) {
                state.tasks[taskIndex].columnId = columnId;
                socket.emit('updateState', state);
            }
        }
    }

    function addColumn() {
        const columnTitle = prompt('Enter column title:', 'New Column');
        if (columnTitle) {
            const newColumn = {
                id: generateId(),
                title: columnTitle
            };
            state.columns.push(newColumn);
            socket.emit('updateState', state);
        }
    }

    function updateColumnTitle(columnId, newTitle) {
        const columnIndex = state.columns.findIndex(col => col.id === columnId);
        if (columnIndex !== -1) {
            state.columns[columnIndex].title = newTitle.trim();
            socket.emit('updateState', state);
        }
    }

    function deleteColumn(columnId) {
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            // Remove column
            state.columns = state.columns.filter(col => col.id !== columnId);

            // Remove associated tasks
            state.tasks = state.tasks.filter(task => task.columnId !== columnId);

            socket.emit('updateState', state);
        }
    }

    function openTaskModal(taskId = null, columnId = null) {
        const task = taskId ? state.tasks.find(t => t.id === taskId) : null;

        // Set form values
        document.getElementById('task-id').value = task ? task.id : '';
        document.getElementById('task-title').value = task ? task.title : '';
        document.getElementById('task-description').value = task ? task.description : '';
        document.getElementById('task-priority').value = task ? task.priority : 'medium';
        document.getElementById('task-assignee').value = task ? task.assignee : '';
        document.getElementById('task-due-date').value = task ? task.dueDate : '';

        // Set column ID if creating a new task
        if (!task && columnId) {
            document.getElementById('task-id').dataset.columnId = columnId;
        }

        // Show delete button only for existing tasks
        deleteTaskBtn.style.display = task ? 'block' : 'none';

        // Show modal
        taskModal.classList.add('active');
    }

    function closeTaskModal() {
        taskModal.classList.remove('active');
    }

    function saveTask(e) {
        e.preventDefault();

        const taskId = document.getElementById('task-id').value;
        const columnId = document.getElementById('task-id').dataset.columnId || state.tasks.find(t => t.id === taskId)?.columnId;
        const title = document.getElementById('task-title').value.trim();
        const description = document.getElementById('task-description').value.trim();
        const priority = document.getElementById('task-priority').value;
        const assignee = document.getElementById('task-assignee').value.trim();
        const dueDate = document.getElementById('task-due-date').value;

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        if (taskId) {
            // Update existing task
            const taskIndex = state.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                state.tasks[taskIndex] = {
                    ...state.tasks[taskIndex],
                    title,
                    description,
                    priority,
                    assignee,
                    dueDate
                };
            }
        } else {
            // Create new task
            const newTask = {
                id: generateId(),
                columnId,
                title,
                description,
                priority,
                assignee,
                dueDate,
                createdBy: state.userName,
                createdAt: new Date().toISOString()
            };
            state.tasks.push(newTask);
        }

        socket.emit('updateState', state);
        closeTaskModal();
    }

    function deleteTask() {
        const taskId = document.getElementById('task-id').value;
        if (taskId && confirm('Are you sure you want to delete this task?')) {
            state.tasks = state.tasks.filter(task => task.id !== taskId);
            socket.emit('updateState', state);
            closeTaskModal();
        }
    }

    function changeUserName() {
        const newName = prompt('Enter your name:', state.userName);
        if (newName && newName.trim() !== '') {
            state.userName = newName.trim();
            localStorage.setItem('userName', state.userName);
            userNameElement.textContent = state.userName;
            socket.emit('updateUserName', { oldName: state.userName, newName: newName.trim() });
        }
    }

    // Helper functions
    function generateId() {
        return Math.random().toString(36).substring(2, 9);
    }

    function formatDate(dateString) {
        if (!dateString) return '';
        const options = { year: 'numeric', month: 'short', day: 'numeric' };
        return new Date(dateString).toLocaleDateString(undefined, options);
    }
});
