## 4. Node.js Server (server.js)

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(path.join(__dirname)));

// Store the current state
let currentState = {
    columns: [],
    tasks: []
};

// Socket.io connection handling
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send current state to new client
    socket.emit('stateUpdate', currentState);

    // Handle state updates from clients
    socket.on('updateState', (newState) => {
        currentState = newState;
        socket.broadcast.emit('stateUpdate', currentState);
    });

    // Handle user name changes
    socket.on('updateUserName', ({ oldName, newName }) => {
        // Update tasks created by the user
        currentState.tasks = currentState.tasks.map(task => {
            if (task.createdBy === oldName) {
                return { ...task, createdBy: newName };
            }
            return task;
        });

        // Broadcast the updated state
        io.emit('stateUpdate', currentState);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
