## 3. JavaScript (app.js)

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // DOM Elements
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const deleteTaskBtn = document.getElementById('delete-task-btn');
    const modalTitle = document.getElementById('modal-title');
    const userNameElement = document.getElementById('user-name');
    const connectionStatusElement = document.getElementById('connection-status');

    // State
    let columns = [];
    let tasks = [];
    let currentTaskId = null;
    let currentColumnId = null;
    let draggedTask = null;
    let socket = null;
    let userId = generateId();
    let userName = `User-${userId.substring(0, 4)}`;

    // Initialize the app
    initApp();

    // Initialize the app
    function initApp() {
        // Set user name
        userNameElement.textContent = userName;

        // Load saved data
        loadData();

        // Set up event listeners
        setupEventListeners();

        // Initialize WebSocket connection
        setupWebSocket();
    }

    // Load data from localStorage
    function loadData() {
        const savedColumns = localStorage.getItem('projectColumns');
        const savedTasks = localStorage.getItem('projectTasks');

        if (savedColumns) {
            columns = JSON.parse(savedColumns);
        } else {
            // Default columns
            columns = [
                { id: generateId(), title: 'To Do', tasks: [] },
                { id: generateId(), title: 'In Progress', tasks: [] },
                { id: generateId(), title: 'Done', tasks: [] }
            ];
        }

        if (savedTasks) {
            tasks = JSON.parse(savedTasks);
        }

        // Render the board
        renderBoard();
    }

    // Save data to localStorage
    function saveData() {
        localStorage.setItem('projectColumns', JSON.stringify(columns));
        localStorage.setItem('projectTasks', JSON.stringify(tasks));
    }

    // Set up event listeners
    function setupEventListeners() {
        // Add column button
        addColumnBtn.addEventListener('click', addNewColumn);

        // Modal close button
        closeModal.addEventListener('click', closeModalHandler);

        // Task form submission
        taskForm.addEventListener('submit', saveTask);

        // Delete task button
        deleteTaskBtn.addEventListener('click', deleteTask);

        // Click outside modal to close
        window.addEventListener('click', function(event) {
            if (event.target === taskModal) {
                closeModalHandler();
            }
        });

        // Drag and drop events
        board.addEventListener('dragstart', dragStart);
        board.addEventListener('dragover', dragOver);
        board.addEventListener('dragenter', dragEnter);
        board.addEventListener('dragleave', dragLeave);
        board.addEventListener('drop', drop);
        board.addEventListener('dragend', dragEnd);
    }

    // Set up WebSocket connection
    function setupWebSocket() {
        // In a real app, you would connect to your WebSocket server
        // For this example, we'll simulate real-time updates
        console.log('Setting up WebSocket connection...');

        // Simulate connection status
        setTimeout(() => {
            document.body.classList.add('connected');
            connectionStatusElement.textContent = 'Online';
        }, 1000);

        // In a real implementation, you would use:
        // socket = io('http://localhost:3000');
        // socket.on('connect', () => { ... });
        // socket.on('task-updated', (data) => { ... });
    }

    // Render the entire board
    function renderBoard() {
        board.innerHTML = '';

        columns.forEach(column => {
            const columnElement = createColumnElement(column);
            board.appendChild(columnElement);
        });
    }

    // Create a column element
    function createColumnElement(column) {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        const columnHeader = document.createElement('div');
        columnHeader.className = 'column-header';

        const columnTitle = document.createElement('div');
        columnTitle.className = 'column-title';
        columnTitle.textContent = column.title;
        columnTitle.contentEditable = true;
        columnTitle.addEventListener('blur', function() {
            const newTitle = this.textContent.trim();
            if (newTitle) {
                column.title = newTitle;
                saveData();
                // In a real app, you would emit this change to the server
            }
        });

        const columnActions = document.createElement('div');
        columnActions.className = 'column-actions';

        const deleteColumnBtn = document.createElement('button');
        deleteColumnBtn.innerHTML = '<i class="fas fa-trash"></i>';
        deleteColumnBtn.title = 'Delete Column';
        deleteColumnBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            deleteColumn(column.id);
        });

        columnActions.appendChild(deleteColumnBtn);
        columnHeader.appendChild(columnTitle);
        columnHeader.appendChild(columnActions);

        const taskList = document.createElement('div');
        taskList.className = 'task-list';

        // Add drop zone for empty columns
        const dropZone = document.createElement('div');
        dropZone.className = 'drop-zone';
        dropZone.textContent = 'Drop tasks here';
        taskList.appendChild(dropZone);

        // Add tasks to the column
        column.tasks.forEach(taskId => {
            const task = tasks.find(t => t.id === taskId);
            if (task) {
                const taskElement = createTaskElement(task);
                taskList.appendChild(taskElement);
            }
        });

        const addTaskBtn = document.createElement('div');
        addTaskBtn.className = 'add-task';
        const addTaskButton = document.createElement('button');
        addTaskButton.innerHTML = '<i class="fas fa-plus"></i> Add Task';
        addTaskButton.addEventListener('click', function() {
            currentColumnId = column.id;
            currentTaskId = null;
            openTaskModal();
        });
        addTaskBtn.appendChild(addTaskButton);

        columnElement.appendChild(columnHeader);
        columnElement.appendChild(taskList);
        columnElement.appendChild(addTaskBtn);

        return columnElement;
    }

    // Create a task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = `task priority-${task.priority}`;
        taskElement.draggable = true;
        taskElement.dataset.taskId = task.id;

        const taskHeader = document.createElement('div');
        taskHeader.className = 'task-header';

        const taskTitle = document.createElement('div');
        taskTitle.className = 'task-title';
        taskTitle.textContent = task.title;

        const taskActions = document.createElement('div');
        taskActions.className = 'task-actions';

        const editBtn = document.createElement('button');
        editBtn.innerHTML = '<i class="fas fa-pencil-alt"></i>';
        editBtn.title = 'Edit Task';
        editBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            currentTaskId = task.id;
            currentColumnId = columns.find(c => c.tasks.includes(task.id)).id;
            openTaskModal(task);
        });

        taskActions.appendChild(editBtn);
        taskHeader.appendChild(taskTitle);
        taskHeader.appendChild(taskActions);

        const taskMeta = document.createElement('div');
        taskMeta.className = 'task-meta';

        if (task.dueDate) {
            const dueDate = document.createElement('span');
            dueDate.innerHTML = `<i class="far fa-calendar-alt"></i> ${formatDate(task.dueDate)}`;
            taskMeta.appendChild(dueDate);
        }

        if (task.assignee) {
            const assignee = document.createElement('span');
            assignee.className = 'task-assignee';
            assignee.innerHTML = `<i class="fas fa-user"></i> ${task.assignee}`;
            taskMeta.appendChild(assignee);
        }

        const taskDescription = document.createElement('div');
        taskDescription.className = 'task-description';
        taskDescription.textContent = task.description || 'No description';

        const taskFooter = document.createElement('div');
        taskFooter.className = 'task-footer';

        const priorityIndicator = document.createElement('span');
        priorityIndicator.className = `priority-indicator priority-${task.priority}`;
        priorityIndicator.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

        taskFooter.appendChild(priorityIndicator);

        taskElement.appendChild(taskHeader);
        if (taskMeta.children.length > 0) {
            taskElement.appendChild(taskMeta);
        }
        taskElement.appendChild(taskDescription);
        taskElement.appendChild(taskFooter);

        return taskElement;
    }

    // Add a new column
    function addNewColumn() {
        const columnTitle = prompt('Enter column title:', 'New Column');
        if (columnTitle) {
            const newColumn = {
                id: generateId(),
                title: columnTitle,
                tasks: []
            };

            columns.push(newColumn);
            saveData();
            renderBoard();

            // In a real app, you would emit this change to the server
        }
    }

    // Delete a column
    function deleteColumn(columnId) {
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            const columnIndex = columns.findIndex(c => c.id === columnId);
            if (columnIndex !== -1) {
                // Remove tasks from the column
                const column = columns[columnIndex];
                column.tasks.forEach(taskId => {
                    const taskIndex = tasks.findIndex(t => t.id === taskId);
                    if (taskIndex !== -1) {
                        tasks.splice(taskIndex, 1);
                    }
                });

                // Remove the column
                columns.splice(columnIndex, 1);
                saveData();
                renderBoard();

                // In a real app, you would emit this change to the server
            }
        }
    }

    // Open the task modal
    function openTaskModal(task = null) {
        if (task) {
            modalTitle.textContent = 'Edit Task';
            document.getElementById('task-id').value = task.id;
            document.getElementById('task-title').value = task.title;
            document.getElementById('task-description').value = task.description || '';
            document.getElementById('task-priority').value = task.priority;
            document.getElementById('task-due-date').value = task.dueDate || '';
            document.getElementById('task-assignee').value = task.assignee || '';
            deleteTaskBtn.style.display = 'block';
        } else {
            modalTitle.textContent = 'Create Task';
            taskForm.reset();
            document.getElementById('task-id').value = '';
            deleteTaskBtn.style.display = 'none';
        }

        taskModal.style.display = 'flex';
    }

    // Close the task modal
    function closeModalHandler() {
        taskModal.style.display = 'none';
    }

    // Save a task
    function saveTask(e) {
        e.preventDefault();

        const taskId = document.getElementById('task-id').value;
        const title = document.getElementById('task-title').value.trim();
        const description = document.getElementById('task-description').value.trim();
        const priority = document.getElementById('task-priority').value;
        const dueDate = document.getElementById('task-due-date').value;
        const assignee = document.getElementById('task-assignee').value.trim();

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        if (taskId) {
            // Update existing task
            const taskIndex = tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                tasks[taskIndex] = {
                    ...tasks[taskIndex],
                    title,
                    description,
                    priority,
                    dueDate,
                    assignee,
                    updatedAt: new Date().toISOString(),
                    updatedBy: userName
                };
            }
        } else {
            // Create new task
            const newTask = {
                id: generateId(),
                title,
                description,
                priority,
                dueDate,
                assignee,
                createdAt: new Date().toISOString(),
                createdBy: userName,
                updatedAt: new Date().toISOString(),
                updatedBy: userName
            };

            tasks.push(newTask);

            // Add to current column
            const column = columns.find(c => c.id === currentColumnId);
            if (column) {
                column.tasks.push(newTask.id);
            }
        }

        saveData();
        renderBoard();
        closeModalHandler();

        // In a real app, you would emit this change to the server
    }

    // Delete a task
    function deleteTask() {
        const taskId = document.getElementById('task-id').value;
        if (taskId && confirm('Are you sure you want to delete this task?')) {
            // Remove from tasks array
            const taskIndex = tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                tasks.splice(taskIndex, 1);
            }

            // Remove from all columns
            columns.forEach(column => {
                const taskIndex = column.tasks.indexOf(taskId);
                if (taskIndex !== -1) {
                    column.tasks.splice(taskIndex, 1);
                }
            });

            saveData();
            renderBoard();
            closeModalHandler();

            // In a real app, you would emit this change to the server
        }
    }

    // Drag and drop functions
    function dragStart(e) {
        if (e.target.classList.contains('task')) {
            draggedTask = e.target;
            e.target.classList.add('dragging');
            e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
            e.dataTransfer.effectAllowed = 'move';
        }
    }

    function dragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';

        const dropZone = e.target.closest('.drop-zone');
        if (dropZone) {
            dropZone.style.backgroundColor = 'rgba(74, 107, 255, 0.2)';
        }
    }

    function dragEnter(e) {
        e.preventDefault();
        const column = e.target.closest('.column');
        if (column && !column.querySelector('.drop-zone')) {
            const dropZone = document.createElement('div');
            dropZone.className = 'drop-zone';
            dropZone.textContent = 'Drop tasks here';
            column.querySelector('.task-list').appendChild(dropZone);
        }
    }

    function dragLeave(e) {
        e.preventDefault();
        const dropZone = e.target.closest('.drop-zone');
        if (dropZone) {
            dropZone.style.backgroundColor = 'rgba(74, 107, 255, 0.1)';
        }
    }

    function drop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const dropZone = e.target.closest('.drop-zone');

        if (dropZone) {
            const columnId = dropZone.closest('.column').dataset.columnId;

            // Remove from old column
            columns.forEach(column => {
                const index = column.tasks.indexOf(taskId);
                if (index !== -1) {
                    column.tasks.splice(index, 1);
                }
            });

            // Add to new column
            const column = columns.find(c => c.id === columnId);
            if (column) {
                column.tasks.push(taskId);
            }

            saveData();
            renderBoard();

            // In a real app, you would emit this change to the server
        }

        if (dropZone) {
            dropZone.style.backgroundColor = 'rgba(74, 107, 255, 0.1)';
        }
    }

    function dragEnd(e) {
        if (e.target.classList.contains('task')) {
            e.target.classList.remove('dragging');
            draggedTask = null;
        }
    }

    // Helper functions
    function generateId() {
        return Math.random().toString(36).substring(2, 9) + Date.now().toString(36);
    }

    function formatDate(dateString) {
        if (!dateString) return '';
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    }
});
