## 4. Server Setup (server.js)

For real-time collaboration, you would need a server to handle WebSocket connections. Here's a basic Node.js server using Socket.IO:

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
    cors: {
        origin: "*",
        methods: ["GET", "POST"]
    }
});

// Serve static files
app.use(express.static('public'));

// Store connected users and board state
let connectedUsers = {};
let boardState = {
    columns: [],
    tasks: []
};

// Socket.IO connection handler
io.on('connection', (socket) => {
    console.log('New client connected:', socket.id);

    // Add user to connected users
    connectedUsers[socket.id] = {
        id: socket.id,
        name: `User-${socket.id.substring(0, 4)}`
    };

    // Send current board state to the new user
    socket.emit('board-state', boardState);

    // Send updated user list to all clients
    io.emit('user-list', Object.values(connectedUsers));

    // Handle task updates
    socket.on('task-updated', (task) => {
        // Update the task in the board state
        const taskIndex = boardState.tasks.findIndex(t => t.id === task.id);
        if (taskIndex !== -1) {
            boardState.tasks[taskIndex] = task;
        } else {
            boardState.tasks.push(task);
        }

        // Broadcast the update to all clients except the sender
        socket.broadcast.emit('task-updated', task);
    });

    // Handle column updates
    socket.on('column-updated', (column) => {
        // Update the column in the board state
        const columnIndex = boardState.columns.findIndex(c => c.id === column.id);
        if (columnIndex !== -1) {
            boardState.columns[columnIndex] = column;
        } else {
            boardState.columns.push(column);
        }

        // Broadcast the update to all clients except the sender
        socket.broadcast.emit('column-updated', column);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected:', socket.id);
        delete connectedUsers[socket.id];
        io.emit('user-list', Object.values(connectedUsers));
    });
});

// Start the server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

