```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize the board
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const newColumnName = document.getElementById('new-column-name');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const deleteTaskBtn = document.getElementById('delete-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');

    // Sample initial data
    let boardData = {
        columns: [
            {
                id: 'todo',
                title: 'To Do',
                tasks: [
                    { id: 'task1', title: 'Design UI', description: 'Create wireframes for the new dashboard' },
                    { id: 'task2', title: 'Implement API', description: 'Develop backend API endpoints' }
                ]
            },
            {
                id: 'in-progress',
                title: 'In Progress',
                tasks: [
                    { id: 'task3', title: 'Write documentation', description: 'Document the new features' }
                ]
            },
            {
                id: 'done',
                title: 'Done',
                tasks: [
                    { id: 'task4', title: 'Setup project', description: 'Initialize Git repository and project structure' }
                ]
            }
        ]
    };

    // Current task being edited
    let currentTask = null;
    let currentColumnId = null;

    // Initialize drag-and-drop
    const drake = dragula({
        isContainer: function (el) {
            return el.classList.contains('task-list');
        },
        moves: function (el, source, handle, sibling) {
            return el.classList.contains('task-card');
        }
    });

    // Load saved data from localStorage if available
    function loadBoardData() {
        const savedData = localStorage.getItem('taskBoardData');
        if (savedData) {
            boardData = JSON.parse(savedData);
        }
        renderBoard();
    }

    // Save data to localStorage
    function saveBoardData() {
        localStorage.setItem('taskBoardData', JSON.stringify(boardData));
    }

    // Render the entire board
    function renderBoard() {
        board.innerHTML = '';

        boardData.columns.forEach(column => {
            const columnElement = createColumnElement(column);
            board.appendChild(columnElement);
        });

        // Set up drag-and-drop events
        setupDragAndDrop();
    }

    // Create a column element
    function createColumnElement(column) {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        const columnHeader = document.createElement('div');
        columnHeader.className = 'column-header';

        const columnTitle = document.createElement('div');
        columnTitle.className = 'column-title';
        columnTitle.textContent = column.title;

        const columnActions = document.createElement('div');
        columnActions.className = 'column-actions';

        const addTaskBtn = document.createElement('button');
        addTaskBtn.textContent = '+';
        addTaskBtn.title = 'Add task';
        addTaskBtn.addEventListener('click', () => {
            currentTask = null;
            currentColumnId = column.id;
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            taskModal.style.display = 'block';
        });

        const deleteColumnBtn = document.createElement('button');
        deleteColumnBtn.textContent = '×';
        deleteColumnBtn.title = 'Delete column';
        deleteColumnBtn.addEventListener('click', () => {
            if (confirm(`Delete column "${column.title}"?`)) {
                deleteColumn(column.id);
            }
        });

        columnActions.appendChild(addTaskBtn);
        columnActions.appendChild(deleteColumnBtn);

        columnHeader.appendChild(columnTitle);
        columnHeader.appendChild(columnActions);

        const taskList = document.createElement('div');
        taskList.className = 'task-list';

        column.tasks.forEach(task => {
            const taskElement = createTaskElement(task);
            taskList.appendChild(taskElement);
        });

        columnElement.appendChild(columnHeader);
        columnElement.appendChild(taskList);

        return columnElement;
    }

    // Create a task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.dataset.taskId = task.id;

        const taskTitle = document.createElement('div');
        taskTitle.className = 'task-title';
        taskTitle.textContent = task.title;

        const taskDescription = document.createElement('div');
        taskDescription.className = 'task-description';
        taskDescription.textContent = task.description;

        taskElement.appendChild(taskTitle);
        taskElement.appendChild(taskDescription);

        taskElement.addEventListener('click', (e) => {
            if (!e.target.closest('.column-actions')) {
                currentTask = task;
                currentColumnId = taskElement.closest('.column').dataset.columnId;
                taskTitleInput.value = task.title;
                taskDescriptionInput.value = task.description;
                taskModal.style.display = 'block';
            }
        });

        return taskElement;
    }

    // Setup drag-and-drop functionality
    function setupDragAndDrop() {
        drake.off('drop').on('drop', (el, target, source, sibling) => {
            const taskId = el.dataset.taskId;
            const oldColumnId = source.closest('.column').dataset.columnId;
            const newColumnId = target.closest('.column').dataset.columnId;

            // Find the task in the old column
            const oldColumn = boardData.columns.find(col => col.id === oldColumnId);
            const taskIndex = oldColumn.tasks.findIndex(task => task.id === taskId);
            const [task] = oldColumn.tasks.splice(taskIndex, 1);

            // Add to new column
            const newColumn = boardData.columns.find(col => col.id === newColumnId);
            newColumn.tasks.push(task);

            saveBoardData();

            // Emit change to other clients
            if (socket) {
                socket.emit('task-moved', {
                    taskId,
                    oldColumnId,
                    newColumnId,
                    task
                });
            }
        });
    }

    // Add a new column
    function addColumn(title) {
        const newColumn = {
            id: 'col-' + Date.now(),
            title: title,
            tasks: []
        };

        boardData.columns.push(newColumn);
        saveBoardData();
        renderBoard();

        // Emit change to other clients
        if (socket) {
            socket.emit('column-added', newColumn);
        }
    }

    // Delete a column
    function deleteColumn(columnId) {
        boardData.columns = boardData.columns.filter(col => col.id !== columnId);
        saveBoardData();
        renderBoard();

        // Emit change to other clients
        if (socket) {
            socket.emit('column-deleted', columnId);
        }
    }

    // Add or update a task
    function saveTask(title, description) {
        if (currentTask) {
            // Update existing task
            const column = boardData.columns.find(col => col.id === currentColumnId);
            const task = column.tasks.find(t => t.id === currentTask.id);
            task.title = title;
            task.description = description;

            // Emit change to other clients
            if (socket) {
                socket.emit('task-updated', {
                    columnId: currentColumnId,
                    taskId: currentTask.id,
                    task: task
                });
            }
        } else {
            // Add new task
            const newTask = {
                id: 'task-' + Date.now(),
                title: title,
                description: description
            };

            const column = boardData.columns.find(col => col.id === currentColumnId);
            column.tasks.push(newTask);

            // Emit change to other clients
            if (socket) {
                socket.emit('task-added', {
                    columnId: currentColumnId,
                    task: newTask
                });
            }
        }

        saveBoardData();
        renderBoard();
        taskModal.style.display = 'none';
    }

    // Delete a task
    function deleteTask() {
        if (currentTask) {
            const column = boardData.columns.find(col => col.id === currentColumnId);
            column.tasks = column.tasks.filter(t => t.id !== currentTask.id);

            saveBoardData();
            renderBoard();

            // Emit change to other clients
            if (socket) {
                socket.emit('task-deleted', {
                    columnId: currentColumnId,
                    taskId: currentTask.id
                });
            }
        }
        taskModal.style.display = 'none';
    }

    // Event listeners
    addColumnBtn.addEventListener('click', () => {
        const title = newColumnName.value.trim();
        if (title) {
            addColumn(title);
            newColumnName.value = '';
        }
    });

    newColumnName.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            const title = newColumnName.value.trim();
            if (title) {
                addColumn(title);
                newColumnName.value = '';
            }
        }
    });

    closeModal.addEventListener('click', () => {
        taskModal.style.display = 'none';
    });

    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            taskModal.style.display = 'none';
        }
    });

    saveTaskBtn.addEventListener('click', () => {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (title) {
            saveTask(title, description);
        }
    });

    deleteTaskBtn.addEventListener('click', () => {
        if (currentTask) {
            if (confirm(`Delete task "${currentTask.title}"?`)) {
                deleteTask();
            }
        }
    });

    // Initialize the board
    loadBoardData();

    // Socket.io for real-time collaboration
    const socket = io();

    // Set username (in a real app, this would come from authentication)
    const username = prompt('Enter your name:') || 'Guest';
    document.getElementById('user-name').textContent = username;
    socket.emit('set-username', username);

    // Update online users count
    socket.on('user-count', (count) => {
        document.getElementById('online-users').textContent = `${count} online`;
    });

    // Handle real-time updates from other clients
    socket.on('board-updated', (newBoardData) => {
        boardData = newBoardData;
        renderBoard();
    });

    // Handle task moved
    socket.on('task-moved', ({ taskId, oldColumnId, newColumnId, task }) => {
        // Find the task in the old column
        const oldColumn = boardData.columns.find(col => col.id === oldColumnId);
        const taskIndex = oldColumn.tasks.findIndex(t => t.id === taskId);
        oldColumn.tasks.splice(taskIndex, 1);

        // Add to new column
        const newColumn = boardData.columns.find(col => col.id === newColumnId);
        newColumn.tasks.push(task);

        renderBoard();
    });

    // Handle column added
    socket.on('column-added', (newColumn) => {
        boardData.columns.push(newColumn);
        renderBoard();
    });

    // Handle column deleted
    socket.on('column-deleted', (columnId) => {
        boardData.columns = boardData.columns.filter(col => col.id !== columnId);
        renderBoard();
    });

    // Handle task added
    socket.on('task-added', ({ columnId, task }) => {
        const column = boardData.columns.find(col => col.id === columnId);
        column.tasks.push(task);
        renderBoard();
    });

    // Handle task updated
    socket.on('task-updated', ({ columnId, taskId, task }) => {
        const column = boardData.columns.find(col => col.id === columnId);
        const existingTask = column.tasks.find(t => t.id === taskId);
        Object.assign(existingTask, task);
        renderBoard();
    });

    // Handle task deleted
    socket.on('task-deleted', ({ columnId, taskId }) => {
        const column = boardData.columns.find(col => col.id === columnId);
        column.tasks = column.tasks.filter(t => t.id !== taskId);
        renderBoard();
    });
});
