## Server Implementation (Node.js with Socket.io)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Store board data in memory (in a real app, use a database)
let boardData = {
    columns: [
        {
            id: 'todo',
            title: 'To Do',
            tasks: [
                { id: 'task1', title: 'Design UI', description: 'Create wireframes for the new dashboard' },
                { id: 'task2', title: 'Implement API', description: 'Develop backend API endpoints' }
            ]
        },
        {
            id: 'in-progress',
            title: 'In Progress',
            tasks: [
                { id: 'task3', title: 'Write documentation', description: 'Document the new features' }
            ]
        },
        {
            id: 'done',
            title: 'Done',
            tasks: [
                { id: 'task4', title: 'Setup project', description: 'Initialize Git repository and project structure' }
            ]
        }
    ]
};

// Track connected users
const users = new Map();

io.on('connection', (socket) => {
    console.log('New client connected');

    // Send initial board data to new client
    socket.emit('board-updated', boardData);

    // Update user count
    socket.on('set-username', (username) => {
        users.set(socket.id, username);
        io.emit('user-count', users.size);
    });

    // Handle task moved
    socket.on('task-moved', (data) => {
        // Update server data
        const oldColumn = boardData.columns.find(col => col.id === data.oldColumnId);
        const taskIndex = oldColumn.tasks.findIndex(t => t.id === data.taskId);
        oldColumn.tasks.splice(taskIndex, 1);

        const newColumn = boardData.columns.find(col => col.id === data.newColumnId);
        newColumn.tasks.push(data.task);

        // Broadcast to all clients
        io.emit('task-moved', data);
    });

    // Handle column added
    socket.on('column-added', (newColumn) => {
        boardData.columns.push(newColumn);
        io.emit('column-added', newColumn);
    });

    // Handle column deleted
    socket.on('column-deleted', (columnId) => {
        boardData.columns = boardData.columns.filter(col => col.id !== columnId);
        io.emit('column-deleted', columnId);
    });

    // Handle task added
    socket.on('task-added', (data) => {
        const column = boardData.columns.find(col => col.id === data.columnId);
        column.tasks.push(data.task);
        io.emit('task-added', data);
    });

    // Handle task updated
    socket.on('task-updated', (data) => {
        const column = boardData.columns.find(col => col.id === data.columnId);
        const task = column.tasks.find(t => t.id === data.taskId);
        Object.assign(task, data.task);
        io.emit('task-updated', data);
    });

    // Handle task deleted
    socket.on('task-deleted', (data) => {
        const column = boardData.columns.find(col => col.id === data.columnId);
        column.tasks = column.tasks.filter(t => t.id !== data.taskId);
        io.emit('task-deleted', data);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        users.delete(socket.id);
        io.emit('user-count', users.size);
        console.log('Client disconnected');
    });
});

// Serve static files
app.use(express.static('public'));

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
