```javascript
// Initialize the application
document.addEventListener('DOMContentLoaded', function() {
    // DOM elements
    const boardsContainer = document.getElementById('boards-container');
    const addBoardBtn = document.getElementById('add-board-btn');
    const newBoardNameInput = document.getElementById('new-board-name');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const deleteTaskBtn = document.getElementById('delete-task-btn');
    const userNameSpan = document.getElementById('user-name');
    const logoutBtn = document.getElementById('logout-btn');

    // State
    let boards = [];
    let currentUser = 'Guest';
    let currentTask = null;
    let currentBoardId = null;

    // Initialize Socket.IO connection
    const socket = io();

    // Set up event listeners
    setupEventListeners();

    // Load initial data
    loadInitialData();

    // Set up real-time collaboration
    setupRealTime();

    function setupEventListeners() {
        // Board events
        addBoardBtn.addEventListener('click', addNewBoard);
        newBoardNameInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') addNewBoard();
        });

        // Modal events
        closeModal.addEventListener('click', closeTaskModal);
        taskForm.addEventListener('submit', saveTask);
        deleteTaskBtn.addEventListener('click', deleteTask);

        // User events
        logoutBtn.addEventListener('click', logoutUser);
    }

    function loadInitialData() {
        // Load from localStorage or use default data
        const savedData = localStorage.getItem('taskBoardData');
        if (savedData) {
            boards = JSON.parse(savedData);
        } else {
            // Default boards
            boards = [
                { id: 'board-1', name: 'To Do', tasks: [] },
                { id: 'board-2', name: 'In Progress', tasks: [] },
                { id: 'board-3', name: 'Done', tasks: [] }
            ];
            saveData();
        }

        // Render boards
        renderBoards();

        // Set up drag and drop
        setupDragAndDrop();
    }

    function setupRealTime() {
        // Listen for board updates from server
        socket.on('boardUpdate', (updatedBoards) => {
            boards = updatedBoards;
            renderBoards();
            setupDragAndDrop();
        });

        // Listen for user updates
        socket.on('userUpdate', (users) => {
            // In a real app, you might update a user list
            console.log('Active users:', users);
        });
    }

    function renderBoards() {
        boardsContainer.innerHTML = '';

        boards.forEach(board => {
            const boardElement = document.createElement('div');
            boardElement.className = 'board';
            boardElement.dataset.boardId = board.id;

            boardElement.innerHTML = `
                <div class="board-header">
                    <h3>${board.name}</h3>
                    <div class="board-actions">
                        <button class="edit-board-btn" data-board-id="${board.id}"><i class="fas fa-edit"></i></button>
                        <button class="delete-board-btn" data-board-id="${board.id}"><i class="fas fa-trash"></i></button>
                    </div>
                </div>
                <div class="board-content" data-board-id="${board.id}">
                    ${board.tasks.map(task => createTaskElement(task)).join('')}
                    <button class="add-task-btn" data-board-id="${board.id}"><i class="fas fa-plus"></i> Add Task</button>
                </div>
            `;

            boardsContainer.appendChild(boardElement);
        });

        // Add event listeners for board actions
        document.querySelectorAll('.add-task-btn').forEach(btn => {
            btn.addEventListener('click', openTaskModal);
        });

        document.querySelectorAll('.edit-board-btn').forEach(btn => {
            btn.addEventListener('click', editBoardName);
        });

        document.querySelectorAll('.delete-board-btn').forEach(btn => {
            btn.addEventListener('click', deleteBoard);
        });

        // Add event listeners for task clicks
        document.querySelectorAll('.task').forEach(task => {
            task.addEventListener('click', (e) => {
                if (!e.target.closest('.task-priority')) {
                    openTaskModal(e, task.dataset.taskId);
                }
            });
        });
    }

    function createTaskElement(task) {
        return `
            <div class="task" draggable="true" data-task-id="${task.id}">
                <div class="task-header">
                    <span class="task-title">${task.title}</span>
                    <span class="task-priority ${task.priority}"></span>
                </div>
                ${task.assignee ? `<div class="task-assignee">Assigned to: ${task.assignee}</div>` : ''}
            </div>
        `;
    }

    function setupDragAndDrop() {
        const tasks = document.querySelectorAll('.task');
        const boardContents = document.querySelectorAll('.board-content');

        tasks.forEach(task => {
            task.addEventListener('dragstart', handleDragStart);
        });

        boardContents.forEach(content => {
            content.addEventListener('dragover', handleDragOver);
            content.addEventListener('drop', handleDrop);
            content.addEventListener('dragenter', handleDragEnter);
            content.addEventListener('dragleave', handleDragLeave);
        });
    }

    function handleDragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
        e.target.classList.add('dragging');
    }

    function handleDragOver(e) {
        e.preventDefault();
    }

    function handleDrop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const boardId = e.currentTarget.dataset.boardId;

        // Find the task and its current board
        let sourceBoardIndex, taskIndex;
        for (let i = 0; i < boards.length; i++) {
            const taskIndexInBoard = boards[i].tasks.findIndex(t => t.id === taskId);
            if (taskIndexInBoard !== -1) {
                sourceBoardIndex = i;
                taskIndex = taskIndexInBoard;
                break;
            }
        }

        if (sourceBoardIndex === undefined) return;

        // Find the target board
        const targetBoardIndex = boards.findIndex(b => b.id === boardId);
        if (targetBoardIndex === -1) return;

        // Move the task
        const [task] = boards[sourceBoardIndex].tasks.splice(taskIndex, 1);
        boards[targetBoardIndex].tasks.push(task);

        // Update UI
        renderBoards();
        setupDragAndDrop();

        // Save and broadcast changes
        saveData();
        socket.emit('updateBoards', boards);
    }

    function handleDragEnter(e) {
        e.currentTarget.classList.add('drag-over');
    }

    function handleDragLeave(e) {
        e.currentTarget.classList.remove('drag-over');
    }

    function addNewBoard() {
        const boardName = newBoardNameInput.value.trim();
        if (!boardName) return;

        const newBoard = {
            id: 'board-' + Date.now(),
            name: boardName,
            tasks: []
        };

        boards.push(newBoard);
        newBoardNameInput.value = '';

        // Update UI
        renderBoards();
        setupDragAndDrop();

        // Save and broadcast changes
        saveData();
        socket.emit('updateBoards', boards);
    }

    function editBoardName(e) {
        const boardId = e.target.closest('.edit-board-btn').dataset.boardId;
        const board = boards.find(b => b.id === boardId);
        if (!board) return;

        const newName = prompt('Enter new board name:', board.name);
        if (newName && newName.trim() !== '') {
            board.name = newName.trim();
            renderBoards();
            setupDragAndDrop();
            saveData();
            socket.emit('updateBoards', boards);
        }
    }

    function deleteBoard(e) {
        const boardId = e.target.closest('.delete-board-btn').dataset.boardId;
        if (confirm('Are you sure you want to delete this board and all its tasks?')) {
            boards = boards.filter(b => b.id !== boardId);
            renderBoards();
            setupDragAndDrop();
            saveData();
            socket.emit('updateBoards', boards);
        }
    }

    function openTaskModal(e, taskId = null) {
        const boardId = e.target.closest('.add-task-btn')?.dataset.boardId ||
                       e.target.closest('.task')?.parentElement.dataset.boardId;

        if (!boardId) return;

        currentBoardId = boardId;

        if (taskId) {
            // Editing existing task
            const board = boards.find(b => b.id === boardId);
            if (!board) return;

            currentTask = board.tasks.find(t => t.id === taskId);
            if (!currentTask) return;

            // Populate form
            document.getElementById('modal-title').textContent = 'Edit Task';
            document.getElementById('task-title').value = currentTask.title;
            document.getElementById('task-description').value = currentTask.description || '';
            document.getElementById('task-priority').value = currentTask.priority || 'medium';
            document.getElementById('task-assignee').value = currentTask.assignee || '';

            deleteTaskBtn.style.display = 'block';
        } else {
            // Creating new task
            currentTask = null;
            document.getElementById('modal-title').textContent = 'Add New Task';
            document.getElementById('task-form').reset();
            deleteTaskBtn.style.display = 'none';
        }

        taskModal.style.display = 'block';
    }

    function closeTaskModal() {
        taskModal.style.display = 'none';
        currentTask = null;
        currentBoardId = null;
    }

    function saveTask(e) {
        e.preventDefault();

        const title = document.getElementById('task-title').value.trim();
        const description = document.getElementById('task-description').value.trim();
        const priority = document.getElementById('task-priority').value;
        const assignee = document.getElementById('task-assignee').value.trim();

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        const board = boards.find(b => b.id === currentBoardId);
        if (!board) return;

        if (currentTask) {
            // Update existing task
            currentTask.title = title;
            currentTask.description = description;
            currentTask.priority = priority;
            currentTask.assignee = assignee;
        } else {
            // Add new task
            const newTask = {
                id: 'task-' + Date.now(),
                title,
                description,
                priority,
                assignee,
                createdBy: currentUser,
                createdAt: new Date().toISOString()
            };
            board.tasks.push(newTask);
        }

        // Update UI
        renderBoards();
        setupDragAndDrop();

        // Save and broadcast changes
        saveData();
        socket.emit('updateBoards', boards);

        // Close modal
        closeTaskModal();
    }

    function deleteTask() {
        if (!currentTask || !currentBoardId) return;

        if (confirm('Are you sure you want to delete this task?')) {
            const board = boards.find(b => b.id === currentBoardId);
            if (!board) return;

            board.tasks = board.tasks.filter(t => t.id !== currentTask.id);

            // Update UI
            renderBoards();
            setupDragAndDrop();

            // Save and broadcast changes
            saveData();
            socket.emit('updateBoards', boards);

            // Close modal
            closeTaskModal();
        }
    }

    function saveData() {
        localStorage.setItem('taskBoardData', JSON.stringify(boards));
    }

    function logoutUser() {
        // In a real app, this would log out the user and redirect
        currentUser = 'Guest';
        userNameSpan.textContent = currentUser;
        alert('Logged out successfully');
    }
});
