// Initialize Socket.IO connection
const socket = io();

// DOM Elements
const board = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnNameInput = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close');
const taskForm = document.getElementById('task-form');
const modalTitle = document.getElementById('modal-title');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskAssigneeInput = document.getElementById('task-assignee');
const taskDueDateInput = document.getElementById('task-due-date');
const taskPriorityInput = document.getElementById('task-priority');
const userNameSpan = document.getElementById('user-name');
const onlineUsersSpan = document.getElementById('online-users');

// App state
let currentProject = {
    id: 'default-project',
    name: 'My Project',
    columns: [
        { id: 'todo', title: 'To Do', tasks: [] },
        { id: 'in-progress', title: 'In Progress', tasks: [] },
        { id: 'done', title: 'Done', tasks: [] }
    ]
};

let draggedTask = null;
let currentTask = null;
let currentColumnId = null;

// Initialize the app
function initApp() {
    // Set a random user name for this session
    const userName = `User-${Math.floor(Math.random() * 1000)}`;
    userNameSpan.textContent = userName;
    socket.emit('set username', userName);

    // Load initial project data
    renderBoard();

    // Set up event listeners
    setupEventListeners();

    // Request initial state from server
    socket.emit('get initial state');
}

// Render the entire board
function renderBoard() {
    board.innerHTML = '';

    currentProject.columns.forEach(column => {
        const columnElement = createColumnElement(column);
        board.appendChild(columnElement);
    });

    // Make columns droppable
    makeColumnsDroppable();
}

// Create a column element
function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = column.id;

    const columnHeader = document.createElement('div');
    columnHeader.className = 'column-header';

    const columnTitle = document.createElement('h3');
    columnTitle.className = 'column-title';
    columnTitle.textContent = column.title;

    const columnActions = document.createElement('div');
    columnActions.className = 'column-actions';

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.title = 'Delete column';
    deleteBtn.addEventListener('click', () => deleteColumn(column.id));

    const renameBtn = document.createElement('button');
    renameBtn.innerHTML = '<i class="fas fa-edit"></i>';
    renameBtn.title = 'Rename column';
    renameBtn.addEventListener('click', () => renameColumn(column.id));

    columnActions.appendChild(renameBtn);
    columnActions.appendChild(deleteBtn);

    columnHeader.appendChild(columnTitle);
    columnHeader.appendChild(columnActions);

    const tasksContainer = document.createElement('div');
    tasksContainer.className = 'tasks';

    column.tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        tasksContainer.appendChild(taskElement);
    });

    const addTaskBtn = document.createElement('button');
    addTaskBtn.className = 'add-task-btn';
    addTaskBtn.textContent = 'Add Task';
    addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));

    columnElement.appendChild(columnHeader);
    columnElement.appendChild(tasksContainer);
    columnElement.appendChild(addTaskBtn);

    return columnElement;
}

// Create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;

    // Set up drag events
    taskElement.addEventListener('dragstart', handleDragStart);
    taskElement.addEventListener('dragend', handleDragEnd);

    // Click to edit
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.task-actions')) {
            openTaskModal(task.id, task.columnId);
        }
    });

    const taskHeader = document.createElement('div');
    taskHeader.className = 'task-header';

    const taskTitle = document.createElement('div');
    taskTitle.className = 'task-title';
    taskTitle.textContent = task.title;

    const taskPriority = document.createElement('div');
    taskPriority.className = `task-priority ${task.priority}`;
    taskPriority.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

    taskHeader.appendChild(taskTitle);
    taskHeader.appendChild(taskPriority);

    const taskDescription = document.createElement('div');
    taskDescription.className = 'task-description';
    taskDescription.textContent = task.description || 'No description';

    const taskMeta = document.createElement('div');
    taskMeta.className = 'task-meta';

    const assignee = document.createElement('span');
    assignee.textContent = task.assignee ? `Assigned: ${task.assignee}` : 'Unassigned';

    const dueDate = document.createElement('span');
    dueDate.textContent = task.dueDate ? `Due: ${formatDate(task.dueDate)}` : 'No due date';

    taskMeta.appendChild(assignee);
    taskMeta.appendChild(dueDate);

    taskElement.appendChild(taskHeader);
    taskElement.appendChild(taskDescription);
    taskElement.appendChild(taskMeta);

    return taskElement;
}

// Format date for display
function formatDate(dateString) {
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
}

// Set up all event listeners
function setupEventListeners() {
    // Add column button
    addColumnBtn.addEventListener('click', addNewColumn);

    // Modal close button
    closeModal.addEventListener('click', closeTaskModal);

    // Click outside modal to close
    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            closeTaskModal();
        }
    });

    // Task form submission
    taskForm.addEventListener('submit', saveTask);

    // Socket.IO events
    socket.on('initial state', (state) => {
        currentProject = state;
        renderBoard();
    });

    socket.on('column added', (column) => {
        currentProject.columns.push(column);
        renderBoard();
    });

    socket.on('column deleted', (columnId) => {
        currentProject.columns = currentProject.columns.filter(c => c.id !== columnId);
        renderBoard();
    });

    socket.on('column renamed', ({ columnId, newTitle }) => {
        const column = currentProject.columns.find(c => c.id === columnId);
        if (column) {
            column.title = newTitle;
            renderBoard();
        }
    });

    socket.on('task added', ({ columnId, task }) => {
        const column = currentProject.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks.push(task);
            renderBoard();
        }
    });

    socket.on('task updated', ({ columnId, task }) => {
        const column = currentProject.columns.find(c => c.id === columnId);
        if (column) {
            const taskIndex = column.tasks.findIndex(t => t.id === task.id);
            if (taskIndex !== -1) {
                column.tasks[taskIndex] = task;
                renderBoard();
            }
        }
    });

    socket.on('task moved', ({ fromColumnId, toColumnId, taskId }) => {
        const fromColumn = currentProject.columns.find(c => c.id === fromColumnId);
        const toColumn = currentProject.columns.find(c => c.id === toColumnId);

        if (fromColumn && toColumn) {
            const taskIndex = fromColumn.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                const [task] = fromColumn.tasks.splice(taskIndex, 1);
                task.columnId = toColumnId;
                toColumn.tasks.push(task);
                renderBoard();
            }
        }
    });

    socket.on('task deleted', ({ columnId, taskId }) => {
        const column = currentProject.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks = column.tasks.filter(t => t.id !== taskId);
            renderBoard();
        }
    });

    socket.on('online users', (count) => {
        onlineUsersSpan.textContent = `${count} online`;
    });
}

// Add a new column
function addNewColumn() {
    const columnName = newColumnNameInput.value.trim();
    if (!columnName) return;

    const newColumn = {
        id: `column-${Date.now()}`,
        title: columnName,
        tasks: []
    };

    socket.emit('add column', newColumn);
    newColumnNameInput.value = '';
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column?')) {
        socket.emit('delete column', columnId);
    }
}

// Rename a column
function renameColumn(columnId) {
    const column = currentProject.columns.find(c => c.id === columnId);
    if (!column) return;

    const newName = prompt('Enter new column name:', column.title);
    if (newName && newName.trim() !== column.title) {
        socket.emit('rename column', { columnId, newTitle: newName.trim() });
    }
}

// Open the task modal
function openTaskModal(taskId, columnId) {
    currentTask = taskId ? currentProject.columns
        .flatMap(c => c.tasks)
        .find(t => t.id === taskId) : null;
    currentColumnId = columnId;

    if (currentTask) {
        modalTitle.textContent = 'Edit Task';
        taskTitleInput.value = currentTask.title;
        taskDescriptionInput.value = currentTask.description || '';
        taskAssigneeInput.value = currentTask.assignee || '';
        taskDueDateInput.value = currentTask.dueDate || '';
        taskPriorityInput.value = currentTask.priority || 'medium';
    } else {
        modalTitle.textContent = 'Add New Task';
        taskForm.reset();
    }

    taskModal.style.display = 'block';
}

// Close the task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
    currentTask = null;
    currentColumnId = null;
}

// Save a task (add or update)
function saveTask(e) {
    e.preventDefault();

    const taskData = {
        id: currentTask ? currentTask.id : `task-${Date.now()}`,
        title: taskTitleInput.value.trim(),
        description: taskDescriptionInput.value.trim(),
        assignee: taskAssigneeInput.value.trim(),
        dueDate: taskDueDateInput.value,
        priority: taskPriorityInput.value,
        columnId: currentColumnId
    };

    if (!taskData.title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTask) {
        socket.emit('update task', { columnId: currentColumnId, task: taskData });
    } else {
        socket.emit('add task', { columnId: currentColumnId, task: taskData });
    }

    closeTaskModal();
}

// Make columns droppable
function makeColumnsDroppable() {
    const columns = document.querySelectorAll('.column');

    columns.forEach(column => {
        column.addEventListener('dragover', (e) => {
            e.preventDefault();
            column.classList.add('drag-over');
        });

        column.addEventListener('dragleave', () => {
            column.classList.remove('drag-over');
        });

        column.addEventListener('drop', (e) => {
            e.preventDefault();
            column.classList.remove('drag-over');

            if (draggedTask) {
                const fromColumnId = draggedTask.closest('.column').dataset.columnId;
                const toColumnId = column.dataset.columnId;
                const taskId = draggedTask.dataset.taskId;

                if (fromColumnId !== toColumnId) {
                    socket.emit('move task', { fromColumnId, toColumnId, taskId });
                }
            }
        });
    });
}

// Drag and drop handlers
function handleDragStart(e) {
    draggedTask = e.target;
    e.target.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/html', e.target.innerHTML);
}

function handleDragEnd(e) {
    e.target.classList.remove('dragging');
    draggedTask = null;
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
