## JavaScript (app.js)

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Sample data
    let currentUser = 'Guest';
    let tasks = [];
    let columns = [
        { id: 'todo', name: 'To Do' },
        { id: 'in-progress', name: 'In Progress' },
        { id: 'done', name: 'Done' }
    ];

    // DOM elements
    const boardElement = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const newColumnNameInput = document.getElementById('new-column-name');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const changeUserBtn = document.getElementById('change-user');
    const currentUserElement = document.getElementById('current-user');

    // Initialize the app
    initApp();

    function initApp() {
        // Set up event listeners
        addColumnBtn.addEventListener('click', addNewColumn);
        closeModal.addEventListener('click', closeTaskModal);
        taskForm.addEventListener('submit', saveTask);
        changeUserBtn.addEventListener('click', changeUser);

        // Initialize columns
        renderColumns();

        // Load sample tasks
        loadSampleTasks();

        // Initialize drag and drop
        initDragAndDrop();

        // Update current user display
        updateCurrentUserDisplay();
    }

    function renderColumns() {
        boardElement.innerHTML = '';

        columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.columnId = column.id;

            columnElement.innerHTML = `
                <div class="column-header">
                    <h3>${column.name}</h3>
                    <div class="column-actions">
                        <button class="edit-column" title="Edit column"><i class="fas fa-edit"></i></button>
                        <button class="delete-column" title="Delete column"><i class="fas fa-trash"></i></button>
                    </div>
                </div>
                <div class="task-list" data-column-id="${column.id}"></div>
                <button class="add-task-btn" data-column-id="${column.id}">
                    <i class="fas fa-plus"></i> Add Task
                </button>
            `;

            boardElement.appendChild(columnElement);

            // Add event listeners for column actions
            const editColumnBtn = columnElement.querySelector('.edit-column');
            const deleteColumnBtn = columnElement.querySelector('.delete-column');
            const addTaskBtn = columnElement.querySelector('.add-task-btn');

            editColumnBtn.addEventListener('click', () => editColumn(column.id));
            deleteColumnBtn.addEventListener('click', () => deleteColumn(column.id));
            addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));
        });

        // Render tasks in each column
        renderTasks();
    }

    function renderTasks() {
        // Clear all task lists
        document.querySelectorAll('.task-list').forEach(list => {
            list.innerHTML = '';
        });

        // Add tasks to their respective columns
        tasks.forEach(task => {
            const taskElement = createTaskElement(task);
            const columnList = document.querySelector(`.task-list[data-column-id="${task.columnId}"]`);

            if (columnList) {
                columnList.appendChild(taskElement);
            }
        });
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.dataset.taskId = task.id;

        // Set priority class
        let priorityClass = '';
        if (task.priority === 'low') priorityClass = 'priority-low';
        else if (task.priority === 'medium') priorityClass = 'priority-medium';
        else if (task.priority === 'high') priorityClass = 'priority-high';

        // Format due date
        const dueDate = task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date';

        taskElement.innerHTML = `
            <div class="task-title">${task.title}</div>
            <div class="task-description">${task.description || ''}</div>
            <div class="task-meta">
                <span class="${priorityClass}">${task.priority}</span>
                <span>${dueDate}</span>
            </div>
        `;

        // Add click event to open task details
        taskElement.addEventListener('click', (e) => {
            if (!e.target.closest('.task-card')) return;
            openTaskModal(task.id);
        });

        return taskElement;
    }

    function initDragAndDrop() {
        // Make all task lists sortable
        document.querySelectorAll('.task-list').forEach(list => {
            new Sortable(list, {
                group: 'shared', // set both lists to same group
                animation: 150,
                ghostClass: 'sortable-ghost',
                chosenClass: 'sortable-chosen',
                dragClass: 'sortable-drag',
                onEnd: function(evt) {
                    // Get the task ID and new column ID
                    const taskId = evt.item.dataset.taskId;
                    const newColumnId = evt.to.dataset.columnId;

                    // Update the task's column in our data
                    const taskIndex = tasks.findIndex(t => t.id === taskId);
                    if (taskIndex !== -1) {
                        tasks[taskIndex].columnId = newColumnId;

                        // Simulate real-time update
                        simulateRealTimeUpdate(taskId, newColumnId);
                    }
                }
            });
        });
    }

    function addNewColumn() {
        const columnName = newColumnNameInput.value.trim();
        if (!columnName) return;

        const newColumnId = 'column-' + Date.now();

        columns.push({
            id: newColumnId,
            name: columnName
        });

        newColumnNameInput.value = '';
        renderColumns();
        initDragAndDrop();
    }

    function editColumn(columnId) {
        const column = columns.find(c => c.id === columnId);
        if (!column) return;

        const newName = prompt('Enter new column name:', column.name);
        if (newName && newName.trim() !== '') {
            column.name = newName.trim();
            renderColumns();
            initDragAndDrop();
        }
    }

    function deleteColumn(columnId) {
        if (columns.length <= 1) {
            alert('You must have at least one column.');
            return;
        }

        if (!confirm('Are you sure you want to delete this column and all its tasks?')) {
            return;
        }

        // Remove the column
        columns = columns.filter(c => c.id !== columnId);

        // Remove tasks in this column
        tasks = tasks.filter(t => t.columnId !== columnId);

        renderColumns();
        initDragAndDrop();
    }

    function openTaskModal(taskId, columnId = null) {
        const task = taskId ? tasks.find(t => t.id === taskId) : null;

        // Set form values
        document.getElementById('task-id').value = task ? task.id : '';
        document.getElementById('task-title').value = task ? task.title : '';
        document.getElementById('task-description').value = task ? task.description || '' : '';
        document.getElementById('task-priority').value = task ? task.priority : 'medium';
        document.getElementById('task-due-date').value = task ? task.dueDate || '' : '';
        document.getElementById('task-assignee').value = task ? task.assignee || '' : '';

        // Show modal
        taskModal.style.display = 'flex';

        // If creating a new task, set the column ID
        if (!taskId && columnId) {
            document.getElementById('task-id').dataset.columnId = columnId;
        }
    }

    function closeTaskModal() {
        taskModal.style.display = 'none';
    }

    function saveTask(e) {
        e.preventDefault();

        const taskId = document.getElementById('task-id').value;
        const columnId = document.getElementById('task-id').dataset.columnId || tasks.find(t => t.id === taskId)?.columnId;

        const taskData = {
            id: taskId || 'task-' + Date.now(),
            title: document.getElementById('task-title').value.trim(),
            description: document.getElementById('task-description').value.trim(),
            priority: document.getElementById('task-priority').value,
            dueDate: document.getElementById('task-due-date').value,
            assignee: document.getElementById('task-assignee').value,
            columnId: columnId
        };

        if (!taskData.title) {
            alert('Please enter a task title');
            return;
        }

        if (taskId) {
            // Update existing task
            const index = tasks.findIndex(t => t.id === taskId);
            if (index !== -1) {
                tasks[index] = taskData;
            }
        } else {
            // Add new task
            tasks.push(taskData);
        }

        closeTaskModal();
        renderTasks();

        // Simulate real-time update
        simulateRealTimeUpdate(taskData.id, taskData.columnId);
    }

    function changeUser() {
        const users = ['Guest', 'User 1', 'User 2', 'User 3'];
        const currentIndex = users.indexOf(currentUser);
        const nextIndex = (currentIndex + 1) % users.length;

        currentUser = users[nextIndex];
        updateCurrentUserDisplay();

        // Notify other users about the change (simulated)
        console.log(`${currentUser} has joined the board.`);
    }

    function updateCurrentUserDisplay() {
        currentUserElement.textContent = `User: ${currentUser}`;
    }

    function loadSampleTasks() {
        // Sample tasks for demonstration
        tasks = [
            {
                id: 'task-1',
                title: 'Design homepage',
                description: 'Create wireframes and mockups for the homepage',
                priority: 'high',
                dueDate: '2023-12-15',
                assignee: 'user1',
                columnId: 'todo'
            },
            {
                id: 'task-2',
                title: 'Implement API endpoints',
                description: 'Develop RESTful API endpoints for user management',
                priority: 'medium',
                dueDate: '2023-12-20',
                assignee: 'user2',
                columnId: 'in-progress'
            },
            {
                id: 'task-3',
                title: 'Write documentation',
                description: 'Document the API and frontend components',
                priority: 'low',
                dueDate: '2023-12-30',
                assignee: '',
                columnId: 'done'
            }
        ];
    }

    // Simulate real-time updates (in a real app, this would use WebSockets or similar)
    function simulateRealTimeUpdate(taskId, columnId) {
        // In a real implementation, this would broadcast to all connected clients
        console.log(`Real-time update: Task ${taskId} moved to column ${columnId}`);

        // Simulate other users seeing the change
        setTimeout(() => {
            console.log(`${currentUser} saw the update: Task ${taskId} moved to column ${columnId}`);
        }, 500);
    }
});
