};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const auth = firebase.auth();
const database = firebase.database();

// DOM elements
const loginBtn = document.getElementById('login-btn');
const logoutBtn = document.getElementById('logout-btn');
const userStatus = document.getElementById('user-status');
const authContainer = document.getElementById('auth-container');
const projectContainer = document.getElementById('project-container');
const loginForm = document.getElementById('login-form');
const registerForm = document.getElementById('register-form');
const registerBtn = document.getElementById('register-btn');
const backToLoginBtn = document.getElementById('back-to-login');
const loginSubmit = document.getElementById('login-submit');
const registerSubmit = document.getElementById('register-submit');
const boardsContainer = document.getElementById('boards-container');
const addBoardBtn = document.getElementById('add-board-btn');
const projectTitle = document.getElementById('project-title');

// Task modal elements
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const taskForm = document.getElementById('task-form');
const saveTaskBtn = document.getElementById('save-task');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskAssigneeInput = document.getElementById('task-assignee');
const taskDueDateInput = document.getElementById('task-due-date');
const taskPriorityInput = document.getElementById('task-priority');

// Board modal elements
const boardModal = new bootstrap.Modal(document.getElementById('boardModal'));
const boardForm = document.getElementById('board-form');
const saveBoardBtn = document.getElementById('save-board');
const deleteBoardBtn = document.getElementById('delete-board');
const boardNameInput = document.getElementById('board-name');

// App state
let currentUser = null;
let currentProjectId = 'default-project'; // In a real app, this would be dynamic
let currentBoardId = null;
let currentTaskId = null;
let dragulaInstance = null;

// Initialize the app
function initApp() {
    // Set up authentication state observer
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            userStatus.textContent = `Logged in as ${user.email}`;
            loginBtn.classList.add('d-none');
            logoutBtn.classList.remove('d-none');
            authContainer.classList.add('d-none');
            projectContainer.classList.remove('d-none');

            // Load project data
            loadProjectData();
        } else {
            currentUser = null;
            userStatus.textContent = 'Not logged in';
            loginBtn.classList.remove('d-none');
            logoutBtn.classList.add('d-none');
            authContainer.classList.remove('d-none');
            projectContainer.classList.add('d-none');
        }
    });

    // Set up event listeners
    setupEventListeners();
}

// Set up event listeners
function setupEventListeners() {
    // Authentication
    loginBtn.addEventListener('click', () => {
        loginForm.classList.remove('d-none');
        registerForm.classList.add('d-none');
    });

    registerBtn.addEventListener('click', () => {
        loginForm.classList.add('d-none');
        registerForm.classList.remove('d-none');
    });

    backToLoginBtn.addEventListener('click', () => {
        loginForm.classList.remove('d-none');
        registerForm.classList.add('d-none');
    });

    loginSubmit.addEventListener('click', handleLogin);
    registerSubmit.addEventListener('click', handleRegister);
    logoutBtn.addEventListener('click', handleLogout);

    // Boards
    addBoardBtn.addEventListener('click', () => {
        currentBoardId = null;
        boardNameInput.value = '';
        boardModal.show();
    });

    saveBoardBtn.addEventListener('click', saveBoard);
    deleteBoardBtn.addEventListener('click', deleteBoard);

    // Tasks
    saveTaskBtn.addEventListener('click', saveTask);
}

// Authentication handlers
function handleLogin(e) {
    e.preventDefault();
    const email = document.getElementById('email').value;
    const password = document.getElementById('password').value;

    auth.signInWithEmailAndPassword(email, password)
        .catch(error => {
            alert(error.message);
        });
}

function handleRegister(e) {
    e.preventDefault();
    const email = document.getElementById('reg-email').value;
    const password = document.getElementById('reg-password').value;
    const confirm = document.getElementById('reg-confirm').value;

    if (password !== confirm) {
        alert("Passwords don't match");
        return;
    }

    auth.createUserWithEmailAndPassword(email, password)
        .then(() => {
