            registerForm.classList.add('d-none');
        })
        .catch(error => {
            alert(error.message);
        });
}

function handleLogout() {
    auth.signOut();
}

// Load project data from Firebase
function loadProjectData() {
    const projectRef = database.ref(`projects/${currentProjectId}`);

    // Listen for changes in the project data
    projectRef.on('value', (snapshot) => {
        const projectData = snapshot.val();

        if (projectData) {
            projectTitle.textContent = projectData.name || 'Untitled Project';

            // Load boards
            if (projectData.boards) {
                renderBoards(projectData.boards);
            } else {
                boardsContainer.innerHTML = '<p class="text-muted">No boards yet. Add one to get started!</p>';
            }
        } else {
            // Initialize project if it doesn't exist
            projectRef.set({
                name: 'My Project',
                createdAt: firebase.database.ServerValue.TIMESTAMP,
                createdBy: currentUser.uid
            });
        }
    });
}

// Render boards
function renderBoards(boards) {
    boardsContainer.innerHTML = '';

    // Convert boards object to array and sort by order
    const boardArray = Object.entries(boards || {}).map(([id, board]) => ({
        id,
        ...board
    })).sort((a, b) => a.order - b.order);

    if (boardArray.length === 0) {
        boardsContainer.innerHTML = '<p class="text-muted">No boards yet. Add one to get started!</p>';
        return;
    }

    // Create board elements
    boardArray.forEach(board => {
        const boardElement = document.createElement('div');
        boardElement.className = 'board';
        boardElement.dataset.boardId = board.id;

        boardElement.innerHTML = `
            <div class="board-header">
                <h3 class="board-title">${board.name}</h3>
                <button class="add-task-btn btn btn-sm btn-outline-secondary" data-board-id="${board.id}">+</button>
            </div>
            <div class="tasks-container" data-board-id="${board.id}"></div>
        `;

        boardsContainer.appendChild(boardElement);

        // Render tasks for this board
        renderTasks(board.id, board.tasks || {});
    });

    // Set up drag-and-drop
    setupDragAndDrop();

    // Set up board title click handlers
    document.querySelectorAll('.board-title').forEach(title => {
        title.addEventListener('click', (e) => {
            const boardId = e.target.closest('.board').dataset.boardId;
            currentBoardId = boardId;
            const boardRef = database.ref(`projects/${currentProjectId}/boards/${boardId}`);
            boardRef.once('value').then(snapshot => {
                const boardData = snapshot.val();
                boardNameInput.value = boardData.name;
                boardModal.show();
            });
        });
    });

    // Set up add task button handlers
    document.querySelectorAll('.add-task-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const boardId = e.target.dataset.boardId;
            currentBoardId = boardId;
            currentTaskId = null;
            resetTaskForm();
            taskModal.show();
        });
    });
}

// Render tasks for a specific board
function renderTasks(boardId, tasks) {
    const tasksContainer = document.querySelector(`.tasks-container[data-board-id="${boardId}"]`);
    tasksContainer.innerHTML = '';

    // Convert tasks object to array and sort by order
    const taskArray = Object.entries(tasks || {}).map(([id, task]) => ({
        id,
        ...task
    })).sort((a, b) => a.order - b.order);

    if (taskArray.length === 0) {
        tasksContainer.innerHTML = '<p class="text-muted text-center">No tasks yet</p>';
        return;
    }

    // Create task elements
    taskArray.forEach(task => {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.dataset.taskId = task.id;
        taskElement.dataset.boardId = boardId;

        // Determine priority class
        let priorityClass = '';
        switch (task.priority) {
            case 'low':
                priorityClass = 'priority-low';
                break;
            case 'medium':
                priorityClass = 'priority-medium';
                break;
            case 'high':
                priorityClass = 'priority-high';
                break;
        }

        taskElement.innerHTML = `
            <h5 class="task-title">${task.title}</h5>
            <div class="task-meta">
                <span>${task.assignee || 'Unassigned'}</span>
                <span class="${priorityClass}">${task.priority || 'medium'}</span>
            </div>
        `;

        tasksContainer.appendChild(taskElement);

        // Set up task click handler
        taskElement.addEventListener('click', (e) => {
            e.stopPropagation();
            currentBoardId = boardId;
            currentTaskId = task.id;
            loadTaskData(task.id);
            taskModal.show();
        });
    });
}

// Set up drag-and-drop functionality
function setupDragAndDrop() {
    // Destroy previous instance if it exists
    if (dragulaInstance) {
        dragulaInstance.destroy();
    }

    // Get all task containers
    const taskContainers = Array.from(document.querySelectorAll('.tasks-container'));

    // Initialize dragula
    dragulaInstance = dragula(taskContainers, {
        moves: (el, container, handle) => {
            // Only allow dragging of task elements
            return el.classList.contains('task');
        },
        accepts: (el, target, source, sibling) => {
            // Allow dropping in any task container
            return target.classList.contains('tasks-container');
        }
    });

    // Handle drop event
    dragulaInstance.on('drop', (el, target, source, sibling) => {
        const taskId = el.dataset.taskId;
        const oldBoardId = el.dataset.boardId;
        const newBoardId = target.dataset.boardId;

        // Update task in database
        const taskRef = database.ref(`projects/${currentProjectId}/boards/${oldBoardId}/tasks/${taskId}`);
        const newTaskRef = database.ref(`projects/${currentProjectId}/boards/${newBoardId}/tasks/${taskId}`);

        // Get the current task data
        taskRef.once('value').then(snapshot => {
            const taskData = snapshot.val();

            // Remove from old board
            taskRef.remove();

            // Add to new board
            newTaskRef.set({
                ...taskData,
                boardId: newBoardId
            });

            // Update the element's data attribute
            el.dataset.boardId = newBoardId;
        });
    });
}

// Save board
function saveBoard() {
    const boardName = boardNameInput.value.trim();

    if (!boardName) {
        alert('Please enter a board name');
        return;
    }

    if (currentBoardId) {
        // Update existing board
        const boardRef = database.ref(`projects/${currentProjectId}/boards/${currentBoardId}`);
        boardRef.update({
            name: boardName
        });
    } else {
        // Create new board
        const newBoardRef = database.ref(`projects/${currentProjectId}/boards`).push();
        newBoardRef.set({
            name: boardName,
            order: Date.now(),
            createdAt: firebase.database.ServerValue.TIMESTAMP,
            createdBy: currentUser.uid
        });
    }

    boardModal.hide();
}

// Delete board
function deleteBoard() {
    if (!currentBoardId) return;

    if (confirm('Are you sure you want to delete this board? All tasks will be lost.')) {
        const boardRef = database.ref(`projects/${currentProjectId}/boards/${currentBoardId}`);
        boardRef.remove();
        boardModal.hide();
    }
}

// Reset task form
function resetTaskForm() {
    taskTitleInput.value = '';
    taskDescriptionInput.value = '';
    taskAssigneeInput.value = '';
    taskDueDateInput.value = '';
    taskPriorityInput.value = 'medium';
}

// Load task data into form
function loadTaskData(taskId) {
    const taskRef = database.ref(`projects/${currentProjectId}/boards/${currentBoardId}/tasks/${taskId}`);
    taskRef.once('value').then(snapshot => {
        const taskData = snapshot.val();

        if (taskData) {
            taskTitleInput.value = taskData.title || '';
            taskDescriptionInput.value = taskData.description || '';
            taskAssigneeInput.value = taskData.assignee || '';
            taskDueDateInput.value = taskData.dueDate || '';
            taskPriorityInput.value = taskData.priority || 'medium';
        }
    });
}

// Save task
function saveTask() {
    const title = taskTitleInput.value.trim();
    const description = taskDescriptionInput.value.trim();
    const assignee = taskAssigneeInput.value.trim();
    const dueDate = taskDueDateInput.value;
    const priority = taskPriorityInput.value;

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTaskId) {
        // Update existing task
        const taskRef = database.ref(`projects/${currentProjectId}/boards/${currentBoardId}/tasks/${currentTaskId}`);
        taskRef.update({
            title,
            description,
            assignee,
            dueDate,
            priority,
            updatedAt: firebase.database.ServerValue.TIMESTAMP,
            updatedBy: currentUser.uid
        });
    } else {
        // Create new task
        const newTaskRef = database.ref(`projects/${currentProjectId}/boards/${currentBoardId}/tasks`).push();
        newTaskRef.set({
            title,
            description,
            assignee,
            dueDate,
            priority,
            order: Date.now(),
            createdAt: firebase.database.ServerValue.TIMESTAMP,
            createdBy: currentUser.uid,
            boardId: currentBoardId
        });
    }

    taskModal.hide();
}

// Initialize the app when the page loads
window.addEventListener('DOMContentLoaded', initApp);
