// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const auth = firebase.auth();
const database = firebase.database();

// DOM elements
const boardsContainer = document.getElementById('boards-container');
const projectSelect = document.getElementById('project-select');
const newProjectBtn = document.getElementById('new-project-btn');
const taskModal = document.getElementById('task-modal');
const modalTitle = document.getElementById('modal-title');
const taskForm = document.getElementById('task-form');
const taskTitle = document.getElementById('task-title');
const taskDescription = document.getElementById('task-description');
const taskPriority = document.getElementById('task-priority');
const taskDueDate = document.getElementById('task-due-date');
const taskAssignee = document.getElementById('task-assignee');
const closeModal = document.querySelector('.close-modal');
const userName = document.getElementById('user-name');
const logoutBtn = document.getElementById('logout-btn');
const collaboratorsList = document.getElementById('collaborators-list');
const addCollaboratorBtn = document.getElementById('add-collaborator-btn');
const collaboratorEmail = document.getElementById('collaborator-email');

// App state
let currentUser = null;
let currentProjectId = null;
let currentTaskId = null;
let socket = null;

// Initialize the app
function initApp() {
    // Check authentication state
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            userName.textContent = user.email.split('@')[0];
            setupRealTimeConnection();
            loadProjects();
            loadCollaborators();
        } else {
            // Show login UI (simplified for this example)
            userName.textContent = 'Guest';
            logoutBtn.style.display = 'none';
        }
    });

    // Event listeners
    newProjectBtn.addEventListener('click', createNewProject);
    projectSelect.addEventListener('change', loadProjectBoards);
    closeModal.addEventListener('click', closeTaskModal);
    taskForm.addEventListener('submit', saveTask);
    logoutBtn.addEventListener('click', logout);
    addCollaboratorBtn.addEventListener('click', addCollaborator);

    // Initialize drag and drop
    setupDragAndDrop();
}

// Set up real-time connection with Socket.io
function setupRealTimeConnection() {
    socket = io('http://localhost:3000'); // Replace with your server URL

    socket.on('connect', () => {
        console.log('Connected to real-time server');
        socket.emit('joinProject', currentProjectId);
    });

    socket.on('taskUpdated', (taskData) => {
        if (currentProjectId === taskData.projectId) {
            updateTaskInUI(taskData);
        }
    });

    socket.on('taskDeleted', (taskId) => {
        if (currentProjectId) {
            removeTaskFromUI(taskId);
        }
    });

    socket.on('boardUpdated', (boardData) => {
        if (currentProjectId === boardData.projectId) {
            updateBoardInUI(boardData);
        }
    });

    socket.on('collaboratorAdded', (collaborator) => {
        if (currentProjectId === collaborator.projectId) {
            addCollaboratorToUI(collaborator);
        }
    });
}

// Load projects from Firebase
function loadProjects() {
    const projectsRef = database.ref(`users/${currentUser.uid}/projects`);

    projectsRef.on('value', (snapshot) => {
        projectSelect.innerHTML = '<option value="default">Select a project</option>';

        if (snapshot.exists()) {
            snapshot.forEach(childSnapshot => {
                const project = childSnapshot.val();
                const option = document.createElement('option');
                option.value = childSnapshot.key;
                option.textContent = project.name;
                projectSelect.appendChild(option);
            });

            // Select the first project by default
            if (projectSelect.options.length > 1) {
                projectSelect.selectedIndex = 1;
                loadProjectBoards();
            }
        }
    });
}

// Create a new project
function createNewProject() {
    const projectName = prompt('Enter project name:');
    if (projectName) {
        const newProjectRef = database.ref(`users/${currentUser.uid}/projects`).push();
        newProjectRef.set({
            name: projectName,
            createdAt: firebase.database.ServerValue.TIMESTAMP,
            boards: {
                'to-do': { name: 'To Do', order: 0 },
                'in-progress': { name: 'In Progress', order: 1 },
                'done': { name: 'Done', order: 2 }
            }
        });

        // Add current user as collaborator
        const collaboratorRef = database.ref(`projects/${newProjectRef.key}/collaborators/${currentUser.uid}`);
        collaboratorRef.set({
            email: currentUser.email,
            role: 'owner',
            joinedAt: firebase.database.ServerValue.TIMESTAMP
        });
    }
}

// Load boards for the selected project
function loadProjectBoards() {
    currentProjectId = projectSelect.value;

    if (currentProjectId === 'default') {
        boardsContainer.innerHTML = '';
        return;
    }

    const boardsRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/boards`);
    boardsRef.on('value', (snapshot) => {
        boardsContainer.innerHTML = '';

        if (snapshot.exists()) {
            const boards = snapshot.val();
            const sortedBoards = Object.entries(boards).sort((a, b) => a[1].order - b[1].order);

            sortedBoards.forEach(([boardId, board]) => {
                createBoardElement(boardId, board);
            });
        }

        // Add "Add Board" button
        const addBoardBtn = document.createElement('button');
        addBoardBtn.className = 'btn add-board-btn';
        addBoardBtn.innerHTML = '<i class="fas fa-plus"></i> Add Board';
        addBoardBtn.addEventListener('click', addNewBoard);
        boardsContainer.appendChild(addBoardBtn);
    });

    // Load tasks for this project
    loadTasks();
}

// Create a board element
function createBoardElement(boardId, board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'board';
    boardElement.dataset.boardId = boardId;

    boardElement.innerHTML = `
        <div class="board-header">
            <span class="board-title">${board.name}</span>
            <div class="board-actions">
                <button class="edit-board-btn" title="Edit board"><i class="fas fa-pencil-alt"></i></button>
                <button class="delete-board-btn" title="Delete board"><i class="fas fa-trash"></i></button>
            </div>
        </div>
        <div class="board-content" data-board-id="${boardId}">
            <!-- Tasks will be added here -->
        </div>
        <button class="btn add-task-btn" data-board-id="${boardId}">
            <i class="fas fa-plus"></i> Add Task
        </button>
    `;

    // Add event listeners
    boardElement.querySelector('.add-task-btn').addEventListener('click', (e) => {
        openTaskModal(null, e.target.dataset.boardId);
    });

    boardElement.querySelector('.edit-board-btn').addEventListener('click', () => {
        editBoard(boardId, board.name);
    });

    boardElement.querySelector('.delete-board-btn').addEventListener('click', () => {
        deleteBoard(boardId);
    });

    boardsContainer.appendChild(boardElement);
}

// Add a new board
function addNewBoard() {
    const boardName = prompt('Enter board name:');
    if (boardName) {
        const boardsRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/boards`);
        const newBoardRef = boardsRef.push();
        newBoardRef.set({
            name: boardName,
            order: Object.keys(boardsRef).length
        });
    }
}

// Edit a board
function editBoard(boardId, currentName) {
    const newName = prompt('Enter new board name:', currentName);
    if (newName && newName !== currentName) {
        const boardRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/boards/${boardId}`);
        boardRef.update({ name: newName });
    }
}

// Delete a board
function deleteBoard(boardId) {
    if (confirm('Are you sure you want to delete this board? All tasks will be lost.')) {
        const boardRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/boards/${boardId}`);
        boardRef.remove();
    }
}

// Load tasks for the current project
function loadTasks() {
    const tasksRef = database.ref(`projects/${currentProjectId}/tasks`);

    tasksRef.on('value', (snapshot) => {
        // Clear all tasks first
        document.querySelectorAll('.task').forEach(task => task.remove());

        if (snapshot.exists()) {
            snapshot.forEach(childSnapshot => {
                const task = childSnapshot.val();
                addTaskToBoard(task.boardId, task);
            });
        }
    });
}

// Add task to a specific board
function addTaskToBoard(boardId, task) {
    const boardContent = document.querySelector(`.board-content[data-board-id="${boardId}"]`);
    if (!boardContent) return;

    const taskElement = createTaskElement(task);
    boardContent.appendChild(taskElement);
}

// Create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;

    // Set priority class
    let priorityClass = '';
    switch (task.priority) {
        case 'low': priorityClass = 'priority-low'; break;
        case 'medium': priorityClass = 'priority-medium'; break;
        case 'high': priorityClass = 'priority-high'; break;
    }

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-title">${task.title}</span>
            <span class="task-priority ${priorityClass}">${task.priority}</span>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span class="task-assignee">${task.assignee ? task.assignee.split('@')[0] : 'Unassigned'}</span>
            <span class="task-due-date">${task.dueDate || ''}</span>
        </div>
    `;

    // Add event listeners
    taskElement.addEventListener('dragstart', handleDragStart);
    taskElement.addEventListener('click', () => openTaskModal(task.id, task.boardId));

    return taskElement;
}

// Open task modal for editing or creating
function openTaskModal(taskId, boardId) {
    currentTaskId = taskId;
    const boardName = document.querySelector(`.board[data-board-id="${boardId}"] .board-title`).textContent;

    if (taskId) {
        // Editing existing task
        modalTitle.textContent = 'Edit Task';
        const taskRef = database.ref(`projects/${currentProjectId}/tasks/${taskId}`);
        taskRef.once('value', (snapshot) => {
            if (snapshot.exists()) {
                const task = snapshot.val();
                taskTitle.value = task.title;
                taskDescription.value = task.description || '';
                taskPriority.value = task.priority || 'medium';
                taskDueDate.value = task.dueDate || '';
                taskAssignee.value = task.assignee || '';
            }
        });
    } else {
        // Creating new task
        modalTitle.textContent = `Add Task to ${boardName}`;
        taskTitle.value = '';
        taskDescription.value = '';
        taskPriority.value = 'medium';
        taskDueDate.value = '';
        taskAssignee.value = '';
    }

    taskModal.style.display = 'flex';
}

// Close task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
}

// Save task (create or update)
function saveTask(e) {
    e.preventDefault();

    const taskData = {
        title: taskTitle.value,
        description: taskDescription.value,
        priority: taskPriority.value,
        dueDate: taskDueDate.value,
        assignee: taskAssignee.value,
        boardId: currentTaskId ? document.querySelector(`.task[data-task-id="${currentTaskId}"]`).closest('.board-content').dataset.boardId : taskForm.closest('.add-task-btn').dataset.boardId,
        updatedAt: firebase.database.ServerValue.TIMESTAMP
    };

    if (currentTaskId) {
        // Update existing task
        const taskRef = database.ref(`projects/${currentProjectId}/tasks/${currentTaskId}`);
        taskRef.update(taskData);
    } else {
        // Create new task
        const tasksRef = database.ref(`projects/${currentProjectId}/tasks`);
        const newTaskRef = tasksRef.push();
        taskData.id = newTaskRef.key;
        newTaskRef.set(taskData);
    }

    closeTaskModal();
}

// Update task in UI
function updateTaskInUI(taskData) {
    const existingTask = document.querySelector(`.task[data-task-id="${taskData.id}"]`);
    if (existingTask) {
        // Task exists, update it
        const taskElement = createTaskElement(taskData);
        existingTask.replaceWith(taskElement);
    } else {
        // Task doesn't exist, add it to the correct board
        addTaskToBoard(taskData.boardId, taskData);
    }
}

// Remove task from UI
function removeTaskFromUI(taskId) {
    const taskElement = document.querySelector(`.task[data-task-id="${taskId}"]`);
    if (taskElement) {
        taskElement.remove();
    }
}

// Update board in UI
function updateBoardInUI(boardData) {
    const boardElement = document.querySelector(`.board[data-board-id="${boardData.id}"]`);
    if (boardElement) {
        boardElement.querySelector('.board-title').textContent = boardData.name;
    }
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    let draggedTask = null;

    document.addEventListener('dragstart', (e) => {
        if (e.target.classList.contains('task')) {
            draggedTask = e.target;
            e.target.classList.add('dragging');
            e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
            e.dataTransfer.effectAllowed = 'move';
        }
    });

    document.addEventListener('dragend', (e) => {
        if (e.target.classList.contains('task')) {
            e.target.classList.remove('dragging');
        }
    });

    document.addEventListener('dragover', (e) => {
        e.preventDefault();
        const boardContent = e.target.closest('.board-content');
        if (boardContent) {
            e.dataTransfer.dropEffect = 'move';
        }
    });

    document.addEventListener('drop', (e) => {
        e.preventDefault();
        const boardContent = e.target.closest('.board-content');
        if (boardContent && draggedTask) {
            const taskId = e.dataTransfer.getData('text/plain');
            const newBoardId = boardContent.dataset.boardId;

            // Update task in database
            const taskRef = database.ref(`projects/${currentProjectId}/tasks/${taskId}`);
            taskRef.update({ boardId: newBoardId });

            // Move task in UI
            boardContent.appendChild(draggedTask);
            draggedTask.classList.remove('dragging');
            draggedTask = null;
        }
    });
}

// Load collaborators for the current project
function loadCollaborators() {
    if (!currentProjectId) return;

    const collaboratorsRef = database.ref(`projects/${currentProjectId}/collaborators`);

    collaboratorsRef.on('value', (snapshot) => {
        collaboratorsList.innerHTML = '';

        if (snapshot.exists()) {
            snapshot.forEach(childSnapshot => {
                const collaborator = childSnapshot.val();
                addCollaboratorToUI(collaborator);
            });
        }
    });
}

// Add collaborator to UI
function addCollaboratorToUI(collaborator) {
