    if (email && currentProjectId) {
        // In a real app, you would send an invitation email
        const collaboratorRef = database.ref(`projects/${currentProjectId}/collaborators`);
        const newCollaboratorRef = collaboratorRef.push();

        newCollaboratorRef.set({
            email: email,
