## Backend Server (server.js)

For real-time collaboration, you'll need a simple Node.js server with Socket.io:

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const admin = require('firebase-admin');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json'); // Download from Firebase Console

admin.initializeApp({
    credential: admin.credential.cert(serviceAccount),
    databaseURL: "YOUR_DATABASE_URL"
});

const db = admin.database();

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Join a project room
    socket.on('joinProject', (projectId) => {
        if (projectId) {
            socket.join(projectId);
            console.log(`Client joined project ${projectId}`);
        }
    });

    // Leave a project room
    socket.on('leaveProject', (projectId) => {
        if (projectId) {
            socket.leave(projectId);
            console.log(`Client left project ${projectId}`);
        }
    });

    // Disconnect
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

// Watch for database changes and broadcast to clients
function setupDatabaseListeners() {
    // Watch for task changes
    db.ref('projects').on('child_changed', (snapshot) => {
        const projectId = snapshot.key;
        const tasksRef = snapshot.ref.child('tasks');

        tasksRef.on('child_changed', (taskSnapshot) => {
            const taskData = taskSnapshot.val();
            io.to(projectId).emit('taskUpdated', taskData);
        });

        tasksRef.on('child_removed', (taskSnapshot) => {
            const taskId = taskSnapshot.key;
            io.to(projectId).emit('taskDeleted', taskId);
        });
    });

    // Watch for board changes
    db.ref('users').on('child_changed', (userSnapshot) => {
        const projectsRef = userSnapshot.ref.child('projects');

        projectsRef.on('child_changed', (projectSnapshot) => {
            const projectId = projectSnapshot.key;
            const boardsRef = projectSnapshot.ref.child('boards');

            boardsRef.on('child_changed', (boardSnapshot) => {
                const boardData = boardSnapshot.val();
                boardData.id = boardSnapshot.key;
                boardData.projectId = projectId;
                io.to(projectId).emit('boardUpdated', boardData);
            });
        });
    });

    // Watch for collaborator changes
    db.ref('projects').on('child_changed', (projectSnapshot) => {
        const projectId = projectSnapshot.key;
        const collaboratorsRef = projectSnapshot.ref.child('collaborators');

        collaboratorsRef.on('child_added', (collaboratorSnapshot) => {
            const collaborator = collaboratorSnapshot.val();
            collaborator.projectId = projectId;
            io.to(projectId).emit('collaboratorAdded', collaborator);
        });
    });
}

setupDatabaseListeners();

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

