            return el.classList.contains('task-list');
        },
        moves: function (el, source, handle, sibling) {
            return el.classList.contains('task');
        }
    });

    // Handle drag events
    drake.on('drag', function(el, source) {
        el.classList.add('dragging');
    });

    drake.on('dragend', function(el) {
        el.classList.remove('dragging');
    });

    drake.on('drop', function(el, target, source, sibling) {
        // Update the board state
        const taskId = el.dataset.taskId;
        const sourceColumnId = source.parentElement.dataset.columnId;
        const targetColumnId = target.parentElement.dataset.columnId;

        // Find the task in the source column
        const sourceColumn = boardState.columns.find(col => col.id === sourceColumnId);
        const taskIndex = sourceColumn.tasks.findIndex(task => task.id === taskId);
        const [task] = sourceColumn.tasks.splice(taskIndex, 1);

        // Add to target column
        const targetColumn = boardState.columns.find(col => col.id === targetColumnId);
        targetColumn.tasks.push(task);

        // Save to localStorage
        saveBoardState();

        // Emit change to other clients
        socket.emit('task-moved', {
            taskId,
            sourceColumnId,
            targetColumnId,
            userId
        });
    });

    // Render the board
    function renderBoard() {
        board.innerHTML = '';

        boardState.columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.columnId = column.id;

            columnElement.innerHTML = `
                <div class="column-header">
                    <h3 class="column-title">${column.title}</h3>
                    <div class="column-actions">
                        <button class="add-task-btn" data-column-id="${column.id}">+</button>
                        <button class="delete-column-btn" data-column-id="${column.id}">×</button>
                    </div>
                </div>
                <div class="task-list" data-column-id="${column.id}">
                    ${column.tasks.map(task => createTaskElement(task)).join('')}
                </div>
            `;

            board.appendChild(columnElement);
        });

        // Add event listeners for new elements
        document.querySelectorAll('.add-task-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                currentColumn = this.dataset.columnId;
                currentTask = null;

                // Reset modal
                taskTitleInput.value = '';
                taskDescriptionInput.value = '';
                taskAssigneeInput.value = '';
                taskDueDateInput.value = '';

                modal.style.display = 'block';
            });
        });

        document.querySelectorAll('.delete-column-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const columnId = this.dataset.columnId;
                if (confirm('Are you sure you want to delete this column?')) {
                    boardState.columns = boardState.columns.filter(col => col.id !== columnId);
                    saveBoardState();
                    renderBoard();
                    socket.emit('column-deleted', { columnId, userId });
                }
            });
        });

        document.querySelectorAll('.task').forEach(task => {
            task.addEventListener('click', function(e) {
                if (e.target.classList.contains('task')) {
                    currentTask = this.dataset.taskId;
                    currentColumn = this.closest('.task-list').dataset.columnId;

                    // Find the task in the board state
                    const column = boardState.columns.find(col => col.id === currentColumn);
                    const taskData = column.tasks.find(t => t.id === currentTask);

                    // Populate modal with task data
                    taskTitleInput.value = taskData.title || '';
                    taskDescriptionInput.value = taskData.description || '';
                    taskAssigneeInput.value = taskData.assignee || '';
                    taskDueDateInput.value = taskData.dueDate || '';

                    modal.style.display = 'block';
                }
            });
        });
    }

    // Create task element
    function createTaskElement(task) {
        return `
            <div class="task" data-task-id="${task.id}">
                <div class="task-header">
                    <span class="task-title">${task.title}</span>
                    <span class="task-priority ${task.priority || 'medium'}">${task.priority || 'medium'}</span>
                </div>
                <div class="task-meta">
                    ${task.assignee ? `<span>Assigned to: ${task.assignee}</span>` : ''}
                    ${task.dueDate ? `<span>Due: ${formatDate(task.dueDate)}</span>` : ''}
                </div>
            </div>
        `;
    }

    // Format date for display
    function formatDate(dateString) {
        if (!dateString) return '';
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    }

    // Save board state to localStorage
    function saveBoardState() {
        localStorage.setItem('boardState', JSON.stringify(boardState));
    }

    // Generate a simple user ID
    function generateUserId() {
        return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
    }

    // Add new column
    addColumnBtn.addEventListener('click', function() {
        const columnName = newColumnName.value.trim();
        if (columnName) {
            const newColumn = {
                id: 'col-' + Date.now(),
                title: columnName,
                tasks: []
            };

            boardState.columns.push(newColumn);
            saveBoardState();
            renderBoard();
            newColumnName.value = '';

            // Notify other clients
            socket.emit('column-added', { column: newColumn, userId });
        }
    });

    // Modal event listeners
    closeModal.addEventListener('click', function() {
        modal.style.display = 'none';
    });

    window.addEventListener('click', function(event) {
        if (event.target === modal) {
            modal.style.display = 'none';
        }
    });

    saveTaskBtn.addEventListener('click', function() {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();
        const assignee = taskAssigneeInput.value.trim();
        const dueDate = taskDueDateInput.value;

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        if (currentTask) {
            // Update existing task
            const column = boardState.columns.find(col => col.id === currentColumn);
            const taskIndex = column.tasks.findIndex(t => t.id === currentTask);
            const updatedTask = {
                ...column.tasks[taskIndex],
                title,
                description,
                assignee,
                dueDate
            };

            column.tasks[taskIndex] = updatedTask;
            saveBoardState();
            renderBoard();

            // Notify other clients
            socket.emit('task-updated', {
                taskId: currentTask,
                columnId: currentColumn,
                task: updatedTask,
                userId
            });
        } else {
            // Add new task
            const newTask = {
                id: 'task-' + Date.now(),
                title,
                description,
                assignee,
                dueDate,
                priority: 'medium'
            };

            const column = boardState.columns.find(col => col.id === currentColumn);
            column.tasks.push(newTask);
            saveBoardState();
            renderBoard();

            // Notify other clients
            socket.emit('task-added', {
                columnId: currentColumn,
                task: newTask,
                userId
            });
        }

        modal.style.display = 'none';
    });

    deleteTaskBtn.addEventListener('click', function() {
        if (currentTask && confirm('Are you sure you want to delete this task?')) {
            const column = boardState.columns.find(col => col.id === currentColumn);
            column.tasks = column.tasks.filter(t => t.id !== currentTask);
            saveBoardState();
            renderBoard();

            // Notify other clients
            socket.emit('task-deleted', {
                taskId: currentTask,
                columnId: currentColumn,
                userId
            });

            modal.style.display = 'none';
        }
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
        socket.emit('join-board', { userId, userName });
    });

    socket.on('user-count', (count) => {
        document.getElementById('online-users').textContent = `${count} online`;
    });

    socket.on('board-state', (state) => {
        boardState = state;
        renderBoard();
    });

    socket.on('column-added', (data) => {
        if (data.userId !== userId) {
            boardState.columns.push(data.column);
            renderBoard();
        }
    });

    socket.on('column-deleted', (data) => {
        if (data.userId !== userId) {
            boardState.columns = boardState.columns.filter(col => col.id !== data.columnId);
            renderBoard();
        }
    });

    socket.on('task-added', (data) => {
        if (data.userId !== userId) {
            const column = boardState.columns.find(col => col.id === data.columnId);
            column.tasks.push(data.task);
            renderBoard();
        }
    });

    socket.on('task-updated', (data) => {
        if (data.userId !== userId) {
            const column = boardState.columns.find(col => col.id === data.columnId);
            const taskIndex = column.tasks.findIndex(t => t.id === data.taskId);
            if (taskIndex !== -1) {
                column.tasks[taskIndex] = data.task;
                renderBoard();
            }
        }
    });

    socket.on('task-deleted', (data) => {
        if (data.userId !== userId) {
            const column = boardState.columns.find(col => col.id === data.columnId);
            column.tasks = column.tasks.filter(t => t.id !== data.taskId);
            renderBoard();
        }
    });

    socket.on('task-moved', (data) => {
        if (data.userId !== userId) {
            // Find the task in the source column
            const sourceColumn = boardState.columns.find(col => col.id === data.sourceColumnId);
            const taskIndex = sourceColumn.tasks.findIndex(task => task.id === data.taskId);
            const [task] = sourceColumn.tasks.splice(taskIndex, 1);

            // Add to target column
            const targetColumn = boardState.columns.find(col => col.id === data.targetColumnId);
            targetColumn.tasks.push(task);

            renderBoard();
        }
    });

    // Initial render
    renderBoard();
});
