## Server Implementation (Node.js with Socket.io)

For real-time collaboration, you'll need a simple server. Here's a basic implementation:

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
    cors: {
        origin: "*",
        methods: ["GET", "POST"]
    }
});

// Store connected users and board state
const users = new Map();
let boardState = {
    columns: [
        { id: 'todo', title: 'To Do', tasks: [] },
        { id: 'in-progress', title: 'In Progress', tasks: [] },
        { id: 'done', title: 'Done', tasks: [] }
    ]
};

io.on('connection', (socket) => {
    console.log('New client connected');

    // Handle user joining
    socket.on('join-board', (data) => {
        users.set(socket.id, data);
        io.emit('user-count', users.size);

        // Send current board state to the new user
        socket.emit('board-state', boardState);
    });

    // Handle column additions
    socket.on('column-added', (data) => {
        boardState.columns.push(data.column);
        socket.broadcast.emit('column-added', data);
    });

    // Handle column deletions
    socket.on('column-deleted', (data) => {
        boardState.columns = boardState.columns.filter(col => col.id !== data.columnId);
        socket.broadcast.emit('column-deleted', data);
    });

    // Handle task additions
    socket.on('task-added', (data) => {
        const column = boardState.columns.find(col => col.id === data.columnId);
        column.tasks.push(data.task);
        socket.broadcast.emit('task-added', data);
    });

    // Handle task updates
    socket.on('task-updated', (data) => {
        const column = boardState.columns.find(col => col.id === data.columnId);
        const taskIndex = column.tasks.findIndex(t => t.id === data.taskId);
        if (taskIndex !== -1) {
            column.tasks[taskIndex] = data.task;
            socket.broadcast.emit('task-updated', data);
        }
    });

    // Handle task deletions
    socket.on('task-deleted', (data) => {
        const column = boardState.columns.find(col => col.id === data.columnId);
        column.tasks = column.tasks.filter(t => t.id !== data.taskId);
        socket.broadcast.emit('task-deleted', data);
    });

    // Handle task movements
    socket.on('task-moved', (data) => {
        // Find the task in the source column
        const sourceColumn = boardState.columns.find(col => col.id === data.sourceColumnId);
        const taskIndex = sourceColumn.tasks.findIndex(task => task.id === data.taskId);
        const [task] = sourceColumn.tasks.splice(taskIndex, 1);

        // Add to target column
        const targetColumn = boardState.columns.find(col => col.id === data.targetColumnId);
        targetColumn.tasks.push(task);

        socket.broadcast.emit('task-moved', data);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        users.delete(socket.id);
        io.emit('user-count', users.size);
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

