## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const userCountElement = document.getElementById('user-count');

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            const status = button.getAttribute('data-status');
            showTaskForm(status);
        });
    });

    // Socket.io events
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('taskAdded', (task) => {
        addTaskToDOM(task);
    });

    socket.on('taskUpdated', (task) => {
        updateTaskInDOM(task);
    });

    socket.on('taskDeleted', (taskId) => {
        removeTaskFromDOM(taskId);
    });

    socket.on('userCount', (count) => {
        userCountElement.textContent = count;
    });

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragEnd(e) {
        e.target.classList.remove('dragging');
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        e.target.classList.add('drag-over');
    }

    function dragLeave(e) {
        e.target.classList.remove('drag-over');
    }

    function drop(e) {
        e.preventDefault();
        e.target.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.getElementById(taskId);
        const newStatus = e.target.getAttribute('data-status');

        if (taskElement && newStatus) {
            // Update the task status
            const task = {
                id: taskId,
                content: taskElement.querySelector('.task-content').textContent,
                status: newStatus
            };

            // Move the task in the DOM
            e.target.appendChild(taskElement);

            // Emit update to server
            socket.emit('updateTask', task);
        }
    }

    // Task form functions
    function showTaskForm(status) {
        const form = document.createElement('div');
        form.className = 'task-form';
        form.innerHTML = `
            <textarea placeholder="Enter task description..."></textarea>
            <div class="form-actions">
                <button class="save-btn">Save</button>
                <button class="cancel-btn">Cancel</button>
            </div>
        `;

        const column = document.querySelector(`.column[data-status="${status}"] .task-list`);
        column.appendChild(form);

        const textarea = form.querySelector('textarea');
        textarea.focus();

        form.querySelector('.save-btn').addEventListener('click', () => {
            const content = textarea.value.trim();
            if (content) {
                const task = {
                    id: 'task-' + Date.now(),
                    content: content,
                    status: status
                };
                socket.emit('addTask', task);
                form.remove();
            }
        });

        form.querySelector('.cancel-btn').addEventListener('click', () => {
            form.remove();
        });
    }

    // DOM manipulation functions
    function addTaskToDOM(task) {
        const taskElement = createTaskElement(task);
        const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
        taskList.appendChild(taskElement);
    }

    function updateTaskInDOM(task) {
        const existingTask = document.getElementById(task.id);
        if (existingTask) {
            existingTask.querySelector('.task-content').textContent = task.content;

            // Move to correct column if status changed
            const currentList = existingTask.parentElement;
            const targetList = document.querySelector(`.task-list[data-status="${task.status}"]`);

            if (currentList !== targetList) {
                targetList.appendChild(existingTask);
            }
        } else {
            addTaskToDOM(task);
        }
    }

    function removeTaskFromDOM(taskId) {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.id = task.id;
        taskElement.draggable = true;
        taskElement.innerHTML = `
            <div class="task-content">${task.content}</div>
        `;

        taskElement.addEventListener('dragstart', dragStart);
        taskElement.addEventListener('dragend', dragEnd);

        return taskElement;
    }
});
