## script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    const socket = io();
    let currentTaskId = null;
    let currentStatus = null;

    // DOM elements
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const userCountElement = document.getElementById('user-count');

    // Initialize drag and drop
    initDragAndDrop();

    // Event listeners for add task buttons
    document.querySelectorAll('.add-task-btn').forEach(button => {
        button.addEventListener('click', function() {
            currentStatus = this.getAttribute('data-status');
            currentTaskId = null;
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            taskModal.style.display = 'block';
        });
    });

    // Close modal
    closeModal.addEventListener('click', function() {
        taskModal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', function() {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (title) {
            if (currentTaskId) {
                // Update existing task
                socket.emit('update-task', {
                    id: currentTaskId,
                    title,
                    description,
                    status: currentStatus
                });
            } else {
                // Create new task
                const newTask = {
                    id: Date.now().toString(),
                    title,
                    description,
                    status: currentStatus
                };
                socket.emit('new-task', newTask);
            }
            taskModal.style.display = 'none';
        }
    });

    // Socket.IO events
    socket.on('task-created', (task) => {
        addTaskToBoard(task);
    });

    socket.on('task-updated', (task) => {
        updateTaskOnBoard(task);
    });

    socket.on('task-moved', (data) => {
        moveTaskOnBoard(data.taskId, data.newStatus);
    });

    socket.on('task-deleted', (taskId) => {
        deleteTaskFromBoard(taskId);
    });

    socket.on('user-count', (count) => {
        userCountElement.textContent = count;
    });

    // Initialize with sample data
    socket.emit('get-tasks');

    // Drag and drop functions
    function initDragAndDrop() {
        const taskLists = document.querySelectorAll('.task-list');

        taskLists.forEach(list => {
            list.addEventListener('dragover', (e) => {
                e.preventDefault();
                const afterElement = getDragAfterElement(list, e.clientY);
                const draggable = document.querySelector('.dragging');

                if (afterElement == null) {
                    list.appendChild(draggable);
                } else {
                    list.insertBefore(draggable, afterElement);
                }
            });
        });

        document.querySelectorAll('.task').forEach(task => {
            task.addEventListener('dragstart', () => {
                task.classList.add('dragging');
            });

            task.addEventListener('dragend', () => {
                task.classList.remove('dragging');

                // Get the new status from the parent task-list
                const newStatus = task.closest('.task-list').getAttribute('data-status');
                const taskId = task.getAttribute('data-id');

                // Emit move event
                socket.emit('move-task', {
                    taskId,
                    newStatus
                });
            });
        });
    }

    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    // Board manipulation functions
    function addTaskToBoard(task) {
        const taskElement = createTaskElement(task);
        const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
        taskList.appendChild(taskElement);
        initDragAndDrop(); // Reinitialize drag events for new tasks
    }

    function updateTaskOnBoard(task) {
        const existingTask = document.querySelector(`.task[data-id="${task.id}"]`);
        if (existingTask) {
            existingTask.querySelector('h4').textContent = task.title;
            existingTask.querySelector('p').textContent = task.description;

            // Move to correct board if status changed
            if (existingTask.closest('.task-list').getAttribute('data-status') !== task.status) {
                const newTaskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
                newTaskList.appendChild(existingTask);
            }
        }
    }

    function moveTaskOnBoard(taskId, newStatus) {
        const taskElement = document.querySelector(`.task[data-id="${taskId}"]`);
        if (taskElement) {
            const newTaskList = document.querySelector(`.task-list[data-status="${newStatus}"]`);
            newTaskList.appendChild(taskElement);
        }
    }

    function deleteTaskFromBoard(taskId) {
        const taskElement = document.querySelector(`.task[data-id="${taskId}"]`);
        if (taskElement) {
            taskElement.remove();
        }
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.setAttribute('data-id', task.id);
        taskElement.setAttribute('draggable', 'true');

        taskElement.innerHTML = `
            <h4>${task.title}</h4>
            <p>${task.description}</p>
            <div class="task-actions">
                <button class="edit-task" data-id="${task.id}">Edit</button>
                <button class="delete-task" data-id="${task.id}">Delete</button>
            </div>
        `;

        // Add event listeners for edit and delete
        taskElement.querySelector('.edit-task').addEventListener('click', function(e) {
            e.stopPropagation();
            currentTaskId = task.id;
            currentStatus = task.status;
            taskTitleInput.value = task.title;
            taskDescriptionInput.value = task.description;
            taskModal.style.display = 'block';
        });

        taskElement.querySelector('.delete-task').addEventListener('click', function(e) {
            e.stopPropagation();
            socket.emit('delete-task', task.id);
        });

        return taskElement;
    }
});
```

## server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Store tasks in memory (in a real app, use a database)
let tasks = [];
let userCount = 0;

app.use(express.static(__dirname));

io.on('connection', (socket) => {
    userCount++;
    io.emit('user-count', userCount);

    // Send all tasks to the newly connected client
    socket.emit('initial-tasks', tasks);

    // Task events
    socket.on('new-task', (task) => {
        tasks.push(task);
        io.emit('task-created', task);
    });

    socket.on('update-task', (task) => {
        const index = tasks.findIndex(t => t.id === task.id);
        if (index !== -1) {
            tasks[index] = task;
            io.emit('task-updated', task);
        }
    });

    socket.on('move-task', (data) => {
        const task = tasks.find(t => t.id === data.taskId);
        if (task) {
            task.status = data.newStatus;
            io.emit('task-moved', data);
        }
    });

    socket.on('delete-task', (taskId) => {
        tasks = tasks.filter(t => t.id !== taskId);
        io.emit('task-deleted', taskId);
    });

    socket.on('get-tasks', () => {
        socket.emit('initial-tasks', tasks);
    });

    socket.on('disconnect', () => {
        userCount--;
        io.emit('user-count', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

