    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const todoTasks = document.getElementById('todo-tasks');
const inProgressTasks = document.getElementById('in-progress-tasks');
const doneTasks = document.getElementById('done-tasks');
const taskModal = document.getElementById('task-modal');
const loginModal = document.getElementById('login-modal');
const taskForm = document.getElementById('task-form');
const loginBtn = document.getElementById('login-btn');
const logoutBtn = document.getElementById('logout-btn');
const userName = document.getElementById('user-name');
const closeButtons = document.querySelectorAll('.close');

// Initialize FirebaseUI
const ui = new firebaseui.auth.AuthUI(auth);

// Current user
let currentUser = null;

// Initialize the app
function initApp() {
    // Set up authentication state observer
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            userName.textContent = user.displayName || user.email;
            loginBtn.style.display = 'none';
            logoutBtn.style.display = 'inline-block';

            // Set up real-time listeners for tasks
            setupTaskListeners();
        } else {
            currentUser = null;
            userName.textContent = 'Guest';
            loginBtn.style.display = 'inline-block';
            logoutBtn.style.display = 'none';

            // Clear tasks when logged out
            clearTasks();
        }
    });

    // Set up event listeners
    setupEventListeners();

    // Initialize drag and drop
    initDragAndDrop();
}

// Set up task listeners for real-time updates
function setupTaskListeners() {
    if (!currentUser) return;

    // Listen for changes in each board
    ['todo', 'in-progress', 'done'].forEach(board => {
        db.collection('tasks')
            .where('board', '==', board)
            .where('userId', '==', currentUser.uid)
            .onSnapshot(snapshot => {
                const tasksContainer = document.getElementById(`${board}-tasks`);
                tasksContainer.innerHTML = '';

                snapshot.docChanges().forEach(change => {
                    if (change.type === 'added' || change.type === 'modified') {
                        renderTask(change.doc.data(), change.doc.id, board);
                    } else if (change.type === 'removed') {
                        const taskElement = document.getElementById(`task-${change.doc.id}`);
                        if (taskElement) taskElement.remove();
                    }
                });
            });
    });
}

// Clear all tasks when logged out
function clearTasks() {
    todoTasks.innerHTML = '';
    inProgressTasks.innerHTML = '';
    doneTasks.innerHTML = '';
}

// Render a single task
function renderTask(task, taskId, board) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.id = `task-${taskId}`;
    taskElement.draggable = true;
    taskElement.dataset.taskId = taskId;
    taskElement.dataset.board = board;

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-title">${task.title}</span>
            <div class="task-actions">
                <button class="edit-task-btn" data-task-id="${taskId}" data-board="${board}">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="delete-task-btn" data-task-id="${taskId}">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span class="task-assignee">${task.assignee || 'Unassigned'}</span>
            <span class="task-due-date">${task.dueDate || ''}</span>
        </div>
    `;

    const tasksContainer = document.getElementById(`${board}-tasks`);
    tasksContainer.appendChild(taskElement);

    // Add event listeners to the buttons
    taskElement.querySelector('.edit-task-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(taskId, board);
    });

    taskElement.querySelector('.delete-task-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(taskId);
    });
}

// Initialize drag and drop functionality
function initDragAndDrop() {
    const boards = ['todo', 'in-progress', 'done'];

    boards.forEach(boardId => {
        const tasksContainer = document.getElementById(`${boardId}-tasks`);

        Sortable.create(tasksContainer, {
            group: 'tasks',
            animation: 150,
            ghostClass: 'sortable-ghost',
            onEnd: function (evt) {
                const taskId = evt.item.dataset.taskId;
                const newBoard = evt.to.id.replace('-tasks', '');

                // Update the task's board in Firestore
                if (currentUser) {
                    db.collection('tasks').doc(taskId).update({
                        board: newBoard
                    }).catch(error => {
                        console.error("Error updating task board: ", error);
                    });
                }
            }
        });
    });
}

// Set up event listeners
function setupEventListeners() {
    // Add task buttons
    document.querySelectorAll('.add-task-btn').forEach(button => {
        button.addEventListener('click', () => {
            if (!currentUser) {
                alert('Please login to add tasks');
                return;
            }
            const board = button.dataset.board;
            openTaskModal(null, board);
        });
    });

    // Task form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();
        saveTask();
    });

    // Login button
    loginBtn.addEventListener('click', () => {
        loginModal.style.display = 'block';
        startAuthUI();
    });

    // Logout button
    logoutBtn.addEventListener('click', () => {
        auth.signOut();
    });

    // Close buttons
    closeButtons.forEach(button => {
        button.addEventListener('click', () => {
            button.closest('.modal').style.display = 'none';
        });
    });

    // Close modals when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) {
            e.target.style.display = 'none';
        }
    });
}

// Open the task modal
function openTaskModal(taskId = null, board = null) {
    const modalTitle = document.getElementById('modal-title');
    const taskIdInput = document.getElementById('task-id');
    const taskBoardInput = document.getElementById('task-board');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const taskAssigneeInput = document.getElementById('task-assignee');
    const taskDueDateInput = document.getElementById('task-due-date');

    if (taskId) {
        // Edit existing task
        modalTitle.textContent = 'Edit Task';
        taskIdInput.value = taskId;
        taskBoardInput.value = board;

        // Get task data from Firestore
        db.collection('tasks').doc(taskId).get()
            .then(doc => {
                if (doc.exists) {
                    const task = doc.data();
                    taskTitleInput.value = task.title || '';
                    taskDescriptionInput.value = task.description || '';
                    taskAssigneeInput.value = task.assignee || '';
                    taskDueDateInput.value = task.dueDate || '';
                }
            })
            .catch(error => {
                console.error("Error getting task: ", error);
            });
    } else {
        // Add new task
        modalTitle.textContent = 'Add Task';
        taskIdInput.value = '';
        taskBoardInput.value = board;
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskAssigneeInput.value = '';
        taskDueDateInput.value = '';
    }

    taskModal.style.display = 'block';
}

// Save a task (add or update)
function saveTask() {
    const taskId = document.getElementById('task-id').value;
    const board = document.getElementById('task-board').value;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;

    if (!title.trim()) {
        alert('Please enter a task title');
        return;
    }

    const taskData = {
        title: title.trim(),
        description: description.trim(),
        assignee: assignee.trim(),
        dueDate: dueDate,
        board: board,
        userId: currentUser.uid,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (taskId) {
        // Update existing task
        db.collection('tasks').doc(taskId).update(taskData)
            .then(() => {
                taskModal.style.display = 'none';
            })
            .catch(error => {
                console.error("Error updating task: ", error);
            });
    } else {
        // Add new task
        db.collection('tasks').add(taskData)
            .then(() => {
                taskModal.style.display = 'none';
            })
            .catch(error => {
                console.error("Error adding task: ", error);
            });
    }
}

// Delete a task
function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        db.collection('tasks').doc(taskId).delete()
            .catch(error => {
                console.error("Error deleting task: ", error);
            });
    }
}

// Start FirebaseUI Auth
function startAuthUI() {
    ui.start('#firebaseui-auth-container', {
        signInOptions: [
            firebase.auth.EmailAuthProvider.PROVIDER_ID,
            firebase.auth.GoogleAuthProvider.PROVIDER_ID
        ],
        callbacks: {
            signInSuccessWithAuthResult: function(authResult, redirectUrl) {
                loginModal.style.display = 'none';
                return false;
            }
        },
        signInFlow: 'popup',
        credentialHelper: firebaseui.auth.CredentialHelper.NONE
    });
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
```

## Setup Instructions

1. **Create a Firebase Project**:
   - Go to the [Firebase Console](https://console.firebase.google.com/)
   - Create a new project
   - Enable Authentication (Email/Password and Google providers)
   - Enable Firestore Database (in test mode for development)

2. **Get Firebase Configuration**:
   - In your Firebase project, go to Project Settings
   - Scroll down to "Your apps" and register a web app
   - Copy the configuration object and replace the placeholder values in the JavaScript file

3. **Deploy the App**:
   - You can host this locally by opening the HTML file in a browser
   - For production, you can deploy to Firebase Hosting or any other static hosting service

## Features

1. **Drag-and-Drop Interface**:
   - Tasks can be dragged between boards
   - Uses the Sortable.js library for smooth drag-and-drop functionality

2. **Real-Time Collaboration**:
   - Uses Firebase Firestore for real-time updates
   - Changes made by one user are instantly visible to others

3. **User Authentication**:
   - Login with email/password or Google
   - User-specific task boards

4. **Task Management**:
   - Create, read, update, and delete tasks
   - Each task has title, description, assignee, and due date

5. **Responsive Design**:
   - Works on mobile and desktop devices

This implementation provides a complete, minimal working version of a project management application with all the requested features. You can extend it further by adding more features like task priorities, comments, or team collaboration.

