## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const boardContainer = document.getElementById('board-container');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const loginBtn = document.getElementById('login-btn');
const userName = document.getElementById('user-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskTitle = document.getElementById('task-title');
const taskName = document.getElementById('task-name');
const taskDescription = document.getElementById('task-description');
const saveTaskBtn = document.getElementById('save-task-btn');
const deleteTaskBtn = document.getElementById('delete-task-btn');

// Current task being edited
let currentTask = null;
let currentColumnId = null;

// Authentication
loginBtn.addEventListener('click', () => {
    const provider = new firebase.auth.GoogleAuthProvider();
    auth.signInWithPopup(provider)
        .then((result) => {
            userName.textContent = result.user.displayName || 'User';
            loginBtn.textContent = 'Logout';
            loadBoard();
        })
        .catch((error) => {
            console.error("Authentication error:", error);
        });
});

auth.onAuthStateChanged((user) => {
    if (user) {
        userName.textContent = user.displayName || 'User';
        loginBtn.textContent = 'Logout';
        loadBoard();
    } else {
        userName.textContent = 'Guest';
        loginBtn.textContent = 'Login';
        // For demo purposes, allow guest access
        loadBoard();
    }
});

// Load the board from Firestore
function loadBoard() {
    boardContainer.innerHTML = '';

    db.collection('columns').orderBy('order').onSnapshot((snapshot) => {
        boardContainer.innerHTML = '';
        snapshot.forEach((doc) => {
            const columnData = doc.data();
            addColumnToDOM(doc.id, columnData.name, columnData.order);
            loadTasks(doc.id);
        });
    });
}

// Add a new column
addColumnBtn.addEventListener('click', () => {
    const columnName = newColumnName.value.trim();
    if (columnName) {
        db.collection('columns').add({
            name: columnName,
            order: Date.now()
        }).then(() => {
            newColumnName.value = '';
        });
    }
});

// Add column to DOM
function addColumnToDOM(columnId, columnName, order) {
    const column = document.createElement('div');
    column.className = 'column';
    column.dataset.columnId = columnId;
    column.dataset.order = order;

    column.innerHTML = `
        <div class="column-header">
            <h2>${columnName}</h2>
            <button class="delete-column-btn"><i class="fas fa-trash"></i></button>
        </div>
        <div class="task-list" id="task-list-${columnId}"></div>
        <div class="add-task">
            <input type="text" class="new-task-name" placeholder="New task">
            <button class="add-task-btn"><i class="fas fa-plus"></i></button>
        </div>
    `;

    boardContainer.appendChild(column);

    // Add event listeners for the new column
    const addTaskBtn = column.querySelector('.add-task-btn');
    const newTaskName = column.querySelector('.new-task-name');
    const deleteColumnBtn = column.querySelector('.delete-column-btn');

    addTaskBtn.addEventListener('click', () => {
        const taskName = newTaskName.value.trim();
        if (taskName) {
            db.collection('tasks').add({
                name: taskName,
                description: '',
                columnId: columnId,
                order: Date.now()
            }).then(() => {
                newTaskName.value = '';
            });
        }
    });

    deleteColumnBtn.addEventListener('click', () => {
        if (confirm('Delete this column and all its tasks?')) {
            // First delete all tasks in this column
            db.collection('tasks').where('columnId', '==', columnId).get()
                .then((querySnapshot) => {
                    const batch = db.batch();
                    querySnapshot.forEach((doc) => {
                        batch.delete(doc.ref);
                    });
                    return batch.commit();
                })
                .then(() => {
                    // Then delete the column
                    db.collection('columns').doc(columnId).delete();
                });
        }
    });

    // Make the task list sortable
    const taskList = column.querySelector('.task-list');
    new Sortable(taskList, {
        group: 'shared',
        animation: 150,
        ghostClass: 'sortable-ghost',
        chosenClass: 'sortable-chosen',
        onEnd: (evt) => {
            const taskId = evt.item.dataset.taskId;
            const newColumnId = evt.to.closest('.column').dataset.columnId;
            const tasks = Array.from(evt.to.children);
            const newOrder = tasks.indexOf(evt.item);

            // Update task in Firestore
            db.collection('tasks').doc(taskId).update({
                columnId: newColumnId,
                order: newOrder
            });
        }
    });
}

// Load tasks for a column
function loadTasks(columnId) {
    const taskList = document.getElementById(`task-list-${columnId}`);

    db.collection('tasks')
        .where('columnId', '==', columnId)
        .orderBy('order')
        .onSnapshot((snapshot) => {
            taskList.innerHTML = '';
            snapshot.forEach((doc) => {
                const taskData = doc.data();
                addTaskToDOM(doc.id, taskData.name, taskData.description, columnId, taskData.order);
            });
        });
}

// Add task to DOM
function addTaskToDOM(taskId, taskName, taskDescription, columnId, order) {
    const taskList = document.getElementById(`task-list-${columnId}`);
    const taskCard = document.createElement('div');
    taskCard.className = 'task-card';
    taskCard.dataset.taskId = taskId;
    taskCard.dataset.order = order;

    taskCard.innerHTML = `
        <h3>${taskName}</h3>
        <p>${taskDescription.substring(0, 50)}${taskDescription.length > 50 ? '...' : ''}</p>
    `;

    taskCard.addEventListener('click', () => {
        currentTask = taskId;
        currentColumnId = columnId;
        taskTitle.textContent = 'Edit Task';
        taskName.value = taskName;
        taskDescription.value = taskDescription;
        taskModal.style.display = 'block';
    });

    taskList.appendChild(taskCard);
}

// Task modal functionality
closeModal.addEventListener('click', () => {
    taskModal.style.display = 'none';
});

window.addEventListener('click', (event) => {
    if (event.target === taskModal) {
        taskModal.style.display = 'none';
    }
});

saveTaskBtn.addEventListener('click', () => {
    if (currentTask) {
        db.collection('tasks').doc(currentTask).update({
            name: taskName.value,
            description: taskDescription.value
        }).then(() => {
            taskModal.style.display = 'none';
        });
    }
});

deleteTaskBtn.addEventListener('click', () => {
    if (currentTask && confirm('Delete this task?')) {
        db.collection('tasks').doc(currentTask).delete()
            .then(() => {
                taskModal.style.display = 'none';
            });
    }
});
