## 3. script.js

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const cancelTaskBtn = document.getElementById('cancel-task');
    const userCountElement = document.getElementById('user-count');

    // Current column being edited
    let currentColumn = null;

    // Drag and drop variables
    let draggedTask = null;

    // Initialize the board
    function initBoard() {
        // Load initial tasks from localStorage or server
        const savedTasks = JSON.parse(localStorage.getItem('tasks')) || {
            todo: [],
            'in-progress': [],
            done: []
        };

        // Render tasks
        renderTasks(savedTasks);

        // Set up event listeners
        setupEventListeners();
    }

    // Render tasks to the board
    function renderTasks(tasks) {
        // Clear all task lists
        taskLists.forEach(list => {
            list.innerHTML = '';
        });

        // Render each task
        for (const status in tasks) {
            const taskList = document.getElementById(`${status}-tasks`);
            tasks[status].forEach(task => {
                const taskElement = createTaskElement(task);
                taskList.appendChild(taskElement);
            });
        }
    }

    // Create a task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;

        taskElement.innerHTML = `
            <h3>${task.title}</h3>
            <p>${task.description}</p>
        `;

        // Set up drag events
        taskElement.addEventListener('dragstart', handleDragStart);
        taskElement.addEventListener('dragend', handleDragEnd);

        return taskElement;
    }

    // Set up event listeners
    function setupEventListeners() {
        // Add task buttons
        addTaskButtons.forEach(button => {
            button.addEventListener('click', function() {
                currentColumn = this.closest('.board-column').dataset.status;
                taskModal.style.display = 'flex';
            });
        });

        // Modal buttons
        saveTaskBtn.addEventListener('click', handleSaveTask);
        cancelTaskBtn.addEventListener('click', function() {
            taskModal.style.display = 'none';
            resetModal();
        });

        // Close modal when clicking outside
        taskModal.addEventListener('click', function(e) {
            if (e.target === taskModal) {
                taskModal.style.display = 'none';
                resetModal();
            }
        });

        // Set up drop zones
        taskLists.forEach(list => {
            list.addEventListener('dragover', handleDragOver);
            list.addEventListener('dragenter', handleDragEnter);
            list.addEventListener('dragleave', handleDragLeave);
            list.addEventListener('drop', handleDrop);
        });

        // Socket.io events
        socket.on('task added', handleTaskAdded);
        socket.on('task moved', handleTaskMoved);
        socket.on('user count', updateUserCount);
    }

    // Handle saving a new task
    function handleSaveTask() {
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;

        if (!title) return;

        const task = {
            id: Date.now().toString(),
            title,
            description,
            status: currentColumn
        };

        // Add to local storage
        const savedTasks = JSON.parse(localStorage.getItem('tasks')) || {
            todo: [],
            'in-progress': [],
            done: []
        };
        savedTasks[currentColumn].push(task);
        localStorage.setItem('tasks', JSON.stringify(savedTasks));

        // Emit to server for real-time update
        socket.emit('add task', task);

        // Close modal and reset
        taskModal.style.display = 'none';
        resetModal();
    }

    // Reset the task modal
    function resetModal() {
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        currentColumn = null;
    }

    // Drag and drop handlers
    function handleDragStart(e) {
        draggedTask = this;
        e.dataTransfer.setData('text/plain', this.dataset.id);
        setTimeout(() => {
            this.classList.add('dragging');
        }, 0);
    }

    function handleDragEnd() {
        this.classList.remove('dragging');
        draggedTask = null;
    }

    function handleDragOver(e) {
        e.preventDefault();
    }

    function handleDragEnter(e) {
        e.preventDefault();
        this.classList.add('drag-over');
    }

    function handleDragLeave() {
        this.classList.remove('drag-over');
    }

    function handleDrop(e) {
        e.preventDefault();
        this.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const newStatus = this.closest('.board-column').dataset.status;

        // Update task status in local storage
        const savedTasks = JSON.parse(localStorage.getItem('tasks')) || {
            todo: [],
            'in-progress': [],
            done: []
        };

        // Find and remove the task from its current column
        let taskToMove = null;
        for (const status in savedTasks) {
            const index = savedTasks[status].findIndex(task => task.id === taskId);
            if (index !== -1) {
                taskToMove = savedTasks[status].splice(index, 1)[0];
                break;
            }
        }

        if (taskToMove) {
            // Update the task's status
            taskToMove.status = newStatus;
            // Add to the new column
            savedTasks[newStatus].push(taskToMove);
            // Save to local storage
            localStorage.setItem('tasks', JSON.stringify(savedTasks));

            // Emit to server for real-time update
            socket.emit('move task', {
                taskId: taskToMove.id,
                newStatus: newStatus
            });
        }
    }

    // Socket.io event handlers
    function handleTaskAdded(task) {
        const taskElement = createTaskElement(task);
        const taskList = document.getElementById(`${task.status}-tasks`);
        taskList.appendChild(taskElement);
    }

    function handleTaskMoved(data) {
        // Find the task element
        const taskElement = document.querySelector(`.task-card[data-id="${data.taskId}"]`);
        if (taskElement) {
            // Remove from current list
            taskElement.remove();

            // Add to new list
            const newList = document.getElementById(`${data.newStatus}-tasks`);
            newList.appendChild(taskElement);
        }
    }

    function updateUserCount(count) {
        userCountElement.textContent = count;
    }

    // Initialize the app
    initBoard();
});
```

## 4. server.js

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Store tasks in memory (in a real app, use a database)
let tasks = {
    todo: [],
    'in-progress': [],
    done: []
};

// Track connected users
let userCount = 0;

// Serve static files
app.use(express.static('public'));

// Socket.io connection
io.on('connection', (socket) => {
    userCount++;
    io.emit('user count', userCount);

    // Send current tasks to the new client
    socket.emit('initial tasks', tasks);

    // Handle new task
    socket.on('add task', (task) => {
        tasks[task.status].push(task);
        io.emit('task added', task);
    });

    // Handle task movement
    socket.on('move task', (data) => {
        // Find and remove the task from its current column
        for (const status in tasks) {
            const index = tasks[status].findIndex(task => task.id === data.taskId);
            if (index !== -1) {
                const [task] = tasks[status].splice(index, 1);
                // Update the task's status
                task.status = data.newStatus;
                // Add to the new column
                tasks[data.newStatus].push(task);
                break;
            }
        }

        io.emit('task moved', {
            taskId: data.taskId,
            newStatus: data.newStatus
        });
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        userCount--;
        io.emit('user count', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

