## JavaScript (app.js)

```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const taskLists = document.querySelectorAll('.task-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const taskModal = document.getElementById('task-modal');
const loginModal = document.getElementById('login-modal');
const taskForm = document.getElementById('task-form');
const closeBtns = document.querySelectorAll('.close');
const loginBtn = document.getElementById('login-btn');
const userNameSpan = document.getElementById('user-name');

// Task data
let currentUser = null;
let tasks = [];

// Initialize the app
function initApp() {
    setupAuth();
    setupEventListeners();
    loadTasks();
}

// Set up authentication
function setupAuth() {
    // Firebase UI configuration
    const uiConfig = {
        signInSuccessUrl: '/',
        signInOptions: [
            firebase.auth.GoogleAuthProvider.PROVIDER_ID,
            firebase.auth.EmailAuthProvider.PROVIDER_ID
        ],
        callbacks: {
            signInSuccessWithAuthResult: function(authResult, redirectUrl) {
                loginModal.style.display = 'none';
                return false;
            }
        }
    };

    // Initialize the FirebaseUI Widget
    const ui = new firebaseui.auth.AuthUI(firebase.auth());
    ui.start('#firebaseui-auth-container', uiConfig);

    // Listen for auth state changes
    auth.onAuthStateChanged(user => {
        currentUser = user;
        if (user) {
            userNameSpan.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
        } else {
            userNameSpan.textContent = 'Guest';
            loginBtn.textContent = 'Login';
        }
    });
}

// Set up event listeners
function setupEventListeners() {
    // Add task buttons
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const column = btn.closest('.column');
            const status = column.dataset.status;

            // Reset form
            document.getElementById('task-id').value = '';
            document.getElementById('task-title').value = '';
            document.getElementById('task-description').value = '';
            document.getElementById('task-priority').value = 'medium';

            document.getElementById('modal-title').textContent = 'Add New Task';
            taskModal.dataset.status = status;
            taskModal.style.display = 'block';
        });
    });

    // Close modals
    closeBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            btn.closest('.modal').style.display = 'none';
        });
    });

    // Close modals when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            taskModal.style.display = 'none';
        }
        if (e.target === loginModal) {
            loginModal.style.display = 'none';
        }
    });

    // Login button
    loginBtn.addEventListener('click', () => {
        if (currentUser) {
            auth.signOut();
        } else {
            loginModal.style.display = 'block';
        }
    });

    // Task form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const id = document.getElementById('task-id').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const priority = document.getElementById('task-priority').value;
        const status = taskModal.dataset.status;

        if (id) {
            // Update existing task
            updateTask(id, { title, description, priority, status });
        } else {
            // Create new task
            createTask({ title, description, priority, status });
        }

        taskModal.style.display = 'none';
    });

    // Set up drag and drop
    setupDragAndDrop();
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });
    });

    // Make tasks draggable
    document.addEventListener('dragstart', (e) => {
        if (e.target.classList.contains('task-card')) {
            e.target.classList.add('dragging');
        }
    });

    document.addEventListener('dragend', (e) => {
        if (e.target.classList.contains('task-card')) {
            e.target.classList.remove('dragging');

            // Update task status in database
            const taskId = e.target.dataset.id;
            const newStatus = e.target.closest('.column').dataset.status;

            updateTask(taskId, { status: newStatus });
        }
    });
}

// Helper function for drag and drop positioning
function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task-card:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Create a new task
function createTask(taskData) {
    if (!currentUser) {
        alert('Please login to create tasks');
        return;
    }

    db.collection('tasks').add({
        ...taskData,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        createdBy: currentUser.uid
    }).then(() => {
        loadTasks();
    }).catch(error => {
        console.error('Error adding task: ', error);
    });
}

// Update an existing task
function updateTask(id, updates) {
    db.collection('tasks').doc(id).update({
        ...updates,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }).then(() => {
        loadTasks();
    }).catch(error => {
        console.error('Error updating task: ', error);
    });
}

// Delete a task
function deleteTask(id) {
    if (confirm('Are you sure you want to delete this task?')) {
        db.collection('tasks').doc(id).delete().then(() => {
            loadTasks();
        }).catch(error => {
            console.error('Error deleting task: ', error);
        });
    }
}

// Load tasks from Firestore
function loadTasks() {
    if (!currentUser) {
        // Clear tasks if not logged in
        tasks = [];
        renderTasks();
        return;
    }

    db.collection('tasks')
        .where('createdBy', '==', currentUser.uid)
        .orderBy('createdAt', 'asc')
        .onSnapshot((snapshot) => {
            tasks = [];
            snapshot.forEach(doc => {
                tasks.push({ id: doc.id, ...doc.data() });
            });
            renderTasks();
        });
}

// Render tasks to the board
function renderTasks() {
    // Clear all task lists
    taskLists.forEach(list => {
        list.innerHTML = '';
    });

    // Count tasks for each status
    const counts = {
        todo: 0,
        'in-progress': 0,
        done: 0
    };

    // Create task cards
    tasks.forEach(task => {
        const taskCard = document.createElement('div');
        taskCard.className = 'task-card';
        taskCard.draggable = true;
        taskCard.dataset.id = task.id;

        taskCard.innerHTML = `
            <div class="task-card-header">
                <span class="task-priority ${task.priority}">${task.priority}</span>
                <div class="task-actions">
                    <button class="edit-btn" title="Edit"><i class="fas fa-edit"></i></button>
                    <button class="delete-btn" title="Delete"><i class="fas fa-trash"></i></button>
                </div>
            </div>
            <div class="task-title">${task.title}</div>
            <div class="task-description">${task.description || ''}</div>
        `;

        // Add event listeners for edit and delete
        taskCard.querySelector('.edit-btn').addEventListener('click', (e) => {
            e.stopPropagation();
            editTask(task.id);
        });

        taskCard.querySelector('.delete-btn').addEventListener('click', (e) => {
            e.stopPropagation();
            deleteTask(task.id);
        });

        // Add to appropriate column
        const columnId = `${task.status}-tasks`;
        const column = document.getElementById(columnId);
        if (column) {
            column.querySelector('.task-list').appendChild(taskCard);
            counts[task.status]++;
        }
    });

    // Update task counts
    document.querySelectorAll('.task-count').forEach(countElement => {
        const status = countElement.closest('.column').dataset.status;
        countElement.textContent = counts[status];
    });
}

// Edit a task
function editTask(id) {
    const task = tasks.find(t => t.id === id);
    if (!task) return;

    document.getElementById('task-id').value = task.id;
    document.getElementById('task-title').value = task.title;
    document.getElementById('task-description').value = task.description || '';
    document.getElementById('task-priority').value = task.priority;

    document.getElementById('modal-title').textContent = 'Edit Task';
    taskModal.dataset.status = task.status;
    taskModal.style.display = 'block';
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
