```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM Elements
const todoList = document.getElementById('todo-list');
const inProgressList = document.getElementById('inProgress-list');
const doneList = document.getElementById('done-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const modal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close');
const taskForm = document.getElementById('task-form');
const modalTitle = document.getElementById('modal-title');
const taskIdInput = document.getElementById('task-id');
const taskStatusInput = document.getElementById('task-status');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskPriorityInput = document.getElementById('task-priority');

// Task data
let tasks = {};

// Initialize the app
function init() {
    // Set up event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            openTaskModal(null, btn.dataset.status);
        });
    });

    closeModal.addEventListener('click', closeTaskModal);

    taskForm.addEventListener('submit', saveTask);

    // Set up drag and drop
    setupDragAndDrop();

    // Load tasks from Firebase
    loadTasks();
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');

    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });
    });

    document.querySelectorAll('.task').forEach(task => {
        task.addEventListener('dragstart', () => {
            task.classList.add('dragging');
        });

        task.addEventListener('dragend', () => {
            task.classList.remove('dragging');
            updateTaskStatus(task);
        });
    });
}

function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Update task status when moved between columns
function updateTaskStatus(taskElement) {
    const taskId = taskElement.dataset.id;
    const newStatus = taskElement.closest('.column').dataset.status;

    if (tasks[taskId].status !== newStatus) {
        tasks[taskId].status = newStatus;
        saveTaskToFirebase(taskId, tasks[taskId]);
        updateTaskCounts();
    }
}

// Open task modal for adding or editing
function openTaskModal(taskId = null, status = 'todo') {
    if (taskId) {
        // Edit existing task
        const task = tasks[taskId];
        modalTitle.textContent = 'Edit Task';
        taskIdInput.value = taskId;
        taskStatusInput.value = task.status;
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description || '';
        taskPriorityInput.value = task.priority || 'medium';
    } else {
        // Add new task
        modalTitle.textContent = 'Add New Task';
        taskIdInput.value = '';
        taskStatusInput.value = status;
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskPriorityInput.value = 'medium';
    }

    modal.style.display = 'block';
}

// Close task modal
function closeTaskModal() {
    modal.style.display = 'none';
}

// Save task (add or update)
function saveTask(e) {
    e.preventDefault();

    const taskId = taskIdInput.value || generateTaskId();
    const task = {
        title: taskTitleInput.value,
        description: taskDescriptionInput.value,
        priority: taskPriorityInput.value,
        status: taskStatusInput.value,
        createdAt: firebase.database.ServerValue.TIMESTAMP
    };

    tasks[taskId] = task;
    saveTaskToFirebase(taskId, task);
    closeTaskModal();
}

// Generate a unique task ID
function generateTaskId() {
    return 'task_' + Math.random().toString(36).substr(2, 9);
}

// Save task to Firebase
function saveTaskToFirebase(taskId, task) {
    database.ref('tasks/' + taskId).set(task)
        .then(() => {
            console.log('Task saved successfully');
        })
        .catch((error) => {
            console.error('Error saving task:', error);
        });
}

// Load tasks from Firebase
function loadTasks() {
    database.ref('tasks').on('value', (snapshot) => {
        tasks = snapshot.val() || {};
        renderTasks();
        updateTaskCounts();
    });
}

// Render tasks to the UI
function renderTasks() {
    // Clear all task lists
    todoList.innerHTML = '';
    inProgressList.innerHTML = '';
    doneList.innerHTML = '';

    // Render each task
    for (const [taskId, task] of Object.entries(tasks)) {
        const taskElement = createTaskElement(taskId, task);

        switch (task.status) {
            case 'todo':
                todoList.appendChild(taskElement);
                break;
            case 'in-progress':
                inProgressList.appendChild(taskElement);
                break;
            case 'done':
                doneList.appendChild(taskElement);
                break;
        }
    }

    // Re-apply drag and drop listeners
    setupDragAndDrop();
}

// Create a task element
function createTaskElement(taskId, task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.id = taskId;
    taskElement.draggable = true;

    taskElement.innerHTML = `
        <div class="task-header">
            <div class="task-title">${task.title}</div>
            <div class="task-priority ${task.priority}">${task.priority}</div>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-actions">
            <button class="edit-task" title="Edit"><i class="fas fa-edit"></i></button>
            <button class="delete-task" title="Delete"><i class="fas fa-trash"></i></button>
        </div>
    `;

    // Add event listeners for edit and delete
    taskElement.querySelector('.edit-task').addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(taskId);
    });

    taskElement.querySelector('.delete-task').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(taskId);
    });

    return taskElement;
}

// Delete a task
function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        database.ref('tasks/' + taskId).remove()
            .then(() => {
                console.log('Task deleted successfully');
            })
            .catch((error) => {
                console.error('Error deleting task:', error);
            });
    }
}

// Update task counts in column headers
function updateTaskCounts() {
    const todoCount = Object.values(tasks).filter(task => task.status === 'todo').length;
    const inProgressCount = Object.values(tasks).filter(task => task.status === 'in-progress').length;
    const doneCount = Object.values(tasks).filter(task => task.status === 'done').length;

    document.querySelector('[data-status="todo"] .task-count').textContent = todoCount;
    document.querySelector('[data-status="in-progress"] .task-count').textContent = inProgressCount;
    document.querySelector('[data-status="done"] .task-count').textContent = doneCount;
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
```

