```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// Sample initial data
const initialData = {
    columns: {
        todo: {
            id: 'todo',
            title: 'To Do',
            tasks: [
                { id: 'task1', content: 'Design the UI', users: ['user1'] },
                { id: 'task2', content: 'Set up Firebase', users: ['user2'] }
            ]
        },
        inProgress: {
            id: 'inProgress',
            title: 'In Progress',
            tasks: [
                { id: 'task3', content: 'Implement drag-and-drop', users: ['user1', 'user2'] }
            ]
        },
        done: {
            id: 'done',
            title: 'Done',
            tasks: [
                { id: 'task4', content: 'Create basic structure', users: ['user1'] }
            ]
        }
    },
    users: {
        user1: { name: 'Alice', online: true },
        user2: { name: 'Bob', online: false }
    }
};

// Initialize the board
function initBoard() {
    const boardRef = database.ref('board');

    // Check if data exists, if not initialize it
    boardRef.once('value').then((snapshot) => {
        if (!snapshot.exists()) {
            boardRef.set(initialData);
        }
    });

    // Listen for changes and update the UI
    boardRef.on('value', (snapshot) => {
        const data = snapshot.val();
        renderBoard(data.columns, data.users);
    });
}

// Render the board
function renderBoard(columns, users) {
    const board = document.getElementById('board');
    board.innerHTML = '';

    // Create columns
    Object.values(columns).forEach(column => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.id = column.id;

        const header = document.createElement('div');
        header.className = 'column-header';

        const title = document.createElement('div');
        title.className = 'column-title';
        title.textContent = column.title;

        const addBtn = document.createElement('button');
        addBtn.className = 'add-btn';
        addBtn.innerHTML = '<i class="fas fa-plus"></i>';
        addBtn.addEventListener('click', () => addTask(column.id));

        header.appendChild(title);
        header.appendChild(addBtn);
        columnElement.appendChild(header);

        // Add task input
        const taskInput = document.createElement('input');
        taskInput.className = 'task-input';
        taskInput.placeholder = 'Add a task...';
        taskInput.id = `input-${column.id}`;
        columnElement.appendChild(taskInput);

        // Add tasks
        const tasksContainer = document.createElement('div');
        tasksContainer.id = `tasks-${column.id}`;

        column.tasks.forEach(task => {
            const taskElement = createTaskElement(task, users);
            tasksContainer.appendChild(taskElement);
        });

        columnElement.appendChild(tasksContainer);
        board.appendChild(columnElement);
    });

    // Initialize drag-and-drop
    initDragAndDrop();
}

// Create a task element
function createTaskElement(task, users) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.id = task.id;
    taskElement.dataset.column = task.column;

    const content = document.createElement('div');
    content.textContent = task.content;

    const userList = document.createElement('div');
    userList.className = 'user-list';

    task.users.forEach(userId => {
        const user = users[userId];
        if (user) {
            const userElement = document.createElement('div');
            userElement.className = 'user';

            const indicator = document.createElement('span');
            indicator.className = `online-indicator ${user.online ? 'online' : 'offline'}`;

            userElement.appendChild(indicator);
            userElement.appendChild(document.createTextNode(user.name));
            userList.appendChild(userElement);
        }
    });

    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'delete-btn';
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(task.id, task.column);
    });

    taskElement.appendChild(content);
    taskElement.appendChild(userList);
    taskElement.appendChild(deleteBtn);

    return taskElement;
}

// Initialize drag-and-drop functionality
function initDragAndDrop() {
    const columns = document.querySelectorAll('.column');
    columns.forEach(column => {
        const tasksContainer = column.querySelector(`[id^="tasks-"]`);
        new Sortable(tasksContainer, {
            group: 'tasks',
            animation: 150,
            onEnd: function (evt) {
                const taskId = evt.item.dataset.id;
                const oldColumnId = evt.from.parentElement.id;
                const newColumnId = evt.to.parentElement.id;

                if (oldColumnId !== newColumnId) {
                    moveTask(taskId, oldColumnId, newColumnId);
                }
            }
        });
    });
}

// Add a new task
function addTask(columnId) {
    const input = document.getElementById(`input-${columnId}`);
    const taskContent = input.value.trim();

    if (taskContent) {
        const newTaskRef = database.ref('board/columns/' + columnId + '/tasks').push();
        newTaskRef.set({
            id: newTaskRef.key,
            content: taskContent,
            users: ['user1'] // Default to current user
        });

        input.value = '';
    }
}

// Delete a task
function deleteTask(taskId, columnId) {
    database.ref('board/columns/' + columnId + '/tasks/' + taskId).remove();
}

// Move a task between columns
function moveTask(taskId, oldColumnId, newColumnId) {
    const taskRef = database.ref('board/columns/' + oldColumnId + '/tasks/' + taskId);

    taskRef.once('value').then((snapshot) => {
        const task = snapshot.val();

        // Remove from old column
        taskRef.remove();

        // Add to new column
        const newTaskRef = database.ref('board/columns/' + newColumnId + '/tasks').push();
        newTaskRef.set({
            id: newTaskRef.key,
            content: task.content,
            users: task.users
        });
    });
}

// Initialize the app
document.addEventListener('DOMContentLoaded', initBoard);
