    boardsContainer.appendChild(boardElement);

    // Create task elements for this board
    if (board.tasks) {
        board.tasks.forEach(task => {
            createTaskElement(task, board.id);
        });
    }

    // Set up real-time listener for this board's tasks
    db.collection('boards').doc(board.id).collection('tasks')
        .onSnapshot((snapshot) => {
            snapshot.docChanges().forEach((change) => {
                if (change.type === 'added') {
                    createTaskElement(change.doc.data(), board.id);
                }
                if (change.type === 'modified') {
                    updateTaskElement(change.doc.data(), board.id);
                }
                if (change.type === 'removed') {
                    removeTaskElement(change.doc.id, board.id);
                }
            });
        });
}

// Create a task element
function createTaskElement(task, boardId) {
    const taskList = document.getElementById(`task-list-${boardId}`);

    // Check if task already exists to avoid duplicates
    if (document.getElementById(`task-${task.id}`)) return;

    const taskElement = document.createElement('div');
