                <span>${currentUser.name}</span>
            </div>
            <span>${task.dueDate || ''}</span>
        </div>
    `;
}

// Remove a task element
function removeTaskElement(taskId, boardId) {
    const taskElement = document.getElementById(`task-${taskId}`);
    if (taskElement) {
        taskElement.remove();
    }
}

// Set up real-time listeners for boards
function setupBoardListeners() {
    db.collection('boards').onSnapshot((snapshot) => {
        snapshot.docChanges().forEach((change) => {
            if (change.type === 'added') {
                // Board already created when page loaded
            }
            if (change.type === 'modified') {
                // Update board title if changed
                const boardElement = document.querySelector(`.board[data-board-id="${change.doc.id}"]`);
                if (boardElement) {
                    boardElement.querySelector('.board-title').textContent = change.doc.data().title;
                }
            }
            if (change.type === 'removed') {
                // Remove board element
                const boardElement = document.querySelector(`.board[data-board-id="${change.doc.id}"]`);
                if (boardElement) {
                    boardElement.remove();
                }
            }
        });
    });
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const containers = Array.from(document.querySelectorAll('.task-list'));
    const drake = dragula(containers, {
        moves: function(el, container, handle) {
            return el.classList.contains('task');
        },
        accepts: function(el, target, source, sibling) {
            return target.classList.contains('task-list');
        }
    });

    // Handle drop events
    drake.on('drop', (el, target, source, sibling) => {
        const taskId = el.dataset.taskId;
        const oldBoardId = source.parentElement.dataset.boardId;
        const newBoardId = target.parentElement.dataset.boardId;

        if (oldBoardId !== newBoardId) {
            // Move task to new board
            moveTaskBetweenBoards(taskId, oldBoardId, newBoardId);
        }
    });
}

// Move task between boards
function moveTaskBetweenBoards(taskId, oldBoardId, newBoardId) {
    // Get the task data from the old board
    db.collection('boards').doc(oldBoardId).collection('tasks').doc(taskId).get()
        .then((doc) => {
            if (doc.exists) {
                const taskData = doc.data();

                // Add to new board
                db.collection('boards').doc(newBoardId).collection('tasks').doc(taskId).set(taskData)
                    .then(() => {
                        // Remove from old board
                        db.collection('boards').doc(oldBoardId).collection('tasks').doc(taskId).delete();
                    });
            }
        });
}

// Set up event listeners
function setupEventListeners() {
    // Add task button click
    document.addEventListener('click', (e) => {
        if (e.target.closest('.add-task-btn')) {
            const boardId = e.target.closest('.add-task-btn').dataset.boardId;
            showTaskModal(boardId);
        }
    });

    // Close modal
    document.getElementById('close-modal').addEventListener('click', hideTaskModal);
    document.getElementById('cancel-task').addEventListener('click', hideTaskModal);

    // Priority selection
    document.querySelectorAll('.priority-option').forEach(option => {
        option.addEventListener('click', () => {
            document.querySelectorAll('.priority-option').forEach(opt => {
                opt.classList.remove('selected');
            });
            option.classList.add('selected');
            document.getElementById('task-priority').value = option.dataset.priority;
        });
    });

    // Task form submission
    document.getElementById('task-form').addEventListener('submit', (e) => {
        e.preventDefault();
        saveTask();
    });

    // Set up real-time presence for collaborators
    setupPresence();
}

// Show task modal
function showTaskModal(boardId) {
    document.getElementById('task-modal').style.display = 'flex';
    document.getElementById('task-modal').dataset.boardId = boardId;

    // Reset form
    document.getElementById('task-form').reset();
    document.getElementById('task-priority').value = 'medium';
    document.querySelectorAll('.priority-option').forEach(opt => {
        opt.classList.remove('selected');
        if (opt.dataset.priority === 'medium') {
            opt.classList.add('selected');
        }
    });
}

// Hide task modal
function hideTaskModal() {
    document.getElementById('task-modal').style.display = 'none';
}

// Save task to Firestore
function saveTask() {
    const boardId = document.getElementById('task-modal').dataset.boardId;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const priority = document.getElementById('task-priority').value;

    if (!title) return;

    const taskId = db.collection('boards').doc(boardId).collection('tasks').doc().id;

    const taskData = {
        id: taskId,
        title,
        description,
        priority,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        createdBy: currentUser.id
    };

    db.collection('boards').doc(boardId).collection('tasks').doc(taskId).set(taskData)
        .then(() => {
            hideTaskModal();
        })
        .catch((error) => {
            console.error("Error adding task: ", error);
        });
}

// Set up real-time presence for collaborators
function setupPresence() {
    const userId = currentUser.id;
    const presenceRef = rtdb.ref('presence/' + userId);

    // Set user as online
    const userStatusDatabaseRef = rtdb.ref('/status/' + userId);

    // We'll use a transaction to safely set the user's status
    const isOfflineForDatabase = {
        state: 'offline',
        last_changed: firebase.database.ServerValue.TIMESTAMP,
    };

    const isOnlineForDatabase = {
        state: 'online',
        last_changed: firebase.database.ServerValue.TIMESTAMP,
    };

    // Set initial online status
    userStatusDatabaseRef.onDisconnect().set(isOfflineForDatabase).then(() => {
        userStatusDatabaseRef.set(isOnlineForDatabase);
    });

    // Listen for changes in presence
    rtdb.ref('.info/connected').on('value', (snapshot) => {
        if (snapshot.val() === false) {
            return;
        }

        // When we disconnect, remove the user from presence
        presenceRef.onDisconnect().remove();

        // Add this device to my presence list
        presenceRef.set(true);
    });

    // Listen for changes in other users' presence
    rtdb.ref('presence').on('value', (snapshot) => {
        const collaborators = document.getElementById('collaborators');
        collaborators.innerHTML = '';

        snapshot.forEach((childSnapshot) => {
            const userId = childSnapshot.key;
            if (userId !== currentUser.id) {
                // Get user status
                rtdb.ref('status/' + userId).once('value').then((statusSnapshot) => {
                    const status = statusSnapshot.val();
                    const isOnline = status && status.state === 'online';

                    // Create collaborator element
                    const collaborator = document.createElement('div');
                    collaborator.className = 'collaborator';
                    if (isOnline) {
                        collaborator.classList.add('online');
                    }

                    // In a real app, you would fetch the user's avatar and name
                    collaborator.textContent = userId.charAt(0).toUpperCase();
                    collaborators.appendChild(collaborator);
                });
            }
        });
    });
}
