## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const modal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitle = document.getElementById('task-title');
    const taskDescription = document.getElementById('task-description');
    const modalTitle = document.getElementById('modal-title');
    const userCount = document.getElementById('user-count');

    // Current task being edited (if any)
    let currentTask = null;
    let currentColumn = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', function() {
            currentTask = null;
            currentColumn = this.getAttribute('data-column');
            modalTitle.textContent = 'Add New Task';
            taskTitle.value = '';
            taskDescription.value = '';
            modal.style.display = 'flex';
        });
    });

    // Close modal
    closeModal.addEventListener('click', function() {
        modal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', function() {
        if (!taskTitle.value.trim()) {
            alert('Please enter a task title');
            return;
        }

        const taskData = {
            id: currentTask ? currentTask.id : Date.now().toString(),
            title: taskTitle.value.trim(),
            description: taskDescription.value.trim(),
            column: currentTask ? currentTask.column : currentColumn
        };

        if (currentTask) {
            // Update existing task
            socket.emit('update-task', taskData);
        } else {
            // Add new task
            socket.emit('add-task', taskData);
        }

        modal.style.display = 'none';
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('user-count', (count) => {
        userCount.textContent = count;
    });

    socket.on('initial-tasks', (tasks) => {
        renderTasks(tasks);
    });

    socket.on('task-added', (task) => {
        addTaskToDOM(task);
    });

    socket.on('task-updated', (task) => {
        updateTaskInDOM(task);
    });

    socket.on('task-moved', (task) => {
        moveTaskInDOM(task);
    });

    socket.on('task-deleted', (taskId) => {
        deleteTaskFromDOM(taskId);
    });

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragEnd(e) {
        e.target.classList.remove('dragging');
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        this.classList.add('drag-over');
    }

    function dragLeave() {
        this.classList.remove('drag-over');
    }

    function drop(e) {
        e.preventDefault();
        this.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.getElementById(taskId);
        const newColumn = this.parentElement.id;

        if (taskElement) {
            this.appendChild(taskElement);

            // Update task data
            const taskData = {
                id: taskId,
                title: taskElement.querySelector('h4').textContent,
                description: taskElement.querySelector('p').textContent,
                column: newColumn
            };

            socket.emit('move-task', taskData);
        }
    }

    // DOM manipulation functions
    function renderTasks(tasks) {
        // Clear all task lists
        document.querySelectorAll('.task-list').forEach(list => {
            list.innerHTML = '';
        });

        // Add all tasks
        tasks.forEach(task => {
            addTaskToDOM(task);
        });
    }

    function addTaskToDOM(task) {
        const taskElement = createTaskElement(task);
        const taskList = document.getElementById(`${task.column}-tasks`);
        taskList.appendChild(taskElement);
    }

    function updateTaskInDOM(task) {
        const existingTask = document.getElementById(task.id);
        if (existingTask) {
            existingTask.querySelector('h4').textContent = task.title;
            existingTask.querySelector('p').textContent = task.description;
        }
    }

    function moveTaskInDOM(task) {
        const taskElement = document.getElementById(task.id);
        if (taskElement) {
            const newList = document.getElementById(`${task.column}-tasks`);
            if (newList) {
                newList.appendChild(taskElement);
            }
        }
    }

    function deleteTaskFromDOM(taskId) {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.id = task.id;
        taskElement.draggable = true;
        taskElement.innerHTML = `
            <h4>${task.title}</h4>
            <p>${task.description}</p>
        `;

        // Add event listeners for editing and dragging
        taskElement.addEventListener('click', function(e) {
            if (e.target !== taskElement) return;

            currentTask = {
                id: task.id,
                title: task.title,
                description: task.description,
                column: task.column
            };

            modalTitle.textContent = 'Edit Task';
            taskTitle.value = task.title;
            taskDescription.value = task.description;
            modal.style.display = 'flex';
        });

        taskElement.addEventListener('dragstart', dragStart);
        taskElement.addEventListener('dragend', dragEnd);

        return taskElement;
    }
});
