## 4. server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage for tasks
let tasks = [];
let userCount = 0;

// Serve static files
app.use(express.static(__dirname));

// Socket.io connection
io.on('connection', (socket) => {
    userCount++;
    io.emit('user-count', userCount);

    // Send initial tasks to the new client
    socket.emit('initial-tasks', tasks);

    // Handle task events
    socket.on('add-task', (task) => {
        tasks.push(task);
        io.emit('task-added', task);
    });

    socket.on('update-task', (updatedTask) => {
        tasks = tasks.map(task =>
            task.id === updatedTask.id ? updatedTask : task
        );
        io.emit('task-updated', updatedTask);
    });

    socket.on('move-task', (movedTask) => {
        tasks = tasks.map(task =>
            task.id === movedTask.id ? movedTask : task
        );
        io.emit('task-moved', movedTask);
    });

    socket.on('delete-task', (taskId) => {
        tasks = tasks.filter(task => task.id !== taskId);
        io.emit('task-deleted', taskId);
    });

    socket.on('disconnect', () => {
        userCount--;
        io.emit('user-count', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

