## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskBtns = document.querySelectorAll('.add-task-btn');
    const modal = document.getElementById('task-modal');
    const closeBtn = document.querySelector('.close-btn');
    const saveTaskBtn = document.getElementById('save-task');
    const userCount = document.getElementById('user-count');

    let currentColumn = null;
    let draggedTask = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            currentColumn = this.parentElement.querySelector('.task-list');
            modal.style.display = 'block';
        });
    });

    // Close modal
    closeBtn.addEventListener('click', function() {
        modal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', function() {
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;

        if (title.trim() === '') return;

        const taskId = Date.now().toString();
        const status = currentColumn.dataset.status;

        const taskData = {
            id: taskId,
            title: title,
            description: description,
            status: status
        };

        socket.emit('new-task', taskData);
        modal.style.display = 'none';

        // Clear form
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
    });

    // Socket.io events
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('user-count', (count) => {
        userCount.textContent = count;
    });

    socket.on('task-added', (task) => {
        addTaskToBoard(task);
    });

    socket.on('task-moved', (task) => {
        updateTaskPosition(task);
    });

    // Drag and drop functions
    function dragStart(e) {
        draggedTask = e.target;
        e.target.classList.add('dragging');
        e.dataTransfer.setData('text/plain', e.target.dataset.id);
        e.dataTransfer.effectAllowed = 'move';
    }

    function dragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    }

    function dragEnter(e) {
        e.preventDefault();
        if (e.target.classList.contains('task-list')) {
            e.target.classList.add('drag-over');
        }
    }

    function dragLeave(e) {
        if (e.target.classList.contains('task-list')) {
            e.target.classList.remove('drag-over');
        }
    }

    function drop(e) {
        e.preventDefault();
        e.target.classList.remove('drag-over');

        if (draggedTask) {
            const taskId = draggedTask.dataset.id;
            const newStatus = e.target.dataset.status;

            socket.emit('move-task', {
                id: taskId,
                status: newStatus
            });

            draggedTask.classList.remove('dragging');
            draggedTask = null;
        }
    }

    // Helper functions
    function addTaskToBoard(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;
        taskElement.dataset.status = task.status;

        taskElement.innerHTML = `
            <h3>${task.title}</h3>
            <p>${task.description}</p>
        `;

        taskElement.addEventListener('dragstart', dragStart);

        const column = document.querySelector(`.task-list[data-status="${task.status}"]`);
        column.appendChild(taskElement);
    }

    function updateTaskPosition(task) {
        const taskElement = document.querySelector(`.task-card[data-id="${task.id}"]`);
        if (taskElement) {
            const newColumn = document.querySelector(`.task-list[data-status="${task.status}"]`);
            if (newColumn) {
                newColumn.appendChild(taskElement);
                taskElement.dataset.status = task.status;
            }
        }
    }
});
