const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

let tasks = [];
let userCount = 0;

// Serve static files
app.use(express.static(__dirname));

// Socket.io connection
io.on('connection', (socket) => {
    userCount++;
    io.emit('user-count', userCount);

    // Send existing tasks to new user
    socket.emit('initial-tasks', tasks);

    // Handle new task
    socket.on('new-task', (task) => {
        tasks.push(task);
        io.emit('task-added', task);
    });

    // Handle task movement
    socket.on('move-task', (taskUpdate) => {
        const taskIndex = tasks.findIndex(t => t.id === taskUpdate.id);
        if (taskIndex !== -1) {
            tasks[taskIndex].status = taskUpdate.status;
            io.emit('task-moved', tasks[taskIndex]);
        }
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        userCount--;
        io.emit('user-count', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
