```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const boardContainer = document.getElementById('board-container');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const connectBtn = document.getElementById('connect-btn');
const userStatus = document.getElementById('user-status');

// State
let columns = [];
let isConnected = false;

// Initialize the app
function initApp() {
    // Load initial data
    database.ref('columns').once('value').then(snapshot => {
        const data = snapshot.val();
        if (data) {
            columns = Object.values(data);
            renderColumns();
        }
    });

    // Set up real-time listeners
    database.ref('columns').on('value', snapshot => {
        const data = snapshot.val();
        if (data) {
            columns = Object.values(data);
            renderColumns();
        }
    });

    // Set up event listeners
    addColumnBtn.addEventListener('click', addColumn);
    newColumnName.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') addColumn();
    });

    connectBtn.addEventListener('click', toggleConnection);
}

// Toggle connection status
function toggleConnection() {
    isConnected = !isConnected;
    if (isConnected) {
        connectBtn.textContent = 'Disconnect';
        userStatus.textContent = 'Connected';
        userStatus.style.color = 'green';
    } else {
        connectBtn.textContent = 'Connect';
        userStatus.textContent = 'Not connected';
        userStatus.style.color = 'var(--text-light)';
    }
}

// Render all columns
function renderColumns() {
    boardContainer.innerHTML = '';

    columns.forEach(column => {
        const columnElement = createColumnElement(column);
        boardContainer.appendChild(columnElement);
    });

    setupDragAndDrop();
}

// Create a column element
function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.id = column.id;

    const columnHeader = document.createElement('div');
    columnHeader.className = 'column-header';

    const columnTitle = document.createElement('h3');
    columnTitle.className = 'column-title';
    columnTitle.textContent = column.name;

    const columnActions = document.createElement('div');
    columnActions.className = 'column-actions';

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', () => deleteColumn(column.id));

    columnActions.appendChild(deleteBtn);

    columnHeader.appendChild(columnTitle);
    columnHeader.appendChild(columnActions);

    const taskList = document.createElement('div');
    taskList.className = 'task-list';

    if (column.tasks) {
        column.tasks.forEach(task => {
            const taskElement = createTaskElement(task, column.id);
            taskList.appendChild(taskElement);
        });
    }

    const addTask = document.createElement('div');
    addTask.className = 'add-task';

    const taskInput = document.createElement('input');
    taskInput.type = 'text';
    taskInput.placeholder = 'Add a task...';

    const addTaskBtn = document.createElement('button');
    addTaskBtn.innerHTML = '<i class="fas fa-plus"></i>';
    addTaskBtn.addEventListener('click', () => {
        if (taskInput.value.trim()) {
            addTaskToColumn(column.id, taskInput.value.trim());
            taskInput.value = '';
        }
    });

    addTask.appendChild(taskInput);
    addTask.appendChild(addTaskBtn);

    columnElement.appendChild(columnHeader);
    columnElement.appendChild(taskList);
    columnElement.appendChild(addTask);

    return columnElement;
}

// Create a task element
function createTaskElement(task, columnId) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.id = task.id;
    taskElement.dataset.columnId = columnId;
    taskElement.draggable = true;

    const taskContent = document.createElement('div');
    taskContent.className = 'task-content';
    taskContent.textContent = task.content;

    const taskActions = document.createElement('div');
    taskActions.className = 'task-actions';

    const deleteTaskBtn = document.createElement('button');
    deleteTaskBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteTaskBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(columnId, task.id);
    });

    taskActions.appendChild(deleteTaskBtn);

    taskElement.appendChild(taskContent);
    taskElement.appendChild(taskActions);

    return taskElement;
}

// Add a new column
function addColumn() {
    if (!newColumnName.value.trim()) return;

    const newColumn = {
        id: Date.now().toString(),
        name: newColumnName.value.trim(),
        tasks: []
    };

    if (isConnected) {
        database.ref(`columns/${newColumn.id}`).set(newColumn);
    } else {
        columns.push(newColumn);
        renderColumns();
    }

    newColumnName.value = '';
}

// Delete a column
function deleteColumn(columnId) {
    if (isConnected) {
        database.ref(`columns/${columnId}`).remove();
    } else {
        columns = columns.filter(column => column.id !== columnId);
        renderColumns();
    }
}

// Add a task to a column
function addTaskToColumn(columnId, content) {
    const newTask = {
        id: Date.now().toString(),
        content: content
    };

    if (isConnected) {
        const columnRef = database.ref(`columns/${columnId}`);
        columnRef.once('value').then(snapshot => {
            const column = snapshot.val();
            if (column) {
                const tasks = column.tasks || [];
                tasks.push(newTask);
                columnRef.update({ tasks });
            }
        });
    } else {
        const column = columns.find(col => col.id === columnId);
        if (column) {
            column.tasks = column.tasks || [];
            column.tasks.push(newTask);
            renderColumns();
        }
    }
}

// Delete a task from a column
function deleteTask(columnId, taskId) {
    if (isConnected) {
        const columnRef = database.ref(`columns/${columnId}`);
        columnRef.once('value').then(snapshot => {
            const column = snapshot.val();
            if (column && column.tasks) {
                const updatedTasks = column.tasks.filter(task => task.id !== taskId);
                columnRef.update({ tasks: updatedTasks });
            }
        });
    } else {
        const column = columns.find(col => col.id === columnId);
        if (column && column.tasks) {
            column.tasks = column.tasks.filter(task => task.id !== taskId);
            renderColumns();
        }
    }
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    const columns = document.querySelectorAll('.column');

    tasks.forEach(task => {
        task.addEventListener('dragstart', dragStart);
        task.addEventListener('dragend', dragEnd);
    });

    columns.forEach(column => {
        column.addEventListener('dragover', dragOver);
        column.addEventListener('dragenter', dragEnter);
        column.addEventListener('dragleave', dragLeave);
        column.addEventListener('drop', drop);
    });
}

function dragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.id);
    e.dataTransfer.setData('columnId', e.target.dataset.columnId);
    setTimeout(() => {
        e.target.classList.add('dragging');
    }, 0);
}

function dragEnd(e) {
    e.target.classList.remove('dragging');
}

function dragOver(e) {
    e.preventDefault();
}

function dragEnter(e) {
    e.preventDefault();
    if (e.target.classList.contains('column')) {
        e.target.classList.add('over');
    } else if (e.target.classList.contains('task')) {
        e.target.classList.add('over');
    }
}

function dragLeave(e) {
    if (e.target.classList.contains('column')) {
        e.target.classList.remove('over');
    } else if (e.target.classList.contains('task')) {
        e.target.classList.remove('over');
    }
}

function drop(e) {
    e.preventDefault();
    e.target.classList.remove('over');

    const taskId = e.dataTransfer.getData('text/plain');
    const sourceColumnId = e.dataTransfer.getData('columnId');
    let targetColumnId;

    if (e.target.classList.contains('column')) {
        targetColumnId = e.target.dataset.id;
    } else if (e.target.classList.contains('task')) {
        targetColumnId = e.target.dataset.columnId;
    } else {
        return;
    }

    if (sourceColumnId === targetColumnId) return;

    // Find the task in the source column
    const sourceColumn = columns.find(col => col.id === sourceColumnId);
    const task = sourceColumn.tasks.find(t => t.id === taskId);

    if (!task) return;

    // Remove from source column
    sourceColumn.tasks = sourceColumn.tasks.filter(t => t.id !== taskId);

    // Add to target column
    const targetColumn = columns.find(col => col.id === targetColumnId);
    targetColumn.tasks = targetColumn.tasks || [];
    targetColumn.tasks.push(task);

    if (isConnected) {
        // Update both columns in Firebase
        database.ref(`columns/${sourceColumnId}`).update({ tasks: sourceColumn.tasks });
        database.ref(`columns/${targetColumnId}`).update({ tasks: targetColumn.tasks });
    } else {
        renderColumns();
    }
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

## Features

1. **Drag-and-Drop Interface**:
   - Tasks can be dragged between columns
   - Visual feedback during drag operations

2. **Real-time Collaboration**:
   - Uses Firebase Realtime Database for synchronization
   - Toggle between connected and disconnected modes

3. **Basic Project Management**:
   - Create and delete columns (boards)
   - Add and delete tasks
   - Move tasks between columns

4. **Responsive Design**:
   - Works on different screen sizes
   - Clean, modern UI

## Setup Instructions

1. Create a Firebase project at [Firebase Console](https://console.firebase.google.com/)
2. Add a Realtime Database to your project
3. Replace the Firebase configuration in `script.js` with your own
4. Open `index.html` in a browser to run the application

