```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// Default boards
const defaultBoards = [
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
];

// DOM elements
const boardsContainer = document.getElementById('boards-container');
const addTaskModal = document.getElementById('add-task-modal');
const editTaskModal = document.getElementById('edit-task-modal');
const notification = document.getElementById('notification');
const userAvatar = document.getElementById('user-avatar');
const userName = document.getElementById('user-name');

// Current user
let currentUser = null;

// Initialize the app
function initApp() {
    // Check authentication state
    auth.onAuthStateChanged((user) => {
        if (user) {
            currentUser = user;
            userName.textContent = user.displayName || user.email;
            userAvatar.textContent = (user.displayName || user.email)[0].toUpperCase();

            // Load boards and tasks
            loadBoards();
            setupEventListeners();
        } else {
            // Sign in anonymously if not authenticated
            auth.signInAnonymously().catch((error) => {
                console.error("Error signing in anonymously:", error);
            });
        }
    });
}

// Load boards from Firestore
function loadBoards() {
    db.collection('boards').orderBy('order').onSnapshot((snapshot) => {
        boardsContainer.innerHTML = '';

        if (snapshot.empty) {
            // Create default boards if none exist
            defaultBoards.forEach((board, index) => {
                db.collection('boards').doc(board.id).set({
                    title: board.title,
                    order: index
                });
            });
            return;
        }

        snapshot.forEach((doc) => {
            const board = doc.data();
            createBoardElement(doc.id, board.title);
        });

        // Initialize drag and drop after boards are loaded
        setupDragAndDrop();
    });
}

// Create a board element
function createBoardElement(boardId, title) {
    const boardElement = document.createElement('div');
    boardElement.className = 'board';
    boardElement.dataset.boardId = boardId;

    boardElement.innerHTML = `
        <div class="board-header">
            <div class="board-title">${title}</div>
            <div class="board-actions">
                <i class="fas fa-ellipsis-h"></i>
            </div>
        </div>
        <div class="task-list connected-sortable" id="${boardId}-tasks"></div>
        <div class="add-task-btn" data-board-id="${boardId}">
            <i class="fas fa-plus"></i> Add Task
        </div>
    `;

    boardsContainer.appendChild(boardElement);

    // Load tasks for this board
    loadTasks(boardId);
}

// Load tasks for a specific board
function loadTasks(boardId) {
    const taskList = document.getElementById(`${boardId}-tasks`);

    db.collection('boards').doc(boardId).collection('tasks')
        .orderBy('order')
        .onSnapshot((snapshot) => {
            taskList.innerHTML = '';

            snapshot.forEach((doc) => {
                const task = doc.data();
                createTaskElement(doc.id, boardId, task);
            });
        });
}

// Create a task element
function createTaskElement(taskId, boardId, task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.taskId = taskId;
    taskElement.dataset.boardId = boardId;

    const priorityClass = `priority-${task.priority}`;
    const dueDate = task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date';

    taskElement.innerHTML = `
        <div class="task-title">${task.title}</div>
        <div class="task-meta">
            <span class="task-priority ${priorityClass}">${task.priority}</span>
            <span class="task-due-date">${dueDate}</span>
        </div>
    `;

    // Add click event to open edit modal
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.task-actions')) {
            openEditTaskModal(taskId, boardId, task);
        }
    });

    document.getElementById(`${boardId}-tasks`).appendChild(taskElement);
}

// Setup drag and drop functionality
function setupDragAndDrop() {
    $(".connected-sortable").sortable({
        connectWith: ".connected-sortable",
        placeholder: "ui-state-highlight",
        cursor: "move",
        start: function(event, ui) {
            ui.placeholder.height(ui.item.height());
        },
        stop: function(event, ui) {
            const taskId = ui.item.data('task-id');
            const oldBoardId = ui.item.data('board-id');
            const newBoardId = ui.item.closest('.board').data('board-id');

            if (oldBoardId !== newBoardId) {
                // Task moved to a different board
                moveTask(taskId, oldBoardId, newBoardId);
            } else {
                // Task reordered within the same board
                updateTaskOrder(newBoardId);
            }
        }
    }).disableSelection();
}

// Move a task to a different board
function moveTask(taskId, oldBoardId, newBoardId) {
    const taskRef = db.collection('boards').doc(oldBoardId).collection('tasks').doc(taskId);

    taskRef.get().then((doc) => {
        if (doc.exists) {
            const taskData = doc.data();

            // Add to new board
            const newTaskRef = db.collection('boards').doc(newBoardId).collection('tasks').doc(taskId);

            // Get the highest order in the new board
            db.collection('boards').doc(newBoardId).collection('tasks')
                .orderBy('order', 'desc')
                .limit(1)
                .get()
                .then((snapshot) => {
                    let newOrder = 0;
                    if (!snapshot.empty) {
                        newOrder = snapshot.docs[0].data().order + 1;
                    }

                    // Set the new task with updated order
                    newTaskRef.set({
                        ...taskData,
                        order: newOrder
                    }).then(() => {
                        // Delete from old board
                        taskRef.delete().then(() => {
                            showNotification('Task moved successfully');
                        });
                    });
                });
        }
    });
}

// Update task order when reordered within the same board
function updateTaskOrder(boardId) {
    const taskList = document.getElementById(`${boardId}-tasks`);
    const tasks = taskList.querySelectorAll('.task');

    tasks.forEach((taskElement, index) => {
        const taskId = taskElement.dataset.taskId;
        db.collection('boards').doc(boardId).collection('tasks').doc(taskId).update({
            order: index
        });
    });
}

// Setup event listeners
function setupEventListeners() {
    // Add task button click
    document.addEventListener('click', (e) => {
        if (e.target.closest('.add-task-btn')) {
            const boardId = e.target.closest('.add-task-btn').dataset.boardId;
            openAddTaskModal(boardId);
        }
    });

    // Close modals
    document.getElementById('close-add-task-modal').addEventListener('click', closeAddTaskModal);
    document.getElementById('cancel-add-task').addEventListener('click', closeAddTaskModal);
    document.getElementById('close-edit-task-modal').addEventListener('click', closeEditTaskModal);

    // Add task form submission
    document.getElementById('add-task-form').addEventListener('submit', (e) => {
        e.preventDefault();
        addTask();
    });

    // Edit task form submission
