## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const board = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const signInBtn = document.getElementById('sign-in-btn');
const userName = document.getElementById('user-name');

// Task modal elements
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskTitle = document.getElementById('task-title');
const taskDescription = document.getElementById('task-description');
const saveTaskBtn = document.getElementById('save-task-btn');
const deleteTaskBtn = document.getElementById('delete-task-btn');

// Current task being edited
let currentTask = null;

// Initialize the app
function initApp() {
    // Set up authentication state observer
    auth.onAuthStateChanged((user) => {
        if (user) {
            userName.textContent = user.displayName || user.email;
            signInBtn.textContent = 'Sign Out';
            loadBoard();
        } else {
            userName.textContent = 'Guest';
            signInBtn.textContent = 'Sign In';
            // For demo purposes, we'll allow guest access
            loadBoard();
        }
    });

    // Set up event listeners
    addColumnBtn.addEventListener('click', addColumn);
    signInBtn.addEventListener('click', toggleSignIn);
    closeModal.addEventListener('click', closeTaskModal);
    saveTaskBtn.addEventListener('click', saveTask);
    deleteTaskBtn.addEventListener('click', deleteTask);

    // Initialize drag and drop
    initDragAndDrop();
}

// Load the board from Firestore
function loadBoard() {
    // Clear existing board
    board.innerHTML = '';

    // Get columns from Firestore
    db.collection('columns').orderBy('order').onSnapshot((snapshot) => {
        snapshot.docChanges().forEach((change) => {
            if (change.type === 'added') {
                renderColumn(change.doc);
            } else if (change.type === 'modified') {
                // Handle column updates if needed
            } else if (change.type === 'removed') {
                document.getElementById(`column-${change.doc.id}`)?.remove();
            }
        });

        // Initialize drag and drop after columns are loaded
        initDragAndDrop();
    });
}

// Render a column
function renderColumn(columnDoc) {
    const columnId = columnDoc.id;
    const columnData = columnDoc.data();

    // Check if column already exists
    if (document.getElementById(`column-${columnId}`)) return;

    const column = document.createElement('div');
    column.className = 'column';
    column.id = `column-${columnId}`;
    column.dataset.columnId = columnId;

    column.innerHTML = `
        <div class="column-header">
            <h3 class="column-title">${columnData.name}</h3>
            <button class="delete-column-btn" data-column-id="${columnId}">
                <i class="fas fa-trash"></i>
            </button>
        </div>
        <div class="task-list" id="task-list-${columnId}"></div>
        <button class="add-task-btn" data-column-id="${columnId}">Add Task</button>
    `;

    board.appendChild(column);

    // Set up event listeners for this column
    column.querySelector('.delete-column-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteColumn(columnId);
    });

    column.querySelector('.add-task-btn').addEventListener('click', () => {
        openTaskModal(null, columnId);
    });

    // Load tasks for this column
    loadTasks(columnId);
}

// Load tasks for a column
function loadTasks(columnId) {
    const taskList = document.getElementById(`task-list-${columnId}`);

    db.collection('columns').doc(columnId).collection('tasks')
        .orderBy('order')
        .onSnapshot((snapshot) => {
            snapshot.docChanges().forEach((change) => {
                if (change.type === 'added') {
                    renderTask(change.doc, columnId);
                } else if (change.type === 'modified') {
                    updateTask(change.doc, columnId);
                } else if (change.type === 'removed') {
                    document.getElementById(`task-${change.doc.id}`)?.remove();
                }
            });
        });
}

// Render a task
function renderTask(taskDoc, columnId) {
    const taskId = taskDoc.id;
    const taskData = taskDoc.data();

    // Check if task already exists
    if (document.getElementById(`task-${taskId}`)) return;

    const task = document.createElement('div');
    task.className = 'task';
    task.id = `task-${taskId}`;
    task.draggable = true;
    task.dataset.taskId = taskId;
    task.dataset.columnId = columnId;

    task.innerHTML = `
        <h4>${taskData.title}</h4>
        <p>${taskData.description || ''}</p>
    `;

    // Add to task list
    const taskList = document.getElementById(`task-list-${columnId}`);
    taskList.appendChild(task);

    // Set up event listeners
    task.addEventListener('click', (e) => {
        if (!e.target.closest('.delete-task-btn')) {
            openTaskModal(taskId, columnId);
        }
    });

    task.addEventListener('dragstart', handleDragStart);
}

// Update an existing task
function updateTask(taskDoc, columnId) {
    const taskId = taskDoc.id;
    const taskData = taskDoc.data();

    const taskElement = document.getElementById(`task-${taskId}`);
    if (taskElement) {
        taskElement.innerHTML = `
            <h4>${taskData.title}</h4>
            <p>${taskData.description || ''}</p>
        `;
    }
}

// Add a new column
function addColumn() {
    const columnName = newColumnName.value.trim();
    if (!columnName) return;

    // Get the current number of columns to set order
    db.collection('columns').get().then((snapshot) => {
        const order = snapshot.size;

        db.collection('columns').add({
            name: columnName,
            order: order
        }).then(() => {
            newColumnName.value = '';
        });
    });
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column and all its tasks?')) {
        // First delete all tasks in the column
        db.collection('columns').doc(columnId).collection('tasks').get()
            .then((snapshot) => {
                const batch = db.batch();
                snapshot.docs.forEach((doc) => {
                    batch.delete(doc.ref);
                });
                return batch.commit();
            })
            .then(() => {
                // Then delete the column
                return db.collection('columns').doc(columnId).delete();
            })
            .catch((error) => {
                console.error("Error deleting column: ", error);
            });
    }
}

// Open task modal
function openTaskModal(taskId, columnId) {
    currentTask = { taskId, columnId };

    if (taskId) {
        // Edit existing task
        db.collection('columns').doc(columnId).collection('tasks').doc(taskId).get()
            .then((doc) => {
                if (doc.exists) {
                    const taskData = doc.data();
                    taskTitle.value = taskData.title || '';
                    taskDescription.value = taskData.description || '';
                }
            });
    } else {
        // New task
        taskTitle.value = '';
        taskDescription.value = '';
    }

    taskModal.style.display = 'block';
}

// Close task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
    currentTask = null;
}

// Save task
function saveTask() {
    const title = taskTitle.value.trim();
    const description = taskDescription.value.trim();

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTask.taskId) {
        // Update existing task
        db.collection('columns').doc(currentTask.columnId).collection('tasks').doc(currentTask.taskId)
            .update({
                title: title,
                description: description,
                updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            })
            .then(() => {
                closeTaskModal();
            });
    } else {
        // Add new task
        db.collection('columns').doc(currentTask.columnId).collection('tasks').get()
            .then((snapshot) => {
                const order = snapshot.size;

                db.collection('columns').doc(currentTask.columnId).collection('tasks').add({
                    title: title,
                    description: description,
                    order: order,
                    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                }).then(() => {
                    closeTaskModal();
                });
            });
    }
}

// Delete task
function deleteTask() {
    if (currentTask.taskId && confirm('Are you sure you want to delete this task?')) {
        db.collection('columns').doc(currentTask.columnId).collection('tasks').doc(currentTask.taskId)
            .delete()
            .then(() => {
                closeTaskModal();
            });
    }
}

// Toggle sign in/out
function toggleSignIn() {
    if (auth.currentUser) {
        auth.signOut();
    } else {
        // For demo purposes, we'll use Google sign-in
        const provider = new firebase.auth.GoogleAuthProvider();
        auth.signInWithPopup(provider)
            .catch((error) => {
                console.error("Error signing in: ", error);
            });
    }
}

// Drag and Drop functionality
function initDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');
    const columns = document.querySelectorAll('.column');

    taskLists.forEach((taskList) => {
        taskList.addEventListener('dragover', handleDragOver);
        taskList.addEventListener('dragenter', handleDragEnter);
        taskList.addEventListener('dragleave', handleDragLeave);
        taskList.addEventListener('drop', handleDrop);
    });

    columns.forEach((column) => {
        column.addEventListener('dragover', handleDragOverColumn);
        column.addEventListener('dragenter', handleDragEnterColumn);
        column.addEventListener('dragleave', handleDragLeaveColumn);
        column.addEventListener('drop', handleDropColumn);
    });
}

function handleDragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.id);
    e.target.classList.add('dragging');
}

function handleDragOver(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
}

function handleDragEnter(e) {
    e.preventDefault();
    if (e.target.classList.contains('task-list')) {
        e.target.classList.add('drag-over');
    }
}

function handleDragLeave(e) {
    if (e.target.classList.contains('task-list')) {
        e.target.classList.remove('drag-over');
    }
}

function handleDrop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain').replace('task-', '');
    const columnId = e.target.closest('.column').dataset.columnId;

    // Get the task element
    const taskElement = document.getElementById(`task-${taskId}`);
    if (!taskElement) return;

    // Get the target task list
    const targetTaskList = e.target.closest('.task-list');
    if (!targetTaskList) return;

    // Remove the task from its current position
    taskElement.remove();

    // Add to the new position
    targetTaskList.appendChild(taskElement);

    // Update the task's column in Firestore
    const taskRef = db.collection('columns').doc(columnId).collection('tasks').doc(taskId);

    // Get the new order (position in the task list)
    const tasks = Array.from(targetTaskList.children);
    const newOrder = tasks.indexOf(taskElement);

    // Update the task's order and column
    taskRef.update({
        order: newOrder
    });

    // If the column changed, we need to move the task to the new column
    if (taskElement.dataset.columnId !== columnId) {
        // Get the old column ID
        const oldColumnId = taskElement.dataset.columnId;

        // Get the task data
        db.collection('columns').doc(oldColumnId).collection('tasks').doc(taskId).get()
            .then((doc) => {
                if (doc.exists) {
                    const taskData = doc.data();

                    // Add to new column
                    return db.collection('columns').doc(columnId).collection('tasks').doc(taskId).set({
                        ...taskData,
                        order: newOrder
                    });
                }
            })
            .then(() => {
                // Delete from old column
                return db.collection('columns').doc(oldColumnId).collection('tasks').doc(taskId).delete();
            })
            .then(() => {
                // Update the task's column ID in the DOM
                taskElement.dataset.columnId = columnId;
            })
            .catch((error) => {
                console.error("Error moving task: ", error);
            });
    }
}

// Column drag and drop handlers
function handleDragOverColumn(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
}

function handleDragEnterColumn(e) {
    e.preventDefault();
    if (e.target.classList.contains('column')) {
        e.target.classList.add('drag-over-column');
    }
}

function handleDragLeaveColumn(e) {
    if (e.target.classList.contains('column')) {
        e.target.classList.remove('drag-over-column');
    }
}

function handleDropColumn(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over-column');

    const taskId = e.dataTransfer.getData('text/plain').replace('task-', '');
    const columnId = e.target.closest('.column').dataset.columnId;

    // Get the task element
    const taskElement = document.getElementById(`task-${taskId}`);
    if (!taskElement) return;

    // If the task is already in this column, do nothing
    if (taskElement.dataset.columnId === columnId) return;

    // Get the target task list
    const targetTaskList = e.target.querySelector('.task-list');
    if (!targetTaskList) return;

    // Remove the task from its current position
    taskElement.remove();

    // Add to the new position (end of the list)
    targetTaskList.appendChild(taskElement);

    // Update the task's column in Firestore
    const taskRef = db.collection('columns').doc(columnId).collection('tasks').doc(taskId);

    // Get the new order (position in the task list)
    const tasks = Array.from(targetTaskList.children);
    const newOrder = tasks.indexOf(taskElement);

    // If the column changed, we need to move the task to the new column
    const oldColumnId = taskElement.dataset.columnId;

    // Get the task data
    db.collection('columns').doc(oldColumnId).collection('tasks').doc(taskId).get()
        .then((doc) => {
            if (doc.exists) {
                const taskData = doc.data();

                // Add to new column
                return db.collection('columns').doc(columnId).collection('tasks').doc(taskId).set({
                    ...taskData,
                    order: newOrder
                });
            }
        })
        .then(() => {
            // Delete from old column
            return db.collection('columns').doc(oldColumnId).collection('tasks').doc(taskId).delete();
        })
        .then(() => {
            // Update the task's column ID in the DOM
            taskElement.dataset.columnId = columnId;
        })
        .catch((error) => {
            console.error("Error moving task: ", error);
        });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

