```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const board = document.getElementById('board');
const taskModal = document.getElementById('taskModal');
const taskForm = document.getElementById('taskForm');
const modalTitle = document.getElementById('modalTitle');
const cancelBtn = document.getElementById('cancelBtn');
const taskTitleInput = document.getElementById('taskTitle');
const taskDescriptionInput = document.getElementById('taskDescription');
const taskAssigneeInput = document.getElementById('taskAssignee');

// Sample initial data
const initialColumns = [
    { id: 'todo', title: 'To Do', tasks: [] },
    { id: 'in-progress', title: 'In Progress', tasks: [] },
    { id: 'done', title: 'Done', tasks: [] }
];

// Current state
let currentColumnId = null;
let currentTaskId = null;
let columns = [...initialColumns];

// Initialize the app
function initApp() {
    // Load data from Firebase
    database.ref('columns').on('value', (snapshot) => {
        const data = snapshot.val();
        if (data) {
            columns = Object.values(data);
        } else {
            // Initialize with sample data if database is empty
            columns.forEach(column => {
                database.ref(`columns/${column.id}`).set(column);
            });
        }
        renderBoard();
    });

    // Set up event listeners
    cancelBtn.addEventListener('click', closeModal);
    taskForm.addEventListener('submit', handleTaskSubmit);
}

// Render the board
function renderBoard() {
    board.innerHTML = '';

    columns.forEach(column => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.id = column.id;

        columnElement.innerHTML = `
            <div class="column-header">
                <div class="column-title">${column.title}</div>
                <div class="task-count">${column.tasks ? column.tasks.length : 0}</div>
            </div>
            <div class="task-list" id="${column.id}"></div>
            <div class="add-task-btn" data-column-id="${column.id}">
                <i class="fas fa-plus"></i> Add Task
            </div>
        `;

        board.appendChild(columnElement);

        // Render tasks
        const taskList = columnElement.querySelector('.task-list');
        if (column.tasks) {
            column.tasks.forEach(task => {
                const taskElement = createTaskElement(task);
                taskList.appendChild(taskElement);
            });
        }

        // Add event listener for add task button
        columnElement.querySelector('.add-task-btn').addEventListener('click', (e) => {
            currentColumnId = e.target.dataset.columnId;
            currentTaskId = null;
            openModal('Add New Task');
        });
    });

    // Initialize drag-and-drop
    initDragAndDrop();
}

// Create task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.id = task.id;

    let assigneeHtml = '';
    if (task.assignee) {
        assigneeHtml = `
            <div class="user-avatar">${task.assignee.charAt(0)}</div>
            <span>${task.assignee}</span>
        `;
    }

    taskElement.innerHTML = `
        <div class="task-title">${task.title}</div>
        <div class="task-meta">
            ${assigneeHtml}
        </div>
    `;

    // Add click event to edit task
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.user-avatar')) {
            currentTaskId = task.id;
            currentColumnId = task.columnId;
            openModal('Edit Task');
            taskTitleInput.value = task.title;
            taskDescriptionInput.value = task.description || '';
            taskAssigneeInput.value = task.assignee || '';
        }
    });

    return taskElement;
}

// Initialize drag-and-drop functionality
function initDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');

    taskLists.forEach(list => {
        new Sortable(list, {
            group: 'shared',
            animation: 150,
            ghostClass: 'ghost',
            dragClass: 'dragging',
            onEnd: function (evt) {
                const taskId = evt.item.dataset.id;
                const newColumnId = evt.to.id;

                // Find the task in the old column and remove it
                let oldColumn = columns.find(col => col.tasks && col.tasks.some(t => t.id === taskId));
                if (oldColumn) {
                    const taskIndex = oldColumn.tasks.findIndex(t => t.id === taskId);
                    if (taskIndex > -1) {
                        const [task] = oldColumn.tasks.splice(taskIndex, 1);

                        // Update the task's column reference
                        task.columnId = newColumnId;

                        // Add to new column
                        const newColumn = columns.find(col => col.id === newColumnId);
                        if (newColumn) {
                            if (!newColumn.tasks) newColumn.tasks = [];
                            newColumn.tasks.push(task);

                            // Update Firebase
                            database.ref(`columns/${oldColumn.id}`).set(oldColumn);
                            database.ref(`columns/${newColumn.id}`).set(newColumn);
                        }
                    }
                }
            }
        });
    });
}

// Open modal
function openModal(title) {
    modalTitle.textContent = title;
    taskModal.style.display = 'flex';
}

// Close modal
function closeModal() {
    taskModal.style.display = 'none';
    taskForm.reset();
}

// Handle task form submission
function handleTaskSubmit(e) {
    e.preventDefault();

    const taskData = {
        id: currentTaskId || Date.now().toString(),
        title: taskTitleInput.value,
        description: taskDescriptionInput.value,
        assignee: taskAssigneeInput.value,
        columnId: currentColumnId
    };

    const column = columns.find(col => col.id === currentColumnId);
    if (column) {
        if (!column.tasks) column.tasks = [];

        if (currentTaskId) {
            // Update existing task
            const taskIndex = column.tasks.findIndex(t => t.id === currentTaskId);
            if (taskIndex > -1) {
                column.tasks[taskIndex] = taskData;
            }
        } else {
            // Add new task
            column.tasks.push(taskData);
        }

        // Update Firebase
        database.ref(`columns/${column.id}`).set(column);

        closeModal();
    }
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
