## script.js
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const connectionStatus = document.getElementById('connection-status');

    // Connection status
    socket.on('connect', () => {
        connectionStatus.textContent = 'Connected';
        connectionStatus.classList.add('connected');
    });

    socket.on('disconnect', () => {
        connectionStatus.textContent = 'Disconnected';
        connectionStatus.classList.remove('connected');
    });

    // Drag and drop functionality
    let draggedTask = null;

    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });

        list.addEventListener('drop', (e) => {
            e.preventDefault();
            const status = list.dataset.status;
            const taskId = draggedTask.dataset.id;

            // Update task status
            draggedTask.dataset.status = status;

            // Emit update to server
            socket.emit('task-moved', {
                id: taskId,
                status: status
            });
        });
    });

    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    // Add task functionality
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            const status = button.dataset.status;
            const taskName = prompt('Enter task name:');

            if (taskName) {
                const taskId = Date.now().toString();
                const taskElement = createTaskElement(taskId, taskName, status);

                document.querySelector(`.task-list[data-status="${status}"]`).appendChild(taskElement);

                // Emit new task to server
                socket.emit('task-added', {
                    id: taskId,
                    name: taskName,
                    status: status
                });
            }
        });
    });

    // Create task element
    function createTaskElement(id, name, status) {
        const task = document.createElement('div');
        task.className = 'task';
        task.draggable = true;
        task.dataset.id = id;
        task.dataset.status = status;

        task.innerHTML = `
            <div class="task-content">${name}</div>
        `;

        task.addEventListener('dragstart', () => {
            draggedTask = task;
            task.classList.add('dragging');
        });

        task.addEventListener('dragend', () => {
            task.classList.remove('dragging');
        });

        return task;
    }

    // Real-time updates from server
    socket.on('task-added', (task) => {
        const existingTask = document.querySelector(`.task[data-id="${task.id}"]`);
        if (!existingTask) {
            const taskElement = createTaskElement(task.id, task.name, task.status);
            document.querySelector(`.task-list[data-status="${task.status}"]`).appendChild(taskElement);
        }
    });

    socket.on('task-moved', (task) => {
        const taskElement = document.querySelector(`.task[data-id="${task.id}"]`);
        if (taskElement) {
            taskElement.dataset.status = task.status;
            document.querySelector(`.task-list[data-status="${task.status}"]`).appendChild(taskElement);
        }
    });
});
