// Serve static files
app.use(express.static(__dirname));

// Store tasks in memory (for demo purposes)
let tasks = [];

io.on('connection', (socket) => {
    console.log('New client connected');

    // Send existing tasks to new client
    socket.emit('initial-tasks', tasks);

    // Handle new task
    socket.on('task-added', (task) => {
        tasks.push(task);
        socket.broadcast.emit('task-added', task);
    });

    // Handle task movement
    socket.on('task-moved', (task) => {
        const taskIndex = tasks.findIndex(t => t.id === task.id);
        if (taskIndex !== -1) {
            tasks[taskIndex].status = task.status;
            socket.broadcast.emit('task-moved', task);
        }
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
