## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const taskLists = document.querySelectorAll('.task-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const modal = document.getElementById('task-modal');
const closeBtn = document.querySelector('.close');
const taskForm = document.getElementById('task-form');
const taskIdInput = document.getElementById('task-id');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskPriorityInput = document.getElementById('task-priority');
const taskDueDateInput = document.getElementById('task-due-date');
const loginBtn = document.getElementById('login-btn');
const userNameSpan = document.getElementById('user-name');

// Current user
let currentUser = null;

// Initialize the app
function initApp() {
    // Set up drag and drop
    setupDragAndDrop();

    // Set up event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            openTaskModal(btn.dataset.status);
        });
    });

    closeBtn.addEventListener('click', closeTaskModal);
    window.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeTaskModal();
        }
    });

    taskForm.addEventListener('submit', handleTaskSubmit);
    loginBtn.addEventListener('click', handleLogin);

    // Set up auth state listener
    auth.onAuthStateChanged(user => {
        currentUser = user;
        if (user) {
            userNameSpan.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
        } else {
            userNameSpan.textContent = 'Guest';
            loginBtn.textContent = 'Login';
        }
        loadTasks();
    });
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
            const draggingTask = document.querySelector('.dragging');
            const afterElement = getDragAfterElement(list, e.clientY);

            if (afterElement) {
                list.insertBefore(draggingTask, afterElement);
            } else {
                list.appendChild(draggingTask);
            }
        });

        list.addEventListener('dragenter', (e) => {
            e.preventDefault();
        });

        list.addEventListener('drop', (e) => {
            e.preventDefault();
            const taskId = e.dataTransfer.getData('text/plain');
            const newStatus = list.dataset.status;

            // Update task status in database
            if (currentUser) {
                db.collection('tasks').doc(taskId).update({
                    status: newStatus,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                });
            }

            updateTaskCounts();
        });
    });
}

// Get the element after which we should insert the dragged task
function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Open task modal
function openTaskModal(status, task = null) {
    if (task) {
        taskIdInput.value = task.id;
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description || '';
        taskPriorityInput.value = task.priority || 'medium';
        taskDueDateInput.value = task.dueDate || '';
    } else {
        taskForm.reset();
        taskIdInput.value = '';
        // Set default status if creating new task
        if (status) {
            taskPriorityInput.value = 'medium';
        }
    }

    modal.style.display = 'block';
}

// Close task modal
function closeTaskModal() {
    modal.style.display = 'none';
}

// Handle task form submission
function handleTaskSubmit(e) {
    e.preventDefault();

    const taskData = {
        title: taskTitleInput.value.trim(),
        description: taskDescriptionInput.value.trim(),
        priority: taskPriorityInput.value,
        dueDate: taskDueDateInput.value || null,
        status: 'todo', // Default status
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (currentUser) {
        if (taskIdInput.value) {
            // Update existing task
            db.collection('tasks').doc(taskIdInput.value).update(taskData);
        } else {
            // Add new task
            db.collection('tasks').add(taskData);
        }
    } else {
        // For demo purposes, we'll just add to the UI without saving to database
        addTaskToUI({
            id: Date.now().toString(),
            ...taskData
        });
    }

    closeTaskModal();
    updateTaskCounts();
}

// Load tasks from database or local storage
function loadTasks() {
    if (currentUser) {
        // Load from Firebase
        db.collection('tasks')
            .where('userId', '==', currentUser.uid)
            .orderBy('createdAt', 'desc')
            .onSnapshot(snapshot => {
                const tasks = [];
                snapshot.docChanges().forEach(change => {
                    if (change.type === 'added' || change.type === 'modified') {
                        tasks.push({
                            id: change.doc.id,
                            ...change.doc.data()
                        });
                    }
                });

                // Clear all task lists
                taskLists.forEach(list => {
                    list.innerHTML = '';
                });

                // Add tasks to appropriate lists
                tasks.forEach(task => {
                    addTaskToUI(task);
                });

                updateTaskCounts();
            });
    } else {
        // Load demo tasks
        const demoTasks = [
            { id: '1', title: 'Design homepage', description: 'Create wireframe for new homepage', priority: 'high', status: 'todo', dueDate: '2023-12-15' },
            { id: '2', title: 'Implement API', description: 'Develop backend API for user authentication', priority: 'medium', status: 'in-progress', dueDate: '2023-12-20' },
            { id: '3', title: 'Write documentation', description: 'Document the new features', priority: 'low', status: 'done', dueDate: '2023-12-10' }
        ];

        // Clear all task lists
        taskLists.forEach(list => {
            list.innerHTML = '';
        });

        // Add demo tasks
        demoTasks.forEach(task => {
            addTaskToUI(task);
        });

        updateTaskCounts();
    }
}

// Add task to the UI
function addTaskToUI(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.id = task.id;

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-title">${task.title}</span>
            <span class="task-priority ${task.priority}">${task.priority}</span>
        </div>
        ${task.description ? `<p class="task-description">${task.description}</p>` : ''}
        <div class="task-meta">
            <span>${task.dueDate ? formatDate(task.dueDate) : 'No due date'}</span>
            <div class="task-actions">
                <span class="task-action edit-task" title="Edit"><i class="fas fa-edit"></i></span>
                <span class="task-action delete-task" title="Delete"><i class="fas fa-trash"></i></span>
            </div>
        </div>
    `;

    // Add event listeners for drag and drop
    taskElement.addEventListener('dragstart', () => {
        taskElement.classList.add('dragging');
        taskElement.style.opacity = '0.5';
        taskElement.style.transform = 'scale(1.02)';
        taskElement.parentNode.dataset.dragging = 'true';
        setTimeout(() => {
            taskElement.style.display = 'none';
        }, 0);
    });

    taskElement.addEventListener('dragend', () => {
        taskElement.classList.remove('dragging');
        taskElement.style.opacity = '1';
        taskElement.style.transform = 'scale(1)';
        taskElement.style.display = 'block';
        taskElement.parentNode.dataset.dragging = 'false';
    });

    // Add event listeners for edit and delete
    taskElement.querySelector('.edit-task').addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(task.status, task);
    });

    taskElement.querySelector('.delete-task').addEventListener('click', (e) => {
        e.stopPropagation();
        if (confirm('Are you sure you want to delete this task?')) {
            if (currentUser) {
                db.collection('tasks').doc(task.id).delete();
            } else {
                taskElement.remove();
                updateTaskCounts();
            }
        }
    });

    // Add to the appropriate task list
    const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
    if (taskList) {
        taskList.appendChild(taskElement);
    }
}

// Update task counts in each board
function updateTaskCounts() {
    taskLists.forEach(list => {
        const countElement = list.closest('.board').querySelector('.task-count');
        const taskCount = list.querySelectorAll('.task').length;
        countElement.textContent = taskCount;
    });
}

// Format date for display
function formatDate(dateString) {
    if (!dateString) return 'No due date';

    const date = new Date(dateString);
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return date.toLocaleDateString(undefined, options);
}

// Handle login/logout
function handleLogin() {
    if (currentUser) {
        // Logout
        auth.signOut();
    } else {
        // Login with Google (you can implement other providers as needed)
        const provider = new firebase.auth.GoogleAuthProvider();
        auth.signInWithPopup(provider)
            .then((result) => {
                // User signed in
                console.log('User signed in:', result.user);
            })
            .catch((error) => {
                console.error('Error during sign in:', error);
                alert('Error during sign in: ' + error.message);
            });
    }
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

