## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const boardsContainer = document.getElementById('boards-container');
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const taskForm = document.getElementById('taskForm');
const saveTaskBtn = document.getElementById('saveTaskBtn');

// Sample initial boards (in a real app, these would come from Firebase)
const initialBoards = [
    { id: 'todo', title: 'To Do', tasks: [] },
    { id: 'inprogress', title: 'In Progress', tasks: [] },
    { id: 'done', title: 'Done', tasks: [] }
];

// Current user
let currentUser = null;

// Initialize the app
function initApp() {
    // Listen for auth state changes
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            loadBoards();
        } else {
            // Sign in anonymously for simplicity (in a real app, you'd use proper auth)
            auth.signInAnonymously().catch(error => {
                console.error("Authentication error:", error);
            });
        }
    });
}

// Load boards from Firebase
function loadBoards() {
    db.collection('boards').onSnapshot(snapshot => {
        boardsContainer.innerHTML = '';

        if (snapshot.empty) {
            // Initialize with default boards if none exist
            initialBoards.forEach(board => {
                db.collection('boards').doc(board.id).set(board);
            });
            return;
        }

        snapshot.forEach(doc => {
            const board = doc.data();
            renderBoard(board);
        });

        setupDragAndDrop();
    });
}

// Render a single board
function renderBoard(board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'col-md-4';
    boardElement.innerHTML = `
        <div class="board" data-board-id="${board.id}">
            <div class="board-header">
                <h3>${board.title}</h3>
                <button class="btn btn-sm btn-outline-primary add-task-btn" data-board-id="${board.id}">
                    <i class="fas fa-plus"></i> Add Task
                </button>
            </div>
            <div class="tasks-container" data-board-id="${board.id}">
                ${board.tasks ? board.tasks.map(task => renderTask(task, board.id)).join('') : ''}
            </div>
        </div>
    `;

    boardsContainer.appendChild(boardElement);

    // Add event listeners for add task buttons
    boardElement.querySelector('.add-task-btn').addEventListener('click', (e) => {
        const boardId = e.target.getAttribute('data-board-id');
        openTaskModal(null, boardId);
    });
}

// Render a single task
function renderTask(task, boardId) {
    return `
        <div class="task" draggable="true" data-task-id="${task.id}" data-board-id="${boardId}">
            <div class="task-header d-flex justify-content-between align-items-center mb-2">
                <h5>${task.title}</h5>
                <div>
                    <button class="btn btn-sm btn-outline-secondary edit-task-btn" data-task-id="${task.id}" data-board-id="${boardId}">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button class="btn btn-sm btn-outline-danger delete-task-btn" data-task-id="${task.id}" data-board-id="${boardId}">
                        <i class="fas fa-trash"></i>
                    </button>
                </div>
            </div>
            <p class="mb-1">${task.description || ''}</p>
            ${task.assignedTo ? `
                <div class="d-flex align-items-center">
                    <small>Assigned to: ${task.assignedTo.displayName || 'Anonymous'}</small>
                    <span class="user-indicator" style="background-color: ${getUserColor(task.assignedTo.uid)};"></span>
                </div>
            ` : ''}
        </div>
    `;
}

// Get a consistent color for a user
function getUserColor(uid) {
    // Simple hash function to get consistent color
    let hash = 0;
    for (let i = 0; i < uid.length; i++) {
        hash = uid.charCodeAt(i) + ((hash << 5) - hash);
    }
    const hue = hash % 360;
    return `hsl(${hue}, 70%, 50%)`;
}

// Setup drag and drop functionality
function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    const boards = document.querySelectorAll('.tasks-container');

    tasks.forEach(task => {
        task.addEventListener('dragstart', handleDragStart);
        task.addEventListener('dragend', handleDragEnd);
    });

    boards.forEach(board => {
        board.addEventListener('dragover', handleDragOver);
        board.addEventListener('dragenter', handleDragEnter);
        board.addEventListener('dragleave', handleDragLeave);
        board.addEventListener('drop', handleDrop);
    });

    // Add event listeners for edit and delete buttons
    document.querySelectorAll('.edit-task-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const taskId = e.target.closest('.edit-task-btn').getAttribute('data-task-id');
            const boardId = e.target.closest('.edit-task-btn').getAttribute('data-board-id');
            openTaskModal(taskId, boardId);
        });
    });

    document.querySelectorAll('.delete-task-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const taskId = e.target.closest('.delete-task-btn').getAttribute('data-task-id');
            const boardId = e.target.closest('.delete-task-btn').getAttribute('data-board-id');
            deleteTask(taskId, boardId);
        });
    });
}

// Drag and drop event handlers
function handleDragStart(e) {
    e.target.classList.add('dragging');
    e.dataTransfer.setData('text/plain', e.target.getAttribute('data-task-id'));
    e.dataTransfer.setData('boardId', e.target.getAttribute('data-board-id'));
}

function handleDragEnd(e) {
    e.target.classList.remove('dragging');
}

function handleDragOver(e) {
    e.preventDefault();
}

function handleDragEnter(e) {
    e.preventDefault();
    if (e.target.classList.contains('tasks-container')) {
        e.target.classList.add('drag-over');
    }
}

function handleDragLeave(e) {
    if (e.target.classList.contains('tasks-container')) {
        e.target.classList.remove('drag-over');
    }
}

function handleDrop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    if (!e.target.classList.contains('tasks-container')) return;

    const taskId = e.dataTransfer.getData('text/plain');
    const sourceBoardId = e.dataTransfer.getData('boardId');
    const targetBoardId = e.target.getAttribute('data-board-id');

    if (sourceBoardId === targetBoardId) return;

    // Move task in Firebase
    moveTask(taskId, sourceBoardId, targetBoardId);
}

// Open task modal for editing or creating
function openTaskModal(taskId, boardId) {
    document.getElementById('taskId').value = taskId || '';
    document.getElementById('boardId').value = boardId;

    if (taskId) {
        // Fetch task data from Firebase
        db.collection('boards').doc(boardId).get().then(doc => {
            const board = doc.data();
            const task = board.tasks.find(t => t.id === taskId);

            if (task) {
                document.getElementById('taskTitle').value = task.title || '';
                document.getElementById('taskDescription').value = task.description || '';
            }
        });
    } else {
        // Clear form for new task
        document.getElementById('taskTitle').value = '';
        document.getElementById('taskDescription').value = '';
    }

    taskModal.show();
}

// Save task (create or update)
saveTaskBtn.addEventListener('click', () => {
    const taskId = document.getElementById('taskId').value;
    const boardId = document.getElementById('boardId').value;
    const title = document.getElementById('taskTitle').value;
    const description = document.getElementById('taskDescription').value;

    if (!title) return;

    if (taskId) {
        // Update existing task
        updateTask(taskId, boardId, { title, description });
    } else {
        // Create new task
        createTask(boardId, { title, description });
    }

    taskModal.hide();
});

// Create a new task
function createTask(boardId, taskData) {
    const task = {
        id: db.collection('boards').doc().id,
        title: taskData.title,
        description: taskData.description,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        assignedTo: currentUser ? {
            uid: currentUser.uid,
            displayName: currentUser.displayName || 'Anonymous'
        } : null
    };

    db.collection('boards').doc(boardId).update({
        tasks: firebase.firestore.FieldValue.arrayUnion(task)
    }).then(() => {
        console.log('Task created successfully');
    }).catch(error => {
        console.error('Error creating task:', error);
    });
}

// Update an existing task
function updateTask(taskId, boardId, taskData) {
    db.collection('boards').doc(boardId).get().then(doc => {
        const board = doc.data();
        const updatedTasks = board.tasks.map(task => {
            if (task.id === taskId) {
                return {
                    ...task,
                    title: taskData.title,
                    description: taskData.description,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                };
            }
            return task;
        });

        return db.collection('boards').doc(boardId).update({
            tasks: updatedTasks
        });
    }).then(() => {
        console.log('Task updated successfully');
    }).catch(error => {
        console.error('Error updating task:', error);
    });
}

// Delete a task
function deleteTask(taskId, boardId) {
    if (!confirm('Are you sure you want to delete this task?')) return;

    db.collection('boards').doc(boardId).get().then(doc => {
        const board = doc.data();
        const updatedTasks = board.tasks.filter(task => task.id !== taskId);

        return db.collection('boards').doc(boardId).update({
            tasks: updatedTasks
        });
    }).then(() => {
        console.log('Task deleted successfully');
    }).catch(error => {
        console.error('Error deleting task:', error);
    });
}

// Move a task between boards
function moveTask(taskId, sourceBoardId, targetBoardId) {
    // Get both boards
    db.collection('boards').doc(sourceBoardId).get().then(sourceDoc => {
        const sourceBoard = sourceDoc.data();
        const task = sourceBoard.tasks.find(t => t.id === taskId);

        if (!task) throw new Error('Task not found in source board');

        // Remove task from source board
        const updatedSourceTasks = sourceBoard.tasks.filter(t => t.id !== taskId);

        // Add task to target board
        return db.collection('boards').doc(targetBoardId).get().then(targetDoc => {
            const targetBoard = targetDoc.data();
            const updatedTargetTasks = [...(targetBoard.tasks || []), task];

            // Update both boards in a batch
            const batch = db.batch();
            batch.update(db.collection('boards').doc(sourceBoardId), { tasks: updatedSourceTasks });
            batch.update(db.collection('boards').doc(targetBoardId), { tasks: updatedTargetTasks });

            return batch.commit();
        });
    }).then(() => {
        console.log('Task moved successfully');
    }).catch(error => {
        console.error('Error moving task:', error);
    });
}

// Initialize the app
initApp();
```

