// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM elements
const taskLists = document.querySelectorAll('.task-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const modal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close');
const taskForm = document.getElementById('task-form');
const taskTitle = document.getElementById('task-title');
const taskDescription = document.getElementById('task-description');
const saveTaskBtn = document.getElementById('save-task');
const deleteTaskBtn = document.getElementById('delete-task');
const loginBtn = document.getElementById('login-btn');
const userName = document.getElementById('user-name');

// State variables
let currentTaskId = null;
let currentUser = null;

// Initialize the app
function initApp() {
    // Set up event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            currentTaskId = null;
            taskTitle.value = '';
            taskDescription.value = '';
            deleteTaskBtn.style.display = 'none';
            modal.style.display = 'block';
        });
    });

    closeModal.addEventListener('click', () => {
        modal.style.display = 'none';
    });

    window.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
        }
    });

    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();
        saveTask();
    });

    deleteTaskBtn.addEventListener('click', deleteTask);

    loginBtn.addEventListener('click', login);

    // Set up drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Load tasks from Firebase
    loadTasks();

    // Auth state listener
    auth.onAuthStateChanged(user => {
        currentUser = user;
        if (user) {
            userName.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
        } else {
            userName.textContent = 'Guest';
            loginBtn.textContent = 'Login';
        }
    });
}

// Load tasks from Firebase
function loadTasks() {
    const tasksRef = database.ref('tasks');
    tasksRef.on('value', (snapshot) => {
        const tasks = snapshot.val();
        taskLists.forEach(list => {
            list.innerHTML = '';
        });

        if (tasks) {
            Object.entries(tasks).forEach(([id, task]) => {
                const taskElement = createTaskElement(id, task);
                const list = document.querySelector(`.task-list[data-status="${task.status}"]`);
                if (list) {
                    list.appendChild(taskElement);
                }
            });
        }
    });
}

// Create a task element
function createTaskElement(id, task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.id = id;

    taskElement.innerHTML = `
        <h3>${task.title}</h3>
        <p>${task.description || ''}</p>
    `;

    taskElement.addEventListener('dragstart', dragStart);
    taskElement.addEventListener('click', () => editTask(id));

    return taskElement;
}

// Drag and drop functions
function dragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.id);
    e.target.classList.add('dragging');
    setTimeout(() => {
        e.target.style.display = 'none';
    }, 0);
}

function dragOver(e) {
    e.preventDefault();
}

function dragEnter(e) {
    e.preventDefault();
    e.target.classList.add('drag-over');
}

function dragLeave(e) {
    e.target.classList.remove('drag-over');
}

function drop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain');
    const newStatus = e.target.dataset.status || e.target.closest('.task-list').dataset.status;

    if (newStatus) {
        updateTaskStatus(taskId, newStatus);
    }

    const taskElement = document.querySelector(`.task[data-id="${taskId}"]`);
    if (taskElement) {
        taskElement.style.display = 'block';
        taskElement.classList.remove('dragging');
    }
}

// Update task status in Firebase
function updateTaskStatus(taskId, newStatus) {
    const taskRef = database.ref(`tasks/${taskId}`);
    taskRef.update({ status: newStatus });
}

// Save task to Firebase
function saveTask() {
    const title = taskTitle.value.trim();
    const description = taskDescription.value.trim();

    if (!title) return;

    if (currentTaskId) {
        // Update existing task
        const taskRef = database.ref(`tasks/${currentTaskId}`);
        taskRef.update({
            title,
            description
        });
    } else {
        // Create new task
        const newTaskRef = database.ref('tasks').push();
        newTaskRef.set({
            title,
            description,
            status: 'todo',
            createdAt: firebase.database.ServerValue.TIMESTAMP,
            createdBy: currentUser ? currentUser.uid : 'anonymous'
        });
    }

    modal.style.display = 'none';
}

// Edit task
function editTask(id) {
    const taskRef = database.ref(`tasks/${id}`);
    taskRef.once('value', (snapshot) => {
        const task = snapshot.val();
        if (task) {
            currentTaskId = id;
            taskTitle.value = task.title;
            taskDescription.value = task.description || '';
            deleteTaskBtn.style.display = 'block';
            modal.style.display = 'block';
        }
    });
}

// Delete task
function deleteTask() {
    if (currentTaskId) {
        const taskRef = database.ref(`tasks/${currentTaskId}`);
        taskRef.remove();
        modal.style.display = 'none';
    }
}

// Login/Logout
function login() {
    if (currentUser) {
        auth.signOut();
    } else {
        // Simple email/password login (you might want to implement proper auth)
        const email = prompt('Enter your email:');
        const password = prompt('Enter your password:');

        if (email && password) {
            auth.signInWithEmailAndPassword(email, password)
                .catch(error => {
                    alert(error.message);
                });
        }
    }
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
