### 3. REST API Gateway (Go for concurrency and scalability)

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"
	"time"
)

type TradingAPI struct {
	orderBook *OrderBook
	mu        sync.RWMutex
}

func NewTradingAPI(orderBook *OrderBook) *TradingAPI {
	return &TradingAPI{
		orderBook: orderBook,
	}
}

func (api *TradingAPI) handleOrder(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var order Order
	err := json.NewDecoder(r.Body).Decode(&order)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Validate order
	if order.Quantity <= 0 || order.Price <= 0 {
		http.Error(w, "Invalid order parameters", http.StatusBadRequest)
		return
	}

	// Add order to the order book
	api.mu.Lock()
	api.orderBook.AddOrder(order)
	api.mu.Unlock()

	// Match orders
	matches := api.orderBook.MatchOrders()

	// Send response
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "success",
		"orderId": order.ID,
		"matches":  matches,
	})
}

func (api *TradingAPI) handleMarketData(w http.ResponseWriter, r *http.Request) {
	api.mu.RLock()
	defer api.mu.RUnlock()

	// Get current market data
	marketData := api.orderBook.GetMarketData()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(marketData)
}

func main() {
	// Initialize order book
	orderBook := NewOrderBook()

	// Create API instance
	api := NewTradingAPI(orderBook)

	// Set up HTTP server
	http.HandleFunc("/api/order", api.handleOrder)
	http.HandleFunc("/api/market", api.handleMarketData)

	// Configure server for high performance
	server := &http.Server{
		Addr:           ":8080",
		ReadTimeout:    100 * time.Millisecond,
		WriteTimeout:   100 * time.Millisecond,
		MaxHeaderBytes: 1 << 20,
	}

	log.Println("Starting trading API server on :8080")
	log.Fatal(server.ListenAndServe())
}
```

### 4. Event Bus (Kafka for high-throughput messaging)

```java
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;
import java.util.Properties;

public class EventBus {
    private final Producer<String, String> producer;
    private final String topic;

    public EventBus(String bootstrapServers, String topic) {
        this.topic = topic;

        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.ACKS_CONFIG, "1");  // Trade-off between durability and latency
        props.put(ProducerConfig.LINGER_MS_CONFIG, "5");  // Small batching for better throughput

        this.producer = new KafkaProducer<>(props);
    }

    public void publishEvent(String key, String value) {
        ProducerRecord<String, String> record = new ProducerRecord<>(topic, key, value);
        producer.send(record, (metadata, exception) -> {
            if (exception != null) {
                System.err.println("Error publishing event: " + exception.getMessage());
            }
        });
    }

    public void close() {
        producer.close();
    }
}
