class OrderBook {
private:
    std::string symbol;
    std::priority_queue<OrderBookEntry, std::vector<OrderBookEntry>,
        std::function<bool(const OrderBookEntry&, const OrderBookEntry&)>> buyOrders;
    std::priority_queue<OrderBookEntry, std::vector<OrderBookEntry>,
        std::function<bool(const OrderBookEntry&, const OrderBookEntry&)>> sellOrders;
    std::mutex mtx;

public:
    OrderBook(const std::string& sym)
        : symbol(sym),
          buyOrders([](const OrderBookEntry& a, const OrderBookEntry& b) { return a.price < b.price; }),
          sellOrders([](const OrderBookEntry& a, const OrderBookEntry& b) { return a.price > b.price; }) {}

    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);

        if (order.side == OrderSide::BUY) {
            buyOrders.push({order.price, order.quantity, {order}});
        } else {
            sellOrders.push({order.price, order.quantity, {order}});
        }

        matchOrders();
    }

    void matchOrders() {
        while (!buyOrders.empty() && !sellOrders.empty()) {
            auto& bestBuy = buyOrders.top();
            auto& bestSell = sellOrders.top();

            if (bestBuy.price >= bestSell.price) {
                // Match found
                uint64_t matchedQty = std::min(bestBuy.totalQuantity, bestSell.totalQuantity);

                // Update quantities
                bestBuy.totalQuantity -= matchedQty;
                bestSell.totalQuantity -= matchedQty;

                // Update orders in the book
                for (auto& order : bestBuy.orders) {
                    if (order.quantity > matchedQty) {
                        order.quantity -= matchedQty;
                    } else {
                        order.isFilled = true;
                        order.filledQuantity = order.quantity;
                    }
                }

                for (auto& order : bestSell.orders) {
                    if (order.quantity > matchedQty) {
                        order.quantity -= matchedQty;
                    } else {
                        order.isFilled = true;
                        order.filledQuantity = order.quantity;
                    }
                }

                // Remove empty entries
                if (bestBuy.totalQuantity == 0) {
                    buyOrders.pop();
                }

                if (bestSell.totalQuantity == 0) {
                    sellOrders.pop();
                }

                // In a real system, we would publish the match event here
            } else {
                break; // No more matches possible
            }
        }
    }

    // Other methods for order cancellation, modification, etc.
};

