class NetworkInterface {
private:
    int serverSocket;
    std::vector<std::thread> workerThreads;
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<Order> orderQueue;
    bool running = true;

    void handleClient(int clientSocket) {
        char buffer[1024];
        while (true) {
            ssize_t bytesRead = recv(clientSocket, buffer, sizeof(buffer), 0);
            if (bytesRead <= 0) break;

            // Parse the message (simplified for example)
            // In a real system, this would be more sophisticated
            std::string message(buffer, bytesRead);
            // Parse message and create Order object
            Order order;
            // ... parsing logic ...

            {
                std::lock_guard<std::mutex> lock(mtx);
                orderQueue.push(order);
            }
            cv.notify_one();
        }
        close(clientSocket);
    }

public:
    NetworkInterface(int port) {
        serverSocket = socket(AF_INET, SOCK_STREAM, 0);
        if (serverSocket < 0) {
            perror("Socket creation failed");
            exit(EXIT_FAILURE);
        }

        sockaddr_in serverAddr{};
        serverAddr.sin_family = AF_INET;
        serverAddr.sin_addr.s_addr = INADDR_ANY;
        serverAddr.sin_port = htons(port);

        if (bind(serverSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
            perror("Bind failed");
            exit(EXIT_FAILURE);
        }

        if (listen(serverSocket, 10) < 0) {
            perror("Listen failed");
            exit(EXIT_FAILURE);
        }
    }

    void start(TradingEngine& engine) {
        // Start worker threads to process orders
        for (int i = 0; i < 4; ++i) { // Adjust based on CPU cores
            workerThreads.emplace_back([this, &engine]() {
                while (running) {
                    Order order;
                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        cv.wait(lock, [this]() { return !orderQueue.empty() || !running; });

                        if (!running && orderQueue.empty()) break;

                        order = orderQueue.front();
                        orderQueue.pop();
                    }
                    engine.addOrder(order);
                }
            });
        }

        // Main accept loop
        while (running) {
            sockaddr_in clientAddr{};
            socklen_t clientLen = sizeof(clientAddr);
            int clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddr, &clientLen);

            if (clientSocket < 0) {
                perror("Accept failed");
                continue;
            }

            // Handle client in a new thread
            std::thread(&NetworkInterface::handleClient, this, clientSocket).detach();
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) thread.join();
        }
        close(serverSocket);
    }
};

