```cpp
// core/trading_engine.cpp
#include "trading_engine.hpp"
#include <algorithm>
#include <stdexcept>

namespace trading {

// OrderBook methods
void OrderBook::addOrder(const Order& order) {
    std::unique_lock lock(mutex_);

    if (order.status != OrderStatus::NEW) {
        throw std::runtime_error("Order must be in NEW status to be added");
    }

    if (orders_.find(order.order_id) != orders_.end()) {
        throw std::runtime_error("Order ID already exists");
    }

    orders_[order.order_id] = order;

    if (order.side == Side::BUY) {
        bids_.emplace(order.price, order);
    } else {
        asks_.emplace(order.price, order);
    }
}

void OrderBook::cancelOrder(const std::string& order_id) {
    std::unique_lock lock(mutex_);

    auto it = orders_.find(order_id);
    if (it == orders_.end()) {
        throw std::runtime_error("Order not found");
    }

    const Order& order = it->second;

    if (order.side == Side::BUY) {
        auto range = bids_.equal_range(order.price);
        for (auto it = range.first; it != range.second; ++it) {
            if (it->second.order_id == order_id) {
                bids_.erase(it);
                break;
            }
        }
    } else {
        auto range = asks_.equal_range(order.price);
        for (auto it = range.first; it != range.second; ++it) {
            if (it->second.order_id == order_id) {
                asks_.erase(it);
                break;
            }
        }
    }

    orders_.erase(order_id);
}

std::vector<ExecutionReport> OrderBook::matchOrders() {
    std::vector<ExecutionReport> reports;
    std::unique_lock lock(mutex_);

    while (!bids_.empty() && !asks_.empty()) {
        auto best_bid = bids_.begin();
        auto best_ask = asks_.begin();

        if (best_bid->first >= best_ask->first) {
            // Match found
            double match_price = (best_bid->first + best_ask->first) / 2.0;
            double match_quantity = std::min(best_bid->second.quantity, best_ask->second.quantity);

            // Create execution reports
            ExecutionReport bid_report{
                best_bid->second.order_id,
                best_bid->second.client_id,
                symbol_,
                best_bid->second.type,
                Side::BUY,
                match_price,
                match_quantity,
                best_bid->second.quantity - match_quantity,
                (best_bid->second.quantity - match_quantity) > 0 ? OrderStatus::PARTIALLY_FILLED : OrderStatus::FILLED,
                "exec_" + std::to_string(std::chrono::system_clock::now().time_since_epoch().count()),
                std::chrono::system_clock::now(),
                best_bid->second.account_id
            };

            ExecutionReport ask_report{
                best_ask->second.order_id,
                best_ask->second.client_id,
                symbol_,
                best_ask->second.type,
                Side::SELL,
                match_price,
                match_quantity,
                best_ask->second.quantity - match_quantity,
                (best_ask->second.quantity - match_quantity) > 0 ? OrderStatus::PARTIALLY_FILLED : OrderStatus::FILLED,
                "exec_" + std::to_string(std::chrono::system_clock::now().time_since_epoch().count()),
                std::chrono::system_clock::now(),
                best_ask->second.account_id
            };

            reports.push_back(bid_report);
            reports.push_back(ask_report);

            // Update quantities
            best_bid->second.quantity -= match_quantity;
            best_ask->second.quantity -= match_quantity;

            // Remove orders if fully filled
            if (best_bid->second.quantity <= 0) {
                bids_.erase(best_bid);
                orders_.erase(best_bid->second.order_id);
            }

            if (best_ask->second.quantity <= 0) {
                asks_.erase(best_ask);
                orders_.erase(best_ask->second.order_id);
            }
        } else {
            break; // No more matches possible
        }
    }

    return reports;
}

