void MatchingEngine::addOrder(const Order& order) {
    Message* msg = new Message{
        MessageType::NEW_ORDER,
        order,
        std::chrono::system_clock::now()
    };

    while (!incoming_messages_.push(msg)) {
        // Queue is full, wait or handle accordingly
        std::this_thread::yield();
    }
}

void MatchingEngine::cancelOrder(const std::string& order_id) {
    Message* msg = new Message{
        MessageType::CANCEL_ORDER,
        order_id,
        std::chrono::system_clock::now()
    };

    while (!incoming_messages_.push(msg)) {
        // Queue is full, wait or handle accordingly
        std::this_thread::yield();
    }
}

void MatchingEngine::processMessages() {
    while (running_) {
        Message* msg = nullptr;
        if (incoming_messages_.pop(msg)) {
            processMessage(msg);
            delete msg;
        } else {
            std::this_thread::yield();
        }
    }
}

void MatchingEngine::processMessage(Message* msg) {
    try {
        switch (msg->type) {
            case MessageType::NEW_ORDER: {
                Order order = std::get<Order>(msg->payload);
                auto it = order_books_.find(order.symbol);
                if (it != order_books_.end()) {
                    it->second->addOrder(order);
                    auto reports = it->second->matchOrders();
                    for (auto& report : reports) {
                        ExecutionReport* report_ptr = new ExecutionReport(report);
                        while (!execution_reports_.push(report_ptr)) {
                            // Queue is full, wait or handle accordingly
                            std::this_thread::yield();
                        }
                    }
                }
                break;
            }
            case MessageType::CANCEL_ORDER: {
                std::string order_id = std::get<std::string>(msg->payload);
                // Find which order book contains this order
                for (auto& [symbol, book] : order_books_) {
                    try {
                        book->cancelOrder(order_id);
                        break;
                    } catch (const std::exception&) {
                        // Order not in this book, continue
                    }
                }
                break;
            }
            // Handle other message types
            default:
                break;
        }
    } catch (const std::exception& e) {
        // Log error
    }
}

// RiskEngine methods
bool RiskEngine::checkRiskLimits(const Order& order) {
    std::shared_lock lock(mutex_);

    // Check position limits
    auto pos_it = position_sizes_.find(order.account_id);
    double current_position = pos_it != position_sizes_.end() ? pos_it->second : 0.0;

    double new_position = current_position + (order.side == Side::BUY ? order.quantity : -order.quantity);

    auto max_pos_it = max_position_sizes_.find(order.account_id);
    if (max_pos_it != max_position_sizes_.end() && std::abs(new_position) > max_pos_it->second) {
        return false;
    }

    // Check account balance (simplified)
    auto balance_it = account_balances_.find(order.account_id);
    if (balance_it != account_balances_.end()) {
        if (order.side == Side::BUY && balance_it->second < order.price * order.quantity) {
            return false;
        }
    }

    return true;
}

void RiskEngine::updatePosition(const ExecutionReport& report) {
    std::unique_lock lock(mutex_);

    if (report.status == OrderStatus::FILLED || report.status == OrderStatus::PARTIALLY_FILLED) {
        double quantity = report.side == Side::BUY ? report.quantity : -report.quantity;
        position_sizes_[report.account_id] += quantity;

        // Update account balance
        if (report.side == Side::BUY) {
            account_balances_[report.account_id] -= report.price * report.quantity;
        } else {
            account_balances_[report.account_id] += report.price * report.quantity;
        }
    }
}

