            order.account_id
        };

        // Handle rejection (could be added to execution reports queue)
    }
}

void TradingEngine::cancelOrder(const std::string& order_id) {
    matching_engine_.cancelOrder(order_id);
}

void TradingEngine::addExecutionHandler(std::function<void(const ExecutionReport&)> handler) {
    execution_handlers_.push_back(handler);
}

void TradingEngine::processExecutionReports() {
    while (matching_engine_.running_) {
        ExecutionReport* report = nullptr;
        if (matching_engine_.tryGetExecutionReport(report)) {
            // Update risk engine
            risk_engine_.updatePosition(*report);

            // Notify all handlers
            for (auto& handler : execution_handlers_) {
                handler(*report);
            }

            delete report;
        } else {
            std::this_thread::yield();
        }
    }
}

} // namespace trading
