class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t length) = 0;
    virtual ~PacketFilter() = default;
};

class SimpleIPFilter : public PacketFilter {
private:
    std::unordered_map<uint32_t, bool> allowedIPs;

public:
    void addAllowedIP(const std::string& ip) {
        in_addr addr;
        inet_pton(AF_INET, ip.c_str(), &addr);
        allowedIPs[addr.s_addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(ether_header) + sizeof(ip)) {
            return false;
        }

        const ip* iph = reinterpret_cast<const ip*>(packet + sizeof(ether_header));

        // Check if the packet is IPv4
        if (iph->ip_v != 4) {
            return false;
        }

        // Check if the source IP is allowed
        return allowedIPs.find(iph->ip_src.s_addr) != allowedIPs.end();
    }
};

class NetworkService {
private:
    int rawSocket;
    std::atomic<bool> running;
    std::vector<std::thread> workers;
    PacketFilter* filter;
    std::string interfaceName;

    void workerThread() {
        uint8_t buffer[65536];
        sockaddr_ll sender;
        socklen_t senderLen = sizeof(sender);

        while (running) {
            ssize_t packetLen = recvfrom(rawSocket, buffer, sizeof(buffer), 0,
                                        reinterpret_cast<sockaddr*>(&sender), &senderLen);

            if (packetLen < 0) {
                if (errno == EINTR) continue;
                perror("recvfrom failed");
                break;
            }

            if (filter->shouldForward(buffer, packetLen)) {
                // Forward the packet (in a real implementation, you'd have a forwarding table)
                // For this example, we'll just send it back out the same interface
                if (sendto(rawSocket, buffer, packetLen, 0,
                          reinterpret_cast<sockaddr*>(&sender), senderLen) < 0) {
                    perror("sendto failed");
                }
            }
        }
    }

public:
    NetworkService(const std::string& interface, PacketFilter* packetFilter)
        : filter(packetFilter), interfaceName(interface), running(false) {

        // Create raw socket
        rawSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rawSocket < 0) {
            perror("socket creation failed");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(rawSocket, F_GETFL, 0);
        fcntl(rawSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to interface
        ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, interfaceName.c_str(), IFNAMSIZ);

        if (setsockopt(rawSocket, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0) {
            perror("bind to device failed");
            close(rawSocket);
            throw std::runtime_error("Failed to bind to interface");
        }

        // Set socket priority to highest
        int priority = 6;
        if (setsockopt(rawSocket, SOL_SOCKET, SO_PRIORITY, &priority, sizeof(priority)) < 0) {
            perror("setsockopt SO_PRIORITY failed");
        }
    }

    void start(int numWorkers = 4) {
        running = true;
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&NetworkService::workerThread, this);
        }
    }

    void stop() {
        running = false;
        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
        close(rawSocket);
    }

    ~NetworkService() {
        if (running) {
            stop();
        }
    }
};

