    virtual ~PacketFilter() = default;
};

class SimplePortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;

public:
    SimplePortFilter(const std::vector<uint16_t>& ports) {
        for (auto port : ports) {
            allowedPorts[htons(port)] = true;
        }
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(ethhdr) + sizeof(iphdr)) {
            return false;
        }

        const ethhdr* eth = reinterpret_cast<const ethhdr*>(packet);
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            return false; // Not an IP packet
        }

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet + sizeof(ethhdr));
        if (ip->protocol == IPPROTO_TCP) {
            if (len < sizeof(ethhdr) + sizeof(iphdr) + sizeof(tcphdr)) {
                return false;
            }
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + sizeof(ethhdr) + ip->ihl * 4);
            return allowedPorts.find(tcp->dest) != allowedPorts.end();
        }
        else if (ip->protocol == IPPROTO_UDP) {
            if (len < sizeof(ethhdr) + sizeof(iphdr) + sizeof(udphdr)) {
                return false;
            }
            const udphdr* udp = reinterpret_cast<const udphdr*>(packet + sizeof(ethhdr) + ip->ihl * 4);
            return allowedPorts.find(udp->dest) != allowedPorts.end();
        }

        return false; // Not TCP/UDP
    }
};

class LowLatencyNetworkService {
    int rawSocket;
    std::atomic<bool> running;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unordered_map<std::string, int> interfaceSockets;

public:
    LowLatencyNetworkService() : rawSocket(-1), running(false) {}

    ~LowLatencyNetworkService() {
        stop();
        for (auto& [ifname, sock] : interfaceSockets) {
            close(sock);
        }
    }

    bool initialize(const std::string& interfaceName) {
        // Create raw socket for packet capture
        rawSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rawSocket < 0) {
            perror("socket");
            return false;
        }

        // Set socket to non-blocking
        int flags = fcntl(rawSocket, F_GETFL, 0);
        fcntl(rawSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to specific interface
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex(interfaceName.c_str());
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(rawSocket, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            close(rawSocket);
            rawSocket = -1;
            return false;
        }

        // Set socket to receive all packets (including outgoing)
        int val = 1;
        if (setsockopt(rawSocket, SOL_PACKET, PACKET_AUXDATA, &val, sizeof(val)) < 0) {
            perror("setsockopt PACKET_AUXDATA");
        }

        // Create additional sockets for each interface for sending
        struct if_nameindex* if_ni = if_nameindex();
        if (if_ni) {
            for (struct if_nameindex* i = if_ni; i->if_index != 0 || i->if_name != nullptr; i++) {
                int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
                if (sock < 0) continue;

                struct sockaddr_ll sll_send;
                memset(&sll_send, 0, sizeof(sll_send));
                sll_send.sll_family = AF_PACKET;
                sll_send.sll_ifindex = i->if_index;
                sll_send.sll_protocol = htons(ETH_P_ALL);

                if (bind(sock, (struct sockaddr*)&sll_send, sizeof(sll_send)) < 0) {
                    close(sock);
                    continue;
                }

                interfaceSockets[i->if_name] = sock;
            }
            if_freenameindex(if_ni);
        }

        return true;
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    bool start() {
        if (rawSocket < 0 || running) {
            return false;
        }

        running = true;
        std::thread processingThread([this]() { this->processPackets(); });
        processingThread.detach();
        return true;
    }

    void stop() {
        running = false;
        if (rawSocket >= 0) {
            close(rawSocket);
            rawSocket = -1;
        }
    }

private:
    void processPackets() {
        const size_t bufferSize = 65536; // Maximum packet size
        uint8_t buffer[bufferSize];
        struct pollfd pfd;
        pfd.fd = rawSocket;
        pfd.events = POLLIN;

        while (running) {
            int ret = poll(&pfd, 1, 100); // 100ms timeout
            if (ret <= 0) continue;

            if (pfd.revents & POLLIN) {
                ssize_t len = recv(rawSocket, buffer, bufferSize, 0);
                if (len <= 0) continue;

                // Check if packet should be forwarded
                bool shouldForward = true;
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(buffer, len)) {
                        shouldForward = false;
                        break;
                    }
                }

                if (shouldForward) {
                    forwardPacket(buffer, len);
                }
            }
        }
    }

    void forwardPacket(const uint8_t* packet, size_t len) {
        if (len < sizeof(ethhdr) + sizeof(iphdr)) {
            return;
        }

        const ethhdr* eth = reinterpret_cast<const ethhdr*>(packet);
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            return; // Not an IP packet
        }

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet + sizeof(ethhdr));
        struct in_addr destAddr;
        destAddr.s_addr = ip->daddr;

        // Find the appropriate interface to send the packet
        for (const auto& [ifname, sock] : interfaceSockets) {
            // In a real implementation, you would determine the correct interface
            // based on routing information or other criteria
            if (send(sock, packet, len, 0) < 0) {
                perror("send");
            }
            break; // Just send to the first interface for this example
        }
    }
};

