# Ultra-Low-Latency Networking Service with Packet Filtering and Forwarding

Below is a C++ implementation of an ultra-low-latency networking service that performs packet-level filtering and forwarding. This implementation uses raw sockets for direct packet manipulation and is optimized for performance.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <thread>
#include <atomic>
#include <cstring>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <net/ethernet.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <linux/filter.h>

#define MAX_PACKET_SIZE 65536
#define MAX_RULES 1024

// Packet filter rule structure
struct FilterRule {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
    bool active;
};

// Network interface information
struct InterfaceInfo {
    int sock_fd;
    int if_index;
    std::string if_name;
    uint8_t mac_addr[6];
};

// Main service class
class LowLatencyNetworkService {
private:
    std::vector<InterfaceInfo> interfaces;
    std::unordered_map<uint32_t, FilterRule> rules;
    std::atomic<bool> running;
    std::thread worker_thread;

    // BPF filter for basic packet filtering
    struct sock_fprog bpf_filter;

    // Initialize BPF filter
    void init_bpf_filter() {
        // Simple BPF filter to allow all packets (can be customized)
        struct sock_filter bpf_code[] = {
            { 0x28, 0, 0, 0x0000000c }, // Load packet length
            { 0x15, 0, 8, 0x000005dc }, // Jump if length > 1500 (Ethernet MTU)
            { 0x6, 0, 0, 0x00040000 },  // Return 0 (drop)
            { 0x6, 0, 0, 0xffffffff }    // Return 0xffffffff (accept)
        };

        bpf_filter.len = sizeof(bpf_code) / sizeof(bpf_code[0]);
        bpf_filter.filter = (struct sock_filter*)bpf_code;
    }

    // Create raw socket for interface
    int create_raw_socket(const std::string& if_name) {
        int sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sock_fd < 0) {
            perror("socket");
            return -1;
        }

        // Set socket to non-blocking
        int flags = fcntl(sock_fd, F_GETFL, 0);
        fcntl(sock_fd, F_SETFL, flags | O_NONBLOCK);

        // Bind to interface
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex(if_name.c_str());
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(sock_fd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            close(sock_fd);
            return -1;
        }

        // Set BPF filter
        if (setsockopt(sock_fd, SOL_SOCKET, SO_ATTACH_FILTER, &bpf_filter, sizeof(bpf_filter)) < 0) {
            perror("setsockopt SO_ATTACH_FILTER");
        }

        return sock_fd;
    }

    // Get MAC address of interface
    bool get_mac_address(int sock_fd, uint8_t* mac_addr) {
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        ifr.ifr_addr.sa_family = AF_INET;

        if (ioctl(sock_fd, SIOCGIFHWADDR, &ifr) < 0) {
            perror("ioctl SIOCGIFHWADDR");
            return false;
        }

        memcpy(mac_addr, ifr.ifr_hwaddr.sa_data, 6);
        return true;
    }

    // Process incoming packet
    void process_packet(const uint8_t* packet, size_t len, int in_if_index) {
        struct ethhdr* eth = (struct ethhdr*)packet;
        if (len < sizeof(struct ethhdr)) return;

        // Check if it's an IP packet
        if (ntohs(eth->h_proto) != ETH_P_IP) return;

        struct iphdr* ip = (struct iphdr*)(packet + sizeof(struct ethhdr));
        if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) return;

        // Check for TCP or UDP
        if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP) return;

        // Get transport layer header
        void* transport_hdr = (void*)(packet + sizeof(struct ethhdr) + (ip->ihl * 4));
        size_t transport_len = len - sizeof(struct ethhdr) - (ip->ihl * 4);

        uint16_t src_port = 0, dst_port = 0;
        if (ip->protocol == IPPROTO_TCP && transport_len >= sizeof(struct tcphdr)) {
            struct tcphdr* tcp = (struct tcphdr*)transport_hdr;
            src_port = ntohs(tcp->source);
            dst_port = ntohs(tcp->dest);
        } else if (ip->protocol == IPPROTO_UDP && transport_len >= sizeof(struct udphdr)) {
            struct udphdr* udp = (struct udphdr*)transport_hdr;
            src_port = ntohs(udp->source);
            dst_port = ntohs(udp->dest);
        } else {
            return;
        }

        // Check against filter rules
        uint32_t rule_key = (ip->saddr << 16) | (ip->daddr & 0xFFFF);
        auto it = rules.find(rule_key);
        if (it != rules.end() && it->second.active) {
            const FilterRule& rule = it->second;
            if (rule.src_ip == ip->saddr && rule.dst_ip == ip->daddr &&
                rule.src_port == src_port && rule.dst_port == dst_port &&
                rule.protocol == ip->protocol) {
                if (!rule.allow) {
                    // Packet dropped by filter
                    return;
                }
            }
        }

        // Forward packet to all other interfaces
        for (const auto& iface : interfaces) {
            if (iface.if_index == in_if_index) continue;

            // Modify Ethernet header for forwarding
            uint8_t out_packet[MAX_PACKET_SIZE];
            memcpy(out_packet, packet, len);

            struct ethhdr* out_eth = (struct ethhdr*)out_packet;
            memcpy(out_eth->h_source, iface.mac_addr, 6);

            // Send packet
            struct sockaddr_ll sll;
            memset(&sll, 0, sizeof(sll));
            sll.sll_family = AF_PACKET;
            sll.sll_ifindex = iface.if_index;
            sll.sll_halen = ETH_ALEN;
            memcpy(sll.sll_addr, out_eth->h_dest, ETH_ALEN);

            sendto(iface.sock_fd, out_packet, len, 0, (struct sockaddr*)&sll, sizeof(sll));
        }
    }

    // Worker thread function
    void worker_loop() {
        std::vector<pollfd> fds;
        for (const auto& iface : interfaces) {
            pollfd pfd;
            pfd.fd = iface.sock_fd;
            pfd.events = POLLIN;
            fds.push_back(pfd);
        }

        while (running) {
            int ret = poll(fds.data(), fds.size(), 10); // 10ms timeout
            if (ret <= 0) continue;

            for (size_t i = 0; i < fds.size(); i++) {
                if (fds[i].revents & POLLIN) {
                    uint8_t buffer[MAX_PACKET_SIZE];
                    ssize_t len = recv(fds[i].fd, buffer, sizeof(buffer), 0);
                    if (len > 0) {
                        process_packet(buffer, len, interfaces[i].if_index);
                    }
                }
            }
        }
    }

public:
    LowLatencyNetworkService() : running(false) {
        init_bpf_filter();
    }

    ~LowLatencyNetworkService() {
        stop();
    }

    // Add network interface to monitor
    bool add_interface(const std::string& if_name) {
        int sock_fd = create_raw_socket(if_name);
        if (sock_fd < 0) return false;

        InterfaceInfo iface;
        iface.sock_fd = sock_fd;
        iface.if_name = if_name;
        iface.if_index = if_nametoindex(if_name.c_str());

        if (!get_mac_address(sock_fd, iface.mac_addr)) {
            close(sock_fd);
            return false;
        }

        interfaces.push_back(iface);
        return true;
    }

    // Add filter rule
    void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                        uint16_t src_port, uint16_t dst_port,
                        uint8_t protocol, bool allow) {
        if (rules.size() >= MAX_RULES) return;

        FilterRule rule;
        rule.src_ip = src_ip;
        rule.dst_ip = dst_ip;
        rule.src_port = src_port;
        rule.dst_port = dst_port;
        rule.protocol = protocol;
        rule.allow = allow;
        rule.active = true;

        uint32_t key = (src_ip << 16) | (dst_ip & 0xFFFF);
        rules[key] = rule;
    }

    // Remove filter rule
    void remove_filter_rule(uint32_t src_ip, uint32_t dst_ip) {
        uint32_t key = (src_ip << 16) | (dst_ip & 0xFFFF);
        rules.erase(key);
    }

    // Start the service
    bool start() {
        if (interfaces.empty()) {
            std::cerr << "No interfaces configured" << std::endl;
            return false;
        }

        running = true;
        worker_thread = std::thread(&LowLatencyNetworkService::worker_loop, this);
        return true;
    }

    // Stop the service
    void stop() {
        running = false;
        if (worker_thread.joinable()) {
            worker_thread.join();
        }

        for (auto& iface : interfaces) {
            close(iface.sock_fd);
        }
        interfaces.clear();
    }
};

int main() {
    LowLatencyNetworkService service;

    // Add network interfaces (replace with your actual interfaces)
    if (!service.add_interface("eth0")) {
        std::cerr << "Failed to add interface eth0" << std::endl;
        return 1;
    }

    if (!service.add_interface("eth1")) {
        std::cerr << "Failed to add interface eth1" << std::endl;
        return 1;
    }

    // Add some filter rules (example: block all TCP traffic from 192.168.1.100)
    uint32_t src_ip = inet_addr("192.168.1.100");
    uint32_t dst_ip = INADDR_ANY; // any destination
    service.add_filter_rule(src_ip, dst_ip, 0, 0, IPPROTO_TCP, false);

    // Start the service
    if (!service.start()) {
        std::cerr << "Failed to start service" << std::endl;
        return 1;
    }

    std::cout << "Low-latency networking service running. Press Enter to stop..." << std::endl;
    std::cin.get();

    service.stop();
    return 0;
}
