#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define MAX_PACKET_SIZE 1500
#define MAX_RULES 100
#define BUFFER_SIZE 1024

// Packet processing statistics
typedef struct {
    uint64_t packets_received;
    uint64_t packets_forwarded;
    uint64_t packets_dropped;
    uint64_t bytes_processed;
} stats_t;

// Filter rule structure
typedef struct {
    uint8_t src_ip[4];
    uint8_t dst_ip[4];
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol; // IPPROTO_TCP, IPPROTO_UDP, etc.
    int action;      // 0 = drop, 1 = forward
    int active;      // 0 = inactive, 1 = active
} filter_rule_t;

// Global variables
filter_rule_t rules[MAX_RULES];
int rule_count = 0;
stats_t statistics = {0};
int running = 1;

// Function prototypes
void handle_packet(unsigned char *buffer, int size);
int check_filter_rules(struct iphdr *ip_header, void *transport_header);
void print_stats();
void cleanup(int sig);
void *stats_thread(void *arg);

// Main function
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Create raw socket
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Get interface index
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, argv[1], IFNAMSIZ-1);

    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) == -1) {
        perror("ioctl");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) == -1) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Start statistics thread
    pthread_t stats_tid;
    if (pthread_create(&stats_tid, NULL, stats_thread, NULL) != 0) {
        perror("pthread_create");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Packet forwarding service started on interface %s\n", argv[1]);

    // Main packet processing loop
    unsigned char buffer[MAX_PACKET_SIZE];
    while (running) {
        int packet_size = recvfrom(sockfd, buffer, MAX_PACKET_SIZE, 0, NULL, NULL);
        if (packet_size == -1) {
            if (errno == EINTR) continue; // Interrupted by signal
            perror("recvfrom");
            break;
        }

        handle_packet(buffer, packet_size);
    }

    // Clean up
    close(sockfd);
    pthread_join(stats_tid, NULL);
    print_stats();

    return EXIT_SUCCESS;
}

// Packet handling function
void handle_packet(unsigned char *buffer, int size) {
    statistics.packets_received++;
    statistics.bytes_processed += size;

    // Parse Ethernet header
    struct ethhdr *eth_header = (struct ethhdr *)buffer;
    if (ntohs(eth_header->h_proto) != ETH_P_IP) {
        // Not an IP packet, drop it
        statistics.packets_dropped++;
        return;
    }

    // Parse IP header
    struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
    if (ip_header->version != 4) {
        // Not IPv4, drop it
        statistics.packets_dropped++;
        return;
    }

    // Calculate transport header offset
    void *transport_header = (void *)(buffer + sizeof(struct ethhdr) + (ip_header->ihl * 4));

    // Check filter rules
    if (!check_filter_rules(ip_header, transport_header)) {
        statistics.packets_dropped++;
        return;
    }

    // Forward the packet (in a real implementation, this would involve sending it out another interface)
    statistics.packets_forwarded++;

    // In a real implementation, you would:
    // 1. Modify MAC addresses if needed
    // 2. Send the packet out the appropriate interface
    // 3. Handle any NAT or other modifications
}

// Check packet against filter rules
int check_filter_rules(struct iphdr *ip_header, void *transport_header) {
    // Default action is to forward
    int action = 1;

    // Check each rule
    for (int i = 0; i < rule_count; i++) {
        if (!rules[i].active) continue;

        // Check protocol
        if (rules[i].protocol != 0 && rules[i].protocol != ip_header->protocol) {
            continue;
        }

        // Check source IP
        if (memcmp(rules[i].src_ip, &ip_header->saddr, 4) != 0 &&
            memcmp(rules[i].src_ip, "\x00\x00\x00\x00", 4) != 0) {
            continue;
        }

        // Check destination IP
        if (memcmp(rules[i].dst_ip, &ip_header->daddr, 4) != 0 &&
            memcmp(rules[i].dst_ip, "\x00\x00\x00\x00", 4) != 0) {
            continue;
        }

        // Check transport layer (TCP/UDP)
        if (ip_header->protocol == IPPROTO_TCP) {
            struct tcphdr *tcp_header = (struct tcphdr *)transport_header;

            if (rules[i].src_port != 0 && rules[i].src_port != ntohs(tcp_header->source)) {
                continue;
            }

            if (rules[i].dst_port != 0 && rules[i].dst_port != ntohs(tcp_header->dest)) {
                continue;
            }
        }
        else if (ip_header->protocol == IPPROTO_UDP) {
            struct udphdr *udp_header = (struct udphdr *)transport_header;

            if (rules[i].src_port != 0 && rules[i].src_port != ntohs(udp_header->source)) {
                continue;
            }

            if (rules[i].dst_port != 0 && rules[i].dst_port != ntohs(udp_header->dest)) {
                continue;
            }
        }

        // Rule matched
        action = rules[i].action;
        break;
    }

    return action;
}

// Statistics thread function
void *stats_thread(void *arg) {
    while (running) {
        sleep(1);
        print_stats();
    }
    return NULL;
}

// Print statistics
void print_stats() {
    printf("\rPackets: %lu received, %lu forwarded, %lu dropped | Bytes: %lu",
           statistics.packets_received,
           statistics.packets_forwarded,
           statistics.packets_dropped,
           statistics.bytes_processed);
    fflush(stdout);
}

// Cleanup function
void cleanup(int sig) {
    running = 0;
    printf("\nShutting down...\n");
}

// Add a filter rule (example function)
void add_filter_rule(uint8_t *src_ip, uint8_t *dst_ip, uint16_t src_port,
                    uint16_t dst_port, uint8_t protocol, int action) {
    if (rule_count >= MAX_RULES) {
        fprintf(stderr, "Maximum number of rules reached\n");
        return;
    }

    filter_rule_t *rule = &rules[rule_count++];
    memcpy(rule->src_ip, src_ip, 4);
    memcpy(rule->dst_ip, dst_ip, 4);
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->action = action;
    rule->active = 1;
}
