# Ultra-Low-Latency Networking Service with Packet Filtering and Forwarding

Below is a C implementation of a high-performance networking service that performs packet filtering and forwarding with minimal latency. This design uses raw sockets for direct packet manipulation and efficient data structures for fast lookups.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <netinet/if_ether.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/if_packet.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>

// Configuration
#define MAX_RULES 1024
#define BUFFER_SIZE 65536
#define MAX_THREADS 4

// Packet processing statistics
typedef struct {
    uint64_t packets_processed;
    uint64_t packets_dropped;
    uint64_t packets_forwarded;
} stats_t;

// Filter rule structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
} filter_rule_t;

// Forwarding rule structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint32_t new_dst_ip;
    uint16_t new_dst_port;
} forward_rule_t;

// Global state
typedef struct {
    filter_rule_t filter_rules[MAX_RULES];
    forward_rule_t forward_rules[MAX_RULES];
    int filter_count;
    int forward_count;
    stats_t stats;
    bool running;
    pthread_mutex_t stats_mutex;
} service_state_t;

service_state_t state;

// Initialize the service state
void init_service() {
    memset(&state, 0, sizeof(service_state_t));
    pthread_mutex_init(&state.stats_mutex, NULL);
    state.running = true;
}

// Cleanup resources
void cleanup_service() {
    state.running = false;
    pthread_mutex_destroy(&state.stats_mutex);
}

// Add a filter rule
bool add_filter_rule(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port,
                    uint16_t dst_port, uint8_t protocol, bool allow) {
    if (state.filter_count >= MAX_RULES) return false;

    pthread_mutex_lock(&state.stats_mutex);
    filter_rule_t *rule = &state.filter_rules[state.filter_count++];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->allow = allow;
    pthread_mutex_unlock(&state.stats_mutex);

    return true;
}

// Add a forwarding rule
bool add_forward_rule(uint32_t src_ip, uint32_t dst_ip, uint32_t new_dst_ip,
                     uint16_t new_dst_port) {
    if (state.forward_count >= MAX_RULES) return false;

    pthread_mutex_lock(&state.stats_mutex);
    forward_rule_t *rule = &state.forward_rules[state.forward_count++];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->new_dst_ip = new_dst_ip;
    rule->new_dst_port = new_dst_port;
    pthread_mutex_unlock(&state.stats_mutex);

    return true;
}

// Check if packet matches any filter rule
bool is_packet_allowed(const uint8_t *packet, int len) {
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));
    uint16_t src_port = 0, dst_port = 0;

    // Get port numbers based on protocol
    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    }

    // Check against all filter rules
    for (int i = 0; i < state.filter_count; i++) {
        filter_rule_t *rule = &state.filter_rules[i];

        // Check if rule matches packet
        if ((rule->src_ip == 0 || rule->src_ip == ip->saddr) &&
            (rule->dst_ip == 0 || rule->dst_ip == ip->daddr) &&
            (rule->src_port == 0 || rule->src_port == src_port) &&
            (rule->dst_port == 0 || rule->dst_port == dst_port) &&
            (rule->protocol == 0 || rule->protocol == ip->protocol)) {

            return rule->allow;
        }
    }

    // Default deny if no rules match
    return false;
}

// Apply forwarding rules to packet
void apply_forwarding_rules(uint8_t *packet, int len) {
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Check against all forwarding rules
    for (int i = 0; i < state.forward_count; i++) {
        forward_rule_t *rule = &state.forward_rules[i];

        if ((rule->src_ip == 0 || rule->src_ip == ip->saddr) &&
            (rule->dst_ip == 0 || rule->dst_ip == ip->daddr)) {

            // Apply forwarding rule
            ip->daddr = rule->new_dst_ip;

            // Update checksum
            ip->check = 0;
            ip->check = in_cksum((unsigned short *)ip, sizeof(struct iphdr));

            // For TCP/UDP, update port if specified
            if (rule->new_dst_port != 0) {
                if (ip->protocol == IPPROTO_TCP) {
                    struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
                    tcp->dest = htons(rule->new_dst_port);
                    tcp->check = 0; // Will be recalculated by kernel
                } else if (ip->protocol == IPPROTO_UDP) {
                    struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
                    udp->dest = htons(rule->new_dst_port);
                    udp->check = 0; // Will be recalculated by kernel
                }
            }

            break; // Apply only the first matching rule
        }
    }
}

// IP checksum calculation
unsigned short in_cksum(unsigned short *buf, int len) {
    unsigned long sum = 0;
    while (len > 1) {
        sum += *buf++;
        len -= 2;
    }
    if (len == 1) {
        sum += *(unsigned char *)buf;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return (unsigned short)(~sum);
}

// Packet processing function
void process_packet(int sockfd, uint8_t *buffer, int len) {
    pthread_mutex_lock(&state.stats_mutex);
    state.stats.packets_processed++;
    pthread_mutex_unlock(&state.stats_mutex);

    // Check if packet is allowed
    if (!is_packet_allowed(buffer, len)) {
        pthread_mutex_lock(&state.stats_mutex);
        state.stats.packets_dropped++;
        pthread_mutex_unlock(&state.stats_mutex);
        return;
    }

    // Apply forwarding rules
    apply_forwarding_rules(buffer, len);

    // Forward the packet
    if (send(sockfd, buffer, len, 0) < 0) {
        perror("send");
        return;
    }

    pthread_mutex_lock(&state.stats_mutex);
    state.stats.packets_forwarded++;
    pthread_mutex_unlock(&state.stats_mutex);
}

// Worker thread function
void *worker_thread(void *arg) {
    int sockfd = *(int *)arg;
    uint8_t buffer[BUFFER_SIZE];

    while (state.running) {
        int len = recv(sockfd, buffer, BUFFER_SIZE, 0);
        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        process_packet(sockfd, buffer, len);
    }

    return NULL;
}

// Create raw socket
int create_raw_socket(const char *ifname) {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(ifname);
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    return sockfd;
}

// Signal handler for graceful shutdown
void sigint_handler(int sig) {
    state.running = false;
}

// Print statistics
void print_stats() {
    pthread_mutex_lock(&state.stats_mutex);
    printf("\nStatistics:\n");
    printf("Packets processed: %lu\n", state.stats.packets_processed);
    printf("Packets dropped: %lu\n", state.stats.packets_dropped);
    printf("Packets forwarded: %lu\n", state.stats.packets_forwarded);
    pthread_mutex_unlock(&state.stats_mutex);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *ifname = argv[1];

    // Initialize service
    init_service();

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Create raw socket
    int sockfd = create_raw_socket(ifname);

    // Add some example rules (in a real application, these would come from config)
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, true); // Allow all ICMP
    add_filter_rule(0, 0, 0, 80, IPPROTO_TCP, true); // Allow HTTP
    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, true); // Allow HTTPS

    // Add forwarding rule example
    // add_forward_rule(inet_addr("192.168.1.100"), inet_addr("10.0.0.1"), inet_addr("192.168.1.200"), 8080);

    // Create worker threads
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, &sockfd) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    // Main thread can do other work or just wait
    while (state.running) {
        sleep(1);
    }

    // Clean up
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    close(sockfd);
    cleanup_service();
    print_stats();

    return 0;
}
