#include <linux/if_ether.h>
#include <linux/if.h>
#include <poll.h>

class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
    virtual ~PacketFilter() = default;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;

public:
    SimpleIPFilter() {
        // Example: Allow only specific IPs
        allowedIPs[inet_addr("192.168.1.1")] = true;
        allowedIPs[inet_addr("10.0.0.1")] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(ethhdr) + sizeof(iphdr)) return false;

        const ethhdr* eth = reinterpret_cast<const ethhdr*>(packet);
        if (ntohs(eth->h_proto) != ETH_P_IP) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet + sizeof(ethhdr));
        return allowedIPs.find(ip->saddr) != allowedIPs.end();
    }
};

class LowLatencyNetworkService {
    int socket_fd;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::atomic<bool> running;
    std::vector<std::thread> worker_threads;
    size_t buffer_size;
    uint8_t* rx_buffer;
    uint8_t* tx_buffer;

public:
    LowLatencyNetworkService(size_t buffer_size = 16 * 1024 * 1024)
        : buffer_size(buffer_size), running(false) {

        // Allocate huge pages for low-latency memory
        rx_buffer = static_cast<uint8_t*>(mmap(
            nullptr, buffer_size * 2,
            PROT_READ | PROT_WRITE,
            MAP_PRIVATE | MAP_ANONYMOUS | MAP_HUGETLB,
            -1, 0));

        if (rx_buffer == MAP_FAILED) {
            std::cerr << "Failed to allocate huge pages, falling back to regular memory" << std::endl;
            rx_buffer = new uint8_t[buffer_size * 2];
        }

        tx_buffer = rx_buffer + buffer_size;

        // Create raw socket for packet capture
        socket_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (socket_fd < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(socket_fd, F_GETFL, 0);
        fcntl(socket_fd, F_SETFL, flags | O_NONBLOCK);

        // Set socket to receive all packets
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex("eth0"); // Change to your interface
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(socket_fd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            throw std::runtime_error("Failed to bind socket");
        }
    }

    ~LowLatencyNetworkService() {
        stop();

        if (rx_buffer != MAP_FAILED) {
            munmap(rx_buffer, buffer_size * 2);
        } else {
            delete[] rx_buffer;
        }

        close(socket_fd);
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    void start(size_t num_threads = 4) {
        running = true;

        for (size_t i = 0; i < num_threads; ++i) {
            worker_threads.emplace_back([this, i]() {
                processPackets(i);
            });
        }
    }

    void stop() {
        running = false;
        for (auto& t : worker_threads) {
            if (t.joinable()) t.join();
        }
        worker_threads.clear();
    }

private:
    void processPackets(size_t thread_id) {
        struct pollfd pfd;
        pfd.fd = socket_fd;
        pfd.events = POLLIN;

        while (running) {
            int ret = poll(&pfd, 1, 100);
            if (ret <= 0) continue;

            if (pfd.revents & POLLIN) {
                ssize_t len = recv(socket_fd, rx_buffer, buffer_size, 0);
                if (len <= 0) continue;

                // Process packet through filters
                bool should_forward = true;
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(rx_buffer, len)) {
                        should_forward = false;
                        break;
                    }
                }

                if (should_forward) {
                    // Forward the packet (simplified - in real code you'd need proper routing)
                    send(socket_fd, rx_buffer, len, 0);
                }
            }
        }
    }
};

int main() {
    try {
        LowLatencyNetworkService service;

        // Add packet filters
        service.addFilter(std::make_unique<SimpleIPFilter>());

        // Start the service with 4 worker threads
        service.start(4);

        std::cout << "Low-latency networking service running. Press Enter to stop..." << std::endl;
        std::cin.get();

        service.stop();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

## Key Features for Ultra-Low Latency:

1. **Huge Page Memory Allocation**: Uses `mmap` with `MAP_HUGETLB` for low-latency memory access.

2. **Non-Blocking I/O**: Uses `poll()` for efficient waiting on socket events.

3. **Lock-Free Design**: Atomic variables and thread-local processing minimize contention.

4. **Direct Packet Access**: Uses raw sockets for minimal protocol overhead.

5. **Filter Pipeline**: Multiple filters can be chained for complex filtering logic.

6. **Multi-threaded Processing**: Distributes packet processing across multiple cores.

