#include <linux/if_ether.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>

// Configuration structure
typedef struct {
    char *interface;
    uint16_t filter_port;
    char *forward_ip;
    uint16_t forward_port;
    int verbose;
} Config;

// Packet processing statistics
typedef struct {
    uint64_t total_packets;
    uint64_t filtered_packets;
    uint64_t forwarded_packets;
    uint64_t dropped_packets;
} Stats;

// Global variables
Config config;
Stats stats = {0};
int running = 1;

// Function prototypes
void *packet_receiver(void *arg);
void process_packet(unsigned char *buffer, int size);
void filter_and_forward(unsigned char *buffer, int size);
void print_stats();

int main(int argc, char *argv[]) {
    // Parse command line arguments
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <interface> <filter_port> <forward_ip> <forward_port> [verbose]\n", argv[0]);
        return 1;
    }

    config.interface = argv[1];
    config.filter_port = atoi(argv[2]);
    config.forward_ip = argv[3];
    config.forward_port = atoi(argv[4]);
    config.verbose = (argc > 5) ? atoi(argv[5]) : 0;

    // Create raw socket
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    // Get interface index
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, config.interface, IFNAMSIZ-1);
    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl");
        close(sockfd);
        return 1;
    }
    int ifindex = ifr.ifr_ifindex;

    // Bind socket to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);
    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return 1;
    }

    // Set socket to non-blocking mode
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    // Create receiver thread
    pthread_t receiver_thread;
    if (pthread_create(&receiver_thread, NULL, packet_receiver, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return 1;
    }

    // Main loop for statistics and control
    while (running) {
        sleep(1);
        print_stats();
    }

    // Cleanup
    pthread_join(receiver_thread, NULL);
    close(sockfd);
    return 0;
}

void *packet_receiver(void *arg) {
    int sockfd = *(int *)arg;
    unsigned char buffer[65536];
    struct sockaddr_ll from;
    socklen_t fromlen = sizeof(from);

    while (running) {
        int size = recvfrom(sockfd, buffer, sizeof(buffer), 0, (struct sockaddr *)&from, &fromlen);
        if (size < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, continue
                usleep(100); // Small sleep to prevent busy waiting
                continue;
            }
            perror("recvfrom");
            break;
        }

        stats.total_packets++;
        process_packet(buffer, size);
    }

    return NULL;
}

void process_packet(unsigned char *buffer, int size) {
    struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));

    // Check for IPv4 packets
    if (ip_header->version != 4) {
        stats.dropped_packets++;
        return;
    }

    // Check protocol (TCP or UDP)
    if (ip_header->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip_header->ihl * 4);

        if (ntohs(tcp_header->dest) == config.filter_port) {
            filter_and_forward(buffer, size);
        }
    } else if (ip_header->protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(buffer + sizeof(struct ethhdr) + ip_header->ihl * 4);

        if (ntohs(udp_header->dest) == config.filter_port) {
            filter_and_forward(buffer, size);
        }
    }
}

void filter_and_forward(unsigned char *buffer, int size) {
    stats.filtered_packets++;

    // Create a new socket for forwarding
    int forward_sock = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (forward_sock < 0) {
        perror("forward socket");
        stats.dropped_packets++;
        return;
    }

    // Set socket options to allow IP header inclusion
    int one = 1;
    if (setsockopt(forward_sock, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        perror("setsockopt");
        close(forward_sock);
        stats.dropped_packets++;
        return;
    }

    // Prepare destination address
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(config.forward_port);
    if (inet_pton(AF_INET, config.forward_ip, &dest_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(forward_sock);
        stats.dropped_packets++;
        return;
    }

    // Forward the packet
    if (sendto(forward_sock, buffer, size, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto");
        stats.dropped_packets++;
    } else {
        stats.forwarded_packets++;
    }

    close(forward_sock);
}

void print_stats() {
    printf("\n=== Statistics ===\n");
    printf("Total packets received: %lu\n", stats.total_packets);
    printf("Filtered packets: %lu\n", stats.filtered_packets);
    printf("Forwarded packets: %lu\n", stats.forwarded_packets);
    printf("Dropped packets: %lu\n", stats.dropped_packets);
    printf("=================\n");
}
