// Packet filter interface
class PacketFilter {
public:
    virtual ~PacketFilter() = default;
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
};

// Simple IP-based filter example
class IPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;

public:
    IPFilter() {
        // Example: Allow only these IPs
        allowedIPs[inet_addr("192.168.1.1")] = true;
        allowedIPs[inet_addr("10.0.0.1")] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(ether_header) + sizeof(ip)) {
            return false;
        }

        const ip* iph = (ip*)(packet + sizeof(ether_header));
        return allowedIPs.find(iph->ip_src.s_addr) != allowedIPs.end();
    }
};

// Packet processor interface
class PacketProcessor {
public:
    virtual ~PacketProcessor() = default;
    virtual void processPacket(const uint8_t* packet, size_t len) = 0;
};

// Forwarding processor
class ForwardingProcessor : public PacketProcessor {
    int forwardSocket;
    std::string destinationIP;
    uint16_t destinationPort;

public:
    ForwardingProcessor(const std::string& destIP, uint16_t destPort)
        : destinationIP(destIP), destinationPort(destPort) {
        forwardSocket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (forwardSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }
    }

    ~ForwardingProcessor() {
        close(forwardSocket);
    }

    void processPacket(const uint8_t* packet, size_t len) override {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_port = htons(destinationPort);
        inet_pton(AF_INET, destinationIP.c_str(), &destAddr.sin_addr);

        if (sendto(forwardSocket, packet, len, 0,
                   (sockaddr*)&destAddr, sizeof(destAddr)) < 0) {
            perror("Packet forwarding failed");
        }
    }
};

// Main networking service
class LowLatencyNetworkService {
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::vector<std::unique_ptr<PacketProcessor>> processors;
    std::atomic<bool> running{false};
    std::thread workerThread;

    int rawSocket;
    uint8_t buffer[65536]; // Max Ethernet frame size

public:
    LowLatencyNetworkService() {
        // Create raw socket for packet capture
        rawSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rawSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }
    }

    ~LowLatencyNetworkService() {
        stop();
        close(rawSocket);
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    void addProcessor(std::unique_ptr<PacketProcessor> processor) {
        processors.push_back(std::move(processor));
    }

    void start() {
        running = true;
        workerThread = std::thread([this]() { this->run(); });
    }

    void stop() {
        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void run() {
        pollfd fds[1];
        fds[0].fd = rawSocket;
        fds[0].events = POLLIN;

        while (running) {
            // Use poll with timeout to allow graceful shutdown
            int ret = poll(fds, 1, 100);
            if (ret <= 0) {
                continue;
            }

            if (fds[0].revents & POLLIN) {
                sockaddr_ll sender{};
                socklen_t senderLen = sizeof(sender);

                ssize_t packetLen = recvfrom(rawSocket, buffer, sizeof(buffer), 0,
                                           (sockaddr*)&sender, &senderLen);

                if (packetLen < 0) {
                    perror("Packet receive failed");
                    continue;
                }

                // Apply all filters
                bool shouldForward = true;
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(buffer, packetLen)) {
                        shouldForward = false;
                        break;
                    }
                }

                // Process packet if it passes all filters
                if (shouldForward) {
                    for (const auto& processor : processors) {
                        processor->processPacket(buffer, packetLen);
                    }
                }
            }
        }
    }
};

