};

class SimplePortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;

public:
    void addAllowedPort(uint16_t port) {
        allowedPorts[port] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        // Skip Ethernet header (14 bytes)
        const iphdr* ipHeader = reinterpret_cast<const iphdr*>(packet + 14);

        if (ipHeader->protocol == IPPROTO_TCP) {
            const tcphdr* tcpHeader = reinterpret_cast<const tcphdr*>(
                packet + 14 + (ipHeader->ihl * 4));
            return allowedPorts.find(ntohs(tcpHeader->dest)) != allowedPorts.end();
        }
        else if (ipHeader->protocol == IPPROTO_UDP) {
            const udphdr* udpHeader = reinterpret_cast<const udphdr*>(
                packet + 14 + (ipHeader->ihl * 4));
            return allowedPorts.find(ntohs(udpHeader->dest)) != allowedPorts.end();
        }

        // Default: forward all non-TCP/UDP packets
        return true;
    }
};

class LowLatencyForwarder {
    int rawSocket;
    int forwardSocket;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::atomic<bool> running;
    std::thread workerThread;

public:
    LowLatencyForwarder(const std::string& interface, const std::string& forwardIP, uint16_t forwardPort)
        : running(false) {

        // Create raw socket for packet capture
        rawSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rawSocket < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create raw socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(rawSocket, F_GETFL, 0);
        fcntl(rawSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to specific interface
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex(interface.c_str());
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(rawSocket, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            close(rawSocket);
            throw std::runtime_error("Failed to bind socket");
        }

        // Create UDP socket for forwarding
        forwardSocket = socket(AF_INET, SOCK_DGRAM, 0);
        if (forwardSocket < 0) {
            perror("socket");
            close(rawSocket);
            throw std::runtime_error("Failed to create forward socket");
        }

        // Configure forward address
        struct sockaddr_in forwardAddr;
        memset(&forwardAddr, 0, sizeof(forwardAddr));
        forwardAddr.sin_family = AF_INET;
        forwardAddr.sin_port = htons(forwardPort);
        inet_pton(AF_INET, forwardIP.c_str(), &forwardAddr.sin_addr);

        if (connect(forwardSocket, (struct sockaddr*)&forwardAddr, sizeof(forwardAddr)) < 0) {
            perror("connect");
            close(rawSocket);
            close(forwardSocket);
            throw std::runtime_error("Failed to connect forward socket");
        }
    }

    ~LowLatencyForwarder() {
        stop();
        close(rawSocket);
        close(forwardSocket);
