        filters.push_back(std::move(filter));
    }

    void start() {
        if (running) return;

        running = true;
        workerThread = std::thread([this]() {
            processPackets();
        });
    }

    void stop() {
        if (!running) return;

        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void processPackets() {
        const size_t bufferSize = 65536;
        uint8_t buffer[bufferSize];

        while (running) {
            ssize_t bytesRead = recv(rawSocket, buffer, bufferSize, 0);
            if (bytesRead < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    // No data available, yield CPU
                    std::this_thread::yield();
                    continue;
                }
                perror("recv");
                break;
            }

            // Check if packet should be forwarded
            bool shouldForward = true;
            for (const auto& filter : filters) {
                if (!filter->shouldForward(buffer, bytesRead)) {
                    shouldForward = false;
                    break;
                }
            }

            if (shouldForward) {
                // Forward the packet
                if (send(forwardSocket, buffer, bytesRead, 0) < 0) {
                    perror("send");
                }
            }
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <interface> <forward_ip> <forward_port> [allowed_ports...]\n";
        return 1;
    }

    try {
        LowLatencyForwarder forwarder(argv[1], argv[2], std::stoi(argv[3]));

