#include <signal.h>
#include <time.h>
#include <stdbool.h>

// Configuration
#define MAX_PACKET_SIZE 1500
#define MAX_RULES 1024
#define MAX_THREADS 4
#define BUFFER_SIZE (1024 * 1024) // 1MB buffer

// Packet filter rule structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
} FilterRule;

// Thread data structure
typedef struct {
    int socket_fd;
    int thread_id;
    FilterRule* rules;
    int rule_count;
    volatile bool running;
} ThreadData;

// Global variables
volatile sig_atomic_t keep_running = 1;
pthread_mutex_t rule_mutex = PTHREAD_MUTEX_INITIALIZER;

// Signal handler for graceful shutdown
void sigint_handler(int sig) {
    keep_running = 0;
}

// Packet processing function
void process_packet(unsigned char* buffer, int size, FilterRule* rules, int rule_count) {
    struct iphdr* iph = (struct iphdr*)(buffer + sizeof(struct ethhdr));
    int iphdr_len = iph->ihl * 4;

    // Check for TCP or UDP
    if (iph->protocol == IPPROTO_TCP) {
        struct tcphdr* tcph = (struct tcphdr*)(buffer + sizeof(struct ethhdr) + iphdr_len);

        // Check rules
        for (int i = 0; i < rule_count; i++) {
            if (rules[i].protocol == IPPROTO_TCP &&
                (rules[i].src_ip == 0 || rules[i].src_ip == iph->saddr) &&
                (rules[i].dst_ip == 0 || rules[i].dst_ip == iph->daddr) &&
                (rules[i].src_port == 0 || rules[i].src_port == ntohs(tcph->source)) &&
                (rules[i].dst_port == 0 || rules[i].dst_port == ntohs(tcph->dest))) {

                if (rules[i].allow) {
                    // Forward packet (simplified - in real implementation you'd send it out another interface)
                    printf("Thread %d: Forwarding TCP packet from %s:%d to %s:%d\n",
                           pthread_self(), inet_ntoa(*(struct in_addr*)&iph->saddr),
                           ntohs(tcph->source), inet_ntoa(*(struct in_addr*)&iph->daddr),
                           ntohs(tcph->dest));
                } else {
                    printf("Thread %d: Dropping TCP packet from %s:%d to %s:%d\n",
                           pthread_self(), inet_ntoa(*(struct in_addr*)&iph->saddr),
                           ntohs(tcph->source), inet_ntoa(*(struct in_addr*)&iph->daddr),
                           ntohs(tcph->dest));
                }
                return;
            }
        }
    } else if (iph->protocol == IPPROTO_UDP) {
        struct udphdr* udph = (struct udphdr*)(buffer + sizeof(struct ethhdr) + iphdr_len);

        // Check rules
        for (int i = 0; i < rule_count; i++) {
            if (rules[i].protocol == IPPROTO_UDP &&
                (rules[i].src_ip == 0 || rules[i].src_ip == iph->saddr) &&
                (rules[i].dst_ip == 0 || rules[i].dst_ip == iph->daddr) &&
                (rules[i].src_port == 0 || rules[i].src_port == ntohs(udph->source)) &&
                (rules[i].dst_port == 0 || rules[i].dst_port == ntohs(udph->dest))) {

                if (rules[i].allow) {
                    printf("Thread %d: Forwarding UDP packet from %s:%d to %s:%d\n",
                           pthread_self(), inet_ntoa(*(struct in_addr*)&iph->saddr),
                           ntohs(udph->source), inet_ntoa(*(struct in_addr*)&iph->daddr),
                           ntohs(udph->dest));
                } else {
                    printf("Thread %d: Dropping UDP packet from %s:%d to %s:%d\n",
                           pthread_self(), inet_ntoa(*(struct in_addr*)&iph->saddr),
                           ntohs(udph->source), inet_ntoa(*(struct in_addr*)&iph->daddr),
                           ntohs(udph->dest));
                }
                return;
            }
        }
    }

    // Default action if no rule matches
    printf("Thread %d: No matching rule, forwarding packet\n", pthread_self());
}

// Worker thread function
void* worker_thread(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    unsigned char buffer[MAX_PACKET_SIZE];

    while (data->running && keep_running) {
        int packet_size = recv(data->socket_fd, buffer, MAX_PACKET_SIZE, 0);
        if (packet_size < 0) {
            if (errno == EINTR) continue; // Interrupted by signal
            perror("recv failed");
            break;
        }

        process_packet(buffer, packet_size, data->rules, data->rule_count);
    }

    printf("Thread %d exiting\n", data->thread_id);
    return NULL;
}

// Add a new filter rule
void add_rule(FilterRule* rules, int* rule_count, FilterRule new_rule) {
    pthread_mutex_lock(&rule_mutex);
    if (*rule_count < MAX_RULES) {
        rules[*rule_count] = new_rule;
        (*rule_count)++;
    }
    pthread_mutex_unlock(&rule_mutex);
}

// Main function
int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Create raw socket
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket creation failed");
        return 1;
    }

    // Bind to interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, argv[1], IFNAMSIZ-1);

    if (setsockopt(sockfd, SOL_SOCKET, SO_BINDTODEVICE, (void *)&ifr, sizeof(ifr)) < 0) {
        perror("setsockopt failed");
        close(sockfd);
        return 1;
    }

    // Set socket to non-blocking
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    // Allocate rules array
    FilterRule* rules = malloc(MAX_RULES * sizeof(FilterRule));
    if (!rules) {
        perror("malloc failed");
        close(sockfd);
        return 1;
    }
    int rule_count = 0;

    // Add some example rules
    FilterRule rule1 = {0, 0, 0, 0, IPPROTO_TCP, true}; // Allow all TCP by default
    add_rule(rules, &rule_count, rule1);

    FilterRule rule2 = {inet_addr("192.168.1.100"), 0, 0, 0, IPPROTO_UDP, false}; // Block UDP from 192.168.1.100
    add_rule(rules, &rule_count, rule2);

    // Create worker threads
    pthread_t threads[MAX_THREADS];
    ThreadData thread_data[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_data[i].socket_fd = sockfd;
        thread_data[i].thread_id = i;
        thread_data[i].rules = rules;
        thread_data[i].rule_count = rule_count;
        thread_data[i].running = true;

        if (pthread_create(&threads[i], NULL, worker_thread, &thread_data[i]) != 0) {
            perror("pthread_create failed");
            keep_running = 0;
            break;
        }
    }

    // Main loop - could be used for management tasks
    while (keep_running) {
        sleep(1);
    }

    // Cleanup
    for (int i = 0; i < MAX_THREADS; i++) {
        thread_data[i].running = false;
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(rules);
    close(sockfd);

    printf("Service shutdown complete\n");
    return 0;
}
