### 2. Main Service Loop

```c
#include <stdio.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <sys/ioctl.h>
#include <net/if.h>

#define BUFFER_SIZE 4096

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    const char *ifname = argv[1];
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd == -1) {
        perror("socket");
        return 1;
    }

    // Set up interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ-1);

    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) == -1) {
        perror("ioctl SIOCGIFINDEX");
        close(sockfd);
        return 1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) == -1) {
        perror("bind");
        close(sockfd);
        return 1;
    }

    // Create packet processor
    PacketProcessor *processor = create_processor(BUFFER_SIZE);
    if (!processor) {
        perror("create_processor");
        close(sockfd);
        return 1;
    }

    // Example rules - in a real implementation these would be configurable
    FilterRule rule1 = {
        .src_ip = 0, // any source
        .dst_ip = inet_addr("192.168.1.100"),
        .src_port = 0,
        .dst_port = 80,
        .protocol = IPPROTO_TCP,
        .action = 1 // forward
    };

    FilterRule rule2 = {
        .src_ip = 0,
        .dst_ip = inet_addr("192.168.1.100"),
        .src_port = 0,
        .dst_port = 22,
        .protocol = IPPROTO_TCP,
        .action = 0 // drop
    };

    add_filter_rule(processor, rule1);
    add_filter_rule(processor, rule2);

    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t fromlen = sizeof(from);

    printf("Starting packet processing on %s...\n", ifname);

    while (1) {
        ssize_t len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0,
                              (struct sockaddr *)&from, &fromlen);
        if (len == -1) {
            perror("recvfrom");
            continue;
        }

        int action = process_packet(processor, buffer, len);
        if (action == 1) {
            // Forward packet
            if (sendto(sockfd, processor->packet_buffer, len, 0,
                       (struct sockaddr *)&from, fromlen) == -1) {
                perror("sendto");
            }
        }
        // else packet is dropped
    }

    destroy_processor(processor);
    close(sockfd);
    return 0;
}
