#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>

class Packet {
public:
    std::vector<uint8_t> data;
    sockaddr_in src_addr;
    sockaddr_in dest_addr;
    uint16_t protocol; // IPPROTO_UDP or IPPROTO_TCP

    Packet() = default;
    Packet(const std::vector<uint8_t>& data, const sockaddr_in& src, const sockaddr_in& dest, uint16_t proto)
        : data(data), src_addr(src), dest_addr(dest), protocol(proto) {}
};

class PacketFilter {
public:
    virtual bool shouldForward(const Packet& packet) = 0;
    virtual ~PacketFilter() = default;
};

class BasicIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowed_ips;
public:
    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowed_ips[addr] = true;
    }

    bool shouldForward(const Packet& packet) override {
        uint32_t src_ip = packet.src_addr.sin_addr.s_addr;
        uint32_t dest_ip = packet.dest_addr.sin_addr.s_addr;

        return allowed_ips.count(src_ip) || allowed_ips.count(dest_ip);
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowed_ports;
public:
    void addAllowedPort(uint16_t port) {
        allowed_ports[port] = true;
    }

    bool shouldForward(const Packet& packet) override {
        if (packet.protocol == IPPROTO_UDP) {
            udphdr* udp = reinterpret_cast<udphdr*>(packet.data.data() + sizeof(iphdr));
            return allowed_ports.count(ntohs(udp->source)) ||
                   allowed_ports.count(ntohs(udp->dest));
        } else if (packet.protocol == IPPROTO_TCP) {
            tcphdr* tcp = reinterpret_cast<tcphdr*>(packet.data.data() + sizeof(iphdr));
            return allowed_ports.count(ntohs(tcp->source)) ||
                   allowed_ports.count(ntohs(tcp->dest));
        }
        return false;
    }
};

class NetworkService {
    int listen_sock;
    std::vector<std::shared_ptr<PacketFilter>> filters;
    std::atomic<bool> running;
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::thread> workers;

public:
    NetworkService() : listen_sock(-1), running(false) {}

    ~NetworkService() {
        stop();
    }

    bool initialize(const std::string& bind_ip, uint16_t port) {
        listen_sock = socket(AF_INET, SOCK_RAW, IPPROTO_IP);
        if (listen_sock < 0) {
            perror("socket");
            return false;
        }

        // Set socket to non-blocking
        int flags = fcntl(listen_sock, F_GETFL, 0);
        fcntl(listen_sock, F_SETFL, flags | O_NONBLOCK);

        // Bind to interface
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = inet_addr(bind_ip.c_str());
        addr.sin_port = htons(port);

        if (bind(listen_sock, (sockaddr*)&addr, sizeof(addr)) < 0) {
            perror("bind");
            close(listen_sock);
            return false;
        }

        return true;
    }

    void addFilter(std::shared_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(filter);
    }

    bool start(size_t num_threads = 4) {
        if (listen_sock < 0) return false;

        running = true;

        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }

        return true;
    }

    void stop() {
        running = false;
        cv.notify_all();

        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }

        if (listen_sock >= 0) {
            close(listen_sock);
            listen_sock = -1;
        }
    }

private:
    void workerThread() {
        std::vector<uint8_t> buffer(65536); // MTU size

        while (running) {
            // Use poll for efficient waiting
            pollfd pfd{};
            pfd.fd = listen_sock;
            pfd.events = POLLIN;

            int ret = poll(&pfd, 1, 100); // 100ms timeout
            if (ret <= 0) continue;

            sockaddr_in src_addr{}, dest_addr{};
            socklen_t addr_len = sizeof(src_addr);

            ssize_t bytes_read = recvfrom(listen_sock, buffer.data(), buffer.size(),
                                        0, (sockaddr*)&src_addr, &addr_len);

            if (bytes_read <= 0) continue;

            // Parse IP header
            iphdr* ip = reinterpret_cast<iphdr*>(buffer.data());

            // Get destination address (we need to reconstruct it)
            dest_addr.sin_family = AF_INET;
            dest_addr.sin_addr.s_addr = ip->daddr;
            dest_addr.sin_port = 0; // Not used for IP filtering

            Packet packet(buffer, src_addr, dest_addr, ip->protocol);

            // Apply filters
            bool should_forward = true;
            {
                std::lock_guard<std::mutex> lock(mtx);
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(packet)) {
                        should_forward = false;
                        break;
                    }
                }
            }

            if (should_forward) {
                // Forward the packet (in a real implementation, this would send to another interface)
                std::cout << "Forwarding packet from "
                          << inet_ntoa(src_addr.sin_addr) << " to "
                          << inet_ntoa(dest_addr.sin_addr) << std::endl;
            }
        }
    }
};

int main() {
    NetworkService service;

    if (!service.initialize("0.0.0.0", 0)) { // 0 means all ports
        std::cerr << "Failed to initialize network service" << std::endl;
        return 1;
    }

    // Add some filters
    auto ip_filter = std::make_shared<BasicIPFilter>();
    ip_filter->addAllowedIP("192.168.1.100");
    ip_filter->addAllowedIP("10.0.0.1");

    auto port_filter = std::make_shared<PortFilter>();
    port_filter->addAllowedPort(80);
    port_filter->addAllowedPort(443);

    service.addFilter(ip_filter);
    service.addFilter(port_filter);

    if (!service.start(4)) { // Start with 4 worker threads
        std::cerr << "Failed to start network service" << std::endl;
        return 1;
    }

    std::cout << "Network service running. Press Enter to stop..." << std::endl;
    std::cin.get();

    service.stop();

    return 0;
}
