#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>

class PacketFilter {
public:
    enum class Action { DROP, FORWARD, MODIFY };

    struct Rule {
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint32_t src_ip = 0;
        uint32_t dst_ip = 0;
        uint8_t protocol = 0; // 0 = any, 6 = TCP, 17 = UDP
        Action action = Action::DROP;
        std::vector<uint8_t> payload_pattern;
    };

    void add_rule(const Rule& rule) {
        std::lock_guard<std::mutex> lock(rules_mutex_);
        rules_.push_back(rule);
    }

    Action evaluate(const uint8_t* packet, size_t len) const {
        std::lock_guard<std::mutex> lock(rules_mutex_);

        // Parse basic IP header
        const iphdr* ip_header = reinterpret_cast<const iphdr*>(packet);
        if (len < sizeof(iphdr) || ip_header->version != 4) {
            return Action::DROP;
        }

        // Check each rule
        for (const auto& rule : rules_) {
            // Protocol check
            if (rule.protocol != 0 && rule.protocol != ip_header->protocol) {
                continue;
            }

            // IP address check
            if (rule.src_ip != 0 && rule.src_ip != ip_header->saddr) {
                continue;
            }
            if (rule.dst_ip != 0 && rule.dst_ip != ip_header->daddr) {
                continue;
            }

            // Transport layer check
            if (ip_header->protocol == IPPROTO_TCP || ip_header->protocol == IPPROTO_UDP) {
                size_t transport_offset = ip_header->ihl * 4;
                if (len < transport_offset + sizeof(tcphdr)) {
                    continue;
                }

                const tcphdr* tcp_header = reinterpret_cast<const tcphdr*>(packet + transport_offset);
                if (rule.src_port != 0 && rule.src_port != ntohs(tcp_header->source)) {
                    continue;
                }
                if (rule.dst_port != 0 && rule.dst_port != ntohs(tcp_header->dest)) {
                    continue;
                }

                // Payload pattern check if specified
                if (!rule.payload_pattern.empty()) {
                    size_t payload_offset = transport_offset + (ip_header->protocol == IPPROTO_TCP ? tcp_header->doff * 4 : sizeof(udphdr));
                    if (len > payload_offset + rule.payload_pattern.size()) {
                        if (memcmp(packet + payload_offset, rule.payload_pattern.data(), rule.payload_pattern.size()) != 0) {
                            continue;
                        }
                    }
                }
            }

            // Rule matched
            return rule.action;
        }

        // No rules matched - default action
        return default_action_;
    }

    void set_default_action(Action action) {
        default_action_ = action;
    }

private:
    mutable std::mutex rules_mutex_;
    std::vector<Rule> rules_;
    Action default_action_ = Action::DROP;
};

class PacketForwarder {
public:
    PacketForwarder(int socket_fd, const std::string& dst_ip, uint16_t dst_port)
        : socket_fd_(socket_fd), dst_ip_(dst_ip), dst_port_(dst_port) {}

    void forward(const uint8_t* packet, size_t len) {
        sockaddr_in dst_addr{};
        dst_addr.sin_family = AF_INET;
        dst_addr.sin_port = htons(dst_port_);
        inet_pton(AF_INET, dst_ip_.c_str(), &dst_addr.sin_addr);

        sendto(socket_fd_, packet, len, 0, reinterpret_cast<sockaddr*>(&dst_addr), sizeof(dst_addr));
    }

private:
    int socket_fd_;
    std::string dst_ip_;
    uint16_t dst_port_;
};

class NetworkService {
public:
    NetworkService(int listen_port, const std::string& forward_ip, uint16_t forward_port)
        : listen_port_(listen_port), forward_ip_(forward_ip), forward_port_(forward_port) {
        filter_.set_default_action(PacketFilter::Action::DROP);
    }

    void add_filter_rule(const PacketFilter::Rule& rule) {
        filter_.add_rule(rule);
    }

    void start() {
        running_ = true;

        // Create raw socket for packet capture
        socket_fd_ = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (socket_fd_ < 0) {
            perror("socket");
            return;
        }

        // Set socket to non-blocking
        int flags = fcntl(socket_fd_, F_GETFL, 0);
        fcntl(socket_fd_, F_SETFL, flags | O_NONBLOCK);

        // Bind to listen port
        sockaddr_in bind_addr{};
        bind_addr.sin_family = AF_INET;
        bind_addr.sin_port = htons(listen_port_);
        bind_addr.sin_addr.s_addr = INADDR_ANY;

        if (bind(socket_fd_, reinterpret_cast<sockaddr*>(&bind_addr), sizeof(bind_addr)) < 0) {
            perror("bind");
            close(socket_fd_);
            return;
        }

        // Create forwarder
        forwarder_ = std::make_unique<PacketForwarder>(socket_fd_, forward_ip_, forward_port_);

        // Start processing thread
        processing_thread_ = std::thread([this]() { process_packets(); });
    }

    void stop() {
        running_ = false;
        if (processing_thread_.joinable()) {
            processing_thread_.join();
        }
        if (socket_fd_ >= 0) {
            close(socket_fd_);
        }
    }

private:
    void process_packets() {
        const size_t BUFFER_SIZE = 65536;
        std::vector<uint8_t> buffer(BUFFER_SIZE);

        while (running_) {
            pollfd pfd{};
            pfd.fd = socket_fd_;
            pfd.events = POLLIN;

            // Wait for data with timeout
            int ret = poll(&pfd, 1, 100);
            if (ret <= 0) {
                continue;
            }

            // Receive packet
            sockaddr_in src_addr{};
            socklen_t src_len = sizeof(src_addr);
            ssize_t bytes_received = recvfrom(socket_fd_, buffer.data(), BUFFER_SIZE, 0,
                                             reinterpret_cast<sockaddr*>(&src_addr), &src_len);

            if (bytes_received <= 0) {
                continue;
            }

            // Filter packet
            auto action = filter_.evaluate(buffer.data(), bytes_received);

            // Process based on filter action
            switch (action) {
                case PacketFilter::Action::FORWARD:
                    forwarder_->forward(buffer.data(), bytes_received);
                    break;
                case PacketFilter::Action::MODIFY:
                    // In a real implementation, we would modify the packet here
                    forwarder_->forward(buffer.data(), bytes_received);
                    break;
                case PacketFilter::Action::DROP:
                    // Packet is dropped
                    break;
            }
        }
    }

    int listen_port_;
    std::string forward_ip_;
    uint16_t forward_port_;
    int socket_fd_ = -1;
    std::atomic<bool> running_{false};
    std::thread processing_thread_;
    PacketFilter filter_;
    std::unique_ptr<PacketForwarder> forwarder_;
};

int main() {
    // Example configuration
    const int LISTEN_PORT = 8080;
    const std::string FORWARD_IP = "192.168.1.100";
    const uint16_t FORWARD_PORT = 80;

    // Create network service
    NetworkService service(LISTEN_PORT, FORWARD_IP, FORWARD_PORT);

    // Add some filter rules
    PacketFilter::Rule rule1;
    rule1.protocol = IPPROTO_TCP;
    rule1.dst_port = 80; // HTTP port
    rule1.action = PacketFilter::Action::FORWARD;
    service.add_filter_rule(rule1);

    PacketFilter::Rule rule2;
    rule2.protocol = IPPROTO_UDP;
    rule2.dst_port = 53; // DNS port
    rule2.action = PacketFilter::Action::DROP;
    service.add_filter_rule(rule2);

    // Start the service
    service.start();

    std::cout << "Network service running. Press Enter to stop..." << std::endl;
    std::cin.get();

    // Stop the service
    service.stop();

    return 0;
}
