class PacketFilter {
public:
    enum class Action { DROP, FORWARD, MODIFY };

    struct Rule {
        uint32_t src_ip = 0;
        uint32_t dst_ip = 0;
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint8_t protocol = 0; // 0 = any, 6 = TCP, 17 = UDP
        Action action = Action::DROP;
        uint32_t new_dst_ip = 0; // For forwarding/modifying
    };

    void add_rule(const Rule& rule) {
        std::lock_guard<std::mutex> lock(rules_mutex_);
        rules_.push_back(rule);
    }

    Action evaluate(const uint8_t* packet, size_t len) const {
        if (len < sizeof(iphdr)) return Action::DROP;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);

        // Basic IP header validation
        if (ip->version != 4 || len < sizeof(iphdr) + (ip->ihl * 4)) {
            return Action::DROP;
        }

        std::lock_guard<std::mutex> lock(rules_mutex_);

        for (const auto& rule : rules_) {
            // Check protocol
            if (rule.protocol != 0 && rule.protocol != ip->protocol) {
                continue;
            }

            // Check source IP
            if (rule.src_ip != 0 && rule.src_ip != ip->saddr) {
                continue;
            }

            // Check destination IP
            if (rule.dst_ip != 0 && rule.dst_ip != ip->daddr) {
                continue;
            }

            // Check transport layer if needed
            if (ip->protocol == IPPROTO_TCP || ip->protocol == IPPROTO_UDP) {
                size_t header_len = sizeof(iphdr) + (ip->ihl * 4);
                if (len < header_len + sizeof(tcphdr)) continue;

                const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + header_len);

                // Check source port
                if (rule.src_port != 0 && rule.src_port != ntohs(tcp->source)) {
                    continue;
                }

                // Check destination port
                if (rule.dst_port != 0 && rule.dst_port != ntohs(tcp->dest)) {
                    continue;
                }
            }

            // Rule matched
            return rule.action;
        }

        // No rules matched - default action
        return default_action_;
    }

    void set_default_action(Action action) {
        default_action_ = action;
    }

private:
    std::vector<Rule> rules_;
    mutable std::mutex rules_mutex_;
    Action default_action_ = Action::DROP;
};

class PacketForwarder {
public:
    PacketForwarder(int socket_fd) : socket_fd_(socket_fd) {}

    bool forward(const uint8_t* packet, size_t len, uint32_t new_dst_ip) {
        if (len < sizeof(iphdr)) return false;

        // Create a copy of the packet to modify
        std::vector<uint8_t> modified_packet(packet, packet + len);
        iphdr* ip = reinterpret_cast<iphdr*>(modified_packet.data());

        // Update destination IP
        ip->daddr = new_dst_ip;

        // Recalculate checksum
        ip->check = 0;
        ip->check = calculate_ip_checksum(ip);

        // Send the packet
        sockaddr_in dest_addr{};
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_addr.s_addr = new_dst_ip;

        ssize_t sent = sendto(socket_fd_, modified_packet.data(), modified_packet.size(),
                             0, reinterpret_cast<sockaddr*>(&dest_addr), sizeof(dest_addr));

        return sent == static_cast<ssize_t>(modified_packet.size());
    }

private:
    int socket_fd_;

    uint16_t calculate_ip_checksum(const iphdr* ip) {
        uint32_t sum = 0;
        const uint16_t* ptr = reinterpret_cast<const uint16_t*>(ip);

        for (int i = 0; i < ip->ihl * 2; ++i) {
            sum += ntohs(*ptr++);
        }

        while (sum >> 16) {
            sum = (sum & 0xFFFF) + (sum >> 16);
        }

        return static_cast<uint16_t>(~sum);
    }
};

class LowLatencyNetworkService {
public:
    LowLatencyNetworkService() : running_(false), socket_fd_(-1) {}

    ~LowLatencyNetworkService() {
        stop();
    }

    bool initialize(const std::string& interface, uint16_t port = 0) {
        // Create raw socket
        socket_fd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (socket_fd_ < 0) {
            std::cerr << "Failed to create socket: " << strerror(errno) << std::endl;
            return false;
        }

        // Set socket to non-blocking
        int flags = fcntl(socket_fd_, F_GETFL, 0);
        if (flags == -1 || fcntl(socket_fd_, F_SETFL, flags | O_NONBLOCK) == -1) {
            std::cerr << "Failed to set socket to non-blocking: " << strerror(errno) << std::endl;
            close(socket_fd_);
            socket_fd_ = -1;
            return false;
        }

        // Bind to interface
        ifreq ifr{};
        strncpy(ifr.ifr_name, interface.c_str(), IFNAMSIZ - 1);

        if (setsockopt(socket_fd_, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0) {
            std::cerr << "Failed to bind to interface: " << strerror(errno) << std::endl;
            close(socket_fd_);
            socket_fd_ = -1;
            return false;
        }

        // Initialize forwarder
        forwarder_ = std::make_unique<PacketForwarder>(socket_fd_);

        return true;
    }

    void add_filter_rule(const PacketFilter::Rule& rule) {
        filter_.add_rule(rule);
    }

    void set_default_filter_action(PacketFilter::Action action) {
        filter_.set_default_action(action);
    }

    bool start() {
        if (running_) return true;
        if (socket_fd_ < 0) return false;

        running_ = true;
        worker_thread_ = std::thread(&LowLatencyNetworkService::process_packets, this);

        return true;
    }

    void stop() {
        if (!running_) return;

        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }

        if (socket_fd_ >= 0) {
            close(socket_fd_);
            socket_fd_ = -1;
        }
    }

private:
    void process_packets() {
        const size_t buffer_size = 65536;
        std::vector<uint8_t> buffer(buffer_size);

        while (running_) {
            pollfd fds[1];
            fds[0].fd = socket_fd_;
            fds[0].events = POLLIN;

            int ret = poll(fds, 1, 10); // 10ms timeout
            if (ret <= 0) continue;

            if (fds[0].revents & POLLIN) {
                sockaddr_ll src_addr{};
                socklen_t addr_len = sizeof(src_addr);

                ssize_t received = recvfrom(socket_fd_, buffer.data(), buffer_size,
                                           0, reinterpret_cast<sockaddr*>(&src_addr), &addr_len);

                if (received <= 0) continue;

                // Process the packet
                auto action = filter_.evaluate(buffer.data(), received);

                switch (action) {
                    case PacketFilter::Action::DROP:
                        // Do nothing
                        break;

                    case PacketFilter::Action::FORWARD: {
                        // Forward to default destination (original destination)
                        const iphdr* ip = reinterpret_cast<const iphdr*>(buffer.data());
                        forwarder_->forward(buffer.data(), received, ip->daddr);
                        break;
                    }

                    case PacketFilter::Action::MODIFY: {
                        // Forward to modified destination
                        // Note: In a real implementation, we'd need to track the new destination
                        // from the filter rule that matched
                        const iphdr* ip = reinterpret_cast<const iphdr*>(buffer.data());
                        forwarder_->forward(buffer.data(), received, ip->daddr);
                        break;
                    }
                }
            }
        }
    }

    std::atomic<bool> running_;
    int socket_fd_;
    std::thread worker_thread_;
    PacketFilter filter_;
    std::unique_ptr<PacketForwarder> forwarder_;
};

