### 4. Main Network Service

```cpp
class LowLatencyNetworkService {
public:
    LowLatencyNetworkService() : running_(false) {}

    void start() {
        if (running_) return;

        running_ = true;
        worker_thread_ = std::thread([this]() { this->run(); });
    }

    void stop() {
        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void add_filter(PacketFilter::FilterFunc filter) {
        filter_engine_.add_filter(std::move(filter));
    }

    void add_forwarder(PacketForwarder::ForwardFunc forwarder) {
        forwarder_engine_.add_forwarder(std::move(forwarder));
    }

    void process_packet(Packet&& packet) {
        packet_queue_.push(std::move(packet));
    }

private:
    void run() {
        while (running_) {
            while (!packet_queue_.empty()) {
                auto packet = packet_queue_.pop();

                if (filter_engine_.should_forward(packet)) {
                    forwarder_engine_.forward(std::move(packet));
                }
            }

            // Yield CPU to avoid busy waiting
            std::this_thread::yield();
        }
    }

    PacketFilter filter_engine_;
    PacketForwarder forwarder_engine_;
    LockFreeQueue<Packet> packet_queue_;
    std::atomic<bool> running_;
    std::thread worker_thread_;
};
