### 5. Lock-Free Queue Implementation

```cpp
template<typename T>
class LockFreeQueue {
public:
    LockFreeQueue() : head_(new Node), tail_(head_.load()) {}

    void push(T&& item) {
        auto new_node = std::make_shared<Node>(std::move(item));

        Node* old_tail = tail_.load();
        while (!tail_.compare_exchange_weak(old_tail, new_node.get())) {
            // Retry if CAS fails
        }

        old_tail->next.store(new_node.get());
    }

    std::optional<T> pop() {
        Node* old_head = head_.load();
        Node* next_node = old_head->next.load();

        if (next_node == nullptr) {
            return std::nullopt;
        }

        if (head_.compare_exchange_strong(old_head, next_node)) {
            return std::move(next_node->value);
        }

        return std::nullopt;
    }

    bool empty() const {
        return head_.load()->next.load() == nullptr;
    }

private:
    struct Node {
        T value;
        std::atomic<Node*> next = nullptr;

        Node() = default;
        explicit Node(T&& v) : value(std::move(v)) {}
    };

    std::atomic<Node*> head_;
    std::atomic<Node*> tail_;
};
```

