    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(config.interface);
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Packet filtering function
bool filter_packet(const uint8_t* packet, size_t len) {
    // Check minimum packet size (Ethernet header)
    if (len < sizeof(struct ethhdr)) {
        return false;
    }

    // Check for IPv4 packets
    struct ethhdr* eth = (struct ethhdr*)packet;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return false;
    }

    // Check for minimum IP header size
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
        return false;
    }

    struct iphdr* ip = (struct iphdr*)(packet + sizeof(struct ethhdr));

    // Filter by source IP if configured
    if (config.filter_ip != 0 && ip->saddr != config.filter_ip) {
        return false;
    }

    // Check for TCP or UDP packets
    if (ip->protocol == IPPROTO_TCP) {
        if (len < sizeof(struct ethhdr) + sizeof(struct iphdr) + sizeof(struct tcphdr)) {
            return false;
        }
        struct tcphdr* tcp = (struct tcphdr*)(packet + sizeof(struct ethhdr) + sizeof(struct iphdr));
        if (config.filter_port != 0 && ntohs(tcp->source) != config.filter_port) {
            return false;
        }
    } else if (ip->protocol == IPPROTO_UDP) {
        if (len < sizeof(struct ethhdr) + sizeof(struct iphdr) + sizeof(struct udphdr)) {
            return false;
        }
        struct udphdr* udp = (struct udphdr*)(packet + sizeof(struct ethhdr) + sizeof(struct iphdr));
        if (config.filter_port != 0 && ntohs(udp->source) != config.filter_port) {
            return false;
        }
    } else {
        // Not TCP or UDP - skip
        return false;
    }

    return true;
}

// Packet forwarding function
void forward_packet(int sockfd, const uint8_t* packet, size_t len) {
    if (!config.forward || !config.forward_dest || config.forward_port == 0) {
        return;
    }

    // Create a new socket for forwarding
    int forward_sock = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (forward_sock < 0) {
        perror("forward socket");
        return;
    }

    // Set IP_HDRINCL to include our own IP header
    int one = 1;
    if (setsockopt(forward_sock, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        perror("setsockopt IP_HDRINCL");
        close(forward_sock);
        return;
    }

    // Create destination address
    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(config.forward_port);
    if (inet_pton(AF_INET, config.forward_dest, &dest_addr.sin_addr) != 1) {
        perror("inet_pton");
        close(forward_sock);
        return;
    }

    // Send the packet
    if (sendto(forward_sock, packet, len, 0, (struct sockaddr*)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto");
    }

    close(forward_sock);
    stats.packets_forwarded++;
}

// Packet processing thread
void* packet_processor(void* arg) {
    int sockfd = *(int*)arg;
    uint8_t buffer[65536]; // Maximum Ethernet frame size

    while (running) {
        ssize_t len = recvfrom(sockfd, buffer, sizeof(buffer), 0, NULL, NULL);
        if (len < 0) {
            if (running) {
                perror("recvfrom");
            }
            continue;
        }

        stats.packets_received++;
        stats.bytes_processed += len;

        if (filter_packet(buffer, len)) {
            stats.packets_filtered++;
            forward_packet(sockfd, buffer, len);
        }
    }

    return NULL;
}

// Statistics thread
void* stats_thread(void* arg) {
    while (running) {
        sleep(1);
        printf("Stats - Received: %lu, Filtered: %lu, Forwarded: %lu, Bytes: %lu\n",
               stats.packets_received, stats.packets_filtered,
               stats.packets_forwarded, stats.bytes_processed);
    }
    return NULL;
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    running = false;
}

int main(int argc, char* argv[]) {
    // Parse command line arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [options]\n", argv[0]);
        fprintf(stderr, "Options:\n");
        fprintf(stderr, "  -p <port>       Filter by source port\n");
        fprintf(stderr, "  -i <ip>         Filter by source IP\n");
        fprintf(stderr, "  -f              Enable forwarding\n");
        fprintf(stderr, "  -d <ip>         Forward destination IP\n");
        fprintf(stderr, "  -P <port>       Forward destination port\n");
        fprintf(stderr, "  --promiscuous   Enable promiscuous mode\n");
        return 1;
    }

    // Initialize default configuration
    config.interface = argv[1];
    config.promiscuous = false;
    config.filter_port = 0;
    config.filter_ip = 0;
    config.forward = false;
    config.forward_dest = NULL;
    config.forward_port = 0;

    // Parse additional arguments
    for (int i = 2; i < argc; i++) {
        if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            config.filter_port = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            inet_pton(AF_INET, argv[++i], &config.filter_ip);
        } else if (strcmp(argv[i], "--promiscuous") == 0) {
            config.promiscuous = true;
        } else if (strcmp(argv[i], "-f") == 0) {
            config.forward = true;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            config.forward_dest = argv[++i];
        } else if (strcmp(argv[i], "-P") == 0 && i + 1 < argc) {
            config.forward_port = atoi(argv[++i]);
        }
    }

    // Initialize network interface
    int sockfd = init_interface();
    if (sockfd < 0) {
        return 1;
    }

    // Set up signal handler for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create processing thread
    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, packet_processor, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return 1;
    }

    // Create statistics thread
    pthread_t stats_thread_id;
    if (pthread_create(&stats_thread_id, NULL, stats_thread, NULL) != 0) {
        perror("pthread_create");
        running = false;
        pthread_join(processor_thread, NULL);
        close(sockfd);
        return 1;
    }

    // Wait for shutdown
    pthread_join(processor_thread, NULL);
    pthread_join(stats_thread_id, NULL);

    // Clean up
    close(sockfd);
    printf("Service stopped. Final stats:\n");
    printf("Received: %lu, Filtered: %lu, Forwarded: %lu, Bytes: %lu\n",
           stats.packets_received, stats.packets_filtered,
           stats.packets_forwarded, stats.bytes_processed);

    return 0;
}
