class BasicIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
    uint16_t allowedPort = 0;

public:
    BasicIPFilter() = default;

    void addAllowedIP(uint32_t ip) {
        allowedIPs[ip] = true;
    }

    void setAllowedPort(uint16_t port) {
        allowedPort = port;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);

        // Check IP version and length
        if (ip->version != 4 || len < (ip->ihl * 4)) return false;

        // Check if source IP is allowed
        if (!allowedIPs.empty() && allowedIPs.find(ip->saddr) == allowedIPs.end()) {
            return false;
        }

        // Check protocol-specific rules
        switch (ip->protocol) {
            case IPPROTO_UDP: {
                if (len < sizeof(iphdr) + sizeof(udphdr)) return false;
                const udphdr* udp = reinterpret_cast<const udphdr*>(packet + ip->ihl * 4);
                if (allowedPort != 0 && ntohs(udp->dest) != allowedPort) {
                    return false;
                }
                break;
            }
            case IPPROTO_TCP: {
                if (len < sizeof(iphdr) + sizeof(tcphdr)) return false;
                const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + ip->ihl * 4);
                if (allowedPort != 0 && ntohs(tcp->dest) != allowedPort) {
                    return false;
                }
                break;
            }
            default:
                break;
        }

        return true;
    }
};

class PacketForwarder {
    int sockfd;
    std::string destinationIP;
    uint16_t destinationPort;
    sockaddr_in destAddr;

public:
    PacketForwarder(const std::string& ip, uint16_t port)
        : destinationIP(ip), destinationPort(port) {

        sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (sockfd < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(sockfd, F_GETFL, 0);
        fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

        // Set destination address
        memset(&destAddr, 0, sizeof(destAddr));
        destAddr.sin_family = AF_INET;
        destAddr.sin_port = htons(port);
        if (inet_pton(AF_INET, ip.c_str(), &destAddr.sin_addr) <= 0) {
            perror("inet_pton");
            throw std::runtime_error("Invalid destination IP");
        }
    }

    ~PacketForwarder() {
        if (sockfd >= 0) {
            close(sockfd);
        }
    }

    bool forwardPacket(const uint8_t* packet, size_t len) {
        ssize_t sent = sendto(sockfd, packet, len, 0,
                             reinterpret_cast<sockaddr*>(&destAddr),
                             sizeof(destAddr));

        if (sent < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("sendto");
            }
            return false;
        }

        return sent == static_cast<ssize_t>(len);
    }
};

class LowLatencyNetworkService {
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;
    std::mutex mtx;
    std::condition_variable cv;

    int captureSocket;
    std::vector<uint8_t> packetBuffer;

public:
    LowLatencyNetworkService(const std::string& forwardIP, uint16_t forwardPort)
        : forwarder(std::make_unique<PacketForwarder>(forwardIP, forwardPort)) {

        // Create raw socket for packet capture
        captureSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (captureSocket < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create capture socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(captureSocket, F_GETFL, 0);
        fcntl(captureSocket, F_SETFL, flags | O_NONBLOCK);

        // Allocate buffer for packets (MTU size)
        packetBuffer.resize(1500);
    }

    ~LowLatencyNetworkService() {
        stop();
        if (captureSocket >= 0) {
            close(captureSocket);
        }
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(std::move(filter));
    }

    void start() {
        if (running.exchange(true)) {
            return;
        }

        workerThread = std::thread([this]() {
            processPackets();
        });
    }

    void stop() {
        if (!running.exchange(false)) {
            return;
        }

        cv.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void processPackets() {
        pollfd fds[1];
        fds[0].fd = captureSocket;
        fds[0].events = POLLIN;

        while (running) {
            int ret = poll(fds, 1, 10); // 10ms timeout

            if (ret < 0) {
                if (errno == EINTR) continue;
                perror("poll");
                break;
            }

            if (ret == 0) continue; // Timeout

            if (fds[0].revents & POLLIN) {
                ssize_t len = recv(captureSocket, packetBuffer.data(), packetBuffer.size(), 0);
                if (len < 0) {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        perror("recv");
                    }
                    continue;
                }

                // Skip link layer headers (assuming Ethernet)
                const uint8_t* ipPacket = packetBuffer.data() + 14;
                size_t ipLen = len - 14;

                if (ipLen < sizeof(iphdr)) continue;

                // Apply filters
                bool shouldForward = true;
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    for (const auto& filter : filters) {
                        if (!filter->shouldForward(ipPacket, ipLen)) {
                            shouldForward = false;
                            break;
                        }
                    }
                }

                if (shouldForward) {
                    forwarder->forwardPacket(ipPacket, ipLen);
                }
            }
        }
    }
};

