class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
    virtual ~PacketFilter() = default;
};

class SimplePortFilter : public PacketFilter {
    uint16_t port_;
public:
    SimplePortFilter(uint16_t port) : port_(port) {}

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr) + sizeof(udphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        if (ip->protocol != IPPROTO_UDP) return false;

        const udphdr* udp = reinterpret_cast<const udphdr*>(packet + (ip->ihl << 2));
        return ntohs(udp->dest) == port_;
    }
};

class PacketForwarder {
    int sockfd_;
    std::unordered_map<std::string, int> interfaceSockets_;
    std::vector<std::unique_ptr<PacketFilter>> filters_;
    std::atomic<bool> running_;
    std::mutex filterMutex_;

public:
    PacketForwarder() : sockfd_(-1), running_(false) {}

    ~PacketForwarder() {
        stop();
        if (sockfd_ != -1) close(sockfd_);
        for (auto& [iface, fd] : interfaceSockets_) {
            close(fd);
        }
    }

    bool initialize() {
        // Create raw socket for packet capture
        sockfd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sockfd_ == -1) {
            perror("socket");
            return false;
        }

        // Set socket to non-blocking
        int flags = fcntl(sockfd_, F_GETFL, 0);
        fcntl(sockfd_, F_SETFL, flags | O_NONBLOCK);

        return true;
    }

    bool addInterface(const std::string& iface) {
        int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (fd == -1) {
            perror("socket");
            return false;
        }

        // Bind to specific interface
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex(iface.c_str());
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(fd, (struct sockaddr*)&sll, sizeof(sll)) == -1) {
            perror("bind");
            close(fd);
            return false;
        }

        // Set to non-blocking
        int flags = fcntl(fd, F_GETFL, 0);
        fcntl(fd, F_SETFL, flags | O_NONBLOCK);

        interfaceSockets_[iface] = fd;
        return true;
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(filterMutex_);
        filters_.push_back(std::move(filter));
    }

    bool start() {
        if (sockfd_ == -1) return false;

        running_ = true;

        // Main processing loop
        std::thread processingThread([this]() {
            const size_t bufferSize = 65536;
            uint8_t buffer[bufferSize];
            struct pollfd fds[interfaceSockets_.size() + 1];

            // Prepare poll fds
            fds[0].fd = sockfd_;
            fds[0].events = POLLIN;
            int i = 1;
            for (auto& [iface, fd] : interfaceSockets_) {
                fds[i].fd = fd;
                fds[i].events = POLLIN;
                i++;
            }

            while (running_) {
                int ret = poll(fds, interfaceSockets_.size() + 1, 100);
                if (ret <= 0) continue;

                for (int j = 0; j < interfaceSockets_.size() + 1; j++) {
                    if (fds[j].revents & POLLIN) {
                        ssize_t len = recv(fds[j].fd, buffer, bufferSize, 0);
                        if (len <= 0) continue;

                        // Process packet
                        processPacket(buffer, len);
                    }
                }
            }
        });

        processingThread.detach();
        return true;
    }

    void stop() {
        running_ = false;
    }

private:
    void processPacket(const uint8_t* packet, size_t len) {
        // Check filters
        bool shouldForward = false;
        {
            std::lock_guard<std::mutex> lock(filterMutex_);
            for (auto& filter : filters_) {
                if (filter->shouldForward(packet, len)) {
                    shouldForward = true;
                    break;
                }
            }
        }

        if (shouldForward) {
            // Forward packet to all interfaces (except source)
            for (auto& [iface, fd] : interfaceSockets_) {
                if (fd != sockfd_) {
                    send(fd, packet, len, 0);
                }
            }
        }
    }
};

int main() {
    PacketForwarder forwarder;

    if (!forwarder.initialize()) {
        std::cerr << "Failed to initialize forwarder" << std::endl;
        return 1;
    }

    // Add interfaces
    if (!forwarder.addInterface("eth0") || !forwarder.addInterface("eth1")) {
        std::cerr << "Failed to add interfaces" << std::endl;
        return 1;
    }

    // Add filters (e.g., forward only UDP packets to port 5000)
    forwarder.addFilter(std::make_unique<SimplePortFilter>(5000));

    // Start processing
    if (!forwarder.start()) {
        std::cerr << "Failed to start forwarder" << std::endl;
        return 1;
    }

    std::cout << "Forwarder running. Press Enter to stop..." << std::endl;
    std::cin.get();

    forwarder.stop();
    return 0;
}
