    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowedIPs[addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end();
    }
};

class PacketForwarder {
    int socket_fd;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::atomic<bool> running{false};
    std::thread worker_thread;

public:
    PacketForwarder(int sock_fd) : socket_fd(sock_fd) {}

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    void start() {
        running = true;
        worker_thread = std::thread([this]() { this->run(); });
    }

    void stop() {
        running = false;
        if (worker_thread.joinable()) {
            worker_thread.join();
        }
    }

    void run() {
        const size_t buffer_size = 65536;
        std::vector<uint8_t> buffer(buffer_size);

        while (running) {
            ssize_t bytes_received = recv(socket_fd, buffer.data(), buffer_size, 0);
            if (bytes_received <= 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    std::this_thread::sleep_for(std::chrono::microseconds(10));
                    continue;
                }
                break;
            }

            bool should_forward = true;
            for (const auto& filter : filters) {
                if (!filter->shouldForward(buffer.data(), bytes_received)) {
                    should_forward = false;
                    break;
                }
            }

            if (should_forward) {
                // In a real implementation, we would forward to another interface
                // For this example, we'll just print the packet info
                processPacket(buffer.data(), bytes_received);
            }
        }
    }

    void processPacket(const uint8_t* packet, size_t length) {
        if (length < sizeof(iphdr)) return;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(ip->saddr), src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &(ip->daddr), dst_ip, INET_ADDRSTRLEN);

        std::cout << "Forwarding packet: "
                  << "Src: " << src_ip << ", "
                  << "Dst: " << dst_ip << ", "
                  << "Proto: " << static_cast<int>(ip->protocol) << ", "
                  << "Len: " << length << " bytes\n";
    }
};

int main() {
