    int sock_fd;            // Raw socket file descriptor
    int* stop_flag;         // Pointer to stop flag
    NetworkConfig* config;  // Configuration
} PacketContext;

// Rule structure for packet filtering
typedef struct {
    uint32_t src_ip;        // Source IP (0 = any)
    uint32_t dst_ip;        // Destination IP (0 = any)
    uint16_t src_port;      // Source port (0 = any)
    uint16_t dst_port;      // Destination port (0 = any)
    uint8_t protocol;       // Protocol (0 = any)
    int action;             // 0 = drop, 1 = forward
} FilterRule;

// Global filter rules (simplified for this example)
FilterRule filter_rules[100];
int rule_count = 0;

// Function to add a filter rule
void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t protocol, int action) {
    if (rule_count >= 100) return;

    filter_rules[rule_count].src_ip = src_ip;
    filter_rules[rule_count].dst_ip = dst_ip;
    filter_rules[rule_count].src_port = src_port;
    filter_rules[rule_count].dst_port = dst_port;
    filter_rules[rule_count].protocol = protocol;
    filter_rules[rule_count].action = action;
    rule_count++;
}

// Function to check if packet matches any rule
int should_forward(const struct iphdr* iph, const void* transport_header) {
    for (int i = 0; i < rule_count; i++) {
        FilterRule* rule = &filter_rules[i];

        // Check protocol
        if (rule->protocol != 0 && rule->protocol != iph->protocol) {
            continue;
        }

        // Check source IP
        if (rule->src_ip != 0 && rule->src_ip != iph->saddr) {
            continue;
        }

        // Check destination IP
        if (rule->dst_ip != 0 && rule->dst_ip != iph->daddr) {
            continue;
        }

        // Check transport layer (TCP/UDP)
        if (iph->protocol == IPPROTO_TCP || iph->protocol == IPPROTO_UDP) {
            const struct tcphdr* tcp = (const struct tcphdr*)transport_header;
            const struct udphdr* udp = (const struct udphdr*)transport_header;

            if (rule->src_port != 0) {
                if (iph->protocol == IPPROTO_TCP && rule->src_port != ntohs(tcp->source)) {
                    continue;
                }
                if (iph->protocol == IPPROTO_UDP && rule->src_port != ntohs(udp->source)) {
                    continue;
                }
            }

            if (rule->dst_port != 0) {
                if (iph->protocol == IPPROTO_TCP && rule->dst_port != ntohs(tcp->dest)) {
                    continue;
                }
                if (iph->protocol == IPPROTO_UDP && rule->dst_port != ntohs(udp->dest)) {
                    continue;
                }
            }
        }

        // If we get here, the rule matches
        return rule->action;
    }

    // Default action if no rules match
    return 1; // Forward by default
}

// Packet processing function
void* process_packet(void* arg) {
    PacketContext* ctx = (PacketContext*)arg;
    NetworkConfig* config = ctx->config;
    int sock_fd = ctx->sock_fd;
    int* stop_flag = ctx->stop_flag;

    char buffer[config->max_packet_size];
    struct sockaddr_ll src_addr;
    socklen_t addr_len = sizeof(src_addr);

