    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, 1); // Forward HTTPS traffic
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, 0); // Drop all ICMP

    // Create worker threads
    int stop_flag = 0;
    pthread_t threads[config.worker_threads];
    PacketContext contexts[config.worker_threads];

    for (int i = 0; i < config.worker_threads; i++) {
        contexts[i].sock_fd = sock_fd;
        contexts[i].stop_flag = &stop_flag;
        contexts[i].config = &config;

        if (pthread_create(&threads[i], NULL, process_packet, &contexts[i]) != 0) {
            perror("pthread_create");
            stop_flag = 1;
            break;
        }
    }

    // Main loop - just wait for termination signal
    printf("Ultra-low-latency networking service running on %s\n", config.interface);
    printf("Press Enter to stop...\n");
    getchar();

    // Signal threads to stop
    stop_flag = 1;

    // Wait for threads to finish
    for (int i = 0; i < config.worker_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    close(sock_fd);

    return 0;
}
