class PacketFilter {
public:
    enum class Action { DROP, FORWARD, MODIFY };

    struct Rule {
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint32_t src_ip = 0;
        uint32_t dst_ip = 0;
        uint8_t protocol = 0; // 0 = any, 6 = TCP, 17 = UDP
        Action action = Action::DROP;
        uint32_t new_dst_ip = 0; // For MODIFY action
    };

    void add_rule(const Rule& rule) {
        std::lock_guard<std::mutex> lock(rules_mutex_);
        rules_.push_back(rule);
    }

    Action evaluate(const uint8_t* packet, size_t len) {
        if (len < sizeof(iphdr)) return Action::DROP;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        uint16_t ip_len = ntohs(ip->tot_len);

        if (len < ip_len) return Action::DROP;

        // Check rules in reverse order (last added has priority)
        for (auto it = rules_.rbegin(); it != rules_.rend(); ++it) {
            const Rule& rule = *it;

            // Check protocol if specified
            if (rule.protocol != 0 && rule.protocol != ip->protocol) continue;

            // Check source IP if specified
            if (rule.src_ip != 0 && rule.src_ip != ip->saddr) continue;

            // Check destination IP if specified
            if (rule.dst_ip != 0 && rule.dst_ip != ip->daddr) continue;

            // Check transport layer ports if applicable
            if (ip->protocol == IPPROTO_TCP || ip->protocol == IPPROTO_UDP) {
                if (len < sizeof(iphdr) + sizeof(tcphdr)) continue;

                const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + sizeof(iphdr));

                if (rule.src_port != 0 && rule.src_port != ntohs(tcp->source)) continue;
                if (rule.dst_port != 0 && rule.dst_port != ntohs(tcp->dest)) continue;
            }

            // Rule matched
            return rule.action;
        }

        return Action::DROP; // Default action if no rules match
    }

private:
    std::vector<Rule> rules_;
    std::mutex rules_mutex_;
};

class PacketForwarder {
public:
    PacketForwarder(int output_fd) : output_fd_(output_fd) {}

    bool forward(const uint8_t* packet, size_t len) {
        if (output_fd_ < 0) return false;

        ssize_t sent = send(output_fd_, packet, len, MSG_DONTWAIT);
        return sent == static_cast<ssize_t>(len);
    }

    bool modify_and_forward(uint8_t* packet, size_t len, uint32_t new_dst_ip) {
        if (output_fd_ < 0 || len < sizeof(iphdr)) return false;

        iphdr* ip = reinterpret_cast<iphdr*>(packet);
        ip->daddr = new_dst_ip;

        // Recalculate checksum
        ip->check = 0;
        ip->check = ip_checksum(ip);

        return forward(packet, len);
    }

private:
    int output_fd_;

    uint16_t ip_checksum(const void* data, size_t len) {
        const uint16_t* buf = static_cast<const uint16_t*>(data);
        uint32_t sum = 0;

        while (len > 1) {
            sum += *buf++;
            len -= 2;
        }

        if (len == 1) {
            sum += *(reinterpret_cast<const uint8_t*>(buf));
        }

        sum = (sum >> 16) + (sum & 0xFFFF);
        sum += (sum >> 16);

        return static_cast<uint16_t>(~sum);
    }
};

class NetworkService {
public:
    NetworkService(int input_fd, int output_fd)
        : input_fd_(input_fd),
          output_fd_(output_fd),
          forwarder_(output_fd),
          running_(false) {}

    void add_filter_rule(const PacketFilter::Rule& rule) {
        filter_.add_rule(rule);
    }

    void start() {
        running_ = true;
        worker_thread_ = std::thread(&NetworkService::process_packets, this);
    }

    void stop() {
        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

private:
    void process_packets() {
        const size_t buffer_size = 65536; // Jumbo frame size
        std::vector<uint8_t> buffer(buffer_size);
        pollfd fds[1] = {{input_fd_, POLLIN, 0}};

        while (running_) {
            int ret = poll(fds, 1, 100); // 100ms timeout

            if (ret <= 0) continue; // Timeout or error

            if (fds[0].revents & POLLIN) {
                ssize_t len = recv(input_fd_, buffer.data(), buffer_size, MSG_DONTWAIT);

                if (len <= 0) {
                    if (len == 0 || errno != EAGAIN) {
                        std::cerr << "Error receiving packet: " << strerror(errno) << std::endl;
                        break;
                    }
                    continue;
                }

                auto action = filter_.evaluate(buffer.data(), len);

                switch (action) {
                    case PacketFilter::Action::FORWARD:
                        forwarder_.forward(buffer.data(), len);
                        break;
                    case PacketFilter::Action::MODIFY:
                        // In a real implementation, we'd need to know which rule matched
                        // For simplicity, we'll assume the last rule with MODIFY action
                        // would have the new_dst_ip set
                        forwarder_.modify_and_forward(buffer.data(), len, 0); // Replace 0 with actual new IP
                        break;
                    case PacketFilter::Action::DROP:
                    default:
                        break; // Do nothing
                }
            }
        }
    }

    int input_fd_;
    int output_fd_;
    PacketFilter filter_;
    PacketForwarder forwarder_;
    std::thread worker_thread_;
    std::atomic<bool> running_;
};

