constexpr size_t MAX_PACKET_SIZE = 1500;
constexpr size_t RING_BUFFER_SIZE = 4096;
constexpr int MAX_FILTER_RULES = 1024;

// Packet structure
struct Packet {
    uint8_t data[MAX_PACKET_SIZE];
    size_t length;
    struct sockaddr_in src_addr;
    struct sockaddr_in dst_addr;
    uint64_t timestamp;
};

// Filter rule structure
struct FilterRule {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
};

// Ring buffer implementation
class RingBuffer {
private:
    std::vector<Packet> buffer;
    std::atomic<size_t> head;
    std::atomic<size_t> tail;
    size_t capacity;

public:
    RingBuffer(size_t size) : buffer(size), capacity(size), head(0), tail(0) {}

    bool push(const Packet& packet) {
        size_t current_tail = tail.load(std::memory_order_relaxed);
        size_t next_tail = (current_tail + 1) % capacity;

        if (next_tail == head.load(std::memory_order_acquire)) {
            return false; // Buffer full
        }

        buffer[current_tail] = packet;
        tail.store(next_tail, std::memory_order_release);
        return true;
    }

    bool pop(Packet& packet) {
        size_t current_head = head.load(std::memory_order_relaxed);

        if (current_head == tail.load(std::memory_order_acquire)) {
            return false; // Buffer empty
        }

        packet = buffer[current_head];
        head.store((current_head + 1) % capacity, std::memory_order_release);
        return true;
    }

    bool is_empty() const {
        return head.load(std::memory_order_acquire) == tail.load(std::memory_order_acquire);
    }
};

// Packet processor class
class PacketProcessor {
private:
    std::vector<FilterRule> filter_rules;
    int output_socket;
    RingBuffer& input_buffer;
    std::atomic<bool> running;

public:
    PacketProcessor(RingBuffer& buffer, int sock)
        : input_buffer(buffer), output_socket(sock), running(false) {}

    void add_filter_rule(const FilterRule& rule) {
        if (filter_rules.size() < MAX_FILTER_RULES) {
            filter_rules.push_back(rule);
        }
    }

    bool should_forward(const Packet& packet) {
        const iphdr* ip_header = reinterpret_cast<const iphdr*>(packet.data);
        if (ip_header->version != 4) return false; // Only IPv4 for simplicity

        uint16_t protocol = ip_header->protocol;
        uint32_t src_ip = ip_header->saddr;
        uint32_t dst_ip = ip_header->daddr;

        uint16_t src_port = 0, dst_port = 0;

        if (protocol == IPPROTO_TCP) {
            const tcphdr* tcp_header = reinterpret_cast<const tcphdr*>(
                packet.data + (ip_header->ihl * 4));
            src_port = ntohs(tcp_header->source);
            dst_port = ntohs(tcp_header->dest);
        } else if (protocol == IPPROTO_UDP) {
            const udphdr* udp_header = reinterpret_cast<const udphdr*>(
                packet.data + (ip_header->ihl * 4));
            src_port = ntohs(udp_header->source);
            dst_port = ntohs(udp_header->dest);
        }

        // Check filter rules
        for (const auto& rule : filter_rules) {
            if ((rule.src_ip == 0 || rule.src_ip == src_ip) &&
                (rule.dst_ip == 0 || rule.dst_ip == dst_ip) &&
                (rule.src_port == 0 || rule.src_port == src_port) &&
                (rule.dst_port == 0 || rule.dst_port == dst_port) &&
                (rule.protocol == 0 || rule.protocol == protocol)) {
                return rule.allow;
            }
        }

        // Default deny if no matching rule
        return false;
    }

    void process_packets() {
        running = true;
        Packet packet;

        while (running.load(std::memory_order_relaxed)) {
            if (input_buffer.pop(packet)) {
                if (should_forward(packet)) {
                    // Forward the packet
                    sendto(output_socket, packet.data, packet.length, 0,
                          (struct sockaddr*)&packet.dst_addr, sizeof(packet.dst_addr));
                }
            } else {
                // Small sleep to prevent busy waiting
                std::this_thread::sleep_for(std::chrono::microseconds(10));
            }
        }
    }

    void stop() {
        running = false;
    }
};

