        output_socket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);

        // Set sockets to non-blocking
        fcntl(input_socket, F_SETFL, O_NONBLOCK);
        fcntl(output_socket, F_SETFL, O_NONBLOCK);

        processor = std::make_unique<PacketProcessor>(input_buffer, output_socket);
    }

    void add_filter_rule(const FilterRule& rule) {
        processor->add_filter_rule(rule);
    }

    void start() {
        processing_thread = std::thread(&PacketProcessor::process_packets, processor.get());

        // Main receive loop
        Packet packet;
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        while (true) {
            packet.length = recvfrom(input_socket, packet.data, MAX_PACKET_SIZE, 0,
                                   (struct sockaddr*)&client_addr, &client_len);

            if (packet.length > 0) {
                packet.src_addr = client_addr;
                packet.timestamp = std::chrono::duration_cast<std::chrono::nanoseconds>(
                    std::chrono::system_clock::now().time_since_epoch()).count();

                // Try to push to ring buffer
                while (!input_buffer.push(packet)) {
                    // Buffer full - wait briefly
                    std::this_thread::sleep_for(std::chrono::microseconds(1));
                }
            }
        }
    }

    void stop() {
        processor->stop();
        if (processing_thread.joinable()) {
            processing_thread.join();
        }
        close(input_socket);
        close(output_socket);
    }

    ~NetworkService() {
        stop();
    }
};

