### 1. Packet Processing Engine

```cpp
#include <vector>
#include <unordered_map>
#include <memory>
#include <functional>
#include <atomic>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>

class PacketProcessor {
public:
    using FilterFunc = std::function<bool(const void* packet, size_t len)>;
    using ForwardFunc = std::function<void(const void* packet, size_t len)>;

    PacketProcessor(size_t buffer_size = 16384)
        : running_(false), buffer_size_(buffer_size) {}

    ~PacketProcessor() {
        stop();
    }

    void add_filter(const std::string& name, FilterFunc filter) {
        std::lock_guard<std::mutex> lock(filters_mutex_);
        filters_[name] = std::move(filter);
    }

    void remove_filter(const std::string& name) {
        std::lock_guard<std::mutex> lock(filters_mutex_);
        filters_.erase(name);
    }

    void set_forwarder(ForwardFunc forwarder) {
        forwarder_ = std::move(forwarder);
    }

    void start() {
        if (running_) return;

        running_ = true;
        worker_thread_ = std::thread([this]() { this->process_packets(); });
    }

    void stop() {
        if (!running_) return;

        running_ = false;
        cv_.notify_all();
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void enqueue_packet(const void* packet, size_t len) {
        if (!running_) return;

        std::lock_guard<std::mutex> lock(queue_mutex_);
        packet_queue_.emplace_back(static_cast<const uint8_t*>(packet),
                                  static_cast<const uint8_t*>(packet) + len);
        cv_.notify_one();
    }

private:
    void process_packets() {
        while (running_) {
            std::vector<uint8_t> packet;

            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                cv_.wait(lock, [this]() { return !packet_queue_.empty() || !running_; });

                if (!running_) break;

                if (!packet_queue_.empty()) {
                    packet = std::move(packet_queue_.front());
                    packet_queue_.pop_front();
                }
            }

            if (!packet.empty()) {
                process_single_packet(packet.data(), packet.size());
            }
        }
    }

    void process_single_packet(const void* packet, size_t len) {
        // Apply all filters
        bool should_forward = true;

        {
            std::lock_guard<std::mutex> lock(filters_mutex_);
            for (const auto& [name, filter] : filters_) {
                if (!filter(packet, len)) {
                    should_forward = false;
                    break;
                }
            }
        }

        // Forward if all filters passed
        if (should_forward && forwarder_) {
            forwarder_(packet, len);
        }
    }

    std::atomic<bool> running_;
    std::thread worker_thread_;
    std::mutex queue_mutex_;
    std::mutex filters_mutex_;
    std::condition_variable cv_;
    std::deque<std::vector<uint8_t>> packet_queue_;
    std::unordered_map<std::string, FilterFunc> filters_;
    ForwardFunc forwarder_;
    size_t buffer_size_;
};
```

### 2. Network Interface Wrapper

```cpp
class NetworkInterface {
public:
    NetworkInterface(const std::string& iface_name)
        : iface_name_(iface_name), sockfd_(-1) {}

    ~NetworkInterface() {
        if (sockfd_ >= 0) {
            close(sockfd_);
        }
    }

    bool initialize() {
        sockfd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sockfd_ < 0) {
            perror("socket");
            return false;
        }

        // Set interface
        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = if_nametoindex(iface_name_.c_str());
        if (sll.sll_ifindex == 0) {
            perror("if_nametoindex");
            return false;
        }

        if (bind(sockfd_, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            return false;
        }

        return true;
    }

    bool receive_packet(std::vector<uint8_t>& buffer) {
        buffer.resize(65536); // MTU size
        ssize_t len = recv(sockfd_, buffer.data(), buffer.size(), 0);
        if (len < 0) {
            perror("recv");
            return false;
        }
        buffer.resize(len);
        return true;
    }

    bool send_packet(const void* packet, size_t len) {
        if (send(sockfd_, packet, len, 0) < 0) {
            perror("send");
            return false;
        }
        return true;
    }

private:
    std::string iface_name_;
    int sockfd_;
};
