### 3. Main Service Implementation

```cpp
class LowLatencyNetworkService {
public:
    LowLatencyNetworkService(const std::string& iface_name)
        : iface_(iface_name), processor_() {}

    bool initialize() {
        if (!iface_.initialize()) {
            return false;
        }

        // Set up packet processor
        processor_.set_forwarder([this](const void* packet, size_t len) {
            iface_.send_packet(packet, len);
        });

        // Start processing thread
        processor_.start();

        // Start receive thread
        running_ = true;
        receive_thread_ = std::thread([this]() { this->receive_loop(); });

        return true;
    }

    void shutdown() {
        running_ = false;
        if (receive_thread_.joinable()) {
            receive_thread_.join();
        }
        processor_.stop();
    }

    void add_filter(const std::string& name, PacketProcessor::FilterFunc filter) {
        processor_.add_filter(name, filter);
    }

    void remove_filter(const std::string& name) {
        processor_.remove_filter(name);
    }

private:
    void receive_loop() {
        std::vector<uint8_t> buffer;

        while (running_) {
            if (iface_.receive_packet(buffer)) {
                processor_.enqueue_packet(buffer.data(), buffer.size());
            }
        }
    }

    NetworkInterface iface_;
    PacketProcessor processor_;
    std::thread receive_thread_;
    std::atomic<bool> running_;
};
