class IPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowedIPs[addr] = true;
    }

    bool shouldForward(const void* packet, size_t length) override {
        if (length < sizeof(iphdr)) return false;

        const iphdr* ip = static_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) {
        allowedPorts[port] = true;
    }

    bool shouldForward(const void* packet, size_t length) override {
        if (length < sizeof(iphdr) + sizeof(udphdr)) return false;

        const iphdr* ip = static_cast<const iphdr*>(packet);
        if (ip->protocol == IPPROTO_UDP) {
            const udphdr* udp = reinterpret_cast<const udphdr*>(static_cast<const char*>(packet) + (ip->ihl << 2));
            return allowedPorts.find(ntohs(udp->dest)) != allowedPorts.end();
        } else if (ip->protocol == IPPROTO_TCP) {
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(static_cast<const char*>(packet) + (ip->ihl << 2));
            return allowedPorts.find(ntohs(tcp->dest)) != allowedPorts.end();
        }
        return false;
    }
};

class PacketForwarder {
    int forwardSocket;
    std::string destinationIP;
    uint16_t destinationPort;

public:
    PacketForwarder(const std::string& destIP, uint16_t destPort)
        : destinationIP(destIP), destinationPort(destPort) {

        forwardSocket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (forwardSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(forwardSocket, F_GETFL, 0);
        fcntl(forwardSocket, F_SETFL, flags | O_NONBLOCK);
    }

    ~PacketForwarder() {
        if (forwardSocket >= 0) {
            close(forwardSocket);
        }
    }

    bool forwardPacket(const void* packet, size_t length) {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_port = htons(destinationPort);
        inet_pton(AF_INET, destinationIP.c_str(), &destAddr.sin_addr);

        ssize_t sent = sendto(forwardSocket, packet, length, 0,
                            reinterpret_cast<sockaddr*>(&destAddr), sizeof(destAddr));

        return sent == static_cast<ssize_t>(length);
    }
};

class NetworkService {
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;
    std::mutex mtx;
    std::condition_variable cv;

    int captureSocket;
    std::vector<char> packetBuffer;

public:
    NetworkService(const std::string& destIP, uint16_t destPort)
        : forwarder(std::make_unique<PacketForwarder>(destIP, destPort)) {

        // Create raw socket for packet capture
        captureSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (captureSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(captureSocket, F_GETFL, 0);
        fcntl(captureSocket, F_SETFL, flags | O_NONBLOCK);

        // Allocate buffer for packets (MTU size)
        packetBuffer.resize(1500);
    }

    ~NetworkService() {
        stop();
        if (captureSocket >= 0) {
            close(captureSocket);
        }
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(std::move(filter));
    }

    void start() {
        running = true;
        workerThread = std::thread([this]() { this->processPackets(); });
    }

    void stop() {
        running = false;
        cv.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void processPackets() {
        pollfd fds[1];
        fds[0].fd = captureSocket;
        fds[0].events = POLLIN;

        while (running) {
            int ret = poll(fds, 1, 100); // 100ms timeout

            if (ret < 0) {
                perror("Poll error");
                break;
            }

            if (ret == 0) {
                continue; // Timeout
            }

            if (fds[0].revents & POLLIN) {
                sockaddr_ll sender{};
                socklen_t senderLen = sizeof(sender);

                ssize_t packetSize = recvfrom(captureSocket, packetBuffer.data(),
                                             packetBuffer.size(), 0,
                                             reinterpret_cast<sockaddr*>(&sender),
                                             &senderLen);

                if (packetSize < 0) {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        perror("Recvfrom error");
                    }
                    continue;
                }

                // Process the packet
                bool shouldForward = true;

                {
                    std::lock_guard<std::mutex> lock(mtx);
                    for (const auto& filter : filters) {
                        if (!filter->shouldForward(packetBuffer.data(), packetSize)) {
                            shouldForward = false;
                            break;
                        }
                    }
                }

                if (shouldForward) {
                    forwarder->forwardPacket(packetBuffer.data(), packetSize);
                }
            }
        }
    }
};

