#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <linux/if_packet.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <pthread.h>

#define BUFFER_SIZE 65536
#define MAX_RULES 100

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    int action; // 0 = drop, 1 = forward
} FilterRule;

FilterRule rules[MAX_RULES];
int rule_count = 0;
pthread_mutex_t rules_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t protocol, int action) {
    pthread_mutex_lock(&rules_mutex);
    if (rule_count < MAX_RULES) {
        rules[rule_count].src_ip = src_ip;
        rules[rule_count].dst_ip = dst_ip;
        rules[rule_count].src_port = src_port;
        rules[rule_count].dst_port = dst_port;
        rules[rule_count].protocol = protocol;
        rules[rule_count].action = action;
        rule_count++;
    }
    pthread_mutex_unlock(&rules_mutex);
}

int should_forward(uint32_t src_ip, uint32_t dst_ip,
                  uint16_t src_port, uint16_t dst_port,
                  uint8_t protocol) {
    pthread_mutex_lock(&rules_mutex);
    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == protocol)) {
            pthread_mutex_unlock(&rules_mutex);
            return rules[i].action;
        }
    }
    pthread_mutex_unlock(&rules_mutex);
    return 1; // Default action: forward
}

void process_packet(int sock_fd, struct sockaddr_ll *addr, unsigned char *buffer, int len) {
    struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
    uint32_t src_ip = ip_header->saddr;
    uint32_t dst_ip = ip_header->daddr;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;
    uint8_t protocol = ip_header->protocol;

    // Extract ports if TCP or UDP
    if (protocol == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + sizeof(struct iphdr));
        src_port = ntohs(tcp_header->source);
        dst_port = ntohs(tcp_header->dest);
    } else if (protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(buffer + sizeof(struct ethhdr) + sizeof(struct iphdr));
        src_port = ntohs(udp_header->source);
        dst_port = ntohs(udp_header->dest);
    }

    if (should_forward(src_ip, dst_ip, src_port, dst_port, protocol)) {
        // Forward the packet
        if (sendto(sock_fd, buffer, len, 0, (struct sockaddr *)addr, sizeof(*addr)) < 0) {
            perror("sendto failed");
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    char *interface = argv[1];
    int sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Get interface index
    struct ifreq if_idx;
    memset(&if_idx, 0, sizeof(struct ifreq));
    strncpy(if_idx.ifr_name, interface, IFNAMSIZ-1);
    if (ioctl(sock_fd, SIOCGIFINDEX, &if_idx) < 0) {
        perror("SIOCGIFINDEX");
        exit(EXIT_FAILURE);
    }

    // Set promiscuous mode
    struct packet_mreq mreq;
    memset(&mreq, 0, sizeof(mreq));
    mreq.mr_ifindex = if_idx.ifr_ifindex;
    mreq.mr_type = PACKET_MR_PROMISC;
    if (setsockopt(sock_fd, SOL_PACKET, PACKET_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("setsockopt PACKET_MR_PROMISC");
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_idx.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);
    if (bind(sock_fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Add some example rules
    add_filter_rule(0, 0, 0, 80, IPPROTO_TCP, 1); // Allow HTTP
    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, 1); // Allow HTTPS
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, 0); // Drop ICMP

    printf("Ultra-low-latency packet filter running on %s\n", interface);

    unsigned char buffer[BUFFER_SIZE];
    struct sockaddr_ll addr;
    socklen_t addr_len = sizeof(addr);

    while (1) {
        int len = recvfrom(sock_fd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&addr, &addr_len);
        if (len < 0) {
            perror("recvfrom");
            continue;
        }

        process_packet(sock_fd, &addr, buffer, len);
    }

    close(sock_fd);
    return 0;
}
