#include <sys/socket.h>
#include <linux/if_ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <pthread.h>
#include <signal.h>

#define BUFFER_SIZE 2048
#define MAX_RULES 100

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint8_t action; // 0=drop, 1=forward
} FirewallRule;

FirewallRule rules[MAX_RULES];
int rule_count = 0;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int create_raw_socket() {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }
    return sockfd;
}

void add_rule(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port,
              uint16_t dst_port, uint8_t protocol, uint8_t action) {
    if (rule_count >= MAX_RULES) {
        fprintf(stderr, "Maximum rules reached\n");
        return;
    }

    rules[rule_count].src_ip = src_ip;
    rules[rule_count].dst_ip = dst_ip;
    rules[rule_count].src_port = src_port;
    rules[rule_count].dst_port = dst_port;
    rules[rule_count].protocol = protocol;
    rules[rule_count].action = action;
    rule_count++;
}

int match_rule(struct iphdr *ip, void *transport) {
    uint16_t src_port = 0, dst_port = 0;

    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr *)transport;
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)transport;
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    }

    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == ip->saddr) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == ip->daddr) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == ip->protocol)) {
            return rules[i].action;
        }
    }

    return 1; // Default action: forward
}

void process_packet(int sockfd, char *buffer, int len) {
    struct ethhdr *eth = (struct ethhdr *)buffer;
    struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));

    // Skip non-IP packets
    if (eth->h_proto != htons(ETH_P_IP)) {
        return;
    }

    // Calculate transport header offset
    void *transport = (void *)ip + (ip->ihl * 4);

    // Check if packet matches any rule
    if (match_rule(ip, transport)) {
        // Forward the packet (in a real implementation, this would send to another interface)
        // For this minimal example, we'll just print the packet info
        printf("Forwarding packet: %s:%d -> %s:%d (proto: %d)\n",
               inet_ntoa(*(struct in_addr *)&ip->saddr),
               ntohs(((struct tcphdr *)transport)->source),
               inet_ntoa(*(struct in_addr *)&ip->daddr),
               ntohs(((struct tcphdr *)transport)->dest),
               ip->protocol);
    } else {
        printf("Dropping packet: %s:%d -> %s:%d (proto: %d)\n",
               inet_ntoa(*(struct in_addr *)&ip->saddr),
               ntohs(((struct tcphdr *)transport)->source),
               inet_ntoa(*(struct in_addr *)&ip->daddr),
               ntohs(((struct tcphdr *)transport)->dest),
               ip->protocol);
    }
}

void *packet_receiver(void *arg) {
    int sockfd = *(int *)arg;
    char buffer[BUFFER_SIZE];

    while (running) {
        int len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, NULL, NULL);
        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        process_packet(sockfd, buffer, len);
    }

    return NULL;
}

int main() {
    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Create raw socket
    int sockfd = create_raw_socket();

    // Add some example rules
    // Rule 1: Drop all TCP traffic from 192.168.1.100 to 192.168.1.1 on port 80
    add_rule(inet_addr("192.168.1.100"), inet_addr("192.168.1.1"),
             0, 80, IPPROTO_TCP, 0);

    // Rule 2: Forward all UDP traffic
    add_rule(0, 0, 0, 0, IPPROTO_UDP, 1);

    // Start packet receiver thread
    pthread_t receiver_thread;
    if (pthread_create(&receiver_thread, NULL, packet_receiver, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return EXIT_FAILURE;
    }

    printf("Ultra-low-latency packet filter running. Press Ctrl+C to stop.\n");

    // Wait for signal
    while (running) {
        sleep(1);
    }

    // Cleanup
    pthread_join(receiver_thread, NULL);
    close(sockfd);

    return EXIT_SUCCESS;
}
