pthread_mutex_t rules_mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the forwarding socket
int init_forward_socket(const char *ifname) {
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ-1);

    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX");
        close(sock);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sock);
        return -1;
    }

    return sock;
}

// Add a filter rule
void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t protocol, uint8_t action) {
    pthread_mutex_lock(&rules_mutex);

    if (rule_count < MAX_RULES) {
        rules[rule_count].src_ip = src_ip;
        rules[rule_count].dst_ip = dst_ip;
        rules[rule_count].src_port = src_port;
        rules[rule_count].dst_port = dst_port;
        rules[rule_count].protocol = protocol;
        rules[rule_count].action = action;
        rule_count++;
    }

    pthread_mutex_unlock(&rules_mutex);
}

// Check if packet matches any rule
int check_packet_rules(const void *packet, int len) {
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Skip non-IP packets
    if (ip->version != 4) return 0;

    uint32_t src_ip = ip->saddr;
    uint32_t dst_ip = ip->daddr;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;

    // Extract ports for TCP/UDP
    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    }

    pthread_mutex_lock(&rules_mutex);

    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == ip->protocol)) {
            pthread_mutex_unlock(&rules_mutex);
            return rules[i].action;
        }
    }

    pthread_mutex_unlock(&rules_mutex);
    return 1; // Default action: forward
