        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        // Check if packet should be forwarded
        if (check_packet_rules(buffer, len)) {
            // Forward the packet (in a real implementation, you'd send it out another interface)
            // For this minimal example, we just print the packet info
            struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
            printf("Forwarding packet: %s:%d -> %s:%d (proto: %d)\n",
                   inet_ntoa(*(struct in_addr *)&ip->saddr),
                   ntohs(((struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip->ihl * 4))->source),
                   inet_ntoa(*(struct in_addr *)&ip->daddr),
                   ntohs(((struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip->ihl * 4))->dest),
                   ip->protocol);
        } else {
            printf("Dropping packet\n");
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    // Initialize forwarding socket
    forward_socket = init_forward_socket(argv[1]);
    if (forward_socket < 0) {
        return 1;
    }

    // Add some example rules
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, 0); // Drop all ICMP
    add_filter_rule(inet_addr("192.168.1.100"), 0, 0, 0, IPPROTO_TCP, 1); // Forward TCP from 192.168.1.100

