        struct tcphdr *tcp_header = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
        src_port = ntohs(tcp_header->source);
        dst_port = ntohs(tcp_header->dest);
    } else if (ip_header->protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
        src_port = ntohs(udp_header->source);
        dst_port = ntohs(udp_header->dest);
    }

    pthread_mutex_lock(&rules_mutex);
    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == ip_header->saddr) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == ip_header->daddr) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == ip_header->protocol)) {
            pthread_mutex_unlock(&rules_mutex);
            return rules[i].action;
        }
    }
    pthread_mutex_unlock(&rules_mutex);

    // Default action: forward
    return 1;
}

// Main packet processing loop
void *packet_processor(void *arg) {
    unsigned char buffer[BUFFER_SIZE];
    struct sockaddr_ll sender;
    socklen_t sender_len = sizeof(sender);

    while (keep_running) {
        int packet_len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&sender, &sender_len);
        if (packet_len < 0) {
            if (errno == EINTR) continue; // Interrupted by signal
            perror("recvfrom");
            break;
        }

        // Check if packet should be forwarded
        if (should_forward(buffer, packet_len)) {
            // Forward the packet (simplified - in real implementation you'd need to:
            // 1. Modify MAC addresses if needed
            // 2. Handle ARP if forwarding to different network
            // 3. Potentially modify IP TTL
            if (sendto(sockfd, buffer, packet_len, 0, (struct sockaddr *)&socket_address, sizeof(socket_address)) < 0) {
                perror("sendto");
            }
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    // Set up signal handler for graceful shutdown
