Below is a minimal working version of a high-performance networking service that performs packet-level filtering and forwarding. This implementation uses raw sockets and efficient data structures to minimize latency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <linux/if_packet.h>
#include <pthread.h>
#include <signal.h>
#include <stdbool.h>

#define BUFFER_SIZE 65536
#define MAX_RULES 100

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint32_t action; // 0=drop, 1=forward, 2=modify
    uint32_t new_dst_ip;
} FilterRule;

typedef struct {
    int sock_fd;
    char if_name[IFNAMSIZ];
    int if_index;
    bool running;
    FilterRule rules[MAX_RULES];
    int rule_count;
    pthread_mutex_t rule_mutex;
} NetworkService;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void setup_raw_socket(NetworkService *service) {
    struct sockaddr_ll sock_addr;
    struct ifreq ifr;

    // Create raw socket
    service->sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (service->sock_fd == -1) {
        handle_error("socket");
    }

    // Get interface index
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, service->if_name, IFNAMSIZ-1);
    if (ioctl(service->sock_fd, SIOCGIFINDEX, &ifr) == -1) {
        handle_error("ioctl SIOCGIFINDEX");
    }
    service->if_index = ifr.ifr_ifindex;

    // Bind to interface
    memset(&sock_addr, 0, sizeof(sock_addr));
    sock_addr.sll_family = AF_PACKET;
    sock_addr.sll_ifindex = service->if_index;
    sock_addr.sll_protocol = htons(ETH_P_ALL);
    if (bind(service->sock_fd, (struct sockaddr *)&sock_addr, sizeof(sock_addr)) == -1) {
        handle_error("bind");
    }
}

bool match_rule(const FilterRule *rule, const struct iphdr *ip_hdr, const void *transport_hdr) {
    // Check IP addresses
    if (rule->src_ip != 0 && rule->src_ip != ip_hdr->saddr) return false;
    if (rule->dst_ip != 0 && rule->dst_ip != ip_hdr->daddr) return false;

    // Check protocol
    if (rule->protocol != 0 && rule->protocol != ip_hdr->protocol) return false;

    // Check transport layer (TCP/UDP)
    if (ip_hdr->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp_hdr = (struct tcphdr *)transport_hdr;
        if (rule->src_port != 0 && rule->src_port != ntohs(tcp_hdr->source)) return false;
        if (rule->dst_port != 0 && rule->dst_port != ntohs(tcp_hdr->dest)) return false;
    } else if (ip_hdr->protocol == IPPROTO_UDP) {
        const struct udphdr *udp_hdr = (struct udphdr *)transport_hdr;
        if (rule->src_port != 0 && rule->src_port != ntohs(udp_hdr->source)) return false;
        if (rule->dst_port != 0 && rule->dst_port != ntohs(udp_hdr->dest)) return false;
    }

    return true;
}

void process_packet(NetworkService *service, const unsigned char *buffer, ssize_t len) {
    struct iphdr *ip_hdr = (struct iphdr *)(buffer + sizeof(struct ethhdr));
    void *transport_hdr = (void *)(buffer + sizeof(struct ethhdr) + (ip_hdr->ihl * 4));

    // Check if we have rules
    if (service->rule_count == 0) {
        // No rules, forward all packets
        send(service->sock_fd, buffer, len, 0);
        return;
    }

    // Check against all rules
    pthread_mutex_lock(&service->rule_mutex);
    for (int i = 0; i < service->rule_count; i++) {
        if (match_rule(&service->rules[i], ip_hdr, transport_hdr)) {
            if (service->rules[i].action == 0) { // Drop
                pthread_mutex_unlock(&service->rule_mutex);
                return;
            } else if (service->rules[i].action == 1) { // Forward
                send(service->sock_fd, buffer, len, 0);
                pthread_mutex_unlock(&service->rule_mutex);
                return;
            } else if (service->rules[i].action == 2) { // Modify and forward
                // Simple example: modify destination IP
                ip_hdr->daddr = service->rules[i].new_dst_ip;
                // Recalculate checksum (simplified)
                ip_hdr->check = 0;
                // In a real implementation, you'd need proper checksum calculation
                send(service->sock_fd, buffer, len, 0);
                pthread_mutex_unlock(&service->rule_mutex);
                return;
            }
        }
    }
    pthread_mutex_unlock(&service->rule_mutex);

    // No matching rule, forward by default
    send(service->sock_fd, buffer, len, 0);
}

void *packet_receiver(void *arg) {
    NetworkService *service = (NetworkService *)arg;
    unsigned char buffer[BUFFER_SIZE];
    ssize_t len;

    while (service->running) {
        len = recv(service->sock_fd, buffer, BUFFER_SIZE, 0);
        if (len == -1) {
            if (errno == EINTR) continue;
            handle_error("recv");
        }

        process_packet(service, buffer, len);
    }

    return NULL;
}

void add_rule(NetworkService *service, const FilterRule *rule) {
    pthread_mutex_lock(&service->rule_mutex);
    if (service->rule_count < MAX_RULES) {
        service->rules[service->rule_count++] = *rule;
    }
    pthread_mutex_unlock(&service->rule_mutex);
}

void cleanup(NetworkService *service) {
    service->running = false;
    close(service->sock_fd);
    pthread_mutex_destroy(&service->rule_mutex);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    NetworkService service = {0};
    strncpy(service.if_name, argv[1], IFNAMSIZ-1);
    service.running = true;
    pthread_mutex_init(&service.rule_mutex, NULL);

    // Example rule: drop all TCP traffic to port 80
    FilterRule rule = {
        .src_ip = 0,
        .dst_ip = 0,
        .src_port = 0,
        .dst_port = htons(80),
        .protocol = IPPROTO_TCP,
        .action = 0, // drop
        .new_dst_ip = 0
    };
    add_rule(&service, &rule);

    setup_raw_socket(&service);

    pthread_t receiver_thread;
    if (pthread_create(&receiver_thread, NULL, packet_receiver, &service) != 0) {
        handle_error("pthread_create");
    }

    printf("Network service running on interface %s. Press Ctrl+C to stop.\n", service.if_name);

    // Simple signal handler for graceful shutdown
    signal(SIGINT, [](int sig) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    });

    // Keep main thread alive
    while (1) {
        sleep(1);
    }

    cleanup(&service);
    return 0;
}
