#define BUFFER_SIZE 65536
#define MAX_RULES 100

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint8_t action; // 0=drop, 1=forward
} FilterRule;

FilterRule rules[MAX_RULES];
int rule_count = 0;

void add_rule(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port, uint8_t protocol, uint8_t action) {
    if (rule_count >= MAX_RULES) {
        fprintf(stderr, "Maximum rules reached\n");
        return;
    }

    rules[rule_count].src_ip = src_ip;
    rules[rule_count].dst_ip = dst_ip;
    rules[rule_count].src_port = src_port;
    rules[rule_count].dst_port = dst_port;
    rules[rule_count].protocol = protocol;
    rules[rule_count].action = action;
    rule_count++;
}

int match_rule(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port, uint8_t protocol) {
    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == protocol)) {
            return rules[i].action;
        }
    }
    return 1; // Default action: forward
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <interface> <forward_interface>\n", argv[0]);
        return 1;
    }

    // Create raw socket for receiving packets
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    // Create raw socket for sending packets
    int send_sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (send_sockfd < 0) {
        perror("send socket");
        close(sockfd);
        return 1;
    }

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(argv[1]);
    if (sll.sll_ifindex == 0) {
        perror("if_nametoindex");
        close(sockfd);
        close(send_sockfd);
        return 1;
    }

    if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        close(send_sockfd);
        return 1;
    }

    // Set up forwarding interface
    struct sockaddr_ll forward_sll;
    memset(&forward_sll, 0, sizeof(forward_sll));
    forward_sll.sll_family = AF_PACKET;
    forward_sll.sll_ifindex = if_nametoindex(argv[2]);
    if (forward_sll.sll_ifindex == 0) {
        perror("if_nametoindex for forward interface");
        close(sockfd);
        close(send_sockfd);
        return 1;
    }

    // Add some example rules (in a real app, these would come from config)
    add_rule(0, 0, 0, 0, IPPROTO_ICMP, 0); // Drop all ICMP
    add_rule(0, 0, 0, 80, IPPROTO_TCP, 1); // Forward all TCP port 80
    add_rule(0, 0, 0, 53, IPPROTO_UDP, 1); // Forward all UDP port 53

    printf("Packet filter running on %s, forwarding to %s\n", argv[1], argv[2]);

    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    while (1) {
        ssize_t packet_len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr*)&from, &from_len);
        if (packet_len < 0) {
            perror("recvfrom");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth = (struct ethhdr *)buffer;
        if (packet_len < sizeof(struct ethhdr)) {
            continue;
        }

        // Check for IP packets
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            continue;
        }

        // Parse IP header
        struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (packet_len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
            continue;
        }

        uint16_t src_port = 0, dst_port = 0;

        // Parse transport layer headers
        if (ip->protocol == IPPROTO_TCP) {
            struct tcphdr *tcp = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip->ihl * 4);
            if (packet_len < sizeof(struct ethhdr) + ip->ihl * 4 + sizeof(struct tcphdr)) {
                continue;
            }
            src_port = ntohs(tcp->source);
            dst_port = ntohs(tcp->dest);
        } else if (ip->protocol == IPPROTO_UDP) {
            struct udphdr *udp = (struct udphdr *)(buffer + sizeof(struct ethhdr) + ip->ihl * 4);
            if (packet_len < sizeof(struct ethhdr) + ip->ihl * 4 + sizeof(struct udphdr)) {
                continue;
            }
            src_port = ntohs(udp->source);
            dst_port = ntohs(udp->dest);
        }

        // Check rules
        int action = match_rule(ip->saddr, ip->daddr, src_port, dst_port, ip->protocol);
        if (action == 0) {
            continue; // Drop packet
        }

        // Forward packet
        if (sendto(send_sockfd, buffer, packet_len, 0, (struct sockaddr*)&forward_sll, sizeof(forward_sll)) < 0) {
            perror("sendto");
        }
    }

    close(sockfd);
    close(send_sockfd);
    return 0;
}
