}

// Check if a packet matches any rule
int check_rules(const uint8_t *packet, int len) {
    struct iphdr *ip_header = (struct iphdr *)(packet + sizeof(struct ethhdr));
    uint32_t src_ip = ip_header->saddr;
    uint32_t dst_ip = ip_header->daddr;

    // For simplicity, we only handle UDP packets in this example
    if (ip_header->protocol != IPPROTO_UDP) {
        return 0; // Drop non-UDP packets
    }

    struct udphdr *udp_header = (struct udphdr *)(packet + sizeof(struct ethhdr) + ip_header->ihl * 4);
    uint16_t src_port = ntohs(udp_header->source);
    uint16_t dst_port = ntohs(udp_header->dest);

    pthread_mutex_lock(&rules_mutex);
    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == ip_header->protocol)) {
            pthread_mutex_unlock(&rules_mutex);
            return rules[i].action;
        }
    }
    pthread_mutex_unlock(&rules_mutex);

    return 0; // Default action: drop
}

// Forward a packet
void forward_packet(int sock, const uint8_t *packet, int len) {
    if (forward_socket < 0) {
        forward_socket = init_forward_socket();
        if (forward_socket < 0) {
            return;
        }
    }

    // In a real implementation, you would modify the packet as needed
    // before forwarding. This is just a simple example.
    if (sendto(forward_socket, packet, len, 0, NULL, 0) < 0) {
        perror("sendto");
    }
}

// Main packet processing loop
void process_packets(int sock) {
    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    while (1) {
        int len = recvfrom(sock, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&from, &from_len);
        if (len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, try again
                usleep(1000); // 1ms sleep to prevent busy waiting
                continue;
            }
            perror("recvfrom");
            break;
        }

        // Check if packet matches any rules
        if (check_rules(buffer, len)) {
            forward_packet(sock, buffer, len);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    // Create raw socket to receive packets
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        return 1;
    }

    // Bind to the specified interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, argv[1], IFNAMSIZ - 1);

    if (setsockopt(sock, SOL_SOCKET, SO_BINDTODEVICE, (void *)&ifr, sizeof(ifr)) < 0) {
        perror("setsockopt");
        close(sock);
        return 1;
    }

    // Set socket to non-blocking
    int flags = fcntl(sock, F_GETFL, 0);
    fcntl(sock, F_SETFL, flags | O_NONBLOCK);

    // Add some example rules (in a real app, these would come from config)
    add_rule(0, 0, 0, 53, IPPROTO_UDP, 1); // Forward DNS traffic
    add_rule(0, 0, 0, 80, IPPROTO_TCP, 1);  // Forward HTTP traffic
    add_rule(0, 0, 0, 443, IPPROTO_TCP, 1); // Forward HTTPS traffic

    printf("Packet forwarding service started on interface %s\n", argv[1]);
    printf("Press Ctrl+C to stop\n");

    // Start processing packets
    process_packets(sock);

    close(sock);
    if (forward_socket >= 0) {
        close(forward_socket);
    }

    return 0;
}
