#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define BUFFER_SIZE 65536

// Simple packet filter structure
typedef struct {
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;  // IPPROTO_TCP or IPPROTO_UDP
    uint32_t src_ip;
    uint32_t dst_ip;
} PacketFilter;

// Initialize a packet filter
void init_filter(PacketFilter *filter) {
    filter->src_port = 0;      // 0 means any port
    filter->dst_port = 0;
    filter->protocol = 0;      // 0 means any protocol
    filter->src_ip = 0;        // 0 means any IP
    filter->dst_ip = 0;
}

// Check if packet matches filter
int packet_matches(const PacketFilter *filter, const struct iphdr *ip, const void *transport) {
    if (filter->protocol != 0 && filter->protocol != ip->protocol) {
        return 0;
    }

    if (filter->src_ip != 0 && filter->src_ip != ip->saddr) {
        return 0;
    }

    if (filter->dst_ip != 0 && filter->dst_ip != ip->daddr) {
        return 0;
    }

    if (ip->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp = (const struct tcphdr *)transport;
        if (filter->src_port != 0 && ntohs(filter->src_port) != tcp->source) {
            return 0;
        }
        if (filter->dst_port != 0 && ntohs(filter->dst_port) != tcp->dest) {
            return 0;
        }
    } else if (ip->protocol == IPPROTO_UDP) {
        const struct udphdr *udp = (const struct udphdr *)transport;
        if (filter->src_port != 0 && ntohs(filter->src_port) != udp->source) {
            return 0;
        }
        if (filter->dst_port != 0 && ntohs(filter->dst_port) != udp->dest) {
            return 0;
        }
    }

    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <interface> <forward_interface>\n", argv[0]);
        return 1;
    }

    char *interface = argv[1];
    char *forward_interface = argv[2];

    // Create raw socket for receiving packets
    int recv_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (recv_sock < 0) {
        perror("socket");
        return 1;
    }

    // Create raw socket for sending packets
    int send_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (send_sock < 0) {
        perror("socket");
        close(recv_sock);
        return 1;
    }

    // Bind to the receive interface
    struct sockaddr_ll recv_addr = {0};
    recv_addr.sll_family = AF_PACKET;
    recv_addr.sll_ifindex = if_nametoindex(interface);
    recv_addr.sll_protocol = htons(ETH_P_ALL);

    if (bind(recv_sock, (struct sockaddr *)&recv_addr, sizeof(recv_addr)) < 0) {
        perror("bind");
        close(recv_sock);
        close(send_sock);
        return 1;
    }

    // Prepare send address (for forwarding)
    struct sockaddr_ll send_addr = {0};
    send_addr.sll_family = AF_PACKET;
    send_addr.sll_ifindex = if_nametoindex(forward_interface);
    send_addr.sll_protocol = htons(ETH_P_ALL);

    // Set up a simple filter (example: forward only TCP port 80)
    PacketFilter filter;
    init_filter(&filter);
    filter.protocol = IPPROTO_TCP;
    filter.dst_port = 80;

    printf("Forwarding TCP port 80 from %s to %s\n", interface, forward_interface);

    char buffer[BUFFER_SIZE];
    while (1) {
        // Receive packet
        ssize_t len = recv(recv_sock, buffer, BUFFER_SIZE, 0);
        if (len < 0) {
            perror("recv");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth = (struct ethhdr *)buffer;
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            continue;  // Not an IP packet
        }

        // Parse IP header
        struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (ip->version != 4) {
            continue;  // Not IPv4
        }

        // Get transport header
        void *transport = (void *)ip + (ip->ihl * 4);

        // Check if packet matches our filter
        if (packet_matches(&filter, ip, transport)) {
            // Forward the packet
            if (sendto(send_sock, buffer, len, 0, (struct sockaddr *)&send_addr, sizeof(send_addr)) < 0) {
                perror("sendto");
            }
        }
    }

    close(recv_sock);
    close(send_sock);
    return 0;
}
