# High-Throughput Streaming Data Parser

Here's a Python implementation of a streaming data parser designed to handle gigabyte-scale input with minimal memory overhead. This solution uses generators and chunked processing to avoid loading the entire file into memory.

```python
import json
import csv
from io import TextIOWrapper
from typing import Generator, Any, Dict, List, Union, Optional
import gzip
import bz2
import lzma
import mmap
import os

class StreamingDataParser:
    """
    A high-throughput streaming data parser for large files with minimal memory overhead.
    Supports JSON, CSV, and plain text formats, with optional compression.
    """

    def __init__(self, file_path: str, format: str = 'json',
                 chunk_size: int = 1024*1024,  # 1MB chunks by default
                 compression: Optional[str] = None):
        """
        Initialize the parser.

        Args:
            file_path: Path to the input file
            format: Data format ('json', 'csv', or 'text')
            chunk_size: Size of chunks to read at once (in bytes)
            compression: Compression type if file is compressed ('gzip', 'bz2', 'xz', or None)
        """
        self.file_path = file_path
        self.format = format.lower()
        self.chunk_size = chunk_size
        self.compression = compression.lower() if compression else None
        self._validate_params()

    def _validate_params(self):
        """Validate input parameters."""
        if self.format not in ['json', 'csv', 'text']:
            raise ValueError(f"Unsupported format: {self.format}. Use 'json', 'csv', or 'text'.")

        if self.compression and self.compression not in ['gzip', 'bz2', 'xz']:
            raise ValueError(f"Unsupported compression: {self.compression}. Use 'gzip', 'bz2', 'xz', or None.")

    def _open_file(self):
        """Open the file with appropriate compression handling."""
        if self.compression == 'gzip':
            return gzip.open(self.file_path, 'rt', encoding='utf-8')
        elif self.compression == 'bz2':
            return bz2.open(self.file_path, 'rt', encoding='utf-8')
        elif self.compression == 'xz':
            return lzma.open(self.file_path, 'rt', encoding='utf-8')
        else:
            return open(self.file_path, 'r', encoding='utf-8')

    def _read_chunks(self, file_obj) -> Generator[str, None, None]:
        """Read the file in chunks to minimize memory usage."""
        while True:
            chunk = file_obj.read(self.chunk_size)
            if not chunk:
                break
            yield chunk

    def parse(self) -> Generator[Union[Dict, List, str], None, None]:
        """
        Parse the file in a streaming fashion, yielding one record at a time.

        Yields:
            Parsed records (dict for JSON, list for CSV, str for text)
        """
        with self._open_file() as f:
            if self.format == 'json':
                yield from self._parse_json(f)
            elif self.format == 'csv':
                yield from self._parse_csv(f)
            else:  # text
                yield from self._parse_text(f)

    def _parse_json(self, file_obj) -> Generator[Dict, None, None]:
        """Parse JSON data line by line (assuming one JSON object per line)."""
        buffer = ""
        for chunk in self._read_chunks(file_obj):
            buffer += chunk
            # Split on newlines to handle partial JSON objects at chunk boundaries
            lines = buffer.split('\n')
            buffer = lines.pop()  # Save the last (potentially incomplete) line

            for line in lines:
                line = line.strip()
                if line:  # Skip empty lines
                    try:
                        yield json.loads(line)
                    except json.JSONDecodeError as e:
                        print(f"Warning: Skipping malformed JSON line: {e}")

        # Process any remaining data in the buffer
        if buffer.strip():
            try:
                yield json.loads(buffer.strip())
            except json.JSONDecodeError as e:
                print(f"Warning: Skipping malformed JSON line: {e}")

    def _parse_csv(self, file_obj) -> Generator[List, None, None]:
        """Parse CSV data line by line."""
        # Use csv.reader with a generator approach
        reader = csv.reader(self._read_chunks(file_obj))
        for row in reader:
            yield row

    def _parse_text(self, file_obj) -> Generator[str, None, None]:
        """Parse plain text line by line."""
        for chunk in self._read_chunks(file_obj):
            lines = chunk.split('\n')
            for line in lines:
                if line.strip():  # Skip empty lines
                    yield line.strip()

    def parse_with_progress(self, progress_callback=None) -> Generator[Union[Dict, List, str], None, None]:
        """
        Parse the file with progress tracking.

        Args:
            progress_callback: Optional function to call with progress updates (bytes processed)

        Yields:
            Parsed records with progress tracking
        """
        total_bytes = os.path.getsize(self.file_path)
        processed_bytes = 0

        with self._open_file() as f:
            if self.format == 'json':
                buffer = ""
                for chunk in self._read_chunks(f):
                    processed_bytes += len(chunk)
                    if progress_callback:
                        progress_callback(processed_bytes / total_bytes * 100)

                    buffer += chunk
                    lines = buffer.split('\n')
                    buffer = lines.pop()

                    for line in lines:
                        line = line.strip()
                        if line:
                            try:
                                yield json.loads(line)
                            except json.JSONDecodeError as e:
                                print(f"Warning: Skipping malformed JSON line: {e}")

                if buffer.strip():
                    try:
                        yield json.loads(buffer.strip())
                    except json.JSONDecodeError as e:
                        print(f"Warning: Skipping malformed JSON line: {e}")

            elif self.format == 'csv':
                reader = csv.reader(self._read_chunks(f))
                for row in reader:
                    processed_bytes += sum(len(cell) + 1 for cell in row)  # Approximate byte count
                    if progress_callback:
                        progress_callback(processed_bytes / total_bytes * 100)
                    yield row

            else:  # text
                for chunk in self._read_chunks(f):
                    processed_bytes += len(chunk)
                    if progress_callback:
                        progress_callback(processed_bytes / total_bytes * 100)

                    lines = chunk.split('\n')
                    for line in lines:
                        if line.strip():
                            yield line.strip()

    def memory_efficient_parse(self) -> Generator[Union[Dict, List, str], None, None]:
        """
        Alternative parsing method using memory-mapped files for even better memory efficiency.
        Note: This may be slower than the chunked approach for some formats.
        """
        with open(self.file_path, 'r+b') as f:
            with mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ) as mm:
                if self.format == 'json':
                    # For JSON, we still need to process line by line
                    buffer = ""
                    for line in iter(mm.readline, b''):
                        line = line.decode('utf-8').strip()
                        if line:
                            try:
                                yield json.loads(line)
                            except json.JSONDecodeError as e:
                                print(f"Warning: Skipping malformed JSON line: {e}")

                elif self.format == 'csv':
                    # CSV reader can work with memory-mapped files
                    reader = csv.reader(TextIOWrapper(mm))
                    for row in reader:
                        yield row

                else:  # text
                    for line in iter(mm.readline, b''):
                        line = line.decode('utf-8').strip()
                        if line:
                            yield line

