# High-Throughput Streaming Data Parser

Here's a Python implementation of a memory-efficient streaming data parser that can handle gigabyte-scale inputs with minimal memory overhead. This solution uses generators and chunked processing to avoid loading the entire file into memory.

```python
import json
import csv
from io import StringIO
from typing import Iterator, Union, Dict, List, Any
import gzip
import bz2
import zlib
import mmap

class StreamingDataParser:
    """
    A high-throughput streaming data parser for large files with minimal memory overhead.
    Supports JSON, CSV, and compressed files (gzip, bzip2).
    """

    def __init__(self, chunk_size: int = 65536):
        """
        Initialize the parser with a chunk size (default: 64KB).
        """
        self.chunk_size = chunk_size

    def parse_file(self, file_path: str, file_type: str = 'auto') -> Iterator[Union[Dict, List]]:
        """
        Parse a file in a streaming fashion.

        Args:
            file_path: Path to the file to parse
            file_type: File type ('json', 'csv', 'auto', 'gzip', 'bzip2')

        Returns:
            Iterator yielding parsed records one at a time
        """
        # Determine file type if not specified
        if file_type == 'auto':
            file_type = self._detect_file_type(file_path)

        # Open file with appropriate handler
        with self._open_file(file_path, file_type) as file_obj:
            if file_type == 'json':
                yield from self._parse_json(file_obj)
            elif file_type == 'csv':
                yield from self._parse_csv(file_obj)
            else:
                # For compressed files, we need to determine the inner type
                inner_type = self._detect_inner_type(file_obj)
                if inner_type == 'json':
                    yield from self._parse_json(file_obj)
                elif inner_type == 'csv':
                    yield from self._parse_csv(file_obj)

    def _detect_file_type(self, file_path: str) -> str:
        """Detect file type based on extension."""
        if file_path.endswith('.gz'):
            return 'gzip'
        elif file_path.endswith('.bz2'):
            return 'bzip2'
        elif file_path.endswith('.json') or file_path.endswith('.jsonl'):
            return 'json'
        elif file_path.endswith('.csv'):
            return 'csv'
        else:
            # For unknown extensions, try to detect by content
            with open(file_path, 'rb') as f:
                first_bytes = f.read(1024)
                if first_bytes.startswith(b'{') or first_bytes.startswith(b'['):
                    return 'json'
                elif b',' in first_bytes and b'\n' in first_bytes:
                    return 'csv'
                elif first_bytes.startswith(b'\x1f\x8b'):
                    return 'gzip'
                elif first_bytes.startswith(b'BZh'):
                    return 'bzip2'
                else:
                    raise ValueError(f"Could not determine file type for {file_path}")

    def _detect_inner_type(self, file_obj) -> str:
        """Detect the inner file type for compressed files."""
        # Read first chunk to detect content type
        chunk = file_obj.read(1024)
        if not chunk:
            raise ValueError("Empty compressed file")

        # Try to decompress to see the content
        try:
            decompressed = zlib.decompress(chunk)
            if decompressed.startswith(b'{') or decompressed.startswith(b'['):
                return 'json'
            elif b',' in decompressed and b'\n' in decompressed:
                return 'csv'
        except zlib.error:
            pass

        # If we couldn't determine, assume JSON (most common for compressed files)
        return 'json'

    def _open_file(self, file_path: str, file_type: str):
        """Open file with appropriate handler based on type."""
        if file_type == 'gzip':
            return gzip.open(file_path, 'rt', encoding='utf-8')
        elif file_type == 'bzip2':
            return bz2.open(file_path, 'rt', encoding='utf-8')
        else:
            return open(file_path, 'r', encoding='utf-8')

    def _parse_json(self, file_obj) -> Iterator[Dict]:
        """
        Parse JSON file in a streaming fashion.
        Handles both JSON array and JSON lines (newline-delimited JSON) formats.
        """
        buffer = StringIO()
        in_array = False
        array_depth = 0

        for chunk in iter(lambda: file_obj.read(self.chunk_size), ''):
            buffer.write(chunk)

            # Check if we have a complete JSON object
            while True:
                pos = buffer.tell()
                buffer.seek(0)
                data = buffer.read()

                # Try to parse the current buffer
                try:
                    if not in_array:
                        # Check if this is a JSON array
                        if data.strip().startswith('['):
                            in_array = True
                            array_depth = 1
                            # Find the matching closing bracket
                            open_brackets = 1
                            for i, char in enumerate(data[1:], 1):
                                if char == '[':
                                    open_brackets += 1
                                elif char == ']':
                                    open_brackets -= 1
                                    if open_brackets == 0:
                                        # Found complete array
                                        array_data = json.loads(data[:i+1])
                                        buffer = StringIO(data[i+1:])
                                        for item in array_data:
                                            yield item
                                        break
                            else:
                                # Incomplete array, keep reading
                                buffer.seek(0, 2)  # Move to end
                                break
                        else:
                            # Assume JSON lines format
                            lines = data.split('\n')
                            for line in lines[:-1]:
                                if line.strip():
                                    yield json.loads(line)
                            buffer = StringIO(lines[-1])
                            break
                    else:
                        # We're in an array, find the closing bracket
                        open_brackets = 1
                        for i, char in enumerate(data):
                            if char == '[':
                                open_brackets += 1
                            elif char == ']':
                                open_brackets -= 1
                                if open_brackets == 0:
                                    # Found complete array
                                    array_data = json.loads(data[:i+1])
                                    buffer = StringIO(data[i+1:])
                                    for item in array_data:
                                        yield item
                                    break
                        else:
                            # Incomplete array, keep reading
                            buffer.seek(0, 2)  # Move to end
                            break
                except json.JSONDecodeError:
                    # JSON is incomplete, keep reading
                    buffer.seek(pos)
                    break

        # Process any remaining data in buffer
        buffer.seek(0)
        remaining = buffer.read().strip()
        if remaining:
            try:
                if in_array:
                    array_data = json.loads(remaining)
                    for item in array_data:
                        yield item
                else:
                    for line in remaining.split('\n'):
                        if line.strip():
                            yield json.loads(line)
            except json.JSONDecodeError as e:
                raise ValueError(f"Invalid JSON in remaining data: {remaining}") from e

    def _parse_csv(self, file_obj) -> Iterator[List]:
        """
        Parse CSV file in a streaming fashion.
        """
        # Use csv.reader with a generator approach
        reader = csv.reader(file_obj)
        for row in reader:
            yield row

    def parse_memory_mapped(self, file_path: str, file_type: str = 'auto') -> Iterator[Union[Dict, List]]:
        """
        Parse a file using memory mapping for very large files.
        This is more efficient for random access but still streaming.
        """
        with open(file_path, 'rb') as f:
            with mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ) as mm:
                if file_type == 'auto':
                    file_type = self._detect_file_type(file_path)

                if file_type == 'json':
                    yield from self._parse_json_memory_mapped(mm)
                elif file_type == 'csv':
                    yield from self._parse_csv_memory_mapped(mm)
                else:
                    # For compressed files, fall back to regular streaming
                    yield from self.parse_file(file_path, file_type)

    def _parse_json_memory_mapped(self, mm: mmap.mmap) -> Iterator[Dict]:
        """
        Parse JSON using memory mapping for better performance.
        """
        # This is a simplified version - a full implementation would need
        # more sophisticated parsing to handle large JSON arrays efficiently
        data = mm.read().decode('utf-8')
        if data.strip().startswith('['):
            # JSON array
            array_data = json.loads(data)
            for item in array_data:
                yield item
        else:
            # JSON lines
            for line in data.split('\n'):
                if line.strip():
                    yield json.loads(line)

    def _parse_csv_memory_mapped(self, mm: mmap.mmap) -> Iterator[List]:
        """
        Parse CSV using memory mapping for better performance.
        """
        data = mm.read().decode('utf-8')
        reader = csv.reader(StringIO(data))
        for row in reader:
            yield row

