# High-Performance System Resource Monitor Daemon

Below is a Python implementation of a high-performance system daemon for monitoring and managing operating system resources. This daemon provides real-time monitoring of CPU, memory, disk, network, and process metrics, with configurable thresholds and automatic response mechanisms.

```python
#!/usr/bin/env python3
import os
import sys
import time
import json
import psutil
import socket
import logging
import argparse
import threading
from datetime import datetime
from collections import deque
from logging.handlers import RotatingFileHandler

class SystemMonitorDaemon:
    def __init__(self, config_file='monitor_config.json'):
        self.config = self._load_config(config_file)
        self.running = False
        self.threads = []
        self.metrics_history = {
            'cpu': deque(maxlen=self.config['history_size']),
            'memory': deque(maxlen=self.config['history_size']),
            'disk': deque(maxlen=self.config['history_size']),
            'network': deque(maxlen=self.config['history_size']),
            'processes': deque(maxlen=self.config['history_size'])
        }
        self._setup_logging()

    def _load_config(self, config_file):
        """Load configuration from JSON file"""
        default_config = {
            'interval': 5,  # seconds
            'history_size': 60,  # number of samples to keep
            'log_file': '/var/log/system_monitor.log',
            'log_level': 'INFO',
            'alert_thresholds': {
                'cpu': 90,
                'memory': 90,
                'disk': 90,
                'network': 100000000  # bytes per second
            },
            'auto_response': {
                'enabled': True,
                'actions': {
                    'cpu': ['notify', 'kill_high_cpu'],
                    'memory': ['notify', 'kill_high_memory'],
                    'disk': ['notify', 'cleanup_temp']
                }
            }
        }

        try:
            with open(config_file, 'r') as f:
                config = json.load(f)
                # Merge with defaults
                for key, value in default_config.items():
                    if key not in config:
                        config[key] = value
                return config
        except (FileNotFoundError, json.JSONDecodeError):
            logging.warning(f"Config file {config_file} not found or invalid. Using defaults.")
            return default_config

    def _setup_logging(self):
        """Configure logging"""
        log_level = getattr(logging, self.config['log_level'].upper(), logging.INFO)

        # Create logs directory if it doesn't exist
        log_dir = os.path.dirname(self.config['log_file'])
        if log_dir and not os.path.exists(log_dir):
            os.makedirs(log_dir)

        # Set up rotating log handler
        handler = RotatingFileHandler(
            self.config['log_file'],
            maxBytes=10*1024*1024,  # 10MB
            backupCount=5
        )
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)

        logging.basicConfig(
            level=log_level,
            handlers=[handler]
        )

        # Also log to console for debugging
        console_handler = logging.StreamHandler()
        console_handler.setFormatter(formatter)
        logging.getLogger().addHandler(console_handler)

    def _get_system_info(self):
        """Collect system information"""
        info = {
            'timestamp': datetime.now().isoformat(),
            'hostname': socket.gethostname(),
            'cpu': {
                'percent': psutil.cpu_percent(interval=None),
                'count': psutil.cpu_count(),
                'load_avg': os.getloadavg()
            },
            'memory': {
                'total': psutil.virtual_memory().total,
                'available': psutil.virtual_memory().available,
                'percent': psutil.virtual_memory().percent,
                'used': psutil.virtual_memory().used
            },
            'disk': {
                'partitions': [],
                'io': psutil.disk_io_counters()
            },
            'network': {
                'interfaces': {},
                'io': psutil.net_io_counters()
            },
            'processes': {
                'count': len(psutil.pids()),
                'top': []
            }
        }

        # Get disk partitions
        for partition in psutil.disk_partitions():
            try:
                usage = psutil.disk_usage(partition.mountpoint)
                info['disk']['partitions'].append({
                    'device': partition.device,
                    'mountpoint': partition.mountpoint,
                    'fstype': partition.fstype,
                    'total': usage.total,
                    'used': usage.used,
                    'free': usage.free,
                    'percent': usage.percent
                })
            except Exception as e:
                logging.warning(f"Error getting disk info for {partition.mountpoint}: {str(e)}")

        # Get network interfaces
        for interface, addrs in psutil.net_if_addrs().items():
            info['network']['interfaces'][interface] = {
                'addresses': [addr.address for addr in addrs]
            }

        # Get top processes by CPU and memory
        processes = sorted(psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent']),
                          key=lambda p: p.info['cpu_percent'], reverse=True)
        for proc in processes[:5]:  # Top 5 processes
            try:
                info['processes']['top'].append({
                    'pid': proc.info['pid'],
                    'name': proc.info['name'],
                    'cpu_percent': proc.info['cpu_percent'],
                    'memory_percent': proc.info['memory_percent']
                })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        return info

    def _check_thresholds(self, metrics):
        """Check if any metrics exceed thresholds"""
        alerts = []

        # Check CPU
        if metrics['cpu']['percent'] > self.config['alert_thresholds']['cpu']:
            alerts.append(f"High CPU usage: {metrics['cpu']['percent']}%")

        # Check memory
        if metrics['memory']['percent'] > self.config['alert_thresholds']['memory']:
            alerts.append(f"High memory usage: {metrics['memory']['percent']}%")

        # Check disk
        for partition in metrics['disk']['partitions']:
            if partition['percent'] > self.config['alert_thresholds']['disk']:
                alerts.append(f"High disk usage on {partition['mountpoint']}: {partition['percent']}%")

        # Check network
        if 'network_io' in metrics:
            if metrics['network_io']['bytes_sent'] > self.config['alert_thresholds']['network'] or \
               metrics['network_io']['bytes_recv'] > self.config['alert_thresholds']['network']:
                alerts.append(f"High network traffic: {metrics['network_io']['bytes_sent']} sent, "
                            f"{metrics['network_io']['bytes_recv']} received")

        return alerts

    def _perform_auto_response(self, alerts):
        """Perform automatic responses to alerts"""
        if not self.config['auto_response']['enabled']:
            return

        for alert in alerts:
            if 'CPU' in alert:
                for action in self.config['auto_response']['actions']['cpu']:
                    if action == 'notify':
                        self._notify_admin(f"ALERT: {alert}")
                    elif action == 'kill_high_cpu':
                        self._kill_high_cpu_processes()

            elif 'memory' in alert.lower():
                for action in self.config['auto_response']['actions']['memory']:
                    if action == 'notify':
                        self._notify_admin(f"ALERT: {alert}")
                    elif action == 'kill_high_memory':
                        self._kill_high_memory_processes()

            elif 'disk' in alert.lower():
                for action in self.config['auto_response']['actions']['disk']:
                    if action == 'notify':
                        self._notify_admin(f"ALERT: {alert}")
                    elif action == 'cleanup_temp':
                        self._cleanup_temp_files()

    def _kill_high_cpu_processes(self):
        """Kill processes with high CPU usage"""
        try:
            processes = sorted(psutil.process_iter(['pid', 'name', 'cpu_percent']),
                             key=lambda p: p.info['cpu_percent'], reverse=True)

            for proc in processes[:3]:  # Kill top 3 CPU processes
                if proc.info['cpu_percent'] > self.config['alert_thresholds']['cpu']:
                    try:
                        proc.terminate()
                        logging.info(f"Terminated high CPU process: {proc.info['name']} (PID: {proc.info['pid']})")
                    except (psutil.NoSuchProcess, psutil.AccessDenied) as e:
                        logging.warning(f"Failed to terminate process {proc.info['name']}: {str(e)}")
        except Exception as e:
            logging.error(f"Error in _kill_high_cpu_processes: {str(e)}")

    def _kill_high_memory_processes(self):
        """Kill processes with high memory usage"""
        try:
            processes = sorted(psutil.process_iter(['pid', 'name', 'memory_percent']),
                             key=lambda p: p.info['memory_percent'], reverse=True)

            for proc in processes[:3]:  # Kill top 3 memory processes
                if proc.info['memory_percent'] > self.config['alert_thresholds']['memory']:
                    try:
                        proc.terminate()
                        logging.info(f"Terminated high memory process: {proc.info['name']} (PID: {proc.info['pid']})")
                    except (psutil.NoSuchProcess, psutil.AccessDenied) as e:
                        logging.warning(f"Failed to terminate process {proc.info['name']}: {str(e)}")
        except Exception as e:
            logging.error(f"Error in _kill_high_memory_processes: {str(e)}")

    def _cleanup_temp_files(self):
        """Clean up temporary files"""
        try:
            temp_dirs = ['/tmp', '/var/tmp']
            for temp_dir in temp_dirs:
                if os.path.exists(temp_dir):
                    for filename in os.listdir(temp_dir):
                        file_path = os.path.join(temp_dir, filename)
                        try:
                            if os.path.isfile(file_path):
                                os.unlink(file_path)
                                logging.info(f"Removed temp file: {file_path}")
                        except Exception as e:
                            logging.warning(f"Failed to remove {file_path}: {str(e)}")
        except Exception as e:
            logging.error(f"Error in _cleanup_temp_files: {str(e)}")

    def _notify_admin(self, message):
        """Send notification to admin (placeholder)"""
        logging.warning(f"ADMIN NOTIFICATION: {message}")
        # In a real implementation, this would send an email, SMS, or other notification

    def _monitor_loop(self):
        """Main monitoring loop"""
        last_network_io = None

        while self.running:
            try:
                start_time = time.time()

                # Get system metrics
                metrics = self._get_system_info()

                # Calculate network I/O rates
                if last_network_io:
                    interval = self.config['interval']
                    network_io = psutil.net_io_counters()
                    metrics['network_io'] = {
                        'bytes_sent': (network_io.bytes_sent - last_network_io.bytes_sent) / interval,
                        'bytes_recv': (network_io.bytes_recv - last_network_io.bytes_recv) / interval
                    }
                last_network_io = psutil.net_io_counters()

                # Store metrics in history
                self.metrics_history['cpu'].append(metrics['cpu'])
                self.metrics_history['memory'].append(metrics['memory'])
                self.metrics_history['disk'].append(metrics['disk'])
                self.metrics_history['network'].append(metrics['network'])
                self.metrics_history['processes'].append(metrics['processes'])

                # Check thresholds and perform auto-responses
                alerts = self._check_thresholds(metrics)
                if alerts:
                    self._perform_auto_response(alerts)

                # Log metrics
                logging.info(f"System metrics: {json.dumps(metrics, indent=2)}")

                # Sleep for remaining interval time
                elapsed = time.time() - start_time
                sleep_time = max(0, self.config['interval'] - elapsed)
                time.sleep(sleep_time)

            except Exception as e:
                logging.error(f"Error in monitoring loop: {str(e)}")
                time.sleep(self.config['interval'])

    def start(self):
        """Start the monitoring daemon"""
        if self.running:
            logging.warning("Daemon is already running")
            return

        self.running = True
        logging.info("Starting system monitor daemon")

        # Start monitoring thread
        monitor_thread = threading.Thread(target=self._monitor_loop, daemon=True)
        monitor_thread.start()
        self.threads.append(monitor_thread)

        # Start HTTP server thread (for remote monitoring)
        if self.config.get('http_server', {}).get('enabled', False):
            from http.server import HTTPServer, BaseHTTPRequestHandler
            from threading import Thread

            class MetricsHandler(BaseHTTPRequestHandler):
                def do_GET(self):
                    if self.path == '/metrics':
                        self.send_response(200)
                        self.send_header('Content-type', 'application/json')
                        self.end_headers()
                        metrics = {
                            'timestamp': datetime.now().isoformat(),
                            'history': self.server.metrics_history
                        }
                        self.wfile.write(json.dumps(metrics).encode())
                    else:
                        self.send_response(404)
                        self.end_headers()

            http_server = HTTPServer(('localhost', self.config['http_server']['port']), MetricsHandler)
            http_server.metrics_history = self.metrics_history
            http_server_thread = Thread(target=http_server.serve_forever, daemon=True)
            http_server_thread.start()
            self.threads.append(http_server_thread)
            logging.info(f"HTTP server started on port {self.config['http_server']['port']}")

    def stop(self):
        """Stop the monitoring daemon"""
        if not self.running:
            logging.warning("Daemon is not running")
            return

        self.running = False
        logging.info("Stopping system monitor daemon")

        # Wait for threads to finish
        for thread in self.threads:
            thread.join(timeout=5)

        self.threads = []
        logging.info("Daemon stopped")

    def run(self):
        """Run the daemon (blocking)"""
        self.start()
        try:
            while self.running:
                time.sleep(1)
        except KeyboardInterrupt:
            self.stop()

def main():
    parser = argparse.ArgumentParser(description='High-Performance System Resource Monitor Daemon')
    parser.add_argument('--config', default='monitor_config.json',
                       help='Path to configuration file')
    parser.add_argument('--start', action='store_true',
                       help='Start the daemon')
    parser.add_argument('--stop', action='store_true',
                       help='Stop the daemon')
    parser.add_argument('--restart', action='store_true',
                       help='Restart the daemon')

    args = parser.parse_args()

    # Check if running as root (required for some operations)
    if os.geteuid() != 0:
        print("Warning: This daemon should ideally be run as root for full functionality")

    daemon = SystemMonitorDaemon(args.config)

    if args.start or not (args.stop or args.restart):
        daemon.run()
    elif args.stop:
        daemon.stop()
    elif args.restart:
        daemon.stop()
        time.sleep(1)
        daemon.run()

if __name__ == '__main__':
    main()
```

