# High-Performance System Resource Monitoring Daemon

Below is an initial implementation of a system daemon for monitoring and managing operating system resources. This implementation uses Python for its cross-platform compatibility and ease of development, while still being capable of high-performance operations.

```python
#!/usr/bin/env python3
import os
import sys
import time
import json
import psutil
import signal
import logging
import argparse
from threading import Thread, Event
from collections import deque
from datetime import datetime

class SystemMonitorDaemon:
    def __init__(self, config_file='config.json', log_file='system_monitor.log'):
        self.config = self._load_config(config_file)
        self.log_file = log_file
        self.running = Event()
        self.threads = []
        self.metrics_buffer = deque(maxlen=self.config.get('buffer_size', 1000))
        self.setup_logging()

        # Initialize metrics collectors
        self.metrics_collectors = {
            'cpu': self._collect_cpu_metrics,
            'memory': self._collect_memory_metrics,
            'disk': self._collect_disk_metrics,
            'network': self._collect_network_metrics,
            'process': self._collect_process_metrics
        }

        # Initialize resource managers
        self.resource_managers = {
            'cpu': self._manage_cpu_usage,
            'memory': self._manage_memory_usage,
            'disk': self._manage_disk_usage,
            'process': self._manage_processes
        }

    def _load_config(self, config_file):
        """Load configuration from JSON file"""
        try:
            with open(config_file, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            logging.warning(f"Config file {config_file} not found, using defaults")
            return {
                'interval': 5,
                'buffer_size': 1000,
                'thresholds': {
                    'cpu': 80,
                    'memory': 80,
                    'disk': 80,
                    'process_count': 500
                },
                'actions': {
                    'cpu': 'log',
                    'memory': 'log',
                    'disk': 'log',
                    'process': 'log'
                }
            }

    def setup_logging(self):
        """Configure logging"""
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(self.log_file),
                logging.StreamHandler()
            ]
        )

    def _collect_cpu_metrics(self):
        """Collect CPU metrics"""
        cpu_percent = psutil.cpu_percent(interval=1)
        cpu_times = psutil.cpu_times_percent()
        cpu_count = psutil.cpu_count()

        metrics = {
            'timestamp': datetime.now().isoformat(),
            'cpu_percent': cpu_percent,
            'cpu_times': {
                'user': cpu_times.user,
                'system': cpu_times.system,
                'idle': cpu_times.idle,
                'iowait': cpu_times.iowait
            },
            'cpu_count': cpu_count
        }

        return metrics

    def _collect_memory_metrics(self):
        """Collect memory metrics"""
        mem = psutil.virtual_memory()
        swap = psutil.swap_memory()

        metrics = {
            'timestamp': datetime.now().isoformat(),
            'total': mem.total,
            'available': mem.available,
            'used': mem.used,
            'percent': mem.percent,
            'swap_total': swap.total,
            'swap_used': swap.used,
            'swap_percent': swap.percent
        }

        return metrics

    def _collect_disk_metrics(self):
        """Collect disk metrics"""
        disk_partitions = psutil.disk_partitions()
        metrics = {
            'timestamp': datetime.now().isoformat(),
            'partitions': []
        }

        for partition in disk_partitions:
            try:
                usage = psutil.disk_usage(partition.mountpoint)
                metrics['partitions'].append({
                    'device': partition.device,
                    'mountpoint': partition.mountpoint,
                    'fstype': partition.fstype,
                    'total': usage.total,
                    'used': usage.used,
                    'free': usage.free,
                    'percent': usage.percent
                })
            except Exception as e:
                logging.warning(f"Error getting disk usage for {partition.mountpoint}: {e}")

        return metrics

    def _collect_network_metrics(self):
        """Collect network metrics"""
        net_io = psutil.net_io_counters()
        net_connections = psutil.net_connections()

        metrics = {
            'timestamp': datetime.now().isoformat(),
            'bytes_sent': net_io.bytes_sent,
            'bytes_recv': net_io.bytes_recv,
            'packets_sent': net_io.packets_sent,
            'packets_recv': net_io.packets_recv,
            'connection_count': len(net_connections)
        }

        return metrics

    def _collect_process_metrics(self):
        """Collect process metrics"""
        processes = []
        for proc in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent']):
            try:
                processes.append({
                    'pid': proc.info['pid'],
                    'name': proc.info['name'],
                    'cpu_percent': proc.info['cpu_percent'],
                    'memory_percent': proc.info['memory_percent']
                })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        metrics = {
            'timestamp': datetime.now().isoformat(),
            'process_count': len(processes),
            'top_processes': sorted(processes, key=lambda x: x['cpu_percent'], reverse=True)[:10]
        }

        return metrics

    def _manage_cpu_usage(self, metrics):
        """Manage CPU usage based on thresholds"""
        threshold = self.config['thresholds']['cpu']
        action = self.config['actions']['cpu']

        if metrics['cpu_percent'] > threshold:
            logging.warning(f"High CPU usage detected: {metrics['cpu_percent']}%")
            if action == 'log':
                pass  # Already logging
            elif action == 'kill':
                # Example: kill top CPU processes
                top_processes = sorted(
                    [p for p in psutil.process_iter(['pid', 'cpu_percent'])
                     if p.info['cpu_percent'] is not None],
                    key=lambda x: x.info['cpu_percent'],
                    reverse=True
                )[:5]  # Kill top 5 CPU processes

                for proc in top_processes:
                    try:
                        proc.terminate()
                        logging.info(f"Terminated process {proc.info['pid']} due to high CPU usage")
                    except Exception as e:
                        logging.error(f"Failed to terminate process {proc.info['pid']}: {e}")

    def _manage_memory_usage(self, metrics):
        """Manage memory usage based on thresholds"""
        threshold = self.config['thresholds']['memory']
        action = self.config['actions']['memory']

        if metrics['percent'] > threshold:
            logging.warning(f"High memory usage detected: {metrics['percent']}%")
            if action == 'log':
                pass  # Already logging
            elif action == 'kill':
                # Example: kill top memory processes
                top_processes = sorted(
                    [p for p in psutil.process_iter(['pid', 'memory_percent'])
                     if p.info['memory_percent'] is not None],
                    key=lambda x: x.info['memory_percent'],
                    reverse=True
                )[:5]  # Kill top 5 memory processes

                for proc in top_processes:
                    try:
                        proc.terminate()
                        logging.info(f"Terminated process {proc.info['pid']} due to high memory usage")
                    except Exception as e:
                        logging.error(f"Failed to terminate process {proc.info['pid']}: {e}")

    def _manage_disk_usage(self, metrics):
        """Manage disk usage based on thresholds"""
        threshold = self.config['thresholds']['disk']
        action = self.config['actions']['disk']

        for partition in metrics['partitions']:
            if partition['percent'] > threshold:
                logging.warning(f"High disk usage detected on {partition['mountpoint']}: {partition['percent']}%")
                if action == 'log':
                    pass  # Already logging
                elif action == 'cleanup':
                    # Example: cleanup temporary files
                    try:
                        temp_dir = '/tmp'
                        if partition['mountpoint'] in temp_dir:
                            for root, dirs, files in os.walk(temp_dir):
                                for file in files:
                                    file_path = os.path.join(root, file)
                                    try:
                                        os.remove(file_path)
                                        logging.info(f"Removed temporary file: {file_path}")
                                    except Exception as e:
                                        logging.warning(f"Could not remove {file_path}: {e}")
                    except Exception as e:
                        logging.error(f"Error during disk cleanup: {e}")

    def _manage_processes(self, metrics):
        """Manage process count based on thresholds"""
        threshold = self.config['thresholds']['process_count']
        action = self.config['actions']['process']

        if metrics['process_count'] > threshold:
            logging.warning(f"High process count detected: {metrics['process_count']}")
            if action == 'log':
                pass  # Already logging
            elif action == 'kill':
                # Example: kill oldest processes
                processes = sorted(
                    [p for p in psutil.process_iter(['pid', 'create_time'])
                     if p.info['create_time'] is not None],
                    key=lambda x: x.info['create_time']
                )[:10]  # Kill 10 oldest processes

                for proc in processes:
                    try:
                        proc.terminate()
                        logging.info(f"Terminated process {proc.info['pid']} due to high process count")
                    except Exception as e:
                        logging.error(f"Failed to terminate process {proc.info['pid']}: {e}")

    def _monitor_loop(self):
        """Main monitoring loop"""
        while self.running.is_set():
            start_time = time.time()

            # Collect all metrics
            all_metrics = {}
            for name, collector in self.metrics_collectors.items():
                try:
                    all_metrics[name] = collector()
                except Exception as e:
                    logging.error(f"Error collecting {name} metrics: {e}")

            # Store metrics
            self.metrics_buffer.append(all_metrics)

            # Manage resources
            for name, manager in self.resource_managers.items():
                try:
                    if name in all_metrics:
                        manager(all_metrics[name])
                except Exception as e:
                    logging.error(f"Error managing {name}: {e}")

            # Calculate sleep time to maintain interval
            elapsed = time.time() - start_time
            sleep_time = max(0, self.config['interval'] - elapsed)
            time.sleep(sleep_time)

    def start(self):
        """Start the daemon"""
        if self.running.is_set():
            logging.warning("Daemon is already running")
            return

        self.running.set()
        logging.info("Starting system monitor daemon")

        # Start monitoring thread
        monitor_thread = Thread(target=self._monitor_loop, daemon=True)
        monitor_thread.start()
        self.threads.append(monitor_thread)

        # Start API server if enabled
        if self.config.get('enable_api', False):
            from flask import Flask, jsonify
            app = Flask(__name__)

            @app.route('/metrics')
            def get_metrics():
                return jsonify(list(self.metrics_buffer))

            @app.route('/status')
            def get_status():
                return jsonify({
                    'status': 'running',
                    'buffer_size': len(self.metrics_buffer),
                    'last_update': datetime.now().isoformat()
                })

            api_thread = Thread(target=lambda: app.run(
                host=self.config.get('api_host', '0.0.0.0'),
                port=self.config.get('api_port', 5000),
                threaded=True
            ), daemon=True)
            api_thread.start()
            self.threads.append(api_thread)

    def stop(self):
        """Stop the daemon"""
        if not self.running.is_set():
            logging.warning("Daemon is not running")
            return

        logging.info("Stopping system monitor daemon")
        self.running.clear()

        # Wait for threads to finish
        for thread in self.threads:
            thread.join(timeout=5)

        self.threads = []

    def signal_handler(self, signum, frame):
        """Handle termination signals"""
        logging.info(f"Received signal {signum}, shutting down...")
        self.stop()
        sys.exit(0)

def main():
    parser = argparse.ArgumentParser(description='System Resource Monitor Daemon')
    parser.add_argument('--config', default='config.json', help='Path to configuration file')
    parser.add_argument('--log', default='system_monitor.log', help='Path to log file')
    args = parser.parse_args()

    daemon = SystemMonitorDaemon(config_file=args.config, log_file=args.log)

    # Set up signal handlers
    signal.signal(signal.SIGINT, daemon.signal_handler)
    signal.signal(signal.SIGTERM, daemon.signal_handler)

    # Start the daemon
    daemon.start()

    # Keep main thread alive
    try:
        while daemon.running.is_set():
            time.sleep(1)
    except KeyboardInterrupt:
        daemon.stop()

if __name__ == '__main__':
    main()
