    }
};

// Hash function for FlowKey
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& k) const {
            return ((hash<uint32_t>()(k.src_ip) ^
                    (hash<uint32_t>()(k.dst_ip) << 1)) >> 1) ^
                   (hash<uint16_t>()(k.src_port) ^
                    (hash<uint16_t>()(k.dst_port) << 1)) ^
                   hash<uint8_t>()(k.protocol);
        }
    };
}

// Flow statistics
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t start_time = 0;
    uint64_t last_seen = 0;
};

// Main flow analyzer class
class FlowAnalyzer {
private:
    std::unordered_map<FlowKey, FlowStats> active_flows;
    std::mutex flow_mutex;
    std::atomic<bool> running{true};
    std::atomic<uint64_t> total_packets{0};
    std::atomic<uint64_t> total_bytes{0};
    std::atomic<uint64_t> active_flow_count{0};

    // Packet processing thread
    void process_packet(const u_char* packet, struct pcap_pkthdr* header) {
        const struct ether_header* eth_header = reinterpret_cast<const struct ether_header*>(packet);
        if (ntohs(eth_header->ether_type) != ETHERTYPE_IP) {
            return; // Not an IP packet
        }

        const struct ip* ip_header = reinterpret_cast<const struct ip*>(packet + sizeof(struct ether_header));
        uint8_t protocol = ip_header->ip_p;
        uint16_t src_port = 0, dst_port = 0;

        if (protocol == IPPROTO_TCP) {
            const struct tcphdr* tcp_header = reinterpret_cast<const struct tcphdr*>(packet + sizeof(struct ether_header) + (ip_header->ip_hl << 2));
            src_port = ntohs(tcp_header->th_sport);
            dst_port = ntohs(tcp_header->th_dport);
        } else if (protocol == IPPROTO_UDP) {
            const struct udphdr* udp_header = reinterpret_cast<const struct udphdr*>(packet + sizeof(struct ether_header) + (ip_header->ip_hl << 2));
            src_port = ntohs(udp_header->uh_sport);
            dst_port = ntohs(udp_header->uh_dport);
        } else {
            // Skip non-TCP/UDP traffic
            return;
        }

        FlowKey key{
            ip_header->ip_src.s_addr,
            ip_header->ip_dst.s_addr,
            src_port,
            dst_port,
            protocol
        };

        uint64_t current_time = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        std::lock_guard<std::mutex> lock(flow_mutex);

        auto it = active_flows.find(key);
        if (it != active_flows.end()) {
            it->second.packets++;
            it->second.bytes += header->len;
            it->second.last_seen = current_time;
        } else {
            if (active_flows.size() >= MAX_FLOWS) {
                // Remove oldest flow if we've hit the limit
                auto oldest = std::min_element(active_flows.begin(), active_flows.end(),
                    [](const auto& a, const auto& b) {
                        return a.second.last_seen < b.second.last_seen;
                    });
                active_flows.erase(oldest);
                active_flow_count--;
            }

            active_flows[key] = FlowStats{
                1,
                header->len,
                current_time,
                current_time
            };
            active_flow_count++;
        }

        total_packets++;
        total_bytes += header->len;
    }

    // Flow expiration thread
    void expire_flows() {
        while (running) {
            std::this_thread::sleep_for(std::chrono::seconds(1));

            uint64_t current_time = std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()).count();

            std::lock_guard<std::mutex> lock(flow_mutex);

            for (auto it = active_flows.begin(); it != active_flows.end(); ) {
                if (current_time - it->second.last_seen > FLOW_TIMEOUT_SECONDS) {
                    // Flow expired, remove it
                    it = active_flows.erase(it);
                    active_flow_count--;
                } else {
                    ++it;
                }
            }
        }
    }

public:
    FlowAnalyzer() {
        // Start flow expiration thread
        std::thread(&FlowAnalyzer::expire_flows, this).detach();
    }

    ~FlowAnalyzer() {
        running = false;
    }

    // Callback for pcap to process packets
    static void packet_handler(u_char* user, const struct pcap_pkthdr* header, const u_char* packet) {
        FlowAnalyzer* analyzer = reinterpret_cast<FlowAnalyzer*>(user);
        analyzer->process_packet(packet, const_cast<struct pcap_pkthdr*>(header));
    }

    // Start capturing packets
    void start_capture(const char* device) {
        char errbuf[PCAP_ERRBUF_SIZE];
        pcap_t* handle = pcap_open_live(device, MAX_PACKET_SIZE, 1, 1000, errbuf);

        if (handle == nullptr) {
            std::cerr << "Couldn't open device " << device << ": " << errbuf << std::endl;
            return;
        }

        // Set non-blocking mode for better performance
        if (pcap_setnonblock(handle, 1, errbuf) == -1) {
            std::cerr << "Couldn't set non-blocking mode: " << errbuf << std::endl;
            pcap_close(handle);
            return;
        }

        std::cout << "Starting capture on " << device << std::endl;

        // Main packet processing loop
        while (running) {
            struct pcap_pkthdr* header;
            const u_char* packet;
            int res = pcap_next_ex(handle, &header, &packet);

            if (res == 1) {
                packet_handler(reinterpret_cast<u_char*>(this), header, packet);
            } else if (res == -1) {
                std::cerr << "Error reading packet: " << pcap_geterr(handle) << std::endl;
                break;
            } else if (res == -2) {
                // No packets available, yield CPU
                std::this_thread::yield();
            }
        }

        pcap_close(handle);
    }

    // Print statistics
    void print_stats() {
        std::lock_guard<std::mutex> lock(flow_mutex);

        std::cout << "\n=== Network Flow Statistics ===" << std::endl;
        std::cout << "Total packets processed: " << total_packets << std::endl;
        std::cout << "Total bytes processed: " << total_bytes << std::endl;
        std::cout << "Active flows: " << active_flow_count << std::endl;
        std::cout << "Flows in map: " << active_flows.size() << std::endl;

        // Print top 10 flows by bytes
        std::vector<std::pair<FlowKey, FlowStats>> flows(active_flows.begin(), active_flows.end());
        std::sort(flows.begin(), flows.end(),
            [](const auto& a, const auto& b) {
                return a.second.bytes > b.second.bytes;
            });

        std::cout << "\nTop 10 flows by bytes:" << std::endl;
        for (size_t i = 0; i < std::min(flows.size(), size_t(10)); ++i) {
            const auto& flow = flows[i];
            char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &(flow.first.src_ip), src_ip, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &(flow.first.dst_ip), dst_ip, INET_ADDRSTRLEN);

            std::cout << i+1 << ". " << src_ip << ":" << flow.first.src_port
                      << " -> " << dst_ip << ":" << flow.first.dst_port
                      << " (" << (flow.first.protocol == IPPROTO_TCP ? "TCP" : "UDP") << ")"
                      << " - " << flow.second.bytes << " bytes, "
                      << flow.second.packets << " packets" << std::endl;
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>" << std::endl;
        return 1;
    }

    FlowAnalyzer analyzer;
    std::thread capture_thread(&FlowAnalyzer::start_capture, &analyzer, argv[1]);

    // Print stats every 5 seconds
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(5));
        analyzer.print_stats();
    }

    capture_thread.join();
    return 0;
}
```

## Key Performance Features:

1. **Efficient Data Structures**:
   - Uses `unordered_map` for O(1) average case flow lookups
   - Custom hash function for `FlowKey` to minimize collisions

2. **Memory Management**:
   - Limits maximum number of active flows to prevent memory exhaustion
   - Automatically removes expired flows (older than 30 seconds)

3. **Concurrency**:
   - Separate thread for flow expiration to avoid blocking packet processing
   - Atomic counters for thread-safe statistics collection

4. **Optimized Packet Processing**:
   - Non-blocking pcap mode for better performance
   - Direct memory access to packet headers
   - Minimal copying of packet data

5. **Scalability**:
   - Handles up to 1 million flows (configurable)
   - Efficient memory usage with simple flow statistics

