#define LED_PIN 13               // Built-in LED for status

// Constants
const float VCC = 5.0;           // Reference voltage
const float TEMP_SENSOR_VOLTAGE = 1.0; // Voltage at 0°C for TMP36
const float TEMP_SENSOR_SCALE = 10.0;  // mV per °C

// Variables
float temperature = 0.0;
float lightIntensity = 0.0;
bool buttonState = false;
unsigned long lastReadTime = 0;
const unsigned long READ_INTERVAL = 1000; // ms

void setup() {
  // Initialize serial communication
  Serial.begin(9600);
  while (!Serial); // Wait for serial port to connect (for USB-based boards)

  // Initialize pins
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);

  // Initial status
  digitalWrite(LED_PIN, HIGH);
  Serial.println("Sensor Processing Firmware Initialized");
  Serial.println("--------------------------------------");

  // Initial sensor read
  readSensors();
  processData();
}

void loop() {
  // Check if it's time to read sensors
  if (millis() - lastReadTime >= READ_INTERVAL) {
    lastReadTime = millis();

    // Read and process sensor data
    readSensors();
    processData();

    // Toggle LED to show activity
    digitalWrite(LED_PIN, !digitalRead(LED_PIN));
  }

  // Check button state
  checkButton();
}

void readSensors() {
  // Read temperature sensor (TMP36)
  int tempRaw = analogRead(TEMP_SENSOR_PIN);
  float tempVoltage = (tempRaw / 1023.0) * VCC;
  temperature = (tempVoltage - TEMP_SENSOR_VOLTAGE) * TEMP_SENSOR_SCALE;

  // Read light sensor (photoresistor)
  int lightRaw = analogRead(LIGHT_SENSOR_PIN);
  lightIntensity = (lightRaw / 1023.0) * 100.0; // Scale to 0-100%

  // Read button state
  buttonState = !digitalRead(BUTTON_PIN); // Invert because of pull-up
}

void processData() {
  // Print sensor data
  Serial.print("Temperature: ");
  Serial.print(temperature, 1);
  Serial.print("°C | Light: ");
  Serial.print(lightIntensity, 0);
  Serial.print("% | Button: ");
  Serial.println(buttonState ? "Pressed" : "Released");

  // Example processing: Check for temperature threshold
  if (temperature > 30.0) {
    Serial.println("Warning: High temperature detected!");
    // Could add additional actions here (e.g., trigger alarm)
  }

  // Example processing: Check for light threshold
  if (lightIntensity < 20.0) {
    Serial.println("Warning: Low light detected!");
    // Could add additional actions here (e.g., turn on lights)
  }
}

void checkButton() {
  static bool lastButtonState = false;

  if (buttonState != lastButtonState) {
    lastButtonState = buttonState;

    if (buttonState) {
      Serial.println("Button pressed - performing action...");
      // Add button press action here
    }
  }
}
