// Sensor configuration
const int SENSOR_PIN = A0;      // Analog input pin for sensor
const int SAMPLE_COUNT = 10;   // Number of samples for averaging
const float VOLTAGE_REF = 3.3; // Reference voltage (adjust based on your board)
const float SENSOR_MAX_VOLTS = 3.0; // Maximum voltage from sensor

// Filter parameters
const float ALPHA = 0.1;       // Smoothing factor for exponential filter (0-1)

// Global variables
float sensorValue = 0;
float filteredValue = 0;
float minValue = 1023;
float maxValue = 0;

void setup() {
  Serial.begin(115200);
  while (!Serial); // Wait for serial port to connect (for boards with native USB)

  pinMode(SENSOR_PIN, INPUT);

  Serial.println("Sensor Data Processing Firmware");
  Serial.println("-------------------------------");
  Serial.println("Initializing...");

  // Initial calibration
  calibrateSensor();

  Serial.println("Ready to process sensor data");
}

void loop() {
  // Read and process sensor data
  readSensorData();

  // Apply filtering
  applyFilter();

  // Calculate statistics
  updateStatistics();

  // Output results
  printResults();

  delay(100); // Adjust based on your sampling rate requirements
}

// Function to read raw sensor data
void readSensorData() {
  // Read multiple samples and average them
  long sum = 0;
  for (int i = 0; i < SAMPLE_COUNT; i++) {
    sum += analogRead(SENSOR_PIN);
    delay(1); // Small delay between samples
  }
  sensorValue = (float)sum / SAMPLE_COUNT;
}

// Apply exponential filter to smooth the data
void applyFilter() {
  filteredValue = ALPHA * sensorValue + (1 - ALPHA) * filteredValue;
}

// Update min/max statistics
void updateStatistics() {
  if (sensorValue < minValue) minValue = sensorValue;
  if (sensorValue > maxValue) maxValue = sensorValue;
}

// Convert ADC reading to voltage
float adcToVoltage(int adcValue) {
  return (adcValue / 1023.0) * VOLTAGE_REF;
}

// Convert voltage to sensor-specific units (example)
float voltageToSensorUnits(float voltage) {
  // This is just an example - replace with your actual sensor conversion
  return (voltage / SENSOR_MAX_VOLTS) * 100.0; // Example: 0-100% scale
}

// Print results to serial monitor
void printResults() {
  float voltage = adcToVoltage(sensorValue);
  float sensorUnits = voltageToSensorUnits(voltage);

