    Wire.beginTransmission(I2C_SENSOR_ADDRESS);
    Wire.write(0x00); // Register to read from
    Wire.endTransmission(false);

    Wire.requestFrom(I2C_SENSOR_ADDRESS, 2); // Request 2 bytes
    if (Wire.available() >= 2) {
        uint8_t msb = Wire.read();
        uint8_t lsb = Wire.read();
        currentData.i2cValue = (msb << 8) | lsb;

        // Optional: Convert to actual units based on sensor datasheet
    }
}

