    // Example SPI read (adjust for your specific sensor)
    digitalWrite(SPI_CS_PIN, LOW); // Select device
    delayMicroseconds(10); // Small delay for chip select setup

    // Example: Read 2 bytes (MSB first)
    uint8_t msb = SPI.transfer(0x00); // Send dummy byte to read MSB
    uint8_t lsb = SPI.transfer(0x00); // Send dummy byte to read LSB

    digitalWrite(SPI_CS_PIN, HIGH); // Deselect device

    currentData.spiValue = (msb << 8) | lsb;

    // Optional: Convert to actual units based on sensor datasheet
}

