    float processedValue = 0.0;

    // Weighted average (adjust weights as needed)
    processedValue += currentData.analogValue * 0.3;
    processedValue += (currentData.digitalState ? 1.0 : 0.0) * 0.2;
    processedValue += currentData.i2cValue * 0.3;
    processedValue += currentData.spiValue * 0.2;

    return processedValue;
}

void updateMovingAverage(float newValue) {
    // Shift all values in the buffer
    for (int i = 0; i < MOVING_AVG_WINDOW - 1; i++) {
        movingAverageBuffer[i] = movingAverageBuffer[i + 1];
    }

    // Add new value to the end
    movingAverageBuffer[MOVING_AVG_WINDOW - 1] = newValue;

    // Calculate average (optional - could be done on demand)
    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_WINDOW; i++) {
        sum += movingAverageBuffer[i];
    }
    movingAverageBuffer[MOVING_AVG_WINDOW - 1] = sum / MOVING_AVG_WINDOW;
}
