    // Initialize sensor pins
    pinMode(ANALOG_SENSOR_PIN, INPUT);
    pinMode(DIGITAL_SENSOR_PIN, INPUT_PULLUP);

    // Initialize moving average array
    for (int i = 0; i < MOVING_AVG_WINDOW; i++) {
        analogReadings[i] = analogRead(ANALOG_SENSOR_PIN);
    }

    Serial.println("Sensor Processing Firmware Initialized");
