    unsigned long currentTime = millis();

    // Read sensors at regular intervals
    if (currentTime - lastReadTime >= SENSOR_READ_INTERVAL) {
        lastReadTime = currentTime;
        readSensors();
    }

    // Add a small delay to prevent watchdog timer issues
    delay(10);
}

void readSensors() {
    // Read analog sensor
    int analogValue = analogRead(ANALOG_SENSOR_PIN);
    processAnalogData(analogValue);

    // Read digital sensor
    bool digitalValue = digitalRead(DIGITAL_SENSOR_PIN);
    processDigitalData(digitalValue);
}

void processAnalogData(int rawValue) {
    // Calculate moving average
    movingAverage = calculateMovingAverage(rawValue);

    // Check against threshold
    if (movingAverage > THRESHOLD_VALUE) {
        Serial.print("Warning: High sensor value detected! ");
        Serial.print("Raw: ");
        Serial.print(rawValue);
        Serial.print(", Avg: ");
        Serial.println(movingAverage);
    }

    // Print periodic status
    Serial.print("Analog Sensor - Raw: ");
    Serial.print(rawValue);
    Serial.print(", Moving Avg: ");
    Serial.println(movingAverage);
}

void processDigitalData(bool state) {
    // Check for state change
    if (state != digitalSensorState) {
        digitalSensorState = state;
        Serial.print("Digital Sensor State Changed: ");
        Serial.println(state ? "HIGH" : "LOW");

        // Add your digital sensor processing logic here
    }
}

float calculateMovingAverage(int newValue) {
    // Remove the oldest value from the sum
    movingAverage -= (float)analogReadings[readingIndex] / MOVING_AVG_WINDOW;

    // Add the new value to the array
    analogReadings[readingIndex] = newValue;

    // Add the new value to the sum
    movingAverage += (float)newValue / MOVING_AVG_WINDOW;

    // Update the index
    readingIndex = (readingIndex + 1) % MOVING_AVG_WINDOW;

    return movingAverage;
}
