    Serial.print("Digital Sensor: ");
    Serial.println(digitalValue ? "HIGH" : "LOW");

    // Add your digital data processing here
    // Example: Trigger action on state change
    static int lastDigitalValue = -1;
    if (digitalValue != lastDigitalValue) {
        Serial.print("Digital sensor state changed to: ");
        Serial.println(digitalValue ? "HIGH" : "LOW");
        lastDigitalValue = digitalValue;
    }
}

float calculateMovingAverage() {
    float sum = 0;
    for (int i = 0; i < MOVING_AVG_WINDOW; i++) {
        sum += analogValues[i];
    }
    return sum / MOVING_AVG_WINDOW;
}
