    // Subtract the oldest value from the moving sum
    moving_sum -= moving_buffer[moving_index];

    // Store the new value in the buffer
    moving_buffer[moving_index] = raw_value;

    // Add the new value to the moving sum
    moving_sum += raw_value;

    // Update the moving index (circular buffer)
    moving_index = (moving_index + 1) % MOVING_AVG_SIZE;

    // Calculate the new moving average
    moving_avg = moving_sum / MOVING_AVG_SIZE;
