# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation is designed for resource-constrained embedded systems but can be adapted for more powerful platforms.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter and normalize the data
3. **Feature Extraction**: Compute relevant features
4. **Anomaly Detection**: Use statistical methods to detect anomalies
5. **Action**: Trigger alerts or logging when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in analysis window
constexpr float ANOMALY_THRESHOLD = 3.0f;  // Standard deviations for anomaly detection
constexpr float MOVING_AVG_ALPHA = 0.1f;  // Smoothing factor for moving average

// Data structure for accelerometer sample
struct AccelSample {
    float x;
    float y;
    float z;
    float magnitude;
};

// Circular buffer for storing recent samples
class SampleBuffer {
private:
    std::vector<AccelSample> buffer;
    size_t head = 0;
    size_t count = 0;

public:
    SampleBuffer(size_t size) : buffer(size) {}

    void addSample(const AccelSample& sample) {
        buffer[head] = sample;
        head = (head + 1) % buffer.size();
        if (count < buffer.size()) count++;
    }

    const AccelSample& getSample(size_t index) const {
        return buffer[(head - 1 - index + buffer.size()) % buffer.size()];
    }

    size_t size() const { return count; }
    bool isFull() const { return count == buffer.size(); }
};

// Feature extraction functions
float calculateMagnitude(const AccelSample& sample) {
    return std::sqrt(sample.x*sample.x + sample.y*sample.y + sample.z*sample.z);
}

float calculateMeanMagnitude(const SampleBuffer& buffer) {
    float sum = 0.0f;
    for (size_t i = 0; i < buffer.size(); i++) {
        sum += buffer.getSample(i).magnitude;
    }
    return sum / buffer.size();
}

float calculateStdDev(const SampleBuffer& buffer, float mean) {
    float sum = 0.0f;
    for (size_t i = 0; i < buffer.size(); i++) {
        float diff = buffer.getSample(i).magnitude - mean;
        sum += diff * diff;
    }
    return std::sqrt(sum / buffer.size());
}

// Anomaly detection class
class AnomalyDetector {
private:
    SampleBuffer buffer;
    float movingAvg = 0.0f;
    float movingStdDev = 0.0f;

public:
    AnomalyDetector() : buffer(WINDOW_SIZE) {}

    void processSample(float x, float y, float z) {
        AccelSample sample{x, y, z, calculateMagnitude({x, y, z, 0})};
        buffer.addSample(sample);

        if (buffer.isFull()) {
            // Calculate statistics
            float mean = calculateMeanMagnitude(buffer);
            float stdDev = calculateStdDev(buffer, mean);

            // Update moving averages (exponential smoothing)
            if (movingAvg == 0.0f) {
                movingAvg = mean;
                movingStdDev = stdDev;
            } else {
                movingAvg = MOVING_AVG_ALPHA * mean + (1 - MOVING_AVG_ALPHA) * movingAvg;
                movingStdDev = MOVING_AVG_ALPHA * stdDev + (1 - MOVING_AVG_ALPHA) * movingStdDev;
            }
        }
    }

    bool isAnomaly(float x, float y, float z) {
        if (!buffer.isFull()) return false;

        float currentMag = calculateMagnitude({x, y, z, 0});
        float zScore = (currentMag - movingAvg) / (movingStdDev + 1e-6f); // Small epsilon to avoid division by zero

        return std::abs(zScore) > ANOMALY_THRESHOLD;
    }
};

// Example usage
int main() {
    AnomalyDetector detector;

    // Simulate sensor data (in a real system, this would come from hardware)
    for (int i = 0; i < 1000; i++) {
        // Normal data (1g in z-axis)
        float x = static_cast<float>(rand() % 100) / 1000.0f - 0.05f;
        float y = static_cast<float>(rand() % 100) / 1000.0f - 0.05f;
