#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint32_t WINDOW_SIZE = 50;  // Number of samples in sliding window
constexpr float THRESHOLD_MULTIPLIER = 3.0f;  // Standard deviations for anomaly detection
constexpr float GRAVITY = 9.81f;  // m/s², for normalization

// Data structure for accelerometer readings
struct AccelData {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Circular buffer for storing recent samples
class AccelBuffer {
private:
    std::vector<AccelData> buffer;
    size_t head = 0;
    size_t count = 0;

public:
    AccelBuffer(size_t size) : buffer(size) {}

    void addSample(const AccelData& sample) {
        buffer[head] = sample;
        head = (head + 1) % buffer.size();
        if (count < buffer.size()) count++;
    }

    bool isFull() const { return count == buffer.size(); }
    size_t size() const { return count; }

    const AccelData& operator[](size_t index) const {
        return buffer[(head + index) % buffer.size()];
    }
};

// Feature extraction and anomaly detection
class AnomalyDetector {
private:
    AccelBuffer buffer;
    float mean_mag = 0.0f;
    float stddev_mag = 0.0f;
    bool initialized = false;

    // Calculate magnitude of acceleration vector
    float calculateMagnitude(const AccelData& data) {
        return std::sqrt(data.x*data.x + data.y*data.y + data.z*data.z);
    }

    // Update statistics for the current window
    void updateStatistics() {
        if (!buffer.isFull()) return;

        // Calculate magnitudes
        std::vector<float> magnitudes;
        magnitudes.reserve(buffer.size());
        for (size_t i = 0; i < buffer.size(); ++i) {
            magnitudes.push_back(calculateMagnitude(buffer[i]));
        }

        // Calculate mean
        mean_mag = std::accumulate(magnitudes.begin(), magnitudes.end(), 0.0f) / magnitudes.size();

        // Calculate standard deviation
        float variance = 0.0f;
        for (float mag : magnitudes) {
            variance += (mag - mean_mag) * (mag - mean_mag);
        }
        variance /= magnitudes.size();
        stddev_mag = std::sqrt(variance);

        initialized = true;
    }

public:
    AnomalyDetector() : buffer(WINDOW_SIZE) {}

    // Process new accelerometer data
    bool processSample(const AccelData& sample) {
        buffer.addSample(sample);
        updateStatistics();

        if (!initialized) return false;

        float current_mag = calculateMagnitude(sample);
        float upper_threshold = mean_mag + THRESHOLD_MULTIPLIER * stddev_mag;
        float lower_threshold = mean_mag - THRESHOLD_MULTIPLIER * stddev_mag;

        // Check for anomalies
        if (current_mag > upper_threshold || current_mag < lower_threshold) {
            return true;  // Anomaly detected
        }

        return false;
    }

    // Get current statistics (for debugging/display)
    void getStatistics(float& mean, float& stddev) const {
        mean = mean_mag;
        stddev = stddev_mag;
    }
};

