// Main processing loop
void process_accelerometer_data() {
    static AccelBuffer raw_data = {0};
    static FeatureStats stats = {0};
    static float feature_buffer[FEATURE_WINDOW] = {0};
    static uint8_t feature_idx = 0;

    // 1. Data Acquisition
    float accel_x, accel_y, accel_z;
    read_accelerometer(&accel_x, &accel_y, &accel_z);

    // 2. Store in circular buffer
    raw_data.x[raw_data.head] = accel_x;
    raw_data.y[raw_data.head] = accel_y;
    raw_data.z[raw_data.head] = accel_z;
    raw_data.head = (raw_data.head + 1) % WINDOW_SIZE;

    // 3. Preprocessing (simple moving average filter)
    float filtered_x = moving_average(raw_data.x, WINDOW_SIZE, 3);
    float filtered_y = moving_average(raw_data.y, WINDOW_SIZE, 3);
    float filtered_z = moving_average(raw_data.z, WINDOW_SIZE, 3);

    // 4. Feature Extraction
    float magnitude = sqrt(filtered_x*filtered_x + filtered_y*filtered_y + filtered_z*filtered_z);

    // Update feature buffer
    feature_buffer[feature_idx] = magnitude;
    feature_idx = (feature_idx + 1) % FEATURE_WINDOW;

    // Calculate current feature statistics
    float current_mean = calculate_mean(feature_buffer, FEATURE_WINDOW);
    float current_std = calculate_std(feature_buffer, FEATURE_WINDOW, current_mean);

    // 5. Anomaly Detection
    float z_score = fabs(current_mean - stats.mean_magnitude) / stats.std_dev_magnitude;

    if (z_score > ANOMALY_THRESHOLD) {
        // Anomaly detected!
        trigger_anomaly_response();
    }

    // Periodically update statistics (e.g., every 100 samples)
    static uint16_t update_counter = 0;
    if (++update_counter >= 100) {
        update_counter = 0;
        update_statistics(&raw_data, &stats);
    }
}

// Helper functions
float moving_average(float *data, uint8_t size, uint8_t window) {
    float sum = 0;
    uint8_t count = 0;

    for (int i = 0; i < window; i++) {
        sum += data[(size + i - window) % size];
        count++;
    }

    return sum / count;
}

float calculate_mean(float *data, uint8_t size) {
    float sum = 0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

float calculate_std(float *data, uint8_t size, float mean) {
    float sum = 0;
    for (int i = 0; i < size; i++) {
        float diff = data[i] - mean;
        sum += diff * diff;
    }
    return sqrt(sum / size);
}

void update_statistics(AccelBuffer *raw_data, FeatureStats *stats) {
    // Calculate statistics over the entire window
    float sum_x = 0, sum_y = 0, sum_z = 0, sum_mag = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0, sum_sq_mag = 0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        float mag = sqrt(raw_data->x[i]*raw_data->x[i] +
                        raw_data->y[i]*raw_data->y[i] +
                        raw_data->z[i]*raw_data->z[i]);

        sum_x += raw_data->x[i];
        sum_y += raw_data->y[i];
        sum_z += raw_data->z[i];
        sum_mag += mag;

        sum_sq_x += raw_data->x[i] * raw_data->x[i];
        sum_sq_y += raw_data->y[i] * raw_data->y[i];
        sum_sq_z += raw_data->z[i] * raw_data->z[i];
        sum_sq_mag += mag * mag;
    }

    // Update means
    stats->mean_x = sum_x / WINDOW_SIZE;
    stats->mean_y = sum_y / WINDOW_SIZE;
    stats->mean_z = sum_z / WINDOW_SIZE;
    stats->mean_magnitude = sum_mag / WINDOW_SIZE;

    // Update standard deviations
    stats->std_dev_magnitude = sqrt((sum_sq_mag / WINDOW_SIZE) -
                                  (stats->mean_magnitude * stats->mean_magnitude));
}

void trigger_anomaly_response() {
    // Implement appropriate response based on your application
    // Could be LED alert, vibration, or communication to host
    set_alert_led(1);
    log_anomaly_event();
}
