#include <math.h>
#include <stdbool.h>

// Configuration parameters
#define SAMPLE_RATE_HZ 100          // 100Hz sampling rate
#define WINDOW_SIZE 50              // 50 samples (0.5 seconds)
#define THRESHOLD_MULTIPLIER 3.0    // 3 standard deviations for anomaly detection

// Circular buffer for storing accelerometer data
typedef struct {
    float x[WINDOW_SIZE];
    float y[WINDOW_SIZE];
    float z[WINDOW_SIZE];
    int index;
} AccelBuffer;

// Statistics structure
typedef struct {
    float mean_x, mean_y, mean_z;
    float stddev_x, stddev_y, stddev_z;
    float magnitude_mean;
    float magnitude_stddev;
} AccelStats;

// Initialize the buffer
void initBuffer(AccelBuffer *buffer) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        buffer->x[i] = 0.0;
        buffer->y[i] = 0.0;
        buffer->z[i] = 0.0;
    }
    buffer->index = 0;
}

// Add new accelerometer reading to buffer
void addReading(AccelBuffer *buffer, float x, float y, float z) {
    buffer->x[buffer->index] = x;
    buffer->y[buffer->index] = y;
    buffer->z[buffer->index] = z;
    buffer->index = (buffer->index + 1) % WINDOW_SIZE;
}

// Calculate basic statistics for the current window
void calculateStats(AccelBuffer *buffer, AccelStats *stats) {
    // Calculate means
    float sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_x += buffer->x[i];
        sum_y += buffer->y[i];
        sum_z += buffer->z[i];
    }

    stats->mean_x = sum_x / WINDOW_SIZE;
    stats->mean_y = sum_y / WINDOW_SIZE;
    stats->mean_z = sum_z / WINDOW_SIZE;

    // Calculate standard deviations
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_sq_x += pow(buffer->x[i] - stats->mean_x, 2);
        sum_sq_y += pow(buffer->y[i] - stats->mean_y, 2);
        sum_sq_z += pow(buffer->z[i] - stats->mean_z, 2);
    }

    stats->stddev_x = sqrt(sum_sq_x / WINDOW_SIZE);
    stats->stddev_y = sqrt(sum_sq_y / WINDOW_SIZE);
    stats->stddev_z = sqrt(sum_sq_z / WINDOW_SIZE);

    // Calculate magnitude statistics
    float sum_mag = 0, sum_sq_mag = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float mag = sqrt(pow(buffer->x[i], 2) + pow(buffer->y[i], 2) + pow(buffer->z[i], 2));
        sum_mag += mag;
        sum_sq_mag += pow(mag, 2);
    }

    stats->magnitude_mean = sum_mag / WINDOW_SIZE;
    stats->magnitude_stddev = sqrt(sum_sq_mag / WINDOW_SIZE - pow(stats->magnitude_mean, 2));
}

// Detect anomalies based on statistical thresholds
bool detectAnomaly(AccelStats *stats, float current_x, float current_y, float current_z) {
    // Calculate current magnitude
    float current_mag = sqrt(pow(current_x, 2) + pow(current_y, 2) + pow(current_z, 2));

    // Check if any axis or magnitude exceeds threshold
    if (fabs(current_x - stats->mean_x) > THRESHOLD_MULTIPLIER * stats->stddev_x ||
        fabs(current_y - stats->mean_y) > THRESHOLD_MULTIPLIER * stats->stddev_y ||
        fabs(current_z - stats->mean_z) > THRESHOLD_MULTIPLIER * stats->stddev_z ||
        fabs(current_mag - stats->magnitude_mean) > THRESHOLD_MULTIPLIER * stats->magnitude_stddev) {
        return true;
    }

    return false;
}

// Main processing loop
void processAccelerometerData(float x, float y, float z) {
    static AccelBuffer buffer;
    static AccelStats stats;
    static bool initialized = false;

    if (!initialized) {
        initBuffer(&buffer);
        initialized = true;
    }

    // Add new reading to buffer
    addReading(&buffer, x, y, z);

    // Calculate statistics every WINDOW_SIZE samples
    if (buffer.index == 0) {
        calculateStats(&buffer, &stats);
    }

    // Detect anomaly
    if (detectAnomaly(&stats, x, y, z)) {
        // Trigger alert (implementation depends on your system)
        triggerAlert();
    }
}

// Example alert function (to be implemented based on your system)
void triggerAlert() {
    // This would typically:
    // - Turn on an LED
    // - Send a signal to another component
    // - Log the event
    // - Trigger a buzzer or vibration
    // Implementation depends on your hardware
}
