#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_ADXL345_U.h>

// Configuration
#define SAMPLE_RATE_HZ 50       // 50 samples per second
#define WINDOW_SIZE 50           // 1-second window (50 samples at 50Hz)
#define ANOMALY_THRESHOLD 2.5   // Z-score threshold for anomaly detection

// Sensor object
Adafruit_ADXL345_Unified accel = Adafruit_ADXL345_Unified(12345);

// Data buffers
float accelX[WINDOW_SIZE];
float accelY[WINDOW_SIZE];
float accelZ[WINDOW_SIZE];
float accelMagnitude[WINDOW_SIZE];

// Statistical features
float meanX, meanY, meanZ, meanMag;
float stdDevX, stdDevY, stdDevZ, stdDevMag;

// Setup function
void setup() {
  Serial.begin(115200);

  // Initialize accelerometer
  if (!accel.begin()) {
    Serial.println("No ADXL345 detected!");
    while (1);
  }

  // Set range to ±16g (adjust based on your needs)
  accel.setRange(ADXL345_RANGE_16_G);

  // Initialize data buffers
  for (int i = 0; i < WINDOW_SIZE; i++) {
    accelX[i] = 0;
    accelY[i] = 0;
    accelZ[i] = 0;
    accelMagnitude[i] = 0;
  }

  Serial.println("Anomaly Detection System Initialized");
}

// Main loop
void loop() {
  // Read accelerometer data
  sensors_event_t event;
  accel.getEvent(&event);

  // Shift old data and add new sample
  for (int i = WINDOW_SIZE - 1; i > 0; i--) {
    accelX[i] = accelX[i-1];
    accelY[i] = accelY[i-1];
    accelZ[i] = accelZ[i-1];
    accelMagnitude[i] = accelMagnitude[i-1];
  }

  // Add new sample
  accelX[0] = event.acceleration.x;
  accelY[0] = event.acceleration.y;
  accelZ[0] = event.acceleration.z;
  accelMagnitude[0] = sqrt(pow(event.acceleration.x, 2) +
                          pow(event.acceleration.y, 2) +
                          pow(event.acceleration.z, 2));

  // Calculate statistics
  calculateStatistics();

  // Detect anomalies
  bool anomalyDetected = detectAnomalies();

  if (anomalyDetected) {
    Serial.println("ANOMALY DETECTED!");
    // Add your alerting mechanism here (LED, buzzer, etc.)
  }

  // Delay to maintain sample rate
  delay(1000 / SAMPLE_RATE_HZ);
}

// Calculate mean and standard deviation for each axis and magnitude
void calculateStatistics() {
  // Calculate means
  meanX = calculateMean(accelX);
  meanY = calculateMean(accelY);
  meanZ = calculateMean(accelZ);
  meanMag = calculateMean(accelMagnitude);

  // Calculate standard deviations
  stdDevX = calculateStdDev(accelX, meanX);
  stdDevY = calculateStdDev(accelY, meanY);
  stdDevZ = calculateStdDev(accelZ, meanZ);
  stdDevMag = calculateStdDev(accelMagnitude, meanMag);
}

// Helper function to calculate mean
float calculateMean(float *data) {
  float sum = 0;
  for (int i = 0; i < WINDOW_SIZE; i++) {
    sum += data[i];
  }
  return sum / WINDOW_SIZE;
}

// Helper function to calculate standard deviation
float calculateStdDev(float *data, float mean) {
  float sum = 0;
  for (int i = 0; i < WINDOW_SIZE; i++) {
    sum += pow(data[i] - mean, 2);
  }
  return sqrt(sum / WINDOW_SIZE);
}

// Detect anomalies using Z-score method
bool detectAnomalies() {
  // Calculate Z-scores for each axis and magnitude
  float zScoreX = fabs(accelX[0] - meanX) / stdDevX;
  float zScoreY = fabs(accelY[0] - meanY) / stdDevY;
  float zScoreZ = fabs(accelZ[0] - meanZ) / stdDevZ;
  float zScoreMag = fabs(accelMagnitude[0] - meanMag) / stdDevMag;

  // Check if any Z-score exceeds threshold
  if (zScoreX > ANOMALY_THRESHOLD ||
      zScoreY > ANOMALY_THRESHOLD ||
      zScoreZ > ANOMALY_THRESHOLD ||
      zScoreMag > ANOMALY_THRESHOLD) {
    return true;
  }

  return false;
}
