    float x_mean = 0.0f, y_mean = 0.0f, z_mean = 0.0f;
    float x_stddev = 0.0f, y_stddev = 0.0f, z_stddev = 0.0f;

    // Learning phase flag
    bool learning_phase = true;
    uint32_t learning_samples = 0;

    // Simple moving average filter
    float moving_avg_filter(float value, float& avg, float alpha = 0.1f) {
        avg = alpha * value + (1.0f - alpha) * avg;
        return avg;
    }

public:
    AccelerometerAnomalyDetector() {
        x_buffer.resize(WINDOW_SIZE, 0.0f);
        y_buffer.resize(WINDOW_SIZE, 0.0f);
        z_buffer.resize(WINDOW_SIZE, 0.0f);
    }

    // Process new accelerometer data
    bool processData(float x, float y, float z) {
        // Apply simple moving average filter
        x = moving_avg_filter(x, x_mean);
        y = moving_avg_filter(y, y_mean);
        z = moving_avg_filter(z, z_mean);

        // Store in circular buffer
        x_buffer[buffer_index] = x;
        y_buffer[buffer_index] = y;
        z_buffer[buffer_index] = z;
        buffer_index = (buffer_index + 1) % WINDOW_SIZE;

        // During learning phase, just collect data
        if (learning_phase) {
            learning_samples++;
            if (learning_samples >= LEARNING_WINDOW) {
                calculateStatistics();
                learning_phase = false;
            }
            return false;
        }

        // Calculate current statistics
        float current_x_mean, current_y_mean, current_z_mean;
        float current_x_stddev, current_y_stddev, current_z_stddev;

        calculateCurrentStatistics(current_x_mean, current_y_mean, current_z_mean,
                                 current_x_stddev, current_y_stddev, current_z_stddev);

        // Check for anomalies
        bool x_anomaly = std::abs(current_x_mean - x_mean) > ANOMALY_THRESHOLD * x_stddev;
        bool y_anomaly = std::abs(current_y_mean - y_mean) > ANOMALY_THRESHOLD * y_stddev;
        bool z_anomaly = std::abs(current_z_mean - z_mean) > ANOMALY_THRESHOLD * z_stddev;

        return x_anomaly || y_anomaly || z_anomaly;
    }

private:
    // Calculate statistics for the current window
    void calculateCurrentStatistics(float& x_mean, float& y_mean, float& z_mean,
                                   float& x_stddev, float& y_stddev, float& z_stddev) {
        // Calculate means
        x_mean = std::accumulate(x_buffer.begin(), x_buffer.end(), 0.0f) / WINDOW_SIZE;
        y_mean = std::accumulate(y_buffer.begin(), y_buffer.end(), 0.0f) / WINDOW_SIZE;
        z_mean = std::accumulate(z_buffer.begin(), z_buffer.end(), 0.0f) / WINDOW_SIZE;

        // Calculate standard deviations
        float x_sum_sq = 0.0f, y_sum_sq = 0.0f, z_sum_sq = 0.0f;
        for (size_t i = 0; i < WINDOW_SIZE; i++) {
            x_sum_sq += (x_buffer[i] - x_mean) * (x_buffer[i] - x_mean);
            y_sum_sq += (y_buffer[i] - y_mean) * (y_buffer[i] - y_mean);
            z_sum_sq += (z_buffer[i] - z_mean) * (z_buffer[i] - z_mean);
        }

        x_stddev = std::sqrt(x_sum_sq / WINDOW_SIZE);
        y_stddev = std::sqrt(y_sum_sq / WINDOW_SIZE);
        z_stddev = std::sqrt(z_sum_sq / WINDOW_SIZE);
    }

    // Calculate statistics for the learning phase
    void calculateStatistics() {
        // Combine all data points from learning phase
        std::vector<float> all_x, all_y, all_z;
        all_x.reserve(LEARNING_WINDOW);
        all_y.reserve(LEARNING_WINDOW);
        all_z.reserve(LEARNING_WINDOW);

        // In a real implementation, you would store all learning samples
        // For this example, we'll just use the last WINDOW_SIZE samples
        all_x.assign(x_buffer.begin(), x_buffer.end());
        all_y.assign(y_buffer.begin(), y_buffer.end());
        all_z.assign(z_buffer.begin(), z_buffer.end());

        // Calculate means
        x_mean = std::accumulate(all_x.begin(), all_x.end(), 0.0f) / all_x.size();
        y_mean = std::accumulate(all_y.begin(), all_y.end(), 0.0f) / all_y.size();
        z_mean = std::accumulate(all_z.begin(), all_z.end(), 0.0f) / all_z.size();

        // Calculate standard deviations
        float x_sum_sq = 0.0f, y_sum_sq = 0.0f, z_sum_sq = 0.0f;
        for (size_t i = 0; i < all_x.size(); i++) {
            x_sum_sq += (all_x[i] - x_mean) * (all_x[i] - x_mean);
            y_sum_sq += (all_y[i] - y_mean) * (all_y[i] - y_mean);
            z_sum_sq += (all_z[i] - z_mean) * (all_z[i] - z_mean);
        }

        x_stddev = std::sqrt(x_sum_sq / all_x.size());
        y_stddev = std::sqrt(y_sum_sq / all_y.size());
        z_stddev = std::sqrt(z_sum_sq / all_z.size());
    }
};
