#include <stdint.h>
#include <math.h>
#include <string.h>

// Configuration parameters
#define SAMPLE_RATE_HZ 100          // 100Hz sampling rate
#define WINDOW_SIZE 50               // 50 samples (0.5s window)
#define FEATURE_WINDOW 10             // 10 windows for feature calculation
#define ANOMALY_THRESHOLD 3.0f       // Z-score threshold for anomaly

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

typedef struct {
    float mean;
    float variance;
    float max;
    float min;
} FeatureStats;

// Circular buffer for raw data
AccelData raw_buffer[WINDOW_SIZE];
uint8_t buffer_index = 0;

// Feature storage
FeatureStats features[FEATURE_WINDOW];
uint8_t feature_index = 0;

// Moving average filter
float moving_avg[3] = {0, 0, 0};  // For X, Y, Z axes
const float alpha = 0.2f;         // Filter coefficient

// Function prototypes
void init_pipeline();
void process_sample(AccelData sample);
void update_moving_avg(AccelData *sample);
void calculate_features();
int detect_anomaly();
void trigger_alert();

void init_pipeline() {
    // Initialize buffers
    memset(raw_buffer, 0, sizeof(raw_buffer));
    memset(features, 0, sizeof(features));

    // Initialize moving averages
    for (int i = 0; i < 3; i++) {
        moving_avg[i] = 0.0f;
    }
}

void process_sample(AccelData sample) {
    // Apply moving average filter
    update_moving_avg(&sample);

    // Store in circular buffer
    raw_buffer[buffer_index] = sample;
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    // When buffer is full, calculate features
    if (buffer_index == 0) {
        calculate_features();
        if (detect_anomaly()) {
            trigger_alert();
        }
    }
}

void update_moving_avg(AccelData *sample) {
    // Simple exponential moving average
    moving_avg[0] = alpha * sample->x + (1 - alpha) * moving_avg[0];
    moving_avg[1] = alpha * sample->y + (1 - alpha) * moving_avg[1];
    moving_avg[2] = alpha * sample->z + (1 - alpha) * moving_avg[2];

    // Update sample with filtered values
    sample->x = moving_avg[0];
    sample->y = moving_avg[1];
    sample->z = moving_avg[2];
}

void calculate_features() {
    // Calculate statistics for the current window
    float sum[3] = {0, 0, 0};
    float sum_sq[3] = {0, 0, 0};
    float max[3] = {-1000, -1000, -1000};
    float min[3] = {1000, 1000, 1000};

    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum[0] += raw_buffer[i].x;
        sum[1] += raw_buffer[i].y;
        sum[2] += raw_buffer[i].z;

        sum_sq[0] += raw_buffer[i].x * raw_buffer[i].x;
        sum_sq[1] += raw_buffer[i].y * raw_buffer[i].y;
        sum_sq[2] += raw_buffer[i].z * raw_buffer[i].z;

        if (raw_buffer[i].x > max[0]) max[0] = raw_buffer[i].x;
        if (raw_buffer[i].y > max[1]) max[1] = raw_buffer[i].y;
        if (raw_buffer[i].z > max[2]) max[2] = raw_buffer[i].z;

        if (raw_buffer[i].x < min[0]) min[0] = raw_buffer[i].x;
        if (raw_buffer[i].y < min[1]) min[1] = raw_buffer[i].y;
        if (raw_buffer[i].z < min[2]) min[2] = raw_buffer[i].z;
    }

    // Calculate mean and variance
    FeatureStats current_features;
    for (int i = 0; i < 3; i++) {
        current_features.mean = sum[i] / WINDOW_SIZE;
        current_features.variance = (sum_sq[i] / WINDOW_SIZE) - (current_features.mean * current_features.mean);
        current_features.max = max[i];
        current_features.min = min[i];

        // Store in feature history
        features[feature_index].mean = current_features.mean;
        features[feature_index].variance = current_features.variance;
        features[feature_index].max = current_features.max;
        features[feature_index].min = current_features.min;
    }

    feature_index = (feature_index + 1) % FEATURE_WINDOW;
}

int detect_anomaly() {
    // Simple Z-score based anomaly detection
    if (feature_index < FEATURE_WINDOW - 1) {
        return 0;  // Not enough data
    }

    // Calculate mean and std dev of recent features
    float mean = 0, variance = 0;
    for (int i = 0; i < FEATURE_WINDOW; i++) {
        mean += features[i].variance;
    }
    mean /= FEATURE_WINDOW;

    for (int i = 0; i < FEATURE_WINDOW; i++) {
        variance += (features[i].variance - mean) * (features[i].variance - mean);
    }
    variance /= FEATURE_WINDOW;
    float std_dev = sqrtf(variance);

    // Check if current variance is significantly different
    float z_score = (features[feature_index].variance - mean) / std_dev;
    if (fabsf(z_score) > ANOMALY_THRESHOLD) {
        return 1;  // Anomaly detected
    }

    return 0;
}

void trigger_alert() {
    // Implement your alert mechanism here
    // Could be LED, buzzer, or communication to host
    // For this example, we'll just print a message
    printf("ANOMALY DETECTED!\n");
}

