#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint32_t WINDOW_SIZE = 50;  // Number of samples in sliding window
constexpr float ANOMALY_THRESHOLD = 3.0f;  // Standard deviations from mean
constexpr float ALPHA = 0.1f;  // Smoothing factor for running statistics

// Data structure for accelerometer sample
struct AccelSample {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Running statistics calculator
class RunningStats {
private:
    float mean_x = 0.0f;
    float mean_y = 0.0f;
    float mean_z = 0.0f;
    float m2_x = 0.0f;
    float m2_y = 0.0f;
    float m2_z = 0.0f;
    uint32_t count = 0;

public:
    void update(float x, float y, float z) {
        count++;
        float delta_x = x - mean_x;
        mean_x += delta_x / count;
        m2_x += delta_x * (x - mean_x);

        float delta_y = y - mean_y;
        mean_y += delta_y / count;
        m2_y += delta_y * (y - mean_y);

        float delta_z = z - mean_z;
        mean_z += delta_z / count;
        m2_z += delta_z * (z - mean_z);
    }

    float getMeanX() const { return mean_x; }
    float getMeanY() const { return mean_y; }
    float getMeanZ() const { return mean_z; }

    float getStdDevX() const {
        return (count < 2) ? 0.0f : sqrt(m2_x / (count - 1));
    }

    float getStdDevY() const {
        return (count < 2) ? 0.0f : sqrt(m2_y / (count - 1));
    }

    float getStdDevZ() const {
        return (count < 2) ? 0.0f : sqrt(m2_z / (count - 1));
    }

    uint32_t getCount() const { return count; }
};

// Anomaly detection class
class AccelAnomalyDetector {
private:
    RunningStats stats;
    std::vector<AccelSample> window;
    bool initialized = false;

public:
    bool detectAnomaly(const AccelSample& sample) {
        // Update running statistics
        stats.update(sample.x, sample.y, sample.z);

        // Add sample to window
        window.push_back(sample);
        if (window.size() > WINDOW_SIZE) {
            window.erase(window.begin());
        }

        // Wait until we have enough samples
        if (window.size() < WINDOW_SIZE / 2) {
            return false;
        }

        // Calculate current magnitude
        float current_mag = sqrt(sample.x*sample.x + sample.y*sample.y + sample.z*sample.z);

        // Calculate mean and std dev of magnitudes in window
        std::vector<float> magnitudes;
        for (const auto& s : window) {
            magnitudes.push_back(sqrt(s.x*s.x + s.y*s.y + s.z*s.z));
        }

        float mean_mag = std::accumulate(magnitudes.begin(), magnitudes.end(), 0.0f) / magnitudes.size();
        float sq_sum = std::inner_product(magnitudes.begin(), magnitudes.end(), magnitudes.begin(), 0.0f);
        float std_mag = sqrt(sq_sum / magnitudes.size() - mean_mag * mean_mag);

        // Check for anomaly
        float z_score = (current_mag - mean_mag) / (std_mag + 1e-6f);  // Small epsilon to avoid division by zero
        return fabs(z_score) > ANOMALY_THRESHOLD;
    }

    // Get current statistics for monitoring
    float getCurrentMeanX() const { return stats.getMeanX(); }
    float getCurrentMeanY() const { return stats.getMeanY(); }
    float getCurrentMeanZ() const { return stats.getMeanZ(); }

    float getCurrentStdDevX() const { return stats.getStdDevX(); }
    float getCurrentStdDevY() const { return stats.getStdDevY(); }
    float getCurrentStdDevZ() const { return stats.getStdDevZ(); }
};

