# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation focuses on a lightweight approach suitable for microcontrollers with limited resources.

## System Architecture

```
[Accelerometer] → [Preprocessing] → [Feature Extraction] → [Anomaly Detection] → [Alert]
```

## Implementation (C/C++ for Embedded Systems)

```c
#include <stdint.h>
#include <math.h>
#include <string.h>

// Configuration parameters
#define WINDOW_SIZE 50          // Number of samples in sliding window
#define THRESHOLD_MULTIPLIER 3.0 // Multiplier for standard deviation threshold
#define MIN_ANOMALY_DURATION 3   // Minimum consecutive anomalies to trigger alert

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

typedef struct {
    float mean;
    float stddev;
    float min;
    float max;
} Stats;

// Global variables
static AccelData window[WINDOW_SIZE];
static uint8_t window_index = 0;
static uint8_t anomaly_count = 0;

// Initialize the pipeline
void init_anomaly_detection() {
    memset(window, 0, sizeof(window));
    window_index = 0;
    anomaly_count = 0;
}

// Calculate statistics for the current window
void calculate_stats(const AccelData* data, Stats* stats) {
    float sum_x = 0, sum_y = 0, sum_z = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    float min_x = data[0].x, max_x = data[0].x;
    float min_y = data[0].y, max_y = data[0].y;
    float min_z = data[0].z, max_z = data[0].z;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_x += data[i].x;
        sum_y += data[i].y;
        sum_z += data[i].z;

        sum_sq_x += data[i].x * data[i].x;
        sum_sq_y += data[i].y * data[i].y;
        sum_sq_z += data[i].z * data[i].z;

        if (data[i].x < min_x) min_x = data[i].x;
        if (data[i].x > max_x) max_x = data[i].x;
        if (data[i].y < min_y) min_y = data[i].y;
        if (data[i].y > max_y) max_y = data[i].y;
        if (data[i].z < min_z) min_z = data[i].z;
        if (data[i].z > max_z) max_z = data[i].z;
    }

    stats->mean = (sum_x + sum_y + sum_z) / (3 * WINDOW_SIZE);
    stats->stddev = sqrtf((sum_sq_x + sum_sq_y + sum_sq_z) / (3 * WINDOW_SIZE) - stats->mean * stats->mean);
    stats->min = fminf(min_x, fminf(min_y, min_z));
    stats->max = fmaxf(max_x, fmaxf(max_y, max_z));
}

// Detect anomalies in the current window
bool detect_anomaly(const AccelData* new_data) {
    // Update sliding window
    window[window_index] = *new_data;
    window_index = (window_index + 1) % WINDOW_SIZE;

    // Calculate statistics
    Stats stats;
    calculate_stats(window, &stats);

    // Simple anomaly detection: check if any axis is beyond threshold
    float threshold = THRESHOLD_MULTIPLIER * stats.stddev;

    bool is_anomaly = false;

    // Check each axis against threshold
    if (fabsf(new_data->x - stats.mean) > threshold ||
        fabsf(new_data->y - stats.mean) > threshold ||
        fabsf(new_data->z - stats.mean) > threshold) {
        is_anomaly = true;
    }

    // Check for minimum duration of anomalies
    if (is_anomaly) {
        anomaly_count++;
        if (anomaly_count >= MIN_ANOMALY_DURATION) {
