// Simple moving average filter
float moving_average_filter(float new_value, float *buffer, uint8_t buffer_size) {
    static float sum = 0;
    static uint8_t count = 0;

    if (count < buffer_size) {
        sum += new_value;
        count++;
    } else {
        sum = sum - buffer[data_index % buffer_size] + new_value;
    }

    buffer[data_index % buffer_size] = new_value;
    return sum / count;
}

// Calculate standard deviation
float calculate_std_dev(float *data, uint8_t size, float mean) {
    float sum = 0.0;
    for (uint8_t i = 0; i < size; i++) {
        sum += pow(data[i] - mean, 2);
    }
    return sqrt(sum / size);
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x*x + y*y + z*z);
}

// Update baseline statistics
void update_baseline(AccelerometerData *data) {
    static float x_values[BASELINE_WINDOW];
    static float y_values[BASELINE_WINDOW];
    static float z_values[BASELINE_WINDOW];

    x_values[baseline_count % BASELINE_WINDOW] = data->x;
    y_values[baseline_count % BASELINE_WINDOW] = data->y;
    z_values[baseline_count % BASELINE_WINDOW] = data->z;

    if (baseline_count < BASELINE_WINDOW) {
        baseline_count++;
    }

    // Calculate statistics every BASELINE_WINDOW samples
    if (baseline_count % BASELINE_WINDOW == 0) {
        // Calculate means
        float x_mean = 0, y_mean = 0, z_mean = 0;
        for (uint16_t i = 0; i < BASELINE_WINDOW; i++) {
            x_mean += x_values[i];
            y_mean += y_values[i];
            z_mean += z_values[i];
        }
        x_mean /= BASELINE_WINDOW;
        y_mean /= BASELINE_WINDOW;
        z_mean /= BASELINE_WINDOW;

        // Calculate standard deviations
        baseline_stats[0].mean = x_mean;
        baseline_stats[0].std_dev = calculate_std_dev(x_values, BASELINE_WINDOW, x_mean);

        baseline_stats[1].mean = y_mean;
        baseline_stats[1].std_dev = calculate_std_dev(y_values, BASELINE_WINDOW, y_mean);

        baseline_stats[2].mean = z_mean;
        baseline_stats[2].std_dev = calculate_std_dev(z_values, BASELINE_WINDOW, z_mean);
    }
}

// Detect anomalies in the current window
uint8_t detect_anomalies(AccelerometerData *window, uint8_t window_size) {
    if (baseline_count < BASELINE_WINDOW) {
        return 0; // Not enough baseline data
    }

    float x_values[window_size];
    float y_values[window_size];
    float z_values[window_size];

    // Extract values from window
    for (uint8_t i = 0; i < window_size; i++) {
        x_values[i] = window[i].x;
        y_values[i] = window[i].y;
        z_values[i] = window[i].z;
    }

    // Calculate current statistics
    float x_mean = 0, y_mean = 0, z_mean = 0;
    for (uint8_t i = 0; i < window_size; i++) {
        x_mean += x_values[i];
        y_mean += y_values[i];
        z_mean += z_values[i];
    }
    x_mean /= window_size;
    y_mean /= window_size;
    z_mean /= window_size;

    float x_std = calculate_std_dev(x_values, window_size, x_mean);
    float y_std = calculate_std_dev(y_values, window_size, y_mean);
    float z_std = calculate_std_dev(z_values, window_size, z_mean);

    // Compare with baseline
    float x_zscore = fabs(x_mean - baseline_stats[0].mean) / baseline_stats[0].std_dev;
    float y_zscore = fabs(y_mean - baseline_stats[1].mean) / baseline_stats[1].std_dev;
    float z_zscore = fabs(z_mean - baseline_stats[2].mean) / baseline_stats[2].std_dev;

    // Check if any axis exceeds threshold
    if (x_zscore > ANOMALY_THRESHOLD ||
        y_zscore > ANOMALY_THRESHOLD ||
        z_zscore > ANOMALY_THRESHOLD) {
        return 1; // Anomaly detected
    }

    return 0; // No anomaly
}

