void calculate_stats(WindowData *window);
bool detect_anomaly(const WindowData *window);
void handle_anomaly(const WindowData *window);

// Initialize the pipeline
void init_pipeline() {
    memset(&current_window, 0, sizeof(WindowData));
    buffer_index = 0;
}

// Process a new accelerometer sample
void process_sample(float x, float y, float z, uint32_t timestamp_ms) {
    // Store raw data
    raw_data_buffer[buffer_index].x = x;
    raw_data_buffer[buffer_index].y = y;
    raw_data_buffer[buffer_index].z = z;

    // Calculate magnitude
    float magnitude = sqrtf(x*x + y*y + z*z);
    current_window.magnitude[buffer_index] = magnitude;

    buffer_index++;

    // When window is full, process it
    if (buffer_index >= WINDOW_SIZE) {
        current_window.timestamp_ms = timestamp_ms;
        calculate_stats(&current_window);
        if (detect_anomaly(&current_window)) {
            handle_anomaly(&current_window);
        }

        // Reset for next window
        buffer_index = 0;
    }
}

// Calculate statistics for the current window
void calculate_stats(WindowData *window) {
    float sum = 0.0f;
    float sum_sq = 0.0f;

    // Calculate mean
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum += window->magnitude[i];
    }
    window->stats.mean = sum / WINDOW_SIZE;

    // Calculate standard deviation
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float diff = window->magnitude[i] - window->stats.mean;
        sum_sq += diff * diff;
    }
    window->stats.stddev = sqrtf(sum_sq / WINDOW_SIZE);
}

// Detect anomalies in the current window
bool detect_anomaly(const WindowData *window) {
    float upper_threshold = window->stats.mean + THRESHOLD_MULTIPLIER * window->stats.stddev;
    float lower_threshold = window->stats.mean - THRESHOLD_MULTIPLIER * window->stats.stddev;

    int anomaly_count = 0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window->magnitude[i] > upper_threshold || window->magnitude[i] < lower_threshold) {
            anomaly_count++;
        }
    }

    // Require at least 10% of samples to be anomalous
    return (anomaly_count > WINDOW_SIZE / 10);
}

