    dataBuffer[bufferIndex] = current;
    bufferIndex = (bufferIndex + 1) % WINDOW_SIZE;
    if (bufferIndex == 0) bufferFull = true;

    // Process data when buffer is full
    if (bufferFull) {
        Features currentFeatures = calculateFeatures();

        if (!profileLearned) {
            // Learn normal profile during initial phase
            normalProfile = currentFeatures;
            profileLearned = true;
            Serial.println("Normal profile learned");
        } else {
            // Detect anomalies
            float anomalyScore = calculateAnomalyScore(currentFeatures);
            if (anomalyScore > ANOMALY_THRESHOLD) {
                triggerAnomalyAlert(currentFeatures, anomalyScore);
            }
        }
    }

    delay(1000 / SAMPLE_RATE);  // Maintain sample rate
}

Features calculateFeatures() {
    Features f;
    float sum = 0, sumSq = 0;
    float max = -INFINITY, min = INFINITY;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        float mag = dataBuffer[i].magnitude;
        sum += mag;
        sumSq += mag * mag;
        if (mag > max) max = mag;
        if (mag < min) min = mag;
