# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation uses a simple statistical approach for anomaly detection, which can be run on resource-constrained embedded systems.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate statistical features
4. **Anomaly Detection**: Compare features against baseline
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in sliding window
constexpr float THRESHOLD_MULTIPLIER = 3.0f;  // For standard deviation threshold
constexpr float MOVING_AVG_ALPHA = 0.1f;  // For exponential moving average

// Structure to hold accelerometer data
struct AccelerometerData {
    float x;
    float y;
    float z;
    float magnitude;
};

// Structure to hold statistical features
struct AccelFeatures {
    float mean;
    float stdDev;
    float min;
    float max;
    float energy;  // Sum of squared magnitudes
};

// Circular buffer for sliding window
class CircularBuffer {
private:
    std::vector<AccelerometerData> buffer;
    size_t head = 0;
    size_t tail = 0;
    size_t count = 0;
    size_t capacity;

public:
    CircularBuffer(size_t size) : capacity(size), buffer(size) {}

    void push(const AccelerometerData& data) {
        buffer[head] = data;
        head = (head + 1) % capacity;
        if (count < capacity) {
            count++;
        } else {
            tail = (tail + 1) % capacity;
        }
    }

    bool isFull() const { return count == capacity; }
    size_t size() const { return count; }

    const AccelerometerData& operator[](size_t index) const {
        return buffer[(tail + index) % capacity];
    }
};

// Anomaly detection class
class AccelAnomalyDetector {
private:
    CircularBuffer dataBuffer;
    AccelFeatures baselineFeatures;
    float movingAvg = 0.0f;
    bool initialized = false;

    // Calculate features from current window
    AccelFeatures calculateFeatures() const {
        AccelFeatures features;
        float sum = 0.0f;
        float sumSq = 0.0f;
        float minVal = std::numeric_limits<float>::max();
        float maxVal = std::numeric_limits<float>::lowest();

        for (size_t i = 0; i < dataBuffer.size(); ++i) {
            float mag = dataBuffer[i].magnitude;
            sum += mag;
            sumSq += mag * mag;
            minVal = std::min(minVal, mag);
            maxVal = std::max(maxVal, mag);
        }

        features.mean = sum / dataBuffer.size();
        features.stdDev = std::sqrt((sumSq / dataBuffer.size()) - (features.mean * features.mean));
        features.min = minVal;
        features.max = maxVal;
        features.energy = sumSq;

        return features;
    }

    // Initialize baseline features
    void initializeBaseline() {
        baselineFeatures = calculateFeatures();
        movingAvg = baselineFeatures.mean;
        initialized = true;
    }

public:
    AccelAnomalyDetector() : dataBuffer(WINDOW_SIZE) {}

    // Process new accelerometer data
    bool processData(float x, float y, float z) {
        // Calculate magnitude
        float magnitude = std::sqrt(x*x + y*y + z*z);

        // Store in buffer
        dataBuffer.push({x, y, z, magnitude});

        // Wait until buffer is full before processing
        if (!dataBuffer.isFull()) {
            return false;
        }

        // Initialize baseline if not done yet
        if (!initialized) {
            initializeBaseline();
            return false;
        }

        // Calculate current features
        AccelFeatures currentFeatures = calculateFeatures();

        // Update moving average of mean
        movingAvg = MOVING_AVG_ALPHA * currentFeatures.mean + (1 - MOVING_AVG_ALPHA) * movingAvg;

        // Detect anomalies
        bool isAnomaly = false;

        // Check for sudden changes in mean
        if (std::abs(currentFeatures.mean - movingAvg) > THRESHOLD_MULTIPLIER * baselineFeatures.stdDev) {
            isAnomaly = true;
        }

        // Check for extreme values
        if (currentFeatures.max > baselineFeatures.max * 2.0f ||
            currentFeatures.min < baselineFeatures.min * 2.0f) {
            isAnomaly = true;
        }

        // Check for high energy (sudden movement)
        if (currentFeatures.energy > baselineFeatures.energy * 3.0f) {
            isAnomaly = true;
        }

        return isAnomaly;
    }

    // Reset the detector (e.g., when device is recalibrated)
    void reset() {
        dataBuffer = CircularBuffer(WINDOW_SIZE);
        initialized = false;
    }
};

// Example usage
int main() {
    AccelAnomalyDetector detector;

    // Simulate some accelerometer data
    // In a real system, this would come from actual sensor readings
    for (int i = 0; i < 1000; ++i) {
        // Normal data (magnitude around 1.0)
        float x = 0.1f * (rand() % 100 - 50);
        float y = 0.1f * (rand() % 100 - 50);
        float z = 0.9f + 0.1f * (rand() % 100 - 50);

        // Occasionally generate an anomaly
        if (i == 500) {
            x = 5.0f;  // Sudden spike
        }

        bool isAnomaly = detector.processData(x, y, z);

        if (isAnomaly) {
            // In a real system, this would trigger an alert
            // For example: blink LED, send notification, etc.
            printf("Anomaly detected at sample %d\n", i);
        }
    }

    return 0;
}
