# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded system pipeline that processes accelerometer data to detect anomalies. This implementation assumes a microcontroller environment with limited resources.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate relevant features
4. **Anomaly Detection**: Compare against learned thresholds
5. **Output**: Trigger alerts or record anomalies

## Implementation (C/C++ for Microcontroller)

```c
#include <stdint.h>
#include <math.h>
#include <string.h>

// Configuration parameters
#define SAMPLE_RATE_HZ 100          // 100Hz sampling
#define WINDOW_SIZE 20               // 200ms window (20 samples at 100Hz)
#define FEATURE_WINDOW 5             // 5 windows for feature calculation
#define ANOMALY_THRESHOLD 2.5        // Z-score threshold for anomaly detection

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

typedef struct {
    float mean;
    float std_dev;
    float max;
    float min;
    float energy;
} FeatureSet;

// Circular buffer for raw data
AccelData raw_data[WINDOW_SIZE];
uint8_t data_index = 0;

// Circular buffer for features
FeatureSet features[FEATURE_WINDOW];
uint8_t feature_index = 0;

// Moving average filter
float moving_avg[3] = {0, 0, 0};     // For x, y, z axes
float alpha = 0.2;                   // Filter coefficient

// Function prototypes
void init_pipeline();
void process_sample(AccelData sample);
void filter_data(AccelData* raw, AccelData* filtered);
void extract_features(AccelData* window, FeatureSet* features);
float calculate_z_score(float value, float mean, float std_dev);
bool detect_anomaly(FeatureSet* current, FeatureSet* history);
void alert_anomaly();

void init_pipeline() {
    // Initialize buffers
    memset(raw_data, 0, sizeof(raw_data));
    memset(features, 0, sizeof(features));

    // Initialize moving averages
    for (int i = 0; i < 3; i++) {
        moving_avg[i] = 0.0f;
    }
}

void process_sample(AccelData sample) {
    // Store raw data in circular buffer
    raw_data[data_index] = sample;
    data_index = (data_index + 1) % WINDOW_SIZE;

    // Apply moving average filter
    AccelData filtered;
    filter_data(&sample, &filtered);

    // When window is full, process features
    if (data_index == 0) {
        FeatureSet current_features;
        extract_features(raw_data, &current_features);

        // Store features in circular buffer
        features[feature_index] = current_features;
        feature_index = (feature_index + 1) % FEATURE_WINDOW;

        // Detect anomalies
        if (detect_anomaly(&current_features, features)) {
            alert_anomaly();
        }
    }
}

void filter_data(AccelData* raw, AccelData* filtered) {
    // Simple exponential moving average filter
    moving_avg[0] = alpha * raw->x + (1 - alpha) * moving_avg[0];
    moving_avg[1] = alpha * raw->y + (1 - alpha) * moving_avg[1];
    moving_avg[2] = alpha * raw->z + (1 - alpha) * moving_avg[2];

    filtered->x = moving_avg[0];
    filtered->y = moving_avg[1];
    filtered->z = moving_avg[2];
}

void extract_features(AccelData* window, FeatureSet* features) {
    float sum_x = 0, sum_y = 0, sum_z = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    float max_x = -INFINITY, max_y = -INFINITY, max_z = -INFINITY;
    float min_x = INFINITY, min_y = INFINITY, min_z = INFINITY;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_x += window[i].x;
        sum_y += window[i].y;
        sum_z += window[i].z;

        sum_sq_x += window[i].x * window[i].x;
        sum_sq_y += window[i].y * window[i].y;
        sum_sq_z += window[i].z * window[i].z;

        if (window[i].x > max_x) max_x = window[i].x;
        if (window[i].y > max_y) max_y = window[i].y;
        if (window[i].z > max_z) max_z = window[i].z;

        if (window[i].x < min_x) min_x = window[i].x;
        if (window[i].y < min_y) min_y = window[i].y;
        if (window[i].z < min_z) min_z = window[i].z;
    }

    // Calculate mean and standard deviation
    features->mean = (sum_x + sum_y + sum_z) / (3 * WINDOW_SIZE);
    float var_x = (sum_sq_x - sum_x * sum_x / WINDOW_SIZE) / WINDOW_SIZE;
    float var_y = (sum_sq_y - sum_y * sum_y / WINDOW_SIZE) / WINDOW_SIZE;
    float var_z = (sum_sq_z - sum_z * sum_z / WINDOW_SIZE) / WINDOW_SIZE;
    features->std_dev = sqrtf((var_x + var_y + var_z) / 3);

    // Calculate max/min
    features->max = fmaxf(fmaxf(max_x, max_y), max_z);
    features->min = fminf(fminf(min_x, min_y), min_z);

    // Calculate energy (sum of squares)
    features->energy = sum_sq_x + sum_sq_y + sum_sq_z;
}

float calculate_z_score(float value, float mean, float std_dev) {
    if (std_dev == 0) return 0;
    return fabsf(value - mean) / std_dev;
}

bool detect_anomaly(FeatureSet* current, FeatureSet* history) {
    // Calculate historical mean and std_dev for each feature
    float mean_mean = 0, mean_std = 0, mean_max = 0, mean_min = 0, mean_energy = 0;
    float std_mean = 0, std_std = 0, std_max = 0, std_min = 0, std_energy = 0;

    for (int i = 0; i < FEATURE_WINDOW; i++) {
        mean_mean += history[i].mean;
        mean_std += history[i].std_dev;
        mean_max += history[i].max;
        mean_min += history[i].min;
        mean_energy += history[i].energy;
    }

    mean_mean /= FEATURE_WINDOW;
    mean_std /= FEATURE_WINDOW;
    mean_max /= FEATURE_WINDOW;
    mean_min /= FEATURE_WINDOW;
    mean_energy /= FEATURE_WINDOW;

    for (int i = 0; i < FEATURE_WINDOW; i++) {
        std_mean += powf(history[i].mean - mean_mean, 2);
        std_std += powf(history[i].std_dev - mean_std, 2);
        std_max += powf(history[i].max - mean_max, 2);
        std_min += powf(history[i].min - mean_min, 2);
        std_energy += powf(history[i].energy - mean_energy, 2);
    }

    std_mean = sqrtf(std_mean / FEATURE_WINDOW);
    std_std = sqrtf(std_std / FEATURE_WINDOW);
    std_max = sqrtf(std_max / FEATURE_WINDOW);
    std_min = sqrtf(std_min / FEATURE_WINDOW);
    std_energy = sqrtf(std_energy / FEATURE_WINDOW);

    // Calculate Z-scores for current features
    float z_mean = calculate_z_score(current->mean, mean_mean, std_mean);
    float z_std = calculate_z_score(current->std_dev, mean_std, std_std);
    float z_max = calculate_z_score(current->max, mean_max, std_max);
    float z_min = calculate_z_score(current->min, mean_min, std_min);
    float z_energy = calculate_z_score(current->energy, mean_energy, std_energy);

    // Check if any feature exceeds threshold
    return (z_mean > ANOMALY_THRESHOLD) ||
           (z_std > ANOMALY_THRESHOLD) ||
           (z_max > ANOMALY_THRESHOLD) ||
           (z_min > ANOMALY_THRESHOLD) ||
           (z_energy > ANOMALY_THRESHOLD);
}

void alert_anomaly() {
    // Implementation depends on your system
    // Could be LED, buzzer, or communication to host
    // For example:
    // GPIO_write(ANOMALY_LED_PIN, 1);
    // send_to_host("ANOMALY_DETECTED");
}
```

