# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation uses a simple statistical approach for anomaly detection, which is suitable for resource-constrained embedded systems.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate statistical features
4. **Anomaly Detection**: Compare features against learned thresholds
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for embedded systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in processing window
constexpr float ANOMALY_THRESHOLD = 3.0f;  // Standard deviations from mean
constexpr float MOVING_AVG_ALPHA = 0.1f;  // For exponential moving average filter

// Data structure for accelerometer readings
struct AccelData {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Circular buffer for storing recent samples
class AccelBuffer {
private:
    std::vector<AccelData> buffer;
    size_t head = 0;
    size_t count = 0;

public:
    AccelBuffer(size_t size) : buffer(size) {}

    void addSample(const AccelData& sample) {
        buffer[head] = sample;
        head = (head + 1) % buffer.size();
        if (count < buffer.size()) count++;
    }

    const AccelData& getSample(size_t index) const {
        return buffer[(head - 1 - index + buffer.size()) % buffer.size()];
    }

    size_t size() const { return count; }
    bool isFull() const { return count == buffer.size(); }
};

// Feature extraction and anomaly detection class
class AnomalyDetector {
private:
    AccelBuffer buffer;
    float x_mean = 0, y_mean = 0, z_mean = 0;
    float x_stddev = 0, y_stddev = 0, z_stddev = 0;
    bool initialized = false;

    // Exponential moving average filter
    float ema_filter(float current, float new_val) {
        return current * (1 - MOVING_AVG_ALPHA) + new_val * MOVING_AVG_ALPHA;
    }

    // Calculate magnitude of acceleration vector
    float calculate_magnitude(const AccelData& data) {
        return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

public:
    AnomalyDetector() : buffer(WINDOW_SIZE) {}

    void processSample(const AccelData& raw_data) {
        // Apply simple low-pass filter
        AccelData filtered_data;
        if (buffer.size() > 0) {
            filtered_data.x = ema_filter(buffer.getSample(0).x, raw_data.x);
            filtered_data.y = ema_filter(buffer.getSample(0).y, raw_data.y);
            filtered_data.z = ema_filter(buffer.getSample(0).z, raw_data.z);
        } else {
            filtered_data = raw_data;
        }

        buffer.addSample(filtered_data);

        // Update statistics when buffer is full
        if (buffer.isFull()) {
            updateStatistics();
            initialized = true;
        }
    }

    void updateStatistics() {
        // Calculate means
        float sum_x = 0, sum_y = 0, sum_z = 0;
        for (size_t i = 0; i < buffer.size(); i++) {
            sum_x += buffer.getSample(i).x;
            sum_y += buffer.getSample(i).y;
            sum_z += buffer.getSample(i).z;
        }

        x_mean = sum_x / buffer.size();
        y_mean = sum_y / buffer.size();
        z_mean = sum_z / buffer.size();

        // Calculate standard deviations
        float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
        for (size_t i = 0; i < buffer.size(); i++) {
            float dx = buffer.getSample(i).x - x_mean;
            float dy = buffer.getSample(i).y - y_mean;
            float dz = buffer.getSample(i).z - z_mean;
            sum_sq_x += dx * dx;
            sum_sq_y += dy * dy;
            sum_sq_z += dz * dz;
        }

        x_stddev = std::sqrt(sum_sq_x / buffer.size());
        y_stddev = std::sqrt(sum_sq_y / buffer.size());
        z_stddev = std::sqrt(sum_sq_z / buffer.size());
    }

    bool detectAnomaly(const AccelData& data) {
        if (!initialized) return false;

        // Check if any axis is beyond threshold standard deviations
        float z_score_x = std::abs(data.x - x_mean) / x_stddev;
        float z_score_y = std::abs(data.y - y_mean) / y_stddev;
        float z_score_z = std::abs(data.z - z_mean) / z_stddev;

        return (z_score_x > ANOMALY_THRESHOLD) ||
               (z_score_y > ANOMALY_THRESHOLD) ||
               (z_score_z > ANOMALY_THRESHOLD);
    }

    // Get current statistics for debugging
    void getStatistics(float& mean_x, float& mean_y, float& mean_z,
                      float& stddev_x, float& stddev_y, float& stddev_z) const {
        mean_x = x_mean;
        mean_y = y_mean;
        mean_z = z_mean;
        stddev_x = x_stddev;
        stddev_y = y_stddev;
        stddev_z = z_stddev;
    }
};

// Example usage
int main() {
    AnomalyDetector detector;
    AccelData sample;

    // Simulate some normal data
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sample.x = 0.1f * i;  // Simulated x-axis data
        sample.y = 0.05f * i;  // Simulated y-axis data
        sample.z = 0.9f;      // Simulated z-axis data (mostly gravity)
        sample.timestamp = i;
        detector.processSample(sample);
    }

    // Test with normal data
    sample.x = 0.1f * WINDOW_SIZE;
    sample.y = 0.05f * WINDOW_SIZE;
    sample.z = 0.9f;
    sample.timestamp = WINDOW_SIZE;
    bool is_anomaly = detector.detectAnomaly(sample);
    printf("Normal data - Anomaly detected: %s\n", is_anomaly ? "Yes" : "No");

    // Test with anomalous data
    sample.x = 10.0f;  // Large deviation
    sample.y = 0.05f * WINDOW_SIZE;
    sample.z = 0.9f;
    sample.timestamp = WINDOW_SIZE + 1;
    is_anomaly = detector.detectAnomaly(sample);
    printf("Anomalous data - Anomaly detected: %s\n", is_anomaly ? "Yes" : "No");

    return 0;
}
```

