#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

// Configuration parameters
#define WINDOW_SIZE 20          // Number of samples in sliding window
#define ANOMALY_THRESHOLD 2.5    // Standard deviations from mean
#define SAMPLE_RATE_HZ 100       // 100Hz sampling rate

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelerometerData;

typedef struct {
    float mean;
    float std_dev;
} StatisticalFeatures;

// Circular buffer for sliding window
AccelerometerData accel_buffer[WINDOW_SIZE];
int buffer_index = 0;
bool buffer_full = false;

// Function prototypes
void process_accelerometer_data(AccelerometerData new_data);
StatisticalFeatures calculate_features();
bool detect_anomaly(StatisticalFeatures features, float magnitude);
float calculate_magnitude(AccelerometerData data);

int main() {
    // Simulated accelerometer data (in real system, this would come from hardware)
    AccelerometerData test_data[] = {
        {0.1, 0.2, 0.3}, {0.15, 0.25, 0.35}, {0.2, 0.3, 0.4},
        // ... more data points
    };

    int num_samples = sizeof(test_data) / sizeof(test_data[0]);

    for (int i = 0; i < num_samples; i++) {
        process_accelerometer_data(test_data[i]);
    }

    return 0;
}

void process_accelerometer_data(AccelerometerData new_data) {
    // Store data in circular buffer
    accel_buffer[buffer_index] = new_data;
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    if (buffer_index == 0) {
        buffer_full = true;
    }

    // Only process if we have enough data
    if (buffer_full) {
        StatisticalFeatures features = calculate_features();
        float magnitude = calculate_magnitude(new_data);

        if (detect_anomaly(features, magnitude)) {
            printf("ANOMALY DETECTED! Magnitude: %.2f, Mean: %.2f, StdDev: %.2f\n",
                   magnitude, features.mean, features.std_dev);
            // In real system, trigger alert or other action
        } else {
            printf("Normal operation. Magnitude: %.2f\n", magnitude);
        }
    }
}

StatisticalFeatures calculate_features() {
    StatisticalFeatures features = {0, 0};
    float sum = 0, sum_sq = 0;

    // Calculate mean
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float mag = calculate_magnitude(accel_buffer[i]);
        sum += mag;
    }
    features.mean = sum / WINDOW_SIZE;

    // Calculate standard deviation
    for (int i = 0; i < WINDOW_SIZE; i++) {
        float mag = calculate_magnitude(accel_buffer[i]);
        sum_sq += (mag - features.mean) * (mag - features.mean);
    }
    features.std_dev = sqrt(sum_sq / WINDOW_SIZE);

    return features;
}

float calculate_magnitude(AccelerometerData data) {
    // Calculate vector magnitude (Euclidean norm)
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

bool detect_anomaly(StatisticalFeatures features, float magnitude) {
    // Simple threshold-based anomaly detection
    float z_score = fabs(magnitude - features.mean) / features.std_dev;
    return z_score > ANOMALY_THRESHOLD;
}
