#include <Wire.h>
#include <Adafruit_MPU6050.h>  // Or equivalent library for your accelerometer

Adafruit_MPU6050 mpu;
const int ledPin = 13;  // For visual feedback

// Anomaly detection parameters
const float ANOMALY_THRESHOLD = 1.5;  // g-force threshold for anomaly
const unsigned long SAMPLE_INTERVAL = 100;  // ms between samples
unsigned long lastSampleTime = 0;

// Moving average filter
const int WINDOW_SIZE = 5;
float accelBuffer[WINDOW_SIZE][3];  // Stores x, y, z values
int bufferIndex = 0;

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);

  // Initialize accelerometer
  if (!mpu.begin()) {
    Serial.println("Failed to find MPU6050 chip");
    while (1) delay(10);
  }

  // Configure accelerometer
  mpu.setAccelerometerRange(MPU6050_RANGE_8_G);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);

  // Initialize buffer
  for (int i = 0; i < WINDOW_SIZE; i++) {
    for (int j = 0; j < 3; j++) {
      accelBuffer[i][j] = 0;
    }
  }
}

void loop() {
  unsigned long currentTime = millis();

  if (currentTime - lastSampleTime >= SAMPLE_INTERVAL) {
    lastSampleTime = currentTime;

    // Read accelerometer data
    sensors_event_t a, g, temp;
    mpu.getEvent(&a, &g, &temp);

    // Store current reading in buffer
    accelBuffer[bufferIndex][0] = a.acceleration.x;
    accelBuffer[bufferIndex][1] = a.acceleration.y;
    accelBuffer[bufferIndex][2] = a.acceleration.z;
    bufferIndex = (bufferIndex + 1) % WINDOW_SIZE;

    // Calculate moving average
    float avgX = 0, avgY = 0, avgZ = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
      avgX += accelBuffer[i][0];
      avgY += accelBuffer[i][1];
      avgZ += accelBuffer[i][2];
    }
    avgX /= WINDOW_SIZE;
    avgY /= WINDOW_SIZE;
    avgZ /= WINDOW_SIZE;

    // Calculate total acceleration magnitude (g-force)
    float totalAccel = sqrt(avgX*avgX + avgY*avgY + avgZ*avgZ);

    // Anomaly detection
    bool anomalyDetected = false;
    if (totalAccel > ANOMALY_THRESHOLD || totalAccel < 0.5) {  // Also check for very low values
      anomalyDetected = true;
    }

    // Output results
    Serial.print("Accel: ");
    Serial.print(totalAccel);
