  accel.getEvent(&event);

  // Store current reading in circular buffer
  xData[currentIndex] = event.acceleration.x;
  yData[currentIndex] = event.acceleration.y;
  zData[currentIndex] = event.acceleration.z;

  // Update buffer index
  currentIndex = (currentIndex + 1) % WINDOW_SIZE;
  if (currentIndex == 0) bufferFull = true;

  // Only process if we have enough data
  if (bufferFull) {
    // Calculate statistics
    float xMean, yMean, zMean;
    float xStdDev, yStdDev, zStdDev;

    calculateStats(xData, &xMean, &xStdDev);
    calculateStats(yData, &yMean, &yStdDev);
    calculateStats(zData, &zMean, &zStdDev);

    // Check for anomalies (simple thresholding)
    bool xAnomaly = abs(event.acceleration.x - xMean) > ANOMALY_THRESHOLD * xStdDev;
    bool yAnomaly = abs(event.acceleration.y - yMean) > ANOMALY_THRESHOLD * yStdDev;
    bool zAnomaly = abs(event.acceleration.z - zMean) > ANOMALY_THRESHOLD * zStdDev;

