#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

// Configuration parameters
#define WINDOW_SIZE 20          // Number of samples for moving window
#define ANOMALY_THRESHOLD 2.5   // Standard deviation multiplier for anomaly detection
#define SAMPLE_RATE_HZ 50       // Sensor sampling rate

// Circular buffer for storing accelerometer data
typedef struct {
    float x[WINDOW_SIZE];
    float y[WINDOW_SIZE];
    float z[WINDOW_SIZE];
    int index;
    bool full;
} AccelBuffer;

// Initialize the buffer
void init_buffer(AccelBuffer *buf) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        buf->x[i] = 0.0f;
        buf->y[i] = 0.0f;
        buf->z[i] = 0.0f;
    }
    buf->index = 0;
    buf->full = false;
}

// Add new accelerometer reading to buffer
void add_sample(AccelBuffer *buf, float x, float y, float z) {
    buf->x[buf->index] = x;
    buf->y[buf->index] = y;
    buf->z[buf->index] = z;

    buf->index = (buf->index + 1) % WINDOW_SIZE;
    if (buf->index == 0) {
        buf->full = true;
    }
}

// Calculate mean of a window
float calculate_mean(float *data) {
    float sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum += data[i];
    }
    return sum / WINDOW_SIZE;
}

// Calculate standard deviation of a window
float calculate_std(float *data, float mean) {
    float sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum += (data[i] - mean) * (data[i] - mean);
    }
    return sqrtf(sum / WINDOW_SIZE);
}

// Check for anomalies in the current window
bool detect_anomaly(AccelBuffer *buf) {
    if (!buf->full) return false; // Not enough data

    // Calculate mean and std for each axis
    float mean_x = calculate_mean(buf->x);
    float mean_y = calculate_mean(buf->y);
    float mean_z = calculate_mean(buf->z);

    float std_x = calculate_std(buf->x, mean_x);
    float std_y = calculate_std(buf->y, mean_y);
    float std_z = calculate_std(buf->z, mean_z);

    // Check if any axis exceeds threshold
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (fabsf(buf->x[i] - mean_x) > ANOMALY_THRESHOLD * std_x ||
            fabsf(buf->y[i] - mean_y) > ANOMALY_THRESHOLD * std_y ||
            fabsf(buf->z[i] - mean_z) > ANOMALY_THRESHOLD * std_z) {
            return true;
        }
    }

    return false;
}

// Simulate accelerometer data (for testing)
void simulate_accelerometer_data(AccelBuffer *buf) {
    // Normal data (mostly between -1 and 1)
    for (int i = 0; i < WINDOW_SIZE * 2; i++) {
