```cpp
#include <Wire.h>
#include <MPU6050.h>

// Initialize MPU6050
MPU6050 mpu;

// Configuration parameters
const int windowSize = 20;  // Number of samples for moving average
const float threshold = 2.5; // Anomaly detection threshold (standard deviations)

// Data storage
float accelX[windowSize];
float accelY[windowSize];
float accelZ[windowSize];
int currentIndex = 0;
bool dataReady = false;

void setup() {
  Serial.begin(9600);
  Wire.begin();

  // Initialize MPU6050
  mpu.initialize();
  if (!mpu.testConnection()) {
    Serial.println("MPU6050 connection failed");
    while(1); // Halt if sensor not found
  }

  // Initialize data arrays
  for (int i = 0; i < windowSize; i++) {
    accelX[i] = 0;
    accelY[i] = 0;
    accelZ[i] = 0;
  }
}

void loop() {
  // Read accelerometer data
  int16_t ax, ay, az;
  mpu.getAcceleration(&ax, &ay, &az);

  // Convert to g-force (assuming ±2g range)
  float currentX = ax / 16384.0;
  float currentY = ay / 16384.0;
  float currentZ = az / 16384.0;

  // Store current reading
  accelX[currentIndex] = currentX;
  accelY[currentIndex] = currentY;
  accelZ[currentIndex] = currentZ;

  // Calculate statistics if we have enough data
  if (currentIndex == windowSize - 1) {
    dataReady = true;
  }

  if (dataReady) {
    // Calculate mean
    float meanX = 0, meanY = 0, meanZ = 0;
    for (int i = 0; i < windowSize; i++) {
      meanX += accelX[i];
      meanY += accelY[i];
      meanZ += accelZ[i];
    }
    meanX /= windowSize;
    meanY /= windowSize;
    meanZ /= windowSize;

    // Calculate standard deviation
    float stdDevX = 0, stdDevY = 0, stdDevZ = 0;
    for (int i = 0; i < windowSize; i++) {
      stdDevX += pow(accelX[i] - meanX, 2);
      stdDevY += pow(accelY[i] - meanY, 2);
      stdDevZ += pow(accelZ[i] - meanZ, 2);
    }
    stdDevX = sqrt(stdDevX / windowSize);
    stdDevY = sqrt(stdDevY / windowSize);
    stdDevZ = sqrt(stdDevZ / windowSize);

    // Check for anomalies
    bool anomalyDetected = false;
    if (abs(currentX - meanX) > threshold * stdDevX ||
        abs(currentY - meanY) > threshold * stdDevY ||
        abs(currentZ - meanZ) > threshold * stdDevZ) {
      anomalyDetected = true;
    }

    // Output results
    Serial.print("X: "); Serial.print(currentX);
    Serial.print(" Y: "); Serial.print(currentY);
    Serial.print(" Z: "); Serial.print(currentZ);
    Serial.print(" | Anomaly: "); Serial.println(anomalyDetected ? "YES" : "NO");
  }

  // Update index (circular buffer)
  currentIndex = (currentIndex + 1) % windowSize;

  delay(100); // Adjust based on your sampling needs
}
