```c
#include <Wire.h>
#include <Adafruit_MPU6050.h>  // Or equivalent library for your accelerometer

// Configuration
#define SAMPLE_WINDOW 100      // Number of samples for baseline calculation
#define ANOMALY_THRESHOLD 2.5   // Standard deviations from mean to trigger anomaly

// Global variables
Adafruit_MPU6050 mpu;
float baseline_mean[3] = {0, 0, 0};
float baseline_std[3] = {0, 0, 0};
float current_sample[3];
int sample_count = 0;

// Initialize system
void setup() {
  Serial.begin(115200);
  while (!Serial) delay(10); // Wait for serial monitor

  if (!mpu.begin()) {
    Serial.println("Failed to find MPU6050 chip");
    while (1) delay(10);
  }

  Serial.println("Accelerometer anomaly detection system ready");
  Serial.println("Collecting baseline data...");

  // Collect initial baseline data
  for (int i = 0; i < SAMPLE_WINDOW; i++) {
    update_baseline();
    delay(10); // Adjust based on your sampling rate
  }

  Serial.println("Baseline established. Monitoring for anomalies...");
}

// Main loop
void loop() {
  // Read current accelerometer data
  sensors_event_t a, g, temp;
  mpu.getEvent(&a, &g, &temp);

  current_sample[0] = a.acceleration.x;
  current_sample[1] = a.acceleration.y;
  current_sample[2] = a.acceleration.z;

  // Check for anomalies
  if (is_anomaly()) {
    Serial.println("ANOMALY DETECTED!");
    // Add your anomaly response here (e.g., LED flash, buzzer, etc.)
  }

  // Update baseline periodically
  if (sample_count % 10 == 0) { // Update every 10 samples
    update_baseline();
  }

  sample_count++;
  delay(10); // Adjust based on your sampling rate
}

// Update baseline statistics
void update_baseline() {
  // Simple moving average and standard deviation calculation
  for (int i = 0; i < 3; i++) {
    float delta = current_sample[i] - baseline_mean[i];
    baseline_mean[i] += delta / SAMPLE_WINDOW;
    baseline_std[i] += delta * (current_sample[i] - baseline_mean[i]);
  }

  // Calculate standard deviation (simplified)
  if (sample_count >= SAMPLE_WINDOW) {
    for (int i = 0; i < 3; i++) {
      baseline_std[i] = sqrt(baseline_std[i] / SAMPLE_WINDOW);
    }
  }
}

// Check if current sample is an anomaly
bool is_anomaly() {
  for (int i = 0; i < 3; i++) {
    if (sample_count >= SAMPLE_WINDOW) {
      float z_score = abs(current_sample[i] - baseline_mean[i]) / baseline_std[i];
      if (z_score > ANOMALY_THRESHOLD) {
        return true;
      }
    }
  }
  return false;
}
