# Resource-Constrained Edge System for Sensor Data Filtering and Actuator Management

Below is a C++ implementation for a lightweight edge system that filters sensor data and manages actuators, optimized for resource-constrained environments.

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>
#include <atomic>
#include <mutex>

class EdgeSystem {
private:
    // Configuration parameters
    static constexpr int MAX_SENSOR_READINGS = 100;
    static constexpr float TEMPERATURE_THRESHOLD = 30.0f; // °C
    static constexpr float HUMIDITY_THRESHOLD = 60.0f;    // %
    static constexpr int ACTUATOR_COOLDOWN_MS = 5000;     // 5 seconds

    // Sensor data structure
    struct SensorData {
        float temperature;
        float humidity;
        std::chrono::system_clock::time_point timestamp;
    };

    // Actuator state
    enum class ActuatorState { OFF, ON, COOLING_DOWN };

    // System state
    std::vector<SensorData> sensorHistory;
    std::mutex dataMutex;
    std::atomic<ActuatorState> actuatorState{ActuatorState::OFF};
    std::chrono::system_clock::time_point lastActuatorTrigger;

    // Simple moving average filter
    float calculateMovingAverage(const std::vector<float>& values, int windowSize) {
        if (values.empty() || windowSize <= 0) return 0.0f;

        int actualWindow = std::min(windowSize, static_cast<int>(values.size()));
        float sum = 0.0f;

        for (int i = values.size() - actualWindow; i < values.size(); ++i) {
            sum += values[i];
        }

        return sum / actualWindow;
    }

    // Basic outlier detection
    bool isOutlier(float value, const std::vector<float>& history) {
        if (history.size() < 3) return false;

        // Simple 3-sigma rule
        float sum = 0.0f;
        for (float v : history) sum += v;
        float mean = sum / history.size();

        float variance = 0.0f;
        for (float v : history) variance += (v - mean) * (v - mean);
        float stddev = std::sqrt(variance / history.size());

        return std::abs(value - mean) > 3 * stddev;
    }

public:
    // Process incoming sensor data
    void processSensorData(float temperature, float humidity) {
        std::lock_guard<std::mutex> lock(dataMutex);

        // Store the new reading
        SensorData newData;
        newData.temperature = temperature;
        newData.humidity = humidity;
        newData.timestamp = std::chrono::system_clock::now();

        // Maintain history (simple circular buffer)
        if (sensorHistory.size() >= MAX_SENSOR_READINGS) {
            sensorHistory.erase(sensorHistory.begin());
        }
        sensorHistory.push_back(newData);

        // Extract temperature and humidity histories
        std::vector<float> tempHistory, humidityHistory;
        for (const auto& data : sensorHistory) {
            tempHistory.push_back(data.temperature);
            humidityHistory.push_back(data.humidity);
        }

        // Apply filters
        float filteredTemp = calculateMovingAverage(tempHistory, 5);
        float filteredHumidity = calculateMovingAverage(humidityHistory, 5);

        // Check for outliers
        bool tempOutlier = isOutlier(temperature, tempHistory);
        bool humidityOutlier = isOutlier(humidity, humidityHistory);

        // Decision logic
        bool shouldTriggerActuator = false;

        if (!tempOutlier && !humidityOutlier) {
            // Only consider filtered data if no outliers
            shouldTriggerActuator = (filteredTemp > TEMPERATURE_THRESHOLD) ||
                                   (filteredHumidity > HUMIDITY_THRESHOLD);
        } else {
            // If outliers detected, use raw data but with caution
            shouldTriggerActuator = (temperature > TEMPERATURE_THRESHOLD * 1.2f) ||
                                   (humidity > HUMIDITY_THRESHOLD * 1.2f);
        }

        // Actuator management
        auto now = std::chrono::system_clock::now();
        auto cooldownEnd = lastActuatorTrigger + std::chrono::milliseconds(ACTUATOR_COOLDOWN_MS);

        if (shouldTriggerActuator) {
            if (actuatorState == ActuatorState::OFF && now >= cooldownEnd) {
                actuatorState = ActuatorState::ON;
                lastActuatorTrigger = now;
                std::cout << "Actuator triggered at: "
                          << std::chrono::system_clock::to_time_t(now) << std::endl;
            }
        } else {
            if (actuatorState == ActuatorState::ON) {
                actuatorState = ActuatorState::COOLING_DOWN;
            } else if (actuatorState == ActuatorState::COOLING_DOWN && now >= cooldownEnd) {
                actuatorState = ActuatorState::OFF;
            }
        }
    }

    // Get current actuator state
    ActuatorState getActuatorState() const {
        return actuatorState.load();
    }

    // Get filtered sensor data
    void getFilteredData(float& temperature, float& humidity) {
        std::lock_guard<std::mutex> lock(dataMutex);

        if (sensorHistory.empty()) {
            temperature = 0.0f;
            humidity = 0.0f;
            return;
        }

        std::vector<float> tempHistory, humidityHistory;
        for (const auto& data : sensorHistory) {
            tempHistory.push_back(data.temperature);
            humidityHistory.push_back(data.humidity);
        }

        temperature = calculateMovingAverage(tempHistory, 5);
        humidity = calculateMovingAverage(humidityHistory, 5);
    }
};

// Example usage
int main() {
    EdgeSystem edgeSystem;

    // Simulate sensor readings
    for (int i = 0; i < 100; ++i) {
        // Normal readings
        float temp = 25.0f + (i % 10) * 0.5f;
        float humidity = 50.0f + (i % 5) * 2.0f;

        // Occasionally add some noise or outliers
        if (i % 20 == 0) {
            temp += 15.0f; // Outlier
        }

        edgeSystem.processSensorData(temp, humidity);

        // Get filtered data
        float filteredTemp, filteredHumidity;
        edgeSystem.getFilteredData(filteredTemp, filteredHumidity);

        std::cout << "Raw: " << temp << "°C, " << humidity << "% | "
                  << "Filtered: " << filteredTemp << "°C, " << filteredHumidity << "% | "
                  << "Actuator: " << (edgeSystem.getActuatorState() == EdgeSystem::ActuatorState::ON ? "ON" : "OFF")
                  << std::endl;

        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
