```python
import time
import threading
from collections import deque
import json
import logging
from abc import ABC, abstractmethod

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class Sensor(ABC):
    """Abstract base class for sensors"""

    @abstractmethod
    def read(self):
        """Read sensor data"""
        pass

    @abstractmethod
    def get_id(self):
        """Get sensor identifier"""
        pass

class Actuator(ABC):
    """Abstract base class for actuators"""

    @abstractmethod
    def activate(self, value):
        """Activate actuator with given value"""
        pass

    @abstractmethod
    def get_id(self):
        """Get actuator identifier"""
        pass

class TemperatureSensor(Sensor):
    """Example temperature sensor implementation"""

    def __init__(self, sensor_id):
        self.sensor_id = sensor_id
        self.simulated_temp = 25.0  # Starting temperature

    def read(self):
        """Simulate temperature reading with some noise"""
        import random
        self.simulated_temp += random.uniform(-0.5, 0.5)
        self.simulated_temp = max(0, min(50, self.simulated_temp))  # Clamp between 0-50°C
        return {
            'timestamp': time.time(),
            'value': round(self.simulated_temp, 2),
            'unit': '°C'
        }

    def get_id(self):
        return self.sensor_id

class RelayActuator(Actuator):
    """Example relay actuator implementation"""

    def __init__(self, actuator_id):
        self.actuator_id = actuator_id
        self.state = False

    def activate(self, value):
        """Activate/deactivate relay based on threshold"""
        threshold = 30.0  # Example threshold
        self.state = value > threshold
        logger.info(f"Actuator {self.actuator_id} {'ON' if self.state else 'OFF'} (value: {value})")
        return self.state

    def get_id(self):
        return self.actuator_id

class DataFilter:
    """Lightweight data filtering and processing"""

    def __init__(self, window_size=5, threshold=2.0):
        self.window_size = window_size
        self.threshold = threshold
        self.data_window = deque(maxlen=window_size)

    def process(self, data):
        """Filter and process sensor data"""
        if not data or 'value' not in data:
            return None

        # Simple moving average filter
        self.data_window.append(data['value'])
        if len(self.data_window) < self.window_size:
            return None

        avg = sum(self.data_window) / len(self.data_window)

        # Detect significant changes
        if abs(data['value'] - avg) > self.threshold:
            logger.warning(f"Significant change detected: {data['value']} (avg: {avg})")
            data['filtered'] = True
        else:
            data['filtered'] = False

        data['processed_value'] = avg
        return data

class EdgeSystem:
    """Main edge system controller"""

    def __init__(self, config=None):
        self.sensors = []
        self.actuators = []
        self.filters = {}
        self.running = False
        self.sample_interval = 1.0  # seconds
        self.config = config or {}

        # Initialize components
        self._initialize_components()

    def _initialize_components(self):
        """Initialize sensors and actuators based on configuration"""
        # Default configuration if none provided
        if not self.config:
            self.config = {
                'sensors': [
                    {'type': 'temperature', 'id': 'temp1'}
                ],
                'actuators': [
                    {'type': 'relay', 'id': 'relay1'}
                ],
                'filters': {
                    'temp1': {'window_size': 5, 'threshold': 2.0}
                }
            }

        # Create sensors
        for sensor_config in self.config.get('sensors', []):
            if sensor_config['type'] == 'temperature':
                self.sensors.append(TemperatureSensor(sensor_config['id']))

        # Create actuators
        for actuator_config in self.config.get('actuators', []):
            if actuator_config['type'] == 'relay':
                self.actuators.append(RelayActuator(actuator_config['id']))

        # Create filters
        for sensor_id, filter_config in self.config.get('filters', {}).items():
            self.filters[sensor_id] = DataFilter(**filter_config)

    def _read_sensors(self):
        """Read data from all sensors"""
        sensor_data = {}
        for sensor in self.sensors:
            data = sensor.read()
            if data:
                sensor_data[sensor.get_id()] = data
        return sensor_data

    def _process_data(self, sensor_data):
        """Process sensor data through filters"""
        processed_data = {}
        for sensor_id, data in sensor_data.items():
            if sensor_id in self.filters:
                processed = self.filters[sensor_id].process(data)
                if processed:
                    processed_data[sensor_id] = processed
            else:
                processed_data[sensor_id] = data
        return processed_data

    def _control_actuators(self, processed_data):
        """Control actuators based on processed data"""
        for actuator in self.actuators:
            # Simple mapping - could be more sophisticated
            for sensor_id, data in processed_data.items():
                if sensor_id.startswith('temp') and actuator.get_id().startswith('relay'):
                    actuator.activate(data.get('processed_value', data['value']))

    def _main_loop(self):
        """Main control loop"""
        while self.running:
            start_time = time.time()

            # Read sensors
            sensor_data = self._read_sensors()

            # Process data
            processed_data = self._process_data(sensor_data)

            # Control actuators
            self._control_actuators(processed_data)

            # Log results
            logger.info(f"Cycle complete. Processed data: {json.dumps(processed_data, indent=2)}")

            # Calculate sleep time to maintain interval
            elapsed = time.time() - start_time
            sleep_time = max(0, self.sample_interval - elapsed)
            time.sleep(sleep_time)

    def start(self):
        """Start the edge system"""
        if not self.running:
            self.running = True
            self.control_thread = threading.Thread(target=self._main_loop)
            self.control_thread.daemon = True
            self.control_thread.start()
            logger.info("Edge system started")

    def stop(self):
        """Stop the edge system"""
        if self.running:
            self.running = False
            if hasattr(self, 'control_thread'):
                self.control_thread.join()
            logger.info("Edge system stopped")

    def get_status(self):
        """Get current system status"""
        return {
            'running': self.running,
            'sensors': [s.get_id() for s in self.sensors],
            'actuators': [a.get_id() for a in self.actuators],
            'filters': list(self.filters.keys())
        }

# Example usage
if __name__ == "__main__":
