```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

// Configuration constants
#define MAX_SENSOR_DATA 100
#define SENSOR_WINDOW_SIZE 5
#define ACTUATOR_THRESHOLD 80.0f
#define MAX_ACTUATOR_COMMANDS 10

// Sensor data structure
typedef struct {
    float value;
    time_t timestamp;
} SensorData;

// Actuator command structure
typedef struct {
    bool activate;
    time_t timestamp;
} ActuatorCommand;

// Edge system state
typedef struct {
    SensorData sensor_buffer[MAX_SENSOR_DATA];
    uint16_t sensor_count;
    ActuatorCommand actuator_commands[MAX_ACTUATOR_COMMANDS];
    uint16_t command_count;
    float current_filtered_value;
} EdgeSystem;

// Initialize the edge system
void init_edge_system(EdgeSystem* system) {
    system->sensor_count = 0;
    system->command_count = 0;
    system->current_filtered_value = 0.0f;
    memset(system->sensor_buffer, 0, sizeof(system->sensor_buffer));
    memset(system->actuator_commands, 0, sizeof(system->actuator_commands));
}

// Simple moving average filter
void filter_sensor_data(EdgeSystem* system, float new_value) {
    // Add new data point
    if (system->sensor_count < MAX_SENSOR_DATA) {
        system->sensor_buffer[system->sensor_count].value = new_value;
        system->sensor_buffer[system->sensor_count].timestamp = time(NULL);
        system->sensor_count++;
    } else {
        // Shift buffer and add new value
        memmove(system->sensor_buffer, system->sensor_buffer + 1,
               (MAX_SENSOR_DATA - 1) * sizeof(SensorData));
        system->sensor_buffer[MAX_SENSOR_DATA - 1].value = new_value;
        system->sensor_buffer[MAX_SENSOR_DATA - 1].timestamp = time(NULL);
    }

    // Calculate moving average of last SENSOR_WINDOW_SIZE values
    uint16_t start = (system->sensor_count > SENSOR_WINDOW_SIZE) ?
                     (system->sensor_count - SENSOR_WINDOW_SIZE) : 0;
    float sum = 0.0f;
    uint16_t count = 0;

    for (uint16_t i = start; i < system->sensor_count; i++) {
        sum += system->sensor_buffer[i].value;
        count++;
    }

    system->current_filtered_value = (count > 0) ? (sum / count) : new_value;
}

// Process filtered data and generate actuator commands
void process_actuator_commands(EdgeSystem* system) {
    if (system->command_count >= MAX_ACTUATOR_COMMANDS) {
        // Shift commands if buffer is full
        memmove(system->actuator_commands, system->actuator_commands + 1,
               (MAX_ACTUATOR_COMMANDS - 1) * sizeof(ActuatorCommand));
        system->command_count--;
    }

    // Create new command based on filtered value
    ActuatorCommand cmd;
    cmd.timestamp = time(NULL);
    cmd.activate = (system->current_filtered_value > ACTUATOR_THRESHOLD);

    system->actuator_commands[system->command_count] = cmd;
    system->command_count++;
}

// Simulate sensor reading
float read_sensor() {
    // In a real system, this would read from actual hardware
    // For simulation, return a random value between 0-100
    return (float)(rand() % 100);
}

// Simulate actuator control
void control_actuator(bool activate) {
    // In a real system, this would control actual hardware
    printf("Actuator %s\n", activate ? "ON" : "OFF");
}

// Main edge processing loop
void edge_processing_loop(EdgeSystem* system) {
    while (true) {
        // Read sensor data
        float sensor_value = read_sensor();
        printf("Raw sensor value: %.2f\n", sensor_value);

        // Filter the data
        filter_sensor_data(system, sensor_value);
        printf("Filtered value: %.2f\n", system->current_filtered_value);

        // Process actuator commands
        process_actuator_commands(system);

        // Execute the latest actuator command
        if (system->command_count > 0) {
            control_actuator(system->actuator_commands[system->command_count - 1].activate);
        }

        // Simulate processing delay (e.g., for resource-constrained systems)
        // In a real system, this would be event-driven or sleep-based
        for (volatile int i = 0; i < 1000000; i++); // Simple delay simulation
    }
}

int main() {
    EdgeSystem system;
    init_edge_system(&system);

    // Seed random number generator
    srand(time(NULL));

    // Start processing loop
    edge_processing_loop(&system);

    return 0;
}
