#include <stdint.h>
#include <stdbool.h>

// Configuration constants
#define SAMPLE_BUFFER_SIZE 10
#define ACTUATOR_THRESHOLD 50

// Simple moving average filter
typedef struct {
    int16_t buffer[SAMPLE_BUFFER_SIZE];
    uint8_t index;
    int16_t sum;
} MovingAverageFilter;

// Actuator state
typedef enum {
    ACTUATOR_OFF = 0,
    ACTUATOR_ON
} ActuatorState;

// System state
typedef struct {
    MovingAverageFilter sensorFilter;
    ActuatorState actuatorState;
} EdgeSystem;

// Initialize the system
void edgeSystemInit(EdgeSystem* system) {
    // Initialize filter
    for (uint8_t i = 0; i < SAMPLE_BUFFER_SIZE; i++) {
        system->sensorFilter.buffer[i] = 0;
    }
    system->sensorFilter.index = 0;
    system->sensorFilter.sum = 0;

    // Initialize actuator
    system->actuatorState = ACTUATOR_OFF;
}

// Process a new sensor reading
void processSensorReading(EdgeSystem* system, int16_t rawValue) {
    // Apply moving average filter
    system->sensorFilter.sum -= system->sensorFilter.buffer[system->sensorFilter.index];
    system->sensorFilter.buffer[system->sensorFilter.index] = rawValue;
    system->sensorFilter.sum += rawValue;

    if (++system->sensorFilter.index >= SAMPLE_BUFFER_SIZE) {
        system->sensorFilter.index = 0;
    }

    int16_t filteredValue = system->sensorFilter.sum / SAMPLE_BUFFER_SIZE;

    // Control actuator based on filtered value
    if (filteredValue > ACTUATOR_THRESHOLD) {
        if (system->actuatorState != ACTUATOR_ON) {
            system->actuatorState = ACTUATOR_ON;
