// System configuration
#define SENSOR_PIN 0
#define ACTUATOR_PIN 1
#define FILTER_WINDOW 5  // Number of samples for moving average
#define THRESHOLD 50     // Actuation threshold

// Global variables
float sensorBuffer[FILTER_WINDOW] = {0};
int bufferIndex = 0;
float filteredValue = 0;
bool actuatorState = false;

// Initialize system
void setup() {
    pinMode(SENSOR_PIN, INPUT);
    pinMode(ACTUATOR_PIN, OUTPUT);
    digitalWrite(ACTUATOR_PIN, LOW);
}

// Read sensor with basic noise filtering
float readFilteredSensor() {
    // Read raw value
    float rawValue = analogRead(SENSOR_PIN);

    // Simple moving average filter
    sensorBuffer[bufferIndex] = rawValue;
    bufferIndex = (bufferIndex + 1) % FILTER_WINDOW;

    // Calculate average
    float sum = 0;
    for (int i = 0; i < FILTER_WINDOW; i++) {
        sum += sensorBuffer[i];
    }
    filteredValue = sum / FILTER_WINDOW;

    return filteredValue;
}

// Control actuator based on filtered data
void controlActuator(float value) {
    if (value > THRESHOLD && !actuatorState) {
        digitalWrite(ACTUATOR_PIN, HIGH);
        actuatorState = true;
    } else if (value <= THRESHOLD && actuatorState) {
        digitalWrite(ACTUATOR_PIN, LOW);
        actuatorState = false;
    }
}

// Main system loop
void loop() {
    // Read and filter sensor data
    float currentValue = readFilteredSensor();

    // Control actuators
    controlActuator(currentValue);

    // Minimal delay to prevent CPU overload
    delay(100);
}
