        torus.position.set(0, 1, 5);
        torus.castShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Custom shader material
        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color1: { value: new THREE.Color(0xff0000) },
                color2: { value: new THREE.Color(0x0000ff) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);
                    vec3 newPosition = position + normal * sin(position.x * 10.0 + time) * 0.1;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color1;
                uniform vec3 color2;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vec3 color = mix(color1, color2, vUv.y);
                    float intensity = pow(0.5 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 2.0);
                    gl_FragColor = vec4(color * intensity, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Apply custom shader to one object
        const shaderCube = new THREE.Mesh(
            new THREE.BoxGeometry(2, 2, 2),
            customShaderMaterial
        );
        shaderCube.position.set(0, 1, -5);
        shaderCube.castShadow = true;
        scene.add(shaderCube);
        objects.push(shaderCube);

        // Animation variables
        let time = 0;
        let lightsEnabled = true;
        let shadersEnabled = true;

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update time
            time += 0.01;

            // Animate objects
            objects.forEach((obj, i) => {
                obj.rotation.x = Math.sin(time + i) * 0.5;
                obj.rotation.y = Math.cos(time + i * 0.7) * 0.5;
            });

            // Animate lights
            if (lightsEnabled) {
                pointLights.forEach((light, i) => {
                    const angle = time * (i + 1) * 0.5;
                    light.position.x = Math.sin(angle) * 5;
                    light.position.z = Math.cos(angle) * 5;
                });
            }

            // Update shader uniforms
            if (shadersEnabled) {
                customShaderMaterial.uniforms.time.value = time;
            }

            // Update controls
            controls.update();

            // Render
            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Keyboard controls
        document.addEventListener('keydown', (event) => {
            switch (event.code) {
                case 'KeyL':
                    lightsEnabled = !lightsEnabled;
                    pointLights.forEach(light => light.visible = lightsEnabled);
                    break;
                case 'KeyS':
                    shadersEnabled = !shadersEnabled;
                    if (shadersEnabled) {
                        shaderCube.material = customShaderMaterial;
                    } else {
                        shaderCube.material = new THREE.MeshStandardMaterial({
                            color: 0x00ff00,
                            roughness: 0.3,
                            metalness: 0.7
                        });
                    }
                    break;
            }
        });

        // Start animation
        animate();
    </script>
</body>
</html>
