        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Dynamic point lights
        const pointLights = [];
        const lightHelpers = [];

        function createDynamicLight(color, intensity, distance, decay) {
            const light = new THREE.PointLight(color, intensity, distance, decay);
            light.castShadow = true;
            light.shadow.mapSize.width = 1024;
            light.shadow.mapSize.height = 1024;
            light.shadow.camera.near = 0.5;
            light.shadow.camera.far = 500;

            // Add to scene
            scene.add(light);
            pointLights.push(light);

            // Add helper
            const helper = new THREE.PointLightHelper(light, 0.5);
            scene.add(helper);
            lightHelpers.push(helper);

            // Update light count display
            document.getElementById('lightCount').textContent = pointLights.length;

            return light;
        }

        // Create some initial lights
        createDynamicLight(0xff0000, 2, 20, 2);
        createDynamicLight(0x00ff00, 2, 20, 2);
        createDynamicLight(0x0000ff, 2, 20, 2);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Custom shader material for special effects
        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                lightPos: { value: new THREE.Vector3() },
                resolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Simple wave effect
                    vec3 newPosition = position + normal * sin(position.x * 5.0 + time) * 0.1;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 lightPos;
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Calculate light direction
                    vec3 lightDir = normalize(lightPos - vPosition);
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Color with light effect
                    vec3 color = vec3(0.5, 0.7, 1.0) * diffuse;

                    // Add some noise for texture
                    float noise = fract(sin(dot(vPosition, vec3(12.9898, 78.233, 45.543))) * 43758.5453);
                    color += noise * 0.1;

                    // Add some animation
                    color += sin(vUv.x * 10.0 + time) * 0.1;

                    gl_FragColor = vec4(color, 1.0);
                }
            `,
            side: THREE.DoubleSide,
            transparent: true
        });

        // Create objects with custom shader
        const sphereGeometry = new THREE.SphereGeometry(2, 32, 32);
        const sphere = new THREE.Mesh(sphereGeometry, customShaderMaterial);
        sphere.position.set(-5, 2, 0);
        sphere.castShadow = true;
        scene.add(sphere);

        // Create a torus knot with standard material
        const torusKnotGeometry = new THREE.TorusKnotGeometry(1, 0.4, 100, 16);
        const torusKnotMaterial = new THREE.MeshStandardMaterial({
            color: 0xff5500,
            roughness: 0.4,
            metalness: 0.7
        });
        const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
        torusKnot.position.set(5, 2, 0);
        torusKnot.castShadow = true;
        scene.add(torusKnot);

        // Create a box with phong material
        const boxGeometry = new THREE.BoxGeometry(3, 3, 3);
        const boxMaterial = new THREE.MeshPhongMaterial({
            color: 0x00aaff,
            specular: 0x111111,
            shininess: 30
        });
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        box.position.set(0, 1.5, 5);
        box.castShadow = true;
        scene.add(box);

        // Animation variables
        let time = 0;
        const clock = new THREE.Clock();

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // Update controls
            controls.update();

            // Animate lights
            pointLights.forEach((light, index) => {
                const angle = time * (0.5 + index * 0.3);
                const radius = 8 + index * 2;
                light.position.x = Math.cos(angle) * radius;
                light.position.z = Math.sin(angle) * radius;
                light.position.y = 5 + Math.sin(time * 2 + index) * 2;

                // Update shader uniforms if this is the first light
                if (index === 0) {
                    customShaderMaterial.uniforms.lightPos.value.copy(light.position);
                    customShaderMaterial.uniforms.time.value = time;
                }
            });

            // Animate objects
            sphere.rotation.y += delta * 0.5;
            torusKnot.rotation.x += delta * 0.3;
            torusKnot.rotation.y += delta * 0.2;
            box.rotation.y += delta * 0.4;

            // Render
            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            customShaderMaterial.uniforms.resolution.value.set(window.innerWidth, window.innerHeight);
        });

        // Start animation
