        addLightBtn.textContent = 'Add Light';
        addLightBtn.style.position = 'absolute';
        addLightBtn.style.bottom = '20px';
        addLightBtn.style.left = '20px';
        addLightBtn.style.padding = '10px';
        addLightBtn.style.backgroundColor = '#444';
        addLightBtn.style.color = 'white';
