        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        // Point lights that will move
        const pointLights = [];
        const pointLightColors = [0xff0000, 0x00ff00, 0x0000ff, 0xffff00];

        for (let i = 0; i < 4; i++) {
            const pointLight = new THREE.PointLight(pointLightColors[i], 1, 20);
            pointLight.position.set(
                Math.random() * 10 - 5,
                Math.random() * 5 + 1,
                Math.random() * 10 - 5
            );
            pointLight.castShadow = true;
            pointLight.shadow.mapSize.width = 512;
            pointLight.shadow.mapSize.height = 512;
            pointLight.shadow.camera.near = 0.1;
            pointLight.shadow.camera.far = 20;
            scene.add(pointLight);

            // Add a small sphere to visualize the light
            const lightSphere = new THREE.Mesh(
                new THREE.SphereGeometry(0.2, 16, 16),
                new THREE.MeshBasicMaterial({ color: pointLightColors[i] })
            );
            lightSphere.position.copy(pointLight.position);
            scene.add(lightSphere);

            pointLights.push({
                light: pointLight,
                sphere: lightSphere,
                direction: new THREE.Vector3(
                    Math.random() * 0.02 - 0.01,
                    Math.random() * 0.02 - 0.01,
                    Math.random() * 0.02 - 0.01
                )
            });
        }

        // Custom shader material for advanced effects
        const customMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                lightPos: { value: new THREE.Vector3() },
                lightColor: { value: new THREE.Color(0xffffff) }
            },
            vertexShader: `
                uniform float time;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Simple wave effect
                    vec3 newPosition = position;
                    newPosition.y += sin(position.x * 2.0 + time) * 0.1;
                    newPosition.z += cos(position.y * 2.0 + time) * 0.1;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 lightPos;
                uniform vec3 lightColor;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Calculate lighting
                    vec3 lightDir = normalize(lightPos - vPosition);
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Base color with lighting
                    vec3 color = vec3(0.5, 0.7, 0.9) * (0.5 + diffuse * 0.5);

                    // Add some specular highlights
                    vec3 viewDir = normalize(-vPosition);
                    vec3 reflectDir = reflect(-lightDir, vNormal);
                    float specular = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
                    color += lightColor * specular * 0.5;

                    gl_FragColor = vec4(color, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Create objects with different materials
        const objects = [];

        // Floor
        const floorGeometry = new THREE.PlaneGeometry(20, 20);
        const floorMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const floor = new THREE.Mesh(floorGeometry, floorMaterial);
        floor.rotation.x = -Math.PI / 2;
        floor.receiveShadow = true;
        scene.add(floor);
        objects.push(floor);

        // Boxes
        for (let i = 0; i < 5; i++) {
            const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
            const boxMaterial = i % 2 === 0 ?
                new THREE.MeshStandardMaterial({
                    color: Math.random() * 0xffffff,
                    roughness: 0.4,
                    metalness: 0.6
                }) : customMaterial;

            const box = new THREE.Mesh(boxGeometry, boxMaterial);
            box.position.set(
                Math.random() * 8 - 4,
                0.5,
                Math.random() * 8 - 4
            );
            box.castShadow = true;
            box.receiveShadow = true;
            scene.add(box);
            objects.push(box);
        }

        // Sphere
        const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0xff5555,
            roughness: 0.3,
            metalness: 0.7,
            emissive: 0x220000,
            emissiveIntensity: 0.5
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(3, 1, 0);
        sphere.castShadow = true;
        sphere.receiveShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Torus
        const torusGeometry = new THREE.TorusGeometry(1, 0.4, 16, 32);
        const torusMaterial = new THREE.MeshStandardMaterial({
            color: 0x5555ff,
            roughness: 0.2,
            metalness: 0.8
        });
        const torus = new THREE.Mesh(torusGeometry, torusMaterial);
        torus.position.set(-3, 1, 0);
        torus.castShadow = true;
        torus.receiveShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Animation loop
        let time = 0;
        function animate() {
            requestAnimationFrame(animate);

            // Update time for shaders
            time += 0.01;
            customMaterial.uniforms.time.value = time;

            // Update point lights
            pointLights.forEach((pl, i) => {
                // Move lights in a circular pattern
                pl.light.position.x += pl.direction.x;
                pl.light.position.z += pl.direction.z;

                // Bounce off walls
                if (Math.abs(pl.light.position.x) > 5) {
                    pl.direction.x *= -1;
                }
                if (Math.abs(pl.light.position.z) > 5) {
                    pl.direction.z *= -1;
                }

                // Update light sphere position
                pl.sphere.position.copy(pl.light.position);

                // Update shader uniforms with one of the lights
                if (i === 0) {
                    customMaterial.uniforms.lightPos.value.copy(pl.light.position);
                    customMaterial.uniforms.lightColor.value.copy(pl.light.color);
                }
            });

            // Handle movement
            if (moveKeys.w) controls.moveForward(moveSpeed);
            if (moveKeys.s) controls.moveForward(-moveSpeed);
            if (moveKeys.a) controls.moveRight(-moveSpeed);
            if (moveKeys.d) controls.moveRight(moveSpeed);

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
