            font-family: Arial, sans-serif;
            background: rgba(0, 0, 0, 0.5);
            padding: 10px;
            border-radius: 5px;
        }
    </style>
</head>
<body>
    <div id="info">
        <h2>3D Scene Viewer</h2>
        <p>Use mouse to look around, WASD to move</p>
        <p>Lights: <span id="lightCount">0</span></p>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 15);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.PointerLockControls(camera, document.body);
        document.addEventListener('click', () => {
            controls.lock();
        });

        // Movement controls
        const moveSpeed = 0.1;
        const keys = {
            w: false,
            a: false,
            s: false,
            d: false,
            shift: false
        };

        document.addEventListener('keydown', (e) => {
            if (e.key.toLowerCase() === 'w') keys.w = true;
            if (e.key.toLowerCase() === 'a') keys.a = true;
            if (e.key.toLowerCase() === 's') keys.s = true;
            if (e.key.toLowerCase() === 'd') keys.d = true;
            if (e.key === 'Shift') keys.shift = true;
        });

        document.addEventListener('keyup', (e) => {
            if (e.key.toLowerCase() === 'w') keys.w = false;
            if (e.key.toLowerCase() === 'a') keys.a = false;
            if (e.key.toLowerCase() === 's') keys.s = false;
            if (e.key.toLowerCase() === 'd') keys.d = false;
            if (e.key === 'Shift') keys.shift = false;
        });

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(10, 20, 10);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        scene.add(directionalLight);

        // Dynamic point lights
        const pointLights = [];
        const lightHelpers = [];

        function createDynamicLights(count = 3) {
            // Clear existing lights
            pointLights.forEach(light => scene.remove(light));
            lightHelpers.forEach(helper => scene.remove(helper));
            pointLights.length = 0;
            lightHelpers.length = 0;

            // Create new lights
            for (let i = 0; i < count; i++) {
                const color = new THREE.Color(Math.random(), Math.random(), Math.random());
                const light = new THREE.PointLight(color, 1, 50);
                light.position.set(
                    (Math.random() - 0.5) * 30,
                    Math.random() * 10 + 5,
                    (Math.random() - 0.5) * 30
                );
                light.castShadow = true;
                light.shadow.mapSize.width = 1024;
                light.shadow.mapSize.height = 1024;

                const helper = new THREE.PointLightHelper(light, 1);
                scene.add(light);
                scene.add(helper);

                pointLights.push(light);
                lightHelpers.push(helper);
            }

            document.getElementById('lightCount').textContent = count;
        }

        createDynamicLights(3);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(100, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Custom shader material for advanced effects
        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(0x00ff00) },
                resolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);

                    // Simple wave effect
                    vec3 pos = position;
                    pos.z += sin(pos.x * 5.0 + time * 2.0) * 0.1;
                    pos.z += cos(pos.y * 5.0 + time * 2.0) * 0.1;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    // Calculate lighting
                    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Color with lighting and time-based effect
                    vec3 col = color * (0.5 + diffuse * 0.5);
                    col += vec3(sin(vUv.x * 10.0 + time) * 0.1);
                    col += vec3(cos(vUv.y * 10.0 + time * 0.5) * 0.1);

                    gl_FragColor = vec4(col, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Create objects with different materials
        const objects = [];

        // Sphere with custom shader
        const sphereGeometry = new THREE.SphereGeometry(2, 32, 32);
        const sphere = new THREE.Mesh(sphereGeometry, customShaderMaterial);
        sphere.position.set(-8, 3, 0);
        sphere.castShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Box with standard material
        const boxGeometry = new THREE.BoxGeometry(3, 3, 3);
        const boxMaterial = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            roughness: 0.4,
            metalness: 0.7
        });
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        box.position.set(8, 3, 0);
        box.castShadow = true;
        scene.add(box);
        objects.push(box);

        // Torus knot with toon shading
        const torusGeometry = new THREE.TorusKnotGeometry(2, 0.8, 100, 16);
        const toonMaterial = new THREE.MeshToonMaterial({
            color: 0x00ffff,
            gradientMap: new THREE.TextureLoader().load('https://threejs.org/examples/textures/gradientMaps/threeTone.jpg')
        });
        const torus = new THREE.Mesh(torusGeometry, toonMaterial);
        torus.position.set(0, 5, 8);
        torus.castShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Skybox
        const skyboxGeometry = new THREE.BoxGeometry(1000, 1000, 1000);
        const skyboxMaterials = [
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/px.jpg'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/nx.jpg'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/py.jpg'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/ny.jpg'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/pz.jpg'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: new THREE.TextureLoader().load('https://threejs.org/examples/textures/skybox/nz.jpg'), side: THREE.BackSide })
        ];
        const skybox = new THREE.Mesh(skyboxGeometry, skyboxMaterials);
        scene.add(skybox);

        // Animation loop
        let time = 0;
        function animate() {
            requestAnimationFrame(animate);

            // Update time for shaders
            time += 0.01;
            customShaderMaterial.uniforms.time.value = time;

            // Update dynamic lights
            pointLights.forEach((light, i) => {
                const angle = time * (0.5 + i * 0.2);
                light.position.x = Math.sin(angle) * 15;
                light.position.z = Math.cos(angle) * 15;
                light.position.y = 5 + Math.sin(angle * 2) * 2;
            });

            // Update objects
            objects.forEach((obj, i) => {
                obj.rotation.y += 0.005 * (i + 1);
            });

            // Handle movement
            if (controls.isLocked) {
                const direction = new THREE.Vector3();
                camera.getWorldDirection(direction);
                direction.y = 0;
                direction.normalize();

                const right = new THREE.Vector3();
                right.crossVectors(camera.up, direction).normalize();

                if (keys.w) {
                    camera.position.addScaledVector(direction, moveSpeed * (keys.shift ? 2 : 1));
                }
                if (keys.s) {
                    camera.position.addScaledVector(direction, -moveSpeed * (keys.shift ? 2 : 1));
                }
                if (keys.a) {
                    camera.position.addScaledVector(right, -moveSpeed * (keys.shift ? 2 : 1));
                }
                if (keys.d) {
                    camera.position.addScaledVector(right, moveSpeed * (keys.shift ? 2 : 1));
                }
            }

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            customShaderMaterial.uniforms.resolution.value.set(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();

        // UI controls
        document.getElementById('lightCount').addEventListener('click', () => {
            const count = prompt('Enter number of lights (1-10):', '3');
            const num = parseInt(count);
            if (!isNaN(num) && num > 0 && num <= 10) {
                createDynamicLights(num);
            }
        });
    </script>
