        this.pointLight = new THREE.PointLight(0xffffff, 1, 100);
        this.pointLight.position.set(5, 5, 5);
        this.pointLight.castShadow = true;
        this.pointLight.shadow.mapSize.width = 1024;
        this.pointLight.shadow.mapSize.height = 1024;
        this.scene.add(this.pointLight);

        // Directional light
        this.directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        this.directionalLight.position.set(10, 10, 10);
        this.directionalLight.castShadow = true;
        this.directionalLight.shadow.mapSize.width = 1024;
        this.directionalLight.shadow.mapSize.height = 1024;
        this.directionalLight.shadow.camera.near = 0.5;
        this.directionalLight.shadow.camera.far = 50;
        this.scene.add(this.directionalLight);

        // Hemisphere light
        this.hemisphereLight = new THREE.HemisphereLight(0xffffbb, 0x080820, 0.5);
        this.scene.add(this.hemisphereLight);

        // Helper for point light
        this.pointLightHelper = new THREE.PointLightHelper(this.pointLight, 0.5);
        this.scene.add(this.pointLightHelper);

        // Helper for directional light
        this.directionalLightHelper = new THREE.DirectionalLightHelper(this.directionalLight, 1);
        this.scene.add(this.directionalLightHelper);
    }

    setupShaders() {
        // Standard shader (default)
        this.standardShader = {
            sphere: this.sphere.material,
            cube: this.cube.material,
            torus: this.torus.material,
            cylinder: this.cylinder.material
        };

        // Toon shader
        this.toonShader = {
            sphere: new THREE.MeshToonMaterial({
                color: 0xff4444,
                gradientMap: this.createGradientTexture()
            }),
            cube: new THREE.MeshToonMaterial({
                color: 0x4444ff,
                gradientMap: this.createGradientTexture()
            }),
            torus: new THREE.MeshToonMaterial({
                color: 0x44ff44,
                gradientMap: this.createGradientTexture()
            }),
            cylinder: new THREE.MeshToonMaterial({
                color: 0xffff44,
                gradientMap: this.createGradientTexture()
            })
        };

        // Custom shader (vertex displacement)
        this.customShader = {
            sphere: this.createCustomShaderMaterial(0xff4444),
            cube: this.createCustomShaderMaterial(0x4444ff),
            torus: this.createCustomShaderMaterial(0x44ff44),
            cylinder: this.createCustomShaderMaterial(0xffff44)
        };
    }

    createGradientTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 1;
        const context = canvas.getContext('2d');

        const gradient = context.createLinearGradient(0, 0, 64, 1);
        gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
        gradient.addColorStop(0.5, 'rgba(255, 255, 255, 0.5)');
        gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

        context.fillStyle = gradient;
        context.fillRect(0, 0, 64, 1);

        const texture = new THREE.CanvasTexture(canvas);
        texture.minFilter = THREE.NearestFilter;
        texture.magFilter = THREE.NearestFilter;
        texture.generateMipmaps = false;

        return texture;
    }

    createCustomShaderMaterial(color) {
        return new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(color) }
            },
            vertexShader: `
                uniform float time;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Add some wave-like displacement
                    float displacement = sin(position.x * 2.0 + time) * 0.1 +
                                        sin(position.y * 2.0 + time) * 0.1 +
                                        sin(position.z * 2.0 + time) * 0.1;

                    vec3 newPosition = position + normal * displacement;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Simple lighting calculation
                    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Add some color variation based on position
                    vec3 col = color * (0.5 + 0.5 * diffuse);
                    col += vec3(sin(vPosition.x * 5.0) * 0.1,
                               sin(vPosition.y * 5.0) * 0.1,
                               sin(vPosition.z * 5.0) * 0.1);

                    gl_FragColor = vec4(col, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });
    }

    setupControls() {
        // Orbit controls for camera movement
        this.controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);
        this.controls.enableDamping = true;
        this.controls.dampingFactor = 0.05;

        // First-person controls alternative
        this.firstPersonControls = {
            moveForward: false,
            moveBackward: false,
            moveLeft: false,
            moveRight: false,
            canJump: false,
            velocity: new THREE.Vector3(),
            direction: new THREE.Vector3(),
            isFirstPerson: false
        };
    }

    setupEventListeners() {
        window.addEventListener('resize', () => this.onWindowResize(), false);
        window.addEventListener('keydown', (e) => this.onKeyDown(e), false);
        window.addEventListener('keyup', (e) => this.onKeyUp(e), false);

        // Add UI controls
        document.getElementById('lighting-info').addEventListener('click', () => this.cycleLighting());
        document.getElementById('shader-info').addEventListener('click', () => this.cycleShaders());
    }

    onWindowResize() {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
    }

    onKeyDown(event) {
        switch (event.code) {
            case 'KeyW': this.firstPersonControls.moveForward = true; break;
            case 'KeyA': this.firstPersonControls.moveLeft = true; break;
            case 'KeyS': this.firstPersonControls.moveBackward = true; break;
            case 'KeyD': this.firstPersonControls.moveRight = true; break;
            case 'Space': if (this.firstPersonControls.canJump) {
                this.firstPersonControls.velocity.y += 350;
                this.firstPersonControls.canJump = false;
            } break;
            case 'KeyC': this.toggleControls(); break;
        }
    }

    onKeyUp(event) {
        switch (event.code) {
            case 'KeyW': this.firstPersonControls.moveForward = false; break;
            case 'KeyA': this.firstPersonControls.moveLeft = false; break;
            case 'KeyS': this.firstPersonControls.moveBackward = false; break;
            case 'KeyD': this.firstPersonControls.moveRight = false; break;
        }
    }

    toggleControls() {
        this.firstPersonControls.isFirstPerson = !this.firstPersonControls.isFirstPerson;
        if (this.firstPersonControls.isFirstPerson) {
            this.controls.enabled = false;
            document.getElementById('info').textContent = 'First-person mode (WASD to move, mouse to look)';
        } else {
            this.controls.enabled = true;
            document.getElementById('info').textContent = 'Orbit mode (mouse to rotate, scroll to zoom)';
        }
    }

    cycleLighting() {
        // Disable all lights
        this.pointLight.visible = false;
        this.directionalLight.visible = false;
        this.hemisphereLight.visible = false;
        this.pointLightHelper.visible = false;
        this.directionalLightHelper.visible = false;

        // Cycle through light types
        if (this.currentLightType === 'point') {
            this.currentLightType = 'directional';
            this.directionalLight.visible = true;
            this.directionalLightHelper.visible = true;
            document.getElementById('lighting-info').textContent = 'Directional Light';
        } else if (this.currentLightType === 'directional') {
            this.currentLightType = 'hemisphere';
            this.hemisphereLight.visible = true;
            document.getElementById('lighting-info').textContent = 'Hemisphere Light';
        } else {
            this.currentLightType = 'point';
            this.pointLight.visible = true;
            this.pointLightHelper.visible = true;
            document.getElementById('lighting-info').textContent = 'Point Light';
        }
    }

    cycleShaders() {
        // Remove current materials
        this.sphere.material.dispose();
        this.cube.material.dispose();
        this.torus.material.dispose();
        this.cylinder.material.dispose();

        // Apply new shader set
        if (this.currentShader === 'standard') {
            this.currentShader = 'toon';
            this.sphere.material = this.toonShader.sphere;
            this.cube.material = this.toonShader.cube;
            this.torus.material = this.toonShader.torus;
            this.cylinder.material = this.toonShader.cylinder;
            document.getElementById('shader-info').textContent = 'Toon Shader';
        } else if (this.currentShader === 'toon') {
            this.currentShader = 'custom';
            this.sphere.material = this.customShader.sphere;
            this.cube.material = this.customShader.cube;
            this.torus.material = this.customShader.torus;
            this.cylinder.material = this.customShader.cylinder;
            document.getElementById('shader-info').textContent = 'Custom Shader';
        } else {
            this.currentShader = 'standard';
            this.sphere.material = this.standardShader.sphere;
            this.cube.material = this.standardShader.cube;
            this.torus.material = this.standardShader.torus;
            this.cylinder.material = this.standardShader.cylinder;
            document.getElementById('shader-info').textContent = 'Standard Shader';
        }
    }

    updateFirstPersonControls(delta) {
        if (!this.firstPersonControls.isFirstPerson) return;

        // Movement
        this.firstPersonControls.velocity.x -= this.firstPersonControls.velocity.x * 10.0 * delta;
        this.firstPersonControls.velocity.z -= this.firstPersonControls.velocity.z * 10.0 * delta;
        this.firstPersonControls.velocity.y -= 9.8 * 100.0 * delta; // Gravity

        this.firstPersonControls.direction.z = Number(this.firstPersonControls.moveForward) - Number(this.firstPersonControls.moveBackward);
        this.firstPersonControls.direction.x = Number(this.firstPersonControls.moveRight) - Number(this.firstPersonControls.moveLeft);
        this.firstPersonControls.direction.normalize();

        if (this.firstPersonControls.moveForward || this.firstPersonControls.moveBackward) {
            this.firstPersonControls.velocity.z -= this.firstPersonControls.direction.z * 400.0 * delta;
        }
        if (this.firstPersonControls.moveLeft || this.firstPersonControls.moveRight) {
            this.firstPersonControls.velocity.x -= this.firstPersonControls.direction.x * 400.0 * delta;
        }

        // Update camera position
        this.camera.translateX(this.firstPersonControls.velocity.x * delta);
        this.camera.translateY(this.firstPersonControls.velocity.y * delta);
        this.camera.translateZ(this.firstPersonControls.velocity.z * delta);

        // Simple collision detection with ground
        if (this.camera.position.y < 1.75) {
            this.camera.position.y = 1.75;
            this.firstPersonControls.velocity.y = 0;
            this.firstPersonControls.canJump = true;
        }
    }

    animate() {
        requestAnimationFrame(() => this.animate());

        const delta = this.clock.getDelta();

        // Update first-person controls if active
        this.updateFirstPersonControls(delta);

        // Animate objects
        this.objectGroup.rotation.y += 0.2 * delta;

        // Animate lights
        if (this.pointLight.visible) {
            this.pointLight.position.x = Math.sin(Date.now() * 0.001) * 5;
            this.pointLight.position.z = Math.cos(Date.now() * 0.001) * 5;
            this.pointLightHelper.update();
        }

        if (this.directionalLight.visible) {
            this.directionalLight.position.x = Math.sin(Date.now() * 0.0005) * 10;
            this.directionalLight.position.z = Math.cos(Date.now() * 0.0005) * 10;
            this.directionalLightHelper.update();
        }

        // Update custom shader uniforms
        if (this.currentShader === 'custom') {
            this.customShader.sphere.uniforms.time.value = Date.now() * 0.001;
            this.customShader.cube.uniforms.time.value = Date.now() * 0.001;
            this.customShader.torus.uniforms.time.value = Date.now() * 0.001;
            this.customShader.cylinder.uniforms.time.value = Date.now() * 0.001;
        }

        // Update controls
        this.controls.update();

        // Render scene
        this.renderer.render(this.scene, this.camera);
    }
}

// Start the application when the page loads
window.addEventListener('load', () => {
    new SceneViewer();
});
```

## Features

1. **Dynamic Lighting System**:
   - Point light with animation
   - Directional light with animation
   - Hemisphere light
   - Ambient light
   - Light helpers for visualization

2. **Shader Effects**:
   - Standard PBR materials
   - Toon shader with gradient mapping
   - Custom vertex/fragment shader with wave displacement

3. **Interactive Controls**:
   - Orbit controls for camera movement
   - First-person movement with WASD keys
   - Mouse look controls
   - UI to cycle between lighting types and shaders

4. **Scene Elements**:
   - Ground plane
   - Sphere, cube, torus, and cylinder objects
   - Shadow casting and receiving
   - Environment mapping

5. **Responsive Design**:
   - Handles window resizing
   - Full-screen rendering

## How to Use

1. Save the HTML and JavaScript code to separate files
2. Open the HTML file in a modern browser
3. Use mouse to look around (orbit mode) or WASD to move (first-person mode)
4. Click on "Point Light" to cycle through different lighting types
5. Click on "Standard Shader" to cycle through different shader effects

This implementation provides a solid foundation that you can extend with additional features like model loading, post-processing effects, or more complex shaders.

# Real-Time 3D Scene Viewer with Dynamic Lighting and Shader Effects

Below is a complete implementation of a real-time 3D scene viewer using WebGL (via Three.js) with dynamic lighting and shader effects. This example includes:
- A 3D scene with multiple objects
- Dynamic point lights that move with the mouse
- Custom shaders for advanced visual effects
- Real-time performance monitoring

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Scene Viewer with Dynamic Lighting</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: Arial, sans-serif;
        }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            background: rgba(0, 0, 0, 0.7);
            padding: 10px;
            border-radius: 5px;
            font-size: 12px;
        }
        #controls {
            position: absolute;
            bottom: 10px;
            left: 10px;
            color: white;
            background: rgba(0, 0, 0, 0.7);
            padding: 10px;
            border-radius: 5px;
        }
    </style>
</head>
<body>
    <div id="info">
        <div>FPS: <span id="fps">0</span></div>
        <div>Lights: <span id="lightCount">0</span></div>
    </div>
    <div id="controls">
        <p>Controls: WASD to move, mouse to look, Q/E to move up/down</p>
        <p>Click to add/remove lights</p>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/libs/stats.min.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111122);
        scene.fog = new THREE.FogExp2(0x111122, 0.001);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Stats for FPS monitoring
        const stats = new Stats();
        stats.showPanel(0); // 0: fps, 1: ms, 2: mb
        document.body.appendChild(stats.dom);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(10, 20, 10);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        // Dynamic lights array
        const dynamicLights = [];
        const lightHelpers = [];

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(100, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333344,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Create some objects
        function createObjects() {
            // Sphere
            const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
            const sphereMaterial = new THREE.MeshStandardMaterial({
                color: 0xff4444,
                roughness: 0.4,
                metalness: 0.6
            });
            const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
            sphere.position.set(-5, 1, 0);
            sphere.castShadow = true;
            scene.add(sphere);

            // Box
            const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
            const boxMaterial = new THREE.MeshStandardMaterial({
                color: 0x4444ff,
                roughness: 0.3,
                metalness: 0.7
            });
            const box = new THREE.Mesh(boxGeometry, boxMaterial);
            box.position.set(5, 1, 0);
            box.castShadow = true;
            scene.add(box);

            // Torus
            const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
            const torusMaterial = new THREE.MeshStandardMaterial({
                color: 0x44ff44,
                roughness: 0.5,
                metalness: 0.3
            });
            const torus = new THREE.Mesh(torusGeometry, torusMaterial);
            torus.position.set(0, 2, 5);
            torus.castShadow = true;
            scene.add(torus);

            // Custom shader material for one object
            const customMaterial = new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0xffaa00) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    varying vec3 vNormal;

                    void main() {
                        vUv = uv;
                        vNormal = normalize(normalMatrix * normal);
                        vec3 pos = position;

                        // Simple wave effect
                        pos.y += sin(pos.x * 5.0 + time * 2.0) * 0.2;

                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec2 vUv;
                    varying vec3 vNormal;

                    void main() {
                        // Simple lighting
                        vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                        float diffuse = max(dot(vNormal, lightDir), 0.0);

                        // Color with lighting
                        vec3 col = color * (0.5 + 0.5 * diffuse);

                        // Add some pattern
                        col *= 0.8 + 0.2 * sin(vUv.x * 10.0) * sin(vUv.y * 10.0);

                        gl_FragColor = vec4(col, 1.0);
                    }
                `,
                side: THREE.DoubleSide
            });

            const customGeometry = new THREE.TorusKnotGeometry(1, 0.3, 100, 16);
            const customMesh = new THREE.Mesh(customGeometry, customMaterial);
            customMesh.position.set(0, 3, -5);
            customMesh.castShadow = true;
            scene.add(customMesh);
        }

        createObjects();

        // Add dynamic lights on click
        function onMouseClick(event) {
            // Calculate mouse position in normalized device coordinates
            const mouse = new THREE.Vector2();
            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            // Create a raycaster
            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(mouse, camera);

            // Check for intersection with ground
            const intersects = raycaster.intersectObject(ground);

            if (intersects.length > 0) {
                const point = intersects[0].point;

                // Check if there's already a light at this position
                const existingLight = dynamicLights.find(light =>
                    light.position.distanceTo(point) < 0.5
                );

                if (existingLight) {
                    // Remove the light
                    const index = dynamicLights.indexOf(existingLight);
                    scene.remove(existingLight);
                    dynamicLights.splice(index, 1);

                    const helperIndex = lightHelpers.findIndex(helper =>
                        helper.light === existingLight
                    );
                    if (helperIndex !== -1) {
                        scene.remove(lightHelpers[helperIndex]);
                        lightHelpers.splice(helperIndex, 1);
                    }
                } else {
                    // Add a new light
                    const color = new THREE.Color(Math.random(), Math.random(), Math.random());
                    const newLight = new THREE.PointLight(color, 2, 10, 2);
                    newLight.position.copy(point);
                    newLight.position.y = 1; // Slightly above the ground
                    newLight.castShadow = true;
                    scene.add(newLight);
                    dynamicLights.push(newLight);

                    // Add a helper to visualize the light
                    const lightHelper = new THREE.PointLightHelper(newLight, 0.5);
                    scene.add(lightHelper);
                    lightHelpers.push(lightHelper);
                }

                // Update light count display
                document.getElementById('lightCount').textContent = dynamicLights.length;
            }
        }

        window.addEventListener('click', onMouseClick, false);

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation loop
        const clock = new THREE.Clock();
        let lastTime = 0;
        let frameCount = 0;

        function animate() {
            requestAnimationFrame(animate);
            stats.begin();

            const deltaTime = clock.getDelta();
            const elapsedTime = clock.getElapsedTime();

            // Update custom shader uniform
            scene.traverse((object) => {
                if (object.material && object.material.uniforms && object.material.uniforms.time) {
                    object.material.uniforms.time.value = elapsedTime;
                }
            });

            // Animate dynamic lights
            dynamicLights.forEach((light, index) => {
                // Move lights in a circular pattern
                const angle = elapsedTime * 0.5 + index;
                light.position.x = Math.sin(angle) * 3;
                light.position.z = Math.cos(angle) * 3;

                // Pulse the light intensity
                light.intensity = 1.5 + Math.sin(elapsedTime * 2 + index) * 0.5;

                // Update light helpers
                if (lightHelpers[index]) {
                    lightHelpers[index].update();
                }
            });

            // Update controls
            controls.update();

            // Render the scene
            renderer.render(scene, camera);

            // Calculate FPS
            frameCount++;
            const currentTime = performance.now();
            if (currentTime - lastTime >= 1000) {
                document.getElementById('fps').textContent = Math.round((frameCount * 1000) / (currentTime - lastTime));
                frameCount = 0;
                lastTime = currentTime;
            }

            stats.end();
        }

        animate();
    </script>
</body>
</html>
