        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0x00aaff,
            roughness: 0.3,
            metalness: 0.7
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(5, 2, 0);
        sphere.castShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Create a box
        const boxGeometry = new THREE.BoxGeometry(3, 3, 3);
        const boxMaterial = new THREE.MeshStandardMaterial({
            color: 0xff00aa,
            roughness: 0.5,
            metalness: 0.3
        });
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        box.position.set(0, 1.5, 5);
        box.castShadow = true;
        scene.add(box);
        objects.push(box);

        // Create a cylinder
        const cylinderGeometry = new THREE.CylinderGeometry(1.5, 1.5, 4, 32);
        const cylinderMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ff55,
            roughness: 0.2,
            metalness: 0.8
        });
        const cylinder = new THREE.Mesh(cylinderGeometry, cylinderMaterial);
        cylinder.position.set(0, 2, -5);
        cylinder.castShadow = true;
        scene.add(cylinder);
        objects.push(cylinder);

        // Animation variables
        let time = 0;
        const clock = new THREE.Clock();

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // Animate objects
            objects.forEach((obj, i) => {
                obj.rotation.x += delta * 0.3;
                obj.rotation.y += delta * 0.5;
            });

            // Animate point lights
            pointLights.forEach((light, i) => {
                const angle = time * (0.5 + i * 0.2);
                const radius = 8 + i * 2;
                light.position.x = Math.sin(angle) * radius;
                light.position.z = Math.cos(angle) * radius;
                light.position.y = 2 + Math.sin(angle * 2) * 1.5;
            });

            // Update controls
            controls.update();

            // Render
            composer.render();
        }

        animate();
    </script>
