        });
        const plane = new THREE.Mesh(planeGeometry, planeMaterial);
        plane.rotation.x = -Math.PI / 2;
        plane.position.y = -2;
        plane.receiveShadow = true;
        scene.add(plane);

        // Add some cubes for variety
        for (let i = 0; i < 5; i++) {
            const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
            const cubeMaterial = new THREE.MeshStandardMaterial({
                color: new THREE.Color(Math.random(), Math.random(), Math.random()),
                metalness: 0.5,
                roughness: 0.3
            });
            const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
            cube.position.set(
                Math.random() * 10 - 5,
                Math.random() * 2 + 0.5,
                Math.random() * 10 - 5
            );
            cube.castShadow = true;
            cube.receiveShadow = true;
            scene.add(cube);
        }

        // UI controls
        const toggleWireframeBtn = document.getElementById('toggleWireframe');
        const toggleShaderBtn = document.getElementById('toggleShader');
        const toggleLightBtn = document.getElementById('toggleLight');
        const lightIntensitySlider = document.getElementById('lightIntensitySlider');
        const lightIntensityDisplay = document.getElementById('lightIntensity');

        let isShaderActive = false;
        let isLightOn = true;

        toggleWireframeBtn.addEventListener('click', () => {
            torusKnot.material.wireframe = !torusKnot.material.wireframe;
        });

        toggleShaderBtn.addEventListener('click', () => {
            isShaderActive = !isShaderActive;
            if (isShaderActive) {
                torusKnot.material = shaderMaterial;
            } else {
                torusKnot.material = material;
            }
        });

        toggleLightBtn.addEventListener('click', () => {
            isLightOn = !isLightOn;
            if (isLightOn) {
                scene.add(directionalLight);
                scene.add(pointLight);
            } else {
                scene.remove(directionalLight);
                scene.remove(pointLight);
            }
        });

        lightIntensitySlider.addEventListener('input', (e) => {
            const intensity = parseFloat(e.target.value);
            directionalLight.intensity = intensity;
            pointLight.intensity = intensity * 0.5;
            lightIntensityDisplay.textContent = intensity.toFixed(1);
        });

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update shader time uniform if active
            if (isShaderActive) {
                shaderMaterial.uniforms.time.value += 0.01;
            }

            // Rotate the torus knot
            torusKnot.rotation.x += 0.005;
            torusKnot.rotation.y += 0.005;

            // Update controls
            controls.update();

            // Render the scene
            renderer.render(scene, camera);
        }

        animate();
    </script>
