# Real-Time 3D Scene Viewer with Dynamic Lighting and Shaders

Below is a complete implementation of a real-time 3D scene viewer using WebGL (via Three.js) with dynamic lighting and shader effects. This example includes:
- A 3D scene with multiple objects
- Dynamic point lights that move
- Custom shaders for advanced effects
- Interactive controls

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Scene Viewer with Dynamic Lighting</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #000;
        }
        canvas {
            display: block;
        }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: white;
            font-family: Arial, sans-serif;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">3D Scene Viewer - Use mouse to look around, WASD to move</div>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>
    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);
        scene.fog = new THREE.FogExp2(0x111111, 0.002);

        // Camera
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 1.6, 5);

        // Renderer
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.PointerLockControls(camera, document.body);
        document.addEventListener('click', () => {
            controls.lock();
        });

        // Movement controls
        const moveSpeed = 0.1;
        const keys = {
            w: false,
            a: false,
            s: false,
            d: false,
            shift: false
        };

        document.addEventListener('keydown', (e) => {
            switch(e.code) {
                case 'KeyW': keys.w = true; break;
                case 'KeyA': keys.a = true; break;
                case 'KeyS': keys.s = true; break;
                case 'KeyD': keys.d = true; break;
                case 'ShiftLeft': keys.shift = true; break;
            }
        });

        document.addEventListener('keyup', (e) => {
            switch(e.code) {
                case 'KeyW': keys.w = false; break;
                case 'KeyA': keys.a = false; break;
                case 'KeyS': keys.s = false; break;
                case 'KeyD': keys.d = false; break;
                case 'ShiftLeft': keys.shift = false; break;
            }
        });

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        // Directional light (sun)
        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(10, 20, 5);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        directionalLight.shadow.camera.left = -20;
        directionalLight.shadow.camera.right = 20;
        directionalLight.shadow.camera.top = 20;
        directionalLight.shadow.camera.bottom = -20;
        scene.add(directionalLight);

        // Dynamic point lights
        const pointLights = [];
        const pointLightHelpers = [];

        for (let i = 0; i < 3; i++) {
            const pointLight = new THREE.PointLight(0xff0000, 1, 20);
            pointLight.position.set(
                Math.random() * 20 - 10,
                Math.random() * 5 + 1,
                Math.random() * 20 - 10
            );
            pointLight.castShadow = true;
            pointLight.shadow.mapSize.width = 512;
            pointLight.shadow.mapSize.height = 512;
            pointLight.shadow.camera.near = 0.1;
            pointLight.shadow.camera.far = 10;

            const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
            scene.add(pointLight);
            scene.add(pointLightHelper);

            pointLights.push(pointLight);
            pointLightHelpers.push(pointLightHelper);
        }

        // Custom shader material for advanced effects
        const customMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color1: { value: new THREE.Color(0x00ff00) },
                color2: { value: new THREE.Color(0xff00ff) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                uniform float time;
                uniform vec3 color1;
                uniform vec3 color2;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vec3 color = mix(color1, color2, sin(vUv.x * 10.0 + time) * 0.5 + 0.5);
                    float light = dot(vNormal, vec3(0.0, 1.0, 0.0));
                    color += light * 0.3;
                    gl_FragColor = vec4(color, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Create scene objects
        const groundGeometry = new THREE.PlaneGeometry(100, 100);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Add some objects
        const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
        const sphereGeometry = new THREE.SphereGeometry(0.5, 32, 32);
        const torusGeometry = new THREE.TorusGeometry(0.5, 0.2, 16, 100);

        for (let i = 0; i < 10; i++) {
            const material = i % 2 === 0 ?
                new THREE.MeshStandardMaterial({
                    color: new THREE.Color(Math.random(), Math.random(), Math.random()),
                    roughness: 0.5,
                    metalness: 0.5
                }) : customMaterial;

            const mesh = new THREE.Mesh(
                i % 3 === 0 ? boxGeometry : (i % 3 === 1 ? sphereGeometry : torusGeometry),
                material
            );

            mesh.position.set(
                Math.random() * 20 - 10,
                Math.random() * 2 + 0.5,
                Math.random() * 20 - 10
            );

            mesh.rotation.set(
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                Math.random() * Math.PI
            );

            mesh.castShadow = true;
            mesh.receiveShadow = true;
            scene.add(mesh);
        }

        // Animation loop
        let time = 0;
        function animate() {
            requestAnimationFrame(animate);

            // Update time uniform for shaders
            time += 0.01;
            customMaterial.uniforms.time.value = time;

            // Move point lights in a circular pattern
            pointLights.forEach((light, index) => {
                const angle = time * (0.5 + index * 0.3);
                light.position.x = Math.sin(angle) * 5;
                light.position.z = Math.cos(angle) * 5;
                light.position.y = Math.sin(angle * 2) * 2 + 2;

                // Change light color over time
                light.color.setHSL(
                    (time * 0.1 + index * 0.3) % 1,
                    0.8,
                    0.5
                );
            });

            // Handle movement
            if (keys.w) camera.translateZ(-moveSpeed * (keys.shift ? 2 : 1));
            if (keys.s) camera.translateZ(moveSpeed * (keys.shift ? 2 : 1));
            if (keys.a) camera.translateX(-moveSpeed * (keys.shift ? 2 : 1));
            if (keys.d) camera.translateX(moveSpeed * (keys.shift ? 2 : 1));

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
