<body>
    <div id="info">3D Scene Viewer - WASD: Move, Mouse: Look, Q/E: Up/Down</div>
    <div id="controls">
        <button id="toggleLight">Toggle Light</button>
        <button id="toggleWireframe">Toggle Wireframe</button>
        <button id="toggleShader">Toggle Shader</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Pointer lock controls for first-person movement
        const pointerLockControls = new THREE.PointerLockControls(camera, document.body);
        let isPointerLocked = false;

        // Lights
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(10, 20, 10);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        const pointLight = new THREE.PointLight(0xff0000, 2, 20);
        pointLight.position.set(0, 5, 0);
        pointLight.castShadow = true;
        scene.add(pointLight);

        // Helper to visualize lights
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 2);
        scene.add(lightHelper);
        const pointLightHelper = new THREE.PointLightHelper(pointLight, 1);
        scene.add(pointLightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Create some objects
        const objects = [];

        // Sphere
        const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ff00,
            roughness: 0.4,
            metalness: 0.6
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(-3, 1.5, 0);
        sphere.castShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Box
        const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
        const boxMaterial = new THREE.MeshStandardMaterial({
            color: 0x0000ff,
            roughness: 0.3,
            metalness: 0.7
        });
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        box.position.set(3, 1, 0);
        box.castShadow = true;
        scene.add(box);
        objects.push(box);

        // Torus
        const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
        const torusMaterial = new THREE.MeshStandardMaterial({
            color: 0xff00ff,
            roughness: 0.5,
            metalness: 0.3
        });
        const torus = new THREE.Mesh(torusGeometry, torusMaterial);
        torus.position.set(0, 1.5, 3);
        torus.castShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Custom shader material for one of the objects
        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(0x00ffff) },
                lightPosition: { value: new THREE.Vector3(0, 5, 0) }
            },
            vertexShader: `
                uniform float time;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Simple wave animation
                    vec3 newPosition = position;
                    newPosition.y += sin(position.x * 2.0 + time) * 0.2;
                    newPosition.z += cos(position.y * 2.0 + time) * 0.2;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                uniform vec3 lightPosition;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Simple lighting
                    vec3 lightDir = normalize(lightPosition - vPosition);
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Combine color with lighting
                    vec3 finalColor = color * (0.5 + 0.5 * diffuse);

                    gl_FragColor = vec4(finalColor, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Apply custom shader to the sphere
        sphere.material = customShaderMaterial;
        let useCustomShader = true;

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader uniforms
            customShaderMaterial.uniforms.time.value += 0.01;
            customShaderMaterial.uniforms.lightPosition.value.copy(pointLight.position);

            // Rotate objects slightly
            objects.forEach(obj => {
                if (obj !== sphere || !useCustomShader) {
                    obj.rotation.x += 0.005;
                    obj.rotation.y += 0.005;
                }
            });

            // Move point light in a circle
            pointLight.position.x = Math.sin(Date.now() * 0.001) * 5;
            pointLight.position.z = Math.cos(Date.now() * 0.001) * 5;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // UI Controls
        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            lightHelper.visible = directionalLight.visible;
        });

        document.getElementById('toggleWireframe').addEventListener('click', () => {
            objects.forEach(obj => {
                obj.material.wireframe = !obj.material.wireframe;
            });
        });

        document.getElementById('toggleShader').addEventListener('click', () => {
            useCustomShader = !useCustomShader;
            if (useCustomShader) {
                sphere.material = customShaderMaterial;
            } else {
                sphere.material = new THREE.MeshStandardMaterial({
                    color: 0x00ff00,
                    roughness: 0.4,
                    metalness: 0.6
                });
            }
        });

        // Pointer lock for first-person movement
        document.addEventListener('click', () => {
            if (!isPointerLocked) {
                document.body.requestPointerLock();
            }
        });

        document.addEventListener('pointerlockchange', () => {
            isPointerLocked = document.pointerLockElement === document.body;
            if (isPointerLocked) {
                document.addEventListener('mousemove', onMouseMove);
            } else {
                document.removeEventListener('mousemove', onMouseMove);
            }
        });

        function onMouseMove(event) {
            if (isPointerLocked) {
                pointerLockControls.update(event);
            }
        }

        // Start animation
        animate();
    </script>
