            d: false,
            shift: false
        };

        document.addEventListener('keydown', (e) => {
            switch (e.code) {
                case 'KeyW': keys.w = true; break;
                case 'KeyA': keys.a = true; break;
                case 'KeyS': keys.s = true; break;
                case 'KeyD': keys.d = true; break;
                case 'ShiftLeft': keys.shift = true; break;
            }
        });

        document.addEventListener('keyup', (e) => {
            switch (e.code) {
                case 'KeyW': keys.w = false; break;
                case 'KeyA': keys.a = false; break;
                case 'KeyS': keys.s = false; break;
                case 'KeyD': keys.d = false; break;
                case 'ShiftLeft': keys.shift = false; break;
            }
        });

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 2048;
        directionalLight.shadow.mapSize.height = 2048;
        scene.add(directionalLight);

        // Dynamic point lights
        const pointLights = [];
        const lightCountElement = document.getElementById('light-count');

        function createDynamicLight() {
            const color = new THREE.Color(Math.random(), Math.random(), Math.random());
            const light = new THREE.PointLight(color, 2, 20, 2);
            light.position.set(
                (Math.random() - 0.5) * 20,
                Math.random() * 5 + 1,
                (Math.random() - 0.5) * 20
            );
            light.castShadow = true;
            light.shadow.mapSize.width = 512;
            light.shadow.mapSize.height = 512;

            // Add light helper
            const lightHelper = new THREE.PointLightHelper(light, 0.5);
            scene.add(lightHelper);

            // Store light data
            const lightData = {
                light: light,
                helper: lightHelper,
                direction: new THREE.Vector3(
                    (Math.random() - 0.5) * 0.02,
                    (Math.random() - 0.5) * 0.01,
                    (Math.random() - 0.5) * 0.02
                ),
                colorChange: new THREE.Vector3(
                    (Math.random() - 0.5) * 0.01,
                    (Math.random() - 0.5) * 0.01,
                    (Math.random() - 0.5) * 0.01
                )
            };

            pointLights.push(lightData);
            scene.add(light);

            lightCountElement.textContent = pointLights.length;
        }

        // Create initial lights
        for (let i = 0; i < 3; i++) {
            createDynamicLight();
        }

        // Add button to create more lights
        const addLightButton = document.createElement('button');
        addLightButton.textContent = 'Add Light';
        addLightButton.style.position = 'absolute';
        addLightButton.style.bottom = '20px';
        addLightButton.style.left = '20px';
        addLightButton.style.padding = '10px';
        addLightButton.style.backgroundColor = '#333';
        addLightButton.style.color = 'white';
        addLightButton.style.border = 'none';
        addLightButton.style.borderRadius = '5px';
        addLightButton.style.cursor = 'pointer';
        document.body.appendChild(addLightButton);

        addLightButton.addEventListener('click', createDynamicLight);

        // Custom shader material for advanced effects
        const customMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                resolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) },
                lightPosition: { value: new THREE.Vector3() },
                lightColor: { value: new THREE.Color(0xffffff) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Simple wave effect
                    vec3 newPosition = position;
                    newPosition.y += sin(position.x * 2.0 + time) * 0.1;
                    newPosition.x += sin(position.y * 2.0 + time) * 0.1;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec2 resolution;
                uniform float time;
                uniform vec3 lightPosition;
                uniform vec3 lightColor;

                varying vec2 vUv;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Calculate lighting
                    vec3 lightDir = normalize(lightPosition - vPosition);
                    float diffuse = max(dot(vNormal, lightDir), 0.0);
                    vec3 diffuseColor = lightColor * diffuse;

                    // Base color
                    vec3 baseColor = vec3(0.2, 0.5, 0.8);

                    // Add some noise for texture
                    float noise = fract(sin(dot(vPosition, vec3(12.9898, 78.233, 45.5432))) * 43758.5453);
                    baseColor += vec3(noise * 0.1);

                    // Combine colors
                    vec3 color = baseColor + diffuseColor;

                    // Add some rim lighting
                    vec3 viewDir = normalize(cameraPosition - vPosition);
                    float rim = 1.0 - max(dot(vNormal, viewDir), 0.0);
                    color += lightColor * pow(rim, 2.0) * 0.5;

                    // Add some time-based color shift
                    color += vec3(
                        sin(time * 0.5) * 0.1,
                        sin(time * 0.3) * 0.1,
                        sin(time * 0.7) * 0.1
                    );

                    gl_FragColor = vec4(color, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Create scene objects
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Create some boxes with custom material
        const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
        for (let i = 0; i < 10; i++) {
            const box = new THREE.Mesh(boxGeometry, customMaterial.clone());
            box.position.set(
                (Math.random() - 0.5) * 15,
                Math.random() * 2 + 0.5,
                (Math.random() - 0.5) * 15
            );
            box.rotation.set(
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                Math.random() * Math.PI
            );
            box.castShadow = true;
            box.receiveShadow = true;
            scene.add(box);
        }

        // Create a sphere with custom material
        const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
        const sphere = new THREE.Mesh(sphereGeometry, customMaterial.clone());
        sphere.position.set(3, 1.5, 0);
        sphere.castShadow = true;
        sphere.receiveShadow = true;
        scene.add(sphere);

        // Create a torus knot with standard material
        const torusKnotGeometry = new THREE.TorusKnotGeometry(1, 0.4, 100, 16);
        const torusKnotMaterial = new THREE.MeshStandardMaterial({
            color: 0xff6600,
            roughness: 0.3,
            metalness: 0.7
        });
        const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
        torusKnot.position.set(-3, 1.5, 0);
        torusKnot.castShadow = true;
        torusKnot.receiveShadow = true;
        scene.add(torusKnot);

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation loop
        const clock = new THREE.Clock();
        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            const time = clock.getElapsedTime();

            // Update custom material uniforms
            customMaterial.uniforms.time.value = time;

            // Update dynamic lights
            pointLights.forEach(lightData => {
                // Move lights
                lightData.light.position.add(lightData.direction);

                // Change light color
                lightData.light.color.r += lightData.colorChange.x;
                lightData.light.color.g += lightData.colorChange.y;
                lightData.light.color.b += lightData.colorChange.z;

                // Bounce lights off walls
                if (Math.abs(lightData.light.position.x) > 10) {
                    lightData.direction.x *= -1;
                }
                if (lightData.light.position.y > 10 || lightData.light.position.y < 0.5) {
                    lightData.direction.y *= -1;
                }
                if (Math.abs(lightData.light.position.z) > 10) {
                    lightData.direction.z *= -1;
                }

                // Clamp colors
                lightData.light.color.r = Math.max(0, Math.min(1, lightData.light.color.r));
                lightData.light.color.g = Math.max(0, Math.min(1, lightData.light.color.g));
                lightData.light.color.b = Math.max(0, Math.min(1, lightData.light.color.b));

                // Update light helper
                lightData.helper.update();
            });

            // Update main directional light to follow camera
            directionalLight.position.copy(camera.position);
            directionalLight.position.y += 10;

            // Handle movement
            if (controls.isLocked) {
                const speed = keys.shift ? moveSpeed * 2 : moveSpeed;

                if (keys.w) {
                    controls.moveForward(speed);
                }
                if (keys.s) {
                    controls.moveForward(-speed);
                }
                if (keys.a) {
                    controls.moveRight(-speed);
                }
                if (keys.d) {
                    controls.moveRight(speed);
                }
            }

            // Rotate torus knot
            torusKnot.rotation.x += 0.01;
            torusKnot.rotation.y += 0.01;

            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
```

