        metalness: 0.8
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(2, 0.7, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Create a torus
    const torusGeometry = new THREE.TorusGeometry(0.8, 0.3, 16, 32);
    const torusMaterial = new THREE.MeshStandardMaterial({
        color: 0x0000ff,
        roughness: 0.3,
        metalness: 0.7
    });
    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(0, 1.2, 2);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update light position for dynamic effect
    const time = Date.now() * 0.0005;
    light.position.x = Math.sin(time) * 10;
    light.position.z = Math.cos(time) * 10;

    // Update UI
    document.getElementById('lightIntensity').textContent = lightIntensity.toFixed(1);
    document.getElementById('shaderEffect').textContent = shaderEffect;

    // Render scene
    renderer.render(scene, camera);
}

// Handle window resize
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Initialize the scene when the page loads
window.onload = init;
