    <div id="controls">
        <button id="toggleLight">Toggle Light</button>
        <button id="toggleWireframe">Toggle Wireframe</button>
        <button id="changeShader">Change Shader</button>
        <button id="addObject">Add Object</button>
    </div>

    <!-- Load Three.js from CDN -->
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/loaders/GLTFLoader.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        scene.add(directionalLight);

        const pointLight = new THREE.PointLight(0xff0000, 1, 10);
        pointLight.position.set(0, 2, 0);
        pointLight.castShadow = true;
        scene.add(pointLight);

        // Light helper
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grid helper
        const gridHelper = new THREE.GridHelper(20, 20);
        scene.add(gridHelper);

        // Shader materials
        const shaderMaterials = [
            // Basic material
            new THREE.MeshStandardMaterial({
                color: 0x00ff00,
                roughness: 0.5,
                metalness: 0.5
            }),

            // Toon shader
            new THREE.MeshToonMaterial({
                color: 0x0000ff,
                gradientMap: createGradientTexture()
            }),

            // Custom shader material
            new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0xff00ff) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.2;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vec3 col = color * (0.5 + 0.5 * sin(vUv.x * 10.0 + time));
                        gl_FragColor = vec4(col, 1.0);
                    }
                `
            })
        ];

        // Create gradient texture for toon shader
        function createGradientTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 16;
            canvas.height = 256;

            const context = canvas.getContext('2d');
            const gradient = context.createLinearGradient(0, 0, 0, 256);

            gradient.addColorStop(0.0, '#ffffff');
            gradient.addColorStop(0.5, '#0000ff');
            gradient.addColorStop(1.0, '#000000');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 16, 256);

            const texture = new THREE.CanvasTexture(canvas);
            texture.minFilter = THREE.NearestFilter;
            texture.magFilter = THREE.NearestFilter;
            texture.generateMipmaps = false;

            return texture;
        }

        // Create objects
        const objects = [];
        let currentShaderIndex = 0;

        function createObject(type = 'box') {
            let geometry;
            switch(type) {
                case 'sphere':
                    geometry = new THREE.SphereGeometry(1, 32, 32);
                    break;
                case 'torus':
                    geometry = new THREE.TorusGeometry(1, 0.4, 16, 32);
                    break;
                default:
                    geometry = new THREE.BoxGeometry(1, 1, 1);
            }

            const material = shaderMaterials[currentShaderIndex].clone();
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(
                (Math.random() - 0.5) * 10,
                1,
                (Math.random() - 0.5) * 10
            );
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            // Add random rotation
            mesh.rotation.x = Math.random() * Math.PI;
            mesh.rotation.y = Math.random() * Math.PI;

            scene.add(mesh);
            objects.push(mesh);

            return mesh;
        }

        // Create initial objects
        createObject('box');
        createObject('sphere');
        createObject('torus');

        // Animation loop
        let time = 0;
        let lightOn = true;
        let wireframeMode = false;

        function animate() {
            requestAnimationFrame(animate);

            // Update time for shaders
            time += 0.01;
            shaderMaterials[2].uniforms.time.value = time;

            // Rotate point light
            pointLight.position.x = Math.sin(time) * 3;
            pointLight.position.z = Math.cos(time) * 3;

            // Rotate objects slightly
            objects.forEach(obj => {
                obj.rotation.y += 0.005;
            });

            controls.update();
            renderer.render(scene, camera);
        }

        animate();

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // UI Controls
        document.getElementById('toggleLight').addEventListener('click', () => {
            lightOn = !lightOn;
            directionalLight.visible = lightOn;
            pointLight.visible = lightOn;
            lightHelper.visible = lightOn;
        });

        document.getElementById('toggleWireframe').addEventListener('click', () => {
            wireframeMode = !wireframeMode;
            objects.forEach(obj => {
                obj.material.wireframe = wireframeMode;
            });
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex].clone();
                obj.material.wireframe = wireframeMode;
            });
        });

        document.getElementById('addObject').addEventListener('click', () => {
            const types = ['box', 'sphere', 'torus'];
            const randomType = types[Math.floor(Math.random() * types.length)];
            createObject(randomType);
        });
    </script>
</body>
</html>
