        <button id="addObject">Add Object</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/loaders/GLTFLoader.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        scene.add(directionalLight);

        const pointLight = new THREE.PointLight(0xff0000, 2, 20);
        pointLight.position.set(0, 5, 0);
        scene.add(pointLight);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grid helper
        const gridHelper = new THREE.GridHelper(50, 50);
        scene.add(gridHelper);

        // Objects
        const objects = [];

        // Create initial objects
        function createInitialObjects() {
            // Box
            const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
            const boxMaterial = new THREE.MeshStandardMaterial({
                color: 0x00ff00,
                roughness: 0.5,
                metalness: 0.5
            });
            const box = new THREE.Mesh(boxGeometry, boxMaterial);
            box.position.set(-5, 1, 0);
            box.castShadow = true;
            scene.add(box);
            objects.push(box);

            // Sphere
            const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
            const sphereMaterial = new THREE.MeshStandardMaterial({
                color: 0xff0000,
                roughness: 0.3,
                metalness: 0.7
            });
            const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
            sphere.position.set(5, 1.5, 0);
            sphere.castShadow = true;
            scene.add(sphere);
            objects.push(sphere);

            // Torus
            const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 100);
            const torusMaterial = new THREE.MeshStandardMaterial({
                color: 0x0000ff,
                roughness: 0.2,
                metalness: 0.8
            });
            const torus = new THREE.Mesh(torusGeometry, torusMaterial);
            torus.position.set(0, 1.5, 5);
            torus.castShadow = true;
            scene.add(torus);
            objects.push(torus);
        }

        createInitialObjects();

        // Shader materials
        const shaderMaterials = [
            // Standard material
            new THREE.MeshStandardMaterial({
                color: 0xffffff,
                roughness: 0.5,
                metalness: 0.5
            }),

            // Custom shader material
            new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0x00ff00) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.2;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vec3 col = color * (0.5 + 0.5 * sin(vUv.x * 10.0 + time));
                        gl_FragColor = vec4(col, 1.0);
                    }
                `
            }),

            // Toon shader
            new THREE.ShaderMaterial({
                uniforms: {
                    uDirLightPos: { value: new THREE.Vector3(5, 10, 7) },
                    uDirLightColor: { value: new THREE.Color(0xffffff) },
                    uAmbientLightColor: { value: new THREE.Color(0x404040) },
                    uBaseColor: { value: new THREE.Color(0xff0000) }
                },
                vertexShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelMatrix * vec4(position, 1.0)).xyz;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 uDirLightPos;
                    uniform vec3 uDirLightColor;
                    uniform vec3 uAmbientLightColor;
                    uniform vec3 uBaseColor;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        // Calculate directional light
                        vec3 lightDir = normalize(uDirLightPos - vPosition);
                        float NdotL = max(dot(vNormal, lightDir), 0.0);

                        // Toon shading
                        float intensity = 0.0;
                        if (NdotL > 0.95) intensity = 1.0;
                        else if (NdotL > 0.5) intensity = 0.6;
                        else if (NdotL > 0.2) intensity = 0.3;
                        else intensity = 0.1;

                        vec3 diffuse = uDirLightColor * uBaseColor * intensity;
                        vec3 ambient = uAmbientLightColor * uBaseColor * 0.2;

                        gl_FragColor = vec4(diffuse + ambient, 1.0);
                    }
                `
            })
        ];

        // Current shader index
        let currentShaderIndex = 0;

        // UI Controls
        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex];
            });
        });

        document.getElementById('addObject').addEventListener('click', () => {
            const types = ['box', 'sphere', 'torus'];
            const type = types[Math.floor(Math.random() * types.length)];

            let geometry, material;
            const x = (Math.random() - 0.5) * 20;
            const z = (Math.random() - 0.5) * 20;

            switch(type) {
                case 'box':
                    geometry = new THREE.BoxGeometry(1, 1, 1);
                    material = shaderMaterials[currentShaderIndex];
                    break;
                case 'sphere':
                    geometry = new THREE.SphereGeometry(0.7, 32, 32);
                    material = shaderMaterials[currentShaderIndex];
                    break;
                case 'torus':
                    geometry = new THREE.TorusGeometry(0.7, 0.2, 16, 100);
                    material = shaderMaterials[currentShaderIndex];
                    break;
            }

            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(x, 0.5, z);
            mesh.castShadow = true;
            scene.add(mesh);
            objects.push(mesh);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update shader uniforms if needed
            if (shaderMaterials[currentShaderIndex].uniforms && shaderMaterials[currentShaderIndex].uniforms.time) {
                shaderMaterials[currentShaderIndex].uniforms.time.value += 0.01;
            }

            // Rotate point light
            pointLight.position.x = Math.sin(Date.now() * 0.001) * 5;
            pointLight.position.z = Math.cos(Date.now() * 0.001) * 5;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();
    </script>
</body>
</html>
```

## Features of this Implementation:

1. **Dynamic Lighting System**:
   - Ambient light for base illumination
   - Directional light with shadows
   - Moving point light that orbits around the scene

2. **Shader Effects**:
   - Standard PBR material
   - Custom wave deformation shader
   - Toon shading effect

3. **Interactive Controls**:
   - Orbit controls for camera movement
   - UI buttons to toggle lights, change shaders, and add objects
   - Responsive to window resizing

4. **Scene Elements**:
   - Ground plane with grid helper
   - Multiple 3D objects (box, sphere, torus)
   - Ability to add more objects dynamically

5. **Performance Optimizations**:
   - Shadow mapping for realistic shadows
   - Antialiasing for smoother edges
   - Efficient rendering loop

