# Real-Time 3D Scene Viewer with Dynamic Lighting and Shaders

Below is a complete implementation of a real-time 3D scene viewer using Three.js, a popular JavaScript 3D library. This example includes dynamic lighting, shader effects, and interactive controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Scene Viewer with Shaders</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: Arial, sans-serif;
        }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: white;
            z-index: 100;
            text-shadow: 1px 1px 2px black;
        }
        #controls {
            position: absolute;
            bottom: 10px;
            width: 100%;
            text-align: center;
            color: white;
            z-index: 100;
            text-shadow: 1px 1px 2px black;
        }
    </style>
</head>
<body>
    <div id="info">
        <h1>3D Scene Viewer with Dynamic Lighting</h1>
        <p>Use mouse to look around, WASD to move</p>
    </div>
    <div id="controls">
        <p>Lighting: <span id="lighting-type">Point</span></p>
        <p>Shader: <span id="shader-type">Phong</span></p>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/PointerLockControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/loaders/GLTFLoader.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 2, 5);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls setup
        const controls = new THREE.PointerLockControls(camera, document.body);
        document.addEventListener('click', () => {
            controls.lock();
        });

        // Movement controls
        const moveSpeed = 0.1;
        const moveKeys = {
            'w': false,
            'a': false,
            's': false,
            'd': false
        };

        document.addEventListener('keydown', (event) => {
            if (moveKeys.hasOwnProperty(event.key.toLowerCase())) {
                moveKeys[event.key.toLowerCase()] = true;
            }
        });

        document.addEventListener('keyup', (event) => {
            if (moveKeys.hasOwnProperty(event.key.toLowerCase())) {
                moveKeys[event.key.toLowerCase()] = false;
            }
        });

        // Lighting setup
        let currentLight;
        const lights = {
            point: new THREE.PointLight(0xffffff, 1, 100),
            directional: new THREE.DirectionalLight(0xffffff, 1),
            spot: new THREE.SpotLight(0xffffff, 1, 20, Math.PI / 6, 0.5, 1)
        };

        // Point light setup
        lights.point.position.set(5, 5, 5);
        lights.point.castShadow = true;
        lights.point.shadow.mapSize.width = 1024;
        lights.point.shadow.mapSize.height = 1024;

        // Directional light setup
        lights.directional.position.set(10, 10, 10);
        lights.directional.castShadow = true;
        lights.directional.shadow.mapSize.width = 1024;
        lights.directional.shadow.mapSize.height = 1024;
        lights.directional.shadow.camera.near = 0.5;
        lights.directional.shadow.camera.far = 50;

        // Spot light setup
        lights.spot.position.set(0, 5, 0);
        lights.spot.castShadow = true;
        lights.spot.shadow.mapSize.width = 1024;
        lights.spot.shadow.mapSize.height = 1024;

        // Set initial light
        currentLight = lights.point;
        scene.add(currentLight);

        // Light helper
        const lightHelper = new THREE.PointLightHelper(lights.point, 1);
        scene.add(lightHelper);

        // Shader materials
        const materials = {
            phong: new THREE.MeshPhongMaterial({
                color: 0x3366ff,
                specular: 0x111111,
                shininess: 30,
                flatShading: false
            }),
            toon: new THREE.MeshToonMaterial({
                color: 0x3366ff,
                gradientMap: new THREE.TextureLoader().load('https://threejs.org/examples/textures/gradientMaps/threeTone.jpg')
            }),
            standard: new THREE.MeshStandardMaterial({
                color: 0x3366ff,
                roughness: 0.5,
                metalness: 0.5
            }),
            custom: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    lightPosition: { value: new THREE.Vector3(5, 5, 5) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = position;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform float time;
                    uniform vec3 lightPosition;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vec3 lightDir = normalize(lightPosition - vPosition);
                        float diffuse = max(dot(vNormal, lightDir), 0.0);
                        vec3 color = vec3(0.3, 0.6, 1.0) * diffuse;

                        // Add some animated effect
                        color += 0.1 * sin(time + vPosition.x * 2.0);

                        gl_FragColor = vec4(color, 1.0);
                    }
                `
            })
        };

        // Current material
        let currentMaterial = materials.phong;

        // Create scene objects
        function createScene() {
            // Ground
            const groundGeometry = new THREE.PlaneGeometry(20, 20);
            const groundMaterial = new THREE.MeshStandardMaterial({
                color: 0x333333,
                roughness: 0.8,
                metalness: 0.2
            });
            const ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Boxes
            const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
            for (let i = 0; i < 10; i++) {
                const box = new THREE.Mesh(boxGeometry, currentMaterial.clone());
                box.position.set(
                    Math.random() * 10 - 5,
                    0.5,
                    Math.random() * 10 - 5
                );
                box.castShadow = true;
                box.receiveShadow = true;
                scene.add(box);
            }

            // Sphere
            const sphereGeometry = new THREE.SphereGeometry(0.8, 32, 32);
            const sphere = new THREE.Mesh(sphereGeometry, currentMaterial.clone());
            sphere.position.set(3, 0.8, 0);
            sphere.castShadow = true;
            sphere.receiveShadow = true;
            scene.add(sphere);

            // Torus
            const torusGeometry = new THREE.TorusGeometry(1, 0.4, 16, 100);
            const torus = new THREE.Mesh(torusGeometry, currentMaterial.clone());
            torus.position.set(-3, 0.8, 0);
            torus.castShadow = true;
            torus.receiveShadow = true;
            scene.add(torus);

            // Add some ambient light
            const ambientLight = new THREE.AmbientLight(0x404040);
            scene.add(ambientLight);
        }

        createScene();

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Animation loop
        let time = 0;
        function animate() {
            requestAnimationFrame(animate);

            // Update time for shaders
            time += 0.01;
            if (materials.custom) {
                materials.custom.uniforms.time.value = time;
                materials.custom.uniforms.lightPosition.value = currentLight.position;
            }

            // Handle movement
            if (controls.isLocked) {
                const direction = new THREE.Vector3();
                camera.getWorldDirection(direction);

                if (moveKeys.w) {
                    camera.position.addScaledVector(direction, moveSpeed);
                }
                if (moveKeys.s) {
                    camera.position.addScaledVector(direction, -moveSpeed);
                }
                if (moveKeys.a) {
                    camera.position.x -= moveSpeed;
                }
                if (moveKeys.d) {
                    camera.position.x += moveSpeed;
                }
            }

            // Animate lights
            if (currentLight === lights.point) {
                lights.point.position.x = Math.sin(time) * 5;
                lights.point.position.z = Math.cos(time) * 5;
                lightHelper.update();
            }

            renderer.render(scene, camera);
        }

        animate();

        // UI controls
        document.addEventListener('keydown', (event) => {
            // Change lighting type
            if (event.key === '1') {
                scene.remove(currentLight);
                currentLight = lights.point;
                scene.add(currentLight);
                document.getElementById('lighting-type').textContent = 'Point';
            } else if (event.key === '2') {
                scene.remove(currentLight);
                currentLight = lights.directional;
                scene.add(currentLight);
                document.getElementById('lighting-type').textContent = 'Directional';
            } else if (event.key === '3') {
                scene.remove(currentLight);
                currentLight = lights.spot;
                scene.add(currentLight);
                document.getElementById('lighting-type').textContent = 'Spot';
            }

            // Change shader type
            if (event.key === '4') {
                changeMaterial(materials.phong, 'Phong');
            } else if (event.key === '5') {
                changeMaterial(materials.toon, 'Toon');
            } else if (event.key === '6') {
                changeMaterial(materials.standard, 'Standard');
            } else if (event.key === '7') {
                changeMaterial(materials.custom, 'Custom');
            }
        });

        function changeMaterial(newMaterial, name) {
            currentMaterial = newMaterial;
            scene.traverse((object) => {
                if (object.isMesh && object !== ground) {
                    object.material = currentMaterial.clone();
                }
            });
            document.getElementById('shader-type').textContent = name;
        }
    </script>
</body>
</html>
```

