        directionalLight.shadow.camera.left = -20;
        directionalLight.shadow.camera.right = 20;
        directionalLight.shadow.camera.top = 20;
        directionalLight.shadow.camera.bottom = -20;
        scene.add(directionalLight);

        const pointLight1 = new THREE.PointLight(0xff0000, 2, 20);
        pointLight1.position.set(5, 5, 5);
        pointLight1.castShadow = true;
        scene.add(pointLight1);

        const pointLight2 = new THREE.PointLight(0x00ff00, 2, 20);
        pointLight2.position.set(-5, 5, -5);
        pointLight2.castShadow = true;
        scene.add(pointLight2);

        // Helper to visualize lights
        const lightHelpers = [];
        lightHelpers.push(new THREE.PointLightHelper(pointLight1, 0.5));
        lightHelpers.push(new THREE.PointLightHelper(pointLight2, 0.5));
        lightHelpers.push(new THREE.DirectionalLightHelper(directionalLight, 2));
        lightHelpers.forEach(helper => scene.add(helper));

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(50, 50);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Custom shader material for some objects
        const customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color1: { value: new THREE.Color(0xff0000) },
                color2: { value: new THREE.Color(0x0000ff) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vUv = uv;
                    vNormal = normalize(normalMatrix * normal);
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }
            `,
            fragmentShader: `
                uniform float time;
                uniform vec3 color1;
                uniform vec3 color2;
                varying vec2 vUv;
                varying vec3 vNormal;

                void main() {
                    vec3 color = mix(color1, color2, sin(vUv.x * 10.0 + time) * 0.5 + 0.5);
                    float lighting = dot(vNormal, vec3(0.0, 1.0, 0.0)) * 0.5 + 0.5;
                    gl_FragColor = vec4(color * lighting, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Create some objects
        const objects = [];

        // Box with custom shader
        const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
        const box = new THREE.Mesh(boxGeometry, customShaderMaterial);
        box.position.set(-5, 1, 0);
        box.castShadow = true;
        scene.add(box);
        objects.push(box);

        // Sphere with standard material
        const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0x00aaff,
            roughness: 0.3,
            metalness: 0.7
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(5, 1.5, 0);
        sphere.castShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Torus knot with toon shading
        const torusKnotGeometry = new THREE.TorusKnotGeometry(1, 0.4, 100, 16);
        const toonMaterial = new THREE.MeshToonMaterial({
            color: 0xffaa00,
            gradientMap: createGradientTexture()
        });
        const torusKnot = new THREE.Mesh(torusKnotGeometry, toonMaterial);
        torusKnot.position.set(0, 2, 5);
        torusKnot.castShadow = true;
        scene.add(torusKnot);
        objects.push(torusKnot);

        // Helper function to create gradient texture for toon shading
        function createGradientTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 16;
            canvas.height = 256;

            const context = canvas.getContext('2d');
            const gradient = context.createLinearGradient(0, 0, 0, 256);

            gradient.addColorStop(0.0, '#111');
            gradient.addColorStop(0.5, '#333');
            gradient.addColorStop(1.0, '#555');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 16, 256);

            const texture = new THREE.CanvasTexture(canvas);
            texture.minFilter = THREE.NearestFilter;
            texture.magFilter = THREE.NearestFilter;
            texture.generateMipmaps = false;

            return texture;
        }

        // Skybox
        const skyboxGeometry = new THREE.BoxGeometry(1000, 1000, 1000);
        const skyboxMaterials = [
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('right'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('left'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('top'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('bottom'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('front'), side: THREE.BackSide }),
            new THREE.MeshBasicMaterial({ map: createSkyboxTexture('back'), side: THREE.BackSide })
        ];
        const skybox = new THREE.Mesh(skyboxGeometry, skyboxMaterials);
        scene.add(skybox);

        // Helper function to create skybox textures
        function createSkyboxTexture(side) {
            const canvas = document.createElement('canvas');
            canvas.width = 128;
            canvas.height = 128;

            const context = canvas.getContext('2d');

            // Gradient based on side
            const gradient = context.createLinearGradient(0, 0, canvas.width, canvas.height);

            if (side === 'top') {
                gradient.addColorStop(0, '#000033');
                gradient.addColorStop(1, '#000066');
            } else if (side === 'bottom') {
                gradient.addColorStop(0, '#330000');
                gradient.addColorStop(1, '#660000');
            } else {
                gradient.addColorStop(0, '#000000');
                gradient.addColorStop(1, '#000033');
            }

            context.fillStyle = gradient;
            context.fillRect(0, 0, canvas.width, canvas.height);

            return new THREE.CanvasTexture(canvas);
        }

        // Animation variables
        let time = 0;
        let lightsOn = true;
        let postProcessingOn = true;

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        });

        // Handle keyboard input
        const keys = {};
        window.addEventListener('keydown', (e) => {
            keys[e.key.toLowerCase()] = true;

            // Toggle lights
            if (e.key.toLowerCase() === 'l') {
                lightsOn = !lightsOn;
                ambientLight.visible = lightsOn;
                directionalLight.visible = lightsOn;
                pointLight1.visible = lightsOn;
                pointLight2.visible = lightsOn;
                lightHelpers.forEach(helper => helper.visible = lightsOn);
            }

            // Toggle post-processing
            if (e.key.toLowerCase() === 'p') {
                postProcessingOn = !postProcessingOn;
            }
        });

        window.addEventListener('keyup', (e) => {
            keys[e.key.toLowerCase()] = false;
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update time
            time += 0.01;
            customShaderMaterial.uniforms.time.value = time;

            // Rotate objects
            objects.forEach(obj => {
                obj.rotation.x += 0.005;
                obj.rotation.y += 0.01;
            });

            // Animate lights
            pointLight1.position.x = Math.sin(time) * 5;
            pointLight1.position.z = Math.cos(time) * 5;
            pointLight2.position.x = Math.sin(time + Math.PI) * 5;
            pointLight2.position.z = Math.cos(time + Math.PI) * 5;

            // Update controls
            controls.update();

            // Render
            if (postProcessingOn) {
                composer.render();
            } else {
                renderer.render(scene, camera);
            }
        }

        animate();
    </script>
</body>
</html>
```

## Features of this Implementation:

1. **Dynamic Lighting System**:
   - Ambient light for base illumination
   - Directional light with shadows
   - Two moving point lights with shadows
   - Light helpers to visualize light positions

2. **Shader Effects**:
   - Custom shader material with animated color transitions
   - Toon shading for the torus knot
   - Skybox with procedural textures
   - Ground plane with standard material

3. **Post-Processing Effects**:
