// Main scene setup
let scene, camera, renderer, controls;
let clock = new THREE.Clock();
let mixer;
let lightHelpers = [];
let shaderMaterials = [];

// Initialize the scene
function init() {
    // Create scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);

    // Create camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(5, 5, 5);

    // Create renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Add orbit controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Add lights
    setupLights();

    // Add ground plane
    addGround();

    // Add some sample objects
    addSampleObjects();

    // Add event listeners
    window.addEventListener('resize', onWindowResize);
    window.addEventListener('keydown', onKeyDown);

    // Start animation loop
    animate();
}

// Set up lighting system
function setupLights() {
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    // Directional light (sun)
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    // Add light helper
    const dirLightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
    scene.add(dirLightHelper);
    lightHelpers.push(dirLightHelper);

    // Point light
    const pointLight = new THREE.PointLight(0xff0000, 1, 10);
    pointLight.position.set(2, 2, 2);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Add light helper
    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
    scene.add(pointLightHelper);
    lightHelpers.push(pointLightHelper);

    // Spot light
    const spotLight = new THREE.SpotLight(0x00ff00, 1, 10, Math.PI / 6, 0.5, 1);
    spotLight.position.set(-2, 3, -2);
    spotLight.castShadow = true;
    scene.add(spotLight);

    // Add light helper
    const spotLightHelper = new THREE.SpotLightHelper(spotLight);
    scene.add(spotLightHelper);
    lightHelpers.push(spotLightHelper);
}

// Add ground plane
function addGround() {
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x333333,
        roughness: 0.8,
        metalness: 0.2
    });

    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Add grid helper
    const gridHelper = new THREE.GridHelper(20, 20, 0x444444, 0x666666);
    scene.add(gridHelper);
}

// Add sample objects
function addSampleObjects() {
    // Create a cube with custom shader material
    const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
    const cubeShaderMaterial = createShaderMaterial();
    const cube = new THREE.Mesh(cubeGeometry, cubeShaderMaterial);
    cube.position.set(-2, 0.5, 0);
    cube.castShadow = true;
    scene.add(cube);
    shaderMaterials.push(cubeShaderMaterial);

    // Create a sphere with standard material
    const sphereGeometry = new THREE.SphereGeometry(0.5, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0x0000ff,
        roughness: 0.2,
        metalness: 0.8
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(2, 0.5, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Create a torus knot with custom shader material
    const torusKnotGeometry = new THREE.TorusKnotGeometry(0.5, 0.2, 100, 16);
    const torusKnotShaderMaterial = createShaderMaterial();
    const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotShaderMaterial);
    torusKnot.position.set(0, 1, 2);
    torusKnot.castShadow = true;
    scene.add(torusKnot);
    shaderMaterials.push(torusKnotShaderMaterial);

    // Add a simple animated object
    const animatedGeometry = new THREE.BoxGeometry(0.5, 0.5, 0.5);
    const animatedMaterial = new THREE.MeshStandardMaterial({
        color: 0xff00ff,
        roughness: 0.3,
        metalness: 0.5
    });
    const animatedMesh = new THREE.Mesh(animatedGeometry, animatedMaterial);
    animatedMesh.position.set(0, 0.5, -2);
    animatedMesh.castShadow = true;
    scene.add(animatedMesh);

    // Create animation mixer
    mixer = new THREE.AnimationMixer(animatedMesh);

    // Create a simple animation clip
    const animationClip = THREE.AnimationClip.createFromMorphTargetSequence(
        'animation',
        [animatedMesh.geometry],
        1
    );

    // Play the animation
    const action = mixer.clipAction(animationClip);
    action.play();
}

// Create a custom shader material
function createShaderMaterial() {
    const vertexShader = `
        varying vec3 vNormal;
        varying vec3 vPosition;
        varying vec2 vUv;

        void main() {
            vNormal = normalize(normalMatrix * normal);
            vPosition = position;
            vUv = uv;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `;

    const fragmentShader = `
        uniform float time;
        uniform vec3 color;
        uniform float pulseSpeed;
        uniform float pulseIntensity;

        varying vec3 vNormal;
        varying vec3 vPosition;
        varying vec2 vUv;

        void main() {
            // Calculate pulse effect
            float pulse = sin(time * pulseSpeed) * 0.5 + 0.5;
            pulse = smoothstep(0.0, 1.0, pulse) * pulseIntensity;

            // Calculate normal-based lighting
            vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
            float diffuse = max(dot(vNormal, lightDir), 0.0);

            // Combine color with lighting and pulse
            vec3 finalColor = color * (0.5 + diffuse * 0.5) * (1.0 + pulse);

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `;

    const uniforms = {
        time: { value: 0 },
        color: { value: new THREE.Color(Math.random(), Math.random(), Math.random()) },
        pulseSpeed: { value: 1.0 + Math.random() * 2.0 },
        pulseIntensity: { value: 0.3 + Math.random() * 0.5 }
    };

    return new THREE.ShaderMaterial({
        uniforms: uniforms,
        vertexShader: vertexShader,
        fragmentShader: fragmentShader,
        lights: true
    });
}

// Handle window resize
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Handle keyboard input
function onKeyDown(event) {
    switch (event.key.toLowerCase()) {
        case 'h':
            alert('Controls:\n\n' +
                  'WASD - Move camera\n' +
                  'Mouse - Rotate/pan camera\n' +
                  'Scroll - Zoom\n' +
                  'L - Toggle lights\n' +
                  'S - Toggle shaders\n' +
                  'H - Show help');
            break;
        case 'l':
            toggleLights();
            break;
        case 's':
            toggleShaders();
            break;
    }
}

// Toggle light helpers
function toggleLights() {
    lightHelpers.forEach(helper => {
        helper.visible = !helper.visible;
    });
}

// Toggle shader effects
function toggleShaders() {
    shaderMaterials.forEach(material => {
        material.uniforms.pulseIntensity.value = material.uniforms.pulseIntensity.value > 0 ? 0 : 0.3 + Math.random() * 0.5;
    });
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();

    // Update animation mixer
    if (mixer) {
        mixer.update(delta);
    }

    // Update shader materials
    shaderMaterials.forEach(material => {
        material.uniforms.time.value += delta;
    });

    // Update controls
    controls.update();

    // Render scene
    renderer.render(scene, camera);
}

// Start the application
init();
