// Main application class
class SceneViewer {
    constructor() {
        this.init();
        this.setupEventListeners();
        this.animate();
    }

    init() {
        // Scene setup
        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x222222);

        // Camera setup
        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.camera.position.set(0, 5, 10);

        // Renderer setup
        this.renderer = new THREE.WebGLRenderer({ antialias: true });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.shadowMap.enabled = true;
        this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(this.renderer.domElement);

        // Controls
        this.controls = new THREE.OrbitControls(this.camera, this.renderer.domElement);
        this.controls.enableDamping = true;
        this.controls.dampingFactor = 0.05;

        // Lighting
        this.setupLights();

        // Shader materials
        this.setupShaders();

        // Add objects to scene
        this.addObjects();

        // Performance monitoring
        this.clock = new THREE.Clock();
        this.stats = {
            fps: 0,
            lastTime: performance.now()
        };

        // UI elements
        this.uiElements = {
            lightingStatus: document.getElementById('lighting-status'),
            shaderStatus: document.getElementById('shader-status'),
            fpsDisplay: document.getElementById('fps')
        };
    }

    setupLights() {
        // Ambient light
        this.ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        this.scene.add(this.ambientLight);

        // Directional light (sun)
        this.sunLight = new THREE.DirectionalLight(0xffffff, 1);
        this.sunLight.position.set(5, 10, 7);
        this.sunLight.castShadow = true;
        this.sunLight.shadow.mapSize.width = 1024;
        this.sunLight.shadow.mapSize.height = 1024;
        this.sunLight.shadow.camera.near = 0.5;
        this.sunLight.shadow.camera.far = 50;
        this.scene.add(this.sunLight);

        // Point light (dynamic)
        this.pointLight = new THREE.PointLight(0xffaa00, 1, 20);
        this.pointLight.position.set(0, 2, 0);
        this.pointLight.castShadow = true;
        this.pointLight.shadow.mapSize.width = 512;
        this.pointLight.shadow.mapSize.height = 512;
        this.scene.add(this.pointLight);

        // Helper for debugging
        // const lightHelper = new THREE.DirectionalLightHelper(this.sunLight, 5);
        // this.scene.add(lightHelper);
    }

    setupShaders() {
        // Standard material
        this.standardMaterial = new THREE.MeshStandardMaterial({
            color: 0x336699,
            roughness: 0.4,
            metalness: 0.5,
            envMapIntensity: 1.0
        });

        // Custom shader material
        this.customShaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                lightPosition: { value: this.pointLight.position },
                color: { value: new THREE.Color(0x336699) }
            },
            vertexShader: `
                uniform float time;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    vPosition = position;

                    // Simple wave effect
                    vec3 newPosition = position;
                    newPosition.y += sin(position.x * 2.0 + time) * 0.2;
                    newPosition.x += sin(position.y * 2.0 + time) * 0.2;

                    gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 lightPosition;
                uniform vec3 color;
                varying vec3 vNormal;
                varying vec3 vPosition;

                void main() {
                    // Simple lighting
                    vec3 lightDir = normalize(lightPosition - vPosition);
                    float diffuse = max(dot(vNormal, lightDir), 0.0);

                    // Combine color with lighting
                    vec3 finalColor = color * (0.5 + diffuse * 0.5);

                    gl_FragColor = vec4(finalColor, 1.0);
                }
            `,
            side: THREE.DoubleSide
        });

        // Current material
        this.currentMaterial = this.standardMaterial;
    }

    addObjects() {
        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x3a5f0b,
            roughness: 0.8,
            metalness: 0.2
        });
        this.ground = new THREE.Mesh(groundGeometry, groundMaterial);
        this.ground.rotation.x = -Math.PI / 2;
        this.ground.receiveShadow = true;
        this.scene.add(this.ground);

        // Sample objects
        const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
        const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);

        this.box = new THREE.Mesh(boxGeometry, this.currentMaterial);
        this.box.position.set(-3, 1, 0);
        this.box.castShadow = true;
        this.scene.add(this.box);

        this.sphere = new THREE.Mesh(sphereGeometry, this.currentMaterial);
        this.sphere.position.set(3, 1, 0);
        this.sphere.castShadow = true;
        this.scene.add(this.sphere);

        // Grid helper
        const gridHelper = new THREE.GridHelper(20, 20);
        this.scene.add(gridHelper);

        // Axes helper
        const axesHelper = new THREE.AxesHelper(5);
        this.scene.add(axesHelper);
    }

    toggleLighting() {
        this.ambientLight.visible = !this.ambientLight.visible;
        this.sunLight.visible = !this.sunLight.visible;
        this.pointLight.visible = !this.pointLight.visible;

        this.uiElements.lightingStatus.textContent = this.ambientLight.visible ? 'On' : 'Off';
    }

    toggleShader() {
        if (this.currentMaterial === this.standardMaterial) {
            this.currentMaterial = this.customShaderMaterial;
            this.uiElements.shaderStatus.textContent = 'Custom';
        } else {
            this.currentMaterial = this.standardMaterial;
            this.uiElements.shaderStatus.textContent = 'Standard';
        }

        // Update all meshes to use the new material
        this.box.material = this.currentMaterial;
        this.sphere.material = this.currentMaterial;
    }

    setupEventListeners() {
        window.addEventListener('resize', () => this.onWindowResize());
        window.addEventListener('keydown', (e) => this.onKeyDown(e));

        // Touch events for mobile
        let touchStartX = 0;
        let touchStartY = 0;

        this.renderer.domElement.addEventListener('touchstart', (e) => {
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
        });

        this.renderer.domElement.addEventListener('touchmove', (e) => {
            const touchX = e.touches[0].clientX;
            const touchY = e.touches[0].clientY;

            const deltaX = touchX - touchStartX;
            const deltaY = touchY - touchStartY;

            this.camera.position.x -= deltaX * 0.01;
            this.camera.position.y += deltaY * 0.01;

            touchStartX = touchX;
            touchStartY = touchY;
        });
    }

    onWindowResize() {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
    }

    onKeyDown(e) {
        switch (e.key.toLowerCase()) {
            case 'l':
                this.toggleLighting();
                break;
            case 's':
                this.toggleShader();
                break;
            case 'h':
                alert(`
                    Controls:
                    - L: Toggle lighting
                    - S: Toggle shader
                    - H: Show help
                    - Mouse drag: Rotate view
                    - Mouse wheel: Zoom
                    - Touch: Move camera
                `);
                break;
        }
    }

    update() {
        const delta = this.clock.getDelta();

        // Update point light position (pulsing effect)
        this.pointLight.position.y = 2 + Math.sin(Date.now() * 0.002) * 0.5;

        // Update custom shader uniforms if active
        if (this.currentMaterial === this.customShaderMaterial) {
            this.currentMaterial.uniforms.time.value += delta;
            this.currentMaterial.uniforms.lightPosition.value = this.pointLight.position;
        }

        // Update controls
        this.controls.update();

        // Update FPS counter
        const now = performance.now();
        const elapsed = now - this.stats.lastTime;
        if (elapsed >= 1000) {
            this.stats.fps = Math.round(1000 / (elapsed / (now - this.stats.lastTime)));
            this.stats.lastTime = now;
            this.uiElements.fpsDisplay.textContent = this.stats.fps;
        }
    }

    render() {
        this.renderer.render(this.scene, this.camera);
    }

    animate() {
        requestAnimationFrame(() => this.animate());
        this.update();
        this.render();
    }
}

// Initialize the application when the page loads
window.addEventListener('DOMContentLoaded', () => {
    new SceneViewer();
});
