scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

// Light helper
const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(lightHelper);

// Shadow camera helper
const shadowHelper = new THREE.CameraHelper(directionalLight.shadow.camera);
scene.add(shadowHelper);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Objects in the scene
const objects = [];

// Create a cube
const cubeGeometry = new THREE.BoxGeometry(2, 2, 2);
const cubeMaterial = new THREE.MeshStandardMaterial({
    color: 0x00aaff,
    roughness: 0.3,
    metalness: 0.5
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.position.set(-4, 1, 0);
cube.castShadow = true;
scene.add(cube);
objects.push(cube);

// Create a sphere
const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
const sphereMaterial = new THREE.MeshStandardMaterial({
    color: 0xffaa00,
    roughness: 0.2,
    metalness: 0.8
});
const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
sphere.position.set(4, 1.5, 0);
sphere.castShadow = true;
scene.add(sphere);
objects.push(sphere);

// Create a torus
const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
const torusMaterial = new THREE.MeshStandardMaterial({
    color: 0xff00aa,
    roughness: 0.4,
    metalness: 0.6
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(0, 1, 4);
torus.castShadow = true;
scene.add(torus);
objects.push(torus);

// Shader effects
const shaderEffects = {
    none: {
        apply: (material) => {
            // Reset to standard material
            material.onBeforeCompile = null;
        }
    },
    toon: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.fragmentShader = shader.fragmentShader.replace(
                    '#include <dithering_fragment>',
                    `
                    #include <dithering_fragment>
                    float intensity = dot(normal, lightDirection);
                    if (intensity > 0.95) intensity = 1.0;
                    else if (intensity > 0.5) intensity = 0.6;
                    else if (intensity > 0.25) intensity = 0.3;
                    else intensity = 0.0;
                    gl_FragColor.rgb *= intensity;
                    `
                );
            };
        }
    },
    water: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.uniforms.time = { value: 0 };
                shader.fragmentShader = shader.fragmentShader.replace(
                    '#include <dithering_fragment>',
                    `
                    #include <dithering_fragment>
                    vec2 distortion = vec2(
                        sin(time + uv.y * 10.0) * 0.1,
                        cos(time + uv.x * 10.0) * 0.1
                    );
                    vec4 texColor = texture2D(map, uv + distortion);
                    gl_FragColor = mix(gl_FragColor, texColor, 0.3);
                    `
                );
            };
        }
    },
    glitch: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.uniforms.time = { value: 0 };
                shader.fragmentShader = shader.fragmentShader.replace(
                    '#include <dithering_fragment>',
                    `
                    #include <dithering_fragment>
                    if (fract(time * 10.0) < 0.1) {
                        float glitch = sin(time * 100.0) * 0.1;
                        gl_FragColor.rgb += vec3(glitch, glitch * 0.5, glitch * 0.3);
                    }
                    `
                );
            };
        }
    }
};

// UI Controls
const lightIntensitySlider = document.getElementById('lightIntensity');
const lightIntensityValue = document.getElementById('lightIntensityValue');
const shaderEffectSelect = document.getElementById('shaderEffect');
const shaderEffectValue = document.getElementById('shaderEffectValue');

lightIntensitySlider.addEventListener('input', (e) => {
