## JavaScript Implementation (app.js)

```javascript
// Main scene setup
let scene, camera, renderer, controls;
let directionalLight, ambientLight;
let shaderMaterials = [];
let currentShaderIndex = 0;
let objects = [];

// Initialize the scene
function init() {
    // Create scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);

    // Create camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(5, 5, 5);

    // Create renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.getElementById('container').appendChild(renderer.domElement);

    // Add orbit controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Add lights
    setupLights();

    // Add initial objects
    addDefaultObjects();

    // Setup shader materials
    setupShaderMaterials();

    // Add event listeners
    setupEventListeners();

    // Start animation loop
    animate();
}

// Setup lighting
function setupLights() {
    // Directional light (sun)
    directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    scene.add(directionalLight);

    // Ambient light
    ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    // Helper for light visualization
    const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
    scene.add(lightHelper);
}

// Add default objects to the scene
function addDefaultObjects() {
    // Ground plane
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x333333,
        roughness: 0.8,
        metalness: 0.2
    });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Add some sample objects
    addObject('box');
    addObject('sphere');
    addObject('torus');
}

// Add an object to the scene
function addObject(type) {
    let geometry, material;

    switch(type) {
        case 'box':
            geometry = new THREE.BoxGeometry(1, 1, 1);
            material = new THREE.MeshStandardMaterial({
                color: 0x00ff00,
                roughness: 0.4,
                metalness: 0.6
            });
            break;
        case 'sphere':
            geometry = new THREE.SphereGeometry(0.7, 32, 32);
            material = new THREE.MeshStandardMaterial({
                color: 0xff0000,
                roughness: 0.3,
                metalness: 0.7
            });
            break;
        case 'torus':
            geometry = new THREE.TorusGeometry(0.7, 0.2, 16, 32);
            material = new THREE.MeshStandardMaterial({
                color: 0x0000ff,
                roughness: 0.5,
                metalness: 0.3
            });
            break;
        default:
            geometry = new THREE.BoxGeometry(1, 1, 1);
            material = new THREE.MeshStandardMaterial({ color: 0xffffff });
    }

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(
        (Math.random() - 0.5) * 8,
        0.5,
        (Math.random() - 0.5) * 8
    );
    mesh.castShadow = true;
    mesh.receiveShadow = true;

    // Add random rotation
    mesh.rotation.x = Math.random() * Math.PI;
    mesh.rotation.y = Math.random() * Math.PI;

    scene.add(mesh);
    objects.push(mesh);

    return mesh;
}

// Setup shader materials
function setupShaderMaterials() {
    // Basic shader material
    const basicShader = new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0x00ff00) }
        },
        vertexShader: `
            uniform float time;
            varying vec2 vUv;

            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.y += sin(pos.x * 5.0 + time) * 0.1;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            varying vec2 vUv;

            void main() {
                gl_FragColor = vec4(color * (0.5 + 0.5 * sin(vUv.y * 10.0)), 1.0);
            }
        `
    });

    // Toon shader material
    const toonShader = new THREE.ShaderMaterial({
        uniforms: {
            uDirLightPos: { value: new THREE.Vector3(5, 10, 7) },
            uDirLightColor: { value: new THREE.Color(0xffffff) },
            uAmbientLightColor: { value: new THREE.Color(0x404040) }
        },
        vertexShader: `
            varying vec3 vNormal;
            varying vec3 vPosition;

            void main() {
                vNormal = normalize(normalMatrix * normal);
                vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 uDirLightPos;
            uniform vec3 uDirLightColor;
            uniform vec3 uAmbientLightColor;
            varying vec3 vNormal;
            varying vec3 vPosition;

            void main() {
                vec3 normal = normalize(vNormal);
                vec3 lightDir = normalize(uDirLightPos - vPosition);

                // Diffuse lighting
                float diff = max(dot(normal, lightDir), 0.0);
                diff = smoothstep(0.0, 0.5, diff);

                // Combine lighting
                vec3 color = uAmbientLightColor + uDirLightColor * diff;

                gl_FragColor = vec4(color, 1.0);
            }
        `
    });

    // Water shader material
    const waterShader = new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            uColor: { value: new THREE.Color(0x00aaff) },
            uWaveSpeed: { value: 0.5 },
            uWaveHeight: { value: 0.2 }
        },
        vertexShader: `
            uniform float time;
            uniform float uWaveSpeed;
            uniform float uWaveHeight;
            varying vec2 vUv;

            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.z += sin(pos.x * 5.0 + time * uWaveSpeed) * uWaveHeight;
                pos.z += cos(pos.y * 5.0 + time * uWaveSpeed) * uWaveHeight;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 uColor;
            varying vec2 vUv;

            void main() {
                float depth = 1.0 - vUv.y;
                vec3 color = uColor * (0.5 + 0.5 * depth);
                gl_FragColor = vec4(color, 0.8);
            }
        `
    });

    shaderMaterials.push(basicShader, toonShader, waterShader);
}

// Apply shader to all objects
function applyShaderToAllObjects(shaderIndex) {
    if (shaderIndex >= 0 && shaderIndex < shaderMaterials.length) {
        currentShaderIndex = shaderIndex;
        objects.forEach(obj => {
            obj.material = shaderMaterials[shaderIndex];
        });
    }
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader uniforms if needed
    const time = performance.now() * 0.001;
    if (currentShaderIndex === 0) {
        shaderMaterials[0].uniforms.time.value = time;
    } else if (currentShaderIndex === 2) {
        shaderMaterials[2].uniforms.time.value = time;
    }

    // Rotate objects slightly
    objects.forEach(obj => {
        obj.rotation.y += 0.005;
    });

    renderer.render(scene, camera);
}

// Event listeners
function setupEventListeners() {
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    document.getElementById('toggleLight').addEventListener('click', () => {
        directionalLight.visible = !directionalLight.visible;
    });

    document.getElementById('changeShader').addEventListener('click', () => {
        currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
        applyShaderToAllObjects(currentShaderIndex);
    });

    document.getElementById('addObject').addEventListener('click', () => {
        const types = ['box', 'sphere', 'torus'];
        const randomType = types[Math.floor(Math.random() * types.length)];
        addObject(randomType);
    });

    document.getElementById('lightIntensity').addEventListener('input', (e) => {
        directionalLight.intensity = parseFloat(e.target.value);
    });

    document.addEventListener('keydown', (e) => {
        if (e.key === 'h' || e.key === 'H') {
            const controlsDiv = document.getElementById('controls');
            controlsDiv.style.display = controlsDiv.style.display === 'none' ? 'block' : 'none';
        }
    });
}

// Start the application
init();
