    standard: cubeMaterial,
    toon: new THREE.MeshToonMaterial({
        color: 0x00ff00,
        gradientMap: createGradientTexture()
    }),
    water: new THREE.MeshPhongMaterial({
        color: 0x00aaff,
        shininess: 100,
        specular: 0x111111,
        transparent: true,
        opacity: 0.8
    }),
    glitch: createGlitchMaterial()
};

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 256;

    const context = canvas.getContext('2d');
    const gradient = context.createLinearGradient(0, 0, 0, 256);

    gradient.addColorStop(0.0, '#ffffff');
    gradient.addColorStop(0.2, '#ffffff');
    gradient.addColorStop(0.4, '#0000ff');
    gradient.addColorStop(0.6, '#000088');
    gradient.addColorStop(0.8, '#000000');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 16, 256);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// Helper function to create glitch material
function createGlitchMaterial() {
    const vertexShader = `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `;

    const fragmentShader = `
        uniform float time;
        uniform sampler2D tDiffuse;
        varying vec2 vUv;

        void main() {
            vec2 uv = vUv;

            // Simple glitch effect
            if (sin(time * 5.0) > 0.9) {
                uv.y = 1.0 - uv.y;
            }

            if (sin(time * 7.0) > 0.95) {
                uv.x = 1.0 - uv.x;
            }

            vec4 color = texture2D(tDiffuse, uv);

            // Add scanlines
            if (mod(gl_FragCoord.y, 2.0) == 0.0) {
                color.rgb *= 0.9;
            }

            gl_FragColor = color;
        }
    `;

    const material = new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            tDiffuse: { value: new THREE.TextureLoader().load('https://threejs.org/examples/textures/uv_grid_opengl.jpg') }
        },
        vertexShader: vertexShader,
        fragmentShader: fragmentShader
    });

    return material;
}

// UI Controls
document.getElementById('light-color').addEventListener('input', (e) => {
    directionalLight.color.set(e.target.value);
});

document.getElementById('light-intensity').addEventListener('input', (e) => {
    directionalLight.intensity = parseFloat(e.target.value);
});

document.getElementById('shader-effect').addEventListener('change', (e) => {
    const effect = e.target.value;
    cube.material = shaderMaterials[effect];

    // Special handling for water effect
    if (effect === 'water') {
        cube.material.displacementMap = new THREE.TextureLoader().load('https://threejs.org/examples/textures/water.jpg');
        cube.material.displacementScale = 0.1;
    }
});

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Animate objects
    cube.rotation.x += 0.01;
    cube.rotation.y += 0.01;
    sphere.rotation.y += 0.005;

    // Update shader uniforms if needed
    if (cube.material.uniforms && cube.material.uniforms.time) {
        cube.material.uniforms.time.value += 0.01;
    }

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
