// Custom shader for glitch effect
const glitchMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        tDiffuse: { value: null },
        amount: { value: 0.02 }
    },
    vertexShader: `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform float time;
        uniform float amount;
        uniform sampler2D tDiffuse;
        varying vec2 vUv;

        float rand(vec2 co){
            return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
        }

        void main() {
            vec2 p = vUv;
            float xs = floor(gl_FragCoord.x / 0.5);
            float ys = floor(gl_FragCoord.y / 0.5);
            vec4 color = texture2D(tDiffuse, p);

            vec2 normalPos = vec2(vUv.x, vUv.y);
            vec2 rnd = vec2(rand(vec2(ys, time)), rand(vec2(xs, time)));
            if (normalPos.x < rnd.x * 0.1 && normalPos.y < rnd.y * 0.1) {
                color = vec4(rnd.x, 0.5, rnd.y, 1.0);
            }

            gl_FragColor = color;
