    torus.position.set(0, 1, 3);
    torus.castShadow = true;
    scene.add(torus);
    objects.push(torus);
}

// Shader effects
const shaderEffects = {
    none: null,
    toon: {
        uniforms: THREE.UniformsUtils.clone(THREE.ToonShader.uniforms),
        vertexShader: THREE.ToonShader.vertexShader,
        fragmentShader: THREE.ToonShader.fragmentShader
    },
    water: {
        uniforms: THREE.UniformsUtils.clone(THREE.WaterRefractionShader.uniforms),
        vertexShader: THREE.WaterRefractionShader.vertexShader,
        fragmentShader: THREE.WaterRefractionShader.fragmentShader
    },
    glow: {
        uniforms: {
            glowColor: { value: new THREE.Color(0xffff00) },
            glowIntensity: { value: 0.5 }
        },
        vertexShader: `
            varying vec3 vNormal;
            void main() {
                vNormal = normalize(normalMatrix * normal);
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 glowColor;
            uniform float glowIntensity;
            varying vec3 vNormal;
            void main() {
                float intensity = pow(0.5 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 2.0);
                gl_FragColor = vec4(glowColor, intensity * glowIntensity);
            }
        `
    }
};

// Apply shader effect to all objects
function applyShaderEffect(effectName) {
    const effect = shaderEffects[effectName];

    objects.forEach(obj => {
        if (effect) {
            if (obj.material.userData.originalMaterial) {
                // Restore original material if it exists
                obj.material = obj.material.userData.originalMaterial;
            } else {
                // Store original material
                obj.material.userData.originalMaterial = obj.material.clone();
            }

            // Create shader material
            const shaderMaterial = new THREE.ShaderMaterial({
                uniforms: effect.uniforms,
                vertexShader: effect.vertexShader,
                fragmentShader: effect.fragmentShader,
                lights: true
            });

            // Copy properties from original material
            shaderMaterial.color = obj.material.color;
            shaderMaterial.roughness = obj.material.roughness;
            shaderMaterial.metalness = obj.material.metalness;

            obj.material = shaderMaterial;
        } else {
            // Restore original material if no effect
            if (obj.material.userData.originalMaterial) {
                obj.material = obj.material.userData.originalMaterial;
                delete obj.material.userData.originalMaterial;
            }
        }
    });
}

