scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

// Helper to visualize light direction
const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(lightHelper);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Objects in the scene
const objects = [];

// Create a cube
const cubeGeometry = new THREE.BoxGeometry(2, 2, 2);
const cubeMaterial = new THREE.MeshStandardMaterial({
    color: 0x00ff00,
    roughness: 0.5,
    metalness: 0.5
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.position.set(-3, 1, 0);
cube.castShadow = true;
scene.add(cube);
objects.push(cube);

// Create a sphere
const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
const sphereMaterial = new THREE.MeshStandardMaterial({
    color: 0xff0000,
    roughness: 0.3,
    metalness: 0.7
});
const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
sphere.position.set(3, 1.5, 0);
sphere.castShadow = true;
scene.add(sphere);
objects.push(sphere);

// Create a torus
const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
const torusMaterial = new THREE.MeshStandardMaterial({
    color: 0x0000ff,
    roughness: 0.4,
    metalness: 0.6
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(0, 1, 3);
torus.castShadow = true;
scene.add(torus);
objects.push(torus);

// Shader effects
const shaderEffects = {
    none: {
        apply: (material) => {
            // Reset to standard material
            material.onBeforeCompile = null;
        }
    },
    toon: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.fragmentShader = `
                    uniform vec3 uLightColor;
                    varying vec3 vNormal;
                    varying vec3 vViewPosition;

                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 lightDir = normalize(vec3(5, 10, 7));
                        float diffuse = max(dot(normal, lightDir), 0.0);

                        // Toon shading with 4 bands
                        float toon = floor(diffuse * 4.0) / 4.0;

                        vec3 color = mix(vec3(0.1), uLightColor, toon);
                        gl_FragColor = vec4(color, 1.0);
                    }
                `;

                shader.uniforms.uLightColor = { value: new THREE.Color(0xffffff) };
            };
        }
    },
    water: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.uniforms.time = { value: 0 };

                shader.vertexShader = `
                    uniform float time;
                    varying vec2 vUv;
                    ${shader.vertexShader}
                `.replace(
                    '#include <begin_vertex>',
                    `#include <begin_vertex>
                    vUv = uv;
                    float wave = sin(position.x * 2.0 + time * 2.0) * 0.1;
                    transformed.y += wave;
                    `
                );

                shader.fragmentShader = `
                    uniform float time;
                    varying vec2 vUv;
                    ${shader.fragmentShader}
                `.replace(
                    'vec4 diffuseColor = vec4( diffuse, opacity );',
                    `vec4 diffuseColor = vec4( diffuse, opacity );
                    float waveEffect = sin(vUv.x * 10.0 + time * 3.0) * 0.1 + 0.5;
                    diffuseColor.rgb *= waveEffect;
                    `
                );
            };
        }
    },
    heat: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.uniforms.time = { value: 0 };

                shader.fragmentShader = `
                    uniform float time;
                    ${shader.fragmentShader}
                `.replace(
                    'vec4 diffuseColor = vec4( diffuse, opacity );',
                    `vec4 diffuseColor = vec4( diffuse, opacity );
                    float heat = sin(vUv.x * 10.0 + time * 2.0) * 0.5 + 0.5;
                    diffuseColor.r += heat * 0.5;
                    diffuseColor.g += heat * 0.3;
                    `
                );
            };
        }
    }
};

// Apply initial shader effect
let currentShader = 'none';
shaderEffects[currentShader].apply(cube.material);
shaderEffects[currentShader].apply(sphere.material);
shaderEffects[currentShader].apply(torus.material);

// UI Controls
document.getElementById('lightIntensity').addEventListener('input', (e) => {
    const intensity = parseFloat(e.target.value);
    directionalLight.intensity = intensity;
    document.getElementById('lightIntensityValue').textContent = intensity.toFixed(1);
});

document.getElementById('shaderEffect').addEventListener('change', (e) => {
    currentShader = e.target.value;

    // Reapply shader to all objects
    objects.forEach(obj => {
        shaderEffects[currentShader].apply(obj.material);
    });
});

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update time for shader effects
    const time = performance.now() * 0.001;

    objects.forEach(obj => {
        if (obj.material.onBeforeCompile) {
            obj.material.userData.time = time;
            if (obj.material.uniforms && obj.material.uniforms.time) {
                obj.material.uniforms.time.value = time;
            }
        }
    });

    // Rotate objects slightly
    cube.rotation.x += 0.005;
    cube.rotation.y += 0.005;
    sphere.rotation.y += 0.007;
    torus.rotation.x += 0.003;

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
