    point: new THREE.PointLightHelper(pointLight, 0.5)
};
scene.add(lightHelpers.directional);
scene.add(lightHelpers.point);

// Create a custom shader material
const customMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        lightPos: { value: new THREE.Vector3(5, 5, 5) },
        color: { value: new THREE.Color(0x00ff00) }
    },
    vertexShader: `
        uniform float time;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            vNormal = normalize(normalMatrix * normal);
            vPosition = position;

            // Simple wave effect
            vec3 newPosition = position + normal * sin(position.x * 10.0 + time) * 0.1;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 lightPos;
        uniform vec3 color;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            // Calculate lighting
            vec3 lightDir = normalize(lightPos - vPosition);
            float diffuse = max(dot(vNormal, lightDir), 0.0);

            // Combine with base color
            vec3 finalColor = color * (0.5 + diffuse * 0.5);

            gl_FragColor = vec4(finalColor, 1.0);
