        void main() {
            // Directional light
            vec3 lightDir = normalize(uDirLightPos - vPosition);
            float diffuse = max(dot(vNormal, lightDir), 0.0);

            // Toon shading - quantize the diffuse value
            diffuse = floor(diffuse * 3.0) / 3.0;

            // Combine lighting
            vec3 color = uAmbientLightColor + uDirLightColor * diffuse;

            gl_FragColor = vec4(color, 1.0);
