        shininess: 30,
        emissive: 0xff4400,
        emissiveIntensity: 0.5
    })
};

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 256;

    const context = canvas.getContext('2d');
    const gradient = context.createLinearGradient(0, 0, 0, 256);

    gradient.addColorStop(0.0, 'rgb(255,255,255)');
    gradient.addColorStop(0.2, 'rgb(255,255,255)');
    gradient.addColorStop(0.4, 'rgb(255,255,255)');
    gradient.addColorStop(0.4, 'rgb(0,0,0)');
    gradient.addColorStop(1.0, 'rgb(0,0,0)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 16, 256);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// Helper function to create environment map for water effect
function createEnvMap() {
    const path = 'https://threejs.org/examples/textures/cube/SwedishRoyalCastle/';
    const format = '.jpg';
    const urls = [
        path + 'px' + format, path + 'nx' + format,
        path + 'py' + format, path + 'ny' + format,
        path + 'pz' + format, path + 'nz' + format
    ];

    return new THREE.CubeTextureLoader().load(urls);
}

// UI Controls
document.getElementById('lightIntensity').addEventListener('input', (e) => {
    const intensity = parseFloat(e.target.value);
    directionalLight.intensity = intensity;
    ambientLight.intensity = intensity * 0.5;
});

document.getElementById('shaderEffect').addEventListener('change', (e) => {
    const effect = e.target.value;
    cube.material = shaderMaterials[effect];

    // Special handling for water effect
    if (effect === 'water') {
        cube.material.envMap = createEnvMap();
    }
});

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Rotate objects
    cube.rotation.x += 0.01;
    cube.rotation.y += 0.01;
    sphere.rotation.x += 0.005;
    sphere.rotation.y += 0.01;

    // Update controls
    controls.update();

    // Render
    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
