directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

// Point light for dynamic effects
const pointLight = new THREE.PointLight(0xff0000, 1, 10);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Shader material for custom effects
const shaderMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        resolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) },
        lightPosition: { value: pointLight.position }
    },
    vertexShader: `
        uniform float time;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            vUv = uv;
            vNormal = normalize(normalMatrix * normal);
            vPosition = position;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform float time;
        uniform vec2 resolution;
        uniform vec3 lightPosition;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            // Calculate light direction
            vec3 lightDir = normalize(lightPosition - vPosition);

            // Diffuse lighting
            float diff = max(dot(vNormal, lightDir), 0.0);

            // Simple wave pattern
            float wave = sin(vUv.x * 10.0 + time) * 0.5 + 0.5;

            // Combine colors
            vec3 color = vec3(0.2, 0.5, 0.8) * diff + vec3(wave * 0.2);

            gl_FragColor = vec4(color, 1.0);
        }
    `,
    side: THREE.DoubleSide
});

