    shaderSphere.rotation.y += 0.01;

    // Animate point light
    pointLight.position.x = Math.sin(Date.now() * 0.001) * 3;
    pointLight.position.z = Math.cos(Date.now() * 0.001) * 3;

    // Update shader uniforms
