        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lights
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        const pointLight = new THREE.PointLight(0xff0000, 1, 10);
        pointLight.position.set(0, 2, 0);
        pointLight.castShadow = true;
        scene.add(pointLight);

        // Helper to visualize lights
        const lightHelpers = [];
        lightHelpers.push(new THREE.DirectionalLightHelper(directionalLight, 1));
        lightHelpers.push(new THREE.PointLightHelper(pointLight, 0.5));
        lightHelpers.forEach(helper => scene.add(helper));

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Objects
        const objects = [];

        // Cube
        const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
        const cubeMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ff00,
            roughness: 0.5,
            metalness: 0.5
        });
        const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
        cube.position.set(-2, 0.5, 0);
        cube.castShadow = true;
        scene.add(cube);
        objects.push(cube);

        // Sphere
        const sphereGeometry = new THREE.SphereGeometry(0.5, 32, 32);
        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0x0000ff,
            roughness: 0.3,
            metalness: 0.7
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(2, 0.5, 0);
        sphere.castShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Torus
        const torusGeometry = new THREE.TorusGeometry(0.7, 0.2, 16, 32);
        const torusMaterial = new THREE.MeshStandardMaterial({
            color: 0xff00ff,
            roughness: 0.4,
            metalness: 0.6
        });
        const torus = new THREE.Mesh(torusGeometry, torusMaterial);
        torus.position.set(0, 0.5, 2);
        torus.castShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Shader materials
        const shaderMaterials = {
            cube: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0x00ff00) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.1;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec2 vUv;
                    void main() {
                        gl_FragColor = vec4(color * (0.5 + 0.5 * sin(vUv.y * 10.0 + time)), 1.0);
                    }
                `
            }),
            sphere: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0x0000ff) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec3 vNormal;
                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vec3 pos = position;
                        pos += normal * sin(pos.x * 5.0 + time) * 0.1;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec3 vNormal;
                    void main() {
                        float intensity = pow(0.5 - dot(vNormal, vec3(0, 0, 1)), 4.0);
                        gl_FragColor = vec4(color * intensity, 1.0);
                    }
                `
            }),
            torus: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0xff00ff) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.x += sin(pos.y * 5.0 + time) * 0.1;
                        pos.z += cos(pos.y * 5.0 + time) * 0.1;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec2 vUv;
                    void main() {
                        float pattern = sin(vUv.x * 10.0) * sin(vUv.y * 10.0);
                        gl_FragColor = vec4(color * (0.5 + 0.5 * pattern), 1.0);
                    }
                `
            })
        };

        // Animation state
        let time = 0;
        let lightsVisible = true;
        let shadersActive = false;

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update time
            time += 0.01;

            // Update shader uniforms
            if (shadersActive) {
                shaderMaterials.cube.uniforms.time.value = time;
                shaderMaterials.sphere.uniforms.time.value = time;
                shaderMaterials.torus.uniforms.time.value = time;
            }

            // Animate objects
            objects.forEach((obj, i) => {
                obj.rotation.x += 0.005 * (i + 1);
                obj.rotation.y += 0.007 * (i + 1);
            });

            // Animate point light
            pointLight.position.x = Math.sin(time) * 3;
            pointLight.position.z = Math.cos(time) * 3;

            // Update controls
            controls.update();

            // Render
            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Keyboard controls
        document.addEventListener('keydown', (event) => {
            switch (event.key.toLowerCase()) {
                case 'l':
                    lightsVisible = !lightsVisible;
                    lightHelpers.forEach(helper => helper.visible = lightsVisible);
                    break;
                case 's':
                    shadersActive = !shadersActive;
                    objects.forEach((obj, i) => {
                        obj.material = shadersActive ?
                            shaderMaterials[Object.keys(shaderMaterials)[i]] :
                            new THREE.MeshStandardMaterial({
                                color: obj.material.color,
                                roughness: 0.5,
                                metalness: 0.5
                            });
                    });
                    break;
            }
        });

        // Start animation
        animate();
    </script>
