    roughness: 0.6,
    metalness: 0.1
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.position.set(0, 1, 3);
cube.castShadow = true;
scene.add(cube);
objects.push(cube);

// Shader materials
const shaderMaterials = {
    none: null,
    toon: new THREE.MeshToonMaterial({
        color: 0xffffff,
        gradientMap: createGradientTexture()
    }),
    water: new THREE.MeshPhongMaterial({
        color: 0x1e90ff,
        specular: 0x111111,
        shininess: 30,
        transparent: true,
        opacity: 0.8
    }),
    heat: new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0xff4500) }
        },
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.z += sin(pos.x * 5.0 + time * 2.0) * 0.1;
                pos.z += cos(pos.y * 5.0 + time * 2.0) * 0.1;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            varying vec2 vUv;
            void main() {
                float intensity = 0.5 + sin(vUv.x * 10.0) * 0.3;
                gl_FragColor = vec4(color * intensity, 1.0);
            }
        `
    })
};

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 256;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 0, 256);
    gradient.addColorStop(0.0, '#111');
    gradient.addColorStop(0.5, '#333');
    gradient.addColorStop(0.9, '#fff');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 16, 256);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// UI Controls
document.getElementById('lightIntensity').addEventListener('input', (e) => {
    directionalLight.intensity = parseFloat(e.target.value);
});

document.getElementById('shaderEffect').addEventListener('change', (e) => {
    const effect = e.target.value;
    objects.forEach(obj => {
        if (effect === 'none') {
            // Restore original material
            obj.material = obj.userData.originalMaterial;
        } else {
            // Store original material if not already stored
            if (!obj.userData.originalMaterial) {
                obj.userData.originalMaterial = obj.material;
            }

            // Apply shader effect
            if (effect === 'toon') {
                obj.material = shaderMaterials.toon.clone();
                obj.material.color.copy(obj.userData.originalMaterial.color);
            } else if (effect === 'water') {
                obj.material = shaderMaterials.water.clone();
                obj.material.color.copy(obj.userData.originalMaterial.color);
            } else if (effect === 'heat') {
                obj.material = shaderMaterials.heat.clone();
                obj.material.uniforms.color.value.copy(obj.userData.originalMaterial.color);
            }
        }
    });
});

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader effects
    if (shaderMaterials.heat) {
        shaderMaterials.heat.uniforms.time.value += 0.01;
    }

    // Rotate objects slightly
    torusKnot.rotation.x += 0.005;
    torusKnot.rotation.y += 0.005;

    sphere.rotation.x += 0.003;
    sphere.rotation.y += 0.007;

    cube.rotation.x += 0.004;
    cube.rotation.y += 0.002;

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
