    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        // Light helper
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Sample objects
        const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
        const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);

        const materials = [
            new THREE.MeshStandardMaterial({ color: 0xff0000, roughness: 0.5, metalness: 0.5 }),
            new THREE.MeshStandardMaterial({ color: 0x00ff00, roughness: 0.5, metalness: 0.5 }),
            new THREE.MeshStandardMaterial({ color: 0x0000ff, roughness: 0.5, metalness: 0.5 })
        ];

        const box = new THREE.Mesh(boxGeometry, materials);
        box.position.set(-3, 1, 0);
        box.castShadow = true;
        scene.add(box);

        const sphere = new THREE.Mesh(sphereGeometry, new THREE.MeshStandardMaterial({
            color: 0xffff00,
            roughness: 0.3,
            metalness: 0.7
        }));
        sphere.position.set(3, 1, 0);
        sphere.castShadow = true;
        scene.add(sphere);

        // Shader effects
        const shaderEffects = {
            none: null,
            toon: new THREE.ShaderMaterial({
                uniforms: {
                    uDirLightPos: { value: directionalLight.position },
                    uDirLightColor: { value: directionalLight.color },
                    uAmbientLightColor: { value: ambientLight.color }
                },
                vertexShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    uniform vec3 uDirLightPos;
                    uniform vec3 uDirLightColor;
                    uniform vec3 uAmbientLightColor;

                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 lightDir = normalize(uDirLightPos - vPosition);
                        float diffuse = max(dot(normal, lightDir), 0.0);

                        // Toon shading
                        if (diffuse > 0.95) diffuse = 1.0;
                        else if (diffuse > 0.5) diffuse = 0.7;
                        else if (diffuse > 0.2) diffuse = 0.4;
                        else diffuse = 0.1;

                        vec3 color = uAmbientLightColor + uDirLightColor * diffuse;
                        gl_FragColor = vec4(color, 1.0);
                    }
                `
            }),
            water: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    uDirLightPos: { value: directionalLight.position },
                    uDirLightColor: { value: directionalLight.color },
                    uAmbientLightColor: { value: ambientLight.color }
                },
                vertexShader: `
                    uniform float time;
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;

                        // Simple water distortion
                        vec3 newPosition = position;
                        newPosition.z += sin(position.x * 5.0 + time * 2.0) * 0.1;
                        newPosition.z += cos(position.y * 5.0 + time * 2.0) * 0.1;

                        gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                    }
                `,
                fragmentShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    uniform vec3 uDirLightPos;
                    uniform vec3 uDirLightColor;
                    uniform vec3 uAmbientLightColor;

                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 lightDir = normalize(uDirLightPos - vPosition);
                        float diffuse = max(dot(normal, lightDir), 0.0);

                        // Water color with lighting
                        vec3 waterColor = vec3(0.2, 0.4, 0.8) * (0.5 + 0.5 * diffuse);
                        vec3 color = uAmbientLightColor * 0.2 + waterColor;

                        gl_FragColor = vec4(color, 0.8);
                    }
                `
            }),
            glow: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    uDirLightPos: { value: directionalLight.position },
                    uDirLightColor: { value: directionalLight.color },
                    uAmbientLightColor: { value: ambientLight.color }
                },
                vertexShader: `
                    uniform float time;
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;

                        // Simple glow effect
                        vec3 newPosition = position;
                        newPosition += normal * sin(time * 2.0 + position.x * 5.0) * 0.1;

                        gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                    }
                `,
                fragmentShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;
                    uniform vec3 uDirLightPos;
                    uniform vec3 uDirLightColor;
                    uniform vec3 uAmbientLightColor;

                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 lightDir = normalize(uDirLightPos - vPosition);
                        float diffuse = max(dot(normal, lightDir), 0.0);

                        // Glow color
                        vec3 glowColor = vec3(1.0, 0.8, 0.5) * (0.5 + 0.5 * diffuse);
                        vec3 color = uAmbientLightColor * 0.2 + glowColor;

                        // Add glow effect
                        float glowIntensity = pow(diffuse, 2.0) * 0.5;
                        color += vec3(glowIntensity);

                        gl_FragColor = vec4(color, 1.0);
                    }
                `
            })
        };

        // Apply initial shader effect
        let currentShader = 'none';

        // UI controls
        document.getElementById('lightIntensity').addEventListener('input', (e) => {
            const intensity = parseFloat(e.target.value);
            directionalLight.intensity = intensity;
            document.getElementById('lightIntensityValue').textContent = intensity.toFixed(1);
        });

        document.getElementById('shaderEffect').addEventListener('change', (e) => {
            const effect = e.target.value;
            applyShaderEffect(effect);
        });

        function applyShaderEffect(effect) {
            currentShader = effect;

            // Reset materials
            box.material = materials;
            sphere.material = new THREE.MeshStandardMaterial({
                color: 0xffff00,
                roughness: 0.3,
                metalness: 0.7
            });

            // Apply shader if not 'none'
            if (effect !== 'none') {
                const shaderMaterial = shaderEffects[effect];

                // Apply to all meshes in the scene
                scene.traverse((obj) => {
                    if (obj.isMesh && obj !== ground) {
                        if (Array.isArray(obj.material)) {
                            // For objects with multiple materials
                            obj.material.forEach(material => {
                                material.userData.original = material;
                                material = shaderMaterial.clone();
                            });
                        } else {
                            // For single material objects
                            obj.userData.originalMaterial = obj.material;
                            obj.material = shaderMaterial.clone();
                        }
                    }
                });
            }
        }

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update shader uniforms if active
            if (currentShader !== 'none') {
                const time = performance.now() * 0.001;

                scene.traverse((obj) => {
                    if (obj.isMesh && obj.material && obj.material.uniforms) {
                        if (obj.material.uniforms.time) {
                            obj.material.uniforms.time.value = time;
                        }
                    }
                });
            }

            // Rotate objects for demonstration
            box.rotation.x += 0.01;
            box.rotation.y += 0.01;
            sphere.rotation.x += 0.01;
            sphere.rotation.y += 0.01;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();
    </script>
