// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x111111);

// Camera setup
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 5, 10);

// Renderer setup
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0xff0000, 1, 10);
pointLight.position.set(0, 2, 0);
pointLight.castShadow = true;
scene.add(pointLight);

const spotLight = new THREE.SpotLight(0x00ff00, 1);
spotLight.position.set(3, 5, 3);
spotLight.angle = Math.PI / 6;
spotLight.penumbra = 0.2;
spotLight.decay = 2;
spotLight.distance = 10;
spotLight.castShadow = true;
scene.add(spotLight);

// Post-processing
const composer = new THREE.EffectComposer(renderer);
const renderPass = new THREE.RenderPass(scene, camera);
composer.addPass(renderPass);

// Bloom effect
const bloomPass = new THREE.UnrealBloomPass(
    new THREE.Vector2(window.innerWidth, window.innerHeight),
    1.5, 0.4, 0.85
);
bloomPass.threshold = 0;
bloomPass.strength = 1;
bloomPass.radius = 0;
composer.addPass(bloomPass);

// FXAA pass
const fxaaPass = new THREE.ShaderPass(THREE.FXAAShader);
fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
composer.addPass(fxaaPass);

// Final pass
const copyPass = new THREE.ShaderPass(THREE.CopyShader);
copyPass.renderToScreen = true;
composer.addPass(copyPass);

// Scene objects
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Create a custom shader material for the main object
const customShaderMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        lightPosition: { value: new THREE.Vector3() },
        lightColor: { value: new THREE.Color(0xffffff) },
        pointLightPosition: { value: new THREE.Vector3() },
        pointLightColor: { value: new THREE.Color(0xff0000) },
        spotLightPosition: { value: new THREE.Vector3() },
        spotLightColor: { value: new THREE.Color(0x00ff00) }
    },
    vertexShader: `
        uniform float time;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            vNormal = normalize(normalMatrix * normal);
            vPosition = position;

            // Simple wave effect
            float wave = sin(position.x * 2.0 + time) * 0.1;
            vec3 newPosition = position + vec3(0.0, wave, 0.0);

            gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 lightPosition;
        uniform vec3 lightColor;
        uniform vec3 pointLightPosition;
        uniform vec3 pointLightColor;
        uniform vec3 spotLightPosition;
        uniform vec3 spotLightColor;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            // Directional light
            vec3 lightDir = normalize(lightPosition - vPosition);
            float dirDiffuse = max(dot(vNormal, lightDir), 0.0);
            vec3 dirLight = dirDiffuse * lightColor;

            // Point light
            vec3 pointLightDir = normalize(pointLightPosition - vPosition);
            float pointDist = length(pointLightPosition - vPosition);
            float pointAttenuation = 1.0 / (1.0 + 0.09 * pointDist + 0.032 * pointDist * pointDist);
            float pointDiffuse = max(dot(vNormal, pointLightDir), 0.0) * pointAttenuation;
            vec3 pointLight = pointDiffuse * pointLightColor;

            // Spot light
            vec3 spotLightDir = normalize(spotLightPosition - vPosition);
            float spotDist = length(spotLightPosition - vPosition);
            float spotAttenuation = 1.0 / (1.0 + 0.09 * spotDist + 0.032 * spotDist * spotDist);
            float spotDiffuse = max(dot(vNormal, spotLightDir), 0.0) * spotAttenuation;
            // Add spot light angle attenuation
            vec3 spotDir = normalize(spotLightPosition - vPosition);
            float spotAngle = dot(spotDir, normalize(-spotLightPosition));
            float spotPenumbra = smoothstep(0.9, 0.8, spotAngle);
            spotDiffuse *= spotPenumbra;
            vec3 spotLight = spotDiffuse * spotLightColor;

            // Combine lights
            vec3 color = dirLight + pointLight + spotLight;

            // Base color with lighting
            vec3 baseColor = vec3(0.8, 0.2, 0.5);
            vec3 finalColor = baseColor * color;

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `,
    side: THREE.DoubleSide
});

// Main object
const mainGeometry = new THREE.TorusKnotGeometry(2, 0.5, 100, 16);
const mainObject = new THREE.Mesh(mainGeometry, customShaderMaterial);
mainObject.position.y = 2;
mainObject.castShadow = true;
mainObject.receiveShadow = true;
scene.add(mainObject);

// Helper objects
const directionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(directionalLightHelper);

const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
scene.add(pointLightHelper);

const spotLightHelper = new THREE.SpotLightHelper(spotLight);
scene.add(spotLightHelper);

// UI Controls
const toggleDirectionalBtn = document.getElementById('toggleDirectional');
const togglePointBtn = document.getElementById('togglePoint');
const toggleSpotBtn = document.getElementById('toggleSpot');
const toggleWireframeBtn = document.getElementById('toggleWireframe');
const togglePostProcessingBtn = document.getElementById('togglePostProcessing');

let directionalLightEnabled = true;
let pointLightEnabled = true;
let spotLightEnabled = true;
let wireframeEnabled = false;
let postProcessingEnabled = true;

toggleDirectionalBtn.addEventListener('click', () => {
    directionalLightEnabled = !directionalLightEnabled;
    directionalLight.visible = directionalLightEnabled;
    directionalLightHelper.visible = directionalLightEnabled;
});

togglePointBtn.addEventListener('click', () => {
    pointLightEnabled = !pointLightEnabled;
    pointLight.visible = pointLightEnabled;
    pointLightHelper.visible = pointLightEnabled;
});

toggleSpotBtn.addEventListener('click', () => {
    spotLightEnabled = !spotLightEnabled;
    spotLight.visible = spotLightEnabled;
    spotLightHelper.visible = spotLightEnabled;
});

toggleWireframeBtn.addEventListener('click', () => {
    wireframeEnabled = !wireframeEnabled;
    mainObject.material.wireframe = wireframeEnabled;
});

togglePostProcessingBtn.addEventListener('click', () => {
    postProcessingEnabled = !postProcessingEnabled;
});

// Animation loop
const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();
    const time = clock.getElapsedTime();

    // Update controls
    controls.update();

    // Update shader uniforms
    customShaderMaterial.uniforms.time.value = time;
    customShaderMaterial.uniforms.lightPosition.value.copy(directionalLight.position);
    customShaderMaterial.uniforms.lightColor.value.copy(directionalLight.color);
    customShaderMaterial.uniforms.pointLightPosition.value.copy(pointLight.position);
    customShaderMaterial.uniforms.pointLightColor.value.copy(pointLight.color);
    customShaderMaterial.uniforms.spotLightPosition.value.copy(spotLight.position);
    customShaderMaterial.uniforms.spotLightColor.value.copy(spotLight.color);

    // Animate lights
    pointLight.position.x = Math.sin(time) * 3;
    pointLight.position.z = Math.cos(time) * 3;

    spotLight.position.x = Math.sin(time * 0.5) * 4;
    spotLight.position.z = Math.cos(time * 0.5) * 4;

    // Update helpers
    directionalLightHelper.update();
    pointLightHelper.update();
    spotLightHelper.update();

    // Render
    if (postProcessingEnabled) {
        composer.render(delta);
    } else {
        renderer.render(scene, camera);
    }
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
    composer.setSize(window.innerWidth, window.innerHeight);
    fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
});

// Help display
document.addEventListener('keydown', (e) => {
    if (e.key === 'h' || e.key === 'H') {
        alert(`
            Controls:
            - Left mouse: Rotate camera
            - Right mouse: Pan camera
            - Scroll: Zoom
            - Buttons: Toggle lights and effects
        `);
    }
});

// Start animation
animate();
