pointLight.position.set(3, 3, 3);
pointLight.castShadow = true;
scene.add(pointLight);

const spotLight = new THREE.SpotLight(0x00ff00, 1, 20, Math.PI / 6, 0.5, 1);
spotLight.position.set(-3, 5, -3);
spotLight.castShadow = true;
scene.add(spotLight);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Objects in the scene
const objects = [];

// Create a cube
const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
const cubeMaterial = new THREE.MeshStandardMaterial({
    color: 0x00ff00,
    roughness: 0.5,
    metalness: 0.5
});
const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.position.set(-2, 0.5, 0);
cube.castShadow = true;
cube.receiveShadow = true;
scene.add(cube);
objects.push(cube);

// Create a sphere
const sphereGeometry = new THREE.SphereGeometry(0.7, 32, 32);
const sphereMaterial = new THREE.MeshStandardMaterial({
    color: 0xff0000,
    roughness: 0.3,
    metalness: 0.7
});
const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
sphere.position.set(2, 0.7, 0);
sphere.castShadow = true;
sphere.receiveShadow = true;
scene.add(sphere);
objects.push(sphere);

// Create a torus knot
const torusKnotGeometry = new THREE.TorusKnotGeometry(0.5, 0.2, 100, 16);
const torusKnotMaterial = new THREE.MeshStandardMaterial({
    color: 0x0000ff,
    roughness: 0.2,
    metalness: 0.8
});
const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
torusKnot.position.set(0, 1, 2);
torusKnot.castShadow = true;
torusKnot.receiveShadow = true;
scene.add(torusKnot);
objects.push(torusKnot);

// Shader materials
const shaderMaterials = [];

// Basic shader
const basicShader = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        color: { value: new THREE.Color(0x00ff00) }
    },
    vertexShader: `
        uniform float time;
        varying vec2 vUv;
        void main() {
            vUv = uv;
            vec3 pos = position;
            pos.y += sin(pos.x * 2.0 + time) * 0.1;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 color;
        varying vec2 vUv;
        void main() {
            gl_FragColor = vec4(color, 1.0);
        }
    `
});
shaderMaterials.push(basicShader);

// Toon shader
const toonShader = new THREE.ShaderMaterial({
    uniforms: {
        uDirLightPos: { value: new THREE.Vector3(5, 10, 7) },
        uDirLightColor: { value: new THREE.Color(0xffffff) },
        uAmbientLightColor: { value: new THREE.Color(0x404040) }
    },
    vertexShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;
        void main() {
            vNormal = normalize(normalMatrix * normal);
            vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 uDirLightPos;
        uniform vec3 uDirLightColor;
        uniform vec3 uAmbientLightColor;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
            vec3 normal = normalize(vNormal);
            vec3 lightDir = normalize(uDirLightPos - vPosition);

            // Diffuse
            float NdotL = max(dot(normal, lightDir), 0.0);
            vec3 diffuse = uDirLightColor * NdotL;

            // Toon shading
            vec3 color = vec3(0.0);
            if (NdotL > 0.95) color = vec3(1.0, 0.5, 0.5);
            else if (NdotL > 0.5) color = vec3(0.6, 0.2, 0.2);
            else if (NdotL > 0.25) color = vec3(0.4, 0.1, 0.1);
            else color = vec3(0.2, 0.05, 0.05);

            // Combine with ambient
            vec3 finalColor = uAmbientLightColor + diffuse * color;

            gl_FragColor = vec4(finalColor, 1.0);
        }
    `
});
shaderMaterials.push(toonShader);

// Water shader
const waterShader = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        uColor: { value: new THREE.Color(0x00aaff) },
        uLightPos: { value: new THREE.Vector3(5, 10, 7) }
    },
    vertexShader: `
        uniform float time;
        varying vec2 vUv;
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
            vUv = uv;
            vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
            vNormal = normalize(normalMatrix * normal);

            vec3 pos = position;
            pos.y += sin(pos.x * 5.0 + time * 2.0) * 0.1;
            pos.y += cos(pos.z * 5.0 + time * 2.0) * 0.1;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 uColor;
        uniform vec3 uLightPos;
        varying vec2 vUv;
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
            vec3 normal = normalize(vNormal);
            vec3 lightDir = normalize(uLightPos - vPosition);

            // Diffuse
            float NdotL = max(dot(normal, lightDir), 0.0);
            vec3 diffuse = vec3(0.8) * NdotL;

            // Specular
            vec3 viewDir = normalize(-vPosition);
            vec3 reflectDir = reflect(-lightDir, normal);
            float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
            vec3 specular = vec3(0.5) * spec;

            // Combine
            vec3 finalColor = (uColor * 0.5 + diffuse + specular) * 1.2;

            // Add some noise
            float noise = fract(sin(dot(vUv, vec2(12.9898, 78.233))) * 43758.5453);
            finalColor += noise * 0.1;

            gl_FragColor = vec4(finalColor, 0.8);
        }
    `
});
shaderMaterials.push(waterShader);

// Apply initial shader to objects
let currentShaderIndex = 0;
function applyShader(index) {
    currentShaderIndex = index;
    const shader = shaderMaterials[index];

    // Apply to all objects
    cube.material = shader;
    sphere.material = shader;
    torusKnot.material = shader;

    // Special case for water shader (make it transparent)
    if (index === 2) {
        waterShader.transparent = true;
        waterShader.opacity = 0.8;
    } else {
        waterShader.transparent = false;
    }
}

// Initial shader
applyShader(0);

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    const time = performance.now();
    const delta = (time - prevTime) / 1000;

    // Update shader uniforms
    if (currentShaderIndex === 0) {
        basicShader.uniforms.time.value += delta;
    } else if (currentShaderIndex === 2) {
        waterShader.uniforms.time.value += delta;
    }

    // Object animations
    cube.rotation.x += 0.5 * delta;
    cube.rotation.y += 0.5 * delta;

    sphere.position.y = 0.7 + Math.sin(time * 0.001) * 0.2;

    torusKnot.rotation.x += 0.3 * delta;
    torusKnot.rotation.y += 0.4 * delta;

    // Movement controls
    velocity.x -= velocity.x * 10.0 * delta;
    velocity.z -= velocity.z * 10.0 * delta;
    velocity.y -= velocity.y * 10.0 * delta;

    direction.z = Number(moveForward) - Number(moveBackward);
    direction.x = Number(moveRight) - Number(moveLeft);
    direction.y = Number(moveUp) - Number(moveDown);
    direction.normalize();

    if (moveForward || moveBackward) velocity.z -= direction.z * 400.0 * delta;
    if (moveLeft || moveRight) velocity.x -= direction.x * 400.0 * delta;
    if (moveUp || moveDown) velocity.y -= direction.y * 400.0 * delta;

    controls.moveRight(-velocity.x * delta);
    controls.moveForward(-velocity.z * delta);
    controls.getObject().position.y += velocity.y * delta;

    prevTime = time;

    renderer.render(scene, camera);
}

// Event listeners
document.addEventListener('keydown', (event) => {
    switch (event.code) {
        case 'KeyW': moveForward = true; break;
        case 'KeyA': moveLeft = true; break;
        case 'KeyS': moveBackward = true; break;
        case 'KeyD': moveRight = true; break;
        case 'KeyQ': moveDown = true; break;
        case 'KeyE': moveUp = true; break;
        case 'Digit1': applyShader(0); break;
        case 'Digit2': applyShader(1); break;
        case 'Digit3': applyShader(2); break;
        case 'KeyL':
            directionalLight.visible = !directionalLight.visible;
            pointLight.visible = !pointLight.visible;
            spotLight.visible = !spotLight.visible;
            break;
    }
});

document.addEventListener('keyup', (event) => {
    switch (event.code) {
        case 'KeyW': moveForward = false; break;
        case 'KeyA': moveLeft = false; break;
        case 'KeyS': moveBackward = false; break;
        case 'KeyD': moveRight = false; break;
        case 'KeyQ': moveDown = false; break;
        case 'KeyE': moveUp = false; break;
    }
});

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Click to enable pointer lock
document.addEventListener('click', () => {
    controls.lock();
});

// Start animation
animate();
