pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Spotlight for focused effects
const spotLight = new THREE.SpotLight(0x00ff00, 1, 15, Math.PI / 6, 0.5, 1);
spotLight.position.set(3, 5, 0);
spotLight.castShadow = true;
scene.add(spotLight);

// Helper to visualize lights
const lightHelpers = new THREE.Group();
scene.add(lightHelpers);

// Add light helpers (comment out in production)
const directionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
lightHelpers.add(directionalLightHelper);

const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
lightHelpers.add(pointLightHelper);

const spotLightHelper = new THREE.SpotLightHelper(spotLight);
lightHelpers.add(spotLightHelper);

