const torusGeometry = new THREE.TorusGeometry(0.5, 0.2, 16, 32);
const torusMaterial = new THREE.MeshStandardMaterial({
    color: 0x0000ff,
    roughness: 0.3,
    metalness: 0.7
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(0, 0.5, 2);
torus.castShadow = true;
torus.receiveShadow = true;
objects.add(torus);

// Shader material for special effects
const shaderMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        color: { value: new THREE.Color(0x00ffff) }
    },
    vertexShader: `
        uniform float time;
        varying vec2 vUv;
        void main() {
            vUv = uv;
            vec3 pos = position;
            pos.y += sin(pos.x * 2.0 + time) * 0.1;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 color;
        varying vec2 vUv;
        void main() {
            vec3 col = color * (0.5 + 0.5 * sin(vUv.x * 10.0 + vUv.y * 10.0));
            gl_FragColor = vec4(col, 1.0);
        }
    `,
    wireframe: false
});

// Apply shader to a plane
const shaderPlaneGeometry = new THREE.PlaneGeometry(3, 3, 32, 32);
const shaderPlane = new THREE.Mesh(shaderPlaneGeometry, shaderMaterial);
shaderPlane.position.set(0, 0.1, -2);
shaderPlane.rotation.x = -Math.PI / 2;
objects.add(shaderPlane);

// Animation loop
const clock = new THREE.Clock();
let time = 0;

function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();
    time += delta;

    // Update controls
    controls.update();

    // Animate objects
    box.rotation.x += 0.01;
    box.rotation.y += 0.01;

    sphere.position.y = 0.7 + Math.sin(time * 2) * 0.2;

    torus.rotation.x += 0.005;
    torus.rotation.y += 0.005;

    // Animate lights
    pointLight.position.x = Math.sin(time) * 3;
    pointLight.position.z = Math.cos(time) * 3;

    spotLight.position.x = Math.sin(time * 0.5) * 4;
    spotLight.position.z = Math.cos(time * 0.5) * 4;

    // Update shader uniforms
    shaderMaterial.uniforms.time.value = time;

    // Update light helpers
    spotLightHelper.update();

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
