renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040);
scene.add(ambientLight);

const pointLight = new THREE.PointLight(0xffffff, 1, 100);
pointLight.position.set(5, 5, 5);
pointLight.castShadow = true;
pointLight.shadow.mapSize.width = 1024;
pointLight.shadow.mapSize.height = 1024;
scene.add(pointLight);

// Create a cube with a custom shader material
const geometry = new THREE.BoxGeometry(1, 1, 1);

const shaderMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        lightPos: { value: pointLight.position }
    },
    vertexShader: `
        uniform float time;
        uniform vec3 lightPos;
        varying vec3 vNormal;
        varying vec3 vPosition;
        varying vec3 vLightDir;

        void main() {
            vNormal = normalize(normalMatrix * normal);
            vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
            vLightDir = normalize(lightPos - vPosition);

            // Simple wave effect
            vec3 newPosition = position;
            newPosition.y += sin(position.x * 2.0 + time) * 0.2;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
        }
    `,
    fragmentShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;
        varying vec3 vLightDir;

        void main() {
            // Diffuse lighting
            float diffuse = max(dot(vNormal, vLightDir), 0.0);

            // Specular highlight
            vec3 viewDir = normalize(-vPosition);
            vec3 reflectDir = reflect(-vLightDir, vNormal);
            float specular = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

            // Combine colors
            vec3 color = vec3(0.2, 0.5, 0.8) * diffuse + vec3(1.0) * specular * 0.5;

            gl_FragColor = vec4(color, 1.0);
        }
    `,
    side: THREE.DoubleSide
});

const cube = new THREE.Mesh(geometry, shaderMaterial);
cube.castShadow = true;
cube.receiveShadow = true;
scene.add(cube);

// Ground plane
