        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Objects
        const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
        const sphereGeometry = new THREE.SphereGeometry(0.7, 32, 32);

        // Custom shader material for one object
        const shaderMaterial = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(0xff00ff) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                void main() {
                    vUv = uv;
                    vec3 pos = position;
                    pos.y += sin(pos.x * 5.0 + time) * 0.1;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                varying vec2 vUv;
                void main() {
                    gl_FragColor = vec4(color * (0.5 + 0.5 * sin(vUv.x * 10.0)), 1.0);
                }
            `,
            wireframe: false
        });

        // Create objects
        const objects = [];
        for (let i = 0; i < 5; i++) {
            const material = i === 0 ? shaderMaterial : new THREE.MeshStandardMaterial({
                color: new THREE.Color(Math.random() * 0xffffff),
                roughness: 0.4,
                metalness: 0.5
            });

            const geometry = i % 2 === 0 ? boxGeometry : sphereGeometry;
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(
