// Scene setup
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
scene.add(directionalLight);

// Create a simple scene with a ground and some objects
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x3a5f0b,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Add some objects
const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
const sphereGeometry = new THREE.SphereGeometry(0.5, 32, 32);

// Create a custom shader material for one of the objects
const customMaterial = new THREE.ShaderMaterial({
    uniforms: {
        time: { value: 0 },
        color: { value: new THREE.Color(0xff0000) }
    },
    vertexShader: `
        uniform float time;
        varying vec3 vNormal;
        void main() {
            vNormal = normalize(normalMatrix * normal);
            vec3 newPosition = position + normal * sin(position.y * 10.0 + time) * 0.1;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
        }
    `,
    fragmentShader: `
        uniform vec3 color;
        varying vec3 vNormal;
        void main() {
            float intensity = pow(0.5 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 4.0);
            gl_FragColor = vec4(color * intensity, 1.0);
        }
    `,
    side: THREE.DoubleSide
});

// Add multiple objects with different materials
for (let i = 0; i < 5; i++) {
    const material = i % 2 === 0
        ? new THREE.MeshStandardMaterial({ color: 0x00ff00, roughness: 0.4, metalness: 0.6 })
        : customMaterial;

    const mesh = i % 2 === 0
        ? new THREE.Mesh(boxGeometry, material)
        : new THREE.Mesh(sphereGeometry, material);

    mesh.position.set(
        Math.random() * 10 - 5,
        Math.random() * 2 + 0.5,
        Math.random() * 10 - 5
    );
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    scene.add(mesh);
}

// Camera position
camera.position.set(5, 5, 10);
camera.lookAt(0, 0, 0);

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update custom shader uniform
    customMaterial.uniforms.time.value += 0.01;

    // Rotate directional light for dynamic effect
    directionalLight.position.x = Math.sin(Date.now() * 0.001) * 10;
    directionalLight.position.z = Math.cos(Date.now() * 0.001) * 10;

    controls.update();
    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();
