void CustomPhysicsPlugin::Initialize()
{
    if (m_Initialized) return;

    // Initialize physics world with default settings
    m_PhysicsWorld = new PhysicsWorld();
    m_PhysicsWorld->SetGravity(m_Gravity);

    // Register with engine
    Engine::GetInstance().RegisterPlugin(this);

    m_Initialized = true;
}

void CustomPhysicsPlugin::Shutdown()
{
    if (!m_Initialized) return;

    // Clean up physics world
    if (m_PhysicsWorld) {
        delete m_PhysicsWorld;
        m_PhysicsWorld = nullptr;
    }

    // Unregister from engine
    Engine::GetInstance().UnregisterPlugin(this);

    m_Initialized = false;
}

void CustomPhysicsPlugin::Update(float deltaTime)
{
    if (!m_Initialized || !m_PhysicsWorld) return;

    // Update physics simulation
    m_PhysicsWorld->StepSimulation(deltaTime);
}

