class FCustomPhysicsPlugin : public IModuleInterface
{
public:
    /** IModuleInterface implementation */
    virtual void StartupModule() override;
    virtual void ShutdownModule() override;

    // Custom physics functionality
    void InitializePhysicsWorld();
    void UpdatePhysics(float DeltaTime);
    void AddRigidBody(class UPrimitiveComponent* Component);
    void RemoveRigidBody(class UPrimitiveComponent* Component);
    void ApplyForce(class UPrimitiveComponent* Component, const FVector& Force);
    void ApplyImpulse(class UPrimitiveComponent* Component, const FVector& Impulse);

private:
