    if (Thread)
    {
        Thread->Kill(true);
        delete Thread;
    }
    FPlatformProcess::ReturnSynchEventToPool(StopEvent);
}

uint32 FPhysicsWorkerThread::Run()
{
    while (!StopEvent->Wait(0))
    {
        FPhysicsTask* Task = nullptr;
        if (TaskQueue.Dequeue(Task))
        {
            Task->Execute();
            delete Task;
        }
        else
        {
            FPlatformProcess::Sleep(0.001f); // Small sleep to prevent busy waiting
        }
    }
    return 0;
}

void FPhysicsWorkerThread::Stop()
{
    StopEvent->Trigger();
}

void FPhysicsWorkerThread::AddTask(FPhysicsTask* Task)
{
    TaskQueue.Enqueue(Task);
}
