    Super::BeginPlay();
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (GetOwner() && GetOwner()->GetRootComponent())
    {
        ApplyCustomPhysics(DeltaTime);
    }
}

void UCustomPhysicsComponent::ApplyCustomPhysics_Implementation(float DeltaTime)
{
    ApplyGravity(DeltaTime);
    ApplyDrag(DeltaTime);
    UpdatePosition(DeltaTime);
}

void UCustomPhysicsComponent::SetCustomPhysicsProperties_Implementation(const FVector& Gravity, float NewMass, float NewDragCoefficient)
{
    CustomGravity = Gravity;
    Mass = FMath::Max(NewMass, 0.1f); // Ensure mass is never zero
    DragCoefficient = FMath::Clamp(NewDragCoefficient, 0.0f, 1.0f);
}

void UCustomPhysicsComponent::GetPhysicsState_Implementation(FVector& OutVelocity, FVector& OutAngularVelocity) const
{
    OutVelocity = Velocity;
    OutAngularVelocity = AngularVelocity;
}

void UCustomPhysicsComponent::ApplyGravity(float DeltaTime)
{
    Velocity += CustomGravity * DeltaTime;
}

void UCustomPhysicsComponent::ApplyDrag(float DeltaTime)
{
    float speed = Velocity.Size();
    if (speed > 0.0f)
    {
        FVector dragForce = -Velocity.GetSafeNormal() * DragCoefficient * speed * speed;
        Velocity += dragForce * DeltaTime;
    }
}

void UCustomPhysicsComponent::UpdatePosition(float DeltaTime)
{
    if (UPrimitiveComponent* RootComponent = Cast<UPrimitiveComponent>(GetOwner()->GetRootComponent()))
    {
        // Update position
        FVector NewLocation = RootComponent->GetComponentLocation() + Velocity * DeltaTime;
        RootComponent->SetWorldLocation(NewLocation);

        // Update rotation
        if (AngularVelocity.SizeSquared() > 0.0f)
        {
            FQuat NewRotation = RootComponent->GetComponentQuat() +
                FQuat(AngularVelocity * DeltaTime * 0.5f, 0.0f) * RootComponent->GetComponentQuat();
            RootComponent->SetWorldRotation(NewRotation);
        }
    }
}
