class PhysicsWorld {
public:
    void Step(float deltaTime) {
        // Update all bodies
        for (auto& body : m_bodies) {
            if (body->IsDynamic()) {
                body->Integrate(deltaTime);
            }
        }

        // Broad phase collision detection
        BroadPhase();

        // Narrow phase and collision response
        NarrowPhase();

        // Solve constraints
        SolveConstraints();
    }

    void SetGravity(const Vector3& gravity) {
        m_gravity = gravity;
    }

    RigidBodyHandle CreateRigidBody(const RigidBodyDesc& desc) {
        auto body = std::make_shared<RigidBody>(desc);
        RigidBodyHandle handle = m_nextBodyHandle++;
        m_bodies[handle] = body;
        return handle;
    }

