## Rigid Body Implementation

```cpp
class RigidBody {
public:
    RigidBody(const RigidBodyDesc& desc)
        : m_transform(desc.initialTransform),
          m_velocity(desc.initialVelocity),
          m_angularVelocity(desc.initialAngularVelocity),
          m_mass(desc.mass),
          m_inverseMass(desc.mass > 0.0f ? 1.0f / desc.mass : 0.0f),
          m_shape(desc.shape),
          m_isDynamic(desc.isDynamic) {}

    void Integrate(float deltaTime) {
        if (m_inverseMass == 0.0f) return; // Static body

        // Apply gravity
        m_velocity += m_world->GetGravity() * deltaTime;

        // Update position
        m_transform.position += m_velocity * deltaTime;

        // Update rotation
        if (m_angularVelocity.LengthSquared() > 0.0f) {
            Quaternion rotationDelta(m_angularVelocity, deltaTime);
            m_transform.rotation = rotationDelta * m_transform.rotation;
            m_transform.rotation.Normalize();
        }
    }

    // ... other rigid body methods ...
};
