// Simple AABB collision detector
public class AABBCollisionDetector : ICollisionDetector
{
    public bool CheckCollision(IPhysicsObject a, IPhysicsObject b, out CollisionInfo collisionInfo)
    {
        collisionInfo = new CollisionInfo();

        // Get AABBs (simplified - would need actual bounds in a real implementation)
        var boundsA = GetBounds(a);
        var boundsB = GetBounds(b);

        // Check for overlap
        if (boundsA.Max.X < boundsB.Min.X || boundsA.Min.X > boundsB.Max.X) return false;
        if (boundsA.Max.Y < boundsB.Min.Y || boundsA.Min.Y > boundsB.Max.Y) return false;
        if (boundsA.Max.Z < boundsB.Min.Z || boundsA.Min.Z > boundsB.Max.Z) return false;

        // Calculate collision normal and penetration
        collisionInfo.Normal = CalculateNormal(boundsA, boundsB);
        collisionInfo.Penetration = CalculatePenetration(boundsA, boundsB, collisionInfo.Normal);

        return true;
    }

    private Bounds GetBounds(IPhysicsObject obj)
    {
        // In a real implementation, this would get the actual bounds of the object
        return new Bounds(obj.Position - Vector3.One, obj.Position + Vector3.One);
    }

    private Vector3 CalculateNormal(Bounds a, Bounds b)
    {
        // Simplified normal calculation
        Vector3 centerA = (a.Min + a.Max) * 0.5f;
        Vector3 centerB = (b.Min + b.Max) * 0.5f;
        return Vector3.Normalize(centerB - centerA);
    }

    private float CalculatePenetration(Bounds a, Bounds b, Vector3 normal)
    {
        // Simplified penetration calculation
        if (normal.X != 0)
            return Math.Min(a.Max.X - b.Min.X, b.Max.X - a.Min.X);
        if (normal.Y != 0)
            return Math.Min(a.Max.Y - b.Min.Y, b.Max.Y - a.Min.Y);
        return Math.Min(a.Max.Z - b.Min.Z, b.Max.Z - a.Min.Z);
    }
}

// Physics world class
public class PhysicsWorld
{
    private List<IPhysicsObject> _objects = new List<IPhysicsObject>();
    private ICollisionDetector _collisionDetector;
    private float _gravity = -9.81f;

    public PhysicsWorld(ICollisionDetector collisionDetector)
    {
        _collisionDetector = collisionDetector;
    }

    public void AddObject(IPhysicsObject obj)
    {
        _objects.Add(obj);
    }

    public void RemoveObject(IPhysicsObject obj)
    {
        _objects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Apply gravity
        foreach (var obj in _objects)
        {
            if (!obj.IsStatic)
            {
                obj.ApplyForce(new Vector3(0, _gravity * obj.Mass, 0));
            }
        }

        // Update all objects
        foreach (var obj in _objects)
        {
            obj.Update(deltaTime);
        }

        // Handle collisions
        HandleCollisions();
    }

    private void HandleCollisions()
    {
        for (int i = 0; i < _objects.Count; i++)
        {
            for (int j = i + 1; j < _objects.Count; j++)
            {
                if (_collisionDetector.CheckCollision(_objects[i], _objects[j], out var collisionInfo))
                {
                    ResolveCollision(_objects[i], _objects[j], collisionInfo);
                }
            }
        }
    }

    private void ResolveCollision(IPhysicsObject a, IPhysicsObject b, CollisionInfo collisionInfo)
    {
        // Simple collision response
        if (a.IsStatic && b.IsStatic) return;

        // Calculate relative velocity
        Vector3 relativeVelocity = b.Velocity - a.Velocity;
        float velocityAlongNormal = Vector3.Dot(relativeVelocity, collisionInfo.Normal);

        // Don't resolve if objects are moving away
        if (velocityAlongNormal > 0) return;

        // Calculate impulse scalar
        float e = 0.8f; // Coefficient of restitution
        float j = -(1 + e) * velocityAlongNormal;
        j /= a.IsStatic ? 1.0f / b.Mass : (1.0f / a.Mass + 1.0f / b.Mass);

        // Apply impulse
        Vector3 impulse = collisionInfo.Normal * j;
        if (!a.IsStatic) a.Velocity -= impulse / a.Mass;
        if (!b.IsStatic) b.Velocity += impulse / b.Mass;

        // Positional correction for penetration
        const float penetrationSlack = 0.05f;
        float penetrationCorrection = Math.Max(collisionInfo.Penetration - penetrationSlack, 0.0f) / (a.IsStatic ? 1.0f : (1.0f / a.Mass + 1.0f / b.Mass));

        if (!a.IsStatic) a.Position -= collisionInfo.Normal * penetrationCorrection / a.Mass;
        if (!b.IsStatic) b.Position += collisionInfo.Normal * penetrationCorrection / b.Mass;
    }
}

