        if (m_initialized) return true;

        // Initialize physics systems
        m_initialized = true;
        return true;
    }

    void PhysicsPlugin::Update(float deltaTime) {
        if (!m_initialized) return;

        // Apply physics simulation
        ApplyPhysics(deltaTime);

        // Detect collisions
        DetectCollisions();
    }

