        if (!m_initialized) return;

        // Clean up resources
        m_rigidBodies.clear();
        m_initialized = false;
    }

    RigidBody* PhysicsPlugin::CreateRigidBody(const RigidBodyDesc& desc) {
        auto body = std::make_unique<RigidBody>(desc);
        RigidBody* ptr = body.get();
        m_rigidBodies.push_back(std::move(body));
        return ptr;
    }

    void PhysicsPlugin::RemoveRigidBody(RigidBody* body) {
        auto it = std::find_if(m_rigidBodies.begin(), m_rigidBodies.end(),
            [body](const std::unique_ptr<RigidBody>& rb) { return rb.get() == body; });

        if (it != m_rigidBodies.end()) {
            m_rigidBodies.erase(it);
        }
    }

