        return m_gravity;
    }

    void PhysicsPlugin::DetectCollisions() {
        BroadPhase();
        NarrowPhase();
    }

    void PhysicsPlugin::BroadPhase() {
        // Simple AABB-based broad phase
        for (size_t i = 0; i < m_rigidBodies.size(); i++) {
            for (size_t j = i + 1; j < m_rigidBodies.size(); j++) {
                RigidBody* bodyA = m_rigidBodies[i].get();
                RigidBody* bodyB = m_rigidBodies[j].get();

                AABB aabbA, aabbB;
                bodyA->GetShape()->CalculateAABB(aabbA);
                bodyB->GetShape()->CalculateAABB(aabbB);

                if (aabbA.Intersects(aabbB)) {
                    // Potential collision - add to narrow phase
                }
            }
        }
    }

    void PhysicsPlugin::NarrowPhase() {
        // Perform precise collision detection
    }

    void PhysicsPlugin::ApplyPhysics(float deltaTime) {
        // Apply gravity and update positions
        for (auto& body : m_rigidBodies) {
            body->ApplyForce(m_gravity * body->GetMass(), Vector3::Zero);
            body->Update(deltaTime);
        }
    }
