    public Vector3 Velocity { get; set; }
    public Vector3 AngularVelocity { get; set; }
    public float Mass { get; set; }
    public float InverseMass => Mass > 0 ? 1.0f / Mass : 0.0f;
    public Matrix3x3 InertiaTensor { get; set; }
    public Matrix3x3 InverseInertiaTensor { get; set; }

    private Vector3 forceAccumulator;
    private Vector3 torqueAccumulator;

    public RigidBody(float mass, Vector3 position, Quaternion rotation)
    {
        Mass = mass;
        Position = position;
        Rotation = rotation;
        Velocity = Vector3.Zero;
        AngularVelocity = Vector3.Zero;

        // Initialize inertia tensor (simplified for sphere)
        float radius = 1.0f; // This would be object-specific
        float sphereInertia = (2.0f / 5.0f) * mass * radius * radius;
        InertiaTensor = Matrix3x3.Identity * sphereInertia;
        InverseInertiaTensor = Matrix3x3.Identity * (1.0f / sphereInertia);
    }

    public void ApplyForce(Vector3 force)
    {
        forceAccumulator += force;
    }

    public void ApplyTorque(Vector3 torque)
    {
        torqueAccumulator += torque;
    }

    public void Update(float deltaTime)
    {
        // Apply forces
        if (InverseMass > 0)
        {
            Velocity += forceAccumulator * InverseMass * deltaTime;
            Position += Velocity * deltaTime;

            // Apply torque
            Vector3 angularAcceleration = InverseInertiaTensor * torqueAccumulator;
            AngularVelocity += angularAcceleration * deltaTime;

            // Update rotation
            Quaternion rotationDelta = new Quaternion(AngularVelocity * deltaTime, 1.0f);
            Rotation = Quaternion.Normalize(Rotation + rotationDelta * Rotation * 0.5f);
        }

        // Clear accumulators
        forceAccumulator = Vector3.Zero;
        torqueAccumulator = Vector3.Zero;
    }
}

// Physics world class
public class PhysicsWorld
{
    private List<IPhysicsObject> physicsObjects = new List<IPhysicsObject>();
    private List<CollisionPair> collisionPairs = new List<CollisionPair>();
    private float gravity = -9.81f;

    public void AddObject(IPhysicsObject obj)
    {
        physicsObjects.Add(obj);
    }

    public void RemoveObject(IPhysicsObject obj)
    {
        physicsObjects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Apply gravity to all objects
        foreach (var obj in physicsObjects)
        {
            obj.ApplyForce(new Vector3(0, gravity * obj.Mass, 0));
        }

        // Update all objects
        foreach (var obj in physicsObjects)
        {
            obj.Update(deltaTime);
        }

        // Broad phase collision detection (simplified)
        collisionPairs.Clear();
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < physicsObjects.Count; j++)
            {
                if (CheckCollision(physicsObjects[i], physicsObjects[j]))
                {
                    collisionPairs.Add(new CollisionPair(physicsObjects[i], physicsObjects[j]));
                }
            }
        }

        // Narrow phase collision resolution
        foreach (var pair in collisionPairs)
        {
            ResolveCollision(pair.ObjectA, pair.ObjectB);
        }
    }

    private bool CheckCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simplified sphere-sphere collision check
        float distance = Vector3.Distance(a.Position, b.Position);
        float radiusA = 1.0f; // Would be object-specific
        float radiusB = 1.0f; // Would be object-specific
        return distance < (radiusA + radiusB);
    }

    private void ResolveCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simple collision response
        Vector3 normal = Vector3.Normalize(b.Position - a.Position);
        Vector3 relativeVelocity = b.Velocity - a.Velocity;

        // Calculate impulse scalar
        float e = 0.8f; // Coefficient of restitution
        float j = -(1 + e) * Vector3.Dot(relativeVelocity, normal);
        j /= a.InverseMass + b.InverseMass;

        // Apply impulse
        Vector3 impulse = normal * j;
        a.Velocity -= impulse * a.InverseMass;
        b.Velocity += impulse * b.InverseMass;

        // Optional: Separate objects slightly to prevent sticking
        float penetration = (1.0f + 1.0f) - Vector3.Distance(a.Position, b.Position);
        Vector3 correction = normal * (penetration * 0.5f);
        a.Position -= correction * a.InverseMass / (a.InverseMass + b.InverseMass);
        b.Position += correction * b.InverseMass / (a.InverseMass + b.InverseMass);
    }

    private class CollisionPair
    {
        public IPhysicsObject ObjectA { get; }
        public IPhysicsObject ObjectB { get; }

        public CollisionPair(IPhysicsObject a, IPhysicsObject b)
        {
            ObjectA = a;
            ObjectB = b;
        }
    }
}

