// Main physics system class
public class CustomPhysicsSystem
{
    private List<IPhysicsObject> physicsObjects = new List<IPhysicsObject>();
    private float timeStep = 1.0f / 60.0f; // Default to 60 FPS
    private Vector3 gravity = new Vector3(0, -9.81f, 0);

    public void AddPhysicsObject(IPhysicsObject obj)
    {
        physicsObjects.Add(obj);
    }

    public void RemovePhysicsObject(IPhysicsObject obj)
    {
        physicsObjects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Fixed time step integration
        while (deltaTime >= timeStep)
        {
            Integrate(timeStep);
            deltaTime -= timeStep;
        }

        if (deltaTime > 0)
        {
            Integrate(deltaTime);
        }
    }

    private void Integrate(float dt)
    {
        // Apply gravity and update positions
        foreach (var obj in physicsObjects)
        {
            if (!obj.IsStatic)
            {
                obj.Acceleration = gravity / obj.Mass;
                obj.Velocity += obj.Acceleration * dt;
                obj.Position += obj.Velocity * dt;
            }
        }

        // Handle collisions
        CheckCollisions();
    }

    private void CheckCollisions()
    {
        // Simple broad-phase collision detection
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < physicsObjects.Count; j++)
            {
                var objA = physicsObjects[i];
                var objB = physicsObjects[j];

                if (CheckCollision(objA, objB))
                {
                    ResolveCollision(objA, objB);
                }
            }
        }
    }

    private bool CheckCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simplified AABB collision detection
        // In a real implementation, this would be more sophisticated
        if (a is ICollider && b is ICollider)
        {
            var colliderA = (ICollider)a;
            var colliderB = (ICollider)b;

            return colliderA.Bounds.Intersects(colliderB.Bounds);
        }
        return false;
    }

    private void ResolveCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simple elastic collision response
        Vector3 normal = (b.Position - a.Position).Normalized();
        float relativeVelocity = Vector3.Dot(b.Velocity - a.Velocity, normal);

        if (relativeVelocity > 0) return; // Objects moving away

        float e = 0.8f; // Coefficient of restitution
        float j = -(1 + e) * relativeVelocity;
        j /= (1 / a.Mass + 1 / b.Mass);

        Vector3 impulse = j * normal;

        if (!a.IsStatic)
        {
            a.Velocity -= impulse / a.Mass;
        }

        if (!b.IsStatic)
        {
            b.Velocity += impulse / b.Mass;
        }
    }
}

