}

// Main physics world class
public class PhysicsWorld
{
    private List<IPhysicsObject> physicsObjects = new List<IPhysicsObject>();
    private List<ICollisionShape> collisionShapes = new List<ICollisionShape>();
    private float fixedTimeStep = 1.0f / 60.0f;
    private float accumulator = 0.0f;

    public Vector3 Gravity { get; set; } = new Vector3(0, -9.81f, 0);

    public void AddPhysicsObject(IPhysicsObject obj, ICollisionShape shape)
    {
        physicsObjects.Add(obj);
        collisionShapes.Add(shape);
    }

    public void RemovePhysicsObject(IPhysicsObject obj)
    {
        int index = physicsObjects.IndexOf(obj);
        if (index >= 0)
        {
            physicsObjects.RemoveAt(index);
            collisionShapes.RemoveAt(index);
        }
    }

    public void Update(float deltaTime)
    {
        accumulator += deltaTime;

        while (accumulator >= fixedTimeStep)
        {
            Step(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }
    }

    private void Step(float deltaTime)
    {
        // Apply gravity to all dynamic objects
        foreach (var obj in physicsObjects)
        {
            if (!obj.IsStatic)
            {
                obj.ApplyForce(Gravity * obj.Mass, obj.Position);
            }
        }

        // Broad phase collision detection (simple AABB for this example)
        List<Tuple<int, int>> potentialCollisions = new List<Tuple<int, int>>();
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < physicsObjects.Count; j++)
            {
                if (AABBIntersect(collisionShapes[i], collisionShapes[j]))
                {
                    potentialCollisions.Add(new Tuple<int, int>(i, j));
                }
            }
        }

        // Narrow phase collision detection and response
        foreach (var pair in potentialCollisions)
        {
            IPhysicsObject objA = physicsObjects[pair.Item1];
            IPhysicsObject objB = physicsObjects[pair.Item2];

            CollisionInfo collision = NarrowPhaseCollision(
                collisionShapes[pair.Item1],
                collisionShapes[pair.Item2],
                objA.Position,
                objB.Position,
                objA.Rotation,
                objB.Rotation);

            if (collision.IsColliding)
            {
                ResolveCollision(objA, objB, collision);
            }
        }

        // Update positions based on velocities
        foreach (var obj in physicsObjects)
        {
            if (!obj.IsStatic)
            {
                obj.Position += obj.Velocity * deltaTime;
                obj.Rotation *= Quaternion.FromAxisAngle(obj.AngularVelocity, deltaTime);
            }
        }
    }

    // Simple AABB intersection test
    private bool AABBIntersect(ICollisionShape shapeA, ICollisionShape shapeB)
    {
        // Implementation would depend on the actual shape types
        // This is a simplified version
        return shapeA.Bounds.Intersects(shapeB.Bounds);
    }

    // Narrow phase collision detection
    private CollisionInfo NarrowPhaseCollision(
        ICollisionShape shapeA, ICollisionShape shapeB,
        Vector3 posA, Vector3 posB,
        Quaternion rotA, Quaternion rotB)
    {
        // Implementation would depend on the actual shape types
        // This is a simplified version
        return shapeA.Intersect(shapeB, posA, posB, rotA, rotB);
    }

    // Collision response
    private void ResolveCollision(IPhysicsObject objA, IPhysicsObject objB, CollisionInfo collision)
    {
        // Calculate relative velocity
        Vector3 relativeVelocity = objB.Velocity - objA.Velocity;

        // Calculate relative velocity at contact point
        Vector3 contactPointVelocity = relativeVelocity +
            Vector3.Cross(objA.AngularVelocity, collision.ContactPoint - objA.Position) -
            Vector3.Cross(objB.AngularVelocity, collision.ContactPoint - objB.Position);

        // Calculate impulse scalar
        float impulseScalar = -(1 + 0.5f) * Vector3.Dot(contactPointVelocity, collision.Normal) /
            (objA.Mass + objB.Mass);

        // Apply impulse
        Vector3 impulse = impulseScalar * collision.Normal;
        objA.ApplyImpulse(-impulse, collision.ContactPoint);
        objB.ApplyImpulse(impulse, collision.ContactPoint);
    }
}
