```csharp
public class RigidBody : IPhysicsObject
{
    public Vector3 Position { get; set; }
    public Quaternion Rotation { get; set; } = Quaternion.Identity;
    public Vector3 Velocity { get; set; }
    public Vector3 AngularVelocity { get; set; }
    public float Mass { get; set; } = 1.0f;
    public bool IsStatic { get; set; } = false;

    private Vector3 forceAccumulator = Vector3.Zero;
    private Vector3 torqueAccumulator = Vector3.Zero;

    public void ApplyForce(Vector3 force, Vector3 point)
    {
        if (IsStatic) return;

        forceAccumulator += force;
        torqueAccumulator += Vector3.Cross(point - Position, force);
    }

    public void ApplyImpulse(Vector3 impulse, Vector3 point)
    {
        if (IsStatic) return;

        Velocity += impulse / Mass;
        AngularVelocity += Vector3.Cross(point - Position, impulse) / Mass;
    }

    public void Integrate(float deltaTime)
    {
        if (IsStatic) return;

        // Update linear velocity
        Velocity += forceAccumulator / Mass * deltaTime;

        // Update angular velocity
        AngularVelocity += torqueAccumulator / Mass * deltaTime;

        // Clear accumulators
        forceAccumulator = Vector3.Zero;
        torqueAccumulator = Vector3.Zero;
    }
}
