public class SphereShape : ICollisionShape
{
    public float Radius { get; set; }
    public Vector3 Position { get; set; }

    public BoundingBox Bounds
    {
        get
        {
            Vector3 min = Position - new Vector3(Radius);
            Vector3 max = Position + new Vector3(Radius);
            return new BoundingBox(min, max);
        }
    }

    public CollisionInfo Intersect(ICollisionShape other, Vector3 posA, Vector3 posB, Quaternion rotA, Quaternion rotB)
    {
        CollisionInfo result = new CollisionInfo();

        if (other is SphereShape otherSphere)
        {
            Vector3 direction = otherSphere.Position - Position;
            float distance = direction.Length();

            if (distance < Radius + otherSphere.Radius)
            {
                result.IsColliding = true;
                result.Normal = direction.Normalized();
                result.ContactPoint = Position + result.Normal * Radius;
                result.PenetrationDepth = (Radius + otherSphere.Radius) - distance;
            }
        }
        // Add other shape type checks here

        return result;
    }
}
