## Implementation

```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"
#include <algorithm>
#include <cmath>

namespace GameEngine {

    void PhysicsPlugin::Initialize(int maxBodies) {
        bodies_.reserve(maxBodies);
    }

    void PhysicsPlugin::Update(float deltaTime) {
        Integrate(deltaTime);
        DetectCollisions();
        ResolveCollisions();
    }

    int PhysicsPlugin::AddRigidBody(const RigidBody& body) {
        bodies_.push_back(std::make_unique<RigidBody>(body));
        return static_cast<int>(bodies_.size()) - 1;
    }

    void PhysicsPlugin::RemoveRigidBody(int bodyId) {
        if (bodyId >= 0 && bodyId < bodies_.size()) {
            bodies_[bodyId] = nullptr; // Mark for removal
        }
    }

    void PhysicsPlugin::ApplyForce(int bodyId, const Vector3& force) {
        if (bodyId >= 0 && bodyId < bodies_.size() && bodies_[bodyId]) {
            auto& body = *bodies_[bodyId];
            if (!body.isStatic) {
                body.acceleration.x += force.x / body.mass;
                body.acceleration.y += force.y / body.mass;
                body.acceleration.z += force.z / body.mass;
            }
        }
    }

    void PhysicsPlugin::ApplyImpulse(int bodyId, const Vector3& impulse) {
        if (bodyId >= 0 && bodyId < bodies_.size() && bodies_[bodyId]) {
            auto& body = *bodies_[bodyId];
            if (!body.isStatic) {
                body.velocity.x += impulse.x / body.mass;
                body.velocity.y += impulse.y / body.mass;
                body.velocity.z += impulse.z / body.mass;
            }
        }
    }

    RigidBody PhysicsPlugin::GetRigidBody(int bodyId) const {
        if (bodyId >= 0 && bodyId < bodies_.size() && bodies_[bodyId]) {
            return *bodies_[bodyId];
        }
        return RigidBody{}; // Return default if invalid
    }

    void PhysicsPlugin::RegisterCollisionCallback(CollisionCallback callback) {
        collisionCallbacks_.push_back(callback);
    }

    void PhysicsPlugin::Shutdown() {
        bodies_.clear();
        collisionCallbacks_.clear();
    }

    void PhysicsPlugin::Integrate(float deltaTime) {
        for (auto& bodyPtr : bodies_) {
            if (!bodyPtr) continue;

            auto& body = *bodyPtr;
            if (body.isStatic) continue;

            // Semi-implicit Euler integration
            body.velocity.x += body.acceleration.x * deltaTime;
            body.velocity.y += body.acceleration.y * deltaTime;
            body.velocity.z += body.acceleration.z * deltaTime;

            body.position.x += body.velocity.x * deltaTime;
            body.position.y += body.velocity.y * deltaTime;
            body.position.z += body.velocity.z * deltaTime;

            // Reset acceleration for next frame
            body.acceleration = {0, 0, 0};
        }
    }

    void PhysicsPlugin::DetectCollisions() {
        // Simple sphere-sphere collision detection
        for (size_t i = 0; i < bodies_.size(); ++i) {
            if (!bodies_[i]) continue;

            for (size_t j = i + 1; j < bodies_.size(); ++j) {
                if (!bodies_[j]) continue;

                const auto& bodyA = *bodies_[i];
                const auto& bodyB = *bodies_[j];

                // Skip if both are static
                if (bodyA.isStatic && bodyB.isStatic) continue;

                // Calculate distance between centers
                float dx = bodyB.position.x - bodyA.position.x;
                float dy = bodyB.position.y - bodyA.position.y;
                float dz = bodyB.position.z - bodyA.position.z;
                float distance = std::sqrt(dx*dx + dy*dy + dz*dz);

                // Check for collision
                if (distance < (bodyA.radius + bodyB.radius)) {
                    // Notify all collision callbacks
                    for (const auto& callback : collisionCallbacks_) {
                        callback(static_cast<int>(i), static_cast<int>(j));
                    }
                }
            }
        }
    }

    void PhysicsPlugin::ResolveCollisions() {
        // Simple collision response (elastic collisions)
        for (size_t i = 0; i < bodies_.size(); ++i) {
            if (!bodies_[i]) continue;

            for (size_t j = i + 1; j < bodies_.size(); ++j) {
                if (!bodies_[j]) continue;

                auto& bodyA = *bodies_[i];
                auto& bodyB = *bodies_[j];

                // Skip if both are static
                if (bodyA.isStatic && bodyB.isStatic) continue;

                // Calculate distance between centers
                float dx = bodyB.position.x - bodyA.position.x;
                float dy = bodyB.position.y - bodyA.position.y;
                float dz = bodyB.position.z - bodyA.position.z;
                float distance = std::sqrt(dx*dx + dy*dy + dz*dz);

                // Check for collision
                if (distance < (bodyA.radius + bodyB.radius)) {
                    // Calculate normal vector
                    Vector3 normal = {dx/distance, dy/distance, dz/distance};

                    // Calculate relative velocity
                    Vector3 relativeVelocity = {
                        bodyB.velocity.x - bodyA.velocity.x,
                        bodyB.velocity.y - bodyA.velocity.y,
                        bodyB.velocity.z - bodyA.velocity.z
                    };

                    // Calculate relative velocity in terms of the normal direction
                    float velocityAlongNormal = relativeVelocity.x * normal.x +
                                              relativeVelocity.y * normal.y +
                                              relativeVelocity.z * normal.z;

                    // Do not resolve if velocities are separating
                    if (velocityAlongNormal > 0) continue;

                    // Calculate restitution (bounciness)
                    float restitution = 0.8f; // Default restitution

                    // Calculate impulse scalar
                    float j = -(1 + restitution) * velocityAlongNormal;
                    j /= (1/bodyA.mass) + (1/bodyB.mass);

                    // Apply impulse
                    Vector3 impulse = {
                        normal.x * j,
                        normal.y * j,
                        normal.z * j
                    };

                    if (!bodyA.isStatic) {
                        bodyA.velocity.x -= impulse.x / bodyA.mass;
                        bodyA.velocity.y -= impulse.y / bodyA.mass;
                        bodyA.velocity.z -= impulse.z / bodyA.mass;
                    }

                    if (!bodyB.isStatic) {
                        bodyB.velocity.x += impulse.x / bodyB.mass;
                        bodyB.velocity.y += impulse.y / bodyB.mass;
                        bodyB.velocity.z += impulse.z / bodyB.mass;
                    }

                    // Position correction to prevent sinking
                    const float percent = 0.2f; // usually 20% to 80%
                    const float slop = 0.01f; // usually 0.01 to 0.1
                    Vector3 correction = {
                        normal.x * percent * (distance - bodyA.radius - bodyB.radius + slop),
                        normal.y * percent * (distance - bodyA.radius - bodyB.radius + slop),
                        normal.z * percent * (distance - bodyA.radius - bodyB.radius + slop)
                    };

                    if (!bodyA.isStatic) {
                        bodyA.position.x -= correction.x * (bodyA.isStatic ? 0 : 1);
                        bodyA.position.y -= correction.y * (bodyA.isStatic ? 0 : 1);
                        bodyA.position.z -= correction.z * (bodyA.isStatic ? 0 : 1);
                    }

                    if (!bodyB.isStatic) {
                        bodyB.position.x += correction.x * (bodyB.isStatic ? 0 : 1);
                        bodyB.position.y += correction.y * (bodyB.isStatic ? 0 : 1);
                        bodyB.position.z += correction.z * (bodyB.isStatic ? 0 : 1);
                    }
                }
            }
        }
    }
}
