    auto it = std::remove_if(s_physicsWorlds.begin(), s_physicsWorlds.end(),
        [world](const std::unique_ptr<PhysicsWorld>& w) { return w.get() == world; });

    if (it != s_physicsWorlds.end()) {
        s_physicsWorlds.erase(it);
    }
}

void CorePhysicsPlugin::OnUpdate(float deltaTime) {
    for (auto& world : s_physicsWorlds) {
        world->Update(deltaTime);
    }
}

void CorePhysicsPlugin::OnRenderDebug() {
    for (auto& world : s_physicsWorlds) {
