// PhysicsPluginImpl.cpp
#include "PhysicsPluginImpl.h"
#include <algorithm>

namespace GameEngine {
    PhysicsPluginImpl::PhysicsPluginImpl() = default;
    PhysicsPluginImpl::~PhysicsPluginImpl() = default;

    bool PhysicsPluginImpl::Initialize() {
        // Initialize any required resources
        return true;
    }

    void PhysicsPluginImpl::Shutdown() {
        m_bodies.clear();
    }

    void PhysicsPluginImpl::Update(float deltaTime) {
        // Fixed time step simulation
        m_timeAccumulator += deltaTime;

        while (m_timeAccumulator >= m_fixedTimeStep) {
            IntegrateBodies(m_fixedTimeStep);
            ApplyForces(m_fixedTimeStep);
            SolveCollisions();
            m_timeAccumulator -= m_fixedTimeStep;
        }
    }

    uint32_t PhysicsPluginImpl::CreateRigidBody(const RigidBodyDesc& desc) {
        uint32_t id = m_nextId++;
        RigidBody body;
        body.id = id;
        body.transform.position = desc.position;
        body.transform.rotation = desc.rotation;
        body.linearVelocity = desc.linearVelocity;
        body.angularVelocity = desc.angularVelocity;
        body.mass = desc.mass;
        body.restitution = desc.restitution;
        body.friction = desc.friction;
        body.isStatic = desc.isStatic;
        body.shape = std::unique_ptr<CollisionShape>(desc.shape->Clone());

        m_bodies[id] = std::move(body);
        return id;
    }

    void PhysicsPluginImpl::DestroyRigidBody(uint32_t bodyId) {
        m_bodies.erase(bodyId);
    }

    void PhysicsPluginImpl::ApplyForce(uint32_t bodyId, const Vector3& force) {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end() && !it->second.isStatic) {
            it->second.forceAccumulator += force;
        }
    }

    void PhysicsPluginImpl::ApplyImpulse(uint32_t bodyId, const Vector3& impulse) {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end() && !it->second.isStatic) {
            it->second.linearVelocity += impulse / it->second.mass;
        }
    }

    void PhysicsPluginImpl::SetTransform(uint32_t bodyId, const Transform& transform) {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end()) {
            it->second.transform = transform;
        }
    }

    Transform PhysicsPluginImpl::GetTransform(uint32_t bodyId) const {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end()) {
            return it->second.transform;
        }
        return Transform{ Vector3::Zero(), Quaternion::Identity() };
    }

    bool PhysicsPluginImpl::CheckCollision(uint32_t bodyId1, uint32_t bodyId2) const {
        auto it1 = m_bodies.find(bodyId1);
        auto it2 = m_bodies.find(bodyId2);

        if (it1 == m_bodies.end() || it2 == m_bodies.end()) {
            return false;
        }

        return CheckCollisionInternal(it1->second, it2->second);
    }

    void PhysicsPluginImpl::IntegrateBodies(float deltaTime) {
        for (auto& pair : m_bodies) {
            RigidBody& body = pair.second;

            if (body.isStatic) continue;

            // Linear motion
            body.transform.position += body.linearVelocity * deltaTime;

            // Angular motion
            Quaternion angularRotation = Quaternion::FromAxisAngle(
                body.angularVelocity.Normalized(),
                body.angularVelocity.Length() * deltaTime
            );
            body.transform.rotation = (body.transform.rotation * angularRotation).Normalized();
        }
    }

    void PhysicsPluginImpl::ApplyForces(float deltaTime) {
        for (auto& pair : m_bodies) {
            RigidBody& body = pair.second;

            if (body.isStatic) continue;

            // Apply gravity
            if (body.mass > 0.0f) {
                Vector3 acceleration = m_gravity + (body.forceAccumulator / body.mass);
                body.linearVelocity += acceleration * deltaTime;
            }

            // Clear accumulators
            body.forceAccumulator = Vector3::Zero();
            body.torqueAccumulator = Vector3::Zero();
        }
    }

    void PhysicsPluginImpl::SolveCollisions() {
        // Simple collision detection and response
        for (auto it1 = m_bodies.begin(); it1 != m_bodies.end(); ++it1) {
            for (auto it2 = std::next(it1); it2 != m_bodies.end(); ++it2) {
                if (CheckCollisionInternal(it1->second, it2->second)) {
                    // Simple response - just separate the bodies
                    // In a real implementation, you'd calculate proper collision response
                    Vector3 direction = (it1->second.transform.position - it2->second.transform.position).Normalized();
                    float penetration = 0.1f; // Simple penetration value

                    if (!it1->second.isStatic) {
                        it1->second.transform.position += direction * penetration * 0.5f;
                    }
                    if (!it2->second.isStatic) {
                        it2->second.transform.position -= direction * penetration * 0.5f;
                    }
                }
            }
        }
    }

    bool PhysicsPluginImpl::CheckCollisionInternal(const RigidBody& body1, const RigidBody& body2) const {
        // Simple AABB collision check for demonstration
        // In a real implementation, you'd use proper collision detection

        // Get AABB for each body
        AABB aabb1 = body1.shape->GetAABB(body1.transform);
        AABB aabb2 = body2.shape->GetAABB(body2.transform);

        return aabb1.Intersects(aabb2);
    }
