void PhysicsPlugin::StepSimulation(float deltaTime) {
    // Update physics state
    IntegrateBodies(deltaTime);
    DetectCollisions();
    ResolveCollisions();
}

void PhysicsPlugin::SetGravity(const Vector3& gravity) {
    m_gravity = gravity;
}

RigidBody* PhysicsPlugin::CreateRigidBody(const Vector3& position, float mass, bool isStatic) {
    auto body = std::make_unique<RigidBody>();
    body->position = position;
    body->velocity = {0.0f, 0.0f, 0.0f};
    body->acceleration = {0.0f, 0.0f, 0.0f};
    body->mass = mass;
    body->inverseMass = isStatic ? 0.0f : 1.0f / mass;
    body->isStatic = isStatic;

    RigidBody* ptr = body.get();
    m_bodies.push_back(std::move(body));
    return ptr;
}

void PhysicsPlugin::DestroyRigidBody(RigidBody* body) {
    auto it = std::find_if(m_bodies.begin(), m_bodies.end(),
        [body](const std::unique_ptr<RigidBody>& b) { return b.get() == body; });

    if (it != m_bodies.end()) {
        m_bodies.erase(it);
    }
}

void PhysicsPlugin::ApplyForce(RigidBody* body, const Vector3& force) {
    if (body->isStatic) return;
    body->acceleration.x += force.x * body->inverseMass;
    body->acceleration.y += force.y * body->inverseMass;
    body->acceleration.z += force.z * body->inverseMass;
}

void PhysicsPlugin::ApplyImpulse(RigidBody* body, const Vector3& impulse) {
    if (body->isStatic) return;
    body->velocity.x += impulse.x * body->inverseMass;
    body->velocity.y += impulse.y * body->inverseMass;
    body->velocity.z += impulse.z * body->inverseMass;
}

void PhysicsPlugin::SetCollisionCallback(CollisionCallback callback) {
    m_collisionCallback = callback;
}

// Basic implementation of integration (Euler integration)
void PhysicsPlugin::IntegrateBodies(float deltaTime) {
    for (auto& body : m_bodies) {
        if (body->isStatic) continue;

        // Apply gravity
        body->acceleration.x += m_gravity.x;
        body->acceleration.y += m_gravity.y;
        body->acceleration.z += m_gravity.z;

        // Update velocity
        body->velocity.x += body->acceleration.x * deltaTime;
        body->velocity.y += body->acceleration.y * deltaTime;
        body->velocity.z += body->acceleration.z * deltaTime;

        // Update position
        body->position.x += body->velocity.x * deltaTime;
        body->position.y += body->velocity.y * deltaTime;
        body->position.z += body->velocity.z * deltaTime;

        // Reset acceleration
        body->acceleration = {0.0f, 0.0f, 0.0f};
    }
}

// Simple AABB collision detection
void PhysicsPlugin::DetectCollisions() {
    // This is a naive O(n^2) implementation - would need optimization for real use
    for (size_t i = 0; i < m_bodies.size(); ++i) {
        for (size_t j = i + 1; j < m_bodies.size(); ++j) {
            RigidBody* bodyA = m_bodies[i].get();
            RigidBody* bodyB = m_bodies[j].get();

            // Simple AABB collision (would need proper collision shapes in real implementation)
            float minA[3] = {bodyA->position.x - 0.5f, bodyA->position.y - 0.5f, bodyA->position.z - 0.5f};
            float maxA[3] = {bodyA->position.x + 0.5f, bodyA->position.y + 0.5f, bodyA->position.z + 0.5f};
            float minB[3] = {bodyB->position.x - 0.5f, bodyB->position.y - 0.5f, bodyB->position.z - 0.5f};
            float maxB[3] = {bodyB->position.x + 0.5f, bodyB->position.y + 0.5f, bodyB->position.z + 0.5f};

            bool overlap = true;
            for (int k = 0; k < 3; ++k) {
                if (maxA[k] < minB[k] || minA[k] > maxB[k]) {
                    overlap = false;
                    break;
                }
            }

            if (overlap) {
                CollisionInfo info;
                info.bodyA = bodyA;
                info.bodyB = bodyB;
                // Simplified collision response - would need proper normal calculation
                info.normal = {bodyB->position.x - bodyA->position.x,
                              bodyB->position.y - bodyA->position.y,
                              bodyB->position.z - bodyA->position.z};

                // Normalize the normal
                float length = std::sqrt(info.normal.x*info.normal.x +
                                        info.normal.y*info.normal.y +
                                        info.normal.z*info.normal.z);
                if (length > 0.0f) {
                    info.normal.x /= length;
                    info.normal.y /= length;
                    info.normal.z /= length;
                }

                info.contactPoint = {
                    (bodyA->position.x + bodyB->position.x) * 0.5f,
                    (bodyA->position.y + bodyB->position.y) * 0.5f,
                    (bodyA->position.z + bodyB->position.z) * 0.5f
                };

                // Simplified penetration - would need proper intersection calculation
                info.penetration = 0.5f;

                if (m_collisionCallback) {
                    m_collisionCallback(info);
                }
            }
        }
    }
