```csharp
// Rigid body class
public class RigidBody
{
    public Collider Collider { get; private set; }
    public float Mass { get; private set; }
    public float InverseMass { get; private set; }
    public Vector3 Position { get; set; }
    public Quaternion Rotation { get; set; }
    public Vector3 LinearVelocity { get; set; }
    public Vector3 AngularVelocity { get; set; }
    public Vector3 ForceAccumulator { get; private set; }
    public Vector3 TorqueAccumulator { get; private set; }

    public RigidBody(Collider collider, float mass)
    {
        Collider = collider;
        Mass = mass;
        InverseMass = mass > 0 ? 1.0f / mass : 0.0f;
        Position = Vector3.Zero;
        Rotation = Quaternion.Identity;
    }

    public void Update(float deltaTime)
    {
        // Apply forces
        if (InverseMass > 0)
        {
            LinearVelocity += ForceAccumulator * InverseMass * deltaTime;
            AngularVelocity += TorqueAccumulator * deltaTime;
        }

        // Update position
        Position += LinearVelocity * deltaTime;

        // Update rotation
        Quaternion angularRotation = new Quaternion(AngularVelocity, deltaTime);
        Rotation = Quaternion.Multiply(Rotation, angularRotation);

        // Clear accumulators
        ClearAccumulators();
    }

    public void AddForce(Vector3 force)
    {
        ForceAccumulator += force;
    }

    public void AddTorque(Vector3 torque)
    {
        TorqueAccumulator += torque;
    }

    private void ClearAccumulators()
    {
        ForceAccumulator = Vector3.Zero;
        TorqueAccumulator = Vector3.Zero;
