// Collider base class
public abstract class Collider
{
    public abstract bool TestCollision(Collider other, out CollisionInfo info);
    public abstract void CalculateMassProperties(out float mass, out Vector3 centerOfMass);
}

// Sphere collider implementation
public class SphereCollider : Collider
{
    public float Radius { get; set; }

    public override bool TestCollision(Collider other, out CollisionInfo info)
    {
        info = new CollisionInfo();

        if (other is SphereCollider sphere)
        {
            // Sphere-sphere collision
            float distance = Vector3.Distance(Position, sphere.Position);
            if (distance < Radius + sphere.Radius)
            {
                info.Normal = Vector3.Normalize(sphere.Position - Position);
                info.Penetration = (Radius + sphere.Radius) - distance;
                info.Point = Position + info.Normal * Radius;
                return true;
            }
        }

        return false;
    }

    // Other collider methods...
}

// Collision information structure
public struct CollisionInfo
{
    public Vector3 Normal;
    public float Penetration;
    public Vector3 Point;
    public RigidBody Body1;
    public RigidBody Body2;
}
