    private static CollisionInfo CheckSphereSphereCollision(SphereCollider a, SphereCollider b)
    {
        var distance = Vector3.Distance(a.Position, b.Position);
        var sumRadii = a.Radius + b.Radius;

        if (distance < sumRadii)
        {
            var normal = (a.Position - b.Position).normalized;
            return new CollisionInfo
            {
                IsColliding = true,
                Normal = normal,
                PenetrationDepth = sumRadii - distance,
                ContactPoint = a.Position + normal * a.Radius
            };
        }

        return new CollisionInfo { IsColliding = false };
    }

