void UMyPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    // Calculate inertia tensor (simplified for a sphere)
    float Radius = 1.0f; // This would normally come from the actor's collision
    InertiaTensor = FVector(Mass * Radius * Radius * 0.4f);
}

void UMyPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    // Simple Euler integration
    Velocity += Acceleration * DeltaTime;
    AngularVelocity += AngularAcceleration * DeltaTime;

    // Update position
    if (AActor* Owner = GetOwner())
    {
        FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;
        Owner->SetActorLocation(NewLocation);

        // Update rotation
        FQuat NewRotation = Owner->GetActorQuat() * FQuat::MakeFromEuler(AngularVelocity * DeltaTime);
        Owner->SetActorRotation(NewRotation.Rotator());
    }

    // Reset accelerations
    Acceleration = FVector::ZeroVector;
    AngularAcceleration = FVector::ZeroVector;
}

void UMyPhysicsComponent::ApplyForce(FVector Force)
{
    Acceleration += Force / Mass;
}

void UMyPhysicsComponent::ApplyTorque(FVector Torque)
{
    // Simplified torque calculation
    AngularAcceleration += Torque / InertiaTensor;
}
