#pragma once

#include <vector>
#include <memory>

namespace CustomPhysics {

// Basic 2D vector class
struct Vector2 {
    float x, y;

    Vector2(float x = 0.0f, float y = 0.0f) : x(x), y(y) {}

    Vector2 operator+(const Vector2& other) const {
        return Vector2(x + other.x, y + other.y);
    }

    Vector2& operator+=(const Vector2& other) {
        x += other.x;
        y += other.y;
        return *this;
    }

    Vector2 operator*(float scalar) const {
        return Vector2(x * scalar, y * scalar);
    }
};

// Rigid body properties
struct RigidBody {
    Vector2 position;
    Vector2 velocity;
    Vector2 acceleration;
    float mass;
    bool isStatic;

    RigidBody(float x = 0.0f, float y = 0.0f, float mass = 1.0f, bool isStatic = false)
        : position(x, y), mass(mass), isStatic(isStatic) {}
};

// Physics world class
class PhysicsWorld {
public:
    PhysicsWorld(float gravity = 9.8f);
    ~PhysicsWorld();

    // Add a rigid body to the simulation
    void AddRigidBody(const RigidBody& body);

    // Update the physics simulation
    void Update(float deltaTime);

    // Apply force to a rigid body
    void ApplyForce(size_t bodyIndex, const Vector2& force);

    // Get the number of rigid bodies
    size_t GetBodyCount() const;

    // Get a rigid body by index
    const RigidBody& GetRigidBody(size_t index) const;

private:
    std::vector<RigidBody> m_bodies;
    float m_gravity;
};

} // namespace CustomPhysics
```

## CustomPhysics.cpp

```cpp
#include "CustomPhysics.h"
#include <algorithm>

namespace CustomPhysics {

PhysicsWorld::PhysicsWorld(float gravity)
    : m_gravity(gravity) {}

PhysicsWorld::~PhysicsWorld() = default;

void PhysicsWorld::AddRigidBody(const RigidBody& body) {
    m_bodies.push_back(body);
}

void PhysicsWorld::Update(float deltaTime) {
    for (auto& body : m_bodies) {
        if (body.isStatic) continue;

        // Apply gravity
        body.acceleration.y = m_gravity;

        // Update velocity
        body.velocity += body.acceleration * deltaTime;

        // Update position
        body.position += body.velocity * deltaTime;

        // Reset acceleration for next frame
        body.acceleration = Vector2(0.0f, 0.0f);
    }
}

void PhysicsWorld::ApplyForce(size_t bodyIndex, const Vector2& force) {
    if (bodyIndex >= m_bodies.size()) return;

    auto& body = m_bodies[bodyIndex];
    if (body.isStatic) return;

    body.acceleration += force * (1.0f / body.mass);
}

size_t PhysicsWorld::GetBodyCount() const {
    return m_bodies.size();
}

const RigidBody& PhysicsWorld::GetRigidBody(size_t index) const {
    return m_bodies[index];
}

} // namespace CustomPhysics
```

