void ACustomPhysicsActor::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    if (bPhysicsEnabled)
    {
        // Simple Euler integration for physics simulation
        FVector Gravity = PhysicsProperties.bUseGravity ? FVector(0, 0, -980.0f) : FVector::ZeroVector;
        FVector Acceleration = Gravity / PhysicsProperties.Mass;

        CurrentVelocity += Acceleration * DeltaTime;
        CurrentVelocity *= FMath::Pow(1.0f - PhysicsProperties.LinearDamping, DeltaTime);

        FVector NewLocation = GetActorLocation() + CurrentVelocity * DeltaTime;
        SetActorLocation(NewLocation);
    }
}

void ACustomPhysicsActor::ApplyForce_Implementation(const FVector& Force, bool bAccelChange)
{
    if (bPhysicsEnabled)
    {
        if (bAccelChange)
        {
            CurrentVelocity += Force / PhysicsProperties.Mass;
        }
        else
        {
            CurrentVelocity += Force * GetWorld()->GetDeltaSeconds() / PhysicsProperties.Mass;
        }
    }
}

void ACustomPhysicsActor::SetVelocity_Implementation(const FVector& NewVelocity)
{
    if (bPhysicsEnabled)
    {
        CurrentVelocity = NewVelocity;
    }
}

