#pragma once

#include <vector>
#include <memory>

namespace CustomPhysics {

// Basic vector math class
struct Vector3 {
    float x, y, z;
    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
    Vector3 operator+(const Vector3& other) const { return Vector3(x + other.x, y + other.y, z + other.z); }
    Vector3 operator*(float scalar) const { return Vector3(x * scalar, y * scalar, z * scalar); }
};

// Rigid body properties
struct RigidBody {
    Vector3 position;
    Vector3 velocity;
    Vector3 acceleration;
    float mass;
    bool isStatic;
};

// Physics world interface
class IPhysicsWorld {
public:
    virtual ~IPhysicsWorld() = default;
    virtual void Step(float deltaTime) = 0;
    virtual void AddRigidBody(const RigidBody& body) = 0;
    virtual void RemoveRigidBody(size_t index) = 0;
    virtual const std::vector<RigidBody>& GetBodies() const = 0;
};

// Plugin interface that the engine will use
class ICustomPhysicsPlugin {
public:
    virtual ~ICustomPhysicsPlugin() = default;
    virtual std::unique_ptr<IPhysicsWorld> CreatePhysicsWorld() = 0;
};

// Plugin factory function that the engine will call
extern "C" ICustomPhysicsPlugin* CreateCustomPhysicsPlugin();
extern "C" void DestroyCustomPhysicsPlugin(ICustomPhysicsPlugin* plugin);

} // namespace CustomPhysics
```

## Implementation File (PhysicsWorld.cpp)

```cpp
#include "CustomPhysicsPlugin.h"
#include <algorithm>

namespace CustomPhysics {

class PhysicsWorld : public IPhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vector3 gravity = Vector3(0, -9.81f, 0);

public:
    void Step(float deltaTime) override {
        // Simple Euler integration
        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // Apply gravity
            body.acceleration = gravity;

            // Update velocity
            body.velocity = body.velocity + body.acceleration * deltaTime;

            // Update position
            body.position = body.position + body.velocity * deltaTime;

            // Simple ground collision
            if (body.position.y < 0) {
                body.position.y = 0;
                body.velocity.y = -body.velocity.y * 0.8f; // Bounce with damping
            }
        }
    }

    void AddRigidBody(const RigidBody& body) override {
        bodies.push_back(body);
    }

    void RemoveRigidBody(size_t index) override {
        if (index < bodies.size()) {
            bodies.erase(bodies.begin() + index);
        }
    }

    const std::vector<RigidBody>& GetBodies() const override {
        return bodies;
    }
};

} // namespace CustomPhysics
```

