    ApplyCustomPhysics(DeltaTime);
}

void UCustomPhysicsComponent::ApplyCustomPhysics_Implementation(float DeltaTime)
{
    // Simple physics simulation
    Acceleration = FVector(0, 0, -980.0f); // Gravity (cm/s²)

    // Apply drag
    Velocity -= Velocity * Drag * DeltaTime;

    // Update velocity
    Velocity += Acceleration * DeltaTime;

    // Move the actor
    if (AActor* Owner = GetOwner())
    {
        FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;
        Owner->SetActorLocation(NewLocation);

        // Simple ground collision
        if (NewLocation.Z <= 0)
        {
            Velocity.Z = -Velocity.Z * Bounciness;
            Owner->SetActorLocation(FVector(NewLocation.X, NewLocation.Y, 0));
        }
    }
}

void UCustomPhysicsComponent::SetPhysicsProperties_Implementation(float NewMass, float NewDrag, float NewBounciness)
{
    Mass = NewMass;
    Drag = NewDrag;
    Bounciness = NewBounciness;
}
