void PhysicsSystem::Update(float deltaTime) {
    for (auto component : mComponents) {
        if (component && component->IsActive()) {
            Vector3 position = component->GetOwner()->GetTransform().GetPosition();
            ApplyGravity(position, component->GetMass(), deltaTime);
            component->GetOwner()->GetTransform().SetPosition(position);
        }
    }
