    // Clean up rigid bodies
    for (auto body : m_RigidBodies) {
        delete body;
    }
    m_RigidBodies.clear();
}

void PhysicsWorld::StepSimulation(float deltaTime) {
    // Simple fixed timestep physics update
    m_TimeAccumulator += deltaTime;

    while (m_TimeAccumulator >= m_FixedTimeStep) {
        // Apply gravity
        for (auto body : m_RigidBodies) {
            body->ApplyForce(Vector3(0, m_Gravity * body->GetMass(), 0));
        }

        // Update positions
        for (auto body : m_RigidBodies) {
            body->Integrate(m_FixedTimeStep);
        }

        m_TimeAccumulator -= m_FixedTimeStep;
    }
}

void PhysicsWorld::AddRigidBody(RigidBody* body) {
    m_RigidBodies.push_back(body);
}

void PhysicsWorld::RemoveRigidBody(RigidBody* body) {
    auto it = std::find(m_RigidBodies.begin(), m_RigidBodies.end(), body);
    if (it != m_RigidBodies.end()) {
        m_RigidBodies.erase(it);
        delete body;
    }
}
