bool SphereShape::TestCollision(const CollisionShape& other) const {
    if (const SphereShape* otherSphere = dynamic_cast<const SphereShape*>(&other)) {
        // Sphere-sphere collision
        float distance = (position - otherSphere->position).Length();
        return distance < (radius + otherSphere->radius);
