bool BoxShape::TestCollision(const CollisionShape& other) const {
    if (const BoxShape* otherBox = dynamic_cast<const BoxShape*>(&other)) {
        // Box-box collision (simplified)
        Vector3 minA = position - extents;
        Vector3 maxA = position + extents;
        Vector3 minB = otherBox->position - otherBox->extents;
        Vector3 maxB = otherBox->position + otherBox->extents;

        return (minA.x <= maxB.x && maxA.x >= minB.x) &&
               (minA.y <= maxB.y && maxA.y >= minB.y) &&
               (minA.z <= maxB.z && maxA.z >= minB.z);
    }
