void UCustomPhysicsComponent::SimulatePhysics(float DeltaTime)
{
    // Simple Euler integration
    Velocity += Acceleration * DeltaTime;
    Velocity *= Damping; // Apply damping

    // Update position
    FVector NewLocation = GetOwner()->GetActorLocation() + Velocity * DeltaTime;
    GetOwner()->SetActorLocation(NewLocation);

    // Reset acceleration (forces need to be reapplied each frame)
    Acceleration = FVector::ZeroVector;
}
