    // Remove an object from the physics simulation
    void RemoveObject(PhysicsObject* object);

    // Update the physics simulation
    void Update(float deltaTime);

    // Set gravity vector
    void SetGravity(const Vector3& gravity) { m_gravity = gravity; }

