    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Physics")
    FVector Velocity;

    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Physics")
    FVector Acceleration;

    // Physics methods
    UFUNCTION(BlueprintCallable, Category = "Physics")
    void ApplyForce(const FVector& Force);

    UFUNCTION(BlueprintCallable, Category = "Physics")
    void Simulate(float DeltaTime);
};
```

## 6. Rigid Body Implementation (Private/CustomRigidBody.cpp)

```cpp
#include "CustomRigidBody.h"

UCustomRigidBody::UCustomRigidBody()
{
    Mass = 1.0f;
    Position = FVector::ZeroVector;
    Velocity = FVector::ZeroVector;
    Acceleration = FVector::ZeroVector;
}

void UCustomRigidBody::ApplyForce(const FVector& Force)
{
    if (Mass > 0.0f)
    {
        Acceleration += Force / Mass;
    }
}

void UCustomRigidBody::Simulate(float DeltaTime)
{
    // Simple Euler integration
    Velocity += Acceleration * DeltaTime;
    Position += Velocity * DeltaTime;

    // Reset acceleration for next frame
    Acceleration = FVector::ZeroVector;
}
```

## 7. Usage Example

To use this plugin in your game:

1. Create a Blueprint class that inherits from `UCustomRigidBody`
2. Call the `Simulate` function in your game loop
