def validate_payment_data(data):
    required_fields = ['amount', 'currency', 'merchant_id', 'customer_id', 'card_details']
    for field in required_fields:
        if field not in data:
            return False, f"Missing required field: {field}"

    if data['amount'] <= 0:
        return False, "Amount must be positive"

    return True, ""

@app.route('/api/payments', methods=['POST'])
def process_payment():
    try:
        data = request.get_json()

        # Validate input
        is_valid, error = validate_payment_data(data)
        if not is_valid:
            return jsonify({"error": error}), 400

        # Check merchant exists
        if data['merchant_id'] not in merchants:
            return jsonify({"error": "Invalid merchant"}), 400

        # Check customer exists
        if data['customer_id'] not in customers:
            return jsonify({"error": "Invalid customer"}), 400

        # Generate payment ID
        payment_id = str(uuid.uuid4())

        # Create payment record
        payment = {
            "id": payment_id,
            "amount": data['amount'],
            "currency": data['currency'],
            "merchant_id": data['merchant_id'],
            "customer_id": data['customer_id'],
            "status": "pending",
            "timestamp": datetime.utcnow().isoformat(),
            "card_details": {
                "last_four": data['card_details']['number'][-4:],
                "expiry": data['card_details']['expiry']
            }
        }

        # In production, you would:
        # 1. Tokenize the card details
        # 2. Send to payment processor
        # 3. Handle the response

        payments[payment_id] = payment

        logger.info(f"Payment processed: {payment_id}")

        return jsonify({
            "payment_id": payment_id,
            "status": "pending",
            "message": "Payment processed successfully"
        }), 201

    except Exception as e:
        logger.error(f"Payment processing error: {str(e)}")
        return jsonify({"error": "Payment processing failed"}), 500

@app.route('/api/payments/<payment_id>', methods=['GET'])
