```typescript
// src/integration/sap-integration.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios, { AxiosInstance } from 'axios';
import { SAPOrderResponse, SAPOrderRequest } from './types/sap-types';

@Injectable()
export class SapIntegrationService {
  private readonly logger = new Logger(SapIntegrationService.name);
  private readonly sapClient: AxiosInstance;

  constructor(private configService: ConfigService) {
    this.sapClient = axios.create({
      baseURL: this.configService.get('SAP_BASE_URL'),
      auth: {
        username: this.configService.get('SAP_USERNAME'),
        password: this.configService.get('SAP_PASSWORD'),
      },
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      timeout: 5000,
    });
  }

  async createOrder(order: SAPOrderRequest): Promise<SAPOrderResponse> {
    try {
      this.logger.log(`Creating order in SAP: ${JSON.stringify(order)}`);

      const response = await this.sapClient.post<SAPOrderResponse>(
        '/sap/opu/odata/sap/API_SALES_ORDER_SRV/A_SalesOrder',
        order
      );

      this.logger.log(`SAP order created successfully: ${response.data.d.SalesOrder}`);
      return response.data;
    } catch (error) {
      this.logger.error(`Failed to create order in SAP: ${error.message}`);
      throw new Error(`SAP integration failed: ${error.message}`);
    }
  }

  async getOrder(orderId: string): Promise<SAPOrderResponse> {
    try {
      this.logger.log(`Fetching order ${orderId} from SAP`);

      const response = await this.sapClient.get<SAPOrderResponse>(
        `/sap/opu/odata/sap/API_SALES_ORDER_SRV/A_SalesOrder('${orderId}')`
      );

      return response.data;
    } catch (error) {
      this.logger.error(`Failed to fetch order ${orderId} from SAP: ${error.message}`);
      throw new Error(`SAP integration failed: ${error.message}`);
    }
  }
}
