#### Order Service (`orders.service.ts`)

```typescript
import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order } from './entities/order.entity';
import { OrderItem } from './entities/order-item.entity';
import { Product } from '../inventory/entities/product.entity';
import { User } from '../users/entities/user.entity';
import { CreateOrderDto, UpdateOrderStatusDto } from './dto/order.dto';
import { ERPService } from '../../integrations/erp/erp.service';
import { CRMService } from '../../integrations/crm/crm.service';

@Injectable()
export class OrdersService {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    @InjectRepository(OrderItem)
    private readonly orderItemRepository: Repository<OrderItem>,
    @InjectRepository(Product)
    private readonly productRepository: Repository<Product>,
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly erpService: ERPService,
    private readonly crmService: CRMService,
  ) {}

  async createOrder(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${createOrderDto.customerId}`);

    const customer = await this.userRepository.findOne({
      where: { id: createOrderDto.customerId },
    });

    if (!customer) {
      throw new NotFoundException('Customer not found');
    }

    const orderItems: OrderItem[] = [];
    let totalAmount = 0;

    for (const item of createOrderDto.items) {
      const product = await this.productRepository.findOne({
        where: { id: item.productId },
      });

      if (!product) {
        throw new NotFoundException(`Product ${item.productId} not found`);
      }

      if (product.stockQuantity < item.quantity) {
        throw new Error(`Insufficient stock for product ${product.id}`);
      }

      const orderItem = this.orderItemRepository.create({
        productId: product.id,
        quantity: item.quantity,
        unitPrice: product.price,
        totalPrice: product.price * item.quantity,
      });

      orderItems.push(orderItem);
      totalAmount += orderItem.totalPrice;
    }

    const orderNumber = this.generateOrderNumber();
    const order = this.orderRepository.create({
      orderNumber,
      customerId: customer.id,
      items: orderItems,
      totalAmount,
      notes: createOrderDto.notes,
    });

    const savedOrder = await this.orderRepository.save(order);

    // Update inventory
    for (const item of orderItems) {
      await this.productRepository.decrement(
        { id: item.productId },
        'stockQuantity',
        item.quantity,
      );
    }

    // Sync with ERP
    try {
      await this.erpService.syncOrder(savedOrder);
    } catch (error) {
      this.logger.error(`Failed to sync order with ERP: ${error.message}`);
      // Consider implementing a retry mechanism or dead letter queue
    }

    // Update CRM
    try {
      await this.crmService.updateCustomerOrderHistory(customer.id, savedOrder);
    } catch (error) {
      this.logger.error(`Failed to update CRM: ${error.message}`);
    }

    return savedOrder;
  }

  async getOrderById(id: string): Promise<Order> {
    const order = await this.orderRepository.findOne({
      where: { id },
      relations: ['customer', 'items', 'items.product'],
    });

    if (!order) {
      throw new NotFoundException('Order not found');
    }

    return order;
  }

  async updateOrderStatus(
    id: string,
    updateOrderStatusDto: UpdateOrderStatusDto,
  ): Promise<Order> {
    const order = await this.getOrderById(id);

    order.status = updateOrderStatusDto.status;
    const updatedOrder = await this.orderRepository.save(order);

    // Sync status with ERP
    try {
      await this.erpService.updateOrderStatus(updatedOrder);
    } catch (error) {
      this.logger.error(`Failed to update order status in ERP: ${error.message}`);
    }

    // Update CRM if order is delivered
    if (updateOrderStatusDto.status === 'delivered') {
      try {
        await this.crmService.markOrderAsDelivered(order.customerId, order.id);
      } catch (error) {
        this.logger.error(`Failed to update CRM: ${error.message}`);
      }
    }

    return updatedOrder;
  }

  private generateOrderNumber(): string {
    const date = new Date();
    const year = date.getFullYear().toString().substr(-2);
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');
    const randomNum = Math.floor(1000 + Math.random() * 9000);

    return `ORD-${year}${month}${day}-${randomNum}`;
  }
}
