#### ERP Service (`erp.service.ts`)

```typescript
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios, { AxiosInstance } from 'axios';
import { Order } from '../../modules/orders/entities/order.entity';

@Injectable()
export class ERPService {
  private readonly logger = new Logger(ERPService.name);
  private readonly erpClient: AxiosInstance;

  constructor(private readonly configService: ConfigService) {
    this.erpClient = axios.create({
      baseURL: configService.get<string>('ERP_API_URL'),
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${configService.get<string>('ERP_API_KEY')}`,
      },
    });
  }

  async syncOrder(order: Order): Promise<void> {
    try {
      const erpOrder = this.mapToERPOrder(order);
      await this.erpClient.post('/orders', erpOrder);
      this.logger.log(`Successfully synced order ${order.id} with ERP`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} with ERP: ${error.message}`);
      throw error;
    }
  }

  async updateOrderStatus(order: Order): Promise<void> {
    try {
      const erpOrderStatus = {
        orderId: order.orderNumber,
        status: order.status,
        updatedAt: order.updatedAt.toISOString(),
      };
      await this.erpClient.patch(`/orders/${order.orderNumber}/status`, erpOrderStatus);
      this.logger.log(`Successfully updated status for order ${order.id} in ERP`);
    } catch (error) {
      this.logger.error(`Failed to update order status in ERP: ${error.message}`);
      throw error;
    }
  }

  private mapToERPOrder(order: Order): any {
    return {
      orderId: order.orderNumber,
      customerId: order.customerId,
      items: order.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        totalPrice: item.totalPrice,
      })),
      totalAmount: order.totalAmount,
      status: order.status,
      createdAt: order.createdAt.toISOString(),
      notes: order.notes,
    };
  }
}
