## Example Service with Strict Typing

```typescript
// src/order/order.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { OrderRepository } from './order.repository';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { Order } from './entities/order.entity';
import { OrderStatus } from './enums/order-status.enum';
import { OrderEventPublisher } from './order-event.publisher';
import { InjectRedis } from '@nestjs-modules/ioredis';
import Redis from 'ioredis';
import { OrderNotFoundException } from './exceptions/order-not-found.exception';
import { InvalidOrderStatusTransitionException } from './exceptions/invalid-order-status-transition.exception';

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(
    @InjectRepository(OrderRepository)
    private readonly orderRepository: OrderRepository,
    private readonly orderEventPublisher: OrderEventPublisher,
    @InjectRedis() private readonly redis: Redis,
  ) {}

  async createOrder(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${createOrderDto.customerId}`);

    const order = await this.orderRepository.createOrder(createOrderDto);

    // Publish order created event
    await this.orderEventPublisher.publishOrderCreated(order);

    // Cache the order
    await this.cacheOrder(order);

    return order;
  }

  async getOrderById(id: string): Promise<Order> {
    // Try to get from cache first
    const cachedOrder = await this.getCachedOrder(id);
    if (cachedOrder) {
      return cachedOrder;
    }

    const order = await this.orderRepository.findOne(id, {
      relations: ['items', 'statusHistory'],
    });

    if (!order) {
      throw new OrderNotFoundException(id);
    }

    // Cache the order
    await this.cacheOrder(order);

    return order;
  }

  async updateOrderStatus(
    id: string,
    newStatus: OrderStatus,
  ): Promise<Order> {
    const order = await this.getOrderById(id);

    // Validate status transition
    if (!this.isValidStatusTransition(order.status, newStatus)) {
      throw new InvalidOrderStatusTransitionException(
        order.status,
        newStatus,
      );
    }

    order.status = newStatus;
    await this.orderRepository.save(order);

    // Publish status changed event
    await this.orderEventPublisher.publishOrderStatusChanged(order);

    // Update cache
    await this.cacheOrder(order);

    return order;
  }

  private async cacheOrder(order: Order): Promise<void> {
    const cacheKey = `order:${order.id}`;
    await this.redis.set(cacheKey, JSON.stringify(order), 'EX', 3600); // 1 hour TTL
  }

  private async getCachedOrder(id: string): Promise<Order | null> {
    const cacheKey = `order:${id}`;
    const cachedOrder = await this.redis.get(cacheKey);

    if (cachedOrder) {
      return JSON.parse(cachedOrder);
    }

    return null;
  }

  private isValidStatusTransition(
    currentStatus: OrderStatus,
    newStatus: OrderStatus,
  ): boolean {
    const validTransitions: Record<OrderStatus, OrderStatus[]> = {
      [OrderStatus.DRAFT]: [OrderStatus.PENDING, OrderStatus.CANCELLED],
      [OrderStatus.PENDING]: [OrderStatus.PROCESSING, OrderStatus.CANCELLED],
      [OrderStatus.PROCESSING]: [OrderStatus.SHIPPED, OrderStatus.CANCELLED],
      [OrderStatus.SHIPPED]: [OrderStatus.DELIVERED],
      [OrderStatus.DELIVERED]: [],
      [OrderStatus.CANCELLED]: [],
      [OrderStatus.RETURNED]: [],
    };

    return validTransitions[currentStatus].includes(newStatus);
  }
}
