```typescript
// src/order/order-event.publisher.ts
import { Injectable, Logger } from '@nestjs/common';
import { ClientKafka } from '@nestjs/microservices';
import { Order } from './entities/order.entity';

@Injectable()
export class OrderEventPublisher {
  private readonly logger = new Logger(OrderEventPublisher.name);

  constructor(private readonly kafkaClient: ClientKafka) {}

  async publishOrderCreated(order: Order): Promise<void> {
    this.logger.log(`Publishing OrderCreated event for order ${order.id}`);

    await this.kafkaClient.emit('order.created', {
      orderId: order.id,
      customerId: order.customerId,
      status: order.status,
      totalAmount: order.totalAmount,
      createdAt: order.createdAt.toISOString(),
    });
  }

  async publishOrderStatusChanged(order: Order): Promise<void> {
    this.logger.log(`Publishing OrderStatusChanged event for order ${order.id}`);

    await this.kafkaClient.emit('order.status.changed', {
      orderId: order.id,
      previousStatus: order.statusHistory[order.statusHistory.length - 2]?.status,
      newStatus: order.status,
      changedAt: new Date().toISOString(),
    });
  }
}
