## Example Kafka Event Subscriber

```typescript
// src/order/order-event.subscriber.ts
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ClientKafka, EventPattern, Payload } from '@nestjs/microservices';
import { OrderService } from './order.service';

@Injectable()
export class OrderEventSubscriber implements OnModuleInit {
  private readonly logger = new Logger(OrderEventSubscriber.name);

  constructor(
    private readonly orderService: OrderService,
    private readonly kafkaClient: ClientKafka,
  ) {}

  async onModuleInit() {
    // Subscribe to topics
    this.kafkaClient.subscribeToResponseOf('payment.processed');
    this.kafkaClient.subscribeToResponseOf('inventory.reserved');
    await this.kafkaClient.connect();
  }

  @EventPattern('payment.processed')
  async handlePaymentProcessed(@Payload() message: any) {
    this.logger.log(`Received payment.processed event for order ${message.orderId}`);

    try {
      // Update order status to PROCESSING
      await this.orderService.updateOrderStatus(
        message.orderId,
        'PROCESSING' as OrderStatus,
      );
    } catch (error) {
      this.logger.error(`Failed to process payment.processed event: ${error.message}`);
      // Implement dead letter queue or retry logic here
    }
  }

  @EventPattern('inventory.reserved')
  async handleInventoryReserved(@Payload() message: any) {
    this.logger.log(`Received inventory.reserved event for order ${message.orderId}`);

    try {
      // Update order status to PROCESSING if payment is already processed
      const order = await this.orderService.getOrderById(message.orderId);
      if (order.status === 'PENDING') {
        await this.orderService.updateOrderStatus(
          message.orderId,
          'PROCESSING' as OrderStatus,
        );
      }
    } catch (error) {
      this.logger.error(`Failed to process inventory.reserved event: ${error.message}`);
    }
  }
}
