# Enterprise-Grade Backend Microservice with Type Safety

Below is a comprehensive implementation of a backend microservice designed for a large enterprise with strict type safety requirements and integration with existing corporate systems. This example uses TypeScript, NestJS (a Node.js framework), and follows enterprise patterns.

## Core Architecture

```typescript
// src/main.ts
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { Logger } from 'nestjs-pino';
import { ConfigService } from '@nestjs/config';
import { MicroserviceOptions, Transport } from '@nestjs/microservices';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['error', 'warn', 'log'],
  });

  // Configure global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      transform: true,
      whitelist: true,
      forbidNonWhitelisted: true,
    }),
  );

  // Configure Pino logger
  app.useLogger(app.get(Logger));

  // Configure Swagger for API documentation
  const config = new DocumentBuilder()
    .setTitle('Enterprise Microservice API')
    .setDescription('API documentation for enterprise-grade microservice')
    .setVersion('1.0')
    .addBearerAuth()
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api-docs', app, document);

  // Configure microservice for inter-service communication
  const configService = app.get(ConfigService);
  app.connectMicroservice<MicroserviceOptions>({
    transport: Transport.TCP,
    options: {
      host: configService.get('MICROSERVICE_HOST'),
      port: configService.get('MICROSERVICE_PORT'),
    },
  });

  await app.startAllMicroservices();
  await app.listen(configService.get('PORT') || 3000);
}

bootstrap();
```

