## Service Layer with Business Logic

```typescript
// src/application/services/user.service.ts
import { Injectable, NotFoundException } from '@nestjs/common';
import { UserRepository } from '../../infrastructure/repositories/user.repository';
import { User, CreateUserDto, UpdateUserDto } from '../../domain/models/user.model';
import { PasswordService } from '../../infrastructure/services/password.service';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly passwordService: PasswordService,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async getAllUsers(): Promise<User[]> {
    return this.userRepository.findAll();
  }

  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return user;
  }

  async createUser(createUserDto: CreateUserDto): Promise<User> {
    const hashedPassword = await this.passwordService.hashPassword(createUserDto.password);
    const userData = {
      ...createUserDto,
      password: hashedPassword,
    };

    const createdUser = await this.userRepository.create(userData);

    // Emit event for other services to react
    this.eventEmitter.emit('user.created', createdUser);

    return createdUser;
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<User> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new NotFoundException('User not found');
    }

    let updatedData: Partial<Omit<User, 'id' | 'createdAt' | 'updatedAt'>> = {
      ...updateUserDto,
    };

    if (updateUserDto.password) {
      updatedData.password = await this.passwordService.hashPassword(updateUserDto.password);
    }

    const updatedUser = await this.userRepository.update(id, updatedData);

    // Emit event for other services to react
    this.eventEmitter.emit('user.updated', updatedUser);

    return updatedUser;
  }

  async deleteUser(id: string): Promise<void> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }

    await this.userRepository.delete(id);

    // Emit event for other services to react
    this.eventEmitter.emit('user.deleted', { id });
  }
}
```

