## Integration with Corporate Systems

```typescript
// src/infrastructure/integrations/sap-integration.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ClientProxy, ClientProxyFactory, Transport } from '@nestjs/microservices';
import { firstValueFrom } from 'rxjs';

@Injectable()
export class SapIntegrationService {
  private readonly logger = new Logger(SapIntegrationService.name);
  private sapClient: ClientProxy;

  constructor(private readonly configService: ConfigService) {
    this.sapClient = ClientProxyFactory.create({
      transport: Transport.TCP,
      options: {
        host: this.configService.get('SAP_HOST'),
        port: this.configService.get('SAP_PORT'),
      },
    });
  }

  async syncUserToSAP(userId: string): Promise<void> {
    try {
      const result = await firstValueFrom(
        this.sapClient.send('sync_user', { userId }),
      );
      this.logger.log(`Successfully synced user ${userId} to SAP: ${JSON.stringify(result)}`);
    } catch (error) {
      this.logger.error(`Failed to sync user ${userId} to SAP: ${error.message}`);
      throw error;
    }
  }

  async getSAPUserData(userId: string): Promise<any> {
    try {
      const userData = await firstValueFrom(
        this.sapClient.send('get_user_data', { userId }),
      );
      this.logger.log(`Retrieved SAP data for user ${userId}`);
      return userData;
    } catch (error) {
      this.logger.error(`Failed to retrieve SAP data for user ${userId}: ${error.message}`);
      throw error;
    }
  }
}
