### Order Service with Type Safety

```typescript
// src/orders/orders.service.ts
import { Injectable, NotFoundException, ConflictException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, DataSource } from 'typeorm';
import { Order } from './entities/order.entity';
import { OrderItem } from './entities/order-item.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { OrderStatus } from './enums/order-status.enum';
import { InventoryService } from '../inventory/inventory.service';
import { LoggingService } from '../logging/logging.service';
import { ERPIntegrationService } from '../integrations/erp.service';

@Injectable()
export class OrdersService {
  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    private readonly inventoryService: InventoryService,
    private readonly loggingService: LoggingService,
    private readonly erpService: ERPIntegrationService,
    private readonly dataSource: DataSource,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    const queryRunner = this.dataSource.createQueryRunner();

    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      // Check inventory availability
      for (const item of createOrderDto.items) {
        await this.inventoryService.checkAvailability(
          item.productId,
          item.quantity,
        );
      }

      // Create order
      const order = this.orderRepository.create({
        ...createOrderDto,
        status: OrderStatus.PENDING,
        items: createOrderDto.items.map((item) =>
          this.orderRepository.manager.create(OrderItem, item),
        ),
      });

      const savedOrder = await queryRunner.manager.save(order);

      // Reserve inventory
      for (const item of createOrderDto.items) {
        await this.inventoryService.reserveInventory(
          item.productId,
          item.quantity,
          savedOrder.id,
        );
      }

      // Sync with ERP
      await this.erpService.syncOrder(savedOrder);

      await queryRunner.commitTransaction();

      this.loggingService.log(
        'OrderService',
        `Order created: ${savedOrder.id}`,
        'INFO',
      );

      return savedOrder;
    } catch (error) {
      await queryRunner.rollbackTransaction();
      this.loggingService.log(
        'OrderService',
        `Failed to create order: ${error.message}`,
        'ERROR',
      );
      throw error;
    } finally {
      await queryRunner.release();
    }
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.find({
      relations: ['customer', 'items'],
    });
  }

  async findOne(id: string): Promise<Order> {
    const order = await this.orderRepository.findOne({
      where: { id },
      relations: ['customer', 'items'],
    });

    if (!order) {
      throw new NotFoundException(`Order with ID ${id} not found`);
    }

    return order;
  }

  async update(id: string, updateOrderDto: UpdateOrderDto): Promise<Order> {
    const order = await this.findOne(id);

    if (order.status === OrderStatus.COMPLETED) {
      throw new ConflictException('Cannot update a completed order');
    }

    Object.assign(order, updateOrderDto);

    return this.orderRepository.save(order);
  }

  async remove(id: string): Promise<void> {
    const order = await this.findOne(id);

    if (order.status !== OrderStatus.PENDING) {
      throw new ConflictException('Only pending orders can be deleted');
    }

    await this.orderRepository.remove(order);
  }

  async completeOrder(id: string): Promise<Order> {
    const order = await this.findOne(id);

    if (order.status !== OrderStatus.PROCESSING) {
      throw new ConflictException('Only processing orders can be completed');
    }

    order.status = OrderStatus.COMPLETED;
    order.completedAt = new Date();

    return this.orderRepository.save(order);
  }
}
