### ERP Integration Service

```typescript
// src/integrations/erp.service.ts
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Order } from '../orders/entities/order.entity';
import { LoggingService } from '../logging/logging.service';
import axios, { AxiosInstance } from 'axios';
import { ERPOrderResponse } from './interfaces/erp-order-response.interface';

@Injectable()
export class ERPIntegrationService {
  private readonly erpClient: AxiosInstance;

  constructor(
    private readonly configService: ConfigService,
    private readonly loggingService: LoggingService,
  ) {
    this.erpClient = axios.create({
      baseURL: this.configService.get<string>('ERP_API_URL'),
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.configService.get<string>('ERP_API_KEY')}`,
      },
      timeout: 5000,
    });
  }

  async syncOrder(order: Order): Promise<ERPOrderResponse> {
    try {
      const response = await this.erpClient.post<ERPOrderResponse>('/orders', {
        orderId: order.id,
        customerId: order.customerId,
        items: order.items.map(item => ({
          productId: item.productId,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
        })),
        totalAmount: order.totalAmount,
        status: order.status,
      });

      this.loggingService.log(
        'ERPIntegrationService',
        `Successfully synced order ${order.id} with ERP`,
        'INFO',
      );

      return response.data;
    } catch (error) {
      this.loggingService.log(
        'ERPIntegrationService',
        `Failed to sync order ${order.id} with ERP: ${error.message}`,
        'ERROR',
      );

      throw new HttpException(
        'Failed to synchronize with ERP system',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  async getOrderStatus(orderId: string): Promise<ERPOrderResponse> {
    try {
      const response = await this.erpClient.get<ERPOrderResponse>(`/orders/${orderId}`);

      this.loggingService.log(
        'ERPIntegrationService',
        `Retrieved status for order ${orderId} from ERP`,
        'INFO',
      );

      return response.data;
    } catch (error) {
      this.loggingService.log(
        'ERPIntegrationService',
        `Failed to retrieve order ${orderId} status from ERP: ${error.message}`,
        'ERROR',
      );

      throw new HttpException(
        'Failed to retrieve order status from ERP system',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }
}
