## Integration with Corporate Systems

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { AxiosRequestConfig } from 'axios';
import { ERPOrderDto } from './dto/erp-order.dto';
import { ERPInventoryDto } from './dto/erp-inventory.dto';

@Injectable()
export class ERPIntegrationService {
  private readonly logger = new Logger(ERPIntegrationService.name);
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_BASE_URL');
    this.erpApiKey = this.configService.get<string>('ERP_API_KEY');
  }

  private async makeERPRequest<T>(config: AxiosRequestConfig): Promise<T> {
    try {
      const response = await firstValueFrom(
        this.httpService.request<T>({
          ...config,
          headers: {
            ...config.headers,
            'Authorization': `Bearer ${this.erpApiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );
      return response.data;
    } catch (error) {
      this.logger.error(`ERP request failed: ${error.message}`);
      throw new Error(`ERP integration failed: ${error.message}`);
    }
  }

  async syncOrderToERP(order: ERPOrderDto): Promise<void> {
    await this.makeERPRequest<void>({
      method: 'POST',
      url: `${this.erpBaseUrl}/api/orders`,
      data: order,
    });
    this.logger.log(`Order ${order.orderId} synced to ERP`);
  }

  async getInventoryFromERP(sku: string): Promise<ERPInventoryDto> {
    const inventory = await this.makeERPRequest<ERPInventoryDto>({
      method: 'GET',
      url: `${this.erpBaseUrl}/api/inventory/${sku}`,
    });
    this.logger.log(`Retrieved inventory for SKU ${sku} from ERP`);
    return inventory;
  }

  async updateInventoryInERP(sku: string, quantity: number): Promise<void> {
    await this.makeERPRequest<void>({
      method: 'PUT',
      url: `${this.erpBaseUrl}/api/inventory/${sku}`,
      data: { quantity },
    });
    this.logger.log(`Updated inventory for SKU ${sku} in ERP`);
  }
}
