```typescript
// src/app.ts
import express, { Application, Request, Response, NextFunction } from 'express';
import { createConnection, Connection } from 'typeorm';
import { validate } from 'class-validator';
import { plainToClass } from 'class-transformer';
import { v4 as uuidv4 } from 'uuid';
import winston from 'winston';
import swaggerUi from 'swagger-ui-express';
import * as swaggerDocument from './swagger.json';
import { User } from './entities/User';
import { Order } from './entities/Order';
import { authMiddleware } from './middleware/auth';
import { errorHandler } from './middleware/errorHandler';
import { corporateIntegrationService } from './services/corporateIntegration';
import { orderService } from './services/orderService';

// Initialize logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

class App {
  public app: Application;
  private connection: Connection;

  constructor() {
    this.app = express();
    this.initializeMiddlewares();
    this.initializeDatabase();
    this.initializeRoutes();
    this.initializeErrorHandling();
  }

  private initializeMiddlewares() {
    this.app.use(express.json());
    this.app.use(express.urlencoded({ extended: true }));

    // Request logging
    this.app.use((req: Request, res: Response, next: NextFunction) => {
      logger.info(`${req.method} ${req.path}`);
      next();
    });

    // API documentation
    this.app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

    // Authentication middleware
    this.app.use(authMiddleware);
  }

  private async initializeDatabase() {
    try {
      this.connection = await createConnection({
        type: 'postgres',
        host: process.env.DB_HOST,
        port: Number(process.env.DB_PORT),
        username: process.env.DB_USERNAME,
        password: process.env.DB_PASSWORD,
        database: process.env.DB_NAME,
        entities: [User, Order],
        synchronize: false, // Never use in production
        logging: ['error']
      });
      logger.info('Database connection established');
    } catch (error) {
      logger.error('Database connection error', error);
      process.exit(1);
    }
  }

  private initializeRoutes() {
    // Health check endpoint
    this.app.get('/health', (req: Request, res: Response) => {
      res.status(200).json({ status: 'healthy' });
    });

    // User routes
    this.app.post('/users', this.validateRequest(User), async (req: Request, res: Response, next: NextFunction) => {
      try {
        const user = await this.connection.manager.save(User, req.body);
        res.status(201).json(user);
      } catch (error) {
        next(error);
      }
    });

    // Order routes
    this.app.post('/orders', this.validateRequest(Order), async (req: Request, res: Response, next: NextFunction) => {
      try {
        const order = plainToClass(Order, req.body);
        const savedOrder = await orderService.createOrder(order);

        // Integrate with corporate systems
        await corporateIntegrationService.notifyOrderCreation(savedOrder);

        res.status(201).json(savedOrder);
      } catch (error) {
        next(error);
      }
    });

    this.app.get('/orders/:id', async (req: Request, res: Response, next: NextFunction) => {
      try {
        const order = await orderService.getOrderById(req.params.id);
        if (!order) {
          return res.status(404).json({ message: 'Order not found' });
        }
        res.json(order);
      } catch (error) {
        next(error);
      }
    });
  }

  private validateRequest<T>(type: any) {
    return async (req: Request, res: Response, next: NextFunction) => {
      const dto = plainToClass(type, req.body);
      const errors = await validate(dto);

      if (errors.length > 0) {
        const errorMessages = errors.map(error => ({
          property: error.property,
          constraints: error.constraints
        }));
        return res.status(400).json({ errors: errorMessages });
      }

      req.body = dto;
      next();
    };
  }

  private initializeErrorHandling() {
    this.app.use(errorHandler);
  }

  public listen(port: number) {
    this.app.listen(port, () => {
      logger.info(`Server is running on port ${port}`);
    });
  }
}

export default App;
