// src/services/orderService.ts
import { getRepository } from 'typeorm';
import { Order, OrderStatus } from '../entities/Order';
import { User } from '../entities/User';
import { corporateIntegrationService } from './corporateIntegration';

export class OrderService {
  async createOrder(orderData: Order): Promise<Order> {
    const orderRepository = getRepository(Order);
    const userRepository = getRepository(User);

    // Validate user exists
    const user = await userRepository.findOne(orderData.user.id);
    if (!user) {
      throw new Error('User not found');
    }

    // Create and save order
    const order = orderRepository.create({
      ...orderData,
      user,
      status: OrderStatus.PENDING
    });

    const savedOrder = await orderRepository.save(order);

    // Additional business logic can be added here

    return savedOrder;
  }

  async getOrderById(id: string): Promise<Order | undefined> {
    const orderRepository = getRepository(Order);
    return orderRepository.findOne(id, { relations: ['user'] });
  }

  async updateOrderStatus(id: string, status: OrderStatus): Promise<Order> {
    const orderRepository = getRepository(Order);
    const order = await orderRepository.findOne(id);

    if (!order) {
      throw new Error('Order not found');
    }

    order.status = status;
    return orderRepository.save(order);
  }
}

