    try {
      const response = await this.axiosInstance.post<CorporateSystemResponse>(
        '/api/orders',
        {
          orderId: order.id,
          productId: order.productId,
          quantity: order.quantity,
          totalAmount: order.totalAmount,
          userId: order.user.id
        }
      );

      if (response.data.success) {
        // Update order with corporate reference ID
        const orderRepository = getRepository(Order);
        await orderRepository.update(order.id, {
          corporateReferenceId: response.data.referenceId
        });
        logger.info(`Successfully integrated order ${order.id} with corporate system`);
      } else {
        logger.error(`Corporate system integration failed for order ${order.id}: ${response.data.message}`);
      }
    } catch (error) {
      logger.error(`Error integrating order ${order.id} with corporate system`, error);
      // Implement retry logic or dead letter queue here
    }
  }

  async getCorporateData(referenceId: string): Promise<any> {
    try {
      const response = await this.axiosInstance.get(`/api/data/${referenceId}`);
      return response.data;
    } catch (error) {
      logger.error(`Error fetching corporate data for reference ${referenceId}`, error);
      throw error;
    }
  }
