## Service Layer with Dependency Injection

```typescript
// src/services/user.service.ts
import { prisma } from '../database';
import { User, CreateUserInput, UpdateUserInput } from '../models/user.model';
import { NotFoundError, ConflictError } from '../errors';
import { logger } from '../utils/logger';

export class UserService {
  constructor() {}

  async createUser(data: CreateUserInput): Promise<User> {
    try {
      // Check if user with same email already exists
      const existingUser = await prisma.user.findUnique({
        where: { email: data.email },
      });

      if (existingUser) {
        throw new ConflictError('User with this email already exists');
      }

      const user = await prisma.user.create({
        data: {
          ...data,
          createdAt: new Date(),
          updatedAt: new Date(),
        },
      });

      logger.info(`Created new user: ${user.id}`);
      return user;
    } catch (error) {
      logger.error(`Failed to create user: ${error.message}`);
      throw error;
    }
  }

  async getUserById(id: string): Promise<User> {
    try {
      const user = await prisma.user.findUnique({
        where: { id },
      });

      if (!user) {
        throw new NotFoundError('User not found');
      }

      return user;
    } catch (error) {
      logger.error(`Failed to get user by ID: ${error.message}`);
      throw error;
    }
  }

  async updateUser(id: string, data: UpdateUserInput): Promise<User> {
    try {
      const user = await prisma.user.update({
        where: { id },
        data: {
          ...data,
          updatedAt: new Date(),
        },
      });

      logger.info(`Updated user: ${user.id}`);
      return user;
    } catch (error) {
      logger.error(`Failed to update user: ${error.message}`);
      throw error;
    }
  }

  async deleteUser(id: string): Promise<void> {
    try {
      await prisma.user.delete({
        where: { id },
      });

      logger.info(`Deleted user: ${id}`);
    } catch (error) {
      logger.error(`Failed to delete user: ${error.message}`);
      throw error;
    }
  }

  async listUsers(): Promise<User[]> {
    try {
      return await prisma.user.findMany();
    } catch (error) {
      logger.error(`Failed to list users: ${error.message}`);
      throw error;
    }
  }
}
