## Corporate System Integration Layer

```typescript
// src/integrations/corporate-api.service.ts
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { IntegrationError } from '../errors';

interface CorporateApiResponse<T> {
  success: boolean;
  data?: T;
  error?: {
    code: string;
    message: string;
  };
}

export class CorporateApiService {
  private axiosInstance: AxiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      timeout: config.CORPORATE_API_TIMEOUT,
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
    });

    // Add request interceptor
    this.axiosInstance.interceptors.request.use(
      (config) => {
        logger.debug(`Corporate API Request: ${config.method?.toUpperCase()} ${config.url}`);
        return config;
      },
      (error) => {
        logger.error(`Corporate API Request Error: ${error.message}`);
        return Promise.reject(error);
      }
    );

    // Add response interceptor
    this.axiosInstance.interceptors.response.use(
      (response) => {
        logger.debug(`Corporate API Response: ${response.status} ${response.config.url}`);
        return response;
      },
      (error) => {
        logger.error(`Corporate API Response Error: ${error.message}`);
        return Promise.reject(error);
      }
    );
  }

  async get<T>(endpoint: string, params?: any): Promise<T> {
    try {
      const response: AxiosResponse<CorporateApiResponse<T>> = await this.axiosInstance.get(endpoint, { params });

      if (!response.data.success) {
        throw new IntegrationError(
          response.data.error?.message || 'Corporate API request failed',
          response.data.error?.code || 'UNKNOWN_ERROR'
        );
      }

      return response.data.data as T;
    } catch (error) {
      this.handleError(error);
    }
  }

  async post<T>(endpoint: string, data: any): Promise<T> {
    try {
      const response: AxiosResponse<CorporateApiResponse<T>> = await this.axiosInstance.post(endpoint, data);

      if (!response.data.success) {
        throw new IntegrationError(
          response.data.error?.message || 'Corporate API request failed',
          response.data.error?.code || 'UNKNOWN_ERROR'
        );
      }

      return response.data.data as T;
    } catch (error) {
      this.handleError(error);
    }
  }

  private handleError(error: any): never {
    if (axios.isAxiosError(error)) {
      if (error.response) {
        // The request was made and the server responded with a status code
        // that falls out of the range of 2xx
        logger.error(`Corporate API Error: ${error.response.status} - ${error.response.data}`);
        throw new IntegrationError(
          error.response.data?.message || 'Corporate API request failed',
          error.response.data?.code || 'HTTP_ERROR'
        );
      } else if (error.request) {
        // The request was made but no response was received
        logger.error('Corporate API Error: No response received');
        throw new IntegrationError('No response received from Corporate API', 'NO_RESPONSE');
      } else {
        // Something happened in setting up the request that triggered an Error
        logger.error(`Corporate API Error: ${error.message}`);
        throw new IntegrationError('Failed to make request to Corporate API', 'REQUEST_SETUP_ERROR');
      }
    } else {
      // Handle non-Axios errors
      logger.error(`Corporate API Error: ${error.message}`);
      throw new IntegrationError('An unexpected error occurred with Corporate API', 'UNEXPECTED_ERROR');
    }
  }
}
