## Error Handling Middleware

```typescript
// src/error-handling.ts
import { Request, Response, NextFunction, Express } from 'express';
import { logger } from './utils/logger';
import { AppError, NotFoundError, ValidationError, IntegrationError } from './errors';

export function setupErrorHandling(app: Express) {
  // Catch 404 and forward to error handler
  app.use((req: Request, res: Response, next: NextFunction) => {
    const err = new NotFoundError(`Not Found - ${req.originalUrl}`);
    next(err);
  });

  // Error handler
  app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
    // Log the error
    logger.error(err.stack);

    // Handle different types of errors
    if (err instanceof AppError) {
      // Custom application errors
      res.status(err.statusCode).json({
        success: false,
        error: {
          code: err.errorCode,
          message: err.message,
          details: err.details,
        },
      });
    } else if (err instanceof ValidationError) {
      // Validation errors
      res.status(400).json({
        success: false,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Validation failed',
          details: err.errors,
        },
      });
    } else if (err instanceof IntegrationError) {
      // Integration errors
      res.status(502).json({
        success: false,
        error: {
          code: err.errorCode,
          message: 'Integration failed',
          details: err.message,
        },
      });
    } else {
      // Default to 500 server error
      res.status(500).json({
        success: false,
        error: {
          code: 'INTERNAL_SERVER_ERROR',
          message: 'An unexpected error occurred',
          details: process.env.NODE_ENV === 'development' ? err.message : undefined,
        },
      });
    }
  });
}
