```typescript
// src/services/corporateIntegration.ts - Type-safe corporate system integration
import axios, { AxiosInstance, AxiosResponse, AxiosError } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { z } from 'zod';

const CorporateSystemResponseSchema = z.object({
  status: z.string(),
  data: z.any(),
  timestamp: z.string().datetime(),
});

type CorporateSystemResponse = z.infer<typeof CorporateSystemResponseSchema>;

class CorporateIntegrationService {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      timeout: config.CORPORATE_API_TIMEOUT,
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': config.CORPORATE_API_KEY,
      },
    });

    this.client.interceptors.response.use(
      (response: AxiosResponse) => {
        try {
          const validated = CorporateSystemResponseSchema.parse(response.data);
          return validated;
        } catch (error) {
          logger.error('Corporate API response validation failed', { error });
          throw new Error('Invalid corporate system response format');
        }
      },
      (error: AxiosError) => {
        logger.error('Corporate API request failed', {
          url: error.config?.url,
          method: error.config?.method,
          status: error.response?.status,
          message: error.message,
        });
        throw error;
      }
    );
  }

  async getEmployeeDetails(employeeId: string): Promise<CorporateSystemResponse> {
    try {
      const response = await this.client.get(`/employees/${employeeId}`);
      return response.data;
    } catch (error) {
      logger.error('Failed to get employee details', { employeeId, error });
      throw error;
    }
  }

  async updateEmployeeStatus(employeeId: string, status: 'ACTIVE' | 'INACTIVE'): Promise<CorporateSystemResponse> {
    try {
      const response = await this.client.patch(`/employees/${employeeId}/status`, { status });
      return response.data;
    } catch (error) {
      logger.error('Failed to update employee status', { employeeId, status, error });
      throw error;
    }
  }
}

