// src/controllers/userController.ts - Type-safe controller with validation
import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { UserService } from '../services/userService';
import { CorporateIntegrationService } from '../services/corporateIntegration';
import { logger } from '../utils/logger';
import { AppError } from '../utils/appError';

const userService = new UserService();
const corporateIntegrationService = new CorporateIntegrationService();

const CreateUserRequestSchema = z.object({
  username: z.string().min(3).max(50),
  email: z.string().email(),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100),
  department: z.string().min(2).max(100),
  role: z.enum(['ADMIN', 'MANAGER', 'EMPLOYEE', 'CONTRACTOR']),
});

type CreateUserRequest = z.infer<typeof CreateUserRequestSchema>;

export class UserController {
  async createUser(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      // Validate request body
      const validatedData = CreateUserRequestSchema.parse(req.body);

      // Check if user exists in corporate system
      const corporateUser = await corporateIntegrationService.getEmployeeDetails(validatedData.username);

      if (!corporateUser) {
        throw new AppError('User not found in corporate system', 404);
      }

      // Create user in our system
      const newUser = await userService.createUser({
        ...validatedData,
        isActive: true,
      });

      logger.info('User created successfully', { userId: newUser.id });

      res.status(201).json({
        status: 'success',
        data: {
          user: newUser,
        },
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        return next(new AppError('Invalid request data', 400, error.errors));
      }
      next(error);
    }
  }

  async getUser(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const userId = req.params.id;

      if (!userId) {
        throw new AppError('User ID is required', 400);
      }

      const user = await userService.getUserById(userId);

      if (!user) {
        throw new AppError('User not found', 404);
      }

      res.status(200).json({
        status: 'success',
        data: {
          user,
        },
      });
    } catch (error) {
      next(error);
    }
  }
}
