// src/services/integrationService.ts
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { Logger } from 'winston';
import { AppError } from '../utils/appError';

interface ERPIntegrationResponse {
  status: string;
  message: string;
  data?: any;
}

export class IntegrationService {
  private erpClient: AxiosInstance;

  constructor(private logger: Logger) {
    this.erpClient = axios.create({
      baseURL: process.env.ERP_BASE_URL,
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${process.env.ERP_API_KEY}`
      }
    });

    // Add request interceptor
    this.erpClient.interceptors.request.use(config => {
      this.logger.info(`ERP Integration Request: ${config.method?.toUpperCase()} ${config.url}`);
      return config;
    });

    // Add response interceptor
    this.erpClient.interceptors.response.use(
      response => {
        this.logger.info(`ERP Integration Response: ${response.status} ${response.config.url}`);
        return response;
      },
      error => {
        this.logger.error(`ERP Integration Error: ${error.message}`);
        return Promise.reject(error);
      }
    );
  }

  async syncWithERP(payload: any): Promise<ERPIntegrationResponse> {
    try {
      const response: AxiosResponse<ERPIntegrationResponse> = await this.erpClient.post(
        '/api/integration/sync',
        payload
      );

      if (response.data.status !== 'success') {
        throw new AppError('ERP integration failed', 502);
      }

      return response.data;
    } catch (error) {
      this.logger.error('ERP integration error:', error);
      throw new AppError('Failed to integrate with ERP system', 502);
    }
  }

  async getERPData(endpoint: string): Promise<any> {
    try {
      const response = await this.erpClient.get(endpoint);
      return response.data;
    } catch (error) {
      this.logger.error(`Error fetching data from ERP endpoint ${endpoint}:`, error);
      throw new AppError(`Failed to fetch data from ERP endpoint ${endpoint}`, 502);
    }
  }
}
