  // Corporate system integrations
  await connectToCorporateSystems();

  // Application routes
  setupRoutes(app);

  // Error handling
  app.use(errorHandler);

  // Start server
  server.listen(config.port, () => {
    logger.info(`Server running on port ${config.port}`);
