## Corporate System Integration

```typescript
// src/integrations/corporateSystems.ts - Integration with corporate systems
import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { CorporateApiError } from '../errors/CorporateApiError';

interface CorporateSystemClient {
  getUserDetails(userId: string): Promise<UserDetails>;
  checkInventory(itemId: string): Promise<InventoryStatus>;
  // Add other corporate system methods as needed
}

interface UserDetails {
  id: string;
  name: string;
  department: string;
  accessLevel: 'basic' | 'standard' | 'admin' | 'superadmin';
}

interface InventoryStatus {
  itemId: string;
  availableQuantity: number;
  lastUpdated: Date;
}

class CorporateSystemClientImpl implements CorporateSystemClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      timeout: config.CORPORATE_API_TIMEOUT_MS,
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': config.CORPORATE_API_KEY
      }
    });

    // Add request interceptor
    this.client.interceptors.request.use(request => {
      logger.debug(`Corporate API request: ${request.method} ${request.url}`);
      return request;
    });

    // Add response interceptor
    this.client.interceptors.response.use(
      response => {
        logger.debug(`Corporate API response: ${response.status} ${response.config.url}`);
        return response;
      },
      error => {
        logger.error(`Corporate API error: ${error.message}`);
        throw new CorporateApiError(error.message, error.response?.status || 500);
      }
    );
  }

  async getUserDetails(userId: string): Promise<UserDetails> {
    const response = await this.client.get(`/users/${userId}`);
    return response.data as UserDetails;
  }

  async checkInventory(itemId: string): Promise<InventoryStatus> {
    const response = await this.client.get(`/inventory/${itemId}`);
    return {
      ...response.data,
      lastUpdated: new Date(response.data.lastUpdated)
    } as InventoryStatus;
  }
}

let corporateSystemClient: CorporateSystemClient;

export async function connectToCorporateSystems(): Promise<void> {
  if (!config.ENABLE_CORPORATE_INTEGRATION) {
    logger.info('Corporate system integration disabled');
    return;
  }

  try {
    corporateSystemClient = new CorporateSystemClientImpl();
    logger.info('Successfully connected to corporate systems');
  } catch (error) {
    logger.error('Failed to connect to corporate systems:', error);
    throw error;
  }
}

export function getCorporateSystemClient(): CorporateSystemClient {
  if (!corporateSystemClient) {
    throw new Error('Corporate system client not initialized');
  }
  return corporateSystemClient;
}
