```typescript
// src/errors/BaseError.ts - Base error class
export class BaseError extends Error {
  constructor(
    public message: string,
    public statusCode: number,
    public isOperational: boolean = true,
    public details?: any
  ) {
    super(message);
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

// src/errors/ServiceError.ts - Service-specific errors
export class ServiceError extends BaseError {
  constructor(message: string, statusCode: number, originalError?: Error) {
    super(message, statusCode, true, originalError?.message);
  }
}

// src/errors/CorporateApiError.ts - Corporate API errors
export class CorporateApiError extends BaseError {
  constructor(message: string, statusCode: number) {
    super(`Corporate API Error: ${message}`, statusCode, true);
  }
}

// src/middleware/errorHandler.ts - Global error handler
import { Request, Response, NextFunction } from 'express';
import { BaseError } from '../errors/BaseError';
import { logger } from '../utils/logger';

export function errorHandler(
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
) {
  if (err instanceof BaseError) {
    logger.error(`BaseError: ${err.message}`, {
      statusCode: err.statusCode,
      stack: err.stack,
      details: err.details
    });

    return res.status(err.statusCode).json({
      error: {
        message: err.message,
        details: err.details
      }
    });
  }

  // Handle other types of errors
  logger.error(`Unexpected error: ${err.message}`, {
    stack: err.stack
  });

  res.status(500).json({
    error: {
      message: 'An unexpected error occurred',
      details: process.env.NODE_ENV === 'development' ? err.message : undefined
    }
  });
}
