// src/health/healthChecks.ts - Health check endpoints
import { Router } from 'express';
import { getCorporateSystemClient } from '../integrations/corporateSystems';
import { logger } from '../utils/logger';

interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'unhealthy';
  checks: {
    [key: string]: {
      status: 'healthy' | 'degraded' | 'unhealthy';
      message?: string;
    };
  };
}

export function setupHealthChecks(app: Router) {
  const healthRouter = Router();

  healthRouter.get('/health/ready', async (req, res) => {
    try {
      // Check corporate system connectivity
      const corporateClient = getCorporateSystemClient();
      await corporateClient.getUserDetails('test');

      res.status(200).json({ status: 'ready' });
    } catch (error) {
      logger.error('Readiness check failed:', error);
      res.status(503).json({ status: 'not ready', error: error.message });
    }
  });

  healthRouter.get('/health/live', (req, res) => {
    res.status(200).json({ status: 'live' });
  });

  healthRouter.get('/health/detailed', async (req, res) => {
    const result: HealthCheckResult = {
      status: 'healthy',
      checks: {}
    };

    try {
      // Check corporate system connectivity
      const corporateClient = getCorporateSystemClient();
      await corporateClient.getUserDetails('test');
      result.checks.corporateSystem = { status: 'healthy' };
    } catch (error) {
      result.checks.corporateSystem = {
        status: 'unhealthy',
        message: error.message
      };
      result.status = 'unhealthy';
    }

    // Add other health checks as needed

    res.status(result.status === 'healthy' ? 200 : 503).json(result);
  });

  app.use('/health', healthRouter);
}
