### `src/integrations/erp/erp.service.ts`

```typescript
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios, { AxiosInstance } from 'axios';
import { Logger } from '@nestjs/common';
import { Order } from '../../orders/entities/order.entity';

@Injectable()
export class ERPIntegrationService {
  private readonly logger = new Logger(ERPIntegrationService.name);
  private readonly erpClient: AxiosInstance;

  constructor(private readonly configService: ConfigService) {
    this.erpClient = axios.create({
      baseURL: this.configService.get<string>('ERP_API_URL'),
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': this.configService.get<string>('ERP_API_KEY'),
      },
    });
  }

  async syncOrderToERP(order: Order): Promise<void> {
    try {
      this.logger.log(`Syncing order ${order.id} to ERP system`);

      const erpOrderPayload = this.mapOrderToERPFormat(order);

      const response = await this.erpClient.post('/orders', erpOrderPayload);

      if (response.status !== 201) {
        throw new HttpException(
          `Failed to sync order to ERP: ${response.statusText}`,
          HttpStatus.INTERNAL_SERVER_ERROR,
        );
      }

      this.logger.log(`Successfully synced order ${order.id} to ERP`);
    } catch (error) {
      this.logger.error(
        `Error syncing order ${order.id} to ERP: ${error.message}`,
        error.stack,
      );
      throw new HttpException(
        `ERP integration failed: ${error.message}`,
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  private mapOrderToERPFormat(order: Order): any {
    // Map our internal order format to ERP's expected format
    return {
      orderId: order.id,
      orderNumber: order.orderNumber,
      orderDate: order.orderDate.toISOString(),
      customerId: order.customerId,
      totalAmount: order.totalAmount,
      status: order.status,
      items: order.items.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        totalPrice: item.totalPrice,
      })),
    };
  }
}
