## API Controller with Type Safety

```typescript
// src/controllers/customer.controller.ts - Type-safe controller
import { Request, Response, NextFunction } from 'express';
import { Customer, CustomerSchema } from '../domain/models';
import { ICustomerRepository } from '../domain/repositories';
import { IntegrationServices } from '../integrations';
import { z } from 'zod';
import { AppError } from '../error-handling';

export class CustomerController {
  constructor(
    private customerRepository: ICustomerRepository,
    private integrations: IntegrationServices
  ) {}

  async createCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      // Validate input with Zod
      const validatedData = CustomerSchema.omit({
        id: true,
        createdAt: true,
        updatedAt: true,
        version: true,
      }).parse(req.body);

      // Get user from auth middleware
      const user = req.user as { id: string; email: string };

      // Create customer with audit info
      const customerToCreate: Omit<Customer, 'id' | 'createdAt' | 'updatedAt' | 'version'> = {
        ...validatedData,
        createdBy: user.email,
        updatedBy: user.email,
      };

      // Create in repository
      const createdCustomer = await this.customerRepository.create(customerToCreate);

      // Sync with SAP if needed
      if (this.integrations.sap) {
        await this.integrations.sap.syncCustomer(createdCustomer);
      }

      // Log audit event
      await this.integrations.audit.logEvent({
        action: 'CREATE_CUSTOMER',
        entityType: 'CUSTOMER',
        entityId: createdCustomer.id,
        userId: user.id,
        metadata: { customerName: createdCustomer.name }
      });

      res.status(201).json(createdCustomer);
    } catch (error) {
      if (error instanceof z.ZodError) {
        next(new AppError('VALIDATION_ERROR', 400, error.errors));
      } else {
        next(error);
      }
    }
  }

  async getCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const customerId = z.string().uuid().parse(req.params.id);

      const customer = await this.customerRepository.findById(customerId);

      if (!customer) {
        throw new AppError('CUSTOMER_NOT_FOUND', 404);
      }

      res.json(customer);
    } catch (error) {
      if (error instanceof z.ZodError) {
        next(new AppError('VALIDATION_ERROR', 400, error.errors));
      } else {
