```typescript
// src/database/index.ts - Type-safe database layer
import { Pool, PoolClient } from 'pg';
import { Customer, CustomerSchema } from '../domain/models';
import { ICustomerRepository } from '../domain/repositories';
import { z } from 'zod';

export class PostgreSQLCustomerRepository implements ICustomerRepository {
  private pool: Pool;

  constructor(config: any) {
    this.pool = new Pool(config.postgres);
  }

  async create(customer: Omit<Customer, 'id' | 'createdAt' | 'updatedAt' | 'version'>): Promise<Customer> {
    const client = await this.pool.connect();

    try {
      await client.query('BEGIN');

      const result = await client.query(
        `INSERT INTO customers
         (name, email, status, created_by, updated_by, metadata)
         VALUES ($1, $2, $3, $4, $5, $6)
         RETURNING *`,
        [
          customer.name,
          customer.email,
          customer.status,
          customer.createdBy,
          customer.updatedBy,
          customer.metadata ? JSON.stringify(customer.metadata) : null
        ]
      );

      const createdCustomer = this.mapRowToCustomer(result.rows[0]);

      await client.query('COMMIT');

      return createdCustomer;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async findById(id: string): Promise<Customer | null> {
    const client = await this.pool.connect();

    try {
      const result = await client.query(
        'SELECT * FROM customers WHERE id = $1',
        [id]
      );

      if (result.rows.length === 0) {
        return null;
      }

      return this.mapRowToCustomer(result.rows[0]);
    } finally {
      client.release();
    }
  }

  // Other repository methods...

  private mapRowToCustomer(row: any): Customer {
    try {
      return CustomerSchema.parse({
        id: row.id,
        name: row.name,
        email: row.email,
        status: row.status,
        createdBy: row.created_by,
        updatedBy: row.updated_by,
        createdAt: new Date(row.created_at),
        updatedAt: new Date(row.updated_at),
        version: row.version,
        metadata: row.metadata ? JSON.parse(row.metadata) : undefined
      });
    } catch (error) {
      if (error instanceof z.ZodError) {
        throw new Error(`Database row validation failed: ${error.message}`);
      }
      throw error;
    }
  }
}
