## Security and Authentication

```typescript
// src/security/index.ts - Enterprise security setup
import express from 'express';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import cors from 'cors';
import { expressjwt } from 'express-jwt';
import { IdentityProviderService } from '../integrations/identity-provider';

export function setupSecurity(app: express.Application, config: any): void {
  // Security headers
  app.use(helmet());

  // CORS configuration
  app.use(cors({
    origin: config.allowedOrigins || [],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true
  }));

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: config.rateLimit || 100,
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);

  // JWT authentication
  app.use(expressjwt({
    secret: config.jwtSecret,
    algorithms: ['RS256'],
    issuer: config.jwtIssuer,
    audience: config.jwtAudience,
    requestProperty: 'auth',
    getToken: (req) => {
      if (req.headers.authorization?.split(' ')[0] === 'Bearer') {
        return req.headers.authorization.split(' ')[1];
      }
      return null;
    }
  }).unless({
    path: [
      '/health',
      '/metrics',
      '/api-docs',
      { url: '/auth/login', methods: ['POST'] }
    ]
  }));

  // User context middleware
  app.use(async (req, res, next) => {
    if (req.auth?.sub) {
      try {
        const identityService = new IdentityProviderService(config.identity);
        const user = await identityService.getUserById(req.auth.sub);

        if (!user) {
          return res.status(401).json({ error: 'User not found' });
        }

        req.user = {
          id: user.id,
          email: user.email,
          roles: user.roles,
          permissions: user.permissions
        };
      } catch (error) {
        return res.status(500).json({ error: 'Authentication service error' });
      }
    }
    next();
  });

  // Role-based access control
  app.use((req, res, next) => {
    if (req.user && req.user.roles) {
      res.locals.userRoles = req.user.roles;
    }
    next();
  });
}
