## Error Handling

```typescript
// src/error-handling/index.ts - Comprehensive error handling
import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { AppError } from './app-error';

export function setupErrorHandling(app: express.Application): void {
  // 404 handler
  app.use((req: Request, res: Response, next: NextFunction) => {
    const error = new AppError('ROUTE_NOT_FOUND', 404);
    next(error);
  });

  // Global error handler
  app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
    // Handle Zod validation errors
    if (err instanceof ZodError) {
      return res.status(400).json({
        error: 'VALIDATION_ERROR',
        details: err.errors.map(e => ({
          path: e.path.join('.'),
          message: e.message
        }))
      });
    }

    // Handle known application errors
    if (err instanceof AppError) {
      return res.status(err.statusCode).json({
        error: err.code,
        message: err.message,
        details: err.details
      });
    }

    // Handle JWT errors
    if (err.name === 'UnauthorizedError') {
      return res.status(401).json({
        error: 'UNAUTHORIZED',
        message: 'Invalid or missing authentication token'
      });
    }

    // Handle other errors
    console.error('Unhandled error:', err);

    // Don't expose stack traces in production
    const response = process.env.NODE_ENV === 'production'
      ? { error: 'INTERNAL_SERVER_ERROR', message: 'An unexpected error occurred' }
      : { error: 'INTERNAL_SERVER_ERROR', message: err.message, stack: err.stack };

    res.status(500).json(response);
  });
}

export class AppError extends Error {
  constructor(
    public code: string,
    public statusCode: number,
    public details?: any,
    public originalError?: Error
  ) {
    super(`${code}: ${originalError?.message || 'Unknown error'}`);
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}
