## Event Bus for Asynchronous Communication

```typescript
// src/event-bus/index.ts - Type-safe event bus
import { EventEmitter } from 'events';
import { z } from 'zod';

export interface EventBus {
  publish<T extends EventType>(event: T): Promise<void>;
  subscribe<T extends EventType>(eventType: T['type'], handler: (event: T) => Promise<void>): void;
  unsubscribe<T extends EventType>(eventType: T['type'], handler: (event: T) => Promise<void>): void;
}

export type EventType = CustomerCreatedEvent | OrderProcessedEvent | PaymentReceivedEvent;

const CustomerCreatedEventSchema = z.object({
  type: z.literal('CustomerCreated'),
  payload: z.object({
    customerId: z.string().uuid(),
    name: z.string(),
    email: z.string().email(),
    createdBy: z.string().email(),
    timestamp: z.string().datetime()
  })
});

const OrderProcessedEventSchema = z.object({
  type: z.literal('OrderProcessed'),
  payload: z.object({
    orderId: z.string().uuid(),
    customerId: z.string().uuid(),
    amount: z.number().positive(),
    status: z.enum(['PENDING', 'COMPLETED', 'FAILED']),
    timestamp: z.string().datetime()
  })
});

const PaymentReceivedEventSchema = z.object({
  type: z.literal('PaymentReceived'),
  payload: z.object({
    paymentId: z.string().uuid(),
    orderId: z.string().uuid(),
    amount: z.number().positive(),
    currency: z.string().length(3),
    status: z.enum(['PENDING', 'COMPLETED', 'FAILED']),
    timestamp: z.string().datetime()
  })
});

type CustomerCreatedEvent = z.infer<typeof CustomerCreatedEventSchema>;
type OrderProcessedEvent = z.infer<typeof OrderProcessedEventSchema>;
type PaymentReceivedEvent = z.infer<typeof PaymentReceivedEventSchema>;

export class InMemoryEventBus implements EventBus {
  private emitter = new EventEmitter();

  async publish<T extends EventType>(event: T): Promise<void> {
    // Validate event structure
    let validatedEvent: T;
    switch (event.type) {
      case 'CustomerCreated':
        validatedEvent = CustomerCreatedEventSchema.parse(event) as T;
        break;
      case 'OrderProcessed':
        validatedEvent = OrderProcessedEventSchema.parse(event) as T;
        break;
      case 'PaymentReceived':
        validatedEvent = PaymentReceivedEventSchema.parse(event) as T;
        break;
      default:
        throw new Error(`Unknown event type: ${(event as any).type}`);
    }

    this.emitter.emit(validatedEvent.type, validatedEvent);
  }

  subscribe<T extends EventType>(eventType: T['type'], handler: (event: T) => Promise<void>): void {
    this.emitter.on(eventType, handler);
  }

  unsubscribe<T extends EventType>(eventType: T['type'], handler: (event: T) => Promise<void>): void {
    this.emitter.off(eventType, handler);
  }
}
