  getEmployeeById(employeeId: string): Promise<Employee>;
  getPayrollData(employeeId: string, payPeriod: string): Promise<PayrollData>;
  updateEmployeeStatus(employeeId: string, status: Employee['status']): Promise<void>;
}

class CorporateSystemIntegration implements CorporateSystemClient {
  private client: AxiosInstance;
  private rateLimiter: RateLimiter;

  constructor(private readonly config: CorporateSystemConfig) {
    this.client = axios.create({
      baseURL: config.baseURL,
      timeout: config.timeout,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.apiKey}`,
        'X-Service-Name': 'enterprise-microservice',
      },
    });

    this.rateLimiter = new RateLimiter({
      maxRequests: config.rateLimit.maxRequests,
      windowMs: config.rateLimit.windowMs,
    });

    // Request interceptor for logging and rate limiting
    this.client.interceptors.request.use(async (config) => {
      await this.rateLimiter.consume();
      logger.debug('Making request to corporate system', {
        url: config.url,
        method: config.method,
      });
      return config;
    });

    // Response interceptor for error handling
    this.client.interceptors.response.use(
      (response) => response,
      (error) => {
        logger.error('Corporate system request failed', {
          message: error.message,
          config: error.config,
          response: error.response?.data,
        });
        throw new IntegrationError('Corporate system integration failed');
      }
    );
  }

  async getEmployeeById(employeeId: string): Promise<Employee> {
    try {
      const response = await this.client.get<Employee>(`/employees/${employeeId}`);
      return this.validateEmployee(response.data);
    } catch (error) {
      logger.error('Failed to get employee from corporate system', { employeeId, error });
      throw error;
    }
