        payPeriod,
        error,
      });
      throw error;
    }
  }

  async updateEmployeeStatus(employeeId: string, status: Employee['status']): Promise<void> {
    try {
      await this.client.patch(`/employees/${employeeId}/status`, { status });
    } catch (error) {
      logger.error('Failed to update employee status in corporate system', {
        employeeId,
        status,
        error,
      });
      throw error;
    }
  }

  private validateEmployee(data: any): Employee {
    // Implement strict validation
    if (!data.id || typeof data.id !== 'string') {
      throw new IntegrationError('Invalid employee ID');
    }
    if (!data.name || typeof data.name !== 'string') {
      throw new IntegrationError('Invalid employee name');
    }
    // Add more validations as needed
    return data as Employee;
  }

  private validatePayrollData(data: any): PayrollData {
    // Implement strict validation
    if (!data.employeeId || typeof data.employeeId !== 'string') {
      throw new IntegrationError('Invalid payroll employee ID');
    }
    if (!data.payPeriod || typeof data.payPeriod !== 'string') {
      throw new IntegrationError('Invalid pay period');
    }
    // Add more validations as needed
    return data as PayrollData;
  }
}

