```typescript
// src/services/employee-service.ts
import { Employee, corporateSystemClient } from '../integrations/corporate-systems';
import { UserRepository, User } from '../database';
import { logger } from '../utils/logger';
import { ServiceError } from '../errors';

interface EmployeeService {
  getEmployeeDetails(employeeId: string): Promise<EmployeeDetails>;
  updateEmployeeStatus(employeeId: string, status: Employee['status']): Promise<void>;
}

interface EmployeeDetails {
  employee: Employee;
  user: User | null;
  payrollHistory: PayrollSummary[];
}

interface PayrollSummary {
  payPeriod: string;
  netPay: number;
  deductionsTotal: number;
}

class EmployeeServiceImpl implements EmployeeService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly corporateSystem: typeof corporateSystemClient
  ) {}

  async getEmployeeDetails(employeeId: string): Promise<EmployeeDetails> {
    try {
      // Parallelize independent requests
      const [employee, user, payrollHistory] = await Promise.all([
        this.corporateSystem.getEmployeeById(employeeId),
        this.userRepository.findById(employeeId),
        this.getPayrollHistory(employeeId),
      ]);

      return {
        employee,
        user,
        payrollHistory,
      };
    } catch (error) {
      logger.error('Failed to get employee details', { employeeId, error });
      throw new ServiceError('Failed to retrieve employee details');
    }
  }

  async updateEmployeeStatus(employeeId: string, status: Employee['status']): Promise<void> {
    try {
      // Validate status transition
      const currentEmployee = await this.corporateSystem.getEmployeeById(employeeId);
      this.validateStatusTransition(currentEmployee.status, status);

      await this.corporateSystem.updateEmployeeStatus(employeeId, status);

      // Log the status change
      logger.info('Employee status updated', {
        employeeId,
        oldStatus: currentEmployee.status,
        newStatus: status,
      });
    } catch (error) {
      logger.error('Failed to update employee status', { employeeId, status, error });
      throw new ServiceError('Failed to update employee status');
    }
  }

  private async getPayrollHistory(employeeId: string): Promise<PayrollSummary[]> {
    // Get last 3 pay periods
    const payPeriods = this.getRecentPayPeriods(3);
    const results = await Promise.allSettled(
      payPeriods.map(period =>
        this.corporateSystem.getPayrollData(employeeId, period)
      )
    );

    return results
      .filter((result): result is PromiseFulfilledResult<PayrollData> =>
        result.status === 'fulfilled'
      )
      .map(result => ({
        payPeriod: result.value.payPeriod,
        netPay: result.value.netPay,
        deductionsTotal: result.value.deductions.reduce(
          (sum, deduction) => sum + deduction.amount,
          0
        ),
      }));
  }

  private getRecentPayPeriods(count: number): string[] {
    // Implement logic to get recent pay periods
    // This is a simplified example
    const periods: string[] = [];
    const now = new Date();
    for (let i = 0; i < count; i++) {
      const month = now.getMonth() - i;
      const year = now.getFullYear();
      periods.push(`${year}-${String(month + 1).padStart(2, '0')}`);
    }
    return periods;
  }

  private validateStatusTransition(current: Employee['status'], next: Employee['status']): void {
    const validTransitions: Record<Employee['status'], Employee['status'][]> = {
      active: ['inactive', 'on_leave'],
      inactive: ['active'],
      on_leave: ['active', 'inactive'],
    };

    if (!validTransitions[current].includes(next)) {
      throw new ServiceError(`Invalid status transition from ${current} to ${next}`);
    }
  }
}

export const employeeService = new EmployeeServiceImpl(
  new UserRepository(),
  corporateSystemClient
);
