## Middleware for Security and Validation

```typescript
// src/middleware/index.ts
import express, { Express } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import { config } from '../config';
import { logger } from '../utils/logger';
import { AppError } from '../errors';

export function setupMiddleware(app: Express): void {
  // Security middleware
  app.use(helmet());
  app.use(cors({
    origin: config.ALLOWED_ORIGINS || '*',
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  }));

  // Request parsing
  app.use(express.json({ limit: config.MAX_REQUEST_SIZE }));
  app.use(express.urlencoded({ extended: true, limit: config.MAX_REQUEST_SIZE }));

  // Rate limiting
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later',
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);

  // Request logging
  app.use((req, res, next) => {
    logger.info('Incoming request', {
      method: req.method,
      path: req.path,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
    });
    next();
  });

  // API key validation for corporate systems
  app.use('/api/corporate', (req, res, next) => {
    const apiKey = req.headers['x-api-key'];
    if (apiKey !== config.CORPORATE_API_KEY) {
      throw new AppError('Unauthorized access to corporate API', 401);
    }
    next();
  });
}
