```typescript
// src/health/index.ts
import { Express, Request, Response } from 'express';
import { config } from '../config';
import { query } from '../database';
import { logger } from '../utils/logger';

interface HealthCheckResult {
  status: 'healthy' | 'unhealthy';
  details?: Record<string, any>;
}

export function setupHealthChecks(app: Express): void {
  app.get('/health/ready', async (req: Request, res: Response) => {
    try {
      // Check database connectivity
      await query('SELECT 1');

      res.status(200).json({
        status: 'healthy',
        environment: config.NODE_ENV,
        timestamp: new Date().toISOString(),
      });
    } catch (error) {
      logger.error('Readiness check failed', error);
      res.status(503).json({
        status: 'unhealthy',
        error: 'Database connectivity check failed',
      });
    }
  });

  app.get('/health/live', (req: Request, res: Response) => {
    res.status(200).json({
      status: 'healthy',
      environment: config.NODE_ENV,
      timestamp: new Date().toISOString(),
    });
  });

  app.get('/health/details', async (req: Request, res: Response) => {
    const healthChecks: Record<string, HealthCheckResult> = {};

    // Database check
    try {
      await query('SELECT 1');
      healthChecks.database = { status: 'healthy' };
    } catch (error) {
      healthChecks.database = {
        status: 'unhealthy',
        details: { error: error instanceof Error ? error.message : 'Unknown error' },
      };
    }

    // Cache check (example)
    healthChecks.cache = { status: 'healthy' };

    // Corporate system integration check
    healthChecks.corporateSystem = { status: 'healthy' };

    const overallStatus = Object.values(healthChecks).every(check => check.status === 'healthy')
      ? 'healthy'
      : 'unhealthy';

    res.status(overallStatus === 'healthy' ? 200 : 503).json({
      status: overallStatus,
      checks: healthChecks,
      environment: config.NODE_ENV,
      timestamp: new Date().toISOString(),
    });
  });
}
