```typescript
// src/modules/integrations/sap/sap.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { AxiosRequestConfig } from 'axios';
import { SAPIntegrationConfig } from './interfaces/sap-integration-config.interface';
import { SAPOrder } from './interfaces/sap-order.interface';

@Injectable()
export class SAPIntegrationService {
  private readonly logger = new Logger(SAPIntegrationService.name);
  private readonly sapConfig: SAPIntegrationConfig;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.sapConfig = {
      baseUrl: this.configService.get<string>('SAP_BASE_URL'),
      clientId: this.configService.get<string>('SAP_CLIENT_ID'),
      clientSecret: this.configService.get<string>('SAP_CLIENT_SECRET'),
      authUrl: this.configService.get<string>('SAP_AUTH_URL'),
      apiKey: this.configService.get<string>('SAP_API_KEY'),
    };
  }

  private async getAuthToken(): Promise<string> {
    const authUrl = `${this.sapConfig.authUrl}/oauth/token`;
    const params = new URLSearchParams();
    params.append('grant_type', 'client_credentials');

    const config: AxiosRequestConfig = {
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: `Basic ${Buffer.from(`${this.sapConfig.clientId}:${this.sapConfig.clientSecret}`).toString('base64')}`,
      },
    };

    try {
      const response = await firstValueFrom(
        this.httpService.post(authUrl, params, config),
      );

      return response.data.access_token;
    } catch (error) {
      this.logger.error(`Failed to authenticate with SAP: ${error.message}`);
      throw new Error('SAP authentication failed');
    }
  }

  async getOrder(orderId: string): Promise<SAPOrder> {
    const token = await this.getAuthToken();
    const url = `${this.sapConfig.baseUrl}/sap/opu/odata/sap/API_SALES_ORDER_SRV/A_SalesOrder('${orderId}')`;

    const config: AxiosRequestConfig = {
      headers: {
        Authorization: `Bearer ${token}`,
        'APIKey': this.sapConfig.apiKey,
        'Accept': 'application/json',
      },
    };

    try {
      const response = await firstValueFrom(
        this.httpService.get(url, config),
      );

      return response.data.d as SAPOrder;
    } catch (error) {
      this.logger.error(`Failed to fetch order ${orderId} from SAP: ${error.message}`);
      throw new Error(`Failed to fetch order ${orderId}`);
    }
  }

  async createOrder(orderData: Partial<SAPOrder>): Promise<SAPOrder> {
    const token = await this.getAuthToken();
    const url = `${this.sapConfig.baseUrl}/sap/opu/odata/sap/API_SALES_ORDER_SRV/A_SalesOrder`;

    const config: AxiosRequestConfig = {
      headers: {
        Authorization: `Bearer ${token}`,
        'APIKey': this.sapConfig.apiKey,
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
    };

    try {
      const response = await firstValueFrom(
        this.httpService.post(url, orderData, config),
      );

      return response.data.d as SAPOrder;
    } catch (error) {
      this.logger.error(`Failed to create order in SAP: ${error.message}`);
      throw new Error('Failed to create order in SAP');
    }
  }
}
