## Integration with ERP System

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios, { AxiosInstance } from 'axios';
import { Order } from '../../orders/entities/order.entity';

@Injectable()
export class ERPService {
  private readonly logger = new Logger(ERPService.name);
  private readonly erpClient: AxiosInstance;

  constructor(private configService: ConfigService) {
    this.erpClient = axios.create({
      baseURL: this.configService.get<string>('ERP_API_URL'),
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.configService.get<string>('ERP_API_KEY')}`,
      },
    });
  }

  async syncOrderToERP(order: Order): Promise<void> {
    try {
      this.logger.log(`Syncing order ${order.id} to ERP system`);

      const erpOrder = this.mapToERPOrder(order);

      const response = await this.erpClient.post('/orders', erpOrder);

      if (response.status !== 201) {
        throw new Error(`ERP sync failed with status ${response.status}`);
      }

      this.logger.log(`Successfully synced order ${order.id} to ERP`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to ERP`, error.stack);
      throw error;
    }
  }

  private mapToERPOrder(order: Order): any {
    // Map our domain model to ERP's expected format
    return {
      orderId: order.id,
      customerId: order.customerId,
      orderDate: order.orderDate,
      status: order.status,
      items: order.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
    };
  }
}
