## Service Layer with Strict Typing

```typescript
// src/orders/orders.service.ts
import { Injectable, Inject, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { OrderRepository } from './repositories/order.repository';
import { OrderItemRepository } from './repositories/order-item.repository';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { Order } from './entities/order.entity';
import { OrderItem } from './entities/order-item.entity';
import { OrderStatus } from './enums/order-status.enum';
import { ClientProxy } from '@nestjs/microservices';
import { lastValueFrom } from 'rxjs';
import { RedisService } from '@nestjs-modules/ioredis';

@Injectable()
export class OrdersService {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    @InjectRepository(OrderRepository)
    private readonly orderRepository: OrderRepository,
    @InjectRepository(OrderItemRepository)
    private readonly orderItemRepository: OrderItemRepository,
    @Inject('BILLING_SERVICE') private readonly billingClient: ClientProxy,
    private readonly redisService: RedisService,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for user ${createOrderDto.userId}`);

    const order = this.orderRepository.create({
      ...createOrderDto,
      status: OrderStatus.PENDING,
    });

    const savedOrder = await this.orderRepository.save(order);

    // Save order items
    const orderItems = createOrderDto.items.map((item) =>
      this.orderItemRepository.create({
        ...item,
        order: savedOrder,
      }),
    );

    await this.orderItemRepository.save(orderItems);

    // Publish order created event to Kafka
    this.billingClient.emit('order_created', {
      orderId: savedOrder.id,
      userId: savedOrder.userId,
      totalAmount: savedOrder.totalAmount,
      currency: savedOrder.currency,
    });

    // Cache the order
    await this.redisService.set(
      `order:${savedOrder.id}`,
      JSON.stringify(savedOrder),
      'EX',
      3600, // 1 hour expiration
    );

    return savedOrder;
  }

  async findAll(): Promise<Order[]> {
    this.logger.log('Fetching all orders');
    return this.orderRepository.find({ relations: ['items'] });
  }

  async findOne(id: string): Promise<Order> {
    this.logger.log(`Fetching order with ID ${id}`);

    // Try to get from cache first
    const cachedOrder = await this.redisService.get(`order:${id}`);
    if (cachedOrder) {
      this.logger.log(`Order ${id} found in cache`);
      return JSON.parse(cachedOrder);
    }

    const order = await this.orderRepository.findOne({
      where: { id },
      relations: ['items'],
    });

    if (!order) {
      throw new Error(`Order with ID ${id} not found`);
    }

    // Cache the order
    await this.redisService.set(
      `order:${id}`,
      JSON.stringify(order),
      'EX',
      3600, // 1 hour expiration
    );

    return order;
  }

  async update(id: string, updateOrderDto: UpdateOrderDto): Promise<Order> {
    this.logger.log(`Updating order with ID ${id}`);

    const order = await this.findOne(id);

    if (!order) {
      throw new Error(`Order with ID ${id} not found`);
    }

    // Update order status if provided
    if (updateOrderDto.status) {
      order.status = updateOrderDto.status;
    }

    // Update total amount if provided
    if (updateOrderDto.totalAmount !== undefined) {
      order.totalAmount = updateOrderDto.totalAmount;
    }

    // Update order items if provided
    if (updateOrderDto.items) {
      // Delete existing items
      await this.orderItemRepository.delete({ order: { id: order.id } });

      // Create new items
      const orderItems = updateOrderDto.items.map((item) =>
        this.orderItemRepository.create({
          ...item,
          order,
        }),
      );

      await this.orderItemRepository.save(orderItems);
    }

    const updatedOrder = await this.orderRepository.save(order);

    // Publish order updated event to Kafka
    this.billingClient.emit('order_updated', {
      orderId: updatedOrder.id,
      userId: updatedOrder.userId,
      totalAmount: updatedOrder.totalAmount,
      currency: updatedOrder.currency,
      status: updatedOrder.status,
    });

    // Update cache
    await this.redisService.set(
      `order:${updatedOrder.id}`,
      JSON.stringify(updatedOrder),
      'EX',
      3600, // 1 hour expiration
    );

    return updatedOrder;
  }

  async remove(id: string): Promise<void> {
    this.logger.log(`Removing order with ID ${id}`);

    const order = await this.findOne(id);

    if (!order) {
      throw new Error(`Order with ID ${id} not found`);
    }

    // Delete order items first
    await this.orderItemRepository.delete({ order: { id: order.id } });

    // Delete the order
    await this.orderRepository.remove(order);

    // Publish order deleted event to Kafka
    this.billingClient.emit('order_deleted', {
      orderId: order.id,
      userId: order.userId,
    });

    // Remove from cache
    await this.redisService.del(`order:${id}`);
  }

  async processPayment(orderId: string): Promise<Order> {
    this.logger.log(`Processing payment for order ${orderId}`);

    const order = await this.findOne(orderId);

    if (!order) {
      throw new Error(`Order with ID ${orderId} not found`);
    }

    // Call billing service via gRPC
    const result = await lastValueFrom(
      this.billingClient.send({ cmd: 'process_payment' }, { orderId }),
    );

    if (result.success) {
      order.status = OrderStatus.PAID;
      const updatedOrder = await this.orderRepository.save(order);

      // Update cache
      await this.redisService.set(
        `order:${updatedOrder.id}`,
        JSON.stringify(updatedOrder),
        'EX',
        3600, // 1 hour expiration
      );

      return updatedOrder;
    } else {
      throw new Error(`Payment processing failed: ${result.message}`);
    }
  }
}
