interface GetOrderResponse {
  order: Order | null;
}

@Controller()
export class OrderGrpcController {
  private readonly logger = new Logger(OrderGrpcController.name);

  constructor(private readonly ordersService: OrdersService) {}

  @GrpcMethod('OrderService', 'GetOrder')
  async getOrder(data: GetOrderRequest): Promise<GetOrderResponse> {
    this.logger.log(`Received gRPC request to get order ${data.id}`);
    try {
      const order = await this.ordersService.findOne(data.id);
      return { order };
    } catch (error) {
      this.logger.error(`Error getting order ${data.id}: ${error.message}`);
      return { order: null };
    }
  }
}
