Below is a comprehensive implementation of a backend microservice for a large enterprise with strict type safety requirements and integration with existing corporate systems. This example uses TypeScript, NestJS (a Node.js framework), and integrates with common enterprise systems like LDAP, database, and message queues.

## Core Microservice Implementation

```typescript
// src/main.ts
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { Logger } from 'nestjs-pino';
import * as helmet from 'helmet';
import * as rateLimit from 'express-rate-limit';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['error', 'warn', 'log', 'debug', 'verbose'],
  });

  // Security middleware
  app.use(helmet());
  app.use(
    rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // limit each IP to 100 requests per windowMs
    }),
  );

  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      transform: true,
      whitelist: true,
      forbidNonWhitelisted: true,
    }),
  );

  // API documentation
  const config = new DocumentBuilder()
    .setTitle('Enterprise Microservice API')
    .setDescription('API for enterprise corporate systems integration')
    .setVersion('1.0')
    .addBearerAuth()
    .build();
  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);

  // Logger
  app.useLogger(app.get(Logger));

  await app.listen(process.env.PORT || 3000);
}
bootstrap();
