## Enterprise Authentication System

```typescript
// src/auth/auth.service.ts
import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { UsersService } from '../users/users.service';
import { CorporateSystemsService } from '../corporate-systems/corporate-systems.service';
import * as bcrypt from 'bcrypt';

@Injectable()
export class AuthService {
  constructor(
    private usersService: UsersService,
    private jwtService: JwtService,
    private configService: ConfigService,
    private corporateSystemsService: CorporateSystemsService,
  ) {}

  async validateUser(email: string, pass: string): Promise<any> {
    const user = await this.usersService.findByEmail(email);
    if (user && (await bcrypt.compare(pass, user.passwordHash))) {
      const { passwordHash, ...result } = user;
      return result;
    }
    return null;
  }

  async login(user: any) {
    // Verify with corporate LDAP system
    const ldapUser = await this.corporateSystemsService.verifyLdapUser(user.email);

    if (!ldapUser) {
      throw new UnauthorizedException('User not authorized in corporate systems');
    }

    const payload = {
      username: user.email,
      sub: user.id,
      employeeId: user.employeeId,
      roles: ldapUser.roles,
      departments: ldapUser.departments,
    };

    return {
      access_token: this.jwtService.sign(payload),
      expires_in: this.configService.get('JWT_EXPIRES_IN'),
    };
  }

  async validateToken(token: string) {
    try {
      return this.jwtService.verify(token);
    } catch (e) {
      throw new UnauthorizedException('Invalid or expired token');
    }
  }
}
