## Corporate Systems Integration Layer

```typescript
// src/corporate-systems/corporate-systems.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ClientProxyFactory, Transport } from '@nestjs/microservices';
import { firstValueFrom } from 'rxjs';
import { LdapClient } from 'ldapjs';
import { DatabaseClient } from './clients/database.client';
import { MessageQueueClient } from './clients/message-queue.client';

@Injectable()
export class CorporateSystemsService {
  private readonly logger = new Logger(CorporateSystemsService.name);
  private ldapClient: LdapClient;
  private databaseClient: DatabaseClient;
  private messageQueueClient: MessageQueueClient;

  constructor(private configService: ConfigService) {
    this.initializeClients();
  }

  private initializeClients() {
    // Initialize LDAP client
    this.ldapClient = new LdapClient({
      url: this.configService.get('LDAP_URL'),
    });

    // Initialize database client
    this.databaseClient = new DatabaseClient({
      host: this.configService.get('DB_HOST'),
      port: this.configService.get('DB_PORT'),
      username: this.configService.get('DB_USERNAME'),
      password: this.configService.get('DB_PASSWORD'),
      database: this.configService.get('DB_NAME'),
    });

    // Initialize message queue client
    this.messageQueueClient = new MessageQueueClient(
      ClientProxyFactory.create({
        transport: Transport.RMQ,
        options: {
          urls: [this.configService.get('RABBITMQ_URL')],
          queue: this.configService.get('RABBITMQ_QUEUE'),
          queueOptions: {
            durable: true,
          },
        },
      }),
    );
  }

  async verifyLdapUser(email: string): Promise<{ roles: string[]; departments: string[] }> {
    try {
      const result = await this.ldapClient.search(email);
      if (!result) {
        throw new Error('User not found in LDAP');
      }

      return {
        roles: result.roles || [],
        departments: result.departments || [],
      };
    } catch (error) {
      this.logger.error(`LDAP verification failed for ${email}: ${error.message}`);
      throw error;
    }
  }

  async getCorporateData(employeeId: string): Promise<any> {
    try {
      const data = await this.databaseClient.query(
        'SELECT * FROM corporate_data WHERE employee_id = $1',
        [employeeId],
      );
      return data;
    } catch (error) {
      this.logger.error(`Database query failed for ${employeeId}: ${error.message}`);
      throw error;
    }
  }

  async publishEvent(eventType: string, payload: any): Promise<void> {
    try {
      await firstValueFrom(
        this.messageQueueClient.send(eventType, payload).pipe(
          // Handle response if needed
        ),
      );
    } catch (error) {
      this.logger.error(`Failed to publish event ${eventType}: ${error.message}`);
      throw error;
    }
  }
}
