Below is a comprehensive implementation of a backend microservice for a large enterprise with strict type safety requirements and integration capabilities. This example uses TypeScript with NestJS framework, which is well-suited for enterprise applications.

## Core Microservice Implementation

```typescript
// src/main.ts
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { ConfigService } from '@nestjs/config';
import { WinstonModule } from 'nest-winston';
import * as winston from 'winston';
import { Transport, MicroserviceOptions } from '@nestjs/microservices';

async function bootstrap() {
  // Configure Winston logger for enterprise-grade logging
  const logger = WinstonModule.createLogger({
    transports: [
      new winston.transports.Console({
        format: winston.format.combine(
          winston.format.timestamp(),
          winston.format.json(),
        ),
      }),
      new winston.transports.File({
        filename: 'logs/error.log',
        level: 'error',
        format: winston.format.combine(
          winston.format.timestamp(),
          winston.format.json(),
        ),
      }),
      new winston.transports.File({
        filename: 'logs/combined.log',
        format: winston.format.combine(
          winston.format.timestamp(),
          winston.format.json(),
        ),
      }),
    ],
  });

  const app = await NestFactory.create(AppModule, {
    logger,
    cors: false, // Disable CORS by default for security
  });

  // Get configuration service
  const configService = app.get(ConfigService);

  // Enable global validation pipe with strict DTO validation
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      transformOptions: {
        enableImplicitConversion: true,
      },
    }),
  );

  // Configure Swagger for API documentation (optional in production)
  if (configService.get('NODE_ENV') !== 'production') {
    const config = new DocumentBuilder()
      .setTitle('Enterprise Microservice API')
      .setDescription('API documentation for enterprise microservice')
      .setVersion('1.0')
      .addBearerAuth()
      .build();

    const document = SwaggerModule.createDocument(app, config);
    SwaggerModule.setup('api', app, document);
  }

  // Configure microservice transport (Kafka example)
  app.connectMicroservice<MicroserviceOptions>({
    transport: Transport.KAFKA,
    options: {
      client: {
        brokers: [configService.get('KAFKA_BROKER')],
      },
      consumer: {
        groupId: configService.get('KAFKA_CONSUMER_GROUP'),
      },
    },
  });

  // Start both HTTP and microservice transports
  await app.startAllMicroservices();
  await app.listen(configService.get('PORT') || 3000);

  logger.log(`Application is running on: ${await app.getUrl()}`);
}

bootstrap();
```

