## ERP Integration Service Example

```typescript
// src/integration/services/erp-integration.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { ConfigService } from '@nestjs/config';
import { firstValueFrom } from 'rxjs';
import { IntegrationLog } from '../entities/integration-log.entity';
import { IntegrationRepository } from '../repositories/integration.repository';
import { IntegrationMapper } from '../mappers/integration.mapper';
import { IntegrationValidator } from '../validators/integration.validator';
import { AxiosError } from 'axios';

@Injectable()
export class ERPIntegrationService {
  private readonly logger = new Logger(ERPIntegrationService.name);

  constructor(
    private readonly httpService: HttpService,
    private readonly configService: ConfigService,
    private readonly integrationRepository: IntegrationRepository,
    private readonly integrationMapper: IntegrationMapper,
    private readonly integrationValidator: IntegrationValidator,
  ) {}

  async syncProduct(productData: any): Promise<{ success: boolean; message: string }> {
    const erpEndpoint = this.configService.get('ERP_PRODUCT_ENDPOINT');
    const authToken = this.configService.get('ERP_AUTH_TOKEN');

    try {
      // Validate input data
      this.integrationValidator.validateProductData(productData);

      // Map to ERP format
      const erpProductData = this.integrationMapper.mapToERPProduct(productData);

      // Log the integration attempt
      const integrationLog = new IntegrationLog();
      integrationLog.system = 'ERP';
      integrationLog.operation = 'PRODUCT_SYNC';
      integrationLog.payload = JSON.stringify(erpProductData);
      integrationLog.status = 'PENDING';

      await this.integrationRepository.save(integrationLog);

      // Make the API call
      const response = await firstValueFrom(
        this.httpService.post(erpEndpoint, erpProductData, {
          headers: {
            Authorization: `Bearer ${authToken}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      // Update log on success
      integrationLog.response = JSON.stringify(response.data);
      integrationLog.status = 'SUCCESS';
      await this.integrationRepository.save(integrationLog);

      this.logger.log(`Successfully synced product to ERP: ${productData.id}`);
      return { success: true, message: 'Product synced successfully to ERP' };
    } catch (error) {
      // Handle different types of errors
      if (error instanceof AxiosError) {
        this.logger.error(`ERP API error: ${error.response?.status} - ${error.response?.data?.message || error.message}`);

        // Update log on failure
        const integrationLog = new IntegrationLog();
        integrationLog.system = 'ERP';
        integrationLog.operation = 'PRODUCT_SYNC';
        integrationLog.payload = JSON.stringify(productData);
        integrationLog.status = 'FAILED';
        integrationLog.error = error.message;
        integrationLog.response = error.response?.data ? JSON.stringify(error.response.data) : null;

        await this.integrationRepository.save(integrationLog);

        return {
          success: false,
          message: `ERP API error: ${error.response?.status} - ${error.response?.data?.message || error.message}`,
        };
      } else {
        this.logger.error(`Unexpected error syncing product to ERP: ${error.message}`);

        // Update log on failure
        const integrationLog = new IntegrationLog();
        integrationLog.system = 'ERP';
        integrationLog.operation = 'PRODUCT_SYNC';
        integrationLog.payload = JSON.stringify(productData);
        integrationLog.status = 'FAILED';
        integrationLog.error = error.message;

        await this.integrationRepository.save(integrationLog);

        return { success: false, message: `Unexpected error: ${error.message}` };
      }
    }
  }
}
```

