## External System Integration Layer

```typescript
// src/external-systems.ts - Type-safe external system integration
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { config } from './config';
import { logger } from './logger';

// Base class for external system clients
abstract class ExternalSystemClient<TConfig> {
  protected client: AxiosInstance;
  protected config: TConfig;

  constructor(baseConfig: TConfig, axiosConfig: AxiosRequestConfig) {
    this.config = baseConfig;
    this.client = axios.create(axiosConfig);
  }

  protected async request<T>(config: AxiosRequestConfig): Promise<T> {
    try {
      const response: AxiosResponse<T> = await this.client.request(config);
      return response.data;
    } catch (error) {
      logger.error('External system request failed', {
        error: error instanceof Error ? error.message : String(error),
        config: {
          url: config.url,
          method: config.method,
        },
      });
      throw error;
    }
  }
}

// Legacy System Client
interface LegacySystemConfig {
  baseUrl: string;
  apiKey: string;
  timeout: number;
}

interface LegacySystemResponse<T> {
  status: 'success' | 'error';
  data: T;
  error?: string;
}

class LegacySystemClient extends ExternalSystemClient<LegacySystemConfig> {
  constructor() {
    super(
      {
        baseUrl: config.externalSystems.legacySystem.baseUrl,
        apiKey: config.externalSystems.legacySystem.apiKey,
        timeout: config.externalSystems.legacySystem.timeout,
      },
      {
        baseURL: config.externalSystems.legacySystem.baseUrl,
        timeout: config.externalSystems.legacySystem.timeout,
        headers: {
          'X-API-KEY': config.externalSystems.legacySystem.apiKey,
          'Content-Type': 'application/json',
        },
      }
    );
  }

  async getUserData(userId: string): Promise<{ name: string; department: string }> {
    const response = await this.request<LegacySystemResponse<{ name: string; department: string }>>({
      method: 'GET',
      url: `/users/${userId}`,
    });

    if (response.status !== 'success') {
      throw new Error(response.error || 'Legacy system request failed');
    }

    return response.data;
  }
}

// ERP System Client
interface ERPSystemConfig {
  baseUrl: string;
  username: string;
  password: string;
}

interface ERPSystemResponse<T> {
  success: boolean;
  result: T;
  errorMessage?: string;
}

class ERPSystemClient extends ExternalSystemClient<ERPSystemConfig> {
  constructor() {
    super(
      {
        baseUrl: config.externalSystems.erpSystem.baseUrl,
        username: config.externalSystems.erpSystem.username,
        password: config.externalSystems.erpSystem.password,
      },
      {
        baseURL: config.externalSystems.erpSystem.baseUrl,
        auth: {
          username: config.externalSystems.erpSystem.username,
          password: config.externalSystems.erpSystem.password,
        },
      }
    );
  }

  async getProductInventory(productId: string): Promise<{ quantity: number; location: string }> {
    const response = await this.request<ERPSystemResponse<{ quantity: number; location: string }>>({
      method: 'GET',
      url: `/api/inventory/${productId}`,
    });

    if (!response.success) {
      throw new Error(response.errorMessage || 'ERP system request failed');
    }

    return response.result;
  }
}

// Initialize all external system clients
export interface ExternalSystems {
  legacySystem: LegacySystemClient;
  erpSystem: ERPSystemClient;
}

let externalSystems: ExternalSystems;

export async function initializeExternalSystems(): Promise<ExternalSystems> {
  externalSystems = {
    legacySystem: new LegacySystemClient(),
    erpSystem: new ERPSystemClient(),
  };

  // Test connections to external systems
  try {
    // Simple ping to verify connections
    await Promise.all([
      externalSystems.legacySystem.getUserData('ping'),
      externalSystems.erpSystem.getProductInventory('ping'),
    ]);
    logger.info('All external system connections established');
  } catch (error) {
    logger.error('Failed to establish external system connections', { error });
    throw error;
  }

  return externalSystems;
}

export function getExternalSystems(): ExternalSystems {
  if (!externalSystems) {
    throw new Error('External systems not initialized');
  }
  return externalSystems;
}
