## Domain Services with Strict Typing

```typescript
// src/services/user.service.ts - Domain service with strict typing
import { getDataSource } from '../database';
import { User } from '../entities/user.entity';
import { getExternalSystems } from '../external-systems';
import { logger } from '../logger';

export interface UserData {
  id: string;
  name: string;
  email: string;
  isActive: boolean;
  department?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface CreateUserInput {
  name: string;
  email: string;
  password: string;
  department?: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
  isActive?: boolean;
  department?: string;
}

export class UserService {
  private dataSource = getDataSource();
  private externalSystems = getExternalSystems();

  async createUser(input: CreateUserInput): Promise<UserData> {
    const userRepository = this.dataSource.getRepository(User);

    // Check if user exists
    const existingUser = await userRepository.findOneBy({ email: input.email });
    if (existingUser) {
      throw new Error('User with this email already exists');
    }

    // Hash password (in a real app, use a proper hashing library)
    const passwordHash = await this.hashPassword(input.password);

    // Create user
    const user = userRepository.create({
      ...input,
      passwordHash,
    });

    await userRepository.save(user);

    // Sync with legacy system
    try {
      await this.externalSystems.legacySystem.getUserData(user.id);
    } catch (error) {
      logger.error('Failed to sync user with legacy system', {
        userId: user.id,
        error: error instanceof Error ? error.message : String(error),
      });
      // Continue even if sync fails - we'll have a retry mechanism
    }

    return this.mapToUserData(user);
  }

  async getUserById(id: string): Promise<UserData | null> {
    const userRepository = this.dataSource.getRepository(User);
    const user = await userRepository.findOneBy({ id });

    if (!user) {
      return null;
    }

    return this.mapToUserData(user);
  }

  async updateUser(id: string, input: UpdateUserInput): Promise<UserData> {
    const userRepository = this.dataSource.getRepository(User);
    const user = await userRepository.findOneBy({ id });

    if (!user) {
      throw new Error('User not found');
    }

    // Update fields
    if (input.name !== undefined) user.name = input.name;
    if (input.email !== undefined) user.email = input.email;
    if (input.isActive !== undefined) user.isActive = input.isActive;
    if (input.department !== undefined) user.department = input.department;

    await userRepository.save(user);

    return this.mapToUserData(user);
  }

  private mapToUserData(user: User): UserData {
    return {
      id: user.id,
      name: user.name,
      email: user.email,
      isActive: user.isActive,
      department: user.department,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }

  private async hashPassword(password: string): Promise<string> {
    // In a real application, use a proper password hashing library like bcrypt
    // This is a placeholder implementation
    return `hashed_${password}`;
  }
}
