## Service Layer with Dependency Injection

```typescript
// src/services/user-service.ts - Type-safe service implementation
import { User, UserSchema } from '../domain/models';
import { Database } from '../database';
import { Logger } from '../logging';
import { IntegrationClient } from '../integrations';
import { z } from 'zod';

interface UserServiceDependencies {
  database: Database;
  logger: Logger;
  integrationClient: IntegrationClient;
}

export class UserService {
  private database: Database;
  private logger: Logger;
  private integrationClient: IntegrationClient;

  constructor(dependencies: UserServiceDependencies) {
    this.database = dependencies.database;
    this.logger = dependencies.logger;
    this.integrationClient = dependencies.integrationClient;
  }

  async createUser(userData: Omit<User, 'id' | 'createdAt' | 'updatedAt'>): Promise<User> {
    const validationResult = UserSchema.omit({ id: true, createdAt: true, updatedAt: true }).safeParse(userData);

    if (!validationResult.success) {
      this.logger.error('Invalid user data', validationResult.error);
      throw new Error('Invalid user data');
    }

    const now = new Date();
    const user: User = {
      ...validationResult.data,
      id: crypto.randomUUID(),
      createdAt: now,
      updatedAt: now
    };

    try {
      const result = await this.database.query<User>(
        'INSERT INTO users (id, username, email, first_name, last_name, is_active, created_at, updated_at) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING *',
        [user.id, user.username, user.email, user.firstName, user.lastName, user.isActive, user.createdAt, user.updatedAt]
      );

      // Notify corporate systems
      await this.integrationClient.notifyUserCreated(user);

      return result[0];
    } catch (err) {
      this.logger.error('Failed to create user', err);
      throw err;
    }
  }

  async getUserById(id: string): Promise<User | null> {
    const validationResult = z.string().uuid().safeParse(id);

    if (!validationResult.success) {
      this.logger.error('Invalid user ID format', validationResult.error);
      throw new Error('Invalid user ID format');
    }

    try {
      const result = await this.database.query<User>(
        'SELECT * FROM users WHERE id = $1',
        [id]
      );

      return result.length > 0 ? result[0] : null;
    } catch (err) {
      this.logger.error('Failed to fetch user', err);
      throw err;
    }
  }

  async updateUser(id: string, updates: Partial<Omit<User, 'id' | 'createdAt'>>): Promise<User> {
    const idValidation = z.string().uuid().safeParse(id);
    if (!idValidation.success) {
      throw new Error('Invalid user ID format');
    }

    const updateValidation = UserSchema.omit({ id: true, createdAt: true }).partial().safeParse(updates);
    if (!updateValidation.success) {
      throw new Error('Invalid update data');
    }

    try {
      const existingUser = await this.getUserById(id);
      if (!existingUser) {
        throw new Error('User not found');
      }

      const updatedUser: User = {
        ...existingUser,
        ...updateValidation.data,
        updatedAt: new Date()
      };

      const result = await this.database.query<User>(
        'UPDATE users SET username = $1, email = $2, first_name = $3, last_name = $4, is_active = $5, updated_at = $6 WHERE id = $7 RETURNING *',
        [updatedUser.username, updatedUser.email, updatedUser.firstName, updatedUser.lastName, updatedUser.isActive, updatedUser.updatedAt, id]
      );

      // Notify corporate systems
      await this.integrationClient.notifyUserUpdated(updatedUser);

      return result[0];
    } catch (err) {
      this.logger.error('Failed to update user', err);
      throw err;
    }
  }
}
