## Integration Client for Corporate Systems

```typescript
// src/integrations/integration-client.ts - Type-safe integration client
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { config } from '../config';
import { Logger } from '../logging';
import { z } from 'zod';

interface IntegrationClientConfig {
  baseUrl: string;
  apiKey: string;
  timeout: number;
}

export class IntegrationClient {
  private client: AxiosInstance;
  private logger: Logger;

  constructor() {
    this.logger = new Logger('IntegrationClient');

    const integrationConfig: IntegrationClientConfig = {
      baseUrl: config.integrationBaseUrl,
      apiKey: config.apiKey,
      timeout: config.integrationTimeout
    };

    this.client = axios.create({
      baseURL: integrationConfig.baseUrl,
      timeout: integrationConfig.timeout,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${integrationConfig.apiKey}`
      }
    });

    // Add request interceptor
    this.client.interceptors.request.use((config: AxiosRequestConfig) => {
      this.logger.debug(`Outgoing request to ${config.url}`, {
        method: config.method,
        url: config.url,
        data: config.data
      });
      return config;
    });

    // Add response interceptor
    this.client.interceptors.response.use(
      (response: AxiosResponse) => {
        this.logger.debug(`Received response from ${response.config.url}`, {
          status: response.status,
          data: response.data
        });
        return response;
      },
      (error) => {
        this.logger.error('Integration request failed', {
          message: error.message,
          config: error.config,
          response: error.response?.data
        });
        return Promise.reject(error);
      }
    );
  }

  async notifyUserCreated(user: User): Promise<void> {
    const UserNotificationSchema = z.object({
      userId: z.string().uuid(),
      username: z.string(),
      email: z.string().email(),
