      userId: user.id,
      username: user.username,
      email: user.email,
      timestamp: new Date()
    });

    try {
      await this.client.post('/api/notifications/user-created', notificationData);
    } catch (err) {
      this.logger.error('Failed to notify corporate systems about user creation', err);
      // Implement retry logic or dead letter queue here
      throw err;
    }
  }

  async notifyUserUpdated(user: User): Promise<void> {
    // Similar implementation as above
  }

  async getCorporateData<T>(endpoint: string, params?: any): Promise<T> {
    try {
      const response = await this.client.get<T>(endpoint, { params });
      return response.data;
    } catch (err) {
      this.logger.error(`Failed to fetch data from ${endpoint}`, err);
      throw err;
    }
  }

  async postCorporateData<T>(endpoint: string, data: any): Promise<T> {
