## API Controller with Validation

```typescript
// src/controllers/user-controller.ts - Type-safe API controller
import { Request, Response, NextFunction } from 'express';
import { UserService } from '../services/user-service';
import { UserSchema } from '../domain/models';
import { z } from 'zod';
import { Logger } from '../logging';

export class UserController {
  private userService: UserService;
  private logger: Logger;

  constructor(userService: UserService) {
    this.userService = userService;
    this.logger = new Logger('UserController');
  }

  async createUser(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const validationResult = UserSchema.omit({ id: true, createdAt: true, updatedAt: true }).safeParse(req.body);

      if (!validationResult.success) {
        this.logger.error('Validation failed', validationResult.error);
        res.status(400).json({
          error: 'Validation failed',
          details: validationResult.error.errors
        });
        return;
      }

      const user = await this.userService.createUser(validationResult.data);
      res.status(201).json(user);
    } catch (err) {
      next(err);
    }
  }

  async getUser(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const validationResult = z.string().uuid().safeParse(req.params.id);

      if (!validationResult.success) {
        res.status(400).json({ error: 'Invalid user ID format' });
        return;
      }

      const user = await this.userService.getUserById(validationResult.data);

      if (!user) {
        res.status(404).json({ error: 'User not found' });
        return;
      }

      res.json(user);
    } catch (err) {
      next(err);
    }
  }

  async updateUser(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const idValidation = z.string().uuid().safeParse(req.params.id);
      if (!idValidation.success) {
        res.status(400).json({ error: 'Invalid user ID format' });
        return;
      }

      const updateValidation = UserSchema.omit({ id: true, createdAt: true }).partial().safeParse(req.body);
      if (!updateValidation.success) {
        res.status(400).json({
          error: 'Validation failed',
          details: updateValidation.error.errors
        });
        return;
      }

      const updatedUser = await this.userService.updateUser(idValidation.data, updateValidation.data);
      res.json(updatedUser);
    } catch (err) {
      next(err);
    }
  }
}
