### 9. Example Service (services/user.service.ts)

```typescript
import { IUserService } from '../interfaces/IUserService';
import { IUserRepository } from '../interfaces/IUserRepository';
import { IUser } from '../interfaces/IUser';
import { CreateUserDto, UpdateUserDto } from '../dtos/user.dto';
import { UserNotFoundError, UserAlreadyExistsError } from '../utils/errors';

export class UserService implements IUserService {
  constructor(private userRepository: IUserRepository) {}

  async createUser(userData: CreateUserDto): Promise<IUser> {
    // Check if user with same email or username already exists
    const existingUser = await this.userRepository.findOne({
      $or: [{ email: userData.email }, { username: userData.username }],
    });

    if (existingUser) {
      throw new UserAlreadyExistsError('User with this email or username already exists');
    }

    const newUser = await this.userRepository.create(userData);
    return newUser;
  }

  async getUserById(id: string): Promise<IUser> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new UserNotFoundError(`User with id ${id} not found`);
    }
    return user;
  }

  async getUserByEmail(email: string): Promise<IUser> {
    const user = await this.userRepository.findOne({ email });
    if (!user) {
      throw new UserNotFoundError(`User with email ${email} not found`);
    }
    return user;
  }

  async updateUser(id: string, userData: UpdateUserDto): Promise<IUser> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new UserNotFoundError(`User with id ${id} not found`);
    }

    // Check if email is being updated and if it's already taken
    if (userData.email && userData.email !== existingUser.email) {
      const emailExists = await this.userRepository.findOne({ email: userData.email });
      if (emailExists) {
        throw new UserAlreadyExistsError('User with this email already exists');
      }
    }

    const updatedUser = await this.userRepository.update(id, userData);
    if (!updatedUser) {
      throw new UserNotFoundError(`User with id ${id} not found`);
    }

    return updatedUser;
  }

  async deleteUser(id: string): Promise<void> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new UserNotFoundError(`User with id ${id} not found`);
    }

    await this.userRepository.delete(id);
  }

  async getAllUsers(): Promise<IUser[]> {
    return this.userRepository.find({});
  }
}
