### 11. Example Middleware (middlewares/auth.middleware.ts)

```typescript
import { Request, Response, NextFunction } from 'express';
import { UnauthorizedError } from '../utils/errors';
import { AuthService } from '../services/auth.service';
import { config } from '../config';

export class AuthMiddleware {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  public async authenticate(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const authHeader = req.headers.authorization;

      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        throw new UnauthorizedError('No token provided');
      }

      const token = authHeader.split(' ')[1];
      const decoded = await this.authService.verifyToken(token);

      if (!decoded) {
        throw new UnauthorizedError('Invalid token');
      }

      // Attach user information to the request
      req.user = decoded;

      next();
    } catch (error) {
      next(error);
    }
  }

  public authorize(roles: string[] = []): (req: Request, res: Response, next: NextFunction) => void {
    return (req: Request, res: Response, next: NextFunction) => {
      try {
        if (!req.user) {
          throw new UnauthorizedError('User not authenticated');
        }

        if (roles.length > 0 && !roles.includes(req.user.role)) {
          throw new UnauthorizedError('Insufficient permissions');
        }

        next();
      } catch (error) {
        next(error);
      }
    };
  }
}
```

