import { createTerminus } from '@godaddy/terminus';
import { logger } from './utils/logger';
import { config } from './config';
import { setupMiddleware } from './middleware';
import { setupRoutes } from './routes';
import { setupDatabase } from './database';
import { setupEventBus } from './event-bus';
import { setupHealthChecks } from './health';
import { setupMetrics } from './metrics';

async function bootstrap() {
  const app = express();
  const server = createServer(app);

  // Initialize core components
  await setupDatabase();
  const eventBus = await setupEventBus();
  const metrics = setupMetrics(app);

  // Setup middleware
  setupMiddleware(app);

  // Setup routes
  setupRoutes(app, eventBus);

  // Health checks and graceful shutdown
  setupHealthChecks(app, server);
  createTerminus(server, {
    signals: ['SIGTERM', 'SIGINT'],
    healthChecks: {
      '/health': async () => {
        // Add custom health checks here
        return { status: 'ok' };
      },
    },
    onSignal: async () => {
      logger.info('Server is starting cleanup');
      await eventBus.close();
      logger.info('Cleanup finished, server is shutting down');
    },
  });

  // Start server
  server.listen(config.port, () => {
    logger.info(`Server running on port ${config.port}`);
    metrics.startCollection();
  });

  return server;
}

// Handle unhandled rejections and exceptions
process.on('unhandledRejection', (err) => {
  logger.error('Unhandled rejection:', err);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  logger.error('Uncaught exception:', err);
  process.exit(1);
});

// Start the application
bootstrap().catch((err) => {
  logger.error('Failed to start server:', err);
  process.exit(1);
});
