## Database Layer with Type Safety

```typescript
// src/database/index.ts - Type-safe database access
import { Pool, PoolClient } from 'pg';
import { config } from '../config';
import { logger } from '../utils/logger';

// Define types for database operations
export interface DatabaseConfig {
  connectionString: string;
  poolSize: number;
}

export interface TransactionClient {
  query: <T = any>(sql: string, params?: any[]) => Promise<T>;
  release: () => Promise<void>;
}

export class Database {
  private pool: Pool;

  constructor(config: DatabaseConfig) {
    this.pool = new Pool({
      connectionString: config.connectionString,
      max: config.poolSize,
    });

    this.pool.on('error', (err) => {
      logger.error('Unexpected error on idle client', err);
      process.exit(-1);
    });
  }

  async connect(): Promise<PoolClient> {
    const client = await this.pool.connect();
    return {
      query: (sql, params) => client.query(sql, params),
      release: () => client.release(),
    };
  }

  async transaction<T>(callback: (client: TransactionClient) => Promise<T>): Promise<T> {
    const client = await this.connect();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      await client.release();
    }
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

// Initialize database
let database: Database;

export async function setupDatabase(): Promise<Database> {
  if (!database) {
    database = new Database({
      connectionString: config.DATABASE_URL,
      poolSize: config.DATABASE_POOL_SIZE,
    });
  }
  return database;
}

export function getDatabase(): Database {
  if (!database) {
    throw new Error('Database not initialized. Call setupDatabase() first.');
  }
  return database;
}
