import { Database, getDatabase } from '../database';

export const UserSchema = z.object({
  id: z.string().uuid(),
  username: z.string().min(3).max(50),
  email: z.string().email(),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100),
  isActive: z.boolean().default(true),
  createdAt: z.date(),
  updatedAt: z.date(),
});

export type User = z.infer<typeof UserSchema>;

export class UserRepository {
  private db: Database;

  constructor(db: Database = getDatabase()) {
    this.db = db;
  }

  async findById(id: string): Promise<User | null> {
    const result = await this.db.connect().then((client) =>
      client.query<User>('SELECT * FROM users WHERE id = $1', [id])
    );

    if (result.rows.length === 0) {
      return null;
    }

    return UserSchema.parse(result.rows[0]);
  }

  async create(user: Omit<User, 'id' | 'createdAt' | 'updatedAt'>): Promise<User> {
    const validatedUser = UserSchema.omit({
      id: true,
      createdAt: true,
      updatedAt: true,
    }).parse(user);

    const result = await this.db.connect().then((client) =>
      client.query<User>(
        `INSERT INTO users (username, email, first_name, last_name, is_active)
         VALUES ($1, $2, $3, $4, $5)
         RETURNING *`,
        [
          validatedUser.username,
          validatedUser.email,
          validatedUser.firstName,
          validatedUser.lastName,
          validatedUser.isActive,
        ]
      )
    );

    return UserSchema.parse(result.rows[0]);
  }

  // Add other repository methods as needed
}
