## Event Bus Integration

```typescript
// src/event-bus/index.ts - Enterprise event bus integration
import { EventEmitter2 } from '@nestjs/event-emitter';
import { logger } from '../utils/logger';
import { config } from '../config';

export interface EventBusConfig {
  serviceName: string;
  serviceVersion: string;
}

export class EventBus {
  private emitter: EventEmitter2;
  private config: EventBusConfig;

  constructor(config: EventBusConfig) {
    this.emitter = new EventEmitter2({
      wildcard: true,
      delimiter: '.',
      maxListeners: 20,
    });
    this.config = config;
  }

  async publish<T = any>(eventName: string, payload: T): Promise<void> {
    const event = {
      eventName,
      payload,
      metadata: {
        serviceName: this.config.serviceName,
        serviceVersion: this.config.serviceVersion,
        timestamp: new Date().toISOString(),
      },
    };

    // In a real implementation, you would integrate with corporate event bus
    // For example: Kafka, RabbitMQ, or enterprise service bus
    logger.debug(`Publishing event: ${eventName}`, event);

    this.emitter.emit(eventName, event);
  }

  subscribe<T = any>(eventName: string, handler: (event: T) => void): void {
    this.emitter.on(eventName, handler);
  }

  async close(): Promise<void> {
    // Cleanup resources if needed
    this.emitter.removeAllListeners();
  }
}

let eventBus: EventBus;

export async function setupEventBus(): Promise<EventBus> {
  if (!eventBus) {
    eventBus = new EventBus({
      serviceName: config.SERVICE_NAME,
      serviceVersion: config.SERVICE_VERSION,
    });
  }
  return eventBus;
}

export function getEventBus(): EventBus {
  if (!eventBus) {
    throw new Error('EventBus not initialized. Call setupEventBus() first.');
  }
  return eventBus;
}
