## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createTerminus } from '@godaddy/terminus';
import { setupMiddleware } from './middleware';
import { setupRoutes } from './routes';
import { setupHealthChecks } from './health';
import { setupErrorHandling } from './error-handling';
import { config } from './config';
import { logger } from './utils/logger';
import { setupSwagger } from './docs/swagger';
import { setupTracing } from './tracing';
import { setupMetrics } from './metrics';

export class EnterpriseMicroservice {
  private app: express.Application;
  private server: ReturnType<typeof createServer>;
  private shutdownInProgress = false;

  constructor() {
    this.app = express();
    this.server = createServer(this.app);
  }

  public async initialize(): Promise<void> {
    try {
      // Setup core middleware
      setupMiddleware(this.app);

      // Setup API documentation
      setupSwagger(this.app);

      // Setup distributed tracing
      setupTracing(this.app);

      // Setup metrics collection
      setupMetrics(this.app);

      // Setup application routes
      setupRoutes(this.app);

      // Setup health checks
      setupHealthChecks(this.app);

      // Setup error handling
      setupErrorHandling(this.app);

      // Setup graceful shutdown
      this.setupGracefulShutdown();

      logger.info('Microservice initialized successfully');
    } catch (error) {
      logger.error('Initialization failed', { error });
      throw error;
    }
  }

  private setupGracefulShutdown(): void {
    createTerminus(this.server, {
      signals: ['SIGTERM', 'SIGINT'],
      healthChecks: {
        '/health': async () => {
          if (this.shutdownInProgress) {
            throw new Error('Service is shutting down');
          }
          return { status: 'ok' };
        },
      },
      onSignal: async () => {
        this.shutdownInProgress = true;
        logger.info('Starting graceful shutdown...');
        // Add any cleanup logic here
        logger.info('Graceful shutdown complete');
      },
      onShutdown: () => {
        logger.info('Server is shutting down');
      },
    });
  }

  public async start(): Promise<void> {
    try {
      await this.initialize();

      this.server.listen(config.port, () => {
        logger.info(`Server running on port ${config.port}`);
      });
    } catch (error) {
      logger.error('Failed to start server', { error });
      process.exit(1);
    }
  }
}

// Start the service
const service = new EnterpriseMicroservice();
service.start();
