```typescript
// src/database/index.ts - Type-safe database layer
import { Pool, PoolClient } from 'pg';
import { config } from '../config';
import { logger } from '../utils/logger';
import { DatabaseError } from '../errors/database.error';

// Define types for your database entities
export interface User {
  id: string;
  username: string;
  email: string;
  createdAt: Date;
  updatedAt: Date;
  isActive: boolean;
}

export interface Transaction {
  id: string;
  userId: string;
  amount: number;
  currency: string;
  status: 'pending' | 'completed' | 'failed';
  createdAt: Date;
  updatedAt: Date;
}

export class Database {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      connectionString: config.DATABASE_URL,
      max: config.DATABASE_MAX_POOL_SIZE,
      connectionTimeoutMillis: config.DATABASE_CONNECTION_TIMEOUT,
    });

    this.pool.on('error', (err) => {
      logger.error('Unexpected error on idle client', { error: err });
    });
  }

  public async query<T>(text: string, params?: any[]): Promise<T[]> {
    let client: PoolClient | null = null;
    try {
      client = await this.pool.connect();
      const result = await client.query(text, params);
      return result.rows as T[];
    } catch (error) {
      logger.error('Database query failed', { error, query: text, params });
      throw new DatabaseError('Database operation failed', error);
    } finally {
      if (client) {
        client.release();
      }
    }
  }

  public async getUserById(id: string): Promise<User | null> {
    const users = await this.query<User>(
      'SELECT * FROM users WHERE id = $1',
      [id]
    );
    return users[0] || null;
  }

  public async createTransaction(transaction: Omit<Transaction, 'id' | 'createdAt' | 'updatedAt'>): Promise<Transaction> {
    const result = await this.query<Transaction>(
      `INSERT INTO transactions (user_id, amount, currency, status)
       VALUES ($1, $2, $3, $4)
       RETURNING *`,
      [transaction.userId, transaction.amount, transaction.currency, transaction.status]
    );
    return result[0];
  }

  // Add more type-safe database methods as needed
}
