  public async validateTransaction(transaction: Omit<CorporateTransaction, 'transactionId'>): Promise<CorporateTransaction> {
    try {
      const response = await this.client.post<CorporateTransaction>('/transactions/validate', transaction);
      return response.data;
    } catch (error) {
      throw new IntegrationError('Failed to validate transaction with corporate system', error);
    }
  }

  public async processTransaction(transactionId: string): Promise<CorporateTransaction> {
    try {
      const response = await this.client.post<CorporateTransaction>(`/transactions/${transactionId}/process`);
      return response.data;
    } catch (error) {
      throw new IntegrationError('Failed to process transaction with corporate system', error);
    }
