## API Controller with Type Safety

```typescript
// src/controllers/transactions.controller.ts - Type-safe controller
import { Request, Response, NextFunction } from 'express';
import { TransactionService } from '../services/transaction.service';
import { logger } from '../utils/logger';
import { ValidationError } from '../errors/validation.error';
import { z } from 'zod';

// Define request/response schemas using Zod
const CreateTransactionRequest = z.object({
  userId: z.string().uuid(),
  amount: z.number().positive(),
  currency: z.string().length(3),
});

const TransactionResponse = z.object({
  id: z.string().uuid(),
  userId: z.string().uuid(),
  amount: z.number(),
  currency: z.string(),
  status: z.enum(['pending', 'completed', 'failed']),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

export class TransactionsController {
  constructor(private transactionService: TransactionService) {}

  public async createTransaction(
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      // Validate request body
      const validatedData = CreateTransactionRequest.parse(req.body);

      // Process the transaction
      const transaction = await this.transactionService.createTransaction(validatedData);

      // Validate response
      const responseData = TransactionResponse.parse(transaction);

      res.status(201).json(responseData);
    } catch (error) {
      if (error instanceof z.ZodError) {
        next(new ValidationError('Invalid request data', error.errors));
      } else {
        next(error);
      }
    }
  }

  public async getTransaction(
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      const transactionId = z.string().uuid().parse(req.params.id);

      const transaction = await this.transactionService.getTransaction(transactionId);

      if (!transaction) {
        res.status(404).json({ message: 'Transaction not found' });
        return;
      }

      const responseData = TransactionResponse.parse(transaction);
      res.json(responseData);
    } catch (error) {
      if (error instanceof z.ZodError) {
        next(new ValidationError('Invalid transaction ID', error.errors));
      } else {
        next(error);
      }
    }
  }
}
