## Service Layer with Domain Logic

```typescript
// src/services/transaction.service.ts - Service layer with domain logic
import { Database, Transaction } from '../database';
import { CorporateSystemIntegration } from '../integrations/corporate-system';
import { logger } from '../utils/logger';
import { ServiceError } from '../errors/service.error';

export interface CreateTransactionInput {
  userId: string;
  amount: number;
  currency: string;
}

export class TransactionService {
  constructor(
    private database: Database,
    private corporateIntegration: CorporateSystemIntegration
  ) {}

  public async createTransaction(input: CreateTransactionInput): Promise<Transaction> {
    try {
      // Validate user exists in corporate system
      const corporateUser = await this.corporateIntegration.getUserByEmployeeId(input.userId);

      if (!corporateUser.isActive) {
        throw new ServiceError('User is not active in corporate system');
      }

      // Validate transaction with corporate system
      const corporateTransaction = await this.corporateIntegration.validateTransaction({
        employeeId: input.userId,
        amount: input.amount,
        currency: input.currency,
        status: 'pending',
      });

      // Create transaction in local database
      const transaction = await this.database.createTransaction({
        userId: input.userId,
        amount: input.amount,
        currency: input.currency,
        status: corporateTransaction.status === 'approved' ? 'completed' : 'pending',
      });

      // If approved, process immediately
      if (corporateTransaction.status === 'approved') {
        await this.corporateIntegration.processTransaction(transaction.id);
      }

      return transaction;
    } catch (error) {
      logger.error('Failed to create transaction', { error, input });
      throw new ServiceError('Failed to create transaction', error);
    }
  }

  public async getTransaction(id: string): Promise<Transaction | null> {
    try {
      return await this.database.getTransactionById(id);
    } catch (error) {
      logger.error('Failed to fetch transaction', { error, id });
      throw new ServiceError('Failed to fetch transaction', error);
    }
  }
}
