### 7. Integration with Corporate Systems (services/ExternalSystemService.ts)

```typescript
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { ExternalSystemError } from '../exceptions';

interface IExternalSystemResponse<T> {
  data: T;
  status: number;
  headers: any;
}

export class ExternalSystemService {
  private legacySystemClient: AxiosInstance;
  private erpSystemClient: AxiosInstance;

  constructor() {
    this.legacySystemClient = this.createClient('legacySystem');
    this.erpSystemClient = this.createClient('erpSystem');
  }

  private createClient(serviceName: string): AxiosInstance {
    const serviceConfig = config.externalServices[serviceName];

    const client = axios.create({
      baseURL: serviceConfig.baseUrl,
      timeout: serviceConfig.timeout || 5000,
      headers: {
        'Content-Type': 'application/json',
        ...(serviceConfig.apiKey ? { 'X-API-KEY': serviceConfig.apiKey } : {}),
      },
    });

    // Request interceptor
    client.interceptors.request.use(
      (config) => {
        logger.info(`Outgoing request to ${serviceName}: ${config.method?.toUpperCase()} ${config.url}`);
        return config;
      },
      (error) => {
        logger.error(`Request error to ${serviceName}:`, error);
        return Promise.reject(error);
      }
    );

    // Response interceptor
    client.interceptors.response.use(
      (response) => {
        logger.info(`Response from ${serviceName}: ${response.status} ${response.config.method?.toUpperCase()} ${response.config.url}`);
        return response;
      },
      (error) => {
        logger.error(`Response error from ${serviceName}:`, error);
        return Promise.reject(error);
      }
    );

    return client;
  }

  async getLegacySystemData<T>(endpoint: string, params?: any): Promise<T> {
    try {
      const response: AxiosResponse<IExternalSystemResponse<T>> = await this.legacySystemClient.get(endpoint, { params });
      return response.data.data;
    } catch (error) {
      throw new ExternalSystemError(`Failed to fetch data from legacy system: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  async postToErpSystem<T>(endpoint: string, data: any): Promise<T> {
    try {
      const response: AxiosResponse<IExternalSystemResponse<T>> = await this.erpSystemClient.post(endpoint, data);
      return response.data.data;
    } catch (error) {
      throw new ExternalSystemError(`Failed to post data to ERP system: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  // Add more methods for other corporate systems as needed
}
