## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createTerminus } from '@godaddy/terminus';
import { configureContainer } from './config/container';
import { configureRoutes } from './config/routes';
import { configureMiddleware } from './config/middleware';
import { configureErrorHandling } from './config/error-handling';
import { logger } from './utils/logger';
import { healthCheck } from './utils/health-check';
import { metricsMiddleware } from './utils/metrics';

export class EnterpriseMicroservice {
  private app: express.Application;
  private server: ReturnType<typeof createServer>;
  private container: ReturnType<typeof configureContainer>;

  constructor() {
    this.app = express();
    this.container = configureContainer();
    this.configure();
  }

  private configure(): void {
    // Configure middleware
    configureMiddleware(this.app, this.container);

    // Configure routes
    configureRoutes(this.app, this.container);

    // Configure error handling
    configureErrorHandling(this.app);

    // Add metrics middleware
    this.app.use(metricsMiddleware);

    // Create HTTP server
    this.server = createServer(this.app);

    // Configure graceful shutdown
    createTerminus(this.server, {
      signal: 'SIGINT',
      healthChecks: {
        '/health': healthCheck(this.container),
      },
      onSignal: async () => {
        logger.info('Received shutdown signal, gracefully closing...');
        await this.container.cradle.dbConnection.close();
        logger.info('Database connection closed');
      },
    });
  }

  public async start(port: number): Promise<void> {
    try {
      // Initialize database connection
      await this.container.cradle.dbConnection.initialize();

      // Start the server
      this.server.listen(port, () => {
        logger.info(`Microservice running on port ${port}`);
      });
    } catch (error) {
      logger.error('Failed to start microservice', { error });
      process.exit(1);
    }
  }
}

// Start the application if run directly
if (require.main === module) {
  const port = process.env.PORT || 3000;
  const service = new EnterpriseMicroservice();
  service.start(port);
}
