## Repository Pattern with Type Safety

```typescript
// src/repositories/user-repository.ts - Type-safe repository
import { User, CreateUser, UpdateUser } from '../models/user';
import { DatabaseConnection } from '../database/connection';
import { logger } from '../utils/logger';

export class UserRepository {
  constructor(private dbConnection: DatabaseConnection) {}

  async create(userData: CreateUser): Promise<User> {
    try {
      const [user] = await this.dbConnection
        .getConnection()
        .insert(userData)
        .into('users')
        .returning('*');

      return UserSchema.parse(user);
    } catch (error) {
      logger.error('Failed to create user', { error, userData });
      throw error;
    }
  }

  async findById(id: string): Promise<User | null> {
    try {
      const user = await this.dbConnection
        .getConnection()
        .select('*')
        .from('users')
        .where({ id })
        .first();

      return user ? UserSchema.parse(user) : null;
    } catch (error) {
      logger.error('Failed to find user by ID', { error, id });
      throw error;
    }
  }

  async update(id: string, updateData: UpdateUser): Promise<User | null> {
    try {
      const [user] = await this.dbConnection
        .getConnection()
        .update(updateData)
        .from('users')
        .where({ id })
        .returning('*');

      return user ? UserSchema.parse(user) : null;
    } catch (error) {
      logger.error('Failed to update user', { error, id, updateData });
      throw error;
    }
  }

  async findAll(limit: number = 100, offset: number = 0): Promise<User[]> {
    try {
      const users = await this.dbConnection
        .getConnection()
        .select('*')
        .from('users')
        .limit(limit)
        .offset(offset);

      return users.map(user => UserSchema.parse(user));
    } catch (error) {
      logger.error('Failed to find all users', { error, limit, offset });
      throw error;
    }
  }
}
