## Service Layer with Strict Typing

```typescript
// src/services/user-service.ts - Business logic with type safety
import { UserRepository } from '../repositories/user-repository';
import { User, CreateUser, UpdateUser } from '../models/user';
import { logger } from '../utils/logger';
import { EventPublisher } from '../events/event-publisher';
import { RedisClient } from '../cache/redis-client';

export class UserService {
  private static readonly CACHE_TTL = 3600; // 1 hour in seconds

  constructor(
    private userRepository: UserRepository,
    private eventPublisher: EventPublisher,
    private redisClient: RedisClient
  ) {}

  async createUser(userData: CreateUser): Promise<User> {
    try {
      // Validate input
      const validatedData = CreateUserSchema.parse(userData);

      // Create user
      const user = await this.userRepository.create(validatedData);

      // Publish event
      await this.eventPublisher.publish('user.created', user);

      // Invalidate cache
      await this.redisClient.del(`user:${user.id}`);

      return user;
    } catch (error) {
      logger.error('Failed to create user', { error, userData });
      throw error;
    }
  }

  async getUserById(id: string): Promise<User | null> {
    try {
      // Check cache first
      const cachedUser = await this.redisClient.get(`user:${id}`);
      if (cachedUser) {
        return UserSchema.parse(JSON.parse(cachedUser));
      }

      // Get from database
      const user = await this.userRepository.findById(id);

      // Cache the result
      if (user) {
        await this.redisClient.setex(
          `user:${id}`,
          UserService.CACHE_TTL,
          JSON.stringify(user)
        );
      }

      return user;
    } catch (error) {
      logger.error('Failed to get user by ID', { error, id });
      throw error;
    }
  }

  async updateUser(id: string, updateData: UpdateUser): Promise<User | null> {
    try {
      // Validate input
      const validatedData = UpdateUserSchema.parse(updateData);

      // Update user
      const updatedUser = await this.userRepository.update(id, validatedData);

      if (updatedUser) {
        // Publish event
        await this.eventPublisher.publish('user.updated', updatedUser);

        // Invalidate cache
        await this.redisClient.del(`user:${id}`);
      }

      return updatedUser;
    } catch (error) {
      logger.error('Failed to update user', { error, id, updateData });
      throw error;
    }
  }
}
