export class SapConnector {
  private client: AxiosInstance;

  constructor(private baseUrl: string, private apiKey: string) {
    this.client = axios.create({
      baseURL: baseUrl,
      headers: {
        'API-Key': apiKey,
        'Content-Type': 'application/json',
      },
      timeout: 10000, // 10 seconds timeout
    });
  }

  async getEmployeeById(employeeId: string): Promise<SapEmployee | null> {
    try {
      const response = await this.client.get(`/employees/${employeeId}`);

      // Validate response
      const employee = SapEmployeeSchema.parse(response.data);

      return employee;
    } catch (error) {
      if (axios.isAxiosError(error)) {
        if (error.response?.status === 404) {
          return null;
        }
        logger.error('SAP API error', {
          status: error.response?.status,
          data: error.response?.data,
        });
      } else {
        logger.error('Unexpected SAP API error', { error });
      }
      throw error;
    }
  }

  async syncEmployeeData(employeeId: string): Promise<void> {
    try {
      const sapEmployee = await this.getEmployeeById(employeeId);

      if (sapEmployee) {
