  constructor(
    @InjectRepository(UserRepository)
    private userRepository: UserRepository,
    private corporateIntegrationService: CorporateIntegrationService
  ) {}

  async createUser(createUserDto: CreateUserDto): Promise<User> {
    const existingUser = await this.userRepository.findByEmail(createUserDto.email);
    if (existingUser) {
      throw new Error('User with this email already exists');
    }

    const user = await this.userRepository.createUser(createUserDto);

    // Integrate with corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.syncUserToCorporateSystem(user);
    }

    return user;
  }

  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findOne(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return user;
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<User> {
    const user = await this.userRepository.updateUser(id, updateUserDto);

    // Integrate with corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.syncUserToCorporateSystem(user);
    }

    return user;
  }

  async deleteUser(id: string): Promise<void> {
    const user = await this.userRepository.findOne(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }

    // Integrate with corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.deactivateUserInCorporateSystem(user.id);
    }

    await this.userRepository.delete(id);
  }

  async getUsersByDepartment(department: string): Promise<User[]> {
    return this.userRepository.findByDepartment(department);
  }
}
