```typescript
import { Injectable } from '@nestjs/common';
import { config } from '@config/config';
import { User } from '@entities/user.entity';
import { HttpService } from '@nestjs/axios';
import { lastValueFrom } from 'rxjs';

@Injectable()
export class CorporateIntegrationService {
  private readonly baseUrl: string;
  private readonly apiKey: string;

  constructor(private httpService: HttpService) {
    this.baseUrl = config.CORPORATE_API_BASE_URL;
    this.apiKey = config.CORPORATE_API_KEY;
  }

  async syncUserToCorporateSystem(user: User): Promise<void> {
    try {
      const response = await lastValueFrom(
        this.httpService.post(`${this.baseUrl}/users/sync`, {
          userId: user.id,
          email: user.email,
          role: user.role,
          department: user.department
        }, {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json'
          }
        })
      );

      if (response.status !== 200) {
        throw new Error(`Corporate system sync failed with status ${response.status}`);
      }
    } catch (error) {
      // Handle error appropriately (retry, log, etc.)
      console.error('Corporate integration error:', error.message);
      throw error;
    }
  }

  async deactivateUserInCorporateSystem(userId: string): Promise<void> {
    try {
      const response = await lastValueFrom(
        this.httpService.post(`${this.baseUrl}/users/deactivate`, {
          userId
        }, {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json'
          }
        })
      );

      if (response.status !== 200) {
        throw new Error(`Corporate system deactivation failed with status ${response.status}`);
      }
    } catch (error) {
      // Handle error appropriately
      console.error('Corporate integration error:', error.message);
      throw error;
    }
  }
}
