```typescript
import { Injectable, Inject } from '@nestjs/common';
import { UserRepository } from '../repositories/user.repository';
import { User } from '../entities/user.entity';
import { CorporateSystemService } from './corporate-system.service';
import { CreateUserDto, UpdateUserDto } from '../dtos/user.dto';

@Injectable()
export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    @Inject('CORPORATE_SYSTEM_SERVICE')
    private readonly corporateSystemService: CorporateSystemService,
  ) {}

  async createUser(createUserDto: CreateUserDto): Promise<User> {
    // Validate with corporate system
    const corporateValidation = await this.corporateSystemService.validateEmployee(
      createUserDto.email,
    );

    if (!corporateValidation.isValid) {
      throw new Error('Employee not found in corporate system');
    }

    const userData: Partial<User> = {
      ...createUserDto,
      corporateId: corporateValidation.corporateId,
      hireDate: corporateValidation.hireDate,
    };

    return this.userRepository.create(userData);
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<User | null> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) return null;

    // Check if department change requires corporate system approval
    if (updateUserDto.department && updateUserDto.department !== existingUser.department) {
      const approval = await this.corporateSystemService.requestDepartmentChangeApproval(
        existingUser.corporateId!,
        updateUserDto.department,
      );

      if (!approval.isApproved) {
        throw new Error('Department change not approved by corporate system');
      }
    }

    return this.userRepository.update(id, updateUserDto);
  }

  async getUserById(id: string): Promise<User | null> {
    return this.userRepository.findById(id);
  }

  async getAllUsers(): Promise<User[]> {
    return this.userRepository.findAll();
  }
}
