    try {
      const response = await this.axiosInstance.post('/validate-employee', { email });
      return response.data;
    } catch (error) {
      console.error('Corporate system validation failed:', error);
      return { isValid: false };
    }
  }

  async requestDepartmentChangeApproval(
    corporateId: string,
    newDepartment: string,
