## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { ApolloServer } from 'apollo-server-express';
import { buildSchema } from 'type-graphql';
import { Container } from 'typedi';
import { useContainer } from 'class-validator';
import { useExpressServer } from 'routing-controllers';
import { createConnection } from 'typeorm';
import { config } from './config';
import { errorHandler } from './middleware/errorHandler';
import { logger } from './utils/logger';
import { healthCheckRouter } from './routes/healthCheck';
import { authMiddleware } from './middleware/auth';
import { metricsMiddleware } from './middleware/metrics';
import { auditLogger } from './middleware/auditLogger';
import { correlationIdMiddleware } from './middleware/correlationId';
import { rateLimiter } from './middleware/rateLimiter';
import { requestValidator } from './middleware/requestValidator';
import { OpenTelemetry } from './instrumentation/opentelemetry';

// Initialize OpenTelemetry for distributed tracing
const otel = new OpenTelemetry();
otel.init();

async function bootstrap() {
  try {
    // Initialize database connection
    await createConnection();

    // Set up dependency injection
    useContainer(Container);

    // Create Express app
    const app = express();

    // Middleware stack
    app.use(correlationIdMiddleware);
    app.use(rateLimiter);
    app.use(express.json({ limit: '10kb' }));
    app.use(requestValidator);
    app.use(authMiddleware);
    app.use(metricsMiddleware);
    app.use(auditLogger);

    // Health check endpoint
    app.use('/health', healthCheckRouter);

    // Set up REST API with routing-controllers
    useExpressServer(app, {
      routePrefix: '/api',
      controllers: [__dirname + '/controllers/**/*.ts'],
      middlewares: [__dirname + '/middleware/**/*.ts'],
      defaultErrorHandler: false,
      validation: true,
      classTransformer: true,
      classToPlainTransformOptions: {
        enableCircularCheck: true,
      },
    });

    // Set up GraphQL API with Apollo Server
    const apolloServer = new ApolloServer({
      schema: await buildSchema({
        resolvers: [__dirname + '/graphql/resolvers/**/*.ts'],
        container: Container,
        validate: true,
      }),
      context: ({ req, res }) => ({
        req,
        res,
        user: req.user,
        correlationId: req.correlationId,
      }),
      plugins: [otel.apolloPlugin()],
      formatError: (err) => {
        logger.error('GraphQL Error:', err);
        return {
          message: err.message,
          code: err.extensions?.code || 'INTERNAL_SERVER_ERROR',
          path: err.path,
        };
      },
    });

    await apolloServer.start();
    apolloServer.applyMiddleware({ app, path: '/graphql' });

    // Error handling middleware
    app.use(errorHandler);

    // Create HTTP server
    const server = createServer(app);

    // Start server
    server.listen(config.port, () => {
      logger.info(`Server running on port ${config.port}`);
      logger.info(`GraphQL endpoint: http://localhost:${config.port}/graphql`);
    });

    // Handle graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed.');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      logger.info('SIGINT received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed.');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error('Application startup failed:', error);
    process.exit(1);
  }
}

bootstrap();
```

