## Service Layer with Strict Typing

```typescript
// src/services/UserService.ts
import { Service } from 'typedi';
import { InjectRepository } from 'typeorm-typedi-extensions';
import { Repository } from 'typeorm';
import { User } from '../entities/User';
import { UserInput } from '../types/UserInput';
import { CorporateSystemClient } from '../clients/CorporateSystemClient';
import { Logger } from '../utils/logger';
import { UserNotFoundError } from '../errors/UserNotFoundError';
import { UserAlreadyExistsError } from '../errors/UserAlreadyExistsError';

@Service()
export class UserService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    private readonly corporateSystemClient: CorporateSystemClient,
    private readonly logger: Logger
  ) {}

  async createUser(userInput: UserInput): Promise<User> {
    this.logger.info(`Creating user with email: ${userInput.email}`);

    const existingUser = await this.userRepository.findOne({ where: { email: userInput.email } });
    if (existingUser) {
      throw new UserAlreadyExistsError(userInput.email);
    }

    const user = this.userRepository.create(userInput);

    // Integrate with corporate system
    try {
      const corporateData = await this.corporateSystemClient.getUserData(userInput.email);
      if (corporateData) {
        user.corporateId = corporateData.corporateId;
        user.department = corporateData.department;
        user.employeeId = corporateData.employeeId;
      }
    } catch (error) {
      this.logger.warn(`Failed to fetch corporate data for ${userInput.email}: ${error.message}`);
    }

    return this.userRepository.save(user);
  }

  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { id } });
    if (!user) {
      throw new UserNotFoundError(id);
    }
    return user;
  }

  async getUserByEmail(email: string): Promise<User> {
    const user = await this.userRepository.findOne({ where: { email } });
    if (!user) {
      throw new UserNotFoundError(email);
    }
    return user;
  }

  async updateUser(id: string, userInput: Partial<UserInput>): Promise<User> {
    const user = await this.getUserById(id);

    Object.assign(user, userInput);

    return this.userRepository.save(user);
  }

  async deleteUser(id: string): Promise<boolean> {
    const result = await this.userRepository.delete(id);
    return result.affected === 1;
  }
}
