## Corporate System Integration Client

```typescript
// src/clients/CorporateSystemClient.ts
import { Service } from 'typedi';
import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { Logger } from '../utils/logger';
import { CorporateUserData } from '../types/CorporateUserData';

@Service()
export class CorporateSystemClient {
  private client: AxiosInstance;

  constructor(private readonly logger: Logger) {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      headers: {
        'Authorization': `Bearer ${config.CORPORATE_API_KEY}`,
        'Content-Type': 'application/json',
      },
      timeout: 5000,
    });

    // Add request interceptor for logging
    this.client.interceptors.request.use((request) => {
      this.logger.debug(`Corporate API Request: ${request.method} ${request.url}`);
      return request;
    });

    // Add response interceptor for logging
    this.client.interceptors.response.use(
      (response) => {
        this.logger.debug(`Corporate API Response: ${response.status} ${response.config.url}`);
        return response;
      },
      (error) => {
        this.logger.error(`Corporate API Error: ${error.message}`);
        return Promise.reject(error);
      }
    );
  }

  async getUserData(email: string): Promise<CorporateUserData | null> {
    try {
      const response = await this.client.get(`/users?email=${encodeURIComponent(email)}`);
      return response.data as CorporateUserData;
    } catch (error) {
      if (error.response?.status === 404) {
        return null;
      }
      throw error;
    }
  }

  async syncUserData(userId: string): Promise<boolean> {
    try {
      await this.client.post('/users/sync', { userId });
      return true;
    } catch (error) {
      this.logger.error(`Failed to sync user data for ${userId}: ${error.message}`);
      return false;
    }
  }
}
