## Observability Setup

```typescript
// src/instrumentation/opentelemetry.ts
import { NodeTracerProvider } from '@opentelemetry/sdk-trace-node';
import { SimpleSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { ApolloServerPlugin } from 'apollo-server-plugin-base';
import { GraphQLRequestContext } from 'apollo-server-types';
import { config } from '../config';
import { logger } from '../utils/logger';

export class OpenTelemetry {
  private provider: NodeTracerProvider;

  constructor() {
    this.provider = new NodeTracerProvider({
      resource: new Resource({
        [SemanticResourceAttributes.SERVICE_NAME]: 'enterprise-microservice',
        [SemanticResourceAttributes.SERVICE_VERSION]: '1.0.0',
      }),
    });
  }

  init() {
    if (!config.TRACING_ENABLED) {
      logger.info('Tracing is disabled');
      return;
    }

    const exporter = new JaegerExporter({
      serviceName: 'enterprise-microservice',
      endpoint: 'http://jaeger:14268/api/traces',
    });

    this.provider.addSpanProcessor(new SimpleSpanProcessor(exporter));
    this.provider.register();

    logger.info('OpenTelemetry tracing initialized');
  }

  apolloPlugin(): ApolloServerPlugin {
    return {
      requestDidStart: (requestContext: GraphQLRequestContext) => {
        const span = this.provider.getTracer('default').startSpan('graphql-request');
        span.setAttribute('graphql.operation.name', requestContext.request.operationName || 'anonymous');
        span.setAttribute('graphql.variables', JSON.stringify(requestContext.request.variables));

        return {
          willSendResponse: () => {
            span.end();
          },
          didEncounterErrors: (ctx) => {
            ctx.errors?.forEach((error) => {
              span.recordException(error);
            });
          },
        };
      },
    };
  }
}
