### 7. Service Layer Example (src/services/UserService.ts)

```typescript
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from '../entities/User';
import { CreateUserDto } from '../dto/CreateUserDto';
import { UpdateUserDto } from '../dto/UpdateUserDto';
import { ApiException } from '../exceptions/ApiException';
import { HttpStatus } from '../enums/HttpStatus';
import { logger } from '../utils/logger';

@Injectable()
export class UserService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>
  ) {}

  async createUser(createUserDto: CreateUserDto): Promise<User> {
    try {
      const existingUser = await this.userRepository.findOne({
        where: { email: createUserDto.email }
      });

      if (existingUser) {
        throw new ApiException('User with this email already exists', HttpStatus.CONFLICT);
      }

      const user = this.userRepository.create(createUserDto);
      return await this.userRepository.save(user);
    } catch (error) {
      logger.error('Error creating user', error);
      throw new ApiException('Failed to create user', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  async getUserById(id: string): Promise<User> {
    try {
      const user = await this.userRepository.findOne({ where: { id } });

      if (!user) {
        throw new ApiException('User not found', HttpStatus.NOT_FOUND);
      }

      return user;
    } catch (error) {
      logger.error('Error fetching user', error);
      throw new ApiException('Failed to fetch user', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<User> {
    try {
      const user = await this.getUserById(id);

      Object.assign(user, updateUserDto);
      return await this.userRepository.save(user);
    } catch (error) {
      logger.error('Error updating user', error);
      throw new ApiException('Failed to update user', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  async deleteUser(id: string): Promise<void> {
    try {
      const user = await this.getUserById(id);
      await this.userRepository.remove(user);
    } catch (error) {
      logger.error('Error deleting user', error);
      throw new ApiException('Failed to delete user', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }
}
```

