## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createTerminus } from '@godaddy/terminus';
import { configureContainer } from './config/container';
import { configureRoutes } from './routes';
import { configureMiddleware } from './middleware';
import { logger } from './utils/logger';
import { healthCheck } from './utils/health';

export class EnterpriseMicroservice {
  private app: express.Application;
  private server: ReturnType<typeof createServer>;
  private container: any;

  constructor() {
    this.app = express();
    this.container = configureContainer();
    this.configureServer();
  }

  private configureServer(): void {
    // Configure middleware
    configureMiddleware(this.app, this.container);

    // Configure routes
    configureRoutes(this.app, this.container);

    // Create HTTP server
    this.server = createServer(this.app);

    // Configure graceful shutdown and health checks
    createTerminus(this.server, {
      signals: ['SIGINT', 'SIGTERM'],
      healthChecks: {
        '/health': healthCheck,
        verbatim: true
      },
      onSignal: async () => {
        logger.info('Server is starting cleanup');
        await this.container.shutdown();
        logger.info('Cleanup finished, server is shutting down');
      },
      onShutdown: () => {
        logger.info('Server has been shutdown');
      }
    });
  }

  public async start(port: number): Promise<void> {
    try {
      await this.container.initialize();
      this.server.listen(port, () => {
        logger.info(`Server running on port ${port}`);
      });
    } catch (error) {
      logger.error('Failed to start server:', error);
      process.exit(1);
    }
  }
}

// Start the service if this is the main module
if (require.main === module) {
  const port = process.env.PORT || 3000;
  const service = new EnterpriseMicroservice();
  service.start(port);
}
