```typescript
// src/services/enterprise.integration.service.ts
import { injectable, inject } from 'inversify';
import { ILogger } from '../utils/logger';
import { TYPES } from '../config/types';
import { IEnterpriseIntegrationService } from './interfaces/enterprise.integration.interface';
import { IConfigService } from './interfaces/config.interface';
import axios, { AxiosInstance } from 'axios';
import { ERPResponse, CRMResponse } from '../types/enterprise.types';

@injectable()
export class EnterpriseIntegrationService implements IEnterpriseIntegrationService {
  private erpClient: AxiosInstance;
  private crmClient: AxiosInstance;

  constructor(
    @inject(TYPES.Logger) private logger: ILogger,
    @inject(TYPES.ConfigService) private configService: IConfigService
  ) {
    this.initializeClients();
  }

  private initializeClients(): void {
    const erpConfig = this.configService.getEnterpriseSystemConfig('erp');
    const crmConfig = this.configService.getEnterpriseSystemConfig('crm');

    this.erpClient = axios.create({
      baseURL: erpConfig.baseUrl,
      headers: {
        'Authorization': `Bearer ${erpConfig.apiKey}`,
        'Content-Type': 'application/json'
      }
    });

    this.crmClient = axios.create({
      baseURL: crmConfig.baseUrl,
      headers: {
        'Authorization': `Bearer ${crmConfig.authToken}`,
        'Content-Type': 'application/json'
      }
    });
  }

  public async getERPData<T>(endpoint: string): Promise<ERPResponse<T>> {
    try {
      this.logger.info(`Fetching ERP data from ${endpoint}`);
      const response = await this.erpClient.get<T>(endpoint);
      return {
        success: true,
        data: response.data,
        status: response.status
      };
    } catch (error) {
      this.logger.error(`Error fetching ERP data: ${error.message}`);
      return {
        success: false,
        error: error.message,
        status: error.response?.status || 500
      };
    }
  }

  public async postToCRM<T>(endpoint: string, data: any): Promise<CRMResponse<T>> {
    try {
      this.logger.info(`Posting to CRM at ${endpoint}`);
      const response = await this.crmClient.post<T>(endpoint, data);
      return {
        success: true,
        data: response.data,
        status: response.status
      };
    } catch (error) {
      this.logger.error(`Error posting to CRM: ${error.message}`);
      return {
        success: false,
        error: error.message,
        status: error.response?.status || 500
      };
    }
  }
}
