## Type-Safe API Routes

```typescript
// src/routes/api.routes.ts
import { Router } from 'express';
import { injectable, inject } from 'inversify';
import { TYPES } from '../config/types';
import { ILogger } from '../utils/logger';
import { IEnterpriseIntegrationService } from '../services/interfaces/enterprise.integration.interface';
import { validateRequest } from '../middleware/validation.middleware';
import { ERPDataRequest, ERPDataResponse } from '../types/api.types';

@injectable()
export class ApiRoutes {
  private router: Router;

  constructor(
    @inject(TYPES.Logger) private logger: ILogger,
    @inject(TYPES.EnterpriseIntegrationService) private integrationService: IEnterpriseIntegrationService
  ) {
    this.router = Router();
    this.configureRoutes();
  }

  private configureRoutes(): void {
    this.router.get(
      '/erp-data',
      validateRequest(ERPDataRequest),
      this.getERPData.bind(this)
    );

    this.router.post(
      '/crm-update',
      validateRequest(CRMUpdateRequest),
      this.postToCRM.bind(this)
    );
  }

  private async getERPData(req: Request, res: Response): Promise<void> {
    try {
      const { endpoint } = req.query as unknown as ERPDataRequest;

      const result = await this.integrationService.getERPData<any>(endpoint);

      if (result.success) {
        const response: ERPDataResponse = {
          data: result.data,
          timestamp: new Date().toISOString()
        };
        res.status(200).json(response);
      } else {
        res.status(result.status || 500).json({
          error: result.error || 'Failed to fetch ERP data'
        });
      }
    } catch (error) {
      this.logger.error('Error in getERPData:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }

  private async postToCRM(req: Request, res: Response): Promise<void> {
    try {
      const { endpoint, data } = req.body as CRMUpdateRequest;

      const result = await this.integrationService.postToCRM<any>(endpoint, data);

      if (result.success) {
        res.status(201).json({
          success: true,
          data: result.data,
          timestamp: new Date().toISOString()
        });
      } else {
        res.status(result.status || 500).json({
          error: result.error || 'Failed to update CRM'
        });
      }
    } catch (error) {
      this.logger.error('Error in postToCRM:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }

  public getRouter(): Router {
    return this.router;
  }
}
