### 4. Repository Pattern with Type Safety

```typescript
// src/repositories/UserRepository.ts
import { User } from '../entities/User';
import { DatabaseService } from '../services/DatabaseService';
import { Injectable } from '../decorators/injectable';

@Injectable()
export class UserRepository {
  constructor(private readonly dbService: DatabaseService) {}

  async findById(id: string): Promise<User | null> {
    const result = await this.dbService.query<User>(
      'SELECT * FROM users WHERE id = $1',
      [id]
    );
    return result.rows[0] || null;
  }

  async findByEmail(email: string): Promise<User | null> {
    const result = await this.dbService.query<User>(
      'SELECT * FROM users WHERE email = $1',
      [email]
    );
    return result.rows[0] || null;
  }

  async create(user: User): Promise<User> {
    const result = await this.dbService.query<User>(
      'INSERT INTO users (email, password, firstName, lastName, role) VALUES ($1, $2, $3, $4, $5) RETURNING *',
      [user.email, user.password, user.firstName, user.lastName, user.role]
    );
    return result.rows[0];
  }

  async update(id: string, user: Partial<User>): Promise<User | null> {
    const setClauses = [];
    const values = [];
    let paramIndex = 1;

    for (const [key, value] of Object.entries(user)) {
      if (value !== undefined) {
        setClauses.push(`${key} = $${paramIndex}`);
        values.push(value);
        paramIndex++;
      }
    }

    if (setClauses.length === 0) {
      return this.findById(id);
    }

    values.push(id);
    const query = `UPDATE users SET ${setClauses.join(', ')} WHERE id = $${paramIndex} RETURNING *`;

    const result = await this.dbService.query<User>(query, values);
    return result.rows[0] || null;
  }
}
```

### 5. Service Layer with Dependency Injection

```typescript
// src/services/UserService.ts
import { User } from '../entities/User';
import { UserRepository } from '../repositories/UserRepository';
import { ERPIntegrationService } from './ERPIntegrationService';
import { Injectable } from '../decorators/injectable';
import { hashPassword } from '../utils/passwordUtils';

@Injectable()
export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly erpIntegrationService: ERPIntegrationService
  ) {}

  async createUser(userData: Partial<User>): Promise<User> {
    // Validate and transform data
    const user = new User({
      ...userData,
      password: await hashPassword(userData.password || ''),
      createdAt: new Date(),
      updatedAt: new Date(),
    });

    // Save to database
    const createdUser = await this.userRepository.create(user);

    // Sync with ERP system
    await this.erpIntegrationService.syncUser(createdUser);

    return createdUser;
  }

  async getUserById(id: string): Promise<User | null> {
    return this.userRepository.findById(id);
  }

  async updateUser(id: string, updates: Partial<User>): Promise<User | null> {
    const updatedUser = await this.userRepository.update(id, {
      ...updates,
      updatedAt: new Date(),
    });

    if (updatedUser) {
      await this.erpIntegrationService.syncUser(updatedUser);
    }

    return updatedUser;
  }
}
