### 6. Corporate System Integration Service

```typescript
// src/services/ERPIntegrationService.ts
import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { User } from '../entities/User';
import { Injectable } from '../decorators/injectable';
import { ERPUserDTO } from '../dtos/ERPUserDTO';

@Injectable()
export class ERPIntegrationService {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.corporateSystems.erp.baseUrl,
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': config.corporateSystems.erp.apiKey,
      },
    });
  }

  async syncUser(user: User): Promise<void> {
    try {
      const erpUser: ERPUserDTO = {
        employeeId: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        role: this.mapRoleToERPRole(user.role),
        isActive: true,
      };

      await this.client.post('/api/employees', erpUser);
    } catch (error) {
      console.error('Failed to sync user with ERP:', error);
      // Implement retry logic or dead letter queue
      throw error;
    }
  }

  private mapRoleToERPRole(role: string): string {
    const roleMapping: Record<string, string> = {
      admin: 'ADMIN',
      user: 'EMPLOYEE',
      manager: 'MANAGER',
    };

    return roleMapping[role] || 'EMPLOYEE';
  }
}
