export function setupUserRoutes(router: Router, userController: UserController): void {
  router.post(
    '/users',
    authenticate,
    authorize(['admin']),
    validateRequest(CreateUserDTO),
    (req, res, next) => userController.createUser(req, res, next)
  );

  router.get(
    '/users/:id',
    authenticate,
    (req, res, next) => userController.getUser(req, res, next)
  );

  router.put(
    '/users/:id',
    authenticate,
    authorize(['admin', 'manager']),
    validateRequest(UpdateUserDTO),
    (req, res, next) => userController.updateUser(req, res, next)
  );
}
