```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { setupMiddleware } from './middleware';
import { setupRoutes } from './routes';
import { setupErrorHandling } from './error-handling';
import { setupDatabase } from './database';
import { setupIntegrationClients } from './integrations';
import { setupLogging } from './logging';
import { setupHealthChecks } from './health';
import { config } from './config';

export class EnterpriseMicroservice {
  private app: express.Application;
  private server: ReturnType<typeof createServer>;
  private isShuttingDown = false;

  constructor() {
    this.app = express();
    this.server = createServer(this.app);
  }

  async initialize(): Promise<void> {
    // Initialize core components
    await setupDatabase();
    await setupIntegrationClients();
    setupLogging();
    setupMiddleware(this.app);
    setupRoutes(this.app);
    setupErrorHandling(this.app);
    setupHealthChecks(this.app);
  }

  start(): void {
    const port = config.port || 3000;
    this.server.listen(port, () => {
      console.log(`Microservice running on port ${port}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', this.shutdown.bind(this));
    process.on('SIGINT', this.shutdown.bind(this));
  }

  private async shutdown(): Promise<void> {
    if (this.isShuttingDown) return;

    this.isShuttingDown = true;
    console.log('Shutting down gracefully...');

    // Close database connections
    await this.closeDatabaseConnections();

    // Close integration clients
    await this.closeIntegrationClients();

    // Close server
    this.server.close(() => {
      console.log('Microservice shutdown complete');
      process.exit(0);
    });
  }

  private async closeDatabaseConnections(): Promise<void> {
    // Implementation for closing database connections
  }

  private async closeIntegrationClients(): Promise<void> {
    // Implementation for closing integration clients
  }
}

// Initialize and start the service
const service = new EnterpriseMicroservice();
service.initialize().then(() => service.start());
