```typescript
import axios, { AxiosInstance } from 'axios';
import { env } from '../config';
import { ExternalSystemException } from '../exceptions/ExternalSystemException';

export class ExternalSystemService {
  private httpClient: AxiosInstance;

  constructor() {
    this.httpClient = axios.create({
      baseURL: env.EXTERNAL_SYSTEM_API_URL,
      timeout: env.REQUEST_TIMEOUT,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${env.EXTERNAL_SYSTEM_API_KEY}`
      }
    });

    // Add request interceptor for logging and error handling
    this.httpClient.interceptors.request.use(
      (config) => {
        if (env.ENABLE_LOGGING) {
          console.log(`Request to ${config.url}:`, config.data);
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Add response interceptor for error handling
    this.httpClient.interceptors.response.use(
      (response) => {
        if (env.ENABLE_LOGGING) {
          console.log(`Response from ${response.config.url}:`, response.data);
        }
        return response;
      },
      (error) => {
        if (error.response) {
          // The request was made and the server responded with a status code
          // that falls out of the range of 2xx
          throw new ExternalSystemException(
            `External system error: ${error.response.status} - ${error.response.data.message || 'Unknown error'}`,
            error.response.status
          );
        } else if (error.request) {
          // The request was made but no response was received
          throw new ExternalSystemException('No response received from external system');
        } else {
          // Something happened in setting up the request that triggered an Error
          throw new ExternalSystemException(`Request setup error: ${error.message}`);
        }
      }
    );
  }

  async getEmployeeDetails(employeeId: string): Promise<any> {
    try {
      const response = await this.httpClient.get(`/employees/${employeeId}`);
      return response.data;
    } catch (error) {
      if (error instanceof ExternalSystemException) {
        throw error;
      }
      throw new ExternalSystemException('Failed to get employee details');
    }
  }

  async updateEmployeeStatus(employeeId: string, status: string): Promise<any> {
    try {
      const response = await this.httpClient.patch(`/employees/${employeeId}/status`, { status });
      return response.data;
    } catch (error) {
      if (error instanceof ExternalSystemException) {
        throw error;
      }
      throw new ExternalSystemException('Failed to update employee status');
    }
  }
}
```

### 8. Main Application Setup (`app.ts`)

```typescript
import express, { Application, Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import { env } from './config';
import { UserController } from './controllers/UserController';
import { UserService } from './services/UserService';
import { UserRepository } from './repositories/UserRepository';
import { errorHandler } from './middlewares/errorHandler';
import { notFoundHandler } from './middlewares/notFoundHandler';
import { requestLogger } from './middlewares/requestLogger';

class App {
  public app: Application;
  private userController: UserController;

  constructor() {
    this.app = express();
    this.initializeMiddlewares();
    this.initializeControllers();
    this.initializeErrorHandling();
  }

  private initializeMiddlewares() {
    // Security middleware
    this.app.use(helmet());

    // CORS configuration
    this.app.use(cors({
      origin: env.ALLOWED_ORIGINS.split(','),
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization']
    }));

    // Rate limiting
    const limiter = rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // limit each IP to 100 requests per windowMs
      message: 'Too many requests from this IP, please try again later'
    });
    this.app.use(limiter);

    // Request parsing
    this.app.use(express.json());
    this.app.use(express.urlencoded({ extended: true }));

    // Request logging
    if (env.ENABLE_LOGGING) {
      this.app.use(requestLogger);
    }
  }

  private initializeControllers() {
    // Initialize repositories
    const userRepository = new UserRepository();

    // Initialize services
    const userService = new UserService(userRepository);

    // Initialize controllers
    this.userController = new UserController(userService);

    // Set up routes
    this.app.post('/api/users', (req: Request, res: Response, next: NextFunction) =>
      this.userController.createUser(req, res, next)
    );
    this.app.get('/api/users/:id', (req: Request, res: Response, next: NextFunction) =>
      this.userController.getUser(req, res, next)
    );
    this.app.put('/api/users/:id', (req: Request, res: Response, next: NextFunction) =>
      this.userController.updateUser(req, res, next)
    );
    this.app.delete('/api/users/:id', (req: Request, res: Response, next: NextFunction) =>
      this.userController.deleteUser(req, res, next)
    );
    this.app.get('/api/users', (req: Request, res: Response, next: NextFunction) =>
      this.userController.listUsers(req, res, next)
    );
  }

  private initializeErrorHandling() {
    // 404 handler
    this.app.use(notFoundHandler);

    // Global error handler
    this.app.use(errorHandler);
  }

  public listen() {
    this.app.listen(env.PORT, () => {
      console.log(`Server running on port ${env.PORT} in ${env.NODE_ENV} mode`);
    });
  }
}

export default App;
```

### 9. Error Handling Middleware (`middlewares/errorHandler.ts`)

```typescript
import { Request, Response, NextFunction } from 'express';
import { ValidationException } from '../exceptions/ValidationException';
import { NotFoundException } from '../exceptions/NotFoundException';
import { ConflictException } from '../exceptions/ConflictException';
import { ExternalSystemException } from '../exceptions/ExternalSystemException';

export function errorHandler(
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
) {
  if (err instanceof ValidationException) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: err.errors
    });
  }

  if (err instanceof NotFoundException) {
    return res.status(404).json({
      status: 'error',
      message: err.message
    });
  }

  if (err instanceof ConflictException) {
    return res.status(409).json({
      status: 'error',
      message: err.message
    });
  }

  if (err instanceof ExternalSystemException) {
    return res.status(err.statusCode || 502).json({
      status: 'error',
      message: err.message
    });
  }

  // Default to 500 server error
  console.error('Unexpected error:', err);
  res.status(500).json({
    status: 'error',
    message: 'Internal server error'
  });
}
```

