import { initializeExternalIntegrations } from './integrations';

export class EnterpriseMicroservice {
  private app: Express;
  private port: number;

  constructor() {
    this.app = express();
    this.port = config.port;
    this.initializeMiddleware();
    this.initializeRoutes();
    this.initializeErrorHandling();
  }

  private initializeMiddleware(): void {
    // Security middleware
    this.app.use(helmet());
    this.app.use(cors({
      origin: config.allowedOrigins,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization']
    }));

    // Request processing
    this.app.use(express.json({ limit: '10kb' }));
    this.app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // Custom middleware
    this.app.use(requestLogger);
    this.app.use(authMiddleware);
  }

  private initializeRoutes(): void {
    this.app.use('/health', healthCheckRouter);
    this.app.use('/api', apiRouter);

    // 404 handler
    this.app.use((req: Request, res: Response) => {
      res.status(404).json({ error: 'Not Found' });
    });
  }

  private initializeErrorHandling(): void {
    this.app.use(errorHandler);
  }

  public async start(): Promise<void> {
    try {
      // Initialize critical systems
      await initializeDatabase();
      await initializeMessageQueue();
      await initializeExternalIntegrations();

      this.app.listen(this.port, () => {
        logger.info(`Microservice running on port ${this.port}`);
      });
    } catch (error) {
      logger.error('Failed to start microservice:', error);
      process.exit(1);
    }
  }
}

