## Message Queue Integration

```typescript
// src/messageQueue/index.ts
import { connect, Connection, Channel, ConsumeMessage } from 'amqplib';
import { config } from '../config';
import { logger } from '../utils/logger';
import { MessageQueueError } from '../errors';

let connection: Connection;
let channel: Channel;

export interface MessageQueueConfig {
  url: string;
  username: string;
  password: string;
}

export async function initializeMessageQueue(): Promise<void> {
  const mqConfig: MessageQueueConfig = {
    url: config.MESSAGE_QUEUE_URL,
    username: config.MESSAGE_QUEUE_USERNAME,
    password: config.MESSAGE_QUEUE_PASSWORD
  };

  try {
    connection = await connect(mqConfig.url, {
      username: mqConfig.username,
      password: mqConfig.password
    });

    channel = await connection.createChannel();
    logger.info('Message queue connection established');

    // Set up error handling
    connection.on('error', (err) => {
      logger.error('Message queue connection error:', err);
    });

    connection.on('close', () => {
      logger.warn('Message queue connection closed');
    });
  } catch (error) {
    logger.error('Message queue connection failed:', error);
    throw new MessageQueueError('Failed to connect to message queue');
  }
}

export async function publishMessage(
  exchange: string,
  routingKey: string,
  message: any
): Promise<void> {
  if (!channel) {
    throw new MessageQueueError('Message queue not initialized');
  }

  try {
    await channel.assertExchange(exchange, 'topic', { durable: true });
    channel.publish(
      exchange,
      routingKey,
      Buffer.from(JSON.stringify(message)),
      { persistent: true }
    );
  } catch (error) {
    logger.error('Failed to publish message:', error);
    throw new MessageQueueError('Failed to publish message');
  }
}

export async function consumeMessages(
  queue: string,
  callback: (message: ConsumeMessage) => Promise<void>
): Promise<void> {
  if (!channel) {
    throw new MessageQueueError('Message queue not initialized');
  }

  try {
    await channel.assertQueue(queue, { durable: true });
    await channel.consume(queue, async (msg) => {
      if (msg) {
        try {
          await callback(msg);
          channel.ack(msg);
        } catch (error) {
          logger.error('Message processing failed:', error);
          channel.nack(msg);
        }
      }
    });
  } catch (error) {
    logger.error('Failed to consume messages:', error);
    throw new MessageQueueError('Failed to consume messages');
  }
}
