## Repository Pattern for Data Access

```typescript
// src/repositories/userRepository.ts
import { User, CreateUser } from '../models/user';
import { query, withTransaction } from '../database';
import { DatabaseError } from '../errors';

export class UserRepository {
  static async findById(id: string): Promise<User | null> {
    const users = await query<User>('SELECT * FROM users WHERE id = $1', [id]);
    return users[0] || null;
  }

  static async findByEmail(email: string): Promise<User | null> {
    const users = await query<User>('SELECT * FROM users WHERE email = $1', [email]);
    return users[0] || null;
  }

  static async create(user: CreateUser): Promise<User> {
    const result = await query<User>(
      `INSERT INTO users (username, email, first_name, last_name, department, role)
       VALUES ($1, $2, $3, $4, $5, $6)
       RETURNING *`,
      [
        user.username,
        user.email,
        user.firstName,
        user.lastName,
        user.department,
        user.role
      ]
    );

    if (!result[0]) {
      throw new DatabaseError('Failed to create user');
    }

    return result[0];
  }

  static async update(id: string, updates: Partial<CreateUser>): Promise<User> {
    const fields = Object.keys(updates);
    if (fields.length === 0) {
      throw new Error('No fields to update');
    }

    const setClause = fields.map((field, index) => `${field} = $${index + 2}`).join(', ');
    const values = fields.map(field => (updates as any)[field]);

    const result = await query<User>(
      `UPDATE users SET ${setClause} WHERE id = $1 RETURNING *`,
      [id, ...values]
    );

    if (!result[0]) {
      throw new DatabaseError('Failed to update user');
    }

    return result[0];
  }

  static async delete(id: string): Promise<void> {
    await withTransaction(async (client) => {
      await client.query('DELETE FROM user_roles WHERE user_id = $1', [id]);
      await client.query('DELETE FROM users WHERE id = $1', [id]);
    });
  }
}
