## Service Layer with Business Logic

```typescript
// src/services/userService.ts
import { UserRepository } from '../repositories/userRepository';
import { User, CreateUser } from '../models/user';
import { BusinessError } from '../errors';
import { publishMessage } from '../messageQueue';

export class UserService {
  static async createUser(userData: CreateUser): Promise<User> {
    // Validate business rules
    const existingUser = await UserRepository.findByEmail(userData.email);
    if (existingUser) {
      throw new BusinessError('User with this email already exists');
    }

    // Create user
    const user = await UserRepository.create(userData);

    // Publish event
    await publishMessage('user.events', 'user.created', {
      userId: user.id,
      timestamp: new Date().toISOString()
    });

    return user;
  }

  static async getUserById(id: string): Promise<User> {
    const user = await UserRepository.findById(id);
    if (!user) {
      throw new BusinessError('User not found');
    }
    return user;
  }

  static async updateUser(id: string, updates: Partial<CreateUser>): Promise<User> {
    // Validate business rules
    if (updates.email) {
      const existingUser = await UserRepository.findByEmail(updates.email);
      if (existingUser && existingUser.id !== id) {
        throw new BusinessError('Email already in use by another user');
      }
    }

    // Update user
    const updatedUser = await UserRepository.update(id, updates);

    // Publish event
    await publishMessage('user.events', 'user.updated', {
      userId: updatedUser.id,
      timestamp: new Date().toISOString()
    });

    return updatedUser;
  }

  static async deleteUser(id: string): Promise<void> {
    // Validate business rules
    const user = await UserRepository.findById(id);
    if (!user) {
      throw new BusinessError('User not found');
    }

    // Delete user
    await UserRepository.delete(id);

    // Publish event
    await publishMessage('user.events', 'user.deleted', {
      userId: id,
      timestamp: new Date().toISOString()
    });
  }
}
