## Core Architecture

```typescript
// src/index.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { ApolloServer } from 'apollo-server-express';
import { buildSchema } from 'type-graphql';
import { Container } from 'typedi';
import { Logger } from './utils/logger';
import { config } from './config';
import { errorHandler } from './middleware/errorHandler';
import { authMiddleware } from './middleware/auth';
import { healthCheckRouter } from './routes/health';
import { metricsRouter } from './routes/metrics';
import { correlationIdMiddleware } from './middleware/correlationId';
import { requestLogger } from './middleware/requestLogger';
import { initializeDatabase } from './database';
import { initializeCache } from './cache';
import { initializeMessageBroker } from './messageBroker';
import { initializeCorporateIntegrations } from './integrations';
import { initializeHealthChecks } from './healthChecks';

async function bootstrap() {
  try {
    // Initialize core services
    const logger = new Logger(config.serviceName);
    logger.info('Starting application bootstrap');

    // Initialize database connection
    const dbConnection = await initializeDatabase(config.database);
    logger.info('Database connection established');

    // Initialize cache
    const cache = await initializeCache(config.cache);
    logger.info('Cache initialized');

    // Initialize message broker
    const messageBroker = await initializeMessageBroker(config.messageBroker);
    logger.info('Message broker initialized');

    // Initialize corporate integrations
    const corporateIntegrations = await initializeCorporateIntegrations(config.integrations);
    logger.info('Corporate integrations initialized');

    // Initialize health checks
    const healthChecks = initializeHealthChecks({
      dbConnection,
      cache,
      messageBroker,
      corporateIntegrations
    });

    // Create Express app
    const app = express();

    // Middleware setup
    app.use(express.json());
    app.use(correlationIdMiddleware());
    app.use(requestLogger(logger));
    app.use(authMiddleware(config.auth));
    app.use(errorHandler(logger));

    // Health check endpoints
    app.use('/health', healthCheckRouter(healthChecks));
    app.use('/metrics', metricsRouter());

    // GraphQL setup
    const schema = await buildSchema({
      resolvers: [__dirname + '/resolvers/**/*.{ts,js}'],
      container: Container,
      emitSchemaFile: config.graphql.emitSchemaFile,
      validate: true,
    });

    const apolloServer = new ApolloServer({
      schema,
      context: ({ req }) => ({
        user: req.user,
        dbConnection,
        cache,
        messageBroker,
        corporateIntegrations,
        logger,
      }),
      plugins: [/* Add Apollo plugins here */],
      formatError: (err) => {
        logger.error('GraphQL error', { error: err });
        return err;
      },
    });

    await apolloServer.start();
    apolloServer.applyMiddleware({ app, path: '/graphql' });

    // Create HTTP server
    const server = createServer(app);

    // Start server
    server.listen(config.port, () => {
      logger.info(`Server ready at http://localhost:${config.port}${apolloServer.graphqlPath}`);
      logger.info(`Health checks available at http://localhost:${config.port}/health`);
      logger.info(`Metrics available at http://localhost:${config.port}/metrics`);
    });

    // Handle shutdown
    process.on('SIGTERM', async () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      await apolloServer.stop();
      await dbConnection.close();
      await cache.disconnect();
      await messageBroker.disconnect();
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('Bootstrap failed:', error);
    process.exit(1);
  }
}

bootstrap();
