@Service()
@Resolver(() => User)
export class UserResolver {
  constructor(private readonly userService: UserService) {}

  @Query(() => [User])
  @Authorized('ADMIN')
  async users(@Ctx() ctx: Context): Promise<User[]> {
    ctx.logger.debug('Fetching all users');
    return this.userService.findAll();
  }

  @Query(() => User, { nullable: true })
  @Authorized()
  async user(@Arg('id') id: string, @Ctx() ctx: Context): Promise<User | undefined> {
    ctx.logger.debug(`Fetching user with ID: ${id}`);
    return this.userService.findById(id);
  }

  @Mutation(() => User)
  @Authorized('ADMIN')
  async createUser(
    @Arg('data') data: CreateUserInput,
    @Ctx() ctx: Context
  ): Promise<User> {
    ctx.logger.debug('Creating new user', { email: data.email });
    return this.userService.create(data);
  }

  @Mutation(() => User)
  @Authorized()
  async updateUser(
    @Arg('id') id: string,
