## Service Layer with Type Safety

```typescript
// src/services/UserService.ts
import { Service } from 'typedi';
import { InjectRepository } from 'typeorm-typedi-extensions';
import { Repository } from 'typeorm';
import { User } from '../entities/User';
import { CreateUserInput } from '../inputs/CreateUserInput';
import { UpdateUserInput } from '../inputs/UpdateUserInput';
import { hashPassword } from '../utils/password';
import { Logger } from '../utils/logger';

@Service()
export class UserService {
  private readonly logger: Logger;

  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>
  ) {
    this.logger = new Logger('UserService');
  }

  async findAll(): Promise<User[]> {
    try {
      return await this.userRepository.find();
    } catch (error) {
      this.logger.error('Failed to fetch users', { error });
      throw error;
    }
  }

  async findById(id: string): Promise<User | undefined> {
    try {
      return await this.userRepository.findOne(id);
    } catch (error) {
      this.logger.error(`Failed to fetch user with ID: ${id}`, { error });
      throw error;
    }
  }

  async create(data: CreateUserInput): Promise<User> {
    try {
      const user = this.userRepository.create({
        ...data,
        passwordHash: await hashPassword(data.password),
      });
      return await this.userRepository.save(user);
    } catch (error) {
      this.logger.error('Failed to create user', { error, email: data.email });
      throw error;
    }
  }

  async update(id: string, data: UpdateUserInput): Promise<User> {
    try {
      const user = await this.userRepository.findOne(id);
      if (!user) {
        throw new Error(`User with ID ${id} not found`);
      }

      Object.assign(user, data);
      if (data.password) {
        user.passwordHash = await hashPassword(data.password);
      }

      return await this.userRepository.save(user);
    } catch (error) {
      this.logger.error(`Failed to update user with ID: ${id}`, { error });
      throw error;
    }
  }

  async delete(id: string): Promise<boolean> {
    try {
      const result = await this.userRepository.delete(id);
      return result.affected === 1;
    } catch (error) {
      this.logger.error(`Failed to delete user with ID: ${id}`, { error });
      throw error;
    }
  }
}
