import { HealthCheck } from './HealthCheck';
import { Connection } from 'typeorm';

export class DatabaseHealthCheck implements HealthCheck {
  constructor(private readonly dbConnection: Connection) {}

  async check(): Promise<boolean> {
    try {
      await this.dbConnection.query('SELECT 1');
      return true;
    } catch (error) {
      return false;
    }
  }

  async details(): Promise<Record<string, any>> {
    try {
      const [result] = await this.dbConnection.query('SELECT VERSION() as version');
      return {
        status: 'healthy',
        version: result.version,
        isConnected: this.dbConnection.isConnected,
      };
    } catch (error) {
      return {
        status: 'unhealthy',
        error: error.message,
      };
    }
  }
