// src/core/api-client.ts - API client for external integrations
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { logger } from './logger';
import { ServiceError } from './errors';

interface ApiClientOptions {
  baseURL: string;
  timeout?: number;
  headers?: Record<string, string>;
}

export class ApiClient {
  private client: AxiosInstance;

  constructor(private options: ApiClientOptions) {
    this.client = axios.create({
      baseURL: options.baseURL,
      timeout: options.timeout || 10000,
      headers: options.headers || {},
    });

    this.setupInterceptors();
  }

  private setupInterceptors(): void {
    this.client.interceptors.request.use(
      (config) => {
        logger.debug('API Request', {
          method: config.method,
          url: config.url,
          headers: config.headers,
        });
        return config;
      },
      (error) => {
        logger.error('API Request Error', { error });
        return Promise.reject(error);
      }
    );

    this.client.interceptors.response.use(
      (response) => {
        logger.debug('API Response', {
          status: response.status,
          data: response.data,
        });
        return response;
      },
      (error) => {
        logger.error('API Response Error', {
          status: error.response?.status,
          data: error.response?.data,
        });
        return Promise.reject(error);
      }
    );
  }

  async get<T>(url: string, config?: AxiosRequestConfig): Promise<T> {
    return this.request<T>('get', url, config);
  }

  async post<T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> {
    return this.request<T>('post', url, { ...config, data });
  }

  async put<T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> {
    return this.request<T>('put', url, { ...config, data });
  }

  async delete<T>(url: string, config?: AxiosRequestConfig): Promise<T> {
    return this.request<T>('delete', url, config);
  }

  private async request<T>(
    method: 'get' | 'post' | 'put' | 'delete',
    url: string,
    config?: AxiosRequestConfig
  ): Promise<T> {
    try {
      const response: AxiosResponse<T> = await this.client.request({
        method,
        url,
        ...config,
      });
      return response.data;
    } catch (error) {
      if (axios.isAxiosError(error)) {
        const status = error.response?.status || 500;
        const message = error.response?.data?.message || error.message;
        throw new ServiceError(`API_${status}`, message, error.response?.data);
      }
      throw error;
    }
  }
}

// src/core/auth.ts - Authentication utilities
import jwt from 'jsonwebtoken';
import { config } from './config';
import { ServiceError } from './errors';

export interface AuthTokenPayload {
  sub: string; // User ID
  roles: string[];
  permissions: string[];
  exp: number;
  iat: number;
}

export const verifyToken = (token: string): AuthTokenPayload => {
  try {
    const decoded = jwt.verify(token, config.JWT_SECRET) as AuthTokenPayload;
    return decoded;
  } catch (error) {
    if (error instanceof jwt.JsonWebTokenError) {
      throw new ServiceError('AUTH_INVALID_TOKEN', 'Invalid or expired token');
    }
    throw error;
  }
};

export const hasPermission = (user: AuthTokenPayload, requiredPermission: string): boolean => {
  return user.permissions.includes(requiredPermission);
};

// src/core/middleware.ts - Express middleware
import { Request, Response, NextFunction } from 'express';
import { verifyToken, AuthTokenPayload } from './auth';
import { logger } from './logger';
import { ServiceError } from './errors';

declare global {
  namespace Express {
    interface Request {
      user?: AuthTokenPayload;
      correlationId: string;
    }
  }
}

export const correlationIdMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  req.correlationId = req.headers['x-correlation-id'] as string || crypto.randomUUID();
  res.setHeader('X-Correlation-ID', req.correlationId);
  next();
};

export const authMiddleware = async (
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      throw new ServiceError('AUTH_MISSING_TOKEN', 'Authorization token is required');
    }

    const token = authHeader.split(' ')[1];
    req.user = verifyToken(token);
    next();
  } catch (error) {
    next(error);
  }
};

export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  logger.error('Unhandled error', {
    error: err,
    correlationId: req.correlationId,
    path: req.path,
    method: req.method,
  });

  if (err instanceof ServiceError) {
    res.status(getStatusCodeForError(err.code)).json({
      success: false,
      error: {
        code: err.code,
        message: err.message,
        details: err.details,
      },
      metadata: {
        timestamp: new Date(),
        correlationId: req.correlationId,
      },
    });
    return;
  }

  if (err instanceof SyntaxError && 'status' in err && err.status === 400 && 'body' in err) {
    res.status(400).json({
      success: false,
      error: {
        code: 'INVALID_JSON',
        message: 'Invalid JSON payload',
      },
      metadata: {
        timestamp: new Date(),
        correlationId: req.correlationId,
      },
    });
    return;
  }

  res.status(500).json({
    success: false,
    error: {
      code: 'INTERNAL_SERVER_ERROR',
      message: 'An unexpected error occurred',
    },
    metadata: {
      timestamp: new Date(),
      correlationId: req.correlationId,
    },
  });
};

const getStatusCodeForError = (errorCode: string): number => {
  const errorCodeToStatus: Record<string, number> = {
    AUTH_MISSING_TOKEN: 401,
    AUTH_INVALID_TOKEN: 401,
    AUTH_INSUFFICIENT_PERMISSIONS: 403,
    VALIDATION_ERROR: 400,
    NOT_FOUND: 404,
    CONFLICT: 409,
    ERP_INTEGRATION_ERROR: 502,
  };

  return errorCodeToStatus[errorCode] || 500;
};
