// src/modules/erp/service.ts - ERP service with caching
import { ErpClient } from './client';
import { ErpCustomer, ErpOrder } from './types';
import { getRedisClient } from '../../core/redis';
import { logger } from '../../core/logger';

export class ErpService {
  private erpClient: ErpClient;
  private redisClient = getRedisClient();

  constructor() {
    this.erpClient = new ErpClient();
  }

  async getCustomer(customerId: string): Promise<ErpCustomer> {
    const cacheKey = `erp:customer:${customerId}`;

    try {
      const cachedCustomer = await this.redisClient.get(cacheKey);
      if (cachedCustomer) {
        logger.debug('Cache hit for customer', { customerId });
        return JSON.parse(cachedCustomer) as ErpCustomer;
      }

      logger.debug('Cache miss for customer, fetching from ERP', { customerId });
      const customer = await this.erpClient.getCustomer(customerId);

      await this.redisClient.setEx(cacheKey, 3600, JSON.stringify(customer)); // Cache for 1 hour
      return customer;
    } catch (error) {
      logger.error('Failed to get customer from ERP', { customerId, error });
      throw error;
    }
  }

  async createOrder(order: Omit<ErpOrder, 'id'>): Promise<ErpOrder> {
    try {
      const createdOrder = await this.erpClient.createOrder(order);

      // Invalidate customer cache if order affects customer data
      await this.redisClient.del(`erp:customer:${order.customerId}`);

      return createdOrder;
    } catch (error) {
      logger.error('Failed to create order in ERP', { order, error });
      throw error;
    }
  }

  async getOrder(orderId: string): Promise<ErpOrder> {
    const cacheKey = `erp:order:${orderId}`;

    try {
      const cachedOrder = await this.redisClient.get(cacheKey);
      if (cachedOrder) {
        logger.debug('Cache hit for order', { orderId });
        return JSON.parse(cachedOrder) as ErpOrder;
      }

      logger.debug('Cache miss for order, fetching from ERP', { orderId });
      const order = await this.erpClient.getOrder(orderId);

      await this.redisClient.setEx(cacheKey, 3600, JSON.stringify(order)); // Cache for 1 hour
      return order;
    } catch (error) {
      logger.error('Failed to get order from ERP', { orderId, error });
      throw error;
    }
  }
}
