// src/modules/orders/service.ts - Business logic
import { OrderRepository } from './repository';
import { Order } from './entity';
import { CreateOrderDto, UpdateOrderStatusDto } from './types';
import { ErpService } from '../erp/service';
import { validateOrReject } from '../../core/validation';
import { CreateOrderSchema, UpdateOrderStatusSchema } from './types';
import { ServiceError } from '../../core/errors';

export class OrderService {
  private orderRepository: OrderRepository;
  private erpService: ErpService;

  constructor() {
    this.orderRepository = new OrderRepository();
    this.erpService = new ErpService();
  }

  async createOrder(data: CreateOrderDto): Promise<Order> {
    // Validate input
    const validatedData = await validateOrReject(CreateOrderSchema, data);

    // Calculate total amount
    const totalAmount = validatedData.items.reduce((sum, item) => {
      const itemTotal = item.quantity * item.unitPrice * (1 - item.discount / 100);
      const taxAmount = itemTotal * (item.taxRate / 100);
      return sum + itemTotal + taxAmount;
    }, 0);

    // Create order in local database
    const order = await this.orderRepository.create({
      ...validatedData,
      totalAmount,
      status: 'draft',
    });

    // Create order in ERP system
    try {
      const erpOrder = await this.erpService.createOrder({
        customerId: order.customerId,
        orderDate: new Date(),
        status: 'draft',
        items: order.items,
        totalAmount: order.totalAmount,
        currency: order.currency,
        paymentTerms: order.paymentTerms,
        deliveryAddress: order.deliveryAddress,
        notes: order.notes,
      });

      // Update local order with ERP order ID
      await this.orderRepository.updateErpOrderId(order.id, erpOrder.id);
    } catch (error) {
      // Log error but don't fail the operation - we'll have a background job to sync
      console.error('Failed to create order in ERP', error);
    }

    return order;
  }

  async getOrder(id: string): Promise<Order> {
    const order = await this.orderRepository.findById(id);
    if (!order) {
      throw new ServiceError('NOT_FOUND', 'Order not found');
    }
    return order;
  }

  async updateOrderStatus(id: string, data: UpdateOrderStatusDto): Promise<Order> {
    // Validate input
    const validatedData = await validateOrReject(UpdateOrderStatusSchema, data);

    // Get current order
    const order = await this.getOrder(id);

    // Update status in local database
    const updatedOrder = await this.orderRepository.updateStatus(id, validatedData.status);
    if (!updatedOrder) {
      throw new ServiceError('NOT_FOUND', 'Order not found');
    }

    // Update status in ERP if order was synced
    if (updatedOrder.erpOrderId) {
      try {
        await this.erpService.updateOrderStatus(updatedOrder.erpOrderId, validatedData.status);
      } catch (error) {
        // Log error but don't fail the operation - we'll have a background job to sync
        console.error('Failed to update order status in ERP', error);
      }
    }

    return updatedOrder;
  }

  async getCustomerOrders(customerId: string): Promise<Order[]> {
    return this.orderRepository.findByCustomerId(customerId);
  }
}
