    this.orderService = new OrderService();
  }

  async createOrder(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      if (!req.user || !hasPermission(req.user, 'orders:create')) {
        res.status(403).json({
          success: false,
          error: {
            code: 'AUTH_INSUFFICIENT_PERMISSIONS',
            message: 'You do not have permission to create orders',
          },
        });
        return;
      }

      const order = await this.orderService.createOrder(req.body as CreateOrderDto);

      const response: ApiResponse<Order> = {
        success: true,
        data: order,
        metadata: {
          timestamp: new Date(),
          correlationId: req.correlationId,
        },
      };

      res.status(201).json(response);
    } catch (error) {
      next(error);
    }
  }

  async getOrder(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      if (!req.user || !hasPermission(req.user, 'orders:read')) {
        res.status(403).json({
          success: false,
          error: {
            code: 'AUTH_INSUFFICIENT_PERMISSIONS',
            message: 'You do not have permission to view orders',
          },
        });
        return;
      }

      const order = await this.orderService.getOrder(req.params.id);

      const response: ApiResponse<Order> = {
        success: true,
        data: order,
        metadata: {
          timestamp: new Date(),
          correlationId: req.correlationId,
        },
      };

      res.json(response);
    } catch (error) {
      next(error);
    }
  }

