// src/utils/validator.ts - Comprehensive validation
import { z, ZodSchema } from 'zod';
import { ValidationError } from '../errors/validation-error';

// Example schema
export const OrderCreateRequestSchema = z.object({
  orderId: z.string().uuid(),
  customerId: z.string().min(3).max(50),
  amount: z.number().positive(),
  currency: z.string().length(3).toUpperCase(),
  requestedBy: z.string().email(),
  department: z.string().min(2).max(50),
  notes: z.string().max(500).optional(),
  items: z.array(
    z.object({
      productId: z.string().min(3).max(50),
      quantity: z.number().int().positive(),
      unitPrice: z.number().positive()
    })
  ).min(1)
});

export function validate<T>(data: unknown, schema: ZodSchema<T>): T {
  try {
    return schema.parse(data);
  } catch (error) {
    if (error instanceof z.ZodError) {
      throw new ValidationError('VALIDATION_FAILED', 'Request validation failed', error.errors);
    }
    throw error;
  }
}
