### 5. `src/services/userService.ts` - Business Logic

```typescript
import { UserRepository } from '../repositories/userRepository';
import { UserDto, CreateUserDto, UpdateUserDto } from '../dto/userDto';
import { IUser } from '../types/commonTypes';
import { MessageQueueService } from '../config/messageQueue';
import { Logger } from '../utils/logger';

export class UserService {
  private userRepository: UserRepository;
  private messageQueue: MessageQueueService;
  private logger: Logger;

  constructor() {
    this.userRepository = new UserRepository();
    this.messageQueue = new MessageQueueService();
    this.logger = new Logger('UserService');
  }

  async createUser(userData: CreateUserDto): Promise<UserDto> {
    try {
      // Validate input
      if (!userData.username || !userData.email || !userData.password) {
        throw new Error('Missing required fields');
      }

      // Check if user exists
      const existingUser = await this.userRepository.findByEmail(userData.email);
      if (existingUser) {
        throw new Error('User with this email already exists');
      }

      // Create user
      const newUser = await this.userRepository.create({
        username: userData.username,
        email: userData.email,
        passwordHash: userData.password, // In production, hash the password
        role: userData.role || 'USER'
      });

      // Publish event to message queue
      await this.messageQueue.publish('user.created', {
        userId: newUser.id,
        email: newUser.email
      });

      this.logger.info(`User created: ${newUser.id}`);
      return UserDto.fromEntity(newUser);
    } catch (error) {
      this.logger.error(`Error creating user: ${error instanceof Error ? error.message : 'Unknown error'}`);
      throw error;
    }
  }

  async getUserById(id: string): Promise<UserDto | null> {
    try {
      const user = await this.userRepository.findById(id);
      if (!user) return null;

      return UserDto.fromEntity(user);
    } catch (error) {
      this.logger.error(`Error getting user: ${error instanceof Error ? error.message : 'Unknown error'}`);
      throw error;
    }
  }

  async updateUser(id: string, updateData: UpdateUserDto): Promise<UserDto | null> {
    try {
      const updatedUser = await this.userRepository.update(id, {
        username: updateData.username,
        email: updateData.email,
        role: updateData.role
      });

      if (!updatedUser) return null;

      // Publish event to message queue
      await this.messageQueue.publish('user.updated', {
        userId: updatedUser.id,
        changes: updateData
      });

      this.logger.info(`User updated: ${updatedUser.id}`);
      return UserDto.fromEntity(updatedUser);
    } catch (error) {
      this.logger.error(`Error updating user: ${error instanceof Error ? error.message : 'Unknown error'}`);
      throw error;
    }
  }

  async deleteUser(id: string): Promise<boolean> {
    try {
      const result = await this.userRepository.delete(id);

      if (result) {
        // Publish event to message queue
        await this.messageQueue.publish('user.deleted', { userId: id });
        this.logger.info(`User deleted: ${id}`);
      }

      return result;
    } catch (error) {
      this.logger.error(`Error deleting user: ${error instanceof Error ? error.message : 'Unknown error'}`);
      throw error;
    }
  }
}
```

