### 8. `src/config/messageQueue.ts` - Message Queue Integration

```typescript
import amqp, { Connection, Channel } from 'amqplib';

export class MessageQueueService {
  private connection: Connection | null = null;
  private channel: Channel | null = null;

  async connect(): Promise<void> {
    try {
      this.connection = await amqp.connect(process.env.RABBITMQ_URL || 'amqp://localhost');
      this.channel = await this.connection.createChannel();

      // Ensure queues exist
      await this.channel.assertQueue('user.created', { durable: true });
      await this.channel.assertQueue('user.updated', { durable: true });
      await this.channel.assertQueue('user.deleted', { durable: true });

      console.log('Connected to message queue');
    } catch (error) {
      console.error('Message queue connection error:', error);
      throw error;
    }
  }

  async publish(queue: string, message: any): Promise<void> {
    if (!this.channel) {
      throw new Error('Message queue not connected');
    }

    this.channel.sendToQueue(queue, Buffer.from(JSON.stringify(message)), {
      persistent: true
    });
  }

  async close(): Promise<void> {
    if (this.channel) await this.channel.close();
    if (this.connection) await this.connection.close();
  }
}
```

