    const corporateResponse = await corporateSystemClient.createUser(user);

    if (corporateResponse.status === 'error') {
      throw new Error(corporateResponse.message || 'Corporate system integration failed');
    }

    logger.info('User created successfully', { userId: user.id });
    res.status(201).json({ user, corporateSystemResponse: corporateResponse.data });
  } catch (error) {
    next(error);
  }
});

// Error handling middleware
app.use(errorHandler);

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});
