// src/repositories/user.repository.ts
import { UserEntity } from '../entities/user.entity';

export interface IUserRepository {
  create(user: Omit<UserEntity, 'id' | 'createdAt' | 'updatedAt'>): Promise<UserEntity>;
  findById(id: string): Promise<UserEntity | null>;
  findByEmail(email: string): Promise<UserEntity | null>;
  update(id: string, updates: Partial<UserEntity>): Promise<UserEntity>;
  delete(id: string): Promise<void>;
}

export class UserRepository implements IUserRepository {
  // Implementation would connect to your database
  // This is a mock implementation
  private users: UserEntity[] = [];

  async create(userData: Omit<UserEntity, 'id' | 'createdAt' | 'updatedAt'>): Promise<UserEntity> {
    const user = new UserEntity(
      Math.random().toString(36).substring(2, 15),
      userData.username,
      userData.email,
      userData.passwordHash,
      userData.department,
      userData.role,
      new Date(),
      new Date()
    );
    this.users.push(user);
    return user;
  }

  async findById(id: string): Promise<UserEntity | null> {
    return this.users.find(user => user.id === id) || null;
  }

  async findByEmail(email: string): Promise<UserEntity | null> {
    return this.users.find(user => user.email === email) || null;
  }

  async update(id: string, updates: Partial<UserEntity>): Promise<UserEntity> {
    const userIndex = this.users.findIndex(user => user.id === id);
    if (userIndex === -1) throw new Error('User not found');

    const updatedUser = { ...this.users[userIndex], ...updates, updatedAt: new Date() };
    this.users[userIndex] = updatedUser;
    return updatedUser;
  }

  async delete(id: string): Promise<void> {
    this.users = this.users.filter(user => user.id !== id);
  }
}
