// src/app.ts
import express from 'express';
import { UserController } from './controllers/user.controller';
import { UserService } from './services/user.service';
import { UserRepository } from './repositories/user.repository';
import { AuthMiddleware } from './middlewares/auth.middleware';
import { errorHandler } from './middlewares/error.middleware';
import { IAuthService } from './interfaces/auth.interface';

export class App {
  public app: express.Application;
  private userController: UserController;
  private authMiddleware: AuthMiddleware;

  constructor(authService: IAuthService) {
    this.app = express();
    this.authMiddleware = new AuthMiddleware(authService);

    // Initialize dependencies
    const userRepository = new UserRepository();
    const userService = new UserService(userRepository);
    this.userController = new UserController(userService);

    this.configureMiddleware();
    this.configureRoutes();
    this.configureErrorHandling();
  }

  private configureMiddleware() {
    this.app.use(express.json());
    // Add other middleware like CORS, rate limiting, etc.
  }

  private configureRoutes() {
    const router = express.Router();

    // Public routes
    router.post('/users', this.userController.createUser.bind(this.userController));

    // Protected routes
    router.use(this.authMiddleware.authenticate.bind(this.authMiddleware));
    router.get('/users/:id', this.userController.getUser.bind(this.userController));
    router.put('/users/:id', this.authMiddleware.authorize(['ADMIN', 'MANAGER']), this.userController.updateUser.bind(this.userController));
    router.delete('/users/:id', this.authMiddleware.authorize(['ADMIN']), this.userController.deleteUser.bind(this.userController));

    this.app.use('/api', router);
  }

  private configureErrorHandling() {
    this.app.use(errorHandler);
  }
}
