import { Corporate } from '../types/corporate';

export class AuthService implements Corporate.AuthSystem {
  private authServerUrl: string;

  constructor() {
    this.authServerUrl = process.env.CORP_AUTH_SERVER || 'https://corp-auth.example.com';
  }

  async validateToken(token: string): Promise<Corporate.AuthToken> {
    // In a real implementation, this would call the corporate auth system
    const response = await fetch(`${this.authServerUrl}/validate`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}` }
    });

    if (!response.ok) {
      throw new Error('Invalid token');
    }

    return response.json() as Promise<Corporate.AuthToken>;
  }

  async getUserDetails(userId: string): Promise<API.User> {
    // In a real implementation, this would call the corporate user service
    const response = await fetch(`${this.authServerUrl}/users/${userId}`);

    if (!response.ok) {
      throw new Error('User not found');
    }

    return response.json() as Promise<API.User>;
  }
}
