import { Request, Response } from 'express';
import { UserService } from '../services/user.service';
import { AuthService } from '../services/auth.service';
import { logger } from '../utils/logger';

export class UserController {
  private userService: UserService;
  private authService: AuthService;

  constructor() {
    this.userService = new UserService();
    this.authService = new AuthService();
  }

  async createUser(req: Request, res: Response): Promise<void> {
    try {
      const authToken = await this.authService.validateToken(req.headers.authorization?.split(' ')[1] || '');
      if (!authToken.roles.includes('ADMIN')) {
        res.status(403).json({ error: 'Forbidden' });
        return;
      }

      const userData: API.CreateUserRequest = req.body;
      const user = await this.userService.createUser(userData);
      res.status(201).json(user);
    } catch (error) {
      logger.error('Error creating user', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }

  async getUser(req: Request, res: Response): Promise<void> {
    try {
      const authToken = await this.authService.validateToken(req.headers.authorization?.split(' ')[1] || '');
      const user = await this.userService.getUser(req.params.id);

      // Ensure users can only access their own data unless they're admins
      if (user.id !== authToken.userId && !authToken.roles.includes('ADMIN')) {
        res.status(403).json({ error: 'Forbidden' });
        return;
      }

      res.json(user);
    } catch (error) {
      logger.error('Error getting user', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
}
```

