import { User } from '../models/user.model';
import { CreateUserDto, UserResponseDto } from '../dto/user.dto';
import { CorporateDirectoryClient } from '../clients/corporate-directory.client';

export class UserService {
  constructor(private corporateDirectory: CorporateDirectoryClient) {}

  async createUser(userData: CreateUserDto): Promise<UserResponseDto> {
    // Validate input
    if (!userData.email.includes('@')) {
      throw new Error('Invalid email format');
    }

    // Check if department exists in corporate directory
    const department = await this.corporateDirectory.getDepartment(userData.departmentId);
    if (!department) {
      throw new Error('Department not found');
    }

    // Create user in our system
    const user: User = {
      id: generateId(),
      email: userData.email,
      name: userData.name,
      departmentId: userData.departmentId,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Map to response DTO
    return {
      id: user.id,
      email: user.email,
      name: user.name,
      department: department.name,
      createdAt: user.createdAt,
    };
  }
}
