  name: string;
  location: string;
}

export class CorporateDirectoryClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.corporateDirectory.baseUrl,
      headers: {
        'Authorization': `Bearer ${config.corporateDirectory.apiKey}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async getDepartment(departmentId: string): Promise<Department | null> {
    try {
      const response = await this.client.get(`/departments/${departmentId}`);
      return response.data;
    } catch (error) {
      if (error.response?.status === 404) {
        return null;
      }
      throw new Error(`Failed to fetch department: ${error.message}`);
    }
  }
}
