// src/index.ts
import express, { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import winston from 'winston';
import dotenv from 'dotenv';

// Load environment variables with validation
dotenv.config();

const envSchema = z.object({
  PORT: z.string().regex(/^\d+$/).transform(Number),
  CORPORATE_API_URL: z.string().url(),
  CORPORATE_API_KEY: z.string().min(1),
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
});

const env = envSchema.parse(process.env);

// Configure structured logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Define strict types for our domain
interface CorporateUser {
  id: string;
  name: string;
  email: string;
  department: string;
  roles: string[];
}

interface ServiceResponse<T> {
  success: boolean;
  data?: T;
  error?: {
    code: string;
    message: string;
    details?: unknown;
  };
}

// Corporate API client with type-safe integration
class CorporateApiClient {
  private baseUrl: string;
  private apiKey: string;

  constructor(baseUrl: string, apiKey: string) {
    this.baseUrl = baseUrl;
    this.apiKey = apiKey;
  }

  async getUser(userId: string): Promise<ServiceResponse<CorporateUser>> {
    try {
      const response = await fetch(`${this.baseUrl}/users/${userId}`, {
        headers: {
          'Authorization': `Bearer ${this.apiKey}`,
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Corporate API returned ${response.status}`);
      }

      const data = await response.json();

      // Validate the response against our type
      const userSchema = z.object({
        id: z.string(),
        name: z.string(),
        email: z.string().email(),
        department: z.string(),
        roles: z.array(z.string()),
      });

      const validatedData = userSchema.parse(data);

      return {
        success: true,
        data: validatedData,
      };
    } catch (error) {
      logger.error('Failed to fetch user from corporate API', { error, userId });
      return {
        success: false,
        error: {
          code: 'CORPORATE_API_ERROR',
          message: 'Failed to fetch user information',
          details: error instanceof Error ? error.message : String(error),
        },
      };
    }
  }
}

// Create Express app with type safety
const app = express();

// Middleware for request logging
app.use((req: Request, res: Response, next: NextFunction) => {
  logger.info('Incoming request', {
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  next();
});

// Health check endpoint
app.get('/health', (req: Request, res: Response) => {
  res.status(200).json({ status: 'healthy' });
});

// Corporate user integration endpoint
app.get('/users/:userId', async (req: Request, res: Response) => {
  const { userId } = req.params;

  // Validate input
  const userIdSchema = z.string().uuid();
  const validationResult = userIdSchema.safeParse(userId);

  if (!validationResult.success) {
    return res.status(400).json({
      success: false,
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Invalid user ID format',
        details: validationResult.error.errors,
      },
    });
  }

  const corporateApi = new CorporateApiClient(
    env.CORPORATE_API_URL,
    env.CORPORATE_API_KEY
  );

  const result = await corporateApi.getUser(userId);

  if (!result.success) {
    return res.status(500).json(result);
  }

  res.status(200).json(result);
});

// Error handling middleware
app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
  logger.error('Unhandled error', { error: err.message, stack: err.stack });
  res.status(500).json({
    success: false,
    error: {
      code: 'INTERNAL_ERROR',
      message: 'An unexpected error occurred',
    },
  });
});

// Start server
const PORT = env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
  logger.info(`Environment: ${env.NODE_ENV}`);
});
```

