  async checkHealth(): Promise<HealthCheckResponse> {
    const corporateSystemStatus = await this.checkCorporateSystemHealth();

    return {
      status: 'UP',
      serviceName: 'enterprise-microservice',
      timestamp: new Date().toISOString(),
      dependencies: {
        database: 'UP', // In a real app, you'd check actual DB connection
        corporateSystem: corporateSystemStatus
      }
    };
  }

  private async checkCorporateSystemHealth(): Promise<'UP' | 'DOWN'> {
    try {
      const response = await axios.get(`${config.corporateSystem.baseUrl}/health`, {
        headers: {
          'Authorization': `Bearer ${config.corporateSystem.apiKey}`
        },
        timeout: config.corporateSystem.timeout
