import { validate } from 'class-validator';
import { plainToClass } from 'class-transformer';
import { Request, Response, NextFunction } from 'express';

export async function validateDto(dto: object): Promise<void> {
  const errors = await validate(dto);
  if (errors.length > 0) {
    throw new Error(`Validation failed: ${errors.map(e => e.toString()).join(', ')}`);
  }
}

export function validateRequestDto(dtoClass: any) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      const output = plainToClass(dtoClass, req.body);
      await validateDto(output);
      req.body = output;
      next();
    } catch (error) {
      next(error);
    }
  };
}
```

