# Minimal Enterprise-Grade Backend Microservice

Below is a minimal but production-ready microservice implementation that meets enterprise requirements for type safety, integration, and maintainability.

## Core Architecture

```typescript
// src/index.ts - Main service entry point
import express from 'express';
import { validateRequest } from './middleware/validation';
import { errorHandler } from './middleware/errorHandler';
import { logger } from './utils/logger';
import { config } from './config';
import { healthCheckRouter } from './routes/healthCheck';
import { apiRouter } from './routes/api';
import { initializeDatabase } from './database';
import { initializeEventBus } from './eventBus';
import { initializeAuth } from './auth';

async function bootstrap() {
  const app = express();

  // Initialize core systems
  await initializeDatabase();
  await initializeEventBus();
  await initializeAuth();

  // Middleware
  app.use(express.json());
  app.use(logger.middleware);

  // Routes
  app.use('/health', healthCheckRouter);
  app.use('/api', validateRequest, apiRouter);

  // Error handling
  app.use(errorHandler);

  // Start server
  const server = app.listen(config.port, () => {
    logger.info(`Service running on port ${config.port}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    logger.info('SIGTERM received. Shutting down gracefully...');
    server.close(() => {
      logger.info('Server closed.');
      process.exit(0);
    });
  });

  return server;
}

// Start the service
bootstrap().catch(err => {
  logger.error('Service failed to start:', err);
  process.exit(1);
});
```

