## Service Layer with Dependency Injection

```typescript
// src/services/userService.ts
import { User, UserSchema } from '../models/user';
import { Database } from '../database';
import { EventBus } from '../eventBus';
import { logger } from '../utils/logger';

interface CreateUserParams {
  username: string;
  email: string;
  firstName: string;
  lastName: string;
}

export class UserService {
  constructor(
    private db: Database,
    private eventBus: EventBus
  ) {}

  async createUser(params: CreateUserParams): Promise<User> {
    const query = `
      INSERT INTO users (username, email, first_name, last_name)
      VALUES ($1, $2, $3, $4)
      RETURNING *;
    `;

    const values = [params.username, params.email, params.firstName, params.lastName];

    try {
      const [user] = await this.db.query<User>(query, values);
      const validatedUser = UserSchema.parse(user);

      // Publish event
      await this.eventBus.publish('user.created', validatedUser);

      return validatedUser;
    } catch (err) {
      logger.error('Error creating user:', err);
      throw err;
    }
  }

  async getUserById(id: string): Promise<User | null> {
    const query = 'SELECT * FROM users WHERE id = $1';
    try {
      const [user] = await this.db.query<User>(query, [id]);
      return user ? UserSchema.parse(user) : null;
    } catch (err) {
      logger.error('Error fetching user:', err);
      throw err;
    }
  }
}
