### 4. Service Layer with Integration

```typescript
// src/services/user.service.ts
import { UserEntity } from '../entities/user.entity';
import { UserRepository } from '../repositories/user.repository';
import { ERPService } from './corporate-integration/erp.service';
import { CreateUserDto, UpdateUserDto } from '../dtos/user.dto';

export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly erpService: ERPService
  ) {}

  async createUser(userData: CreateUserDto): Promise<UserEntity> {
    // Validate ERP customer if ID is provided
    if (userData.erpCustomerId) {
      const erpCustomer = await this.erpService.getCustomerDetails(userData.erpCustomerId);
      if (!erpCustomer) {
        throw new Error('ERP customer not found');
      }
    }

    return this.userRepository.create(userData);
  }

  async updateUser(id: string, userData: UpdateUserDto): Promise<UserEntity> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new Error('User not found');
    }

    // If ERP ID is being updated, validate it first
    if (userData.erpCustomerId && userData.erpCustomerId !== existingUser.erpCustomerId) {
      const erpCustomer = await this.erpService.getCustomerDetails(userData.erpCustomerId);
      if (!erpCustomer) {
        throw new Error('ERP customer not found');
      }
    }

    return this.userRepository.update(id, userData);
  }

  async getUserWithERPDetails(id: string): Promise<UserEntity & { erpDetails?: ERPCustomerDetails }> {
    const user = await this.userRepository.findById(id);
    if (!user || !user.erpCustomerId) {
      return user;
    }

    const erpDetails = await this.erpService.getCustomerDetails(user.erpCustomerId);
    return { ...user, erpDetails };
  }
}
