```typescript
// src/services/eventBus.ts
import { Kafka } from 'kafkajs';
import { logger } from '../utils/logger';

let kafka: Kafka;

export const initializeEventBus = (config: {
  brokers: string[];
  clientId: string;
}) => {
  if (!kafka) {
    kafka = new Kafka({
      clientId: config.clientId,
      brokers: config.brokers,
    });

    // Test connection
    const admin = kafka.admin();
    admin.connect()
      .then(() => logger.info('Connected to event bus'))
      .catch((err) => logger.error('Event bus connection failed', err))
      .finally(() => admin.disconnect());
  }

  return {
    producer: kafka.producer(),
    consumer: kafka.consumer({ groupId: 'microservice-group' }),
    async publish(topic: string, message: unknown) {
      const producer = kafka.producer();
      await producer.connect();
      await producer.send({
        topic,
        messages: [{ value: JSON.stringify(message) }],
      });
      await producer.disconnect();
    },
    async subscribe(topic: string, handler: (message: unknown) => Promise<void>) {
      const consumer = kafka.consumer({ groupId: 'microservice-group' });
      await consumer.connect();
      await consumer.subscribe({ topic, fromBeginning: true });

      await consumer.run({
        eachMessage: async ({ message }) => {
          try {
            const value = message.value?.toString();
            if (value) {
              const parsed = JSON.parse(value);
              await handler(parsed);
            }
          } catch (err) {
            logger.error('Error processing message', err);
          }
        },
      });
    },
  };
};

export type EventBus = ReturnType<typeof initializeEventBus>;
