```typescript
// src/external-systems.ts - Type-safe external system integration
import axios, { AxiosInstance, AxiosRequestConfig } from 'axios';
import { config } from './config';
import { logger } from './utils/logger';

interface ExternalSystemClient {
  get<T>(path: string, params?: any): Promise<T>;
  post<T>(path: string, data?: any): Promise<T>;
  put<T>(path: string, data?: any): Promise<T>;
  delete<T>(path: string): Promise<T>;
}

class ExternalSystemClientImpl implements ExternalSystemClient {
  private client: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.client = axios.create({
      baseURL,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      timeout: config.REQUEST_TIMEOUT,
    });

    // Add request interceptor for logging
    this.client.interceptors.request.use((config) => {
      logger.debug('External system request:', {
        method: config.method,
        url: config.url,
        params: config.params,
        data: config.data,
      });
      return config;
    });

    // Add response interceptor for logging
    this.client.interceptors.response.use(
      (response) => {
        logger.debug('External system response:', {
          status: response.status,
          data: response.data,
        });
        return response;
      },
      (error) => {
        logger.error('External system error:', {
          message: error.message,
          config: error.config,
          response: error.response?.data,
        });
        return Promise.reject(error);
      }
    );
  }

  async get<T>(path: string, params?: any): Promise<T> {
    const response = await this.client.get<T>(path, { params });
    return response.data;
  }

  async post<T>(path: string, data?: any): Promise<T> {
    const response = await this.client.post<T>(path, data);
    return response.data;
  }

  async put<T>(path: string, data?: any): Promise<T> {
    const response = await this.client.put<T>(path, data);
    return response.data;
  }

  async delete<T>(path: string): Promise<T> {
    const response = await this.client.delete<T>(path);
    return response.data;
  }
}

let externalSystemClient: ExternalSystemClient;

export async function initializeExternalSystems(): Promise<void> {
  externalSystemClient = new ExternalSystemClientImpl(
    config.EXTERNAL_SYSTEM_BASE_URL,
    config.EXTERNAL_SYSTEM_API_KEY
  );

  // Test the connection
  try {
    await externalSystemClient.get('/health');
    logger.info('External system connection established');
  } catch (error) {
    logger.error('External system connection failed:', error);
    throw error;
  }
}

export function getExternalSystemClient(): ExternalSystemClient {
  if (!externalSystemClient) {
    throw new Error('External system client not initialized');
  }
  return externalSystemClient;
}
