// src/controllers/user.ts - Type-safe controller
import { Request, Response } from 'express';
import { query } from '../database';
import { getExternalSystemClient } from '../external-systems';
import { logger } from '../utils/logger';

interface User {
  id: string;
  name: string;
  email: string;
  createdAt: Date;
}

export async function getUser(req: Request, res: Response): Promise<void> {
  try {
    const { id } = req.params;

    // Query database
    const users = await query<User>('SELECT * FROM users WHERE id = $1', [id]);

    if (users.length === 0) {
      res.status(404).json({ error: 'User not found' });
      return;
    }

    // Call external system for additional data
    const externalData = await getExternalSystemClient().get<any>(
      `/users/${id}/external-data`
    );

    res.json({
      ...users[0],
      externalData,
    });
  } catch (error) {
    logger.error('Error getting user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}

export async function createUser(req: Request, res: Response): Promise<void> {
  try {
    const { name, email } = req.body;

    // Insert into database
    const result = await query<User>(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );

    // Notify external system
    await getExternalSystemClient().post('/users', {
      id: result[0].id,
      name,
      email,
    });

    res.status(201).json(result[0]);
  } catch (error) {
    logger.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
}
