// WindowsService.cs - Enterprise Windows Service
using System;
using System.ServiceProcess;
using System.Threading;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;

namespace EnterpriseBackend.WindowsService
{
    public partial class EnterpriseBackendService : ServiceBase
    {
        private IServiceProvider _serviceProvider;
        private ILogger<EnterpriseBackendService> _logger;
        private CancellationTokenSource _cancellationTokenSource;

        public EnterpriseBackendService()
        {
            InitializeComponent();
            ServiceName = "EnterpriseBackendService";
        }

        protected override void OnStart(string[] args)
        {
            _cancellationTokenSource = new CancellationTokenSource();

            // Configure services
            var services = new ServiceCollection();
            ConfigureServices(services);

            _serviceProvider = services.BuildServiceProvider();
            _logger = _serviceProvider.GetService<ILogger<EnterpriseBackendService>>();

            _logger.LogInformation("Enterprise Backend Service starting...");

            // Start background processing
            var processor = _serviceProvider.GetService<IBackgroundProcessor>();
            processor.StartProcessing(_cancellationTokenSource.Token);
        }

        protected override void OnStop()
        {
            _logger.LogInformation("Enterprise Backend Service stopping...");

            // Signal cancellation to stop processing
            _cancellationTokenSource.Cancel();

            // Clean up
            if (_serviceProvider is IDisposable disposable)
            {
                disposable.Dispose();
            }

            _logger.LogInformation("Enterprise Backend Service stopped.");
        }

        private void ConfigureServices(IServiceCollection services)
        {
            // Configuration
            var configuration = new ConfigurationBuilder()
                .SetBasePath(AppContext.BaseDirectory)
                .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
                .AddEnvironmentVariables()
                .Build();

            services.AddSingleton<IConfiguration>(configuration);

            // Logging
            services.AddLogging(configure =>
            {
                configure.AddConfiguration(configuration.GetSection("Logging"));
                configure.AddConsole();
                configure.AddEventLog();
            });

            // Enterprise services
            services.AddSingleton<IBackgroundProcessor, BackgroundProcessor>();
            services.AddSingleton<IDataRepository, SqlDataRepository>();
            services.AddSingleton<IMessageQueueService, AzureServiceBusService>();

            // Azure integration
            services.AddSingleton<IAzureKeyVaultService, AzureKeyVaultService>();
            services.AddSingleton<IAzureStorageService, AzureStorageService>();
        }
    }
}
