### 4. Azure Integration Services (C#)

```csharp
// AzureServiceBusService.cs
using System;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Azure.ServiceBus;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace EnterpriseBackend.Services
{
    public class AzureServiceBusService : IAzureServiceBusService
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<AzureServiceBusService> _logger;
        private readonly QueueClient _queueClient;

        public AzureServiceBusService(IConfiguration configuration, ILogger<AzureServiceBusService> logger)
        {
            _configuration = configuration;
            _logger = logger;

            var serviceBusConnectionString = _configuration["ServiceBus:ConnectionString"];
            var queueName = _configuration["ServiceBus:QueueName"];

            _queueClient = new QueueClient(serviceBusConnectionString, queueName);
        }

        public async Task SendMessageAsync<T>(T message)
        {
            try
            {
                var messageBody = JsonConvert.SerializeObject(message);
                var serviceBusMessage = new Message(Encoding.UTF8.GetBytes(messageBody));

                await _queueClient.SendAsync(serviceBusMessage);

                _logger.LogInformation($"Message sent to Service Bus queue: {messageBody}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error sending message to Service Bus");
                throw;
            }
        }

        public async Task RegisterMessageHandlerAsync(Func<Message, Task> handler)
        {
            var messageHandlerOptions = new MessageHandlerOptions(ExceptionReceivedHandler)
            {
                MaxConcurrentCalls = 1,
                AutoComplete = false
            };

            _queueClient.RegisterMessageHandler(handler, messageHandlerOptions);
        }

        private Task ExceptionReceivedHandler(ExceptionReceivedEventArgs args)
        {
            _logger.LogError(args.Exception, $"Message handler encountered an exception: {args.Exception.Message}");
            return Task.CompletedTask;
        }

        public void Dispose()
        {
            _queueClient?.CloseAsync().GetAwaiter().GetResult();
        }
    }
}
