```csharp
// EnterpriseBackendService.Infrastructure/DependencyInjection.cs
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace EnterpriseBackendService.Infrastructure
{
    public static class DependencyInjection
    {
        public static IServiceCollection AddInfrastructureServices(this IServiceCollection services, IConfiguration configuration)
        {
            // Configure database context
            services.AddDbContext<ApplicationDbContext>(options =>
                options.UseSqlServer(configuration.GetConnectionString("DefaultConnection")));

            // Configure Cosmos DB
            services.AddSingleton<ICosmosDbService>(InitializeCosmosClientInstanceAsync(configuration).GetAwaiter().GetResult());

            // Configure Redis cache
            services.AddStackExchangeRedisCache(options =>
            {
                options.Configuration = configuration["Redis:ConnectionString"];
                options.InstanceName = "EnterpriseBackendService_";
            });

            // Configure Azure Service Bus
            services.AddSingleton<IServiceBusPublisher>(new ServiceBusPublisher(configuration["ServiceBus:ConnectionString"]));
            services.AddSingleton<IServiceBusSubscriber>(new ServiceBusSubscriber(configuration["ServiceBus:ConnectionString"]));

            // Configure Azure Storage
            services.AddSingleton<IBlobStorageService>(new BlobStorageService(configuration["Storage:ConnectionString"]));

            return services;
        }

        private static async Task<CosmosDbService> InitializeCosmosClientInstanceAsync(IConfiguration configuration)
        {
            var databaseName = configuration["CosmosDb:DatabaseName"];
            var containerName = configuration["CosmosDb:ContainerName"];
            var account = configuration["CosmosDb:Account"];
            var key = configuration["CosmosDb:Key"];

            var cosmosClient = new CosmosClient(account, key);
            var database = await cosmosClient.CreateDatabaseIfNotExistsAsync(databaseName);
            await database.Database.CreateContainerIfNotExistsAsync(containerName, "/id");

            return new CosmosDbService(cosmosClient, databaseName, containerName);
        }
    }
}
