// EnterpriseBackendService.WindowsService/Worker.cs
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using System.Threading;
using System.Threading.Tasks;

namespace EnterpriseBackendService.WindowsService
{
    public class Worker : BackgroundService
    {
        private readonly ILogger<Worker> _logger;
        private readonly IServiceBusSubscriber _subscriber;

        public Worker(ILogger<Worker> logger, IServiceBusSubscriber subscriber)
        {
            _logger = logger;
            _subscriber = subscriber;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _logger.LogInformation("Windows Service is starting.");

            // Subscribe to messages
            await _subscriber.SubscribeAsync("enterprise-queue", ProcessMessageAsync, stoppingToken);

            while (!stoppingToken.IsCancellationRequested)
            {
                _logger.LogInformation("Windows Service is running. Press Ctrl+C to exit.");
                await Task.Delay(10000, stoppingToken);
            }

            _logger.LogInformation("Windows Service is stopping.");
        }

        private async Task ProcessMessageAsync(string message, CancellationToken cancellationToken)
        {
            _logger.LogInformation($"Processing message: {message}");

            // Add your message processing logic here
            await Task.Delay(1000, cancellationToken);
        }
    }
}
