### 1. API Gateway (Node.js with Express)

```javascript
// api-gateway.js
const express = require('express');
const { createProxyMiddleware } = require('http-proxy-middleware');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { AzureMonitorTransport } = require('winston-azure-application-insights');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 1000 // limit each IP to 1000 requests per windowMs
});
app.use(limiter);

// Logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new AzureMonitorTransport({
      instrumentationKey: process.env.APPINSIGHTS_INSTRUMENTATIONKEY
    })
  ]
});

// JWT Authentication Middleware
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (authHeader) {
    const token = authHeader.split(' ')[1];

    jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
      if (err) {
        logger.error('JWT verification failed', { error: err });
        return res.sendStatus(403);
      }

      req.user = user;
      next();
    });
  } else {
    res.sendStatus(401);
  }
};

// Service routes
const services = [
  { route: '/auth', target: 'http://auth-service:3001' },
  { route: '/orders', target: 'http://order-service:3002' },
  { route: '/inventory', target: 'http://inventory-service:3003' },
  { route: '/legacy', target: 'http://windows-backend:8080' } // Legacy Windows service
];

services.forEach(({ route, target }) => {
  app.use(route, authenticateJWT, createProxyMiddleware({
    target,
    changeOrigin: true,
    pathRewrite: { [`^${route}`]: '' },
    onProxyReq: (proxyReq, req, res) => {
      // Add authentication headers to downstream services
      proxyReq.setHeader('X-User-Id', req.user.id);
      proxyReq.setHeader('X-User-Roles', req.user.roles);
    },
    onError: (err, req, res) => {
      logger.error(`Proxy error for ${route}`, { error: err });
      res.status(500).json({ error: 'Service unavailable' });
    }
  }));
});

// Health check
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'healthy' });
});

// Error handling
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err });
  res.status(500).json({ error: 'Internal server error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`API Gateway running on port ${PORT}`);
});
```

### 2. Authentication Service (Node.js)

```javascript
// auth-service.js
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const { Pool } = require('pg');
const winston = require('winston');
const { AzureMonitorTransport } = require('winston-azure-application-insights');

const app = express();
app.use(express.json());

// Logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console(),
    new AzureMonitorTransport({
      instrumentationKey: process.env.APPINSIGHTS_INSTRUMENTATIONKEY
    })
  ]
});

// Database connection
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false
});

// User registration
app.post('/register', async (req, res) => {
  try {
    const { username, password, email, roles } = req.body;

    // Validate input
    if (!username || !password || !email) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Store user in database
    const result = await pool.query(
      'INSERT INTO users (username, password, email, roles) VALUES ($1, $2, $3, $4) RETURNING id, username, email, roles',
      [username, hashedPassword, email, roles || ['user']]
    );

    const user = result.rows[0];
    delete user.password;

    logger.info('User registered', { userId: user.id });
    res.status(201).json(user);
  } catch (error) {
    logger.error('Registration error', { error });
    res.status(500).json({ error: 'Registration failed' });
  }
});

// User login
app.post('/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    // Find user
    const result = await pool.query(
      'SELECT * FROM users WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];

    // Verify password
    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Create JWT token
    const token = jwt.sign(
      { id: user.id, username: user.username, roles: user.roles },
      process.env.ACCESS_TOKEN_SECRET,
      { expiresIn: '1h' }
    );

    logger.info('User logged in', { userId: user.id });
    res.json({ token });
  } catch (error) {
    logger.error('Login error', { error });
    res.status(500).json({ error: 'Login failed' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'healthy' });
});

const PORT = process.env.PORT || 3001;
app.listen(PORT, () => {
  logger.info(`Auth service running on port ${PORT}`);
});
