using System;
using System.Threading.Tasks;
using Microsoft.Azure.WebJobs;
using Microsoft.Extensions.Logging;
using Microsoft.ApplicationInsights;
using Microsoft.ApplicationInsights.Extensibility;

namespace InventoryService
{
    public class InventoryUpdateFunction
    {
        private readonly TelemetryClient _telemetryClient;

        public InventoryUpdateFunction(TelemetryConfiguration telemetryConfig)
        {
            _telemetryClient = new TelemetryClient(telemetryConfig);
        }

        [FunctionName("ProcessInventoryUpdate")]
        public async Task Run(
            [ServiceBusTrigger("inventory-updates", Connection = "ServiceBusConnection")]string message,
            ILogger log)
        {
            try
            {
                log.LogInformation($"C# ServiceBus queue trigger function processed message: {message}");

                // Process inventory update
                var update = Newtonsoft.Json.JsonConvert.DeserializeObject<InventoryUpdate>(message);

                // Validate update
                if (update == null || string.IsNullOrEmpty(update.ProductId) || update.QuantityChange == 0)
                {
                    log.LogWarning("Invalid inventory update received");
                    _telemetryClient.TrackEvent("InvalidInventoryUpdate");
                    return;
                }

                // In a real implementation, this would update the database
                log.LogInformation($"Updating inventory for product {update.ProductId} by {update.QuantityChange}");

                _telemetryClient.TrackEvent("InventoryUpdated", new Dictionary<string, string> {
                    { "ProductId", update.ProductId },
                    { "QuantityChange", update.QuantityChange.ToString() }
                });
            }
            catch (Exception ex)
            {
                log.LogError(ex, "Error processing inventory update");
                _telemetryClient.TrackException(ex);
                throw; // This will trigger the dead-letter queue
            }
        }
    }

    public class InventoryUpdate
    {
        public string ProductId { get; set; }
        public int QuantityChange { get; set; }
        public string Reason { get; set; }
    }
}
