// Api/Startup.cs
public class Startup
{
    public IConfiguration Configuration { get; }

    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public void ConfigureServices(IServiceCollection services)
    {
        // Add controllers and GraphQL
        services.AddControllers();
        services.AddGraphQLServer()
            .AddQueryType<Query>()
            .AddMutationType<Mutation>();

        // Configure authentication (Azure AD)
        services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
            .AddMicrosoftIdentityWebApi(Configuration.GetSection("AzureAd"));

        // Add authorization policies
        services.AddAuthorization(options =>
        {
            options.AddPolicy("AdminOnly", policy => policy.RequireRole("Admin"));
            options.AddPolicy("ReadOnly", policy => policy.RequireRole("Reader"));
        });

        // Configure database contexts
        services.AddDbContext<SqlDbContext>(options =>
            options.UseSqlServer(Configuration.GetConnectionString("SqlServer")));

        services.AddSingleton<IMongoClient>(new MongoClient(
            Configuration.GetConnectionString("MongoDb")));

        // Register application services
        services.AddScoped<IOrderService, OrderService>();
        services.AddScoped<ICustomerService, CustomerService>();

        // Configure service bus
        services.AddSingleton<IServiceBusClient>(provider =>
            new ServiceBusClient(Configuration.GetConnectionString("ServiceBus")));

        // Add health checks
        services.AddHealthChecks()
            .AddSqlServer(Configuration.GetConnectionString("SqlServer"))
            .AddMongoDb(Configuration.GetConnectionString("MongoDb"));
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseHttpsRedirection();
        app.UseRouting();

        app.UseAuthentication();
        app.UseAuthorization();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
            endpoints.MapGraphQL();
            endpoints.MapHealthChecks("/health");
        });
    }
}
