### 4. Repository Pattern Implementation

```csharp
// Infrastructure/Data/Repositories/OrderRepository.cs
public class OrderRepository : IOrderRepository
{
    private readonly SqlDbContext _context;
    private readonly IMongoCollection<Order> _mongoCollection;

    public OrderRepository(SqlDbContext context, IMongoClient mongoClient)
    {
        _context = context;
        _mongoCollection = mongoClient.GetDatabase("EnterpriseDb").GetCollection<Order>("Orders");
    }

    public async Task<Order> GetByIdAsync(Guid id)
    {
        // Hybrid approach - try SQL first, fall back to MongoDB
        var order = await _context.Orders
            .Include(o => o.Customer)
            .Include(o => o.Items)
            .FirstOrDefaultAsync(o => o.Id == id);

        if (order == null)
        {
            order = await _mongoCollection.Find(o => o.Id == id).FirstOrDefaultAsync();
        }

        return order;
    }

    public async Task<IEnumerable<Order>> GetByCustomerIdAsync(Guid customerId)
    {
        return await _context.Orders
            .Where(o => o.CustomerId == customerId)
            .ToListAsync();
    }

    public async Task AddAsync(Order order)
    {
        // Add to both databases for redundancy
        await _context.Orders.AddAsync(order);
        await _mongoCollection.InsertOneAsync(order);
        await _context.SaveChangesAsync();
    }

    public async Task UpdateAsync(Order order)
    {
        _context.Orders.Update(order);
        await _mongoCollection.ReplaceOneAsync(o => o.Id == order.Id, order);
        await _context.SaveChangesAsync();
    }
}
