### 5. Service Bus Integration

```csharp
// Infrastructure/Messaging/OrderEventPublisher.cs
public class OrderEventPublisher : IOrderEventPublisher
{
    private readonly IServiceBusClient _serviceBusClient;
    private readonly ILogger<OrderEventPublisher> _logger;

    public OrderEventPublisher(IServiceBusClient serviceBusClient, ILogger<OrderEventPublisher> logger)
    {
        _serviceBusClient = serviceBusClient;
        _logger = logger;
    }

    public async Task PublishOrderCreatedEvent(Order order)
    {
        var sender = _serviceBusClient.CreateSender("order-created");
        var message = new ServiceBusMessage(JsonSerializer.Serialize(order))
        {
            ContentType = "application/json",
            CorrelationId = order.Id.ToString()
        };

        try
        {
            await sender.SendMessageAsync(message);
            _logger.LogInformation("Published OrderCreated event for order {OrderId}", order.Id);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to publish OrderCreated event for order {OrderId}", order.Id);
            throw;
        }
    }

    public async Task PublishOrderStatusChangedEvent(Order order)
    {
        var sender = _serviceBusClient.CreateSender("order-status-changed");
        var message = new ServiceBusMessage(JsonSerializer.Serialize(new
        {
            OrderId = order.Id,
            PreviousStatus = order.Status,
            NewStatus = order.Status
        }))
        {
            ContentType = "application/json",
            CorrelationId = order.Id.ToString()
        };

        await sender.SendMessageAsync(message);
    }
}
