            {
                return service.Status;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to get status for Windows service {ServiceName}", serviceName);
            throw;
        }
    }

    public async Task StartServiceAsync(string serviceName)
    {
        try
        {
            using (var service = new ServiceController(serviceName, _configuration["WindowsService:Server"]))
            {
                if (service.Status != ServiceControllerStatus.Running)
                {
                    service.Start();
                    service.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(30));
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to start Windows service {ServiceName}", serviceName);
            throw;
        }
    }
