// HybridIntegrationService.cs
using System.ServiceModel;
using Microsoft.Azure.ServiceBus;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class HybridIntegrationService
{
    private readonly IConfiguration _config;
    private readonly ILogger<HybridIntegrationService> _logger;
    private readonly IQueueClient _queueClient;

    public HybridIntegrationService(
        IConfiguration config,
        ILogger<HybridIntegrationService> logger)
    {
        _config = config;
        _logger = logger;
        _queueClient = new QueueClient(
            _config["AzureServiceBus:ConnectionString"],
            _config["AzureServiceBus:QueueName"]);
    }

    public async Task ProcessOrder(Order order)
    {
        try
        {
            // Process with on-prem Windows service
            var windowsServiceClient = new ChannelFactory<IOrderProcessingService>(
                new NetTcpBinding(),
                new EndpointAddress(_config["WindowsService:Endpoint"]))
                .CreateChannel();

            var windowsResult = await windowsServiceClient.ProcessOrderAsync(order);

            // Process with Azure service
            var message = new Message(Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(order)));
            await _queueClient.SendAsync(message);

            _logger.LogInformation("Order {OrderId} processed successfully", order.Id);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing order {OrderId}", order.Id);
            throw;
        }
    }
}
