// EnterpriseBackend.Infrastructure/AzureServiceBusClient.cs
using Azure.Messaging.ServiceBus;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace EnterpriseBackend.Infrastructure
{
    public interface IAzureServiceBusClient
    {
        Task SendMessageAsync(string queueName, string message);
        Task<string> ReceiveMessageAsync(string queueName);
    }

    public class AzureServiceBusClient : IAzureServiceBusClient
    {
        private readonly ServiceBusClient _client;
        private readonly ILogger<AzureServiceBusClient> _logger;

        public AzureServiceBusClient(ServiceBusClient client, ILogger<AzureServiceBusClient> logger)
        {
            _client = client;
            _logger = logger;
        }

        public async Task SendMessageAsync(string queueName, string message)
        {
            try
            {
                var sender = _client.CreateSender(queueName);
                var serviceBusMessage = new ServiceBusMessage(message);
                await sender.SendMessageAsync(serviceBusMessage);
                _logger.LogInformation($"Message sent to queue: {queueName}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error sending message to queue: {queueName}");
                throw;
            }
        }

        public async Task<string> ReceiveMessageAsync(string queueName)
        {
            try
            {
                var receiver = _client.CreateReceiver(queueName);
                var message = await receiver.ReceiveMessageAsync();
                if (message != null)
                {
                    await receiver.CompleteMessageAsync(message);
                    return message.Body.ToString();
                }
                return null;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error receiving message from queue: {queueName}");
                throw;
            }
        }
    }
}
