```csharp
// LegacySystemIntegrationService.cs
using System.ServiceModel;

namespace Enterprise.Backend.Integration
{
    public interface ILegacyOrderService
    {
        [OperationContract]
        LegacyOrderResponse SubmitOrder(LegacyOrderRequest request);
    }

    public class LegacySystemIntegrationService : ILegacySystemIntegrationService
    {
        private readonly ILogger<LegacySystemIntegrationService> _logger;
        private readonly IConfiguration _configuration;

        public LegacySystemIntegrationService(
            ILogger<LegacySystemIntegrationService> logger,
            IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
        }

        public async Task<LegacyOrderResponse> SubmitOrderToLegacySystem(Order order)
        {
            try
            {
                var legacyEndpoint = _configuration["LegacySystems:OrderServiceEndpoint"];

                var binding = new BasicHttpBinding
                {
                    Security = new BasicHttpSecurity
                    {
                        Mode = BasicHttpSecurityMode.TransportCredentialOnly,
                        Transport = new HttpTransportSecurity
                        {
                            ClientCredentialType = HttpClientCredentialType.Windows
                        }
                    }
                };

                var endpoint = new EndpointAddress(legacyEndpoint);

                var client = new ChannelFactory<ILegacyOrderService>(binding, endpoint);
                client.Credentials.Windows.ClientCredential = new System.Net.NetworkCredential(
                    _configuration["LegacySystems:Username"],
                    _configuration["LegacySystems:Password"],
                    _configuration["LegacySystems:Domain"]);

                var legacyService = client.CreateChannel();

                var legacyRequest = MapToLegacyOrderRequest(order);
                var legacyResponse = await legacyService.SubmitOrderAsync(legacyRequest);

                return MapToLegacyOrderResponse(legacyResponse);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error submitting order to legacy system");
                throw;
            }
        }

        private LegacyOrderRequest MapToLegacyOrderRequest(Order order)
        {
            // Mapping logic here
            return new LegacyOrderRequest();
        }

        private LegacyOrderResponse MapToLegacyOrderResponse(LegacyOrderResponse legacyResponse)
        {
            // Mapping logic here
            return new LegacyOrderResponse();
        }
    }
}
