```csharp
using System.DirectoryServices.AccountManagement;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.Extensions.Configuration;

namespace EnterpriseBackend.Services.Auth;

public interface IAuthService
{
    Task<string> AuthenticateWindowsUser(string username, string password);
    Task<string> AuthenticateAzureAdUser(string token);
    Task<bool> ValidateActiveDirectoryUser(string username, string password);
}

public class AuthService : IAuthService
{
    private readonly IConfiguration _configuration;

    public AuthService(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public async Task<string> AuthenticateWindowsUser(string username, string password)
    {
        if (await ValidateActiveDirectoryUser(username, password))
        {
            return GenerateJwtToken(username, "Windows");
        }
        throw new UnauthorizedAccessException("Invalid Windows credentials");
    }

    public async Task<string> AuthenticateAzureAdUser(string token)
    {
        // Validate Azure AD token (simplified for example)
        var handler = new JwtSecurityTokenHandler();
        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidIssuer = _configuration["AzureAd:Issuer"],
            ValidateAudience = true,
            ValidAudience = _configuration["AzureAd:Audience"],
            ValidateLifetime = true,
            IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes(_configuration["AzureAd:ClientSecret"]))
        };

        try
        {
            var principal = handler.ValidateToken(token, validationParameters, out _);
            var username = principal.FindFirst(ClaimTypes.Name)?.Value;
            return GenerateJwtToken(username, "AzureAD");
        }
        catch
        {
            throw new UnauthorizedAccessException("Invalid Azure AD token");
        }
    }

    public async Task<bool> ValidateActiveDirectoryUser(string username, string password)
    {
        using (var context = new PrincipalContext(ContextType.Domain))
        {
            return context.ValidateCredentials(username, password);
        }
    }

    private string GenerateJwtToken(string username, string authType)
    {
        var securityKey = new SymmetricSecurityKey(
            Encoding.UTF8.GetBytes(_configuration["Jwt:Key"]));
        var credentials = new SigningCredentials(securityKey, SecurityAlgorithms.HmacSha256);

        var claims = new[]
        {
            new Claim(ClaimTypes.Name, username),
            new Claim("AuthType", authType),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
        };

        var token = new JwtSecurityToken(
            issuer: _configuration["Jwt:Issuer"],
            audience: _configuration["Jwt:Audience"],
            claims: claims,
            expires: DateTime.Now.AddMinutes(Convert.ToDouble(_configuration["Jwt:ExpiryMinutes"])),
            signingCredentials: credentials);

        return new JwtSecurityTokenHandler().WriteToken(token);
    }
}
