namespace EnterpriseBackend.Integration.Services
{
    public class AzureServiceBusIntegration : IMessageIntegration
    {
        private readonly ServiceBusClient _client;
        private readonly string _queueName;

        public AzureServiceBusIntegration(IConfiguration configuration)
        {
            var connectionString = configuration["AzureServiceBus:ConnectionString"];
            _queueName = configuration["AzureServiceBus:QueueName"];
            _client = new ServiceBusClient(connectionString);
        }

        public async Task SendMessageAsync<T>(T message)
        {
            var sender = _client.CreateSender(_queueName);
            var jsonMessage = JsonSerializer.Serialize(message);
            var serviceBusMessage = new ServiceBusMessage(jsonMessage);

            await sender.SendMessageAsync(serviceBusMessage);
        }

        public async Task<T> ReceiveMessageAsync<T>()
        {
            var processor = _client.CreateProcessor(_queueName);
            await processor.StartProcessingAsync();

            // In a real implementation, you would handle messages as they arrive
            // This is simplified for demonstration
            var receivedMessage = await processor.ReceiveMessageAsync();
            if (receivedMessage != null)
            {
                var messageBody = receivedMessage.Body.ToString();
                return JsonSerializer.Deserialize<T>(messageBody);
            }

            return default;
        }
    }

    public interface IMessageIntegration
    {
        Task SendMessageAsync<T>(T message);
        Task<T> ReceiveMessageAsync<T>();
    }
