### 4. Business Service (Services Layer)

```csharp
// OrderService.cs
using EnterpriseBackend.Infrastructure;
using EnterpriseBackend.Shared.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Distributed;
using System.Text.Json;

namespace EnterpriseBackend.Services
{
    public interface IOrderService
    {
        Task<Order> CreateOrderAsync(Order order);
        Task<Order> GetOrderByIdAsync(int orderId);
        Task<IEnumerable<Order>> GetUserOrdersAsync(int userId);
    }

    public class OrderService : IOrderService
    {
        private readonly EnterpriseDbContext _dbContext;
        private readonly IDistributedCache _cache;
        private readonly IMessagePublisher _messagePublisher;

        public OrderService(
            EnterpriseDbContext dbContext,
            IDistributedCache cache,
            IMessagePublisher messagePublisher)
        {
            _dbContext = dbContext;
            _cache = cache;
            _messagePublisher = messagePublisher;
        }

        public async Task<Order> CreateOrderAsync(Order order)
        {
            order.CreatedDate = DateTime.UtcNow;
            _dbContext.Orders.Add(order);
            await _dbContext.SaveChangesAsync();

            // Publish order created event
            await _messagePublisher.PublishMessageAsync("orders", order);

            // Invalidate cache for user orders
            await _cache.RemoveAsync($"user_orders_{order.UserId}");

            return order;
        }

        public async Task<Order> GetOrderByIdAsync(int orderId)
        {
            var cacheKey = $"order_{orderId}";
            var cachedOrder = await _cache.GetStringAsync(cacheKey);

            if (cachedOrder != null)
            {
                return JsonSerializer.Deserialize<Order>(cachedOrder);
            }

            var order = await _dbContext.Orders
                .Include(o => o.User)
                .Include(o => o.Items)
                .FirstOrDefaultAsync(o => o.Id == orderId);

            if (order != null)
            {
                var options = new DistributedCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(30)
                };
                await _cache.SetStringAsync(cacheKey, JsonSerializer.Serialize(order), options);
            }

            return order;
        }

        public async Task<IEnumerable<Order>> GetUserOrdersAsync(int userId)
        {
            var cacheKey = $"user_orders_{userId}";
            var cachedOrders = await _cache.GetStringAsync(cacheKey);

            if (cachedOrders != null)
            {
                return JsonSerializer.Deserialize<IEnumerable<Order>>(cachedOrders);
            }

            var orders = await _dbContext.Orders
                .Where(o => o.UserId == userId)
                .Include(o => o.Items)
                .ToListAsync();

            var options = new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(15)
            };
            await _cache.SetStringAsync(cacheKey, JsonSerializer.Serialize(orders), options);

            return orders;
        }
    }
}
