using Azure.Messaging.ServiceBus;
using System.Text.Json;

namespace EnterpriseBackend.Infrastructure
{
    public interface IMessagePublisher
    {
        Task PublishMessageAsync<T>(string queueName, T message);
    }

    public class AzureServiceBusPublisher : IMessagePublisher, IDisposable
    {
        private readonly ServiceBusClient _client;

        public AzureServiceBusPublisher(string connectionString)
        {
            _client = new ServiceBusClient(connectionString);
        }

        public async Task PublishMessageAsync<T>(string queueName, T message)
        {
            var sender = _client.CreateSender(queueName);
            var messageBody = JsonSerializer.Serialize(message);
            var serviceBusMessage = new ServiceBusMessage(messageBody);

            await sender.SendMessageAsync(serviceBusMessage);
        }

        public void Dispose()
        {
            _client?.DisposeAsync().GetAwaiter().GetResult();
        }
    }
}
