### 4. Service Implementation Example

```csharp
// Services/OrderService.cs
using EnterpriseBackend.Infrastructure;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Memory;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace EnterpriseBackend.Services
{
    public class OrderService : IOrderService
    {
        private readonly ApplicationDbContext _context;
        private readonly IMemoryCache _cache;
        private readonly ILogger<OrderService> _logger;

        public OrderService(
            ApplicationDbContext context,
            IMemoryCache cache,
            ILogger<OrderService> logger)
        {
            _context = context;
            _cache = cache;
            _logger = logger;
        }

        public async Task<IEnumerable<OrderDto>> GetOrdersAsync(OrderFilter filter)
        {
            var cacheKey = $"orders_{filter.GetHashCode()}";

            if (!_cache.TryGetValue(cacheKey, out IEnumerable<OrderDto> orders))
            {
                var query = _context.Orders
                    .Include(o => o.Customer)
                    .Include(o => o.OrderItems)
                    .AsQueryable();

                if (filter.CustomerId.HasValue)
                {
                    query = query.Where(o => o.CustomerId == filter.CustomerId);
                }

                if (filter.Status.HasValue)
                {
                    query = query.Where(o => o.Status == filter.Status);
                }

                if (filter.StartDate.HasValue)
                {
                    query = query.Where(o => o.OrderDate >= filter.StartDate);
                }

                if (filter.EndDate.HasValue)
                {
                    query = query.Where(o => o.OrderDate <= filter.EndDate);
                }

                orders = await query
                    .OrderByDescending(o => o.OrderDate)
                    .Select(o => new OrderDto
                    {
                        Id = o.Id,
                        CustomerId = o.CustomerId,
                        OrderDate = o.OrderDate,
                        Status = o.Status,
                        TotalAmount = o.TotalAmount,
                        Items = o.OrderItems.Select(oi => new OrderItemDto
                        {
                            ProductId = oi.ProductId,
                            Quantity = oi.Quantity,
                            UnitPrice = oi.UnitPrice
                        }).ToList()
                    })
                    .ToListAsync();

                var cacheOptions = new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromMinutes(10))
                    .SetAbsoluteExpiration(TimeSpan.FromHours(1));

                _cache.Set(cacheKey, orders, cacheOptions);
            }

            return orders;
        }

        public async Task<OrderDto> GetOrderByIdAsync(int id)
        {
            var cacheKey = $"order_{id}";

            if (!_cache.TryGetValue(cacheKey, out OrderDto order))
            {
                order = await _context.Orders
                    .Include(o => o.Customer)
                    .Include(o => o.OrderItems)
                    .Where(o => o.Id == id)
                    .Select(o => new OrderDto
                    {
                        Id = o.Id,
                        CustomerId = o.CustomerId,
                        OrderDate = o.OrderDate,
                        Status = o.Status,
                        TotalAmount = o.TotalAmount,
                        Items = o.OrderItems.Select(oi => new OrderItemDto
                        {
                            ProductId = oi.ProductId,
                            Quantity = oi.Quantity,
                            UnitPrice = oi.UnitPrice
                        }).ToList()
                    })
                    .FirstOrDefaultAsync();

                if (order != null)
                {
                    var cacheOptions = new MemoryCacheEntryOptions()
                        .SetSlidingExpiration(TimeSpan.FromMinutes(5))
                        .SetAbsoluteExpiration(TimeSpan.FromHours(1));

                    _cache.Set(cacheKey, order, cacheOptions);
                }
            }

            return order;
        }

        public async Task<OrderDto> CreateOrderAsync(OrderCreateDto orderDto)
        {
            // Validate the order
            if (orderDto.Items == null || !orderDto.Items.Any())
            {
                throw new ValidationException("Order must contain at least one item");
            }

            // Check inventory
            foreach (var item in orderDto.Items)
            {
                var inventory = await _context.Inventory
                    .FirstOrDefaultAsync(i => i.ProductId == item.ProductId);

                if (inventory == null || inventory.Quantity < item.Quantity)
                {
                    throw new ValidationException($"Insufficient inventory for product {item.ProductId}");
                }
            }

            // Create the order
            var order = new Order
            {
                CustomerId = orderDto.CustomerId,
                OrderDate = DateTime.UtcNow,
                Status = OrderStatus.Pending,
                OrderItems = orderDto.Items.Select(i => new OrderItem
                {
                    ProductId = i.ProductId,
                    Quantity = i.Quantity,
                    UnitPrice = i.UnitPrice
                }).ToList()
            };

            order.TotalAmount = order.OrderItems.Sum(i => i.Quantity * i.UnitPrice);

            _context.Orders.Add(order);
            await _context.SaveChangesAsync();

            // Update inventory
            foreach (var item in order.OrderItems)
            {
                var inventory = await _context.Inventory
                    .FirstOrDefaultAsync(i => i.ProductId == item.ProductId);

                if (inventory != null)
                {
                    inventory.Quantity -= item.Quantity;
                }
            }

            await _context.SaveChangesAsync();

            // Clear cache
            _cache.Remove($"orders_{order.CustomerId.GetHashCode()}");

            return new OrderDto
            {
                Id = order.Id,
                CustomerId = order.CustomerId,
                OrderDate = order.OrderDate,
                Status = order.Status,
                TotalAmount = order.TotalAmount,
                Items = order.OrderItems.Select(oi => new OrderItemDto
                {
                    ProductId = oi.ProductId,
                    Quantity = oi.Quantity,
                    UnitPrice = oi.UnitPrice
                }).ToList()
            };
        }

        // Additional methods for Update and Delete would follow similar patterns
    }
}
```

