// Infrastructure/WindowsServiceIntegration.cs
using System.ServiceProcess;

namespace EnterpriseBackend.Infrastructure
{
    public class WindowsServiceIntegration : IWindowsServiceIntegration
    {
        private readonly ILogger<WindowsServiceIntegration> _logger;

        public WindowsServiceIntegration(ILogger<WindowsServiceIntegration> logger)
        {
            _logger = logger;
        }

        public async Task<bool> CheckServiceStatusAsync(string serviceName)
        {
            try
            {
                using (var controller = new ServiceController(serviceName))
                {
                    return controller.Status == ServiceControllerStatus.Running;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error checking status of Windows service {serviceName}");
                throw;
            }
        }

        public async Task StartServiceAsync(string serviceName)
        {
            try
            {
                using (var controller = new ServiceController(serviceName))
                {
                    if (controller.Status != ServiceControllerStatus.Running)
                    {
                        controller.Start();
                        controller.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(30));
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error starting Windows service {serviceName}");
                throw;
            }
        }

        public async Task StopServiceAsync(string serviceName)
        {
            try
            {
                using (var controller = new ServiceController(serviceName))
                {
                    if (controller.Status != ServiceControllerStatus.Stopped)
                    {
                        controller.Stop();
                        controller.WaitForStatus(ServiceControllerStatus.Stopped, TimeSpan.FromSeconds(30));
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error stopping Windows service {serviceName}");
                throw;
            }
        }
    }
}
