### 7. Background Service Example

```csharp
// Services/InventorySyncService.cs
using EnterpriseBackend.Infrastructure;
using Microsoft.Extensions.Hosting;
using System.Threading;
using System.Threading.Tasks;

namespace EnterpriseBackend.Services
{
    public class InventorySyncService : BackgroundService
    {
        private readonly IServiceProvider _serviceProvider;
        private readonly ILogger<InventorySyncService> _logger;
        private readonly IConfiguration _configuration;

        public InventorySyncService(
            IServiceProvider serviceProvider,
            ILogger<InventorySyncService> logger,
            IConfiguration configuration)
        {
            _serviceProvider = serviceProvider;
            _logger = logger;
            _configuration = configuration;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _logger.LogInformation("Inventory Sync Service is starting");

            stoppingToken.Register(() =>
                _logger.LogInformation("Inventory Sync Service is stopping"));

            while (!stoppingToken.IsCancellationRequested)
            {
                try
                {
                    using (var scope = _serviceProvider.CreateScope())
                    {
                        var dbContext = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
                        var windowsService = scope.ServiceProvider.GetRequiredService<IWindowsServiceIntegration>();

                        // Check if the Windows inventory service is running
                        var isRunning = await windowsService.CheckServiceStatusAsync("EnterpriseInventoryService");

                        if (!isRunning)
                        {
                            _logger.LogWarning("Windows inventory service is not running. Attempting to start it.");
                            await windowsService.StartServiceAsync("EnterpriseInventoryService");
                        }

                        // Sync inventory data
                        var lastSync = await dbContext.InventorySyncLogs
                            .OrderByDescending(l => l.SyncDate)
                            .FirstOrDefaultAsync();

                        var syncInterval = _configuration.GetValue<int>("InventorySync:IntervalMinutes", 60);
                        var nextSync = lastSync?.SyncDate.AddMinutes(syncInterval) ?? DateTime.UtcNow.AddMinutes(-syncInterval);

                        if (DateTime.UtcNow >= nextSync)
                        {
                            _logger.LogInformation("Starting inventory synchronization");

                            // Get inventory data from Windows service
                            // This would typically be via WCF, gRPC, or some other IPC mechanism
                            var inventoryData = await GetInventoryDataFromWindowsService();

                            // Update database
                            foreach (var item in inventoryData)
                            {
                                var existingItem = await dbContext.Inventory
                                    .FirstOrDefaultAsync(i => i.ProductId == item.ProductId);

                                if (existingItem != null)
                                {
                                    existingItem.Quantity = item.Quantity;
                                    existingItem.LastUpdated = DateTime.UtcNow;
                                }
                                else
                                {
                                    dbContext.Inventory.Add(new InventoryItem
                                    {
                                        ProductId = item.ProductId,
                                        Quantity = item.Quantity,
                                        LastUpdated = DateTime.UtcNow
                                    });
                                }
                            }

                            await dbContext.InventorySyncLogs.AddAsync(new InventorySyncLog
                            {
                                SyncDate = DateTime.UtcNow,
                                ItemsSynced = inventoryData.Count
                            });

                            await dbContext.SaveChangesAsync();

                            _logger.LogInformation($"Inventory synchronization completed. Synced {inventoryData.Count} items.");
                        }
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error in inventory synchronization");
                }

                await Task.Delay(TimeSpan.FromMinutes(5), stoppingToken);
            }

            _logger.LogInformation("Inventory Sync Service has stopped");
        }

        private async Task<List<InventoryItemDto>> GetInventoryDataFromWindowsService()
        {
            // Implementation would depend on how you're communicating with the Windows service
            // This could be via WCF, gRPC, or some other IPC mechanism
            // For demonstration, we'll return mock data

            return new List<InventoryItemDto>
            {
                new InventoryItemDto { ProductId = 1, Quantity = 100 },
                new InventoryItemDto { ProductId = 2, Quantity = 50 },
                new InventoryItemDto { ProductId = 3, Quantity = 75 }
            };
        }
    }
}
