// AuthService/AuthController.cs
[ApiController]
[Route("api/[controller]")]
public class AuthController : ControllerBase
{
    private readonly IConfiguration _config;
    private readonly ILogger<AuthController> _logger;

    public AuthController(IConfiguration config, ILogger<AuthController> logger)
    {
        _config = config;
        _logger = logger;
    }

    [HttpPost("token")]
    public async Task<IActionResult> GetToken([FromBody] TokenRequest request)
    {
        try
        {
            // Validate request
            if (string.IsNullOrEmpty(request.ClientId) || string.IsNullOrEmpty(request.ClientSecret))
            {
                return BadRequest("Client credentials are required");
            }

            // Get token from Azure AD
            var client = ConfidentialClientApplicationBuilder
                .Create(request.ClientId)
                .WithClientSecret(request.ClientSecret)
                .WithAuthority(new Uri($"https://login.microsoftonline.com/{_config["AzureAd:TenantId"]}"))
                .Build();

            var scopes = new[] { "api://" + _config["AzureAd:ClientId"] + "/.default" };

            var result = await client.AcquireTokenForClient(scopes)
                .ExecuteAsync();

            return Ok(new
            {
                AccessToken = result.AccessToken,
                ExpiresOn = result.ExpiresOn
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error getting token");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class TokenRequest
{
    public string ClientId { get; set; }
    public string ClientSecret { get; set; }
}
