### 3. Business Logic Service (Azure Functions)

```csharp
// BusinessLogic/OrderProcessor.cs
public class OrderProcessor
{
    private readonly ILogger _logger;
    private readonly IOrderRepository _orderRepository;
    private readonly IServiceBusClient _serviceBusClient;

    public OrderProcessor(
        ILogger<OrderProcessor> logger,
        IOrderRepository orderRepository,
        IServiceBusClient serviceBusClient)
    {
        _logger = logger;
        _orderRepository = orderRepository;
        _serviceBusClient = serviceBusClient;
    }

    [FunctionName("ProcessOrder")]
    public async Task Run(
        [ServiceBusTrigger("orders", Connection = "ServiceBusConnection")] Order order,
        ILogger log)
    {
        try
        {
            log.LogInformation($"Processing order {order.OrderId}");

            // Validate order
            if (!order.IsValid())
            {
                log.LogWarning($"Invalid order {order.OrderId}");
                await SendToDeadLetterQueue(order);
                return;
            }

            // Process order
            await _orderRepository.ProcessOrderAsync(order);

            // Send confirmation
            await SendOrderConfirmation(order);

            log.LogInformation($"Order {order.OrderId} processed successfully");
        }
        catch (Exception ex)
        {
            log.LogError(ex, $"Error processing order {order.OrderId}");
            await SendToDeadLetterQueue(order);
        }
    }

    private async Task SendOrderConfirmation(Order order)
    {
        var sender = _serviceBusClient.CreateSender("order-confirmations");
        await sender.SendMessageAsync(new ServiceBusMessage(JsonSerializer.Serialize(order)));
    }

    private async Task SendToDeadLetterQueue(Order order)
    {
        var sender = _serviceBusClient.CreateSender("order-errors");
        await sender.SendMessageAsync(new ServiceBusMessage(JsonSerializer.Serialize(order)));
    }
}
