```csharp
// DataAccess/OrderRepository.cs
public class OrderRepository : IOrderRepository
{
    private readonly CosmosClient _cosmosClient;
    private readonly SqlConnection _sqlConnection;
    private readonly ILogger<OrderRepository> _logger;

    public OrderRepository(
        CosmosClient cosmosClient,
        SqlConnection sqlConnection,
        ILogger<OrderRepository> logger)
    {
        _cosmosClient = cosmosClient;
        _sqlConnection = sqlConnection;
        _logger = logger;
    }

    public async Task ProcessOrderAsync(Order order)
    {
        // Use Cosmos DB for high-volume document storage
        var container = _cosmosClient.GetContainer("Orders", "OrderItems");
        await container.CreateItemAsync(order);

        // Use SQL DB for relational data
        using var command = new SqlCommand(
            "INSERT INTO OrderHeaders (OrderId, CustomerId, OrderDate) VALUES (@OrderId, @CustomerId, @OrderDate)",
            _sqlConnection);

        command.Parameters.AddWithValue("@OrderId", order.OrderId);
        command.Parameters.AddWithValue("@CustomerId", order.CustomerId);
        command.Parameters.AddWithValue("@OrderDate", order.OrderDate);

        await _sqlConnection.OpenAsync();
        await command.ExecuteNonQueryAsync();
    }
}
