public class WindowsServiceClient : IWindowsServiceClient
{
    private readonly IConfiguration _config;
    private readonly ILogger<WindowsServiceClient> _logger;

    public WindowsServiceClient(IConfiguration config, ILogger<WindowsServiceClient> logger)
    {
        _config = config;
        _logger = logger;
    }

    public async Task<string> CallLegacyService(string serviceName, string method, object parameters)
    {
        try
        {
            // Get service endpoint from configuration
            var endpoint = _config.GetValue<string>($"WindowsServices:{serviceName}:Endpoint");

            // Create WCF client (for legacy .NET Framework services)
            var binding = new BasicHttpBinding();
            var address = new EndpointAddress(endpoint);
            var factory = new ChannelFactory<IServiceContract>(binding, address);

            var client = factory.CreateChannel();

            // Call the service
            var result = await client.CallAsync(method, parameters);

            ((IClientChannel)client).Close();

            return result;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error calling Windows service {serviceName}");
            throw;
        }
    }
}
