### 2. Service Bus Integration
```csharp
public class EnterpriseEventProcessor : IHostedService
{
    private readonly IServiceBusReceiver _serviceBusReceiver;
    private readonly ILogger<EnterpriseEventProcessor> _logger;

    public EnterpriseEventProcessor(
        IServiceBusReceiver serviceBusReceiver,
        ILogger<EnterpriseEventProcessor> logger)
    {
        _serviceBusReceiver = serviceBusReceiver;
        _logger = logger;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _serviceBusReceiver.RegisterMessageHandler(
            async (message, token) =>
            {
                try
                {
                    // Process message
                    _logger.LogInformation("Processing message: {MessageId}", message.MessageId);
                    await ProcessMessageAsync(message);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing message");
                    throw;
                }
            },
            new ServiceBusMessageHandlerOptions(ExceptionReceivedHandler)
            {
                AutoComplete = false,
                MaxConcurrentCalls = 10
            });

        return Task.CompletedTask;
    }

    private Task ExceptionReceivedHandler(ExceptionReceivedEventArgs args)
    {
        _logger.LogError(args.Exception, "Message handler encountered an exception");
        return Task.CompletedTask;
    }

    private async Task ProcessMessageAsync(ServiceBusReceivedMessage message)
    {
        // Business logic to process the message
        await Task.Delay(100); // Simulate processing
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        _serviceBusReceiver.CloseAsync();
        return Task.CompletedTask;
    }
}
```

