           {
               // Validate inventory
               var inventoryCheck = await _inventoryService.CheckAvailability(request.Items);

               if (!inventoryCheck.IsAvailable)
                   throw new BusinessException("Insufficient inventory");

               // Process payment
               var paymentResult = await _paymentProcessor.ProcessPayment(
                   request.PaymentDetails,
                   inventoryCheck.TotalAmount);

               if (!paymentResult.Success)
                   throw new BusinessException("Payment processing failed");

               // Create order
               var order = new Order {
                   Items = request.Items,
                   CustomerId = request.CustomerId,
                   PaymentId = paymentResult.TransactionId,
                   Status = OrderStatus.Processing
               };

               await _orderRepository.CreateOrder(order);

               // Update inventory
               await _inventoryService.ReserveItems(request.Items);

               return new OrderResponse {
                   OrderId = order.Id,
                   Status = order.Status,
                   Message = "Order processed successfully"
               };
           }
           catch (Exception ex)
           {
               _logger.LogError(ex, "Order processing failed");
               throw;
           }
       }
   }
   ```

