       public async Task<LegacyResponse> ProcessRequest(LegacyRequest request)
       {
           try
           {
               var endpoint = _config["LegacySystem:Endpoint"];
               var timeout = TimeSpan.FromSeconds(int.Parse(_config["LegacySystem:TimeoutSeconds"]));

               using (var client = new HttpClient())
               {
                   client.Timeout = timeout;

                   var response = await client.PostAsJsonAsync(endpoint, request);

                   if (!response.IsSuccessStatusCode)
                   {
                       _logger.LogError($"Legacy system returned status code: {response.StatusCode}");
                       throw new IntegrationException("Legacy system processing failed");
                   }

                   return await response.Content.ReadFromJsonAsync<LegacyResponse>();
               }
           }
           catch (Exception ex)
           {
               _logger.LogError(ex, "Error calling legacy system");
               throw;
           }
       }
