// Example Windows Service integration
public class WindowsIntegrationService : IWindowsIntegrationService
{
    private readonly ILogger<WindowsIntegrationService> _logger;

    public WindowsIntegrationService(ILogger<WindowsIntegrationService> logger)
    {
        _logger = logger;
    }

    public async Task<WindowsServiceResponse> ExecuteLegacyProcess(string processName, string parameters)
    {
        try
        {
            // Use Process class to execute Windows executable
            var process = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = processName,
                    Arguments = parameters,
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    CreateNoWindow = true
                }
            };

            process.Start();
            var output = await process.StandardOutput.ReadToEndAsync();
            var error = await process.StandardError.ReadToEndAsync();
            await process.WaitForExitAsync();

            return new WindowsServiceResponse
            {
                Success = process.ExitCode == 0,
                Output = output,
                Error = error
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error executing Windows process");
            throw;
        }
    }
}
