    public class SqlRepository<T> : IRepository<T> where T : class
    {
        private readonly string _connectionString;

        public SqlRepository(IConfiguration configuration)
        {
            _connectionString = configuration.GetConnectionString("DefaultConnection");
        }

        public async Task<IEnumerable<T>> GetAllAsync()
        {
            using var connection = new SqlConnection(_connectionString);
            return await connection.QueryAsync<T>($"SELECT * FROM {typeof(T).Name}");
        }

        public async Task<T> GetByIdAsync(int id)
        {
            using var connection = new SqlConnection(_connectionString);
            return await connection.QueryFirstOrDefaultAsync<T>(
                $"SELECT * FROM {typeof(T).Name} WHERE Id = @Id", new { Id = id });
        }

        public async Task<T> CreateAsync(T entity)
        {
            // Implementation would use Dapper or Entity Framework
            // This is simplified for the example
            using var connection = new SqlConnection(_connectionString);
            var id = await connection.ExecuteScalarAsync<int>(
                $"INSERT INTO {typeof(T).Name} (...) OUTPUT INSERTED.Id VALUES (...)", entity);
            return await GetByIdAsync(id);
        }

        // Similar implementations for UpdateAsync and DeleteAsync
    }
}
