            {
                return BadRequest("Invalid request data");
            }

            _logger.LogInformation($"Processing data: {request.Data}");

            // Simulate processing
            await Task.Delay(100);

            var response = new ProcessResponse
            {
                Result = $"Processed: {request.Data}",
                Timestamp = DateTime.UtcNow
            };

            return Ok(response);
        }
    }
}
