using EnterpriseBackend.Core.Interfaces;
using EnterpriseBackend.Core.Models;
using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace EnterpriseBackend.Api.Controllers
