```go
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
)

func main() {
	// Parse command line flags
	port := flag.Int("port", 8080, "Port to listen on")
	workers := flag.Int("workers", runtime.NumCPU(), "Number of worker threads")
	readTimeout := flag.Duration("read-timeout", 5*time.Second, "Server read timeout")
	writeTimeout := flag.Duration("write-timeout", 10*time.Second, "Server write timeout")
	idleTimeout := flag.Duration("idle-timeout", 15*time.Second, "Server idle timeout")
	flag.Parse()

	// Set GOMAXPROCS to the number of CPU cores
	runtime.GOMAXPROCS(*workers)

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      newRouter(),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
	}

	// Channel to listen for OS signals
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	// Start the server in a goroutine
	go func() {
		log.Printf("Starting server on port %d with %d workers", *port, *workers)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Could not start server: %v\n", err)
		}
	}()

	// Wait for interrupt signal
	<-stop

	// Create a context with timeout for shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Shutdown the server gracefully
	log.Println("Shutting down server...")
	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("Server shutdown failed: %v\n", err)
	}
	log.Println("Server stopped")
}

func newRouter() http.Handler {
	// Create a new ServeMux (router)
	mux := http.NewServeMux()

	// Register handlers
	mux.HandleFunc("/", homeHandler)
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/api/data", dataHandler)

	// Return the router with middleware
	return withMiddleware(mux)
}

func withMiddleware(next http.Handler) http.Handler {
	// Add middleware here (logging, CORS, etc.)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Log the request
		start := time.Now()
		defer func() {
			log.Printf("%s %s %v", r.Method, r.URL.Path, time.Since(start))
		}()

		// Set common headers
		w.Header().Set("Content-Type", "application/json")

		// Call the next handler
		next.ServeHTTP(w, r)
	})
}

func homeHandler(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}

	w.WriteHeader(http.StatusOK)
