package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
)

func main() {
	// Parse command line flags
	port := flag.Int("port", 8080, "Port to listen on")
	maxConns := flag.Int("max-conns", 10000, "Maximum number of concurrent connections")
	readTimeout := flag.Duration("read-timeout", 5*time.Second, "Read timeout duration")
	writeTimeout := flag.Duration("write-timeout", 10*time.Second, "Write timeout duration")
	idleTimeout := flag.Duration("idle-timeout", 120*time.Second, "Idle timeout duration")
	flag.Parse()

	// Set GOMAXPROCS to utilize all available CPU cores
	runtime.GOMAXPROCS(runtime.NumCPU())

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      http.HandlerFunc(handleRequest),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
		// Limit the maximum number of concurrent connections
		MaxHeaderBytes: 1 << 20, // 1 MB
	}

	// Configure the server to handle graceful shutdown
	serverCtx, serverStopCtx := context.WithCancel(context.Background())

	// Listen for syscall signals for process to interrupt/quit
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGHUP, syscall.SIGINT, syscall.SIGTERM, syscall.SIGQUIT)
	go func() {
		<-sig

		// Shutdown signal with grace period of 30 seconds
		shutdownCtx, _ := context.WithTimeout(serverCtx, 30*time.Second)

		go func() {
			<-shutdownCtx.Done()
			if shutdownCtx.Err() == context.DeadlineExceeded {
				log.Fatal("graceful shutdown timed out.. forcing exit.")
			}
		}()

		// Trigger graceful shutdown
		err := server.Shutdown(shutdownCtx)
		if err != nil {
			log.Fatal(err)
		}
		serverStopCtx()
	}()

	// Run the server
	log.Printf("Server is running on http://localhost:%d\n", *port)
	log.Printf("Max concurrent connections: %d\n", *maxConns)
	log.Printf("Timeouts - Read: %v, Write: %v, Idle: %v\n", *readTimeout, *writeTimeout, *idleTimeout)

	// Start the server with connection limit
	limiter := make(chan struct{}, *maxConns)
	go func() {
		for {
			select {
			case <-serverCtx.Done():
				return
			default:
				limiter <- struct{}{}
			}
		}
	}()

	// Wrap the handler to enforce connection limits
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		<-limiter
		defer func() { limiter <- struct{}{} }()
		handleRequest(w, r)
	})

	// Start the server
	err := server.ListenAndServe()
	if err != nil && err != http.ErrServerClosed {
		log.Fatal(err)
	}

	// Wait for server context to be stopped
	<-serverCtx.Done()
}

