    try {
      const parsedUrl = url.parse(req.url, true);
      const pathname = parsedUrl.pathname;

      // Check if it's a route we handle
      if (routes[pathname]) {
        routes[pathname](req, res);
        return;
      }

      // Serve static files
      serveStaticFile(pathname, res);
    } catch (err) {
      console.error('Error handling request:', err);
      res.writeHead(500, { 'Content-Type': 'text/plain' });
      res.end('Internal Server Error');
    }
  });

  // Handle server errors
  server.on('error', (err) => {
    console.error('Server error:', err);
  });

  // Handle client errors
  server.on('clientError', (err, socket) => {
    console.error('Client error:', err);
    socket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
  });

  // Handle connection limits
  let currentConnections = 0;
  server.on('connection', (socket) => {
    currentConnections++;
    if (currentConnections > MAX_CONNECTIONS) {
      socket.destroy();
      return;
    }

    socket.on('close', () => {
      currentConnections--;
    });
  });

  return server;
}

// Serve static files with caching
function serveStaticFile(filePath, res) {
  // Normalize the path to prevent directory traversal
  const safePath = path.normalize(filePath).replace(/^(\.\.[\/\\])+/, '');
  const fullPath = path.join(STATIC_DIR, safePath);

  // Check if file exists and is within the static directory
  if (!fullPath.startsWith(STATIC_DIR)) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    res.end('Forbidden');
    return;
  }

  // Check cache first
  if (staticFileCache.has(fullPath)) {
    const { content, mimeType } = staticFileCache.get(fullPath);
    res.writeHead(200, { 'Content-Type': mimeType });
    res.end(content);
    return;
  }

  // Read file from disk
  fs.readFile(fullPath, (err, content) => {
    if (err) {
      if (err.code === 'ENOENT') {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not Found');
      } else {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end('Internal Server Error');
      }
      return;
    }

    // Determine MIME type
    const ext = path.extname(fullPath).toLowerCase();
    const mimeType = MIME_TYPES[ext] || 'application/octet-stream';

    // Cache the file
    staticFileCache.set(fullPath, { content, mimeType });

    // Serve the file
    res.writeHead(200, { 'Content-Type': mimeType });
    res.end(content);
  });
}

// Cluster mode for multi-core utilization
if (cluster.isPrimary) {
  console.log(`Primary ${process.pid} is running`);

  // Fork workers equal to the number of CPU cores
  const numCPUs = os.cpus().length;
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died`);
    // Restart the worker
    cluster.fork();
  });
} else {
  // Workers can share any TCP connection
  const server = createServer();

  server.listen(PORT, HOST, () => {
    console.log(`Worker ${process.pid} started and listening on http://${HOST}:${PORT}`);
  });
}
