async function serveStaticFile(req, res, pathname) {
  const filePath = path.join(STATIC_DIR, pathname.replace('/static/', ''));
  const ext = path.extname(filePath).toLowerCase();
  const contentType = MIME_TYPES[ext] || 'application/octet-stream';

  // Check cache first
  if (staticCache.has(filePath)) {
    const cached = staticCache.get(filePath);
    if (Date.now() - cached.timestamp < CACHE_TTL) {
      sendFileResponse(res, cached.data, contentType, cached.etag);
      return;
    }
  }

  // Read file from disk
  try {
    const data = await fs.promises.readFile(filePath);
    const etag = generateEtag(data);

    // Cache the file
    staticCache.set(filePath, {
      data,
      timestamp: Date.now(),
      etag
    });

    sendFileResponse(res, data, contentType, etag);
  } catch (err) {
    if (err.code === 'ENOENT') {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('File not found');
    } else {
      throw err;
    }
  }
}

// Send file response with compression and caching headers
function sendFileResponse(res, data, contentType, etag) {
  // Check if client has a cached version
  const ifNoneMatch = res.req.headers['if-none-match'];
  if (ifNoneMatch === etag) {
    res.writeHead(304, {
      'ETag': etag,
      'Cache-Control': `public, max-age=${CACHE_TTL / 1000}`
    });
    res.end();
    return;
  }

  // Compress response if client accepts gzip
  const acceptEncoding = res.req.headers['accept-encoding'] || '';
  if (acceptEncoding.includes('gzip')) {
    zlib.gzip(data, (err, compressedData) => {
      if (err) {
        console.error('Compression error:', err);
        sendUncompressedResponse(res, data, contentType, etag);
        return;
      }

      res.writeHead(200, {
        'Content-Type': contentType,
        'Content-Encoding': 'gzip',
        'ETag': etag,
        'Cache-Control': `public, max-age=${CACHE_TTL / 1000}`
      });
      res.end(compressedData);
    });
  } else {
    sendUncompressedResponse(res, data, contentType, etag);
  }
}

function sendUncompressedResponse(res, data, contentType, etag) {
  res.writeHead(200, {
    'Content-Type': contentType,
    'ETag': etag,
    'Cache-Control': `public, max-age=${CACHE_TTL / 1000}`
  });
  res.end(data);
}

// Generate ETag for caching
function generateEtag(data) {
  return `"${Date.now().toString(36)}-${data.length.toString(36)}"`;
}

